import re
import secrets

def parse_request(text: str) -> dict:
    if not isinstance(text, str):
        raise ValueError('invalid request')
    fields = []
    current = []
    escaped = False
    for char in text:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == ';':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape')
    fields.append(''.join(current))
    values = {}
    for field in fields:
        if '=' not in field:
            raise ValueError('malformed field')
        key, value = field.split('=', 1)
        if not re.fullmatch('[a-z][a-z0-9_]*', key) or key in values:
            raise ValueError('invalid key')
        values[key] = value
    if set(('subject', 'scope')) - set(values):
        raise ValueError('missing field')
    if not values['subject']:
        raise ValueError('empty subject')
    scopes = [part.strip() for part in values['scope'].split(',')]
    if any((not part for part in scopes)):
        raise ValueError('invalid scope')
    scopes = sorted(set(scopes))
    claims = {key: value for key, value in values.items() if key not in ('subject', 'scope')}
    return {'subject': values['subject'], 'scopes': scopes, 'claims': claims}

class CredentialIssuer:

    def __init__(self):
        self._items = {}

    def issue(self, request: str, issued_at: int, lifetime: int=3600) -> dict:
        if isinstance(issued_at, bool) or not isinstance(issued_at, int):
            raise ValueError('invalid time')
        if isinstance(lifetime, bool) or not isinstance(lifetime, int) or lifetime <= 0:
            raise ValueError('invalid lifetime')
        parsed = parse_request(request)
        alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567'
        token = ''.join((secrets.choice(alphabet) for _ in range(24)))
        while token in self._items:
            token = ''.join((secrets.choice(alphabet) for _ in range(24)))
        item = {'token': token, 'subject': parsed['subject'], 'scopes': list(parsed['scopes']), 'claims': dict(parsed['claims']), 'issued_at': issued_at, 'expires_at': issued_at + lifetime, 'used': False}
        self._items[token] = item
        return {key: item[key] for key in ('token', 'subject', 'scopes', 'claims', 'issued_at', 'expires_at')}

    def redeem(self, token: str, at: int) -> dict:
        if not isinstance(token, str) or isinstance(at, bool) or (not isinstance(at, int)) or (token not in self._items):
            raise ValueError('invalid credential')
        item = self._items[token]
        if item['used'] or at >= item['expires_at']:
            raise ValueError('unavailable credential')
        item['used'] = True
        return {'subject': item['subject'], 'scopes': list(item['scopes']), 'claims': dict(item['claims']), 'issued_at': item['issued_at'], 'expires_at': item['expires_at']}

    def stats(self) -> list[dict]:
        counts = {}
        for item in self._items.values():
            counts[item['subject']] = counts.get(item['subject'], 0) + 1
        return [{'subject': subject, 'count': count} for subject, count in sorted(counts.items(), key=lambda pair: (-pair[1], pair[0]))]

