import json
import os
import tempfile

def export_notebook(cells: list[dict], destination: str) -> str:
    if not isinstance(cells, list):
        raise TypeError('cells must be a list')
    exported = []
    for cell in cells:
        if not isinstance(cell, dict):
            raise TypeError('each cell must be a dictionary')
        if 'cell_type' not in cell or 'source' not in cell:
            raise ValueError('cell requires cell_type and source')
        cell_type = cell['cell_type']
        source = cell['source']
        if cell_type not in ('code', 'markdown'):
            raise ValueError('unsupported cell type')
        if not isinstance(source, (str, list)) or (isinstance(source, list) and (not all((isinstance(x, str) for x in source)))):
            raise TypeError('source must contain strings')
        item = {'cell_type': cell_type, 'metadata': {}, 'source': source}
        if cell_type == 'code':
            item['outputs'] = []
            item['execution_count'] = None
        exported.append(item)
    notebook = {'cells': exported, 'metadata': {'kernelspec': {'display_name': 'Python 3', 'language': 'python', 'name': 'python3'}, 'language_info': {'name': 'python'}}, 'nbformat': 4, 'nbformat_minor': 5}
    directory = os.path.dirname(os.path.abspath(destination))
    temporary = None
    try:
        with tempfile.NamedTemporaryFile(mode='w', encoding='utf-8', dir=directory, delete=False) as handle:
            temporary = handle.name
            json.dump(notebook, handle, indent=2)
            handle.write('\n')
        os.replace(temporary, destination)
        temporary = None
    finally:
        if temporary is not None:
            try:
                os.unlink(temporary)
            except FileNotFoundError:
                pass
    return destination

