import json
import math
import os
from pathlib import Path

def write_lease_report(records: list[dict], base_dir: str, relative_name: str) -> str:
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    if not isinstance(relative_name, str) or not relative_name or (not relative_name.endswith('.json')):
        raise ValueError('invalid filename')
    active = []
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        required = {'tower_id', 'carrier', 'monthly_rent', 'status', 'months_remaining'}
        if set(record) != required:
            raise ValueError('invalid record')
        if not isinstance(record['tower_id'], str) or not record['tower_id'] or (not isinstance(record['carrier'], str)) or (not record['carrier']) or isinstance(record['monthly_rent'], bool) or (not isinstance(record['monthly_rent'], (int, float))) or (not math.isfinite(record['monthly_rent'])) or (record['monthly_rent'] < 0) or (record['status'] not in ('active', 'expired')) or isinstance(record['months_remaining'], bool) or (not isinstance(record['months_remaining'], int)) or (record['months_remaining'] < 0):
            raise ValueError('invalid record')
        if record['status'] == 'active':
            active.append(record)
    active.sort(key=lambda item: (item['tower_id'], item['carrier']))
    grouped = {}
    for record in active:
        item = grouped.setdefault(record['carrier'], [0, 0.0, 0])
        item[0] += 1
        item[1] += record['monthly_rent']
        item[2] += record['months_remaining']
    summary = [{'carrier': carrier, 'lease_count': values[0], 'total_monthly_rent': round(values[1], 2), 'average_months_remaining': round(values[2] / values[0], 1)} for carrier, values in sorted(grouped.items())]
    report = {'leases': active, 'summary': summary}
    base = Path(base_dir).resolve()
    target = (base / relative_name).resolve()
    if os.path.commonpath((str(base), str(target))) != str(base):
        raise ValueError('invalid filename')
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(json.dumps(report, indent=2) + '\n', encoding='utf-8')
    return str(target)

