import os
from pathlib import Path

def store_artifact(base_dir: str, artifact_name: str, content: bytes) -> str:
    base = Path(base_dir).resolve()
    target = (base / artifact_name).resolve()
    try:
        target.relative_to(base)
    except ValueError:
        raise ValueError('artifact path is outside the base directory')
    target.parent.mkdir(parents=True, exist_ok=True)
    with open(target, 'wb') as handle:
        handle.write(content)
    return os.path.abspath(str(target))

import hashlib
import hmac
import json
import math

def inspect_signed_report(text: str, secret: bytes) -> dict:
    if not isinstance(text, str) or not isinstance(secret, bytes):
        raise ValueError('invalid input')
    first, sep, body = text.partition('\n')
    if sep != '\n' or len(first) != 74 or (not first.startswith('signature:')):
        raise ValueError('invalid signature')
    supplied = first[10:]
    if any((c not in '0123456789abcdef' for c in supplied)):
        raise ValueError('invalid signature')
    expected = hmac.new(secret, body.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, supplied):
        raise ValueError('invalid signature')
    try:
        records = json.loads(body)
    except Exception as exc:
        raise ValueError('invalid body') from exc
    if not isinstance(records, list):
        raise ValueError('invalid body')
    grouped = {}
    for item in records:
        if not isinstance(item, dict) or set(item) not in ({'timestamp', 'station', 'status', 'score'}, {'timestamp', 'station', 'status', 'score', 'note'}):
            raise ValueError('invalid record')
        t, station, status, score = (item['timestamp'], item['station'], item['status'], item['score'])
        if isinstance(t, bool) or not isinstance(t, int) or t < 0 or (not isinstance(station, str)) or (not station) or (status not in ('pass', 'fail')) or isinstance(score, bool) or (not isinstance(score, (int, float))) or (not math.isfinite(score)) or (not 0 <= score <= 100) or ('note' in item and (not isinstance(item['note'], str))):
            raise ValueError('invalid record')
        grouped.setdefault(station, []).append((t, score, status))
    output = []
    for station, rows in grouped.items():
        rows.sort(key=lambda x: x[0])
        peaks = [sum((r[1] for r in rows if t - 10 <= r[0] <= t)) / sum((1 for r in rows if t - 10 <= r[0] <= t)) for t, _, _ in rows]
        output.append({'station': station, 'passed': sum((r[2] == 'pass' for r in rows)), 'failed': sum((r[2] == 'fail' for r in rows)), 'average_score': round(sum((r[1] for r in rows)) / len(rows), 2), 'latest_timestamp': rows[-1][0], 'rolling_peak': round(max(peaks), 2)})
    output.sort(key=lambda x: (-x['average_score'], -x['passed'], x['station']))
    return {'total': len(records), 'stations': output}

