import hashlib
import hmac
import json
import pytest
from solution import process_transcription_webhook

def signed(body):
    return hmac.new(b'speech-hook-v1', body.encode(), hashlib.sha256).hexdigest()

def test_empty_jobs_returns_empty_summary():
    body = json.dumps({'jobs': []})
    assert process_transcription_webhook(body, signed(body)) == {'total_jobs': 0, 'total_duration_seconds': 0, 'languages': []}

def test_filters_status_sorts_and_aggregates_languages():
    payload = {'jobs': [{'id': 'b', 'status': 'completed', 'language': 'en', 'duration_seconds': 4.0, 'word_count': 20}, {'id': 'a', 'status': 'completed', 'language': 'fr', 'duration_seconds': 9.0, 'word_count': 40}, {'id': 'c', 'status': 'queued', 'language': 'en', 'duration_seconds': 100, 'word_count': 1}, {'id': 'd', 'status': 'completed', 'language': 'en', 'duration_seconds': 6.0, 'word_count': 30}]}
    body = json.dumps(payload)
    assert process_transcription_webhook(body, signed(body)) == {'total_jobs': 3, 'total_duration_seconds': 19.0, 'languages': [{'language': 'en', 'jobs': 2, 'average_duration_seconds': 5.0}, {'language': 'fr', 'jobs': 1, 'average_duration_seconds': 9.0}]}

def test_bad_signature_is_rejected():
    body = json.dumps({'jobs': []})
    with pytest.raises(ValueError):
        process_transcription_webhook(body, '0' * 64)

def test_invalid_body_and_pagination_raise_value_error():
    with pytest.raises(ValueError):
        process_transcription_webhook('not json', 'x')
    body = json.dumps({'jobs': []})
    for offset, limit in [(-1, 1), (0, 0), (0, 101)]:
        with pytest.raises(ValueError):
            process_transcription_webhook(body, signed(body), offset, limit)

def test_invalid_job_fields_raise_value_error():
    cases = [{'id': 'x', 'status': 'completed', 'language': 'en', 'duration_seconds': -1, 'word_count': 2}, {'id': 'x', 'status': 'completed', 'language': 'en', 'duration_seconds': 1, 'word_count': True}, {'id': 'x', 'status': 'completed', 'language': '', 'duration_seconds': 1, 'word_count': 2}]
    for job in cases:
        body = json.dumps({'jobs': [job]})
        with pytest.raises(ValueError):
            process_transcription_webhook(body, signed(body))

