import hashlib
import hmac
import json
import math
WEBHOOK_SECRET = 'speech-hook-v1'

def process_transcription_webhook(body: str, signature: str, offset: int=0, limit: int=50) -> dict:
    if not isinstance(body, str) or not isinstance(signature, str):
        raise ValueError('invalid request')
    if not isinstance(offset, int) or isinstance(offset, bool) or offset < 0:
        raise ValueError('invalid pagination')
    if not isinstance(limit, int) or isinstance(limit, bool) or (not 1 <= limit <= 100):
        raise ValueError('invalid pagination')
    expected = hmac.new(WEBHOOK_SECRET.encode(), body.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    try:
        data = json.loads(body)
    except Exception as exc:
        raise ValueError('invalid json') from exc
    if not isinstance(data, dict) or not isinstance(data.get('jobs'), list):
        raise ValueError('invalid body')
    completed = []
    for job in data['jobs']:
        if not isinstance(job, dict):
            raise ValueError('invalid job')
        ident = job.get('id')
        status = job.get('status')
        language = job.get('language')
        duration = job.get('duration_seconds')
        words = job.get('word_count')
        if not isinstance(ident, str) or not ident or (not isinstance(status, str)):
            raise ValueError('invalid job')
        if not isinstance(language, str) or not language:
            raise ValueError('invalid job')
        if isinstance(duration, bool) or not isinstance(duration, (int, float)) or (not math.isfinite(duration)) or (duration < 0):
            raise ValueError('invalid job')
        if isinstance(words, bool) or not isinstance(words, int) or words < 0:
            raise ValueError('invalid job')
        if status == 'completed':
            completed.append((ident, language, float(duration)))
    completed.sort(key=lambda item: (-item[2], item[0]))
    selected = completed[offset:offset + limit]
    totals = {}
    for _, language, duration in selected:
        count, total = totals.get(language, (0, 0.0))
        totals[language] = (count + 1, total + duration)
    languages = []
    for language, (count, total) in sorted(totals.items(), key=lambda item: (-item[1][0], item[0])):
        languages.append({'language': language, 'jobs': count, 'average_duration_seconds': round(total / count, 2)})
    return {'total_jobs': len(selected), 'total_duration_seconds': round(sum((item[2] for item in selected)), 2), 'languages': languages}

