import io
import os
import tempfile
import zipfile
from datetime import date
from collections import defaultdict

def summarize_vaccination_archive(base_dir: str, archive_name: str, start_date: str, end_date: str) -> list[dict]:
    try:
        start = date.fromisoformat(start_date)
        end = date.fromisoformat(end_date)
    except Exception as exc:
        raise ValueError('invalid date') from exc
    if start > end:
        raise ValueError('inverted range')
    base = os.path.realpath(base_dir)
    archive = os.path.realpath(os.path.join(base, archive_name))
    if os.path.commonpath([base, archive]) != base:
        raise ValueError('archive path')
    if not os.path.isfile(archive):
        raise FileNotFoundError(archive)
    try:
        zf = zipfile.ZipFile(archive)
    except (OSError, zipfile.BadZipFile) as exc:
        raise ValueError('invalid archive') from exc
    records = set()
    with zf:
        with tempfile.TemporaryDirectory() as tmp:
            root = os.path.realpath(tmp)
            for info in zf.infolist():
                target = os.path.realpath(os.path.join(root, info.filename))
                if os.path.commonpath([root, target]) != root:
                    raise ValueError('archive member path')
                if info.is_dir():
                    os.makedirs(target, exist_ok=True)
                    continue
                os.makedirs(os.path.dirname(target), exist_ok=True)
                with open(target, 'wb') as out, zf.open(info) as src:
                    out.write(src.read())
            for current, _, names in os.walk(root):
                for name in names:
                    if not name.lower().endswith('.csv'):
                        continue
                    with open(os.path.join(current, name), encoding='utf-8', newline='') as stream:
                        reader = csv.reader(stream)
                        try:
                            header = next(reader)
                        except StopIteration:
                            continue
                        if header != ['patient_id', 'vaccine', 'dose_date', 'region', 'dose_number']:
                            raise ValueError('invalid header')
                        for row in reader:
                            if len(row) != 5:
                                raise ValueError('invalid row')
                            patient, vaccine, when, region, number = [x.strip() for x in row]
                            try:
                                parsed = date.fromisoformat(when)
                                dose = int(number)
                            except Exception as exc:
                                raise ValueError('invalid field') from exc
                            if not patient or not vaccine or (not region) or (dose <= 0):
                                raise ValueError('invalid field')
                            if start <= parsed <= end:
                                records.add((patient, vaccine, when, region, dose))
    groups = defaultdict(list)
    for record in records:
        groups[record[3], record[1]].append(record)
    result = []
    for (region, vaccine), rows in sorted(groups.items()):
        dates = [r[2] for r in rows]
        result.append({'region': region, 'vaccine': vaccine, 'doses': len(rows), 'patients': len({r[0] for r in rows}), 'first_date': min(dates), 'last_date': max(dates)})
    return result

