import csv
import datetime
import os
import tempfile

def _time(value):
    if not isinstance(value, str) or not value:
        raise ValueError('invalid time')
    try:
        text = value[:-1] + '+00:00' if value.endswith('Z') else value
        result = datetime.datetime.fromisoformat(text)
    except Exception as exc:
        raise ValueError('invalid time') from exc
    if result.tzinfo is None or result.microsecond:
        raise ValueError('invalid time')
    return result.astimezone(datetime.timezone.utc)

def build_queue(events: list[dict], now: str) -> list[dict]:
    if not isinstance(events, list):
        raise ValueError('invalid events')
    moment = _time(now)
    parsed = []
    for index, event in enumerate(events):
        if not isinstance(event, dict) or not isinstance(event.get('time'), str):
            raise ValueError('invalid event')
        stamp = _time(event['time'])
        if stamp > moment:
            raise ValueError('future event')
        action = event.get('action')
        if action not in ('enqueue', 'dequeue'):
            raise ValueError('invalid action')
        if action == 'enqueue':
            caller = event.get('caller')
            priority = event.get('priority')
            if not isinstance(caller, str) or not caller or isinstance(priority, bool) or (not isinstance(priority, int)) or (not 0 <= priority <= 9):
                raise ValueError('invalid enqueue')
        else:
            caller = event.get('caller')
            if not isinstance(caller, str) or not caller:
                raise ValueError('invalid dequeue')
        parsed.append((stamp, index, event))
    parsed.sort(key=lambda x: (x[0], x[1]))
    queued = {}
    for stamp, _, event in parsed:
        caller = event['caller']
        if event['action'] == 'enqueue':
            if caller in queued:
                raise ValueError('duplicate caller')
            queued[caller] = (event['priority'], stamp)
        else:
            if caller not in queued:
                raise ValueError('unknown caller')
            del queued[caller]
    result = []
    for caller, (priority, stamp) in queued.items():
        result.append({'caller': caller, 'priority': priority, 'entered': stamp.strftime('%Y-%m-%dT%H:%M:%SZ'), 'wait_seconds': int((moment - stamp).total_seconds())})
    result.sort(key=lambda x: (-x['priority'], x['entered'], x['caller']))
    return result

def export_queue(events: list[dict], now: str, destination: str) -> int:
    rows = build_queue(events, now)
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent, prefix='.queue-', suffix='.tmp')
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as stream:
            writer = csv.writer(stream)
            writer.writerow(['caller', 'priority', 'entered', 'wait_seconds'])
            for row in rows:
                writer.writerow([row['caller'], row['priority'], row['entered'], row['wait_seconds']])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except OSError:
            pass
        raise
    return len(rows)

