def _check(events, limits):
    if not isinstance(limits, dict):
        raise ValueError('invalid limits')
    for user, limit in limits.items():
        if not isinstance(user, str) or not user or isinstance(limit, bool) or (not isinstance(limit, int)) or (limit < 0):
            raise ValueError('invalid limits')
    checked = []
    for event in events:
        if not isinstance(event, dict) or set(event) != {'user', 'timestamp', 'delta'}:
            raise ValueError('invalid event')
        user, stamp, delta = (event['user'], event['timestamp'], event['delta'])
        if not isinstance(user, str) or not user or user not in limits:
            raise ValueError('invalid user')
        if isinstance(delta, bool) or not isinstance(delta, int) or delta < 0:
            raise ValueError('invalid delta')
        try:
            parsed = datetime.datetime.fromisoformat(stamp)
        except (TypeError, ValueError):
            raise ValueError('invalid timestamp')
        checked.append((parsed, len(checked), user, delta))
    return checked

def compute_quota(events, limits):
    checked = _check(events, limits)
    usage = {user: 0 for user in limits}
    peak = {user: 0 for user in limits}
    for _, _, user, delta in sorted(checked, key=lambda x: x[0]):
        usage[user] += delta
        peak[user] = max(peak[user], usage[user])
    rows = []
    for user, limit in limits.items():
        over = max(0, usage[user] - limit)
        rows.append({'user': user, 'usage': usage[user], 'peak': peak[user], 'limit': limit, 'overage': over, 'status': 'over' if over else 'ok'})
    return sorted(rows, key=lambda r: (-r['overage'], -r['usage'], r['user']))

def export_quota_report(events, limits, destination, format='csv'):
    if format not in ('csv', 'json'):
        raise ValueError('invalid format')
    rows = compute_quota(events, limits)
    if format == 'json':
        content = json.dumps(rows, ensure_ascii=False, separators=(',', ':'))
    else:
        stream = io.StringIO(newline='')
        writer = csv.DictWriter(stream, fieldnames=['user', 'usage', 'peak', 'limit', 'overage', 'status'], lineterminator='\n')
        writer.writeheader()
        writer.writerows(rows)
        content = stream.getvalue()
    fd, temporary = tempfile.mkstemp(dir=os.path.dirname(os.path.abspath(destination)))
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as handle:
            handle.write(content)
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return destination

