import secrets
from datetime import date

def create_payment_token(policy_id: str, amount_cents: int) -> str:
    if not isinstance(policy_id, str):
        raise TypeError('policy_id must be a string')
    if not isinstance(amount_cents, int) or isinstance(amount_cents, bool):
        raise TypeError('amount_cents must be an integer')
    if not policy_id:
        raise ValueError('policy_id must not be empty')
    if amount_cents < 0:
        raise ValueError('amount_cents must not be negative')
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    return ''.join((secrets.choice(alphabet) for _ in range(24)))

def summarize_billing(records: list[dict], page: int=1, page_size: int=10) -> dict:
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    if not isinstance(page, int) or isinstance(page, bool) or (not isinstance(page_size, int)) or isinstance(page_size, bool):
        raise TypeError('page values must be integers')
    if page < 1 or page_size < 1:
        raise ValueError('page values must be positive')
    groups = {}
    total_due = 0
    total_paid = 0
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('record must be a dictionary')
        for key in ('policy_id', 'invoice_id', 'due_cents', 'paid_cents', 'due_date'):
            if key not in record:
                raise ValueError('missing field')
        policy = record['policy_id']
        invoice = record['invoice_id']
        due = record['due_cents']
        paid = record['paid_cents']
        if not isinstance(policy, str) or not policy or (not isinstance(invoice, str)) or (not invoice):
            raise ValueError('invalid identifier')
        if not isinstance(due, int) or isinstance(due, bool) or due < 0 or (not isinstance(paid, int)) or isinstance(paid, bool) or (paid < 0):
            raise ValueError('invalid amount')
        try:
            date.fromisoformat(record['due_date'])
        except (TypeError, ValueError):
            raise ValueError('invalid date')
        total_due += due
        total_paid += paid
        if policy not in groups:
            groups[policy] = {'due': 0, 'paid': 0, 'invoice_count': 0, 'earliest_due_date': record['due_date']}
        group = groups[policy]
        group['due'] += due
        group['paid'] += paid
        group['invoice_count'] += 1
        group['earliest_due_date'] = min(group['earliest_due_date'], record['due_date'])
    policies = []
    for policy, group in groups.items():
        outstanding = max(group['due'] - group['paid'], 0)
        policies.append({'policy_id': policy, **group, 'outstanding': outstanding})
    policies.sort(key=lambda item: (-item['outstanding'], item['policy_id']))
    start = (page - 1) * page_size
    return {'total_due': total_due, 'total_paid': total_paid, 'total_outstanding': max(total_due - total_paid, 0), 'total_policies': len(policies), 'page': page, 'page_size': page_size, 'policies': policies[start:start + page_size]}

