import hashlib
import os
import base64
import datetime
import hmac

def hash_password(password: str) -> str:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return '100000$' + base64.b64encode(salt).decode() + '$' + base64.b64encode(value).decode()

def verify_password(stored: str, password: str) -> bool:
    if not isinstance(password, str) or not isinstance(stored, str):
        return False
    try:
        count, salt_text, value_text = stored.split('$')
        count = int(count)
        salt = base64.b64decode(salt_text.encode(), validate=True)
        expected = base64.b64decode(value_text.encode(), validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, count)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def production_report(records: list[dict], stored_password: str, password: str, page: int=1, page_size: int=20) -> list[dict]:
    if not verify_password(stored_password, password):
        raise PermissionError('invalid password')
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError('invalid pagination')
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        well = record.get('well')
        date = record.get('date')
        barrels = record.get('barrels')
        downtime = record.get('downtime_minutes')
        if not isinstance(well, str) or not well or (not isinstance(date, str)) or isinstance(barrels, bool) or (not isinstance(barrels, int)) or (barrels < 0) or isinstance(downtime, bool) or (not isinstance(downtime, int)) or (downtime < 0):
            raise ValueError('invalid record')
        try:
            datetime.date.fromisoformat(date)
        except ValueError:
            raise ValueError('invalid record')
        item = groups.setdefault(well, [0, 0, 0])
        item[0] += barrels
        item[1] += downtime
        item[2] += 1
    result = [{'well': w, 'total_barrels': v[0], 'total_downtime_minutes': v[1], 'days': v[2], 'average_barrels': round(v[0] / v[2], 2)} for w, v in groups.items()]
    result.sort(key=lambda x: (-x['total_barrels'], x['well']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

