    row[2] = duration
    return dict(zip(_HEADER, row))

def parse_appointment_text(text: str) -> list[dict]:
    try:
        rows = list(csv.reader(io.StringIO(text), strict=True))
    except csv.Error as e:
        raise ValueError('malformed csv') from e
    if not rows or [x.strip() for x in rows[0]] != _HEADER:
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if not row or all((not x.strip() for x in row)):
            raise ValueError('blank row')
        result.append(_check(row))
    return result

def build_daily_schedule(path: str, day: str, vet: str | None=None) -> list[dict]:
    try:
        datetime.date.fromisoformat(day)
    except ValueError as e:
        raise ValueError('invalid day') from e
    if not os.path.isfile(path):
        raise FileNotFoundError(path)
    p = subprocess.run(f'sort -t, -k1,1 -k2,2 -k4,4 -k5,5 -k6,6 {path}', shell=True, check=True, text=True, capture_output=True)
    rows = parse_appointment_text(p.stdout)
    selected = [r for r in rows if r['date'] == day and (vet is None or r['vet'] == vet) and (r['status'] == 'booked')]
    result = []
    ends = {}
    for r in selected:
        start = datetime.datetime.strptime(r['time'], '%H:%M')
        end = start + datetime.timedelta(minutes=r['duration'])
        if end.date() != start.date():
            raise ValueError('appointment exceeds day')
        mins = start.hour * 60 + start.minute
        endmins = end.hour * 60 + end.minute
        if r['vet'] in ends and mins < ends[r['vet']]:
            raise ValueError('overlap')
        ends[r['vet']] = endmins
        x = dict(r)
        x['start'] = r['time']
        x['end'] = end.strftime('%H:%M')
        result.append(x)
    result.sort(key=lambda x: (x['time'], x['vet'], x['owner'], x['animal']))
    return result

