import hashlib
import hmac
import json

def verify_and_summarize(payload: str, signature: str, secret: bytes, offset: int=0, limit: int=50) -> dict:
    expected = hmac.new(secret, payload.encode('utf-8'), hashlib.sha256).hexdigest()
    try:
        valid = hmac.compare_digest(expected, signature)
    except (TypeError, ValueError):
        valid = False
    if not valid:
        raise PermissionError('invalid signature')
    if not isinstance(offset, int) or isinstance(offset, bool) or offset < 0:
        raise ValueError('invalid offset')
    if not isinstance(limit, int) or isinstance(limit, bool) or (not 1 <= limit <= 100):
        raise ValueError('invalid limit')
    try:
        document = json.loads(payload)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(document, dict) or not isinstance(document.get('events'), list):
        raise ValueError('invalid payload')
    totals = {}
    for event in document['events']:
        if not isinstance(event, dict):
            raise ValueError('invalid event')
        if not all((key in event for key in ('resident_id', 'minutes', 'status'))):
            raise ValueError('invalid event')
        resident = event['resident_id']
        minutes = event['minutes']
        status = event['status']
        if not isinstance(resident, str) or not resident or (not isinstance(minutes, int)) or isinstance(minutes, bool) or (not 0 <= minutes <= 1440) or (status not in ('completed', 'cancelled')):
            raise ValueError('invalid event')
        if status == 'completed':
            total, visits = totals.get(resident, (0, 0))
            totals[resident] = (total + minutes, visits + 1)
    ordered = sorted(totals.items(), key=lambda item: (-item[1][0], item[0]))
    residents = [{'resident_id': resident, 'minutes': values[0], 'visits': values[1]} for resident, values in ordered[offset:offset + limit]]
    return {'total_minutes': sum((values[0] for values in totals.values())), 'residents': residents}

