import subprocess
from collections import defaultdict
_BLOOD = {'O-', 'O+', 'A-', 'A+', 'B-', 'B+', 'AB-', 'AB+'}
_STATUS = {'ACTIVE', 'PAUSED', 'REMOVED'}

def _read(path):
    with open(path, 'rb'):
        pass
    r = subprocess.run(['sort', '-t', '\t', '-k6,6', '-k4,4nr', '-k5,5nr', '-k1,1', path], capture_output=True, text=True, check=True)
    out = []
    ids = set()
    for raw in r.stdout.splitlines():
        if not raw.strip():
            continue
        p = raw.split('\t')
        if len(p) != 7:
            raise ValueError('malformed row')
        cid, name, blood, urg, days, region, status = p
        if not cid or blood not in _BLOOD or status not in _STATUS:
            raise ValueError('invalid field')
        try:
            u, d = (int(urg), int(days))
        except ValueError:
            raise ValueError('invalid number')
        if not 0 <= u <= 9 or d < 0 or cid in ids:
            raise ValueError('invalid record')
        ids.add(cid)
        if status == 'ACTIVE':
            out.append((cid, name, blood, u, d, region))
    return out

def rank_waitlist(path: str, region: str | None=None, limit: int | None=None) -> list[dict]:
    if limit is not None and (not isinstance(limit, int) or isinstance(limit, bool) or limit <= 0):
        raise ValueError('invalid limit')
