import os

def issue_permit(worker_id: str, habitat: str, hectares: float, species: list[str], password: str) -> dict:
    if not isinstance(worker_id, str) or not worker_id:
        raise ValueError('invalid worker_id')
    if not isinstance(habitat, str) or not habitat:
        raise ValueError('invalid habitat')
    if not isinstance(password, str) or not password:
        raise ValueError('invalid password')
    if not isinstance(hectares, (int, float)) or isinstance(hectares, bool) or (not math.isfinite(hectares)) or (hectares <= 0):
        raise ValueError('invalid hectares')
    if not isinstance(species, list) or not species or any((not isinstance(x, str) or not x for x in species)):
        raise ValueError('invalid species')
    names = sorted(set(species))
    if len(names) != len(species):
        raise ValueError('duplicate species')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    stored = 'pbkdf2$' + base64.b64encode(salt).decode() + '$' + base64.b64encode(digest).decode()
    return {'worker_id': worker_id, 'habitat': habitat, 'hectares': float(hectares), 'species': names, 'password_hash': stored}

def verify_permit(permit: dict, password: str) -> bool:
    if not isinstance(password, str) or not isinstance(permit, dict):
        return False
    try:
        kind, salt_text, digest_text = permit['password_hash'].split('$')
        if kind != 'pbkdf2':
            return False
        salt = base64.b64decode(salt_text, validate=True)
        expected = base64.b64decode(digest_text, validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (KeyError, ValueError, TypeError):
        return False

def permit_report(permits: list[dict], habitat: str | None=None, page: int=1, page_size: int=10) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError('invalid page_size')
    if habitat is not None and (not isinstance(habitat, str)):
        raise ValueError('invalid habitat')
    selected = [p for p in permits if habitat is None or p.get('habitat') == habitat]
    selected.sort(key=lambda p: (-p['hectares'], p['worker_id']))
    counts = {}
    for p in selected:
        for name in p['species']:
            counts[name] = counts.get(name, 0) + 1
    start = (page - 1) * page_size
    items = [{'worker_id': p['worker_id'], 'habitat': p['habitat'], 'hectares': p['hectares'], 'species': list(p['species'])} for p in selected[start:start + page_size]]
    return {'total_count': len(selected), 'total_hectares': round(sum((p['hectares'] for p in selected)), 2), 'species_counts': dict(sorted(counts.items())), 'permits': items}

