import hashlib
import hmac
import os

def parse_expenses(text: str) -> dict[str, int]:
    if not isinstance(text, str):
        raise ValueError('expenses')
    if not text:
        return {}
    items = []
    cur = []
    escaped = False
    for ch in text:
        if escaped:
            cur.append(('lit', ch))
            escaped = False
        elif ch == '\\':
            escaped = True
        elif ch == ';':
            items.append(cur)
            cur = []
        else:
            cur.append(('raw', ch))
    if escaped:
        raise ValueError('escape')
    items.append(cur)
    out = {}
    for item in items:
        if not item or not ''.join((x[1] for x in item)).strip():
            raise ValueError('item')
        pos = next((i for i, x in enumerate(item) if x[0] == 'raw' and x[1] == '='), None)
        if pos is None:
            raise ValueError('equals')
        key = ''.join((x[1] for x in item[:pos])).strip()
        val = ''.join((x[1] for x in item[pos + 1:])).strip()
        if not key or not val or (not val.isdigit()):
            raise ValueError('value')
        out[key] = out.get(key, 0) + int(val)
    return dict(sorted(out.items()))

def create_case(case_id: str, household_size: int, annual_income_cents: int, expenses: str, password: str) -> dict:
    if not isinstance(case_id, str) or not case_id or (not isinstance(password, str)) or (not password):
        raise ValueError('text')
    if type(household_size) is not int or not 1 <= household_size <= 20:
        raise ValueError('household')
    if type(annual_income_cents) is not int or annual_income_cents < 0:
        raise ValueError('income')
    parsed = parse_expenses(expenses)
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return {'case_id': case_id, 'household_size': household_size, 'annual_income_cents': annual_income_cents, 'expenses': dict(parsed), 'password_hash': salt.hex() + ':' + digest.hex()}

def verify_case_password(case: dict, password: str) -> bool:
    try:
        if not isinstance(password, str) or not isinstance(case, dict):
            return False
        salt, expected = case['password_hash'].split(':')
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), bytes.fromhex(salt), 100000).hex()
        return hmac.compare_digest(actual, expected)
    except Exception:
        return False

def allocate_charity_funds(cases: list[dict], budget_cents: int) -> list[dict]:
    if type(budget_cents) is not int or budget_cents < 0:
        raise ValueError('budget')
    seen = set()
    work = []
    for c in cases:
        if not isinstance(c, dict) or set(c) != {'case_id', 'household_size', 'annual_income_cents', 'expenses', 'password_hash'} or (not isinstance(c['case_id'], str)) or (c['case_id'] in seen):
            raise ValueError('case')
        if type(c['household_size']) is not int or not 1 <= c['household_size'] <= 20 or type(c['annual_income_cents']) is not int or (c['annual_income_cents'] < 0) or (not isinstance(c['expenses'], dict)) or (not isinstance(c['password_hash'], str)):
            raise ValueError('case')
        seen.add(c['case_id'])
        total = sum(c['expenses'].values())
        threshold = 1500000 + 550000 * (c['household_size'] - 1)
        request = min(200000, max(0, total - c['annual_income_cents'] // 10))
        if request:
            work.append((c['annual_income_cents'] / threshold, -request, c['case_id'], request))
    work.sort()
    result = []
    left = budget_cents
    for _, _, ident, request in work:
        amount = min(request, left)
        result.append({'case_id': ident, 'requested_cents': request, 'allocated_cents': amount})
        left -= amount
    return result

