def build_queue_request(jobs: list[dict], config: dict) -> dict:
    if not isinstance(config, dict):
        raise ValueError('invalid configuration')
    for key in ('endpoint', 'api_token', 'max_total_grams'):
        if key not in config:
            raise ValueError('missing configuration')
    if not isinstance(config['endpoint'], str) or not isinstance(config['api_token'], str):
        raise ValueError('invalid configuration')
    limit = config['max_total_grams']
    if isinstance(limit, bool) or not isinstance(limit, (int, float)) or limit <= 0:
        raise ValueError('invalid configuration')
    if not isinstance(jobs, list):
        raise ValueError('invalid jobs')
    selected = []
    for job in jobs:
        if not isinstance(job, dict):
            raise ValueError('invalid job')
        required = ('id', 'material', 'grams', 'priority', 'status')
        if any((key not in job for key in required)):
            raise ValueError('invalid job')
        if not isinstance(job['id'], str) or not job['id'] or (not isinstance(job['material'], str)) or (not job['material']):
            raise ValueError('invalid job')
        if isinstance(job['grams'], bool) or not isinstance(job['grams'], (int, float)) or job['grams'] <= 0 or (not isinstance(job['priority'], int)) or isinstance(job['priority'], bool) or (not isinstance(job['status'], str)):
            raise ValueError('invalid job')
        if job['status'] == 'queued' and job['grams'] <= limit:
            selected.append(job)
    selected.sort(key=lambda item: (-item['priority'], item['material'], item['id']))
    batches = []
    by_material = {}
    for job in selected:
        material = job['material']
        if material not in by_material:
            by_material[material] = {'material': material, 'job_ids': [], 'grams': 0.0}
            batches.append(by_material[material])
        batch = by_material[material]
        batch['job_ids'].append(job['id'])
        batch['grams'] += job['grams']
    for batch in batches:
