def extract_bundle(base_dir: str) -> list[dict]:
    root = os.path.abspath(base_dir)
    out = os.path.join(root, 'extracted')
    os.makedirs(out, exist_ok=True)
    with zipfile.ZipFile(os.path.join(root, 'bundle.zip')) as z:
        for info in z.infolist():
            target = os.path.abspath(os.path.join(out, info.filename))
            if os.path.commonpath([out, target]) != out:
                raise ValueError('invalid archive member')
            if info.is_dir():
                os.makedirs(target, exist_ok=True)
