import hmac
import json
import os

def build_installation_manifest(records: list[dict], appliance_type: str, installation_date: str, page: int, page_size: int, config: dict | None=None) -> dict:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError('page and page_size must be positive integers')
    token = None
    if config is not None and 'api_token' in config:
        token = config['api_token']
    if not token:
        token = os.environ.get('INSTALLATION_API_TOKEN')
    if not isinstance(token, str) or not token:
        raise ValueError('missing installation API token')
    required = {'id', 'appliance', 'date', 'start', 'end', 'capacity', 'booked', 'available'}
    selected = []
    for record in records:
        if not required.issubset(record):
            raise ValueError('malformed installation record')
        if not isinstance(record['capacity'], int) or isinstance(record['capacity'], bool) or (not isinstance(record['booked'], int)) or isinstance(record['booked'], bool):
            raise ValueError('capacity and booked must be integers')
        if record['appliance'] == appliance_type and record['date'] == installation_date and (record['available'] is True) and (record['capacity'] - record['booked'] > 0):
            selected.append({'id': record['id'], 'start': record['start'], 'end': record['end'], 'remaining': record['capacity'] - record['booked']})
    selected.sort(key=lambda item: (item['start'], item['id']))
    total = len(selected)
    begin = (page - 1) * page_size
    slots = selected[begin:begin + page_size]
    body = {'appliance_type': appliance_type, 'date': installation_date, 'total': total, 'page': page, 'page_size': page_size, 'slots': slots}
    raw = json.dumps(body, sort_keys=True, separators=(',', ':')).encode()
    signature = hmac.new(token.encode(), raw, hashlib.sha256).hexdigest()
    return {**body, 'signature': signature}

