def extract_accommodation_plans(archive_path: str, output_dir: str, student_ids: list[str] | None=None) -> list[dict]:
    if student_ids is not None and any((not isinstance(x, str) for x in student_ids)):
        raise ValueError('student_ids must contain strings')
    selected = None if student_ids is None else set(student_ids)
    totals = {}
    with zipfile.ZipFile(archive_path) as archive:
        base = os.path.realpath(output_dir)
        for info in archive.infolist():
            name = info.filename
            if info.is_dir() or not name.endswith('.json'):
                continue
            destination = os.path.realpath(os.path.join(base, name))
            try:
                inside = os.path.commonpath([base, destination]) == base
            except ValueError:
                inside = False
            if not inside:
                raise ValueError('archive member is outside output directory')
            os.makedirs(os.path.dirname(destination), exist_ok=True)
