                target.write(source.read())
            try:
                with open(destination, encoding='utf-8') as handle:
                    record = json.load(handle)
            except (json.JSONDecodeError, UnicodeDecodeError) as exc:
                raise ValueError('invalid plan JSON') from exc
            if not isinstance(record, dict) or not isinstance(record.get('student_id'), str) or (not record['student_id']) or (not isinstance(record.get('accommodations'), list)) or any((not isinstance(x, str) for x in record['accommodations'])):
                raise ValueError('invalid plan record')
