import os
from pathlib import Path

def write_work_instruction(base_dir: str, relative_name: str, content: str) -> str:
    if relative_name == '':
        raise ValueError('relative_name must not be empty')
    base = Path(base_dir).resolve()
    target = (base / relative_name).resolve()
    try:
        target.relative_to(base)
    except ValueError:
        raise ValueError('file location is outside base directory')
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding='utf-8')
    return str(target)

