import os
from datetime import datetime, timezone

def parse_log_line(line: str) -> tuple[str, str, str, str]:
    fields = []
    current = []
    escaped = False
    for char in line.rstrip('\n'):
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape')
    fields.append(''.join(current))
    if len(fields) != 4 or not fields[1] or (not fields[2]):
        raise ValueError('malformed log line')
    try:
        dt = datetime.strptime(fields[0], '%Y-%m-%dT%H:%M:%SZ').replace(tzinfo=timezone.utc)
    except ValueError as exc:
        raise ValueError('invalid timestamp') from exc
    if dt.strftime('%Y-%m-%dT%H:%M:%SZ') != fields[0]:
        raise ValueError('invalid timestamp')
    return tuple(fields)

def aggregate_log_files(base_dir: str, relative_paths: list[str], window_seconds: int=60) -> list[dict[str, object]]:
    if isinstance(window_seconds, bool) or not isinstance(window_seconds, int) or window_seconds <= 0:
        raise ValueError('window_seconds must be positive')
    base = os.path.realpath(base_dir)
    groups = {}
    for relative in relative_paths:
        path = os.path.realpath(os.path.join(base, relative))
        try:
            inside = os.path.commonpath((base, path)) == base
        except ValueError:
            inside = False
        if not inside:
            raise ValueError('path outside base directory')
        with open(path, 'r', encoding='utf-8') as handle:
            for raw in handle:
                if not raw.strip():
                    continue
                timestamp, service, level, _ = parse_log_line(raw)
                instant = datetime.strptime(timestamp, '%Y-%m-%dT%H:%M:%SZ').replace(tzinfo=timezone.utc)
                epoch = int(instant.timestamp())
                start = epoch - epoch % window_seconds
                key = (start, service)
                item = groups.setdefault(key, {'count': 0, 'levels': {}, 'first': timestamp, 'last': timestamp})
                item['count'] += 1
                item['levels'][level] = item['levels'].get(level, 0) + 1
                item['first'] = min(item['first'], timestamp)
                item['last'] = max(item['last'], timestamp)
    result = []
    for (start, service), item in sorted(groups.items(), key=lambda pair: (pair[0][0], pair[0][1])):
        stamp = datetime.fromtimestamp(start, timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')
        result.append({'window_start': stamp, 'service': service, 'count': item['count'], 'levels': dict(sorted(item['levels'].items())), 'first_timestamp': item['first'], 'last_timestamp': item['last']})
    return result

