import csv
import os
import tempfile
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def _money(value):
    try:
        result = Decimal(str(value))
    except (InvalidOperation, ValueError, TypeError):
        raise ValueError
    if not result.is_finite() or result < 0:
        raise ValueError
    return result

def _rows(entries, tax_rate):
    tax_rate = _money(tax_rate)
    if tax_rate > 100:
        raise ValueError
    groups = {}
    for entry in entries:
        if not isinstance(entry, dict):
            raise ValueError
        customer = entry.get('customer')
        equipment = entry.get('equipment')
        days = entry.get('days')
        if not isinstance(customer, str) or not customer or (not isinstance(equipment, str)) or (not equipment):
            raise ValueError
        if isinstance(days, bool) or not isinstance(days, int) or days <= 0:
            raise ValueError
        daily = _money(entry.get('daily_rate'))
        damage = _money(entry.get('damage_fee'))
        late = _money(entry.get('late_fee'))
        key = (customer, equipment)
        if key not in groups:
            groups[key] = [0, Decimal('0'), Decimal('0'), Decimal('0')]
        group = groups[key]
        group[0] += days
        group[1] += daily * days
        group[2] += damage
        group[3] += late
    result = []
    quant = Decimal('0.01')
    for (customer, equipment), (days, rental, damage, late) in sorted(groups.items()):
        subtotal = rental + damage + late
        tax = (subtotal * tax_rate / Decimal('100')).quantize(quant, rounding=ROUND_HALF_UP)
        total = (subtotal + tax).quantize(quant, rounding=ROUND_HALF_UP)
        result.append({'customer': customer, 'equipment': equipment, 'days': days, 'rental': format(rental.quantize(quant, rounding=ROUND_HALF_UP), '.2f'), 'damage': format(damage.quantize(quant, rounding=ROUND_HALF_UP), '.2f'), 'late': format(late.quantize(quant, rounding=ROUND_HALF_UP), '.2f'), 'subtotal': format(subtotal.quantize(quant, rounding=ROUND_HALF_UP), '.2f'), 'tax': format(tax, '.2f'), 'total': format(total, '.2f')})
    return result

def invoice_totals(entries, tax_rate):
    return _rows(entries, tax_rate)

def export_invoice_csv(entries, tax_rate, destination):
    rows = _rows(entries, tax_rate)
    fields = ['customer', 'equipment', 'days', 'rental', 'damage', 'late', 'subtotal', 'tax', 'total']
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=directory, prefix='.invoice-', suffix='.tmp')
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.DictWriter(handle, fieldnames=fields)
            writer.writeheader()
            writer.writerows(rows)
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except OSError:
            pass
        raise
    return len(rows)

