from pathlib import Path

def load_donor_batch(base_dir: str, relative_name: str) -> list[dict]:
    base = Path(base_dir).resolve()
    target = (base / relative_name).resolve()
    try:
        target.relative_to(base)
    except ValueError:
        raise ValueError('file is outside base directory')
    with target.open('r', encoding='utf-8') as handle:
        try:
            value = json.load(handle)
        except (json.JSONDecodeError, UnicodeDecodeError) as exc:
            raise ValueError('invalid donor batch') from exc
    if not isinstance(value, dict) or 'donors' not in value or (not isinstance(value['donors'], list)):
        raise ValueError('invalid donor batch')
    return value['donors']

def select_matches(donor: dict, recipients: list[dict], limit: int=10) -> list[dict]:
    if limit < 0:
        raise ValueError('limit must not be negative')
    if donor['blood'] not in {'O', 'A', 'B', 'AB'}:
        raise ValueError('invalid donor blood group')
    compatible = {'O': {'O', 'A', 'B', 'AB'}, 'A': {'A', 'AB'}, 'B': {'B', 'AB'}, 'AB': {'AB'}}[donor['blood']]
    selected = []
    for recipient in recipients:
        gap = abs(donor['age'] - recipient['age'])
        if recipient['blood'] in compatible and recipient['organ'] in donor['organs'] and (gap <= recipient['max_age_gap']) and (recipient['distance_km'] <= recipient['max_distance_km']):
