import csv
import io
import re
_MONTH = re.compile('^\\d{4}-(0[1-9]|1[0-2])$')

def parse_income_csv(text: str) -> list[dict]:
    if not isinstance(text, str):
        raise ValueError('text')
    reader = csv.DictReader(io.StringIO(text))
    if reader.fieldnames is None or set(reader.fieldnames) != {'month', 'source', 'amount'} or len(reader.fieldnames) != 3:
        raise ValueError('header')
    result = []
    for row in reader:
        if all((v is None or not v.strip() for v in row.values())):
            continue
        if None in row or any((v is None for v in row.values())):
            raise ValueError('columns')
        month, source, raw = (row['month'].strip(), row['source'].strip(), row['amount'].strip())
        if not _MONTH.fullmatch(month) or not source:
            raise ValueError('row')
        try:
            amount = float(raw)
        except ValueError:
            raise ValueError('amount')
        if amount < 0 or round(amount, 2) != amount:
            raise ValueError('amount')
        result.append({'month': month, 'source': source, 'amount': amount})
    return result

def calculate_benefit(rows: list[dict], household_size: int, threshold: float=1800.0) -> dict:
    if isinstance(household_size, bool) or household_size <= 0 or threshold <= 0:
        raise ValueError('arguments')
    totals = {}
    for row in rows:
        if not isinstance(row, dict) or not _MONTH.fullmatch(str(row.get('month', ''))):
            raise ValueError('row')
        amount = row.get('amount')
        if not isinstance(amount, (int, float)) or amount < 0:
            raise ValueError('amount')
        totals[row['month']] = totals.get(row['month'], 0) + amount
    months = sorted(totals)[-3:]
    average = sum((totals[m] for m in months)) / len(months) if months else 0
    benefit = max(0, (threshold * household_size - average) * 0.5)
    return {'months_used': months, 'average_income': round(average, 2), 'benefit': round(benefit, 2)}

def build_case_report(requester: dict, cases: list[dict], case_id: str, income_csv: str) -> dict:
    case = next((c for c in cases if c.get('id') == case_id), None)
    if case is None:
        raise KeyError(case_id)
    if not isinstance(case.get('applicant'), str) or not isinstance(case.get('tenant'), str) or (not isinstance(case.get('owner_id'), str)):
        raise ValueError('case')
    size = case.get('household_size')
    if isinstance(size, bool) or not isinstance(size, int) or size <= 0:
        raise ValueError('case')
    allowed = requester.get('id') == case['owner_id'] or ('supervisor' in requester.get('roles', []) and requester.get('tenant') == case['tenant'])
    if not allowed:
        raise PermissionError('case')
    threshold = case.get('threshold', 1800.0)
    if not isinstance(threshold, (int, float)) or threshold <= 0:
        raise ValueError('case')
    return {'case_id': case['id'], 'applicant': case['applicant'], 'tenant': case['tenant'], 'household_size': size, 'calculation': calculate_benefit(parse_income_csv(income_csv), size, threshold)}

