from datetime import datetime, timedelta
from typing import Any

def _allowed(user: dict[str, Any], device: dict[str, Any]) -> bool:
    return user.get('tenant_id') == device.get('tenant_id') and (user.get('id') == device.get('owner_id') or user.get('role') == 'manager')

def _visible(user: dict[str, Any], device: dict[str, Any]) -> bool:
    return user.get('tenant_id') == device.get('tenant_id')

def _aware(value: datetime) -> None:
    if value.tzinfo is None or value.utcoffset() is None:
        raise ValueError('timezone-aware datetime required')

def checkout_device(devices: dict[str, dict[str, Any]], user: dict[str, Any], device_id: str, duration_minutes: int, now: datetime) -> dict[str, Any]:
    device = devices[device_id]
    if not isinstance(duration_minutes, int) or isinstance(duration_minutes, bool) or (not 1 <= duration_minutes <= 480):
        raise ValueError('duration out of range')
    _aware(now)
    if not _allowed(user, device):
        raise PermissionError('not permitted')
    if device.get('checked_out_by') is not None:
        raise RuntimeError('device is checked out')
    until = (now + timedelta(minutes=duration_minutes)).isoformat()
    device['checked_out_by'] = user['id']
    device['checked_out_until'] = until
    return {'device_id': device_id, 'label': device['label'], 'user_id': user['id'], 'checked_out_until': until}

def release_device(devices: dict[str, dict[str, Any]], user: dict[str, Any], device_id: str, now: datetime) -> dict[str, Any]:
    device = devices[device_id]
    _aware(now)
    if not _allowed(user, device):
        raise PermissionError('not permitted')
    if device.get('checked_out_by') is None:
        raise RuntimeError('device is available')
    old_user = device['checked_out_by']
    device['checked_out_by'] = None
    device['checked_out_until'] = None
    return {'device_id': device_id, 'label': device['label'], 'user_id': old_user, 'released_at': now.isoformat()}

