import hashlib
import hmac
from datetime import datetime

def _split(line):
    out = []
    cur = []
    i = 0
    while i < len(line):
        c = line[i]
        if c == '\\':
            i += 1
            if i == len(line) or line[i] not in '\\|':
                raise ValueError('invalid escape')
            cur.append(line[i])
        elif c == '|':
            out.append(''.join(cur))
            cur = []
        else:
            cur.append(c)
        i += 1
    out.append(''.join(cur))
    return out

def parse_signed_record(line: str, key: bytes) -> dict:
    if not isinstance(line, str) or not isinstance(key, (bytes, bytearray, memoryview)):
        raise TypeError('invalid argument type')
    parts = _split(line)
    if len(parts) != 6:
        raise ValueError('wrong field count')
    stamp, unit, task, hours_text, status, digest = parts
    if not unit or not task or len(digest) != 64:
        raise ValueError('invalid field')
    try:
        timestamp = datetime.strptime(stamp, '%Y-%m-%dT%H:%M')
        hours = float(hours_text)
        int(digest, 16)
    except (ValueError, OverflowError):
        raise ValueError('invalid value')
    if not 0 <= hours <= 24 or status not in {'scheduled', 'completed', 'failed'}:
        raise ValueError('invalid value')
    body = '|'.join((stamp, unit, task, hours_text, status)).encode()
    actual = hmac.new(key, body, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(actual.lower(), digest.lower()):
        raise ValueError('digest mismatch')
    return {'timestamp': timestamp, 'unit': unit, 'task': task, 'hours': hours, 'status': status}

def summarize_records(text: str, key: bytes) -> list[dict]:
    if not isinstance(text, str):
        raise TypeError('text must be a string')
    groups = {}
    for line in text.splitlines():
        if not line.strip():
            continue
        record = parse_signed_record(line, key)
        group_key = (record['timestamp'].date().isoformat(), record['unit'])
        if group_key not in groups:
            groups[group_key] = {'date': group_key[0], 'unit': group_key[1], 'records': 0, 'completed_hours': 0.0, 'failed': 0, 'tasks': []}
        group = groups[group_key]
        group['records'] += 1
        if record['status'] == 'completed':
            group['completed_hours'] += record['hours']
        if record['status'] == 'failed':
            group['failed'] += 1
        if record['task'] not in group['tasks']:
            group['tasks'].append(record['task'])
    return [groups[k] for k in sorted(groups)]

