import csv
import datetime
import os
import tempfile

def parse_event(item: dict) -> dict:
    if not isinstance(item, dict):
        raise ValueError('event must be a dictionary')
    try:
        patient_id = item['patient_id']
        timestamp = item['timestamp']
        code = item['code']
        value = item['value']
    except (KeyError, TypeError):
        raise ValueError('missing event field')
    if not isinstance(patient_id, str) or not patient_id or (not isinstance(code, str)) or (not code):
        raise ValueError('invalid text field')
    if not isinstance(value, (int, float)) or isinstance(value, bool):
        raise ValueError('invalid value')
    if not isinstance(timestamp, str):
        raise ValueError('invalid timestamp')
    try:
        dt = datetime.datetime.fromisoformat(timestamp.replace('Z', '+00:00'))
    except ValueError:
        raise ValueError('invalid timestamp')
    if dt.tzinfo is None:
        raise ValueError('timezone required')
    dt = dt.astimezone(datetime.timezone.utc).replace(microsecond=0)
    return {'patient_id': patient_id, 'timestamp': dt.strftime('%Y-%m-%dT%H:%M:%SZ'), 'code': code, 'value': value}

def summarize_records(records: list[dict]) -> list[dict]:
    parsed = [parse_event(x) for x in records]
    groups = {}
    for position, event in enumerate(parsed):
        groups.setdefault(event['patient_id'], []).append((event, position))
    result = []
    for patient_id in sorted(groups):
        entries = sorted(groups[patient_id], key=lambda x: (x[0]['timestamp'], x[0]['code'], x[1]))
        latest = {}
        for event, _ in entries:
            latest[event['code']] = event['value']
        values = '|'.join((f'{code}={latest[code]}' for code in sorted(latest)))
        result.append({'patient_id': patient_id, 'event_count': len(entries), 'first_timestamp': entries[0][0]['timestamp'], 'last_timestamp': entries[-1][0]['timestamp'], 'latest_code_values': values})
    return result

def export_summary(records: list[dict], destination: str) -> dict:
    summaries = summarize_records(records)
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(prefix='emr-export-', suffix='.tmp', dir=directory)
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle)
            writer.writerow(['patient_id', 'event_count', 'first_timestamp', 'last_timestamp', 'latest_code_values'])
            for row in summaries:
                writer.writerow([row[x] for x in ('patient_id', 'event_count', 'first_timestamp', 'last_timestamp', 'latest_code_values')])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return {'patients': len(summaries), 'events': len(records), 'destination': destination}

