import hmac
import json

def summarize_webhook(payload: str, signature: str, webhook_key: str, page: int=1, page_size: int=20) -> dict:
    if not isinstance(signature, str) or not isinstance(webhook_key, str):
        raise ValueError('invalid signature')
    if not hmac.compare_digest(signature, webhook_key):
        raise ValueError('signature mismatch')
    if not isinstance(page, int) or isinstance(page, bool) or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (page <= 0) or (page_size <= 0):
        raise ValueError('invalid pagination')
    try:
        data = json.loads(payload)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(data, dict) or not isinstance(data.get('subscriptions'), list):
        raise ValueError('invalid subscriptions')
    groups = {}
    for record in data['subscriptions']:
        if not isinstance(record, dict) or set(record) != {'issue', 'subscriber', 'status', 'amount_cents'}:
            raise ValueError('invalid record')
        issue = record['issue']
        subscriber = record['subscriber']
        status = record['status']
        amount = record['amount_cents']
        if not all((isinstance(value, str) for value in (issue, subscriber, status))) or not isinstance(amount, int) or isinstance(amount, bool):
            raise ValueError('invalid record')
        if status == 'paid':
            group = groups.setdefault(issue, {'subscribers': set(), 'amount_cents': 0})
            group['subscribers'].add(subscriber)
            group['amount_cents'] += amount
    items = [{'issue': issue, 'subscribers': len(value['subscribers']), 'amount_cents': value['amount_cents']} for issue, value in groups.items()]
    items.sort(key=lambda item: (-item['amount_cents'], item['issue']))
    start = (page - 1) * page_size
    return {'total': len(items), 'page': page, 'page_size': page_size, 'items': items[start:start + page_size]}

