    if result.returncode not in (0, 1):
        raise FileNotFoundError(path)
    records = []
    for line in result.stdout.splitlines():
        if not line:
            continue
        fields = line.split(',')
        if len(fields) != 4 or fields[0] != date:
            continue
        time, title, duration_text = (fields[1], fields[2], fields[3])
        try:
            datetime.datetime.strptime(time, '%H:%M')
            if len(time) != 5 or time[2] != ':':
                continue
            duration = int(duration_text)
            if duration < 0:
                continue
        except ValueError:
            continue
        records.append({'time': time, 'title': title, 'duration': duration})
    records.sort(key=lambda item: (item['time'], item['title']))
    start = (page - 1) * page_size
    return {'date': date, 'total_programs': len(records), 'total_minutes': sum((x['duration'] for x in records)), 'programs': records[start:start + page_size]}

