import os
import subprocess

def summarize_tracking(path: str, species: str, window_minutes: int, limit: int) -> list[dict]:
    if window_minutes <= 0:
        raise ValueError('window_minutes must be positive')
    if limit < 0:
        raise ValueError('limit must not be negative')
    if not os.path.isfile(path):
        raise FileNotFoundError(path)
    completed = subprocess.run(['grep', '-F', species, path], capture_output=True, text=True)
    if completed.returncode not in (0, 1):
        raise FileNotFoundError(path)
    records = []
    for line in completed.stdout.splitlines():
        if not line.strip():
            continue
        fields = line.split('\t')
        if len(fields) != 6:
            raise ValueError('invalid record')
        try:
            timestamp = int(fields[0])
            latitude = float(fields[3])
            longitude = float(fields[4])
            activity = float(fields[5])
        except ValueError as exc:
            raise ValueError('invalid record') from exc
        if fields[2] == species:
            records.append((fields[1], timestamp, latitude, longitude, activity))
    records.sort(key=lambda item: (item[0], item[1]))
    windows = []
    width = window_minutes * 60
    current = None
    for collar, timestamp, latitude, longitude, activity in records:
        if current is None or current[0] != collar or timestamp >= current[1] + width:
            if current is not None:
                windows.append(current)
            current = [collar, timestamp, timestamp + width, 1, latitude, longitude, activity]
        else:
            current[3] += 1
            current[4] += latitude
            current[5] += longitude
            current[6] += activity
    if current is not None:
        windows.append(current)
    result = []
    for collar, start, end, count, lat, lon, activity in windows[:limit]:
        result.append({'collar_id': collar, 'start': start, 'end': end, 'count': count, 'average_latitude': lat / count, 'average_longitude': lon / count, 'total_activity': float(activity)})
    return result

