import os, json, hmac, hashlib
from datetime import date

def _key(config):
    key = config['matter_signing_key'] if config is not None and 'matter_signing_key' in config else os.environ.get('LEGAL_MATTER_SIGNING_KEY')
    if key is None:
        raise RuntimeError('matter signing key is missing')
    if not isinstance(key, str):
        raise ValueError('matter signing key must be a string')
    return key.encode()

def _clean(v):
    if not isinstance(v, str):
        raise ValueError('expected string')
    v = ' '.join(v.split())
    if not v:
        raise ValueError('empty string')
    return v

def prepare_matter_record(matter: dict) -> dict:
    if not isinstance(matter, dict):
        raise ValueError('matter must be a mapping')
    out = []
    for p in matter.get('parties', []):
        if not isinstance(p, dict):
            raise ValueError('invalid party')
        out.append({'name': _clean(p.get('name')), 'role': _clean(p.get('role'))})
    if not isinstance(matter.get('parties'), list):
        raise ValueError('parties must be a list')
    out.sort(key=lambda x: (x['role'], x['name']))
    ev = []
    if not isinstance(matter.get('events'), list):
        raise ValueError('events must be a list')
    for e in matter['events']:
        if not isinstance(e, dict):
            raise ValueError('invalid event')
        i, d, t = (_clean(e.get('id')), _clean(e.get('date')), _clean(e.get('type')))
        h = e.get('hours')
        try:
            date.fromisoformat(d)
        except ValueError:
            raise ValueError('invalid date')
        if isinstance(h, bool) or not isinstance(h, (int, float)) or h < 0:
            raise ValueError('invalid hours')
        ev.append({'id': i, 'date': d, 'type': t, 'hours': round(float(h), 2)})
    ev.sort(key=lambda x: (x['date'], x['id']))
    totals = {}
    for e in ev:
        totals[e['type']] = round(totals.get(e['type'], 0) + e['hours'], 2)
    return {'matter_id': _clean(matter.get('matter_id')), 'jurisdiction': _clean(matter.get('jurisdiction')), 'parties': out, 'events': ev, 'hours_by_type': dict(sorted(totals.items()))}

def issue_matter_token(matter: dict, config: dict | None=None) -> str:
    p = json.dumps(prepare_matter_record(matter), separators=(',', ':'), sort_keys=True)
    return p + '.' + hmac.new(_key(config), p.encode(), hashlib.sha256).hexdigest()

def verify_matter_token(token: str, matter: dict, config: dict | None=None) -> bool:
    key = _key(config)
    try:
        if not isinstance(token, str) or token.count('.') != 1:
            return False
        p, d = token.split('.')
        q = json.dumps(prepare_matter_record(matter), separators=(',', ':'), sort_keys=True)
        x = hmac.new(key, q.encode(), hashlib.sha256).hexdigest()
        return p == q and hmac.compare_digest(d, x)
    except (ValueError, TypeError, json.JSONDecodeError):
        return False

