import operator

def normalize_invoice_number(value: str) -> str:
    if not isinstance(value, str):
        raise TypeError('value must be a string')
    return ''.join((c for c in value.strip().lower() if 'a' <= c <= 'z' or '0' <= c <= '9'))

def evaluate_formula(expression: str, variables: dict[str, int | float | bool]) -> int | float | bool:
    try:
        tree = ast.parse(expression, mode='eval').body

        def ev(n):
            if isinstance(n, ast.Constant) and isinstance(n.value, (int, float)) and (not isinstance(n.value, complex)):
                return n.value
            if isinstance(n, ast.Name) and n.id in variables:
                return variables[n.id]
            if isinstance(n, ast.UnaryOp) and isinstance(n.op, (ast.UAdd, ast.USub, ast.Not)):
                return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(n.op)](ev(n.operand))
            if isinstance(n, ast.BinOp) and isinstance(n.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
                return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(n.op)](ev(n.left), ev(n.right))
            if isinstance(n, ast.BoolOp) and isinstance(n.op, (ast.And, ast.Or)):
                value = ev(n.values[0])
                for part in n.values[1:]:
                    if isinstance(n.op, ast.And) and (not value):
                        return value
                    if isinstance(n.op, ast.Or) and value:
                        return value
                    value = ev(part)
                return value
            if isinstance(n, ast.Compare):
                left = ev(n.left)
                for op, part in zip(n.ops, n.comparators):
                    right = ev(part)
                    fn = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}.get(type(op))
                    if fn is None or not fn(left, right):
                        return False
                    left = right
                return True
            if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and (n.func.id in ('min', 'max', 'round')) and (not n.keywords):
                args = [ev(a) for a in n.args]
                return {'min': min, 'max': max, 'round': round}[n.func.id](*args)
            raise ValueError('unsupported expression')
        result = ev(tree)
        if not isinstance(result, (int, float, bool)) or isinstance(result, complex):
            raise ValueError('invalid result')
        return result
    except Exception as exc:
        if isinstance(exc, ValueError):
            raise
        raise ValueError('invalid expression') from exc

def match_invoices(ocr_rows: list[dict], master_rows: list[dict], expression: str) -> list[dict]:
    if not master_rows:
        raise ValueError('master list is empty')
    result = []
    for oi, ocr in enumerate(ocr_rows):
        candidates = []
        for mi, master in enumerate(master_rows):
            vars = {'number_match': int(normalize_invoice_number(ocr['invoice_no']) == normalize_invoice_number(master['invoice_no'])), 'vendor_match': int(ocr['vendor'].strip().lower() == master['vendor'].strip().lower()), 'date_match': int(ocr['date'].strip() == master['date'].strip()), 'total_diff': abs(ocr['total'] - master['total']), 'confidence': ocr['confidence']}
            score = float(evaluate_formula(expression, vars))
            if not math.isfinite(score):
                raise ValueError('non-finite score')
            candidates.append((score, -vars['total_diff'], -mi, master['id']))
        score, _, _, ident = max(candidates)
