import csv
import math
import os
from decimal import Decimal, InvalidOperation

def write_inventory_report(records: list[dict], base_dir: str, relative_name: str, min_stock: int=0) -> str:
    if not isinstance(base_dir, str) or not os.path.isdir(base_dir):
        raise NotADirectoryError(base_dir)
    if not isinstance(relative_name, str) or not relative_name:
        raise ValueError('invalid report name')
    if not isinstance(min_stock, int) or isinstance(min_stock, bool) or min_stock < 0:
        raise ValueError('invalid minimum')
    if not isinstance(records, list):
        raise ValueError('invalid records')
    grouped = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        if not isinstance(record.get('sku'), str) or not record['sku']:
            raise ValueError('invalid sku')
        if not isinstance(record.get('name'), str):
            raise ValueError('invalid name')
        quantity = record.get('quantity')
        if not isinstance(quantity, int) or isinstance(quantity, bool) or quantity < 0:
            raise ValueError('invalid quantity')
        price = record.get('unit_price')
        if isinstance(price, bool) or not isinstance(price, (int, float)) or price < 0:
            raise ValueError('invalid price')
        try:
            decimal_price = Decimal(str(price))
        except InvalidOperation:
            raise ValueError('invalid price')
        if not decimal_price.is_finite():
            raise ValueError('invalid price')
        sku = record['sku']
        if sku not in grouped:
            grouped[sku] = [record['name'], 0, Decimal('0')]
        grouped[sku][1] += quantity
        grouped[sku][2] += Decimal(quantity) * decimal_price
    rows = [(sku, data) for sku, data in grouped.items() if data[1] >= min_stock]
    rows.sort(key=lambda item: (-item[1][1], item[0]))
    base = os.path.realpath(base_dir)
    destination = os.path.realpath(os.path.join(base, relative_name))
    if os.path.commonpath([base, destination]) != base:
        raise ValueError('invalid report path')
    os.makedirs(os.path.dirname(destination), exist_ok=True)
    with open(destination, 'w', newline='') as handle:
        writer = csv.writer(handle)
        writer.writerow(['SKU', 'Name', 'Quantity', 'Total Value'])
        for sku, data in rows:
            writer.writerow([sku, data[0], data[1], f"{data[2].quantize(Decimal('0.01')):.2f}"])
    return destination

