import sqlite3

def list_cases(conn: sqlite3.Connection, filters: dict[str, object] | None=None, search: str='', sort_by: str='case_id', descending: bool=False, limit: int | None=None, offset: int=0) -> list[dict[str, object]]:
    allowed = {'case_id', 'patient_code', 'diagnosis', 'country', 'status', 'onset_year', 'last_review'}
    filter_keys = {'country', 'status', 'onset_year_min', 'onset_year_max'}
    filters = {} if filters is None else filters
    if any((k not in filter_keys for k in filters)) or sort_by not in allowed:
        raise ValueError('unsupported field')
    if offset < 0 or (limit is not None and limit < 0):
        raise ValueError('invalid page')
    clauses = []
    params = []
    for key in ('country', 'status'):
        if key in filters:
            clauses.append(key + ' = ?')
            params.append(filters[key])
    if 'onset_year_min' in filters:
        clauses.append('onset_year >= ?')
        params.append(filters['onset_year_min'])
    if 'onset_year_max' in filters:
        clauses.append('onset_year <= ?')
        params.append(filters['onset_year_max'])
    if search:
        clauses.append('(lower(patient_code) like lower(?) or lower(diagnosis) like lower(?))')
        term = '%' + search + '%'
        params.extend([term, term])
    query = 'select case_id, patient_code, diagnosis, country, status, onset_year, last_review from cases'
    if clauses:
        query += ' where ' + ' and '.join(clauses)
    query += ' order by ' + sort_by + (' desc' if descending else ' asc') + ', case_id asc'
    if limit is not None:
        query += ' limit ?'
        params.append(limit)
    elif offset:
        query += ' limit -1'
    if offset:
        query += ' offset ?'
        params.append(offset)
