            scheduled.append(record)
    scheduled.sort(key=lambda item: (item['hearing_date'], item['id']))
    total = len(scheduled)
    pages = math.ceil(total / page_size) if total else 0
    start = (page - 1) * page_size
    body = {'items': scheduled[start:start + page_size], 'total': total, 'page': page, 'page_size': page_size, 'pages': pages, 'total_acres': round(sum((item['acres'] for item in scheduled)), 2)}
