        values.append(status)
    if search:
        clauses.append("lower(s.customer || ' ' || s.origin || ' ' || s.destination) like lower(?)")
        values.append('%' + search + '%')
    where = ' where ' + ' and '.join(clauses) if clauses else ''
    sql = 'select s.id, s.customer, s.origin, s.destination, s.weight_kg, s.rate_cents, s.status, s.ship_date, round(s.weight_kg * s.rate_cents) as charge_cents from shipments s' + where + ' order by ' + sort_columns[sort_by] + ', s.id'
    rows = conn.execute(sql, values).fetchall()
    keys = ['id', 'customer', 'origin', 'destination', 'weight_kg', 'rate_cents', 'status', 'ship_date', 'charge_cents']
