import hashlib
import hmac
import os

def create_account(username: str, password: str, items: list[dict]) -> dict:
    if not isinstance(username, str) or not username:
        raise ValueError('invalid username')
    if not isinstance(password, str) or not password:
        raise ValueError('invalid password')
    if not isinstance(items, list):
        raise ValueError('invalid items')
    seen = set()
    normalized = []
    totals = {}
    for item in items:
        if not isinstance(item, dict) or set(item) != {'sku', 'name', 'category', 'quantity', 'unit_price'}:
            raise ValueError('invalid item')
        sku, name, category = (item['sku'], item['name'], item['category'])
        quantity, price = (item['quantity'], item['unit_price'])
        if not all((isinstance(x, str) and x for x in (sku, name, category))) or sku in seen or (not isinstance(quantity, int)) or isinstance(quantity, bool) or (quantity < 0) or (not isinstance(price, (int, float))) or isinstance(price, bool) or (price < 0):
            raise ValueError('invalid item')
        seen.add(sku)
        record = dict(item)
        normalized.append(record)
        totals[category] = totals.get(category, 0) + quantity * price
    normalized.sort(key=lambda x: (x['category'], x['name'], x['sku']))
    salt = os.urandom(16)
    hashed = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return {'username': username, 'password_hash': hashed.hex(), 'salt': salt.hex(), 'items': normalized, 'category_totals': {k: round(v, 2) for k, v in sorted(totals.items())}, 'total_value': round(sum(totals.values()), 2)}

def authenticate(account: dict, password: str) -> bool:
    try:
        if not isinstance(password, str):
            return False
        salt = bytes.fromhex(account['salt'])
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000).hex()
        return hmac.compare_digest(actual, account['password_hash'])
    except (KeyError, TypeError, ValueError):
        return False

