def _split_line(line):
    fields = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape')
    fields.append(''.join(current))
    return fields

def parse_appointments(text: str) -> list[dict]:
    result = []
    seen = set()
    for line in text.splitlines():
        if not line:
            continue
        fields = _split_line(line)
        if len(fields) != 7 or not fields[0]:
            raise ValueError('invalid appointment')
        try:
            start = int(fields[4])
            duration = int(fields[5])
        except ValueError:
            raise ValueError('invalid number')
        if duration < 1 or fields[6] not in {'booked', 'checked_in', 'cancelled'} or fields[0] in seen:
            raise ValueError('invalid appointment')
        seen.add(fields[0])
        result.append({'id': fields[0], 'tenant': fields[1], 'owner': fields[2], 'vessel': fields[3], 'start': start, 'duration': duration, 'status': fields[6]})
    return result

def reschedule_appointment(requester: dict, appointment_id: str, new_start: int, appointments: list[dict], port_windows: dict[str, tuple[int, int]]) -> dict:
    item = next((x for x in appointments if x.get('id') == appointment_id), None)
    if item is None:
        raise KeyError(appointment_id)
    if requester.get('tenant') != item['tenant'] and 'harbor_master' not in requester.get('roles', []):
        raise PermissionError('not permitted')
    if requester.get('id') != item['owner'] and 'harbor_master' not in requester.get('roles', []):
        raise PermissionError('not permitted')
    if item['status'] == 'cancelled':
        raise ValueError('cancelled')
    try:
        lo, hi = port_windows[item['tenant']]
    except KeyError:
        raise KeyError(item['tenant'])
    if new_start < lo or new_start + item['duration'] > hi:
        raise ValueError('outside window')
    end = new_start + item['duration']
    for other in appointments:
        if other is item or other['tenant'] != item['tenant'] or other['status'] == 'cancelled':
            continue
        if new_start < other['start'] + other['duration'] and other['start'] < end:
            raise ValueError('overlap')
    item['start'] = new_start
    return item

