    if 'id' not in requester or 'tenant' not in requester:
        raise KeyError('requester')
    if not tenant:
        raise ValueError('tenant')
    result = [dict(x) for x in appointments if x['tenant'] == tenant and x['status'] != 'cancelled' and (x['start'] + x['duration'] > 0) and (x['start'] < 1440)]
    return sorted(result, key=lambda x: (x['start'], x['duration'], x['id']))

