def hash_collection_pin(pin: str) -> str:
    if not isinstance(pin, str):
        raise TypeError('pin must be a string')
    if not pin:
        raise ValueError('pin must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode('utf-8'), salt, 100000)
    return salt.hex() + ':' + digest.hex()

def verify_collection_pin(pin: str, stored: str) -> bool:
    if not isinstance(pin, str):
        raise TypeError('pin must be a string')
    if not pin or not isinstance(stored, str):
        return False
    try:
        salt_text, digest_text = stored.split(':', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    if len(salt) != 16 or len(expected) != 32:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode('utf-8'), salt, 100000)
    return hmac.compare_digest(actual, expected)

def can_release_collection_hold(pin: str, stored: str, overdue_cents: int) -> bool:
    if overdue_cents <= 0:
        return False
    return verify_collection_pin(pin, stored)

