def generate_invite_code(team: str, length: int=8) -> str:
    if not isinstance(team, str) or not isinstance(length, int) or isinstance(length, bool):
        raise ValueError('invalid arguments')
    team = team.strip()
    if not 2 <= len(team) <= 12 or not team.isascii() or (not team.isalpha()):
        raise ValueError('invalid team')
    if not 6 <= length <= 20:
        raise ValueError('invalid length')
    alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
    return team.upper() + '-' + ''.join((secrets.choice(alphabet) for _ in range(length)))

