            raise ValueError('invalid shift')
        name, hours, status = (item['volunteer'], item['hours'], item['status'])
        if not isinstance(name, str) or not isinstance(status, str) or isinstance(hours, bool) or (not isinstance(hours, (int, float))) or (hours < 0):
            raise ValueError('invalid shift')
        if status == 'completed':
            if name not in totals:
                totals[name] = [0.0, 0]
            totals[name][0] += hours
            totals[name][1] += 1
