def export_work_orders(records: list[dict], technician: str | None=None, min_cost: float=0.0, page: int=1, page_size: int=10) -> str:
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    if isinstance(min_cost, bool) or not isinstance(min_cost, (int, float)) or (not math.isfinite(min_cost)) or (min_cost < 0):
        raise ValueError('invalid minimum cost')
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0 or isinstance(page_size, bool) or (not isinstance(page_size, int)) or (page_size <= 0):
        raise ValueError('invalid pagination')
    rows = []
    for record in records:
        if not isinstance(record, dict):
            raise TypeError('each record must be a dictionary')
        required = ('id', 'property', 'technician', 'cost', 'status', 'completed_date')
        if any((key not in record for key in required)):
            raise ValueError('missing field')
        if any((not isinstance(record[key], str) or not record[key] for key in ('id', 'property', 'technician'))):
            raise ValueError('invalid text field')
        cost = record['cost']
        if isinstance(cost, bool) or not isinstance(cost, (int, float)) or (not math.isfinite(cost)) or (cost < 0):
            raise ValueError('invalid cost')
        if record['status'] not in ('completed', 'scheduled', 'cancelled'):
            raise ValueError('invalid status')
        try:
            datetime.date.fromisoformat(record['completed_date'])
        except (TypeError, ValueError):
            raise ValueError('invalid date')
        if record['status'] == 'completed' and (technician is None or record['technician'] == technician) and (cost >= min_cost):
            rows.append(record)
    rows.sort(key=lambda r: (-r['cost'], r['completed_date'], r['id']))
    start = (page - 1) * page_size
    selected = rows[start:start + page_size]
    fd, path = tempfile.mkstemp()
    try:
        with os.fdopen(fd, 'w', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(('id', 'property', 'technician', 'cost', 'status', 'completed_date'))
            for row in selected:
                writer.writerow((row['id'], row['property'], row['technician'], f"{row['cost']:.2f}", row['status'], row['completed_date']))
        with open(path, 'r', newline='') as handle:
            return handle.read()
    finally:
        try:
            os.unlink(path)
        except FileNotFoundError:
            pass

