import sqlite3
from datetime import date
from typing import Any

def get_customer_summary(conn: sqlite3.Connection, customer_id: int) -> dict[str, Any]:
    customer = conn.execute('SELECT id, name FROM customers WHERE id = ?', (customer_id,)).fetchone()
    if customer is None:
        raise ValueError('customer does not exist')
    row = conn.execute("\n        SELECT COALESCE(SUM(CASE WHEN kind = 'earn' THEN points ELSE 0 END), 0),\n               COALESCE(SUM(CASE WHEN kind = 'redeem' THEN points ELSE 0 END), 0),\n               COUNT(*)\n        FROM transactions WHERE customer_id = ?\n    ", (customer_id,)).fetchone()
    earned, redeemed, count = map(int, row)
    tier = 'gold' if earned >= 1000 else 'silver' if earned >= 500 else 'bronze'
    return {'customer_id': customer[0], 'name': customer[1], 'earned': earned, 'redeemed': redeemed, 'balance': earned - redeemed, 'transaction_count': count, 'tier': tier}

def find_transactions(conn: sqlite3.Connection, customer_id: int, query: str='', sort_by: str='date', descending: bool=False) -> list[dict[str, Any]]:
    columns = {'date': 'occurred_on', 'points': 'points', 'id': 'id'}
    if sort_by not in columns:
        raise ValueError('invalid sort')
    direction = 'DESC' if descending else 'ASC'
    sql = f'SELECT id, kind, points, description, occurred_on FROM transactions WHERE customer_id = ? AND description LIKE ? ORDER BY {columns[sort_by]} {direction}, id ASC'
    rows = conn.execute(sql, (customer_id, '%' + query + '%')).fetchall()
    return [{'id': r[0], 'kind': r[1], 'points': r[2], 'description': r[3], 'occurred_on': r[4]} for r in rows]

def redeem_points(conn: sqlite3.Connection, customer_id: int, points: int, note: str, occurred_on: str) -> int:
    if isinstance(points, bool) or not isinstance(points, int) or points <= 0:
        raise ValueError('points must be positive')
    try:
        date.fromisoformat(occurred_on)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    summary = get_customer_summary(conn, customer_id)
    if summary['balance'] < points:
        raise ValueError('insufficient balance')
    conn.execute("INSERT INTO transactions(customer_id, kind, points, description, occurred_on) VALUES (?, 'redeem', ?, ?, ?)", (customer_id, points, note, occurred_on))
    conn.commit()
    return summary['balance'] - points

