import csv
import copy
import io
import math

def parse_assay_csv(text: str) -> list[dict]:
    rows = list(csv.reader(io.StringIO(text)))
    rows = [row for row in rows if any((cell.strip() for cell in row))]
    if not rows or [x.strip() for x in rows[0]] != ['sample_id', 'depth_m', 'grade_pct', 'element']:
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if len(row) != 4:
            raise ValueError('invalid row')
        sample_id, depth, grade, element = [x.strip() for x in row]
        if not sample_id or not element:
            raise ValueError('empty field')
        try:
            depth_value = float(depth)
            grade_value = float(grade)
        except ValueError as exc:
            raise ValueError('invalid number') from exc
        if not math.isfinite(depth_value) or depth_value < 0 or (not math.isfinite(grade_value)) or (not 0 <= grade_value <= 100):
            raise ValueError('number out of range')
        result.append({'sample_id': sample_id, 'depth_m': depth_value, 'grade_pct': grade_value, 'element': element})
    return result

def update_campaign(requester: dict, campaign: dict, assay_csv: str) -> dict:
    if requester.get('tenant') != campaign.get('tenant'):
        raise ValueError('tenant mismatch')
    if requester.get('id') != campaign.get('owner_id') and 'geologist' not in requester.get('roles', []):
        raise PermissionError('not permitted')
    result = copy.deepcopy(campaign)
    samples = result.setdefault('samples', {})
    for sample_id, sample in samples.items():
        if not isinstance(sample, dict) or not isinstance(sample.get('assays'), list):
            raise ValueError('invalid sample')
    for assay in parse_assay_csv(assay_csv):
        sample = samples.setdefault(assay['sample_id'], {'assays': []})
        sample['assays'].append(assay)
    summary = []
    for sample_id, sample in samples.items():
        assays = sample['assays']
        grades = [float(a['grade_pct']) for a in assays]
        depths = [float(a['depth_m']) for a in assays]
        summary.append({'sample_id': sample_id, 'count': len(assays), 'mean_grade': sum(grades) / len(grades) if grades else 0.0, 'max_depth': max(depths) if depths else 0.0, 'elements': sorted({a['element'] for a in assays})})
    result['summary'] = sorted(summary, key=lambda x: (-x['mean_grade'], x['sample_id']))
    return result

