import hashlib
import hmac

def parse_packet(packet: str) -> tuple[str, int, float, float, str]:
    if not isinstance(packet, str):
        raise ValueError('invalid packet')
    fields = []
    current = []
    escaped = False
    for ch in packet:
        if escaped:
            current.append(ch)
            escaped = False
        elif ch == '\\':
            escaped = True
        elif ch == ';':
            fields.append(''.join(current))
            current = []
        else:
            current.append(ch)
    if escaped:
        raise ValueError('invalid escape')
    fields.append(''.join(current))
    if len(fields) != 5 or any(('\\' in x for x in fields[1:])):
        raise ValueError('invalid packet')
    station, raw_ts, raw_level, raw_flow, tag = fields
    try:
        timestamp = int(raw_ts)
        level = float(raw_level)
        flow = float(raw_flow)
    except ValueError:
        raise ValueError('invalid number')
    if timestamp < 0 or not 0 <= level <= 100000 or flow < 0:
        raise ValueError('out of range')
    if len(tag) != 64 or any((c not in '0123456789abcdef' for c in tag)):
        raise ValueError('invalid tag')
    return (station, timestamp, level, flow, tag)

def record_packet(packet: str, keys: dict[str, bytes], history: dict[str, list[tuple[int, float, float]]]) -> dict[str, object]:
    station, timestamp, level, flow, tag = parse_packet(packet)
    if station not in keys:
        raise ValueError('unknown station')
    canonical = f'{station};{timestamp};{level:.3f};{flow:.3f}'.encode()
    expected = hmac.new(keys[station], canonical, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, tag):
        raise ValueError('invalid tag')
    old = history.get(station, [])
    if old and timestamp <= old[-1][0]:
        raise ValueError('timestamp order')
    readings = old + [(timestamp, level, flow)]
    readings = readings[-3:]
    history[station] = readings
    return {'station': station, 'timestamp': timestamp, 'level': level, 'flow': flow, 'window_level': round(sum((x[1] for x in readings)) / len(readings), 3), 'window_flow': round(sum((x[2] for x in readings)), 3)}

