from solution import summarize_emissions

import os
import tempfile
from decimal import Decimal


def make_file(text):
    fd, path = tempfile.mkstemp()
    try:
        os.write(fd, text.encode("utf-8"))
    finally:
        os.close(fd)
    return path


def test_aggregates_categories_and_orders_by_total():
    path = make_file(
        "source,category,kg\n"
        "factory,energy,10.25\n"
        "truck,transport,8\n"
        "office,energy,2.755\n"
        "flight,travel,20.00\n"
    )
    try:
        assert summarize_emissions(path) == [("travel", 20.0), ("energy", 13.01), ("transport", 8.0)]
    finally:
        os.unlink(path)


def test_ties_are_sorted_alphabetically_and_blank_lines_are_ignored():
    path = make_file(
        "\nsource,category,kg\n"
        "a,zeta,2\n\n"
        "b,alpha,2.00\n"
        "c,beta,2\n"
    )
    try:
        assert summarize_emissions(path) == [("alpha", 2.0), ("beta", 2.0), ("zeta", 2.0)]
    finally:
        os.unlink(path)


def test_pagination_is_one_based():
    path = make_file(
        "source,category,kg\n"
        "a,a,5\n"
        "b,b,4\n"
        "c,c,3\n"
        "d,d,2\n"
        "e,e,1\n"
    )
    try:
        assert summarize_emissions(path, page=1, page_size=2) == [("a", 5.0), ("b", 4.0)]
        assert summarize_emissions(path, page=2, page_size=2) == [("c", 3.0), ("d", 2.0)]
        assert summarize_emissions(path, page=3, page_size=2) == [("e", 1.0)]
        assert summarize_emissions(path, page=4, page_size=2) == []
    finally:
        os.unlink(path)


def test_rounding_uses_decimal_half_up():
    path = make_file(
        "source,category,kg\n"
        "a,materials,1.005\n"
        "b,materials,2.005\n"
    )
    try:
        assert summarize_emissions(path) == [("materials", 3.01)]
    finally:
        os.unlink(path)


def test_empty_data_returns_empty_list():
    path = make_file("source,category,kg\n\n")
    try:
        assert summarize_emissions(path) == []
    finally:
        os.unlink(path)


def test_invalid_pagination_raises_value_error():
    path = make_file("source,category,kg\na,energy,1\n")
    try:
        for page, size in [(0, 1), (1, 0), (-1, 2), (1, -3), (1.5, 2), (1, "2")]:
            try:
                summarize_emissions(path, page, size)
            except ValueError:
                pass
            else:
                assert False
    finally:
        os.unlink(path)


def test_malformed_rows_raise_value_error():
    cases = [
        "source,category,kg\na,energy\n",
        "source,category,kg\na,,1\n",
        "source,category,kg\n,energy,1\n",
        "source,category,kg\na,energy,nope\n",
        "source,category,kg\na,energy,-1\n",
        "wrong,category,kg\na,energy,1\n",
    ]
    for text in cases:
        path = make_file(text)
        try:
            try:
                summarize_emissions(path)
            except ValueError:
                pass
            else:
                assert False
        finally:
            os.unlink(path)


def test_missing_file_raises_file_not_found():
    path = os.path.join(tempfile.gettempdir(), "definitely_missing_emissions_file.csv")
    try:
        os.unlink(path)
    except FileNotFoundError:
        pass
    try:
        summarize_emissions(path)
    except FileNotFoundError:
        pass
    else:
        assert False

