import csv
import io
import subprocess
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def summarize_emissions(path: str, page: int=1, page_size: int=10) -> list[tuple[str, float]]:
    if type(page) is not int or type(page_size) is not int or page < 1 or (page_size < 1):
        raise ValueError('invalid pagination')
    try:
        result = subprocess.run(['cat', path], check=True, capture_output=True, text=True)
    except (subprocess.CalledProcessError, FileNotFoundError):
        raise FileNotFoundError(path)
    rows = [row for row in csv.reader(io.StringIO(result.stdout)) if any((field != '' for field in row))]
    if not rows or rows[0] != ['source', 'category', 'kg']:
        raise ValueError('invalid header')
    totals = {}
    for row in rows[1:]:
        if len(row) != 3 or not row[0] or (not row[1]):
            raise ValueError('invalid row')
        try:
            amount = Decimal(row[2])
        except InvalidOperation:
            raise ValueError('invalid quantity')
        if not amount.is_finite() or amount < 0:
            raise ValueError('invalid quantity')
        totals[row[1]] = totals.get(row[1], Decimal('0')) + amount
    ordered = sorted(totals.items(), key=lambda item: (-item[1], item[0]))
    start = (page - 1) * page_size
    end = start + page_size
    return [(category, float(total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))) for category, total in ordered[start:end]]

