import hashlib
import hmac
import json
from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def _money(value):
    try:
        number = Decimal(str(value))
    except (InvalidOperation, ValueError, TypeError):
        raise ValueError('invalid amount')
    if number < 0:
        raise ValueError('negative amount')
    return number.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

def _day(value):
    try:
        return date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def reconcile_invoices(invoices: list[dict], payments: list[dict], config: dict, as_of: str) -> dict:
    if 'currency' not in config or 'signing_key' not in config:
        raise ValueError('missing configuration')
    today = _day(as_of)
    records = {}
    for invoice in invoices:
        try:
            ident = invoice['id']
            customer = invoice['customer']
            amount = _money(invoice['amount'])
            due = invoice['due_date']
            _day(due)
        except (KeyError, TypeError):
            raise ValueError('malformed invoice')
        if ident in records:
            raise ValueError('duplicate invoice')
        records[ident] = {'customer': customer, 'amount': amount, 'due': due, 'paid': Decimal('0')}
    for payment in payments:
        try:
            ident = payment['invoice_id']
            amount = _money(payment['amount'])
            _day(payment['paid_at'])
        except (KeyError, TypeError):
            raise ValueError('malformed payment')
        if ident in records:
            records[ident]['paid'] += amount
    rank = {'overdue': 0, 'partial': 1, 'open': 2, 'paid': 3}
    items = []
    for ident, record in records.items():
        amount = record['amount']
        paid = record['paid'].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        balance = max(amount - paid, Decimal('0')).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        if paid >= amount:
            status = 'paid'
        elif paid > 0:
            status = 'partial'
        elif _day(record['due']) < today:
            status = 'overdue'
        else:
            status = 'open'
        items.append({'invoice_id': ident, 'customer': record['customer'], 'amount': f'{amount:.2f}', 'paid': f'{paid:.2f}', 'balance': f'{balance:.2f}', 'status': status, 'due_date': record['due']})
    items.sort(key=lambda item: (rank[item['status']], item['due_date'], item['invoice_id']))
    result = {'currency': config['currency'], 'as_of': as_of, 'items': items}
    encoded = json.dumps(result, sort_keys=True, separators=(',', ':')).encode()
