    categories = {}
    for item in admitted:
        categories[item['category']] = categories.get(item['category'], 0) + 1
    start = (page - 1) * page_size
    selected = admitted[start:start + page_size]
    body = {'total_admitted': len(admitted), 'total_pages': sum((item['pages'] for item in admitted)), 'categories': {key: categories[key] for key in sorted(categories)}, 'page': page, 'page_size': page_size, 'exhibits': [{'exhibit_id': item['exhibit_id'], 'title': item['title'], 'category': item['category'], 'pages': item['pages']} for item in selected]}
    key = None
