import os
import zipfile

def sync_catalog(archive_path: str, destination: str, page: int=1, page_size: int=10) -> list[dict]:
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    base = os.path.realpath(destination)
    os.makedirs(base, exist_ok=True)
    rows = []
    with zipfile.ZipFile(archive_path) as archive:
        names = sorted((name for name in archive.namelist() if not name.endswith('/') and name.lower().endswith('.csv')))
        for name in names:
            target = os.path.realpath(os.path.join(base, name))
            if os.path.commonpath((base, target)) != base:
                raise ValueError('invalid archive member')
            os.makedirs(os.path.dirname(target), exist_ok=True)
            with archive.open(name) as source, open(target, 'wb') as output:
                output.write(source.read())
            with open(target, newline='', encoding='utf-8') as source:
                reader = csv.DictReader(source)
                required = {'sku', 'description', 'quantity', 'unit_price', 'active'}
                if not reader.fieldnames or not required.issubset(reader.fieldnames):
                    raise ValueError('missing columns')
                for row in reader:
                    if row['active'].strip().lower() not in {'yes', 'true', '1'}:
                        continue
                    if not row['sku'].strip():
                        raise ValueError('empty sku')
                    try:
                        quantity = int(row['quantity'])
                        price = decimal.Decimal(row['unit_price'])
                    except (decimal.InvalidOperation, TypeError, ValueError):
                        raise ValueError('invalid number')
                    if quantity <= 0 or price < 0:
                        raise ValueError('invalid number')
                    rows.append((row['sku'], row['description'], quantity, price))
    grouped = {}
    for sku, description, quantity, price in rows:
        if sku not in grouped:
            grouped[sku] = [description, 0, decimal.Decimal('0')]
        grouped[sku][1] += quantity
        grouped[sku][2] += price * quantity
    result = [{'sku': sku, 'description': value[0], 'quantity': value[1], 'total_value': float(value[2].quantize(decimal.Decimal('0.01')))} for sku, value in grouped.items()]
    result.sort(key=lambda item: (-item['total_value'], item['sku']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

