import hmac
import json
import math

def build_demand_response(readings: list[dict], config: dict, start: int, end: int, page: int=1, page_size: int=50) -> dict:
    if start >= end:
        raise ValueError('start must be less than end')
    if page <= 0 or page_size <= 0:
        raise ValueError('page and page_size must be positive')
    if 'signing_key' not in config:
        raise ValueError('signing_key is required')
    groups = {}
    for reading in readings:
        site = reading.get('site_id')
        timestamp = reading.get('timestamp')
        kw = reading.get('kw')
        if not isinstance(site, str) or not site:
            raise ValueError('invalid site_id')
        if isinstance(timestamp, bool) or not isinstance(timestamp, int):
            raise ValueError('invalid timestamp')
        if isinstance(kw, bool) or not isinstance(kw, (int, float)) or (not math.isfinite(kw)) or (kw < 0):
            raise ValueError('invalid kw')
        if start <= timestamp < end:
            item = groups.setdefault(site, {'total': 0.0, 'peak': 0.0, 'count': 0})
            item['total'] += kw
            item['peak'] = max(item['peak'], kw)
            item['count'] += 1
    sites = [{'site_id': site, 'total_kw': round(value['total'], 2), 'peak_kw': round(value['peak'], 2), 'reading_count': value['count']} for site, value in groups.items()]
    sites.sort(key=lambda x: (-x['total_kw'], x['site_id']))
    first = (page - 1) * page_size
    payload = {'start': start, 'end': end, 'sites': sites[first:first + page_size]}
    encoded = json.dumps(payload, sort_keys=True, separators=(',', ':')).encode()
    signature = hmac.new(str(config['signing_key']).encode(), encoded, hashlib.sha256).hexdigest()
    return {'payload': payload, 'signature': signature}

