from datetime import date
_TIERS = ('patron', 'supporter', 'artist', 'sustaining')

def membership_summary(requester: dict, organization: dict, events: list[dict], as_of: str) -> dict:
    try:
        cutoff = date.fromisoformat(as_of)
    except Exception as exc:
        raise ValueError('invalid date') from exc
    roles = requester.get('roles', [])
    if requester.get('tenant_id') != organization.get('tenant_id') or (requester.get('id') != organization.get('owner_id') and (not {'director', 'membership_manager'} & set(roles))):
        raise PermissionError('not permitted')
    states = {}
    ordered = []
    for position, event in enumerate(events):
        try:
            when = date.fromisoformat(event['at'])
        except Exception as exc:
            raise ValueError('invalid event date') from exc
        tier = event.get('tier')
        if tier not in _TIERS:
            raise ValueError('invalid tier')
        if when <= cutoff:
            ordered.append((when, position, event))
    for _, _, event in sorted(ordered, key=lambda item: (item[0], item[1])):
        try:
            member_id = event['member_id']
            action = event['action']
            name = event['name']
            email = event['email']
            tier = event['tier']
            when = event['at']
        except KeyError as exc:
            raise ValueError('missing field') from exc
        active = member_id in states
        if action == 'join':
            if active:
                raise ValueError('duplicate join')
            states[member_id] = {'member_id': member_id, 'name': name, 'email': email, 'tier': tier, 'joined': when}
        elif action in ('upgrade', 'downgrade'):
            if not active:
                raise ValueError('member is not active')
            states[member_id]['tier'] = tier
        elif action == 'leave':
            if not active:
                raise ValueError('member is not active')
            del states[member_id]
        else:
            raise ValueError('invalid action')
    members = list(states.values())
    rank = {tier: index for index, tier in enumerate(_TIERS)}
    members.sort(key=lambda member: (rank[member['tier']], member['name'].casefold(), member['member_id']))
    counts = {'active': len(members), **{tier: 0 for tier in _TIERS}}
    for member in members:
        counts[member['tier']] += 1
    return {'organization': organization['name'], 'as_of': as_of, 'counts': counts, 'members': members}

