    output = io.StringIO(newline='')
    writer = csv.writer(output, lineterminator='\r\n')
    writer.writerow(('member_id', 'name', 'email', 'tier', 'joined'))
    for member in report['members']:
        writer.writerow(tuple((member[field] for field in ('member_id', 'name', 'email', 'tier', 'joined'))))
    return output.getvalue()

