import hashlib
import hmac
import json

def summarize_registration_webhook(body: bytes, shared_key: bytes, signature: str) -> dict:
    if not isinstance(signature, str) or not signature.startswith('sha256='):
        raise ValueError('invalid signature')
    encoded = signature[7:]
    if len(encoded) != 64:
        raise ValueError('invalid signature')
    try:
        supplied = bytes.fromhex(encoded)
    except ValueError:
        raise ValueError('invalid signature')
    expected = hmac.new(shared_key, body, hashlib.sha256).digest()
    if not hmac.compare_digest(expected, supplied):
        raise ValueError('invalid signature')
    try:
        data = json.loads(body.decode('utf-8'))
        registrations = data['registrations']
        if not isinstance(data, dict) or not isinstance(registrations, list):
            raise ValueError
        prices = {'standard': 15000, 'student': 9000, 'workshop': 22000}
        groups = {}
        names = []
        total = 0
        for item in registrations:
            if not isinstance(item, dict):
                raise ValueError
            name = item.get('name')
            track = item.get('track')
            ticket = item.get('ticket')
            if not isinstance(name, str) or not isinstance(track, str) or ticket not in prices:
                raise ValueError
            name = name.strip()
            track = track.strip()
            if not name or not track:
                raise ValueError
            amount = prices[ticket]
            names.append(name)
            total += amount
            group = groups.setdefault(track, {'name': track, 'count': 0, 'total_cents': 0})
            group['count'] += 1
            group['total_cents'] += amount
        tracks = list(groups.values())
        tracks.sort(key=lambda x: (-x['count'], -x['total_cents'], x['name']))
        names.sort(key=lambda x: (x.casefold(), x))
        return {'count': len(registrations), 'total_cents': total, 'tracks': tracks, 'attendees': names}
    except (KeyError, TypeError, ValueError, UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('invalid payload')

