from datetime import date
from lxml import etree

def summarize_crossings(xml_text: str, country: str | None=None, page: int=1, page_size: int=10) -> dict:
    if type(page) is not int or type(page_size) is not int or page <= 0 or (page_size <= 0):
        raise ValueError('invalid pagination')
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode('utf-8'), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'crossings':
        raise ValueError('invalid root')
    records = []
    required = {'id', 'country', 'date', 'travelers', 'cargo_kg'}
    for node in root:
        if node.tag != 'record' or set(node.attrib) != required or len(node):
            raise ValueError('invalid record')
        try:
            record_date = date.fromisoformat(node.attrib['date'])
            travelers = int(node.attrib['travelers'])
            cargo = float(node.attrib['cargo_kg'])
        except Exception as exc:
            raise ValueError('invalid record values') from exc
        if travelers < 0 or cargo < 0:
            raise ValueError('invalid record values')
        if country is None or node.attrib['country'] == country:
            records.append({'id': node.attrib['id'], 'country': node.attrib['country'], 'date': record_date.isoformat(), 'travelers': travelers, 'cargo_kg': cargo})
    records.sort(key=lambda item: (item['date'], item['id']))
    counts = {}
    for item in records:
        counts[item['country']] = counts.get(item['country'], 0) + 1
    total = len(records)
    start = (page - 1) * page_size
    return {'total': total, 'page': page, 'page_size': page_size, 'pages': (total + page_size - 1) // page_size, 'records': records[start:start + page_size], 'total_travelers': sum((item['travelers'] for item in records)), 'total_cargo': round(sum((item['cargo_kg'] for item in records)), 2), 'by_country': dict(sorted(counts.items()))}

