            continue
        fields = _split_fields(raw)
        if len(fields) != 4 or not fields[0] or (not fields[1]):
            raise ValueError('invalid record')
        if fields[0] in seen:
            raise ValueError('duplicate request id')
        try:
            priority = int(fields[2])
        except ValueError:
            raise ValueError('invalid priority')
        if not 0 <= priority <= 9:
            raise ValueError('invalid priority')
        stamp = fields[3]
        if not stamp.endswith('Z'):
            raise ValueError('invalid timestamp')
        try:
            when = datetime.fromisoformat(stamp[:-1] + '+00:00')
        except ValueError:
            raise ValueError('invalid timestamp')
        if when.tzinfo is None or when.utcoffset() != timezone.utc.utcoffset(when):
            raise ValueError('invalid timestamp')
        seen.add(fields[0])
        records.append({'request_id': fields[0], 'member_name': fields[1], 'priority': priority, 'requested_at': when})
    records.sort(key=lambda r: (-r['priority'], r['requested_at'], r['request_id']))
    return records

