from datetime import date as Date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def build_hvac_schedule(xml_text: str, technician: str | None=None, date: str | None=None, page: int=1, page_size: int=10) -> list[dict]:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
    try:
        if date is not None:
            Date.fromisoformat(date)
        root = ET.fromstring(xml_text)
    except (ET.ParseError, TypeError, ValueError):
        raise ValueError('invalid XML or date')
    if root.tag != 'schedule':
        raise ValueError('invalid root')
    jobs = []
    for node in root:
        if node.tag != 'job':
            raise ValueError('unexpected element')
        try:
            ident = node.attrib['id']
            tech = node.attrib['technician']
            day = node.attrib['date']
            duration = int(node.attrib['duration_minutes'])
            priority = int(node.attrib['priority'])
            rate = Decimal(node.attrib['hourly_rate'])
            Date.fromisoformat(day)
        except (KeyError, TypeError, ValueError, InvalidOperation):
            raise ValueError('invalid job')
        if not ident or not tech or (not day) or (duration < 0) or (priority < 0) or (not rate.is_finite()) or (rate < 0):
            raise ValueError('invalid job')
        if technician is not None and tech != technician:
            continue
        if date is not None and day != date:
            continue
        cost = (rate * Decimal(duration) / Decimal(60)).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        jobs.append({'id': ident, 'technician': tech, 'date': day, 'duration_minutes': duration, 'priority': priority, 'cost': float(cost)})
    jobs.sort(key=lambda item: (item['date'], -item['priority'], item['id']))
    start = (page - 1) * page_size
    return jobs[start:start + page_size]

