def _init(conn):
    conn.execute('CREATE TABLE IF NOT EXISTS consent_events (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id TEXT NOT NULL, purpose TEXT NOT NULL, granted INTEGER NOT NULL, occurred_at TEXT NOT NULL)')
    conn.commit()

def record_consent(conn: sqlite3.Connection, user_id: str, purpose: str, granted: bool, occurred_at: str) -> int:
    if not isinstance(user_id, str) or not user_id:
        raise ValueError('invalid user_id')
    if not isinstance(purpose, str) or not purpose:
        raise ValueError('invalid purpose')
    if not isinstance(granted, bool):
        raise ValueError('invalid granted')
    if not isinstance(occurred_at, str) or not occurred_at:
        raise ValueError('invalid occurred_at')
    _init(conn)
    cur = conn.execute('INSERT INTO consent_events (user_id, purpose, granted, occurred_at) VALUES (?, ?, ?, ?)', (user_id, purpose, int(granted), occurred_at))
    conn.commit()
    return int(cur.lastrowid)

def summarize_consents(conn: sqlite3.Connection, purposes: list[str] | None=None, search: str | None=None, sort_by: str='user_id', descending: bool=False) -> list[dict]:
    if purposes is not None and (not isinstance(purposes, list) or any((not isinstance(x, str) or not x for x in purposes))):
        raise ValueError('invalid purposes')
    if search is not None and (not isinstance(search, str)):
        raise ValueError('invalid search')
    if sort_by not in {'user_id', 'purpose', 'granted', 'occurred_at'}:
        raise ValueError('invalid sort')
    if not isinstance(descending, bool):
        raise ValueError('invalid direction')
    _init(conn)
    clauses = []
    if purposes is not None:
        if not purposes:
            return []
        clauses.append('purpose IN (' + ','.join(("'" + x + "'" for x in purposes)) + ')')
    if search is not None:
        clauses.append("user_id LIKE '%" + search + "%'")
    where = ' WHERE ' + ' AND '.join(clauses) if clauses else ''
    direction = ' DESC' if descending else ' ASC'
    sql = 'WITH latest AS (SELECT user_id, purpose, granted, occurred_at, ROW_NUMBER() OVER (PARTITION BY user_id, purpose ORDER BY occurred_at DESC, id DESC) AS rn FROM consent_events) SELECT user_id, purpose, granted, occurred_at FROM latest' + where.replace('purpose', 'latest.purpose').replace('user_id', 'latest.user_id') + ' AND rn = 1' if where else 'WITH latest AS (SELECT user_id, purpose, granted, occurred_at, ROW_NUMBER() OVER (PARTITION BY user_id, purpose ORDER BY occurred_at DESC, id DESC) AS rn FROM consent_events) SELECT user_id, purpose, granted, occurred_at FROM latest WHERE rn = 1'
    sql += ' ORDER BY ' + sort_by + direction + ', user_id ASC, purpose ASC, occurred_at ASC'
    return [dict(zip(('user_id', 'purpose', 'granted', 'occurred_at'), row)) for row in conn.execute(sql) if row[-1] is not None]

def consent_history(conn: sqlite3.Connection, user_id: str) -> list[dict]:
    if not isinstance(user_id, str) or not user_id:
        raise ValueError('invalid user_id')
    _init(conn)
    rows = conn.execute('SELECT id, purpose, granted, occurred_at FROM consent_events WHERE user_id = ? ORDER BY occurred_at ASC, id ASC', (user_id,))
    return [dict(zip(('id', 'purpose', 'granted', 'occurred_at'), row)) for row in rows]

