def issue_exam_invites(records: list[dict[str, object]], page: int, page_size: int) -> list[dict[str, str]]:
    if isinstance(page, bool) or not isinstance(page, int):
        raise TypeError('page must be an integer')
    if isinstance(page_size, bool) or not isinstance(page_size, int):
        raise TypeError('page_size must be an integer')
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    eligible = []
    for record in records:
        if not isinstance(record, dict):
            raise TypeError('record must be a dictionary')
        for key in ('student_id', 'status', 'attempts', 'score'):
            if key not in record:
                raise TypeError('missing field')
        student_id = record['student_id']
        status = record['status']
        attempts = record['attempts']
        score = record['score']
        if not isinstance(student_id, str) or not isinstance(status, str):
            raise TypeError('invalid text field')
        if isinstance(attempts, bool) or not isinstance(attempts, int):
            raise TypeError('invalid attempts')
        if isinstance(score, bool) or not isinstance(score, (int, float)):
            raise TypeError('invalid score')
        if attempts < 0 or score < 0 or score > 100:
            raise ValueError('invalid numeric value')
        if status == 'approved' and attempts < 3:
            eligible.append((score, student_id))
    eligible.sort(key=lambda item: (-item[0], item[1]))
    start = (page - 1) * page_size
    selected = eligible[start:start + page_size]
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    used = set()
    result = []
    for score, student_id in selected:
        code = 'EX-' + ''.join((secrets.choice(alphabet) for _ in range(10)))
        while code in used:
            code = 'EX-' + ''.join((secrets.choice(alphabet) for _ in range(10)))
        used.add(code)
        result.append({'student_id': student_id, 'code': code})
    return result

