from solution import summarize_signed_inspections

def make_blob(records, secret=b"field-key"):
    encoded = json.dumps(records, sort_keys=True, separators=(",", ":")).encode()
    signature = hmac.new(secret, encoded, hashlib.sha256).hexdigest()
    return json.dumps({"records": records, "signature": signature})

def test_groups_active_records_and_ignores_closed_records():
    records=[{"corridor":"North","acres":1.25,"priority":3,"status":"active"},{"corridor":"North","acres":2.5,"priority":5,"status":"active"},{"corridor":"North","acres":99,"priority":1,"status":"closed"},{"corridor":"South","acres":4,"priority":2,"status":"active"}]
    assert summarize_signed_inspections(make_blob(records),b"field-key")=={"page":1,"page_size":10,"total":2,"items":[{"corridor":"South","acres":4.0,"count":1,"max_priority":2},{"corridor":"North","acres":3.75,"count":2,"max_priority":5}]}

def test_ties_are_sorted_by_corridor_and_rounding_is_applied():
    records=[{"corridor":"Zeta","acres":1.005,"priority":1,"status":"active"},{"corridor":"Alpha","acres":2.0,"priority":4,"status":"active"},{"corridor":"Zeta","acres":0.995,"priority":2,"status":"active"}]
    assert summarize_signed_inspections(make_blob(records),b"field-key")["items"]==[{"corridor":"Alpha","acres":2.0,"count":1,"max_priority":4},{"corridor":"Zeta","acres":2.0,"count":2,"max_priority":2}]

def test_pagination_and_past_end_page():
    records=[{"corridor":n,"acres":a,"priority":1,"status":"active"} for n,a in [("A",1),("B",3),("C",2)]]
    assert summarize_signed_inspections(make_blob(records),b"field-key",page=2,page_size=2)=={"page":2,"page_size":2,"total":3,"items":[{"corridor":"A","acres":1.0,"count":1,"max_priority":1}]}
    assert summarize_signed_inspections(make_blob(records),b"field-key",page=3,page_size=2)=={"page":3,"page_size":2,"total":3,"items":[]}

def test_empty_records():
    assert summarize_signed_inspections(make_blob([]),b"field-key")=={"page":1,"page_size":10,"total":0,"items":[]}

def test_bad_signature_and_wrong_secret_raise_value_error():
    records=[{"corridor":"A","acres":1,"priority":1,"status":"active"}]
    blob=json.loads(make_blob(records)); blob["signature"]="0"*64
    with pytest.raises(ValueError): summarize_signed_inspections(json.dumps(blob),b"field-key")
    with pytest.raises(ValueError): summarize_signed_inspections(make_blob(records),b"other-key")

def test_malformed_json_and_invalid_record_raise_value_error():
