    with pytest.raises(ValueError): summarize_signed_inspections(make_blob([{"corridor":"","acres":1,"priority":1,"status":"active"}]),b"field-key")
    with pytest.raises(ValueError): summarize_signed_inspections(make_blob([{"corridor":"A","acres":-1,"priority":1,"status":"active"}]),b"field-key")

