import hashlib, hmac, json, math

def summarize_signed_inspections(blob: str, secret: bytes, page: int=1, page_size: int=10) -> dict:
    if not isinstance(secret, bytes):
        raise ValueError('invalid secret')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1 or (page_size > 100):
        raise ValueError('invalid page size')
    try:
        outer = json.loads(blob)
    except Exception as e:
        raise ValueError('invalid json') from e
    if not isinstance(outer, dict) or set(outer) != {'records', 'signature'}:
        raise ValueError('invalid document')
    records, sig = (outer['records'], outer['signature'])
    if not isinstance(records, list) or not isinstance(sig, str):
        raise ValueError('invalid document')
    canonical = json.dumps(records, sort_keys=True, separators=(',', ':')).encode()
    expected = hmac.new(secret, canonical, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(sig, expected):
        raise ValueError('invalid signature')
    groups = {}
    for r in records:
        if not isinstance(r, dict) or set(r) != {'corridor', 'acres', 'priority', 'status'}:
            raise ValueError('invalid record')
        c, a, p, s = (r['corridor'], r['acres'], r['priority'], r['status'])
        if not isinstance(c, str) or not c:
            raise ValueError('invalid corridor')
        if isinstance(a, bool) or not isinstance(a, (int, float)) or (not math.isfinite(a)) or (a < 0):
            raise ValueError('invalid acres')
        if isinstance(p, bool) or not isinstance(p, int) or p < 1 or (p > 5):
            raise ValueError('invalid priority')
        if s not in {'active', 'closed'}:
            raise ValueError('invalid status')
        if s == 'active':
            g = groups.setdefault(c, [0.0, 0, 0])
            g[0] += a
            g[1] += 1
            g[2] = max(g[2], p)
    ordered = sorted(groups.items(), key=lambda x: (-x[1][0], x[0]))
    items = [{'corridor': c, 'acres': round(v[0], 2), 'count': v[1], 'max_priority': v[2]} for c, v in ordered]
    start = (page - 1) * page_size
    return {'page': page, 'page_size': page_size, 'total': len(items), 'items': items[start:start + page_size]}

