from datetime import datetime, timezone, timedelta

def parse_log_records(text: str) -> list[dict]:
    if not isinstance(text, str):
        raise ValueError('text')
    out = []
    for raw in text.splitlines():
        if not raw:
            continue
        fields, cur, esc = ([], [], False)
        for ch in raw:
            if esc:
                if ch not in '\\|':
                    raise ValueError('escape')
                cur.append(ch)
                esc = False
            elif ch == '\\':
                esc = True
            elif ch == '|' and len(fields) < 2:
                fields.append(''.join(cur))
                cur = []
            else:
                cur.append(ch)
        if esc:
            raise ValueError('escape')
        fields.append(''.join(cur))
        if len(fields) != 3 or not fields[1]:
            raise ValueError('line')
        try:
            stamp = datetime.fromisoformat(fields[0].replace('Z', '+00:00'))
        except Exception as e:
            raise ValueError('timestamp') from e
        if stamp.tzinfo is None:
            raise ValueError('timezone')
        out.append({'timestamp': stamp.astimezone(timezone.utc), 'level': fields[1], 'message': fields[2]})
    return out

def build_retention_plan(requester: dict, resources: list[dict], now: datetime) -> list[dict]:
    if now.tzinfo is None:
        raise ValueError('now')
    now = now.astimezone(timezone.utc)
    result = []
    for r in sorted(resources, key=lambda x: x['id']):
        if not (r['owner_id'] == requester.get('id') or ('admin' in requester.get('roles', []) and r['tenant_id'] == requester.get('tenant_id'))):
            raise PermissionError('resource access denied')
        try:
            cutoff = now - timedelta(days=r['retention_days'])
            records = parse_log_records(r['log'])
            kept = []
            for i, rec in enumerate(records):
                if rec['timestamp'] < cutoff and rec['level'] not in r['keep_levels']:
                    item = dict(rec)
                    item['line_bytes'] = len(r['log'].splitlines(True)[i].encode())
                    kept.append(item)
            kept.sort(key=lambda x: x['timestamp'])
        except PermissionError:
            raise
        except Exception as e:
            raise ValueError('resource') from e
        result.append({'resource_id': r['id'], 'cutoff': cutoff, 'records': kept, 'bytes_reclaimable': sum((x['line_bytes'] for x in kept))})
    return result

