from solution import build_inspection_report, issue_review_token
import pytest

def test_empty_report():
    result = build_inspection_report([])
    assert result == {'total': 0, 'page': 1, 'page_size': 10, 'pages': 0, 'items': [], 'summary': {'pass_count': 0, 'fail_count': 0, 'average_score': 0.0, 'finding_counts': {}}}

def test_summary_and_alphabetical_finding_counts():
    records = [{'inspection_id': '2', 'inspector': 'A', 'score': 80.125, 'status': 'pass', 'findings': ['zeta', 'alpha']}, {'inspection_id': '1', 'inspector': 'B', 'score': 79.124, 'status': 'fail', 'findings': ['alpha', 'middle']}, {'inspection_id': '3', 'inspector': 'C', 'score': 90, 'status': 'pass', 'findings': []}]
    result = build_inspection_report(records)
    assert result['summary'] == {'pass_count': 2, 'fail_count': 1, 'average_score': 83.08, 'finding_counts': {'alpha': 2, 'middle': 1, 'zeta': 1}}
    assert [x['inspection_id'] for x in result['items']] == ['3', '2', '1']

def test_page_boundaries_and_validation():
    record = {'inspection_id': 'x', 'inspector': 'A', 'score': 50, 'status': 'pass', 'findings': []}
    assert build_inspection_report([record], page=2, page_size=1)['items'] == []
    assert build_inspection_report([record], page=1, page_size=1)['pages'] == 1
    with pytest.raises(ValueError):
        build_inspection_report([record], page=0)
    with pytest.raises(ValueError):
        build_inspection_report([record], page_size=101)
    with pytest.raises(ValueError):
        build_inspection_report([record], page=True)

def test_invalid_records_raise_value_error():
    base = {'inspection_id': 'x', 'inspector': 'A', 'score': 50, 'status': 'pass', 'findings': []}
    cases = [{**base, 'score': True}, {**base, 'score': 101}, {**base, 'status': 'unknown'}, {**base, 'findings': [3]}, {**base, 'inspection_id': ''}, {**base, 'inspection_id': 'x'}]
    for bad in cases:
        records = [base, bad] if bad['inspection_id'] == 'x' else [bad]
        with pytest.raises(ValueError):
            build_inspection_report(records)

def test_token_format_and_lengths():
    for length in (8, 16, 64):
        token = issue_review_token(length)
        assert isinstance(token, str)
        assert len(token) == length
        assert all((c in 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789' for c in token))

def test_token_length_validation_and_distinct_calls():
    for length in (7, 65, 1, 100):
        with pytest.raises(ValueError):
            issue_review_token(length)
    with pytest.raises(ValueError):
        issue_review_token(True)
    assert issue_review_token(32) != issue_review_token(32)

