import secrets
import string

def build_inspection_report(records: list[dict], page: int=1, page_size: int=10) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    seen = set()
    normalized = []
    pass_count = 0
    fail_count = 0
    scores = []
    findings = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        required = {'inspection_id', 'inspector', 'score', 'status', 'findings'}
        if set(record) != required:
            raise ValueError('invalid record')
        ident = record['inspection_id']
        inspector = record['inspector']
        score = record['score']
        status = record['status']
        item_findings = record['findings']
        if not isinstance(ident, str) or not ident or ident in seen:
            raise ValueError('invalid inspection id')
        if not isinstance(inspector, str) or not inspector:
            raise ValueError('invalid inspector')
        if isinstance(score, bool) or not isinstance(score, (int, float)) or (not 0 <= score <= 100):
            raise ValueError('invalid score')
        if status not in ('pass', 'fail') or not isinstance(item_findings, list) or (not all((isinstance(x, str) for x in item_findings))):
            raise ValueError('invalid record')
        seen.add(ident)
        scores.append(score)
        pass_count += status == 'pass'
        fail_count += status == 'fail'
        for finding in item_findings:
            findings[finding] = findings.get(finding, 0) + 1
        normalized.append({'inspection_id': ident, 'inspector': inspector, 'score': score, 'status': status, 'findings': list(item_findings)})
    normalized.sort(key=lambda x: (-x['score'], x['inspection_id']))
    start = (page - 1) * page_size
    items = normalized[start:start + page_size]
    for item in items:
        item['score'] = round(item['score'], 2)
    total = len(normalized)
    return {'total': total, 'page': page, 'page_size': page_size, 'pages': (total + page_size - 1) // page_size if total else 0, 'items': items, 'summary': {'pass_count': pass_count, 'fail_count': fail_count, 'average_score': round(sum(scores) / total, 2) if total else 0.0, 'finding_counts': dict(sorted(findings.items()))}}

