    try:
        root = etree.fromstring(xml_text.encode('utf-8'), parser)
    except (etree.XMLSyntaxError, ValueError) as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'appointments':
        raise ValueError('unexpected root')
    result = []
    for child in root:
        if child.tag != 'appointment':
            raise ValueError('unexpected child')
        values = {}
        for name in ('id', 'date', 'office'):
            value = child.get(name)
            if value is None or value == '':
                raise ValueError('missing attribute')
            values[name] = value
        status = child.get('status', 'scheduled')
        if status == '':
            raise ValueError('empty status')
        values['status'] = status
        result.append(values)
    return result

