        seen.add(values['id'])
        if min_vintage is None or vintage >= min_vintage:
            records.append((values['id'], values['generator'], values['technology'], vintage, volume, price))
    records.sort(key=lambda item: (item[5], item[0]))
    total = sum((item[4] for item in records), Decimal('0'))
    average = sum((item[5] for item in records), Decimal('0')) / len(records) if records else Decimal('0')
