import datetime
import subprocess

def parse_claim_line(line: str) -> dict:
    if line.endswith('\n'):
        line = line[:-1]
    if not line:
        raise ValueError('blank claim')
    fields = line.split('|')
    if len(fields) != 6:
        raise ValueError('invalid claim')
    claim_id, region, amount, status, days, filed_date = fields
    if not claim_id or not region or status not in {'approved', 'denied', 'pending'}:
        raise ValueError('invalid claim')
    try:
        amount_value = int(amount)
        days_value = int(days)
        datetime.date.fromisoformat(filed_date)
    except ValueError as exc:
        raise ValueError('invalid claim') from exc
    if amount_value < 0 or days_value < 0 or len(filed_date) != 10:
        raise ValueError('invalid claim')
    return {'claim_id': claim_id, 'region': region, 'amount_cents': amount_value, 'status': status, 'days_open': days_value, 'filed_date': filed_date}

def assess_claims(path: str, region: str | None=None) -> dict:
    command = ['sort', '-t', '|', '-k2,2', '-k1,1', '--', path]
    try:
        completed = subprocess.run(command, check=True, capture_output=True, text=True)
    except subprocess.CalledProcessError as exc:
        raise OSError('unable to read claims') from exc
    records = []
    for line in completed.stdout.splitlines():
        if not line:
            continue
        if region is not None:
            prefix = line.split('|', 2)
            if len(prefix) < 2 or prefix[1] != region:
                continue
        records.append(parse_claim_line(line))
    seen = set()
    groups = {}
    for claim in records:
        if claim['claim_id'] in seen:
            raise ValueError('duplicate claim id')
        seen.add(claim['claim_id'])
        group = groups.setdefault(claim['region'], {'claim_count': 0, 'total_amount_cents': 0, 'approved_cents': 0, 'denied_cents': 0, 'pending_cents': 0, 'days_total': 0, 'claim_ids': []})
        group['claim_count'] += 1
        group['total_amount_cents'] += claim['amount_cents']
        group[claim['status'] + '_cents'] += claim['amount_cents']
        group['days_total'] += claim['days_open']
        group['claim_ids'].append(claim['claim_id'])
    result_groups = {}
    for key, group in groups.items():
        count = group['claim_count']
        result_groups[key] = {'claim_count': count, 'total_amount_cents': group['total_amount_cents'], 'approved_cents': group['approved_cents'], 'denied_cents': group['denied_cents'], 'pending_cents': group['pending_cents'], 'average_days_open': round(group['days_total'] / count, 2) if count else 0.0, 'claim_ids': group['claim_ids']}
    return {'claim_count': len(records), 'total_amount_cents': sum((item['total_amount_cents'] for item in result_groups.values())), 'by_region': result_groups}

