        if not isinstance(payload[key], str):
            raise ValueError('invalid date')
        try:
            date = datetime.date.fromisoformat(payload[key])
        except ValueError:
            raise ValueError('invalid date')
        if date.isoformat() != payload[key]:
            raise ValueError('invalid date')
