import hmac
import json

def parse_alert(raw: str) -> dict:
    if not isinstance(raw, str) or not raw:
        raise ValueError('invalid alert')
    parts, cur, escaped = ([], [], False)
    for ch in raw:
        if escaped:
            cur.append(ch)
            escaped = False
        elif ch == '\\':
            escaped = True
        elif ch == '&':
            if not cur:
                raise ValueError('invalid field')
            parts.append(''.join(cur))
            cur = []
        else:
            cur.append(ch)
    if escaped or not cur:
        raise ValueError('invalid alert')
    parts.append(''.join(cur))
    out = {}
    for part in parts:
        if '=' not in part:
            raise ValueError('invalid field')
        name, value = part.split('=', 1)
        if not name or name in out:
            raise ValueError('invalid field')
        out[name] = value
    if set(out) != {'kid', 'ts', 'sig', 'body'}:
        raise ValueError('invalid fields')
    return {k: out[k] for k in ('kid', 'ts', 'sig', 'body')}

def verify_alert(raw: str, keys: dict[str, bytes], now: int, max_age: int=300) -> dict:
    a = parse_alert(raw)
    if max_age < 0:
        raise ValueError('invalid age')
    try:
        timestamp = int(a['ts'], 10)
    except Exception as exc:
        raise ValueError('invalid timestamp') from exc
    if timestamp > now or now - timestamp > max_age or a['kid'] not in keys:
        raise ValueError('invalid alert')
    if len(a['sig']) != 64:
        raise ValueError('invalid signature')
    try:
        supplied = bytes.fromhex(a['sig'])
    except ValueError as exc:
        raise ValueError('invalid signature') from exc
    message = (a['kid'] + '\n' + a['ts'] + '\n' + a['body']).encode()
    expected = hmac.new(keys[a['kid']], message, hashlib.sha256).digest()
    if not hmac.compare_digest(supplied, expected):
        raise ValueError('invalid signature')
    try:
        data = json.loads(a['body'])
        items = data['items']
    except Exception as exc:
        raise ValueError('invalid body') from exc
    if not isinstance(data, dict) or not isinstance(items, list):
        raise ValueError('invalid body')
    counts = {'positive': 0, 'negative': 0, 'neutral': 0}
    outlets, total = ([], 0)
    for item in items:
        if not isinstance(item, dict) or not isinstance(item.get('outlet'), str) or (not item['outlet']):
            raise ValueError('invalid item')
        if item.get('sentiment') not in counts or isinstance(item.get('reach'), bool) or (not isinstance(item.get('reach'), int)) or (item['reach'] < 0):
            raise ValueError('invalid item')
        counts[item['sentiment']] += 1
        total += item['reach']
        outlets.append({'outlet': item['outlet'], 'reach': item['reach']})
    outlets.sort(key=lambda x: (-x['reach'], x['outlet']))
    return {'kid': a['kid'], 'timestamp': timestamp, 'count': len(items), 'total_reach': total, 'sentiment_counts': counts, 'outlets': outlets}

