import json
import hmac
import hashlib
import math

def parse_telemetry_line(line: str) -> dict[str, object]:
    fields = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            if char not in '\\|':
                raise ValueError('invalid escape')
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current).strip())
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('invalid escape')
    fields.append(''.join(current).strip())
    if len(fields) != 4 or any((not x for x in fields)):
        raise ValueError('invalid telemetry line')
    try:
        timestamp = int(fields[0])
        value = float(fields[3])
    except ValueError as exc:
        raise ValueError('invalid telemetry value') from exc
    if timestamp < 0 or not math.isfinite(value) or str(timestamp) != fields[0]:
        raise ValueError('invalid telemetry value')
    return {'timestamp': timestamp, 'spacecraft': fields[1], 'metric': fields[2], 'value': value}

def build_telemetry_report(lines: list[str], config: dict[str, str] | None=None) -> dict[str, object]:
    parsed = []
    for position, line in enumerate(lines):
        if line.strip():
            record = parse_telemetry_line(line)
            parsed.append((record['timestamp'], record['spacecraft'], record['metric'], position, record))
    parsed.sort(key=lambda item: item[:4])
    records = [item[4] for item in parsed]
    groups = {}
    for timestamp, craft, metric, position, record in parsed:
        groups.setdefault(craft, {}).setdefault(metric, []).append((timestamp, position, record['value']))
    crafts = {}
    for craft in sorted(groups):
        crafts[craft] = {}
        for metric in sorted(groups[craft]):
            values = groups[craft][metric]
            nums = [item[2] for item in values]
            latest = max(values, key=lambda item: (item[0], item[1]))[2]
            crafts[craft][metric] = {'count': len(nums), 'average': round(sum(nums) / len(nums), 6), 'minimum': round(min(nums), 6), 'maximum': round(max(nums), 6), 'latest': round(latest, 6)}
    if config is not None and 'TELEMETRY_SIGNING_KEY' in config:
        secret = config['TELEMETRY_SIGNING_KEY']
    else:
        secret = os.environ.get('TELEMETRY_SIGNING_KEY')
    if secret is None:
        raise ValueError('TELEMETRY_SIGNING_KEY is required')
    body = {'records': records, 'crafts': crafts}
    encoded = json.dumps(body, separators=(',', ':'), sort_keys=True).encode()
    signature = hmac.new(secret.encode(), encoded, hashlib.sha256).hexdigest()
    return {'records': records, 'crafts': crafts, 'signature': signature}

