import hashlib
import hmac
import json
import os

def hash_password(password: str) -> str:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return salt.hex() + ':' + digest.hex()

def verify_password(password: str, stored: str) -> bool:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    try:
        salt_hex, digest_hex = stored.split(':')
        salt = bytes.fromhex(salt_hex)
        expected = bytes.fromhex(digest_hex)
    except (AttributeError, ValueError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def aggregate_coverage(report_text: str, password: str, stored_password: str, min_coverage: float=0.0, page: int=1, page_size: int=10) -> list[dict]:
    if page < 1 or page_size < 1:
        raise ValueError('invalid pagination')
    try:
        threshold = float(min_coverage)
    except (TypeError, ValueError):
        raise ValueError('invalid threshold')
    if not verify_password(password, stored_password):
        raise PermissionError('invalid password')
    try:
        records = json.loads(report_text)
    except (TypeError, json.JSONDecodeError):
        raise ValueError('invalid JSON')
    if not isinstance(records, list):
        raise ValueError('report must be a list')
    grouped = {}
    for record in records:
        if not isinstance(record, dict) or not isinstance(record.get('file'), str):
            raise ValueError('invalid record')
        covered = record.get('covered')
        total = record.get('total')
        if isinstance(covered, bool) or not isinstance(covered, int) or covered < 0 or isinstance(total, bool) or (not isinstance(total, int)) or (total <= 0) or (covered > total):
            raise ValueError('invalid counts')
        if record['file'] not in grouped:
            grouped[record['file']] = [0, 0]
        grouped[record['file']][0] += covered
        grouped[record['file']][1] += total
    rows = []
    for name, (covered, total) in grouped.items():
