        if isinstance(rating, bool) or not isinstance(rating, (int, float)) or rating <= 0:
            raise ValueError('invalid rating')
        if isinstance(slope, bool) or not isinstance(slope, int) or (not 1 <= slope <= 255):
            raise ValueError('invalid slope')
        if isinstance(score, bool) or not isinstance(score, int) or (not 1 <= score <= 300):
            raise ValueError('invalid score')
