    for value in (max_weight, offset, limit):
        if not isinstance(value, int):
            raise TypeError('numeric arguments must be integers')
    if max_weight < 0 or offset < 0 or limit < 0:
        raise ValueError('numeric arguments must not be negative')
    eligible = []
    for item in containers:
