            raise ValueError('container must be a dictionary')
        for field in ('id', 'status', 'weight', 'priority', 'arrival_order'):
            if field not in item:
                raise ValueError('missing container field')
        if not isinstance(item['id'], str) or not isinstance(item['status'], str):
            raise ValueError('invalid container field')
        for field in ('weight', 'priority', 'arrival_order'):
            if not isinstance(item[field], int):
                raise TypeError('numeric container fields must be integers')
        if item['weight'] < 0:
            raise ValueError('weight must not be negative')
        if item['status'] == 'queued':
            eligible.append(item)
    eligible.sort(key=lambda item: (-item['priority'], item['arrival_order'], item['id']))
    selected = []
