import datetime
import hashlib
import hmac
import json

def _time(value):
    try:
        result = datetime.datetime.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid datetime')
    if result.tzinfo is not None:
        result = result.astimezone(datetime.timezone.utc).replace(tzinfo=None)
    return result

def schedule_shifts(employees: list[dict], shifts: list[dict]) -> list[dict]:
    ids = [e.get('id') for e in employees]
    if any((not isinstance(x, str) for x in ids)) or len(set(ids)) != len(ids):
        raise ValueError('duplicate employee id')
    seen = set()
    parsed = []
    for s in shifts:
        if s.get('id') in seen:
            raise ValueError('duplicate shift id')
        seen.add(s.get('id'))
        start, end = (_time(s.get('start')), _time(s.get('end')))
        if end <= start:
            raise ValueError('invalid shift interval')
        parsed.append((start, end, s))
    parsed.sort(key=lambda x: (x[0], x[1], x[2]['id']))
    state = {e['id']: {'hours': 0.0, 'count': 0, 'ranges': [], 'employee': e} for e in employees}
    result = []
    for start, end, shift in parsed:
        duration = (end - start).total_seconds() / 3600
        choices = []
        required = set(shift.get('skills', []))
        for ident, data in state.items():
            e = data['employee']
            if not required.issubset(set(e.get('skills', []))):
                continue
            if data['hours'] + duration > e.get('max_hours', -1):
                continue
            available = False
            for pair in e.get('availability', []):
                a, b = (_time(pair[0]), _time(pair[1]))
                if b > a and a <= start and (end <= b):
                    available = True
                    break
            if not available or any((start < b and a < end for a, b in data['ranges'])):
                continue
            choices.append((data['hours'], data['count'], ident, data))
        if not choices:
            raise ValueError('shift cannot be assigned')
        _, _, ident, data = min(choices, key=lambda x: (x[0], x[1], x[2]))
        data['hours'] += duration
        data['count'] += 1
        data['ranges'].append((start, end))
        result.append({'shift_id': shift['id'], 'employee_id': ident, 'start': shift['start'], 'end': shift['end'], 'duration_hours': float(duration)})
    return result

def sign_schedule(schedule: list[dict], config: dict) -> str:
    if 'signing_key' not in config:
        raise ValueError('missing signing key')
    key = config['signing_key']
    if not isinstance(key, str):
        raise ValueError('signing key must be a string')
    payload = json.dumps(schedule, sort_keys=True, separators=(',', ':'), allow_nan=False)
    digest = hmac.new(key.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()
    return payload + '.' + digest

