from datetime import date, timedelta, datetime, timezone

def verify_envelope(text: str, keys: dict[str, bytes], now: int) -> dict:
    try:
        obj = json.loads(text)
    except Exception as exc:
        raise ValueError('invalid envelope') from exc
    if not isinstance(obj, dict) or set(obj) != {'key_id', 'issued', 'signature', 'records'}:
        raise ValueError('invalid envelope')
    kid, issued, sig, records = (obj['key_id'], obj['issued'], obj['signature'], obj['records'])
    if not isinstance(kid, str) or not isinstance(issued, int) or isinstance(issued, bool) or (issued > now) or (not isinstance(sig, str)) or (not isinstance(records, list)):
        raise ValueError('invalid envelope')
    if kid not in keys:
        raise ValueError('unknown key')
    checked = []
    for rec in records:
        if not isinstance(rec, dict) or set(rec) != {'id', 'category', 'created', 'retention_days', 'hold'}:
            raise ValueError('invalid record')
        if not isinstance(rec['id'], str) or not rec['id'] or (not isinstance(rec['category'], str)) or (not rec['category']):
            raise ValueError('invalid record')
        if not isinstance(rec['retention_days'], int) or isinstance(rec['retention_days'], bool) or rec['retention_days'] < 0 or (not isinstance(rec['hold'], bool)):
            raise ValueError('invalid record')
        try:
            date.fromisoformat(rec['created'])
        except Exception as exc:
            raise ValueError('invalid date') from exc
        checked.append(dict(rec))
    try:
        supplied = bytes.fromhex(sig)
    except ValueError as exc:
        raise ValueError('invalid signature') from exc
    payload = {'key_id': kid, 'issued': issued, 'records': checked}
    raw = json.dumps(payload, sort_keys=True, separators=(',', ':')).encode()
    expected = hmac.new(keys[kid], raw, hashlib.sha256).digest()
    if len(supplied) != len(expected) or not hmac.compare_digest(expected, supplied):
        raise ValueError('invalid signature')
    payload['signature'] = sig
    return payload

def retention_plan(text: str, keys: dict[str, bytes], now: int) -> list[dict]:
    obj = verify_envelope(text, keys, now)
    today = datetime.fromtimestamp(now, timezone.utc).date()
    result = []
    for rec in obj['records']:
        expires = date.fromisoformat(rec['created']) + timedelta(days=rec['retention_days'])
        action = 'hold' if rec['hold'] else 'delete' if expires <= today else 'retain'
        result.append({'id': rec['id'], 'category': rec['category'], 'expires': expires.isoformat(), 'action': action})
    result.sort(key=lambda x: (x['category'], x['expires'], x['id']))
    return result

