            cur.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            out.append(''.join(cur))
            cur = []
        else:
            cur.append(char)
    if escaped:
        raise ValueError('malformed frame')
    out.append(''.join(cur))
    return out

def verify_alarm(frame, secrets, now, max_age=300):
    if not isinstance(frame, str) or not isinstance(secrets, dict):
        raise TypeError('invalid arguments')
    if max_age < 0:
        raise ValueError('invalid age')
    parts = _split(frame)
    if len(parts) != 6:
        raise ValueError('malformed frame')
    plant, stamp, severity, code_text, message, signature = parts
    if not plant or not message or plant not in secrets:
        raise ValueError('invalid fields')
    if not re.fullmatch('[0-9]+', stamp):
        raise ValueError('invalid timestamp')
    timestamp = int(stamp)
    if abs(now - timestamp) > max_age:
        raise ValueError('stale')
    if severity not in {'LOW', 'MEDIUM', 'HIGH', 'CRITICAL'}:
        raise ValueError('invalid severity')
    codes = code_text.split(',')
    if not code_text or any((not re.fullmatch('[A-Z0-9_]+', x) for x in codes)):
        raise ValueError('invalid codes')
    if not re.fullmatch('[0-9a-fA-F]{64}', signature):
        raise ValueError('invalid signature')
    key = secrets[plant]
    if isinstance(key, str):
        key = key.encode()
    payload = '|'.join(parts[:5]).encode()
    expected = hmac.new(key, payload, hashlib.sha256).hexdigest()
    if expected != signature.lower():
        raise ValueError('invalid signature')
    return {'plant': plant, 'timestamp': timestamp, 'severity': severity, 'codes': codes, 'message': message}

def process_alarms(frames, secrets, now, window=3600, max_age=300):
    if window < 0:
        raise ValueError('invalid window')
    groups = {}
    for text in frames:
        try:
            alarm = verify_alarm(text, secrets, now, max_age)
        except (ValueError, TypeError):
            continue
        if not now - window <= alarm['timestamp'] <= now:
            group = groups.setdefault(alarm['plant'], {'items': [], 'codes': set()})
            group['items'].append(alarm)
            group['codes'].update(alarm['codes'])
    result = []
    for plant, group in groups.items():
        items = group['items']
        result.append({'plant': plant, 'total': len(items), 'critical': sum((x['severity'] == 'CRITICAL' for x in items)), 'latest': max((x['timestamp'] for x in items)), 'codes': sorted(group['codes'])})
    return sorted(result, key=lambda x: (-x['critical'], -x['total'], x['plant']))

