import secrets

def create_invite_code(length: int=10) -> str:
    if isinstance(length, bool) or not isinstance(length, int) or (not 4 <= length <= 64):
        raise ValueError('length must be an integer from 4 through 64')
    alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
    return 'MUSE-' + ''.join((secrets.choice(alphabet) for _ in range(length)))

def summarize_memberships(records: list[dict], page: int=1, per_page: int=10) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('page must be positive')
    if isinstance(per_page, bool) or not isinstance(per_page, int) or per_page < 1:
        raise ValueError('per_page must be positive')
    tiers = {'standard': [], 'family': [], 'patron': []}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('record must be a dictionary')
        member_id = record.get('member_id')
        tier = record.get('tier')
        visits = record.get('visits')
        if not isinstance(member_id, str) or not member_id:
            raise ValueError('invalid member_id')
        if tier not in tiers:
            raise ValueError('invalid tier')
        if isinstance(visits, bool) or not isinstance(visits, int) or visits < 0:
            raise ValueError('invalid visits')
        tiers[tier].append(visits)
    items = []
    for tier, visits in tiers.items():
        if visits:
            items.append({'tier': tier, 'count': len(visits), 'average_visits': round(sum(visits) / len(visits), 2)})
    order = {'standard': 0, 'family': 1, 'patron': 2}
    items.sort(key=lambda item: (-item['count'], order[item['tier']]))
    start = (page - 1) * per_page
    pages = (len(items) + per_page - 1) // per_page
    return {'total': sum((len(values) for values in tiers.values())), 'pages': pages, 'items': items[start:start + per_page]}

