import json

def _split_fields(line):
    fields = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current).strip())
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape')
    fields.append(''.join(current).strip())
    return fields

def parse_bom(text: str) -> list[dict]:
    result = []
    for raw in text.splitlines():
        if not raw.strip() or raw.lstrip().startswith('#'):
            continue
        fields = _split_fields(raw)
        if len(fields) != 3 or not fields[0] or (not fields[1]):
            raise ValueError('invalid BOM line')
        parts = fields[1].split('.')
        if any((not p.isdigit() for p in parts)):
            raise ValueError('invalid version')
        licenses = [x.strip() for x in fields[2].split(',')]
        if any((not x for x in licenses)):
            raise ValueError('invalid license')
        result.append({'name': fields[0], 'version': fields[1], 'licenses': sorted(set(licenses))})
    return result

def aggregate_components(records: list[dict]) -> list[dict]:
    grouped = {}
    for record in records:
        item = grouped.setdefault(record['name'], {'versions': set(), 'licenses': set()})
        item['versions'].add(record['version'])
        item['licenses'].update(record['licenses'])

    def version_key(value):
        return tuple((int(x) for x in value.split('.')))
    return [{'name': name, 'versions': sorted(data['versions'], key=version_key), 'licenses': sorted(data['licenses'])} for name, data in sorted(grouped.items())]

