    key = config.get('signing_key')
    if not isinstance(key, str) or not key:
        raise ValueError('missing signing key')
    manifest = json.dumps(aggregate_components(parse_bom(text)), sort_keys=True, separators=(',', ':'))
    signature = hmac.new(key.encode(), manifest.encode(), hashlib.sha256).hexdigest()
    return {'manifest': manifest, 'signature': signature}

