        raise ValueError('unexpected text')
    result = []
    for node in root:
        if not isinstance(node.tag, str) or node.tag != 'case':
            raise ValueError('unexpected element')
        if node.tail and node.tail.strip():
            raise ValueError('unexpected text')
        values = {}
        for key in ('number', 'title', 'status'):
            value = node.get(key)
            if value is None or not value.strip():
                raise ValueError('missing attribute')
            values[key] = value.strip()
        events = []
        for index, child in enumerate(node):
            if child.tag != 'event' or (child.tail and child.tail.strip()):
                raise ValueError('unexpected element')
            if child.text and child.text.strip():
                raise ValueError('unexpected text')
            raw_date = child.get('date')
