        raise ValueError('invalid manifest')
    result = []
    seen = set()
    for item in obj['backups']:
        if not isinstance(item, dict) or not isinstance(item.get('id'), str) or (not item['id']):
            raise ValueError('invalid backup')
        if item['id'] in seen or not isinstance(item.get('timestamp'), str):
            raise ValueError('invalid backup')
        if not isinstance(item.get('size'), int) or isinstance(item['size'], bool) or item['size'] < 0:
            raise ValueError('invalid backup')
        if item.get('kind') not in ('full', 'incremental'):
            raise ValueError('invalid backup')
        _time(item['timestamp'])
        seen.add(item['id'])
        result.append(item)
    return result

