    records = verify_manifest(text, tag, key)
    current = _time(now)
    chosen = {}
    for item in records:
        stamp = _time(item['timestamp'])
        age = (current - stamp).total_seconds()
        if age < 7 * 86400:
            bucket = ('day', stamp.date())
        elif age < 30 * 86400:
            iso = stamp.isocalendar()
            bucket = ('week', iso.year, iso.week)
        else:
