def verify_customer_batch(records: list[dict], page: int=1, page_size: int=20) -> dict:
    key = os.environ.get('IDENTITY_VERIFICATION_KEY')
    if key is None:
        raise RuntimeError('IDENTITY_VERIFICATION_KEY is required')
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('page must be at least 1')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('page_size must be between 1 and 100')
    verified = []
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('each record must be a dictionary')
        required = ('customer_id', 'full_name', 'country', 'risk_score', 'proof')
        if any((field not in record for field in required)):
            raise ValueError('record is missing a required field')
        for field in ('customer_id', 'full_name', 'country', 'proof'):
            if not isinstance(record[field], str) or not record[field]:
                raise ValueError('record contains an invalid string field')
        if not isinstance(record['risk_score'], int) or isinstance(record['risk_score'], bool) or (not 0 <= record['risk_score'] <= 100):
            raise ValueError('risk_score must be an integer from 0 through 100')
        message = f"{record['customer_id']}|{record['full_name']}|{record['country']}|{record['risk_score']}".encode()
        expected = hmac.new(key.encode(), message, hashlib.sha256).hexdigest()
        if hmac.compare_digest(record['proof'], expected):
            verified.append(record)
    verified.sort(key=lambda item: (-item['risk_score'], item['customer_id']))
    total = len(verified)
    start = (page - 1) * page_size
    counts = {}
    for record in verified:
        counts[record['country']] = counts.get(record['country'], 0) + 1
    counts = dict(sorted(counts.items()))
    return {'total': total, 'page': page, 'page_size': page_size, 'pages': math.ceil(total / page_size) if total else 0, 'customers': verified[start:start + page_size], 'country_counts': counts, 'average_risk': round(sum((item['risk_score'] for item in verified)) / total, 2) if total else None}

