import hashlib
import hmac
import json
from datetime import datetime

def parse_signature(signature: str) -> bytes:
    if not isinstance(signature, str) or len(signature) != 71 or (not signature.startswith('sha256=')):
        raise ValueError('invalid signature')
    text = signature[7:]
    if any((c not in '0123456789abcdef' for c in text)):
        raise ValueError('invalid signature')
    try:
        return bytes.fromhex(text)
    except ValueError as exc:
        raise ValueError('invalid signature') from exc

def summarize_webhook(payload: str, signature: str, secret: str) -> dict:
    if not isinstance(secret, str) or not secret:
        raise ValueError('invalid secret')
    supplied = parse_signature(signature)
    raw = payload.encode('utf-8') if isinstance(payload, str) else b''
    expected = hmac.new(secret.encode('utf-8'), raw, hashlib.sha256).digest()
    if not hmac.compare_digest(supplied, expected):
        raise ValueError('invalid signature')
    try:
        document = json.loads(payload)
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(document, dict) or not isinstance(document.get('events'), list):
        raise ValueError('invalid payload')
    campaigns = {}
    seen = set()
    required = {'id', 'campaign', 'donor', 'amount_cents', 'kind', 'timestamp'}
    for event in document['events']:
        if not isinstance(event, dict) or set(event) != required:
            raise ValueError('invalid event')
        ident = event['id']
        if not isinstance(ident, str) or not ident or ident in seen:
            raise ValueError('invalid event')
        seen.add(ident)
        campaign = event['campaign']
        donor = event['donor']
        amount = event['amount_cents']
        kind = event['kind']
        stamp = event['timestamp']
        if not isinstance(campaign, str) or not campaign or (not isinstance(donor, str)) or (not donor):
            raise ValueError('invalid event')
        if isinstance(amount, bool) or not isinstance(amount, int) or amount <= 0 or (kind not in ('donation', 'refund')):
            raise ValueError('invalid event')
        if not isinstance(stamp, str) or not stamp.endswith('Z'):
            raise ValueError('invalid event')
        try:
            day = datetime.fromisoformat(stamp[:-1]).date().isoformat()
        except (TypeError, ValueError) as exc:
            raise ValueError('invalid event') from exc
        sign = 1 if kind == 'donation' else -1
        value = sign * amount
        item = campaigns.setdefault(campaign, {'net_cents': 0, 'events': 0, 'donor_totals': {}, 'daily': {}})
        item['net_cents'] += value
        item['events'] += 1
        item['donor_totals'][donor] = item['donor_totals'].get(donor, 0) + value
        item['daily'][day] = item['daily'].get(day, 0) + value
    output = {'campaigns': {}}
    for campaign in sorted(campaigns):
        item = campaigns[campaign]
        top = min(item['donor_totals'], key=lambda name: (-item['donor_totals'][name], name))
        output['campaigns'][campaign] = {'net_cents': item['net_cents'], 'events': item['events'], 'donors': len(item['donor_totals']), 'daily': {day: item['daily'][day] for day in sorted(item['daily'])}, 'top_donor': top}
    return output

