def _allowed(requester, participant):
    return requester.get('id') == participant.get('owner_id') or ('clinician' in requester.get('roles', []) and participant.get('trial_id') in requester.get('trial_ids', []))

def _check_visit(v, enrollment, seen):
    if set(v) != {'id', 'date', 'status'}:
        raise ValueError('invalid visit')
    try:
        d = date.fromisoformat(v['date'])
        e = date.fromisoformat(enrollment)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if v['status'] not in {'completed', 'missed', 'scheduled'} or d < e or v['id'] in seen:
        raise ValueError('invalid visit')
    return d

def _validated(participant, visits):
    seen = set()
    rows = []
    for v in visits:
        d = _check_visit(v, participant['enrollment_date'], seen)
        seen.add(v['id'])
        rows.append((d, v['status'], v['id']))
    return rows

def build_participant_report(requester: dict, participant: dict, visits: list[dict]) -> dict:
    if not _allowed(requester, participant):
        raise PermissionError('not permitted')
    try:
        date.fromisoformat(participant['enrollment_date'])
    except (KeyError, TypeError, ValueError):
        raise ValueError('invalid enrollment date')
    rows = _validated(participant, visits)
    counts = {'completed': 0, 'missed': 0, 'scheduled': 0}
    months = {}
    for d, status, _ in rows:
        counts[status] += 1
        m = d.strftime('%Y-%m')
        if m not in months:
            months[m] = {'month': m, 'completed': 0, 'missed': 0, 'scheduled': 0}
        months[m][status] += 1
    denominator = counts['completed'] + counts['missed']
