    return {'participant_id': participant['id'], 'trial_id': participant['trial_id'], 'enrollment_date': participant['enrollment_date'], 'total_visits': len(rows), 'completed_visits': counts['completed'], 'missed_visits': counts['missed'], 'scheduled_visits': counts['scheduled'], 'completion_rate': round(counts['completed'] / denominator, 2) if denominator else 0.0, 'last_completed_date': max(completed).isoformat() if completed else None, 'by_month': [months[k] for k in sorted(months)]}

def record_visit(requester: dict, participant: dict, visits: list[dict], new_visit: dict) -> list[dict]:
    if not _allowed(requester, participant):
        raise PermissionError('not permitted')
    _validated(participant, visits)
    _check_visit(new_visit, participant['enrollment_date'], {v['id'] for v in visits})
    return list(visits) + [dict(new_visit)]

