import hashlib
import hmac
import os

def make_credential_record(secret: str) -> str:
    if not isinstance(secret, str):
        raise TypeError('secret must be a string')
    if not secret:
        raise ValueError('secret must not be empty')
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
    return 'pbkdf2$100000$' + salt.hex() + '$' + value.hex()

def verify_credential(secret: str, record: str) -> bool:
    if not isinstance(secret, str):
        raise TypeError('secret must be a string')
    if not isinstance(record, str) or not record:
        return False
    try:
        kind, count, salt_text, value_text = record.split('$')
        if kind != 'pbkdf2' or int(count) != 100000:
            return False
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(value_text)
        actual = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def summarize_incidents(records: list[dict], page: int, page_size: int) -> dict:
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    if isinstance(page, bool) or not isinstance(page, int):
        raise TypeError('page must be an integer')
    if isinstance(page_size, bool) or not isinstance(page_size, int):
        raise TypeError('page_size must be an integer')
    if page <= 0 or page_size <= 0:
        raise ValueError('pagination values must be positive')
    statuses = {'investigating': 0, 'monitoring': 0, 'resolved': 0}
    ordered = []
    total_duration = 0
    for item in records:
        if not isinstance(item, dict):
            raise ValueError('invalid incident')
        if not isinstance(item.get('id'), str) or item.get('status') not in statuses:
            raise ValueError('invalid incident')
        duration = item.get('duration_minutes')
        impact = item.get('impact')
        if isinstance(duration, bool) or not isinstance(duration, int) or duration < 0:
            raise ValueError('invalid incident')
        if isinstance(impact, bool) or not isinstance(impact, int) or (not 1 <= impact <= 5):
            raise ValueError('invalid incident')
        statuses[item['status']] += 1
        total_duration += duration
        ordered.append((impact, duration, item['id']))
    ordered.sort(key=lambda x: (-x[0], -x[1], x[2]))
    start = (page - 1) * page_size
    end = start + page_size
    average = round(total_duration / len(records), 2) if records else 0.0
    return {'total': len(records), 'by_status': statuses, 'average_duration_minutes': average, 'incidents': [x[2] for x in ordered[start:end]]}

