import hashlib
import hmac
import os

def make_credential(password: str) -> str:
    if not isinstance(password, str):
        raise TypeError()
    if not password:
        raise ValueError()
    salt = os.urandom(16)
    iterations = 100000
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, iterations)
    return '1$%d$%s$%s' % (iterations, base64.b64encode(salt).decode(), digest.hex())

def verify_credential(credential: str, password: str) -> bool:
    try:
        if not isinstance(credential, str) or not isinstance(password, str):
            return False
        version, count, encoded, expected = credential.split('$')
        if version != '1':
            return False
        iterations = int(count)
        salt = base64.b64decode(encoded.encode(), validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, iterations).hex()
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError, UnicodeError):
        return False

def _fields(line):
    fields = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current).strip())
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError()
    fields.append(''.join(current).strip())
    return fields

def parse_inspection(text: str) -> list[dict]:
    if not isinstance(text, str):
        raise TypeError()
    result = []
    for line in text.splitlines():
        if not line.strip():
            continue
        fields = _fields(line)
        if len(fields) != 4 or not all(fields) or fields[1] not in {'low', 'medium', 'high', 'critical'}:
            raise ValueError()
        result.append(dict(zip(('room', 'severity', 'code', 'description'), fields)))
    return result

def authorized_summary(text: str, credential: str, password: str) -> dict:
    if not verify_credential(credential, password):
        raise PermissionError()
    rows = parse_inspection(text)
    weights = {'low': 1, 'medium': 3, 'high': 7, 'critical': 12}
    order = ('low', 'medium', 'high', 'critical')
    rooms = {}
    codes = {}
    score = 0
    for row in rows:
        room = rooms.setdefault(row['room'], {'room': row['room'], 'findings': 0, 'severity_counts': {x: 0 for x in order}})
        room['findings'] += 1
        room['severity_counts'][row['severity']] += 1
        codes[row['code']] = codes.get(row['code'], 0) + 1
        score += weights[row['severity']]
    highest = max(codes.values(), default=0)
    top = [{'code': code, 'count': count} for code, count in sorted(codes.items()) if count == highest]
    return {'total_findings': len(rows), 'risk_score': score, 'rooms': [rooms[x] for x in sorted(rooms)], 'top_codes': top}

