import base64
import datetime
import hashlib
import hmac
import os

def hash_api_secret(secret: str) -> str:
    if not isinstance(secret, str) or not secret:
        raise ValueError('secret must be non-empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
    return base64.b64encode(salt).decode() + ':' + base64.b64encode(digest).decode()

def verify_api_secret(secret: str, stored: str) -> bool:
    if not isinstance(secret, str) or not isinstance(stored, str):
        return False
    try:
        salt_text, digest_text = stored.split(':')
        salt = base64.b64decode(salt_text, validate=True)
        expected = base64.b64decode(digest_text, validate=True)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def certificate_renewal_page(records: list[dict], as_of: str, window_days: int, page: int, page_size: int) -> dict:
    if window_days < 0 or page < 1 or page_size < 1 or (page_size > 100):
        raise ValueError('invalid pagination')
    try:
        start = datetime.date.fromisoformat(as_of)
    except ValueError as exc:
        raise ValueError('invalid date') from exc
    end = start + datetime.timedelta(days=window_days)
    counts = {}
    matching = []
    for record in records:
        status = record['status']
        expires_text = record['expires']
        expires = datetime.date.fromisoformat(expires_text)
        counts[status] = counts.get(status, 0) + 1
        if start <= expires <= end:
            matching.append((expires, record['id'], record, (expires - start).days))
    matching.sort(key=lambda item: (item[0], item[1]))
    first = (page - 1) * page_size
    items = []
    for _, _, record, days_left in matching[first:first + page_size]:
        items.append({'id': record['id'], 'subject': record['subject'], 'status': record['status'], 'expires': record['expires'], 'days_left': days_left})
    return {'total': len(records), 'matching': len(matching), 'by_status': {key: counts[key] for key in sorted(counts)}, 'items': items}

