import hashlib
import hmac
import json

def verify_webhook(payload: str, signature: str, key: bytes) -> dict:
    if not isinstance(key, bytes) or not key:
        raise ValueError('invalid key')
    if not isinstance(payload, str) or not isinstance(signature, str):
        raise PermissionError('invalid signature')
    if len(signature) != 71 or not signature.startswith('sha256='):
        raise PermissionError('invalid signature')
    text = signature[7:]
    try:
        supplied = bytes.fromhex(text)
    except ValueError:
        raise PermissionError('invalid signature')
    if len(supplied) != 32:
        raise PermissionError('invalid signature')
    expected = hmac.new(key, payload.encode('utf-8'), hashlib.sha256).digest()
    if not hmac.compare_digest(expected, supplied):
        raise PermissionError('invalid signature')
    try:
        value = json.loads(payload)
    except (UnicodeEncodeError, json.JSONDecodeError):
        raise ValueError('invalid json')
    return summarize_donations(value)

def summarize_donations(events: object) -> dict:
    if not isinstance(events, dict) or not isinstance(events.get('events'), list):
        raise ValueError('events must be a list')
    seen = set()
    totals = {}
    for item in events['events']:
        if not isinstance(item, dict):
            raise ValueError('invalid event')
        required = ('id', 'campaign', 'cents', 'status', 'timestamp')
        if any((name not in item for name in required)):
            raise ValueError('invalid event')
        identifier = item['id']
        campaign = item['campaign']
        cents = item['cents']
        status = item['status']
        timestamp = item['timestamp']
        if not isinstance(identifier, str) or not identifier or (not isinstance(campaign, str)) or (not campaign) or (not isinstance(cents, int)) or isinstance(cents, bool) or (cents <= 0) or (status not in ('completed', 'refunded')) or (not isinstance(timestamp, int)) or isinstance(timestamp, bool) or (timestamp < 0):
            raise ValueError('invalid event')
        if identifier in seen:
            continue
        seen.add(identifier)
        if status != 'completed':
            continue
        record = totals.setdefault(campaign, [0, 0, 0])
        record[0] += cents
        record[1] += 1
        record[2] = max(record[2], timestamp)
    campaigns = [{'campaign': name, 'total_cents': data[0], 'count': data[1], 'latest_timestamp': data[2]} for name, data in totals.items()]
    campaigns.sort(key=lambda row: (-row['total_cents'], row['campaign']))
    return {'total_cents': sum((row['total_cents'] for row in campaigns)), 'campaigns': campaigns}

