            raise ValueError('invalid id')
        if not isinstance(disposition, str) or not disposition.strip():
            raise ValueError('invalid disposition')
        if isinstance(acuity, bool) or not isinstance(acuity, int) or (not 1 <= acuity <= 5):
            raise ValueError('invalid acuity')
        if isinstance(wait, bool) or not isinstance(wait, int) or wait < 0:
            raise ValueError('invalid wait')
        ident = ident.strip()
        disposition = disposition.strip()
        if ident in seen:
            raise ValueError('duplicate id')
        seen.add(ident)
        band = 'under_30' if wait < 30 else '30_59' if wait < 60 else '60_plus'
        normalized.append({'id': ident, 'acuity': acuity, 'wait_minutes': wait, 'disposition': disposition, 'wait_band': band})
    normalized.sort(key=lambda row: (row['acuity'], row['id']))
    fields = ['id', 'acuity', 'wait_minutes', 'disposition', 'wait_band']
    directory = os.path.dirname(os.path.abspath(output_path))
    temporary = tempfile.mktemp(dir=directory, prefix='triage-', suffix='.csv')
    try:
        with open(temporary, 'w', newline='', encoding='utf-8') as stream:
            writer = csv.DictWriter(stream, fieldnames=fields, lineterminator='\n')
            writer.writeheader()
            writer.writerows(normalized)
        os.replace(temporary, output_path)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    start = (page - 1) * page_size
    selected = normalized[start:start + page_size]
    return {'total': len(normalized), 'page': page, 'page_size': page_size, 'page_count': (len(normalized) + page_size - 1) // page_size, 'rows': selected}

