    lines = [x.strip() for x in text.splitlines() if x.strip()]
    if not lines or not lines[0].startswith('FLIGHT|'):
        raise ValueError()
    head = lines[0].split('|')
    if len(head) != 3 or not head[1] or '|' in head[1]:
        raise ValueError()
    try:
        date.fromisoformat(head[2])
    except Exception:
        raise ValueError()
    passengers = []
    seats = set()
    for raw in lines[1:]:
        parts = raw.split('|', 2)
        if len(parts) != 3 or parts[0] != 'PASSENGER':
            raise ValueError()
        _, tag, payload = parts
        try:
            supplied = bytes.fromhex(tag)
        except ValueError:
            raise ValueError()
        expected = hmac.new(secret, payload.encode('utf-8'), hashlib.sha256).digest()
        if not hmac.compare_digest(supplied, expected):
            raise ValueError()
        try:
            obj = json.loads(payload)
        except Exception:
            raise ValueError()
        if not isinstance(obj, dict) or set(obj) != {'name', 'seat', 'cabin', 'status'}:
            raise ValueError()
        name, seat, cabin, status = obj.values()
        if not isinstance(name, str) or not name.strip():
            raise ValueError()
        if isinstance(seat, bool) or not isinstance(seat, int) or seat <= 0 or (seat in seats):
            raise ValueError()
        if cabin not in {'economy', 'business'} or status not in {'checked-in', 'boarded', 'no-show'}:
            raise ValueError()
        seats.add(seat)
        passengers.append({'name': name.strip(), 'seat': seat, 'cabin': cabin, 'status': status})
    passengers.sort(key=lambda x: (x['seat'], x['name']))
    return {'flight': head[1], 'date': head[2], 'passengers': passengers}

def manifest_totals(manifest: dict) -> dict:
    if not isinstance(manifest, dict) or not isinstance(manifest.get('passengers'), list):
        raise ValueError()
    cabins = {'economy': 0, 'business': 0}
    statuses = {'checked-in': 0, 'boarded': 0, 'no-show': 0}
    seats = set()
    boarded = []
    for p in manifest['passengers']:
        if not isinstance(p, dict) or set(p) != {'name', 'seat', 'cabin', 'status'}:
            raise ValueError()
        if isinstance(p['seat'], bool) or not isinstance(p['seat'], int) or p['seat'] <= 0 or (p['seat'] in seats):
            raise ValueError()
        if p['cabin'] not in cabins or p['status'] not in statuses:
            raise ValueError()
        seats.add(p['seat'])
        cabins[p['cabin']] += 1
        statuses[p['status']] += 1
        if p['status'] == 'boarded':
            boarded.append(p['seat'])
    return {'total': len(manifest['passengers']), 'by_cabin': cabins, 'by_status': statuses, 'boarded_seats': sorted(boarded)}

