import hashlib
import os

def hash_pin(pin: str) -> str:
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return salt.hex() + ':' + digest.hex()

def verify_pin(stored: str, pin: str) -> bool:
    try:
        salt_text, digest_text = stored.split(':', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return actual == expected

def create_meal_account(student_id: str, plan: str, pin: str, balance: int) -> dict:
    if not isinstance(student_id, str) or not student_id:
        raise ValueError('invalid student id')
    if plan not in {'standard', 'premium'}:
        raise ValueError('invalid plan')
    if not isinstance(pin, str) or len(pin) != 4 or (not pin.isdecimal()):
        raise ValueError('invalid pin')
    if not isinstance(balance, int) or isinstance(balance, bool) or balance < 0:
        raise ValueError('invalid balance')
    return {'student_id': student_id, 'plan': plan, 'balance': balance, 'pin_hash': hash_pin(pin)}

def charge_meal(account: dict, pin: str, cost: int) -> dict:
    if not verify_pin(account.get('pin_hash', ''), pin):
        raise ValueError('invalid pin')
    if not isinstance(cost, int) or isinstance(cost, bool) or cost <= 0:
        raise ValueError('invalid cost')
    if account.get('balance', -1) < cost:
        raise ValueError('insufficient balance')
    result = dict(account)
    result['balance'] -= cost
    return result

