    if min_weight is not None and (not math.isfinite(min_weight) or min_weight < 0):
        raise ValueError('invalid minimum weight')
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml_text.encode('utf-8'), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'livestock':
        raise ValueError('invalid root')
    groups = {}
    for animal in root.findall('animal'):
        name = animal.get('species')
        raw_weight = animal.get('weight')
        if name is None or raw_weight is None:
            raise ValueError('missing animal data')
        try:
            weight = float(raw_weight)
        except (TypeError, ValueError) as exc:
            raise ValueError('invalid weight') from exc
        if not math.isfinite(weight):
            raise ValueError('invalid weight')
        if animal.get('status') == 'inactive' or (species is not None and name != species) or (min_weight is not None and weight < min_weight):
            continue
        groups.setdefault(name, []).append(weight)
    result = []
    for name, weights in groups.items():
        total = sum(weights)
        result.append({'species': name, 'count': len(weights), 'total_weight_kg': round(total, 2), 'average_weight_kg': round(total / len(weights), 2)})
    result.sort(key=lambda item: (-item['count'], item['species']))
    return result

