import ast
import operator

def summarize_absences(records: list[dict], expression: str, variables: dict[str, int | float]) -> dict[str, int]:
    try:
        tree = ast.parse(expression, mode='eval').body
    except SyntaxError as exc:
        raise ValueError('invalid expression') from exc

    def calc(node, env):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id in env:
                return env[node.id]
            raise NameError(node.id)
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
            value = calc(node.operand, env)
            return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
        if isinstance(node, ast.BinOp) and type(node.op) in {ast.Add, ast.Sub, ast.Mult, ast.Div}:
            a, b = (calc(node.left, env), calc(node.right, env))
            return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](a, b)
        if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
            value = calc(node.values[0], env)
            for item in node.values[1:]:
                if isinstance(node.op, ast.And) and (not value) or (isinstance(node.op, ast.Or) and value):
                    return value
                value = calc(item, env)
            return value
        if isinstance(node, ast.Compare):
            left = calc(node.left, env)
            for op, right_node in zip(node.ops, node.comparators):
                right = calc(right_node, env)
                if not {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max', 'round'}) and (not node.keywords):
            return {'min': min, 'max': max, 'round': round}[node.func.id](*(calc(x, env) for x in node.args))
        raise ValueError('unsupported expression')
    result = {}
    for record in records:
        env = dict(variables)
        env.update(record)
        if calc(tree, env):
            result[record['team']] = result.get(record['team'], 0) + record['days']
    return result

