import sqlite3

def billing_summary(conn: sqlite3.Connection, matter_id: int | None, search: str, sort_by: str, descending: bool, page: int, page_size: int) -> list[dict]:
    allowed = {'attorney', 'entry_count', 'total_hours', 'total_amount'}
    if sort_by not in allowed:
        raise ValueError('invalid sort field')
    if page < 1 or page_size < 1:
        raise ValueError('invalid pagination')
    clauses = []
    if matter_id is not None:
        clauses.append(f'matter_id = {matter_id}')
    if search:
        value = '%' + search + '%'
        clauses.append(f"(lower(attorney) LIKE lower('{value}') OR lower(description) LIKE lower('{value}'))")
    where = ' WHERE ' + ' AND '.join(clauses) if clauses else ''
    rows = conn.execute('SELECT attorney, hours, rate FROM time_entries' + where).fetchall()
    grouped = {}
    for attorney, hours, rate in rows:
        item = grouped.setdefault(attorney, {'attorney': attorney, 'entry_count': 0, 'total_hours': 0.0, 'total_amount': 0.0})
        item['entry_count'] += 1
        item['total_hours'] += hours
        item['total_amount'] += hours * rate
    result = []
    for item in grouped.values():
        item['total_hours'] = round(item['total_hours'], 2)
        item['total_amount'] = round(item['total_amount'], 2)
        result.append(item)
    result.sort(key=lambda x: (x[sort_by], x['attorney'].lower()), reverse=descending)
    start = (page - 1) * page_size
    return result[start:start + page_size]

