    except Exception as exc:
        raise ValueError('invalid minutes') from exc
    if minutes < 0:
        raise ValueError('invalid minutes')
    return {'timestamp': timestamp, 'ride': ride, 'minutes': minutes, 'status': status, 'note': raw[4]}

