            raise ValueError('invalid event')
        group = groups.setdefault(ride, {'ride': ride, 'total_minutes': 0, 'event_count': 0, 'status_counts': {'planned': 0, 'completed': 0, 'overdue': 0}, 'latest': timestamp, 'daily_totals': {}})
        group['total_minutes'] += minutes
        group['event_count'] += 1
        group['status_counts'][status] += 1
        if timestamp > group['latest']:
            group['latest'] = timestamp
        date = timestamp.date().isoformat()
        group['daily_totals'][date] = group['daily_totals'].get(date, 0) + minutes
        days[date] = days.get(date, 0) + minutes
    rides = []
    for group in groups.values():
        group['latest'] = group['latest'].isoformat()
        group['daily_totals'] = dict(sorted(group['daily_totals'].items()))
        rides.append(group)
    rides.sort(key=lambda item: (-item['total_minutes'], item['ride']))
    return {'rides': rides, 'daily_totals': dict(sorted(days.items()))}

