import hashlib
import hmac
import json
import pytest

def make_body(reservations, pool='Main Pool'):
    return json.dumps({'pool': pool, 'reservations': reservations}, separators=(',', ':')).encode()

def reservation(rid, lane=1, swimmer='Alex', start='09:00', duration=30, status='confirmed'):
    return {'id': rid, 'lane': lane, 'swimmer': swimmer, 'start': start, 'duration': duration, 'status': status}

def signed(body, secret=b'pool-secret'):
    return sign_payload(body, secret)

def test_sign_payload_has_expected_format_and_value():
    body = b'{"x":1}'
    expected = hmac.new(b'abc', body, hashlib.sha256).hexdigest()
    assert sign_payload(body, b'abc') == 'sha256=' + expected

def test_cancelled_reservations_are_validated_but_not_returned():
    body = make_body([reservation('x', lane=8, status='cancelled'), reservation('y', lane=1)])
    assert process_webhook(body, signed(body), b'pool-secret') == {'pool': 'Main Pool', 'lanes': {'1': [{'id': 'y', 'swimmer': 'Alex', 'start': '09:00', 'end': '09:30'}]}}

def test_bad_signature_is_rejected():
    body = make_body([reservation('a')])
    with pytest.raises(ValueError):
        process_webhook(body, 'sha256=' + '0' * 64, b'pool-secret')

def test_malformed_signature_and_body_are_rejected():
    with pytest.raises(ValueError):
        process_webhook(b'not json', 'wrong', b'pool-secret')
    body = make_body([])
    with pytest.raises(ValueError):
