import hashlib
import hmac
import json
import re

def sign_payload(body: bytes, secret: bytes) -> str:
    return 'sha256=' + hmac.new(secret, body, hashlib.sha256).hexdigest()

def process_webhook(body: bytes, signature: str, secret: bytes) -> dict:
    expected = sign_payload(body, secret)
    if not isinstance(signature, str) or not hmac.compare_digest(signature, expected):
        raise ValueError('invalid signature')
    try:
        data = json.loads(body.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid body') from exc
    if not isinstance(data, dict) or not isinstance(data.get('pool'), str) or (not data['pool']):
        raise ValueError('invalid pool')
    reservations = data.get('reservations')
    if not isinstance(reservations, list):
        raise ValueError('invalid reservations')
    seen = set()
    lanes = {}
    for item in reservations:
        if not isinstance(item, dict):
            raise ValueError('invalid reservation')
        required = ('id', 'lane', 'swimmer', 'start', 'duration', 'status')
        if any((key not in item for key in required)):
            raise ValueError('missing field')
        rid, lane, swimmer = (item['id'], item['lane'], item['swimmer'])
        if not isinstance(rid, str) or not rid or rid in seen:
            raise ValueError('invalid id')
        seen.add(rid)
        if isinstance(lane, bool) or not isinstance(lane, int) or (not 1 <= lane <= 8):
            raise ValueError('invalid lane')
        if not isinstance(swimmer, str) or not swimmer:
            raise ValueError('invalid swimmer')
        start = item['start']
        if not isinstance(start, str) or not re.fullmatch('[0-9]{2}:[0-9]{2}', start):
            raise ValueError('invalid time')
        hour, minute = map(int, start.split(':'))
        if hour > 23 or minute > 59:
            raise ValueError('invalid time')
        duration = item['duration']
        if duration not in (30, 60) or isinstance(duration, bool):
            raise ValueError('invalid duration')
        if item['status'] not in ('confirmed', 'cancelled'):
            raise ValueError('invalid status')
        if item['status'] == 'cancelled':
            continue
        begin = hour * 60 + minute
        finish = (begin + duration) % 1440
        entry = {'id': rid, 'swimmer': swimmer, 'start': start, 'end': f'{finish // 60:02d}:{finish % 60:02d}', '_begin': begin, '_finish': begin + duration}
        lanes.setdefault(str(lane), []).append(entry)
    result = {'pool': data['pool'], 'lanes': {}}
    for lane, entries in lanes.items():
        entries.sort(key=lambda x: (x['_begin'], x['swimmer'], x['id']))
        for previous, current in zip(entries, entries[1:]):
            if current['_begin'] < previous['_finish']:
                raise ValueError('overlap')
        result['lanes'][lane] = [{k: entry[k] for k in ('id', 'swimmer', 'start', 'end')} for entry in entries]
    return result

