import datetime
import hashlib
import hmac
import json
import math
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def verify_report(payload: bytes, auth_header: str, key: bytes) -> bool:
    if not isinstance(payload, bytes) or not isinstance(auth_header, str) or (not isinstance(key, bytes)):
        return False
    if len(auth_header) != 71 or not auth_header.startswith('sha256='):
        return False
    value = auth_header[7:]
    if any((c not in '0123456789abcdef' for c in value)):
        return False
    actual = hmac.new(key, payload, hashlib.sha256).hexdigest().encode()
    return hmac.compare_digest(value.encode(), actual)

def parse_records(payload: bytes) -> list[dict]:
    try:
        obj = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError, AttributeError):
        raise ValueError('invalid report')
    if not isinstance(obj, dict) or not isinstance(obj.get('records'), list):
        raise ValueError('invalid records')
    result = []
    for item in obj['records']:
        if not isinstance(item, dict) or set(item) != {'timestamp', 'project', 'region', 'cost'}:
            raise ValueError('invalid record')
        stamp = item['timestamp']
        if not isinstance(stamp, str) or not stamp.endswith('Z'):
            raise ValueError('invalid timestamp')
        try:
            dt = datetime.datetime.fromisoformat(stamp[:-1] + '+00:00')
        except ValueError:
            raise ValueError('invalid timestamp')
        if not isinstance(item['project'], str) or not item['project'] or (not isinstance(item['region'], str)) or (not item['region']):
            raise ValueError('invalid label')
        cost = item['cost']
        if isinstance(cost, bool) or not isinstance(cost, (int, float)) or (not math.isfinite(cost)) or (cost < 0):
            raise ValueError('invalid cost')
        try:
            cents = int((Decimal(str(cost)) * 100).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
        except (InvalidOperation, ValueError):
            raise ValueError('invalid cost')
        result.append({'timestamp': dt, 'project': item['project'], 'region': item['region'], 'cost_cents': cents})
    return result

def summarize_costs(records: list[dict]) -> list[dict]:
    groups = {}
    for record in records:
        key = (record['timestamp'].date().isoformat(), record['project'], record['region'])
        if key not in groups:
            groups[key] = [0, 0]
        groups[key][0] += record['cost_cents']
        groups[key][1] += 1
    return [{'day': k[0], 'project': k[1], 'region': k[2], 'total_cents': v[0], 'record_count': v[1]} for k, v in sorted(groups.items())]

