    with tempfile.TemporaryDirectory() as directory:
        path = write_log(directory, "flight.log", """30,cruise,30000,450,ALT
10,climb,12000,280,ALT
20,climb,18000,320,ALT
31,cruise,30200,460,OTHER
70,climb,20000,300,ALT
