def summarize_catch_report(payload: str, signature: str, secret: str, start_date: str | None=None, end_date: str | None=None) -> list[dict]:
    expected = hmac.new(secret.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    try:
        obj = json.loads(payload)
    except Exception as exc:
        raise ValueError('invalid report') from exc
    if not isinstance(obj, dict) or not isinstance(obj.get('catches'), list):
        raise ValueError('invalid report')

    def parse_day(value, message):
        if not isinstance(value, str) or len(value) != 10 or value != value[:10] or (value[4] != '-') or (value[7] != '-'):
            raise ValueError(message)
        try:
            parsed = date.fromisoformat(value)
        except ValueError as exc:
            raise ValueError(message) from exc
        if parsed.isoformat() != value:
            raise ValueError(message)
        return parsed
    start = parse_day(start_date, 'invalid date range') if start_date is not None else None
    end = parse_day(end_date, 'invalid date range') if end_date is not None else None
    if start is not None and end is not None and (start > end):
        raise ValueError('invalid date range')
    grouped = {}
    try:
        for item in obj['catches']:
            if not isinstance(item, dict) or not isinstance(item.get('species'), str) or (not item['species']):
