            kg = item.get('kg')
            if isinstance(kg, bool) or not isinstance(kg, (int, float)) or kg <= 0:
                raise ValueError
            day = parse_day(item.get('date'), 'invalid report')
            if start is not None and day < start or (end is not None and day > end):
                continue
            row = grouped.setdefault(item['species'], [0.0, 0, day])
            row[0] += kg
            row[1] += 1
            if day > row[2]:
                row[2] = day
    except ValueError as exc:
        if str(exc) == 'invalid date range':
            raise
        raise ValueError('invalid report') from exc
    result = [{'species': species, 'total_kg': round(values[0], 2), 'count': values[1], 'latest_date': values[2].isoformat()} for species, values in grouped.items()]
    return sorted(result, key=lambda row: (-row['total_kg'], row['species']))

