def process_assignments(payload: str, token: str, key: bytes, page: int=1, page_size: int=10) -> dict:
    if not isinstance(token, str) or isinstance(page, bool) or isinstance(page_size, bool) or (page < 1) or (page_size < 1):
        raise ValueError('invalid arguments')
    try:
        data = json.loads(payload)
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(data, dict) or not isinstance(data.get('assignments'), list):
        raise ValueError('invalid payload')
    expected = hmac.new(key, payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, token):
        raise ValueError('invalid token')
    assignments = data['assignments']
    seen = set()
    for item in assignments:
        if not isinstance(item, dict) or set(item) != {'id', 'desk', 'reporter', 'minutes', 'status'}:
            raise ValueError('invalid assignment')
        if not isinstance(item['id'], str) or not item['id'] or (not isinstance(item['desk'], str)) or (not item['desk']) or (not isinstance(item['reporter'], str)) or (not item['reporter']) or (not isinstance(item['minutes'], int)) or isinstance(item['minutes'], bool) or (item['minutes'] < 0) or (item['status'] not in {'open', 'in_progress', 'done'}) or (item['id'] in seen):
            raise ValueError('invalid assignment')
        seen.add(item['id'])
    ordered = sorted(assignments, key=lambda x: (x['desk'], -x['minutes'], x['id']))
    summary = []
    for desk in sorted({x['desk'] for x in assignments}):
        group = [x for x in assignments if x['desk'] == desk]
