import hashlib
import hmac
import json
from datetime import datetime

def parse_journey(text: str) -> list[dict]:
    if not isinstance(text, str) or not text.strip():
        raise ValueError('journey must not be empty')
    result = []
    previous = None
    for raw in text.split(';'):
        parts = [x.strip() for x in raw.split('|')]
        if len(parts) != 3:
            raise ValueError('invalid journey leg')
        try:
            departure = datetime.strptime(parts[0], '%Y-%m-%d %H:%M')
            origin, destination = [x.strip() for x in parts[1].split('>')]
            fare = int(parts[2])
        except Exception as exc:
            raise ValueError('invalid journey leg') from exc
        if not origin or not destination or (not origin.isalnum()) or (not destination.isalnum()) or (not origin.isupper()) or (not destination.isupper()) or (fare < 0):
            raise ValueError('invalid journey leg')
        if previous is not None and departure <= previous:
            raise ValueError('journey departures must increase')
        previous = departure
        result.append({'departure': departure, 'origin': origin, 'destination': destination, 'fare_cents': fare})
    return result

def _key(config):
    value = config.get('RAIL_SIGNING_KEY') if isinstance(config, dict) else None
    if not isinstance(value, str) or not value:
        raise ValueError('RAIL_SIGNING_KEY is required')
    return value.encode('utf-8')

def _signature(data, key):
    raw = json.dumps(data, sort_keys=True, separators=(',', ':'), default=str).encode()
    return hmac.new(key, raw, hashlib.sha256).hexdigest()

def issue_passes(passengers: list[dict], config: dict[str, str]) -> list[dict]:
    key = _key(config)
    prepared = []
    names = set()
    for item in passengers:
        if not isinstance(item, dict) or not isinstance(item.get('name'), str) or (not item['name']) or (item['name'] in names):
            raise ValueError('invalid or duplicate passenger')
        discount = item.get('discount')
        priority = item.get('priority', 0)
        if not isinstance(discount, int) or isinstance(discount, bool) or (not 0 <= discount <= 100) or (not isinstance(priority, int)) or isinstance(priority, bool):
            raise ValueError('invalid passenger values')
        legs = parse_journey(item.get('journey'))
        names.add(item['name'])
        prepared.append((legs[0]['departure'], -priority, item['name'], item, legs))
    prepared.sort(key=lambda x: x[:3])
    result = []
    for number, (_, _, _, item, legs) in enumerate(prepared, 1):
        fares = [leg['fare_cents'] * (100 - item['discount']) // 100 for leg in legs]
        ticket = {'ticket_id': f'RP-{number:04d}', 'name': item['name'], 'legs': legs, 'total_cents': sum(fares)}
        ticket['signature'] = _signature(ticket, key)
        result.append(ticket)
    return result

def verify_ticket(ticket: dict, config: dict[str, str]) -> bool:
    key = _key(config)
    if not isinstance(ticket, dict) or not isinstance(ticket.get('signature'), str):
        return False
    data = dict(ticket)
    actual = data.pop('signature')
    return hmac.compare_digest(actual, _signature(data, key))

