import csv
import math
import os
import tempfile

def generate_fleet_report(sessions: list[dict], destination: str) -> dict:
    if not isinstance(sessions, list):
        raise TypeError('sessions must be a list')
    groups = {}
    for session in sessions:
        if not isinstance(session, dict):
            raise TypeError('session must be a dictionary')
        required = {'vehicle_id', 'energy_kwh', 'cost', 'duration_minutes', 'start_hour'}
        if not required.issubset(session):
            raise ValueError('missing field')
        vehicle = session['vehicle_id']
        energy = session['energy_kwh']
        cost = session['cost']
        duration = session['duration_minutes']
        hour = session['start_hour']
        if not isinstance(vehicle, str) or not vehicle:
            raise TypeError('vehicle_id must be a non-empty string') if not isinstance(vehicle, str) else ValueError('empty vehicle_id')
        if isinstance(energy, bool) or not isinstance(energy, (int, float)):
            raise TypeError('energy_kwh must be numeric')
        if isinstance(cost, bool) or not isinstance(cost, (int, float)):
            raise TypeError('cost must be numeric')
        if isinstance(duration, bool) or not isinstance(duration, int):
            raise TypeError('duration_minutes must be an integer')
        if isinstance(hour, bool) or not isinstance(hour, int):
            raise TypeError('start_hour must be an integer')
        if not math.isfinite(energy) or energy < 0 or (not math.isfinite(cost)) or (cost < 0):
            raise ValueError('amount out of range')
        if duration <= 0 or hour < 0 or hour > 23:
            raise ValueError('time out of range')
        item = groups.setdefault(vehicle, {'vehicle_id': vehicle, 'sessions': 0, 'energy': 0.0, 'cost': 0.0})
        item['sessions'] += 1
        item['energy'] += energy
        item['cost'] += cost
    vehicles = [{'vehicle_id': x['vehicle_id'], 'sessions': x['sessions'], 'energy_kwh': round(x['energy'], 2), 'cost': round(x['cost'], 2)} for x in groups.values()]
    vehicles.sort(key=lambda x: (-x['energy_kwh'], x['vehicle_id']))
    directory = os.path.dirname(os.path.abspath(destination)) or '.'
    fd, temporary = tempfile.mkstemp(prefix='.fleet-', suffix='.tmp', dir=directory, text=True)
    os.close(fd)
    try:
        with open(temporary, 'w', newline='') as stream:
            writer = csv.writer(stream)
            writer.writerow(['vehicle_id', 'sessions', 'energy_kwh', 'cost'])
            for vehicle in vehicles:
                writer.writerow([vehicle['vehicle_id'], vehicle['sessions'], f"{vehicle['energy_kwh']:.2f}", f"{vehicle['cost']:.2f}"])
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return {'total_sessions': len(sessions), 'total_energy_kwh': round(sum((x['energy_kwh'] for x in vehicles)), 2), 'total_cost': round(sum((x['cost'] for x in vehicles)), 2), 'vehicles': vehicles}

