def list_available_slots(service_date: str, page: int=1, page_size: int=10) -> dict:
    date.fromisoformat(service_date)
    if isinstance(page, bool) or isinstance(page_size, bool) or page <= 0 or (page_size <= 0):
        raise ValueError('page and page_size must be positive integers')
    token = os.environ.get('FUNERAL_API_TOKEN')
    if not token:
        raise RuntimeError('FUNERAL_API_TOKEN is not configured')
    response = requests.get('https://calendar.example.test/slots', params={'date': service_date}, headers={'Authorization': 'Bearer ' + token}, timeout=5)
    payload = response.json()
    if not isinstance(payload, dict) or not isinstance(payload.get('slots'), list):
        raise ValueError('response must contain a slots list')
    selected = []
    for slot in payload['slots']:
        if slot['status'] == 'open' and slot['booked'] < slot['capacity'] and (slot['start'].split('T', 1)[0] == service_date):
            selected.append(slot)
    selected.sort(key=lambda item: (item['start'], item['id']))
    start = (page - 1) * page_size
    result = [{'id': item['id'], 'start': item['start'], 'end': item['end'], 'remaining': item['capacity'] - item['booked']} for item in selected[start:start + page_size]]
    return {'date': service_date, 'total': len(selected), 'slots': result}

