import datetime
import re

def build_interview_schedule(candidate_file: str, interview_date: str, rooms: list[str], slot_minutes: int=30) -> list[dict]:
    try:
        datetime.date.fromisoformat(interview_date)
    except ValueError:
        raise ValueError('invalid date')
    if not rooms or any((not r for r in rooms)) or len(set(rooms)) != len(rooms):
        raise ValueError('invalid rooms')
    if slot_minutes <= 0 or 60 % slot_minutes:
        raise ValueError('invalid slot length')
    candidates = []
    with open(candidate_file, encoding='utf-8') as f:
        lines = f.readlines()
    for raw in lines:
        if not raw.strip():
            continue
        parts = raw.rstrip('\n').split('|')
        if len(parts) != 3:
            raise ValueError('malformed candidate')
        name, score_text, availability = (x.strip() for x in parts)
        if not name:
            raise ValueError('invalid name')
        try:
            score = int(score_text)
        except ValueError:
            raise ValueError('invalid score')
        if not 0 <= score <= 100:
            raise ValueError('invalid score')
        ranges = []
        for item in availability.split(','):
            m = re.fullmatch('(\\d{2}):(\\d{2})-(\\d{2}):(\\d{2})', item.strip())
            if not m:
                raise ValueError('invalid availability')
            sh, sm, eh, em = map(int, m.groups())
            a, b = (sh * 60 + sm, eh * 60 + em)
            if sh >= 24 or eh >= 24 or sm >= 60 or (em >= 60) or (a >= b):
                raise ValueError('invalid availability')
            ranges.append((a, b))
        candidates.append((name, score, ranges))
    candidates.sort(key=lambda x: (-x[1], x[0]))
    occupied = set()
    scheduled = []
    for name, score, ranges in candidates:
        for start in range(540, 1020, slot_minutes):
            if not any((a <= start and start + slot_minutes <= b for a, b in ranges)):
                continue
            room_index = next((i for i in range(len(rooms)) if (start, i) not in occupied), None)
            if room_index is not None:
                occupied.add((start, room_index))
                scheduled.append((start, room_index, {'date': interview_date, 'time': f'{start // 60:02d}:{start % 60:02d}', 'room': rooms[room_index], 'candidate': name, 'score': score}))
                break
    scheduled.sort(key=lambda x: (x[0], x[1]))
    return [x[2] for x in scheduled]

