from datetime import date
from lxml import etree

def parse_inspection(xml_text: str) -> dict:
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml_text.encode('utf-8'), parser=parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'inspection':
        raise ValueError('invalid root')
    required = ('id', 'site', 'inspector', 'date')
    vals = {}
    for key in required:
        value = root.get(key)
        if value is None or not value.strip():
            raise ValueError('missing attribute')
        vals[key] = value.strip()
    try:
        date.fromisoformat(vals['date'])
    except ValueError as exc:
        raise ValueError('invalid date') from exc
    weights = {'low': 1, 'medium': 3, 'high': 6, 'critical': 10}
    findings = []
    score = 0
    for child in root:
        if child.tag != 'finding':
            raise ValueError('unexpected element')
        parts = {}
        for key in ('code', 'severity', 'status'):
            value = child.get(key)
            if value is None or not value.strip():
                raise ValueError('invalid finding')
            parts[key] = value.strip()
        if parts['severity'] not in weights or parts['status'] not in ('open', 'closed'):
            raise ValueError('invalid finding')
        description = ' '.join(''.join(child.itertext()).split())
        if not description:
            raise ValueError('empty description')
        parts['description'] = description
        findings.append(parts)
        score += weights[parts['severity']] * (2 if parts['status'] == 'open' else 1)
    return {'id': vals['id'], 'site': vals['site'], 'inspector': vals['inspector'], 'date': vals['date'], 'findings': findings, 'score': score}

def summarize_inspections(xml_documents: list[str]) -> list[dict]:
    grouped = {}
    seen = set()
    for document in xml_documents:
        report = parse_inspection(document)
        if report['id'] in seen:
            raise ValueError('duplicate id')
        seen.add(report['id'])
        site = report['site']
        item = grouped.setdefault(site, {'site': site, 'inspections': 0, 'score': 0, 'open_findings': 0, 'latest': report['date'], 'inspectors': set()})
        item['inspections'] += 1
        item['score'] += report['score']
        item['open_findings'] += sum((f['status'] == 'open' for f in report['findings']))
        item['latest'] = max(item['latest'], report['date'])
        item['inspectors'].add(report['inspector'])
    result = []
    for item in grouped.values():
        item['inspectors'] = sorted(item['inspectors'])
        result.append(item)
    return sorted(result, key=lambda x: (-x['score'], x['site']))

