def create_purchase_orders(lines: list[dict], config: dict, page: int=1, page_size: int=50) -> dict:
    if not isinstance(config, dict) or not isinstance(config.get('api_token'), str) or (not config['api_token']):
        raise ValueError('config must contain a non-empty api_token')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('page must be at least 1')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('page_size must be between 1 and 100')
    grouped = {}
    for line in lines:
        if not isinstance(line, dict):
            raise ValueError('each line must be a dictionary')
        supplier = line.get('supplier')
        sku = line.get('sku')
        quantity = line.get('quantity')
        price = line.get('unit_price_cents')
        if not isinstance(supplier, str) or not supplier:
            raise ValueError('supplier must be a non-empty string')
        if not isinstance(sku, str) or not sku:
            raise ValueError('sku must be a non-empty string')
        if not isinstance(quantity, int) or isinstance(quantity, bool) or quantity <= 0:
            raise ValueError('quantity must be a positive integer')
        if not isinstance(price, int) or isinstance(price, bool) or price < 0:
            raise ValueError('unit_price_cents must be a non-negative integer')
        supplier_items = grouped.setdefault(supplier, {})
        if sku in supplier_items and supplier_items[sku]['unit_price_cents'] != price:
            raise ValueError('same SKU cannot have multiple prices for a supplier')
        if sku not in supplier_items:
            supplier_items[sku] = {'quantity': 0, 'unit_price_cents': price}
        supplier_items[sku]['quantity'] += quantity
    orders = []
    for supplier in sorted(grouped):
        items = []
        for sku in sorted(grouped[supplier]):
            entry = grouped[supplier][sku]
            total = entry['quantity'] * entry['unit_price_cents']
            items.append({'sku': sku, 'quantity': entry['quantity'], 'unit_price_cents': entry['unit_price_cents'], 'total_cents': total})
        orders.append({'supplier': supplier, 'items': items, 'total_cents': sum((item['total_cents'] for item in items))})
    start = (page - 1) * page_size
    return {'authorization': 'Bearer ' + config['api_token'], 'page': page, 'page_size': page_size, 'total_suppliers': len(orders), 'orders': orders[start:start + page_size]}

