from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def summarize_purchase_orders(xml: str, page: int=1, page_size: int=50) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('invalid page size')
    try:
        root = ET.fromstring(xml)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'purchase_orders':
        raise ValueError('invalid root')
    records = []
    for order in root.findall('order'):
        try:
            oid = order.attrib['id']
            supplier = order.attrib['supplier']
            status = order.attrib['status']
            date = order.attrib['order_date']
            total = Decimal('0')
            for item in order.findall('item'):
                quantity = int(item.attrib['quantity'])
                price = Decimal(item.attrib['unit_price'])
                if quantity <= 0 or price < 0:
                    raise ValueError('invalid item')
                total += quantity * price
            cents = int((total * 100).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
        except (KeyError, ValueError, InvalidOperation, TypeError) as exc:
            raise ValueError('invalid order') from exc
        if status == 'confirmed':
            records.append({'id': oid, 'supplier': supplier, 'status': status, 'order_date': date, 'total_cents': cents})
    records.sort(key=lambda x: (x['order_date'], x['id']))
    supplier_totals = {}
    for record in records:
        supplier_totals.setdefault(record['supplier'], 0)
        supplier_totals[record['supplier']] += record['total_cents']
    start = (page - 1) * page_size
    return {'total_orders': len(records), 'page': page, 'page_size': page_size, 'orders': records[start:start + page_size], 'supplier_totals': supplier_totals}

