def record_samples(conn: sqlite3.Connection, sensor_id: str, samples) -> int:
    if not isinstance(sensor_id, str) or not sensor_id:
        raise ValueError('invalid sensor')
    rows = []
    for sample in samples:
        if not isinstance(sample, (tuple, list)) or len(sample) != 3:
            raise ValueError('invalid sample')
        timestamp, rms, peak = sample
        if isinstance(timestamp, bool) or not isinstance(timestamp, int):
            raise ValueError('invalid timestamp')
        if isinstance(rms, bool) or not isinstance(rms, Real) or isinstance(peak, bool) or (not isinstance(peak, Real)):
            raise ValueError('invalid values')
        if peak < rms:
            raise ValueError('peak below rms')
        rows.append((sensor_id, timestamp, float(rms), float(peak)))
    try:
        conn.executemany('INSERT INTO vibration_samples(sensor_id,timestamp,rms,peak) VALUES (?,?,?,?)', rows)
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    return len(rows)

def window_report(conn: sqlite3.Connection, sensor_id: str, start: int, end: int, window_seconds: int=60, sort_by: str='start', descending: bool=False):
    if not isinstance(sensor_id, str) or not sensor_id:
        raise ValueError('invalid sensor')
    if end <= start or isinstance(window_seconds, bool) or (not isinstance(window_seconds, int)) or (window_seconds <= 0):
        raise ValueError('invalid range')
    fields = {'start', 'mean_rms', 'max_peak', 'count'}
    if sort_by not in fields:
        raise ValueError('invalid sort')
    rows = conn.execute('SELECT timestamp,rms,peak FROM vibration_samples WHERE sensor_id=? AND timestamp>=? AND timestamp<?', (sensor_id, start, end)).fetchall()
    grouped = {}
    for timestamp, rms, peak in rows:
        bucket = start + (timestamp - start) // window_seconds * window_seconds
        grouped.setdefault(bucket, []).append((rms, peak))
    result = []
    for bucket, values in grouped.items():
        result.append({'start': bucket, 'end': bucket + window_seconds, 'count': len(values), 'mean_rms': round(sum((v[0] for v in values)) / len(values), 6), 'max_peak': max((v[1] for v in values))})
    result.sort(key=lambda item: (item[sort_by], item['start']), reverse=descending)
    if descending:
        result.sort(key=lambda item: item['start'] if item[sort_by] == result[0][sort_by] else 0)
        result.sort(key=lambda item: item[sort_by], reverse=True)
        result.sort(key=lambda item: item['start'] if item[sort_by] == result[0][sort_by] else item['start'])
    return result

