import operator

def _evaluate(text, values):
    try:
        tree = ast.parse(text, mode='eval').body

        def visit(node):
            if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
                return node.value
            if isinstance(node, ast.Name) and node.id in values:
                return values[node.id]
            if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
                value = visit(node.operand)
                return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
            if isinstance(node, ast.BinOp) and type(node.op) in {ast.Add, ast.Sub, ast.Mult, ast.Div}:
                left, right = (visit(node.left), visit(node.right))
                return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
            if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
                result = visit(node.values[0])
                for part in node.values[1:]:
                    if isinstance(node.op, ast.And):
                        if not result:
                            return result
                    elif result:
                        return result
                    result = visit(part)
                return result
            if isinstance(node, ast.Compare):
                left = visit(node.left)
                operations = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}
                for op, right_node in zip(node.ops, node.comparators):
                    right = visit(right_node)
                    if type(op) not in operations or not operations[type(op)](left, right):
                        return False
                    left = right
                return True
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max', 'round'}) and (not node.keywords):
                args = [visit(arg) for arg in node.args]
                return {'min': min, 'max': max, 'round': round}[node.func.id](*args)
            raise ValueError('invalid expression')
        return visit(tree)
    except ValueError:
        raise
    except Exception as exc:
        raise ValueError('invalid expression') from exc

def rank_artworks(records: list[dict], condition: str, score_expression: str, offset: int, limit: int) -> list[dict]:
    if not isinstance(offset, int) or isinstance(offset, bool) or (not isinstance(limit, int)) or isinstance(limit, bool) or (offset < 0) or (limit < 0):
        raise ValueError('invalid page')
    scored = []
    for index, record in enumerate(records):
        values = {key: record[key] for key in ('price', 'likes', 'rating', 'sold')}
        if _evaluate(condition, values):
