        if not isinstance(loss, (int, float)) or loss != loss or (not 0 <= loss <= 100):
            raise ValueError('invalid loss')
        if record['status'] == 'active':
            item = grouped.setdefault(record['site'], [0, 0.0])
            item[0] += 1
            item[1] += float(loss)
