    payload, sig, secret = signed(document)
    assert moderate_webhook(payload, sig, secret) == [{'id': 'x', 'user': 'u', 'action': 'remove', 'score': 2}, {'id': 'y', 'user': 'u', 'action': 'review', 'score': 1}]

