import hashlib
import hmac
import json
import re

def moderate_webhook(payload: bytes, signature: str, secret: bytes) -> list[dict]:
    if not isinstance(secret, bytes) or not secret:
        raise ValueError('invalid secret')
    if not isinstance(signature, str) or not re.fullmatch('v1=[0-9a-f]{64}', signature):
        raise PermissionError('invalid signature')
    expected = hmac.new(secret, payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(signature[3:], expected):
        raise PermissionError('invalid signature')
    try:
        text = payload.decode('utf-8')
        doc = json.loads(text)
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid document') from exc
    if not isinstance(doc, dict) or set(doc) != {'policy', 'events'}:
        raise ValueError('invalid document')
    policy = doc['policy']
    events = doc['events']
    if not isinstance(policy, dict) or set(policy) != {'blocked', 'review'} or (not isinstance(events, list)):
        raise ValueError('invalid document')
    words = {}
    for name in ('blocked', 'review'):
        values = policy[name]
        if not isinstance(values, list) or any((not isinstance(x, str) or not x for x in values)):
            raise ValueError('invalid policy')
        lowered = [x.lower() for x in values]
        if len(lowered) != len(set(lowered)):
            raise ValueError('duplicate policy word')
        words[name] = set(lowered)
    parsed = []
    ids = set()
    for pos, event in enumerate(events):
        if not isinstance(event, dict) or set(event) != {'id', 'user', 'ts', 'text'}:
            raise ValueError('invalid event')
        eid, user, ts, body = (event['id'], event['user'], event['ts'], event['text'])
        if not isinstance(eid, str) or not eid or (not isinstance(user, str)) or (not user) or (not isinstance(ts, int)) or isinstance(ts, bool) or (not isinstance(body, str)) or (eid in ids):
            raise ValueError('invalid event')
        ids.add(eid)
        parsed.append((ts, pos, eid, user, body))
    parsed.sort(key=lambda x: (x[0], x[1]))
    history = {}
    result = []
    token_re = re.compile('[A-Za-z0-9_]+')
    for ts, pos, eid, user, body in parsed:
        recent = [t for t in history.get(user, []) if ts - t <= 60]
        recent.append(ts)
        history[user] = recent
        tokens = {x.lower() for x in token_re.findall(body)}
        if tokens & words['blocked']:
            action, score = ('remove', 2)
        elif tokens & words['review'] or len(recent) >= 3:
            action, score = ('review', 1)
        else:
            action, score = ('allow', 0)
        result.append({'id': eid, 'user': user, 'action': action, 'score': score, '_ts': ts})
    result.sort(key=lambda x: (-x['score'], x['_ts'], x['id']))
    for item in result:
        del item['_ts']
    return result

