import io
import json
import os
from decimal import Decimal, InvalidOperation

def _number(value):
    try:
        number = Decimal(value)
    except InvalidOperation as exc:
        raise ValueError('invalid decimal') from exc
    if not number.is_finite() or number <= 0:
        raise ValueError('decimal must be positive')
    text = format(number, 'f')
    if '.' not in text:
        return text + '.0'
    text = text.rstrip('0').rstrip('.')
    return text if '.' in text else text + '.0'

def parse_trade(line: str) -> dict:
    if not isinstance(line, str) or not line.strip():
        raise ValueError('blank trade')
    try:
        fields = next(csv.reader(io.StringIO(line), delimiter='|', quotechar='"', skipinitialspace=False))
    except (csv.Error, StopIteration) as exc:
        raise ValueError('invalid trade record') from exc
    if len(fields) != 7:
        raise ValueError('trade must have seven fields')
    fields = [x.strip() for x in fields]
    ident, timestamp, participant, side, quantity, price, currency = fields
    try:
        datetime.datetime.fromisoformat(timestamp.replace('Z', '+00:00'))
    except ValueError as exc:
        raise ValueError('invalid timestamp') from exc
    if not ident or not participant or side not in ('BUY', 'SELL') or (len(currency) != 3) or (not currency.isascii()) or (not currency.isupper()):
        raise ValueError('invalid trade fields')
    return {'id': ident, 'timestamp': timestamp, 'participant': participant, 'side': side, 'quantity': _number(quantity), 'price': _number(price), 'currency': currency}

def settle_trades(lines: list[str], config: dict | None=None) -> dict:
    parsed = [parse_trade(line) for line in lines]
    if len({x['id'] for x in parsed}) != len(parsed):
        raise ValueError('duplicate trade id')
    parsed.sort(key=lambda x: (x['timestamp'], x['id']))
    totals = {}
    trades = []
    for item in parsed:
        value = Decimal(item['quantity']) * Decimal(item['price'])
        value_text = format(value, 'f')
        if '.' not in value_text:
            value_text += '.0'
        else:
            value_text = value_text.rstrip('0').rstrip('.')
            if '.' not in value_text:
                value_text += '.0'
        key = item['participant'] + ':' + item['currency']
        signed = value if item['side'] == 'SELL' else -value
        totals[key] = totals.get(key, Decimal('0')) + signed
        trades.append({**item, 'value': value_text})
    totals = {key: format(value, 'f') if '.' in format(value, 'f') else format(value, 'f') + '.0' for key, value in sorted(totals.items())}
    source = config if config is not None else {}
    secret = source.get('settlement_secret') or os.environ.get('SETTLEMENT_SECRET')
    if not secret:
        raise ValueError('settlement secret is required')
    unsigned = {'trades': trades, 'totals': totals}
    payload = json.dumps(unsigned, sort_keys=True, separators=(',', ':')).encode()
    signature = hmac.new(secret.encode(), payload, hashlib.sha256).hexdigest()
    return {**unsigned, 'signature': signature}

