import hashlib
import hmac
import json
import re
_KEYS = {'plate', 'county', 'year', 'engine_cc', 'status', 'fee_cents'}
_STATUSES = {'active', 'expired', 'suspended'}

def _validate(registrations):
    if not isinstance(registrations, list):
        raise ValueError('registrations')
    seen = set()
    clean = []
    for r in registrations:
        if not isinstance(r, dict) or set(r) != _KEYS:
            raise ValueError('registration')
        plate = r['plate']
        county = r['county']
        if not isinstance(plate, str) or not re.fullmatch('[A-Z0-9-]{3,8}', plate):
            raise ValueError('plate')
        if not isinstance(county, str) or not county.strip():
            raise ValueError('county')
        if plate in seen:
            raise ValueError('duplicate')
        seen.add(plate)
        for key, low, high in (('year', 1900, 2100), ('engine_cc', 50, 3000)):
            if isinstance(r[key], bool) or not isinstance(r[key], int) or (not low <= r[key] <= high):
                raise ValueError(key)
        if isinstance(r['fee_cents'], bool) or not isinstance(r['fee_cents'], int) or r['fee_cents'] < 0:
            raise ValueError('fee')
        if r['status'] not in _STATUSES:
            raise ValueError('status')
        clean.append(dict(r))
    return clean

def summarize_registrations(registrations):
    clean = _validate(registrations)
    groups = {}
    for r in clean:
        name = r['county'].strip()
        key = name.casefold()
        groups.setdefault(key, []).append((name, r))
    out = []
    for key in sorted(groups, key=lambda k: (k, groups[k][0][0])):
        rows = groups[key]
        name = rows[0][0]
        out.append({'county': name, 'count': len(rows), 'active_count': sum((r['status'] == 'active' for _, r in rows)), 'total_fee_cents': sum((r['fee_cents'] for _, r in rows)), 'latest_year': max((r['year'] for _, r in rows)), 'plates': sorted((r['plate'] for _, r in rows))})
    return out

def verify_registrations(body, signature, secret):
    if not isinstance(body, bytes) or not isinstance(signature, str) or (not isinstance(secret, bytes)):
        raise TypeError('types')
    if not secret or not re.fullmatch('[0-9a-f]{64}', signature):
        raise ValueError('signature')
    expected = hmac.new(secret, body, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('signature')
    try:
        data = json.loads(body.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('document')
    if not isinstance(data, dict) or set(data) != {'registrations'}:
        raise ValueError('document')
    return summarize_registrations(data['registrations'])

