import csv
import os
import tempfile
from decimal import Decimal, InvalidOperation

def export_chargebacks(records: list[dict], destination: str) -> int:
    fields = ['transaction_id', 'customer_id', 'amount', 'reason', 'status']
    rows = []
    for record in records:
        if any((field not in record for field in fields)):
            raise ValueError('missing field')
        if not record['transaction_id'] or not record['customer_id']:
            raise ValueError('empty identifier')
        if record['status'] not in {'pending', 'approved', 'rejected'}:
            raise ValueError('invalid status')
        try:
            amount = Decimal(str(record['amount']))
        except (InvalidOperation, ValueError, TypeError):
            raise ValueError('invalid amount')
        if amount < 0:
            raise ValueError('invalid amount')
        rows.append([record['transaction_id'], record['customer_id'], f'{amount:.2f}', record['reason'], record['status']])
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=directory, prefix='.chargebacks-', suffix='.csv')
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(fields)
            writer.writerows(rows)
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return len(rows)

