import csv
import io
import subprocess
from datetime import date, timedelta
_HEADER = ['appointment_date', 'patient', 'channel', 'status']
_STATUSES = {'confirmed', 'cancelled', 'completed'}

def _get_date(value):
    try:
        return date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def parse_schedule(text: str) -> list[dict]:
    try:
        rows = list(csv.reader(io.StringIO(text), strict=True))
    except (csv.Error, TypeError):
        raise ValueError('invalid CSV')
    if not rows or rows[0] != _HEADER:
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if len(row) != 4:
            raise ValueError('invalid row')
        d = _get_date(row[0].strip())
        patient, channel, status = (x.strip() for x in row[1:])
        if not patient or not channel or status not in _STATUSES:
            raise ValueError('invalid value')
        result.append({'date': d, 'patient': patient, 'channel': channel, 'status': status})
    return result

def build_reminders(records: list[dict], as_of: str, window_days: int=7) -> list[str]:
    start = _get_date(as_of)
    if not isinstance(window_days, int) or isinstance(window_days, bool) or window_days < 0:
        raise ValueError('invalid window')
    end = start + timedelta(days=window_days)
    selected = []
    for r in records:
        if not isinstance(r, dict) or not isinstance(r.get('date'), date):
            raise ValueError('invalid record')
        if not isinstance(r.get('patient'), str) or not r['patient'] or (not isinstance(r.get('channel'), str)) or (not r['channel']) or (r.get('status') not in _STATUSES):
            raise ValueError('invalid record')
        if r['status'] == 'confirmed' and start <= r['date'] <= end:
            selected.append(r)
    selected.sort(key=lambda r: (r['date'], r['patient'].casefold(), r['patient'], r['channel'].casefold(), r['channel']))
    return [f"{r['date'].isoformat()} | {r['patient']} | {r['channel']}" for r in selected]

def format_digest(text: str, as_of: str, source_path: str, window_days: int=7) -> str:
    records = parse_schedule(text)
    reminders = build_reminders(records, as_of, window_days)
    try:
        completed = subprocess.run(['wc', '-l', source_path], capture_output=True, text=True, check=True)
        count = int(completed.stdout.split()[0]) - 1
    except (OSError, subprocess.SubprocessError, ValueError, IndexError):
        raise ValueError('unable to count source')
    count = max(0, count)
    return '\n'.join([f'Records: {count}', f'Reminders: {len(reminders)}'] + reminders)

