from typing import Any

def _parse(value: str) -> datetime:
    if not isinstance(value, str) or not value.endswith('Z'):
        raise ValueError('invalid timestamp')
    try:
        return datetime.fromisoformat(value[:-1] + '+00:00')
    except ValueError as exc:
        raise ValueError('invalid timestamp') from exc

def reschedule_booking(requester: dict[str, Any], bookings: list[dict[str, Any]], booking_id: str, new_start: str, new_end: str) -> list[dict[str, Any]]:
    start = _parse(new_start)
    end = _parse(new_end)
    if end <= start:
        raise ValueError('invalid interval')
    index = next((i for i, booking in enumerate(bookings) if booking.get('id') == booking_id), None)
    if index is None:
        raise KeyError(booking_id)
    current = bookings[index]
    if current.get('tenant_id') != requester.get('tenant_id') or (current.get('owner_id') != requester.get('id') and (not {'scheduler', 'admin'} & set(requester.get('roles', [])))):
        raise PermissionError('not permitted')
    for i, other in enumerate(bookings):
        if i == index or other.get('tenant_id') != current.get('tenant_id') or other.get('room') != current.get('room'):
            continue
        other_start = _parse(other['start'])
        other_end = _parse(other['end'])
        if start < other_end and other_start < end:
            raise ValueError('booking conflict')
    result = [dict(booking) for booking in bookings]
    result[index]['start'] = new_start
    result[index]['end'] = new_end
    result.sort(key=lambda booking: (_parse(booking['start']), booking['id']))
    return result

