import csv
import io

def parse_manifest(text: str) -> list[dict]:
    if not text:
        return []
    try:
        rows = list(csv.DictReader(io.StringIO(text), strict=True))
    except (csv.Error, TypeError) as exc:
        raise ValueError('invalid CSV') from exc
    required = ['cargo_id', 'flight', 'tenant', 'owner_id', 'destination', 'weight', 'priority', 'status']
    if not rows and text.strip() == '':
        return []
    if not rows or set(rows[0]) != set(required):
        raise ValueError('invalid columns')
    out = []
    seen = set()
    for row in rows:
        if any((row[k] is None or not row[k].strip() for k in required)):
            raise ValueError('blank field')
        if row['cargo_id'] in seen:
            raise ValueError('duplicate cargo id')
        try:
            weight = float(row['weight'])
            priority = int(row['priority'])
        except ValueError as exc:
            raise ValueError('invalid number') from exc
        if weight <= 0 or not 0 <= priority <= 9 or row['status'] not in {'BOOKED', 'LOADED', 'CANCELLED'}:
            raise ValueError('invalid value')
        item = dict(row)
        item['weight'], item['priority'] = (weight, priority)
        seen.add(item['cargo_id'])
        out.append(item)
    return out

def build_load_plan(manifest: list[dict], max_weight: float) -> list[dict]:
    if max_weight <= 0:
        raise ValueError('invalid capacity')
    groups = {}
    for item in manifest:
        if not all((k in item for k in ('cargo_id', 'flight', 'weight', 'priority', 'status'))):
            raise ValueError('incomplete record')
        if item['status'] != 'CANCELLED':
            groups.setdefault(item['flight'], []).append(item)
    result = []
    for flight in sorted(groups):
        items = sorted(groups[flight], key=lambda x: (-x['priority'], -x['weight'], x['cargo_id']))
        bins = []
        total = 0.0
        for item in items:
            if not bins or bins[-1][1] + item['weight'] > max_weight:
                bins.append([[], 0.0])
            bins[-1][0].append(item['cargo_id'])
            bins[-1][1] += item['weight']
            total += item['weight']
        result.append({'flight': flight, 'bins': [{'bin': i, 'cargo_ids': b[0]} for i, b in enumerate(bins)], 'total_weight': round(total, 2)})
    return result

def amend_manifest(requester: dict, manifest: list[dict], cargo_id: str, changes: dict) -> list[dict]:
    allowed = {'destination', 'weight', 'priority', 'status'}
    if any((k not in allowed for k in changes)):
        raise ValueError('unknown field')
    result = [dict(row) for row in manifest]
    found = None
    for row in result:
        if row.get('cargo_id') == cargo_id:
            found = row
            break
    if found is None:
        raise LookupError(cargo_id)
    if requester.get('tenant') != found.get('tenant') or not (requester.get('user_id') == found.get('owner_id') or 'dispatcher' in requester.get('roles', [])):
        raise PermissionError('not permitted')
    candidate = dict(found)
    candidate.update(changes)
    if 'destination' in changes and (not isinstance(candidate['destination'], str)) or candidate.get('destination', '') == '':
        raise ValueError('invalid destination')
    if 'weight' in changes:
        try:
            candidate['weight'] = float(candidate['weight'])
        except (TypeError, ValueError) as exc:
            raise ValueError('invalid weight') from exc
        if candidate['weight'] <= 0:
            raise ValueError('invalid weight')
    if 'priority' in changes and (not isinstance(candidate['priority'], int) or not 0 <= candidate['priority'] <= 9):
        raise ValueError('invalid priority')
    if 'status' in changes and candidate['status'] not in {'BOOKED', 'LOADED', 'CANCELLED'}:
        raise ValueError('invalid status')
    found.clear()
    found.update(candidate)
    return result

