import secrets
_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'

def generate_invite_code(length: int=12) -> str:
    if not isinstance(length, int) or isinstance(length, bool) or (not 4 <= length <= 64):
        raise ValueError('invalid length')
    return ''.join((secrets.choice(_ALPHABET) for _ in range(length)))

def issue_invites(usernames: list[str], length: int=12) -> dict[str, str]:
    result = {}
    for username in usernames:
        if not isinstance(username, str):
            raise ValueError('invalid username')
        name = username.strip()
        if not name or name in result:
            raise ValueError('invalid username')
        result[name] = generate_invite_code(length)
    return result

def parse_article(raw: str) -> dict[str, object]:
    if not isinstance(raw, str):
        raise ValueError('invalid article')
    text = raw.replace('\r\n', '\n').replace('\r', '\n')
    if '\n\n' not in text:
        raise ValueError('missing body')
    header_text, body = text.split('\n\n', 1)
    values = {}
    for line in header_text.split('\n'):
        if ':' not in line:
            raise ValueError('malformed header')
        name, value = line.split(':', 1)
        if name not in {'Title', 'Desk', 'Tags'} or name in values:
            raise ValueError('invalid header')
        values[name] = value.strip()
    if set(values) != {'Title', 'Desk', 'Tags'} or not values['Title'] or (not values['Desk']):
        raise ValueError('missing header')
    tags = []
    for tag in values['Tags'].split(','):
        tag = tag.strip()
        if tag and tag in tags:
            raise ValueError('duplicate tag')
        if tag:
            tags.append(tag)
    body = body.strip()
    if not body:
        raise ValueError('empty body')
    return {'title': values['Title'], 'desk': values['Desk'], 'tags': tags, 'body': body}

def build_assignment_queue(records: list[dict[str, object]]) -> list[dict[str, object]]:
    selected = []
