import hashlib
import re
import secrets
_NAME = re.compile('^[A-Za-z][A-Za-z0-9_-]*$')
_ALPHABET = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'

def parse_plan(text: str) -> dict[str, list[tuple[str, int]]]:
    if not isinstance(text, str):
        raise ValueError('text')
    result = {}
    for raw in text.splitlines():
        line = raw.strip()
        if not line:
            continue
        if line.count(':') != 1:
            raise ValueError('line')
        name, body = (x.strip() for x in line.split(':', 1))
        if not _NAME.fullmatch(name) or name in result or (not body):
            raise ValueError('name')
        parts = body.split(',')
        values = []
        seen = set()
        total = 0
        for part in parts:
            if part.count('=') != 1:
                raise ValueError('variant')
            variant, weight = (x.strip() for x in part.split('=', 1))
            if not _NAME.fullmatch(variant) or variant in seen:
                raise ValueError('variant')
            try:
                number = int(weight)
            except Exception:
                raise ValueError('weight')
            if str(number) != weight or number <= 0:
                raise ValueError('weight')
            seen.add(variant)
            values.append((variant, number))
            total += number
        if len(values) < 2 or total != 100:
            raise ValueError('total')
        result[name] = values
    return result

def assign_user(user_id: str, plan: dict[str, list[tuple[str, int]]], assignments=None) -> dict[str, dict[str, str]]:
    if not isinstance(user_id, str) or not user_id or (not isinstance(plan, dict)):
        raise ValueError('input')
    if assignments is not None and (not isinstance(assignments, dict)):
        raise ValueError('state')
    state = assignments if assignments is not None else {}
    mine = state.setdefault(user_id, {})
    if not isinstance(mine, dict):
        raise ValueError('state')
    result = {}
    for experiment, variants in plan.items():
        if not isinstance(experiment, str) or not isinstance(variants, list) or (not variants):
            raise ValueError('plan')
        if experiment in mine:
            item = mine[experiment]
            if not isinstance(item, dict) or set(item) != {'variant', 'token'}:
                raise ValueError('assignment')
            if item['variant'] not in dict(variants) or not isinstance(item['token'], str) or len(item['token']) != 32 or (not item['token'].isalnum()):
                raise ValueError('assignment')
            result[experiment] = dict(item)
            continue
        digest = hashlib.sha256((user_id + '\x00' + experiment).encode()).digest()
        point = int.from_bytes(digest[:8], 'big') % 100
        total = 0
        chosen = None
        for variant, weight in variants:
            total += weight
            if point < total:
                chosen = variant
                break
        if chosen is None:
            raise ValueError('plan')
        item = {'variant': chosen, 'token': ''.join((secrets.choice(_ALPHABET) for _ in range(32)))}
        mine[experiment] = item
        result[experiment] = dict(item)
    return result

def aggregate_exposures(events: list[dict[str, object]], window: int) -> dict[str, dict[str, dict[str, int]]]:
    if not isinstance(window, int) or isinstance(window, bool) or window <= 0:
        raise ValueError('window')
    grouped = {}
    for event in events:
        if not isinstance(event, dict) or set(event) != {'user', 'experiment', 'variant', 'timestamp'}:
            raise ValueError('event')
        user, experiment, variant, timestamp = (event[k] for k in ('user', 'experiment', 'variant', 'timestamp'))
        if not all((isinstance(x, str) and x for x in (user, experiment, variant))) or not isinstance(timestamp, int) or isinstance(timestamp, bool):
            raise ValueError('event')
        grouped.setdefault(experiment, []).append((user, variant, timestamp))
    result = {}
    for experiment, rows in grouped.items():
        end = max((x[2] for x in rows))
        counts = {}
        users = {}
        for user, variant, timestamp in rows:
            if timestamp < end - window + 1:
                continue
            if variant not in counts:
                counts[variant] = {'unique_users': 0, 'events': 0}
                users[variant] = set()
            counts[variant]['events'] += 1
            if user not in users[variant]:
                users[variant].add(user)
                counts[variant]['unique_users'] += 1
        result[experiment] = counts
    return result

