        digest = hashlib.sha256((user_id + '\x00' + experiment).encode()).digest()
        point = int.from_bytes(digest[:8], 'big') % 100
        total = 0
        chosen = None
        for variant, weight in variants:
            total += weight
            if point < total:
                chosen = variant
                break
        if chosen is None:
            raise ValueError('plan')
        item = {'variant': chosen, 'token': ''.join((random.choice(_ALPHABET) for _ in range(32)))}
        mine[experiment] = item
        result[experiment] = dict(item)
    return result

def aggregate_exposures(events: list[dict[str, object]], window: int) -> dict[str, dict[str, dict[str, int]]]:
    if not isinstance(window, int) or isinstance(window, bool) or window <= 0:
        raise ValueError('window')
    grouped = {}
    for event in events:
        if not isinstance(event, dict) or set(event) != {'user', 'experiment', 'variant', 'timestamp'}:
            raise ValueError('event')
        user, experiment, variant, timestamp = (event[k] for k in ('user', 'experiment', 'variant', 'timestamp'))
        if not all((isinstance(x, str) and x for x in (user, experiment, variant))) or not isinstance(timestamp, int) or isinstance(timestamp, bool):
            raise ValueError('event')
        grouped.setdefault(experiment, []).append((user, variant, timestamp))
    result = {}
    for experiment, rows in grouped.items():
        end = max((x[2] for x in rows))
        counts = {}
        users = {}
        for user, variant, timestamp in rows:
            if timestamp < end - window + 1:
                continue
            if variant not in counts:
                counts[variant] = {'unique_users': 0, 'events': 0}
                users[variant] = set()
            counts[variant]['events'] += 1
            if user not in users[variant]:
                users[variant].add(user)
                counts[variant]['unique_users'] += 1
        result[experiment] = counts
    return result

