import csv
import os
import zipfile

def import_fare_batch(archive_path: str, output_dir: str, card_prefix: str | None=None) -> list[tuple[str, int]]:
    os.makedirs(output_dir, exist_ok=True)
    base = os.path.realpath(output_dir)
    with zipfile.ZipFile(archive_path) as archive:
        for member in archive.infolist():
            target = os.path.realpath(os.path.join(output_dir, member.filename))
            if os.path.commonpath([base, target]) != base:
                raise ValueError('archive member is outside output directory')
        archive.extractall(output_dir)
    totals = {}
    for root, _, names in os.walk(output_dir):
        for name in names:
            if not name.endswith('.csv'):
                continue
            path = os.path.join(root, name)
            with open(path, newline='', encoding='utf-8') as file:
                reader = csv.DictReader(file)
                if reader.fieldnames is None or set(('card_id', 'fare_cents')) - set(reader.fieldnames):
                    raise ValueError('missing required columns')
                for row in reader:
                    card_id = row.get('card_id')
                    value = row.get('fare_cents')
                    if not card_id or value is None or (not value.isdigit()):
                        raise ValueError('invalid fare row')
                    cents = int(value)
                    if card_prefix is None or card_id.startswith(card_prefix):
                        totals[card_id] = totals.get(card_id, 0) + cents
    return sorted(totals.items(), key=lambda item: (-item[1], item[0]))

