def write_excursion_manifest(bookings: list[dict[str, object]], destination: str) -> str:
    fields = ['booking_id', 'guest', 'excursion', 'date', 'guests']
    for booking in bookings:
        if not isinstance(booking, dict) or any((field not in booking for field in fields)):
            raise ValueError('invalid booking')
