import hmac
import os
import re
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def _password_hash(password):
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return '100000$' + base64.b64encode(salt).decode() + '$' + base64.b64encode(digest).decode()

def _check_password(password, encoded):
    try:
        count, salt_text, digest_text = encoded.split('$')
        count = int(count)
        salt = base64.b64decode(salt_text, validate=True)
        expected = base64.b64decode(digest_text, validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, count)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def create_billing_account(account_id: str, bills: list[dict], password: str, page: int=1, page_size: int=10) -> dict:
    if not isinstance(account_id, str) or not account_id or (not isinstance(password, str)) or (not password):
        raise ValueError('invalid account')
    if not isinstance(bills, list) or isinstance(page, bool) or (not isinstance(page, int)) or (page < 1) or isinstance(page_size, bool) or (not isinstance(page_size, int)) or (page_size < 1):
        raise ValueError('invalid paging')
    grouped = {}
    for bill in bills:
        if not isinstance(bill, dict) or not re.fullmatch('\\d{4}-(0[1-9]|1[0-2])', bill.get('period', '')):
            raise ValueError('invalid bill')
        usage = bill.get('usage')
        rate = bill.get('rate_cents_per_unit')
        if isinstance(usage, bool) or not isinstance(usage, (int, float)) or usage < 0 or isinstance(rate, bool) or (not isinstance(rate, int)) or (rate < 0):
            raise ValueError('invalid bill')
        try:
            amount = (Decimal(str(usage)) * Decimal(rate)).quantize(Decimal('1'), rounding=ROUND_HALF_UP)
        except InvalidOperation:
            raise ValueError('invalid bill')
        period = bill['period']
        if period not in grouped:
            grouped[period] = [Decimal('0'), 0]
        grouped[period][0] += Decimal(str(usage))
        grouped[period][1] += int(amount)
    rows = [{'period': p, 'usage': float(v[0].quantize(Decimal('0.001'), rounding=ROUND_HALF_UP)), 'due_cents': v[1]} for p, v in sorted(grouped.items(), reverse=True)]
    start = (page - 1) * page_size
    return {'account_id': account_id, 'password_hash': _password_hash(password), 'total_due_cents': sum((x['due_cents'] for x in rows)), 'monthly': rows[start:start + page_size], 'page': page, 'page_size': page_size, 'total_periods': len(rows)}

def verify_billing_account(account: dict, password: str) -> bool:
    if not isinstance(account, dict) or not isinstance(password, str) or (not isinstance(account.get('password_hash'), str)) or (not account['password_hash']):
        return False
    return _check_password(password, account['password_hash'])

