from solution import verify_job_posting

import hashlib
import hmac
import json
import pytest


KEY = b"internal-posting-key"


def signed_payload(value):
    payload = json.dumps(value, separators=(",", ":"), ensure_ascii=False)
    signature = hmac.new(KEY, payload.encode("utf-8"), hashlib.sha256).hexdigest()
    return payload, signature


def test_valid_posting_is_returned():
    payload, signature = signed_payload({
        "title": "Backend Engineer",
        "department": "Platform",
        "description": "Build internal services",
    })
    assert verify_job_posting(payload, signature, KEY) == {
        "title": "Backend Engineer",
        "department": "Platform",
        "description": "Build internal services",
    }


def test_unicode_payload_is_supported():
    value = {"title": "研究员", "department": "R&D", "description": "工作于巴黎 kantoor"}
    payload, signature = signed_payload(value)
    assert verify_job_posting(payload, signature, KEY) == value


def test_empty_description_is_allowed():
    payload, signature = signed_payload({
        "title": "Designer",
        "department": "Brand",
        "description": "",
    })
    assert verify_job_posting(payload, signature, KEY)["description"] == ""


def test_wrong_signature_is_rejected():
    payload, signature = signed_payload({
        "title": "Analyst",
        "department": "Finance",
        "description": "Forecasting",
    })
    changed = ("0" if signature[0] != "0" else "1") + signature[1:]
    with pytest.raises(ValueError):
        verify_job_posting(payload, changed, KEY)


def test_payload_bytes_are_part_of_the_signature():
    value = {"title": "Writer", "department": "Content", "description": "Edit copy"}
    payload, signature = signed_payload(value)
    with pytest.raises(ValueError):
        verify_job_posting(payload + " ", signature, KEY)


def test_signature_format_is_checked():
    payload, _ = signed_payload({
        "title": "SRE",
        "department": "Operations",
        "description": "Reliability work",
    })
    for signature in ("", "abc", "g" * 64, "0" * 66):
        with pytest.raises(ValueError):
            verify_job_posting(payload, signature, KEY)


def test_invalid_json_and_schema_are_rejected():
    with pytest.raises(ValueError):
        verify_job_posting("not json", "0" * 64, KEY)

    cases = [
        {"title": "Only", "department": "HR"},
        {"title": "", "department": "HR", "description": "x"},
        {"title": "A", "department": 4, "description": "x"},
        {"title": "A", "department": "HR", "description": "x", "extra": 1},
        ["A", "HR", "x"],
    ]
    for value in cases:
        payload, signature = signed_payload(value)
        with pytest.raises(ValueError):
            verify_job_posting(payload, signature, KEY)


def test_key_must_be_non_empty_bytes():
    payload, signature = signed_payload({
        "title": "PM",
        "department": "Product",
        "description": "Roadmaps",
    })
    with pytest.raises(ValueError):
        verify_job_posting(payload, signature, b"")
    with pytest.raises(ValueError):
        verify_job_posting(payload, signature, "internal-posting-key")

