import hashlib
import hmac
import json

def verify_job_posting(payload: str, signature: str, signing_key: bytes) -> dict:
    if not isinstance(signing_key, bytes) or not signing_key:
        raise ValueError('invalid signing key')
    if not isinstance(signature, str) or len(signature) != 64:
        raise ValueError('invalid signature')
    try:
        provided = bytes.fromhex(signature)
    except ValueError:
        raise ValueError('invalid signature')
    if len(provided) != 32:
        raise ValueError('invalid signature')
    expected = hmac.new(signing_key, payload.encode('utf-8'), hashlib.sha256).digest()
    if not hmac.compare_digest(provided, expected):
        raise ValueError('invalid signature')
    try:
        posting = json.loads(payload)
    except (TypeError, ValueError, UnicodeError):
        raise ValueError('invalid posting')
    if not isinstance(posting, dict) or set(posting) != {'title', 'department', 'description'}:
        raise ValueError('invalid posting')
    if not all((isinstance(posting[name], str) for name in posting)):
        raise ValueError('invalid posting')
    if not posting['title'] or not posting['department']:
        raise ValueError('invalid posting')
    return posting

