def parse_submissions(text: str) -> list[dict[str, object]]:
    result = []
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields = []
        current = []
        escaped = False
        for char in raw:
            if escaped:
                current.append(char)
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == '|':
                fields.append(''.join(current))
                current = []
            else:
                current.append(char)
        if escaped:
            raise ValueError('malformed record')
        fields.append(''.join(current))
        if len(fields) != 4 or not fields[0] or (not fields[1]):
            raise ValueError('malformed record')
        try:
            score = int(fields[2], 10)
            datetime.fromisoformat(fields[3])
        except Exception as exc:
            raise ValueError('malformed record') from exc
        if not 0 <= score <= 100:
            raise ValueError('malformed record')
        result.append({'student_id': fields[0], 'assignment': fields[1], 'score': score, 'timestamp': fields[3]})
    return result

def summarize_grades(submissions: list[dict[str, object]], weights: dict[str, float]) -> list[dict[str, object]]:
    if not weights or any((not isinstance(v, (int, float)) or v <= 0 for v in weights.values())):
        raise ValueError('invalid weights')
    chosen = {}
    for index, record in enumerate(submissions):
        try:
            student = record['student_id']
            assignment = record['assignment']
            score = record['score']
            stamp = record['timestamp']
            parsed = datetime.fromisoformat(stamp)
            if not isinstance(student, str) or not isinstance(assignment, str) or (not isinstance(score, int)) or (not 0 <= score <= 100) or (assignment not in weights):
                raise ValueError
        except Exception as exc:
            raise ValueError('invalid submission') from exc
        key = (student, assignment)
        if key not in chosen or (parsed, index) >= chosen[key][0]:
            chosen[key] = ((parsed, index), score)
    grouped = {}
    for (student, assignment), (_, score) in chosen.items():
        grouped.setdefault(student, {})[assignment] = score
    output = []
    for student, assignments in grouped.items():
        total = sum((assignments[a] * weights[a] for a in assignments))
        divisor = sum((weights[a] for a in assignments))
        average = round(total / divisor, 2)
        output.append({'student_id': student, 'average': average, 'passed': average >= 60, 'assignments': sorted(assignments)})
    return sorted(output, key=lambda item: (-item['average'], item['student_id']))

