import hmac
import json

def verify_and_distribute(payload: str, signature: str, key: bytes) -> list[dict]:
    try:
        provided = bytes.fromhex(signature)
    except ValueError:
        return []
    expected = hmac.new(key, payload.encode('utf-8'), hashlib.sha256).digest()
    if len(provided) != len(expected) or not hmac.compare_digest(provided, expected):
        return []
    try:
        data = json.loads(payload)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(data, dict) or not isinstance(data.get('payments'), list):
        raise ValueError('invalid payments')
    totals = {}
    for payment in data['payments']:
        if not isinstance(payment, dict):
            raise ValueError('invalid payment')
        merchant = payment.get('merchant')
        amount = payment.get('amount_cents')
        currency = payment.get('currency')
        status = payment.get('status')
        if not isinstance(merchant, str) or not merchant or isinstance(amount, bool) or (not isinstance(amount, int)) or (amount <= 0) or (not isinstance(currency, str)) or (not isinstance(status, str)):
            raise ValueError('invalid payment')
        if currency == 'USD' and status == 'captured':
            totals[merchant] = totals.get(merchant, 0) + amount
    result = []
    for merchant in sorted(totals):
