        raise ValueError('demand')
    eligible = [c for c in certificates if c.get('technology') == demand['technology'] and c.get('vintage', 0) >= demand['min_vintage'] and (c.get('available_mwh', 0) > 0)]
    eligible.sort(key=lambda c: (c['vintage'], c['certificate_id']))
    if sum((c['available_mwh'] for c in eligible)) < demand['mwh']:
        raise ValueError('insufficient')
    left = demand['mwh']
    plan = []
    for c in eligible:
        if c['tenant_id'] != requester['tenant_id'] and 'market_operator' not in requester['roles']:
            continue
        if c['owner_id'] != requester['id'] and 'market_operator' not in requester['roles']:
            continue
        n = min(left, c['available_mwh'])
        plan.append((c, n))
        left -= n
        if not left:
            break
    if left:
        raise ValueError('insufficient')
    out = []
    for c, n in plan:
        c['available_mwh'] -= n
        item = {'certificate_id': c['certificate_id'], 'mwh': n, 'technology': c['technology'], 'vintage': c['vintage'], 'tenant_id': c['tenant_id']}
        out.append(item)
        ledger.append({'certificate_id': c['certificate_id'], 'buyer_id': requester['id'], 'tenant_id': c['tenant_id'], 'mwh': n, 'vintage': c['vintage']})
    return out

