    result = {}
    for c in certificates:
        if not all((k in c for k in ('technology', 'vintage', 'available_mwh'))):
            raise ValueError('record')
        t = c['technology']
        if t not in result:
            result[t] = {'certificate_count': 0, 'total_mwh': 0, 'earliest_vintage': c['vintage']}
        result[t]['certificate_count'] += 1
        result[t]['total_mwh'] += c['available_mwh']
        result[t]['earliest_vintage'] = min(result[t]['earliest_vintage'], c['vintage'])
    return {k: result[k] for k in sorted(result)}

