def _eval(node, env):
    if isinstance(node, ast.Expression):
        return _eval(node.body, env)
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, complex)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in env:
            raise ValueError('unknown name')
        return env[node.id]
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
        value = _eval(node.operand, env)
        return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
    if isinstance(node, ast.BinOp) and type(node.op) in {ast.Add, ast.Sub, ast.Mult, ast.Div}:
        a, b = (_eval(node.left, env), _eval(node.right, env))
        return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](a, b)
    if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
        value = _eval(node.values[0], env)
        for part in node.values[1:]:
            if isinstance(node.op, ast.And):
                if not value:
                    return value
            elif value:
                return value
            value = _eval(part, env)
        return value
    if isinstance(node, ast.Compare):
        left = _eval(node.left, env)
        ops = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}
        for op, part in zip(node.ops, node.comparators):
            right = _eval(part, env)
            if type(op) not in ops or not ops[type(op)](left, right):
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max', 'round'}) and (not node.keywords):
        args = [_eval(x, env) for x in node.args]
        if node.func.id == 'round' and len(args) not in (1, 2):
            raise ValueError('bad arguments')
        if node.func.id != 'round' and len(args) < 2:
            raise ValueError('bad arguments')
        return {'min': min, 'max': max, 'round': round}[node.func.id](*args)
    raise ValueError('unsupported expression')

def _expression(text, env):
    try:
        return _eval(ast.parse(text, mode='eval'), env)
    except ValueError:
        raise
    except Exception as exc:
        raise ValueError('invalid expression') from exc

