            value = _expression(score, env)
            result.append({'name': record['name'], 'species': record['species'], 'stock': record['stock'], 'price': record['price'], 'score': value, 'reorder': record['stock'] < variables['reorder_level']})
    result.sort(key=lambda x: (-x['score'], x['stock'], x['name']))
    return result

