import base64
import hashlib
import hmac
import os

def create_credential(password: str) -> str:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    if not password:
        raise ValueError('password must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return '1$' + base64.b64encode(salt).decode() + '$' + base64.b64encode(digest).decode()

def verify_credential(password: str, stored: str) -> bool:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    if not isinstance(stored, str):
        return False
    try:
        version, salt_text, digest_text = stored.split('$')
        if version != '1':
            return False
        salt = base64.b64decode(salt_text.encode(), validate=True)
        expected = base64.b64decode(digest_text.encode(), validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def renewal_report(records: list[dict], page: int=1, page_size: int=10) -> dict:
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('invalid page size')
    selected = []
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        required = {'candidate', 'certification', 'due_days', 'completed', 'score'}
        if set(record) != required:
            raise ValueError('invalid record')
        if not isinstance(record['candidate'], str) or not record['candidate'] or (not isinstance(record['certification'], str)) or (not record['certification']) or isinstance(record['due_days'], bool) or (not isinstance(record['due_days'], int)) or (not 0 <= record['due_days'] <= 365) or (not isinstance(record['completed'], bool)) or isinstance(record['score'], bool) or (not isinstance(record['score'], (int, float))) or (not 0 <= record['score'] <= 100):
            raise ValueError('invalid record')
        if not record['completed'] and record['due_days'] <= 30:
            selected.append(dict(record))
    selected.sort(key=lambda x: (x['due_days'], -x['score'], x['candidate'], x['certification']))
    total = len(selected)
    start = (page - 1) * page_size
    pages = (total + page_size - 1) // page_size if total else 0
    average = round(sum((x['score'] for x in selected)) / total, 2) if total else 0.0
    return {'total': total, 'page': page, 'page_size': page_size, 'pages': pages, 'average_score': average, 'items': selected[start:start + page_size]}

