import hashlib
import hmac
import os

def hash_pin(pin: str) -> str:
    if not isinstance(pin, str):
        raise TypeError('pin must be a string')
    salt = os.urandom(16)
    rounds = 100000
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, rounds)
    return f'{rounds}${salt.hex()}${digest.hex()}'

def verify_pin(stored: str, pin: str) -> bool:
    if not isinstance(stored, str) or not isinstance(pin, str):
        return False
    try:
        rounds_text, salt_text, digest_text = stored.split('$', 2)
        rounds = int(rounds_text)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, rounds)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def build_unit(bed_ids: list[str], coordinator_pin: str) -> dict:
    if not isinstance(coordinator_pin, str) or not coordinator_pin:
        raise ValueError('invalid coordinator pin')
    if any((not isinstance(x, str) or not x for x in bed_ids)):
        raise ValueError('invalid bed')
    if len(set(bed_ids)) != len(bed_ids):
        raise ValueError('duplicate bed')
    return {'beds': {x: None for x in bed_ids}, 'patients': {}, 'pin_hash': hash_pin(coordinator_pin)}

def schedule_admissions(unit: dict, requests: list[dict], coordinator_pin: str) -> list[dict]:
    if not verify_pin(unit['pin_hash'], coordinator_pin):
        raise PermissionError('invalid coordinator pin')
    seen = set()
    checked = []
    for index, item in enumerate(requests):
        if not isinstance(item, dict) or not isinstance(item.get('patient_id'), str) or (not item.get('patient_id')):
            raise ValueError('invalid patient')
        patient = item['patient_id']
        acuity = item.get('acuity')
        if type(acuity) is not int or not 1 <= acuity <= 5:
            raise ValueError('invalid acuity')
        if patient in seen or patient in unit['patients']:
            raise ValueError('duplicate patient')
        seen.add(patient)
        preferred = item.get('preferred_bed')
        if preferred is not None and (not isinstance(preferred, str) or preferred not in unit['beds']):
            raise ValueError('invalid preferred bed')
        checked.append((index, patient, acuity, preferred))
    free = {bed for bed, occupant in unit['beds'].items() if occupant is None}
    assignments = {}
    for _, patient, acuity, preferred in sorted(checked, key=lambda x: (-x[2], x[0])):
        bed = preferred if preferred in free else min(free) if free else None
        if bed is None:
            raise ValueError('not enough beds')
        free.remove(bed)
        assignments[patient] = bed
    result = []
    for _, patient, acuity, _ in checked:
        bed = assignments[patient]
        result.append({'patient_id': patient, 'acuity': acuity, 'bed': bed})
    for item in result:
        unit['patients'][item['patient_id']] = item['bed']
        unit['beds'][item['bed']] = item['patient_id']
    return result

def discharge_patient(unit: dict, patient_id: str, coordinator_pin: str) -> str:
    if not verify_pin(unit['pin_hash'], coordinator_pin):
        raise PermissionError('invalid coordinator pin')
    if patient_id not in unit['patients']:
        raise KeyError(patient_id)
    bed = unit['patients'].pop(patient_id)
    unit['beds'][bed] = None
    return bed

