from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from datetime import date
from xml.etree import ElementTree

def summarize_matter_billing(xml_text: str, start_date: str | None=None, end_date: str | None=None, page: int=1, page_size: int=10) -> list[dict]:

    def parsed_date(value):
        try:
            return date.fromisoformat(value)
        except (TypeError, ValueError):
            raise ValueError('invalid date')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    first = parsed_date(start_date) if start_date is not None else None
    last = parsed_date(end_date) if end_date is not None else None
    if first is not None and last is not None and (first > last):
        raise ValueError('invalid range')
    try:
        root = ElementTree.fromstring(xml_text)
    except Exception as exc:
        raise ValueError('invalid xml') from exc
    if root.tag != 'billing':
        raise ValueError('invalid root')
    groups = {}
    for node in root:
        if node.tag != 'entry':
            raise ValueError('invalid entry')
        try:
            matter = node.attrib['matter']
            raw_date = node.attrib['date']
            if not matter:
                raise ValueError
            current = parsed_date(raw_date)
            hours = Decimal(node.attrib['hours'])
            rate = Decimal(node.attrib['rate'])
            if hours < 0 or rate < 0:
                raise ValueError
        except (KeyError, InvalidOperation, ValueError):
            raise ValueError('invalid entry')
        if first is not None and current < first or (last is not None and current > last):
            continue
        groups.setdefault(matter, []).append((current, hours, rate))
    result = []
    quant = Decimal('0.01')
    for matter in sorted(groups):
        rows = groups[matter]
        dates = [row[0] for row in rows]
        total_hours = sum((row[1] for row in rows), Decimal(0))
        fees = sum((row[1] * row[2] for row in rows), Decimal(0)).quantize(quant, rounding=ROUND_HALF_UP)
        result.append({'matter': matter, 'entries': len(rows), 'hours': f'{total_hours.quantize(quant, rounding=ROUND_HALF_UP):.2f}', 'fees': f'{fees:.2f}', 'first_date': min(dates).isoformat(), 'last_date': max(dates).isoformat()})
    start = (page - 1) * page_size
    return result[start:start + page_size]

