import hmac
import os
from decimal import Decimal, ROUND_HALF_UP

def hash_pin(pin: str) -> str:
    if not isinstance(pin, str):
        raise TypeError('pin must be a string')
    if not pin:
        raise ValueError('pin must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def verify_pin(pin: str, stored: str) -> bool:
    if not isinstance(pin, str) or not isinstance(stored, str):
        return False
    try:
        salt_text, digest_text = stored.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def carbon_report(shipments: list[dict], page: int=1, page_size: int=20) -> list[dict]:
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    groups = {}
    for row in shipments:
        if not isinstance(row, dict) or any((k not in row for k in ('shipment_id', 'carrier', 'status', 'distance_km', 'co2_kg'))):
            raise ValueError('invalid shipment')
        if not isinstance(row['carrier'], str) or not row['carrier'] or (not isinstance(row['status'], str)):
            raise ValueError('invalid shipment')
        if isinstance(row['distance_km'], bool) or not isinstance(row['distance_km'], (int, float)) or row['distance_km'] < 0:
            raise ValueError('invalid shipment')
        if isinstance(row['co2_kg'], bool) or not isinstance(row['co2_kg'], (int, float)) or row['co2_kg'] < 0:
            raise ValueError('invalid shipment')
        if row['status'] == 'delivered':
            item = groups.setdefault(row['carrier'], [0, Decimal('0'), Decimal('0')])
            item[0] += 1
            item[1] += Decimal(str(row['distance_km']))
            item[2] += Decimal(str(row['co2_kg']))
    result = []
    for carrier, (count, distance, co2) in groups.items():
        q = Decimal('0.01')
        result.append({'carrier': carrier, 'shipments': count, 'distance_km': float(distance.quantize(q, rounding=ROUND_HALF_UP)), 'co2_kg': float(co2.quantize(q, rounding=ROUND_HALF_UP)), 'average_co2_kg': float((co2 / count).quantize(q, rounding=ROUND_HALF_UP))})
    result.sort(key=lambda x: (-x['co2_kg'], x['carrier']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

