import json
import os
import tempfile
import yaml

def plan_environment(manifest: str, platform: str) -> list[dict]:
    try:
        data = yaml.safe_load(manifest)
    except Exception as exc:
        raise ValueError('invalid manifest') from exc
    if not isinstance(data, dict) or not isinstance(data.get('base'), list):
        raise ValueError('invalid profiles')
    selected = [data['base']]
    if platform in data:
        if not isinstance(data[platform], list):
            raise ValueError('invalid profile')
        selected.append(data[platform])
    packages = {}
    for profile in selected:
        for item in profile:
            if not isinstance(item, dict) or set(item) - {'name', 'version', 'priority'}:
                raise ValueError('invalid package')
            name = item.get('name')
            version = item.get('version')
            priority = item.get('priority', 0)
            if not isinstance(name, str) or not name or (version is not None and (not isinstance(version, str))) or (not isinstance(priority, int)) or isinstance(priority, bool):
                raise ValueError('invalid package')
            packages[name] = {'name': name, 'version': version, 'priority': priority}
    result = list(packages.values())
    result.sort(key=lambda x: (-x['priority'], x['name'], x['version'] is None, x['version'] or ''))
    return result

def export_plan(manifest: str, platform: str, destination: str) -> str:
    payload = {'platform': platform, 'packages': plan_environment(manifest, platform)}
    text = json.dumps(payload, indent=2) + '\n'
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent, prefix='.plan-')
    try:
        with os.fdopen(fd, 'w', encoding='utf-8') as handle:
            handle.write(text)
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return destination

