import operator

def _evaluate(expression, values):
    tree = ast.parse(expression, mode='eval').body

    def visit(node):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in values:
                raise NameError(node.id)
            return values[node.id]
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
            value = visit(node.operand)
            return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
        if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
            left, right = (visit(node.left), visit(node.right))
            return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
        if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
            result = visit(node.values[0])
            for child in node.values[1:]:
                if isinstance(node.op, ast.And) and (not result):
                    return result
                if isinstance(node.op, ast.Or) and result:
                    return result
                result = visit(child)
            return result
        if isinstance(node, ast.Compare):
            left = visit(node.left)
            for op, child in zip(node.ops, node.comparators):
                right = visit(child)
                if not isinstance(op, (ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE)):
                    raise ValueError('unsupported comparison')
                if not {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
            return {'min': min, 'max': max, 'round': round}[node.func.id](*(visit(arg) for arg in node.args))
        raise ValueError('unsupported expression')
    return visit(tree)

def select_parcels(parcels: list[dict], filter_expr: str, score_expr: str, offset: int=0, limit: int=10) -> list[dict]:
    if offset < 0 or limit <= 0:
        raise ValueError('invalid paging')
    ranked = []
    for position, parcel in enumerate(parcels):
        if _evaluate(filter_expr, parcel):
            score = _evaluate(score_expr, parcel)
            if not isinstance(score, (int, float)) or isinstance(score, bool):
                raise ValueError('score must be numeric')
            ranked.append((score, position, {'id': parcel['id'], 'score': score}))
    ranked.sort(key=lambda item: (-item[0], item[1]))
    return [item[2] for item in ranked[offset:offset + limit]]

