import hashlib
import hmac
import json

def canonical_job(job: dict) -> bytes:
    return json.dumps(job, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode('utf-8')

def sign_job(job: dict, secret: bytes) -> str:
    return hmac.new(secret, canonical_job(job), hashlib.sha256).hexdigest()

def _validate(job):
    required = {'id', 'priority', 'material', 'duration', 'created', 'depends'}
    if set(job) != required:
        raise ValueError('invalid job')
    if not isinstance(job['id'], str) or not job['id']:
        raise ValueError('invalid job')
    if isinstance(job['priority'], bool) or not isinstance(job['priority'], int) or (not 0 <= job['priority'] <= 100):
        raise ValueError('invalid job')
    if not isinstance(job['material'], str) or not job['material']:
        raise ValueError('invalid job')
    if isinstance(job['duration'], bool) or not isinstance(job['duration'], int) or job['duration'] <= 0:
        raise ValueError('invalid job')
    if isinstance(job['created'], bool) or not isinstance(job['created'], int):
        raise ValueError('invalid job')
    if not isinstance(job['depends'], list) or any((not isinstance(x, str) or not x for x in job['depends'])):
        raise ValueError('invalid job')
    if len(set(job['depends'])) != len(job['depends']):
        raise ValueError('invalid job')
    if job['id'] in job['depends']:
        raise ValueError('invalid job')

def process_queue(text: str, secret: bytes) -> list[dict]:
    lines = text.splitlines()
    if not lines or lines[0] != 'QUEUE/1':
        raise ValueError('invalid header')
    jobs = []
    ids = set()
    for raw in lines[1:]:
        if not raw.strip():
            continue
        if '\t' not in raw:
            raise ValueError('invalid record')
        encoded, signature = raw.rsplit('\t', 1)
        try:
            job = json.loads(encoded)
        except Exception as exc:
            raise ValueError('invalid json') from exc
        if not isinstance(job, dict):
            raise ValueError('invalid job')
        _validate(job)
        if job['id'] in ids or not isinstance(signature, str) or len(signature) != 64:
            raise ValueError('invalid signature')
        try:
            given = bytes.fromhex(signature)
        except ValueError as exc:
            raise ValueError('invalid signature') from exc
        expected = hmac.new(secret, canonical_job(job), hashlib.sha256).digest()
        if not hmac.compare_digest(given, expected):
            raise ValueError('invalid signature')
        ids.add(job['id'])
        jobs.append(job)
    by_id = {j['id']: j for j in jobs}
    if any((dep not in by_id for j in jobs for dep in j['depends'])):
        raise ValueError('unknown dependency')
    done = set()
    result = []
    while len(result) < len(jobs):
        ready = [j for j in jobs if j['id'] not in done and all((x in done for x in j['depends']))]
        if not ready:
            raise ValueError('dependency cycle')
        ready.sort(key=lambda j: (-j['priority'], j['created'], j['id']))
        chosen = ready[0]
        result.append(chosen)
        done.add(chosen['id'])
    return result

