import hashlib
import hmac
import json
import pytest

from solution import calculate_dispatch


def signed(data, secret=b"route-key"):
    payload = json.dumps(data, separators=(",", ":"), ensure_ascii=False)
    digest = hmac.new(secret, payload.encode(), hashlib.sha256).hexdigest()
    return payload, "sha256=" + digest


def test_empty_plan_and_bus_order():
    payload, auth = signed({"stops": [], "buses": []})
    assert calculate_dispatch(payload, auth, b"route-key") == []

    data = {"stops": [], "buses": [
        {"id": "bus-10", "capacity": 4, "zones": ["north"]},
        {"id": "bus-2", "capacity": 4, "zones": ["north"]},
    ]}
    payload, auth = signed(data)
    assert calculate_dispatch(payload, auth, b"route-key") == [
        {"id": "bus-10", "stops": []}, {"id": "bus-2", "stops": []}
    ]


def test_assignment_and_route_tie_breaks():
    data = {
        "stops": [
            {"id": "c", "zone": "z", "minutes": 2, "priority": 1, "window": [40, 80]},
            {"id": "a", "zone": "z", "minutes": 3, "priority": 1, "window": [10, 80]},
            {"id": "b", "zone": "z", "minutes": 1, "priority": 5, "window": [10, 80]},
        ],
        "buses": [
            {"id": "B", "capacity": 3, "zones": ["z"]},
            {"id": "A", "capacity": 5, "zones": ["z"]},
        ],
    }
    payload, auth = signed(data)
    assert calculate_dispatch(payload, auth, b"route-key") == [
        {"id": "A", "stops": ["b", "a"]}, {"id": "B", "stops": ["c"]}
    ]


def test_zone_and_capacity_choose_first_eligible_bus():
    data = {
        "stops": [
            {"id": "x", "zone": "west", "minutes": 4, "priority": 0, "window": [0, 1]},
            {"id": "y", "zone": "east", "minutes": 2, "priority": 0, "window": [0, 1]},
        ],
        "buses": [
            {"id": "a", "capacity": 3, "zones": ["east", "west"]},
            {"id": "b", "capacity": 4, "zones": ["west"]},
        ],
    }
    payload, auth = signed(data)
    assert calculate_dispatch(payload, auth, b"route-key") == [
        {"id": "a", "stops": ["y"]}, {"id": "b", "stops": ["x"]}
    ]


