    data = {"stops": [], "buses": []}
    payload, auth = signed(data)
    for value in [auth[:-1] + ("0" if auth[-1] != "0" else "1"), auth.upper(), auth[7:], "sha256=" + "0" * 64]:
        with pytest.raises(ValueError):
            calculate_dispatch(payload, value, b"route-key")


