from solution import summarize_receipts
import hashlib
import hmac


def sig(key, message_id, recipient, status, timestamp):
    text = f"{message_id}|{recipient}|{status}|{timestamp}".encode()
    return hmac.new(key.encode(), text, hashlib.sha256).hexdigest()


def test_empty_input():
    result = summarize_receipts([], {"signing_key": "alpha"})
    assert result == {
        "total": 0,
        "page": 1,
        "page_size": 20,
        "receipts": [],
    }


def test_latest_receipt_and_signature():
    result = summarize_receipts([
        {"message_id": "m1", "recipient": "a@example.com", "status": "deferred", "timestamp": "2024-01-01T10:00:00Z"},
        {"message_id": "m1", "recipient": "a@example.com", "status": "delivered", "timestamp": "2024-01-01T11:00:00+01:00"},
        {"message_id": "m2", "recipient": "b@example.com", "status": "bounced", "timestamp": "2024-01-01T12:00:00Z"},
    ], {"signing_key": "alpha"})
    assert result["total"] == 2
    assert result["receipts"] == [
        {
            "message_id": "m2",
            "recipient": "b@example.com",
            "status": "bounced",
            "timestamp": "2024-01-01T12:00:00Z",
            "signature": sig("alpha", "m2", "b@example.com", "bounced", "2024-01-01T12:00:00Z"),
        },
        {
            "message_id": "m1",
            "recipient": "a@example.com",
            "status": "delivered",
            "timestamp": "2024-01-01T10:00:00Z",
            "signature": sig("alpha", "m1", "a@example.com", "delivered", "2024-01-01T10:00:00Z"),
        },
    ]


def test_tie_uses_later_input():
    rows = [
        {"message_id": "x", "recipient": "old", "status": "deferred", "timestamp": "2024-02-01T00:00:00Z"},
        {"message_id": "x", "recipient": "new", "status": "delivered", "timestamp": "2024-02-01T00:00:00+00:00"},
    ]
    result = summarize_receipts(rows, {"signing_key": "k"})
    assert result["receipts"][0]["recipient"] == "new"
    assert result["receipts"][0]["status"] == "delivered"


def test_sort_ties_by_message_id():
    rows = [
        {"message_id": "z", "recipient": "z", "status": "delivered", "timestamp": "2024-03-01T00:00:00Z"},
        {"message_id": "a", "recipient": "a", "status": "delivered", "timestamp": "2024-03-01T00:00:00Z"},
    ]
    result = summarize_receipts(rows, {"signing_key": "k"})
    assert [x["message_id"] for x in result["receipts"]] == ["a", "z"]


def test_pagination_boundaries():
    rows = [
        {"message_id": str(i), "recipient": str(i), "status": "delivered", "timestamp": f"2024-01-0{i + 1}T00:00:00Z"}
        for i in range(5)
    ]
    first = summarize_receipts(rows, {"signing_key": "k"}, page=1, page_size=2)
    second = summarize_receipts(rows, {"signing_key": "k"}, page=2, page_size=2)
    beyond = summarize_receipts(rows, {"signing_key": "k"}, page=4, page_size=2)
    assert first["total"] == 5
    assert [x["message_id"] for x in first["receipts"]] == ["4", "3"]
    assert [x["message_id"] for x in second["receipts"]] == ["2", "1"]
    assert beyond["receipts"] == []


def test_invalid_page_arguments():
    for kwargs in ({"page": 0}, {"page": True}, {"page_size": 0}, {"page_size": 101}, {"page_size": False}):
        try:
            summarize_receipts([], {"signing_key": "k"}, **kwargs)
            assert False
        except ValueError:
            pass


def test_invalid_receipts_raise_value_error():
    cases = [
        {},
        {"message_id": "m", "recipient": "r", "status": "sent", "timestamp": "2024-01-01T00:00:00Z"},
        {"message_id": "m", "recipient": "r", "status": "delivered", "timestamp": "not-a-date"},
        {"message_id": "m", "recipient": "r", "status": "delivered", "timestamp": "2024-01-01T00:00:00"},
        {"message_id": "", "recipient": "r", "status": "delivered", "timestamp": "2024-01-01T00:00:00Z"},
    ]
    for row in cases:
        try:
            summarize_receipts([row], {"signing_key": "k"})
            assert False
        except ValueError:
            pass


def test_signature_changes_with_configured_key():
    row = {"message_id": "m", "recipient": "r", "status": "delivered", "timestamp": "2024-01-01T00:00:00Z"}
    a = summarize_receipts([row], {"signing_key": "one"})["receipts"][0]["signature"]
    b = summarize_receipts([row], {"signing_key": "two"})["receipts"][0]["signature"]
    assert a != b

