            raise ValueError('invalid receipt')
        if not all((k in row for k in ('message_id', 'recipient', 'status', 'timestamp'))):
            raise ValueError('invalid receipt')
        if not isinstance(row['message_id'], str) or not row['message_id']:
            raise ValueError('invalid message_id')
        if not isinstance(row['recipient'], str) or not row['recipient']:
            raise ValueError('invalid recipient')
        if row['status'] not in {'delivered', 'bounced', 'deferred'}:
            raise ValueError('invalid status')
