            text = row['timestamp']
            parsed = datetime.fromisoformat(text.replace('Z', '+00:00'))
        except (AttributeError, TypeError, ValueError):
            raise ValueError('invalid timestamp')
        if parsed.tzinfo is None:
            raise ValueError('timestamp must include timezone')
        normalized = parsed.astimezone(timezone.utc).replace(microsecond=0).isoformat().replace('+00:00', 'Z')
        item = (parsed.timestamp(), {'message_id': row['message_id'], 'recipient': row['recipient'], 'status': row['status'], 'timestamp': normalized})
        if row['message_id'] not in latest or item[0] >= latest[row['message_id']][0]:
            latest[row['message_id']] = item
    ordered = sorted((x[1] for x in latest.values()), key=lambda x: (-datetime.fromisoformat(x['timestamp'].replace('Z', '+00:00')).timestamp(), x['message_id']))
