        patient_id = record['patient_id']
        ward = record['ward']
        priority = record['priority']
        arrival = record['arrival']
        if not isinstance(patient_id, str) or not patient_id or (not isinstance(ward, str)) or (not ward):
            raise ValueError('invalid record')
        if type(priority) is not int or not 1 <= priority <= 5:
            raise ValueError('invalid record')
        if not isinstance(arrival, str):
            raise ValueError('invalid record')
        try:
            parsed = datetime.datetime.fromisoformat(arrival)
        except ValueError:
            raise ValueError('invalid record')
        if patient_id in seen:
            raise ValueError('duplicate patient_id')
        seen.add(patient_id)
        normalized.append((patient_id, ward, priority, arrival, parsed))
