import secrets
_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'

def generate_invite_code(length: int=12) -> str:
    if type(length) is not int or not 6 <= length <= 32:
        raise ValueError('invalid length')
    return ''.join((secrets.choice(_ALPHABET) for _ in range(length)))

def resolve_memberships(events: list[dict], now: int) -> dict[str, dict[str, str]]:
    if type(now) is not int:
        raise ValueError('invalid now')
    prepared = []
    for index, event in enumerate(events):
        if not isinstance(event, dict):
            raise ValueError('invalid event')
        required = {'user', 'group', 'action', 'at', 'seq'}
        if not required.issubset(event):
            raise ValueError('missing field')
        user, group, action = (event['user'], event['group'], event['action'])
        if not isinstance(user, str) or not user or (not isinstance(group, str)) or (not group):
            raise ValueError('invalid name')
        if action not in ('add', 'remove') or type(event['at']) is not int or type(event['seq']) is not int:
            raise ValueError('invalid event')
        allowed = required | ({'role', 'expires'} if action == 'add' else set())
        if set(event) - allowed:
            raise ValueError('unexpected field')
        if action == 'add':
            if event.get('role') not in ('member', 'admin'):
                raise ValueError('invalid role')
            if 'expires' in event and (type(event['expires']) is not int or event['expires'] <= event['at']):
                raise ValueError('invalid expiration')
        prepared.append((event['at'], event['seq'], index, event))
    state = {}
    for _, _, _, event in sorted(prepared, key=lambda x: (x[0], x[1], x[2])):
        key = (event['group'], event['user'])
        if event['action'] == 'remove':
            state.pop(key, None)
        else:
            state[key] = (event['role'], event.get('expires'))
    result = {}
    for (group, user), (role, expires) in sorted(state.items()):
        if expires is not None and expires <= now:
            continue
        result.setdefault(group, {})[user] = role
    return result

