import csv
import os
import re
import tempfile
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def build_royalty_statement(records: list[dict], period: str, page: int=1, page_size: int=50) -> str:
    if not isinstance(period, str) or re.fullmatch('\\d{4}-(0[1-9]|1[0-2])', period) is None:
        raise ValueError('invalid period')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 1000):
        raise ValueError('invalid page size')
    grouped = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        try:
            record_period = record['period']
            artist = record['artist']
            track = record['track']
            streams = record['streams']
            raw_rate = record['rate']
        except (KeyError, TypeError):
            raise ValueError('invalid record')
        if not isinstance(record_period, str) or not isinstance(artist, str) or (not isinstance(track, str)) or (not artist) or (not track):
            raise ValueError('invalid record')
        if isinstance(streams, bool) or not isinstance(streams, int) or streams < 0:
            raise ValueError('invalid streams')
        try:
            rate = Decimal(str(raw_rate))
        except (InvalidOperation, ValueError, TypeError):
            raise ValueError('invalid rate')
        if not rate.is_finite() or rate < 0:
            raise ValueError('invalid rate')
        if record_period == period:
            key = (artist, track)
            if key not in grouped:
                grouped[key] = [0, Decimal('0')]
            grouped[key][0] += streams
            grouped[key][1] += Decimal(streams) * rate
    rows = []
    for (artist, track), (streams, payout) in grouped.items():
        amount = payout.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        rows.append((artist, track, streams, amount))
    rows.sort(key=lambda row: (-row[3], row[0], row[1]))
    start = (page - 1) * page_size
    selected = rows[start:start + page_size]
    fd, path = tempfile.mkstemp()
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['artist', 'track', 'streams', 'payout'])
            for artist, track, streams, payout in selected:
                writer.writerow([artist, track, streams, format(payout, '.2f')])
        with open(path, 'r', newline='', encoding='utf-8') as handle:
            return handle.read()
    finally:
        try:
            os.unlink(path)
        except FileNotFoundError:
            pass

