    records = [{'reservation_id': '1', 'equipment': 'incubator', 'researcher': 'x', 'start': '2025-02-01T08:00:59Z', 'end': '2025-02-01T08:10:01Z', 'status': 'confirmed'}, {'reservation_id': '2', 'equipment': 'incubator', 'researcher': 'y', 'start': '2025-02-01T08:10:00Z', 'end': '2025-02-01T08:20:59Z', 'status': 'confirmed'}, {'reservation_id': '3', 'equipment': 'incubator', 'researcher': 'z', 'start': '2025-02-01T09:00:59Z', 'end': '2025-02-01T09:02:00Z', 'status': 'confirmed'}]
    with tempfile.TemporaryDirectory() as d:
        result = export_reservations(records, os.path.join(d, 'x.csv'))
    assert result['minutes'] == 22
    assert result['equipment'] == {'incubator': 22}

def test_quotes_csv_fields_and_normalizes_fractional_timestamps():
    record = {'reservation_id': 'r,1', 'equipment': 'freezer', 'researcher': 'Lee "L"', 'start': '2025-03-01T01:02:03.999Z', 'end': '2025-03-01T01:04:59.100Z', 'status': 'confirmed'}
    with tempfile.TemporaryDirectory() as d:
        path = os.path.join(d, 'x.csv')
        assert export_reservations([record], path)['minutes'] == 2
        with open(path, encoding='utf-8', newline='') as f:
            text = f.read()
    assert '"r,1",freezer,"Lee ""L""",2025-03-01T01:02:03Z,2025-03-01T01:04:59Z,confirmed\n' in text

