import ast
import operator

def filter_containers(containers: list[dict[str, object]], expression: str) -> list[dict[str, object]]:
    tree = ast.parse(expression, mode='eval').body

    def visit(node, values):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in values:
                raise NameError(node.id)
            return values[node.id]
        if isinstance(node, ast.BinOp):
            ops = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
            if type(node.op) not in ops:
                raise ValueError('unsupported operator')
            return ops[type(node.op)](visit(node.left, values), visit(node.right, values))
        if isinstance(node, ast.UnaryOp):
            if isinstance(node.op, ast.Not):
                return not visit(node.operand, values)
            if isinstance(node.op, ast.UAdd):
                return +visit(node.operand, values)
            if isinstance(node.op, ast.USub):
                return -visit(node.operand, values)
        if isinstance(node, ast.BoolOp):
            if isinstance(node.op, ast.And):
                result = True
                for item in node.values:
                    result = visit(item, values)
                    if not result:
                        return result
                return result
            result = False
            for item in node.values:
                result = visit(item, values)
                if result:
                    return result
            return result
        if isinstance(node, ast.Compare):
            left = visit(node.left, values)
            checks = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}
            for op, part in zip(node.ops, node.comparators):
                right = visit(part, values)
                if type(op) not in checks or not checks[type(op)](left, right):
                    return False
                left = right
            return True
        raise ValueError('unsupported expression')
    return [record for record in containers if visit(tree, record)]

import csv
import datetime
import json
import os
import tempfile

def parse_download_log(text: str) -> list[dict]:
    rows = [line for line in text.splitlines() if line.strip()]
    if not rows:
        return []
    try:
        reader = csv.reader(rows)
        header = next(reader)
    except Exception as exc:
        raise ValueError('invalid CSV') from exc
    if header != ['timestamp', 'user', 'package', 'version', 'bytes', 'status']:
        raise ValueError('invalid header')
    result = []
    for number, row in enumerate(reader, 2):
        if len(row) != 6:
            raise ValueError(f'invalid row {number}')
        try:
            stamp = row[0].replace('Z', '+00:00')
            dt = datetime.datetime.fromisoformat(stamp)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            timestamp = int(dt.timestamp())
            size = int(row[4])
            if size < 0:
                raise ValueError
        except (ValueError, OverflowError):
            raise ValueError(f'invalid row {number}')
        result.append({'timestamp': timestamp, 'user': row[1], 'package': row[2], 'version': row[3], 'bytes': size, 'status': row[5]})
    return result

def build_report(events: list[dict], window_seconds: int=3600) -> list[dict]:
    if not isinstance(window_seconds, int) or isinstance(window_seconds, bool) or window_seconds <= 0:
        raise ValueError('invalid window')
    groups = {}
    required = ('timestamp', 'user', 'package', 'version', 'bytes', 'status')
    for event in events:
        if any((key not in event for key in required)):
            raise ValueError('missing event field')
        timestamp, size = (event['timestamp'], event['bytes'])
        if not isinstance(timestamp, int) or isinstance(timestamp, bool) or (not isinstance(size, int)) or isinstance(size, bool) or (size < 0):
            raise ValueError('invalid event value')
        if event['status'] != 'ok':
            continue
        key = (timestamp // window_seconds * window_seconds, event['package'], event['version'])
        if key not in groups:
            groups[key] = [0, set(), 0]
        groups[key][0] += 1
        groups[key][1].add(event['user'])
        groups[key][2] += size
    result = []
    for (start, package, version), (count, users, total) in sorted(groups.items()):
        result.append({'window_start': start, 'package': package, 'version': version, 'downloads': count, 'users': len(users), 'bytes': total})
    return result

def export_report(events: list[dict], destination: str, window_seconds: int=3600) -> list[dict]:
    report = build_report(events, window_seconds)
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(prefix='.report-', dir=parent, text=True)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8') as stream:
            json.dump(report, stream, indent=2, ensure_ascii=False)
            stream.write('\n')
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return report

