import math

def build_batch_report(requester: dict, batches: list[dict], status: str | None=None, page: int=1, page_size: int=20) -> dict:
    if not isinstance(requester, dict) or not isinstance(requester.get('id'), str) or (not isinstance(requester.get('tenant_id'), str)) or (not isinstance(requester.get('roles'), list)) or (not all((isinstance(x, str) for x in requester['roles']))):
        raise ValueError('invalid requester')
    if not isinstance(batches, list) or isinstance(page, bool) or (not isinstance(page, int)) or (page < 1) or isinstance(page_size, bool) or (not isinstance(page_size, int)) or (page_size < 1):
        raise ValueError('invalid arguments')
    if status is not None and (not isinstance(status, str)):
        raise ValueError('invalid status')
    selected = []
    for record in batches:
        if not isinstance(record, dict):
            raise ValueError('invalid batch')
        required = ('batch_id', 'tenant_id', 'owner_id', 'status', 'produced_at', 'measurements')
        if any((not isinstance(record.get(k), str) for k in required[:5])) or not isinstance(record.get('measurements'), list):
            raise ValueError('invalid batch')
        try:
            stamp = record['produced_at'].replace('Z', '+00:00')
            when = datetime.fromisoformat(stamp)
            if when.tzinfo is None:
                when = when.replace(tzinfo=timezone.utc)
        except Exception as exc:
            raise ValueError('invalid timestamp') from exc
        measurements = []
        for measurement in record['measurements']:
            if not isinstance(measurement, dict) or not isinstance(measurement.get('mass_kg'), (int, float)) or isinstance(measurement.get('mass_kg'), bool) or (not isinstance(measurement.get('quality_score'), (int, float))) or isinstance(measurement.get('quality_score'), bool):
                raise ValueError('invalid measurement')
            mass = measurement['mass_kg']
            quality = measurement['quality_score']
            if not math.isfinite(mass) or not math.isfinite(quality) or mass < 0 or (quality < 0):
                raise ValueError('invalid measurement')
            measurements.append((mass, quality))
        allowed = record['tenant_id'] == requester['tenant_id'] and (record['owner_id'] == requester['id'] or bool(set(requester['roles']) & {'plant_manager', 'quality_manager'}))
        if allowed and (status is None or record['status'] == status):
            selected.append((record, when, measurements))
    selected.sort(key=lambda x: (-x[1].timestamp(), x[0]['batch_id']))
    start = (page - 1) * page_size
    items = []
    for record, _, measurements in selected[start:start + page_size]:
        total = sum((x[0] for x in measurements))
        average = sum((x[1] for x in measurements)) / len(measurements) if measurements else None
        items.append({'batch_id': record['batch_id'], 'status': record['status'], 'measurement_count': len(measurements), 'total_mass_kg': round(total, 2), 'average_quality': None if average is None else round(average, 2)})
    return {'total': len(selected), 'page': page, 'page_size': page_size, 'items': items}

