def _inside(base, name):
    root = os.path.realpath(base)
    path = os.path.realpath(os.path.join(root, name))
    if os.path.commonpath([root, path]) != root:
        raise ValueError('invalid path')
    return path

def extract_question_bank(archive_path: str, base_dir: str) -> list[str]:
    os.makedirs(base_dir, exist_ok=True)
    seen = set()
    result = []
    with zipfile.ZipFile(archive_path) as archive:
        for info in archive.infolist():
            name = info.filename.replace('\\', '/')
            if name in seen:
                raise ValueError('duplicate archive name')
            seen.add(name)
            target = _inside(base_dir, name)
            if info.is_dir() or name.endswith('/'):
                os.makedirs(target, exist_ok=True)
                continue
            os.makedirs(os.path.dirname(target), exist_ok=True)
            with archive.open(info) as source, open(target, 'wb') as output:
                output.write(source.read())
            if name.endswith('.json'):
                result.append(name)
    return sorted(result)

def read_question(base_dir: str, relative_name: str) -> dict:
    path = _inside(base_dir, relative_name)
    try:
        if not os.path.isfile(path):
            raise ValueError('not a file')
        with open(path, encoding='utf-8') as f:
            value = json.load(f)
    except (OSError, json.JSONDecodeError, TypeError):
        raise ValueError('invalid question')
    keys = {'id', 'topic', 'difficulty', 'marks', 'prompt', 'choices', 'answer'}
    if not isinstance(value, dict) or set(value) != keys:
        raise ValueError('invalid question')
    if any((not isinstance(value[k], str) or not value[k] for k in ('id', 'topic', 'difficulty', 'prompt'))):
        raise ValueError('invalid question')
    if isinstance(value['marks'], bool) or not isinstance(value['marks'], int) or value['marks'] <= 0:
        raise ValueError('invalid question')
    if not isinstance(value['choices'], list) or len(value['choices']) < 2 or any((not isinstance(x, str) or not x for x in value['choices'])):
        raise ValueError('invalid question')
    if isinstance(value['answer'], bool) or not isinstance(value['answer'], int) or (not 0 <= value['answer'] < len(value['choices'])):
        raise ValueError('invalid question')
    return value

def assemble_exam(base_dir: str, relative_names: list[str], total_marks: int) -> list[dict]:
    if isinstance(total_marks, bool) or not isinstance(total_marks, int) or total_marks < 0:
        raise ValueError('invalid budget')
    questions = [read_question(base_dir, name) for name in relative_names]
    if len({q['id'] for q in questions}) != len(questions):
        raise ValueError('duplicate id')
    ranks = {'easy': 0, 'medium': 1, 'hard': 2}
    for q in questions:
        if q['difficulty'] not in ranks:
            raise ValueError('invalid difficulty')
    questions.sort(key=lambda q: (ranks[q['difficulty']], q['topic'], q['id']))
    result = []
    used = 0
    for q in questions:
        if used + q['marks'] <= total_marks:
            result.append(q)
            used += q['marks']
    return result

