import sqlite3
import time

def query_tasks(conn: sqlite3.Connection, search: str='', states: tuple[str, ...]=(), queue: str | None=None, sort_by: str='priority', descending: bool=False, limit: int=100) -> list[dict]:
    columns = {'priority', 'updated_at', 'attempts', 'id', 'queue', 'state', 'worker'}
    if sort_by not in columns:
        raise ValueError('invalid sort column')
    if isinstance(limit, bool) or not isinstance(limit, int) or limit <= 0:
        raise ValueError('invalid limit')
    args = []
    clauses = []
    if search:
        pattern = '%' + search + '%'
        clauses.append("(lower(payload) like lower(?) or lower(coalesce(worker, '')) like lower(?))")
        args.extend([pattern, pattern])
    if states:
        clauses.append('state in (' + ','.join(('?' for _ in states)) + ')')
        args.extend(states)
    if queue is not None:
        clauses.append('queue = ?')
        args.append(queue)
    where = ' where ' + ' and '.join(clauses) if clauses else ''
    direction = ' desc' if descending else ' asc'
    sql = 'select id, queue, state, priority, worker, payload, updated_at, attempts from tasks' + where + ' order by ' + sort_by + direction + ', id asc limit ?'
    args.append(limit)
    rows = conn.execute(sql, args).fetchall()
    names = ('id', 'queue', 'state', 'priority', 'worker', 'payload', 'updated_at', 'attempts')
    return [dict(zip(names, row)) for row in rows]

def record_attempt(conn: sqlite3.Connection, task_id: int, state: str, error: str | None=None, now: int | None=None) -> int:
    if state not in {'queued', 'running', 'succeeded', 'failed'}:
        raise ValueError('invalid state')
    row = conn.execute('select attempts from tasks where id = ?', (task_id,)).fetchone()
    if row is None:
        raise KeyError(task_id)
    stamp = int(time.time()) if now is None else now
    with conn:
        attempts = row[0] + 1
        conn.execute('update tasks set state = ?, error = ?, updated_at = ?, attempts = ? where id = ?', (state, error, stamp, attempts, task_id))
        conn.execute('insert into task_events values (?, ?, ?, ?)', (task_id, state, error, stamp))
    return attempts

def queue_snapshot(conn: sqlite3.Connection) -> dict[str, object]:
    counts = {row[0]: row[1] for row in conn.execute('select state, count(*) from tasks group by state order by state')}
    workers = {row[0]: row[1] for row in conn.execute('select worker, count(*) from tasks where worker is not null group by worker order by worker')}
    total = conn.execute('select count(*) from tasks').fetchone()[0]
    return {'counts': counts, 'workers': workers, 'total': total}

