def hash_pin(pin: str) -> str:
    if not isinstance(pin, str) or not pin:
        raise ValueError('invalid pin')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return salt.hex() + ':' + digest.hex()

def appraisal_dashboard(records: list[dict], stored_pin: str, supplied_pin: str, page: int=1, page_size: int=10) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError('invalid page size')
    try:
        salt_hex, digest_hex = stored_pin.split(':')
        salt = bytes.fromhex(salt_hex)
        expected = bytes.fromhex(digest_hex)
        actual = hashlib.pbkdf2_hmac('sha256', supplied_pin.encode(), salt, 100000)
    except (AttributeError, ValueError, TypeError):
        raise PermissionError('invalid pin')
    if not hmac.compare_digest(actual, expected):
        raise PermissionError('invalid pin')
    if not isinstance(records, list):
        raise ValueError('invalid records')
    seen = set()
    completed = []
    for record in records:
        if not isinstance(record, dict) or not all((k in record for k in ('order_id', 'appraiser', 'value', 'status'))):
