            raise ValueError('invalid record')
        if order_id in seen or isinstance(value, bool) or (not isinstance(value, (int, float))) or (not math.isfinite(value)) or (value < 0):
            raise ValueError('invalid record')
        if status not in ('pending', 'completed', 'cancelled'):
            raise ValueError('invalid record')
        seen.add(order_id)
