import json
import os
import zipfile
from datetime import datetime, timezone
from pathlib import Path
_ACTIONS = {'cast', 'revoke', 'open', 'close', 'export'}

def _time(value):
    if not isinstance(value, str):
        raise ValueError('invalid timestamp')
    try:
        d = datetime.fromisoformat(value.replace('Z', '+00:00'))
        if d.tzinfo is None:
            raise ValueError
        return d.astimezone(timezone.utc)
    except Exception as e:
        raise ValueError('invalid timestamp') from e

def parse_audit_log(path: str) -> list[dict]:
    records = []
    try:
        with open(path, encoding='utf-8') as f:
            for line in f:
                if not line.strip():
                    continue
                try:
                    item = json.loads(line)
                except Exception as e:
                    raise ValueError('invalid json') from e
                if not isinstance(item, dict) or not all((isinstance(item.get(k), str) and item[k] for k in ('actor', 'precinct', 'action'))) or item.get('action') not in _ACTIONS:
                    raise ValueError('invalid record')
                d = _time(item['timestamp'])
                if 'details' in item and (not isinstance(item['details'], dict)):
                    raise ValueError('invalid details')
                out = {'timestamp': d.isoformat().replace('+00:00', 'Z'), 'actor': item['actor'], 'precinct': item['precinct'], 'action': item['action']}
                if 'details' in item:
                    out['details'] = item['details']
                records.append((d, out))
    except UnicodeDecodeError as e:
        raise ValueError('invalid encoding') from e
    records.sort(key=lambda x: x[0])
    return [x[1] for x in records]

def summarize_events(events: list[dict], window_seconds: int=300) -> dict:
    if isinstance(window_seconds, bool) or not isinstance(window_seconds, int) or window_seconds <= 0:
        raise ValueError('invalid window')
    groups = {}
    for e in events:
        if not isinstance(e, dict) or not isinstance(e.get('precinct'), str) or (not e['precinct']) or (e.get('action') not in _ACTIONS):
            raise ValueError('invalid event')
        d = _time(e.get('timestamp'))
        start = int(d.timestamp()) // window_seconds * window_seconds
        groups.setdefault(start, {}).setdefault(e['precinct'], {}).setdefault(e['action'], 0)
        groups[start][e['precinct']][e['action']] += 1
    result = {}
    for start in sorted(groups):
        result[datetime.fromtimestamp(start, timezone.utc).isoformat().replace('+00:00', 'Z')] = {p: {'total': sum(a.values()), 'actions': {k: a[k] for k in sorted(a)}} for p, a in sorted(groups[start].items())}
    return result

def extract_audit_bundle(archive_path: str, destination: str) -> list[str]:
    base = Path(destination).resolve()
    base.mkdir(parents=True, exist_ok=True)
    result = []
    try:
        with zipfile.ZipFile(archive_path) as z:
            for info in z.infolist():
                target = (base / info.filename).resolve()
                try:
                    target.relative_to(base)
                except ValueError as e:
                    raise ValueError('member outside destination') from e
                if info.is_dir():
                    target.mkdir(parents=True, exist_ok=True)
                else:
                    target.parent.mkdir(parents=True, exist_ok=True)
                    with z.open(info) as src, open(target, 'wb') as dst:
                        dst.write(src.read())
                    result.append(info.filename)
    except zipfile.BadZipFile as e:
        raise ValueError('invalid zip') from e
    return result

