import datetime
import math
import os
import tempfile

def export_volunteer_summary(shifts: list[dict], output_path: str, minimum_hours: float=0.0) -> int:
    if not isinstance(shifts, list) or not isinstance(minimum_hours, (int, float)) or isinstance(minimum_hours, bool) or (not math.isfinite(minimum_hours)) or (minimum_hours < 0):
        raise ValueError('invalid arguments')
    totals = {}
    for item in shifts:
        if not isinstance(item, dict):
            raise ValueError('invalid shift')
        try:
            volunteer = item['volunteer']
            date_text = item['date']
            start_text = item['start']
            end_text = item['end']
            status = item['status']
        except (KeyError, TypeError):
            raise ValueError('invalid shift')
        if not isinstance(volunteer, str) or not volunteer or (not isinstance(date_text, str)) or (not isinstance(start_text, str)) or (not isinstance(end_text, str)) or (status not in ('confirmed', 'cancelled')):
            raise ValueError('invalid shift')
        try:
            date_value = datetime.date.fromisoformat(date_text)
            start = datetime.datetime.strptime(start_text, '%H:%M')
            end = datetime.datetime.strptime(end_text, '%H:%M')
        except (ValueError, TypeError):
            raise ValueError('invalid shift')
        minutes = end.hour * 60 + end.minute - (start.hour * 60 + start.minute)
        if minutes <= 0:
            raise ValueError('invalid shift')
        if status == 'confirmed' and minutes / 60 >= minimum_hours:
            entry = totals.setdefault(volunteer, [0, 0, date_value])
            entry[0] += 1
            entry[1] += minutes
            if date_value < entry[2]:
                entry[2] = date_value
    rows = sorted(totals.items(), key=lambda x: (-x[1][1], x[0]))
    directory = os.path.dirname(os.path.abspath(output_path))
    fd, temporary = tempfile.mkstemp(dir=directory, prefix='festival-', suffix='.csv')
    try:
        with os.fdopen(fd, 'w', newline='') as stream:
            writer = csv.writer(stream, lineterminator='\n')
