import ast

def _value(node, variables):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in variables:
            raise ValueError('unknown variable')
        return variables[node.id]
    if isinstance(node, ast.IfExp):
        return _value(node.body if _value(node.test, variables) else node.orelse, variables)
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
        value = _value(node.operand, variables)
        if isinstance(node.op, ast.UAdd):
            return +value
        if isinstance(node.op, ast.USub):
            return -value
        return not value
    if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
        left, right = (_value(node.left, variables), _value(node.right, variables))
        if isinstance(node.op, ast.Add):
            return left + right
        if isinstance(node.op, ast.Sub):
            return left - right
        if isinstance(node.op, ast.Mult):
            return left * right
        return left / right
    if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
        result = _value(node.values[0], variables)
        for child in node.values[1:]:
            if isinstance(node.op, ast.And):
                if not result:
                    return result
            elif result:
                return result
            result = _value(child, variables)
        return result
    if isinstance(node, ast.Compare):
        left = _value(node.left, variables)
        for op, child in zip(node.ops, node.comparators):
            right = _value(child, variables)
            checks = {ast.Lt: left < right, ast.LtE: left <= right, ast.Eq: left == right, ast.NotEq: left != right, ast.GtE: left >= right, ast.Gt: left > right}
            if type(op) not in checks or not checks[type(op)]:
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
        return {'min': min, 'max': max, 'round': round}[node.func.id](*[_value(x, variables) for x in node.args])
    raise ValueError('invalid expression')

def build_campaign_shortlist(influencers: list[dict], expression: str, threshold: float, page: int, page_size: int) -> dict:
    if not isinstance(page, int) or not isinstance(page_size, int) or page <= 0 or (page_size <= 0):
        raise ValueError('invalid pagination')
    tree = ast.parse(expression, mode='eval').body
    selected = []
    for influencer in influencers:
        variables = {key: influencer[key] for key in ('name', 'followers', 'engagement', 'fee')}
        score = _value(tree, variables)
        if not isinstance(score, (int, float, bool)):
            raise ValueError('non-numeric result')
