import csv
import json
import os
import tempfile
_SEVERITY = {'info': 0, 'watch': 1, 'warning': 2, 'emergency': 3}
_FIELDS = {'id', 'region', 'severity', 'issued', 'expires', 'message'}

def parse_alert_feed(text: str) -> list[dict]:
    try:
        value = json.loads(text)
    except Exception as exc:
        raise ValueError('invalid feed') from exc
    if not isinstance(value, dict) or set(value) != {'alerts'} or (not isinstance(value['alerts'], list)):
        raise ValueError('invalid feed')
    result = []
    seen = set()
    for item in value['alerts']:
        if not isinstance(item, dict) or set(item) != _FIELDS:
            raise ValueError('invalid alert')
        if not isinstance(item['id'], str) or not item['id'] or item['id'] in seen or (not isinstance(item['region'], str)) or (not item['region']) or (not isinstance(item['severity'], str)) or (item['severity'] not in _SEVERITY) or (type(item['issued']) is not int) or (type(item['expires']) is not int) or (item['expires'] <= item['issued']) or (not isinstance(item['message'], str)):
            raise ValueError('invalid alert')
        seen.add(item['id'])
        result.append(dict(item))
    return result

def summarize_alerts(text: str, as_of: int) -> list[dict]:
    alerts = parse_alert_feed(text)
    groups = {}
    for item in alerts:
        if item['issued'] <= as_of < item['expires']:
            groups.setdefault(item['region'], []).append(item)
    output = []
    for region, items in groups.items():
        highest = max(items, key=lambda x: _SEVERITY[x['severity']])['severity']
        ordered = sorted(items, key=lambda x: (-x['issued'], x['id']))
        output.append({'region': region, 'highest_severity': highest, 'count': len(items), 'alert_ids': [x['id'] for x in ordered]})
    return sorted(output, key=lambda x: (-_SEVERITY[x['highest_severity']], x['region']))

def export_alert_digest(text: str, destination: str, as_of: int) -> int:
    rows = summarize_alerts(text, as_of)
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=directory)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as stream:
            writer = csv.writer(stream)
            writer.writerow(['region', 'highest_severity', 'count', 'alert_ids'])
            for row in rows:
                writer.writerow([row['region'], row['highest_severity'], row['count'], ';'.join(row['alert_ids'])])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return len(rows)

