import os
import zipfile
from datetime import date

def _fields(line):
    out = []
    cur = []
    escaped = False
    for ch in line:
        if escaped:
            cur.append(ch)
            escaped = False
        elif ch == '\\':
            escaped = True
        elif ch == '|':
            out.append(''.join(cur))
            cur = []
        else:
            cur.append(ch)
    if escaped:
        raise ValueError('incomplete escape')
    out.append(''.join(cur))
    return out

def parse_assembly_orders(text: str) -> list[dict]:
    result = []
    for line in text.splitlines():
        if not line.strip():
            continue
        fields = _fields(line)
        if len(fields) != 5:
            raise ValueError('wrong field count')
        oid, customer, due, priority, count = fields
        try:
            date.fromisoformat(due)
            p = int(priority)
            n = int(count)
        except (ValueError, TypeError):
            raise ValueError('invalid order')
        if p < 0 or p > 9 or n <= 0:
            raise ValueError('invalid order')
        result.append({'order_id': oid, 'customer': customer, 'due_date': due, 'priority': p, 'item_count': n})
    return result

def batch_assembly_orders(orders: list[dict], max_items: int) -> list[list[str]]:
    if not isinstance(max_items, int) or max_items <= 0:
        raise ValueError('invalid capacity')
    checked = []
    for o in orders:
        try:
            oid, due, priority, count = (o['order_id'], o['due_date'], o['priority'], o['item_count'])
            date.fromisoformat(due)
            if not isinstance(priority, int) or not 0 <= priority <= 9 or (not isinstance(count, int)) or (count <= 0):
                raise ValueError
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid order')
        if count > max_items:
            raise ValueError('order too large')
        checked.append((due, -priority, oid, count))
    checked.sort(key=lambda x: (x[0], x[1], x[2]))
    batches, current, total = ([], [], 0)
    for _, _, oid, count in checked:
        if current and total + count > max_items:
            batches.append(current)
            current, total = ([], 0)
        current.append(oid)
        total += count
    if current:
        batches.append(current)
    return batches

def extract_order_documents(archive_path: str, destination: str, members: list[str]) -> list[str]:
    base = os.path.realpath(destination)
    result = []
    with zipfile.ZipFile(archive_path) as archive:
        for member in members:
            info = archive.getinfo(member)
            if member.endswith('/'):
                raise ValueError('directory member')
            target = os.path.realpath(os.path.join(base, *member.split('/')))
            if os.path.commonpath((base, target)) != base:
                raise ValueError('invalid destination')
            os.makedirs(os.path.dirname(target), exist_ok=True)
            with open(target, 'wb') as stream:
                stream.write(archive.read(info))
            result.append(target)
    return result

