    record = make_camper('  Maya Chen  ', 12, '0427')
    assert record['name'] == 'Maya Chen'
    assert record['age'] == 12
    assert set(record) == {'name', 'age', 'pin_hash', 'salt'}
    assert isinstance(record['pin_hash'], str)
    assert isinstance(record['salt'], str)

def test_pin_round_trip_and_wrong_pin():
    record = make_camper('Luis', 10, '1234')
    assert verify_pin(record, '1234') is True
    assert verify_pin(record, '1235') is False
    assert verify_pin(record, '123') is False

def test_validation_rules():
    for args in [('', 10, '1234'), ('   ', 10, '1234'), ('A', 6, '1234'), ('A', 18, '1234'), ('A', True, '1234'), ('A', 10, '12a4'), ('A', 10, '123'), ('A', 10, 1234)]:
