import hashlib
import hmac
import os

def _digest(pin, salt):
    return hashlib.pbkdf2_hmac('sha256', pin.encode('ascii'), salt, 100000).hex()

def make_camper(name: str, age: int, pin: str) -> dict:
    if not isinstance(name, str) or not name.strip():
        raise ValueError('invalid name')
    if isinstance(age, bool) or not isinstance(age, int) or (not 7 <= age <= 17):
        raise ValueError('invalid age')
    if not isinstance(pin, str) or len(pin) != 4 or (not pin.isascii()) or (not pin.isdigit()):
        raise ValueError('invalid pin')
    salt = os.urandom(16)
    return {'name': name.strip(), 'age': age, 'pin_hash': _digest(pin, salt), 'salt': salt.hex()}

def verify_pin(record: dict, pin: str) -> bool:
    if not isinstance(record, dict) or not isinstance(pin, str) or len(pin) != 4 or (not pin.isascii()) or (not pin.isdigit()):
        return False
    try:
        salt = bytes.fromhex(record['salt'])
        actual = _digest(pin, salt)
        return hmac.compare_digest(actual, record['pin_hash'])
    except (KeyError, TypeError, ValueError):
        return False

def camp_report(records: list[dict], min_age: int=7, max_age: int=17, page: int=1, page_size: int=10) -> dict:
    if any((isinstance(x, bool) or not isinstance(x, int) or x <= 0 for x in (page, page_size))):
        raise ValueError('invalid page')
    if isinstance(min_age, bool) or isinstance(max_age, bool) or (not isinstance(min_age, int)) or (not isinstance(max_age, int)) or (min_age > max_age):
        raise ValueError('invalid age range')
    selected = [r for r in records if min_age <= r['age'] <= max_age]
    selected.sort(key=lambda r: (r['age'], r['name'].casefold()))
    average = round(sum((r['age'] for r in selected)) / len(selected), 2) if selected else 0.0
    start = (page - 1) * page_size
    return {'count': len(selected), 'average_age': average, 'campers': selected[start:start + page_size]}

