import hashlib
import os
from datetime import date

def hash_pin(pin: str) -> str:
    if not isinstance(pin, str):
        raise TypeError('pin must be a string')
    if not pin.isdigit() or not 4 <= len(pin) <= 12:
        raise ValueError('invalid pin')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def verify_pin(pin: str, stored: str) -> bool:
    if not isinstance(pin, str) or not isinstance(stored, str):
        return False
    if not pin.isdigit() or not 4 <= len(pin) <= 12:
        return False
    try:
        salt_text, digest_text = stored.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except ValueError:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return actual == expected

def summarize_certifications(records: list[dict], as_of: str, page: int=1, page_size: int=10) -> dict:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    if not isinstance(as_of, str) or not isinstance(page, int) or isinstance(page, bool) or (not isinstance(page_size, int)) or isinstance(page_size, bool):
        raise ValueError('invalid arguments')
    if page < 1 or not 1 <= page_size <= 100:
        raise ValueError('invalid pagination')
    try:
        cutoff = date.fromisoformat(as_of)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    valid = []
    for record in records:
        if not isinstance(record, dict) or set(record) != {'seafarer', 'certificate', 'expires', 'points'}:
            raise ValueError('invalid record')
        if not isinstance(record['seafarer'], str) or not isinstance(record['certificate'], str) or (not isinstance(record['expires'], str)) or (not isinstance(record['points'], int)) or isinstance(record['points'], bool) or (record['points'] < 0):
            raise ValueError('invalid record')
        try:
            expiry = date.fromisoformat(record['expires'])
        except ValueError:
            raise ValueError('invalid date')
        if expiry >= cutoff:
            valid.append((expiry, record['seafarer'], record['certificate'], record))
    valid.sort(key=lambda item: item[:3])
    start = (page - 1) * page_size
    return {'total': len(valid), 'page': page, 'page_size': page_size, 'items': [item[3] for item in valid[start:start + page_size]]}

