import pytest


def test_owner_can_update_assigned_work_order():
    requester = {"id": "u1", "tenant_id": "city-a", "roles": ["technician"]}
    orders = [{"id": "wo-1", "tenant_id": "city-a", "assigned_to": "u1", "status": "open", "vehicle": "truck-7"}]
