    assert orders[0]["status"] == "in_progress"
    assert result is orders[0]


def test_fleet_manager_can_update_work_order():
    requester = {"id": "manager", "tenant_id": "city-a", "roles": ["fleet_manager"]}
    orders = [{"id": "wo-2", "tenant_id": "city-a", "assigned_to": "u9", "status": "in_progress"}]
    result = update_work_order_status(requester, orders, "wo-2", "completed")
    assert result["status"] == "completed"
    assert orders == [{"id": "wo-2", "tenant_id": "city-a", "assigned_to": "u9", "status": "completed"}]


def test_all_valid_statuses_are_accepted():
    requester = {"id": "u1", "tenant_id": "city-a", "roles": []}
    for status in ("open", "in_progress", "completed", "cancelled"):
        orders = [{"id": "wo", "tenant_id": "city-a", "assigned_to": "u1", "status": "open"}]
        assert update_work_order_status(requester, orders, "wo", status)["status"] == status


