    requester = {"id": "u1", "tenant_id": "city-a", "roles": []}
    orders = [{"id": "wo-3", "tenant_id": "city-a", "assigned_to": "u1", "status": "open", "note": "scheduled"}]
    with pytest.raises(ValueError):
        update_work_order_status(requester, orders, "wo-3", "paused")
    assert orders[0] == {"id": "wo-3", "tenant_id": "city-a", "assigned_to": "u1", "status": "open", "note": "scheduled"}


