    if new_status not in {'open', 'in_progress', 'completed', 'cancelled'}:
        raise ValueError(new_status)
    for order in work_orders:
        if order.get('id') == order_id:
            same_tenant = order.get('tenant_id') == requester.get('tenant_id')
            is_owner = order.get('assigned_to') == requester.get('id')
            is_manager = 'fleet_manager' in requester.get('roles', [])
            if not same_tenant or not (is_owner or is_manager):
                raise PermissionError(order_id)
            order['status'] = new_status
            return order
    raise KeyError(order_id)

