import os
import subprocess

def build_review_queue(paths: list[str], reviewers: list[str]) -> list[dict[str, object]]:
    if not reviewers or any((not isinstance(name, str) or not name for name in reviewers)):
        raise ValueError('invalid reviewers')
    if len(set(reviewers)) != len(reviewers):
        raise ValueError('duplicate reviewers')
    if any((not isinstance(path, str) or not path for path in paths)):
        raise ValueError('invalid path')
    if len(set(paths)) != len(paths):
        raise ValueError('duplicate paths')
    records = []
    for path in paths:
        if not os.path.exists(path):
            raise FileNotFoundError(path)
        if not os.path.isfile(path):
            raise ValueError('path is not a regular file')
        completed = subprocess.run(['wc', '-l', path], capture_output=True, text=True, check=True)
        fields = completed.stdout.split()
        if not fields:
            raise ValueError('invalid wc output')
        records.append({'path': path, 'line_count': int(fields[0]), 'size': os.path.getsize(path)})
    records.sort(key=lambda item: (-item['line_count'], -item['size'], item['path']))
    result = []
    for index, record in enumerate(records):
        result.append({'path': record['path'], 'line_count': record['line_count'], 'size': record['size'], 'reviewer': reviewers[index % len(reviewers)]})
    return result

