import copy
import secrets

def parse_call(text: str) -> dict:
    fields = []
    current = []
    escaped = False
    for ch in text:
        if escaped:
            current.append(ch)
            escaped = False
        elif ch == '\\':
            escaped = True
        elif ch == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(ch)
    if escaped:
        raise ValueError('trailing escape')
    fields.append(''.join(current))
    if len(fields) != 6 or any((not fields[i] for i in (0, 1, 4))):
        raise ValueError('invalid record')
    try:
        priority = int(fields[2])
        wait = int(fields[3])
    except ValueError:
        raise ValueError('invalid number')
    if not 1 <= priority <= 5 or wait < 0 or fields[5] not in ('yes', 'no'):
        raise ValueError('invalid value')
    return {'customer': fields[0], 'queue': fields[1], 'priority': priority, 'wait_minutes': wait, 'language': fields[4], 'callback': fields[5] == 'yes'}

class CallCenterQueue:

    def __init__(self):
        self._calls = []
        self._sequence = 0
        self._codes = {}

    def add_call(self, call: dict) -> None:
        item = copy.deepcopy(call)
        item['_sequence'] = self._sequence
        self._sequence += 1
        self._calls.append(item)

    def dispatch(self, queue: str, limit: int) -> list[dict]:
        if limit <= 0:
            return []
        chosen = [x for x in self._calls if x['queue'] == queue]
        chosen.sort(key=lambda x: (-x['priority'], -x['wait_minutes'], not x['callback'], x['language'], x['customer'], x['_sequence']))
        chosen = chosen[:limit]
        selected = {x['_sequence'] for x in chosen}
        self._calls = [x for x in self._calls if x['_sequence'] not in selected]
        return [copy.deepcopy({k: v for k, v in x.items() if k != '_sequence'}) for x in chosen]

    def issue_callback_code(self, customer: str) -> str:
        if not customer:
            raise ValueError('empty customer')
        alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
        while True:
            code = ''.join((secrets.choice(alphabet) for _ in range(12)))
            if code not in self._codes:
                self._codes[code] = customer
                return code

    def redeem_callback_code(self, code: str) -> str | None:
        return self._codes.pop(code, None)

