from lxml import etree

def extract_document_metadata(xml_text: str) -> dict[str, object]:
    if not isinstance(xml_text, str):
        raise ValueError('xml_text must be a string')
    try:
        parser = etree.XMLParser(resolve_entities=False, load_dtd=False, no_network=True)
        root = etree.fromstring(xml_text.encode('utf-8'), parser)
        if root.tag != 'project-document':
            raise ValueError('invalid root')
        attrs = {name: root.get(name) for name in ('id', 'revision', 'status')}
        if any((value is None or value == '' for value in attrs.values())):
            raise ValueError('missing attribute')
        values = {}
        for name in ('title', 'discipline', 'issued'):
            element = root.find(name)
            if element is None:
                raise ValueError('missing element')
            values[name] = (element.text or '').strip()
        tags_element = root.find('tags')
        tags = [] if tags_element is None else [(tag.text or '').strip() for tag in tags_element.findall('tag')]
        return {**attrs, **values, 'tags': tags}
    except ValueError:
        raise
    except Exception as exc:
        raise ValueError('invalid XML') from exc

