import hashlib
from datetime import datetime, timedelta

def _key(config):
    if config is not None and 'signing_key' in config:
        value = config['signing_key']
    else:
        value = os.environ.get('NOTARY_SIGNING_KEY')
    if not value:
        raise ValueError('missing signing key')
    return str(value).encode()

def _checked(a):
    required = ('id', 'notary', 'start', 'duration', 'priority')
    if any((x not in a for x in required)) or not isinstance(a['id'], str) or (not a['id']) or (not isinstance(a['notary'], str)) or (not a['notary']):
        raise ValueError('invalid appointment')
    try:
        start = datetime.strptime(a['start'], '%Y-%m-%d %H:%M')
    except (TypeError, ValueError):
        raise ValueError('invalid appointment')
    if type(a['duration']) is not int or a['duration'] <= 0 or type(a['priority']) is not int:
        raise ValueError('invalid appointment')
    return start

def make_appointment_token(appointment: dict, config: dict | None=None) -> str:
    _checked(appointment)
    body = json.dumps(appointment, sort_keys=True, separators=(',', ':')).encode()
    return hmac.new(_key(config), body, hashlib.sha256).hexdigest()

def schedule_appointments(appointments: list[dict], day: str, config: dict | None=None) -> list[dict]:
    try:
        datetime.strptime(day, '%Y-%m-%d')
    except ValueError:
        raise ValueError('invalid day')
    groups = {}
    for item in appointments:
        start = _checked(item)
        if start.strftime('%Y-%m-%d') == day:
            groups.setdefault(item['notary'], []).append((start, item))
    chosen = []
    for notary, values in groups.items():
        values.sort(key=lambda x: (x[0], -x[1]['priority'], x[1]['id']))
        end = None
        for start, item in values:
            finish = start + timedelta(minutes=item['duration'])
            if end is None or start >= end:
                chosen.append((start, notary, item))
                end = finish
    chosen.sort(key=lambda x: (x[0], x[1], x[2]['id']))
    result = []
    for _, _, item in chosen:
        copy = dict(item)
        copy['token'] = make_appointment_token(item, config)
        result.append(copy)
    return result

