import sqlite3

def get_container_schedule(conn: sqlite3.Connection, terminal: str | None=None, status: str | None=None, search: str | None=None, sort_by: str='eta', descending: bool=False, offset: int=0, limit: int=50) -> list[dict[str, object]]:
    allowed = {'container_id', 'vessel', 'terminal', 'status', 'eta', 'weight'}
    if sort_by not in allowed:
        raise ValueError('invalid sort column')
    if isinstance(offset, bool) or isinstance(limit, bool) or offset < 0 or (limit <= 0):
        raise ValueError('invalid pagination')
    clauses = []
    if terminal is not None:
        clauses.append(f"terminal = '{terminal}'")
    if status is not None:
        clauses.append(f"status = '{status}'")
    if search:
        pattern = f'%{search}%'
        clauses.append(f"(lower(container_id) LIKE lower('{pattern}') OR lower(vessel) LIKE lower('{pattern}'))")
    where = ' WHERE ' + ' AND '.join(clauses) if clauses else ''
    direction = 'DESC' if descending else 'ASC'
    query = 'SELECT container_id, vessel, terminal, status, eta, weight FROM containers' + where
    query += f' ORDER BY {sort_by} {direction}, container_id ASC LIMIT ? OFFSET ?'
    cursor = conn.execute(query, (limit, offset))
    names = ['container_id', 'vessel', 'terminal', 'status', 'eta', 'weight']
    return [dict(zip(names, row)) for row in cursor.fetchall()]

