    if not isinstance(requester, dict) or not isinstance(requester.get('user_id'), str) or (not isinstance(requester.get('tenant_id'), str)) or (not isinstance(requester.get('roles'), list)) or (not all((isinstance(x, str) for x in requester['roles']))):
        raise ValueError('invalid requester')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1 or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (page_size < 1):
        raise ValueError('invalid pagination')
    if not isinstance(interviews, list):
        raise ValueError('invalid interviews')
    fields = ('panel_id', 'tenant_id', 'panel_owner_id', 'interviewer', 'score', 'duration_minutes', 'completed')
    groups = {}
    for item in interviews:
        if not isinstance(item, dict) or any((k not in item for k in fields)):
            raise ValueError('invalid interview')
        if any((not isinstance(item[k], str) or not item[k] for k in fields[:4])) or not isinstance(item['score'], int) or isinstance(item['score'], bool) or (not 1 <= item['score'] <= 5) or (not isinstance(item['duration_minutes'], int)) or isinstance(item['duration_minutes'], bool) or (item['duration_minutes'] <= 0) or (not isinstance(item['completed'], bool)) or (not item['completed']):
            raise ValueError('invalid interview')
        if item['tenant_id'] != requester['tenant_id']:
            continue
        g = groups.setdefault(item['interviewer'], [0, 0, 0])
        g[0] += 1
        g[1] += item['score']
        g[2] += item['duration_minutes']
    result = []
    for name, (count, total, minutes) in groups.items():
        average = float(Decimal(total) / Decimal(count).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
        result.append({'interviewer': name, 'count': count, 'average_score': average, 'total_minutes': minutes})
    result.sort(key=lambda x: (-x['average_score'], x['interviewer']))
    start = (page - 1) * page_size
    return {'page': page, 'page_size': page_size, 'total_interviewers': len(result), 'interviewers': result[start:start + page_size]}

