import ast
import operator

def _evaluate(node, names):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in names:
            raise ValueError()
        return names[node.id]
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
        value = _evaluate(node.operand, names)
        if isinstance(node.op, ast.UAdd):
            return +value
        if isinstance(node.op, ast.USub):
            return -value
        return not value
    if isinstance(node, ast.BinOp) and type(node.op) in {ast.Add, ast.Sub, ast.Mult, ast.Div}:
        left = _evaluate(node.left, names)
        right = _evaluate(node.right, names)
        return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
    if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
        value = _evaluate(node.values[0], names)
        for child in node.values[1:]:
            if isinstance(node.op, ast.And) and (not value):
                return value
            if isinstance(node.op, ast.Or) and value:
                return value
            value = _evaluate(child, names)
        return value
    if isinstance(node, ast.Compare):
        left = _evaluate(node.left, names)
        for op, child in zip(node.ops, node.comparators):
            right = _evaluate(child, names)
            functions = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}
            if type(op) not in functions or not functions[type(op)](left, right):
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max', 'round'}) and (not node.keywords):
        values = [_evaluate(arg, names) for arg in node.args]
        if node.func.id == 'round' and len(values) in (1, 2):
            return round(*values)
        if node.func.id == 'min' and len(values) >= 2:
            return min(*values)
        if node.func.id == 'max' and len(values) >= 2:
            return max(*values)
    raise ValueError()

def rank_gift_cards(cards: list[dict], rule: str, page: int, page_size: int) -> dict:
    if page <= 0 or page_size <= 0:
        raise ValueError()
    try:
        tree = ast.parse(rule, mode='eval').body
        selected = []
        for card in cards:
            names = {key: card[key] for key in ('id', 'balance', 'redeemed', 'active', 'priority')}
