from decimal import Decimal, ROUND_HALF_UP

def build_trade_in_report(requester: dict, trade_ins: list[dict], market_prices: dict[str, float], page: int, page_size: int) -> dict:
    if not isinstance(requester, dict) or not isinstance(trade_ins, list) or (not isinstance(market_prices, dict)):
        raise TypeError('invalid argument type')
    if type(page) is not int or type(page_size) is not int or page < 1 or (page_size < 1):
        raise ValueError('invalid pagination')
    conditions = {'mint': Decimal('1.0'), 'good': Decimal('0.85'), 'fair': Decimal('0.65'), 'poor': Decimal('0.4')}
    items = []
    total = Decimal('0')
    for record in trade_ins:
        for key in ('id', 'owner_id', 'tenant_id', 'model', 'condition', 'battery_percent', 'has_original_accessories'):
            if key not in record:
                raise KeyError(key)
        if not (record['owner_id'] == requester['id'] or ('manager' in requester['roles'] and record['tenant_id'] == requester['tenant_id'])):
            raise PermissionError('not permitted')
        if record['condition'] not in conditions or type(record['battery_percent']) is not int or (not 0 <= record['battery_percent'] <= 100):
            raise ValueError('invalid trade-in')
        if record['model'] not in market_prices or market_prices[record['model']] < 0:
            raise ValueError('invalid price')
        deductions = []
        factor = conditions[record['condition']]
        if record['battery_percent'] < 60:
            factor *= Decimal('0.8')
            deductions.append('battery')
        elif record['battery_percent'] < 80:
            factor *= Decimal('0.9')
            deductions.append('battery')
        if not record['has_original_accessories']:
            factor *= Decimal('0.95')
            deductions.append('accessories')
        value = (Decimal(str(market_prices[record['model']])) * factor).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        total += value
        items.append({'id': record['id'], 'model': record['model'], 'condition': record['condition'], 'value': float(value), 'deductions': deductions})
    items.sort(key=lambda item: (-item['value'], item['id']))
    start = (page - 1) * page_size
    total = total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    return {'items': items[start:start + page_size], 'total': len(trade_ins), 'page': page, 'page_size': page_size, 'total_value': float(total)}

