def summarize_fleet(path: str, max_gap_seconds: int=3600, min_speed: float=0.0) -> list[dict]:
    completed = subprocess.run(['sort', '-t,', '-k1,1', '-k2,2', path], check=True, capture_output=True, text=True)
    records = []
