import hashlib
import hmac
import json
import os

def build_aqi_report(records: list[dict], city: str, page: int, page_size: int) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('page must be a positive integer')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError('page_size must be a positive integer')
    for record in records:
        if not all((name in record for name in ('city', 'pollutant', 'aqi', 'timestamp'))):
            raise ValueError('record is missing a required field')
        if not isinstance(record['city'], str) or not isinstance(record['pollutant'], str):
            raise ValueError('city and pollutant must be strings')
        if not isinstance(record['timestamp'], str) or not record['timestamp']:
            raise ValueError('timestamp must be a nonempty string')
        if isinstance(record['aqi'], bool) or not isinstance(record['aqi'], (int, float)) or (not 0 <= record['aqi'] <= 500):
            raise ValueError('aqi must be between 0 and 500')
    matching = [record for record in records if record['city'] == city]
    matching.sort(key=lambda record: (record['timestamp'], record['pollutant']))
    values = [record['aqi'] for record in matching]
    if values:
        maximum = max(values)
        if maximum <= 50:
            category = 'Good'
        elif maximum <= 100:
            category = 'Moderate'
        elif maximum <= 150:
            category = 'Unhealthy for Sensitive Groups'
        elif maximum <= 200:
            category = 'Unhealthy'
        elif maximum <= 300:
            category = 'Very Unhealthy'
        else:
            category = 'Hazardous'
        summary = {'count': len(values), 'average_aqi': round(sum(values) / len(values), 2), 'maximum_aqi': maximum, 'category': category}
    else:
        summary = {'count': 0, 'average_aqi': 0.0, 'maximum_aqi': None, 'category': 'No data'}
    start = (page - 1) * page_size
    report = {'city': city, 'page': page, 'page_size': page_size, 'total': len(matching), 'readings': matching[start:start + page_size], 'summary': summary}
    key = os.environ.get('AQI_REPORT_SIGNING_KEY')
    if key is None:
        raise RuntimeError('AQI_REPORT_SIGNING_KEY is required')
    body = json.dumps(report, sort_keys=True, separators=(',', ':')).encode()
    report['signature'] = hmac.new(key.encode(), body, hashlib.sha256).hexdigest()
    return report

