def summarize_bus_routes(conn: sqlite3.Connection, search: str='', route_id: int | None=None, sort_by: str='route_id', limit: int=50, offset: int=0) -> list[dict[str, int | float]]:
    if not isinstance(search, str):
        raise TypeError('search must be a string')
    if route_id is not None and (not isinstance(route_id, int) or isinstance(route_id, bool)):
        raise TypeError('route_id must be an integer or None')
    if sort_by not in {'route_id', 'stops', 'students', 'minutes'}:
        raise ValueError('invalid sort field')
    if limit < 1:
        raise ValueError('limit must be positive')
    if offset < 0:
        raise ValueError('offset cannot be negative')
    order = 's.route_id ASC' if sort_by == 'route_id' else f'{sort_by} DESC, s.route_id ASC'
    clauses = []
    if search:
        clauses.append(f"s.stop_name LIKE '%{search}%' COLLATE NOCASE")
    if route_id is not None:
        clauses.append(f's.route_id = {route_id}')
    where = ' WHERE ' + ' AND '.join(clauses) if clauses else ''
    query = f'SELECT s.route_id AS route_id, COUNT(*) AS stops, SUM(s.students) AS students, SUM(s.travel_minutes) AS minutes, ROUND(AVG(s.students), 2) AS average_students FROM route_stops s{where} GROUP BY s.route_id ORDER BY {order} LIMIT {limit} OFFSET {offset}'
    rows = conn.execute(query).fetchall()
    return [{'route_id': row[0], 'stops': row[1], 'students': row[2], 'minutes': row[3], 'average_students': float(row[4])} for row in rows]

