import hashlib
import hmac
import math
import os

def hash_password(password: str) -> str:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    if not password:
        raise ValueError('password must not be empty')
    iterations = 100000
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, iterations)
    return f'{iterations}${salt.hex()}${digest.hex()}'

def verify_password(password: str, stored: str) -> bool:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    if not isinstance(stored, str):
        return False
    try:
        iterations_text, salt_text, digest_text = stored.split('$')
        iterations = int(iterations_text)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        if iterations <= 0 or len(salt) == 0:
            return False
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, iterations)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def rank_response_events(events: list[dict], page: int, page_size: int) -> list[dict]:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError('invalid pagination')
    grouped = {}
    for event in events:
        operator = event.get('operator')
        value = event.get('reduction_kw')
        if not isinstance(operator, str) or isinstance(value, bool) or (not isinstance(value, (int, float))) or (not math.isfinite(value)):
            raise ValueError('invalid event')
        if value > 0:
            total, count = grouped.get(operator, (0.0, 0))
            grouped[operator] = (total + value, count + 1)
    result = [{'operator': name, 'total_kw': round(total, 2), 'event_count': count} for name, (total, count) in grouped.items()]
    result.sort(key=lambda item: (-item['total_kw'], item['operator']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

