import secrets
_ALPHABET = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'

def make_limit_token(client_id: str, length: int=24) -> str:
    if not isinstance(client_id, str):
        raise TypeError('client_id must be a string')
    if not client_id:
        raise ValueError('client_id must not be empty')
    if not isinstance(length, int):
        raise TypeError('length must be an integer')
    if length < 16 or length > 64:
        raise ValueError('invalid length')
    return ''.join((secrets.choice(_ALPHABET) for _ in range(length)))

def rate_limit_report(events: list[dict], now: int, window_seconds: int, limit: int, page: int=1, page_size: int=10) -> dict:
    if not isinstance(events, list) or not isinstance(now, int) or (not isinstance(window_seconds, int)) or (not isinstance(limit, int)) or (not isinstance(page, int)) or (not isinstance(page_size, int)):
        raise TypeError('invalid argument type')
    if window_seconds <= 0 or limit < 0 or page <= 0 or (page_size <= 0):
        raise ValueError('invalid argument value')
    counts = {}
    start = now - window_seconds + 1
    for event in events:
        if not isinstance(event, dict):
            raise ValueError('invalid event')
        client = event.get('client')
        timestamp = event.get('timestamp')
        if not isinstance(client, str) or not client or (not isinstance(timestamp, int)):
            raise ValueError('invalid event')
        if start <= timestamp <= now:
            counts[client] = counts.get(client, 0) + 1
    entries = []
    for client, count in counts.items():
        entries.append({'client_id': client, 'requests': count, 'remaining': max(limit - count, 0), 'token': make_limit_token(client, 20)})
    entries.sort(key=lambda item: (-item['requests'], item['client_id']))
    begin = (page - 1) * page_size
    return {'total_clients': len(entries), 'page': page, 'page_size': page_size, 'clients': entries[begin:begin + page_size]}

