import ast
import operator

def select_rotation_targets(secrets: list[dict], rule: str, variables: dict[str, int | float | bool]) -> list[str]:
    if not isinstance(secrets, list) or not isinstance(variables, dict):
        raise ValueError('invalid inputs')
    tree = ast.parse(rule, mode='eval').body
    funcs = {'min': min, 'max': max, 'round': round}
    ops = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
    comparisons = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}

    def ev(n, env):
        if isinstance(n, ast.Constant) and isinstance(n.value, (int, float, bool)):
            return n.value
        if isinstance(n, ast.Name):
            if n.id not in env:
                raise NameError(n.id)
            return env[n.id]
        if isinstance(n, ast.BinOp) and type(n.op) in ops:
            return ops[type(n.op)](ev(n.left, env), ev(n.right, env))
        if isinstance(n, ast.UnaryOp) and isinstance(n.op, (ast.UAdd, ast.USub, ast.Not)):
            value = ev(n.operand, env)
            return +value if isinstance(n.op, ast.UAdd) else -value if isinstance(n.op, ast.USub) else not value
        if isinstance(n, ast.BoolOp):
            value = ev(n.values[0], env)
            for child in n.values[1:]:
                if isinstance(n.op, ast.And):
                    if not value:
                        return value
                elif value:
                    return value
                value = ev(child, env)
            return value
        if isinstance(n, ast.Compare):
            left = ev(n.left, env)
            for op, right_node in zip(n.ops, n.comparators):
                right = ev(right_node, env)
                if not comparisons[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and (n.func.id in funcs):
            return funcs[n.func.id](*(ev(a, env) for a in n.args))
        raise SyntaxError('unsupported expression')
    result = []
    for index, secret in enumerate(secrets):
        if not isinstance(secret, dict) or not all((k in secret for k in ('name', 'age_days', 'risk', 'active'))):
            raise ValueError('invalid secret')
        score = ev(tree, {**variables, **secret})
        if secret['active'] and score > 0:
            result.append((score, index, secret['name']))
    return [name for _, _, name in sorted(result, key=lambda x: (-x[0], x[1]))]

