import tempfile
from pathlib import Path
import pytest

def test_parse_invoice_line_valid():
    value = parse_invoice_line(' INV-7 | Acme Ltd | 1250.50 | 2024-03-01 | approved ')
    assert value == {'id': 'INV-7', 'client': 'Acme Ltd', 'amount': 1250.5, 'due_date': datetime.date(2024, 3, 1), 'status': 'approved'}

def test_parse_invoice_line_rejects_bad_records():
    bad = ['', 'a|b|1|2024-01-01', 'a|b|-1|2024-01-01|paid', 'a|b|1.234|2024-01-01|paid', 'a|b|x|2024-01-01|paid', 'a|b|1|2024-02-30|paid', 'a||1|2024-01-01|paid', 'a|b|1|2024-01-01|unknown']
    for line in bad:
        with pytest.raises(ValueError):
            parse_invoice_line(line)

def test_report_ignores_blank_lines_and_orders_clients():
    with tempfile.TemporaryDirectory() as td:
        Path(td, 'one.inv').write_text('\nZ|Zulu|1|2024-01-01|paid\nA|Alpha|2|2024-01-01|paid\n', encoding='utf-8')
        got = invoice_report(td, '*.inv', '2024-01-01')
        assert got['by_client'] == {'Alpha': 2.0, 'Zulu': 1.0}
        assert got['aging'] == {'current': 3.0, '1-30': 0.0, '31-60': 0.0, '61+': 0.0}

def test_report_empty_match_and_invalid_as_of():
    with tempfile.TemporaryDirectory() as td:
        assert invoice_report(td, '*.inv', '2024-01-01') == {'files': [], 'invoice_count': 0, 'total_amount': 0.0, 'approved_amount': 0.0, 'by_client': {}, 'aging': {'current': 0.0, '1-30': 0.0, '31-60': 0.0, '61+': 0.0}}
        with pytest.raises(ValueError):
            invoice_report(td, '*.inv', '2024-02-30')

def test_report_rejects_duplicate_ids():
    with tempfile.TemporaryDirectory() as td:
        Path(td, 'a.inv').write_text('D|A|1|2024-01-01|paid\n', encoding='utf-8')
        Path(td, 'b.inv').write_text('D|B|2|2024-01-01|paid\n', encoding='utf-8')
        with pytest.raises(ValueError):
            invoice_report(td, '*.inv', '2024-01-01')

def test_report_rejects_malformed_file():
    with tempfile.TemporaryDirectory() as td:
        Path(td, 'bad.inv').write_text('I|Client|1.00|2024-01-01|paid\nnot valid\n', encoding='utf-8')
        with pytest.raises(ValueError):
