import datetime
import subprocess
from decimal import Decimal, InvalidOperation

def parse_invoice_line(line: str) -> dict:
    if not line.strip():
        raise ValueError('blank invoice line')
    fields = [x.strip() for x in line.rstrip('\n').split('|')]
    if len(fields) != 5 or any((not x for x in fields)):
        raise ValueError('invalid invoice line')
    try:
        amount = Decimal(fields[2])
        date = datetime.date.fromisoformat(fields[3])
    except (InvalidOperation, ValueError):
        raise ValueError('invalid invoice value')
    if amount < 0 or amount.as_tuple().exponent < -2 or fields[4] not in {'pending', 'approved', 'paid'}:
        raise ValueError('invalid invoice value')
    return {'id': fields[0], 'client': fields[1], 'amount': float(amount), 'due_date': date, 'status': fields[4]}

def invoice_report(directory: str, name_pattern: str, as_of: str) -> dict:
    try:
        cutoff = datetime.date.fromisoformat(as_of)
    except ValueError:
        raise ValueError('invalid as_of')
    result = subprocess.run(['find', directory, '-maxdepth', '1', '-type', 'f', '-name', name_pattern, '-print'], capture_output=True, text=True, check=True)
    paths = sorted([x for x in result.stdout.splitlines() if x])
    records = []
    seen = set()
    for path in paths:
        with open(path, encoding='utf-8') as f:
            for line in f:
                if not line.strip():
                    continue
                record = parse_invoice_line(line)
                if record['id'] in seen:
                    raise ValueError('duplicate invoice')
                seen.add(record['id'])
                records.append(record)
    by_client = {}
    aging = {'current': 0.0, '1-30': 0.0, '31-60': 0.0, '61+': 0.0}
    total = approved = 0.0
    for r in records:
        amount = r['amount']
        total += amount
        if r['status'] == 'approved':
            approved += amount
        by_client[r['client']] = by_client.get(r['client'], 0.0) + amount
        days = (cutoff - r['due_date']).days
        bucket = 'current' if days <= 0 else '1-30' if days <= 30 else '31-60' if days <= 60 else '61+'
        aging[bucket] += amount
    return {'files': [path.rsplit('/', 1)[-1] for path in paths], 'invoice_count': len(records), 'total_amount': round(total, 2), 'approved_amount': round(approved, 2), 'by_client': {k: round(by_client[k], 2) for k in sorted(by_client)}, 'aging': {k: round(v, 2) for k, v in aging.items()}}

