import hashlib
import hmac
import json
import math

def verify_caseload_signature(payload: bytes, signature: str, secret: bytes, page: int=1, page_size: int=10) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
    if not isinstance(signature, str) or not signature.startswith('sha256='):
        raise ValueError('invalid signature')
    supplied = signature[7:]
    if len(supplied) != 64:
        raise ValueError('invalid signature')
    try:
        supplied_bytes = bytes.fromhex(supplied)
    except ValueError:
        raise ValueError('invalid signature')
    expected = hmac.new(secret, payload, hashlib.sha256).digest()
    if not hmac.compare_digest(supplied_bytes, expected):
        raise ValueError('invalid signature')
    try:
        data = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    if not isinstance(data, dict) or not isinstance(data.get('cases'), list):
        raise ValueError('invalid payload')
    groups = {}
    ids = set()
    for case in data['cases']:
        if not isinstance(case, dict):
            raise ValueError('invalid case')
        case_id = case.get('case_id')
        attorney = case.get('attorney')
        status = case.get('status')
        hours = case.get('hours')
        if not isinstance(case_id, str) or not case_id or case_id in ids or (not isinstance(attorney, str)) or (not attorney) or (status not in ('open', 'closed')) or isinstance(hours, bool) or (not isinstance(hours, (int, float))) or (not math.isfinite(hours)) or (hours < 0):
            raise ValueError('invalid case')
        ids.add(case_id)
        item = groups.setdefault(attorney, [0, 0.0])
        item[0] += status == 'open'
        item[1] += hours
    entries = [{'attorney': name, 'open_cases': values[0], 'total_hours': round(values[1], 2)} for name, values in groups.items()]
    entries.sort(key=lambda item: (-item['total_hours'], item['attorney']))
    pages = (len(entries) + page_size - 1) // page_size
    if page > max(1, pages):
        raise ValueError('page out of range')
    start = (page - 1) * page_size
    return {'total_cases': len(data['cases']), 'attorneys': entries[start:start + page_size], 'page': page, 'pages': pages}

