import json
import os
import re
import tempfile
from datetime import datetime

def parse_document_feed(text: str) -> list[dict[str, object]]:
    if not isinstance(text, str):
        raise ValueError('text must be a string')
    records = []
    seen = set()
    for raw in text.splitlines():
        if not raw:
            continue
        fields = []
        current = []
        i = 0
        while i < len(raw):
            c = raw[i]
            if c == '\\':
                if i + 1 == len(raw) or raw[i + 1] not in '\\|':
                    raise ValueError('invalid escape')
                current.append(raw[i + 1])
                i += 2
            elif c == '|':
                fields.append(''.join(current))
                current = []
                i += 1
            else:
                current.append(c)
                i += 1
        fields.append(''.join(current))
        if len(fields) != 4 or not fields[0] or (not re.fullmatch('\\d{4}-\\d\\d-\\d\\dT\\d\\d:\\d\\d:\\d\\dZ', fields[3])):
            raise ValueError('invalid record')
        try:
            datetime.strptime(fields[3], '%Y-%m-%dT%H:%M:%SZ')
        except ValueError as e:
            raise ValueError('invalid timestamp') from e
        if fields[0] in seen:
            raise ValueError('duplicate id')
        seen.add(fields[0])
        tags = []
        for tag in fields[2].split(','):
            tag = tag.strip()
            if tag and tag not in tags:
                tags.append(tag)
        records.append({'id': fields[0], 'title': fields[1], 'tags': tags, 'updated': fields[3]})
    return records

def build_index(text: str) -> dict[str, list[dict[str, object]]]:
    result = {}
    for record in parse_document_feed(text):
        for tag in record['tags']:
            result.setdefault(tag, []).append(record.copy())
    for tag in result:
        result[tag].sort(key=lambda r: (-int(datetime.strptime(r['updated'], '%Y-%m-%dT%H:%M:%SZ').timestamp()), r['id']))
    return dict(sorted(result.items()))

def export_index(text: str, destination: str) -> int:
    index = build_index(text)
    fd, temporary = tempfile.mkstemp(dir=os.path.dirname(os.path.abspath(destination)))
    try:
        with os.fdopen(fd, 'w', encoding='utf-8') as f:
            for tag, documents in index.items():
                f.write(json.dumps({'tag': tag, 'documents': documents}, ensure_ascii=False, separators=(',', ':')) + '\n')
            f.flush()
            os.fsync(f.fileno())
        os.replace(temporary, destination)
        return len(index)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise

