import secrets
from datetime import datetime
_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'

def generate_invite_code(length: int=10) -> str:
    if isinstance(length, bool) or not isinstance(length, int) or length < 4 or (length > 64):
        raise ValueError('invalid length')
    return ''.join((secrets.choice(_ALPHABET) for _ in range(length)))

def find_available_slots(slots: list[dict], target_language: str, page: int=1, page_size: int=10) -> dict:
    if not isinstance(target_language, str) or not target_language:
        raise ValueError('invalid language')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1 or (page_size > 100):
        raise ValueError('invalid page size')
    selected = []
    for item in slots:
        if not isinstance(item, dict) or any((key not in item for key in ('interpreter', 'language', 'start', 'end', 'rating'))):
            raise ValueError('invalid slot')
        if any((not isinstance(item[key], str) or not item[key] for key in ('interpreter', 'language', 'start', 'end'))):
            raise ValueError('invalid slot')
        if isinstance(item['rating'], bool) or not isinstance(item['rating'], (int, float)) or (not 0 <= item['rating'] <= 5):
            raise ValueError('invalid rating')
