    if not isinstance(ambulance_id, str) or not isinstance(station, str):
        raise TypeError('ambulance_id and station must be strings')
    if isinstance(length, bool) or not isinstance(length, int):
        raise TypeError('length must be an integer')
    ambulance_id = ambulance_id.strip()
    station = station.strip()
    if not ambulance_id or not station:
        raise ValueError('ambulance_id and station cannot be empty')
    if length < 6 or length > 32:
        raise ValueError('length must be between 6 and 32')
    code = ''.join((random.choice(_ALPHABET) for _ in range(length)))
    return {'ambulance_id': ambulance_id.upper(), 'station': station, 'code': code, 'status': 'queued'}

