import csv
import datetime
import math
import os
import tempfile
_FIELDS = ['date', 'well_id', 'oil_bbl', 'water_bbl', 'downtime_h', 'water_cut_pct']

def _number(value):
    if isinstance(value, bool) or not isinstance(value, (int, float)) or (not math.isfinite(value)) or (value < 0):
        raise ValueError('invalid production value')
    return float(value)

def _validated(record):
    if not isinstance(record, dict):
        raise ValueError('invalid record')
    try:
        well = record['well_id']
        date = record['date']
        oil = _number(record['oil_bbl'])
        water = _number(record['water_bbl'])
        down = record['downtime_h']
    except (KeyError, TypeError):
        raise ValueError('invalid record')
    if not isinstance(well, str) or not well or (not isinstance(date, str)):
        raise ValueError('invalid record')
    try:
        datetime.date.fromisoformat(date)
    except ValueError:
        raise ValueError('invalid date')
    if isinstance(down, bool) or not isinstance(down, int) or (not 0 <= down <= 24):
        raise ValueError('invalid downtime')
    return (date, well, oil, water, down)

def summarize_production(records: list[dict]) -> list[dict]:
    groups = {}
    try:
        iterator = iter(records)
    except TypeError:
        raise ValueError('invalid records')
    for record in iterator:
        date, well, oil, water, down = _validated(record)
        key = (date, well)
        if key not in groups:
            groups[key] = [0.0, 0.0, 0]
        groups[key][0] += oil
        groups[key][1] += water
        groups[key][2] += down
    result = []
    for (date, well), (oil, water, down) in sorted(groups.items()):
        pct = 0.0 if oil + water == 0 else round(water * 100 / (oil + water), 2)
        result.append({'date': date, 'well_id': well, 'oil_bbl': oil, 'water_bbl': water, 'downtime_h': down, 'water_cut_pct': pct})
    return result

def export_production_report(records: list[dict], output_path: str) -> list[dict]:
    rows = summarize_production(records)
    directory = os.path.dirname(os.path.abspath(output_path))
    fd, temporary = tempfile.mkstemp(dir=directory, prefix='report-')
    try:
        with os.fdopen(fd, 'w', newline='') as stream:
            writer = csv.writer(stream)
            writer.writerow(_FIELDS)
            for row in rows:
                writer.writerow([row['date'], row['well_id'], f"{row['oil_bbl']:.2f}", f"{row['water_bbl']:.2f}", row['downtime_h'], f"{row['water_cut_pct']:.2f}"])
        os.replace(temporary, output_path)
    except Exception:
        try:
            os.unlink(temporary)
        except OSError:
            pass
        raise
    return rows

def read_production_report(path: str) -> list[dict]:
    try:
        with open(path, newline='') as stream:
            reader = csv.DictReader(stream)
            if reader.fieldnames != _FIELDS:
                raise ValueError('invalid header')
            rows = []
            seen = set()
            for raw in reader:
                if any((value is None for value in raw.values())):
                    raise ValueError('invalid row')
                date, well, oil, water, down = _validated({'date': raw['date'], 'well_id': raw['well_id'], 'oil_bbl': float(raw['oil_bbl']), 'water_bbl': float(raw['water_bbl']), 'downtime_h': int(raw['downtime_h'])})
                key = (date, well)
                if key in seen:
                    raise ValueError('duplicate row')
                seen.add(key)
                pct = float(raw['water_cut_pct'])
                if not math.isfinite(pct) or round(water * 100 / (oil + water), 2) != pct if oil + water else pct != 0.0:
                    raise ValueError('invalid percentage')
                rows.append({'date': date, 'well_id': well, 'oil_bbl': oil, 'water_bbl': water, 'downtime_h': down, 'water_cut_pct': pct})
            return rows
    except (OSError, csv.Error, ValueError, TypeError, OverflowError):
        raise ValueError('invalid report')

