import datetime
import hashlib
import hmac
import json

def verify_and_summarize(payload: str, signature: str, secret: str) -> dict:
    expected = hmac.new(secret.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not isinstance(signature, str) or not hmac.compare_digest(expected, signature):
        raise PermissionError('invalid signature')
    try:
        data = json.loads(payload)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(data, dict) or not isinstance(data.get('employees'), list):
        raise ValueError('invalid employees')
    groups = {}
    ids = set()
    for employee in data['employees']:
        if not isinstance(employee, dict):
            raise ValueError('invalid employee')
        required = ('id', 'department', 'status', 'start_date', 'salary')
        if any((key not in employee for key in required)):
            raise ValueError('missing employee field')
        ident = employee['id']
        department = employee['department']
        status = employee['status']
        start = employee['start_date']
        salary = employee['salary']
        if not isinstance(ident, str) or not ident or (not isinstance(department, str)) or (not department):
            raise ValueError('invalid employee text')
        if ident in ids or status not in ('pending', 'complete'):
            raise ValueError('invalid employee')
        if not isinstance(start, str) or len(start) != 10 or start[4] != '-' or (start[7] != '-'):
            raise ValueError('invalid date')
        try:
            parsed = datetime.date.fromisoformat(start)
        except ValueError as exc:
            raise ValueError('invalid date') from exc
        if parsed.isoformat() != start or isinstance(salary, bool) or (not isinstance(salary, int)) or (salary < 0):
            raise ValueError('invalid employee value')
        ids.add(ident)
        group = groups.setdefault(department, {'department': department, 'employees': 0, 'completed': 0, 'earliest_start': start, 'total_salary': 0})
        group['employees'] += 1
        group['completed'] += status == 'complete'
        group['earliest_start'] = min(group['earliest_start'], start)
        group['total_salary'] += salary
    departments = list(groups.values())
    departments.sort(key=lambda item: (-item['employees'], item['department']))
    return {'total': len(data['employees']), 'departments': departments}

