def make_payload(events):
    return json.dumps({'events': events}, separators=(',', ':')).encode()

def sign(payload, secret=b'cleaning-key'):
    return 'sha256=' + hmac.new(secret, payload, hashlib.sha256).hexdigest()

def event(order_id, status, timestamp, minutes, supplies):
    return {'order_id': order_id, 'status': status, 'timestamp': timestamp, 'minutes': minutes, 'supplies': supplies}

def test_parse_event_normalizes_timestamp_and_supplies():
