    got = parse_event(raw, 7)
    assert got == {'order_id': 'WO-4', 'status': 'scheduled', 'timestamp': '2025-03-02T08:15:20Z', 'minutes': 35, 'supplies': [{'name': 'Mop', 'quantity': 2}], 'position': 7}

