    provided = signature[7:]
    if len(provided) != hashlib.sha256().digest_size * 2:
        return False
    try:
        int(provided, 16)
    except ValueError:
        return False
    expected = hmac.new(secret.encode('utf-8'), payload, hashlib.sha256).hexdigest()
    return provided == expected

