import csv
import math
import os
import tempfile
from collections import defaultdict

def export_return_summary(records: list[dict], destination: str) -> int:
    groups = defaultdict(list)
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('record must be a dictionary')
        required = {'return_id', 'customer', 'warehouse', 'weight_kg', 'status'}
        if not required.issubset(record):
            raise ValueError('missing field')
        status = record['status']
        weight = record['weight_kg']
        if status not in {'approved', 'pending', 'rejected'}:
            raise ValueError('invalid status')
        if isinstance(weight, bool) or not isinstance(weight, (int, float)) or (not math.isfinite(weight)) or (weight < 0):
            raise ValueError('invalid weight')
        if status == 'approved':
            groups[record['warehouse']].append(float(weight))
    rows = []
    for warehouse, weights in groups.items():
        total = sum(weights)
        rows.append((warehouse, len(weights), total, total / len(weights)))
    rows.sort(key=lambda row: (-row[1], row[0]))
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent, prefix='.returns-')
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['warehouse', 'return_count', 'total_weight_kg', 'average_weight_kg'])
            for warehouse, count, total, average in rows:
                writer.writerow([warehouse, count, f'{total:.2f}', f'{average:.2f}'])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return sum((row[1] for row in rows))

