import csv
import datetime
import math
import os
import tempfile

def export_review_summary(reviews: list[dict], destination: str, min_score: float=0.0) -> int:
    if not isinstance(reviews, list):
        raise ValueError('reviews must be a list')
    if isinstance(min_score, bool) or not isinstance(min_score, (int, float)) or (not math.isfinite(min_score)) or (not 0 <= min_score <= 100):
        raise ValueError('invalid minimum score')
    grouped = {}
    for review in reviews:
        if not isinstance(review, dict):
            raise ValueError('invalid review')
        try:
            employee = review['employee']
            department = review['department']
            score = review['score']
            review_date = review['review_date']
        except KeyError as exc:
            raise ValueError('missing review field') from exc
        if not isinstance(employee, str) or not employee:
            raise ValueError('invalid employee')
        if not isinstance(department, str) or not department:
            raise ValueError('invalid department')
        if isinstance(score, bool) or not isinstance(score, (int, float)) or (not math.isfinite(score)) or (not 0 <= score <= 100):
            raise ValueError('invalid score')
        if not isinstance(review_date, str):
            raise ValueError('invalid date')
        try:
            parsed_date = datetime.date.fromisoformat(review_date)
        except ValueError as exc:
            raise ValueError('invalid date') from exc
        if score >= min_score:
            item = grouped.setdefault(department, {'employees': set(), 'scores': [], 'latest': parsed_date})
            item['employees'].add(employee)
            item['scores'].append(score)
            if parsed_date > item['latest']:
                item['latest'] = parsed_date
    rows = []
    for department, item in grouped.items():
        average = round(sum(item['scores']) / len(item['scores']), 2)
        rows.append((department, len(item['employees']), average, item['latest'].isoformat()))
    rows.sort(key=lambda row: (-row[2], row[0]))
    parent = os.path.dirname(os.path.abspath(destination))
    descriptor, temporary = tempfile.mkstemp(dir=parent)
    try:
        with os.fdopen(descriptor, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['department', 'employee_count', 'average_score', 'latest_review'])
            for department, count, average, latest in rows:
                writer.writerow([department, count, f'{average:.2f}', latest])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.close(descriptor)
        except OSError:
            pass
        try:
            os.unlink(temporary)
        except OSError:
            pass
        raise
    return len(rows)

