            raise ValueError('missing requester field')
    matches = [d for d in devices if isinstance(d, dict) and d.get('id') == device_id]
    if len(matches) != 1:
        raise ValueError('device not found or duplicated')
    device = matches[0]
    if device.get('status') != 'new':
        raise ValueError('device is not new')
    if not all((isinstance(value, bool) for value in settings.values())):
        raise TypeError('settings values must be boolean')
