import base64
import hashlib
import hmac
import os

def hash_pin(pin: str) -> str:
    if not isinstance(pin, str) or not pin.isdigit() or (not 4 <= len(pin) <= 12):
        raise ValueError('invalid pin')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return base64.b64encode(salt).decode() + '$' + base64.b64encode(digest).decode()

def verify_pin(pin: str, stored: str) -> bool:
    if not isinstance(pin, str) or not pin.isdigit() or (not 4 <= len(pin) <= 12):
        return False
    try:
        salt_text, digest_text = stored.split('$', 1)
        salt = base64.b64decode(salt_text.encode(), validate=True)
        expected = base64.b64decode(digest_text.encode(), validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (AttributeError, ValueError, TypeError):
        return False

def summarize_bookings(bookings: list[dict], page: int=1, page_size: int=20) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    groups = {}
    for booking in bookings:
        if not isinstance(booking, dict) or not isinstance(booking.get('id'), str):
            raise ValueError('invalid booking')
        language = booking.get('language')
        minutes = booking.get('minutes')
        status = booking.get('status')
        if not isinstance(language, str) or not language or (not isinstance(minutes, int)) or isinstance(minutes, bool) or (minutes <= 0) or (status not in ('confirmed', 'cancelled')):
            raise ValueError('invalid booking')
        if status == 'confirmed':
            item = groups.setdefault(language, [0, 0])
            item[0] += 1
            item[1] += minutes
    result = []
    for language, (count, minutes) in groups.items():
        result.append({'language': language, 'bookings': count, 'minutes': minutes, 'average_minutes': round(minutes / count, 2)})
    result.sort(key=lambda item: (-item['bookings'], item['language']))
    start = (page - 1) * page_size
    return {'total': sum((item['bookings'] for item in result)), 'items': result[start:start + page_size]}

