import os

def _credential(pin):
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return salt.hex() + ':' + digest.hex()

def create_collar(collar_id: str, pin: str, species: str) -> dict:
    if not isinstance(collar_id, str) or not collar_id.strip() or (not isinstance(species, str)) or (not species.strip()):
