        raise ValueError('invalid pin')
    return {'collar_id': collar_id, 'species': species, 'credential': _credential(pin), 'readings': []}

def verify_collar(collar: dict, pin: str) -> bool:
    try:
        if not isinstance(pin, str):
            return False
        salt, value = collar['credential'].split(':')
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), bytes.fromhex(salt), 100000).hex()
        return hmac.compare_digest(actual, value)
    except (KeyError, TypeError, ValueError):
        return False

def _valid_reading(r):
    if not isinstance(r, dict) or set(r) != {'timestamp', 'latitude', 'longitude', 'temperature', 'battery'}:
        return False
    if isinstance(r['timestamp'], bool) or not isinstance(r['timestamp'], int) or r['timestamp'] < 0:
        return False
    for key, low, high in (('latitude', -90, 90), ('longitude', -180, 180), ('temperature', -80, 80), ('battery', 0, 100)):
        if isinstance(r[key], bool) or not isinstance(r[key], (int, float)) or (not low <= r[key] <= high):
            return False
    return True

def record_reading(collar: dict, reading: dict) -> None:
    if not isinstance(collar, dict) or not isinstance(collar.get('readings'), list) or (not _valid_reading(reading)):
        raise ValueError('invalid reading')
    items = [r for r in collar['readings'] if r.get('timestamp') != reading['timestamp']]
    items.append(dict(reading))
    collar['readings'][:] = sorted(items, key=lambda r: r['timestamp'])

def daily_summary(collar: dict, start: int, end: int) -> list[dict]:
    if isinstance(start, bool) or isinstance(end, bool) or (not isinstance(start, int)) or (not isinstance(end, int)) or (start < 0) or (end <= start):
