    result = []
    for day in sorted(groups):
        rows = groups[day]
        distance = 0.0
        for a, b in zip(rows, rows[1:]):
            p, q = (math.radians(a['latitude']), math.radians(b['latitude']))
            dp = math.radians(b['latitude'] - a['latitude'])
            dl = math.radians(b['longitude'] - a['longitude'])
            x = math.sin(dp / 2) ** 2 + math.cos(p) * math.cos(q) * math.sin(dl / 2) ** 2
            distance += 6371.0 * 2 * math.atan2(math.sqrt(x), math.sqrt(1 - x))
        result.append({'day': day, 'count': len(rows), 'average_temperature': round(sum((r['temperature'] for r in rows)) / len(rows), 2), 'minimum_battery': min((r['battery'] for r in rows)), 'distance_km': round(distance, 3)})
