from solution import evaluate_expression, rank_claims, region_totals
import pytest


def test_evaluate_arithmetic_precedence_and_variables():
    values = {'amount': 1200, 'deductible': 250, 'factor': 1.5}
    assert evaluate_expression('(amount - deductible) * factor / 2', values) == 712.5
    assert values == {'amount': 1200, 'deductible': 250, 'factor': 1.5}


def test_evaluate_boolean_short_circuit_and_chained_comparison():
    values = {'amount': 900, 'days_open': 12, 'vehicle_value': 20000}
    assert evaluate_expression('amount >= 500 and 5 < days_open < 30', values) is True
    assert evaluate_expression('amount < 0 or vehicle_value > 10000 and not days_open == 0', values) is True


def test_evaluate_named_functions_and_python_result_types():
    assert evaluate_expression('max(amount, deductible) + min(3, 8)', {'amount': 400, 'deductible': 600}) == 603
    assert evaluate_expression('round(value / 3, 2)', {'value': 10}) == 3.33
    assert evaluate_expression('amount == 4', {'amount': 4}) is True


def test_evaluate_invalid_expression_and_unknown_name():
    with pytest.raises(ValueError): evaluate_expression('amount + missing', {'amount': 4})
    with pytest.raises(ValueError): evaluate_expression('amount ** 2', {'amount': 4})
    with pytest.raises(ValueError): evaluate_expression('min()', {'amount': 4})


def test_rank_claims_sorting_limit_and_expression_fields():
    claims = [
        {'id': 'C3', 'amount': 800, 'days_open': 20, 'region': 'West', 'vehicle_value': 18000, 'claimant': 'A'},
        {'id': 'C1', 'amount': 1200, 'days_open': 5, 'region': 'East', 'vehicle_value': 25000, 'claimant': 'B'},
        {'id': 'C2', 'amount': 1200, 'days_open': 10, 'region': 'East', 'vehicle_value': 22000, 'claimant': 'C'},
        {'id': 'C4', 'amount': 500, 'days_open': 40, 'region': 'South', 'vehicle_value': 9000, 'claimant': 'D'}]
    assert rank_claims(claims, 'amount >= 800 and days_open < 30', 'amount / vehicle_value * 100000', 3) == ['C2', 'C1', 'C3']
    assert rank_claims(claims, "claimant == 'A'", 'amount', 10) == ['C3']
    assert rank_claims(claims, 'amount > 0', 'amount', 0) == []


def test_rank_claims_ties_and_negative_limit():
    claims = [{'id': x, 'amount': 100 if x != 'c' else 90, 'days_open': 1, 'region': 'X', 'vehicle_value': 1, 'claimant': 'x'} for x in ['b', 'a', 'c']]
    assert rank_claims(claims, 'True', 'amount', 10) == ['a', 'b', 'c']
    with pytest.raises(ValueError): rank_claims(claims, 'True', 'amount', -1)


