def export_incident_report(incidents: list[dict], output_path: str, min_severity: int=1) -> dict:
    if isinstance(min_severity, bool) or not isinstance(min_severity, int) or (not 1 <= min_severity <= 5):
        raise ValueError('invalid minimum severity')
    parsed = []
    for item in incidents:
        try:
            incident_id = item['incident_id']
            vessel = item['vessel']
            category = item['category']
            severity = item['severity']
            date_text = item['date']
            fatalities = item['fatalities']
        except (KeyError, TypeError):
            raise ValueError('invalid incident')
        if any((not isinstance(value, str) or not value for value in (incident_id, vessel, category, date_text))):
            raise ValueError('invalid incident')
        if isinstance(severity, bool) or not isinstance(severity, int) or (not 1 <= severity <= 5):
            raise ValueError('invalid incident')
        if isinstance(fatalities, bool) or not isinstance(fatalities, int) or fatalities < 0:
            raise ValueError('invalid incident')
        try:
            date_value = datetime.date.fromisoformat(date_text)
        except ValueError:
            raise ValueError('invalid incident')
        if severity >= min_severity:
            parsed.append((date_value, incident_id, vessel, category, severity, date_text, fatalities))
    parsed.sort(key=lambda row: (row[0], row[4], row[1]), reverse=False)
    parsed.sort(key=lambda row: (row[0], row[4]), reverse=True)
    parsed.sort(key=lambda row: row[1] if row[0] == row[0] else row[1])
    parsed.sort(key=lambda row: (-row[0].toordinal(), -row[4], row[1]))
    categories = {}
    for row in parsed:
        categories[row[3]] = categories.get(row[3], 0) + 1
    categories = dict(sorted(categories.items()))
    parent = os.path.dirname(os.path.abspath(output_path))
    fd, temporary_path = tempfile.mkstemp(dir=parent)
    try:
        with os.fdopen(fd, 'w', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['incident_id', 'vessel', 'category', 'severity', 'date', 'fatalities'])
            for _, incident_id, vessel, category, severity, date_text, fatalities in parsed:
                writer.writerow([incident_id, vessel, category, severity, date_text, fatalities])
        os.replace(temporary_path, output_path)
    except Exception:
        try:
            os.unlink(temporary_path)
        except FileNotFoundError:
            pass
        raise
    return {'count': len(parsed), 'fatalities': sum((row[6] for row in parsed)), 'by_category': categories}

