    clauses = []
    params = []
    if search:
        clauses.append('(patient_name LIKE ? COLLATE NOCASE OR medication LIKE ? COLLATE NOCASE)')
        params.extend([f'%{search}%', f'%{search}%'])
    if status is not None:
        clauses.append('status = ?')
        params.append(status)
    query = 'SELECT id, patient_name, medication, quantity, status, quantity * unit_price AS total_cost FROM prescriptions'
    if clauses:
        query += ' WHERE ' + ' AND '.join(clauses)
