import os
from decimal import Decimal, InvalidOperation

def write_cart_invoice(base_dir: str, filename: str, items: list[tuple[str, float, int]]) -> str:
    if not filename or os.path.isabs(filename):
        raise ValueError('filename must be relative and non-empty')
    rows = []
    total = Decimal('0')
    for sku, price, quantity in items:
        if not isinstance(sku, str) or not sku:
            raise ValueError('invalid sku')
        if not isinstance(quantity, int) or isinstance(quantity, bool) or quantity <= 0:
            raise ValueError('invalid quantity')
        try:
            unit = Decimal(str(price))
        except (InvalidOperation, ValueError):
            raise ValueError('invalid price')
        if unit < 0:
            raise ValueError('invalid price')
        line_total = unit * quantity
        rows.append((sku, quantity, unit, line_total))
        total += line_total
    base = os.path.realpath(base_dir)
    output = os.path.realpath(os.path.join(base, filename))
    if os.path.commonpath((base, output)) != base:
        raise ValueError('filename is outside base directory')
    os.makedirs(os.path.dirname(output), exist_ok=True)
    with open(output, 'w', encoding='utf-8') as handle:
        handle.write('Invoice\nSKU,Quantity,Unit Price,Line Total\n')
        for sku, quantity, unit, line_total in rows:
            handle.write(f'{sku},{quantity},${unit:.2f},${line_total:.2f}\n')
        handle.write(f'Total,${total:.2f}\n')
    return output

