import hashlib
import hmac
import math
import os

def _password_data(password):
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 100000)
    return (salt.hex(), digest.hex())

def create_contract_record(narrator: str, title: str, royalty_percent: float, password: str) -> dict:
    if not isinstance(narrator, str) or not narrator.strip():
        raise ValueError('invalid narrator')
    if not isinstance(title, str) or not title.strip():
        raise ValueError('invalid title')
    if not isinstance(royalty_percent, (int, float)) or isinstance(royalty_percent, bool) or (not math.isfinite(royalty_percent)) or (not 0 <= royalty_percent <= 100):
        raise ValueError('invalid royalty')
    if not isinstance(password, str) or not password:
        raise ValueError('invalid password')
    salt, digest = _password_data(password)
    return {'narrator': narrator.strip(), 'title': title.strip(), 'royalty_percent': round(float(royalty_percent), 2), 'password_salt': salt, 'password_digest': digest}

def verify_contract_password(record: dict, password: str) -> bool:
    try:
        if not isinstance(record, dict) or not isinstance(password, str):
            return False
        salt = bytes.fromhex(record['password_salt'])
        expected = bytes.fromhex(record['password_digest'])
        actual = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError):
        return False

def summarize_contracts(records: list[dict], page: int, page_size: int) -> list[dict]:
    if not isinstance(page, int) or isinstance(page, bool) or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (page < 1) or (not 1 <= page_size <= 100):
        raise ValueError('invalid pagination')
    groups = {}
    for record in records:
        try:
            narrator = record['narrator']
            value = record['royalty_percent']
            if not isinstance(narrator, str) or not isinstance(value, (int, float)) or isinstance(value, bool) or (not math.isfinite(value)):
                raise ValueError
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid record')
        item = groups.setdefault(narrator, [])
        item.append(float(value))
    result = []
    for narrator, values in groups.items():
        total = round(sum(values), 2)
        result.append({'narrator': narrator, 'contract_count': len(values), 'total_royalty_percent': total, 'average_royalty_percent': round(total / len(values), 2)})
    result.sort(key=lambda x: (-x['total_royalty_percent'], x['narrator']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

