        assert [x['date'] for x in result] == ['2024-02-03', '2024-02-01', '2024-02-02']
    finally:
        os.unlink(path)

def test_pagination_is_one_based_and_applied_after_sorting():
    path = make_file('timestamp,station,flow_m3,turbidity_ntu\n2024-01-01T00:00:00,A,1,1\n2024-01-02T00:00:00,A,1,2\n2024-01-03T00:00:00,A,1,3\n2024-01-04T00:00:00,A,1,4\n')
