from collections import defaultdict

def summarize_readings(path: str, station: str, page: int=1, page_size: int=10) -> list[dict]:
    if not station or page < 1 or page_size < 1 or (page_size > 100):
        raise ValueError('invalid arguments')
    try:
        with open(path, 'rb'):
            pass
    except FileNotFoundError:
        raise
    result = subprocess.run(['grep', '-F', ',' + station + ',', path], capture_output=True, text=True)
    if result.returncode not in (0, 1):
        raise subprocess.CalledProcessError(result.returncode, result.args)
    groups = defaultdict(list)
    for row in csv.reader(result.stdout.splitlines()):
        if len(row) != 4:
            raise ValueError('invalid record')
        try:
            date = datetime.datetime.fromisoformat(row[0].replace('Z', '+00:00')).date().isoformat()
            flow = float(row[2])
            turbidity = float(row[3])
        except (ValueError, TypeError):
            raise ValueError('invalid record')
        if row[1] == station:
            groups[date].append((flow, turbidity))
    summaries = []
    for date, values in groups.items():
        total = sum((x[0] for x in values))
        average = sum((x[1] for x in values)) / len(values)
        summaries.append({'date': date, 'count': len(values), 'total_flow': round(total, 2), 'avg_turbidity': round(average, 2)})
    summaries.sort(key=lambda x: (-x['avg_turbidity'], x['date']))
    start = (page - 1) * page_size
    return summaries[start:start + page_size]

