import re
import xml.etree.ElementTree as ET
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def _cents(value):
    try:
        d = Decimal(value)
    except (InvalidOperation, TypeError):
        raise ValueError('invalid amount')
    if not d.is_finite() or d < 0 or d.quantize(Decimal('0.01')) != d:
        raise ValueError('invalid amount')
    return int(d * 100)

def parse_payroll(xml_text: str) -> list[dict]:
    try:
        root = ET.fromstring(xml_text)
    except Exception as exc:
        raise ValueError('invalid xml') from exc
    if root.tag != 'payroll':
        raise ValueError('invalid root')
    result = []
    seen = set()
    for employee in root:
        if employee.tag != 'employee':
            raise ValueError('invalid employee')
        ident = employee.get('id')
        name = employee.get('name')
        if not ident or not name or ident in seen:
            raise ValueError('invalid employee')
        seen.add(ident)
        pays = []
        for pay in employee:
            if pay.tag != 'pay' or not re.fullmatch('\\d{4}-(0[1-9]|1[0-2])', pay.get('period', '')):
                raise ValueError('invalid pay')
            gross = _cents(pay.get('gross'))
            pension = _cents(pay.get('pension'))
            bonus = 0
            children = list(pay)
            if len(children) > 1 or (children and children[0].tag != 'bonus'):
                raise ValueError('invalid bonus')
            if children:
                bonus = _cents(children[0].get('amount'))
            pays.append({'period': pay.get('period'), 'gross': gross, 'pension': pension, 'bonus': bonus})
        if not pays:
            raise ValueError('no pays')
        result.append({'id': ident, 'name': name, 'pays': pays})
    return result

def calculate_payroll(records: list[dict], brackets: list[tuple[int | None, str]]) -> list[dict]:
    if not brackets or brackets[-1][0] is not None:
        raise ValueError('invalid brackets')
    previous = -1
    parsed = []
    for limit, rate in brackets:
        if limit is not None and (not isinstance(limit, int) or limit <= previous):
            raise ValueError('invalid brackets')
        try:
            r = Decimal(rate)
        except (InvalidOperation, TypeError):
            raise ValueError('invalid brackets')
        if not r.is_finite() or r < 0 or r > 1:
            raise ValueError('invalid brackets')
        parsed.append((limit, r))
        if limit is not None:
            previous = limit
    output = []
    for record in records:
        try:
            gross = sum((p['gross'] for p in record['pays']))
            bonus = sum((p['bonus'] for p in record['pays']))
            pension = sum((p['pension'] for p in record['pays']))
        except Exception as exc:
            raise ValueError('invalid records') from exc
        taxable = gross + bonus - pension
        if taxable < 0:
            raise ValueError('negative taxable income')
        tax = Decimal(0)
        start = 0
        remaining = taxable
        for limit, rate in parsed:
            span = remaining if limit is None else min(remaining, limit - start)
            if span > 0:
                tax += Decimal(span) * rate
                remaining -= span
            if limit is not None:
                start = limit
        tax_cents = int(tax.quantize(Decimal('1'), rounding=ROUND_HALF_UP))
        output.append({'id': record['id'], 'name': record['name'], 'gross': gross, 'bonus': bonus, 'pension': pension, 'taxable': taxable, 'tax': tax_cents, 'net': gross + bonus - pension - tax_cents})
    return output

