import hashlib
import hmac
import os
from decimal import Decimal, ROUND_HALF_UP

def create_campaign_credential(secret: str) -> dict:
    if not isinstance(secret, str) or not secret:
        raise ValueError('invalid secret')
    salt = os.urandom(16)
    iterations = 100000
