import ast
import operator

def _value(node, names):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in names:
            raise ValueError('unknown name')
        return names[node.id]
    if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub, ast.Not):
        value = _value(node.operand, names)
        return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
    if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
        return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](_value(node.left, names), _value(node.right, names))
    if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
        values = [_value(x, names) for x in node.values]
        result = values[0]
        for value in values[1:]:
            result = value if (bool(result) if isinstance(node.op, ast.And) else not bool(result)) else result
        return result
    if isinstance(node, ast.Compare):
        left = _value(node.left, names)
        result = True
        for op, item in zip(node.ops, node.comparators):
            right = _value(item, names)
            result = result and {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}[type(op)](left, right)
            left = right
        return result
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
        return {'min': min, 'max': max, 'round': round}[node.func.id](*[_value(x, names) for x in node.args])
    raise ValueError('unsupported expression')

def dispatch_orders(orders: list[dict], expression: str, variables: dict[str, float], page: int=1, page_size: int=10) -> list[str]:
    if page < 1 or page_size < 1:
        raise ValueError('invalid page')
    try:
        tree = ast.parse(expression, mode='eval').body
        selected = []
        for order in orders:
            names = dict(variables)
            names.update(order)
            if _value(tree, names):
                priority = order['tip'] * 100 - order['distance'] * 10 - order['prep_minutes']
                selected.append((priority, order['id']))
    except Exception as exc:
        raise ValueError('invalid expression') from exc
    selected.sort(key=lambda item: (-item[0], item[1]))
    start = (page - 1) * page_size
    return [item[1] for item in selected[start:start + page_size]]

