    values: list[object] = [vessel_id]
    if species is not None:
        sql += ' AND c.species = ?'
        values.append(species)
    sql += f' GROUP BY c.species ORDER BY {order}, species ASC'
    rows = conn.execute(sql, values).fetchall()
