import math
import subprocess

def parse_record(line: str) -> tuple[str, int, float]:
    if not isinstance(line, str) or not line.strip():
        raise ValueError('invalid record')
    parts = line.split('|')
    if len(parts) != 3:
        raise ValueError('invalid record')
    beneficiary, year_text, amount_text = (part.strip() for part in parts)
    if not beneficiary:
        raise ValueError('invalid beneficiary')
    try:
        year = int(year_text)
        amount = float(amount_text)
    except (TypeError, ValueError):
        raise ValueError('invalid record')
    if not 1900 <= year <= 2100 or amount < 0 or (not math.isfinite(amount)):
        raise ValueError('invalid record')
    return (beneficiary, year, amount)

def summarize_records(records: list[tuple[str, int, float]], year: int, threshold: float) -> list[tuple[str, float, int]]:
    if not 1900 <= year <= 2100 or threshold < 0 or (not math.isfinite(threshold)):
        raise ValueError('invalid parameters')
    totals: dict[str, list[float | int]] = {}
    for beneficiary, record_year, amount in records:
        if record_year == year:
            if beneficiary not in totals:
                totals[beneficiary] = [0.0, 0]
            totals[beneficiary][0] += amount
            totals[beneficiary][1] += 1
    result = [(name, values[0], values[1]) for name, values in totals.items() if values[0] >= threshold]
    result.sort(key=lambda item: (-item[1], item[0]))
    return result

def generate_report(path: str, year: int, threshold: float) -> str:
    completed = subprocess.run(['sort', '-t', '|', '-k1,1', path], capture_output=True, text=True, check=True)
    records = [parse_record(line) for line in completed.stdout.splitlines() if line.strip()]
    summaries = summarize_records(records, year, threshold)
    return '\n'.join((f'{name}|{amount:.2f}|{count}' for name, amount, count in summaries))

