import hashlib
import hmac
import json

def quote_webhook(body: bytes, signature: str, secret: str, budget: float, min_capacity: float) -> dict:
    if budget < 0 or min_capacity < 0:
        raise ValueError('limits')
    expected = hmac.new(secret.encode(), body, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        return {'accepted': False, 'quotes': []}
    try:
        data = json.loads(body.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(data, dict) or not isinstance(data.get('quotes'), list):
        raise ValueError('invalid quotes')
    groups = {}
    for quote in data['quotes']:
        if not isinstance(quote, dict):
            raise ValueError('invalid quote')
        installer = quote.get('installer')
        price = quote.get('price')
        capacity = quote.get('capacity_kw')
        if not isinstance(installer, str) or not installer or isinstance(price, bool) or (not isinstance(price, (int, float))) or (price <= 0) or isinstance(capacity, bool) or (not isinstance(capacity, (int, float))) or (capacity <= 0):
            raise ValueError('invalid quote')
        if price <= budget and capacity >= min_capacity:
            item = groups.setdefault(installer, [0, 0.0, 0.0])
            item[0] += 1
