from datetime import datetime
from copy import deepcopy

def _fields(line):
    out = []
    cur = []
    escaped = False
    for ch in line:
        if escaped:
            cur.append(ch)
            escaped = False
        elif ch == '\\':
            escaped = True
        elif ch == '|':
            out.append(''.join(cur))
            cur = []
        else:
            cur.append(ch)
    if escaped:
        raise ValueError('dangling escape')
    out.append(''.join(cur))
    return out

def parse_shift_feed(text: str) -> list[dict]:
    result = []
    ids = set()
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields = _fields(raw)
        if len(fields) != 6 or any((x == '' for x in fields)):
            raise ValueError('malformed record')
        try:
            start = datetime.fromisoformat(fields[2].replace('Z', '+00:00'))
            end = datetime.fromisoformat(fields[3].replace('Z', '+00:00'))
        except ValueError as exc:
            raise ValueError('invalid timestamp') from exc
        if fields[0] in ids or end <= start:
            raise ValueError('invalid shift')
        ids.add(fields[0])
        result.append({'id': fields[0], 'employee': fields[1], 'start': start, 'end': end, 'location': fields[4], 'tenant': fields[5], 'status': 'open'})
    result.sort(key=lambda x: (x['start'], x['id']))
    previous = {}
    for shift in result:
        old = previous.get(shift['employee'])
        if old and shift['start'] < old['end']:
            raise ValueError('overlap')
        previous[shift['employee']] = shift
    return result

def approve_swap(shifts: list[dict], requester: dict, shift_id: str, replacement_id: str) -> list[dict]:
    result = deepcopy(shifts)
    found = {x['id']: x for x in result}
    if shift_id not in found or replacement_id not in found or shift_id == replacement_id:
        raise ValueError('unknown shift')
    first, second = (found[shift_id], found[replacement_id])
    if first['status'] != 'open' or second['status'] != 'open':
        raise ValueError('not open')
    if requester.get('tenant') != first.get('tenant') or requester.get('tenant') != second.get('tenant'):
        raise PermissionError('not permitted')
    if requester.get('id') != first.get('employee') and 'scheduler' not in requester.get('roles', []):
        raise PermissionError('not permitted')
    if first['tenant'] != second['tenant'] or first['start'].date() != second['start'].date() or first['employee'] == second['employee']:
        raise ValueError('invalid swap')
    first['employee'], second['employee'] = (second['employee'], first['employee'])
    first['status'] = second['status'] = 'approved'
    previous = {}
    for shift in sorted(result, key=lambda x: (x['start'], x['id'])):
        old = previous.get(shift['employee'])
        if old and shift['start'] < old['end']:
            raise ValueError('overlap')
        previous[shift['employee']] = shift
    return result

