import re
import subprocess
_BARCODE = re.compile('[A-Z0-9-]+\\Z')
_LOCATION = re.compile('[A-Za-z0-9_-]+\\Z')

def parse_scan_line(line: str) -> tuple[str, str, int]:
    fields = line.split(',')
    if len(fields) != 3:
        raise ValueError('invalid scan record')
    barcode, location, quantity_text = fields
    if not _BARCODE.fullmatch(barcode) or not _LOCATION.fullmatch(location):
        raise ValueError('invalid scan record')
    try:
        quantity = int(quantity_text, 10)
    except ValueError as exc:
        raise ValueError('invalid scan record') from exc
    if quantity <= 0:
        raise ValueError('invalid scan record')
    return (barcode, location, quantity)

def inventory_report(paths: list[str], warehouse: str | None=None) -> list[dict[str, object]]:
    if not paths:
        return []
    command = ['sort', '-t,', '-k1,1', '-k2,2', *paths]
    completed = subprocess.run(command, capture_output=True, text=True, check=True)
    grouped: dict[tuple[str, str], list[int]] = {}
    for line in completed.stdout.splitlines():
        if not line:
            continue
        barcode, location, quantity = parse_scan_line(line)
        if warehouse is not None and location != warehouse:
            continue
        key = (barcode, location)
        if key not in grouped:
            grouped[key] = [0, 0]
        grouped[key][0] += quantity
        grouped[key][1] += 1
    result = []
    for (barcode, location), values in grouped.items():
        result.append({'barcode': barcode, 'location': location, 'quantity': values[0], 'scans': values[1]})
    return result

def inventory_totals(paths: list[str], warehouse: str | None=None) -> dict[str, int]:
    totals: dict[str, int] = {}
    for record in inventory_report(paths, warehouse):
        location = record['location']
        totals[location] = totals.get(location, 0) + record['quantity']
    return totals

