import csv
import os
import tempfile
from decimal import Decimal, InvalidOperation

def parse_booking_line(line: str) -> dict:
    fields = []
    current = []
    escaped = False
    for char in line.rstrip('\n'):
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current).strip())
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('incomplete escape')
    fields.append(''.join(current).strip())
    if len(fields) != 6 or any((not value for value in fields)):
        raise ValueError('invalid booking line')
    try:
        price = Decimal(fields[5])
    except InvalidOperation as exc:
        raise ValueError('invalid price') from exc
    if not price.is_finite() or price < 0 or price.as_tuple().exponent < -2:
        raise ValueError('invalid price')
    return dict(zip(('id', 'customer', 'movie', 'showtime', 'seat'), fields[:5]), price=price)

def summarize_bookings(bookings: list[dict]) -> list[dict]:
    groups = {}
    required = ('id', 'customer', 'movie', 'showtime', 'seat', 'price')
    for booking in bookings:
        if any((key not in booking for key in required)):
            raise ValueError('missing booking field')
        status = booking.get('status', 'confirmed')
        if status == 'cancelled':
            continue
        if status != 'confirmed':
            raise ValueError('invalid status')
        try:
            price = Decimal(str(booking['price']))
        except (InvalidOperation, ValueError, TypeError) as exc:
            raise ValueError('invalid price') from exc
        if not price.is_finite() or price < 0 or price.as_tuple().exponent < -2:
            raise ValueError('invalid price')
        if any((not str(booking[key]) for key in ('movie', 'showtime', 'seat'))):
            raise ValueError('empty booking field')
        key = (str(booking['movie']), str(booking['showtime']))
        if key not in groups:
            groups[key] = [0, Decimal('0'), []]
        groups[key][0] += 1
        groups[key][1] += price
        groups[key][2].append(str(booking['seat']))
    result = []
    for (movie, showtime), (count, revenue, seats) in sorted(groups.items()):
        result.append({'movie': movie, 'showtime': showtime, 'confirmed_count': count, 'seats': ','.join(seats), 'revenue': f'{revenue:.2f}'})
    return result

def export_booking_report(bookings: list[dict], destination: str) -> list[dict]:
    summary = summarize_bookings(bookings)
    fd, temporary = tempfile.mkstemp(prefix='booking-', suffix='.csv', dir=os.path.dirname(destination) or None)
    os.close(fd)
    try:
        with open(temporary, 'w', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['movie', 'showtime', 'confirmed_count', 'seats', 'revenue'])
            for row in summary:
                writer.writerow([row['movie'], row['showtime'], row['confirmed_count'], row['seats'], row['revenue']])
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return summary

