import csv
import datetime
import os
import tempfile

def export_release_report(releases: list[dict], destination: str, environment: str='production', page: int=1, page_size: int=10) -> dict:
    if not isinstance(releases, list):
        raise TypeError('releases must be a list')
    if not isinstance(environment, str) or not environment:
        raise ValueError('invalid environment')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    allowed = {'pending', 'successful', 'failed', 'cancelled'}
    checked = []
    required = {'release_id', 'version', 'environment', 'status', 'deployed_at', 'duration_seconds'}
    for item in releases:
        if not isinstance(item, dict):
            raise TypeError('record must be a dictionary')
        if not required.issubset(item):
            raise ValueError('missing field')
        for key in ('release_id', 'version', 'environment', 'status', 'deployed_at'):
            if not isinstance(item[key], str):
                raise ValueError('invalid field')
        if item['status'] not in allowed:
            raise ValueError('invalid status')
        if isinstance(item['duration_seconds'], bool) or not isinstance(item['duration_seconds'], int) or item['duration_seconds'] < 0:
            raise ValueError('invalid duration')
        try:
            parsed = datetime.datetime.fromisoformat(item['deployed_at'])
        except (TypeError, ValueError):
            raise ValueError('invalid datetime')
        checked.append((item, parsed))
    selected = [(x, dt) for x, dt in checked if x['environment'] == environment]
    selected.sort(key=lambda pair: (-pair[1].timestamp(), pair[0]['release_id']))
    columns = ['release_id', 'version', 'status', 'deployed_at', 'duration_seconds']
    directory = os.path.dirname(os.path.abspath(destination)) or '.'
    fd, temporary = tempfile.mkstemp(dir=directory)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as stream:
            writer = csv.writer(stream)
            writer.writerow(columns)
            for item, _ in selected:
                writer.writerow([item[key] for key in columns])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    start = (page - 1) * page_size
    rows = [{key: item[key] for key in columns} for item, _ in selected[start:start + page_size]]
    return {'total': len(selected), 'page': page, 'page_size': page_size, 'rows': rows}

