import os
import json
import hashlib
import hmac
from datetime import date

def normalize_application(record: dict) -> dict:
    if not isinstance(record, dict):
        raise ValueError('record must be a mapping')
    if set(record) != {'id', 'applicant', 'submitted', 'category', 'dependents', 'complete'}:
        raise ValueError('invalid record fields')
    if not isinstance(record['id'], str) or not record['id']:
        raise ValueError('invalid id')
    person = record['applicant']
    if not isinstance(person, dict) or set(person) != {'family_name', 'given_name'}:
        raise ValueError('invalid applicant')
    family = person['family_name'].strip() if isinstance(person['family_name'], str) else ''
    given = person['given_name'].strip() if isinstance(person['given_name'], str) else ''
    if not family or not given:
        raise ValueError('empty name')
    submitted = record['submitted']
    if not isinstance(submitted, str):
        raise ValueError('invalid date')
    try:
        date.fromisoformat(submitted)
    except ValueError:
        raise ValueError('invalid date')
    weights = {'family': 20, 'employment': 30, 'humanitarian': 40}
    category = record['category']
    if category not in weights:
        raise ValueError('invalid category')
    dependents = record['dependents']
    if isinstance(dependents, bool) or not isinstance(dependents, int) or dependents < 0:
        raise ValueError('invalid dependents')
    complete = record['complete']
    if not isinstance(complete, bool):
        raise ValueError('invalid complete flag')
    return {'id': record['id'], 'family_name': family, 'given_name': given, 'submitted': submitted, 'category': category, 'dependents': dependents, 'complete': complete, 'priority': weights[category] + min(dependents, 3) + (4 if complete else 0)}

def prioritize_applications(records: list[dict]) -> list[dict]:
    result = [normalize_application(r) for r in records]
    if len({r['id'] for r in result}) != len(result):
        raise ValueError('duplicate id')
    return sorted(result, key=lambda r: (-r['priority'], r['submitted'], r['family_name'].casefold(), r['given_name'].casefold(), r['id']))

def build_intake_packet(records: list[dict], config: dict | None=None) -> dict:
    applications = prioritize_applications(records)
    summary = {'total': len(applications), 'complete': sum((r['complete'] for r in applications)), 'dependents': sum((r['dependents'] for r in applications)), 'by_category': {c: sum((r['category'] == c for r in applications)) for c in ('family', 'employment', 'humanitarian')}}
    key = config['INTAKE_SIGNING_KEY'] if config is not None and 'INTAKE_SIGNING_KEY' in config else os.environ.get('INTAKE_SIGNING_KEY')
    if not isinstance(key, str) or not key:
        raise ValueError('INTAKE_SIGNING_KEY is required')
    signed = {'applications': applications, 'summary': summary}
    raw = json.dumps(signed, sort_keys=True, separators=(',', ':')).encode('utf-8')
    return {'applications': applications, 'summary': summary, 'signature': hmac.new(key.encode('utf-8'), raw, hashlib.sha256).hexdigest()}

