import json
import os
from datetime import datetime

def _validate(record):
    if not isinstance(record, dict) or set(record) != {'plot_id', 'occupant', 'burial_date', 'status', 'notes'}:
        raise ValueError('invalid record')
    if any((not isinstance(record[k], str) for k in ('plot_id', 'occupant', 'burial_date', 'notes'))):
        raise ValueError('invalid record')
    if not record['occupant'].strip() or record['status'] not in {'available', 'reserved', 'occupied'}:
        raise ValueError('invalid record')
    try:
        parsed = datetime.strptime(record['burial_date'], '%Y-%m-%d')
    except ValueError:
        raise ValueError('invalid record')
    if parsed.strftime('%Y-%m-%d') != record['burial_date']:
        raise ValueError('invalid record')
    return record

def _path(base_dir, relative_name):
    if not isinstance(relative_name, str) or not relative_name:
        raise ValueError('invalid name')
    base = os.path.realpath(base_dir)
    candidate = os.path.realpath(os.path.join(base, relative_name + '.json'))
    if os.path.commonpath((base, candidate)) != base:
        raise ValueError('invalid name')
    return candidate

def write_plot_record(base_dir: str, relative_name: str, record: dict) -> str:
    _validate(record)
    path = _path(base_dir, relative_name)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'w', encoding='utf-8') as stream:
        json.dump(record, stream, indent=2, sort_keys=True)
        stream.write('\n')
    return path

def read_plot_record(base_dir: str, relative_name: str) -> dict:
    with open(_path(base_dir, relative_name), encoding='utf-8') as stream:
        value = json.load(stream)
    return _validate(value)

def summarize_records(records: list[dict]) -> dict:
    checked = [_validate(dict(item)) for item in records]
    statuses = {}
    years = {}
    for item in checked:
        statuses[item['status']] = statuses.get(item['status'], 0) + 1
        year = item['burial_date'][:4]
        years[year] = years.get(year, 0) + 1
    ordered = sorted(checked, key=lambda x: (x['burial_date'], x['plot_id']))
    return {'total': len(checked), 'by_status': dict(sorted(statuses.items())), 'by_year': dict(sorted(years.items())), 'ordered_plot_ids': [x['plot_id'] for x in ordered]}

