import re
import secrets

def generate_followup_code(bus_number: str, length: int=8) -> str:
    if not isinstance(bus_number, str):
        raise ValueError('invalid bus number')
    bus_number = bus_number.strip()
    if not bus_number or re.fullmatch('[A-Za-z0-9-]+', bus_number) is None:
        raise ValueError('invalid bus number')
    if isinstance(length, bool) or not isinstance(length, int) or (not 8 <= length <= 32):
        raise ValueError('invalid length')
    alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
    token = ''.join((secrets.choice(alphabet) for _ in range(length)))
    return f'BUS-{bus_number.upper()}-{token}'

def summarize_incidents(records: list[dict], page: int=1, page_size: int=10) -> dict:
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    required = {'incident_id', 'route', 'severity', 'minutes_late', 'resolved'}
    valid = []
    for record in records:
        if not isinstance(record, dict) or not required.issubset(record):
            raise ValueError('invalid record')
        if not isinstance(record['incident_id'], str) or not isinstance(record['route'], str) or record['severity'] not in {'low', 'medium', 'high'} or isinstance(record['minutes_late'], bool) or (not isinstance(record['minutes_late'], int)) or (record['minutes_late'] < 0) or (not isinstance(record['resolved'], bool)):
            raise ValueError('invalid record')
        if not record['resolved']:
            valid.append(record)
    ranks = {'high': 0, 'medium': 1, 'low': 2}
    valid.sort(key=lambda record: (ranks[record['severity']], record['incident_id']))
    counts = {severity: sum((r['severity'] == severity for r in valid)) for severity in ('high', 'medium', 'low')}
    average = round(sum((r['minutes_late'] for r in valid)) / len(valid), 2) if valid else 0.0
    start = (page - 1) * page_size
    return {'total': len(valid), 'by_severity': counts, 'average_minutes_late': average, 'incidents': valid[start:start + page_size]}

