import csv
import math
import os
import tempfile
from numbers import Real

def export_particle_events(events: list[dict], destination: str, min_pt: float=0.0, page: int=1, page_size: int=100) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('invalid page size')
    if isinstance(min_pt, bool) or not isinstance(min_pt, Real) or (not math.isfinite(float(min_pt))) or (min_pt < 0):
        raise ValueError('invalid minimum')
    parsed = []
    for record in events:
        try:
            run, event = (record['run'], record['event'])
            pt, eta, phi = (record['pt'], record['eta'], record['phi'])
        except (KeyError, TypeError):
            raise ValueError('invalid record')
        if isinstance(run, bool) or not isinstance(run, int) or run < 0 or isinstance(event, bool) or (not isinstance(event, int)) or (event < 0):
            raise ValueError('invalid record')
        if any((isinstance(value, bool) or not isinstance(value, Real) or (not math.isfinite(float(value))) for value in (pt, eta, phi))):
            raise ValueError('invalid record')
        if pt < 0:
            raise ValueError('invalid record')
        if pt >= min_pt:
            parsed.append((run, event, float(pt), float(eta), float(phi)))
    parsed.sort(key=lambda row: (row[0], -row[2], row[1]))
    start = (page - 1) * page_size
    selected = parsed[start:start + page_size]
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(prefix='.particle-', dir=parent, text=True)
    try:
        with os.fdopen(fd, 'w', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(('run', 'event', 'pt', 'eta', 'phi'))
            for run, event, pt, eta, phi in selected:
                writer.writerow((run, event, f'{pt:.3f}', f'{eta:.3f}', f'{phi:.3f}'))
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    counts = {}
    for run, _, _, _, _ in selected:
        counts[str(run)] = counts.get(str(run), 0) + 1
    return {'written': len(selected), 'runs': {key: counts[key] for key in sorted(counts, key=int)}}

