        raw_date = record['date']
        status = record['status']
        score = record['hazard_score']
        if not isinstance(facility, str) or not facility:
            raise ValueError('invalid facility')
        if not isinstance(raw_date, str):
            raise ValueError('invalid date')
        try:
            date.fromisoformat(raw_date)
        except ValueError:
            raise ValueError('invalid date')
        if status not in ('compliant', 'noncompliant'):
            raise ValueError('invalid status')
        if isinstance(score, bool) or not isinstance(score, int) or (not 0 <= score <= 100):
            raise ValueError('invalid score')
        groups.setdefault(facility, []).append((raw_date, status, score))
    facilities = []
    for facility in sorted(groups):
        items = groups[facility]
        scores = [item[2] for item in items]
        dates = [item[0] for item in items]
        compliant = sum((item[1] == 'compliant' for item in items))
        facilities.append({'facility': facility, 'total_records': len(items), 'compliant_records': compliant, 'noncompliant_records': len(items) - compliant, 'average_hazard_score': round(sum(scores) / len(scores), 2), 'first_record_date': min(dates), 'last_record_date': max(dates)})
    report = {'facilities': facilities, 'record_count': len(records)}
    canonical = json.dumps(report, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode('utf-8')
    signature = hmac.new(key.encode('utf-8'), canonical, hashlib.sha256).hexdigest()
    return {'report': report, 'signature': signature}

