import os
import tempfile

def make_file(text):
    handle = tempfile.NamedTemporaryFile(mode='w', encoding='utf-8', delete=False)
    try:
        handle.write(text)
        return handle.name
    finally:
        handle.close()

def remove_file(path):
    try:
        os.unlink(path)
    except FileNotFoundError:
        pass

def test_ordering_is_descending_with_alphabetical_ties():
    path = make_file('date,equipment,duration,member\n2025-01-01,Zebra,20,A\n2025-01-01,Alpha,20,B\n2025-01-01,Beta,35,C\n')
    try:
        assert booking_totals(path, '2025-01-01', 1, 10) == [('Beta', 35), ('Alpha', 20), ('Zebra', 20)]
    finally:
        remove_file(path)

def test_pagination_and_empty_day():
    path = make_file('date,equipment,duration,member\n2025-02-01,A,1,x\n2025-02-01,B,2,x\n2025-02-01,C,3,x\n')
