        header = next(reader)
    except StopIteration:
        return []
    if header != ['date', 'equipment', 'duration', 'member']:
        raise ValueError('invalid header')
    totals = {}
    for row in reader:
        if len(row) != 4:
            raise ValueError('invalid row')
        try:
