import csv
import math
import os
import tempfile

def publish_index(pages: list[dict], destination: str, page_size: int=50) -> dict:
    if not isinstance(pages, list):
        raise TypeError('pages must be a list')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('page_size must be positive')
    checked = []
    for page in pages:
        if not isinstance(page, dict):
            raise ValueError('invalid page')
        if set(page) != {'title', 'section', 'words', 'published'}:
            raise ValueError('invalid page')
        title = page['title']
        section = page['section']
        words = page['words']
        published = page['published']
        if not isinstance(title, str) or not title:
            raise ValueError('invalid page')
        if not isinstance(section, str) or not section:
            raise ValueError('invalid page')
        if isinstance(words, bool) or not isinstance(words, int) or words < 0:
            raise ValueError('invalid page')
        if not isinstance(published, bool):
            raise ValueError('invalid page')
        if published:
            checked.append((title, section, words))
    checked.sort(key=lambda item: (item[1].casefold(), -item[2], item[0].casefold(), item[0]))
    sections = {}
    for title, section, words in checked:
        sections[section] = sections.get(section, 0) + 1
    ordered_sections = dict(sorted(sections.items(), key=lambda item: (item[0].casefold(), item[0])))
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(prefix='.index-', suffix='.tmp', dir=directory)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['title', 'section', 'words'])
            writer.writerows(checked)
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return {'pages': len(checked), 'sections': ordered_sections, 'batches': math.ceil(len(checked) / page_size) if checked else 0}

