import secrets
import string

def parse_registrations(text: str) -> list[dict]:
    records = []
    seen = set()
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields = []
        current = []
        escaped = False
        for char in raw:
            if escaped:
                if char not in '\\|':
                    raise ValueError('invalid escape')
                current.append(char)
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == '|':
                fields.append(''.join(current).strip())
                current = []
            else:
                current.append(char)
        if escaped:
            raise ValueError('trailing escape')
        fields.append(''.join(current).strip())
        if len(fields) != 4:
            raise ValueError('wrong field count')
        name, email, session, dietary = fields
        if not name or not email or (not session):
            raise ValueError('empty field')
        if email.count('@') != 1 or any((ch.isspace() for ch in email)):
            raise ValueError('invalid email')
        key = email.casefold()
        if key in seen:
            raise ValueError('duplicate email')
        seen.add(key)
        records.append({'name': name, 'email': email, 'session': session, 'dietary': dietary or 'none'})
    return records

def create_invite_code(prefix: str='EVENT', length: int=10) -> str:
    if not isinstance(prefix, str) or not prefix or any((c not in string.ascii_uppercase + string.digits + '_' for c in prefix)):
        raise ValueError('invalid prefix')
    if isinstance(length, bool) or not isinstance(length, int) or (not 4 <= length <= 64):
        raise ValueError('invalid length')
    alphabet = string.ascii_uppercase + string.digits
    return prefix + '-' + ''.join((secrets.choice(alphabet) for _ in range(length)))

def register_event(text: str, capacities: dict[str, int]) -> dict:
    if any((not isinstance(k, str) or not k or isinstance(v, bool) or (not isinstance(v, int)) or (v <= 0) for k, v in capacities.items())):
        raise ValueError('invalid capacities')
    records = parse_registrations(text)
    if any((r['session'] not in capacities for r in records)):
        raise ValueError('unknown session')
    used = {key: 0 for key in capacities}
    totals = {key: {'accepted': 0, 'waitlisted': 0} for key in sorted(capacities)}
    output = []
    for record in records:
        row = dict(record)
        session = record['session']
        if used[session] < capacities[session]:
            used[session] += 1
            row['status'] = 'accepted'
            row['code'] = create_invite_code()
            totals[session]['accepted'] += 1
        else:
            row['status'] = 'waitlisted'
            row['code'] = None
            totals[session]['waitlisted'] += 1
        output.append(row)
    return {'registrations': output, 'summary': totals}

