import hashlib
import hmac
import json
import math

def verify_and_summarize(payload: bytes, signature: str, secret: str) -> dict:
    expected = hmac.new(secret.encode(), payload, hashlib.sha256).hexdigest()
    if not isinstance(signature, str) or len(signature) != 64:
        raise PermissionError('invalid signature')
    try:
        valid = hmac.compare_digest(expected, signature)
    except TypeError:
        valid = False
    if not valid:
        raise PermissionError('invalid signature')
    try:
        data = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(data, dict) or not isinstance(data.get('readings'), list):
        raise ValueError('invalid readings')
    groups = {}
    for reading in data['readings']:
        if not isinstance(reading, dict):
            raise ValueError('invalid reading')
        station = reading.get('station')
        level = reading.get('level')
        timestamp = reading.get('timestamp')
        if not isinstance(station, str) or not station or isinstance(level, bool) or (not isinstance(level, (int, float))) or (not math.isfinite(level)) or isinstance(timestamp, bool) or (not isinstance(timestamp, int)):
            raise ValueError('invalid reading')
        groups.setdefault(station, []).append((level, timestamp))
    stations = []
    for name in sorted(groups):
        values = groups[name]
        peak_level = max((level for level, _ in values))
        peak_timestamp = min((ts for level, ts in values if level == peak_level))
        average = round(sum((level for level, _ in values)) / len(values), 2)
        status = 'critical' if peak_level >= 8.0 else 'warning' if peak_level >= 6.0 else 'normal'
        stations.append({'name': name, 'count': len(values), 'average_level': average, 'peak_level': peak_level, 'peak_timestamp': peak_timestamp, 'status': status})
    return {'stations': stations}

