import hmac
import os

def create_operator(username: str, password: str) -> dict:
    if not isinstance(username, str) or not username.strip() or (not isinstance(password, str)) or (not password):
        raise ValueError('invalid operator')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return {'username': username.strip(), 'salt': salt.hex(), 'password': digest.hex()}

def authenticate_operator(operator: dict, password: str) -> bool:
    try:
        if not isinstance(operator, dict) or not isinstance(password, str):
            return False
        salt = bytes.fromhex(operator['salt'])
        expected = bytes.fromhex(operator['password'])
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError):
        return False

def parse_inventory(text: str) -> list[dict]:
    if not isinstance(text, str):
        raise ValueError('invalid inventory')
    rows = list(csv.reader(text.splitlines()))
    if not rows or rows[0] != ['site', 'equipment_id', 'kind', 'status', 'capacity']:
        raise ValueError('invalid header')
    result = []
    seen = set()
    for row in rows[1:]:
        if len(row) != 5 or not any(row):
            raise ValueError('invalid row')
        site, equipment, kind, status, capacity = [x.strip() for x in row]
        if not site or not equipment or (not kind) or (status not in {'active', 'maintenance', 'retired'}):
            raise ValueError('invalid field')
        try:
            capacity = int(capacity)
        except ValueError:
            raise ValueError('invalid capacity')
        if capacity <= 0 or equipment in seen:
            raise ValueError('invalid capacity or duplicate')
        seen.add(equipment)
        result.append({'site': site, 'equipment_id': equipment, 'kind': kind, 'status': status, 'capacity': capacity})
    if not result:
        raise ValueError('empty inventory')
    return result

def polling_report(inventory: list[dict], observations: list[tuple[str, int, int]], operator: dict, password: str, start: int, end: int) -> dict:
    if not authenticate_operator(operator, password):
        raise PermissionError('authentication failed')
    if not isinstance(start, int) or not isinstance(end, int) or start >= end:
        raise ValueError('invalid interval')
    items = {}
    try:
        for item in inventory:
            if set(item) != {'site', 'equipment_id', 'kind', 'status', 'capacity'} or item['equipment_id'] in items:
                raise ValueError('invalid inventory')
            if item['status'] not in {'active', 'maintenance', 'retired'} or not isinstance(item['capacity'], int) or item['capacity'] <= 0:
                raise ValueError('invalid inventory')
            items[item['equipment_id']] = dict(item)
    except (TypeError, KeyError):
        raise ValueError('invalid inventory')
    totals = {key: 0 for key in items}
    for observation in observations:
        if not isinstance(observation, tuple) or len(observation) != 3:
            raise ValueError('invalid observation')
        equipment, timestamp, quantity = observation
        if not isinstance(timestamp, int) or not isinstance(quantity, int) or quantity < 0 or (equipment not in items):
