import hmac
import json

def summarize_customer_export(payload: str, signature: str, signing_key: str, page: int=1, page_size: int=50) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page <= 0:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size <= 0:
        raise ValueError('invalid page size')
    expected = hmac.new(signing_key.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not isinstance(signature, str) or not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    try:
        records = json.loads(payload)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(records, list):
        raise ValueError('invalid payload')
    grouped = {}
    total = 0
    count = 0
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid order')
        customer = record.get('customer_id')
        amount = record.get('amount_cents')
        status = record.get('status')
        if not isinstance(customer, str) or not customer:
            raise ValueError('invalid order')
        if not isinstance(amount, int) or isinstance(amount, bool) or amount < 0:
            raise ValueError('invalid order')
        if not isinstance(status, str):
            raise ValueError('invalid order')
        if status == 'completed':
            if customer not in grouped:
                grouped[customer] = [0, 0]
            grouped[customer][0] += 1
            grouped[customer][1] += amount
            count += 1
            total += amount
    customers = [{'customer_id': name, 'order_count': values[0], 'total_cents': values[1]} for name, values in grouped.items()]
    customers.sort(key=lambda item: (-item['total_cents'], item['customer_id']))
    pages = (len(customers) + page_size - 1) // page_size if customers else 0
    start = (page - 1) * page_size
    return {'customers': customers[start:start + page_size], 'total_cents': total, 'order_count': count, 'page': page, 'page_size': page_size, 'pages': pages}

