from solution import build_bom_cost_report

def requester(user_id='u1', tenant='t1', roles=None):
    return {'id': user_id, 'tenant_id': tenant, 'roles': [] if roles is None else roles}

def assembly(lines, owner='u1', tenant='t1', assembly_id='A-7'):
    return {'assembly_id': assembly_id, 'owner_id': owner, 'tenant_id': tenant, 'lines': lines}

def test_ties_are_sorted_by_component_name():
    a = assembly([{'component': 'zeta', 'quantity': 1, 'unit_cost': 2}, {'component': 'alpha', 'quantity': 2, 'unit_cost': 1}, {'component': 'mid', 'quantity': 4, 'unit_cost': 0.5}])
    result = build_bom_cost_report(requester(), a, 1, 10)
    assert [x['component'] for x in result['components']] == ['alpha', 'mid', 'zeta']
    assert result['total_cost'] == 6.0

def test_pagination_metadata_and_boundaries():
    lines = [{'component': c, 'quantity': 1, 'unit_cost': n} for c, n in [('a', 5), ('b', 4), ('c', 3), ('d', 2), ('e', 1)]]
    a = assembly(lines)
    first = build_bom_cost_report(requester(), a, 1, 2)
    third = build_bom_cost_report(requester(), a, 3, 2)
    beyond = build_bom_cost_report(requester(), a, 4, 2)
    assert first['page_count'] == 3 and [x['component'] for x in first['components']] == ['a', 'b']
    assert [x['component'] for x in third['components']] == ['e']
    assert beyond['components'] == [] and beyond['page'] == 4

def test_empty_lines_return_empty_report():
    result = build_bom_cost_report(requester(), assembly([]), 1, 5)
    assert result['total_cost'] == 0.0
    assert result['component_count'] == 0
    assert result['page_count'] == 0
    assert result['components'] == []

def test_invalid_paging_is_rejected():
    a = assembly([])
    for page, size in [(0, 5), (-1, 5), (1, 0), (1, 101), (1, True)]:
        try:
            build_bom_cost_report(requester(), a, page, size)
        except ValueError:
            pass
        else:
            assert False

def test_invalid_line_data_is_rejected():
    base = {'component': 'x', 'quantity': 1, 'unit_cost': 1}
    bad_lines = [{**base, 'component': ''}, {**base, 'quantity': 0}, {**base, 'quantity': True}, {**base, 'unit_cost': -1}, {**base, 'unit_cost': float('inf')}, {'component': 'x', 'quantity': 1}]
    for line in bad_lines:
