import re

def create_site_invite(site_code: str, season: int, existing_codes: list[str] | None=None) -> dict:
    if not isinstance(site_code, str) or not re.fullmatch('[A-Za-z0-9]{3,8}', site_code):
        raise ValueError('invalid site code')
    if isinstance(season, bool) or not isinstance(season, int) or (not 1900 <= season <= 2100):
        raise ValueError('invalid season')
    existing = set(existing_codes or [])
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    while True:
        code = ''.join((random.choice(alphabet) for _ in range(8)))
        if code not in existing:
            return {'site_code': site_code.upper(), 'season': season, 'code': code}

def summarize_find_records(records: list[dict], year_range: tuple[int, int] | None=None, page: int=1, page_size: int=10) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
    if year_range is not None:
        if len(year_range) != 2 or any((isinstance(x, bool) or not isinstance(x, int) for x in year_range)) or year_range[0] > year_range[1]:
            raise ValueError('invalid year range')
    totals = {}
    for record in records:
        if not all((key in record for key in ('site', 'year', 'category', 'count'))):
            raise ValueError('invalid record')
        if not isinstance(record['site'], str) or not record['site'] or (not isinstance(record['category'], str)) or (not record['category']):
            raise ValueError('invalid record')
        if isinstance(record['year'], bool) or not isinstance(record['year'], int) or isinstance(record['count'], bool) or (not isinstance(record['count'], int)) or (record['count'] < 0):
            raise ValueError('invalid record')
        if year_range is None or year_range[0] <= record['year'] <= year_range[1]:
            totals[record['site']] = totals.get(record['site'], 0) + record['count']
    ordered = sorted(totals.items(), key=lambda pair: (-pair[1], pair[0]))
    start = (page - 1) * page_size
    items = [{'site': site, 'total': total} for site, total in ordered[start:start + page_size]]
    return {'items': items, 'total_sites': len(ordered), 'page': page, 'page_size': page_size, 'pages': (len(ordered) + page_size - 1) // page_size}

import sqlite3

def list_deliveries(conn: sqlite3.Connection, hub: str, status: str | None=None, sort_by: str='eta', limit: int=20, offset: int=0) -> list[dict]:
    if isinstance(limit, bool) or not isinstance(limit, int) or (not 1 <= limit <= 100):
        raise ValueError('invalid limit')
    if isinstance(offset, bool) or not isinstance(offset, int) or offset < 0:
        raise ValueError('invalid offset')
    columns = {'eta': 'eta_minutes', 'distance': 'distance_km', 'id': 'id'}
    if sort_by not in columns:
        raise ValueError('invalid sort')
    condition = f"hub = '{hub}'"
    if status is not None:
        condition += f" and status = '{status}'"
    sql = f'select id, hub, driver, status, distance_km, eta_minutes from deliveries where {condition} order by {columns[sort_by]}, id limit {limit} offset {offset}'
    rows = conn.execute(sql).fetchall()
    keys = ['id', 'hub', 'driver', 'status', 'distance_km', 'eta_minutes']
    return [dict(zip(keys, row)) for row in rows]

def route_totals(conn: sqlite3.Connection, hub: str, status: str | None=None) -> list[dict]:
    sql = 'select driver, count(*), sum(distance_km) from deliveries where hub = ?'
    params = [hub]
    if status is not None:
        sql += ' and status = ?'
        params.append(status)
    sql += ' group by driver order by driver'
    return [{'driver': driver, 'delivery_count': count, 'total_distance_km': round(total, 2)} for driver, count, total in conn.execute(sql, params).fetchall()]

