    assert reservation_summary(records) == {7: {'nights': 1, 'confirmed_nights': 1, 'revenue': '80.25', 'reservations': 1}, 12: {'nights': 4, 'confirmed_nights': 3, 'revenue': '300.00', 'reservations': 2}}

def test_summary_is_empty_and_order_independent():
    assert reservation_summary([]) == {}
    a = {'guest': 'Z', 'room': 2, 'check_in': '2025-01-02', 'check_out': '2025-01-04', 'status': 'confirmed', 'amount': 1.1}
    b = {'guest': 'Y', 'room': 1, 'check_in': '2025-01-01', 'check_out': '2025-01-02', 'status': 'confirmed', 'amount': 2.2}
    assert reservation_summary([a, b]) == reservation_summary([b, a])

