    records = [{'guest': 'Zed', 'room': 10, 'check_in': '2025-02-01', 'check_out': '2025-02-02', 'status': 'confirmed', 'amount': 4}, {'guest': 'Ann, Jr', 'room': 2, 'check_in': '2025-01-01', 'check_out': '2025-01-03', 'status': 'cancelled', 'amount': 77}, {'guest': 'Amy', 'room': 2, 'check_in': '2025-01-01', 'check_out': '2025-01-02', 'status': 'confirmed', 'amount': 12.5}]
    with tempfile.TemporaryDirectory() as d:
        p = os.path.join(d, 'out.csv')
        assert export_reservations(records, p) == 3
        with open(p, encoding='utf-8', newline='') as f:
            rows = list(csv.reader(f))
    assert rows == [['guest', 'room', 'check_in', 'check_out', 'status', 'amount'], ['Amy', '2', '2025-01-01', '2025-01-02', 'confirmed', '12.50'], ['Ann, Jr', '2', '2025-01-01', '2025-01-03', 'cancelled', '0.00'], ['Zed', '10', '2025-02-01', '2025-02-02', 'confirmed', '4.00']]

