import csv
import os
import tempfile
from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def _rows(reservations):
    out = []
    for r in reservations:
        try:
            if not isinstance(r['guest'], str) or not r['guest']:
                raise ValueError
            if isinstance(r['room'], bool) or not isinstance(r['room'], int) or r['room'] <= 0:
                raise ValueError
            start = date.fromisoformat(r['check_in'])
            end = date.fromisoformat(r['check_out'])
            if end <= start or r['status'] not in ('confirmed', 'cancelled'):
                raise ValueError
            amount = r['amount']
            if isinstance(amount, bool) or not isinstance(amount, (int, float, str, Decimal)):
                raise ValueError
            amount = Decimal(str(amount))
            if amount < 0 or not amount.is_finite():
                raise ValueError
        except (KeyError, TypeError, ValueError, InvalidOperation):
            raise ValueError('invalid reservation')
        out.append((r, start, end, amount))
    return out

def _money(x):
    return str(x.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))

def reservation_summary(reservations):
    groups = {}
    for r, start, end, amount in _rows(reservations):
        room = r['room']
        g = groups.setdefault(room, {'nights': 0, 'confirmed_nights': 0, 'revenue': Decimal('0'), 'reservations': 0})
        nights = (end - start).days
        g['nights'] += nights
        g['reservations'] += 1
        if r['status'] == 'confirmed':
            g['confirmed_nights'] += nights
            g['revenue'] += amount
    return {k: {'nights': v['nights'], 'confirmed_nights': v['confirmed_nights'], 'revenue': _money(v['revenue']), 'reservations': v['reservations']} for k, v in groups.items()}

def export_reservations(reservations, destination):
    rows = _rows(reservations)
    rows.sort(key=lambda x: (x[1], x[0]['room'], x[0]['guest']))
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as f:
            writer = csv.writer(f)
            writer.writerow(['guest', 'room', 'check_in', 'check_out', 'status', 'amount'])
            for r, start, end, amount in rows:
                writer.writerow([r['guest'], r['room'], start.isoformat(), end.isoformat(), r['status'], _money(amount if r['status'] == 'confirmed' else Decimal('0'))])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return len(rows)

