import hashlib
import hmac
import os

def hash_access_token(token: str) -> str:
    if not isinstance(token, str):
        raise TypeError('token must be a string')
    if token == '':
        raise ValueError('token must not be empty')
    iterations = 100000
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', token.encode(), salt, iterations)
    return f'{iterations}${salt.hex()}${digest.hex()}'

def verify_access_token(token: str, stored: str) -> bool:
    if not isinstance(token, str):
        raise TypeError('token must be a string')
    if token == '':
        raise ValueError('token must not be empty')
    if not isinstance(stored, str):
        return False
    try:
        iterations_text, salt_text, digest_text = stored.split('$')
        iterations = int(iterations_text)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', token.encode(), salt, iterations)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def generate_license_report(records: list[dict], page: int=1, page_size: int=10, license_filter: str | None=None) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('invalid page size')
    if license_filter is not None:
        if not isinstance(license_filter, str) or not license_filter.strip():
            raise ValueError('invalid license filter')
        license_filter = license_filter.strip()
    selected = []
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        if set(record) != {'package', 'license', 'compliant', 'issues'}:
            raise ValueError('invalid record')
        package = record['package'].strip() if isinstance(record['package'], str) else None
        license_name = record['license'].strip() if isinstance(record['license'], str) else None
        if not package or not license_name or type(record['compliant']) is not bool or (type(record['issues']) is not int) or (record['issues'] < 0):
            raise ValueError('invalid record')
        if license_filter is None or license_name == license_filter:
            selected.append({'package': package, 'license': license_name, 'compliant': record['compliant'], 'issues': record['issues']})
    selected.sort(key=lambda x: (x['package'].casefold(), x['package']))
    counts = {}
    for record in selected:
        counts[record['license']] = counts.get(record['license'], 0) + 1
    counts = dict(sorted(counts.items(), key=lambda x: (x[0].casefold(), x[0])))
    start = (page - 1) * page_size
    return {'page': page, 'page_size': page_size, 'total': len(selected), 'items': selected[start:start + page_size], 'license_counts': counts, 'compliant_count': sum((x['compliant'] for x in selected)), 'issue_count': sum((x['issues'] for x in selected))}

