import pytest


def test_parse_time_window_valid_and_whitespace():
    assert parse_time_window(" 08:05 - 11:30 ") == (485, 690)
    assert parse_time_window("00:00-23:59") == (0, 1439)


def test_parse_time_window_rejects_bad_values():
    for value in ["8:05-11:30", "08:60-11:30", "24:00-25:00", "12:00", "12:00-12:00", "13:00-12:59", "abc"]:
        with pytest.raises(ValueError):
            parse_time_window(value)


def test_rank_households_is_stable_by_all_tiebreakers_and_nonmutating():
    rows = [
        {"id": "b", "priority": 2, "registered": "2024-01-02"},
        {"id": "a", "priority": 3, "registered": "2024-02-01"},
        {"id": "c", "priority": 2, "registered": "2024-01-01"},
        {"id": "a0", "priority": 2, "registered": "2024-01-01"},
    ]
    original = list(rows)
    assert [x["id"] for x in rank_households(rows)] == ["a", "a0", "c", "b"]
