        {"id": "h2", "tenant": "north", "priority": 2, "registered": "2024-01-01", "size": 2},
        {"id": "h1", "tenant": "north", "priority": 5, "registered": "2024-01-03", "size": 1},
        {"id": "other", "tenant": "south", "priority": 9, "registered": "2024-01-01", "size": 1},
    ]
    slots = [
        {"id": "late", "tenant": "north", "date": "2024-06-02", "window": "10:00-11:00", "capacity": 2},
        {"id": "early", "tenant": "north", "date": "2024-06-01", "window": "09:00-10:00", "capacity": 1},
    ]
    assert publish_schedule(requester, households, slots) == [
        {"household_id": "h1", "slot_id": "early", "date": "2024-06-01", "window": "09:00-10:00", "size": 1},
        {"household_id": "h2", "slot_id": "late", "date": "2024-06-02", "window": "10:00-11:00", "size": 2},
