import re
from datetime import date

def parse_time_window(value: str) -> tuple[int, int]:
    if not isinstance(value, str):
        raise ValueError()
    m = re.fullmatch('\\s*(\\d{2}):(\\d{2})\\s*-\\s*(\\d{2}):(\\d{2})\\s*', value)
    if not m:
        raise ValueError()
    h1, m1, h2, m2 = map(int, m.groups())
    if h1 > 23 or h2 > 23 or m1 > 59 or (m2 > 59):
        raise ValueError()
    a, b = (h1 * 60 + m1, h2 * 60 + m2)
    if a >= b:
        raise ValueError()
    return (a, b)

def rank_households(households: list[dict]) -> list[dict]:
    try:
        return sorted(households, key=lambda x: (-int(x['priority']), x['registered'], x['id']))
    except (KeyError, TypeError, ValueError):
        raise ValueError()

def publish_schedule(requester: dict, households: list[dict], slots: list[dict]) -> list[dict]:
    if not isinstance(requester, dict) or not isinstance(requester.get('id'), str) or (not isinstance(requester.get('tenant'), str)) or (not isinstance(requester.get('roles'), list)):
        raise ValueError()
    if not {'coordinator', 'scheduler', 'admin'} & set(requester['roles']):
        raise PermissionError()
    tenant = requester['tenant']
    try:
        seen_h = set()
        hs = []
        for h in households:
            if not isinstance(h, dict) or h['id'] in seen_h or (not isinstance(h['id'], str)) or (not isinstance(h['tenant'], str)) or (not isinstance(h['priority'], int)) or (not isinstance(h['registered'], str)) or (not isinstance(h['size'], int)) or (h['size'] <= 0):
