from decimal import Decimal, ROUND_HALF_UP

def load_declarations(path: str, origin: str | None=None, page: int=1, page_size: int=10) -> list[dict]:
    if page < 1 or not 1 <= page_size <= 1000:
        raise ValueError('invalid pagination')
    result = subprocess.run(['sort', path], check=True, capture_output=True, text=True)
    rows = []
    for line in result.stdout.splitlines():
        if not line.strip():
            continue
        fields = [item.strip() for item in line.split(',')]
        if len(fields) != 4:
            raise ValueError('invalid row')
        ident, row_origin, value_text, rate_text = fields
        if not ident or not row_origin:
            raise ValueError('invalid row')
        try:
            value = Decimal(value_text)
            rate = Decimal(rate_text)
        except Exception as exc:
            raise ValueError('invalid row') from exc
        if not value.is_finite() or not rate.is_finite() or value < 0 or (not 0 <= rate <= 1):
            raise ValueError('invalid row')
        if origin is None or row_origin == origin:
            rounded_value = value.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
            duty = (value * rate).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
            rows.append((value, ident, {'id': ident, 'origin': row_origin, 'value': float(rounded_value), 'duty': float(duty)}))
