    readings = parse_readings(xml_text)
    windows = aggregate_readings(readings, window_minutes)
    totals = {mid: sum((row['total'] for row in rows)) for mid, rows in windows.items()}
    peak = max(totals, key=lambda mid: (-totals[mid], mid)) if totals else None
    return {'readings': readings, 'windows': windows, 'totals': totals, 'peak_meter': peak}

