def register_validator(name: str, api_secret: str) -> dict:
    if not isinstance(name, str) or not name:
        raise ValueError('invalid name')
    if not isinstance(api_secret, str) or not api_secret:
        raise ValueError('invalid secret')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', api_secret.encode(), salt, 100000)
    return {'name': name, 'secret_hash': salt.hex() + '$' + digest.hex()}

def verify_validator_secret(registration: dict, api_secret: str) -> bool:
    if not isinstance(registration, dict) or not isinstance(api_secret, str):
        return False
    value = registration.get('secret_hash')
    if not isinstance(value, str) or '$' not in value:
        return False
    try:
        salt_text, digest_text = value.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except ValueError:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', api_secret.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def filter_addresses(addresses: list[dict], bounds: tuple[float, float, float, float], page: int, page_size: int) -> dict:
    if not isinstance(addresses, list) or not isinstance(bounds, tuple) or len(bounds) != 4:
        raise ValueError('invalid input')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1 or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (page_size < 1):
        raise ValueError('invalid paging')
    south, west, north, east = bounds
    if any((isinstance(x, bool) or not isinstance(x, (int, float)) for x in bounds)) or not (-90 <= south <= north <= 90 and -180 <= west <= east <= 180):
        raise ValueError('invalid bounds')
    for item in addresses:
        if not isinstance(item, dict) or any((not isinstance(item.get(k), str) or not item[k] for k in ('id', 'address', 'city'))):
            raise ValueError('invalid address')
        if any((isinstance(item.get(k), bool) or not isinstance(item.get(k), (int, float)) for k in ('latitude', 'longitude', 'confidence'))) or not 0 <= item['confidence'] <= 1:
            raise ValueError('invalid address')
    selected = [x for x in addresses if south <= x['latitude'] <= north and west <= x['longitude'] <= east]
    selected.sort(key=lambda x: (-x['confidence'], x['id']))
    counts = {}
    for item in selected:
        counts[item['city']] = counts.get(item['city'], 0) + 1
    counts = dict(sorted(counts.items()))
    start = (page - 1) * page_size
    return {'total': len(selected), 'page': page, 'page_size': page_size, 'results': selected[start:start + page_size], 'city_counts': counts}

