import secrets

def create_access_record(username: str, password: str, experiment: str, created_at: int) -> dict:
    if not isinstance(username, str) or not username:
        raise ValueError('invalid username')
    if not isinstance(password, str) or not password:
        raise ValueError('invalid password')
    if not isinstance(experiment, str) or not experiment:
        raise ValueError('invalid experiment')
    if isinstance(created_at, bool) or not isinstance(created_at, int):
        raise ValueError('invalid timestamp')
    salt = secrets.token_bytes(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 120000)
    return {'username': username, 'experiment': experiment, 'created_at': created_at, 'password_digest': salt.hex() + '$' + digest.hex()}

def authenticate(record: dict, username: str, password: str) -> bool:
    if not isinstance(username, str) or not isinstance(password, str) or (not isinstance(record, dict)):
        return False
    try:
        if record['username'] != username:
            return False
        salt_text, digest_text = record['password_digest'].split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 120000)
        return secrets.compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError):
        return False

def parse_measurements(text: str) -> list[dict]:
    if not isinstance(text, str):
        raise TypeError('text must be a string')
    try:
        rows = list(csv.reader((line for line in text.splitlines() if line.strip())))
    except csv.Error as exc:
        raise ValueError('invalid csv') from exc
    header = ['sample', 'time_s', 'temp_c', 'stress_mpa']
    if not rows or rows[0] != header:
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if len(row) != 4 or not row[0]:
            raise ValueError('invalid row')
        try:
            values = [float(x) for x in row[1:]]
        except ValueError as exc:
            raise ValueError('invalid number') from exc
        if not all((math.isfinite(x) for x in values)):
            raise ValueError('non-finite number')
        result.append({'sample': row[0], 'time_s': values[0], 'temp_c': values[1], 'stress_mpa': values[2]})
    return result

def windowed_temperature(rows: list[dict], window_s: float) -> list[tuple[str, float, float]]:
    if isinstance(window_s, bool) or not isinstance(window_s, (int, float)) or (not math.isfinite(window_s)) or (window_s < 0):
        raise ValueError('invalid window')
    checked = []
    for index, row in enumerate(rows):
        try:
            sample, time_s, temp, stress = (row['sample'], row['time_s'], row['temp_c'], row['stress_mpa'])
        except (KeyError, TypeError) as exc:
            raise ValueError('invalid row') from exc
        if not isinstance(sample, str) or not sample or any((isinstance(x, bool) or not isinstance(x, (int, float)) or (not math.isfinite(x)) for x in (time_s, temp, stress))):
            raise ValueError('invalid row')
        checked.append((sample, float(time_s), float(temp), index))
    result = []
