import hashlib
import hmac
import json
import re
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
_RATE = re.compile('(?:0|[1-9]\\d*)(?:\\.\\d{1,4})?\\Z')
_PERIOD = re.compile('\\d{4}-(?:0[1-9]|1[0-2])\\Z')

def _check(report):
    if not isinstance(report, dict) or not isinstance(report.get('period'), str) or (not _PERIOD.fullmatch(report['period'])):
        raise ValueError('invalid report')
    tracks = report.get('tracks')
    if not isinstance(tracks, list):
        raise ValueError('invalid tracks')
    for track in tracks:
        if not isinstance(track, dict):
            raise ValueError('invalid track')
        for key in ('isrc', 'title', 'artist'):
            if not isinstance(track.get(key), str) or not track[key]:
                raise ValueError('invalid text')
        if isinstance(track.get('streams'), bool) or not isinstance(track.get('streams'), int) or track['streams'] < 0:
            raise ValueError('invalid streams')
        rate = track.get('rate')
        if not isinstance(rate, str) or not _RATE.fullmatch(rate):
            raise ValueError('invalid rate')
        try:
            Decimal(rate)
        except InvalidOperation:
            raise ValueError('invalid rate')
    return report

def verify_report(payload: str, secret: bytes) -> dict:
    if not isinstance(payload, str) or not isinstance(secret, bytes):
        raise ValueError('invalid input')
    first, marker, body = payload.partition('\n')
    if not marker or not re.fullmatch('SIGNATURE [0-9a-f]{64}', first):
        raise ValueError('invalid header')
    supplied = first[10:]
    expected = hmac.new(secret, body.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(supplied, expected):
        raise ValueError('invalid signature')
    try:
        report = json.loads(body)
    except (TypeError, json.JSONDecodeError):
        raise ValueError('invalid json')
    return _check(report)

def summarize_report(report: dict) -> dict:
    _check(report)
    groups = {}
    total = 0
    for track in report['tracks']:
        cents = (Decimal(track['streams']) * Decimal(track['rate']) * Decimal(100)).quantize(Decimal('1'), rounding=ROUND_HALF_UP)
        value = int(cents)
        name = track['artist']
        if name not in groups:
            groups[name] = [0, 0]
        groups[name][0] += track['streams']
        groups[name][1] += value
        total += value
    artists = [{'artist': n, 'streams': v[0], 'cents': v[1]} for n, v in groups.items()]
    artists.sort(key=lambda x: (-x['cents'], x['artist']))
    return {'period': report['period'], 'track_count': len(report['tracks']), 'total_cents': total, 'artists': artists}

