import os
import json
import hmac
import hashlib
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def _fields(line):
    out, cur, escaped = ([], [], False)
    for ch in line:
        if escaped:
            cur.append(ch)
            escaped = False
        elif ch == '\\':
            escaped = True
        elif ch == '|':
            out.append(''.join(cur))
            cur = []
        else:
            cur.append(ch)
    if escaped:
        raise ValueError('invalid escape')
    out.append(''.join(cur))
    return out

def parse_trade_feed(text: str) -> list[dict]:
    trades = []
    seen = set()
    for raw in text.splitlines():
        if not raw.strip():
            continue
        p = _fields(raw)
        if len(p) != 7:
            raise ValueError('invalid trade')
        tid, account, symbol, side, qty, price, currency = p
        if not tid or not account or (not symbol) or (side not in ('BUY', 'SELL')):
            raise ValueError('invalid trade')
        if tid in seen:
            raise ValueError('duplicate trade')
        if not currency or len(currency) != 3 or (not currency.isascii()) or (not currency.isupper()):
            raise ValueError('invalid currency')
        try:
            quantity = int(qty)
            value = Decimal(price)
        except (ValueError, InvalidOperation):
            raise ValueError('invalid number')
        if quantity <= 0 or value < 0 or (not value.is_finite()):
            raise ValueError('invalid number')
        normalized = value.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        seen.add(tid)
        trades.append({'trade_id': tid, 'account': account, 'symbol': symbol, 'side': side, 'quantity': quantity, 'price': format(normalized, '.2f'), 'currency': currency})
    return sorted(trades, key=lambda x: x['trade_id'])

def create_confirmation(text: str, config: dict[str, str] | None=None) -> dict:
    trades = parse_trade_feed(text)
    sums = {}
    for trade in trades:
        cur = trade['currency']
        sums[cur] = sums.get(cur, Decimal('0')) + Decimal(trade['price']) * trade['quantity']
    totals = {cur: format(sums[cur].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP), '.2f') for cur in sorted(sums)}
    key = config.get('signing_key') if config is not None and 'signing_key' in config else os.environ.get('TRADE_CONFIRMATION_KEY')
    if key is None:
        raise ValueError('missing signing key')
    if not isinstance(key, str):
        raise ValueError('invalid signing key')
    body = {'trades': trades, 'totals': totals}
    encoded = json.dumps(body, sort_keys=True, separators=(',', ':')).encode()
    signature = hmac.new(key.encode(), encoded, hashlib.sha256).hexdigest()
    return {'trades': trades, 'totals': totals, 'signature': signature}

