_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'

def generate_invite_code(length: int=10) -> str:
    if isinstance(length, bool) or not isinstance(length, int):
        raise TypeError('length must be an integer')
    if length < 6 or length > 32:
        raise ValueError('length must be between 6 and 32')
    return ''.join((secrets.choice(_ALPHABET) for _ in range(length)))

def _minutes(value: str) -> int:
    if not isinstance(value, str) or len(value) != 5 or value[2] != ':':
        raise ValueError('invalid time')
    hour, minute = (value[:2], value[3:])
    if not hour.isdigit() or not minute.isdigit():
        raise ValueError('invalid time')
    result = int(hour) * 60 + int(minute)
    if int(hour) > 23 or int(minute) > 59:
        raise ValueError('invalid time')
    return result

def get_departure_page(records: list[dict], station: str, start: str, end: str, page: int, page_size: int) -> dict:
    begin = _minutes(start)
    finish = _minutes(end)
    if begin > finish or page <= 0 or page_size <= 0:
        raise ValueError('invalid range or page')
    selected = []
    for record in records:
        moment = _minutes(record['departure'])
        if record['station'] == station and record['status'] != 'cancelled' and (begin <= moment <= finish):
            selected.append((moment, record))
    selected.sort(key=lambda pair: (pair[0], pair[1]['platform'], pair[1]['train']))
    total = len(selected)
    first = (page - 1) * page_size
    items = [{'train': r['train'], 'departure': r['departure'], 'platform': r['platform']} for _, r in selected[first:first + page_size]]
    return {'total': total, 'items': items}

