def index_record(index: dict[str, list[str]], requester: dict, record: dict) -> dict[str, list[str]]:
    required_record = ('id', 'surname', 'owner_id', 'tenant_id')
    required_requester = ('id', 'tenant_id', 'roles')
    if any((key not in record or not isinstance(record[key], str) for key in required_record)):
        raise ValueError('invalid record')
    if any((key not in requester for key in required_requester)):
        raise ValueError('invalid requester')
    if not isinstance(requester['id'], str) or not isinstance(requester['tenant_id'], str) or (not isinstance(requester['roles'], list)):
        raise ValueError('invalid requester')
    if not (record['owner_id'] == requester['id'] or ('editor' in requester['roles'] and record['tenant_id'] == requester['tenant_id'])):
        raise PermissionError('record cannot be indexed')
    values = index.setdefault(record['surname'], [])
    if record['id'] not in values:
        values.append(record['id'])
        values.sort()
