import os
import tempfile

def export_reservations(reservations: list[dict[str, object]]) -> str:
    fields = ['guest_name', 'reservation_date', 'reservation_time', 'party_size']
    fd, path = tempfile.mkstemp()
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.DictWriter(handle, fieldnames=fields, lineterminator='\r\n')
            writer.writeheader()
            for reservation in reservations:
                for field in fields:
                    if field not in reservation:
                        raise ValueError('missing reservation field')
                for field in fields[:3]:
                    if not isinstance(reservation[field], str) or not reservation[field]:
                        raise ValueError('invalid reservation value')
                party_size = reservation['party_size']
                if isinstance(party_size, bool) or not isinstance(party_size, int) or party_size <= 0:
                    raise ValueError('invalid party size')
                writer.writerow(reservation)
        with open(path, 'r', newline='', encoding='utf-8') as handle:
            return handle.read()
    finally:
        try:
            os.unlink(path)
        except FileNotFoundError:
            pass

