    try:
        handle = open(path, newline='', encoding='utf-8')
    except (OSError, TypeError):
        raise ValueError('unable to read log')
    groups = {}
    required = ['cell_id', 'timestamp', 'status', 'battery', 'temperature']
    try:
        with handle:
            reader = csv.DictReader(handle)
            if reader.fieldnames != required:
                raise ValueError('invalid header')
            for row in reader:
                if any((row[k] is None or row[k] == '' for k in required)):
                    raise ValueError('invalid row')
                try:
                    timestamp = datetime.fromisoformat(row['timestamp'])
                    battery = float(row['battery'])
                    temperature = float(row['temperature'])
                except (TypeError, ValueError):
                    raise ValueError('invalid row')
                if not 0 <= battery <= 100 or not -100 <= temperature <= 200:
                    raise ValueError('invalid value')
                if battery < min_battery:
                    continue
                cell = row['cell_id']
                item = groups.setdefault(cell, {'temps': [], 'batteries': [], 'latest': None})
                item['temps'].append(temperature)
                item['batteries'].append(battery)
                if item['latest'] is None or timestamp >= item['latest'][0]:
                    item['latest'] = (timestamp, row['timestamp'], row['status'])
    except csv.Error as exc:
        raise ValueError('invalid csv') from exc
    result = []
    for cell, item in groups.items():
        latest = item['latest']
        result.append({'cell_id': cell, 'event_count': len(item['temps']), 'average_temperature': round(sum(item['temps']) / len(item['temps']), 2), 'latest_timestamp': latest[1], 'latest_status': latest[2], 'minimum_battery': round(min(item['batteries']), 2), '_sort': latest[0]})
    result.sort(key=lambda x: (-x['_sort'].timestamp(), x['cell_id']))
    for item in result:
        del item['_sort']
    return result[:limit]

