    result = []
    seen = set()
    for fields in rows[1:]:
        if len(fields) != len(HEAD):
            raise ValueError('invalid row')
        pid, blood, organ, status, listed, urgency, pra, pediatric = fields
        if not pid or pid in seen or blood not in BLOODS or (organ not in ORGANS) or (status not in STATUSES):
            raise ValueError('invalid field')
        try:
            listed_on = date.fromisoformat(listed)
            urgency = int(urgency)
            pra = int(pra)
        except Exception as exc:
            raise ValueError('invalid value') from exc
        if urgency not in range(4) or not 0 <= pra <= 100 or pediatric not in ('true', 'false'):
            raise ValueError('invalid value')
        seen.add(pid)
        result.append({'patient_id': pid, 'blood': blood, 'organ': organ, 'status': status, 'listed_on': listed_on, 'urgency': urgency, 'pra': pra, 'pediatric': pediatric == 'true'})
