        days = (as_of - row['listed_on']).days
        priority = row['urgency'] * 100000 + (50000 if row['pediatric'] else 0) + days * 10 + row['pra']
        item = dict(row)
        item.update(wait_days=days, priority=priority)
        chosen.append(item)
    chosen.sort(key=lambda x: (-x['priority'], x['patient_id']))
    return chosen[:limit]

