import re
import xml.etree.ElementTree as ET

def _date(value):
    if not isinstance(value, str) or not re.fullmatch('\\d{4}-\\d{2}', value) or (not 1 <= int(value[5:]) <= 12):
        raise ValueError('invalid date')
    return (int(value[:4]), int(value[5:]))

def _num(attrs, key, integer=True, nonnegative=True):
    try:
        value = int(attrs[key]) if integer else float(attrs[key])
    except (KeyError, TypeError, ValueError):
        raise ValueError('invalid attribute')
    if nonnegative and value < 0:
        raise ValueError('invalid attribute')
    return value

def parse_valuation_report(xml: str) -> dict:
    try:
        root = ET.fromstring(xml)
    except Exception as exc:
        raise ValueError('invalid xml') from exc
    if root.tag != 'valuation':
        raise ValueError('invalid root')
    subject = root.find('subject')
    group = root.find('comparables')
    if subject is None or group is None or len(root) != 2:
        raise ValueError('invalid document')
    s = {'area': _num(subject.attrib, 'area'), 'beds': _num(subject.attrib, 'beds'), 'baths': _num(subject.attrib, 'baths')}
    result = []
    ids = set()
    for item in group:
        if item.tag != 'property' or item.attrib.get('id', '') == '' or item.attrib['id'] in ids:
            raise ValueError('invalid comparable')
        a = item.attrib
        year, month = _date(a.get('sale_date'))
        ids.add(a['id'])
        result.append({'id': a['id'], 'sale_date': a['sale_date'], 'price': _num(a, 'price'), 'area': _num(a, 'area'), 'beds': _num(a, 'beds'), 'baths': _num(a, 'baths'), 'distance': _num(a, 'distance', False)})
    return {'subject': s, 'comparables': result}

def estimate_property_value(xml: str, as_of: str) -> dict:
    ay, am = _date(as_of)
    data = parse_valuation_report(xml)
    s = data['subject']
    comps = sorted(data['comparables'], key=lambda x: (x['distance'], abs(x['area'] - s['area']), x['id']))[:3]
    output = []
    for c in comps:
        sy, sm = _date(c['sale_date'])
        months = (ay - sy) * 12 + am - sm
        base = c['price'] + (s['area'] - c['area']) * 100 + (s['beds'] - c['beds']) * 10000 + (s['baths'] - c['baths']) * 7500
        output.append({'id': c['id'], 'distance': c['distance'], 'adjusted_price': round(base * (1 + 0.005 * months))})
    if not output:
        return {'estimate': None, 'comparables': []}
    weights = [1 / (x['distance'] + 0.1) for x in output]
    estimate = round(sum((x['adjusted_price'] * w for x, w in zip(output, weights))) / sum(weights))
    return {'estimate': estimate, 'comparables': output}

