import hashlib
import os

class ArtifactStore:

    def __init__(self, credential: str) -> None:
        if not isinstance(credential, str) or not credential:
            raise ValueError('invalid credential')
        self._credential = self._hash(credential)
        self._items = {}

    @staticmethod
    def _hash(value: str) -> str:
        salt = os.urandom(16)
        digest = hashlib.pbkdf2_hmac('sha256', value.encode(), salt, 100000)
        return salt.hex() + '$' + digest.hex()

    @staticmethod
    def _check(value: str, stored: str) -> bool:
        try:
            salt, expected = stored.split('$', 1)
            actual = hashlib.pbkdf2_hmac('sha256', value.encode(), bytes.fromhex(salt), 100000).hex()
            return actual == expected
        except (ValueError, TypeError):
            return False

    def _auth(self, credential):
        if not isinstance(credential, str) or not self._check(credential, self._credential):
