def rank_boxes(boxes: list[dict], expression: str, limit: int) -> dict:
    if isinstance(limit, bool) or not isinstance(limit, int) or limit <= 0:
        raise ValueError('invalid limit')
    if not boxes:
        return {'total': 0, 'items': []}
    try:
        tree = ast.parse(expression, mode='eval')
    except Exception as exc:
        raise ValueError('invalid expression') from exc
    names = {'price', 'stock', 'rating', 'subscribers'}
    functions = {'min': min, 'max': max, 'round': round}

    def evaluate(node, env):
        if isinstance(node, ast.Expression):
            return evaluate(node.body, env)
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, bool)):
            return node.value
        if isinstance(node, ast.Name) and node.id in names:
            return env[node.id]
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
            value = evaluate(node.operand, env)
            if isinstance(node.op, ast.UAdd):
                return +value
            if isinstance(node.op, ast.USub):
                return -value
            return not value
        if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
            left = evaluate(node.left, env)
            right = evaluate(node.right, env)
            if isinstance(node.op, ast.Add):
                return left + right
            if isinstance(node.op, ast.Sub):
                return left - right
            if isinstance(node.op, ast.Mult):
                return left * right
            return left / right
        if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
            result = evaluate(node.values[0], env)
            for item in node.values[1:]:
                result = result and evaluate(item, env) if isinstance(node.op, ast.And) else result or evaluate(item, env)
            return result
        if isinstance(node, ast.Compare):
            left = evaluate(node.left, env)
            result = True
            for op, item in zip(node.ops, node.comparators):
                right = evaluate(item, env)
                if isinstance(op, ast.Lt):
                    result = result and left < right
                elif isinstance(op, ast.LtE):
                    result = result and left <= right
                elif isinstance(op, ast.Gt):
                    result = result and left > right
                elif isinstance(op, ast.GtE):
                    result = result and left >= right
                elif isinstance(op, ast.Eq):
                    result = result and left == right
                elif isinstance(op, ast.NotEq):
                    result = result and left != right
                else:
                    raise ValueError('invalid expression')
                left = right
            return result
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in functions) and (not node.keywords):
            return functions[node.func.id](*(evaluate(arg, env) for arg in node.args))
        raise ValueError('invalid expression')
    selected = []
    for box in boxes:
        try:
            score = evaluate(tree, {key: box[key] for key in names})
            if isinstance(score, bool) or not isinstance(score, (int, float)):
                raise ValueError('non-numeric result')
        except Exception as exc:
            raise ValueError('expression evaluation failed') from exc
        if score > 0:
            selected.append((score, box['id']))
    selected.sort(key=lambda item: (-item[0], item[1]))
    return {'total': len(selected), 'items': [{'id': item[1], 'score': item[0]} for item in selected[:limit]]}

