from datetime import datetime
from lxml import etree

def parse_redemptions(xml_text: str) -> list[dict[str, object]]:
    try:
        root = etree.fromstring(xml_text.encode(), parser=etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False))
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'redemptions':
        raise ValueError('invalid root')
    result = []
    for child in root:
        if child.tag != 'redemption':
            raise ValueError('invalid child')
        for name in ('member', 'reward', 'points', 'at'):
            if not child.get(name):
                raise ValueError('missing attribute')
        try:
            points = int(child.get('points'))
            datetime.fromisoformat(child.get('at'))
        except Exception as exc:
            raise ValueError('invalid redemption') from exc
        if points <= 0:
            raise ValueError('invalid points')
        result.append({'member': child.get('member'), 'reward': child.get('reward'), 'points': points, 'at': child.get('at'), 'channel': child.get('channel') or 'unknown'})
    return result

def summarize_redemptions(xml_text: str, balances: dict[str, int]) -> list[dict[str, object]]:
    if any((type(value) is not int or value < 0 for value in balances.values())):
        raise ValueError('invalid balance')
    records = parse_redemptions(xml_text)
    states = {member: {'accepted': 0, 'rejected': 0, 'spent': 0, 'remaining': balance, 'last_at': None, 'rewards': []} for member, balance in balances.items()}
    for record in records:
        member = record['member']
        if member not in states:
            states[member] = {'accepted': 0, 'rejected': 0, 'spent': 0, 'remaining': 0, 'last_at': None, 'rewards': []}
    ordered = sorted(enumerate(records), key=lambda pair: (datetime.fromisoformat(pair[1]['at']), pair[0]))
    for _, record in ordered:
        state = states[record['member']]
        state['last_at'] = record['at']
        if record['points'] <= state['remaining']:
            state['remaining'] -= record['points']
            state['accepted'] += 1
            state['spent'] += record['points']
            state['rewards'].append(record['reward'])
        else:
            state['rejected'] += 1
    result = [{'member': member, **state} for member, state in states.items()]
    return sorted(result, key=lambda row: (-row['accepted'], -row['spent'], row['member']))

