def build_location_alerts(records, window_seconds=600, minimum_reports=2):
    if not isinstance(window_seconds, int) or isinstance(window_seconds, bool) or window_seconds <= 0:
        raise ValueError('window_seconds must be positive')
    if not isinstance(minimum_reports, int) or isinstance(minimum_reports, bool) or minimum_reports <= 0:
        raise ValueError('minimum_reports must be positive')
    groups = {}
    for r in records:
        try:
            ident, ts, lat, lon, category = (r['id'], r['timestamp'], r['latitude'], r['longitude'], r['category'])
        except (KeyError, TypeError):
            raise ValueError('invalid record')
        if not isinstance(ident, str) or not ident or (not isinstance(category, str)) or (not category):
            raise ValueError('invalid record')
        if not isinstance(ts, int) or isinstance(ts, bool) or ts < 0 or (not isinstance(lat, (int, float))) or (not isinstance(lon, (int, float))):
            raise ValueError('invalid record')
        if not math.isfinite(lat) or not math.isfinite(lon) or (not -90 <= lat <= 90) or (not -180 <= lon <= 180):
            raise ValueError('invalid record')
        cell = (category, min(math.floor(lat), 89), min(math.floor(lon), 179))
        groups.setdefault(cell, []).append((ts, ident))
    answer = []
    for (category, la, lo), items in groups.items():
        items.sort()
        active = False
        for i, (ts, _) in enumerate(items):
            ids = {ident for old, ident in items[:i + 1] if old >= ts - window_seconds}
            qualifies = len(ids) >= minimum_reports
            if qualifies and (not active):
                answer.append({'category': category, 'latitude_cell': la, 'longitude_cell': lo, 'timestamp': ts, 'reporter_ids': sorted(ids)})
            active = qualifies
    return sorted(answer, key=lambda x: (x['timestamp'], x['category'], x['latitude_cell'], x['longitude_cell']))

