from decimal import Decimal, InvalidOperation
from datetime import date

def _date(value):
    if not isinstance(value, str):
        raise ValueError('invalid date')
    try:
        parsed = date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid date')
    if parsed.isoformat() != value:
        raise ValueError('invalid date')
    return value

def _account(value):
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError('invalid account')

def _money(value):
    try:
        result = Decimal(str(value))
    except (InvalidOperation, ValueError):
        raise ValueError('invalid amount')
    if not result.is_finite() or result.as_tuple().exponent < -2:
        raise ValueError('invalid amount')
    return float(result.quantize(Decimal('0.01')))

def add_transaction(conn: sqlite3.Connection, account_id: int, occurred: str, category: str, amount: int | float | str, note: str='') -> int:
    _account(account_id)
    _date(occurred)
    if not isinstance(category, str) or not category:
        raise ValueError('invalid category')
    if not isinstance(note, str):
        raise ValueError('invalid note')
    value = _money(amount)
    cur = conn.execute('insert into transactions(account_id, occurred, category, amount, note) values (?, ?, ?, ?, ?)', (account_id, occurred, category, value, note))
    conn.commit()
    return cur.lastrowid

def list_transactions(conn: sqlite3.Connection, account_id: int, start: str | None=None, end: str | None=None, category: str | None=None, search: str | None=None, sort_by: str='occurred') -> list[dict]:
    _account(account_id)
    if start is not None:
        _date(start)
    if end is not None:
        _date(end)
    if category is not None and (not isinstance(category, str)):
        raise ValueError('invalid category')
    if search is not None and (not isinstance(search, str)):
        raise ValueError('invalid search')
    if sort_by not in {'occurred', 'amount', 'category', 'id'}:
        raise ValueError('invalid sort')
    clauses = ['account_id = ?']
    args = [account_id]
    if start is not None:
        clauses.append('occurred >= ?')
        args.append(start)
    if end is not None:
        clauses.append('occurred <= ?')
        args.append(end)
    if category is not None:
        clauses.append('category = ?')
        args.append(category)
    if search is not None:
        clauses.append('(lower(category) like lower(?) or lower(note) like lower(?))')
        args.extend([f'%{search}%', f'%{search}%'])
    order = {'occurred': 'occurred', 'amount': 'amount', 'category': 'category', 'id': 'id'}[sort_by]
    rows = conn.execute(f"select id, occurred, category, amount, note from transactions where {' and '.join(clauses)} order by {order} asc, id asc", args).fetchall()
    return [dict(zip(('id', 'occurred', 'category', 'amount', 'note'), (r[0], r[1], r[2], round(float(r[3]), 2), r[4]))) for r in rows]

def budget_totals(conn: sqlite3.Connection, account_id: int, start: str, end: str) -> list[dict]:
    _account(account_id)
    _date(start)
    _date(end)
    if start > end:
        raise ValueError('invalid range')
    rows = conn.execute('select category, round(sum(amount), 2), count(*) from transactions where account_id = ? and occurred >= ? and occurred <= ? group by category order by sum(amount) desc, category asc', (account_id, start, end)).fetchall()
    return [{'category': r[0], 'total': round(float(r[1]), 2), 'count': r[2]} for r in rows]

