import csv
import datetime
import os
import tempfile

def build_billing_csv(events: list[dict], destination: str) -> dict:
    aggregates = {}
    for event in events:
        if not isinstance(event, dict):
            raise ValueError('invalid event')
        required = ('customer', 'month', 'units', 'unit_price', 'kind')
        if any((key not in event for key in required)):
            raise ValueError('invalid event')
        customer = event['customer']
        month = event['month']
        units = event['units']
        price = event['unit_price']
        kind = event['kind']
        if not isinstance(customer, str) or not customer:
            raise ValueError('invalid event')
        if not isinstance(month, str) or len(month) != 7 or month[4] != '-':
            raise ValueError('invalid event')
        try:
            if datetime.date.fromisoformat(month + '-01').strftime('%Y-%m') != month:
                raise ValueError
        except ValueError:
            raise ValueError('invalid event')
        if isinstance(units, bool) or not isinstance(units, int) or units <= 0:
            raise ValueError('invalid event')
        if isinstance(price, bool) or not isinstance(price, int) or price < 0:
            raise ValueError('invalid event')
        if kind not in ('charge', 'refund'):
            raise ValueError('invalid event')
        sign = 1 if kind == 'charge' else -1
        key = (month, customer)
        row = aggregates.setdefault(key, [0, 0, 0])
        row[0] += sign * units
        row[1] += sign * units * price
        row[2] += 1
    rows = sorted(aggregates.items())
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent)
    os.close(fd)
    try:
        with open(temporary, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle)
            writer.writerow(['month', 'customer', 'units', 'net_cents', 'events'])
            for (month, customer), values in rows:
                writer.writerow([month, customer, values[0], values[1], values[2]])
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return {'rows': len(rows), 'total_cents': sum((value[1][1] for value in rows))}

