    groups = {}
    for record in records:
        try:
            if not isinstance(record, dict) or not isinstance(record.get('id'), str) or (not isinstance(record.get('title'), str)) or (not isinstance(record.get('size'), int)) or isinstance(record.get('size'), bool) or (not isinstance(record.get('updated'), str)) or (not isinstance(record.get('metadata'), dict)) or (not isinstance(record['metadata'].get('collection'), str)):
