import copy
import re
import secrets
_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'

def parse_inventory(text: str) -> dict[str, list[dict[str, int | str]]]:
    result = {}
    for number, raw in enumerate(text.splitlines(), 1):
        line = raw.strip()
        if not line or line.startswith('#'):
            continue
        parts = [x.strip() for x in line.split('|')]
        if len(parts) != 4 or not parts[0] or (not parts[1]):
            raise ValueError(f'invalid line {number}')
        if not re.fullmatch('\\d+(?:\\.\\d{2})', parts[2]) or not re.fullmatch('\\d+', parts[3]):
            raise ValueError(f'invalid line {number}')
        price = int(parts[2].replace('.', ''))
        quantity = int(parts[3])
        event, section = (parts[0], parts[1])
        rows = result.setdefault(event, [])
        if any((row['section'] == section for row in rows)):
            raise ValueError(f'duplicate line {number}')
        rows.append({'section': section, 'price': price, 'quantity': quantity})
    for rows in result.values():
        rows.sort(key=lambda row: (row['price'], row['section']))
    return result

def reserve_tickets(inventory: dict[str, list[dict[str, int | str]]], orders: list[tuple[str, str, int]]) -> tuple[dict[str, list[dict[str, int | str]]], list[dict[str, object]]]:
    updated = copy.deepcopy(inventory)
    confirmations = []
    for customer, event, count in orders:
        if not isinstance(count, int) or isinstance(count, bool) or count <= 0 or (event not in updated):
            raise ValueError('invalid order')
        available = sum((row['quantity'] for row in updated[event]))
        if available < count:
            raise ValueError('insufficient tickets')
        left = count
        allocations = []
        for row in updated[event]:
            taken = min(left, row['quantity'])
            if taken:
                row['quantity'] -= taken
                allocations.append((row['section'], taken, row['price']))
                left -= taken
            if not left:
                break
        code = ''.join((secrets.choice(_ALPHABET) for _ in range(8)))
        confirmations.append({'customer': customer, 'event': event, 'count': count, 'sections': tuple(allocations), 'code': code})
    return (updated, confirmations)

def sales_summary(confirmations: list[dict[str, object]]) -> dict[str, dict[str, int]]:
    result = {}
    for confirmation in confirmations:
        try:
            event = confirmation['event']
            count = confirmation['count']
            sections = confirmation['sections']
            if not isinstance(event, str) or not isinstance(count, int) or count <= 0:
                raise ValueError
            total_count = 0
            revenue = 0
            for section, quantity, price in sections:
                if not isinstance(section, str) or not isinstance(quantity, int) or (not isinstance(price, int)) or (quantity <= 0) or (price < 0):
                    raise ValueError
                total_count += quantity
                revenue += quantity * price
            if total_count != count:
                raise ValueError
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid confirmation')
        if event not in result:
            result[event] = {'tickets': 0, 'revenue': 0}
        result[event]['tickets'] += count
        result[event]['revenue'] += revenue
    return result

