        dt = datetime.fromisoformat(value['timestamp'][:-1] + '+00:00')
    except Exception as exc:
        raise ValueError('invalid record') from exc
    return dt

def import_consent_bundle(zip_path: str, output_dir: str) -> list[dict]:
    os.makedirs(output_dir, exist_ok=True)
    base = os.path.realpath(output_dir)
    result = []
    seen = set()
    with zipfile.ZipFile(zip_path) as archive:
        for info in archive.infolist():
            if info.is_dir() or not info.filename.lower().endswith('.json'):
                continue
            if info.filename in seen:
                raise ValueError('duplicate member')
            seen.add(info.filename)
            destination = os.path.realpath(os.path.join(base, info.filename))
            if os.path.commonpath((base, destination)) != base:
                raise ValueError('invalid destination')
            raw = archive.read(info)
            try:
                value = json.loads(raw.decode('utf-8'))
            except Exception as exc:
                raise ValueError('invalid json') from exc
            _parse(value)
            os.makedirs(os.path.dirname(destination), exist_ok=True)
            with open(destination, 'wb') as handle:
                handle.write(raw)
            result.append(value)
    result.sort(key=lambda x: (_parse(x), x['user_id'], x['purpose']))
    return result

def summarize_consents(records: list[dict]) -> list[dict]:
    chosen = {}
    for index, value in enumerate(records):
        timestamp = _parse(value)
        key = (value['user_id'], value['purpose'])
        if key not in chosen or (timestamp, index) >= chosen[key][0]:
            chosen[key] = ((timestamp, index), value)
    users = {}
    for (user, purpose), (_, value) in chosen.items():
        users.setdefault(user, {})[purpose] = value
    output = []
    for user in sorted(users):
        grants = {purpose: users[user][purpose]['granted'] for purpose in sorted(users[user])}
        latest = max(users[user].values(), key=lambda x: _parse(x))
        output.append({'user_id': user, 'grants': grants, 'active_count': sum(grants.values()), 'changed_at': latest['timestamp']})
    return output

