import hmac
import os

def hash_admin_secret(secret: str) -> str:
    if not isinstance(secret, str):
        raise TypeError('secret must be a string')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
    return 'pbkdf2$100000$' + salt.hex() + '$' + digest.hex()

def verify_admin_secret(secret: str, stored: str) -> bool:
    if not isinstance(secret, str):
        raise TypeError('secret must be a string')
    if not isinstance(stored, str):
        return False
    try:
        kind, count, salt_hex, digest_hex = stored.split('$')
        if kind != 'pbkdf2' or int(count) != 100000:
            return False
        salt = bytes.fromhex(salt_hex)
        expected = bytes.fromhex(digest_hex)
        actual = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def evaluate_flags(flags: list[dict], context: dict, now: int) -> dict[str, bool]:
    if not isinstance(flags, list):
        raise TypeError('flags must be a list')
    if not isinstance(context, dict):
        raise TypeError('context must be a dictionary')
    if isinstance(now, bool) or not isinstance(now, int):
        raise ValueError('now must be an integer')
    result = {}
    for flag in flags:
        if not isinstance(flag, dict) or not isinstance(flag.get('name'), str) or (not flag['name']) or (not isinstance(flag.get('enabled'), bool)):
            raise ValueError('invalid flag')
        name = flag['name']
        if name in result:
            raise ValueError('duplicate flag')
        start, end = (flag.get('start'), flag.get('end'))
        if start is not None and (isinstance(start, bool) or not isinstance(start, int)):
            raise ValueError('invalid start')
        if end is not None and (isinstance(end, bool) or not isinstance(end, int)):
            raise ValueError('invalid end')
        if start is not None and end is not None and (start > end):
            raise ValueError('invalid window')
        active = (start is None or now >= start) and (end is None or now < end)
        value = False
        if active:
            value = flag['enabled']
            rules = flag.get('rules', [])
            if not isinstance(rules, list):
                raise ValueError('invalid rules')
            matched = False
            for rule in rules:
                if not isinstance(rule, dict) or not isinstance(rule.get('when'), dict) or (not isinstance(rule.get('value'), bool)):
                    raise ValueError('invalid rule')
                if all((k in context and context[k] == v for k, v in rule['when'].items())):
                    value, matched = (rule['value'], True)
                    break
            if not matched and 'rollout' in flag:
                rollout = flag['rollout']
                if not isinstance(rollout, dict) or isinstance(rollout.get('percent'), bool) or (not isinstance(rollout.get('percent'), int)) or (not 0 <= rollout['percent'] <= 100) or (not isinstance(rollout.get('value'), bool)):
                    raise ValueError('invalid rollout')
                if not isinstance(context.get('user_id'), str):
                    raise ValueError('missing user_id')
                bucket = int(hashlib.sha256((context['user_id'] + ':' + name).encode()).hexdigest()[:8], 16) % 100
                value = rollout['value'] if bucket < rollout['percent'] else False
        result[name] = value
    return result

