    if not key:
        raise ValueError('RENTAL_SIGNING_KEY is required')
    unit_id = unit_id.strip()
    customer_id = customer_id.strip()
    total = round(monthly_rate * months, 2)
    canonical = f'{unit_id}|{customer_id}|{monthly_rate:.2f}|{months}|{total:.2f}'
    signature = hmac.new(key.encode(), canonical.encode(), hashlib.sha256).hexdigest()
    return {'unit_id': unit_id, 'customer_id': customer_id, 'monthly_rate': monthly_rate, 'months': months, 'total': total, 'signature': signature}

