    totals = {}
    for raw in result.stdout.splitlines():
        if not raw.strip():
            continue
        fields = raw.split('|')
        if len(fields) != 6:
            raise ValueError('invalid record')
        tenant, prop, start_s, end_s, rent_s, status = fields
        try:
            start = datetime.date.fromisoformat(start_s)
            end = datetime.date.fromisoformat(end_s)
        except ValueError as exc:
            raise ValueError('invalid date') from exc
        if start > end or status not in {'ACTIVE', 'EXPIRED', 'PENDING'}:
            raise ValueError('invalid record')
        try:
            if rent_s.count('.') > 1 or ('.' in rent_s and len(rent_s.split('.', 1)[1]) > 2):
                raise ValueError
            amount = int(round(float(rent_s) * 100))
            if amount < 0 or format(amount / 100, '.2f') != format(float(rent_s), '.2f'):
                raise ValueError
        except (ValueError, OverflowError) as exc:
            raise ValueError('invalid rent') from exc
        if status == 'ACTIVE' and start <= day <= end:
            item = totals.setdefault(tenant, {'tenant': tenant, 'monthly_rent_cents': 0, 'properties': [], 'lease_count': 0})
            item['monthly_rent_cents'] += amount
            item['lease_count'] += 1
            if prop not in item['properties']:
                item['properties'].append(prop)
    return [totals[name] for name in sorted(totals)]

