from datetime import date, timedelta
from typing import Any

def forecast_demand(requester: dict[str, Any], meters: list[dict[str, Any]], readings: list[dict[str, Any]], horizon_days: int) -> list[dict[str, Any]]:
    if not isinstance(requester, dict) or not all((k in requester for k in ('id', 'tenant_id', 'role'))):
        raise ValueError('invalid requester')
    if isinstance(horizon_days, bool) or not isinstance(horizon_days, int) or (not 1 <= horizon_days <= 30):
        raise ValueError('invalid horizon')
    if not isinstance(meters, list) or not isinstance(readings, list):
        raise ValueError('invalid records')
    by_id = {}
    for meter in meters:
        if not isinstance(meter, dict) or not all((k in meter for k in ('id', 'owner_id', 'tenant_id', 'active'))) or meter['id'] in by_id:
            raise ValueError('invalid meter')
        by_id[meter['id']] = meter
    grouped = {}
    seen = set()
    for reading in readings:
        if not isinstance(reading, dict) or not all((k in reading for k in ('meter_id', 'day', 'kwh'))):
            raise ValueError('invalid reading')
        if reading['meter_id'] not in by_id or (reading['meter_id'], reading['day']) in seen:
            raise ValueError('invalid reading')
        try:
            day = date.fromisoformat(reading['day'])
        except (TypeError, ValueError):
            raise ValueError('invalid date')
        if isinstance(reading['kwh'], bool) or not isinstance(reading['kwh'], (int, float)) or reading['kwh'] < 0:
            raise ValueError('invalid kwh')
        seen.add((reading['meter_id'], reading['day']))
        grouped.setdefault(reading['meter_id'], []).append((day, reading['kwh']))
    result = []
    for meter_id in sorted(by_id, key=str):
        meter = by_id[meter_id]
        if not meter['active'] or not (meter['owner_id'] == requester['id'] or (requester['role'] == 'utility_admin' and meter['tenant_id'] == requester['tenant_id'])):
            continue
        values = sorted(grouped.get(meter_id, []))
        base = values[-1][0] if values else date(1970, 1, 1)
        average = round(sum((v for _, v in values[-7:])) / min(7, len(values)), 2) if values else 0.0
        result.append({'meter_id': meter_id, 'forecast': [{'day': (base + timedelta(days=i)).isoformat(), 'kwh': average} for i in range(1, horizon_days + 1)]})
    return result

