import ast
import operator

def compute_tourist_tax(stays: list[dict], formula: str, variables: dict[str, int | float], minimum_nights: int=1) -> dict:
    if minimum_nights < 1:
        raise ValueError('minimum_nights must be positive')
    tree = ast.parse(formula, mode='eval')
    funcs = {'min': min, 'max': max, 'round': round}

    def evaluate(node, env):
        if isinstance(node, ast.Expression):
            return evaluate(node.body, env)
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id in funcs:
                return funcs[node.id]
            if node.id not in env:
                raise NameError(node.id)
            return env[node.id]
        if isinstance(node, ast.BinOp) and type(node.op) in {ast.Add, ast.Sub, ast.Mult, ast.Div}:
            left = evaluate(node.left, env)
            right = evaluate(node.right, env)
            operation = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)]
            return operation(left, right)
        if isinstance(node, ast.UnaryOp) and type(node.op) in {ast.UAdd, ast.USub, ast.Not}:
            value = evaluate(node.operand, env)
            return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
        if isinstance(node, ast.BoolOp) and type(node.op) in {ast.And, ast.Or}:
            value = evaluate(node.values[0], env)
            for part in node.values[1:]:
                if isinstance(node.op, ast.And) and (not value):
                    return value
                if isinstance(node.op, ast.Or) and value:
                    return value
                value = evaluate(part, env)
            return value
        if isinstance(node, ast.Compare):
            left = evaluate(node.left, env)
            operations = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}
            for op, part in zip(node.ops, node.comparators):
                right = evaluate(part, env)
                if not operations[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.IfExp):
            if evaluate(node.test, env):
                return evaluate(node.body, env)
            return evaluate(node.orelse, env)
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in funcs) and (not node.keywords):
            return funcs[node.func.id](*(evaluate(arg, env) for arg in node.args))
        raise ValueError('unsupported expression')
    total = 0
    by_city = {}
    count = 0
    for stay in stays:
        if stay['nights'] < minimum_nights:
            continue
        env = {**variables, 'nights': stay['nights'], 'guests': stay['guests'], 'nightly_rate': stay['nightly_rate']}
        value = evaluate(tree, env)
        if value > 0:
            total += value
            by_city[stay['city']] = by_city.get(stay['city'], 0) + value
            count += 1
    return {'total': total, 'by_city': by_city, 'count': count}

