import json
import os

def generate_bed_report(base_dir: str, filename: str, residents: list[dict], beds: list[dict]) -> str:
    if not isinstance(base_dir, str) or not os.path.isdir(base_dir):
        raise ValueError('invalid base directory')
    if not isinstance(filename, str) or not filename or (not filename.endswith('.json')):
        raise ValueError('invalid filename')
    seen = set()
    for r in residents:
        if not isinstance(r, dict) or not isinstance(r.get('id'), str) or (not r['id']) or (r['id'] in seen) or (not isinstance(r.get('priority'), int)) or (not 1 <= r['priority'] <= 5) or (not isinstance(r.get('nights'), int)) or (r['nights'] <= 0) or (not isinstance(r.get('needs_accessible'), bool)):
            raise ValueError('invalid resident')
        seen.add(r['id'])
    seen = set()
    for b in beds:
        if not isinstance(b, dict) or not isinstance(b.get('id'), str) or (not b['id']) or (b['id'] in seen) or (not isinstance(b.get('floor'), int)) or (b['floor'] <= 0) or (not isinstance(b.get('accessible'), bool)):
            raise ValueError('invalid bed')
        seen.add(b['id'])
    base = os.path.realpath(base_dir)
    path = os.path.realpath(os.path.join(base_dir, filename))
    if os.path.commonpath([base, path]) != base:
        raise ValueError('invalid filename')
    ordered_residents = sorted(residents, key=lambda r: (-r['priority'], -r['nights'], r['id']))
    available = sorted(beds, key=lambda b: (b['floor'], b['id']))
    allocations = []
    unassigned = []
    for resident in ordered_residents:
        choice = next((i for i, bed in enumerate(available) if not resident['needs_accessible'] or bed['accessible']), None)
        if choice is None:
            unassigned.append(resident['id'])
        else:
            bed = available.pop(choice)
            allocations.append({'resident_id': resident['id'], 'bed_id': bed['id'], 'nights': resident['nights']})
    report = {'allocations': allocations, 'unassigned': unassigned, 'summary': {'allocated': len(allocations), 'total_nights': sum((x['nights'] for x in allocations))}}
    with open(path, 'w', encoding='utf-8') as f:
        json.dump(report, f, indent=2, sort_keys=True)
        f.write('\n')
    return path

