import hashlib
import hmac
import os

def hash_secret(secret: str) -> str:
    if not isinstance(secret, str):
        raise TypeError('secret must be a string')
    if not secret:
        raise ValueError('secret must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
    return salt.hex() + ':' + digest.hex()

def search_prior_art(records, query, stored_secret, candidate_secret, page=1, page_size=10, year_from=None, year_to=None):
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    if not isinstance(query, str) or not query.strip():
        raise ValueError('query must not be empty')
    if not isinstance(page, int) or page < 1 or (not isinstance(page_size, int)) or (not 1 <= page_size <= 50):
        raise ValueError('invalid pagination')
    if year_from is not None and (not isinstance(year_from, int)):
        raise ValueError('invalid year')
    if year_to is not None and (not isinstance(year_to, int)):
        raise ValueError('invalid year')
    if year_from is not None and year_to is not None and (year_from > year_to):
        raise ValueError('invalid year range')
    try:
        salt, expected = stored_secret.split(':')
        actual = hashlib.pbkdf2_hmac('sha256', candidate_secret.encode(), bytes.fromhex(salt), 100000).hex()
        allowed = hmac.compare_digest(actual, expected)
    except (AttributeError, ValueError):
        allowed = False
    if not allowed:
        raise PermissionError('invalid secret')
    terms = query.strip().lower().split()
    found = []
    for record in records:
        if not isinstance(record, dict) or any((k not in record for k in ('id', 'title', 'abstract', 'year', 'citations'))):
            raise ValueError('invalid record')
        if not isinstance(record['id'], str) or not isinstance(record['title'], str) or (not isinstance(record['abstract'], str)) or (not isinstance(record['year'], int)) or (not isinstance(record['citations'], list)) or any((not isinstance(x, str) for x in record['citations'])):
            raise ValueError('invalid record')
        if year_from is not None and record['year'] < year_from or (year_to is not None and record['year'] > year_to):
            continue
        title, abstract = (record['title'].lower(), record['abstract'].lower())
        if not all((term in title or term in abstract for term in terms)):
            continue
        score = sum((title.count(term) * 3 + abstract.count(term) for term in terms))
        found.append((score, record['year'], record['id'], {'id': record['id'], 'title': record['title'], 'year': record['year'], 'score': score}))
    found.sort(key=lambda x: (-x[0], -x[1], x[2]))
    start = (page - 1) * page_size
    return {'total': len(found), 'page': page, 'page_size': page_size, 'results': [x[3] for x in found[start:start + page_size]]}

