from datetime import datetime
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def generate_payment_access_code(customer_id: str, charges: list[dict], page: int=1, page_size: int=10) -> dict:
    if not isinstance(customer_id, str) or not customer_id.strip():
        raise ValueError('invalid customer_id')
    if not isinstance(charges, list):
        raise ValueError('invalid charges')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 50):
        raise ValueError('invalid page_size')
    grouped = {}
    for item in charges:
        if not isinstance(item, dict) or not all((k in item for k in ('month', 'amount', 'paid'))):
            raise ValueError('invalid charge')
        month, paid = (item['month'], item['paid'])
        if not isinstance(month, str):
            raise ValueError('invalid month')
        try:
            datetime.strptime(month, '%Y-%m')
            amount = Decimal(str(item['amount']))
        except (ValueError, TypeError, InvalidOperation):
            raise ValueError('invalid charge')
        if not amount.is_finite() or amount < 0 or (not isinstance(paid, bool)):
            raise ValueError('invalid charge')
        if not paid:
            grouped[month] = grouped.get(month, Decimal('0')) + amount
    quantized = {m: v.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP) for m, v in grouped.items()}
    ordered = sorted(quantized.items(), key=lambda x: (-x[1], x[0]))
    start = (page - 1) * page_size
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    code = ''.join((secrets.choice(alphabet) for _ in range(12)))
    return {'code': code, 'customer_id': customer_id.strip(), 'overdue_total': float(sum(quantized.values(), Decimal('0'))), 'total_months': len(ordered), 'page': page, 'page_size': page_size, 'months': [{'month': m, 'amount': float(v)} for m, v in ordered[start:start + page_size]]}

