from datetime import datetime, timezone, timedelta

def parse_telemetry(text: str) -> list[dict]:
    if not isinstance(text, str):
        raise TypeError('text must be a string')
    result = []
    previous = None
    for raw in text.splitlines():
        if not raw.strip():
            continue
        parts = raw.split('|')
        if len(parts) != 5:
            raise ValueError('invalid record')
        stamp = parts[0]
        try:
            if len(stamp) != 20 or not stamp.endswith('Z'):
                raise ValueError
            dt = datetime.strptime(stamp, '%Y-%m-%dT%H:%M:%SZ').replace(tzinfo=timezone.utc)
            epoch = dt.timestamp()
            values = [float(x) for x in parts[1:]]
        except Exception as exc:
            raise ValueError('invalid record') from exc
        if previous is not None and epoch <= previous:
            raise ValueError('timestamps must increase')
        previous = epoch
        result.append({'timestamp': stamp, 'epoch': epoch, 'rpm': values[0], 'egt': values[1], 'oil_pressure': values[2], 'vibration': values[3]})
    return result

def _allowed(requester, engine):
    return requester.get('tenant_id') == engine.get('tenant_id') and (requester.get('id') == engine.get('owner_id') or 'fleet_admin' in requester.get('roles', []))

def summarize_engine(requester: dict, engine: dict, telemetry_text: str, window_seconds: int=60) -> dict:
    if not isinstance(window_seconds, int):
        raise TypeError('window_seconds must be an integer')
    if window_seconds <= 0:
        raise ValueError('window_seconds must be positive')
    if not _allowed(requester, engine):
        raise PermissionError('not allowed')
    records = parse_telemetry(telemetry_text)
    answer = {'engine_id': engine['id'], 'model': engine['model'], 'sample_count': len(records), 'peak_rpm': max((r['rpm'] for r in records), default=None), 'windows': []}
    if not records:
        return answer
    base = records[0]['epoch']
    groups = {}
    for r in records:
        index = int((r['epoch'] - base) // window_seconds)
        groups.setdefault(index, []).append(r)
    for index in sorted(groups):
        rows = groups[index]
        start_dt = datetime.fromtimestamp(base + index * window_seconds, timezone.utc)
        end_dt = start_dt + timedelta(seconds=window_seconds)
        answer['windows'].append({'start': start_dt.strftime('%Y-%m-%dT%H:%M:%SZ'), 'end': end_dt.strftime('%Y-%m-%dT%H:%M:%SZ'), 'count': len(rows), 'average_rpm': round(sum((x['rpm'] for x in rows)) / len(rows), 2), 'average_egt': round(sum((x['egt'] for x in rows)) / len(rows), 2), 'minimum_oil_pressure': min((x['oil_pressure'] for x in rows)), 'maximum_vibration': max((x['vibration'] for x in rows))})
    return answer

def acknowledge_alert(requester: dict, engine: dict, alerts: list[dict], alert_id: str) -> dict:
    if not _allowed(requester, engine):
        raise PermissionError('not allowed')
    if not isinstance(alerts, list):
        raise TypeError('alerts must be a list')
    if not isinstance(alert_id, str) or not alert_id:
        raise ValueError('invalid alert id')
    found = next((a for a in alerts if a.get('id') == alert_id), None)
    if found is None:
        raise KeyError(alert_id)
    if found.get('engine_id') != engine.get('id'):
        raise ValueError('wrong engine')
    result = dict(found)
    result['acknowledged'] = True
    result['acknowledged_by'] = requester['id']
    return result

