        if not all((math.isfinite(value) for value in (raw, temperature))):
            raise ValueError(f'invalid line {number}')
        result.append({'timestamp': timestamp, 'sensor': fields[1], 'raw': raw, 'temperature': temperature})
    return result

def calibrate_report(text: str, config: dict) -> dict:
    if not isinstance(config, dict) or not isinstance(config.get('signing_key'), str):
        raise ValueError('signing_key is required')
