import json

def verify_feedback(body: str, signature: str, secret: bytes) -> list[dict]:
    if not isinstance(body, str) or not isinstance(signature, str) or (not isinstance(secret, bytes)):
        raise ValueError('invalid input')
    if len(signature) != 71 or not signature.startswith('sha256='):
        raise ValueError('invalid signature')
    supplied = signature[7:]
    if any((c not in '0123456789abcdef' for c in supplied)):
        raise ValueError('invalid signature')
    expected = hmac.new(secret, body.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(supplied, expected):
        raise ValueError('invalid signature')
    try:
        data = json.loads(body)
    except (ValueError, TypeError):
        raise ValueError('invalid json')
    if not isinstance(data, list) or not data:
        raise ValueError('invalid payload')
    result = []
    ids = set()
    keys = {'id', 'user', 'rating', 'comment', 'tags', 'timestamp'}
    for item in data:
        if not isinstance(item, dict) or set(item) != keys:
            raise ValueError('invalid record')
        if any((not isinstance(item[k], str) or not item[k] for k in ('id', 'user', 'comment'))):
            raise ValueError('invalid text')
        if item['id'] in ids or isinstance(item['rating'], bool) or (not isinstance(item['rating'], int)) or (not 1 <= item['rating'] <= 5):
            raise ValueError('invalid record')
        tags = item['tags']
        if not isinstance(tags, list) or any((not isinstance(t, str) or not t for t in tags)) or len(tags) != len(set(tags)):
