import hashlib
import hmac
import os

def create_agent(name: str, password: str) -> dict:
    if not isinstance(name, str) or not name or (not isinstance(password, str)) or (not password):
        raise ValueError('name and password are required')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return {'name': name, 'credential': salt.hex() + '$' + digest.hex()}

def check_agent(agent: dict, password: str) -> bool:
    if not isinstance(agent, dict) or not isinstance(password, str):
        return False
    value = agent.get('credential')
    if not isinstance(value, str) or '$' not in value:
        return False
    try:
        salt_text, digest_text = value.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except ValueError:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

