    if not isinstance(records, list) or isinstance(page, bool) or (not isinstance(page, int)) or (page < 1):
        raise ValueError('invalid pagination or records')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        flight = record.get('flight')
        status = record.get('status')
        weight = record.get('weight')
        if not isinstance(flight, str) or not flight or (not isinstance(status, str)):
            raise ValueError('invalid record')
        if isinstance(weight, bool) or not isinstance(weight, (int, float)) or weight < 0:
            raise ValueError('invalid record')
        if status == 'loaded':
            item = groups.setdefault(flight, [0, 0.0])
            item[0] += 1
            item[1] += weight
    result = [{'flight': f, 'bags': v[0], 'weight': round(v[1], 2)} for f, v in groups.items()]
    result.sort(key=lambda x: (-x['weight'], x['flight']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

