        if type(timestamp) is not int or not isinstance(events, list) or (not isinstance(signature, str)):
            raise ValueError
        message = str(timestamp) + '\n' + json.dumps(events, sort_keys=True, separators=(',', ':'))
        expected = hmac.new(secret, message.encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(signature, expected) or abs(timestamp - now) > 300:
            raise ValueError
        result = []
        allowed = {'room', 'category', 'severity', 'opened_at', 'resolved_at'}
        levels = {'low', 'medium', 'high', 'critical'}
        for item in events:
            if not isinstance(item, dict) or set(item) != allowed:
                raise ValueError
            if not isinstance(item['room'], str) or not item['room'] or (not isinstance(item['category'], str)) or (not item['category']) or (item['severity'] not in levels) or (type(item['opened_at']) is not int):
                raise ValueError
            resolved = item['resolved_at']
            if resolved is not None and (type(resolved) is not int or resolved < item['opened_at']):
                raise ValueError
            result.append(dict(item))
        return result
    except (TypeError, json.JSONDecodeError, UnicodeError):
        raise ValueError

def summarize_alerts(events: list[dict]) -> list[dict]:
    levels = {'low': 0, 'medium': 1, 'high': 2, 'critical': 3}
    groups = {}
    for item in events:
        if not isinstance(item, dict) or set(item) != {'room', 'category', 'severity', 'opened_at', 'resolved_at'}:
            raise ValueError
        if not isinstance(item['room'], str) or not item['room'] or (not isinstance(item['category'], str)) or (not item['category']) or (item['severity'] not in levels) or (type(item['opened_at']) is not int) or (item['resolved_at'] is not None and (type(item['resolved_at']) is not int or item['resolved_at'] < item['opened_at'])):
            raise ValueError
        name = item['category']
        if name not in groups:
            groups[name] = {'category': name, 'count': 0, 'active': 0, 'minutes': 0, 'highest_severity': item['severity']}
        out = groups[name]
        out['count'] += 1
        if item['resolved_at'] is None:
            out['active'] += 1
        else:
            out['minutes'] += (item['resolved_at'] - item['opened_at']) // 60
        if levels[item['severity']] > levels[out['highest_severity']]:
            out['highest_severity'] = item['severity']
    return sorted(groups.values(), key=lambda x: (-x['active'], -x['minutes'], x['category']))

