import ast

class _Evaluator:

    def __init__(self, values):
        self.values = values

    def visit(self, node):
        if isinstance(node, ast.Expression):
            return self.visit(node.body)
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in self.values:
                raise NameError(node.id)
            return self.values[node.id]
        if isinstance(node, ast.BinOp):
            a, b = (self.visit(node.left), self.visit(node.right))
            if isinstance(node.op, ast.Add):
                return a + b
            if isinstance(node.op, ast.Sub):
                return a - b
            if isinstance(node.op, ast.Mult):
                return a * b
            if isinstance(node.op, ast.Div):
                return a / b
        if isinstance(node, ast.UnaryOp):
            value = self.visit(node.operand)
            if isinstance(node.op, ast.USub):
                return -value
            if isinstance(node.op, ast.UAdd):
                return +value
            if isinstance(node.op, ast.Not):
                return not value
        if isinstance(node, ast.BoolOp):
            values = [self.visit(x) for x in node.values]
            if isinstance(node.op, ast.And):
                result = values[0]
                for value in values[1:]:
                    result = value if result else result
                return result
            result = values[0]
            for value in values[1:]:
                result = result if result else value
            return result
        if isinstance(node, ast.Compare):
            left = self.visit(node.left)
            for op, part in zip(node.ops, node.comparators):
                right = self.visit(part)
                if isinstance(op, ast.Lt):
                    ok = left < right
                elif isinstance(op, ast.LtE):
                    ok = left <= right
                elif isinstance(op, ast.Gt):
                    ok = left > right
                elif isinstance(op, ast.GtE):
                    ok = left >= right
                elif isinstance(op, ast.Eq):
                    ok = left == right
                else:
                    ok = left != right
                if not ok:
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max', 'round'}) and (not node.keywords):
            return {'min': min, 'max': max, 'round': round}[node.func.id](*[self.visit(x) for x in node.args])
        raise ValueError('invalid expression')

def _evaluate(rule, values):
    return _Evaluator(values).visit(ast.parse(rule, mode='eval'))

def generate_report(records: list[dict], rule: str, page: int, page_size: int) -> dict:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page <= 0) or (page_size <= 0):
        raise ValueError('invalid pagination')
    selected = [r for r in records if _evaluate(rule, {k: r[k] for k in ('amount', 'year', 'indirect', 'score')})]
