    start = (page - 1) * page_size
    grants = [{k: r[k] for k in ('id', 'faculty', 'amount', 'year', 'indirect', 'score')} for r in selected[start:start + page_size]]
    total = sum((r['amount'] for r in selected))
    average = sum((r['score'] for r in selected)) / len(selected) if selected else 0.0
    return {'grants': grants, 'total_count': len(selected), 'total_amount': round(total, 2), 'average_score': round(average, 2)}

