    if not isinstance(requester, dict) or not isinstance(inspections, list):
        raise TypeError('invalid top-level types')
    if page < 1 or page_size < 1:
        raise ValueError('invalid pagination')
    required = {'id', 'facility', 'tenant_id', 'owner_id', 'score', 'violations', 'inspected_at', 'status'}
    allowed = []
    roles = requester.get('roles', [])
    for item in inspections:
        if not isinstance(item, dict) or not required.issubset(item):
            raise ValueError('invalid inspection')
        if not isinstance(item['score'], (int, float)) or not 0 <= item['score'] <= 100:
            raise ValueError('invalid score')
        if not isinstance(item['violations'], int) or item['violations'] < 0:
            raise ValueError('invalid violations')
        if item['owner_id'] == requester.get('id') or ('inspector_admin' in roles and item['tenant_id'] == requester.get('tenant_id')):
            allowed.append(item)
    ordered = sorted(allowed, key=lambda x: (-1, x['id']))
    ordered.sort(key=lambda x: x['inspected_at'], reverse=True)
    total = len(ordered)
    start = (page - 1) * page_size
    counts = {}
    for item in ordered:
        counts[item['status']] = counts.get(item['status'], 0) + 1
    counts = {key: counts[key] for key in sorted(counts)}
    average = None if not ordered else round(sum((x['score'] for x in ordered)) / total, 2)
    return {'total': total, 'page': page, 'page_size': page_size, 'items': ordered[start:start + page_size], 'average_score': average, 'status_counts': counts}

