import hashlib
import hmac
import json
import math

def process_webhook(payload: str, signature: str, secret: str, max_cloud: float=20.0, page: int=1, page_size: int=10) -> dict:
    if not isinstance(signature, str) or len(signature) != 71 or (not signature.startswith('sha256=')):
        raise ValueError('invalid signature')
    supplied = signature[7:]
    if any((c not in '0123456789abcdef' for c in supplied)):
        raise ValueError('invalid signature')
    expected = hmac.new(secret.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(supplied, expected):
        raise ValueError('invalid signature')
    data = json.loads(payload)
    if not isinstance(data, dict) or not isinstance(data.get('scenes'), list):
        raise ValueError('invalid payload')
    if not isinstance(max_cloud, (int, float)) or isinstance(max_cloud, bool) or (not math.isfinite(max_cloud)) or (not 0 <= max_cloud <= 100):
        raise ValueError('invalid cloud limit')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1 or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (page_size < 1):
        raise ValueError('invalid pagination')
    selected = []
    for item in data['scenes']:
        if not isinstance(item, dict) or not isinstance(item.get('id'), str) or (not item['id']) or (not isinstance(item.get('orbit'), int)) or isinstance(item.get('orbit'), bool) or (not isinstance(item.get('acquired'), str)) or (not isinstance(item.get('cloud_cover'), (int, float))) or isinstance(item.get('cloud_cover'), bool) or (not math.isfinite(item['cloud_cover'])):
            raise ValueError('invalid scene')
        if item['cloud_cover'] <= max_cloud:
            selected.append({'id': item['id'], 'orbit': item['orbit'], 'acquired': item['acquired'], 'cloud_cover': item['cloud_cover']})
    selected.sort(key=lambda x: (x['acquired'], x['id']))
    counts = {}
    for item in selected:
        counts[item['orbit']] = counts.get(item['orbit'], 0) + 1
    counts = {str(k): counts[k] for k in sorted(counts)}
    total = len(selected)
    start = (page - 1) * page_size
    return {'total': total, 'page': page, 'pages': (total + page_size - 1) // page_size if total else 0, 'scenes': selected[start:start + page_size], 'orbit_counts': counts}

