import sqlite3

def build_station_report(conn: sqlite3.Connection, station: str | None=None, min_moisture: float | None=None, sort_by: str='station', limit: int=100, offset: int=0) -> list[dict]:
    if station is not None and (not isinstance(station, str) or not station):
        raise ValueError('station must be a nonempty string or None')
    if min_moisture is not None and (isinstance(min_moisture, bool) or not isinstance(min_moisture, (int, float)) or (not math.isfinite(min_moisture))):
        raise ValueError('min_moisture must be finite')
    if sort_by not in {'station', 'average', 'count'}:
        raise ValueError('invalid sort_by')
    if isinstance(limit, bool) or not isinstance(limit, int) or limit < 0:
        raise ValueError('invalid limit')
    if isinstance(offset, bool) or not isinstance(offset, int) or offset < 0:
        raise ValueError('invalid offset')
    clauses = []
    params = []
    if station is not None:
        clauses.append('station = ?')
        params.append(station)
    if min_moisture is not None:
        clauses.append('moisture >= ?')
        params.append(min_moisture)
    query = 'SELECT station, COUNT(*), AVG(moisture), MIN(moisture), MAX(moisture) FROM readings'
    if clauses:
        query += ' WHERE ' + ' AND '.join(clauses)
    query += ' GROUP BY station'
    rows = conn.execute(query, params).fetchall()
    report = [{'station': r[0], 'count': r[1], 'average': round(r[2], 2), 'minimum': round(r[3], 2), 'maximum': round(r[4], 2)} for r in rows]
    if sort_by == 'station':
        report.sort(key=lambda x: x['station'])
    elif sort_by == 'average':
        report.sort(key=lambda x: (-x['average'], x['station']))
    else:
        report.sort(key=lambda x: (-x['count'], x['station']))
    return report[offset:offset + limit]

