import xml.etree.ElementTree as ET
from datetime import date

def _day(value):
    if not isinstance(value, str):
        raise ValueError('invalid date')
    try:
        result = date.fromisoformat(value)
    except ValueError as exc:
        raise ValueError('invalid date') from exc
    if result.isoformat() != value:
        raise ValueError('invalid date')
    return result

def parse_onboarding(xml_text: str) -> list[dict]:
    if not isinstance(xml_text, str):
        raise ValueError('invalid XML')
    try:
        root = ET.fromstring(xml_text)
        if root.tag != 'onboarding':
            raise ValueError('wrong root')
        result = []
        seen = set()
        for node in root:
            if node.tag != 'employee':
                raise ValueError('invalid child')
            values = {}
            for key in ('id', 'name', 'department', 'start'):
                value = node.get(key)
                if value is None or not value.strip():
                    raise ValueError('missing attribute')
                values[key] = value.strip()
            if values['id'] in seen:
                raise ValueError('duplicate id')
            seen.add(values['id'])
            _day(values['start'])
            skills = []
            for child in node:
                if child.tag != 'skill' or child.text is None or (not child.text.strip()):
                    raise ValueError('invalid skill')
                skill = child.text.strip()
                if skill not in skills:
                    skills.append(skill)
            result.append({'id': values['id'], 'name': values['name'], 'department': values['department'], 'start_date': values['start'], 'skills': skills})
        return sorted(result, key=lambda x: (x['start_date'], x['id']))
    except ValueError:
        raise
    except Exception as exc:
        raise ValueError('invalid XML') from exc

def active_summary(xml_text: str, as_of: str) -> dict:
    cutoff = _day(as_of)
    employees = parse_onboarding(xml_text)
    departments = {}
    skills = {}
    active = 0
    for employee in employees:
        if _day(employee['start_date']) <= cutoff:
            active += 1
            departments[employee['department']] = departments.get(employee['department'], 0) + 1
            for skill in employee['skills']:
                skills[skill] = skills.get(skill, 0) + 1
    return {'active_count': active, 'by_department': dict(sorted(departments.items())), 'skills': dict(sorted(skills.items()))}

def employee_labels(xml_text: str) -> list[str]:
    return [f"{x['id']} - {x['name']} ({x['department']})" for x in parse_onboarding(xml_text)]

