def build_loyalty_leaderboard(paths: list[str], minimum_points: int, offset: int, limit: int) -> list[tuple[str, int, int]]:
    if minimum_points < 0 or offset < 0 or limit <= 0:
        raise ValueError('invalid pagination or threshold')
    if not paths:
        return []
    result = subprocess.run(['sort', '-t,', '-k1,1', *paths], capture_output=True, text=True, check=True)
    totals: dict[str, list[int]] = {}
    for raw in result.stdout.splitlines():
        if not raw.strip():
