            points = int(fields[1])
            visits = int(fields[2])
        except ValueError as exc:
            raise ValueError('invalid record') from exc
        if fields[0] not in totals:
            totals[fields[0]] = [0, 0]
        totals[fields[0]][0] += points
        totals[fields[0]][1] += visits
    rows = [(guest, values[0], values[1]) for guest, values in totals.items() if values[0] >= minimum_points]
    rows.sort(key=lambda row: (-row[1], row[0]))
    return rows[offset:offset + limit]

