from datetime import datetime
_STATUSES = ('planned', 'ready', 'complete')
_SORTS = {'start_time': 'start_time', 'scene_number': 'scene_number', 'location': 'location', 'status': 'status'}

def create_schema(conn: sqlite3.Connection) -> None:
    conn.execute('CREATE TABLE IF NOT EXISTS scenes (id INTEGER PRIMARY KEY AUTOINCREMENT, shoot_date TEXT NOT NULL, scene_number TEXT NOT NULL, location TEXT NOT NULL, cast_count INTEGER NOT NULL, start_time TEXT NOT NULL, status TEXT NOT NULL)')
    conn.commit()

def _date(value: str) -> None:
    if not isinstance(value, str) or len(value) != 10:
        raise ValueError('invalid date')
    try:
        if datetime.strptime(value, '%Y-%m-%d').strftime('%Y-%m-%d') != value:
            raise ValueError('invalid date')
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def _time(value: str) -> None:
    if not isinstance(value, str) or len(value) != 5:
        raise ValueError('invalid time')
    try:
        if datetime.strptime(value, '%H:%M').strftime('%H:%M') != value:
            raise ValueError('invalid time')
    except (TypeError, ValueError):
        raise ValueError('invalid time')

def add_scene(conn: sqlite3.Connection, shoot_date: str, scene_number: str, location: str, cast_count: int, start_time: str, status: str='planned') -> int:
    _date(shoot_date)
    _time(start_time)
    if not isinstance(scene_number, str) or not scene_number or (not isinstance(location, str)) or (not location):
        raise ValueError('empty text')
    if isinstance(cast_count, bool) or not isinstance(cast_count, int) or cast_count < 0:
        raise ValueError('invalid cast count')
    if status not in _STATUSES:
        raise ValueError('invalid status')
    cur = conn.execute('INSERT INTO scenes (shoot_date, scene_number, location, cast_count, start_time, status) VALUES (?, ?, ?, ?, ?, ?)', (shoot_date, scene_number, location, cast_count, start_time, status))
    conn.commit()
    return cur.lastrowid

