    _date(shoot_date)
    if sort_key not in _SORTS:
        raise ValueError('invalid sort key')
    query = 'SELECT id, scene_number, location, cast_count, start_time, status FROM scenes WHERE shoot_date = ? ORDER BY ' + _SORTS[sort_key] + ' ASC, scene_number ASC, id ASC'
    rows = conn.execute(query, (shoot_date,)).fetchall()
    names = ('id', 'scene_number', 'location', 'cast_count', 'start_time', 'status')
    return [dict(zip(names, row)) for row in rows]

def update_scene_status(conn: sqlite3.Connection, scene_id: int, status: str) -> bool:
    if isinstance(scene_id, bool) or not isinstance(scene_id, int) or status not in _STATUSES:
        raise ValueError('invalid argument')
    cur = conn.execute('UPDATE scenes SET status = ? WHERE id = ?', (status, scene_id))
    conn.commit()
    return cur.rowcount == 1

