import os
from pathlib import Path

def save_underwriting_document(base_dir: str, document_name: str, contents: str) -> str:
    if not document_name:
        raise ValueError('document_name must not be empty')
    base = Path(base_dir)
    base.mkdir(parents=True, exist_ok=True)
    base = base.resolve()
    target = (base / document_name).resolve()
    try:
        target.relative_to(base)
    except ValueError:
        raise ValueError('document_name must stay within base_dir')
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(contents, encoding='utf-8')
    return str(target)

