        second = write_log(directory, 'second.log', 'fin,81.5\nbody,33.333\n')
        assert rank_components([first, second]) == [('fin', 81.5), ('engine', 44.25), ('body', 33.33)]

def test_limit_boundaries_and_zero():
    with tempfile.TemporaryDirectory() as directory:
        path = write_log(directory, 'many.log', 'a,1\nb,3\nc,2\n')
        assert rank_components([path], 0) == []
        assert rank_components([path], 1) == [('b', 3.0)]
        assert rank_components([path], 2) == [('b', 3.0), ('c', 2.0)]
        assert rank_components([path], 10) == [('b', 3.0), ('c', 2.0), ('a', 1.0)]

