import subprocess

def rank_components(paths: list[str], limit: int=10) -> list[tuple[str, float]]:
    if not isinstance(paths, (list, tuple)) or not paths or (not all((isinstance(path, str) for path in paths))):
        raise ValueError('paths must be a non-empty sequence of strings')
    if isinstance(limit, bool) or not isinstance(limit, int) or limit < 0:
        raise ValueError('limit must be a non-negative integer')
    try:
        result = subprocess.run(['sort', '-t,', '-k2,2n', '--', *paths], check=True, capture_output=True, text=True)
    except (OSError, subprocess.CalledProcessError) as exc:
        raise ValueError('unable to read input files') from exc
    peaks: dict[str, float] = {}
    for raw in result.stdout.splitlines():
        if not raw.strip() or raw.lstrip().startswith('#'):
            continue
        fields = raw.split(',')
        if len(fields) != 2:
            raise ValueError('malformed record')
        name = fields[0].strip()
        if not name:
            raise ValueError('empty component name')
        try:
            temperature = float(fields[1].strip())
        except ValueError as exc:
            raise ValueError('invalid temperature') from exc
        if name not in peaks or temperature > peaks[name]:
            peaks[name] = temperature
    ordered = sorted(peaks.items(), key=lambda item: (-item[1], item[0]))
    return [(name, round(value, 2)) for name, value in ordered[:limit]]

