import datetime
import secrets

def _split(line):
    fields = []
    current = []
    escaped = False
    for ch in line:
        if escaped:
            if ch not in '|\\':
                raise ValueError('invalid escape')
            current.append(ch)
            escaped = False
        elif ch == '\\':
            escaped = True
        elif ch == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(ch)
    if escaped:
        raise ValueError('trailing escape')
    fields.append(''.join(current))
    return fields

def parse_renewal_feed(text: str) -> list[dict]:
    result = []
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith('#'):
            continue
        fields = _split(line)
        if len(fields) != 5 or not fields[0] or (not fields[1]):
            raise ValueError('invalid record')
        try:
            datetime.date.fromisoformat(fields[2])
            amount = int(fields[3])
        except (ValueError, TypeError):
            raise ValueError('invalid record')
        if amount < 0 or fields[4] not in {'ACTIVE', 'RENEWED', 'CANCELLED'}:
            raise ValueError('invalid record')
        result.append({'contract_id': fields[0], 'vendor': fields[1], 'renewal_date': fields[2], 'amount_cents': amount, 'status': fields[4]})
    return result

def summarize_renewals(records: list[dict], as_of: str) -> dict:
    try:
        start = datetime.date.fromisoformat(as_of)
    except ValueError:
        raise ValueError('invalid date')
    end = start + datetime.timedelta(days=90)
    groups = {}
    for r in records:
        if set(r) != {'contract_id', 'vendor', 'renewal_date', 'amount_cents', 'status'} or not r['contract_id'] or (not r['vendor']) or (r['status'] not in {'ACTIVE', 'RENEWED', 'CANCELLED'}) or (not isinstance(r['amount_cents'], int)) or (r['amount_cents'] < 0):
            raise ValueError('invalid record')
        try:
            day = datetime.date.fromisoformat(r['renewal_date'])
        except ValueError:
            raise ValueError('invalid date')
        if r['status'] == 'ACTIVE' and start <= day < end:
            groups.setdefault(r['vendor'], []).append((day, r['contract_id'], r['amount_cents']))
    vendors = []
    for vendor, items in groups.items():
        items.sort(key=lambda x: (x[0], x[1]))
        vendors.append({'vendor': vendor, 'count': len(items), 'amount_cents': sum((x[2] for x in items)), 'contracts': [x[1] for x in items]})
    vendors.sort(key=lambda x: (-x['amount_cents'], -x['count'], x['vendor']))
    return {'as_of': as_of, 'due_count': sum((x['count'] for x in vendors)), 'due_amount_cents': sum((x['amount_cents'] for x in vendors)), 'vendors': vendors}

def generate_invite_code(length: int=16) -> str:
    if not 8 <= length <= 64:
        raise ValueError('invalid length')
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    return ''.join((secrets.choice(alphabet) for _ in range(length)))

