def export_verification_report(records: list[dict], destination: str, min_score: float=0.0) -> dict[str, int]:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    if isinstance(min_score, bool) or not isinstance(min_score, (int, float)) or (not math.isfinite(min_score)) or (not 0.0 <= min_score <= 1.0):
        raise ValueError('invalid threshold')
    valid_statuses = {'pending', 'verified', 'rejected'}
    selected = []
    for record in records:
        if not isinstance(record, dict) or not all((key in record for key in ('customer_id', 'status', 'score'))):
            raise ValueError('invalid record')
        customer_id = record['customer_id']
        status = record['status']
        score = record['score']
        if not isinstance(customer_id, str) or not customer_id or status not in valid_statuses:
            raise ValueError('invalid record')
        if isinstance(score, bool) or not isinstance(score, (int, float)) or (not math.isfinite(score)) or (not 0.0 <= score <= 1.0):
            raise ValueError('invalid record')
        if score >= min_score:
            selected.append((customer_id, status, score))
    selected.sort(key=lambda item: (-item[2], item[0]))
    counts = {}
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent, prefix='.verification-', suffix='.csv')
    os.close(fd)
    try:
        with open(temporary, 'w', encoding='utf-8', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['customer_id', 'status', 'score', 'decision'])
            for customer_id, status, score in selected:
                writer.writerow([customer_id, status, f'{score:.2f}', 'verified' if score >= 0.8 else 'review'])
                counts.setdefault(status, 0)
                counts[status] += 1
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return counts

