import base64
import hashlib
import hmac
import os

def create_passcode_record(passcode: str) -> str:
    if not isinstance(passcode, str):
        raise TypeError('passcode must be a string')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', passcode.encode('utf-8'), salt, 100000)
    return base64.b64encode(salt).decode('ascii') + '.' + base64.b64encode(digest).decode('ascii')

def verify_passcode(stored_record: str, candidate: str) -> bool:
    if not isinstance(stored_record, str) or not isinstance(candidate, str):
        raise TypeError('arguments must be strings')
    try:
        salt_text, digest_text = stored_record.split('.')
        salt = base64.b64decode(salt_text.encode('ascii'), validate=True)
        expected = base64.b64decode(digest_text.encode('ascii'), validate=True)
        if len(salt) != 16 or len(expected) != 32:
            return False
    except (ValueError, UnicodeEncodeError, base64.binascii.Error):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', candidate.encode('utf-8'), salt, 100000)
    return hmac.compare_digest(actual, expected)

