import os
import json
import hmac
import hashlib

def _key(config):
    value = config.get('receipt_key')
    if value is None:
        value = os.environ.get('CONF_RECEIPT_KEY')
    if value is None:
        raise ValueError('receipt key is required')
    return str(value).encode()

def _minutes(value):
    if not isinstance(value, str) or len(value) != 5 or value[2] != ':':
        raise ValueError('invalid time')
    try:
        hour, minute = (int(value[:2]), int(value[3:]))
    except ValueError:
        raise ValueError('invalid time')
    if hour > 23 or minute > 59 or hour < 0 or (minute < 0):
        raise ValueError('invalid time')
    return hour * 60 + minute

def process_registrations(registrations: list[dict], config: dict) -> list[dict]:
    key = _key(config)
    sessions = config.get('sessions')
    if not isinstance(sessions, dict):
        raise ValueError('invalid sessions')
    remaining, parsed = ({}, {})
    for code, item in sessions.items():
        try:
            start, end = (_minutes(item['start']), _minutes(item['end']))
            capacity = item['capacity']
            if end <= start or not isinstance(capacity, int) or isinstance(capacity, bool) or (capacity < 0):
                raise ValueError
            parsed[code], remaining[code] = ((start, end), capacity)
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid session')
    output = []
    for row in registrations:
        if not isinstance(row, dict) or not isinstance(row.get('attendee'), str) or (not isinstance(row.get('email'), str)) or (not isinstance(row.get('sessions'), list)):
            raise ValueError('invalid registration')
        accepted, waitlisted, occupied = ([], [], [])
        for code in row['sessions']:
            if code in accepted or code in waitlisted:
                continue
            if code not in parsed:
                raise ValueError('unknown session')
            start, end = parsed[code]
            conflict = any((start < b and end > a for a, b in occupied))
            if remaining[code] and (not conflict):
                accepted.append(code)
                remaining[code] -= 1
                occupied.append((start, end))
            else:
