_STATUS = {'awarded': 0, 'accepted': 1, 'pending': 2, 'rejected': 3}
_FIELDS = ('id', 'origin', 'destination', 'weight', 'rate', 'status')

def normalize_tenders(records: list[dict]) -> list[dict]:
    result = []
    for source in records:
        if not isinstance(source, dict):
            raise ValueError('record must be a mapping')
        if any((field not in source for field in _FIELDS)):
            raise ValueError('missing field')
        text = {}
        for field in ('id', 'origin', 'destination'):
            value = source[field]
            if not isinstance(value, str) or not value.strip():
                raise ValueError('invalid text')
            text[field] = value.strip()
        status = source['status']
        if not isinstance(status, str) or status not in _STATUS:
            raise ValueError('invalid status')
        try:
            weight = float(source['weight'])
            rate = float(source['rate'])
        except (TypeError, ValueError, OverflowError):
            raise ValueError('invalid number')
        if not math.isfinite(weight) or not math.isfinite(rate) or weight <= 0 or (rate <= 0):
            raise ValueError('invalid number')
        result.append({**text, 'weight': weight, 'rate': rate, 'status': status, 'value': round(weight * rate, 2)})
    result.sort(key=lambda x: (_STATUS[x['status']], x['destination'].casefold(), -x['rate'], x['id']))
    return result

