    rows = normalize_tenders(records)
    parent = os.path.dirname(os.path.abspath(destination))
    os.makedirs(parent, exist_ok=True)
    fd, temporary = tempfile.mkstemp(prefix='tender-', suffix='.csv', dir=parent)
    os.close(fd)
    try:
        with open(temporary, 'w', encoding='utf-8', newline='') as stream:
            writer = csv.writer(stream, lineterminator='\n')
            writer.writerow(['id', 'origin', 'destination', 'weight', 'rate', 'status', 'value'])
            for row in rows:
                writer.writerow([row['id'], row['origin'], row['destination'], f"{row['weight']:.2f}", f"{row['rate']:.2f}", row['status'], f"{row['value']:.2f}"])
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return {'count': len(rows), 'total_weight': round(sum((x['weight'] for x in rows)), 2), 'total_value': round(sum((x['value'] for x in rows)), 2)}

