    return hmac.new(key.encode("utf-8"), payload, hashlib.sha256).hexdigest()


def test_signature_matches_expected_digest():
    with patch.dict(os.environ, {"INDUSTRIAL_SENSOR_SIGNING_KEY": "alpha-key"}, clear=False):
        result = sensor_reading_signature("furnace-07", 83.5, 1700000000)
    assert result == expected_signature("alpha-key", "furnace-07", 83.5, 1700000000)


def test_temperature_is_formatted_to_two_decimal_places():
    with patch.dict(os.environ, {"INDUSTRIAL_SENSOR_SIGNING_KEY": "format-key"}, clear=False):
        result = sensor_reading_signature("tank", 21, 12)
    assert result == expected_signature("format-key", "tank", 21, 12)


def test_unicode_sensor_id_is_supported():
    with patch.dict(os.environ, {"INDUSTRIAL_SENSOR_SIGNING_KEY": "unicode-key"}, clear=False):
        result = sensor_reading_signature("炉-温度", -4.256, 99)
    assert result == expected_signature("unicode-key", "炉-温度", -4.256, 99)


def test_environment_key_changes_the_result():
    with patch.dict(os.environ, {"INDUSTRIAL_SENSOR_SIGNING_KEY": "first-key"}, clear=False):
        first = sensor_reading_signature("line-a", 10.0, 1)
