        second = sensor_reading_signature("line-a", 10.0, 1)
    assert first == expected_signature("first-key", "line-a", 10.0, 1)
    assert second == expected_signature("second-key", "line-a", 10.0, 1)
    assert first != second


def test_empty_sensor_id_is_rejected():
    with patch.dict(os.environ, {"INDUSTRIAL_SENSOR_SIGNING_KEY": "key"}, clear=False):
        try:
            sensor_reading_signature("", 1.0, 0)
        except ValueError as exc:
            assert "sensor_id" in str(exc)
        else:
            assert False


def test_non_finite_temperature_is_rejected():
    with patch.dict(os.environ, {"INDUSTRIAL_SENSOR_SIGNING_KEY": "key"}, clear=False):
