import base64
import hashlib
import hmac
import os

def register_operator(operator_id: str, password: str, station: str) -> dict:
    if not isinstance(operator_id, str) or not operator_id:
        raise ValueError('invalid operator id')
    if not isinstance(station, str) or not station:
        raise ValueError('invalid station')
    if not isinstance(password, str) or len(password) < 4:
        raise ValueError('invalid password')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    stored = base64.b64encode(salt).decode() + ':' + base64.b64encode(digest).decode()
    return {'operator_id': operator_id, 'station': station, 'password_hash': stored}

def authenticate_operator(record: dict, password: str) -> bool:
    if not isinstance(record, dict) or not isinstance(password, str):
        return False
    stored = record.get('password_hash')
    if not isinstance(stored, str) or ':' not in stored:
        return False
    try:
        salt_text, digest_text = stored.split(':', 1)
        salt = base64.b64decode(salt_text.encode(), validate=True)
        expected = base64.b64decode(digest_text.encode(), validate=True)
    except Exception:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def takt_status(elapsed_seconds: float, units_completed: int, target_cycle_seconds: float) -> dict:
    if elapsed_seconds < 0 or units_completed <= 0 or target_cycle_seconds <= 0:
        raise ValueError('invalid takt values')
    actual = round(elapsed_seconds / units_completed, 2)
    expected = round(elapsed_seconds / target_cycle_seconds, 2)
    return {'units_completed': units_completed, 'target_cycle_seconds': target_cycle_seconds, 'actual_cycle_seconds': actual, 'units_expected': expected, 'on_schedule': units_completed >= expected}

