import ast
import math

def _expression(tree, env):
    allowed = {'min': min, 'max': max, 'round': round}

    def visit(node):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, str, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id in env:
                return env[node.id]
            if node.id in allowed:
                return allowed[node.id]
            raise ValueError()
        if isinstance(node, ast.BinOp):
            a, b = (visit(node.left), visit(node.right))
            ops = {ast.Add: lambda: a + b, ast.Sub: lambda: a - b, ast.Mult: lambda: a * b, ast.Div: lambda: a / b, ast.Mod: lambda: a % b}
            if type(node.op) not in ops:
                raise ValueError()
            return ops[type(node.op)]()
        if isinstance(node, ast.UnaryOp):
            value = visit(node.operand)
            if isinstance(node.op, ast.USub):
                return -value
            if isinstance(node.op, ast.UAdd):
                return +value
            if isinstance(node.op, ast.Not):
                return not value
            raise ValueError()
        if isinstance(node, ast.BoolOp):
            values = [visit(x) for x in node.values]
            if isinstance(node.op, ast.And):
                return all(values)
            if isinstance(node.op, ast.Or):
                return any(values)
            raise ValueError()
        if isinstance(node, ast.Compare):
            left = visit(node.left)
            for op, right_node in zip(node.ops, node.comparators):
                right = visit(right_node)
                good = {ast.Eq: left == right, ast.NotEq: left != right, ast.Lt: left < right, ast.LtE: left <= right, ast.Gt: left > right, ast.GtE: left >= right}
                if type(op) not in good:
                    raise ValueError()
                if not good[type(op)]:
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in allowed) and (not node.keywords):
            return allowed[node.func.id](*(visit(x) for x in node.args))
        raise ValueError()
    return visit(tree.body)

def find_lift_ticket_offers(tickets: list[dict], condition: str, page: int=1, page_size: int=10) -> dict:
    if page < 1 or page_size < 1:
        raise ValueError()
    try:
        tree = ast.parse(condition, mode='eval')
    except Exception as exc:
        raise ValueError() from exc
    required = {'name', 'age', 'days', 'base_price', 'student', 'blackout'}
    found = []
    for item in tickets:
        if not isinstance(item, dict) or set(item) != required:
            raise ValueError()
        if not isinstance(item['name'], str) or not isinstance(item['age'], int) or (not isinstance(item['days'], int)) or (not isinstance(item['base_price'], (int, float))) or (not isinstance(item['student'], bool)) or (not isinstance(item['blackout'], bool)):
            raise ValueError()
        total = round(item['base_price'] * item['days'] * (0.8 if item['student'] else 1.0) + (5.0 if item['blackout'] else 0.0), 2)
        env = dict(item, total=total)
        try:
            matched = bool(_expression(tree, env))
        except Exception as exc:
            raise ValueError() from exc
        if matched:
            found.append({'name': item['name'], 'total': total})
    found.sort(key=lambda x: (x['total'], x['name']))
    count = len(found)
    pages = math.ceil(count / page_size) if count else 0
    start = (page - 1) * page_size
    selected = found[start:start + page_size]
    return {'count': count, 'page': page, 'pages': pages, 'subtotal': round(sum((x['total'] for x in selected)), 2), 'tickets': selected}

