import csv
import math
import subprocess

def read_zoning_applications(path: str) -> list[dict]:
    expected = ['application_id', 'zone', 'applicant', 'score', 'status', 'area']
    try:
        with open(path, encoding='utf-8', newline='') as handle:
            rows = list(csv.reader((line for line in handle if line.strip())))
    except (OSError, csv.Error) as exc:
        raise ValueError('invalid application file') from exc
    if not rows or rows[0] != expected:
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if len(row) != 6 or any((not row[i].strip() for i in (0, 1, 2, 4))):
            raise ValueError('invalid row')
        try:
            score = float(row[3])
            area = float(row[5])
        except ValueError as exc:
            raise ValueError('invalid number') from exc
        if not math.isfinite(score) or not math.isfinite(area) or area < 0:
            raise ValueError('invalid number')
        result.append({'application_id': row[0], 'zone': row[1], 'applicant': row[2], 'score': score, 'status': row[4], 'area': area})
    return result

def rank_zoning_applications(path: str, minimum_score: float=0.0) -> list[dict]:
    try:
        threshold = float(minimum_score)
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid threshold') from exc
    if not math.isfinite(threshold):
        raise ValueError('invalid threshold')
    rows = read_zoning_applications(path)
    try:
        completed = subprocess.run(['sort', '-t,', '-k4,4nr', '-k1,1', path], capture_output=True, text=True, check=True)
    except (OSError, subprocess.CalledProcessError) as exc:
        raise ValueError('unable to sort applications') from exc
    selected = []
    for row in csv.reader((line for line in completed.stdout.splitlines() if line.strip())):
        if row == ['application_id', 'zone', 'applicant', 'score', 'status', 'area']:
            continue
        if len(row) == 6:
            item = next((x for x in rows if x['application_id'] == row[0] and x['zone'] == row[1]), None)
            if item and item['status'] == 'approved' and (item['score'] >= threshold):
                selected.append(item)
    return selected

def summarize_zoning_applications(path: str) -> dict[str, dict]:
    rows = read_zoning_applications(path)
    result = {}
    for row in rows:
        zone = row['zone']
        if zone not in result:
            result[zone] = {'application_count': 0, 'approved_count': 0, 'approved_area': 0.0, 'average_approved_score': None}
        entry = result[zone]
        entry['application_count'] += 1
        if row['status'] == 'approved':
            entry['approved_count'] += 1
            entry['approved_area'] += row['area']
            old = entry['average_approved_score'] or 0.0
            entry['average_approved_score'] = old + row['score']
    for entry in result.values():
        if entry['approved_count']:
            entry['approved_area'] = round(entry['approved_area'], 2)
            entry['average_approved_score'] = round(entry['average_approved_score'] / entry['approved_count'], 2)
    return result

