from datetime import date, timedelta

def _date(value):
    try:
        return date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def parse_claims(text: str) -> list[dict]:
    if not isinstance(text, str):
        raise ValueError('invalid claims')
    result = []
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields = []
        buf = []
        escaped = False
        for ch in raw:
            if escaped:
                buf.append(ch)
                escaped = False
            elif ch == '\\':
                escaped = True
            elif ch == '|':
                fields.append(''.join(buf))
                buf = []
            else:
                buf.append(ch)
        if escaped:
            raise ValueError('invalid escape')
        fields.append(''.join(buf))
        if len(fields) != 3:
            raise ValueError('invalid claim')
        try:
            number = int(fields[0].strip())
        except ValueError:
            raise ValueError('invalid number')
        kind = fields[1].strip()
        if number != len(result) + 1 or kind not in ('apparatus', 'method'):
            raise ValueError('invalid claim')
        result.append({'number': number, 'kind': kind, 'text': fields[2].strip()})
    return result

def payment_summary(payments: list[dict], filing_date: str) -> dict:
    end = _date(filing_date)
    counted = []
    for payment in payments:
        try:
            pid = payment['id']
            when = _date(payment['date'])
            amount = payment['amount_cents']
            currency = payment['currency']
        except (KeyError, TypeError):
            raise ValueError('invalid payment')
        if not isinstance(pid, str) or not pid or (not isinstance(amount, int)) or isinstance(amount, bool) or (amount < 0) or (currency not in ('USD', 'EUR')):
            raise ValueError('invalid payment')
        if payment.get('status') == 'accepted' and currency == 'USD' and (end - timedelta(days=30) <= when <= end):
            counted.append((when, pid, amount))
    counted.sort(key=lambda x: (x[0], x[1]))
    return {'total_cents': sum((x[2] for x in counted)), 'payment_ids': [x[1] for x in counted]}

def prepare_filing(requester: dict, application: dict, claims_text: str, payments: list[dict]) -> dict:
    try:
        rid = requester['id']
        rtenant = requester['tenant_id']
        roles = requester['roles']
        aid = application['application_id']
        tenant = application['tenant_id']
        owner = application['owner_id']
        title = application['title']
        filing_date = application['filing_date']
    except (KeyError, TypeError):
        raise ValueError('invalid data')
    if not isinstance(rid, str) or not isinstance(rtenant, str) or (not isinstance(roles, list)):
        raise ValueError('invalid requester')
    if not all((isinstance(x, str) and x for x in (aid, tenant, owner, title))):
        raise ValueError('invalid application')
    if rtenant != tenant or not (rid == owner or 'patent_attorney' in roles):
        raise PermissionError('not authorized')
    _date(filing_date)
    claims = parse_claims(claims_text)
    if not claims:
        raise ValueError('claims required')
    summary = payment_summary(payments, filing_date)
    return {'application_id': aid, 'tenant_id': tenant, 'owner_id': owner, 'title': title, 'filing_date': filing_date, 'claims': claims, 'claim_count': len(claims), 'payment_total_cents': summary['total_cents'], 'payment_ids': summary['payment_ids']}

