from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from lxml import etree

def parse_invoice_report(xml_text: str, min_total: str='0.00', page: int=1, page_size: int=20) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page <= 0:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size <= 0:
        raise ValueError('invalid page size')
    try:
        minimum = Decimal(str(min_total))
        if not minimum.is_finite():
            raise ValueError('invalid minimum')
    except (InvalidOperation, ValueError, TypeError):
        raise ValueError('invalid minimum')
    parser = etree.XMLParser(resolve_entities=False, load_dtd=False, no_network=True)
    try:
        root = etree.fromstring(xml_text.encode() if isinstance(xml_text, str) else xml_text, parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'invoices':
        raise ValueError('invalid root')
    records = []
    seen = set()
    quantum = Decimal('0.01')
    for node in root.findall('invoice'):
        values = {key: node.get(key) for key in ('id', 'advertiser', 'currency', 'issue_date')}
        if any((value is None or value == '' for value in values.values())):
            raise ValueError('missing invoice attribute')
        if values['id'] in seen:
            raise ValueError('duplicate invoice id')
        seen.add(values['id'])
        total = Decimal('0')
        lines = node.findall('line')
        for line in lines:
            campaign = line.get('campaign')
            if campaign is None or campaign == '':
                raise ValueError('missing campaign')
