        with open(path, encoding='utf-8') as handle:
            for line_number, raw in enumerate(handle, 1):
                if not raw.strip():
                    continue
                fields = [part.strip() for part in raw.rstrip('\n').split('|')]
                if len(fields) != 4 or not fields[0] or (not fields[1]):
                    raise ValueError(f'invalid line {line_number}')
                try:
                    winner_score = int(fields[2])
                    loser_score = int(fields[3])
                except ValueError as exc:
                    raise ValueError(f'invalid line {line_number}') from exc
                if winner_score < 0 or loser_score < 0 or winner_score <= loser_score:
                    raise ValueError(f'invalid line {line_number}')
                matches.append((fields[0], fields[1], winner_score, loser_score))
    return matches

