    table = {}
    for winner, loser, winner_score, loser_score in matches:
        table.setdefault(winner, [0, 0, 0])
        table.setdefault(loser, [0, 0, 0])
        table[winner][0] += 1
        table[loser][1] += 1
        table[winner][2] += winner_score - loser_score
        table[loser][2] -= winner_score - loser_score
    return sorted([(name, values[0], values[1], values[2]) for name, values in table.items()], key=lambda row: (-row[1], -row[3], row[0]))

