def parse_donation_feed(text: str) -> list[dict]:
    lines = [line for line in text.splitlines() if line.strip()]
    if not lines:
        raise ValueError('donation feed is empty')
    reader = csv.reader(lines, skipinitialspace=True)
    rows = list(reader)
    if rows[0] != ['donor_id', 'name', 'year', 'amount', 'campaign']:
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if len(row) != 5:
            raise ValueError('invalid row')
        donor_id, name, year_text, amount_text, campaign = [x.strip() for x in row]
        if not donor_id or not name or (not campaign):
            raise ValueError('empty field')
        try:
            year = int(year_text)
            amount = Decimal(amount_text)
        except (ValueError, InvalidOperation):
            raise ValueError('invalid numeric value')
        if year < 1900 or year > 2100 or (not amount.is_finite()) or (amount < 0) or (amount.as_tuple().exponent < -2):
            raise ValueError('invalid numeric value')
        result.append({'donor_id': donor_id, 'name': name, 'year': year, 'amount_cents': int(amount * 100), 'campaign': campaign})
    return result

def create_donation_report(records: list[dict], config: dict[str, str]) -> dict:
    if 'DONATION_SIGNING_KEY' not in config:
        raise ValueError('DONATION_SIGNING_KEY is required')
    donors = {}
    campaigns = {}
    years = {}
    for record in records:
        ident = record['donor_id']
        if ident in donors and donors[ident]['name'] != record['name']:
            raise ValueError('donor has conflicting names')
        if ident not in donors:
            donors[ident] = {'donor_id': ident, 'name': record['name'], 'total_cents': 0, 'donation_count': 0, 'campaigns': {}}
        item = donors[ident]
        amount = record['amount_cents']
        item['total_cents'] += amount
        item['donation_count'] += 1
        item['campaigns'][record['campaign']] = item['campaigns'].get(record['campaign'], 0) + amount
        campaigns[record['campaign']] = campaigns.get(record['campaign'], 0) + amount
        years[record['year']] = years.get(record['year'], 0) + amount
    donor_list = []
    for item in donors.values():
        item['campaigns'] = dict(sorted(item['campaigns'].items()))
        donor_list.append(item)
    donor_list.sort(key=lambda x: (-x['total_cents'], x['donor_id']))
    body = {'donors': donor_list, 'campaign_totals': dict(sorted(campaigns.items())), 'year_totals': dict(sorted(years.items()))}
    encoded = json.dumps(body, sort_keys=True, separators=(',', ':')).encode()
    body['signature'] = hmac.new(config['DONATION_SIGNING_KEY'].encode(), encoded, hashlib.sha256).hexdigest()
    return body

