from lxml import etree
import math

def _number(value, name):
    try:
        result = float(value)
    except (TypeError, ValueError):
        raise ValueError(name)
    if not math.isfinite(result):
        raise ValueError(name)
    return result

def parse_telemetry(xml_text: str) -> dict:
    if not isinstance(xml_text, str):
        raise ValueError('xml')
    try:
        parser = etree.XMLParser(resolve_entities=False, load_dtd=False, no_network=True)
        root = etree.fromstring(xml_text.encode(), parser)
    except Exception as exc:
        raise ValueError('xml') from exc
    if root.tag != 'report' or not root.get('engine', '').strip():
        raise ValueError('root')
    samples = []
    previous = -1
    for node in root:
        if node.tag != 'sample':
            continue
        try:
            timestamp = int(node.get('ts'))
        except (TypeError, ValueError):
            raise ValueError('sample')
        spool = _number(node.get('spool'), 'spool')
        egt = _number(node.get('egt'), 'egt')
        fuel = _number(node.get('fuel'), 'fuel')
        if timestamp < 0 or timestamp <= previous or (not 0 <= spool <= 100) or (fuel < 0):
            raise ValueError('sample')
        previous = timestamp
        samples.append({'timestamp': timestamp, 'spool': spool, 'egt': egt, 'fuel': fuel})
    alerts = []
    for container in root:
        if container.tag != 'alerts':
            continue
        for node in container:
            if node.tag != 'alert' or not node.get('code', '').strip():
                raise ValueError('alert')
            try:
                severity = int(node.get('severity'))
            except (TypeError, ValueError):
                raise ValueError('alert')
            message = '' if node.text is None else node.text.strip()
            if not 1 <= severity <= 5:
                raise ValueError('alert')
            alerts.append({'code': node.get('code').strip(), 'severity': severity, 'message': message})
    return {'engine': root.get('engine'), 'samples': samples, 'alerts': alerts}

def summarize_telemetry(report: dict, window: int) -> list[dict]:
    if not isinstance(window, int) or isinstance(window, bool) or window <= 0:
        raise ValueError('window')
    if not isinstance(report, dict) or not isinstance(report.get('samples'), list):
        raise ValueError('report')
