import json
import os
import tempfile

def build_distribution_manifest(events: list[dict], window: int=60) -> dict:
    if isinstance(window, bool) or not isinstance(window, int) or window <= 0:
        raise ValueError('invalid window')
    grouped = {}
    for event in events:
        if not isinstance(event, dict):
            raise ValueError('invalid event')
        for key in ('timestamp', 'asset', 'region', 'bytes', 'status'):
            if key not in event:
                raise ValueError('missing field')
        timestamp = event['timestamp']
        amount = event['bytes']
        if isinstance(timestamp, bool) or not isinstance(timestamp, int) or timestamp < 0:
            raise ValueError('invalid timestamp')
        if isinstance(amount, bool) or not isinstance(amount, int) or amount < 0:
            raise ValueError('invalid bytes')
        if not isinstance(event['asset'], str) or not event['asset']:
            raise ValueError('invalid asset')
        if not isinstance(event['region'], str) or not event['region']:
            raise ValueError('invalid region')
        if event['status'] not in ('ok', 'retry'):
            raise ValueError('invalid status')
        if event['status'] == 'retry':
            continue
        start = timestamp // window * window
        region = event['region']
        asset = event['asset']
        bucket = grouped.setdefault(start, {})
        stats = bucket.setdefault(region, {'bytes': 0, 'events': 0, 'assets': {}})
        stats['bytes'] += amount
        stats['events'] += 1
        asset_stats = stats['assets'].setdefault(asset, {'bytes': 0, 'events': 0})
        asset_stats['bytes'] += amount
        asset_stats['events'] += 1
    buckets = []
    for start in sorted(grouped):
        regions = {}
        for region in sorted(grouped[start]):
            value = grouped[start][region]
            value['assets'] = {k: value['assets'][k] for k in sorted(value['assets'])}
            regions[region] = value
        buckets.append({'start': start, 'regions': regions})
    return {'window': window, 'buckets': buckets}

def export_distribution_manifest(events: list[dict], output_path: str, window: int=60) -> dict:
    manifest = build_distribution_manifest(events, window)
    directory = os.path.dirname(os.path.abspath(output_path))
    fd, temporary = tempfile.mkstemp(dir=directory)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8') as stream:
            json.dump(manifest, stream, indent=2, sort_keys=True)
            stream.write('\n')
        os.replace(temporary, output_path)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return manifest

