def process_work_order_webhook(payload: bytes, headers: dict[str, str], secret: bytes) -> dict:
    signature = None
    for key, value in headers.items():
        if key.lower() == 'x-work-order-signature':
            signature = value
            break
    if not isinstance(signature, str) or len(signature) != 71 or (not signature.startswith('sha256=')):
        raise ValueError('invalid signature')
    supplied = signature[7:]
    if any((c not in '0123456789abcdef' for c in supplied)):
        raise ValueError('invalid signature')
    expected = hmac.new(secret, payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(supplied, expected):
        raise ValueError('invalid signature')
    try:
        data = json.loads(payload.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(data, dict) or not isinstance(data.get('work_order'), str) or (not data['work_order']):
        raise ValueError('invalid payload')
    if not isinstance(data.get('asset'), str) or not data['asset'] or (not isinstance(data.get('events'), list)) or (not data['events']):
        raise ValueError('invalid payload')
    expected_states = ['scheduled', 'in_progress', 'completed']
    totals = {}
    previous = None
    for index, event in enumerate(data['events']):
        if not isinstance(event, dict) or set(event) != {'at', 'minutes', 'state', 'technician'}:
            raise ValueError('invalid event')
        if not isinstance(event['at'], str) or not event['at'].endswith('Z'):
            raise ValueError('invalid event')
        try:
            moment = datetime.datetime.strptime(event['at'], '%Y-%m-%dT%H:%M:%SZ')
        except ValueError as exc:
            raise ValueError('invalid event') from exc
        if previous is not None and moment <= previous:
            raise ValueError('invalid event')
        previous = moment
        if index >= 3 or event['state'] != expected_states[index]:
            raise ValueError('invalid event')
        if isinstance(event['minutes'], bool) or not isinstance(event['minutes'], int) or event['minutes'] < 0:
            raise ValueError('invalid event')
        if not isinstance(event['technician'], str) or not event['technician']:
