    ordered = dict(sorted(totals.items(), key=lambda item: (-item[1], item[0])))
    return {'work_order': data['work_order'], 'asset': data['asset'], 'total_minutes': sum(totals.values()), 'completed': True, 'technician_minutes': ordered}

