    result = build_transmittal_manifest(requester(), docs(), ['d2', 'd3', 'd1', 'd4'], 1, 10)
    assert result['total_documents'] == 4
    assert result['total_bytes'] == 65
    assert result['disciplines'] == [{'discipline': 'A', 'documents': 3, 'bytes': 45}, {'discipline': 'E', 'documents': 1, 'bytes': 20}]
    assert [x['id'] for x in result['items']] == ['d4', 'd1', 'd3', 'd2']
    assert result['total_pages'] == 1

