    result = build_transmittal_manifest(requester(), docs(), [], 3, 2)
    assert result == {'total_documents': 0, 'total_bytes': 0, 'disciplines': [], 'page': 3, 'page_size': 2, 'total_pages': 0, 'items': []}

def test_empty_page_after_results():
    result = build_transmittal_manifest(requester(), docs(), ['d1'], 2, 1)
    assert result['total_pages'] == 1
    assert result['items'] == []

def test_missing_id_raises_key_error():
    with pytest.raises(KeyError) as exc:
        build_transmittal_manifest(requester(), docs(), ['missing'], 1, 10)
    assert exc.value.args == ('missing',)

