import re
from datetime import datetime
from math import ceil
from lxml import etree

def parse_calendar(xml_text: str, month: str, page: int=1, page_size: int=10) -> dict:
    if not re.fullmatch('\\d{4}-\\d{2}', month):
        raise ValueError('invalid month')
    try:
        month_date = datetime.strptime(month, '%Y-%m')
    except ValueError as exc:
        raise ValueError('invalid month') from exc
    if page < 1 or page_size < 1:
        raise ValueError('invalid pagination')
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode('utf-8'), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'calendar':
        raise ValueError('invalid root')
    records = []
    for node in root.findall('event'):
        event_id = (node.get('id') or '').strip()
        title_node = node.find('title')
        start_node = node.find('start')
        end_node = node.find('end')
        if title_node is None or start_node is None or end_node is None:
            raise ValueError('missing event data')
        title = (title_node.text or '').strip()
        start_text = (start_node.text or '').strip()
        end_text = (end_node.text or '').strip()
        if not event_id or not title:
            raise ValueError('missing event data')
        try:
            start = datetime.fromisoformat(start_text)
            end = datetime.fromisoformat(end_text)
        except ValueError as exc:
            raise ValueError('invalid date') from exc
        if end < start:
            raise ValueError('invalid event range')
        location_node = node.find('location')
        category_node = node.find('category')
        location = (location_node.text or '').strip() if location_node is not None else ''
        category = (category_node.text or '').strip() if category_node is not None else 'general'
        if start.year == month_date.year and start.month == month_date.month:
            records.append((start, title.casefold(), event_id, {'id': event_id, 'title': title, 'start': start_text, 'end': end_text, 'location': location, 'category': category}))
    records.sort(key=lambda item: item[:3])
    total = len(records)
    first = (page - 1) * page_size
    return {'month': month, 'total': total, 'pages': ceil(total / page_size) if total else 0, 'events': [item[3] for item in records[first:first + page_size]]}

