import json
import os

def create_route_manifest(loads: list[dict], truck_capacity: int, config: dict | None=None) -> dict:
    if not isinstance(truck_capacity, int) or isinstance(truck_capacity, bool) or truck_capacity <= 0:
        raise ValueError('truck capacity must be a positive integer')
    groups = {}
    for load in loads:
        if not isinstance(load, dict):
            raise ValueError('invalid load')
        required = ('load_id', 'destination', 'weight', 'priority', 'distance')
        if any((field not in load for field in required)):
            raise ValueError('invalid load')
        if not isinstance(load['load_id'], str) or not load['load_id']:
            raise ValueError('invalid load')
        if not isinstance(load['destination'], str) or not load['destination']:
            raise ValueError('invalid load')
        if not isinstance(load['weight'], int) or isinstance(load['weight'], bool) or load['weight'] <= 0 or (load['weight'] > truck_capacity):
            raise ValueError('invalid load')
        if not isinstance(load['priority'], int) or isinstance(load['priority'], bool):
            raise ValueError('invalid load')
        if not isinstance(load['distance'], (int, float)) or isinstance(load['distance'], bool) or load['distance'] < 0:
            raise ValueError('invalid load')
        groups.setdefault(load['destination'], []).append(load)
    routes = []
    route_id = 1
    for destination in sorted(groups):
        ordered = sorted(groups[destination], key=lambda x: (-x['priority'], x['distance'], x['load_id']))
        current = None
        for load in ordered:
            if current is None or current['total_weight'] + load['weight'] > truck_capacity:
                current = {'route_id': route_id, 'destination': destination, 'load_ids': [], 'total_weight': 0, 'total_distance': 0.0}
                routes.append(current)
                route_id += 1
            current['load_ids'].append(load['load_id'])
            current['total_weight'] += load['weight']
            current['total_distance'] += load['distance']
        for route in routes:
            if route['destination'] == destination:
                route['total_distance'] = round(route['total_distance'], 2)
    key = config.get('signing_key') if isinstance(config, dict) else None
    if not key:
        key = os.environ.get('ROUTE_SIGNING_KEY')
    if not key:
        raise ValueError('signing key is missing')
    payload = json.dumps(routes, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode('utf-8')
    signature = hmac.new(key.encode('utf-8'), payload, hashlib.sha256).hexdigest()
    return {'routes': routes, 'signature': signature}

