import csv
import io
import secrets
from datetime import datetime, date

def parse_permit_text(text: str) -> list[dict]:
    result = []
    try:
        rows = csv.reader(io.StringIO(text), delimiter='|', quotechar='"')
        for row in rows:
            if not row or all((not x.strip() for x in row)):
                continue
            if len(row) != 4:
                raise ValueError('invalid row')
            plate, zone, start, end = [x.strip() for x in row]
            if not plate or zone not in ('A', 'B', 'C'):
                raise ValueError('invalid permit')
            begin = datetime.fromisoformat(start)
            finish = datetime.fromisoformat(end)
            if finish <= begin:
                raise ValueError('invalid interval')
            result.append({'plate': plate, 'zone': zone, 'start': begin, 'end': finish})
    except (csv.Error, TypeError, ValueError) as exc:
        raise ValueError('invalid permit text') from exc
    return result

def issue_permits(text: str, issued_on: date) -> list[dict]:
    records = parse_permit_text(text)
    seen = set()
    permits = []
    rates = {'A': 3, 'B': 2, 'C': 1}
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ23456789'
    for record in records:
        key = record['plate'].casefold()
        if key in seen:
            raise ValueError('duplicate plate')
        seen.add(key)
        seconds = (record['end'] - record['start']).total_seconds()
        hours = int((seconds + 3599) // 3600)
        if hours > 8:
            raise ValueError('duration too long')
        code = ''.join((secrets.choice(alphabet) for _ in range(10)))
        permits.append({**record, 'hours': hours, 'fee': hours * rates[record['zone']], 'code': code, 'issued_on': issued_on})
    permits.sort(key=lambda p: (p['zone'], p['start'], p['plate'].casefold()))
    return permits

def summarize_permits(permits: list[dict]) -> dict:
    zones = {}
    for permit in permits:
        zone = permit['zone']
        if zone not in zones:
            zones[zone] = {'count': 0, 'hours': 0, 'revenue': 0}
        item = zones[zone]
        item['count'] += 1
        item['hours'] += permit['hours']
        item['revenue'] += permit['fee']
    zones = dict(sorted(zones.items()))
    total = {'count': 0, 'hours': 0, 'revenue': 0}
    for item in zones.values():
        for key in total:
            total[key] += item[key]
    return {'zones': zones, 'total': total}

