import hashlib
import hmac
import json
import os

def make_tracker(api_secret: str) -> dict:
    if not isinstance(api_secret, str) or not api_secret:
        raise ValueError('invalid secret')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', api_secret.encode(), salt, 100000)
    return {'credential': (salt, digest), 'events': set(), 'records': []}

def _check(t, secret):
    if not isinstance(secret, str):
        raise PermissionError('invalid secret')
    salt, expected = t['credential']
    actual = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
    if not hmac.compare_digest(actual, expected):
        raise PermissionError('invalid secret')

def _validate(e):
    if not isinstance(e, dict) or set(e) != {'id', 'player', 'level', 'score', 'timestamp', 'mode'}:
        raise ValueError('invalid event')
    if any((not isinstance(e[k], str) or not e[k] for k in ('id', 'player', 'mode'))):
        raise ValueError('invalid event')
    if any((isinstance(e[k], bool) or not isinstance(e[k], int) for k in ('level', 'score', 'timestamp'))):
        raise ValueError('invalid event')
    if e['level'] <= 0 or e['score'] < 0 or e['timestamp'] < 0:
        raise ValueError('invalid event')

def add_event(tracker: dict, api_secret: str, event: dict) -> None:
    _check(tracker, api_secret)
    _validate(event)
    if event['id'] in tracker['events']:
        raise ValueError('duplicate id')
    tracker['events'].add(event['id'])
    tracker['records'].append(dict(event))

def add_event_line(tracker: dict, api_secret: str, line: str) -> None:
    try:
        value = json.loads(line)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid json') from exc
    if not isinstance(value, dict):
        raise ValueError('invalid event')
    add_event(tracker, api_secret, value)

def leaderboard(tracker: dict, start: int=0, end: int | None=None) -> list[dict]:
    if isinstance(start, bool) or not isinstance(start, int) or start < 0:
        raise ValueError('invalid range')
    if end is not None and (isinstance(end, bool) or not isinstance(end, int) or end < start):
        raise ValueError('invalid range')
    groups = {}
    for e in tracker['records']:
        if e['timestamp'] < start or (end is not None and e['timestamp'] >= end):
            continue
        g = groups.setdefault(e['player'], {'player': e['player'], 'total_score': 0, 'games': 0, 'best_level': 0, 'modes': {}})
        g['total_score'] += e['score']
        g['games'] += 1
        g['best_level'] = max(g['best_level'], e['level'])
        g['modes'][e['mode']] = g['modes'].get(e['mode'], 0) + 1
    out = []
    for g in groups.values():
        g['modes'] = dict(sorted(g['modes'].items()))
        out.append(g)
    return sorted(out, key=lambda x: (-x['total_score'], -x['games'], x['player']))

