import hashlib
import os
import tempfile
from datetime import date
_FIELDS = ['candidate', 'department', 'status', 'effective_date', 'base_salary', 'bonus_salary', 'annual_total']

def _date(value):
    if not isinstance(value, str):
        raise ValueError('invalid date')
    try:
        return date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid date')

def prepare_offer_rows(offers: list[dict], as_of: str) -> list[dict]:
    limit = _date(as_of)
    if not isinstance(offers, list):
        raise ValueError('offers must be a list')
    chosen = {}
    for item in offers:
        if not isinstance(item, dict):
            raise ValueError('invalid offer')
        required = ('candidate', 'department', 'effective_date', 'status', 'base_salary', 'bonus_salary')
        if any((k not in item for k in required)):
            raise ValueError('missing field')
        if not isinstance(item['candidate'], str) or not item['candidate'] or (not isinstance(item['department'], str)) or (not item['department']):
            raise ValueError('invalid name')
        if item['status'] not in ('pending', 'accepted', 'declined'):
            raise ValueError('invalid status')
        when = _date(item['effective_date'])
        if not isinstance(item['base_salary'], int) or isinstance(item['base_salary'], bool) or item['base_salary'] < 0:
            raise ValueError('invalid salary')
        if not isinstance(item['bonus_salary'], int) or isinstance(item['bonus_salary'], bool) or item['bonus_salary'] < 0:
            raise ValueError('invalid salary')
        seq = item.get('sequence', 0)
        if not isinstance(seq, int) or isinstance(seq, bool) or seq < 0:
            raise ValueError('invalid sequence')
        if when <= limit:
            key = (when, seq)
            old = chosen.get(item['candidate'])
            if old is None or key > old[0]:
                chosen[item['candidate']] = (key, item)
    rows = []
    for _, item in chosen.values():
        if item['status'] == 'declined':
            continue
        rows.append({'candidate': item['candidate'], 'department': item['department'], 'status': item['status'], 'effective_date': item['effective_date'], 'base_salary': item['base_salary'], 'bonus_salary': item['bonus_salary'], 'annual_total': item['base_salary'] + item['bonus_salary']})
    rows.sort(key=lambda x: (x['department'].casefold(), -x['annual_total'], x['candidate'].casefold(), x['candidate']))
    return rows

def write_offer_report(offers: list[dict], destination: str, as_of: str) -> str:
    rows = prepare_offer_rows(offers, as_of)
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=directory)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as out:
            writer = csv.DictWriter(out, fieldnames=_FIELDS, lineterminator='\r\n')
            writer.writeheader()
            writer.writerows(rows)
        with open(temporary, 'rb') as src:
            digest = hashlib.sha256(src.read()).hexdigest()
        os.replace(temporary, destination)
        return digest
    except Exception:
        try:
            os.unlink(temporary)
        except OSError:
            pass
        raise

def read_offer_report(path: str) -> list[dict]:
    try:
        with open(path, encoding='utf-8', newline='') as f:
            reader = csv.DictReader(f)
            if reader.fieldnames != _FIELDS:
                raise ValueError('invalid header')
            result = []
            for row in reader:
                if None in row or any((row[k] == '' for k in _FIELDS)):
                    raise ValueError('invalid row')
                try:
                    base = int(row['base_salary'])
                    bonus = int(row['bonus_salary'])
                    total = int(row['annual_total'])
                except ValueError:
                    raise ValueError('invalid number')
                if total != base + bonus:
                    raise ValueError('invalid total')
                result.append({'candidate': row['candidate'], 'department': row['department'], 'status': row['status'], 'effective_date': row['effective_date'], 'base_salary': base, 'bonus_salary': bonus, 'annual_total': total})
            return result
    except csv.Error as e:
        raise ValueError('invalid csv') from e

