import hashlib
import hmac
import math
import os

def make_staff_pin_record(pin: str) -> str:
    if not isinstance(pin, str):
        raise ValueError('pin must be a string')
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return 'pbkdf2$' + salt.hex() + '$' + value.hex()

def check_staff_pin(record: str, pin: str) -> bool:
    if not isinstance(record, str) or not isinstance(pin, str):
        return False
    try:
        kind, salt_text, value_text = record.split('$', 2)
        if kind != 'pbkdf2':
            return False
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(value_text)
    except ValueError:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def trade_in_report(records: list[dict], stored_pin: str, pin: str, page: int=1, page_size: int=2) -> dict:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1) or (page_size > 100):
        raise ValueError('invalid pagination')
    if not check_staff_pin(stored_pin, pin):
        raise PermissionError('invalid PIN')
    groups = {}
    approved_count = 0
    for item in records:
        if not isinstance(item, dict):
            raise ValueError('invalid record')
        if not isinstance(item.get('id'), str) or not item['id'] or (not isinstance(item.get('model'), str)) or (not item['model']):
            raise ValueError('invalid record')
        if item.get('condition') not in {'excellent', 'good', 'fair'}:
            raise ValueError('invalid record')
        offer = item.get('offer')
        if isinstance(offer, bool) or not isinstance(offer, (int, float)) or (not math.isfinite(offer)) or (offer < 0) or (not isinstance(item.get('approved'), bool)):
            raise ValueError('invalid record')
        if item['approved']:
            approved_count += 1
            groups.setdefault(item['model'], []).append(float(offer))
    result = []
    for model, offers in groups.items():
        total = round(sum(offers), 2)
        result.append({'model': model, 'count': len(offers), 'total_offer': total, 'average_offer': round(total / len(offers), 2)})
    result.sort(key=lambda x: (-x['total_offer'], x['model']))
    start = (page - 1) * page_size
    return {'total_models': len(result), 'total_approved_records': approved_count, 'models': result[start:start + page_size]}

