    try:
        root = json.loads(payload)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid claims JSON') from exc
    if not isinstance(root, dict) or not isinstance(root.get('claims'), list):
        raise ValueError('claims must be a list')
    result = []
    for claim in root['claims']:
        if not isinstance(claim, dict):
            raise ValueError('invalid claim')
        fields = ('claim_id', 'policyholder', 'country', 'status')
        if any((not isinstance(claim.get(x), str) or not claim[x] for x in fields)):
            raise ValueError('invalid claim fields')
        if not isinstance(claim.get('expenses'), list):
            raise ValueError('invalid expenses')
        expenses = []
        for expense in claim['expenses']:
            if not isinstance(expense, dict) or not isinstance(expense.get('category'), str) or (not expense['category']):
                raise ValueError('invalid expense')
            try:
                amount = Decimal(str(expense['amount']))
                if not amount.is_finite() or amount < 0 or amount.as_tuple().exponent < -2:
                    raise ValueError
                cents = int((amount * 100).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
            except (KeyError, InvalidOperation, ValueError, TypeError):
