    entries.sort(key=lambda x: (-x['reimbursement_cents'], x['claim_id']))
    body = {'claims': entries, 'by_country': dict(sorted(countries.items())), 'grand_total_cents': sum(countries.values())}
    raw = json.dumps(body, sort_keys=True, separators=(',', ':')).encode()
    return body | {'signature': hmac.new(_key(config), raw, hashlib.sha256).hexdigest()}

def verify_report(report: dict, config: dict | None=None) -> bool:
    if not isinstance(report, dict) or not isinstance(report.get('signature'), str):
        return False
    body = {k: report.get(k) for k in ('claims', 'by_country', 'grand_total_cents')}
    raw = json.dumps(body, sort_keys=True, separators=(',', ':')).encode()
