import xml.etree.ElementTree as ET

def dispatch_manifest(xml: str, page: int=1, page_size: int=20) -> dict:
    if type(page) is not int or type(page_size) is not int or page <= 0 or (page_size <= 0):
        raise ValueError('invalid pagination')
    try:
        root = ET.fromstring(xml)
    except ET.ParseError as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'manifest':
        raise ValueError('invalid root')
    required = ('id', 'flight', 'service', 'priority', 'eta_minutes', 'duration_minutes')
    jobs = []
    for child in root:
        if child.tag != 'job':
            continue
        if list(child):
            raise ValueError('unexpected child')
        if any((name not in child.attrib for name in required)):
            raise ValueError('missing attribute')
        try:
            values = {name: int(child.attrib[name]) for name in required[3:]}
        except (TypeError, ValueError) as exc:
            raise ValueError('invalid integer') from exc
        if child.attrib.get('status', 'scheduled') != 'scheduled':
            continue
        job = {'id': child.attrib['id'], 'flight': child.attrib['flight'], 'service': child.attrib['service'], **values}
        jobs.append(job)
    jobs.sort(key=lambda x: (-x['priority'], x['eta_minutes'], x['id']))
    summary = {}
    for job in jobs:
        item = summary.setdefault(job['service'], {'count': 0, 'duration_minutes': 0})
        item['count'] += 1
        item['duration_minutes'] += job['duration_minutes']
    summary = {key: summary[key] for key in sorted(summary)}
    total = len(jobs)
    start = (page - 1) * page_size
    return {'jobs': jobs[start:start + page_size], 'total': total, 'page': page, 'page_size': page_size, 'pages': math.ceil(total / page_size), 'summary': summary}

