    for item in readings:
        if not isinstance(item, dict) or not isinstance(item.get('timestamp'), int) or isinstance(item.get('timestamp'), bool) or (not isinstance(item.get('heart_rate'), (int, float))) or isinstance(item.get('heart_rate'), bool) or (not isinstance(item.get('spo2'), (int, float))) or isinstance(item.get('spo2'), bool):
