from lxml import etree
from datetime import date
import re

def _day(value):
    try:
        date.fromisoformat(value)
    except Exception as exc:
        raise ValueError('invalid date') from exc
    return value

def _cents(value):
    if not re.fullmatch('\\d+(?:\\.\\d{1,2})?', value):
        raise ValueError('invalid amount')
    whole, _, frac = value.partition('.')
    return int(whole) * 100 + int((frac + '00')[:2])

def parse_grant_feed(xml_text: str) -> list[dict]:
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml_text.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'grants':
        raise ValueError('wrong root')
    result = []
    seen = set()
    for node in root:
        if node.tag != 'grant' or node.get('id') in seen:
            raise ValueError('invalid grant')
        seen.add(node.get('id'))
        required = ['id', 'institution', 'start', 'end', 'amount']
        if any((node.get(k) is None for k in required)):
            raise ValueError('missing attribute')
        start, end = (_day(node.get('start')), _day(node.get('end')))
        if end < start:
            raise ValueError('date order')
        amount = _cents(node.get('amount'))
        titles = [x for x in node if x.tag == 'title']
        if len(titles) != 1:
            raise ValueError('title')
        tags = []
        payments = []
        for child in node:
            if child.tag == 'title':
                continue
            if child.tag == 'tags':
                for tag in child:
                    if tag.tag != 'tag':
                        raise ValueError('tag')
                    text = ' '.join(''.join(tag.itertext()).split())
                    if text:
                        tags.append(text)
            elif child.tag == 'payments':
                for payment in child:
                    if payment.tag != 'payment' or payment.get('date') is None or payment.get('amount') is None:
                        raise ValueError('payment')
                    payments.append({'date': _day(payment.get('date')), 'amount_cents': _cents(payment.get('amount'))})
            else:
