_STATUSES = ('STORED', 'IN_TRANSIT', 'RELEASED', 'DESTROYED')
_SORTS = {'evidence_id': 'evidence_id', 'case_number': 'case_number', 'description': 'description', 'status': 'status', 'current_holder': 'current_holder'}

def initialize(conn: sqlite3.Connection) -> None:
    conn.executescript('CREATE TABLE IF NOT EXISTS evidence (evidence_id TEXT PRIMARY KEY, case_number TEXT NOT NULL, description TEXT NOT NULL, status TEXT NOT NULL, current_holder TEXT); CREATE TABLE IF NOT EXISTS custody (sequence INTEGER PRIMARY KEY AUTOINCREMENT, evidence_id TEXT NOT NULL REFERENCES evidence(evidence_id), event_type TEXT NOT NULL, officer TEXT NOT NULL, timestamp TEXT NOT NULL, note TEXT NOT NULL);')
    conn.commit()

def add_evidence(conn: sqlite3.Connection, evidence_id: str, case_number: str, description: str, status: str='STORED') -> None:
    if not evidence_id or not case_number or (not description) or (status not in _STATUSES):
        raise ValueError('invalid evidence')
    try:
        with conn:
            conn.execute('INSERT INTO evidence VALUES (?, ?, ?, ?, NULL)', (evidence_id, case_number, description, status))
            conn.execute('INSERT INTO custody(evidence_id,event_type,officer,timestamp,note) VALUES (?,?,?,?,?)', (evidence_id, 'ADD', 'SYSTEM', '', 'Initial intake'))
    except sqlite3.IntegrityError as exc:
        raise ValueError('duplicate evidence') from exc

def transfer_evidence(conn: sqlite3.Connection, evidence_id: str, officer: str, timestamp: str, note: str='') -> None:
    if not officer or not timestamp:
        raise ValueError('invalid transfer')
    with conn:
        cur = conn.execute("UPDATE evidence SET status='IN_TRANSIT', current_holder=? WHERE evidence_id=?", (officer, evidence_id))
        if cur.rowcount != 1:
            raise ValueError('unknown evidence')
        conn.execute('INSERT INTO custody(evidence_id,event_type,officer,timestamp,note) VALUES (?,?,?,?,?)', (evidence_id, 'TRANSFER', officer, timestamp, note))

def find_evidence(conn: sqlite3.Connection, search: str='', status: str | None=None, sort_by: str='evidence_id') -> list[dict]:
    if status is not None and status not in _STATUSES:
        raise ValueError('invalid status')
    if sort_by not in _SORTS:
        raise ValueError('invalid sort')
    pattern = f'%{search.lower()}%'
    sql = 'SELECT evidence_id,case_number,description,status,current_holder FROM evidence WHERE (lower(evidence_id) LIKE ? OR lower(case_number) LIKE ? OR lower(description) LIKE ?)'
    args = [pattern, pattern, pattern]
    if status is not None:
        sql += ' AND status=?'
        args.append(status)
    sql += ' ORDER BY ' + _SORTS[sort_by] + ', evidence_id'
    return [dict(zip(('evidence_id', 'case_number', 'description', 'status', 'current_holder'), row)) for row in conn.execute(sql, args)]

