    if conn.execute('SELECT 1 FROM evidence WHERE evidence_id=?', (evidence_id,)).fetchone() is None:
        raise ValueError('unknown evidence')
    rows = conn.execute('SELECT sequence,event_type,officer,timestamp,note FROM custody WHERE evidence_id=? ORDER BY sequence', (evidence_id,))
