import hashlib
import hmac
import json
import math
import os

def build_compliance_report(records: list[dict], config: dict | None=None) -> dict:
    key = config['COMPLIANCE_SIGNING_KEY'] if config is not None and 'COMPLIANCE_SIGNING_KEY' in config else os.environ.get('COMPLIANCE_SIGNING_KEY')
    if not isinstance(key, str) or not key:
        raise RuntimeError('COMPLIANCE_SIGNING_KEY is required')
    groups = {}
    for record in records:
        if not isinstance(record, dict) or any((field not in record for field in ('name', 'site', 'quantity', 'unit', 'hazardous'))):
            raise ValueError('invalid record')
        name, site, quantity, unit, hazardous = (record[x] for x in ('name', 'site', 'quantity', 'unit', 'hazardous'))
        if not isinstance(name, str) or not name or (not isinstance(site, str)) or (not site) or isinstance(quantity, bool) or (not isinstance(quantity, (int, float))) or (not math.isfinite(quantity)) or (quantity < 0) or (unit not in ('kg', 'g')) or (not isinstance(hazardous, bool)):
            raise ValueError('invalid record')
        amount = float(quantity) if unit == 'kg' else float(quantity) / 1000
        slot = groups.setdefault((site, name), [0.0, hazardous])
        if slot[1] != hazardous:
            raise ValueError('conflicting hazardous values')
        slot[0] += amount
    data = {}
    for (site, name), (amount, hazardous) in groups.items():
        row = data.setdefault(site, [0.0, 0.0, []])
        row[0] += amount
        if hazardous:
            row[1] += amount
            if amount >= 50:
                row[2].append(name)
    sites = [{'site': site, 'total_kg': round(row[0], 3), 'hazardous_kg': round(row[1], 3), 'flagged': sorted(row[2])} for site, row in sorted(data.items())]
    payload = json.dumps(sites, sort_keys=True, separators=(',', ':')).encode()
    return {'sites': sites, 'signature': hmac.new(key.encode(), payload, hashlib.sha256).hexdigest()}

