import csv
import os

def write_enrollment_report(base_dir: str, relative_name: str, records: list[dict], site_filter: str | None=None, page: int=1, page_size: int=10) -> str:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1 or (page_size > 100):
        raise ValueError('invalid page size')
    groups = {}
    for record in records:
        if not isinstance(record, dict) or set(record) != {'participant_id', 'site', 'status', 'age'}:
            raise ValueError('invalid record')
        participant_id = record['participant_id']
        site = record['site']
        status = record['status']
        age = record['age']
        if not isinstance(participant_id, str) or not participant_id or (not isinstance(site, str)) or (not site):
            raise ValueError('invalid record')
        if status not in {'enrolled', 'screened', 'withdrawn'}:
            raise ValueError('invalid record')
        if isinstance(age, bool) or not isinstance(age, int) or age < 18 or (age > 100):
            raise ValueError('invalid record')
        if site_filter is not None and site != site_filter:
            continue
        groups.setdefault(site, []).append((status, age))
    rows = []
    for site in sorted(groups):
        values = groups[site]
        counts = {name: sum((status == name for status, age in values)) for name in ('enrolled', 'screened', 'withdrawn')}
        enrolled_ages = [age for status, age in values if status == 'enrolled']
        average = round(sum(enrolled_ages) / len(enrolled_ages), 2) if enrolled_ages else 0.0
        rows.append([site, len(values), counts['enrolled'], counts['screened'], counts['withdrawn'], f'{average:.2f}'])
    start = (page - 1) * page_size
    base = os.path.realpath(base_dir)
    target = os.path.realpath(os.path.join(base, relative_name))
    if os.path.commonpath([base, target]) != base:
        raise ValueError('path outside base directory')
    os.makedirs(os.path.dirname(target), exist_ok=True)
    with open(target, 'w', newline='', encoding='utf-8') as handle:
        writer = csv.writer(handle, lineterminator='\n')
        writer.writerow(['site', 'total', 'enrolled', 'screened', 'withdrawn', 'average_enrolled_age'])
        writer.writerows(rows[start:start + page_size])
    return target

