def fetch_reports(conn: sqlite3.Connection, status: str | None=None, search: str='', sort_by: str='created_at', descending: bool=False, limit: int=50) -> list[dict]:
    allowed = {'created_at', 'severity', 'player', 'id'}
    if sort_by not in allowed or not isinstance(limit, int) or isinstance(limit, bool) or (not 1 <= limit <= 100):
        raise ValueError('invalid query options')
    clauses = []
    values = []
    if status is not None:
        clauses.append('status = ?')
        values.append(status)
    if search:
        clauses.append('(lower(player) LIKE lower(?) OR lower(reason) LIKE lower(?))')
        term = '%' + search + '%'
        values.extend([term, term])
    where = ' WHERE ' + ' AND '.join(clauses) if clauses else ''
    direction = ' DESC' if descending else ' ASC'
    column = 'player COLLATE NOCASE' if sort_by == 'player' else sort_by
    query = 'SELECT id, player, reason, status, created_at, severity FROM reports' + where + ' ORDER BY ' + column + direction + ', id ASC LIMIT ?'
    values.append(limit)
    rows = conn.execute(query, values).fetchall()
    keys = ['id', 'player', 'reason', 'status', 'created_at', 'severity']
    return [dict(zip(keys, row)) for row in rows]

