        raise ValueError('invalid resolution data')
    ids = []
    for report_id in report_ids:
        if not isinstance(report_id, int) or isinstance(report_id, bool) or report_id <= 0:
            raise ValueError('invalid report id')
        if report_id not in ids:
            ids.append(report_id)
    if not ids:
        return 0
    placeholders = ','.join(('?' for _ in ids))
    with conn:
        cursor = conn.execute('UPDATE reports SET status = ?, resolved_by = ?, resolution_note = ? WHERE status = ? AND id IN (' + placeholders + ')', ['resolved', moderator, note, 'pending', *ids])
    return cursor.rowcount

def moderation_summary(conn: sqlite3.Connection) -> dict[str, dict[str, int | None]]:
    rows = conn.execute('SELECT status, COUNT(*), MAX(severity) FROM reports GROUP BY status ORDER BY status ASC').fetchall()
    return {status: {'count': count, 'max_severity': maximum} for status, count, maximum in rows}

