from lxml import etree

def get_directory(xml: str, department: str | None=None, page: int=1, page_size: int=10) -> dict:
    if page < 1 or page_size < 1:
        raise ValueError('invalid pagination')
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml.encode('utf-8'), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'directory':
        raise ValueError('invalid root')
    records = []
    seen = set()
    for node in root.findall('employee'):
        employee_id = node.get('id')
        employee_department = node.get('department')
        values = {}
        for key in ('name', 'title', 'location'):
            child = node.find(key)
            if child is None or child.text is None:
                raise ValueError('missing employee field')
            values[key] = child.text.strip()
        if employee_id is None or employee_department is None:
            raise ValueError('missing employee attribute')
        employee_id = employee_id.strip()
        employee_department = employee_department.strip()
        if employee_id in seen:
            raise ValueError('duplicate employee id')
        seen.add(employee_id)
        if department is None or employee_department == department:
            records.append({'id': employee_id, 'department': employee_department, **values})
    records.sort(key=lambda item: (item['name'].casefold(), item['name'], item['id']))
    start = (page - 1) * page_size
    return {'total': len(records), 'employees': records[start:start + page_size]}

