import ast

def evaluate_rule(expression: str, variables: dict[str, int | float | bool]) -> int | float | bool:
    try:
        tree = ast.parse(expression, mode='eval').body
    except SyntaxError as exc:
        raise ValueError('invalid expression') from exc

    def visit(node):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in variables:
                raise NameError(node.id)
            return variables[node.id]
        if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
            a, b = (visit(node.left), visit(node.right))
            return {ast.Add: lambda: a + b, ast.Sub: lambda: a - b, ast.Mult: lambda: a * b, ast.Div: lambda: a / b}[type(node.op)]()
        if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub, ast.Not):
            value = visit(node.operand)
            return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
        if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
            value = visit(node.values[0])
            for child in node.values[1:]:
                if isinstance(node.op, ast.And) and (not value):
                    return value
                if isinstance(node.op, ast.Or) and value:
                    return value
                value = visit(child)
            return value
        if isinstance(node, ast.Compare):
            left = visit(node.left)
            for op, child in zip(node.ops, node.comparators):
                right = visit(child)
                if not {ast.Eq: lambda: left == right, ast.NotEq: lambda: left != right, ast.Lt: lambda: left < right, ast.LtE: lambda: left <= right, ast.Gt: lambda: left > right, ast.GtE: lambda: left >= right}[type(op)]():
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
            return {'min': min, 'max': max, 'round': round}[node.func.id](*(visit(x) for x in node.args))
        raise ValueError('invalid expression')
    return visit(tree)

def schedule_deliveries(offers: list[dict], requests: list[dict], rule: str) -> list[dict]:
    for offer in offers:
        if offer['quantity'] < 0:
            raise ValueError('negative quantity')
    for request in requests:
        if request['need'] < 0:
            raise ValueError('negative need')
    remaining = {offer['id']: offer['quantity'] for offer in offers}
    result = []
    ordered = sorted(requests, key=lambda r: (-r['priority'], r['distance'], r['id']))
    for request in ordered:
        need = request['need']
        matching = sorted((o for o in offers if o['item'] == request['item']), key=lambda o: (o['expires'], o['id']))
        for offer in matching:
            available = remaining[offer['id']]
            values = {'need': need, 'available': available, 'priority': request['priority'], 'distance': request['distance'], 'shelf_days': offer['expires']}
            if need and available and evaluate_rule(rule, values):
                amount = min(need, available)
                result.append({'request_id': request['id'], 'offer_id': offer['id'], 'item': request['item'], 'quantity': amount})
                need -= amount
                remaining[offer['id']] -= amount
            if not need:
                break
    return result

def summarize_schedule(records: list[dict]) -> dict:
    result = {}
    for record in records:
        if record['quantity'] < 0:
            raise ValueError('negative quantity')
        rid, oid = (record['request_id'], record['offer_id'])
        if rid not in result:
            result[rid] = {'quantity': 0, 'offers': []}
        result[rid]['quantity'] += record['quantity']
        if oid not in result[rid]['offers']:
            result[rid]['offers'].append(oid)
    return result

