    columns = {'severity': 'severity', 'room': 'room', 'category': 'category', 'status': 'status', 'id': 'id'}
    if sort_by not in columns:
        raise ValueError('invalid sort key')
    direction = 'DESC' if descending else 'ASC'
    rank = "CASE severity WHEN 'critical' THEN 0 WHEN 'high' THEN 1 WHEN 'medium' THEN 2 WHEN 'low' THEN 3 WHEN 'informational' THEN 4 ELSE 5 END"
    primary = rank if sort_by == 'severity' else columns[sort_by]
    pattern = '%' + search + '%'
    rows = conn.execute(f'SELECT id, category, severity, description, room, status FROM findings WHERE report_id = ? AND (lower(category) LIKE lower(?) OR lower(description) LIKE lower(?) OR lower(room) LIKE lower(?) OR lower(status) LIKE lower(?)) ORDER BY {primary} {direction}, id ASC', (report_id, pattern, pattern, pattern, pattern)).fetchall()
    return [dict(zip(('id', 'category', 'severity', 'description', 'room', 'status'), row)) for row in rows]

def update_finding_status(conn: sqlite3.Connection, finding_id: int, status: str) -> dict:
    if status not in {'open', 'in_progress', 'resolved', 'deferred'}:
        raise ValueError('invalid status')
    cur = conn.execute('UPDATE findings SET status = ? WHERE id = ?', (status, finding_id))
    if cur.rowcount == 0:
        raise KeyError(finding_id)
    conn.commit()
    row = conn.execute('SELECT id, report_id, category, severity, description, room, status FROM findings WHERE id = ?', (finding_id,)).fetchone()
    return dict(zip(('id', 'report_id', 'category', 'severity', 'description', 'room', 'status'), row))

