    rows = conn.execute('SELECT severity, status FROM findings WHERE report_id = ?', (report_id,)).fetchall()
    names = ['critical', 'high', 'medium', 'low', 'informational']
    weights = dict(zip(names, (4, 3, 2, 1, 0)))
    counts = {name: 0 for name in names}
    open_count = resolved_count = risk = 0
    for severity, status in rows:
        if severity in counts:
            counts[severity] += 1
            risk += weights[severity]
        if status in {'open', 'in_progress', 'deferred'}:
            open_count += 1
        elif status == 'resolved':
            resolved_count += 1
    return {'report_id': report_id, 'total': len(rows), 'open_count': open_count, 'resolved_count': resolved_count, 'by_severity': counts, 'risk_score': risk}

