import hashlib
import hmac
import os

def make_operator(name: str, password: str, role: str) -> dict:
    if not isinstance(name, str) or not name or (not isinstance(password, str)) or (not password):
        raise ValueError()
    if role not in ('controller', 'observer'):
        raise ValueError()
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000).hex()
    return {'name': name, 'role': role, 'salt': salt.hex(), 'digest': digest}

def authenticate(record: dict, password: str) -> bool:
    try:
        salt = bytes.fromhex(record['salt'])
        expected = record['digest']
        if not isinstance(password, str) or not isinstance(expected, str):
            return False
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000).hex()
        return hmac.compare_digest(actual, expected)
    except (TypeError, ValueError, KeyError):
        return False

def schedule_launches(record: dict, password: str, requests: list[dict], pad_count: int) -> list[dict]:
    if not authenticate(record, password) or record.get('role') != 'controller':
        raise PermissionError()
    if not isinstance(pad_count, int) or isinstance(pad_count, bool) or pad_count <= 0:
        raise ValueError()
    seen = set()
    clean = []
    for item in requests:
        if not isinstance(item, dict) or set(item) != {'id', 'earliest', 'latest', 'duration', 'priority'}:
            raise ValueError()
        ident = item['id']
        if not isinstance(ident, str) or not ident or ident in seen:
            raise ValueError()
        vals = [item[x] for x in ('earliest', 'latest', 'duration', 'priority')]
        if any((not isinstance(x, int) or isinstance(x, bool) for x in vals)):
            raise ValueError()
        if item['earliest'] < 0 or item['latest'] <= item['earliest'] or item['duration'] <= 0:
            raise ValueError()
        seen.add(ident)
        clean.append(item)
    clean.sort(key=lambda x: (-x['priority'], x['latest'], x['id']))
    occupied = [[] for _ in range(pad_count)]
    result = []
    for item in clean:
        choices = []
        for pad in range(pad_count):
            start = item['earliest']
            for a, b in sorted(occupied[pad]):
                if start + item['duration'] <= a:
                    break
                if start < b:
                    start = b
            if start + item['duration'] <= item['latest']:
                choices.append((start, pad))
        if choices:
            start, pad = min(choices)
            end = start + item['duration']
            occupied[pad].append((start, end))
            result.append({'id': item['id'], 'pad': pad, 'start': start, 'end': end})
    return sorted(result, key=lambda x: (x['start'], x['pad'], x['id']))

