from solution import create_registration_code

import hashlib
import hmac
import json
import os
from unittest.mock import patch


def expected_code(registration, key):
    payload = json.dumps(registration, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
    digest = hmac.new(key.encode("utf-8"), payload, hashlib.sha256).hexdigest()[:12]
    return f"CONF-{registration['attendee_id']}-{digest}"


def test_generates_code_from_environment_key():
    registration = {"attendee_id": "A104", "email": "lee@example.org", "conference": "ACL2025"}
    with patch.dict(os.environ, {"CONFERENCE_SIGNING_KEY": "env-key-123"}, clear=False):
        result = create_registration_code(registration)
    assert result == expected_code(registration, "env-key-123")


def test_uses_key_from_config():
    registration = {"attendee_id": "B7", "email": "maria@example.org", "conference": "NeurIPS"}
    result = create_registration_code(registration, {"CONFERENCE_SIGNING_KEY": "config-key"})
    assert result == expected_code(registration, "config-key")


def test_config_key_takes_precedence_over_environment():
    registration = {"attendee_id": "C88", "email": "sam@example.org", "conference": "ICML"}
    with patch.dict(os.environ, {"CONFERENCE_SIGNING_KEY": "environment-key"}, clear=False):
        result = create_registration_code(registration, {"CONFERENCE_SIGNING_KEY": "preferred-key"})
    assert result == expected_code(registration, "preferred-key")


def test_does_not_modify_registration():
    registration = {"conference": "CHI", "email": "n@example.org", "attendee_id": "Z9"}
    original = registration.copy()
    with patch.dict(os.environ, {"CONFERENCE_SIGNING_KEY": "stable"}, clear=False):
        create_registration_code(registration)
    assert registration == original


def test_supports_unicode_registration_values():
    registration = {"attendee_id": "参加-1", "email": "ana@example.org", "conference": "安全会議"}
