import ast
import operator

def select_shipments(shipments: list[dict], expression: str) -> list[str]:
    tree = ast.parse(expression, mode='eval').body
    functions = {'min': min, 'max': max, 'round': round}
    binary = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
    comparisons = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}

    def evaluate(node, values):
        if isinstance(node, ast.Constant):
            return node.value
        if isinstance(node, ast.Name):
            if node.id in values:
                return values[node.id]
            if node.id in functions:
                return functions[node.id]
            raise NameError(node.id)
        if isinstance(node, ast.BinOp):
            return binary[type(node.op)](evaluate(node.left, values), evaluate(node.right, values))
        if isinstance(node, ast.UnaryOp):
            value = evaluate(node.operand, values)
            return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
        if isinstance(node, ast.BoolOp):
            result = evaluate(node.values[0], values)
            for item in node.values[1:]:
                if isinstance(node.op, ast.And) and (not result):
                    return result
                if isinstance(node.op, ast.Or) and result:
                    return result
                result = evaluate(item, values)
            return result
        if isinstance(node, ast.Compare):
            left = evaluate(node.left, values)
            for op, right_node in zip(node.ops, node.comparators):
                right = evaluate(right_node, values)
                if not comparisons[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (not node.keywords) and (node.func.id in functions):
            return functions[node.func.id](*(evaluate(arg, values) for arg in node.args))
        raise ValueError('unsupported expression')
    selected = [row for row in shipments if evaluate(tree, row)]
    return [row['id'] for row in sorted(selected, key=lambda row: (-row['urgency'], row['distance_km']))]

