            if course in courses:
                raise ValueError('duplicate course')
            courses.append(course)
            credits += value
            index += 1
        students.append({'student_id': student, 'courses': courses, 'credits': credits})
        total_courses += len(courses)
        total_credits += credits
    return {'term': term, 'students': students, 'totals': {'students': len(students), 'courses': total_courses, 'credits': total_credits}}

