import csv
import os
import tempfile

def export_ticket_report(tickets: list[dict], destination: str, statuses: list[str] | None=None, page: int=1, page_size: int=50) -> list[dict]:
    if page < 1 or page_size < 1:
        raise ValueError('invalid pagination')
    allowed = None if statuses is None else set(statuses)
    groups = {}
    for ticket in tickets:
        required = ('id', 'customer', 'category', 'status', 'minutes')
        if any((key not in ticket for key in required)):
            raise ValueError('malformed ticket')
        if any((not isinstance(ticket[key], str) or not ticket[key] for key in ('id', 'customer', 'category', 'status'))):
            raise ValueError('malformed ticket')
        if isinstance(ticket['minutes'], bool) or not isinstance(ticket['minutes'], int) or ticket['minutes'] < 0:
            raise ValueError('malformed ticket')
        if allowed is not None and ticket['status'] not in allowed:
            continue
        key = (ticket['customer'], ticket['category'])
        if key not in groups:
            groups[key] = {'customer': key[0], 'category': key[1], 'tickets': 0, 'total_minutes': 0, 'open_tickets': 0}
        row = groups[key]
        row['tickets'] += 1
        row['total_minutes'] += ticket['minutes']
        if ticket['status'] != 'closed':
            row['open_tickets'] += 1
    rows = sorted(groups.values(), key=lambda row: (-row['total_minutes'], row['customer'], row['category']))
    start = (page - 1) * page_size
    selected = rows[start:start + page_size]
    directory = os.path.dirname(os.path.abspath(destination))
    descriptor, temporary = tempfile.mkstemp(dir=directory, prefix='.ticket-report-')
    try:
        with os.fdopen(descriptor, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.DictWriter(handle, fieldnames=['customer', 'category', 'tickets', 'total_minutes', 'open_tickets'])
            writer.writeheader()
            writer.writerows(selected)
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return selected

