import hashlib
import hmac
import json
import pytest


def make_signature(payload, secret):
    return hmac.new(secret.encode(), payload.encode(), hashlib.sha256).hexdigest()


def test_accepts_valid_charge_event():
    payload = json.dumps({
        "transaction_id": "txn-1001",
        "amount_cents": 2599,
        "currency": "USD",
        "event_type": "charge"
    })
    signature = make_signature(payload, "ledger-key")
    assert verify_reconciliation_event(payload, signature, "ledger-key") == json.loads(payload)


def test_accepts_valid_refund_event_and_preserves_extra_fields():
    value = {
        "transaction_id": "txn-1002",
        "amount_cents": 700,
        "currency": "EUR",
        "event_type": "refund",
        "invoice_id": "inv-44"
    }
    payload = json.dumps(value, separators=(",", ":"))
    assert verify_reconciliation_event(payload, make_signature(payload, "key"), "key") == value


def test_rejects_wrong_signature():
    payload = json.dumps({
        "transaction_id": "txn-1",
        "amount_cents": 1,
        "currency": "USD",
        "event_type": "charge"
    })
    signature = make_signature(payload, "right-key")
    with pytest.raises(ValueError):
        verify_reconciliation_event(payload, signature, "wrong-key")


def test_rejects_malformed_signature_text():
    payload = json.dumps({
        "transaction_id": "txn-2",
        "amount_cents": 10,
        "currency": "USD",
        "event_type": "charge"
    })
    with pytest.raises(ValueError):
        verify_reconciliation_event(payload, "not-a-hex-signature", "key")


def test_rejects_invalid_json():
    payload = '{"transaction_id": "txn-3"'
    with pytest.raises(ValueError):
        verify_reconciliation_event(payload, make_signature(payload, "key"), "key")


def test_rejects_missing_and_invalid_fields():
    values = [
        {"amount_cents": 1, "currency": "USD", "event_type": "charge"},
        {"transaction_id": "x", "amount_cents": -1, "currency": "USD", "event_type": "charge"},
        {"transaction_id": "x", "amount_cents": True, "currency": "USD", "event_type": "charge"},
        {"transaction_id": "x", "amount_cents": 1, "currency": "usd", "event_type": "charge"},
        {"transaction_id": "x", "amount_cents": 1, "currency": "USD", "event_type": "capture"}
    ]
    for value in values:
        payload = json.dumps(value)
        with pytest.raises(ValueError):
            verify_reconciliation_event(payload, make_signature(payload, "key"), "key")


def test_rejects_non_object_json_values():
    for value in ["[]", "null", "42", '"text"']:
        with pytest.raises(ValueError):
            verify_reconciliation_event(value, make_signature(value, "key"), "key")


