import hashlib
import hmac
import json

def verify_reconciliation_event(payload: str, signature: str, secret: str) -> dict:
    if not isinstance(payload, str) or not isinstance(signature, str) or (not isinstance(secret, str)):
        raise ValueError('invalid input')
    if len(signature) != 64:
        raise ValueError('invalid signature')
    try:
        expected = hmac.new(secret.encode(), payload.encode(), hashlib.sha256).hexdigest()
        valid = hmac.compare_digest(expected, signature)
    except (TypeError, ValueError, UnicodeError):
        raise ValueError('invalid signature')
    if not valid:
        raise ValueError('invalid signature')
    try:
        value = json.loads(payload)
    except (TypeError, ValueError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    if not isinstance(value, dict):
        raise ValueError('invalid payload')
    required = ('transaction_id', 'amount_cents', 'currency', 'event_type')
    if any((field not in value for field in required)):
        raise ValueError('invalid fields')
    if not isinstance(value['transaction_id'], str) or not value['transaction_id']:
        raise ValueError('invalid fields')
    if isinstance(value['amount_cents'], bool) or not isinstance(value['amount_cents'], int) or value['amount_cents'] < 0:
        raise ValueError('invalid fields')
    if not isinstance(value['currency'], str) or len(value['currency']) != 3 or (not value['currency'].isupper()) or (not value['currency'].isalpha()):
        raise ValueError('invalid fields')
    if value['event_type'] not in ('charge', 'refund'):
        raise ValueError('invalid fields')
    return value

