from lxml import etree
from datetime import date
from decimal import Decimal, InvalidOperation
import re

def _date(value):
    try:
        date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def _amount(value):
    if not isinstance(value, str) or not re.fullmatch('(?:0|[1-9]\\d*)(?:\\.\\d{1,2})?', value):
        raise ValueError('invalid amount')
    try:
        return int(Decimal(value) * 100)
    except InvalidOperation:
        raise ValueError('invalid amount')

def parse_escrow_xml(xml_text: str) -> list[dict]:
    try:
        root = etree.fromstring(xml_text.encode(), etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False))
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'escrow':
        raise ValueError('invalid root')
    result = []
    for loan in root:
        if loan.tag != 'loan' or not loan.get('id'):
            continue
        seen = set()
        for node in loan:
            if node.tag != 'disbursement':
                continue
            required = ['id', 'date', 'category', 'vendor', 'amount', 'status']
            if any((not node.get(k) for k in required)):
                raise ValueError('missing attribute')
            ident = node.get('id')
            if ident in seen:
                raise ValueError('duplicate id')
            seen.add(ident)
            _date(node.get('date'))
            if node.get('status') not in {'approved', 'pending', 'void'}:
                raise ValueError('invalid status')
            result.append({'loan_id': loan.get('id'), 'disbursement_id': ident, 'date': node.get('date'), 'category': node.get('category'), 'vendor': node.get('vendor'), 'status': node.get('status'), 'amount_cents': _amount(node.get('amount'))})
    return result

def build_escrow_report(records: list[dict], start_date: str, end_date: str) -> dict:
    _date(start_date)
    _date(end_date)
    if start_date > end_date:
        raise ValueError('invalid range')
    groups = [{}, {}, {}]
    total = pending = count = 0
    for r in records:
        for k in ('loan_id', 'category', 'vendor'):
            if not isinstance(r.get(k), str) or not r[k]:
                raise ValueError('invalid grouping field')
        _date(r.get('date'))
        if r.get('status') not in {'approved', 'pending', 'void'} or not isinstance(r.get('amount_cents'), int) or r['amount_cents'] < 0:
            raise ValueError('invalid record')
        if not start_date <= r['date'] <= end_date:
            continue
        if r['status'] == 'pending':
            pending += r['amount_cents']
        if r['status'] != 'approved':
            continue
        total += r['amount_cents']
        count += 1
        for i, key in enumerate(('loan_id', 'category', 'vendor')):
            item = groups[i].setdefault(r[key], [0, 0])
            item[0] += r['amount_cents']
            item[1] += 1
    lists = []
    for group in groups:
        lists.append([{'name': n, 'cents': v[0], 'count': v[1]} for n, v in sorted(group.items(), key=lambda x: (-x[1][0], x[0]))])
    return {'total_cents': total, 'approved_count': count, 'pending_cents': pending, 'by_loan': lists[0], 'by_category': lists[1], 'by_vendor': lists[2]}

