import csv
import io
import datetime

def parse_demand_csv(text: str) -> list[dict]:
    if not isinstance(text, str):
        raise ValueError('text')
    reader = csv.reader(io.StringIO(text, newline=''))
    try:
        header = next(reader)
    except StopIteration:
        raise ValueError('header')
    if header != ['date', 'sku', 'units']:
        raise ValueError('header')
    result = []
    seen = set()
    for row in reader:
        if not row or all((x == '' for x in row)):
            continue
        if len(row) != 3:
            raise ValueError('row')
        try:
            day = datetime.date.fromisoformat(row[0])
        except Exception as exc:
            raise ValueError('date') from exc
        if not row[1]:
            raise ValueError('sku')
        try:
            units = int(row[2])
        except Exception as exc:
            raise ValueError('units') from exc
        if str(units) != row[2] or units < 0:
            raise ValueError('units')
        key = (day, row[1])
        if key in seen:
            raise ValueError('duplicate')
        seen.add(key)
        result.append({'date': day, 'sku': row[1], 'units': units})
    return sorted(result, key=lambda x: (x['date'], x['sku']))

def generate_forecast(requester: dict, resource: dict, horizon: int) -> dict:
    if isinstance(horizon, bool) or not isinstance(horizon, int) or (not 0 <= horizon <= 90):
        raise ValueError('horizon')
    if not isinstance(resource, dict) or not isinstance(requester, dict):
        raise ValueError('input')
    if not isinstance(resource.get('csv'), str):
        raise ValueError('resource')
    if requester.get('user_id') != resource.get('owner_id') and (not ('forecast_admin' in requester.get('roles', []) and requester.get('tenant_id') == resource.get('tenant_id'))):
        raise PermissionError('not authorized')
    rows = parse_demand_csv(resource['csv'])
    groups = {}
    for row in rows:
        groups.setdefault(row['sku'], []).append(row)
    output = []
    for sku in sorted(groups):
        values = groups[sku][-3:]
        denominator = sum(range(1, len(values) + 1))
        numerator = sum(((i + 1) * row['units'] for i, row in enumerate(values)))
        base = (numerator * 2 + denominator) // (2 * denominator)
        day = groups[sku][-1]['date']
        for offset in range(1, horizon + 1):
            output.append({'sku': sku, 'date': (day + datetime.timedelta(days=offset)).isoformat(), 'units': base})
    return {'resource_id': resource['resource_id'], 'horizon': horizon, 'forecasts': output}

