import os

def save_onboarding_document(base_dir: str, employee_id: str, filename: str, content: str) -> str:
    if not all((isinstance(value, str) for value in (base_dir, employee_id, filename, content))):
        raise TypeError()
    if not employee_id or not filename:
        raise ValueError()
    base = os.path.realpath(base_dir)
    employee = os.path.join(base, employee_id)
    target = os.path.realpath(os.path.join(employee, filename))
    try:
        common = os.path.commonpath((base, target))
    except ValueError:
        raise ValueError()
    if common != base:
        raise ValueError()
    os.makedirs(os.path.dirname(target), exist_ok=True)
    with open(target, 'w', encoding='utf-8') as handle:
        handle.write(content)
    return target

