import hmac
import json

def assess_rollout_webhook(payload: str, signature: str, secret: str) -> dict:
    if not isinstance(signature, str) or not signature.startswith('sha256='):
        raise ValueError('invalid signature')
    supplied = signature[7:]
    if len(supplied) != 64 or any((c not in '0123456789abcdef' for c in supplied)):
        raise ValueError('invalid signature')
    expected = hmac.new(secret.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(supplied, expected):
        raise ValueError('invalid signature')
    try:
        data = json.loads(payload)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(data, dict) or not isinstance(data.get('rollout'), str) or (not data['rollout']) or (not isinstance(data.get('namespace'), str)) or (not data['namespace']) or (not isinstance(data.get('replicas'), list)):
        raise ValueError('invalid payload')
    names = set()
    ready = 0
    restart_total = 0
    unhealthy = []
    for replica in data['replicas']:
        if not isinstance(replica, dict) or not isinstance(replica.get('name'), str) or (not replica['name']) or (replica['name'] in names) or (not isinstance(replica.get('ready'), bool)) or (not isinstance(replica.get('restarts'), int)) or isinstance(replica['restarts'], bool) or (replica['restarts'] < 0) or (not isinstance(replica.get('age_seconds'), (int, float))) or isinstance(replica['age_seconds'], bool) or (replica['age_seconds'] < 0):
            raise ValueError('invalid replica')
        names.add(replica['name'])
        restart_total += replica['restarts']
        if replica['ready']:
            ready += 1
        else:
            unhealthy.append(replica['name'])
    total = len(data['replicas'])
    unhealthy.sort()
    availability = round(ready * 100 / total, 2) if total else 0.0
    return {'rollout': data['rollout'], 'namespace': data['namespace'], 'total': total, 'ready': ready, 'unhealthy': unhealthy, 'restart_total': restart_total, 'availability': availability}

