import csv
import io
from datetime import datetime

def parse_docket_event(text: str) -> dict:
    if not isinstance(text, str):
        raise TypeError('text must be a string')
    parts, current, escaped = ([], [], False)
    for ch in text:
        if escaped:
            current.append(ch)
            escaped = False
        elif ch == '\\':
            escaped = True
        elif ch == ';':
            parts.append(''.join(current))
            current = []
        else:
            current.append(ch)
    if escaped:
        raise ValueError('trailing escape')
    parts.append(''.join(current))
    if not parts or not parts[0]:
        raise ValueError('empty kind')
    fields = {}
    for item in parts[1:]:
        if not item or '=' not in item:
            raise ValueError('bad field')
        key, value = item.split('=', 1)
        if not key or key in fields:
            raise ValueError('bad field')
        fields[key] = value
    return {'kind': parts[0], 'fields': fields}

def _check(requester, case):
    if requester.get('tenant_id') != case['tenant_id']:
        raise PermissionError('case access denied')
    if requester.get('id') != case['owner_id'] and (not {'clerk', 'judge'} & set(requester.get('roles', []))):
        raise PermissionError('case access denied')

def build_docket_report(requester: dict, case_record: dict, start_date: str | None=None, end_date: str | None=None) -> dict:
    _check(requester, case_record)
    try:
        start = datetime.strptime(start_date, '%Y-%m-%d').date() if start_date else None
        end = datetime.strptime(end_date, '%Y-%m-%d').date() if end_date else None
        if start and end and (start > end):
            raise ValueError('invalid range')
        participants = []
        for p in case_record['participants']:
            if not isinstance(p, dict) or not isinstance(p.get('id'), str) or (not isinstance(p.get('name'), str)):
                raise ValueError('bad participant')
            participants.append(dict(p))
        events = []
        for raw in case_record['events']:
            if not isinstance(raw.get('seq'), int) or isinstance(raw.get('seq'), bool) or (not isinstance(raw.get('minutes'), int)) or isinstance(raw.get('minutes'), bool) or (raw['minutes'] < 0):
                raise ValueError('bad event numbers')
            try:
                stamp = datetime.strptime(raw['at'], '%Y-%m-%dT%H:%M')
            except (KeyError, TypeError, ValueError):
                raise ValueError('bad timestamp')
            if start and stamp.date() < start or (end and stamp.date() > end):
                continue
            parsed = parse_docket_event(raw['text'])
            events.append({'seq': raw['seq'], 'at': raw['at'], 'kind': parsed['kind'], 'fields': parsed['fields'], 'minutes': raw['minutes'], '_stamp': stamp})
        events.sort(key=lambda x: (x['_stamp'], x['seq']))
        totals = {}
        for e in events:
            t = totals.setdefault(e['kind'], {'count': 0, 'minutes': 0})
            t['count'] += 1
            t['minutes'] += e['minutes']
            del e['_stamp']
        participants.sort(key=lambda p: (p['name'].casefold(), p['id']))
        return {'case_id': case_record['case_id'], 'events': events, 'totals': totals, 'participants': participants}
    except KeyError as exc:
        raise ValueError('missing field') from exc

def render_docket_csv(report: dict) -> str:
    out = io.StringIO(newline='')
    writer = csv.writer(out, lineterminator='\n')
    writer.writerow(['seq', 'at', 'kind', 'minutes', 'fields'])
    for e in report['events']:
        fields = ';'.join((f'{k}={v}' for k, v in e['fields'].items()))
        writer.writerow([e['seq'], e['at'], e['kind'], e['minutes'], fields])
    return out.getvalue()

