def build_notification_digest(events: list[dict], page: int, page_size: int) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('page must be at least 1')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('page_size must be between 1 and 100')
    grouped = {}
    for event in events:
        if not isinstance(event, dict):
            raise ValueError('each event must be a dictionary')
        required = ('mark', 'jurisdiction', 'event', 'priority', 'occurred_at')
        if any((key not in event for key in required)):
            raise ValueError('event is missing a required field')
        mark = event['mark']
        jurisdiction = event['jurisdiction']
        name = event['event']
        priority = event['priority']
        timestamp = event['occurred_at']
        if not all((isinstance(value, str) and value for value in (mark, jurisdiction, name, timestamp))):
            raise ValueError('event strings must be non-empty')
        if not isinstance(priority, int) or isinstance(priority, bool) or priority < 0:
            raise ValueError('priority must be a non-negative integer')
        try:
            parsed = datetime.fromisoformat(timestamp.replace('Z', '+00:00'))
        except ValueError as exc:
            raise ValueError('occurred_at must be an ISO 8601 datetime') from exc
        key = (mark, jurisdiction)
        if key not in grouped:
            grouped[key] = {'mark': mark, 'jurisdiction': jurisdiction, 'priority': priority, 'latest_occurred_at': timestamp, 'event_count': 1, 'events': {name}, 'parsed': parsed}
        else:
            item = grouped[key]
            item['priority'] = max(item['priority'], priority)
            item['event_count'] += 1
            item['events'].add(name)
            if parsed > item['parsed']:
                item['parsed'] = parsed
                item['latest_occurred_at'] = timestamp
    items = []
    for item in grouped.values():
        item = dict(item)
        item.pop('parsed')
        item['events'] = sorted(item['events'])
        items.append(item)
    items.sort(key=lambda item: (-item['priority'], -datetime.fromisoformat(item['latest_occurred_at'].replace('Z', '+00:00')).timestamp(), item['mark'], item['jurisdiction']))
    total = len(items)
    start = (page - 1) * page_size
    payload = {'page': page, 'page_size': page_size, 'total': total, 'items': items[start:start + page_size]}
    key = os.environ.get('TM_WATCH_SIGNING_KEY')
    if not key:
        raise RuntimeError('TM_WATCH_SIGNING_KEY is not set')
    data = json.dumps(payload, sort_keys=True, separators=(',', ':')).encode('utf-8')
    payload['signature'] = hmac.new(key.encode('utf-8'), data, hashlib.sha256).hexdigest()
    return payload

