import hmac
import json
from datetime import datetime

def verify_and_parse(payload: bytes, signature: str, secret: bytes) -> list[dict]:
    if not isinstance(payload, bytes) or not isinstance(signature, str) or (not isinstance(secret, bytes)):
        raise ValueError('invalid input')
    if len(signature) != 71 or not signature.startswith('sha256='):
        raise ValueError('invalid signature')
    value = signature[7:]
    if any((c not in '0123456789abcdef' for c in value)):
        raise ValueError('invalid signature')
    expected = hmac.new(secret, payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(value, expected):
        raise ValueError('invalid signature')
    try:
        result = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    if not isinstance(result, list):
        raise ValueError('invalid payload')
    return result

def reconcile_payments(events: list[dict], opening_balance: int=0) -> dict:
    if not isinstance(events, list) or isinstance(opening_balance, bool) or (not isinstance(opening_balance, int)):
        raise ValueError('invalid input')
    chosen = {}
    for position, item in enumerate(events):
        if not isinstance(item, dict):
            raise ValueError('invalid event')
        required = ('id', 'provider', 'amount', 'currency', 'status', 'timestamp')
        if any((k not in item for k in required)):
            raise ValueError('invalid event')
        ident, provider, amount, currency, status, stamp = (item[k] for k in required)
        if not isinstance(ident, str) or not ident or (not isinstance(provider, str)) or (not provider):
            raise ValueError('invalid event')
        if isinstance(amount, bool) or not isinstance(amount, int) or amount < 0:
            raise ValueError('invalid event')
        if not isinstance(currency, str) or len(currency) != 3 or (not currency.isascii()) or (not currency.isupper()):
            raise ValueError('invalid event')
        if status not in ('paid', 'refunded', 'failed') or not isinstance(stamp, str) or (not stamp.endswith('Z')):
            raise ValueError('invalid event')
        try:
            moment = datetime.fromisoformat(stamp[:-1])
        except ValueError:
            raise ValueError('invalid event')
        if ident not in chosen or (moment, position) >= chosen[ident][0]:
            chosen[ident] = ((moment, position), item)
    ordered = sorted((v[1] for v in chosen.values()), key=lambda x: (datetime.fromisoformat(x['timestamp'][:-1]), x['provider'], x['id']))
    by_currency = {}
    daily = {}
    balance = opening_balance
    for item in ordered:
        amount = item['amount'] if item['status'] == 'paid' else -item['amount'] if item['status'] == 'refunded' else 0
        currency = item['currency']
        date = item['timestamp'][:10]
        by_currency[currency] = by_currency.get(currency, 0) + amount
        daily[date] = daily.get(date, 0) + amount
        balance += amount
    return {'balance': balance, 'by_currency': dict(sorted(by_currency.items())), 'daily': dict(sorted(daily.items()))}

