                fields.append(''.join(current))
                current = []
            else:
                current.append(char)
        if escaped:
            raise ValueError('dangling escape')
        fields.append(''.join(current))
        if len(fields) != 4 or not fields[0] or (not fields[1]):
            raise ValueError('invalid membership record')
        try:
            visits = int(fields[2])
            points = int(fields[3])
        except ValueError as exc:
            raise ValueError('invalid membership numbers') from exc
        if visits < 0 or points < 0:
            raise ValueError('negative membership number')
        records.append({'id': fields[0], 'name': fields[1], 'visits': visits, 'points': points})
    return records

def aggregate_memberships(lines: list[str], config: dict[str, str] | None=None) -> list[dict[str, object]]:
    records = parse_membership_records(lines)
    if not records:
        return []
    key = config.get('membership_signing_key') if config is not None else None
    if key is None:
        key = os.environ.get('MUSEUM_MEMBERSHIP_SIGNING_KEY', 'museum-production-signing-key')
    combined = {}
    for record in records:
        member = combined.setdefault(record['id'], {'id': record['id'], 'name': record['name'], 'visits': 0, 'points': 0})
        member['visits'] += record['visits']
        member['points'] += record['points']
    result = []
    for member in combined.values():
        tier = 'patron' if member['points'] >= 500 else 'supporter' if member['points'] >= 200 else 'friend'
        item = {**member, 'tier': tier}
        text = '|'.join((str(item[k]) for k in ('id', 'name', 'visits', 'points', 'tier')))
        item['signature'] = hmac.new(key.encode(), text.encode(), hashlib.sha256).hexdigest()
        result.append(item)
    result.sort(key=lambda x: (-x['points'], -x['visits'], x['id']))
    return result

