import xml.etree.ElementTree as ET

def _numbered_bag(bag):
    required = ['tag', 'passenger', 'destination', 'weight', 'scanned', 'priority']
    if not isinstance(bag, dict) or any((k not in bag for k in required)):
        raise ValueError('invalid bag')
    tag = bag['tag']
    passenger = bag['passenger']
    destination = bag['destination']
    if not all((isinstance(x, str) and x.strip() for x in (tag, passenger, destination))):
        raise ValueError('invalid bag')
    try:
        weight = float(bag['weight'])
        scanned = int(bag['scanned'])
        priority = int(bag['priority'])
    except (TypeError, ValueError, OverflowError):
        raise ValueError('invalid bag')
    if weight <= 0 or scanned < 0 or (not 0 <= priority <= 9):
        raise ValueError('invalid bag')
    return {'tag': tag.strip(), 'passenger': passenger.strip(), 'destination': destination.strip(), 'weight': weight, 'scanned': scanned, 'priority': priority}

def parse_manifest(xml_text: str) -> dict[str, object]:
    try:
        root = ET.fromstring(xml_text)
    except (ET.ParseError, TypeError):
        raise ValueError('invalid XML')
    if root.tag != 'manifest':
        raise ValueError('invalid manifest')
    flight = root.get('flight', '').strip()
    if not flight:
        raise ValueError('invalid flight')
    bags = []
    seen = set()
    for node in root:
        if node.tag != 'bag':
            continue
        passenger_node = node.find('passenger')
        passenger = '' if passenger_node is None else ''.join(passenger_node.itertext()).strip()
        values = {'tag': node.get('tag', ''), 'destination': node.get('destination', ''), 'weight': node.get('weight'), 'scanned': node.get('scanned'), 'priority': node.get('priority'), 'passenger': passenger}
        bag = _numbered_bag(values)
        if bag['tag'] in seen:
            raise ValueError('duplicate tag')
        seen.add(bag['tag'])
        bags.append(bag)
    return {'flight': flight, 'bags': bags}

def reconcile_baggage(manifests: list[dict[str, object]], cutoff: int=30) -> dict[str, object]:
    if not isinstance(cutoff, int) or isinstance(cutoff, bool) or cutoff < 0:
        raise ValueError('invalid cutoff')
    all_bags = []
    tags = set()
    for manifest in manifests:
        if not isinstance(manifest, dict) or not isinstance(manifest.get('flight'), str) or (not isinstance(manifest.get('bags'), list)):
            raise ValueError('invalid manifest')
        for raw in manifest['bags']:
            bag = _numbered_bag(raw)
            if bag['tag'] in tags:
                raise ValueError('duplicate tag')
            tags.add(bag['tag'])
            all_bags.append(dict(bag))
    ordered = sorted(all_bags, key=lambda b: (b['destination'], -b['priority'], b['scanned'], b['tag']))
    grouped = {}
    for bag in ordered:
        d = bag['destination']
        if d not in grouped:
            grouped[d] = {'count': 0, 'weight': 0.0, 'late': 0, 'priority_count': 0}
        item = grouped[d]
        item['count'] += 1
        item['weight'] += bag['weight']
        item['late'] += bag['scanned'] > cutoff
        item['priority_count'] += bag['priority'] >= 5
    for item in grouped.values():
        item['weight'] = round(item['weight'], 2)
    return {'bags': ordered, 'destinations': grouped}

