    except ValueError:
        raise ValueError('invalid date')
    if parsed.isoformat() != value:
        raise ValueError('invalid date')
    return parsed

def parse_signed_renewal(message: bytes, secret: bytes) -> dict:
    if not isinstance(message, bytes) or not isinstance(secret, bytes):
        raise ValueError('invalid message')
    try:
        header, body = message.split(b'\n\n', 1)
        if b'\n' in header or not header.startswith(b'Signature: '):
            raise ValueError('invalid header')
        signature = header[11:]
        if len(signature) != 64 or any((c not in b'0123456789abcdef' for c in signature)):
            raise ValueError('invalid signature')
        text = body.decode('utf-8')
        supplied = bytes.fromhex(signature.decode('ascii'))
    except (ValueError, UnicodeDecodeError):
        raise ValueError('invalid message')
    expected = hmac.new(secret, body, hashlib.sha256).digest()
    if not hmac.compare_digest(expected, supplied):
        raise ValueError('invalid signature')
    try:
        value = json.loads(text)
    except (ValueError, TypeError):
        raise ValueError('invalid json')
    if not isinstance(value, dict) or set(value) != {'application_id', 'renewal_year', 'due_date', 'fees'}:
        raise ValueError('invalid body')
    app, year, due, fees = value.values()
    if not isinstance(app, str) or not app or isinstance(year, bool) or (not isinstance(year, int)) or (not 1 <= year <= 20):
        raise ValueError('invalid body')
    _date(due)
    if not isinstance(fees, list) or not fees:
        raise ValueError('invalid fees')
    total = 0
    descriptions = []
    for fee in fees:
        if not isinstance(fee, dict) or set(fee) != {'description', 'currency', 'amount'}:
            raise ValueError('invalid fee')
        desc, currency, amount = fee.values()
        if not isinstance(desc, str) or not desc or currency != 'USD' or isinstance(amount, bool) or (not isinstance(amount, int)) or (amount < 0):
            raise ValueError('invalid fee')
        total += amount
        descriptions.append(desc)
    return {'application_id': app, 'renewal_year': year, 'due_date': due, 'total_fee': total, 'descriptions': descriptions}

def build_renewal_schedule(records: list[dict], as_of: str) -> list[dict]:
    start = _date(as_of)
    end = start + timedelta(days=365)
    groups = {}
    keys = {'application_id', 'renewal_year', 'due_date', 'total_fee', 'descriptions'}
    for record in records:
        if not isinstance(record, dict) or set(record) != keys:
            raise ValueError('invalid record')
