        if not isinstance(app, str) or not app or isinstance(year, bool) or (not isinstance(year, int)) or (not 1 <= year <= 20) or isinstance(total, bool) or (not isinstance(total, int)) or (total < 0) or (not isinstance(descriptions, list)) or any((not isinstance(x, str) or not x for x in descriptions)):
