import ast
import operator

def _evaluate(expression, values):
    tree = ast.parse(expression, mode='eval')

    def visit(node):
        if isinstance(node, ast.Expression):
            return visit(node.body)
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, complex)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in values:
                raise NameError(node.id)
            return values[node.id]
        if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
            return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](visit(node.left), visit(node.right))
        if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub, ast.Not):
            value = visit(node.operand)
            return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
        if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
            result = visit(node.values[0])
            for child in node.values[1:]:
                if isinstance(node.op, ast.And) and (not result) or (isinstance(node.op, ast.Or) and result):
                    return result
                result = visit(child)
            return result
        if isinstance(node, ast.Compare):
            left = visit(node.left)
            ops = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.GtE: operator.ge, ast.Gt: operator.gt}
            for op, child in zip(node.ops, node.comparators):
                right = visit(child)
                if type(op) not in ops:
                    raise ValueError('unsupported expression')
                if not ops[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
            return {'min': min, 'max': max, 'round': round}[node.func.id](*[visit(a) for a in node.args])
        raise ValueError('unsupported expression')
    try:
        return visit(tree)
    except (SyntaxError, TypeError, ZeroDivisionError) as exc:
        raise ValueError('invalid expression') from exc

def build_pulse_report(records: list[dict], expression: str, page: int, page_size: int) -> dict:
    if page < 1 or page_size < 1:
        raise ValueError('invalid page')
    matched = [r for r in records if _evaluate(expression, {'score': r['score'], 'responses': r['responses'], 'tenure': r['tenure']})]
    matched.sort(key=lambda r: (-r['score'], r['id']))
    start = (page - 1) * page_size
    items = [{'id': r['id'], 'team': r['team'], 'score': r['score']} for r in matched[start:start + page_size]]
    average = round(sum((r['score'] for r in matched)) / len(matched), 2) if matched else None
    return {'total': len(matched), 'average_score': average, 'items': items}

