from solution import validate_and_report
import hashlib
import hmac
import json
import math
import pytest


def signed(payload, secret="warehouse-key"):
    digest = hmac.new(secret.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return "sha256=" + digest


def test_empty_inventory():
    payload = json.dumps({"items": []}, separators=(",", ":"))
    assert validate_and_report(payload, signed(payload), "warehouse-key") == {
        "verified": True,
        "item_count": 0,
        "total_quantity_kg": 0.0,
        "categories": [],
        "over_limit": [],
    }


def test_aggregation_sorting_rounding_and_limits():
    data = {
        "items": [
            {"name": "Acetone", "category": "Solvent", "quantity_kg": 1.2346, "threshold_kg": 2},
            {"name": "Benzene", "category": "Toxic", "quantity_kg": 4.0, "threshold_kg": 4},
            {"name": "ammonia", "category": "Toxic", "quantity_kg": 1.005, "threshold_kg": 1},
            {"name": "Zinc", "category": "Metal", "quantity_kg": 2.5, "threshold_kg": 1},
        ]
    }
    payload = json.dumps(data, separators=(",", ":"))
    result = validate_and_report(payload, signed(payload), "warehouse-key")
    assert result == {
        "verified": True,
        "item_count": 4,
        "total_quantity_kg": 8.74,
        "categories": [
            {"category": "Toxic", "quantity_kg": 5.005, "item_count": 2},
            {"category": "Metal", "quantity_kg": 2.5, "item_count": 1},
            {"category": "Solvent", "quantity_kg": 1.235, "item_count": 1},
        ],
        "over_limit": ["ammonia", "Zinc"],
    }


def test_category_ties_use_category_name():
    data = {"items": [
        {"name": "one", "category": "Zeta", "quantity_kg": 2, "threshold_kg": 9},
        {"name": "two", "category": "Alpha", "quantity_kg": 2, "threshold_kg": 9},
    ]}
    payload = json.dumps(data)
    result = validate_and_report(payload, signed(payload), "warehouse-key")
    assert [x["category"] for x in result["categories"]] == ["Alpha", "Zeta"]


def test_signature_rejection_variants():
    payload = '{"items":[]}'
    good = signed(payload)
    assert validate_and_report(payload, "", "warehouse-key") == {"verified": False}
    assert validate_and_report(payload, "sha256=" + good[7:-1], "warehouse-key") == {"verified": False}
    assert validate_and_report(payload, "sha256=" + "g" * 64, "warehouse-key") == {"verified": False}
