import hashlib
import hmac
import json
import math

def validate_and_report(payload: str, signature: str, secret: str) -> dict:
    if not isinstance(signature, str) or not signature.startswith('sha256='):
        return {'verified': False}
    supplied = signature[7:]
    if len(supplied) != 64:
        return {'verified': False}
    try:
        provided = bytes.fromhex(supplied)
    except ValueError:
        return {'verified': False}
    expected = hmac.new(secret.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).digest()
    if not hmac.compare_digest(expected, provided):
        return {'verified': False}
    try:
        document = json.loads(payload)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(document, dict) or not isinstance(document.get('items'), list):
        raise ValueError('invalid payload')
    totals = {}
    counts = {}
    over_limit = []
    for item in document['items']:
        if not isinstance(item, dict):
            raise ValueError('invalid item')
        name = item.get('name')
        category = item.get('category')
        quantity = item.get('quantity_kg')
        threshold = item.get('threshold_kg')
        if not isinstance(name, str) or not name or (not isinstance(category, str)) or (not category) or isinstance(quantity, bool) or (not isinstance(quantity, (int, float))) or isinstance(threshold, bool) or (not isinstance(threshold, (int, float))) or (not math.isfinite(quantity)) or (not math.isfinite(threshold)) or (quantity < 0) or (threshold < 0):
            raise ValueError('invalid item')
        totals[category] = totals.get(category, 0) + quantity
        counts[category] = counts.get(category, 0) + 1
        if quantity > threshold:
            over_limit.append(name)
    categories = [{'category': category, 'quantity_kg': round(total, 3), 'item_count': counts[category]} for category, total in totals.items()]
    categories.sort(key=lambda value: (-value['quantity_kg'], value['category']))
    over_limit.sort(key=lambda value: (value.casefold(), value))
    return {'verified': True, 'item_count': len(document['items']), 'total_quantity_kg': round(sum(totals.values()), 3), 'categories': categories, 'over_limit': over_limit}

