import hashlib
import hmac
import os

def build_collection(records: list[dict], curator_password: str) -> dict:
    if not isinstance(curator_password, str) or not curator_password:
        raise ValueError('invalid password')
    if not isinstance(records, list):
        raise ValueError('invalid records')
    seen = set()
    items = []
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        if set(record) != {'specimen_id', 'species', 'region', 'year', 'weight_g'}:
            raise ValueError('invalid record')
        sid, species, region = (record['specimen_id'], record['species'], record['region'])
        year, weight = (record['year'], record['weight_g'])
        if any((not isinstance(x, str) or not x for x in (sid, species, region))):
            raise ValueError('invalid record')
        if not isinstance(year, int) or isinstance(year, bool) or (not 1800 <= year <= 2100):
            raise ValueError('invalid record')
        if isinstance(weight, bool) or not isinstance(weight, (int, float)) or weight <= 0:
            raise ValueError('invalid record')
        if sid in seen:
            raise ValueError('duplicate specimen')
        seen.add(sid)
        items.append(dict(record))
    items.sort(key=lambda x: (x['species'], x['specimen_id']))
    summary = []
    for species in sorted({x['species'] for x in items}):
        weights = [x['weight_g'] for x in items if x['species'] == species]
        summary.append({'species': species, 'count': len(weights), 'total_weight_g': round(sum(weights), 2), 'average_weight_g': round(sum(weights) / len(weights), 2)})
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', curator_password.encode(), salt, 100000)
    return {'curator_hash': digest.hex(), 'curator_salt': salt.hex(), 'specimens': items, 'species_summary': summary}

def verify_curator(collection: dict, password: str) -> bool:
    try:
        if not isinstance(password, str) or not password or (not isinstance(collection, dict)):
            return False
        salt = bytes.fromhex(collection['curator_salt'])
        expected = bytes.fromhex(collection['curator_hash'])
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError):
        return False

def specimen_page(collection: dict, page: int, page_size: int) -> list[dict]:
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0 or isinstance(page_size, bool) or (not isinstance(page_size, int)) or (page_size <= 0):
        raise ValueError('invalid page')
    if not isinstance(collection, dict) or not isinstance(collection.get('specimens'), list) or any((not isinstance(x, dict) for x in collection['specimens'])):
        raise ValueError('invalid collection')
    start = (page - 1) * page_size
    return [dict(x) for x in collection['specimens'][start:start + page_size]]

