def format_publication_metadata(records: list[dict[str, object]]) -> str:
    blocks = []
    for record in records:
        title = record['title']
        authors = record['authors']
        year = record['year']
        if not isinstance(title, str) or not title:
            raise ValueError('title')
        if not isinstance(authors, list):
            raise TypeError('authors')
        if any((not isinstance(author, str) for author in authors)):
            raise ValueError('author')
        doi = record.get('doi')
        if doi is not None and (not isinstance(doi, str)):
            raise ValueError('doi')
        lines = ['TY  - JOUR', f'TI  - {title}']
        lines.extend((f'AU  - {author}' for author in authors))
        lines.append(f'PY  - {year}')
        if doi:
            lines.append(f'DO  - {doi}')
        lines.append('ER  -')
        blocks.append('\n'.join(lines))
    text = '\n\n'.join(blocks)
    if text:
        text += '\n'
    path = tempfile.mktemp()
    try:
        with open(path, 'w', encoding='utf-8') as handle:
            handle.write(text)
        with open(path, 'r', encoding='utf-8') as handle:
            return handle.read()
    finally:
        try:
            os.unlink(path)
        except FileNotFoundError:
            pass

