def generate_refresh_token(user_id: str, issued_at: int, used_tokens: set[str], length: int=32) -> str:
    if not isinstance(user_id, str) or not user_id or any((c not in string.ascii_letters + string.digits + '_-' for c in user_id)):
        raise ValueError('invalid user')
    if isinstance(issued_at, bool) or not isinstance(issued_at, int) or issued_at < 0:
        raise ValueError('invalid timestamp')
    if isinstance(length, bool) or not isinstance(length, int) or (not 16 <= length <= 128):
        raise ValueError('invalid length')
    alphabet = string.ascii_letters + string.digits
    while True:
        value = ''.join((secrets.choice(alphabet) for _ in range(length)))
        if value not in used_tokens:
            return value

def _split_line(line: str) -> list[str]:
    fields, current, escaped = ([], [], False)
    for char in line:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('dangling escape')
    fields.append(''.join(current))
    return fields

def parse_refresh_log(text: str) -> list[dict]:
    if not isinstance(text, str):
        raise ValueError('invalid text')
    result = []
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields = _split_line(raw)
        if len(fields) != 4 or not fields[1] or fields[3] not in ('success', 'failure'):
            raise ValueError('invalid record')
        try:
            timestamp = int(fields[0])
            duration = float(fields[2])
        except (TypeError, ValueError):
            raise ValueError('invalid number')
        if timestamp < 0 or duration < 0 or (not math.isfinite(duration)):
            raise ValueError('invalid value')
        result.append({'timestamp': timestamp, 'user': fields[1], 'duration': duration, 'status': fields[3]})
    return result

def summary_refreshes(text: str, window_seconds: int=60) -> list[dict]:
    if isinstance(window_seconds, bool) or not isinstance(window_seconds, int) or window_seconds <= 0:
        raise ValueError('invalid window')
    groups = {}
    for record in parse_refresh_log(text):
        start = record['timestamp'] // window_seconds * window_seconds
        key = (record['user'], start)
        if key not in groups:
            groups[key] = {'user': record['user'], 'window_start': start, 'count': 0, 'successful': 0, 'duration': 0.0, 'latest_status': record['status']}
        group = groups[key]
        group['count'] += 1
        group['successful'] += record['status'] == 'success'
        group['duration'] += record['duration']
        group['latest_status'] = record['status']
    return [groups[key] for key in sorted(groups)]

