import re
import secrets
from decimal import Decimal, ROUND_HALF_UP

def generate_sync_token(store_id: str, length: int=16) -> str:
    if not isinstance(store_id, str):
        raise TypeError('store_id must be a string')
    if not re.fullmatch('[A-Za-z0-9-]+', store_id):
        raise ValueError('invalid store_id')
    if not isinstance(length, int) or isinstance(length, bool):
        raise TypeError('length must be an integer')
    if length < 8 or length > 64:
        raise ValueError('invalid length')
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    return store_id + '-' + ''.join((secrets.choice(alphabet) for _ in range(length)))

def synchronize_inventory(records: list[dict], page: int=1, page_size: int=50) -> dict:
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    if not isinstance(page, int) or isinstance(page, bool) or (not isinstance(page_size, int)) or isinstance(page_size, bool):
        raise TypeError('pagination must be integers')
    if page < 1 or page_size < 1:
        raise ValueError('pagination must be positive')
    combined = {}
    total_units = 0
    for record in records:
        if not isinstance(record, dict):
            raise TypeError('record must be a dictionary')
        if 'sku' not in record or 'quantity' not in record or 'unit_price' not in record:
            raise ValueError('missing inventory field')
        sku = record['sku']
        quantity = record['quantity']
        price = record['unit_price']
        if not isinstance(sku, str):
            raise TypeError('sku must be a string')
        if not sku:
            raise ValueError('sku must not be empty')
        if not isinstance(quantity, int) or isinstance(quantity, bool):
            raise TypeError('quantity must be an integer')
        if not isinstance(price, (int, float)) or isinstance(price, bool):
            raise TypeError('unit_price must be numeric')
        if quantity < 0 or price < 0:
            raise ValueError('quantity and price must be non-negative')
        amount = Decimal(str(price)) * quantity
        if sku not in combined:
            combined[sku] = [0, Decimal('0')]
        combined[sku][0] += quantity
        combined[sku][1] += amount
        total_units += quantity
    items = []
    for sku, (quantity, value) in combined.items():
        rounded = value.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        items.append({'sku': sku, 'quantity': quantity, 'value': f'{rounded:.2f}'})
    items.sort(key=lambda item: (-item['quantity'], item['sku']))
    total = sum((value for _, value in (entry for entry in combined.values())), Decimal('0'))
    total = total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    start = (page - 1) * page_size
    return {'total': len(items), 'total_units': total_units, 'total_value': f'{total:.2f}', 'items': items[start:start + page_size]}

