import csv
import subprocess
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from io import StringIO
from typing import Optional

def transaction_summary(path: str, category: Optional[str]=None, page: int=1, page_size: int=10) -> list[dict[str, object]]:
    if page < 1 or page_size < 1:
        raise ValueError('page and page_size must be positive')
    result = subprocess.run(['cat', path], check=True, capture_output=True, text=True)
    reader = csv.DictReader(StringIO(result.stdout))
    required = ['date', 'description', 'amount', 'category']
    if reader.fieldnames != required:
        raise ValueError('invalid header')
    totals = {}
    counts = {}
    for row in reader:
        if None in row or any((value is None for value in row.values())):
            raise ValueError('malformed row')
        try:
            amount = Decimal(row['amount']).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        except (InvalidOperation, ValueError):
            raise ValueError('invalid amount')
        name = row['category']
        if category is not None and name != category:
            continue
        totals[name] = totals.get(name, Decimal('0.00')) + amount
        counts[name] = counts.get(name, 0) + 1
    names = sorted(totals, key=lambda name: (-totals[name], name))
    start = (page - 1) * page_size
    selected = names[start:start + page_size]
    return [{'category': name, 'count': counts[name], 'total': f'{totals[name]:.2f}'} for name in selected]

