import base64
import datetime
import hashlib
import hmac
import os

def hash_password(password: str) -> str:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 120000)
    return base64.b64encode(salt).decode() + ':' + base64.b64encode(digest).decode()

def verify_password(password: str, stored: str) -> bool:
    if not isinstance(password, str) or not isinstance(stored, str):
        raise TypeError('arguments must be strings')
    try:
        salt_text, digest_text = stored.split(':', 1)
        salt = base64.b64decode(salt_text.encode(), validate=True)
        expected = base64.b64decode(digest_text.encode(), validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 120000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def _parse_time(value):
    try:
        parsed = datetime.datetime.fromisoformat(value.replace('Z', '+00:00'))
    except (AttributeError, ValueError):
        raise ValueError('invalid timestamp')
    if parsed.tzinfo is None:
        raise ValueError('timestamp must have timezone')
    return parsed.astimezone(datetime.timezone.utc)

def generate_timeline_report(events: list[dict], start: str | None=None, end: str | None=None, page: int=1, page_size: int=10) -> dict:
    if not isinstance(events, list):
        raise TypeError('events must be a list')
    if start is not None and (not isinstance(start, str)) or (end is not None and (not isinstance(end, str))):
        raise TypeError('boundaries must be strings')
    if not isinstance(page, int) or not isinstance(page_size, int) or page < 1 or (page_size < 1):
        raise ValueError('invalid pagination')
    lower = _parse_time(start) if start is not None else None
    upper = _parse_time(end) if end is not None else None
    if lower is not None and upper is not None and (lower > upper):
        raise ValueError('invalid range')
    parsed = []
    for event in events:
        if not isinstance(event, dict) or not all((k in event for k in ('id', 'timestamp', 'category', 'severity', 'minutes'))):
            raise ValueError('invalid event')
        if not all((isinstance(event[k], str) for k in ('id', 'timestamp', 'category', 'severity'))) or isinstance(event['minutes'], bool) or (not isinstance(event['minutes'], (int, float))):
            raise ValueError('invalid event')
        moment = _parse_time(event['timestamp'])
        if (lower is None or moment >= lower) and (upper is None or moment <= upper):
            parsed.append((moment, event['id'], dict(event)))
    parsed.sort(key=lambda x: (x[0], x[1]))
    counts = {}
    for _, _, event in parsed:
        counts[event['category']] = counts.get(event['category'], 0) + 1
    counts = dict(sorted(counts.items()))
    first = (page - 1) * page_size
    return {'total': len(parsed), 'page': page, 'page_size': page_size, 'events': [x[2] for x in parsed[first:first + page_size]], 'by_category': counts, 'total_minutes': round(sum((x[2]['minutes'] for x in parsed)), 2)}

