    iterations = 100000
    digest = hashlib.pbkdf2_hmac('sha256', code.encode(), salt, iterations)
    return f'{iterations}${salt.hex()}${digest.hex()}'

def check_access_code(code: str, stored: str) -> bool:
    if not isinstance(code, str) or not isinstance(stored, str):
        return False
    try:
        iterations_text, salt_text, digest_text = stored.split('$')
        iterations = int(iterations_text)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', code.encode(), salt, iterations)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

