from numbers import Real

def build_incident_report(records: list[dict], config: dict | None=None) -> dict:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    config = config or {}
    key = config.get('REPORT_SIGNING_KEY') or os.environ.get('REPORT_SIGNING_KEY')
    if not key:
        raise ValueError('REPORT_SIGNING_KEY is required')
    if not isinstance(key, str):
        raise ValueError('REPORT_SIGNING_KEY must be a string')
    seen = set()
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('each record must be a dictionary')
        try:
            incident_id = record['incident_id']
            district = record['district']
            severity = record['severity']
            response = record['response_minutes']
            resolved = record['resolved']
        except KeyError as exc:
            raise ValueError('missing incident field') from exc
        if not isinstance(incident_id, str) or not incident_id or incident_id in seen:
            raise ValueError('incident_id must be unique and non-empty')
        if not isinstance(district, str) or not district:
            raise ValueError('district must be non-empty')
        if severity not in {'low', 'medium', 'high', 'critical'}:
            raise ValueError('invalid severity')
        if isinstance(response, bool) or not isinstance(response, Real) or response < 0:
            raise ValueError('invalid response_minutes')
        if not isinstance(resolved, bool):
            raise ValueError('resolved must be boolean')
        seen.add(incident_id)
        group = groups.setdefault(district, [0, 0, 0.0])
        group[0] += 1
        group[1] += severity == 'critical'
        group[2] += response
    by_district = []
    for district in sorted(groups):
        count, critical, total = groups[district]
        by_district.append({'district': district, 'incidents': count, 'average_response_minutes': round(total / count, 2), 'critical_incidents': critical})
    payload = {'total_incidents': len(records), 'open_incidents': sum((not r['resolved'] for r in records)), 'by_district': by_district}
    encoded = json.dumps(payload, sort_keys=True, separators=(',', ':')).encode()
    payload['signature'] = hmac.new(key.encode(), encoded, hashlib.sha256).hexdigest()
    return payload

