import base64
import hashlib
import hmac
import os

def make_pin_record(pin: str) -> str:
    if not isinstance(pin, str):
        raise TypeError('pin must be a string')
    if not pin:
        raise ValueError('pin must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return base64.b64encode(salt + digest).decode('ascii')

def verify_pin(pin: str, record: str) -> bool:
    if not isinstance(pin, str) or not isinstance(record, str):
        return False
    try:
        raw = base64.b64decode(record.encode('ascii'), validate=True)
        if len(raw) != 48:
            return False
        salt, expected = (raw[:16], raw[16:])
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, UnicodeError):
        return False

def leave_report(requests: list[dict], approver_pin: str, stored_pin: str, offset: int=0, limit: int=10) -> list[dict]:
    if not verify_pin(approver_pin, stored_pin):
        raise PermissionError('invalid approver PIN')
    if not isinstance(requests, list):
        raise TypeError('requests must be a list')
    if offset < 0 or limit <= 0:
        raise ValueError('invalid pagination')
    groups = {}
    for item in requests:
        if not isinstance(item, dict) or any((key not in item for key in ('employee', 'department', 'days', 'status'))):
            raise ValueError('invalid request')
        if not isinstance(item['employee'], str) or not isinstance(item['department'], str) or (not isinstance(item['status'], str)) or (item['status'] not in {'approved', 'pending', 'rejected'}) or (not isinstance(item['days'], int)) or isinstance(item['days'], bool) or (item['days'] <= 0):
            raise ValueError('invalid request')
        if item['status'] == 'rejected':
            continue
        department = item['department']
        group = groups.setdefault(department, {'department': department, 'approved_days': 0, 'pending_count': 0, 'request_count': 0})
        group['request_count'] += 1
        if item['status'] == 'approved':
            group['approved_days'] += item['days']
        else:
            group['pending_count'] += 1
    result = sorted(groups.values(), key=lambda x: (-x['approved_days'], -x['pending_count'], x['department']))
    return result[offset:offset + limit]

