import os
import json
import hmac
import hashlib

def parse_preferences(text: str) -> list[str]:
    if not isinstance(text, str):
        raise ValueError('preferences must be a string')
    if not text.strip():
        return []
    result = []
    current = []
    escaped = False
    for char in text:
        if escaped:
            if char not in ',\\':
                current.append('\\')
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == ',':
            item = ''.join(current).strip()
            if not item:
                raise ValueError('empty preference')
            result.append(item)
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape')
    item = ''.join(current).strip()
    if not item:
        raise ValueError('empty preference')
    result.append(item)
    return result

def allocate_housing(applications: list[dict], rooms: list[dict], config: dict | None=None) -> dict:
    key = None
    if config is not None and 'signing_key' in config:
        key = config['signing_key']
    if key is None:
        key = os.environ.get('HOUSING_SIGNING_KEY')
    if key is None:
        raise ValueError('missing signing key')
    room_map = {}
    remaining = {}
    for room in rooms:
        if 'id' not in room or 'capacity' not in room or room['id'] in room_map or (room['capacity'] <= 0):
            raise ValueError('invalid room')
        room_map[room['id']] = room
        remaining[room['id']] = room['capacity']
    seen = set()
    normalized = []
    for app in applications:
        required = ('id', 'year', 'submitted_at', 'preferences')
        if any((field not in app for field in required)) or app['id'] in seen:
            raise ValueError('invalid application')
        seen.add(app['id'])
        prefs = parse_preferences(app['preferences']) if isinstance(app['preferences'], str) else list(app['preferences'])
        normalized.append((app, prefs))
    normalized.sort(key=lambda pair: (-pair[0]['year'], pair[0]['submitted_at'], pair[0]['id']))
    assignments = []
    unassigned = []
    for app, prefs in normalized:
        selected = None
        for room_id in prefs:
            room = room_map.get(room_id)
            if room is not None and remaining[room_id] and (not app.get('accessible', False) or room.get('accessible', False)):
                selected = room_id
                break
        if selected is None:
            unassigned.append(app['id'])
        else:
            remaining[selected] -= 1
            assignments.append({'id': app['id'], 'room_id': selected})
    payload = {'assignments': assignments, 'unassigned': unassigned}
    body = json.dumps(payload, sort_keys=True, separators=(',', ':')).encode()
    signature = hmac.new(str(key).encode(), body, hashlib.sha256).hexdigest()
    return {'assignments': assignments, 'unassigned': unassigned, 'signature': signature}

