                raise ValueError('invalid row')
            section, page, title, count = (x.strip() for x in row)
            if not section or not page.isdecimal() or (not count.isdecimal()):
                raise ValueError('invalid value')
            page_number = int(page)
            byte_count = int(count)
            if page_number < 1:
                raise ValueError('invalid page')
            if (section, page_number) in result:
                raise ValueError('duplicate page')
            result[section, page_number] = (title, byte_count)
    except (csv.Error, TypeError):
        raise ValueError('invalid manifest')
    grouped = {}
    for (section, page), (title, count) in result.items():
        grouped.setdefault(section, []).append({'page': page, 'title': title, 'bytes': count})
    return [{'section': s, 'pages': sorted(p, key=lambda x: x['page']), 'total_bytes': sum((x['bytes'] for x in p))} for s, p in sorted(grouped.items(), key=lambda x: (x[0].lower(), x[0]))]

