            raise ValueError('invalid byte count')
        if not isinstance(asset['approved'], bool):
            raise ValueError('invalid approval')
        checked.append(asset)
    selected = [a for a in checked if a['approved']]
    rows = sorted(selected, key=lambda a: (a['brand'], -a['bytes'], a['id']))
    total = sum((a['bytes'] for a in selected))
    largest = min(selected, key=lambda a: (-a['bytes'], a['id']))['id'] if selected else None
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(prefix='brand-report-', suffix='.csv', dir=directory)
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as output:
            writer = csv.writer(output)
            writer.writerow(['asset_id', 'brand', 'name', 'kind', 'bytes'])
            for asset in rows:
                writer.writerow([asset['id'], asset['brand'], asset['name'], asset['kind'], asset['bytes']])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return {'assets': len(selected), 'bytes': total, 'brands': len({a['brand'] for a in selected}), 'largest': largest}

