import base64
import hashlib
import hmac
import json
from typing import Mapping

def _key(config: Mapping[str, str]) -> bytes:
    try:
        value = config['signing_key']
    except (KeyError, TypeError):
        raise ValueError('missing signing_key')
    if not isinstance(value, str) or not value:
        raise ValueError('missing signing_key')
    return value.encode()

def create_access_pass(member_id: str, zones: list[str], valid_from: int, valid_until: int, config: dict[str, str]) -> str:
    if not isinstance(member_id, str) or not member_id:
        raise ValueError('invalid member_id')
    if not isinstance(zones, list) or not zones or any((not isinstance(z, str) or not z for z in zones)):
        raise ValueError('invalid zones')
    if not isinstance(valid_from, int) or isinstance(valid_from, bool) or (not isinstance(valid_until, int)) or isinstance(valid_until, bool) or (valid_from >= valid_until):
        raise ValueError('invalid interval')
    unique = list(dict.fromkeys(zones))
    payload = {'member_id': member_id, 'zones': unique, 'valid_from': valid_from, 'valid_until': valid_until}
    raw = json.dumps(payload, separators=(',', ':'), ensure_ascii=False).encode()
    encoded = base64.urlsafe_b64encode(raw).decode().rstrip('=')
    signature = hmac.new(_key(config), encoded.encode(), hashlib.sha256).hexdigest()
    return encoded + '.' + signature

def validate_access_pass(token: str, zone: str, at: int, config: dict[str, str]) -> bool:
    try:
        if not isinstance(token, str) or token.count('.') != 1:
            return False
        encoded, signature = token.split('.')
        expected = hmac.new(_key(config), encoded.encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(signature, expected):
            return False
        raw = base64.urlsafe_b64decode(encoded + '=' * (-len(encoded) % 4))
        payload = json.loads(raw.decode())
        if set(payload) != {'member_id', 'zones', 'valid_from', 'valid_until'}:
            return False
        member = payload['member_id']
        zones = payload['zones']
        start = payload['valid_from']
        end = payload['valid_until']
        if not isinstance(member, str) or not member or (not isinstance(zones, list)) or (not zones):
            return False
        if any((not isinstance(z, str) or not z for z in zones)) or len(zones) != len(set(zones)):
            return False
        if not isinstance(start, int) or isinstance(start, bool) or (not isinstance(end, int)) or isinstance(end, bool) or (start >= end):
            return False
        return isinstance(zone, str) and isinstance(at, int) and (not isinstance(at, bool)) and (zone in zones) and (start <= at < end)
    except (ValueError, TypeError, KeyError, UnicodeError, json.JSONDecodeError):
        return False

def summarize_entries(entries: list[dict[str, object]]) -> dict[str, dict[str, object]]:
    result = {}
    for record in entries:
        if not isinstance(record, dict) or set(record) != {'member_id', 'zone', 'at'}:
            raise ValueError('invalid record')
        member, zone, at = (record['member_id'], record['zone'], record['at'])
        if not isinstance(member, str) or not member or (not isinstance(zone, str)) or (not zone) or (not isinstance(at, int)) or isinstance(at, bool):
            raise ValueError('invalid record')
        if member not in result:
            result[member] = {'entries': 0, 'first_at': at, 'last_at': at, 'zones': []}
        item = result[member]
        item['entries'] += 1
        item['first_at'] = min(item['first_at'], at)
        item['last_at'] = max(item['last_at'], at)
        if zone not in item['zones']:
            item['zones'].append(zone)
