        if sub.tag != 'subscriber' or (sub.tail or '').strip() or (sub.text or '').strip():
            raise ValueError('unexpected content')
        sid = (sub.get('id') or '').strip()
        plan = (sub.get('plan') or '').strip()
        if not sid or not plan or sid in seen:
            raise ValueError('invalid subscriber')
        seen.add(sid)
        statuses = [x for x in sub if x.tag == 'status']
        events_nodes = [x for x in sub if x.tag == 'events']
        if len(statuses) != 1 or len(events_nodes) > 1:
            raise ValueError('invalid structure')
        if any((x.tag not in ('status', 'events') or (x.tail or '').strip() for x in sub)):
            raise ValueError('unexpected content')
        status = _text(statuses[0])
        if status not in ('active', 'suspended', 'closed') or list(statuses[0]):
            raise ValueError('invalid status')
        events = []
        if events_nodes:
            box = events_nodes[0]
            if (box.text or '').strip():
                raise ValueError('unexpected text')
            for ev in box:
