                    raise ValueError('invalid event')
                try:
                    timestamp = int(ev.get('timestamp'))
                    units = int(ev.get('units'))
                except (TypeError, ValueError) as exc:
                    raise ValueError('invalid number') from exc
                kind = (ev.get('kind') or '').strip()
                if timestamp < 0 or units < 0 or (not kind) or (ev.text or '').strip():
                    raise ValueError('invalid event')
                events.append({'timestamp': timestamp, 'kind': kind, 'units': units})
        events.sort(key=lambda x: (x['timestamp'], x['kind'], x['units']))
        result.append({'id': sid, 'plan': plan, 'status': status, 'events': events})
    return sorted(result, key=lambda x: x['id'])

def summarize_provisioning(document: str) -> dict:
    subscribers = parse_subscribers(document)
    counts = {'active': 0, 'suspended': 0, 'closed': 0}
    plans = {}
    hours = {}
    for sub in subscribers:
        counts[sub['status']] += 1
        plans[sub['plan']] = plans.get(sub['plan'], 0)
        for event in sub['events']:
            plans[sub['plan']] += event['units']
            hour = event['timestamp'] // 3600
            hours[hour] = hours.get(hour, 0) + event['units']
    peak = None if not hours else min(hours, key=lambda h: (-hours[h], h))
    return {'subscriber_count': len(subscribers), 'by_status': counts, 'units_by_plan': {k: plans[k] for k in sorted(plans)}, 'peak_hour': peak}

