    total = sum((row[0] for row in rows))
    months = {}
    for price, month in rows:
        if month not in months:
            months[month] = [0, 0.0]
        months[month][0] += 1
        months[month][1] += price
    return {'artist': artist, 'sale_count': len(rows), 'total_revenue': round(total, 2), 'average_price': round(total / len(rows), 2) if rows else 0.0, 'by_month': [{'month': month, 'sale_count': count, 'revenue': round(revenue, 2)} for month, (count, revenue) in months.items()]}

