import hashlib
import hmac
import json

def build_housekeeping_plan(body: bytes, signature: str, secret: bytes) -> list[dict]:
    if not isinstance(body, bytes) or not isinstance(secret, bytes):
        raise ValueError('invalid input')
    if not isinstance(signature, str) or len(signature) != 71 or (not signature.startswith('sha256=')):
        raise ValueError('invalid signature')
    supplied = signature[7:]
    if any((c not in '0123456789abcdef' for c in supplied)):
        raise ValueError('invalid signature')
    expected = hmac.new(secret, body, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, supplied):
        raise ValueError('invalid signature')
    try:
        document = json.loads(body.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('invalid body')
    if not isinstance(document, dict) or not isinstance(document.get('events'), list):
        raise ValueError('invalid body')
    latest = {}
    for event in document['events']:
        if not isinstance(event, dict):
            raise ValueError('invalid event')
        required = ('task_id', 'room', 'status', 'priority', 'minutes', 'updated')
        if any((key not in event for key in required)):
            raise ValueError('invalid event')
        task_id = event['task_id']
        room = event['room']
        status = event['status']
        priority = event['priority']
        minutes = event['minutes']
        updated = event['updated']
        if not isinstance(task_id, str) or not task_id or (not isinstance(room, str)) or (not room) or (status not in ('pending', 'in_progress', 'done')) or (type(priority) is not int) or (not 1 <= priority <= 5) or (type(minutes) is not int) or (minutes < 0) or (type(updated) is not int) or (updated < 0):
            raise ValueError('invalid event')
        old = latest.get(task_id)
        if old is None or updated >= old['updated']:
            latest[task_id] = event
    active = [event for event in latest.values() if event['status'] != 'done']
    active.sort(key=lambda event: (-event['priority'], event['updated'], event['room'], event['task_id']))
    return [{key: event[key] for key in ('task_id', 'room', 'status', 'priority', 'minutes')} for event in active]

