    actors = [
        {"name": "Drew", "score": 90, "experience": 1, "auditions": 1, "available": True},
        {"name": "Ava", "score": 90, "experience": 1, "auditions": 1, "available": True},
        {"name": "Bea", "score": 80, "experience": 1, "auditions": 1, "available": True},
