import base64
import hashlib
import hmac
import os

def _sequence(sequence):
    if not isinstance(sequence, str) or not sequence:
        raise ValueError('invalid sequence')
    sequence = sequence.upper()
    if any((ch not in 'ACGTN' for ch in sequence)):
        raise ValueError('invalid sequence')
    return sequence

def parse_fastq(text: str) -> list[tuple[str, str, str]]:
    if not isinstance(text, str) or not text or len(text.splitlines()) % 4:
        raise ValueError('invalid FASTQ')
    lines = text.splitlines()
    result = []
    for i in range(0, len(lines), 4):
        title, seq, plus, qual = lines[i:i + 4]
        if not title.startswith('@') or not title[1:] or plus != '+':
            raise ValueError('invalid FASTQ')
        ident = title[1:].split(None, 1)[0]
        seq = _sequence(seq)
        if len(qual) != len(seq) or any((not 33 <= ord(c) <= 126 for c in qual)):
            raise ValueError('invalid quality')
        result.append((ident, seq, qual))
    return result

def window_gc(sequence: str, size: int) -> list[tuple[int, int, float]]:
    sequence = _sequence(sequence)
    if isinstance(size, bool) or not isinstance(size, int) or size <= 0:
        raise ValueError('invalid window')
    return [(i, sum((c in 'GC' for c in sequence[i:i + size])), sum((c in 'GC' for c in sequence[i:i + size])) / size) for i in range(len(sequence) - size + 1)]

def make_sample_record(sequence: str, password: str) -> dict[str, str]:
    sequence = _sequence(sequence)
    if not isinstance(password, str) or not password:
        raise ValueError('invalid password')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return {'sequence': sequence, 'salt': base64.b64encode(salt).decode(), 'digest': digest.hex()}

def verify_sample_record(record: dict[str, str], password: str) -> bool:
    try:
        if not isinstance(record, dict) or not isinstance(password, str) or (not password):
            return False
        sequence = _sequence(record['sequence'])
        salt = base64.b64decode(record['salt'], validate=True)
        expected = bytes.fromhex(record['digest'])
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected) and sequence == record['sequence']
    except (KeyError, TypeError, ValueError):
        return False

def annotate_fastq(text: str, size: int) -> list[dict[str, object]]:
    return [{'id': ident, 'length': len(seq), 'gc_windows': window_gc(seq, size)} for ident, seq, _ in parse_fastq(text)]

