import csv
import datetime
import re
import subprocess

def attendance_report(path: str, week: str, page: int, page_size: int) -> list[dict[str, object]]:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1 or (page_size > 100):
        raise ValueError('invalid page size')
    if not re.fullmatch('\\d{4}-W\\d{2}', week):
        raise ValueError('invalid week')
    year = int(week[:4])
    number = int(week[6:])
    try:
        datetime.date.fromisocalendar(year, number, 1)
    except ValueError:
        raise ValueError('invalid week')
    result = subprocess.run(['sort', path], check=True, capture_output=True, text=True)
    totals = {}
    for row in csv.reader(result.stdout.splitlines()):
        if not row:
            continue
        if len(row) != 3:
            raise ValueError('malformed record')
        date_text, participant, status = row
        try:
            date = datetime.date.fromisoformat(date_text)
        except ValueError:
            raise ValueError('invalid date')
        if date.isoformat() != date_text or not participant or status not in {'present', 'absent', 'excused'}:
            raise ValueError('malformed record')
        iso = date.isocalendar()
        if iso.year != year or iso.week != number:
            continue
        if participant not in totals:
            totals[participant] = [0, 0]
        totals[participant][1] += 1
        if status == 'present':
            totals[participant][0] += 1
    rows = []
    for participant, (present, total) in totals.items():
        rows.append({'participant': participant, 'present': present, 'total': total, 'rate': round(present / total, 2)})
    rows.sort(key=lambda x: (-x['present'], -x['rate'], x['participant']))
    start = (page - 1) * page_size
    return rows[start:start + page_size]

