            row['pnl'] += value - h['cost_basis']
            row['accounts'].add(account['id'])
            row['holdings'] += 1
    out = [{'asset_class': k, 'market_value': round(v['value'], 2), 'pnl': round(v['pnl'], 2), 'accounts': len(v['accounts']), 'holdings': v['holdings']} for k, v in data.items()]
