def allocation_dashboard(requester: dict, allocations: list[dict], page: int, page_size: int) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1 or (page_size > 100):
        raise ValueError('invalid page size')
    is_admin = requester.get('role') == 'housing_admin'
    tenant_id = requester.get('tenant_id')
    if not is_admin and (not any((row.get('tenant_id') == tenant_id for row in allocations))):
        raise PermissionError('tenant is not available')
    visible = allocations if is_admin else [row for row in allocations if row.get('tenant_id') == tenant_id]
    groups = {}
    for row in visible:
        name = row['building']
        group = groups.setdefault(name, {'building': name, 'allocation_count': 0, 'occupied_count': 0, 'monthly_rent_total': 0.0})
        group['allocation_count'] += 1
        group['occupied_count'] += row['status'] == 'allocated'
        group['monthly_rent_total'] += row['monthly_rent']
    ordered = []
    for name in sorted(groups):
        group = groups[name]
        group['monthly_rent_total'] = round(group['monthly_rent_total'], 2)
        ordered.append(group)
    start = (page - 1) * page_size
    return {'page': page, 'page_size': page_size, 'total_buildings': len(ordered), 'buildings': ordered[start:start + page_size]}

