import os
import json
import hmac
import hashlib
from datetime import date, timedelta

def _key(settings):
    value = settings.get('plan_signing_key') if settings is not None else None
    if value is None:
        value = os.environ.get('PT_PLAN_SIGNING_KEY')
    if not value:
        raise ValueError('missing plan signing key')
    return value

def _session(item):
    try:
        day = date.fromisoformat(item['date'])
        exercise = item['exercise']
        sets = item['sets']
        reps = item['reps']
        weight = item['weight']
    except (KeyError, TypeError, ValueError):
        raise ValueError('invalid session')
    if not isinstance(exercise, str) or not exercise or isinstance(sets, bool) or (not isinstance(sets, int)) or (sets <= 0):
        raise ValueError('invalid session')
    if isinstance(reps, bool) or not isinstance(reps, int) or reps <= 0:
        raise ValueError('invalid session')
    if isinstance(weight, bool) or not isinstance(weight, (int, float)) or weight < 0:
        raise ValueError('invalid session')
    volume = sets * reps * weight
    return ({'date': day.isoformat(), 'exercise': exercise, 'sets': sets, 'reps': reps, 'weight': weight, 'volume': volume}, day)

def create_plan(client: str, sessions: list[dict], settings: dict[str, str] | None=None) -> dict:
    groups = {}
    for item in sessions:
        normalized, day = _session(item)
        monday = day - timedelta(days=day.weekday())
        groups.setdefault(monday.isoformat(), []).append(normalized)
    weeks = []
    for week in sorted(groups):
        entries = sorted(groups[week], key=lambda x: (x['date'], x['exercise']))
        weeks.append({'week': week, 'sessions': entries, 'total_volume': sum((x['volume'] for x in entries))})
    core = {'client': client, 'weeks': weeks}
    raw = json.dumps(core, sort_keys=True, separators=(',', ':')).encode()
    signature = hmac.new(_key(settings).encode(), raw, hashlib.sha256).hexdigest()
    return {'client': client, 'weeks': weeks, 'signature': signature}

def render_plan(plan: dict) -> str:
    lines = []
    for week in plan['weeks']:
        lines.append(f"WEEK {week['week']} TOTAL {week['total_volume']}")
        for item in week['sessions']:
            lines.append(f"  {item['date']} {item['exercise']} {item['sets']}x{item['reps']} @ {item['weight']} = {item['volume']}")
    return '\n'.join(lines) + ('\n' if lines else '')

