def write_expense_report(base_dir: str, relative_name: str, month: str, expenses: list[dict[str, object]]) -> str:
    if not isinstance(month, str) or not re.fullmatch('\\d{4}-\\d{2}', month):
        raise ValueError('invalid month')
    try:
