        if not isinstance(employee, str) or not employee or (not isinstance(category, str)) or (not category):
            raise ValueError('invalid expense')
        try:
            day = datetime.strptime(expense['date'], '%Y-%m-%d')
            amount = Decimal(str(expense['amount']))
        except (TypeError, ValueError, InvalidOperation):
            raise ValueError('invalid expense')
        if not amount.is_finite() or amount < 0:
            raise ValueError('invalid expense')
        if day.year == month_date.year and day.month == month_date.month:
            groups[employee, category][0] += amount
            groups[employee, category][1] += 1
    rows = sorted(groups.items(), key=lambda x: (-x[1][0], x[0][0], x[0][1]))
    os.makedirs(os.path.dirname(target), exist_ok=True)
    with open(target, 'w', encoding='utf-8', newline='') as handle:
