        writer.writerow(['employee', 'category', 'total', 'entries'])
        for (employee, category), (total, count) in rows:
            value = total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
            writer.writerow([employee, category, format(value, '.2f'), count])
    return target

