def verify_and_summarize(payload: str, signature: str, key: bytes, page: int=1, page_size: int=2) -> list[dict]:
    if not isinstance(signature, str) or len(signature) != 64:
        raise ValueError('invalid signature format')
    try:
        provided = bytes.fromhex(signature)
    except ValueError:
        raise ValueError('invalid signature format')
    expected = hmac.new(key, payload.encode('utf-8'), hashlib.sha256).digest()
    if not hmac.compare_digest(expected, provided):
        raise PermissionError('signature mismatch')
    if isinstance(page, bool) or isinstance(page_size, bool) or page < 1 or (page_size < 1):
        raise ValueError('invalid pagination')
    try:
        data = json.loads(payload)
    except (TypeError, json.JSONDecodeError):
        raise ValueError('invalid JSON')
    if not isinstance(data, list):
        raise ValueError('top level must be a list')
    groups = {}
    for item in data:
        if not isinstance(item, dict):
            raise ValueError('invalid event')
        required = ('lot', 'facility', 'quantity', 'timestamp', 'status')
        if any((k not in item for k in required)):
            raise ValueError('invalid event')
        lot, facility, quantity, timestamp, status = (item[k] for k in required)
        if not all((isinstance(x, str) for x in (lot, facility, timestamp, status))):
            raise ValueError('invalid event')
        try:
            parsed = datetime.fromisoformat(timestamp.replace('Z', '+00:00'))
        except ValueError:
            raise ValueError('invalid timestamp')
        if not isinstance(quantity, (int, float)) or isinstance(quantity, bool) or (not math.isfinite(quantity)) or (quantity < 0):
            raise ValueError('invalid quantity')
        if status != 'released':
            continue
        if lot not in groups:
            groups[lot] = {'lot': lot, 'quantity': 0, 'latest': timestamp, '_time': parsed, 'facilities': set()}
        group = groups[lot]
        group['quantity'] += quantity
        group['facilities'].add(facility)
        if parsed > group['_time']:
            group['latest'], group['_time'] = (timestamp, parsed)
    result = []
    for group in groups.values():
        result.append({'lot': group['lot'], 'quantity': round(group['quantity'], 2), 'latest': group['latest'], 'facilities': sorted(group['facilities']), '_time': group['_time']})
    result.sort(key=lambda x: (-x['_time'].timestamp(), x['lot']))
    for item in result:
        del item['_time']
    start = (page - 1) * page_size
    return result[start:start + page_size]

