    requester = {'id': 'u1', 'tenant_id': 't1', 'roles': []}

    def alert(i, mark, jurisdiction, score, when):
        return {'id': i, 'tenant_id': 't1', 'owner_id': 'u1', 'mark': mark, 'jurisdiction': jurisdiction, 'status': 'new', 'risk_score': score, 'created_at': when, 'message': i}
