        alerts.append({'id': str(i), 'tenant_id': 't1', 'owner_id': 'u1', 'mark': mark, 'jurisdiction': 'US', 'status': 'new', 'risk_score': i, 'created_at': f'2024-01-0{i + 1}T00:00:00Z', 'message': mark})
    assert [x['mark'] for x in build_watch_digest(requester, alerts, 2, 2)['items']] == ['C', 'B']
