from datetime import datetime

def build_watch_digest(requester: dict, alerts: list[dict], page: int=1, page_size: int=20) -> dict:
    if not isinstance(requester, dict) or not isinstance(alerts, list):
        raise ValueError('invalid arguments')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    required = {'id', 'tenant_id', 'owner_id', 'mark', 'jurisdiction', 'status', 'risk_score', 'created_at', 'message'}
    groups = {}
    for alert in alerts:
        if not isinstance(alert, dict) or not required.issubset(alert):
            raise ValueError('invalid alert')
        try:
            score = float(alert['risk_score'])
            stamp = datetime.fromisoformat(str(alert['created_at']).replace('Z', '+00:00'))
        except (TypeError, ValueError):
            raise ValueError('invalid alert')
        if not 0 <= score <= 100:
            raise ValueError('invalid score')
        allowed = alert['owner_id'] == requester.get('id') or ('watch_admin' in requester.get('roles', []) and alert['tenant_id'] == requester.get('tenant_id'))
        if not allowed:
            continue
        key = (alert['mark'], alert['jurisdiction'])
        groups.setdefault(key, []).append((alert, score, stamp))
    output = []
    for (mark, jurisdiction), values in groups.items():
        values.sort(key=lambda x: (-x[1], -x[2].timestamp(), str(x[0]['id'])))
        latest = max((x[2] for x in values))
        output.append({'mark': mark, 'jurisdiction': jurisdiction, 'count': len(values), 'max_risk_score': round(max((x[1] for x in values)), 2), 'latest_created_at': max((x[0]['created_at'] for x in values if x[2] == latest)), 'alerts': [{'id': x[0]['id'], 'status': x[0]['status'], 'risk_score': x[1], 'created_at': x[0]['created_at'], 'message': x[0]['message']} for x in values]})
    output.sort(key=lambda x: (-x['max_risk_score'], -datetime.fromisoformat(x['latest_created_at'].replace('Z', '+00:00')).timestamp(), x['mark'], x['jurisdiction']))
    start = (page - 1) * page_size
    return {'page': page, 'page_size': page_size, 'total': len(output), 'items': output[start:start + page_size]}

