from lxml import etree

def parse_risk_register(xml_text: str, min_score: float=0.0, page: int=1, page_size: int=50) -> list[dict]:
    if min_score < 0 or page <= 0 or page_size <= 0:
        raise ValueError('invalid pagination or score')
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode(), parser=parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'risk_register':
        raise ValueError('invalid root')
    seen = set()
    risks = []
    required = ('id', 'category', 'likelihood', 'impact', 'status')
    for node in root.findall('risk'):
        if any((name not in node.attrib for name in required)):
            raise ValueError('missing attribute')
        rid = node.attrib['id']
        if rid in seen:
            raise ValueError('duplicate id')
        seen.add(rid)
        title_node = node.find('title')
        owner_node = node.find('owner')
        if title_node is None or owner_node is None:
            raise ValueError('missing child')
        try:
            likelihood = int(node.attrib['likelihood'])
            impact = int(node.attrib['impact'])
        except Exception as exc:
            raise ValueError('invalid number') from exc
        if not 1 <= likelihood <= 5 or not 1 <= impact <= 5:
            raise ValueError('number out of range')
        score = likelihood * impact
        if score >= min_score:
            risks.append({'id': rid, 'category': node.attrib['category'], 'title': (title_node.text or '').strip(), 'owner': (owner_node.text or '').strip(), 'status': node.attrib['status'], 'score': score})
    risks.sort(key=lambda item: (-item['score'], item['id']))
    start = (page - 1) * page_size
    return risks[start:start + page_size]

