from solution import build_visit_schedule

def test_filters_sorts_and_normalizes_output():
    visits = [{'visit_id': 'v2', 'patient_id': 'p2', 'clinician': 'Dr B', 'start': '2025-04-12T09:00:00Z', 'duration_minutes': 30, 'status': 'confirmed', 'fee': 80.0, 'extra': 'ignored'}, {'visit_id': 'v1', 'patient_id': 'p1', 'clinician': 'Dr A', 'start': '2025-04-12T09:00:00+00:00', 'duration_minutes': 45, 'status': 'confirmed', 'fee': 99.999}, {'visit_id': 'v3', 'patient_id': 'p3', 'clinician': 'Dr A', 'start': '2025-04-12T10:00:00Z', 'duration_minutes': 20, 'status': 'cancelled', 'fee': 40}, {'visit_id': 'v4', 'patient_id': 'p4', 'clinician': 'Dr C', 'start': '2025-04-13T09:00:00Z', 'duration_minutes': 30, 'status': 'confirmed', 'fee': 50}]
    result = build_visit_schedule(visits, {'api_token': 'abc'}, '2025-04-12')
    assert result['headers'] == {'Authorization': 'Bearer abc'}
    assert result['total'] == 2
    assert result['total_fee'] == 180.0
    assert result['by_clinician'] == {'Dr A': 1, 'Dr B': 1}
    assert result['visits'] == [{'visit_id': 'v1', 'patient_id': 'p1', 'clinician': 'Dr A', 'start': '2025-04-12T09:00:00+00:00', 'duration_minutes': 45, 'fee': 100.0}, {'visit_id': 'v2', 'patient_id': 'p2', 'clinician': 'Dr B', 'start': '2025-04-12T09:00:00Z', 'duration_minutes': 30, 'fee': 80.0}]

def test_ties_use_visit_id_and_pagination_is_one_based():
    visits = [{'visit_id': 'z', 'patient_id': 'p', 'clinician': 'C', 'start': '2025-01-01T08:00:00', 'duration_minutes': 1, 'status': 'confirmed', 'fee': 1}, {'visit_id': 'a', 'patient_id': 'p', 'clinician': 'C', 'start': '2025-01-01T08:00:00Z', 'duration_minutes': 1, 'status': 'confirmed', 'fee': 2}, {'visit_id': 'm', 'patient_id': 'p', 'clinician': 'D', 'start': '2025-01-01T09:00:00Z', 'duration_minutes': 1, 'status': 'confirmed', 'fee': 3}]
