import csv
import datetime
import json
import math
import os
import tempfile

def parse_telemetry(text: str) -> list[dict]:
    try:
        rows = list(csv.reader(text.splitlines()))
    except csv.Error as exc:
        raise ValueError('invalid csv') from exc
    header = ['timestamp', 'engine', 'egt_c', 'fuel_flow_kg_s', 'vibration_mm_s']
    if not rows or rows[0] != header:
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if len(row) != 5:
            raise ValueError('invalid row')
        try:
            stamp = row[0]
            if not stamp.endswith('Z'):
                raise ValueError
            when = datetime.datetime.fromisoformat(stamp[:-1]).replace(tzinfo=datetime.timezone.utc)
            if when.microsecond and len(stamp) != 27 or (not when.microsecond and len(stamp) != 20):
                raise ValueError
            engine = row[1].strip()
            egt, flow, vibration = (float(x) for x in row[2:])
        except (TypeError, ValueError, OverflowError) as exc:
            raise ValueError('invalid row') from exc
        if not engine or not all((math.isfinite(x) for x in (egt, flow, vibration))) or egt < -80 or (flow < 0) or (vibration < 0):
            raise ValueError('invalid row')
        result.append({'timestamp': when, 'engine': engine, 'egt_c': egt, 'fuel_flow_kg_s': flow, 'vibration_mm_s': vibration})
    return result

def aggregate_windows(records: list[dict], window_seconds: int) -> list[dict]:
    if isinstance(window_seconds, bool) or not isinstance(window_seconds, int) or window_seconds <= 0:
        raise ValueError('invalid window')
    groups = {}
    for record in records:
        if any((key not in record for key in ('timestamp', 'engine', 'egt_c', 'fuel_flow_kg_s', 'vibration_mm_s'))):
            raise ValueError('invalid record')
        stamp = record['timestamp'].timestamp()
        start = datetime.datetime.fromtimestamp(stamp - stamp % window_seconds, datetime.timezone.utc)
        key = (record['engine'], start)
        groups.setdefault(key, []).append(record)
    output = []
    for (engine, start), values in sorted(groups.items(), key=lambda item: (item[0][0], item[0][1])):
        output.append({'engine': engine, 'window_start': start.strftime('%Y-%m-%dT%H:%M:%SZ'), 'samples': len(values), 'avg_egt_c': round(sum((x['egt_c'] for x in values)) / len(values), 2), 'peak_vibration_mm_s': round(max((x['vibration_mm_s'] for x in values)), 2), 'fuel_total_kg': round(sum((x['fuel_flow_kg_s'] for x in values)), 2)})
    return output

def write_report(records: list[dict], destination: str, window_seconds: int=60) -> None:
    payload = json.dumps(aggregate_windows(records, window_seconds), indent=2) + '\n'
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=directory, prefix='.telemetry-')
    try:
        with os.fdopen(fd, 'w', encoding='utf-8') as handle:
            handle.write(payload)
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise

