import hmac
import json
import math
import re

def verify_and_summarize(message: bytes, signing_key: bytes) -> dict:
    if not isinstance(message, bytes) or not isinstance(signing_key, bytes):
        raise ValueError('invalid arguments')
    try:
        head, body = message.split(b'\n\n', 1)
        if b'\n' in head or not head.startswith(b'X-Baggage-Signature: '):
            raise ValueError('invalid framing')
        supplied = head[len(b'X-Baggage-Signature: '):]
        if len(supplied) != 64 or not re.fullmatch(b'[0-9a-fA-F]{64}', supplied):
            raise ValueError('invalid signature')
        expected = hmac.new(signing_key, body, hashlib.sha256).hexdigest().encode()
        if not hmac.compare_digest(supplied.lower(), expected):
            raise ValueError('invalid signature')
        data = json.loads(body.decode('utf-8'))
        if not isinstance(data, dict) or not isinstance(data.get('events'), list):
            raise ValueError('invalid document')
        latest = {}
        for pos, item in enumerate(data['events']):
            if not isinstance(item, dict):
                raise ValueError('invalid event')
            bag = item.get('bag_id')
            airport = item.get('airport')
            status = item.get('status')
            stamp = item.get('timestamp')
            if not isinstance(bag, str) or not re.fullmatch('[A-Z0-9-]{3,12}', bag):
                raise ValueError('invalid bag')
            if not isinstance(airport, str) or not re.fullmatch('[A-Z]{3}', airport):
                raise ValueError('invalid airport')
            if status not in {'CHECKED_IN', 'IN_TRANSIT', 'DELAYED', 'CLAIMED', 'LOST'}:
                raise ValueError('invalid status')
            if not isinstance(stamp, str) or not re.fullmatch('\\d{4}-\\d\\d-\\d\\dT\\d\\d:\\d\\d:\\d\\d(?:\\.\\d{1,6})?Z', stamp):
                raise ValueError('invalid timestamp')
            dt = datetime.datetime.fromisoformat(stamp[:-1] + '+00:00')
            weight = item.get('weight_kg')
            if weight is not None and (isinstance(weight, bool) or not isinstance(weight, (int, float)) or (not math.isfinite(weight)) or (weight < 0)):
                raise ValueError('invalid weight')
            old = latest.get(bag)
            if old is None or (dt, pos) >= (old[0], old[1]):
                latest[bag] = (dt, pos, {'bag_id': bag, 'airport': airport, 'status': status, 'timestamp': stamp, 'weight_kg': weight})
        bags = [latest[k][2] for k in sorted(latest)]
        total = round(sum((x['weight_kg'] for x in bags if x['weight_kg'] is not None)), 2)
        return {'bags': bags, 'total_weight_kg': total, 'delayed_count': sum((x['status'] == 'DELAYED' for x in bags))}
    except (UnicodeDecodeError, json.JSONDecodeError, KeyError, TypeError, ValueError) as exc:
        if str(exc) in {'invalid signature', 'invalid framing', 'invalid document', 'invalid event', 'invalid bag', 'invalid airport', 'invalid status', 'invalid timestamp', 'invalid weight', 'invalid arguments'}:
            raise
        raise ValueError('invalid message')

