import hashlib
import hmac
import json
import os
import re

def _minute(value):
    if not isinstance(value, str) or not re.fullmatch('(?:[01]\\d|2[0-3]):[0-5]\\d|24:00', value):
        raise ValueError('invalid time')
    hour, minute = map(int, value.split(':'))
    if hour == 24 and minute != 0:
        raise ValueError('invalid time')
    return hour * 60 + minute

def parse_contact_tree(text: str) -> dict:
    try:
        raw = json.loads(text)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid contact tree') from exc
    if not isinstance(raw, dict):
        raise ValueError('contact tree must be an object')
    result = {}
    required = {'name', 'channel', 'level', 'priority', 'hours'}
    for team, contacts in raw.items():
        if not isinstance(team, str) or not isinstance(contacts, list):
            raise ValueError('invalid team')
        seen = set()
        output = []
        for contact in contacts:
            if not isinstance(contact, dict) or not required.issubset(contact):
                raise ValueError('invalid contact')
            if any((not isinstance(contact[k], str) or not contact[k] for k in ('name', 'channel', 'hours'))):
                raise ValueError('invalid contact text')
            if not isinstance(contact['level'], int) or isinstance(contact['level'], bool) or contact['level'] < 0:
                raise ValueError('invalid level')
            if not isinstance(contact['priority'], int) or isinstance(contact['priority'], bool) or contact['priority'] < 0:
                raise ValueError('invalid priority')
            parts = contact['hours'].split('-')
            if len(parts) != 2:
                raise ValueError('invalid hours')
            _minute(parts[0])
            _minute(parts[1])
            if contact['name'] in seen:
                raise ValueError('duplicate contact')
            seen.add(contact['name'])
            output.append({k: contact[k] for k in ('name', 'channel', 'level', 'priority', 'hours')})
