from pathlib import Path


def test_counts_exact_status_lines():
    with tempfile.TemporaryDirectory() as directory:
        path = Path(directory) / "preorders.txt"
        path.write_text("pending\nconfirmed\npending\ncancelled\nconfirmed\n", encoding="utf-8")
        assert count_preorders_by_status(str(path), "pending") == 2
        assert count_preorders_by_status(str(path), "confirmed") == 2
        assert count_preorders_by_status(str(path), "cancelled") == 1


def test_matching_is_case_sensitive_and_exact():
    with tempfile.TemporaryDirectory() as directory:
        path = Path(directory) / "statuses"
        path.write_text("pending\nPending\npending-review\n pending\npending \n", encoding="utf-8")
        assert count_preorders_by_status(str(path), "pending") == 1
        assert count_preorders_by_status(str(path), "Pending") == 1
        assert count_preorders_by_status(str(path), "pending-review") == 1


def test_empty_file_and_missing_status():
    with tempfile.TemporaryDirectory() as directory:
        path = Path(directory) / "empty"
        path.write_text("", encoding="utf-8")
        assert count_preorders_by_status(str(path), "pending") == 0


def test_file_without_final_newline():
    with tempfile.TemporaryDirectory() as directory:
        path = Path(directory) / "no-final-newline"
        path.write_text("confirmed\npending\nconfirmed", encoding="utf-8")
        assert count_preorders_by_status(str(path), "confirmed") == 2
