from decimal import Decimal, ROUND_HALF_UP

def create_credential(password: str) -> str:
    if not isinstance(password, str) or not password:
        raise ValueError('password must be a non-empty string')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return salt.hex() + ':' + digest.hex()

def verify_credential(record: str, password: str) -> bool:
    if not isinstance(record, str) or not isinstance(password, str):
        return False
    try:
        salt_text, digest_text = record.split(':', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    if len(salt) != 16 or len(expected) != 32:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return actual == expected

def summarize_declarations(declarations: list[dict], min_value: float=0.0, offset: int=0, limit: int | None=None) -> list[dict]:
    if not isinstance(declarations, list):
        raise ValueError('declarations must be a list')
    if isinstance(min_value, bool) or not isinstance(min_value, (int, float)) or min_value < 0:
        raise ValueError('invalid min_value')
    if isinstance(offset, bool) or not isinstance(offset, int) or offset < 0:
        raise ValueError('invalid offset')
    if limit is not None and (isinstance(limit, bool) or not isinstance(limit, int) or limit < 0):
        raise ValueError('invalid limit')
    groups = {}
    for item in declarations:
        if not isinstance(item, dict) or set(item) != {'country', 'value', 'duty_rate'}:
            raise ValueError('invalid declaration')
        country, value, rate = (item['country'], item['value'], item['duty_rate'])
        if not isinstance(country, str) or not country or isinstance(value, bool) or (not isinstance(value, (int, float))) or (value < 0) or isinstance(rate, bool) or (not isinstance(rate, (int, float))) or (not 0 <= rate <= 100):
            raise ValueError('invalid declaration')
        if value < min_value:
            continue
        if country not in groups:
            groups[country] = [Decimal('0'), Decimal('0')]
        groups[country][0] += Decimal(str(value))
        groups[country][1] += Decimal(str(value)) * Decimal(str(rate)) / Decimal('100')
    rows = [{'country': c, 'total_value': float(v[0].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)), 'total_duty': float(v[1].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))} for c, v in groups.items()]
    rows.sort(key=lambda x: (-x['total_duty'], x['country']))
    return rows[offset:] if limit is None else rows[offset:offset + limit]

