def create_account(artist_id: str, api_secret: str) -> dict:
    if not isinstance(artist_id, str) or not isinstance(api_secret, str):
        raise TypeError()
    if not artist_id or not api_secret:
        raise ValueError()
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', api_secret.encode(), salt, 100000)
    return {'artist': artist_id, 'salt': salt.hex(), 'secret': digest.hex()}

def verify_secret(account: dict, candidate: str) -> bool:
    if not isinstance(account, dict) or not isinstance(candidate, str):
        return False
    try:
        salt = bytes.fromhex(account['salt'])
        expected = bytes.fromhex(account['secret'])
        actual = hashlib.pbkdf2_hmac('sha256', candidate.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError):
        return False

def calculate_royalties(account: dict, candidate: str, events: list[dict], rates: dict[str, int]) -> dict:
    if not verify_secret(account, candidate):
        raise PermissionError()
    if not isinstance(events, list) or not isinstance(rates, dict):
        raise TypeError()
