from lxml import etree

def get_tile_urls(xml_text: str, zoom: int) -> list[str]:
    if type(zoom) is not int or zoom < 0 or zoom > 22:
        raise ValueError('invalid zoom')
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml_text.encode(), parser=parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'map':
        raise ValueError('invalid root')
    result = []
    for layer in root.findall('layer'):
        try:
            template = layer.attrib['template']
            low = int(layer.attrib['min_zoom'])
            high = int(layer.attrib['max_zoom'])
        except (KeyError, TypeError, ValueError) as exc:
            raise ValueError('invalid layer') from exc
        if not all((part in template for part in ('{z}', '{x}', '{y}'))):
            raise ValueError('invalid template')
        if low <= zoom <= high:
            for tile in layer.findall('tile'):
                try:
                    x = int(tile.attrib['x'])
                    y = int(tile.attrib['y'])
                except (KeyError, TypeError, ValueError) as exc:
                    raise ValueError('invalid tile') from exc
                if x < 0 or y < 0:
                    raise ValueError('invalid tile')
                result.append(template.format(z=zoom, x=x, y=y))
    return result

