    base = Path(base_dir).resolve()
    if not base.is_dir():
        raise NotADirectoryError(base_dir)
    if not isinstance(relative_name, str) or not relative_name:
        raise ValueError('relative_name must not be empty')
    destination = (base / relative_name).resolve()
    try:
        destination.relative_to(base)
    except ValueError:
        raise ValueError('relative_name must refer to a file below base_dir')
    if destination == base:
        raise ValueError('relative_name must refer to a file')
    destination.parent.mkdir(parents=True, exist_ok=True)
    with destination.open('w', encoding='utf-8', newline='') as handle:
        writer = csv.writer(handle)
        writer.writerow(['student_id', 'date', 'status'])
        writer.writerows(records)
    return str(destination)

