def process_expenses(records: list[dict], config: dict, page: int=1, page_size: int=10) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('page must be positive')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    try:
        endpoint = config['endpoint']
        token = config['api_token']
    except (KeyError, TypeError):
        raise ValueError('endpoint and api token are required')
    grouped = {}
    for record in records:
        if not isinstance(record, dict) or not isinstance(record.get('employee'), str) or (not record['employee']) or (not isinstance(record.get('status'), str)):
            raise ValueError('invalid record')
        amount = record.get('amount')
        if isinstance(amount, bool) or not isinstance(amount, (int, float)) or (not math.isfinite(amount)) or (amount < 0):
            raise ValueError('invalid amount')
