            grouped.setdefault(record['employee'], [Decimal('0'), 0])
            grouped[record['employee']][0] += Decimal(str(amount))
            grouped[record['employee']][1] += 1
    entries = [{'employee': name, 'total': float(total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)), 'count': count} for name, (total, count) in grouped.items()]
    entries.sort(key=lambda item: (-item['total'], item['employee']))
