import math
import subprocess

def generate_recommendation_features(input_path: str, limit: int) -> list[dict]:
    if isinstance(limit, bool) or not isinstance(limit, int) or limit < 0:
        raise ValueError('limit must be a non-negative integer')
    result = subprocess.run(['sort', '-t', '\t', '-k2,2', '-k1,1', '--', input_path], check=True, capture_output=True, text=True)
    groups = {}
    for line in result.stdout.splitlines():
        if not line.strip():
            continue
        fields = line.split('\t')
        if len(fields) != 3:
            raise ValueError('invalid record')
        user, item, raw_score = fields
        if not user or not item:
            raise ValueError('invalid record')
        try:
            score = float(raw_score)
        except ValueError as exc:
            raise ValueError('invalid score') from exc
        if not math.isfinite(score) or score < 0:
            raise ValueError('invalid score')
        if item not in groups:
            groups[item] = [0, 0.0, score]
        groups[item][0] += 1
        groups[item][1] += score
        groups[item][2] = max(groups[item][2], score)
    output = []
    for item, (count, total, maximum) in groups.items():
        output.append({'item': item, 'count': count, 'average': round(total / count, 3), 'maximum': round(maximum, 3)})
    output.sort(key=lambda row: (-row['average'], -row['count'], row['item']))
    return output[:limit]

