def maintenance_report(paths: list[str], page: int=1, page_size: int=10) -> dict:
    if page < 1 or page_size < 1:
        raise ValueError('pagination')
    records = []
    for path in paths:
        completed = subprocess.run(['cat', path], check=True, capture_output=True, text=True)
        for raw in completed.stdout.splitlines():
