                    raise ValueError
                if '.' in cost_text:
                    whole, fraction = cost_text.split('.', 1)
                    if len(fraction) > 2 or not fraction:
                        raise ValueError
                else:
                    whole = cost_text
                if not whole.isdigit() or ('.' in cost_text and (not cost_text.replace('.', '').isdigit())):
                    raise ValueError
                cents = int(whole) * 100 + int((cost_text.split('.', 1)[1] if '.' in cost_text else '').ljust(2, '0'))
            except (ValueError, TypeError):
                raise ValueError('record')
            records.append((vehicle, miles, cents))
    grouped = {}
    for vehicle, miles, cents in records:
        item = grouped.setdefault(vehicle, [0, 0, 0])
        item[0] += 1
        item[1] += miles
        item[2] += cents
    ordered = sorted(grouped.items(), key=lambda pair: (-pair[1][2], pair[0]))
    start = (page - 1) * page_size
