from lxml import etree

def parse_expense_report(xml_text: str) -> dict:
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode(), parser)
    except (etree.XMLSyntaxError, ValueError) as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'expense_report':
        raise ValueError('invalid root')
    employee = root.find('employee')
    currency = root.find('currency')
    items_node = root.find('items')
    if employee is None or currency is None or items_node is None:
        raise ValueError('missing field')
    employee_text = (employee.text or '').strip()
    currency_text = (currency.text or '').strip()
    if not employee_text or not currency_text:
        raise ValueError('empty field')
    if any((child.tag != 'item' for child in root if child.tag != 'employee' and child.tag != 'currency' and (child.tag != 'items'))):
        raise ValueError('unexpected element')
    result = []
    total = 0.0
    for item in items_node:
        if item.tag != 'item':
            raise ValueError('unexpected item')
        description = item.find('description')
        amount = item.find('amount')
        if description is None or amount is None:
            raise ValueError('missing item field')
        description_text = (description.text or '').strip()
        if not description_text:
            raise ValueError('empty description')
        try:
            value = float((amount.text or '').strip())
        except ValueError as exc:
            raise ValueError('invalid amount') from exc
        if value < 0:
            raise ValueError('negative amount')
        result.append({'description': description_text, 'amount': value})
        total += value
    return {'employee': employee_text, 'currency': currency_text, 'total': total, 'items': result}

