from datetime import datetime

def build_subject_access_report(requester: dict, target_subject_id: str, records: list[dict], page: int, page_size: int) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('page must be positive')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('page_size must be positive')
    required = {'id', 'subject_id', 'tenant_id', 'category', 'created_at', 'data'}
    for record in records:
        if not isinstance(record, dict) or not required.issubset(record):
            raise ValueError('malformed record')
        try:
            datetime.fromisoformat(record['created_at'].replace('Z', '+00:00'))
        except (AttributeError, TypeError, ValueError):
            raise ValueError('malformed timestamp')
    same_tenant = any((r['subject_id'] == target_subject_id and r['tenant_id'] == requester.get('tenant_id') for r in records))
    owner = requester.get('id') == target_subject_id
    staff = 'privacy_officer' in requester.get('roles', []) and same_tenant
    if not owner and (not staff):
        raise PermissionError('report access denied')
    matching = [r for r in records if r['subject_id'] == target_subject_id]
    matching.sort(key=lambda r: (-datetime.fromisoformat(r['created_at'].replace('Z', '+00:00')).timestamp(), r['id']))
    counts = {}
    for r in matching:
        counts[r['category']] = counts.get(r['category'], 0) + 1
    counts = {k: counts[k] for k in sorted(counts)}
    start = (page - 1) * page_size
    items = [{'id': r['id'], 'category': r['category'], 'created_at': r['created_at'], 'data': r['data']} for r in matching[start:start + page_size]]
    return {'total': len(matching), 'page': page, 'page_size': page_size, 'category_counts': counts, 'items': items}

