_STATUSES = ('planned', 'in_progress', 'done', 'blocked')

def _split_line(line):
    fields = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape')
    fields.append(''.join(current))
    return fields

def parse_changes(text: str) -> list[dict]:
    result = []
    seen = set()
    for number, raw in enumerate(text.splitlines(), 1):
        if not raw.strip() or raw.lstrip().startswith('#'):
            continue
        fields = _split_line(raw)
        if len(fields) != 5:
            raise ValueError('bad field count')
        ident, owner, status, priority_text, hours_text = fields
        if not ident or not owner or ident in seen or (status not in _STATUSES):
            raise ValueError('invalid record')
        try:
            priority = int(priority_text)
            hours = float(hours_text)
        except ValueError as exc:
            raise ValueError('invalid number') from exc
        if not 1 <= priority <= 5 or not math.isfinite(hours) or hours < 0:
            raise ValueError('invalid value')
        seen.add(ident)
        result.append({'id': ident, 'owner': owner, 'status': status, 'priority': priority, 'hours': hours})
    if not result:
        raise ValueError('no records')
    return result

def summarize_changes(records: list[dict]) -> list[dict]:
    groups = {}
    for record in records:
        try:
            owner = record['owner']
            status = record['status']
            priority = record['priority']
            hours = record['hours']
        except KeyError as exc:
            raise ValueError('missing field') from exc
        if not isinstance(owner, str) or not owner or status not in _STATUSES:
            raise ValueError('invalid record')
        if not isinstance(priority, int) or isinstance(priority, bool) or (not 1 <= priority <= 5):
            raise ValueError('invalid priority')
        if not isinstance(hours, (int, float)) or isinstance(hours, bool) or (not math.isfinite(hours)) or (hours < 0):
            raise ValueError('invalid hours')
        key = (owner, status)
        item = groups.setdefault(key, [0, 0.0, 0])
        item[0] += 1
        item[1] += hours
        item[2] += priority
    result = []
    for (owner, status), (count, hours, priorities) in groups.items():
        result.append({'owner': owner, 'status': status, 'count': count, 'total_hours': round(hours, 2), 'average_priority': round(priorities / count, 2)})
    result.sort(key=lambda x: (x['owner'].casefold(), _STATUSES.index(x['status'])))
