        if not isinstance(item, dict):
            raise ValueError('invalid match')
        fields = ('id', 'game', 'start', 'team_a', 'team_b', 'status', 'score_a', 'score_b')
        if any((field not in item for field in fields)):
            raise ValueError('invalid match')
