            raise ValueError('invalid match')
        if not isinstance(item['score_a'], int) or item['score_a'] < 0 or (not isinstance(item['score_b'], int)) or (item['score_b'] < 0):
            raise ValueError('invalid match')
        if item['status'] == 'scheduled':
            selected.append(item)
