import subprocess
from datetime import date, timedelta

def load_progress(path: str, learner: str) -> list[dict]:
    if not learner:
        raise ValueError('learner must not be empty')
    result = subprocess.run(['cat', path], capture_output=True, text=True, check=True)
    records = []
    for line in result.stdout.splitlines():
        if not line:
            continue
        fields = line.split('\t')
        if len(fields) != 5:
            raise ValueError('invalid record')
        day, who, item, score, seconds = fields
        try:
            parsed_day = date.fromisoformat(day)
            score_number = int(score)
            seconds_number = int(seconds)
        except (ValueError, TypeError):
            raise ValueError('invalid record')
        if not 0 <= score_number <= 100 or seconds_number < 0:
            raise ValueError('invalid record')
        if who == learner:
            records.append({'date': parsed_day.isoformat(), 'learner': who, 'item': item, 'score': score_number, 'seconds': seconds_number})
    return records

def summarize_progress(records: list[dict], window: int=3) -> dict:
    if window < 1:
        raise ValueError('window must be positive')
    if not records:
        return {'sessions': 0, 'average_score': 0.0, 'best_item': None, 'streak': 0, 'recent': [], 'items': []}
    groups = {}
    for record in records:
        group = groups.setdefault(record['item'], {'scores': [], 'seconds': 0})
        group['scores'].append(record['score'])
        group['seconds'] += record['seconds']
    items = []
    for item, group in groups.items():
        average = round(sum(group['scores']) / len(group['scores']), 2)
        items.append({'item': item, 'sessions': len(group['scores']), 'average_score': average, 'seconds': group['seconds']})
    items.sort(key=lambda x: (-x['average_score'], -x['seconds'], x['item']))
    days = sorted({date.fromisoformat(record['date']) for record in records})
    streak = current = 0
    previous = None
    for day in days:
        current = current + 1 if previous is not None and day == previous + timedelta(days=1) else 1
        streak = max(streak, current)
        previous = day
    chosen = sorted(enumerate(records), key=lambda pair: (pair[1]['date'], pair[0]))[-window:]
    recent = [{'date': record['date'], 'item': record['item'], 'score': record['score']} for _, record in chosen]
    return {'sessions': len(records), 'average_score': round(sum((r['score'] for r in records)) / len(records), 2), 'best_item': items[0]['item'], 'streak': streak, 'recent': recent, 'items': items}

