def write_kitchen_tickets(orders: list[dict], base_dir: str) -> dict[str, int]:
    if not isinstance(orders, list):
        raise ValueError('orders must be a list')
    grouped = {}
    for order in orders:
        if not isinstance(order, dict) or any((key not in order for key in ('id', 'station', 'item', 'quantity', 'priority'))):
            raise ValueError('invalid order')
        order_id = order['id']
        station = order['station']
        item = order['item']
        quantity = order['quantity']
        priority = order['priority']
        if not isinstance(order_id, str) or not order_id or (not isinstance(station, str)) or (not station) or (not isinstance(item, str)) or (not item):
            raise ValueError('invalid order')
        if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity <= 0:
            raise ValueError('invalid quantity')
        if isinstance(priority, bool) or not isinstance(priority, int) or (not 0 <= priority <= 9):
            raise ValueError('invalid priority')
        grouped.setdefault(station, []).append(order)
    root = Path(base_dir).resolve()
    result = {}
    for station in sorted(grouped):
        target = (root / (station + '.ticket')).resolve()
        try:
            target.relative_to(root)
        except ValueError:
            raise ValueError('invalid station')
        target.parent.mkdir(parents=True, exist_ok=True)
        entries = sorted(grouped[station], key=lambda order: (-order['priority'], order['id']))
        target.write_text(''.join((f"{order['id']}|{order['item']}|{order['quantity']}|{order['priority']}\n" for order in entries)), encoding='utf-8')
        result[station] = len(entries)
    return result

