import csv
import datetime
import io
import os
import tempfile
HEADER = ['shipment_id', 'date', 'status', 'quantity', 'destination']
STATUSES = {'planned', 'in_transit', 'delivered', 'cancelled'}

def parse_tracking(text: str) -> list[dict]:
    if not text:
        raise ValueError('empty input')
    try:
        rows = list(csv.reader(io.StringIO(text)))
    except Exception as exc:
        raise ValueError('invalid csv') from exc
    if not rows or rows[0] != HEADER:
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if not row or all((x == '' for x in row)):
            raise ValueError('blank row')
        if len(row) != 5:
            raise ValueError('wrong field count')
        shipment_id, date, status, quantity, destination = row
        if not shipment_id or not destination or status not in STATUSES:
            raise ValueError('invalid field')
        try:
            datetime.date.fromisoformat(date)
            number = int(quantity)
        except Exception as exc:
            raise ValueError('invalid value') from exc
        if number <= 0 or str(number) != quantity:
            raise ValueError('invalid quantity')
        result.append({'shipment_id': shipment_id, 'date': date, 'status': status, 'quantity': number, 'destination': destination})
    return result

def build_report(text: str, as_of: str) -> list[dict]:
    try:
        datetime.date.fromisoformat(as_of)
    except Exception as exc:
        raise ValueError('invalid cutoff') from exc
    latest = {}
    for index, event in enumerate(parse_tracking(text)):
        if event['date'] <= as_of:
            old = latest.get(event['shipment_id'])
            if old is None or (event['date'], index) >= (old[0], old[1]):
                latest[event['shipment_id']] = (event['date'], index, event)
    groups = {}
    for _, _, event in latest.values():
        key = (event['destination'], event['status'])
        item = groups.setdefault(key, {'destination': event['destination'], 'status': event['status'], 'shipments': 0, 'quantity': 0, 'last_update': event['date']})
        item['shipments'] += 1
        item['quantity'] += event['quantity']
        item['last_update'] = max(item['last_update'], event['date'])
    return [groups[key] for key in sorted(groups)]

def export_report(text: str, as_of: str, output_path: str) -> int:
    report = build_report(text, as_of)
    parent = os.path.dirname(os.path.abspath(output_path))
    handle = tempfile.NamedTemporaryFile(mode='w', newline='', encoding='utf-8', dir=parent, delete=False)
    temporary = handle.name
    try:
        with handle:
            writer = csv.writer(handle)
            writer.writerow(['destination', 'status', 'shipments', 'quantity', 'last_update'])
            for row in report:
                writer.writerow([row['destination'], row['status'], row['shipments'], row['quantity'], row['last_update']])
        os.replace(temporary, output_path)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return len(report)

