import csv
import io
import json
from pathlib import Path

def parse_ticket_log(text: str) -> list[dict]:
    if text == '':
        return []
    try:
        rows = list(csv.reader(io.StringIO(text, newline='')))
    except csv.Error as exc:
        raise ValueError('invalid CSV') from exc
    if not rows or rows[0] != ['time', 'event', 'section', 'seat', 'price', 'status']:
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if len(row) != 6:
            raise ValueError('invalid row')
        try:
            time = int(row[0])
            price = int(row[4])
        except ValueError as exc:
            raise ValueError('invalid number') from exc
        if time < 0 or price < 0 or any((not row[i] for i in (1, 2, 3))) or (row[5] not in ('SOLD', 'REFUNDED')):
            raise ValueError('invalid value')
        result.append({'time': time, 'event': row[1], 'section': row[2], 'seat': row[3], 'price': price, 'status': row[5]})
    return result

def summarize_tickets(records: list[dict]) -> dict:
    events = {}
    sold = refunded = revenue = 0
    for r in records:
        if set(r) != {'time', 'event', 'section', 'seat', 'price', 'status'} or not isinstance(r['event'], str) or (not isinstance(r['price'], int)) or (r['price'] < 0) or (r['status'] not in ('SOLD', 'REFUNDED')):
            raise ValueError('invalid record')
        name = r['event']
        if name not in events:
            events[name] = {'sold': 0, 'refunded': 0, 'revenue': 0}
        sign = 1 if r['status'] == 'SOLD' else -1
        key = 'sold' if sign == 1 else 'refunded'
        events[name][key] += 1
        events[name]['revenue'] += sign * r['price']
        revenue += sign * r['price']
        sold += sign == 1
        refunded += sign == -1
    return {'tickets': len(records), 'sold': sold, 'refunded': refunded, 'revenue': revenue, 'events': {k: events[k] for k in sorted(events)}}

def write_summary(base_dir: str, relative_name: str, summary: dict) -> str:
    if not relative_name:
        raise ValueError('empty name')
    base = Path(base_dir).resolve()
    target = (base / relative_name).resolve()
    try:
        target.relative_to(base)
    except ValueError as exc:
        raise ValueError('invalid path') from exc
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(json.dumps(summary, indent=2, sort_keys=True) + '\n', encoding='utf-8')
    return str(target)

