        if time < 0 or price < 0 or any((not row[i] for i in (1, 2, 3))) or (row[5] not in ('SOLD', 'REFUNDED')):
            raise ValueError('invalid value')
        result.append({'time': time, 'event': row[1], 'section': row[2], 'seat': row[3], 'price': price, 'status': row[5]})
    return result

def summarize_tickets(records: list[dict]) -> dict:
    events = {}
    sold = refunded = revenue = 0
    for r in records:
        if set(r) != {'time', 'event', 'section', 'seat', 'price', 'status'} or not isinstance(r['event'], str) or (not isinstance(r['price'], int)) or (r['price'] < 0) or (r['status'] not in ('SOLD', 'REFUNDED')):
