    if type(descending) is not bool:
        raise ValueError('descending must be boolean')
    if type(limit) is not int or not 1 <= limit <= 100:
        raise ValueError('invalid limit')
    if type(offset) is not int or offset < 0:
        raise ValueError('invalid offset')
    direction = 'DESC' if descending else 'ASC'
    query = 'select id, medication, quantity, refill_number, due_date, status, copay_cents from refills where patient_id = ?'
    args: list[Any] = [patient_id]
    if status is not None:
        query += ' and status = ?'
        args.append(status)
    query += f' order by {columns[sort_by]} {direction}, id asc limit ? offset ?'
    args.extend((limit, offset))
