import subprocess

def parse_usage(text: str) -> list[tuple[str, str, int]]:
    rows = [line for line in text.splitlines() if line.strip()]
    if not rows or rows[0].strip() != 'account,service,units':
        raise ValueError('invalid header')
    result = []
    for line in rows[1:]:
        fields = line.split(',')
        if len(fields) != 3:
            raise ValueError('invalid row')
        account, service, raw = (x.strip() for x in fields)
        if not account or not service:
            raise ValueError('empty name')
        try:
            units = int(raw, 10)
        except ValueError:
            raise ValueError('invalid units')
        if units < 0:
            raise ValueError('negative units')
        result.append((account, service, units))
    return result

def allocate_costs(text: str, rates: dict[str, int]) -> dict[str, int]:
    for value in rates.values():
        if type(value) is not int or value < 0:
            raise ValueError('invalid rate')
    totals = {}
    for account, service, units in parse_usage(text):
        if service not in rates:
            raise ValueError('unknown service')
        totals[account] = totals.get(account, 0) + units * rates[service]
    return {key: totals[key] for key in sorted(totals)}

def rank_accounts(costs: dict[str, int], minimum: int=0) -> list[tuple[str, int]]:
    if type(minimum) is not int or minimum < 0:
        raise ValueError('invalid minimum')
    for value in costs.values():
        if type(value) is not int or value < 0:
            raise ValueError('invalid cost')
    return sorted(((name, value) for name, value in costs.items() if value >= minimum), key=lambda item: (-item[1], item[0]))

