import ast
import operator

def rank_bins(bins: list[dict], formula: str) -> list[str]:
    tree = ast.parse(formula, mode='eval').body
    names = {'temperature', 'moisture', 'age_days'}
    funcs = {'min': min, 'max': max}
    ops = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}

    def visit(node, values):
        if isinstance(node, ast.Constant) and type(node.value) in (int, float):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in names:
                raise NameError(node.id)
            return values[node.id]
        if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub):
            value = visit(node.operand, values)
            return value if isinstance(node.op, ast.UAdd) else -value
        if isinstance(node, ast.BinOp) and type(node.op) in ops:
            return ops[type(node.op)](visit(node.left, values), visit(node.right, values))
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in funcs) and (not node.keywords):
            return funcs[node.func.id](*(visit(arg, values) for arg in node.args))
        raise ValueError('unsupported expression')
    scored = [(visit(tree, {'temperature': b['temperature'], 'moisture': b['moisture'], 'age_days': b['age_days']}), b['id']) for b in bins]
    scored.sort(key=lambda pair: (-pair[0], pair[1]))
    return [item[1] for item in scored]

