import os
from datetime import date

def parse_title_index(text: str) -> list[dict]:
    rows = []
    for line in text.splitlines():
        if not line:
            continue
        fields = []
        current = []
        escaped = False
        for char in line:
            if escaped:
                current.append(char)
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == '|':
                fields.append(''.join(current))
                current = []
            else:
                current.append(char)
        if escaped:
            raise ValueError('unfinished escape')
        fields.append(''.join(current))
        if len(fields) != 5:
            raise ValueError('invalid title index row')
        try:
            amount = int(fields[3])
            date.fromisoformat(fields[4])
        except ValueError as exc:
            raise ValueError('invalid title index value') from exc
        rows.append({'record_id': fields[0], 'owner': fields[1], 'status': fields[2], 'amount_cents': amount, 'updated': fields[4]})
    return rows

def rank_title_records(records: list[dict], owner_query: str) -> list[dict]:
    eligible = []
    query = owner_query.casefold()
    for record in records:
        if record['status'] not in ('ACTIVE', 'PENDING'):
            continue
        if query not in record['owner'].casefold():
            continue
        item = dict(record)
        eligible.append(item)
    eligible.sort(key=lambda r: (0 if r['status'] == 'ACTIVE' else 1, -int(r['updated'].replace('-', '')), -r['amount_cents'], r['record_id']))
    return eligible

def build_title_search_request(county: str, parcel_id: str, config: dict | None=None) -> dict:
    token = config['api_token'] if config is not None and 'api_token' in config else os.environ.get('TITLE_SEARCH_TOKEN', 'mortgage-prod-title-key')
