import math
import os
from pathlib import Path
import zipfile

def extract_and_rank_remediation_sites(archive_path: str, output_dir: str, min_ratio: float=0.0) -> list[dict]:
    if not math.isfinite(min_ratio) or min_ratio < 0:
        raise ValueError('invalid minimum ratio')
    base = Path(output_dir).resolve()
    base.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(archive_path) as archive:
        for member in archive.infolist():
            target = (base / member.filename).resolve()
            try:
                target.relative_to(base)
            except ValueError:
                raise ValueError('archive entry outside output directory')
            archive.extract(member, base)
    csv_path = base / 'data' / 'samples.csv'
    if not csv_path.is_file():
        raise ValueError('missing samples CSV')
    groups = {}
    with csv_path.open(newline='', encoding='utf-8') as handle:
        reader = csv.DictReader(handle)
        required = ['site', 'contaminant', 'concentration', 'threshold']
        if reader.fieldnames != required:
            raise ValueError('invalid CSV header')
        for row in reader:
            if any((value is None for value in row.values())) or not row['site']:
                raise ValueError('invalid sample row')
            try:
                concentration = float(row['concentration'])
                threshold = float(row['threshold'])
            except (TypeError, ValueError):
                raise ValueError('invalid measurement')
            if not math.isfinite(concentration) or not math.isfinite(threshold) or threshold <= 0 or (concentration < 0):
                raise ValueError('invalid measurement')
            ratio = concentration / threshold
            if ratio < min_ratio:
                continue
            group = groups.setdefault(row['site'], {'samples': 0, 'max_ratio': 0.0, 'total_excess': 0.0})
            group['samples'] += 1
            group['max_ratio'] = max(group['max_ratio'], ratio)
            group['total_excess'] += max(0.0, concentration - threshold)
    result = [{'site': site, 'samples': data['samples'], 'max_ratio': round(data['max_ratio'], 2), 'total_excess': round(data['total_excess'], 2)} for site, data in groups.items()]
    return sorted(result, key=lambda item: (-item['max_ratio'], item['site']))

