def plan_maintenance_route(requester: dict, jobs: list[dict], service_date: str, page: int=1, page_size: int=20) -> dict:
    requester_id = requester['id']
    tenant_id = requester['tenant_id']
    roles = requester['roles']
    if not isinstance(page, int) or isinstance(page, bool) or page <= 0:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size <= 0:
        raise ValueError('invalid page size')
    try:
        date.fromisoformat(service_date)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    selected = []
    for item in jobs:
        for key in ('id', 'tenant_id', 'owner_id', 'service_date', 'status', 'priority', 'start_window', 'duration_minutes', 'zone', 'address'):
            item[key]
        if not isinstance(item['priority'], int) or isinstance(item['priority'], bool) or (not isinstance(item['duration_minutes'], int)) or isinstance(item['duration_minutes'], bool):
            raise ValueError('invalid numeric field')
        allowed = item['tenant_id'] == tenant_id and (item['owner_id'] == requester_id or 'manager' in roles)
        if allowed and item['service_date'] == service_date and (item['status'] == 'scheduled'):
            selected.append(item)
    selected.sort(key=lambda x: (-x['priority'], x['start_window'], x['id']))
    total = len(selected)
    zones = {}
    for item in selected:
        zones[item['zone']] = zones.get(item['zone'], 0) + item['duration_minutes']
    start = (page - 1) * page_size
    output_jobs = []
    for item in selected[start:start + page_size]:
        output_jobs.append({'id': item['id'], 'zone': item['zone'], 'priority': item['priority'], 'start_window': item['start_window'], 'duration_minutes': item['duration_minutes'], 'address': item['address']})
    return {'service_date': service_date, 'page': page, 'page_size': page_size, 'total': total, 'total_pages': (total + page_size - 1) // page_size, 'total_minutes': sum((x['duration_minutes'] for x in selected)), 'zones': {key: zones[key] for key in sorted(zones)}, 'jobs': output_jobs}

