from pathlib import Path

def make_file(directory, name, content):
    path = Path(directory) / name
    path.write_text(content, encoding='utf-8')
    return str(path)

def test_read_inventory_preserves_file_and_row_order():
    with tempfile.TemporaryDirectory() as directory:
        first = make_file(directory, 'first.csv', 'sku,warehouse,quantity,expires\n A1 , East , 4 ,2025-01-10\nA2,West,0,2025-01-12\n')
        second = make_file(directory, 'second.csv', 'sku,warehouse,quantity,expires\nB1,East,9,2025-02-01\n')
        assert read_inventory([first, second]) == [{'sku': 'A1', 'warehouse': 'East', 'quantity': 4, 'expires': datetime.date(2025, 1, 10)}, {'sku': 'A2', 'warehouse': 'West', 'quantity': 0, 'expires': datetime.date(2025, 1, 12)}, {'sku': 'B1', 'warehouse': 'East', 'quantity': 9, 'expires': datetime.date(2025, 2, 1)}]

def test_empty_input_and_header_only_files():
    with tempfile.TemporaryDirectory() as directory:
        header = make_file(directory, 'header.csv', 'sku,warehouse,quantity,expires\n')
        assert read_inventory([]) == []
        assert read_inventory([header]) == []

def test_report_includes_window_end_and_excludes_later_items():
    with tempfile.TemporaryDirectory() as directory:
        path = make_file(directory, 'stock.csv', 'sku,warehouse,quantity,expires\nend,A,4,2025-01-11\nlate,A,8,2025-01-12\nnow,B,1,2025-01-01\n')
        result = expiration_report([path], '2025-01-01', 10)
        assert result['expired'] == []
        assert result['expiring'] == [{'sku': 'now', 'days': 0, 'quantity': 1}, {'sku': 'end', 'days': 10, 'quantity': 4}]
        assert result['warehouse_totals'] == {'A': 4, 'B': 1}

def test_duplicate_skus_across_files_are_rejected():
    with tempfile.TemporaryDirectory() as directory:
        a = make_file(directory, 'a.csv', 'sku,warehouse,quantity,expires\nx,A,1,2025-01-01\n')
        b = make_file(directory, 'b.csv', 'sku,warehouse,quantity,expires\nx,B,2,2025-01-02\n')
