        raise ValueError('invalid ticket id')
    try:
        datetime.date.fromisoformat(day)
    except Exception:
        raise ValueError('invalid date')
    if not isinstance(rides, int) or isinstance(rides, bool) or (not 1 <= rides <= 20):
        raise ValueError('invalid rides')
    if not isinstance(issued, int) or isinstance(issued, bool) or issued < 0:
        raise ValueError('invalid issue time')
    payload = f'{ticket_id}|{day}|{rides}|{issued}'
    sig = hmac.new(secret, payload.encode(), hashlib.sha256).hexdigest()
    return payload + '|' + sig

def verify_ticket(token: str, secret: bytes, now: int) -> dict:
    if not isinstance(token, str):
        raise ValueError('invalid token')
    parts = token.split('|')
    if len(parts) != 5:
        raise ValueError('invalid token')
    ticket_id, day, rides_s, issued_s, sig = parts
    if not _ID.fullmatch(ticket_id) or not re.fullmatch('[0-9a-f]{64}', sig):
        raise ValueError('invalid token')
    try:
        datetime.date.fromisoformat(day)
        rides = int(rides_s)
        issued = int(issued_s)
    except Exception:
        raise ValueError('invalid token')
    if str(rides) != rides_s or str(issued) != issued_s or (not 1 <= rides <= 20) or (issued < 0):
        raise ValueError('invalid token')
    payload = '|'.join(parts[:4]).encode()
    expected = hmac.new(secret, payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(sig, expected) or issued > now or now - issued > 172800:
        raise ValueError('invalid token')
    return {'ticket_id': ticket_id, 'day': day, 'rides': rides, 'issued': issued}

def summarize_scans(records: list[tuple[str, str, int]], secret: bytes, now: int) -> dict:
    lifts = {}
    tickets = {}
    seen = set()
    allowances = {}
    for record in records:
        if not isinstance(record, tuple) or len(record) != 3:
            raise ValueError('invalid record')
        token, lift, scan_time = record
        info = verify_ticket(token, secret, now)
        if not isinstance(lift, str) or not _LIFT.fullmatch(lift):
            raise ValueError('invalid lift')
        if not isinstance(scan_time, int) or isinstance(scan_time, bool):
            raise ValueError('invalid scan time')
        if scan_time < info['issued'] or scan_time > now or scan_time - info['issued'] > 172800:
            raise ValueError('invalid scan time')
        key = (info['ticket_id'], lift, scan_time)
        if key in seen:
            raise ValueError('duplicate scan')
        seen.add(key)
        count = tickets.get(info['ticket_id'], 0) + 1
        if count > info['rides']:
            raise ValueError('ride limit')
        tickets[info['ticket_id']] = count
        lifts[lift] = lifts.get(lift, 0) + 1
    return {'accepted': len(records), 'by_lift': dict(sorted(lifts.items())), 'by_ticket': dict(sorted(tickets.items()))}

