import datetime
import xml.etree.ElementTree as ET

def parse_inspection_report(xml_text: str, page: int=1, page_size: int=10) -> list[dict]:
    if not isinstance(xml_text, str) or not isinstance(page, int) or isinstance(page, bool) or (not isinstance(page_size, int)) or isinstance(page_size, bool):
        raise ValueError('invalid arguments')
    if page < 1 or page_size < 1:
        raise ValueError('invalid pagination')
    try:
        root = ET.fromstring(xml_text)
    except (ET.ParseError, TypeError):
        raise ValueError('invalid xml')
    if root.tag != 'inspections':
        raise ValueError('invalid root')
    records = []
    ids = set()
    for node in root:
        if node.tag != 'inspection':
            raise ValueError('invalid inspection')
        values = {key: node.get(key) for key in ('id', 'site', 'inspector', 'date')}
        if any((value is None or value == '' for value in values.values())):
            raise ValueError('missing attribute')
        if values['id'] in ids:
            raise ValueError('duplicate id')
        try:
            parsed_date = datetime.date.fromisoformat(values['date'])
        except ValueError:
            raise ValueError('invalid date')
        if parsed_date.isoformat() != values['date']:
            raise ValueError('invalid date')
        hazards = []
        for hazards_node in node:
            if hazards_node.tag != 'hazards':
                raise ValueError('invalid inspection content')
            for hazard in hazards_node:
                if hazard.tag != 'hazard' or hazard.get('severity') is None:
                    raise ValueError('invalid hazard')
                try:
                    severity = int(hazard.get('severity'))
                except (TypeError, ValueError):
                    raise ValueError('invalid severity')
                if severity < 1 or severity > 5:
                    raise ValueError('invalid severity')
                hazards.append(severity)
        ids.add(values['id'])
        records.append({'id': values['id'], 'site': values['site'], 'inspector': values['inspector'], 'date': values['date'], 'hazard_count': len(hazards), 'critical_count': sum((value >= 4 for value in hazards)), 'score': sum(hazards)})
    records.sort(key=lambda item: (-datetime.date.fromisoformat(item['date']).toordinal(), item['id']))
    start = (page - 1) * page_size
    return records[start:start + page_size]

