import csv
import io

def parse_load_manifest(text: str) -> list[dict]:
    lines = [line for line in text.splitlines() if line.strip()]
    header = ['load_id', 'tenant_id', 'owner_id', 'origin', 'destination', 'weight', 'latest_delivery']
    if not lines:
        raise ValueError('missing header')
    try:
        rows = list(csv.reader(lines, delimiter='|', escapechar='\\'))
    except csv.Error as exc:
        raise ValueError('invalid manifest') from exc
    if not rows or rows[0] != header:
        raise ValueError('invalid header')
    result = []
    seen = set()
    for row in rows[1:]:
        if len(row) != 7 or any((x == '' for x in row)):
            raise ValueError('invalid row')
        if row[0] in seen:
            raise ValueError('duplicate load')
        try:
            weight = int(row[5], 10)
            latest = int(row[6], 10)
        except ValueError as exc:
            raise ValueError('invalid number') from exc
        if weight <= 0 or latest < 0:
            raise ValueError('invalid number')
        seen.add(row[0])
        result.append(dict(zip(header[:5], row[:5]), weight=weight, latest_delivery=latest))
    return result

def select_carrier(load: dict, bids: list[dict]) -> dict:
    required = {'carrier_id', 'tenant_id', 'capacity', 'eta', 'rate', 'reliability', 'available'}
    eligible = []
    for bid in bids:
        if set(bid) != required or not isinstance(bid['carrier_id'], str) or (not isinstance(bid['tenant_id'], str)):
            raise ValueError('malformed bid')
        if not isinstance(bid['capacity'], int) or isinstance(bid['capacity'], bool) or bid['capacity'] <= 0 or (not isinstance(bid['eta'], int)) or isinstance(bid['eta'], bool) or (bid['eta'] < 0) or (not isinstance(bid['rate'], (int, float))) or isinstance(bid['rate'], bool) or (bid['rate'] < 0) or (not isinstance(bid['reliability'], (int, float))) or isinstance(bid['reliability'], bool) or (not 0 <= bid['reliability'] <= 100) or (not isinstance(bid['available'], bool)):
            raise ValueError('malformed bid')
        if bid['tenant_id'] == load['tenant_id'] and bid['available'] and (bid['capacity'] >= load['weight']) and (bid['eta'] <= load['latest_delivery']):
            eligible.append(bid)
    if not eligible:
        raise ValueError('no eligible carrier')
    return dict(min(eligible, key=lambda b: (b['rate'], -b['reliability'], b['eta'], b['carrier_id'])))

def tender_load(requester: dict, load: dict, bids: list[dict], audit_log: list[dict]) -> dict:
    if load.get('status') != 'open':
        raise ValueError('load is not open')
    if requester.get('tenant_id') != load.get('tenant_id'):
        raise ValueError('tenant mismatch')
    if requester.get('user_id') != load.get('owner_id') and (not {'dispatcher', 'admin'} & set(requester.get('roles', []))):
        raise PermissionError('not permitted')
    chosen = select_carrier(load, bids)
    if chosen['tenant_id'] != load['tenant_id']:
        raise ValueError('tenant mismatch')
    load['status'] = 'awarded'
    load['carrier_id'] = chosen['carrier_id']
    load['rate'] = chosen['rate']
    audit_log.append({'load_id': load['load_id'], 'user_id': requester['user_id'], 'carrier_id': chosen['carrier_id'], 'rate': chosen['rate']})
    return {'load_id': load['load_id'], 'carrier_id': chosen['carrier_id'], 'rate': chosen['rate'], 'tenant_id': load['tenant_id']}

