def summarize_signed_crop_plan(payload: str, signature: str, shared_key: str, minimum_yield: float) -> list[dict]:
    if not isinstance(minimum_yield, (int, float)) or isinstance(minimum_yield, bool) or (not math.isfinite(minimum_yield)) or (minimum_yield < 0):
        raise ValueError('invalid minimum yield')
    expected = hmac.new(shared_key.encode(), payload.encode(), hashlib.sha256).hexdigest()
