    for plot in document['plots']:
        if not isinstance(plot, dict):
            raise ValueError('invalid plot')
        crop = plot.get('crop')
        area = plot.get('area_ha')
        rate = plot.get('expected_yield_t_ha')
        day = plot.get('harvest_day')
        if not isinstance(crop, str) or not crop or (not isinstance(area, (int, float))) or isinstance(area, bool) or (not math.isfinite(area)) or (area <= 0) or (not isinstance(rate, (int, float))) or isinstance(rate, bool) or (not math.isfinite(rate)) or (rate <= 0) or (not isinstance(day, int)) or isinstance(day, bool) or (not 1 <= day <= 365):
            raise ValueError('invalid plot')
        if rate >= minimum_yield:
            item = groups.setdefault(crop, [0.0, 0.0, 0])
