from solution import rank_players

import os
import tempfile


def write_records(text):
    directory = tempfile.TemporaryDirectory()
    path = os.path.join(directory.name, "scores.txt")
    with open(path, "w", encoding="utf-8") as handle:
        handle.write(text)
    return directory, path


def test_empty_file_returns_empty_list():
    directory, path = write_records("")
    try:
        assert rank_players(path, 5) == []
    finally:
        directory.cleanup()


def test_ignores_blank_lines_and_orders_scores_and_names():
    directory, path = write_records("Zed,80\n Alice,95\n\nBob,95\nCara,70\n")
    try:
        assert rank_players(path, 10) == [("Alice", 95), ("Bob", 95), ("Zed", 80), ("Cara", 70)]
    finally:
        directory.cleanup()


def test_duplicate_players_keep_highest_score():
    directory, path = write_records("Nova,40\nNova,91\nByte,90\nNova,75\n")
    try:
        assert rank_players(path, 10) == [("Nova", 91), ("Byte", 90)]
    finally:
        directory.cleanup()


def test_pagination_applies_offset_then_limit():
    directory, path = write_records("A,100\nB,90\nC,80\nD,70\n")
    try:
        assert rank_players(path, 2, 1) == [("B", 90), ("C", 80)]
        assert rank_players(path, 2, 10) == []
    finally:
        directory.cleanup()


def test_whitespace_and_boundary_scores_are_handled():
    directory, path = write_records(" Low , 0 \nHigh,10000\nMiddle,1\n")
    try:
        assert rank_players(path, 3) == [("High", 10000), ("Middle", 1), ("Low", 0)]
    finally:
        directory.cleanup()


def test_invalid_pagination_raises_value_error():
    directory, path = write_records("A,5\n")
    try:
        try:
            rank_players(path, 0)
            assert False
        except ValueError:
            pass
        try:
            rank_players(path, 1, -1)
            assert False
        except ValueError:
            pass
    finally:
        directory.cleanup()


def test_invalid_records_raise_value_error():
    cases = ["A,1,2\n", ",5\n", "A,10001\n", "A,nope\n"]
    for content in cases:
        directory, path = write_records(content)
        try:
            try:
                rank_players(path, 5)
                assert False
            except ValueError:
                pass
        finally:
            directory.cleanup()

