import base64
import hashlib
import hmac
import os
from datetime import date

def _day(value):
    try:
        parsed = date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if not isinstance(value, str) or len(value) != 10 or value != parsed.isoformat():
        raise ValueError('invalid date')
    return parsed

def make_rights_record(show: str, territories: str, start: str, end: str, credential: str) -> dict:
    if not isinstance(show, str) or not show.strip() or (not isinstance(credential, str)) or (not credential):
        raise ValueError('invalid text')
    first = _day(start)
    last = _day(end)
    if first >= last or not isinstance(territories, str):
        raise ValueError('invalid interval')
    found = []
    for part in territories.split(','):
        pieces = part.split(':')
        if len(pieces) != 2:
            raise ValueError('invalid territory')
        code, mode = (x.strip() for x in pieces)
        if len(code) != 2 or not code.isascii() or (not code.isupper()) or (not code.isalpha()):
            raise ValueError('invalid territory')
        if mode not in ('exclusive', 'nonexclusive') or code in {x[0] for x in found}:
            raise ValueError('invalid territory')
        found.append((code, mode))
    if not found:
        raise ValueError('invalid territory')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', credential.encode(), salt, 100000)
    stored = base64.b64encode(salt).decode() + '$' + base64.b64encode(digest).decode()
    return {'show': show.strip(), 'start': first.isoformat(), 'end': last.isoformat(), 'rights': [{'territory': c, 'mode': m} for c, m in sorted(found)], 'credential_hash': stored}

def verify_rights_record(record: dict, credential: str) -> bool:
    if not isinstance(credential, str) or not isinstance(record, dict):
        return False
    try:
        salt_text, digest_text = record['credential_hash'].split('$', 1)
        salt = base64.b64decode(salt_text, validate=True)
        expected = base64.b64decode(digest_text, validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', credential.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (KeyError, ValueError, TypeError):
        return False

def summarize_catalog(records: list[dict], day: str) -> list[dict]:
    target = _day(day)
    grouped = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        start, end = (_day(record.get('start')), _day(record.get('end')))
        if start >= end:
            raise ValueError('invalid interval')
        if not start <= target < end:
            continue
        show = record.get('show')
        if not isinstance(show, str):
            raise ValueError('invalid show')
        for right in record.get('rights', []):
            if not isinstance(right, dict):
                raise ValueError('invalid right')
            code, mode = (right.get('territory'), right.get('mode'))
            if not isinstance(code, str) or len(code) != 2 or (not code.isascii()) or (not code.isupper()) or (not code.isalpha()) or (mode not in ('exclusive', 'nonexclusive')):
                raise ValueError('invalid right')
            grouped.setdefault(code, {}).setdefault(show, False)
            grouped[code][show] = grouped[code][show] or mode == 'exclusive'
    result = []
    for code in sorted(grouped):
        values = grouped[code]
        ordered = sorted(values, key=lambda x: (x.lower(), x))
        result.append({'territory': code, 'titles': ordered, 'exclusive_titles': [x for x in ordered if values[x]]})
    return result

