import io
import subprocess

def plan_routes(schedule_path: str, capacity: int=40, max_wait: int=15) -> list[dict]:
    if not isinstance(capacity, int) or isinstance(capacity, bool) or capacity <= 0:
        raise ValueError('invalid capacity')
    if not isinstance(max_wait, int) or isinstance(max_wait, bool) or max_wait < 0:
        raise ValueError('invalid max_wait')
    completed = subprocess.run(['sort', '-t,', '-k1,1', '-k2,2n', schedule_path], check=True, capture_output=True, text=True)
    groups = {}
    for row in csv.reader(io.StringIO(completed.stdout)):
        if len(row) != 5:
            raise ValueError('malformed record')
        route, order_text, stop, students_text, arrival_text = [x.strip() for x in row]
        if not route or not stop:
            raise ValueError('empty name')
        try:
            order = int(order_text)
            students = int(students_text)
            arrival = int(arrival_text)
        except ValueError:
            raise ValueError('invalid number')
        if order <= 0 or students < 0 or arrival < 0:
            raise ValueError('invalid number')
        groups.setdefault(route, []).append((order, stop, students, arrival))
    result = []
    for route in sorted(groups):
        records = groups[route]
        seen = set()
        previous = None
        stops = []
        waits = []
        total = 0
        for order, stop, students, arrival in records:
            if order in seen:
                raise ValueError('duplicate order')
            seen.add(order)
            if previous is not None:
                if arrival < previous:
                    raise ValueError('decreasing arrival')
                waits.append(arrival - previous)
            previous = arrival
            total += students
            stops.append({'stop': stop, 'order': order, 'students': students, 'arrival': arrival})
