import os
import tempfile
_KEYS = {'version', 'player', 'coins', 'inventory', 'quests', 'events'}

def _pairs(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError('duplicate key')
        result[key] = value
    return result

def parse_save(text: str) -> dict:
    try:
