    except (json.JSONDecodeError, TypeError, ValueError) as exc:
        raise ValueError('invalid save') from exc
    if not isinstance(value, dict) or set(value) != _KEYS:
        raise ValueError('invalid save')
    if not isinstance(value['version'], int) or isinstance(value['version'], bool) or value['version'] < 0:
        raise ValueError('invalid save')
    if not isinstance(value['coins'], int) or isinstance(value['coins'], bool) or value['coins'] < 0:
        raise ValueError('invalid save')
    if not isinstance(value['player'], str) or not value['player']:
        raise ValueError('invalid save')
    inventory = value['inventory']
    if not isinstance(inventory, dict):
        raise ValueError('invalid save')
    for key, count in inventory.items():
        if not isinstance(key, str) or not key or (not isinstance(count, int)) or isinstance(count, bool) or (count < 0):
            raise ValueError('invalid save')
    quests = value['quests']
    if not isinstance(quests, dict):
        raise ValueError('invalid save')
    for name, quest in quests.items():
        if not isinstance(name, str) or not name or (not isinstance(quest, dict)) or (set(quest) != {'progress', 'completed', 'updated'}):
            raise ValueError('invalid save')
        if not isinstance(quest['progress'], int) or isinstance(quest['progress'], bool) or quest['progress'] < 0 or (not isinstance(quest['completed'], bool)) or (not isinstance(quest['updated'], int)) or isinstance(quest['updated'], bool) or (quest['updated'] < 0):
            raise ValueError('invalid save')
    events = value['events']
    if not isinstance(events, list):
        raise ValueError('invalid save')
    ids = set()
    for event in events:
        if not isinstance(event, dict) or set(event) != {'id', 'time', 'kind'} or (not isinstance(event['id'], str)) or (not event['id']) or (event['id'] in ids) or (not isinstance(event['time'], int)) or isinstance(event['time'], bool) or (event['time'] < 0) or (not isinstance(event['kind'], str)):
            raise ValueError('invalid save')
        ids.add(event['id'])
    return value

def merge_saves(local: dict, remote: dict) -> dict:
    if local['player'] != remote['player']:
        raise ValueError('different players')
    quests = dict(local['quests'])
    for name, right in remote['quests'].items():
        left = quests.get(name)
        if left is None or right['updated'] > left['updated']:
            quests[name] = dict(right)
        elif right['updated'] == left['updated']:
            quests[name] = {'progress': max(left['progress'], right['progress']), 'completed': left['completed'] or right['completed'], 'updated': left['updated']}
    inventory = dict(local['inventory'])
    for name, count in remote['inventory'].items():
        inventory[name] = max(inventory.get(name, 0), count)
    events = {event['id']: event for event in local['events']}
    for event in remote['events']:
        if event['id'] not in events or event['time'] >= events[event['id']]['time']:
            events[event['id']] = event
    return {'version': max(local['version'], remote['version']), 'player': local['player'], 'coins': max(local['coins'], remote['coins']), 'inventory': inventory, 'quests': quests, 'events': sorted(events.values(), key=lambda x: (x['time'], x['id']))}

def save_game(path: str, state: dict) -> None:
    state = parse_save(json.dumps(state))
    data = json.dumps(state, ensure_ascii=False, sort_keys=True, separators=(',', ':')) + '\n'
    directory = os.path.dirname(os.path.abspath(path))
    fd, temporary = tempfile.mkstemp(dir=directory)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8') as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, path)
    except Exception:
        try:
            os.unlink(temporary)
        except OSError:
            pass
        raise

def load_game(path: str) -> dict:
    with open(path, encoding='utf-8') as handle:
        return parse_save(handle.read())

