import math
import re
import xml.etree.ElementTree as ET

def parse_translation_memory(xml_text: str, source_lang: str, target_lang: str) -> list[dict]:
    if not source_lang or not target_lang or source_lang == target_lang:
        raise ValueError('invalid languages')
    try:
        root = ET.fromstring(xml_text)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'tm':
        raise ValueError('invalid root')
    chosen = {}
    for tu in root:
        if tu.tag != 'tu':
            continue
        ident = tu.get('id')
        if not ident:
            raise ValueError('missing id')
        try:
            confidence = float(tu.attrib['confidence'])
        except Exception as exc:
            raise ValueError('invalid confidence') from exc
        if not math.isfinite(confidence) or not 0 <= confidence <= 1:
            raise ValueError('invalid confidence')
        values = {}
        for tuv in tu:
            if tuv.tag != 'tuv':
                continue
            lang = tuv.get('lang')
            if lang in values:
                raise ValueError('duplicate language')
            seg = next((x for x in tuv if x.tag == 'seg'), None)
            if seg is not None:
                values[lang] = re.sub('\\s+', ' ', ''.join(seg.itertext())).strip()
        if source_lang not in values or target_lang not in values:
            continue
        source, target = (values[source_lang], values[target_lang])
        if not source or not target:
            continue
        key = (source, target)
        old = chosen.get(key)
        if old is None or confidence > old['confidence']:
            chosen[key] = {'id': ident, 'source': source, 'target': target, 'confidence': confidence}
    return sorted(chosen.values(), key=lambda r: (-r['confidence'], r['source'].casefold(), r['target'].casefold(), r['id']))

def translation_memory_statistics(records: list[dict]) -> dict:
    if not records:
        return {'total': 0, 'average_confidence': 0.0, 'highest_confidence': 0.0, 'sources': []}
    sources = []
    seen = set()
    for record in records:
        if record['source'] not in seen:
            seen.add(record['source'])
            sources.append(record['source'])
    confidences = [record['confidence'] for record in records]
    return {'total': len(records), 'average_confidence': sum(confidences) / len(records), 'highest_confidence': max(confidences), 'sources': sources}

