import sqlite3

def list_fulfillment_orders(conn: sqlite3.Connection, status: str | None, min_total: float, sort_by: str, page: int, page_size: int) -> list[dict[str, object]]:
    statuses = {'pending', 'packed', 'shipped', 'cancelled'}
    columns = {'id': 'id', 'customer': 'customer', 'status': 'status', 'total': 'total'}
    if status is not None and status not in statuses:
        raise ValueError('invalid status')
    if not isinstance(min_total, (int, float)) or not math.isfinite(min_total) or min_total < 0:
        raise ValueError('invalid minimum')
    if sort_by not in columns:
        raise ValueError('invalid sort column')
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    clauses = ['total >= ?']
    params: list[object] = [min_total]
    if status is not None:
        clauses.append('status = ?')
        params.append(status)
    order = columns[sort_by]
    if sort_by != 'id':
        order += ', id'
    sql = 'SELECT id, customer, status, total, item_count FROM orders WHERE ' + ' AND '.join(clauses) + ' ORDER BY ' + order + ' LIMIT ? OFFSET ?'
    params.extend([page_size, (page - 1) * page_size])
    rows = conn.execute(sql, params).fetchall()
    return [{'id': row[0], 'customer': row[1], 'status': row[2], 'total': round(row[3], 2), 'item_count': row[4]} for row in rows]

