import hashlib
import hmac
import os

def _valid_pin(pin):
    return isinstance(pin, str) and 4 <= len(pin) <= 12 and pin.isascii() and pin.isdigit()

def hash_rights_pin(pin: str) -> str:
    if not isinstance(pin, str):
        raise TypeError('pin must be a string')
    if not _valid_pin(pin):
        raise ValueError('invalid pin')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return salt.hex() + ':' + digest.hex()

def verify_rights_pin(pin: str, stored: str) -> bool:
    if not _valid_pin(pin) or not isinstance(stored, str):
        return False
    try:
        salt_text, digest_text = stored.split(':', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        if len(salt) != 16 or len(expected) != 32:
            return False
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def register_rights(title: str, publisher: str, pin: str) -> dict:
    if not isinstance(title, str) or not isinstance(publisher, str):
        raise TypeError('title and publisher must be strings')
    title = title.strip()
    publisher = publisher.strip()
    if not title or not publisher:
        raise ValueError('title and publisher must not be empty')
    return {'title': title, 'publisher': publisher, 'pin_hash': hash_rights_pin(pin)}

def can_view_rights(record: dict, pin: str) -> bool:
    if not isinstance(record, dict) or not isinstance(record.get('pin_hash'), str):
        return False
    return verify_rights_pin(pin, record['pin_hash'])

