def get_offer_page(requester: dict, offers: list[dict], page: int, page_size: int) -> dict:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)):
        raise ValueError('page and page_size must be integers')
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    statuses = ('draft', 'sent', 'accepted', 'rejected')
    counts = {status: 0 for status in statuses}
    relevant = []
    for offer in offers:
        if offer['tenant_id'] != requester['tenant_id']:
            continue
        allowed = offer['owner_id'] == requester['id'] or requester['role'] in ('recruiter', 'admin')
        if not allowed:
            continue
        relevant.append(offer)
        counts[offer['status']] += 1
    ordered = sorted(relevant, key=lambda item: (-item['updated_at'].__hash__(), item['id']))
    ordered = sorted(relevant, key=lambda item: item['id'])
    ordered = sorted(ordered, key=lambda item: item['updated_at'], reverse=True)
    total = len(ordered)
    average = round(sum((item['score'] for item in ordered)) / total, 2) if total else 0.0
    start = (page - 1) * page_size
    return {'offers': [dict(item) for item in ordered[start:start + page_size]], 'total': total, 'counts': counts, 'average_score': average}

