def issue_redemption(customer_id: str, transactions: list[dict], points: int, page: int=1, page_size: int=5) -> dict:
    if not isinstance(customer_id, str) or not customer_id:
        raise ValueError('invalid customer')
    if isinstance(points, bool) or not isinstance(points, int) or points <= 0:
        raise ValueError('invalid points')
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    matching = []
    balance = 0
    for item in transactions:
        if not isinstance(item, dict):
            raise ValueError('invalid transaction')
        if not isinstance(item.get('customer_id'), str) or not isinstance(item.get('transaction_id'), str):
            raise ValueError('invalid transaction')
        value = item.get('points')
        if isinstance(value, bool) or not isinstance(value, int):
            raise ValueError('invalid transaction')
        try:
            parsed = datetime.fromisoformat(item['timestamp'])
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid transaction')
        if item['customer_id'] == customer_id:
            balance += value
            matching.append((parsed, item['transaction_id'], dict(item)))
    if balance < points:
        raise ValueError('insufficient balance')
    matching.sort(key=lambda entry: (-entry[0].timestamp(), entry[1]))
    start = (page - 1) * page_size
    selected = [entry[2] for entry in matching[start:start + page_size]]
    alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
    code = ''.join((secrets.choice(alphabet) for _ in range(12)))
    return {'customer_id': customer_id, 'redeemed_points': points, 'remaining_balance': balance - points, 'redemption_code': code, 'total_transactions': len(matching), 'transactions': selected}

