from solution import parse_orders, make_schedule, utilization
import pytest

def test_parse_orders_preserves_order_and_dependencies():
    xml = '<plan><order id="B" priority="1" due="8" family="paint" duration="3"><depends-on ref="A"/><depends-on ref="C"/></order><order id="A" priority="2" due="4" family="cut" duration="2"/><order id="C" priority="2" due="5" family="cut" duration="1"/></plan>'
    assert parse_orders(xml) == [{'id': 'B', 'priority': 1, 'due': 8, 'family': 'paint', 'duration': 3, 'depends': ['A', 'C']}, {'id': 'A', 'priority': 2, 'due': 4, 'family': 'cut', 'duration': 2, 'depends': []}, {'id': 'C', 'priority': 2, 'due': 5, 'family': 'cut', 'duration': 1, 'depends': []}]

def test_parse_rejects_bad_documents():
    bad = ['<wrong/>', '<plan><order id="x" priority="0" due="0" family="a" duration="1"/><order id="x" priority="0" due="1" family="b" duration="1"/></plan>', '<plan><order id="x" priority="0" due="0" family="a" duration="1"><depends-on ref="z"/></order></plan>', '<plan><order id="x" priority="0" due="0" family="a" duration="0"/></plan>', '<plan>unexpected<order id="x" priority="0" due="0" family="a" duration="1"/></plan>']
    for xml in bad:
        with pytest.raises(ValueError):
            parse_orders(xml)

def test_schedule_respects_priority_due_and_machine_ties():
    xml = '<plan><order id="z" priority="2" due="5" family="a" duration="2"/><order id="b" priority="2" due="3" family="a" duration="1"/><order id="a" priority="2" due="3" family="a" duration="1"/></plan>'
    result = make_schedule(xml, 2)
    assert result == [{'id': 'a', 'machine': 0, 'start': 0, 'end': 1, 'setup': 0, 'duration': 1}, {'id': 'b', 'machine': 1, 'start': 0, 'end': 1, 'setup': 0, 'duration': 1}, {'id': 'z', 'machine': 0, 'start': 1, 'end': 3, 'setup': 0, 'duration': 2}]

def test_schedule_cycle_and_machine_validation():
    cyclic = '<plan><order id="a" priority="1" due="1" family="x" duration="1"><depends-on ref="b"/></order><order id="b" priority="1" due="1" family="x" duration="1"><depends-on ref="a"/></order></plan>'
    with pytest.raises(ValueError):
        make_schedule(cyclic)
    with pytest.raises(ValueError):
        make_schedule('<plan/>', 0)

def test_utilization_aggregates_and_sorts_machines():
    schedule = [{'id': 'x', 'machine': 3, 'start': 4, 'end': 9, 'setup': 0, 'duration': 5}, {'id': 'y', 'machine': 1, 'start': 0, 'end': 2, 'setup': 0, 'duration': 2}, {'id': 'z', 'machine': 3, 'start': 10, 'end': 12, 'setup': 1, 'duration': 1}]
    assert utilization(schedule) == {1: 2, 3: 7}
    assert utilization([]) == {}

def test_utilization_rejects_invalid_entries():
    with pytest.raises(ValueError):
        utilization([{'machine': 1, 'start': 4, 'end': 2}])
    with pytest.raises(ValueError):
        utilization([{'machine': '1', 'start': 0, 'end': 1}])

