    orders = {'name': 'p.name COLLATE NOCASE ASC, p.id ASC', 'price': 'p.unit_cents ASC, p.name COLLATE NOCASE ASC, p.id ASC', 'quantity': 'ci.quantity DESC, p.name COLLATE NOCASE ASC, p.id ASC'}
