import ast
import operator

def _evaluate(text, values):
    try:
        tree = ast.parse(text, mode='eval').body

        def visit(node):
            if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
                return node.value
            if isinstance(node, ast.Name):
                if node.id not in values:
                    raise ValueError()
                return values[node.id]
            if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
                value = visit(node.operand)
                return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
            if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
                left, right = (visit(node.left), visit(node.right))
                return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
            if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
                result = visit(node.values[0])
                for item in node.values[1:]:
                    if isinstance(node.op, ast.And):
                        if not result:
                            return result
                    elif result:
                        return result
                    result = visit(item)
                return result
            if isinstance(node, ast.Compare):
                left = visit(node.left)
                for op, part in zip(node.ops, node.comparators):
                    right = visit(part)
                    fn = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}.get(type(op))
                    if fn is None or not fn(left, right):
                        return False
                    left = right
                return True
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
                return {'min': min, 'max': max, 'round': round}[node.func.id](*[visit(x) for x in node.args])
            raise ValueError()
        return visit(tree)
    except Exception as exc:
        raise ValueError() from exc

def rank_courses(courses: list[dict], rule: str, formula: str, limit: int) -> list[dict]:
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 0:
        raise ValueError()
    selected = []
    for index, course in enumerate(courses):
        try:
            values = {key: course[key] for key in ('price', 'rating', 'enrolled', 'capacity', 'duration')}
            title = course['title']
            if not isinstance(title, str):
                raise ValueError()
            decision = _evaluate(rule, values)
            if not isinstance(decision, bool):
                raise ValueError()
            if decision:
                score = _evaluate(formula, values)
                if isinstance(score, bool) or not isinstance(score, (int, float)):
                    raise ValueError()
                selected.append((score, title, index))
        except Exception as exc:
            raise ValueError() from exc
    selected.sort(key=lambda item: (-item[0], item[1], item[2]))
    return [{'title': title, 'score': score} for score, title, _ in selected[:limit]]

