from datetime import datetime, timezone
from lxml import etree

def _read(xml_text):
    if not isinstance(xml_text, str):
        raise ValueError()
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode(), parser)
    except Exception as exc:
        raise ValueError() from exc
    if root.tag != 'building' or not len(root):
        raise ValueError()
    records = []
    for elevator in root:
        if elevator.tag != 'elevator' or not elevator.get('id') or (not len(elevator)):
            raise ValueError()
        eid = elevator.get('id')
        for index, reading in enumerate(elevator):
            if reading.tag != 'reading':
                raise ValueError()
            required = ['timestamp', 'floor', 'direction', 'load']
            if any((reading.get(k) is None for k in required)) or len(reading.attrib) != 4:
                raise ValueError()
            stamp = reading.get('timestamp')
            if not stamp.endswith('Z'):
                raise ValueError()
            try:
                dt = datetime.fromisoformat(stamp[:-1] + '+00:00')
                if dt.tzinfo != timezone.utc:
                    raise ValueError()
                floor = int(reading.get('floor'))
                load = int(reading.get('load'))
            except Exception as exc:
                raise ValueError() from exc
            if floor < 0 or not 0 <= load <= 100 or reading.get('direction') not in ('up', 'down', 'idle'):
                raise ValueError()
            records.append((dt, eid, index, {'elevator_id': eid, 'timestamp': stamp, 'floor': floor, 'direction': reading.get('direction'), 'load': load}))
    if not records:
        raise ValueError()
    records.sort(key=lambda x: (x[0], x[1], x[2]))
    return [x[3] for x in records]

def parse_elevator_feed(xml_text: str) -> list[dict]:
    return _read(xml_text)

def summarize_elevators(xml_text: str, window_seconds: int=300) -> list[dict]:
    if isinstance(window_seconds, bool) or not isinstance(window_seconds, int) or window_seconds <= 0:
        raise ValueError()
    rows = _read(xml_text)
    groups = {}
    for row in rows:
        groups.setdefault(row['elevator_id'], []).append(row)
    output = []
    for eid in sorted(groups):
        items = groups[eid]
        times = [datetime.fromisoformat(x['timestamp'][:-1] + '+00:00') for x in items]
        best = 0
        for i, start in enumerate(times):
            count = sum(((t - start).total_seconds() <= window_seconds for t in times[i:]))
            best = max(best, count)
        changes = sum((items[i]['direction'] != items[i - 1]['direction'] for i in range(1, len(items))))
        output.append({'elevator_id': eid, 'readings': len(items), 'first_timestamp': items[0]['timestamp'], 'last_timestamp': items[-1]['timestamp'], 'latest_floor': items[-1]['floor'], 'average_load': round(sum((x['load'] for x in items)) / len(items), 2), 'direction_changes': changes, 'busiest_window_count': best})
    return output

