import os
import subprocess

def submission_storage(root: str, extension: str='.jpg', page: int=1, per_page: int=10) -> dict:
    if not extension or not extension.startswith('.'):
        raise ValueError('extension must begin with a dot')
    if page < 1 or per_page < 1:
        raise ValueError('invalid pagination')
    entries = []
    with os.scandir(root) as directory:
        for entry in directory:
            if entry.is_file() and entry.name.endswith(extension):
                path = os.path.join(root, entry.name)
                completed = subprocess.run(['wc', '-c', path], capture_output=True, text=True, check=True)
                size = int(completed.stdout.split()[0])
                entries.append({'name': entry.name, 'bytes': size})
    entries.sort(key=lambda item: (-item['bytes'], item['name']))
    total_items = len(entries)
    pages = (total_items + per_page - 1) // per_page
    start = (page - 1) * per_page
    return {'total_items': total_items, 'total_bytes': sum((item['bytes'] for item in entries)), 'pages': pages, 'items': entries[start:start + per_page]}

