import hashlib
import hmac
import json
import pytest


def make_payload(call=None, timestamp=1000):
    if call is None:
        call = {"id": "c1", "language": "en", "skill": "billing", "priority": 2}
    return json.dumps({"event": "call.created", "timestamp": timestamp, "call": call}, separators=(",", ":"))


def signed(payload, secret="top-secret"):
    digest = hmac.new(secret.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return "sha256=" + digest


def agents():
    return [
        {"id": "zara", "languages": ["en"], "skills": ["billing", "vip"], "available": True, "active_calls": 1, "max_calls": 3},
        {"id": "amy", "languages": ["en"], "skills": ["billing", "vip"], "available": True, "active_calls": 0, "max_calls": 3},
        {"id": "bob", "languages": ["fr"], "skills": ["billing", "vip"], "available": True, "active_calls": 0, "max_calls": 3},
    ]


def test_verify_accepts_valid_payload_and_preserves_values():
    payload = make_payload(timestamp=1200)
    result = verify_webhook(payload, signed(payload), "top-secret", 1000)
    assert result["event"] == "call.created"
    assert result["timestamp"] == 1200
    assert result["call"]["id"] == "c1"


def test_verify_rejects_bad_signature_and_bad_header():
    payload = make_payload()
    with pytest.raises(PermissionError):
        verify_webhook(payload, "sha256=" + "0" * 64, "top-secret", 1000)
    with pytest.raises(ValueError):
        verify_webhook(payload, "sha1=" + "0" * 64, "top-secret", 1000)
    with pytest.raises(ValueError):
        verify_webhook(payload, "sha256=" + "A" * 64, "top-secret", 1000)


def test_verify_checks_json_structure_and_time_window():
    payload = make_payload(timestamp=1301)
    with pytest.raises(ValueError):
        verify_webhook(payload, signed(payload), "top-secret", 1000)
    bad = json.dumps({"event": "other", "timestamp": 1000, "call": {}}, separators=(",", ":"))
    with pytest.raises(ValueError):
        verify_webhook(bad, signed(bad), "top-secret", 1000)


def test_parse_call_accepts_optional_skills_and_returns_copy():
    data = {"event": "call.created", "timestamp": 1000, "call": {"id": "x", "language": "en", "skill": "sales", "priority": 5, "skills": ["vip"]}}
    result = parse_call(data)
    assert result == {"id": "x", "language": "en", "skill": "sales", "priority": 5, "skills": ["vip"], "timestamp": 1000}
    assert result is not data["call"]


def test_parse_call_rejects_extra_fields_types_and_bad_priority():
    base = {"event": "call.created", "timestamp": 1000, "call": {"id": "x", "language": "en", "skill": "sales", "priority": 1}}
    extra = dict(base, source="x")
    with pytest.raises(ValueError):
        parse_call(extra)
    for value in [True, -1, 6, "1"]:
        item = json.loads(json.dumps(base))
        item["call"]["priority"] = value
        with pytest.raises(ValueError):
            parse_call(item)


