    result = choose_agent(call, agents())
    assert result == {"id": "amy", "active_calls": 0, "score": 2}


def test_choose_agent_filters_and_route_webhook_returns_summary():
    call = {"id": "c9", "language": "en", "skill": "billing", "priority": 1}
    payload = make_payload(call)
    result = route_webhook(payload, signed(payload), "top-secret", agents(), 1000)
    assert result == {"call_id": "c9", "agent_id": "amy", "score": 1, "active_calls": 0}
    blocked = [dict(a, available=False) for a in agents()]
    with pytest.raises(LookupError):
        choose_agent({"id": "c", "language": "en", "skill": "billing", "priority": 1, "skills": []}, blocked)

