import hashlib
import hmac
import json

def verify_webhook(payload: str, signature: str, secret: str, now: int) -> dict:
    if not isinstance(payload, str) or not isinstance(signature, str):
        raise ValueError('invalid input')
    if len(signature) != 71 or not signature.startswith('sha256='):
        raise ValueError('invalid signature')
    supplied = signature[7:]
    if any((c not in '0123456789abcdef' for c in supplied)):
        raise ValueError('invalid signature')
    expected = hmac.new(secret.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(supplied, expected):
        raise PermissionError('signature mismatch')
    try:
        data = json.loads(payload)
    except Exception as exc:
        raise ValueError('invalid json') from exc
    if not isinstance(data, dict) or set(data) != {'event', 'timestamp', 'call'}:
        raise ValueError('invalid webhook')
    if data['event'] != 'call.created' or type(data['timestamp']) is not int:
        raise ValueError('invalid webhook')
    if abs(data['timestamp'] - now) > 300:
        raise ValueError('expired webhook')
    return data

def parse_call(data: dict) -> dict:
    if not isinstance(data, dict) or set(data) != {'event', 'timestamp', 'call'}:
        raise ValueError('invalid webhook')
    if data['event'] != 'call.created' or type(data['timestamp']) is not int or (not isinstance(data['call'], dict)):
        raise ValueError('invalid call')
    c = data['call']
    allowed = {'id', 'language', 'skill', 'priority', 'skills'}
    if set(c) - allowed or not {'id', 'language', 'skill', 'priority'} <= set(c):
        raise ValueError('invalid call')
    for key in ('id', 'language', 'skill'):
        if not isinstance(c[key], str) or not c[key]:
            raise ValueError('invalid call')
    if type(c['priority']) is not int or not 0 <= c['priority'] <= 5:
        raise ValueError('invalid call')
    skills = c.get('skills', [])
    if not isinstance(skills, list) or any((not isinstance(x, str) or not x for x in skills)):
        raise ValueError('invalid call')
    return {'id': c['id'], 'language': c['language'], 'skill': c['skill'], 'priority': c['priority'], 'skills': list(skills), 'timestamp': data['timestamp']}

def choose_agent(call: dict, agents: list[dict]) -> dict:
    wanted = set(call.get('skills', [])) | {call['skill']}
    choices = []
    for agent in agents:
        if agent.get('available') is True and call['language'] in agent.get('languages', []) and agent['skill'] if False else False:
            pass
        if agent.get('available') is True and call['language'] in agent.get('languages', []) and (call['skill'] in agent.get('skills', [])) and (type(agent.get('active_calls')) is int) and (agent['active_calls'] >= 0) and (type(agent.get('max_calls')) is int) and (agent['active_calls'] < agent['max_calls']):
            score = len(wanted & set(agent['skills']))
            choices.append((score, agent['active_calls'], str(agent['id']), agent))
    if not choices:
        raise LookupError('no eligible agent')
    score, active, ident, _ = sorted(choices, key=lambda x: (-x[0], x[1], x[2]))[0]
    return {'id': ident, 'active_calls': active, 'score': score}

def route_webhook(payload: str, signature: str, secret: str, agents: list[dict], now: int) -> dict:
    data = verify_webhook(payload, signature, secret, now)
    call = parse_call(data)
    selected = choose_agent(call, agents)
    return {'call_id': call['id'], 'agent_id': selected['id'], 'score': selected['score'], 'active_calls': selected['active_calls']}

