def create_purchase_order(base_dir: str, relative_name: str, lines: list[dict], max_total: float) -> str:
    if not isinstance(relative_name, str) or not relative_name:
        raise ValueError('invalid name')
    if not isinstance(lines, list):
        raise ValueError('invalid lines')
    try:
        budget = Decimal(str(max_total))
    except (InvalidOperation, ValueError):
        raise ValueError('invalid budget')
    if budget < 0:
        raise ValueError('invalid budget')
    grouped = {}
    for item in lines:
        if not isinstance(item, dict) or set(item) != {'ingredient', 'quantity', 'unit_price'}:
            raise ValueError('invalid item')
        name = item['ingredient']
        quantity = item['quantity']
        if not isinstance(name, str) or not name.strip() or isinstance(quantity, bool) or (not isinstance(quantity, int)) or (quantity <= 0):
            raise ValueError('invalid item')
        if isinstance(item['unit_price'], bool):
            raise ValueError('invalid item')
        try:
            price = Decimal(str(item['unit_price']))
        except (InvalidOperation, ValueError):
            raise ValueError('invalid item')
        if price < 0:
            raise ValueError('invalid item')
        grouped.setdefault(name, [0, Decimal('0')])
        grouped[name][0] += quantity
        grouped[name][1] += price * quantity
    rows = []
    for name, (quantity, total) in grouped.items():
        rounded = total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        rows.append((name, quantity, rounded))
    rows.sort(key=lambda row: (-row[2], row[0]))
    overall = sum((row[2] for row in rows), Decimal('0'))
    if overall > budget:
        raise ValueError('budget exceeded')
    base = os.path.realpath(base_dir)
    target = os.path.realpath(os.path.join(base, relative_name))
    if os.path.commonpath([base, target]) != base or target == base:
        raise ValueError('invalid name')
    with open(target, 'w', newline='', encoding='utf-8') as output:
        writer = csv.writer(output)
        writer.writerow(['ingredient', 'quantity', 'total'])
        for name, quantity, total in rows:
            writer.writerow([name, quantity, f'{total:.2f}'])
        writer.writerow(['total', '', f'{overall:.2f}'])
    return target

