    result = []
    for raw in text.splitlines():
        if not raw.strip() or raw.lstrip().startswith('#'):
            continue
        fields = _split(raw)
        if len(fields) != 4:
            raise ValueError('wrong field count')
        stamp, visitor, resident, duration = fields
        try:
            parsed = datetime.strptime(stamp, '%Y-%m-%d %H:%M')
            if parsed.strftime('%Y-%m-%d %H:%M') != stamp:
                raise ValueError
            amount = int(duration)
        except ValueError:
            raise ValueError('invalid request')
        if not 8 <= parsed.hour <= 18 or (parsed.hour == 18 and parsed.minute != 0):
            raise ValueError('invalid time')
        visitor, resident = (visitor.strip(), resident.strip())
        if not visitor or not resident or amount not in (30, 60):
            raise ValueError('invalid request')
        result.append({'date': stamp[:10], 'time': stamp[11:], 'visitor': visitor, 'resident': resident, 'duration': amount})
    return sorted(result, key=lambda x: (x['date'], x['time'], x['resident'], x['visitor']))

def build_schedule(request_text: str, daily_limit: int=3) -> dict[str, list[dict]]:
    if isinstance(daily_limit, bool) or not isinstance(daily_limit, int) or daily_limit <= 0:
        raise ValueError('invalid limit')
    output = {}
    visitors = {}
    intervals = {}
    for item in parse_requests(request_text):
        date = item['date']
        start = datetime.strptime(date + ' ' + item['time'], '%Y-%m-%d %H:%M')
        end = start + timedelta(minutes=item['duration'])
        if len(output.get(date, [])) >= daily_limit or item['visitor'] in visitors.get(date, set()):
            continue
        if any((item['resident'] == r and start < e and (s < end) for r, s, e in intervals.get(date, []))):
            continue
        output.setdefault(date, []).append(dict(item))
        visitors.setdefault(date, set()).add(item['visitor'])
        intervals.setdefault(date, []).append((item['resident'], start, end))
    return output

def issue_invite(schedule: dict[str, list[dict]], date: str, visitor: str, resident: str, used: set[str] | None=None) -> str:
    if not isinstance(schedule.get(date), list):
        raise ValueError('visit not found')
    if not any((x.get('visitor') == visitor and x.get('resident') == resident for x in schedule[date])):
        raise ValueError('visit not found')
    alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
    while True:
        token = 'VIS-' + ''.join((random.choice(alphabet) for _ in range(12)))
        if used is None or token not in used:
            break
    if used is not None:
        used.add(token)
    return token

