def list_scheduled_posts(account: dict, start: str, end: str, page: int, page_size: int) -> list[dict]:
    if not isinstance(account, dict) or set(account) != {'username', 'password_hash', 'posts'}:
        raise ValueError('invalid account')
    begin = _timestamp(start)
    finish = _timestamp(end)
    if begin >= finish or type(page) is not int or type(page_size) is not int or (page < 1) or (not 1 <= page_size <= 100):
        raise ValueError('invalid range')
    items = _valid_posts(account['posts'])
    items = [p for p in items if p['status'] == 'scheduled' and begin <= _timestamp(p['run_at']) < finish]
    items.sort(key=lambda p: (_timestamp(p['run_at']), p['id']))
    offset = (page - 1) * page_size
    return [dict(p) for p in items[offset:offset + page_size]]

