import hashlib
import hmac
import os
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from datetime import date

def encode_payment_pin(pin: str) -> str:
    if not isinstance(pin, str):
        raise TypeError('pin must be a string')
    if not pin:
        raise ValueError('pin must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return salt.hex() + ':' + digest.hex()

def verify_payment_pin(stored: str, pin: str) -> bool:
    if not isinstance(stored, str) or not isinstance(pin, str):
        return False
    try:
        salt_text, digest_text = stored.split(':', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def summarize_mortgage_payments(records: list[dict], page: int=1, page_size: int=20) -> list[dict]:
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('invalid page size')
    groups = {}
    for record in records:
        try:
            loan_id = record['loan_id']
            raw_amount = record['amount']
            raw_date = record['date']
            status = record['status']
            if not isinstance(loan_id, str) or not loan_id or status not in ('posted', 'pending'):
                raise ValueError
            if not isinstance(raw_date, str) or date.fromisoformat(raw_date).isoformat() != raw_date:
                raise ValueError
            amount = Decimal(str(raw_amount))
            if amount < 0 or not amount.is_finite():
                raise ValueError
        except (KeyError, TypeError, InvalidOperation, ValueError):
            raise ValueError('invalid record')
        if status == 'posted':
            item = groups.setdefault(loan_id, [Decimal('0'), 0, raw_date])
            item[0] += amount
            item[1] += 1
            item[2] = max(item[2], raw_date)
    result = [{'loan_id': k, 'total': v[0].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP).__format__('f'), 'count': v[1], 'latest_date': v[2]} for k, v in groups.items()]
    result.sort(key=lambda x: (-Decimal(x['total']), x['loan_id']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

