from decimal import Decimal, ROUND_HALF_UP

def build_booking_report(bookings: list[dict], config: dict) -> dict:
    if not isinstance(bookings, list) or not isinstance(config, dict):
        raise ValueError('bookings and config must be valid mappings')
    key = config.get('signing_key')
    if not isinstance(key, str) or not key:
        raise ValueError('missing signing_key')
    seen = set()
    confirmed = []
    for item in bookings:
        if not isinstance(item, dict):
            raise ValueError('invalid booking')
        required = ('booking_id', 'guide', 'date', 'guests', 'price', 'status')
        if any((field not in item for field in required)):
            raise ValueError('invalid booking')
        booking_id, guide, date_text = (item['booking_id'], item['guide'], item['date'])
        guests, price, status = (item['guests'], item['price'], item['status'])
        if not isinstance(booking_id, str) or not booking_id or (not isinstance(guide, str)) or (not guide) or (booking_id in seen):
            raise ValueError('invalid booking')
        try:
            date.fromisoformat(date_text)
        except (TypeError, ValueError):
            raise ValueError('invalid booking')
        if isinstance(guests, bool) or not isinstance(guests, int) or guests <= 0 or isinstance(price, bool) or (not isinstance(price, (int, float))) or (price < 0) or (status not in ('confirmed', 'pending', 'cancelled')):
            raise ValueError('invalid booking')
        seen.add(booking_id)
        if status == 'confirmed':
            confirmed.append(item)
    groups = {}
    for item in confirmed:
        groups.setdefault(item['guide'], []).append(item)
    guides = []
    for guide in sorted(groups):
        entries = sorted(groups[guide], key=lambda x: (x['date'], x['booking_id']))
        revenue = sum((Decimal(str(x['price'])) for x in entries), Decimal('0')).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        guides.append({'guide': guide, 'bookings': [x['booking_id'] for x in entries], 'guests': sum((x['guests'] for x in entries)), 'revenue': float(revenue)})
    total = sum((Decimal(str(x['price'])) for x in confirmed), Decimal('0')).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    payload = {'guides': guides, 'total_bookings': len(confirmed), 'total_guests': sum((x['guests'] for x in confirmed)), 'total_revenue': float(total)}
    raw = json.dumps(payload, sort_keys=True, separators=(',', ':')).encode('utf-8')
    payload['signature'] = hmac.new(key.encode('utf-8'), raw, hashlib.sha256).hexdigest()
    return payload

