        if not line.strip():
            continue
        fields = [part.strip() for part in line.split('|')]
        if len(fields) != 4:
            raise ValueError(f'invalid line {number}')
        month, category, hours, rate = fields
        if not category or len(month) != 7 or month[4] != '-':
            raise ValueError(f'invalid line {number}')
        try:
            year = int(month[:4])
            month_number = int(month[5:])
            hours_number = int(hours)
            rate_number = int(rate)
        except ValueError as exc:
            raise ValueError(f'invalid line {number}') from exc
        if year < 0 or not 1 <= month_number <= 12 or hours_number < 0 or (rate_number < 0):
            raise ValueError(f'invalid line {number}')
        if not month[:4].isdigit() or not month[5:].isdigit():
            raise ValueError(f'invalid line {number}')
        rows.append({'month': month, 'category': category, 'hours': hours_number, 'rate_cents': rate_number})
    return rows

def _validated(tasks):
    if not isinstance(tasks, list):
        raise ValueError('tasks must be a list')
    required = {'month', 'category', 'hours', 'rate_cents'}
    result = []
    for task in tasks:
        if not isinstance(task, Mapping) or set(task) != required:
            raise ValueError('invalid task')
        parsed = parse_task_rows('|'.join((str(task[k]) for k in ('month', 'category', 'hours', 'rate_cents'))))[0]
        if any((not isinstance(task[k], int) or isinstance(task[k], bool) for k in ('hours', 'rate_cents'))):
            raise ValueError('invalid task')
        result.append(parsed)
    return result

def estimate_project(tasks: list[dict], config: dict | None=None) -> dict:
    rows = _validated(tasks)
    if config is not None and (not isinstance(config, dict)):
        raise ValueError('config must be a dictionary')
    key = config.get('cost_estimate_key') if config is not None and 'cost_estimate_key' in config else os.environ.get('COST_ESTIMATE_KEY')
    if not isinstance(key, str) or not key:
        raise ValueError('COST_ESTIMATE_KEY is required')
    months = {}
    categories = {}
    for row in rows:
        cost = row['hours'] * row['rate_cents']
        months[row['month']] = months.get(row['month'], 0) + cost
        item = categories.setdefault(row['category'], {'hours': 0, 'total_cents': 0})
        item['hours'] += row['hours']
        item['total_cents'] += cost
    monthly = dict(sorted(months.items()))
    ordered_categories = {k: categories[k] for k in sorted(categories)}
    payload = {'total_cents': sum(monthly.values()), 'monthly': monthly, 'categories': ordered_categories}
    raw = json.dumps(payload, sort_keys=True, separators=(',', ':')).encode('utf-8')
    return {**payload, 'signature': hmac.new(key.encode('utf-8'), raw, hashlib.sha256).hexdigest()}

