import csv
import io
import json
import math

def parse_inventory(text: str) -> list[dict]:
    lines = [line for line in text.splitlines() if line.strip()]
    if not lines:
        raise ValueError('invalid header')
    expected = ['sku', 'on_hand', 'daily_use', 'lead_days', 'pack_size', 'priority']
    rows = csv.reader(io.StringIO('\n'.join(lines)))
    if next(rows, None) != expected:
        raise ValueError('invalid header')
    result = []
    for row in rows:
        if len(row) != 6 or not row[0].strip():
            raise ValueError('invalid row')
        try:
            item = {'sku': row[0], 'on_hand': float(row[1]), 'daily_use': float(row[2]), 'lead_days': int(row[3]), 'pack_size': int(row[4]), 'priority': int(row[5])}
        except (ValueError, TypeError):
            raise ValueError('invalid row')
        if item['on_hand'] < 0 or item['daily_use'] < 0 or item['lead_days'] < 0 or (item['pack_size'] <= 0) or (item['priority'] < 0):
            raise ValueError('invalid row')
        result.append(item)
    return result

def build_replenishment(records: list[dict], config: dict) -> list[dict]:
    grouped = {}
    for item in records:
        sku = item['sku']
        if sku not in grouped:
            grouped[sku] = [item['on_hand'], item['daily_use'], item['lead_days'], item['pack_size'], item['priority']]
        else:
            value = grouped[sku]
            if value[3] != item['pack_size']:
                raise ValueError('conflicting pack size')
            value[0] += item['on_hand']
            value[1] += item['daily_use']
            value[2] = max(value[2], item['lead_days'])
            value[4] = min(value[4], item['priority'])
    result = []
    for sku, (stock, use, lead, pack, priority) in grouped.items():
        demand = math.ceil(use * lead * 1.2)
        need = max(0, demand - stock)
