import sqlite3
from datetime import datetime, date, timedelta

def _dt(value):
    try:
        return datetime.strptime(value, '%Y-%m-%d %H:%M')
    except (TypeError, ValueError):
        raise ValueError('invalid datetime')

def _day(value):
    try:
        return date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def ensure_schema(conn):
    conn.execute('CREATE TABLE IF NOT EXISTS shifts (id INTEGER PRIMARY KEY AUTOINCREMENT, employee TEXT NOT NULL, start TEXT NOT NULL, end TEXT NOT NULL, role TEXT NOT NULL)')
    conn.commit()

def add_shift(conn, employee, start, end, role):
    if not employee or not role:
        raise ValueError('empty value')
    a, b = (_dt(start), _dt(end))
    if b <= a:
        raise ValueError('invalid interval')
    cur = conn.execute('INSERT INTO shifts(employee,start,end,role) VALUES(?,?,?,?)', (employee, start, end, role))
    conn.commit()
    return cur.lastrowid

def list_shifts(conn, employee=None, date_from=None, date_to=None, sort_by='start', descending=False):
    allowed = {'id': 'id', 'employee': 'employee', 'start': 'start', 'end': 'end', 'role': 'role', 'duration': 'end'}
    if sort_by not in allowed:
        raise ValueError('invalid sort')
    params, clauses = ([], [])
    if employee is not None:
        clauses.append('employee = ?')
        params.append(employee)
    if date_from is not None:
        _day(date_from)
        clauses.append('substr(start,1,10) >= ?')
        params.append(date_from)
    if date_to is not None:
        _day(date_to)
        clauses.append('substr(start,1,10) <= ?')
        params.append(date_to)
    sql = 'SELECT id,employee,start,end,role FROM shifts'
    if clauses:
        sql += ' WHERE ' + ' AND '.join(clauses)
    direction = ' DESC' if descending else ' ASC'
    sql += ' ORDER BY ' + allowed[sort_by] + direction + ', id ASC'
    out = []
    for row in conn.execute(sql, params):
        duration = int((_dt(row[3]) - _dt(row[2])).total_seconds() // 60)
        out.append(dict(zip(('id', 'employee', 'start', 'end', 'role'), row), duration_minutes=duration))
    return out

def weekly_totals(conn, week_start):
    monday = _day(week_start)
    if monday.weekday() != 0:
        raise ValueError('not Monday')
    end = monday + timedelta(days=7)
    groups = {}
    for row in conn.execute('SELECT employee,start,end FROM shifts WHERE substr(start,1,10) >= ? AND substr(start,1,10) < ?', (week_start, end.isoformat())):
        duration = int((_dt(row[2]) - _dt(row[1])).total_seconds() // 60)
        item = groups.setdefault(row[0], [0, 0])
        item[0] += 1
        item[1] += duration
    return [{'employee': k, 'shift_count': groups[k][0], 'total_minutes': groups[k][1]} for k in sorted(groups)]

