import csv
import os
import re
import tempfile

def _fields(line):
    fields = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            if char == 'n':
                current.append('\n')
            elif char in '\\|':
                current.append(char)
            else:
                raise ValueError('invalid escape')
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape')
    fields.append(''.join(current))
    return fields

def parse_ledger(text: str) -> list[dict]:
    result = []
    seen = set()
    for number, raw in enumerate(text.splitlines(), 1):
        if not raw.strip():
            continue
        try:
            parts = _fields(raw)
            if len(parts) != 4:
                raise ValueError('wrong field count')
            identifier, year_text, title, pages_text = [part.strip() for part in parts]
            if not re.fullmatch('[A-Z0-9-]+', identifier):
                raise ValueError('invalid identifier')
            year = int(year_text)
            pages = int(pages_text)
            if len(year_text) != 4 or not 1500 <= year <= 2100:
                raise ValueError('invalid year')
            if pages <= 0 or pages_text.startswith('+'):
                raise ValueError('invalid pages')
            title = ' '.join(title.split())
            if identifier in seen:
                raise ValueError('duplicate identifier')
            seen.add(identifier)
            result.append({'id': identifier, 'year': year, 'title': title, 'pages': pages})
        except (ValueError, TypeError):
            raise ValueError(f'invalid record on line {number}') from None
    return sorted(result, key=lambda item: (item['year'], item['id']))

def summarize_records(records: list[dict]) -> dict[int, dict[str, int]]:
    summary = {}
    for record in records:
        year = record['year']
        bucket = summary.setdefault(year, {'records': 0, 'pages': 0})
        bucket['records'] += 1
        bucket['pages'] += record['pages']
    return dict(sorted(summary.items()))

def export_catalog(records: list[dict], destination: str) -> int:
    ordered = sorted(records, key=lambda item: (item['year'], item['id']))
    parent = os.path.dirname(os.path.abspath(destination))
    descriptor, temporary = tempfile.mkstemp(prefix='catalog-', suffix='.csv', dir=parent, text=True)
    try:
        with os.fdopen(descriptor, 'w', encoding='utf-8', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['id', 'year', 'title', 'pages'])
            for record in ordered:
                writer.writerow([record['id'], record['year'], record['title'], record['pages']])
        os.replace(temporary, destination)
        return len(ordered)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise

