from pathlib import Path

def write_anomaly_report(base_dir: str, relative_name: str, readings: list[float], threshold: float) -> str:
    if not relative_name or Path(relative_name).is_absolute():
        raise ValueError('relative_name must be non-empty and relative')
    if threshold < 0:
        raise ValueError('threshold must not be negative')
    base = Path(base_dir).resolve()
    target = (base / relative_name).resolve()
    try:
        target.relative_to(base)
    except ValueError:
        raise ValueError('report path is outside the base directory')
    target.parent.mkdir(parents=True, exist_ok=True)
    with target.open('w', encoding='utf-8') as handle:
        handle.write('index,value,anomaly\n')
        for index, value in enumerate(readings):
            anomaly = 'true' if abs(value) > threshold else 'false'
            handle.write(f'{index},{value},{anomaly}\n')
    return str(target)

