import hashlib
import hmac
import json
from datetime import date, datetime

def _key(config):
    try:
        value = config['signing_key']
    except (KeyError, TypeError):
        raise ValueError('missing signing_key')
    if not isinstance(value, str) or not value:
        raise ValueError('missing signing_key')
    return value.encode('utf-8')

def _payload(item):
    return json.dumps(item, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode('utf-8')

def _digest(item, key):
    return hmac.new(key, _payload(item), hashlib.sha256).hexdigest()

def _valid_record(record):
    if not isinstance(record, dict):
        raise ValueError('invalid record')
    for name in ('student', 'course', 'issued_at'):
        if not isinstance(record.get(name), str) or not record[name]:
            raise ValueError('invalid record')
    score = record.get('score')
    if isinstance(score, bool) or not isinstance(score, (int, float)) or (not 0 <= score <= 100):
        raise ValueError('invalid record')
    try:
        datetime.fromisoformat(record['issued_at'])
    except ValueError:
        try:
            date.fromisoformat(record['issued_at'])
        except ValueError:
            raise ValueError('invalid record')

def issue_certificates(records: list[dict], config: dict[str, str]) -> list[dict]:
    key = _key(config)
    prepared = []
    for position, record in enumerate(records):
        _valid_record(record)
        prepared.append((record, position))
    prepared.sort(key=lambda pair: (-pair[0]['score'], pair[0]['student'].casefold(), pair[0]['course'], pair[1]))
    result = []
    for rank, (record, _) in enumerate(prepared, 1):
        item = {'serial': f'CERT-{rank:04d}', 'student': record['student'], 'course': record['course'], 'score': record['score'], 'issued_at': record['issued_at'], 'rank': rank}
        result.append({**item, 'signature': _digest(item, key)})
    return result

def parse_certificate(text: str, config: dict[str, str]) -> dict:
    try:
        key = _key(config)
        value = json.loads(text)
        fields = ('serial', 'student', 'course', 'score', 'issued_at', 'rank', 'signature')
        if not isinstance(value, dict) or any((field not in value for field in fields)):
            raise ValueError
        if not isinstance(value['serial'], str) or not value['serial'].startswith('CERT-'):
            raise ValueError
        if isinstance(value['rank'], bool) or not isinstance(value['rank'], int) or value['rank'] < 1:
            raise ValueError
        signature = value['signature']
        if not isinstance(signature, str) or len(signature) != 64 or any((c not in '0123456789abcdef' for c in signature)):
            raise ValueError
        item = {field: value[field] for field in fields[:-1]}
        if not hmac.compare_digest(_digest(item, key), signature):
            raise ValueError
        return value
    except Exception as exc:
        if isinstance(exc, ValueError) and str(exc) == 'missing signing_key':
            raise
        raise ValueError('invalid certificate')

