            grouped[sku][0] += quantity
            grouped[sku][1] += quantity * cents
            totals.setdefault(sku, [0, 0])
            totals[sku][0] += quantity
            totals[sku][1] += quantity * cents
        lines = [{'sku': sku, 'quantity': grouped[sku][0], 'line_total_cents': grouped[sku][1]} for sku in sorted(grouped)]
        shipments.append({'order_id': order['order_id'], 'customer': order['customer'], 'items': lines})
