def make_body(applications):
    return json.dumps({"applications": applications}, separators=(",", ":")).encode()


def signed(body, secret=b"gallery-key"):
    return hmac.new(secret, body, hashlib.sha256).hexdigest()


def app(id, artist, region, status, score, amount):
    return {"id": id, "artist": artist, "region": region, "status": status, "score": score, "amount": amount}


def test_accepts_signature_and_filters_and_normalizes_fields():
    body = make_body([
        app("b", "Beta", "North", "submitted", 72, 1000),
        app("a", "Alpha", "South", "draft", 99, 200),
        app("c", "Gamma", "East", "submitted", 59.9, 300),
    ])
    result = verify_and_rank_applications(body, signed(body), b"gallery-key")
    assert result == {
        "applications": [{"id": "b", "artist": "Beta", "region": "North", "score": 72, "amount": 1000}],
        "total_count": 1, "total_amount": 1000, "page": 1, "page_size": 10, "total_pages": 1
    }


