def verify_and_rank_applications(body: bytes, signature: str, secret: bytes, page: int=1, page_size: int=10) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1 or (page_size > 100):
        raise ValueError('invalid page size')
    try:
        expected = hmac.new(secret, body, hashlib.sha256).hexdigest()
        if not hmac.compare_digest(expected, signature):
            raise ValueError('invalid signature')
        data = json.loads(body.decode('utf-8'))
    except ValueError:
        raise
    except Exception as exc:
        raise ValueError('invalid body') from exc
    if not isinstance(data, dict) or not isinstance(data.get('applications'), list):
        raise ValueError('invalid applications')
    selected = []
    for item in data['applications']:
        if not isinstance(item, dict):
            raise ValueError('invalid application')
        required = ('id', 'artist', 'region', 'status', 'score', 'amount')
        if any((key not in item for key in required)):
            raise ValueError('invalid application')
        if not isinstance(item['id'], str) or not item['id']:
            raise ValueError('invalid application')
        if not all((isinstance(item[key], str) for key in ('artist', 'region', 'status'))):
            raise ValueError('invalid application')
        if isinstance(item['score'], bool) or not isinstance(item['score'], (int, float)) or (not 0 <= item['score'] <= 100):
            raise ValueError('invalid application')
        if isinstance(item['amount'], bool) or not isinstance(item['amount'], (int, float)) or item['amount'] <= 0:
            raise ValueError('invalid application')
        if item['status'] == 'submitted' and item['score'] >= 60:
            selected.append({'id': item['id'], 'artist': item['artist'], 'region': item['region'], 'score': item['score'], 'amount': item['amount']})
    selected.sort(key=lambda x: (-x['score'], x['amount'], x['id']))
    total = len(selected)
    start = (page - 1) * page_size
    return {'applications': selected[start:start + page_size], 'total_count': total, 'total_amount': round(sum((x['amount'] for x in selected)), 2), 'page': page, 'page_size': page_size, 'total_pages': math.ceil(total / page_size) if total else 0}

