import re
from datetime import datetime, timedelta

def parse_delivery_window(text: str) -> tuple:
    if not isinstance(text, str):
        raise ValueError('invalid window')
    m = re.fullmatch('\\s*(\\d{4}-\\d{2}-\\d{2})\\s+(\\d{2}:\\d{2})\\s*-\\s*(\\d{2}:\\d{2})\\s*', text)
    if not m:
        raise ValueError('invalid window')
    try:
        start = datetime.strptime(m.group(1) + ' ' + m.group(2), '%Y-%m-%d %H:%M')
        end = datetime.strptime(m.group(1) + ' ' + m.group(3), '%Y-%m-%d %H:%M')
    except ValueError as exc:
        raise ValueError('invalid window') from exc
    if start.minute % 30 or end.minute % 30 or start.hour < 8 or (end.hour > 20) or (start < datetime(start.year, start.month, start.day, 8)) or (end > datetime(start.year, start.month, start.day, 20)) or (end <= start) or (end - start < timedelta(minutes=30)) or (end - start > timedelta(minutes=120)):
        raise ValueError('invalid window')
    return (start, end)

def reschedule_delivery(requester: dict, delivery: dict, new_start: str, occupied: list[dict]) -> dict:
    required = {'id', 'owner_id', 'tenant_id', 'status', 'window'}
    if not isinstance(requester, dict) or not isinstance(delivery, dict) or (not required <= delivery.keys()):
        raise ValueError('invalid delivery')
    if not isinstance(occupied, list) or delivery['status'] not in {'scheduled', 'confirmed'}:
        raise ValueError('cannot reschedule')
    try:
        start = datetime.strptime(new_start, '%Y-%m-%d %H:%M')
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid start') from exc
    end = start + timedelta(hours=1)
    parse_delivery_window(start.strftime('%Y-%m-%d %H:%M-') + end.strftime('%H:%M'))
    if not (requester.get('user_id') == delivery['owner_id'] or ('dispatcher' in requester.get('roles', []) and requester.get('tenant_id') == delivery['tenant_id'])):
        raise PermissionError('not permitted')
    for item in occupied:
        if not isinstance(item, dict) or item.get('id') == delivery['id'] or item.get('tenant_id') != delivery['tenant_id'] or (item.get('status') == 'cancelled'):
            continue
        try:
            other_start, other_end = parse_delivery_window(item['window'])
        except (KeyError, ValueError) as exc:
            raise ValueError('invalid occupied delivery') from exc
        if start < other_end and other_start < end:
            raise ValueError('occupied')
    result = dict(delivery)
    result['window'] = start.strftime('%Y-%m-%d %H:%M-') + end.strftime('%H:%M')
    result['status'] = 'scheduled'
    return result

def build_route_manifest(deliveries: list[dict]) -> list[dict]:
    result, ids = ([], set())
    for item in deliveries:
        if not isinstance(item, dict) or not {'id', 'window', 'address', 'priority', 'flowers'} <= item.keys() or item['id'] in ids or (type(item['flowers']) is not int) or (item['flowers'] < 0):
            raise ValueError('invalid delivery')
        ids.add(item['id'])
        start, end = parse_delivery_window(item['window'])
        result.append({'date': start.strftime('%Y-%m-%d'), 'start': start.strftime('%H:%M'), 'end': end.strftime('%H:%M'), 'id': item['id'], 'address': item['address'], 'priority': item['priority'], 'flowers': item['flowers']})
    result.sort(key=lambda x: (x['date'], x['start'], -x['priority'], x['address'].casefold(), x['id']))
    return result

