import zipfile
_FIELDS = ['freezer', 'box', 'position', 'sample_id', 'volume_ul', 'status']
_POS = re.compile('^([A-Z])(\\d+)$')
_STATUSES = ('present', 'consumed', 'discarded')

def load_inventory(base_dir: str, archive_path: str) -> list[dict]:
    root = os.path.realpath(base_dir)
    try:
        with zipfile.ZipFile(archive_path) as zf:
            names = zf.namelist()
            if 'inventory.csv' not in names:
                raise ValueError('inventory.csv is required')
            for name in names:
                target = os.path.realpath(os.path.join(root, name))
                if os.path.commonpath((root, target)) != root:
                    raise ValueError('archive member is outside base directory')
                zf.extract(name, root)
            with open(os.path.join(root, 'inventory.csv'), 'r', encoding='utf-8', newline='') as f:
                rows = list(csv.reader(f))
    except ValueError:
        raise
    except (OSError, zipfile.BadZipFile, UnicodeError, csv.Error) as e:
        raise ValueError('invalid inventory archive') from e
    if not rows or rows[0] != _FIELDS:
        raise ValueError('incorrect header')
    result = []
    seen = set()
    for row in rows[1:]:
        if len(row) != 6:
            raise ValueError('invalid row')
        freezer, box, position, sample_id, volume, status = (x.strip() for x in row)
        match = _POS.fullmatch(position)
        try:
            box_num = int(box)
            volume_num = float(volume)
        except ValueError as e:
            raise ValueError('invalid number') from e
        if not freezer or not sample_id or box_num <= 0 or (not match) or (int(match.group(2)) <= 0) or (volume_num < 0) or (status not in _STATUSES) or (sample_id in seen):
            raise ValueError('invalid inventory row')
        seen.add(sample_id)
        result.append({'freezer': freezer, 'box': box_num, 'position': position, 'sample_id': sample_id, 'volume_ul': volume_num, 'status': status})
    result.sort(key=lambda x: (x['freezer'], x['box'], x['position'][0], int(x['position'][1:]), x['sample_id']))
    return result

def summarize_inventory(records: list[dict]) -> dict:
    out = {}
    for record in records:
        if any((k not in record for k in _FIELDS)) or record['status'] not in _STATUSES:
            raise ValueError('invalid record')
        try:
            volume = float(record['volume_ul'])
        except (TypeError, ValueError) as e:
            raise ValueError('invalid volume') from e
        if volume < 0:
            raise ValueError('invalid volume')
        freezer = record['freezer']
        if freezer not in out:
            out[freezer] = {'sample_count': 0, 'total_volume_ul': 0.0, 'by_status': {s: 0 for s in _STATUSES}}
        out[freezer]['sample_count'] += 1
        out[freezer]['total_volume_ul'] += volume
        out[freezer]['by_status'][record['status']] += 1
    for value in out.values():
        value['total_volume_ul'] = round(value['total_volume_ul'], 2)
    return dict(sorted(out.items()))

