    for node in root:
        if node.tag != 'document':
            continue
        ident = node.get('id')
        title = node.get('title')
        if ident is None or title is None or (not ident.strip()) or (not title.strip()):
            raise ValueError('invalid document')
        ident = ident.strip()
        if ident in seen:
            raise ValueError('duplicate id')
        seen.add(ident)
