                continue
            stage = child.get('stage')
            actor = child.get('actor')
            stamp = child.get('at')
            if any((x is None or not x.strip() for x in (stage, actor, stamp))):
                raise ValueError('invalid event')
            stage, actor, stamp = (stage.strip(), actor.strip(), stamp.strip())
            try:
                when = datetime.strptime(stamp, '%Y-%m-%dT%H:%M:%SZ')
            except ValueError:
                raise ValueError('invalid timestamp')
            events.append((when, stage, actor, stamp))
            if actor not in actors:
                actors.append(actor)
        if events:
            latest = max(enumerate(events), key=lambda pair: (pair[1][0], pair[0]))[1]
            first_time = min((event[0] for event in events))
            result.append({'id': ident, 'title': title, 'status': latest[1], 'updated_at': latest[3], 'actors': actors, 'elapsed_seconds': int((latest[0] - first_time).total_seconds()), '_sort': (0, latest[0], ident)})
