import os
from datetime import date, timedelta
import math

def hash_secret(secret: str) -> str:
    if not isinstance(secret, str) or not secret:
        raise ValueError('invalid secret')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
    return 'pbkdf2$100000$' + salt.hex() + '$' + digest.hex()

def verify_secret(stored: str, secret: str) -> bool:
    if not isinstance(stored, str) or not isinstance(secret, str):
        return False
    try:
        kind, count, salt, digest = stored.split('$')
        if kind != 'pbkdf2' or int(count) != 100000:
            return False
        actual = hashlib.pbkdf2_hmac('sha256', secret.encode(), bytes.fromhex(salt), 100000).hex()
        return hmac.compare_digest(actual, digest)
    except (ValueError, TypeError):
        return False

def build_remediation_report(records: list[dict], start_date: str, end_date: str, stored_secret: str, supplied_secret: str) -> dict:
    if not verify_secret(stored_secret, supplied_secret):
        raise PermissionError('unauthorized')
    try:
        first = date.fromisoformat(start_date)
        last = date.fromisoformat(end_date)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if first > last or not isinstance(records, list):
        raise ValueError('invalid range or records')
    projects = {}
    daily = {}
    for row in records:
        try:
            project, stamp, contaminant = (row['project'], row['date'], row['contaminant'])
            mass, status = (row['mass'], row['status'])
            when = date.fromisoformat(stamp)
            valid = isinstance(project, str) and bool(project) and isinstance(contaminant, str) and bool(contaminant)
            valid = valid and status in {'planned', 'in_progress', 'completed'}
            valid = valid and isinstance(mass, (int, float)) and (not isinstance(mass, bool)) and math.isfinite(mass) and (mass >= 0)
            if not valid:
                raise ValueError
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid record')
        if status == 'completed' and first <= when <= last:
