            projects[project][contaminant] += mass
            daily[when] = daily.get(when, 0.0) + mass
    output = []
    for project in sorted(projects):
        contaminants = [{'contaminant': c, 'total_mass': round(projects[project][c], 3)} for c in sorted(projects[project])]
