    xml = '<bid id=" X7 "><supplier>  North Works </supplier><total>12.340</total><delivery_days>31</delivery_days><items><item sku="A" qty="2" unit_price="3.1"/><item sku="B" qty="1" unit_price="6.14"/></items></bid>'
    assert parse_bid(xml) == {'id': 'X7', 'supplier': 'North Works', 'total': 12.34, 'delivery_days': 31, 'items': [{'sku': 'A', 'qty': 2, 'unit_price': 3.1}, {'sku': 'B', 'qty': 1, 'unit_price': 6.14}]}

