    cases = ['<offer id="a"><supplier>x</supplier></offer>', '<bid id=""><supplier>x</supplier><total>1</total><delivery_days>1</delivery_days><items><item sku="a" qty="1" unit_price="1"/></items></bid>', bid_xml(items='<item sku="a" qty="0" unit_price="1"/>'), bid_xml(items='<item sku="a" qty="1" unit_price="1"/><item sku="a" qty="2" unit_price="2"/>'), bid_xml(total='-1'), bid_xml(days='2.5'), '<bid id="a"><supplier>x</supplier><total>1</total><delivery_days>1</delivery_days><items></items></bid>']
    for value in cases:
