from lxml import etree
from decimal import Decimal, InvalidOperation

def _root(text):
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        return etree.fromstring(text.encode(), parser=parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc

def _text(node, name):
    child = node.find(name)
    if child is None or child.text is None or (not child.text.strip()):
        raise ValueError('missing field')
    return child.text.strip()

def _decimal(value):
    try:
        value = Decimal(value)
    except (InvalidOperation, ValueError):
        raise ValueError('invalid number')
    if not value.is_finite() or value < 0:
        raise ValueError('invalid number')
    return float(value)

def parse_bid(xml_text: str) -> dict:
    root = _root(xml_text)
    if root.tag != 'bid' or not root.get('id', '').strip():
        raise ValueError('invalid bid')
    supplier = _text(root, 'supplier')
    total = _decimal(_text(root, 'total'))
    try:
        delivery = int(_text(root, 'delivery_days'))
    except ValueError:
        raise ValueError('invalid delivery')
    if delivery < 0 or str(delivery) != _text(root, 'delivery_days'):
        raise ValueError('invalid delivery')
    items_node = root.find('items')
    if items_node is None or not items_node.findall('item'):
        raise ValueError('missing items')
    items = []
    seen = set()
    for node in items_node.findall('item'):
        sku = node.get('sku', '').strip()
        if not sku or sku in seen:
            raise ValueError('invalid sku')
        seen.add(sku)
        try:
            qty = int(node.get('qty', ''))
        except ValueError:
            raise ValueError('invalid quantity')
        if qty <= 0 or str(qty) != node.get('qty', ''):
            raise ValueError('invalid quantity')
        items.append({'sku': sku, 'qty': qty, 'unit_price': _decimal(node.get('unit_price', ''))})
    return {'id': root.get('id').strip(), 'supplier': supplier, 'total': total, 'delivery_days': delivery, 'items': items}

def rank_bids(xml_documents: list[str]) -> list[dict]:
    bids = []
    for bid in (parse_bid(x) for x in xml_documents):
        score = bid['total'] + max(0, bid['delivery_days'] - 30) * 100.0
        bid = dict(bid)
        bid['score'] = round(score, 2)
        bids.append(bid)
    bids.sort(key=lambda x: (x['score'], x['total'], x['delivery_days'], x['id']))
    for index, bid in enumerate(bids, 1):
        bid['rank'] = index
    return bids

def procurement_summary(xml_documents: list[str]) -> dict:
    ranked = rank_bids(xml_documents)
    suppliers = {}
    for bid in ranked:
        suppliers[bid['supplier']] = suppliers.get(bid['supplier'], 0) + 1
    suppliers = dict(sorted(suppliers.items()))
    return {'count': len(ranked), 'total_value': round(sum((x['total'] for x in ranked)), 2), 'suppliers': suppliers, 'recommended_id': ranked[0]['id'] if ranked else None}

