from solution import summarize_inventory
import hashlib
import hmac
import json
import pytest
from datetime import datetime, timezone, timedelta


def signed(rows, secret=b"key"):
    result = []
    for row in rows:
        body = {k: row[k] for k in ("campaign", "slot", "start", "seconds", "impressions")}
        text = json.dumps(body, separators=(",", ":"), ensure_ascii=False)
        result.append({**body, "signature": hmac.new(secret, text.encode(), hashlib.sha256).hexdigest()})
    return json.dumps(result)


def test_empty_inventory():
    assert summarize_inventory("[]", b"key") == {"campaigns": {}, "timeline": []}


def test_aggregation_and_timeline_order():
    rows = [
        {"campaign": "Bravo", "slot": "b", "start": "2025-01-02T12:01:00Z", "seconds": 30, "impressions": 7},
        {"campaign": "Alpha", "slot": "z", "start": "2025-01-02T12:00:00Z", "seconds": 10, "impressions": 3},
        {"campaign": "Alpha", "slot": "a", "start": "2025-01-02T12:00:20Z", "seconds": 5, "impressions": 4},
    ]
    assert summarize_inventory(signed(rows), b"key") == {
        "campaigns": {
            "Alpha": {"impressions": 7, "seconds": 15},
            "Bravo": {"impressions": 7, "seconds": 30},
        },
        "timeline": [
            {"slot": "z", "campaign": "Alpha", "start": "2025-01-02T12:00:00Z", "end": "2025-01-02T12:00:10Z"},
            {"slot": "a", "campaign": "Alpha", "start": "2025-01-02T12:00:20Z", "end": "2025-01-02T12:00:25Z"},
            {"slot": "b", "campaign": "Bravo", "start": "2025-01-02T12:01:00Z", "end": "2025-01-02T12:01:30Z"},
        ],
    }


def test_same_start_uses_slot_tiebreaker():
    rows = [
        {"campaign": "C", "slot": "z", "start": "2025-01-01T00:00:00Z", "seconds": 1, "impressions": 1},
        {"campaign": "C", "slot": "a", "start": "2025-01-01T00:00:02Z", "seconds": 1, "impressions": 1},
    ]
    assert [x["slot"] for x in summarize_inventory(signed(rows), b"key")["timeline"]] == ["z", "a"]


def test_wrong_secret_and_changed_data_are_rejected():
    row = {"campaign": "C", "slot": "s", "start": "2025-01-01T00:00:00Z", "seconds": 5, "impressions": 1}
    with pytest.raises(ValueError):
        summarize_inventory(signed([row], b"other"), b"key")
    altered = json.loads(signed([row]))
    altered[0]["impressions"] = 2
    with pytest.raises(ValueError):
        summarize_inventory(json.dumps(altered), b"key")


def test_overlap_and_duplicate_slot_rejected():
    a = {"campaign": "A", "slot": "1", "start": "2025-01-01T00:00:00Z", "seconds": 10, "impressions": 1}
    b = {"campaign": "B", "slot": "2", "start": "2025-01-01T00:00:09Z", "seconds": 2, "impressions": 1}
    with pytest.raises(ValueError):
        summarize_inventory(signed([a, b]), b"key")
    c = {**a, "start": "2025-01-01T00:00:20Z"}
    with pytest.raises(ValueError):
        summarize_inventory(signed([a, c]), b"key")


def test_bad_shapes_and_values_raise_value_error():
    for payload in ["not json", "{}", "[1]", "[{\"campaign\":\"x\"}]"]:
        with pytest.raises(ValueError):
            summarize_inventory(payload, b"key")
    row = {"campaign": "A", "slot": "s", "start": "2025-01-01T00:00:00+00:00", "seconds": 1, "impressions": 0}
    with pytest.raises(ValueError):
        summarize_inventory(signed([row]), b"key")


def test_touching_intervals_are_allowed():
    rows = [
        {"campaign": "A", "slot": "1", "start": "2025-01-01T00:00:00Z", "seconds": 10, "impressions": 0},
        {"campaign": "B", "slot": "2", "start": "2025-01-01T00:00:10Z", "seconds": 1, "impressions": 2},
    ]
    result = summarize_inventory(signed(rows), b"key")
    assert result["timeline"][1]["end"] == "2025-01-01T00:00:11Z"

