import sqlite3
from datetime import datetime, date, timedelta

def _stamp(value):
    try:
        return datetime.strptime(value, '%Y-%m-%d %H:%M')
    except (TypeError, ValueError):
        raise ValueError('invalid timestamp')

def fetch_jobs(conn: sqlite3.Connection, line: str | None, window_start: str, window_end: str, sort_by: str='start') -> list[dict]:
    start = _stamp(window_start)
    end = _stamp(window_end)
    if start >= end:
        raise ValueError('invalid window')
    columns = {'start': 'start_ts', 'priority': 'priority', 'duration': 'duration_min', 'product': 'product'}
    if sort_by not in columns:
        raise ValueError('invalid sort')
    sql = "select id,line,product,start_ts,duration_min,status,priority from jobs where status <> ? and start_ts < ? and datetime(start_ts, '+' || duration_min || ' minutes') > ?"
    args = ['cancelled', window_end, window_start]
    if line is not None:
        sql += ' and line = ?'
        args.append(line)
    sql += ' order by ' + columns[sort_by] + ' asc, start_ts asc, id asc'
    result = []
    for row in conn.execute(sql, args):
        finish = _stamp(row['start_ts']) + timedelta(minutes=row['duration_min'])
        result.append({'id': row['id'], 'line': row['line'], 'product': row['product'], 'start_ts': row['start_ts'], 'duration_min': row['duration_min'], 'status': row['status'], 'priority': row['priority'], 'end_ts': finish.strftime('%Y-%m-%d %H:%M')})
    return result

def reserve_jobs(conn: sqlite3.Connection, job_ids: list[int], operator: str) -> list[int]:
    if not isinstance(operator, str) or not operator.strip():
        raise ValueError('invalid operator')
    ids = list(dict.fromkeys(job_ids))
    changed = []
    with conn:
        for job_id in ids:
            cur = conn.execute('update jobs set status = ?, reserved_by = ? where id = ? and status = ?', ('reserved', operator, job_id, 'queued'))
            if cur.rowcount:
                changed.append(job_id)
    return changed

def daily_load(conn: sqlite3.Connection, line: str, day: str) -> list[dict]:
    try:
        date.fromisoformat(day)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    rows = conn.execute('select product, duration_min, priority from jobs where line = ? and start_ts >= ? and start_ts < ? and status <> ?', (line, day + ' 00:00', (date.fromisoformat(day) + timedelta(days=1)).isoformat() + ' 00:00', 'cancelled'))
    groups = {}
    for product, minutes, priority in rows:
        item = groups.setdefault(product, [0, 0, priority])
        item[0] += 1
        item[1] += minutes
        item[2] = min(item[2], priority)
    result = [{'product': p, 'job_count': v[0], 'total_minutes': v[1], 'highest_priority': v[2]} for p, v in groups.items()]
    return sorted(result, key=lambda x: (-x['total_minutes'], x['highest_priority'], x['product']))

