import os

def hash_password(password: str) -> str:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    if password == '':
        raise ValueError('password must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 120000)
    return base64.b64encode(salt).decode() + '$' + base64.b64encode(digest).decode()

def verify_password(password: str, stored_hash: str) -> bool:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    if not isinstance(stored_hash, str):
        return False
    try:
        salt_text, digest_text = stored_hash.split('$', 1)
        salt = base64.b64decode(salt_text.encode(), validate=True)
        expected = base64.b64decode(digest_text.encode(), validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 120000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def compliance_summary(records: list[dict], page: int=1, page_size: int=10, department: str | None=None) -> dict:
    if type(page) is not int or page <= 0 or type(page_size) is not int or (page_size <= 0):
        raise ValueError('invalid pagination')
    if department == '':
        raise ValueError('invalid department')
    groups = {}
    seen = set()
    required = {'employee', 'department', 'course', 'score', 'completed'}
    for record in records:
        if not isinstance(record, dict) or set(record) != required:
            raise ValueError('invalid record')
        employee = record['employee']
        dept = record['department']
        course = record['course']
        score = record['score']
        completed = record['completed']
        if not isinstance(employee, str) or not employee or (not isinstance(dept, str)) or (not dept) or (not isinstance(course, str)) or (not course):
            raise ValueError('invalid record')
        if isinstance(score, bool) or not isinstance(score, (int, float)) or (not 0 <= score <= 100) or (not isinstance(completed, bool)):
            raise ValueError('invalid record')
        if department is not None and dept != department:
            continue
        key = (employee, course)
        if key in seen:
            raise ValueError('duplicate course')
        seen.add(key)
