import csv
from collections import defaultdict
from datetime import datetime

def summarize_sessions(path: str, bucket_minutes: int=30, station: str | None=None) -> dict[str, dict[str, int | float]]:
    if not isinstance(bucket_minutes, int) or isinstance(bucket_minutes, bool) or (not 1 <= bucket_minutes <= 1440):
        raise ValueError('invalid bucket')
    try:
        with open(path, newline='') as handle:
            rows = list(csv.reader(handle))
    except (OSError, csv.Error) as exc:
        raise ValueError('cannot read input') from exc
    if not rows or rows[0] != ['session_id', 'station', 'start', 'end', 'kwh', 'status']:
        raise ValueError('invalid header')
    groups = defaultdict(list)
    for row in rows[1:]:
        if len(row) != 6:
            raise ValueError('invalid row')
        try:
            sid, name, start_text, end_text, kwh_text, status = row
            start = datetime.fromisoformat(start_text)
            end = datetime.fromisoformat(end_text)
            kwh = float(kwh_text)
        except (ValueError, TypeError) as exc:
            raise ValueError('invalid row') from exc
        if not name or end < start or kwh < 0 or (status not in ('completed', 'cancelled')):
            raise ValueError('invalid row')
        if station is None or station == name:
            groups[name].append((start, end, kwh, status))
    result = {}
    for name in sorted(groups):
        items = sorted(groups[name], key=lambda item: item[0])
        events = [(s, 1) for s, _, _, _ in items] + [(e, -1) for _, e, _, _ in items]
        events.sort(key=lambda event: (event[0], event[1]))
        current = peak = 0
        for _, change in events:
            current += change
            peak = max(peak, current)
        total_minutes = sum(((e - s).total_seconds() / 60 for s, e, _, _ in items))
        total_kwh = sum((k for _, _, k, state in items if state == 'completed'))
        result[name] = {'session_count': len(items), 'completed_kwh': round(total_kwh, 3), 'average_duration_minutes': round(total_minutes / len(items), 2), 'max_concurrent': peak}
    return result

