    if not isinstance(api_secret, str) or not api_secret:
        raise ValueError('api_secret must be non-empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', api_secret.encode(), salt, 100000)
    return {'reviewer_id': reviewer_id, 'secret_hash': salt.hex() + '$' + digest.hex()}

def authenticate_reviewer(record: dict, api_secret: str) -> bool:
    if not isinstance(record, dict) or not isinstance(api_secret, str) or (not api_secret):
        return False
    if not isinstance(record.get('reviewer_id'), str) or not isinstance(record.get('secret_hash'), str):
        return False
    try:
        salt_text, digest_text = record['secret_hash'].split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', api_secret.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def review_summary(reviews: list[dict]) -> dict:
    counts = {'approved': 0, 'changes_requested': 0, 'commented': 0}
