import re
import secrets

def parse_substitution_rules(text: str) -> dict[str, list[str]]:
    result = {}
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith('#'):
            continue
        if line.count('=>') != 1:
            raise ValueError('invalid rule')
        left, right = line.split('=>')
        item = left.strip()
        values = [x.strip() for x in right.split(',')]
        if not item or any((not x for x in values)):
            raise ValueError('invalid rule')
        target = result.setdefault(item, [])
        for value in values:
            if value not in target:
                target.append(value)
    return result

def fulfill_order(order: list[dict[str, int]], rules: dict[str, list[str]], stock: dict[str, int]) -> list[dict[str, object]]:
    available = dict(stock)
    for value in available.values():
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            raise ValueError('invalid stock')
    output = []
    for line in order:
        if set(line) != {'sku', 'quantity'}:
            raise ValueError('invalid order line')
        requested = line['sku']
        quantity = line['quantity']
        if not isinstance(requested, str) or isinstance(quantity, bool) or (not isinstance(quantity, int)) or (quantity <= 0):
            raise ValueError('invalid order line')
        for candidate in [requested] + list(rules.get(requested, [])):
            if available.get(candidate, 0) >= quantity:
                available[candidate] -= quantity
                output.append({'requested': requested, 'sku': candidate, 'quantity': quantity, 'substituted': candidate != requested})
                break
    return output

def make_invite_code(prefix: str, length: int=12) -> str:
    alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
    if not isinstance(prefix, str) or not re.fullmatch('[A-Z]{2,8}', prefix):
        raise ValueError('invalid prefix')
    if isinstance(length, bool) or not isinstance(length, int) or (not 6 <= length <= 32):
        raise ValueError('invalid length')
    return prefix + '-' + ''.join((secrets.choice(alphabet) for _ in range(length)))

