def summarize_scans(requester: dict, documents: list[dict], offset: int=0, limit: int=50) -> list[dict]:
    if isinstance(offset, bool) or not isinstance(offset, int) or offset < 0:
        raise ValueError('invalid offset')
    if isinstance(limit, bool) or not isinstance(limit, int) or limit < 1 or (limit > 100):
        raise ValueError('invalid limit')
    results = []
    for document in documents:
        for key in ('id', 'owner_id', 'tenant_id', 'status', 'pages'):
            if key not in document:
                raise ValueError('invalid document')
        allowed = document['owner_id'] == requester.get('id') or ('scanner_admin' in requester.get('roles', []) and document['tenant_id'] == requester.get('tenant_id'))
        if not allowed:
            raise PermissionError('document access denied')
        if not isinstance(document['pages'], list):
            raise ValueError('invalid pages')
