        counts = {}
        for page in document['pages']:
            if 'findings' not in page or not isinstance(page['findings'], list):
                raise ValueError('invalid findings')
            for finding in page['findings']:
                counts[finding] = counts.get(finding, 0) + 1
        finding_types = [{'type': name, 'count': count} for name, count in sorted(counts.items(), key=lambda item: (-item[1], item[0]))]
