import csv
import io
from datetime import datetime, timezone
STATUSES = ('idle', 'working', 'charging', 'fault', 'offline')

def _time(value):
    try:
        parsed = datetime.fromisoformat(value.replace('Z', '+00:00'))
    except Exception as exc:
        raise ValueError('invalid timestamp') from exc
    if parsed.tzinfo is None:
        raise ValueError('timestamp must include timezone')
    return parsed.astimezone(timezone.utc)

def _stamp(value):
    return _time(value).isoformat().replace('+00:00', 'Z')

def parse_status_stream(text: str) -> list[dict]:
    result = []
    for row in csv.reader(io.StringIO(text)):
        if not row or all((not item.strip() for item in row)):
            continue
        if len(row) != 5:
            raise ValueError('wrong field count')
        timestamp, robot, status, battery, temperature = [x.strip() for x in row]
        if not robot or status not in STATUSES:
            raise ValueError('invalid record')
        moment = _time(timestamp)
        try:
            level = int(battery)
            heat = float(temperature)
        except Exception as exc:
            raise ValueError('invalid number') from exc
        if level < 0 or level > 100:
            raise ValueError('invalid battery')
        result.append({'timestamp': moment, 'robot_id': robot, 'status': status, 'battery': level, 'temperature': heat})
    result.sort(key=lambda x: x['timestamp'])
    for item in result:
        item['timestamp'] = item['timestamp'].isoformat().replace('+00:00', 'Z')
    return result

def robot_report(requester: dict, robot_id: str, fleet: dict[str, dict], events: list[dict], start: str, end: str) -> dict:
    begin, finish = (_time(start), _time(end))
    if begin > finish:
        raise ValueError('reversed range')
    robot = fleet.get(robot_id)
    if robot is None or robot['tenant_id'] != requester.get('tenant_id') or (robot['owner_id'] != requester.get('id') and 'supervisor' not in requester.get('roles', [])):
        raise PermissionError('report unavailable')
    selected = [e for e in events if e['robot_id'] == robot_id and begin <= _time(e['timestamp']) <= finish]
    counts = {name: 0 for name in STATUSES}
    for event in selected:
        if event['status'] not in counts:
            raise ValueError('invalid status')
        counts[event['status']] += 1
    batteries = [e['battery'] for e in selected]
    temperatures = [e['temperature'] for e in selected]
    latest = max(selected, key=lambda e: _time(e['timestamp'])) if selected else None
    return {'robot_id': robot_id, 'model': robot['model'], 'period': [_stamp(start), _stamp(end)], 'event_count': len(selected), 'status_counts': counts, 'average_battery': round(sum(batteries) / len(batteries), 2) if batteries else None, 'minimum_temperature': min(temperatures) if temperatures else None, 'maximum_temperature': max(temperatures) if temperatures else None, 'latest_status': latest['status'] if latest else None}

def rank_reports(reports: list[dict]) -> list[str]:
    checked = []
    for report in reports:
        try:
            faults = report['status_counts']['fault']
            average = report['average_battery']
            robot = report['robot_id']
        except (KeyError, TypeError) as exc:
            raise ValueError('incomplete report') from exc
        if not isinstance(faults, int) or isinstance(faults, bool):
            raise ValueError('invalid fault count')
        checked.append((robot, faults, average))
    checked.sort(key=lambda x: (-x[1], x[2] is None, x[2] if x[2] is not None else 0, x[0]))
    return [x[0] for x in checked]

