import datetime
import hashlib
import json
import math

def parse_readings(text: str) -> list[tuple[str, float]]:
    if not isinstance(text, str):
        raise ValueError('text')
    out = []
    for line in text.splitlines():
        if not line.strip():
            continue
        parts = line.split('|')
        if len(parts) != 3 or parts[2] != 'mm' or (not parts[0].endswith('Z')):
            raise ValueError('record')
        try:
            datetime.datetime.fromisoformat(parts[0][:-1]).replace(tzinfo=datetime.timezone.utc)
            value = float(parts[1])
        except Exception as exc:
            raise ValueError('record') from exc
        if not math.isfinite(value) or parts[0] in {x[0] for x in out}:
            raise ValueError('record')
        out.append((parts[0], value))
    if not out:
        raise ValueError('empty')
    return sorted(out)

def certify_component(requester: dict, component: dict, readings_text: str) -> dict:
    required = ['id', 'tenant_id', 'owner_id', 'nominal_mm', 'tolerance_mm', 'required_samples', 'expires_on']
    if not isinstance(component, dict) or any((k not in component for k in required)):
        raise ValueError('component')
    try:
        datetime.date.fromisoformat(component['expires_on'])
        nominal = float(component['nominal_mm'])
        tolerance = float(component['tolerance_mm'])
        count = int(component['required_samples'])
    except Exception as exc:
        raise ValueError('component') from exc
    if not math.isfinite(nominal) or not math.isfinite(tolerance) or tolerance <= 0 or (count <= 0):
        raise ValueError('component')
    if not isinstance(requester, dict) or not isinstance(requester.get('id'), str) or (not isinstance(requester.get('tenant_id'), str)) or (not isinstance(requester.get('roles'), list)):
        raise ValueError('requester')
    if requester['tenant_id'] != component['tenant_id'] or (requester['id'] != component['owner_id'] and 'certifier' not in requester['roles']):
        raise PermissionError('not authorized')
    readings = parse_readings(readings_text)
    values = [x[1] for x in readings]
    status = 'incomplete' if len(values) < count else 'certified' if all((abs(v - nominal) <= tolerance for v in values)) else 'rejected'
    result = {'component_id': component['id'], 'tenant_id': component['tenant_id'], 'certified_by': requester['id'], 'status': status, 'sample_count': len(values), 'minimum_mm': round(min(values), 6), 'maximum_mm': round(max(values), 6), 'mean_mm': round(sum(values) / len(values), 6), 'nominal_mm': nominal, 'tolerance_mm': tolerance, 'expires_on': component['expires_on']}
    result['certificate_id'] = hashlib.sha256(json.dumps(result, sort_keys=True, separators=(',', ':')).encode()).hexdigest()
    return result

def certificate_summary(certificates: list[dict], tenant_id: str) -> dict:
    if not isinstance(tenant_id, str) or not tenant_id:
        raise ValueError('tenant')
    selected = []
    for cert in certificates:
        if not isinstance(cert, dict) or 'tenant_id' not in cert or 'status' not in cert or ('component_id' not in cert):
            raise ValueError('certificate')
        if cert['tenant_id'] == tenant_id:
            selected.append(cert)
    return {'tenant_id': tenant_id, 'total': len(selected), 'certified': sum((x['status'] == 'certified' for x in selected)), 'rejected': sum((x['status'] == 'rejected' for x in selected)), 'incomplete': sum((x['status'] == 'incomplete' for x in selected)), 'components': sorted({x['component_id'] for x in selected})}

