import hashlib
import hmac
import os
from datetime import date
from math import isfinite

def _password_record(password):
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def _password_matches(password, record):
    salt_text, digest_text = record.split('$', 1)
    salt = bytes.fromhex(salt_text)
    actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return hmac.compare_digest(actual.hex(), digest_text)

def register_user(users: dict, username: str, password: str, district: str) -> None:
    if not isinstance(username, str) or not username.strip() or (not isinstance(district, str)) or (not district.strip()):
        raise ValueError('invalid user')
    if not isinstance(password, str) or len(password) < 4 or username.strip() in users:
        raise ValueError('invalid user')
    name = username.strip()
    users[name] = {'username': name, 'district': district.strip(), 'password': _password_record(password)}

def authenticate(users: dict, username: str, password: str) -> dict | None:
    record = users.get(username)
    if record is None or not isinstance(password, str) or (not _password_matches(password, record['password'])):
        return None
    return {'username': record['username'], 'district': record['district']}

def add_hearing(hearings: dict, case_id: str, district: str, hearing_date: str, acres: float, decision: str) -> None:
    if not isinstance(case_id, str) or not case_id.strip() or (not isinstance(district, str)) or (not district.strip()):
        raise ValueError('invalid hearing')
    try:
        parsed = date.fromisoformat(hearing_date)
    except (TypeError, ValueError):
        raise ValueError('invalid hearing')
    if case_id.strip() in hearings or isinstance(acres, bool) or (not isinstance(acres, (int, float))) or (not isfinite(acres)) or (acres <= 0) or (decision not in {'approved', 'denied', 'continued'}):
        raise ValueError('invalid hearing')
    hearings[case_id.strip()] = {'district': district.strip(), 'date': parsed.isoformat(), 'acres': float(acres), 'decision': decision}

def hearing_summary(hearings: dict, district: str, start: str, end: str) -> list[dict]:
    if not isinstance(district, str) or not district.strip():
        raise ValueError('invalid range')
    try:
        first, last = (date.fromisoformat(start), date.fromisoformat(end))
    except (TypeError, ValueError):
        raise ValueError('invalid range')
    if first > last:
        raise ValueError('invalid range')
    grouped = {}
    for item in hearings.values():
        when = date.fromisoformat(item['date'])
        if item['district'] == district.strip() and first <= when <= last:
            month = when.strftime('%Y-%m')
            bucket = grouped.setdefault(month, {'month': month, 'hearings': 0, 'approved_acres': 0.0, 'denied_acres': 0.0, 'continued_acres': 0.0, 'total_acres': 0.0})
            bucket['hearings'] += 1
            key = item['decision'] + '_acres'
            bucket[key] += item['acres']
            bucket['total_acres'] += item['acres']
    result = []
    for month in sorted(grouped):
        item = grouped[month]
        for key in ('approved_acres', 'denied_acres', 'continued_acres', 'total_acres'):
            item[key] = round(item[key], 2)
        result.append(item)
    return result

