import csv
import math
import os

def write_material_summary(records: list[dict], relative_name: str, base_dir: str, min_temperature: float=float('-inf')) -> str:
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    if not isinstance(relative_name, str) or not relative_name or (not relative_name.endswith('.csv')):
        raise ValueError('invalid file name')
    if not isinstance(min_temperature, (int, float)) or isinstance(min_temperature, bool) or math.isnan(min_temperature) or (min_temperature == float('inf')):
        raise ValueError('invalid temperature threshold')
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        if not isinstance(record.get('material'), str) or not record['material']:
            raise ValueError('invalid material')
        for key in ('temperature', 'strength'):
            value = record.get(key)
            if not isinstance(value, (int, float)) or isinstance(value, bool) or (not math.isfinite(value)):
                raise ValueError('invalid measurement')
    groups = {}
    for record in records:
        if record['temperature'] >= min_temperature:
            groups.setdefault(record['material'], []).append(record)
    summary = []
    for material, items in groups.items():
        average = sum((item['strength'] for item in items)) / len(items)
        summary.append((material, len(items), average, max((item['temperature'] for item in items))))
    summary.sort(key=lambda row: (-row[2], row[0]))
    base = os.path.realpath(base_dir)
    target = os.path.realpath(os.path.join(base, relative_name))
    if os.path.commonpath((base, target)) != base:
        raise ValueError('path outside base directory')
    os.makedirs(os.path.dirname(target), exist_ok=True)
    with open(target, 'w', newline='') as handle:
        writer = csv.writer(handle, lineterminator='\n')
        writer.writerow(['material', 'count', 'average_strength', 'max_temperature'])
        for material, count, average, maximum in summary:
            writer.writerow([material, count, f'{average:.2f}', maximum])
    return target

