from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from lxml import etree

def inventory_report(xml_text: str, page: int=1, page_size: int=10) -> list[dict[str, object]]:
    if not isinstance(xml_text, str):
        raise ValueError('xml_text must be a string')
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('invalid page size')
    try:
        parser = etree.XMLParser(resolve_entities=False, load_dtd=False, no_network=True)
        root = etree.fromstring(xml_text.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'inventory':
        raise ValueError('invalid root')
    groups = {}
    for item in root:
        if item.tag != 'item':
            continue
        attrs = item.attrib
        if any((name not in attrs for name in ('sku', 'quantity', 'unit_price', 'active'))):
            raise ValueError('missing attribute')
        sku = attrs['sku']
        if not sku or attrs['active'] not in ('true', 'false'):
            raise ValueError('invalid attribute')
        try:
            quantity = int(attrs['quantity'])
            price = Decimal(attrs['unit_price'])
        except (ValueError, InvalidOperation) as exc:
            raise ValueError('invalid number') from exc
        if quantity < 0 or price < 0 or price.as_tuple().exponent < -2:
            raise ValueError('invalid number')
        if attrs['active'] == 'true':
            if sku not in groups:
                groups[sku] = [0, Decimal('0')]
            groups[sku][0] += quantity
            groups[sku][1] += quantity * price
    results = [{'sku': sku, 'quantity': data[0], 'value': str(data[1].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))} for sku, data in groups.items()]
    results.sort(key=lambda row: (-int(row['quantity']), str(row['sku'])))
    start = (page - 1) * page_size
    return results[start:start + page_size]

