from datetime import date
import secrets

def _day(value):
    try:
        return date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def build_client_report(client_id: str, entries: list[dict], as_of: str) -> dict:
    if not isinstance(client_id, str) or not isinstance(as_of, str):
        raise TypeError('client_id and as_of must be strings')
    cutoff = _day(as_of)
    state = {}
    cash = {}
    for row in entries:
        try:
            when = _day(row['date'])
            kind = row['type']
            asset = row['asset']
            units = row['units']
            price = row['price']
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid entry')
        if not isinstance(asset, str) or not asset:
            raise ValueError('invalid asset')
        if kind not in ('buy', 'sell', 'dividend', 'fee'):
            raise ValueError('invalid type')
        if kind in ('buy', 'sell') and units <= 0:
            raise ValueError('invalid units')
        if kind in ('dividend', 'fee') and units != 0:
            raise ValueError('invalid units')
        if when > cutoff:
            continue
        month = row['date'][:7]
        if kind == 'buy':
            state.setdefault(asset, [0.0, 0.0])
            state[asset][0] += units
            state[asset][1] = float(price)
            cash[month] = cash.get(month, 0.0) - units * price
        elif kind == 'sell':
            state.setdefault(asset, [0.0, 0.0])
            state[asset][0] -= units
            state[asset][1] = float(price)
            cash[month] = cash.get(month, 0.0) + units * price
        elif kind == 'dividend':
            cash[month] = cash.get(month, 0.0) + price
        else:
            cash[month] = cash.get(month, 0.0) - price
    positions = []
    for asset, (units, price) in state.items():
        if units != 0:
            value = units * price
            positions.append({'asset': asset, 'units': round(units, 2), 'price': round(price, 2), 'value': round(value, 2)})
    positions.sort(key=lambda x: (-x['value'], x['asset']))
    return {'client_id': client_id, 'as_of': as_of, 'positions': positions, 'monthly_cashflow': {k: round(cash[k], 2) for k in sorted(cash)}, 'total_value': round(sum((x['value'] for x in positions)), 2)}

def generate_invite_code(existing: set[str] | list[str]=()) -> str:
    try:
        used = set(existing)
    except TypeError:
        raise TypeError('existing must be iterable')
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    for _ in range(100):
        code = ''.join((secrets.choice(alphabet) for _ in range(12)))
        if code not in used:
            return code
    raise RuntimeError('unable to generate code')

def create_client_report_bundle(client_id: str, entries: list[dict], as_of: str, existing_codes: set[str] | list[str]=()) -> dict:
    return {'report': build_client_report(client_id, entries, as_of), 'invite_code': generate_invite_code(existing_codes)}

