import csv
import datetime
import os
import re
import tempfile
KINDS = ('filing', 'hearing', 'order', 'note')

def _split_record(line):
    fields = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            if char not in '\\|':
                raise ValueError('invalid escape')
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('dangling escape')
    fields.append(''.join(current))
    if len(fields) != 3:
        raise ValueError('invalid record')
    return fields

def parse_docket(text: str) -> list[dict]:
    result = []
    for position, raw in enumerate(text.splitlines()):
        if not raw.strip():
            continue
        date, kind, description = _split_record(raw)
        if not re.fullmatch('\\d{4}-\\d{2}-\\d{2}', date):
            raise ValueError('invalid date')
        try:
            datetime.date.fromisoformat(date)
