def _tax(income, year, status):
    if status == 'married':
        factor = 2
    elif status == 'single':
        factor = 1
    else:
        raise ValueError('invalid filing status')
    b = {2023: (1100000, 4472500, 9537500), 2024: (1160000, 4715000, 10052500)}[year]
    bounds = [x * factor for x in b]
    total = 0
    previous = 0
    for limit, rate in zip(bounds, (10, 12, 22)):
        total += min(max(income - previous, 0), limit - previous) * rate
        previous = limit
    total += max(income - previous, 0) * 24
    return (total + 50) // 100

def calculate_payroll_tax(requester: dict, payroll: dict, tax_year: int, pay_period: int) -> list[dict]:
    if tax_year not in (2023, 2024):
        raise ValueError('unsupported year')
    if not isinstance(pay_period, int) or isinstance(pay_period, bool):
        raise TypeError('pay period must be an integer')
    if not 1 <= pay_period <= 26:
        raise ValueError('invalid pay period')
    if requester.get('tenant_id') != payroll.get('tenant_id') and 'payroll_admin' not in requester.get('roles', []):
        raise PermissionError('not authorized')
    if requester.get('id') != payroll.get('owner_user_id') and 'payroll_admin' not in requester.get('roles', []):
        raise PermissionError('not authorized')
    required = ('employee_id', 'name', 'filing_status', 'gross_cents', 'pretax_cents', 'ytd_taxable_cents')
    result = []
