        if any((not isinstance(x, int) or isinstance(x, bool) or x < 0 for x in (g, p, y))) or p > g:
            raise ValueError('invalid amount')
        taxable = g - p
        annual = _tax(y + taxable, tax_year, e['filing_status'])
        old = _tax(y, tax_year, e['filing_status'])
        result.append({'employee_id': e['employee_id'], 'name': e['name'], 'taxable_cents': taxable, 'annualized_tax_cents': annual, 'current_withholding_cents': annual - old, 'filing_status': e['filing_status']})
    return sorted(result, key=lambda r: r['employee_id'])

