import ast
import datetime
import math

def _eval(text, names):
    try:
        tree = ast.parse(text, mode='eval').body

        def go(n):
            if isinstance(n, ast.Constant) and isinstance(n.value, (int, float, str, bool)):
                return n.value
            if isinstance(n, ast.Name) and n.id in names:
                return names[n.id]
            if isinstance(n, ast.UnaryOp) and isinstance(n.op, (ast.UAdd, ast.USub, ast.Not)):
                v = go(n.operand)
                return +v if isinstance(n.op, ast.UAdd) else -v if isinstance(n.op, ast.USub) else not v
            if isinstance(n, ast.BoolOp) and isinstance(n.op, (ast.And, ast.Or)):
                v = go(n.values[0])
                for x in n.values[1:]:
                    if isinstance(n.op, ast.And) and (not v) or (isinstance(n.op, ast.Or) and v):
                        return v
                    v = go(x)
                return v
            if isinstance(n, ast.BinOp) and isinstance(n.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
                a, b = (go(n.left), go(n.right))
                return a + b if isinstance(n.op, ast.Add) else a - b if isinstance(n.op, ast.Sub) else a * b if isinstance(n.op, ast.Mult) else a / b
            if isinstance(n, ast.Compare):
                a = go(n.left)
                for op, q in zip(n.ops, n.comparators):
                    b = go(q)
                    ok = a == b if isinstance(op, ast.Eq) else a != b if isinstance(op, ast.NotEq) else a < b if isinstance(op, ast.Lt) else a <= b if isinstance(op, ast.LtE) else a > b if isinstance(op, ast.Gt) else a >= b if isinstance(op, ast.GtE) else None
                    if ok is None or not ok:
                        return False
                    a = b
                return True
            if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and (n.func.id in ('min', 'max', 'round')) and (not n.keywords):
                return {'min': min, 'max': max, 'round': round}[n.func.id](*[go(x) for x in n.args])
            raise ValueError()
        return go(tree)
    except Exception as e:
        raise ValueError() from e

def rank_deliveries(records: list[dict], filter_expr: str, score_expr: str, as_of: str) -> list[dict]:
    try:
        end = datetime.datetime.fromisoformat(as_of.replace('Z', '+00:00'))
        if end.tzinfo is None:
            end = end.replace(tzinfo=datetime.timezone.utc)
        seen, out = (set(), [])
        for r in records:
            if not isinstance(r, dict) or not isinstance(r.get('id'), str) or (not r['id']) or (r['id'] in seen):
                raise ValueError()
            seen.add(r['id'])
            ev = r.get('events')
            if not isinstance(ev, list):
                raise ValueError()
            parsed = []
            for e in ev:
                if not isinstance(e, dict) or e.get('type') not in ('attempt', 'delivered', 'failed') or (not isinstance(e.get('at'), str)):
                    raise ValueError()
                t = datetime.datetime.fromisoformat(e['at'].replace('Z', '+00:00'))
                if t.tzinfo is None:
                    t = t.replace(tzinfo=datetime.timezone.utc)
                parsed.append((t, e['type'], e['at']))
            parsed.sort(key=lambda x: x[0])
            status = parsed[-1][1] if parsed else 'pending'
            delivered = [x for x in parsed if x[1] == 'delivered']
            latest = parsed[-1][0] if parsed else end
            names = {'attempts': sum((x[1] == 'attempt' for x in parsed)), 'delivered': bool(delivered), 'failed': status == 'failed', 'age_days': (end - latest).total_seconds() / 86400, 'status': status}
            filt = _eval(filter_expr, names)
            if not isinstance(filt, bool):
                raise ValueError()
            if not filt:
                continue
            score = _eval(score_expr, names)
            if isinstance(score, bool) or not isinstance(score, (int, float)) or (not math.isfinite(score)):
                raise ValueError()
            out.append({'id': r['id'], 'status': status, 'attempts': names['attempts'], 'delivered_at': delivered[-1][2] if delivered else None, 'score': score})
        return sorted(out, key=lambda x: (-x['score'], x['id']))
    except ValueError:
        raise
    except Exception as e:
        raise ValueError() from e

