from datetime import datetime, timezone
import math

def parse_observation(line: str) -> dict:
    fields = []
    cur = []
    escaped = False
    for ch in line:
        if escaped:
            cur.append(ch)
            escaped = False
        elif ch == '\\':
            escaped = True
        elif ch == '|':
            fields.append(''.join(cur))
            cur = []
        else:
            cur.append(ch)
    if escaped:
        raise ValueError('invalid escape')
    fields.append(''.join(cur))
    if len(fields) != 5 or not fields[0]:
        raise ValueError('invalid record')
    try:
        stamp = datetime.fromisoformat(fields[1].replace('Z', '+00:00'))
        if stamp.tzinfo is None or fields[1][-1] != 'Z':
            raise ValueError
        stamp = stamp.astimezone(timezone.utc)
        lat, lon, value = map(float, fields[2:])
    except Exception as exc:
        raise ValueError('invalid record') from exc
    if not all((math.isfinite(x) for x in (lat, lon, value))) or not -90 <= lat <= 90 or (not -180 <= lon <= 180):
        raise ValueError('invalid numbers')
    return {'id': fields[0], 'timestamp': stamp, 'lat': lat, 'lon': lon, 'value': value}

def haversine_meters(lat1: float, lon1: float, lat2: float, lon2: float) -> float:
    vals = (lat1, lon1, lat2, lon2)
    if not all((math.isfinite(x) for x in vals)) or not -90 <= lat1 <= 90 or (not -90 <= lat2 <= 90) or (not -180 <= lon1 <= 180) or (not -180 <= lon2 <= 180):
        raise ValueError('invalid coordinates')
    r = 6371000
    p1, p2 = (math.radians(lat1), math.radians(lat2))
    a = math.sin((p2 - p1) / 2) ** 2 + math.cos(p1) * math.cos(p2) * math.sin(math.radians(lon2 - lon1) / 2) ** 2
    return 2 * r * math.asin(math.sqrt(a))

def build_alert_report(requester: dict, alerts: list[dict], observation_lines: list[str], end_time: datetime) -> list[dict]:
    if end_time.tzinfo is None:
        raise ValueError('timezone required')
    end = end_time.astimezone(timezone.utc)
    observations = [parse_observation(x) for x in observation_lines]
    if len({a.get('id') for a in alerts}) != len(alerts):
        raise ValueError('duplicate alert')
    output = []
    for a in alerts:
        try:
            center = a['center']
            radius = float(a['radius_meters'])
            window = float(a['window_minutes'])
            threshold = a['threshold']
            priority = a['priority']
            if not isinstance(threshold, int) or isinstance(threshold, bool) or threshold <= 0 or (radius < 0) or (window < 0) or (not all((math.isfinite(x) for x in (radius, window, float(priority))))):
                raise ValueError
            haversine_meters(float(center[0]), float(center[1]), float(center[0]), float(center[1]))
        except Exception as exc:
            raise ValueError('invalid alert') from exc
        allowed = a['tenant_id'] == requester['tenant_id'] and (a['owner_id'] == requester['id'] or 'manager' in requester.get('roles', []))
        if not allowed:
            raise PermissionError('alert access denied')
        start = end.timestamp() - window * 60
        matches = [o for o in observations if start <= o['timestamp'].timestamp() <= end.timestamp() and haversine_meters(float(center[0]), float(center[1]), o['lat'], o['lon']) <= radius]
        latest = max((o['timestamp'] for o in matches), default=None)
        output.append({'id': a['id'], 'priority': priority, 'active': len(matches) >= threshold, 'count': len(matches), 'total_value': round(sum((o['value'] for o in matches)), 2), 'latest_timestamp': latest.isoformat().replace('+00:00', 'Z') if latest else None})
    return sorted(output, key=lambda x: (-x['priority'], x['id']))

