import hashlib
import hmac
import json

def summarize_signed_corpus(document: str, signature: str, key: bytes, page: int=1, page_size: int=10) -> dict:
    if not isinstance(key, bytes):
        raise TypeError('key must be bytes')
    if not key:
        raise TypeError('key must not be empty')
    if not isinstance(page, int) or isinstance(page, bool) or page <= 0:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size <= 0:
        raise ValueError('invalid page size')
    expected = hmac.new(key, document.encode('utf-8'), hashlib.sha256).hexdigest()
    if not isinstance(signature, str) or not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    try:
        value = json.loads(document)
    except (TypeError, json.JSONDecodeError):
        raise ValueError('invalid document')
    if not isinstance(value, dict) or not isinstance(value.get('text'), str) or (not isinstance(value.get('annotations'), list)):
        raise ValueError('invalid document')
    text = value['text']
    groups = {}
    total = 0
    for annotation in value['annotations']:
        if not isinstance(annotation, dict) or not isinstance(annotation.get('label'), str) or (not annotation['label']):
            raise ValueError('invalid annotation')
        start = annotation.get('start')
        end = annotation.get('end')
        if isinstance(start, bool) or isinstance(end, bool) or (not isinstance(start, int)) or (not isinstance(end, int)) or (start < 0) or (start > end) or (end > len(text)):
            raise ValueError('invalid annotation')
        length = end - start
        label = annotation['label']
        if label not in groups:
            groups[label] = [0, 0]
        groups[label][0] += 1
        groups[label][1] += length
        total += length
    labels = [{'label': label, 'count': data[0], 'characters': data[1]} for label, data in sorted(groups.items(), key=lambda item: (-item[1][0], item[0]))]
    pages = (len(labels) + page_size - 1) // page_size
    if page > max(1, pages):
        raise IndexError('page out of range')
    begin = (page - 1) * page_size
    return {'total_annotations': len(value['annotations']), 'total_characters': total, 'page': page, 'page_size': page_size, 'pages': pages, 'labels': labels[begin:begin + page_size]}

