import os
import tempfile

def make_file(contents, name='bookings.txt'):
    directory = tempfile.TemporaryDirectory()
    path = os.path.join(directory.name, name)
    with open(path, 'w', encoding='utf-8') as handle:
        handle.write(contents)
    return (directory, path)

def test_empty_file_returns_empty_list():
    directory, path = make_file('\n  \n')
    try:
        assert summarize_bookings(path) == []
    finally:
        directory.cleanup()

def test_results_are_sorted_and_pagination_is_one_based():
    directory, path = make_file('Zebra|1|1\nAlpha|1|2\nMiddle|1|3\nBeta|1|4\n')
    try:
        assert summarize_bookings(path, page=1, page_size=2) == [('Alpha', 1, 2.0), ('Beta', 1, 4.0)]
        assert summarize_bookings(path, page=2, page_size=2) == [('Middle', 1, 3.0), ('Zebra', 1, 1.0)]
        assert summarize_bookings(path, page=3, page_size=2) == []
    finally:
        directory.cleanup()

def test_blank_lines_are_ignored_and_integer_types_are_preserved():
    directory, path = make_file('\nFilm|4|7.25\n\n')
    try:
        result = summarize_bookings(path)
        assert result == [('Film', 4, 29.0)]
        assert type(result[0][1]) is int
        assert type(result[0][2]) is float
    finally:
        directory.cleanup()

def test_malformed_records_raise_value_error():
    cases = ['Movie|1\n', '|1|4.00\n', 'Movie|zero|4.00\n', 'Movie|0|4.00\n', 'Movie|1|-1.00\n', 'Movie|1|not-a-price\n', 'Movie|1|2|extra\n']
    for contents in cases:
        directory, path = make_file(contents)
        try:
            try:
                summarize_bookings(path)
            except ValueError:
                pass
            else:
                assert False, contents
        finally:
            directory.cleanup()

def test_invalid_pagination_raises_value_error():
    directory, path = make_file('Movie|1|5.00\n')
    try:
        for page, page_size in [(0, 1), (-1, 1), (1, 0), (1, -2), (1.5, 1), (1, 2.0)]:
            try:
                summarize_bookings(path, page=page, page_size=page_size)
            except ValueError:
                pass
            else:
                assert False, (page, page_size)
    finally:
        directory.cleanup()

def test_missing_file_raises_file_not_found():
    with tempfile.TemporaryDirectory() as directory:
        path = os.path.join(directory, 'does-not-exist.txt')
        try:
            summarize_bookings(path)
        except FileNotFoundError:
            pass
        else:
            assert False

def test_page_size_boundary_and_decimal_aggregation():
    directory, path = make_file('A|1|0.10\nA|1|0.20\nB|2|1.005\nC|1|3.333\n')
    try:
        assert summarize_bookings(path, page=1, page_size=1) == [('A', 2, 0.3)]
        assert summarize_bookings(path, page=2, page_size=1) == [('B', 2, 2.01)]
        assert summarize_bookings(path, page=3, page_size=1) == [('C', 1, 3.33)]
