        raise ValueError('invalid event')
    if not isinstance(event['date'], str) or len(event['date']) != 10 or event['date'][4] != '-' or (event['date'][7] != '-'):
        raise ValueError('invalid event')
    try:
        date.fromisoformat(event['date'])
    except ValueError:
        raise ValueError('invalid event')

def process_registry_webhook(payload: bytes, headers: dict[str, str], secret: bytes) -> dict[str, object]:
    supplied = _signature(headers)
    expected = 'sha256=' + hmac.new(secret, payload, hashlib.sha256).hexdigest()
    if not isinstance(supplied, str) or len(supplied) != 71 or (not supplied.startswith('sha256=')) or any((c not in '0123456789abcdef' for c in supplied[7:])) or (not hmac.compare_digest(supplied, expected)):
        raise PermissionError('invalid signature')
    try:
        body = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    if not isinstance(body, dict) or not isinstance(body.get('events'), list):
        raise ValueError('invalid payload')
    seen = set()
    patients = set()
    groups = {}
    for event in body['events']:
        _check_event(event)
        if event['id'] in seen:
            continue
        seen.add(event['id'])
        patients.add(event['patient_id'])
        item = groups.setdefault(event['vaccine'], {'vaccine': event['vaccine'], 'count': 0, 'latest': event['date']})
        item['count'] += 1
        if event['date'] > item['latest']:
            item['latest'] = event['date']
    result = list(groups.values())
    result.sort(key=lambda x: (-x['count'], x['vaccine']))
    return {'accepted': len(seen), 'patients': len(patients), 'by_vaccine': result}

