from datetime import datetime
import re

def _unescape(value):
    out = []
    i = 0
    while i < len(value):
        if value[i] == '\\\\':
            i += 1
            if i == len(value) or value[i] not in 'n:\\\\':
                raise ValueError('bad escape')
            out.append({'n': '\n', ':': ':', '\\\\': '\\'}[value[i]])
        else:
            out.append(value[i])
        i += 1
    return ''.join(out)

def parse_report(raw: str) -> dict:
    if not raw:
        raise ValueError('empty')
    vals = {}
    names = {'from': 'sender', 'to': 'recipient', 'subject': 'subject', 'received': 'received', 'body': 'body', 'links': 'links'}
    for line in raw.splitlines():
        if ':' not in line:
            raise ValueError('line')
        key, value = line.split(':', 1)
        key = key.strip().lower()
        if key not in names or names[key] in vals:
            raise ValueError('field')
        vals[names[key]] = _unescape(value.strip())
    if any((x not in vals for x in ('sender', 'recipient', 'subject', 'received'))):
        raise ValueError('missing')
    try:
        dt = datetime.fromisoformat(vals['received'].replace('Z', '+00:00'))
        if not vals['received'].endswith('Z') or dt.tzinfo is None:
            raise ValueError
        vals['received'] = dt.strftime('%Y-%m-%dT%H:%M:%SZ')
    except ValueError:
        raise ValueError('timestamp')
    vals.setdefault('body', '')
    vals['links'] = [x.strip() for x in vals.get('links', '').split(',') if x.strip()]
    return vals

def add_report(reports: list[dict], raw: str, reporter: dict) -> dict:
    item = parse_report(raw).copy()
    item.update(id='r' + str(len(reports) + 1), owner=reporter['id'], tenant=reporter['tenant'], status='new')
    reports.append(item)
    return item

def review_queue(reports: list[dict], requester: dict, limit: int=10) -> list[dict]:
    if limit < 0:
        raise ValueError('limit')
    if not limit:
        return []
    allowed = [r for r in reports if r.get('status') in ('new', 'in_review') and (r.get('owner') == requester.get('id') or ('reviewer' in requester.get('roles', []) and r.get('tenant') == requester.get('tenant')))]

    def sev(r):
        text = (r.get('subject', '') + ' ' + r.get('body', '')).lower()
        for word, rank in (('credential', 4), ('password', 4), ('urgent', 3), ('verify', 3), ('login', 3), ('invoice', 2), ('payment', 2)):
            if re.search('\\\\b' + word + '\\\\b', text):
                return rank
        return 1
    ordered = sorted(allowed, key=lambda r: (-sev(r), r.get('received', ''), r.get('id', '')))
    names = {4: 'critical', 3: 'high', 2: 'medium', 1: 'low'}
    return [dict(r, severity=names[sev(r)]) for r in ordered[:limit]]

