import os

def make_credential(password: str) -> str:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return 'h:' + base64.b64encode(salt).decode() + ':' + base64.b64encode(digest).decode()

def verify_credential(stored: str, password: str) -> bool:
    if not isinstance(stored, str) or not isinstance(password, str):
        raise TypeError('arguments must be strings')
    parts = stored.split(':')
    if len(parts) != 3 or parts[0] != 'h':
        raise ValueError('malformed credential')
    try:
        salt = base64.b64decode(parts[1], validate=True)
        expected = base64.b64decode(parts[2], validate=True)
    except Exception as exc:
        raise ValueError('malformed credential') from exc
    actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def docket_page(records: list[dict], status: str, page: int, page_size: int) -> dict:
    if status not in {'pending', 'granted', 'abandoned'}:
        raise ValueError('invalid status')
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
