import re
import tempfile
_HEADER = ['stop_id', 'zone', 'bags', 'priority', 'window']

def _time(value):
    if not re.fullmatch('\\d{2}:\\d{2}', value):
        raise ValueError('invalid time')
    h, m = map(int, value.split(':'))
    if h > 23 or m > 59:
        raise ValueError('invalid time')
    return h * 60 + m

def schedule_manifest(manifest: str, capacity: int) -> list[dict]:
    if isinstance(capacity, bool) or not isinstance(capacity, int) or capacity <= 0:
        raise ValueError('invalid capacity')
    reader = csv.DictReader(io.StringIO(manifest))
    if reader.fieldnames != _HEADER:
        raise ValueError('invalid header')
    seen = set()
    groups = {}
    for row in reader:
        if None in row or any((v is None for v in row.values())):
            raise ValueError('invalid row')
        ident = row['stop_id'].strip()
        zone = row['zone'].strip()
        if not ident or not zone or ident in seen:
            raise ValueError('invalid identifier')
        try:
            bags = int(row['bags'])
            priority = int(row['priority'])
        except Exception as exc:
            raise ValueError('invalid number') from exc
        if bags < 0:
            raise ValueError('invalid bags')
        parts = row['window'].split('-')
        if len(parts) != 2:
            raise ValueError('invalid window')
        start, end = (_time(parts[0]), _time(parts[1]))
        if start >= end:
            raise ValueError('invalid window')
        item = {'id': ident, 'bags': bags, 'priority': priority, 'start': start, 'end': end, 'window': row['window']}
        seen.add(ident)
        groups.setdefault(zone, []).append(item)
    result = []
    for zone in sorted(groups):
        items = sorted(groups[zone], key=lambda x: (x['start'], -x['priority'], x['id']))
        current = []
        total = 0
        number = 1
        for item in items + [None]:
            if item is not None and item['bags'] <= capacity and (not current or total + item['bags'] <= capacity):
                current.append(item)
                total += item['bags']
                continue
            if item is not None and item['bags'] > capacity:
                raise ValueError('stop exceeds capacity')
            if current:
                result.append({'route': f'{zone}-{number}', 'zone': zone, 'stops': [x['id'] for x in current], 'total_bags': total, 'window_start': f"{min((x['start'] for x in current)) // 60:02d}:{min((x['start'] for x in current)) % 60:02d}", 'window_end': f"{max((x['end'] for x in current)) // 60:02d}:{max((x['end'] for x in current)) % 60:02d}", '_records': current})
                number += 1
            current = []
            total = 0
            if item is not None:
                current = [item]
                total = item['bags']
    return result

def export_schedule(routes: list[dict], destination: str) -> None:
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent, prefix='.routes-', suffix='.tmp', text=True)
    try:
        with os.fdopen(fd, 'w', newline='') as handle:
            writer = csv.writer(handle)
            writer.writerow(['route', 'zone', 'stop_order', 'stop_id', 'bags', 'priority', 'window'])
            for route in routes:
                records = route.get('_records')
                if records is None:
                    raise ValueError('invalid route')
                for index, item in enumerate(records, 1):
                    writer.writerow([route['route'], route['zone'], index, item['id'], item['bags'], item['priority'], item['window']])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
