        params.extend([term, term])
    if status is not None:
        clauses.append('status = ?')
        params.append(status)
    direction = 'DESC' if descending else 'ASC'
    sql = 'SELECT id, project_id, title, description, status, amount, submitted_at FROM change_orders WHERE ' + ' AND '.join(clauses) + ' ORDER BY ' + sort_by + ' ' + direction + ', id ASC'
    conn.row_factory = sqlite3.Row
    return [dict(row) for row in conn.execute(sql, params).fetchall()]

def summarize_change_orders(conn: sqlite3.Connection, project_id: int) -> dict:
    statuses = ['proposed', 'submitted', 'approved', 'rejected']
    result = {s: {'count': 0, 'amount': 0.0} for s in statuses}
    rows = conn.execute('SELECT status, COUNT(*), COALESCE(SUM(amount), 0) FROM change_orders WHERE project_id = ? GROUP BY status', (project_id,)).fetchall()
    for status, count, amount in rows:
        if status in result:
            result[status] = {'count': count, 'amount': round(float(amount), 2)}
    count, amount = conn.execute('SELECT COUNT(*), COALESCE(SUM(amount), 0) FROM change_orders WHERE project_id = ?', (project_id,)).fetchone()
    return {'count': count, 'amount': round(float(amount), 2), 'by_status': result}

def transition_change_order(conn: sqlite3.Connection, order_id: int, new_status: str, expected_status: Optional[str]=None) -> bool:
    statuses = {'proposed', 'submitted', 'approved', 'rejected'}
    if new_status not in statuses or (expected_status is not None and expected_status not in statuses):
        raise ValueError('invalid status')
    current = conn.execute('SELECT status FROM change_orders WHERE id = ?', (order_id,)).fetchone()
    if current is None:
        return False
    old = current[0]
    if expected_status is not None and old != expected_status:
        return False
    allowed = {'proposed': {'submitted', 'rejected'}, 'submitted': {'approved', 'rejected'}}
    if new_status not in allowed.get(old, set()):
        return False
    cursor = conn.execute('UPDATE change_orders SET status = ? WHERE id = ?', (new_status, order_id))
