import hmac
import json
import math

def refresh_dashboard(payload: str, token: str, expected_token: str, page: int=1, page_size: int=20) -> list[dict]:
    if not isinstance(token, str) or not isinstance(expected_token, str):
        raise TypeError('tokens must be strings')
    if not hmac.compare_digest(token, expected_token):
        raise PermissionError('invalid token')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    try:
        document = json.loads(payload)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(document, dict) or not isinstance(document.get('rows'), list):
        raise ValueError('rows must be a list')
    groups = {}
    for row in document['rows']:
        if not isinstance(row, dict):
            raise ValueError('invalid row')
        region = row.get('region')
        revenue = row.get('revenue')
        orders = row.get('orders')
        if not isinstance(region, str) or not region or isinstance(revenue, bool) or (not isinstance(revenue, (int, float))) or (not math.isfinite(revenue)) or (revenue < 0) or isinstance(orders, bool) or (not isinstance(orders, int)) or (orders < 0):
            raise ValueError('invalid row')
        if region not in groups:
            groups[region] = [0.0, 0]
        groups[region][0] += revenue
        groups[region][1] += orders
    result = []
    for region, (revenue, orders) in groups.items():
        rounded_revenue = round(revenue, 2)
        result.append({'region': region, 'revenue': rounded_revenue, 'orders': orders, 'avg_order_value': round(revenue / orders, 2) if orders else 0.0})
    result.sort(key=lambda item: (-item['revenue'], item['region']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

