def _text(value):
    if value is None:
        raise ValueError()
    return value.strip()

def _integer(value):
    try:
        return int(_text(value))
    except (TypeError, ValueError):
        raise ValueError()

def parse_progress(xml_text: str) -> list[dict]:
    try:
        root = ET.fromstring(xml_text)
    except Exception as exc:
        raise ValueError() from exc
    if root.tag != 'progress':
        raise ValueError()
    result = []
    for learner in root:
        if learner.tag != 'learner':
            raise ValueError()
        learner_id = _text(learner.attrib.get('id'))
        if not learner_id:
            raise ValueError()
        for session in learner:
            if session.tag != 'session' or (session.text and session.text.strip()):
                raise ValueError()
            date = _text(session.attrib.get('date'))
            try:
                if datetime.date.fromisoformat(date).isoformat() != date:
                    raise ValueError()
            except ValueError as exc:
                raise ValueError() from exc
            for exercise in session:
                if exercise.tag != 'exercise' or (exercise.text and exercise.text.strip()):
                    raise ValueError()
                lesson = _text(exercise.attrib.get('lesson'))
                if not lesson:
                    raise ValueError()
                correct = _integer(exercise.attrib.get('correct'))
                total = _integer(exercise.attrib.get('total'))
                seconds = _integer(exercise.attrib.get('seconds'))
                if total <= 0 or correct < 0 or correct > total or (seconds < 0):
                    raise ValueError()
                result.append({'learner': learner_id, 'date': date, 'lesson': lesson, 'correct': correct, 'total': total, 'seconds': seconds})
    return result

def summarize_progress(records: list[dict]) -> list[dict]:
    groups = {}
