        nums = [record[x] for x in ('correct', 'total', 'seconds')]
        if any((isinstance(x, bool) or not isinstance(x, int) for x in nums)):
            raise ValueError()
        correct, total, seconds = nums
        if total <= 0 or correct < 0 or correct > total or (seconds < 0):
            raise ValueError()
        key = (learner, lesson)
        if key not in groups:
            groups[key] = [0, 0, 0, 0]
        groups[key][0] += 1
        groups[key][1] += correct
        groups[key][2] += total
        groups[key][3] += seconds
    result = []
