import os
from pathlib import Path

def save_application_document(base_dir: str, relative_name: str, content: bytes) -> str:
    if not isinstance(base_dir, str) or not isinstance(relative_name, str):
        raise TypeError('directory and name must be strings')
    if not isinstance(content, bytes):
        raise TypeError('content must be bytes')
    base = Path(base_dir).resolve()
    target = (base / relative_name).resolve()
    if target != base and base not in target.parents:
        raise ValueError('name is outside the base directory')
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(content)
    return str(target)

def allocate_subsidies(applications: list[dict], budget: int) -> list[dict]:
    if not isinstance(applications, list):
        raise TypeError('applications must be a list')
    if type(budget) is not int:
        raise TypeError('budget must be an integer')
    if budget < 0:
        raise ValueError('budget must be nonnegative')
    checked = []
    for item in applications:
        if not isinstance(item, dict):
            raise TypeError('each application must be a dictionary')
        for key in ('id', 'region', 'requested', 'score'):
            if key not in item:
                raise ValueError('missing application field')
        if not isinstance(item['id'], str) or not isinstance(item['region'], str):
            raise TypeError('id and region must be strings')
        if type(item['requested']) is not int or type(item['score']) is not int:
            raise TypeError('numeric fields must be integers')
        if item['requested'] < 0 or not 0 <= item['score'] <= 100:
            raise ValueError('invalid application values')
        checked.append(item)
    ordered = sorted(checked, key=lambda x: (-x['score'], x['id']))
    result = []
    remaining = budget
    for item in ordered:
        approved = min(item['requested'], remaining)
        remaining -= approved
        result.append({'id': item['id'], 'region': item['region'], 'score': item['score'], 'approved': approved})
    return result

