def parse_note(note: str) -> dict[str, object]:
    if not isinstance(note, str):
        raise TypeError('note')
    s = note.strip()
    if not s:
        return {'text': '', 'fields': {}}
    m = re.match('^(.*?)(?:\\s+([A-Za-z0-9_-]+=.*))?$', s)
    if not m:
        raise ValueError('note')
    text = m.group(1)
    tail = m.group(2)
    fields = {}
    if tail is None:
        return {'text': text, 'fields': fields}
    if not text:
        text = ''
