            raise ValueError('fields')
        while i < len(tail) and tail[i] == ' ':
            i += 1
        start = i
        while i < len(tail) and tail[i] not in '= ':
            i += 1
        if i == start or i >= len(tail) or tail[i] != '=':
            raise ValueError('field')
        key = tail[start:i]
