            while i < len(tail) and tail[i] != '"':
                if tail[i] == '\\':
                    i += 1
                    if i >= len(tail) or tail[i] not in '\\"':
                        raise ValueError('escape')
                out.append(tail[i])
                i += 1
            if i >= len(tail):
                raise ValueError('quote')
            i += 1
            value = ''.join(out)
            if i < len(tail) and tail[i] != ' ':
                raise ValueError('token')
        else:
