            value = tail[start:i]
            if not value:
                raise ValueError('value')
            if not re.fullmatch('\\d+', value) and '=' in value:
                raise ValueError('token')
        if key in fields:
            raise ValueError('duplicate')
        fields[key] = int(value) if isinstance(value, str) and value.isdigit() else value
    return {'text': text.strip(), 'fields': fields}

def _doc(project, ident):
    if not isinstance(project, dict) or not isinstance(ident, str):
        raise TypeError('argument')
    for d in project.get('documents', []):
