import ast
import math
import operator

def _evaluate(text, values):
    try:
        tree = ast.parse(text, mode='eval').body

        def visit(n):
            if isinstance(n, ast.Constant) and isinstance(n.value, (int, float, bool)):
                return n.value
            if isinstance(n, ast.Name) and n.id in values:
                return values[n.id]
            if isinstance(n, ast.UnaryOp) and isinstance(n.op, (ast.Not, ast.USub, ast.UAdd)):
                v = visit(n.operand)
                return not v if isinstance(n.op, ast.Not) else -v if isinstance(n.op, ast.USub) else +v
            if isinstance(n, ast.BinOp) and isinstance(n.op, (ast.Add, ast.Sub, ast.Mult, ast.Div, ast.Mod)):
                a, b = (visit(n.left), visit(n.right))
                return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv, ast.Mod: operator.mod}[type(n.op)](a, b)
            if isinstance(n, ast.BoolOp) and isinstance(n.op, (ast.And, ast.Or)):
                result = visit(n.values[0])
                for part in n.values[1:]:
                    if isinstance(n.op, ast.And):
                        if not result:
                            return result
                    elif result:
                        return result
                    result = visit(part)
                return result
            if isinstance(n, ast.Compare):
                left = visit(n.left)
                checks = []
                for op, right_node in zip(n.ops, n.comparators):
                    right = visit(right_node)
                    checks.append({ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}[type(op)](left, right))
                    left = right
                return all(checks)
            if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and (n.func.id in ('min', 'max', 'round')) and (not n.keywords):
                return {'min': min, 'max': max, 'round': round}[n.func.id](*[visit(x) for x in n.args])
            raise ValueError('invalid rule')
        return visit(tree)
    except Exception as exc:
        if isinstance(exc, ValueError):
            raise
        raise ValueError('invalid rule') from exc

def plan_orders(supplies: list[dict], rule: str, review_days: int=7) -> list[dict]:
    if not isinstance(review_days, int) or isinstance(review_days, bool) or review_days < 0:
        raise ValueError('invalid review_days')
    result = []
    for s in supplies:
        try:
            name, stock, use, lead, pack, cost, critical = (s[k] for k in ('name', 'stock', 'daily_use', 'lead_days', 'pack_size', 'unit_cost', 'critical'))
            if not isinstance(name, str) or not isinstance(stock, int) or stock < 0 or (use < 0) or (lead < 0) or (pack <= 0) or (cost < 0) or (not isinstance(critical, bool)):
                raise ValueError
            if not _evaluate(rule, {'stock': stock, 'daily_use': use, 'lead_days': lead, 'pack_size': pack, 'unit_cost': cost, 'critical': critical, 'min': min, 'max': max, 'round': round}):
                continue
            shortage = max(use * (lead + review_days) - stock, 0)
            quantity = math.ceil(shortage / pack) * pack
            days = float('inf') if use == 0 else round(stock / use, 2)
            result.append({'name': name, 'quantity': quantity, 'estimated_cost': round(quantity * cost, 2), 'days_until_stockout': days, '_critical': critical})
        except (KeyError, TypeError, ZeroDivisionError):
            raise ValueError('invalid supply')
    result.sort(key=lambda x: (not x.pop('_critical'), x['days_until_stockout'], x['name']))
    return result

