import csv
import io
import math
from datetime import datetime, timezone

def _time(value):
    try:
        if isinstance(value, datetime):
            dt = value
        else:
            dt = datetime.fromisoformat(value.replace('Z', '+00:00'))
        if dt.tzinfo is None:
            raise ValueError()
        return dt.astimezone(timezone.utc)
    except Exception as exc:
        raise ValueError('invalid timestamp') from exc

def parse_telemetry_lines(text: str) -> list[dict]:
    result = []
    for row in csv.reader(io.StringIO(text)):
        if not row or not any(row):
            continue
        if len(row) != 4 or not row[1] or (not row[3]):
            raise ValueError('invalid row')
        try:
            value = float(row[2])
        except Exception as exc:
            raise ValueError('invalid value') from exc
        if not math.isfinite(value):
            raise ValueError('invalid value')
        result.append({'timestamp': _time(row[0]), 'metric': row[1], 'value': value, 'unit': row[3]})
    return result

def build_telemetry_report(requester: dict, device: dict, readings: list[dict], start: str, end: str, bucket_seconds: int) -> list[dict]:
    if not isinstance(bucket_seconds, int) or isinstance(bucket_seconds, bool) or bucket_seconds <= 0:
        raise ValueError('invalid bucket')
    if requester.get('tenant_id') != device.get('tenant_id') or (requester.get('id') != device.get('owner_id') and (not {'admin', 'operator'} & set(requester.get('roles', [])))):
        raise PermissionError('not permitted')
    begin, finish = (_time(start), _time(end))
    if finish <= begin:
        raise ValueError('invalid range')
    groups = {}
    units = {}
    for item in readings:
        try:
            stamp, metric, value, unit = (_time(item['timestamp']), item['metric'], float(item['value']), item['unit'])
        except Exception as exc:
            raise ValueError('invalid reading') from exc
        if not metric or not unit or (not math.isfinite(value)):
            raise ValueError('invalid reading')
        if begin <= stamp < finish:
            if metric in units and units[metric] != unit:
                raise ValueError('inconsistent unit')
            units[metric] = unit
            index = int((stamp - begin).total_seconds() // bucket_seconds)
            groups.setdefault((index, metric, unit), []).append(value)
    output = []
    for (index, metric, unit), values in sorted(groups.items(), key=lambda x: (x[0][0], x[0][1], x[0][2])):
        left = begin.timestamp() + index * bucket_seconds
        right = left + bucket_seconds
        output.append({'metric': metric, 'unit': unit, 'start': datetime.fromtimestamp(left, timezone.utc).isoformat().replace('+00:00', 'Z'), 'end': datetime.fromtimestamp(right, timezone.utc).isoformat().replace('+00:00', 'Z'), 'count': len(values), 'average': round(sum(values) / len(values), 6), 'minimum': min(values), 'maximum': max(values)})
    return output

