def rank_dispatch_candidates(requester: dict, ride: dict, drivers: list[dict], limit: int=3) -> list[str]:
    if not isinstance(requester, dict) or not isinstance(ride, dict) or (not isinstance(drivers, list)):
        raise ValueError('invalid arguments')
    if not isinstance(limit, int) or isinstance(limit, bool) or (not 0 <= limit <= 20):
        raise ValueError('invalid limit')
    for obj in (requester, ride):
        if not isinstance(obj, dict):
            raise ValueError('invalid record')
    try:
