        requester_tenant = requester['tenant_id']
        tenant = ride['tenant_id']
        pickup = ride['pickup']
        vehicle = ride['vehicle_type']
        maximum = ride['max_distance']
    except (KeyError, TypeError):
        raise ValueError('invalid ride')
    if role not in ('dispatcher', 'admin') or requester_tenant != tenant:
        raise PermissionError('not permitted')
    if not isinstance(pickup, list) or len(pickup) != 2 or (not isinstance(maximum, (int, float))) or isinstance(maximum, bool) or (not math.isfinite(maximum)) or (maximum < 0):
        raise ValueError('invalid ride geometry')
    if any((isinstance(x, bool) or not isinstance(x, (int, float)) or (not math.isfinite(x)) for x in pickup)):
        raise ValueError('invalid pickup')
    seen = set()
    ranked = []
    for item in drivers:
        if not isinstance(item, dict):
            raise ValueError('invalid driver')
        try:
            identifier = item['id']
            dtenant = item['tenant_id']
            active = item['active']
            location = item['location']
            dtype = item['vehicle_type']
            rating = item['rating']
            completed = item['completed_rides']
        except KeyError:
            raise ValueError('invalid driver')
        if not isinstance(identifier, str) or identifier in seen:
            raise ValueError('duplicate driver')
        seen.add(identifier)
        if not isinstance(location, list) or len(location) != 2 or any((isinstance(x, bool) or not isinstance(x, (int, float)) or (not math.isfinite(x)) for x in location)):
            raise ValueError('invalid location')
        if isinstance(rating, bool) or not isinstance(rating, (int, float)) or (not math.isfinite(rating)) or isinstance(completed, bool) or (not isinstance(completed, (int, float))) or (not math.isfinite(completed)):
            raise ValueError('invalid metrics')
        distance = math.hypot(location[0] - pickup[0], location[1] - pickup[1])
        if active and dtenant == tenant and (dtype == vehicle) and (distance <= maximum):
            ranked.append((distance, -rating, -completed, identifier))
    ranked.sort()
    return [row[3] for row in ranked[:limit]]

