def initialize_database(conn: sqlite3.Connection) -> None:
    conn.execute('create table if not exists audits (id integer primary key, farm text not null, certifier text not null, status text not null, score real not null, audit_date text not null, findings text not null)')
    conn.execute('create index if not exists audits_certifier_status_idx on audits(certifier, status)')
    conn.commit()

def add_audit(conn: sqlite3.Connection, farm: str, certifier: str, status: str, score: float, audit_date: str, findings: str) -> int:
    if status not in {'pending', 'approved', 'rejected'}:
        raise ValueError('invalid status')
    try:
        value = float(score)
    except (TypeError, ValueError):
        raise ValueError('invalid score')
    if not 0 <= value <= 100:
        raise ValueError('invalid score')
    try:
        date.fromisoformat(audit_date)
        if len(audit_date) != 10:
            raise ValueError
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    cur = conn.execute('insert into audits(farm, certifier, status, score, audit_date, findings) values (?, ?, ?, ?, ?, ?)', (farm, certifier, status, value, audit_date, findings))
    conn.commit()
    return int(cur.lastrowid)

def generate_report(conn: sqlite3.Connection, certifier: str | None=None, status: str | None=None, search: str | None=None, sort_by: str='audit_date', descending: bool=False) -> list[dict]:
    allowed = {'id', 'farm', 'certifier', 'status', 'score', 'audit_date'}
    if sort_by not in allowed:
        raise ValueError('invalid sort field')
    clauses = []
    params = []
    if certifier is not None:
        clauses.append('certifier = ?')
        params.append(certifier)
    if status is not None:
        clauses.append('status = ?')
        params.append(status)
    if search is not None:
        clauses.append('(lower(farm) like lower(?) or lower(findings) like lower(?))')
        term = '%' + search + '%'
        params.extend([term, term])
    query = 'select id, farm, certifier, status, score, audit_date, findings from audits'
    if clauses:
        query += ' where ' + ' and '.join(clauses)
    rows = [dict(zip(('id', 'farm', 'certifier', 'status', 'score', 'audit_date', 'findings'), row)) for row in conn.execute(query, params)]
    groups = {}
    for row in rows:
        month = row['audit_date'][:7]
        groups.setdefault(month, []).append(row['score'])
    for row in rows:
        values = groups[row['audit_date'][:7]]
        row['month_count'] = len(values)
        row['month_average'] = round(sum(values) / len(values), 2)
    rows.sort(key=lambda r: r['id'])
    rows.sort(key=lambda r: r[sort_by], reverse=descending)
    return rows

