def test_empty_input_and_defaults():
    assert rank_work_orders([], "priority > 1", "priority") == []


def test_filters_scores_and_sorting():
    orders = [
        {"id": "B", "priority": 4, "hours": 2, "age": 3, "team": "east"},
        {"id": "A", "priority": 4, "hours": 1, "age": 5, "team": "west"},
        {"id": "C", "priority": 2, "hours": 8, "age": 1, "team": "east"},
        {"id": "D", "priority": 5, "hours": 9, "age": 2, "team": "west"},
    ]
    result = rank_work_orders(
        orders,
        "priority >= 3 and (team == 'east' or age < 6)",
        "priority * 10 - hours / 2",
    )
    assert result == [
        {"id": "D", "score": 45.5},
        {"id": "A", "score": 39.5},
        {"id": "B", "score": 39.0},
    ]


def test_ties_use_id_and_pagination():
    orders = [
        {"id": "Z", "priority": 3, "hours": 2, "age": 1, "team": "x"},
        {"id": "A", "priority": 3, "hours": 2, "age": 1, "team": "x"},
