        raise ValueError('invalid XML') from exc
    if root.tag != 'invoices':
        raise ValueError('invalid root')
    records = []
    ids = set()
    for node in root:
        if node.tag != 'invoice':
            raise ValueError('invalid invoice')
        ident = node.get('id')
        name = node.get('client')
        issued = node.get('issued')
        if not ident or not name or (not issued) or (ident in ids):
            raise ValueError('invalid invoice attributes')
        try:
            date.fromisoformat(issued)
        except Exception as exc:
            raise ValueError('invalid date') from exc
        lines = [x for x in node if x.tag == 'line']
        if not lines:
            raise ValueError('missing lines')
        total = Decimal('0')
        for line in lines:
            try:
                quantity = Decimal(line.attrib['quantity'])
                price = Decimal(line.attrib['unit_price'])
            except (KeyError, InvalidOperation) as exc:
                raise ValueError('invalid amount') from exc
            if not quantity.is_finite() or not price.is_finite() or quantity <= 0 or (price < 0):
                raise ValueError('invalid amount')
            total += quantity * price
        total = total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
