    start = (page - 1) * page_size
    selected = records[start:start + page_size]
    return {'total_count': len(records), 'page': page, 'page_size': page_size, 'invoices': [{'id': x['id'], 'client': x['client'], 'issued': x['issued'], 'total': f"{x['total_value']:.2f}"} for x in selected], 'grand_total': f"{sum((x['total_value'] for x in records), Decimal('0')):.2f}"}

