import hashlib
import hmac
import os
from datetime import datetime, timezone

def make_credential(secret: str) -> str:
    if not isinstance(secret, str):
        raise TypeError()
    if not secret:
        raise ValueError()
    salt = os.urandom(16)
    iterations = 100000
    digest = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, iterations)
    return f'{iterations}${salt.hex()}${digest.hex()}'

def check_credential(stored: str, candidate: str) -> bool:
    if not isinstance(stored, str) or not isinstance(candidate, str) or (not candidate):
        return False
    try:
        count, salt_text, digest_text = stored.split('$')
        count = int(count)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        if count <= 0 or not salt or (not expected):
            return False
        actual = hashlib.pbkdf2_hmac('sha256', candidate.encode(), salt, count)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def _fields(line):
    out = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            if char not in '\\|':
                raise ValueError()
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            out.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError()
    out.append(''.join(current))
    return out

def aggregate_logs(lines: list[str], credential: str, window_seconds: int=60) -> list[dict[str, object]]:
    if not check_credential(credential, 'log-reader'):
        raise PermissionError()
    if isinstance(window_seconds, bool) or not isinstance(window_seconds, int) or window_seconds <= 0:
        raise ValueError()
    groups = {}
    for line in lines:
        fields = _fields(line)
        if len(fields) != 4 or not fields[1] or fields[2] not in {'INFO', 'WARN', 'ERROR'}:
            raise ValueError()
        try:
            stamp = datetime.strptime(fields[0], '%Y-%m-%dT%H:%M:%SZ').replace(tzinfo=timezone.utc)
        except ValueError:
            raise ValueError()
        epoch = int(stamp.timestamp())
        bucket = epoch - epoch % window_seconds
        key = (bucket, fields[1])
        if key not in groups:
            groups[key] = {'total': 0, 'errors': 0, 'messages': []}
        groups[key]['total'] += 1
        groups[key]['errors'] += fields[2] == 'ERROR'
        groups[key]['messages'].append(fields[3])
    result = []
    for (bucket, service), data in sorted(groups.items()):
        start = datetime.fromtimestamp(bucket, timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')
        result.append({'window_start': start, 'service': service, **data})
    return result

