import subprocess

def inspect_document(path: str, terms: list[str]) -> dict[str, int]:
    if not isinstance(path, str):
        raise ValueError('path must be a string')
    if any((not isinstance(term, str) or not term for term in terms)):
        raise ValueError('terms must be non-empty strings')
    if len(set(terms)) != len(terms):
        raise ValueError('terms must be unique')
    result = {}
    for term in terms:
        try:
            completed = subprocess.run(['grep', '-F', '-c', '--', term, path], capture_output=True, text=True)
        except FileNotFoundError:
            raise
        except OSError as exc:
            raise RuntimeError(str(exc))
        if completed.returncode not in (0, 1):
            if completed.returncode == 2 and (not os.path.exists(path)):
                raise FileNotFoundError(path)
            raise RuntimeError(completed.stderr.strip() or 'grep failed')
        try:
            result[term] = int(completed.stdout.strip() or '0')
        except ValueError as exc:
            raise RuntimeError('invalid grep output') from exc
    return result

def build_seller_report(paths: list[str], terms: list[str], threshold: int=1) -> dict[str, object]:
    if threshold < 0:
        raise ValueError('threshold must not be negative')
    if any((not isinstance(term, str) or not term for term in terms)) or len(set(terms)) != len(terms):
        raise ValueError('terms must be non-empty and unique')
    documents = []
    for path in paths:
        counts = inspect_document(path, terms)
        score = sum(counts.values())
        approved = all((counts[term] >= 1 for term in terms)) and score >= threshold
        documents.append({'name': os.path.basename(path), 'counts': counts, 'score': score, 'approved': approved})
    documents.sort(key=lambda item: (-item['score'], item['name']))
    return {'documents': documents, 'approved': bool(documents) and all((item['approved'] for item in documents))}

