    cleaned.sort(key=lambda item: (-datetime.date.fromisoformat(item['inspected_on']).toordinal(), item['id']))
    total = len(cleaned)
    counts = {'pass': 0, 'fail': 0, 'review': 0}
    for item in cleaned:
        counts[item['status']] += 1
    start = (page - 1) * page_size
    return {'total': total, 'page': page, 'page_size': page_size, 'pages': (total + page_size - 1) // page_size, 'average_score': round(sum((item['score'] for item in cleaned)) / total, 2) if total else 0.0, 'counts': counts, 'items': cleaned[start:start + page_size]}

