import hashlib
import os
import hmac
from datetime import date

def make_credential(password: str) -> str:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    if not password:
        raise ValueError('password must not be empty')
    salt = os.urandom(16)
    iterations = 100000
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, iterations)
    return f'{iterations}${salt.hex()}${digest.hex()}'

def verify_credential(password: str, credential: str) -> bool:
    if not isinstance(password, str) or not isinstance(credential, str):
        raise TypeError('arguments must be strings')
    try:
        count, salt_hex, digest_hex = credential.split('$')
        iterations = int(count)
        salt = bytes.fromhex(salt_hex)
        expected = bytes.fromhex(digest_hex)
        if iterations < 1 or not salt or (not expected):
            return False
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, iterations)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def generate_statement(account_id: str, transactions: list[dict], password: str, credential: str, month: str) -> dict:
    if not all((isinstance(x, str) for x in (account_id, password, credential, month))) or not isinstance(transactions, list):
        raise TypeError('invalid argument type')
    if not account_id.strip():
        raise ValueError('account id is empty')
    try:
        year, mon = month.split('-')
        if len(year) != 4 or len(mon) != 2:
            raise ValueError
        date(int(year), int(mon), 1)
    except (ValueError, TypeError):
        raise ValueError('invalid month')
    if not verify_credential(password, credential):
        raise PermissionError('invalid password')
    checked = []
    seen = set()
    for item in transactions:
        if not isinstance(item, dict):
            raise ValueError('invalid transaction')
        if set(item) != {'date', 'id', 'amount', 'description'}:
            raise ValueError('invalid transaction')
        d, ident, amount, description = (item[k] for k in ('date', 'id', 'amount', 'description'))
        if not all((isinstance(x, str) for x in (d, ident, description))) or not ident or ident in seen or isinstance(amount, bool) or (not isinstance(amount, int)):
            raise ValueError('invalid transaction')
        try:
            parsed = date.fromisoformat(d)
        except ValueError:
            raise ValueError('invalid date')
        if d[:7] != month or parsed.strftime('%Y-%m-%d') != d:
            raise ValueError('date outside period')
        seen.add(ident)
        checked.append((d, ident, description, amount))
    checked.sort(key=lambda x: (x[0], x[1]))
    balance = credits = debits = 0
    rows = []
    for d, ident, description, amount in checked:
        balance += amount
        if amount > 0:
            credits += amount
        else:
            debits -= amount
        rows.append({'date': d, 'id': ident, 'description': description, 'amount': amount, 'balance': balance})
    return {'account_id': account_id, 'period': month, 'transactions': rows, 'summary': {'credits': credits, 'debits': debits, 'net': balance}}

