import csv
import subprocess

def generate_round_robin(players: list[str], rounds: int) -> list[list[tuple[str, str]]]:
    if not isinstance(rounds, int) or isinstance(rounds, bool):
        raise ValueError('invalid rounds')
    if len(players) < 2 or any((not isinstance(p, str) or not p for p in players)) or len(set(players)) != len(players):
        raise ValueError('invalid players')
    limit = len(players) - 1 if len(players) % 2 == 0 else len(players)
    if rounds < 1 or rounds > limit:
        raise ValueError('invalid rounds')
    items = list(players)
    if len(items) % 2:
        items.append(None)
    result = []
    for _ in range(rounds):
        result.append([(items[i], items[-1 - i]) for i in range(len(items) // 2) if items[i] is not None and items[-1 - i] is not None])
        items = [items[0], items[-1]] + items[1:-1]
    return result

def summarize_results(path: str) -> dict:
    try:
        count_process = subprocess.run(['wc', '-l', path], capture_output=True, text=True, check=True)
        physical_lines = int(count_process.stdout.split()[0])
        with open(path, 'r', encoding='utf-8', newline='') as stream:
            rows = list(csv.reader(stream))
    except (OSError, UnicodeError, ValueError, subprocess.SubprocessError):
        raise ValueError('invalid file')
    if not rows or rows[0] != ['round', 'player_a', 'score_a', 'player_b', 'score_b'] or physical_lines != len(rows):
        raise ValueError('invalid log')
    stats = {}
    seen = set()
    round_numbers = set()
    for row in rows[1:]:
        if len(row) != 5 or any((x == '' for x in row)):
            raise ValueError('invalid row')
        try:
            rnd, a, sa, b, sb = row
            rnd, sa, sb = (int(rnd), int(sa), int(sb))
        except ValueError:
            raise ValueError('invalid row')
        if rnd <= 0 or sa < 0 or sb < 0 or (a == b):
            raise ValueError('invalid row')
        key = frozenset((a, b))
        if key in seen:
            raise ValueError('duplicate match')
        seen.add(key)
        round_numbers.add(rnd)
        for name in (a, b):
            stats.setdefault(name, {'played': 0, 'wins': 0, 'draws': 0, 'losses': 0, 'points': 0, 'score_diff': 0})
        stats[a]['played'] += 1
        stats[b]['played'] += 1
        stats[a]['score_diff'] += sa - sb
        stats[b]['score_diff'] += sb - sa
        if sa > sb:
            stats[a]['wins'] += 1
            stats[a]['points'] += 3
            stats[b]['losses'] += 1
        elif sb > sa:
            stats[b]['wins'] += 1
            stats[b]['points'] += 3
            stats[a]['losses'] += 1
        else:
            stats[a]['draws'] += 1
            stats[b]['draws'] += 1
            stats[a]['points'] += 1
            stats[b]['points'] += 1
    if not stats:
        raise ValueError('empty tournament')
    standings = [{'player': name, **values} for name, values in stats.items()]
    standings.sort(key=lambda x: (-x['points'], -x['score_diff'], -x['wins'], x['player']))
    return {'matches': len(rows) - 1, 'rounds': sorted(round_numbers), 'standings': standings}

