def export_weather_summary(records: list[dict], start_date: str, end_date: str, destination: str) -> list[dict]:
    try:
        first = datetime.date.fromisoformat(start_date)
        last = datetime.date.fromisoformat(end_date)
    except Exception as exc:
        raise ValueError('invalid date') from exc
    if first > last:
        raise ValueError('invalid range')
    groups = {}
    for record in records:
        if not all((key in record for key in ('station', 'timestamp', 'temp_c', 'rainfall_mm'))):
            raise ValueError('missing field')
        station = record['station']
        if not isinstance(station, str) or not station:
            raise ValueError('invalid station')
        try:
            moment = datetime.datetime.fromisoformat(record['timestamp'])
        except Exception as exc:
            raise ValueError('invalid timestamp') from exc
        temp = record['temp_c']
        rain = record['rainfall_mm']
        if isinstance(temp, bool) or isinstance(rain, bool) or (not isinstance(temp, (int, float))) or (not isinstance(rain, (int, float))) or (not math.isfinite(temp)) or (not math.isfinite(rain)):
            raise ValueError('invalid measurement')
        day = moment.date()
        if first <= day <= last:
            key = (day.isoformat(), station)
            if key not in groups:
                groups[key] = [0.0, 0.0, 0]
            groups[key][0] += temp
            groups[key][1] += rain
            groups[key][2] += 1
    rows = []
    for (day, station), values in sorted(groups.items()):
        rows.append({'date': day, 'station': station, 'mean_temp_c': round(values[0] / values[2], 2), 'total_rain_mm': round(values[1], 2), 'readings': values[2]})
    fd, temporary = tempfile.mkstemp(prefix='weather-', suffix='.csv', dir=os.path.dirname(os.path.abspath(destination)))
    os.close(fd)
    try:
        with open(temporary, 'w', newline='') as handle:
            writer = csv.DictWriter(handle, fieldnames=['date', 'station', 'mean_temp_c', 'total_rain_mm', 'readings'])
            writer.writeheader()
            writer.writerows(rows)
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return rows

