import hashlib
import hmac
import os

def make_pin_record(pin: str) -> str:
    if not isinstance(pin, str):
        raise TypeError('pin must be a string')
    if not pin:
        raise ValueError('pin must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def check_pin(pin: str, record: str) -> bool:
    if not isinstance(pin, str):
        raise TypeError('pin must be a string')
    if not isinstance(record, str):
        return False
    try:
        salt_text, digest_text = record.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def claims_report(claims: list[dict], page: int=1, page_size: int=20) -> dict:
    if not isinstance(claims, list):
        raise TypeError('claims must be a list')
    if not isinstance(page, int) or isinstance(page, bool) or (not isinstance(page_size, int)) or isinstance(page_size, bool):
        raise TypeError('page values must be integers')
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    groups = {}
    for claim in claims:
        if claim['status'] != 'accepted':
            continue
        group = groups.setdefault(claim['category'], [0, 0, 0.0])
        group[0] += 1
        group[1] += claim['days_lost']
        group[2] += claim['amount']
    rows = [{'category': k, 'claims': v[0], 'days_lost': v[1], 'amount': round(v[2], 2)} for k, v in groups.items()]
    rows.sort(key=lambda x: (-x['amount'], x['category']))
    total = sum((x['claims'] for x in rows))
    total_amount = round(sum((x['amount'] for x in rows)), 2)
    total_pages = (total + page_size - 1) // page_size if total else 0
    start = (page - 1) * page_size
    return {'total_claims': total, 'total_amount': total_amount, 'page': page, 'page_size': page_size, 'total_pages': total_pages, 'items': rows[start:start + page_size]}

