from pathlib import Path

def store_campaign_asset(base_dir: str, asset_name: str, content: str) -> str:
    if not asset_name:
        raise ValueError('asset_name must not be empty')
    base = Path(base_dir).resolve()
    target = (base / asset_name).resolve()
    try:
        target.relative_to(base)
    except ValueError:
        raise ValueError('asset_name is outside the campaign directory')
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding='utf-8')
    return str(target)

