import secrets

def generate_coupon_code(campaign: str, issued_codes: set[str]) -> str:
    if not isinstance(campaign, str):
        raise ValueError('campaign must be a string')
    if not 2 <= len(campaign) <= 12 or re.fullmatch('[A-Za-z0-9]+', campaign) is None:
        raise ValueError('invalid campaign')
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ23456789'
    normalized = campaign.upper()
    while True:
        suffix = ''.join((secrets.choice(alphabet) for _ in range(8)))
        code = f'{normalized}-{suffix}'
        if code not in issued_codes:
            issued_codes.add(code)
            return code

