import csv
import io
import json
import math
from datetime import datetime, timezone
from typing import Any

def _time(value: str) -> datetime:
    if not isinstance(value, str) or not value.endswith('Z'):
        raise ValueError('invalid timestamp')
    try:
        dt = datetime.fromisoformat(value[:-1] + '+00:00')
    except ValueError as exc:
        raise ValueError('invalid timestamp') from exc
    if dt.tzinfo is None:
        raise ValueError('invalid timestamp')
    return dt.astimezone(timezone.utc)

def _stamp(dt: datetime) -> str:
    s = dt.strftime('%Y-%m-%dT%H:%M:%S')
    if dt.microsecond:
        s += '.%06d' % dt.microsecond
        s = s.rstrip('0')
    return s + 'Z'

def parse_observations(text: str) -> list[dict[str, Any]]:
    rows = list(csv.reader(io.StringIO(text, newline='')))
    header = ['timestamp', 'station_id', 'retreat_mm', 'uncertainty_mm']
    if not rows or rows[0] != header:
        raise ValueError('invalid header')
    last = {}
    result = []
    for row in rows[1:]:
        if len(row) != 4 or not row[1]:
            raise ValueError('invalid row')
        dt = _time(row[0])
        if row[1] in last and dt < last[row[1]]:
            raise ValueError('out of order')
        try:
            retreat = float(row[2])
            uncertainty = float(row[3])
        except ValueError as exc:
            raise ValueError('invalid number') from exc
        if not math.isfinite(retreat) or not math.isfinite(uncertainty) or retreat < 0 or (uncertainty < 0):
            raise ValueError('invalid number')
        last[row[1]] = dt
        result.append({'timestamp': _stamp(dt), 'station_id': row[1], 'retreat_mm': retreat, 'uncertainty_mm': uncertainty})
    if not result:
        raise ValueError('no rows')
    return result

def summarize_station(observations: list[dict[str, Any]], station_id: str) -> dict[str, Any]:
    if not station_id:
        raise ValueError('invalid station')
    selected = [x for x in observations if x['station_id'] == station_id]
    if not selected:
        raise ValueError('no observations')
    times = [_time(x['timestamp']) for x in selected]
    daily = {}
    for x, dt in zip(selected, times):
        daily[dt.date()] = daily.get(dt.date(), 0.0) + x['retreat_mm']
    return {'station_id': station_id, 'count': len(selected), 'total_retreat_mm': round(sum((x['retreat_mm'] for x in selected)), 3), 'mean_uncertainty_mm': round(sum((x['uncertainty_mm'] for x in selected)) / len(selected), 3), 'max_daily_retreat_mm': round(max(daily.values()), 3), 'first_timestamp': min((x['timestamp'] for x in selected)), 'last_timestamp': max((x['timestamp'] for x in selected))}

def export_station_report(requester: dict[str, Any], station_id: str, stations: dict[str, dict[str, Any]], observation_text: str, format: str='json') -> str:
    station = stations[station_id]
    if requester['tenant_id'] != station['tenant_id'] and 'admin' not in requester['roles']:
        raise PermissionError('not authorized')
    if requester['id'] != station['owner_id'] and (not {'analyst', 'admin'} & set(requester['roles'])):
        raise PermissionError('not authorized')
    if format not in ('json', 'csv'):
        raise ValueError('invalid format')
    summary = summarize_station(parse_observations(observation_text), station_id)
    report = {'station': station, 'summary': summary, 'generated_for': requester['id']}
    if format == 'json':
        return json.dumps(report, sort_keys=True, separators=(',', ':'))
    out = io.StringIO(newline='')
    writer = csv.writer(out, lineterminator='\n')
    keys = ['station_id', 'count', 'total_retreat_mm', 'mean_uncertainty_mm', 'max_daily_retreat_mm', 'first_timestamp', 'last_timestamp']
