import datetime
import json
import math
import os

def write_retention_report(base_dir: str, relative_name: str, backups: list[dict[str, object]], as_of: str, page: int=1, page_size: int=50) -> dict[str, object]:
    try:
        day = datetime.date.fromisoformat(as_of)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
    limits = {'hot': 30, 'warm': 90, 'cold': 365}
    seen = set()
    kept = []
    for item in backups:
        if not isinstance(item, dict) or not all((k in item for k in ('id', 'created', 'tier', 'size_mb'))):
            raise ValueError('invalid backup')
        ident, tier, size = (item['id'], item['tier'], item['size_mb'])
        if not isinstance(ident, str) or ident in seen or tier not in limits:
            raise ValueError('invalid backup')
        if isinstance(size, bool) or not isinstance(size, (int, float)) or (not math.isfinite(size)) or (size < 0):
            raise ValueError('invalid size')
        try:
            created = datetime.date.fromisoformat(item['created'])
        except (TypeError, ValueError):
            raise ValueError('invalid date')
        age = (day - created).days
        if age < 0:
            raise ValueError('future backup')
        seen.add(ident)
        if age <= limits[tier]:
            kept.append({'id': ident, 'created': item['created'], 'tier': tier, 'size_mb': size})
    kept.sort(key=lambda x: (-datetime.date.fromisoformat(x['created']).toordinal(), x['id']))
    groups = []
    for tier in ('hot', 'warm', 'cold'):
        values = [x['size_mb'] for x in kept if x['tier'] == tier]
        groups.append({'tier': tier, 'count': len(values), 'size_mb': round(sum(values), 2)})
    report = {'as_of': as_of, 'total_size_mb': round(sum((x['size_mb'] for x in kept)), 2), 'backups': kept[(page - 1) * page_size:page * page_size], 'by_tier': groups}
    target = os.path.abspath(os.path.join(base_dir, relative_name))
    root = os.path.realpath(base_dir)
    if os.path.commonpath((root, os.path.realpath(target))) != root:
        raise ValueError('invalid path')
    os.makedirs(os.path.dirname(target), exist_ok=True)
    with open(target, 'w', encoding='utf-8') as f:
        json.dump(report, f, indent=2, sort_keys=True)
        f.write('\n')
    return report

