def build_forecast_page(records: list[dict], region: str, page: int=1, page_size: int=2) -> dict:
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    if page < 1 or page_size < 1:
        raise ValueError('page and page_size must be positive')
    grouped = {}
    for record in records:
        for key in ('day', 'region', 'forecast_mwh', 'price'):
            if key not in record:
                raise KeyError(key)
        if record['region'] == region:
            day = record['day']
            bucket = grouped.setdefault(day, [0.0, 0.0])
            bucket[0] += record['forecast_mwh']
            bucket[1] += record['forecast_mwh'] * record['price']
    ordered = sorted(grouped.items(), key=lambda pair: (-pair[1][0], pair[0]))
