import base64
import hashlib
import hmac
import os

def create_member(name: str, email: str, password: str, joined_year: int, genres: list[str]) -> dict:
    if not isinstance(name, str) or not name.strip():
        raise ValueError('invalid name')
    if not isinstance(email, str) or email.count('@') != 1:
        raise ValueError('invalid email')
    local, domain = email.strip().split('@')
    if not local or not domain:
        raise ValueError('invalid email')
    if not isinstance(password, str) or not password:
        raise ValueError('invalid password')
    if isinstance(joined_year, bool) or not isinstance(joined_year, int) or (not 1900 <= joined_year <= 2100):
        raise ValueError('invalid year')
    if not isinstance(genres, list):
        raise ValueError('invalid genres')
    seen = set()
    clean_genres = []
    for genre in genres:
        if not isinstance(genre, str) or not genre.strip():
            raise ValueError('invalid genre')
        value = genre.strip()
        key = value.casefold()
        if key not in seen:
            seen.add(key)
            clean_genres.append(value)
    clean_genres.sort(key=str.casefold)
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return {'name': name.strip(), 'email': email.strip(), 'joined_year': joined_year, 'genres': clean_genres, 'salt': base64.b64encode(salt).decode(), 'password_hash': base64.b64encode(digest).decode()}

def verify_member(member: dict, password: str) -> bool:
    if not isinstance(member, dict) or not isinstance(password, str):
        return False
    try:
        salt = base64.b64decode(member['salt'], validate=True)
        expected = base64.b64decode(member['password_hash'], validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError):
        return False

def list_members(members: list[dict], genre: str | None=None, page: int=1, page_size: int=10) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1 or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid pagination')
    if genre is not None and (not isinstance(genre, str) or not genre.strip()):
        raise ValueError('invalid genre')
    wanted = genre.strip().casefold() if genre is not None else None
    filtered = [m for m in members if wanted is None or any((g.casefold() == wanted for g in m['genres']))]
    filtered.sort(key=lambda m: (m['joined_year'], m['name'].casefold(), m['email'].casefold()))
    counts = {}
    for member in filtered:
        for value in member['genres']:
            counts[value] = counts.get(value, 0) + 1
    counts = dict(sorted(counts.items(), key=lambda item: (-item[1], item[0].casefold())))
    start = (page - 1) * page_size
    selected = filtered[start:start + page_size]
    public = [{'name': m['name'], 'email': m['email'], 'joined_year': m['joined_year'], 'genres': list(m['genres'])} for m in selected]
    return {'members': public, 'total': len(filtered), 'genre_counts': counts}

