import hashlib
import hmac
import json

def rank_housing_applications(payload: str, signature: str, page: int=1, page_size: int=10, secret: str='campus-key') -> list[dict]:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError('invalid page size')
    expected = hmac.new(secret.encode(), payload.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    try:
        data = json.loads(payload)
    except Exception as exc:
        raise ValueError('invalid json') from exc
    if not isinstance(data, dict) or not isinstance(data.get('halls'), dict) or (not isinstance(data.get('applications'), list)):
        raise ValueError('invalid payload')
    halls = data['halls']
    for name, capacity in halls.items():
        if not isinstance(name, str) or not isinstance(capacity, int) or isinstance(capacity, bool) or (capacity < 0):
            raise ValueError('invalid hall')
    seen = set()
    grouped = {name: [] for name in halls}
    for app in data['applications']:
        if not isinstance(app, dict) or any((k not in app for k in ('student_id', 'hall', 'points', 'submitted_at', 'eligible'))):
            raise ValueError('invalid application')
        sid, hall, points, submitted, eligible = (app[k] for k in ('student_id', 'hall', 'points', 'submitted_at', 'eligible'))
        if not isinstance(sid, str) or not sid or sid in seen or (not isinstance(hall, str)) or (not isinstance(points, (int, float))) or isinstance(points, bool) or (not isinstance(submitted, str)) or (not isinstance(eligible, bool)):
            raise ValueError('invalid application')
        seen.add(sid)
        if eligible and hall in grouped:
            grouped[hall].append((points, submitted, sid))
    result = []
    for hall in sorted(halls):
        items = sorted(grouped[hall], key=lambda x: (-x[0], x[1], x[2]))
        admitted = items[:halls[hall]]
        result.append({'hall': hall, 'admitted': [x[2] for x in admitted], 'cutoff_points': admitted[-1][0] if admitted else None, 'total': len(items)})
    start = (page - 1) * page_size
    return result[start:start + page_size]

