def _time(value):
    if not isinstance(value, str) or not value.endswith('Z'):
        raise ValueError('invalid timestamp')
    try:
        return datetime.datetime.fromisoformat(value[:-1] + '+00:00')
    except ValueError:
        raise ValueError('invalid timestamp')

def rotation_plan(records: list[dict], as_of: str, window_days: int) -> list[dict]:
    now = _time(as_of)
    if not isinstance(window_days, int) or isinstance(window_days, bool) or window_days < 0:
        raise ValueError('invalid window')
    newest = {}
    for item in records:
        try:
            name, version = (item['secret'], item['version'])
            rotated, expires = (_time(item['rotated_at']), _time(item['expires_at']))
            owner, status = (item['owner'], item['status'])
        except (KeyError, TypeError):
            raise ValueError('invalid record')
        if not isinstance(name, str) or not name or (not isinstance(owner, str)) or (not owner):
            raise ValueError('invalid record')
        if not isinstance(version, int) or isinstance(version, bool) or version <= 0 or (status not in ('active', 'revoked')):
            raise ValueError('invalid record')
        old = newest.get(name)
        if old is None or (rotated, version) > (old[0], old[1]):
            newest[name] = (rotated, version, expires, owner, status)
    result = []
    cutoff = now + datetime.timedelta(days=window_days)
    for name, (rotated, version, expires, owner, status) in newest.items():
        if status == 'active' and expires <= cutoff:
            text = expires.strftime('%Y-%m-%dT%H:%M:%SZ')
            result.append({'secret': name, 'version': version, 'owner': owner, 'expires_at': text, 'reason': 'expired' if expires <= now else 'window'})
    result.sort(key=lambda x: (x['expires_at'], x['owner'], x['secret'], x['version']))
    return result

def write_rotation_report(records: list[dict], destination: str, as_of: str, window_days: int) -> int:
    plan = rotation_plan(records, as_of, window_days)
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent, prefix='.rotation-')
    os.close(fd)
    try:
        with open(temporary, 'w', encoding='utf-8', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['secret', 'version', 'owner', 'expires_at', 'reason'])
            for row in plan:
                writer.writerow([row[k] for k in ('secret', 'version', 'owner', 'expires_at', 'reason')])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return len(plan)

