    except ValueError:
        raise ValueError('malformed record')
    if parsed_day.isoformat() != day or not account or (not reference):
        raise ValueError('malformed record')
    if not re.fullmatch('\\d+\\.\\d{1,2}', amount):
        raise ValueError('malformed record')
