import base64
import hashlib
import hmac
import os
from datetime import date

def hash_password(password: str) -> str:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    salt = os.urandom(16)
    iterations = 100000
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, iterations)
    return 'pbkdf2$%d$%s$%s' % (iterations, base64.b64encode(salt).decode(), base64.b64encode(digest).decode())

def verify_password(password: str, stored: str) -> bool:
    if not isinstance(password, str) or not isinstance(stored, str):
        return False
    try:
        kind, count, salt_text, digest_text = stored.split('$', 3)
        if kind != 'pbkdf2':
            return False
        iterations = int(count)
        salt = base64.b64decode(salt_text, validate=True)
        expected = base64.b64decode(digest_text, validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, iterations)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def _parts(text, performance=False):
    if not isinstance(text, str) or not text.strip():
        raise ValueError('empty input')
    rows = []
    for line in text.splitlines():
        if not line.strip():
            raise ValueError('blank line')
        bits = [x.strip() for x in line.split('|')]
        if performance and len(bits) != 2 or (not performance and len(bits) != 3):
            raise ValueError('bad line')
        rows.append(bits)
    return rows

def schedule_cast(cast_data: str, performance_data: str, password: str, credential: str) -> list[dict]:
    if not verify_password(password, credential):
        raise PermissionError('invalid credential')
    members = {}
    for name, roles, dates in _parts(cast_data):
        roles = [x.strip() for x in roles.split(',')]
        dates = [x.strip() for x in dates.split(',')]
        if not name or not roles or any((not x for x in roles)) or (not dates) or any((not x for x in dates)):
            raise ValueError('bad cast')
        if name in members or len(set(roles)) != len(roles) or len(set(dates)) != len(dates):
            raise ValueError('duplicate cast data')
        try:
            [date.fromisoformat(x) for x in dates]
        except ValueError:
            raise ValueError('bad date')
        members[name] = (set(roles), set(dates))
    shows = []
    seen = set()
    for day_time, roles_text in _parts(performance_data, True):
        bits = day_time.split()
        roles = [x.strip() for x in roles_text.split(',')]
        if len(bits) != 2 or not all(roles) or len(set(roles)) != len(roles):
            raise ValueError('bad performance')
        try:
            date.fromisoformat(bits[0])
            hour, minute = map(int, bits[1].split(':'))
            if not (0 <= hour <= 23 and 0 <= minute <= 59) or len(bits[1]) != 5:
                raise ValueError
        except ValueError:
            raise ValueError('bad time')
        key = (bits[0], bits[1])
        if key in seen:
            raise ValueError('duplicate performance')
        seen.add(key)
        shows.append((key, roles))
    shows.sort()
    counts = {name: 0 for name in members}
    result = []
    for (day, time), roles in shows:
        assigned = set()
        cast = {}
        for role in sorted(roles):
            choices = [n for n, (rs, ds) in members.items() if role in rs and day in ds and (n not in assigned)]
            if not choices:
                raise ValueError('no assignment')
            name = min(choices, key=lambda n: (counts[n], n))
            cast[role] = name
            assigned.add(name)
            counts[name] += 1
        result.append({'date': day, 'time': time, 'cast': cast})
    return result

