import ast
import operator

def rank_geological_samples(records: list[dict[str, object]], expression: str, minimum: float) -> list[dict[str, object]]:
    try:
        tree = ast.parse(expression, mode='eval').body
    except SyntaxError as exc:
        raise ValueError('invalid expression') from exc
    names = {'sample_id', 'depth', 'grade', 'moisture'}
    funcs = {'min': min, 'max': max, 'round': round}
    binary = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
    compares = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}

    def visit(node, values):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, bool)):
            return node.value
        if isinstance(node, ast.Name) and node.id in names:
            return values[node.id]
        if isinstance(node, ast.BinOp) and type(node.op) in binary:
            return binary[type(node.op)](visit(node.left, values), visit(node.right, values))
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
            value = visit(node.operand, values)
            return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
        if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
            value = visit(node.values[0], values)
            for child in node.values[1:]:
                if isinstance(node.op, ast.And) and (not value) or (isinstance(node.op, ast.Or) and value):
                    return value
                value = visit(child, values)
            return value
        if isinstance(node, ast.Compare):
            left = visit(node.left, values)
            for op, child in zip(node.ops, node.comparators):
                right = visit(child, values)
                if type(op) not in compares or not compares[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in funcs) and (not node.keywords):
            return funcs[node.func.id](*(visit(arg, values) for arg in node.args))
        raise ValueError('invalid expression')
    output = []
    for record in records:
        try:
            score = visit(tree, {name: record[name] for name in names})
        except (KeyError, TypeError, ZeroDivisionError) as exc:
            raise ValueError('invalid expression') from exc
        if score >= minimum:
            item = dict(record)
            item['score'] = score
            output.append(item)
