    assert verify_webhook(body, sig, key) is True
    assert verify_webhook(body + b" ", sig, key) is False
    assert verify_webhook(body, "sha256=" + "0" * 64, key) is False
    assert verify_webhook(body, "wrong", key) is False
    assert verify_webhook(body, None, key) is False


