import hashlib
import hmac
import json
from datetime import datetime

def verify_webhook(body: bytes, signature: str, signing_key: bytes) -> bool:
    if not isinstance(body, bytes) or not isinstance(signature, str):
        return False
    if len(signature) != 71 or not signature.startswith('sha256='):
        return False
    supplied = signature[7:]
    if any((c not in '0123456789abcdef' for c in supplied)):
        return False
    expected = hmac.new(signing_key, body, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, supplied)

def _event(event):
    if not isinstance(event, dict):
        raise ValueError('invalid event')
    required = ('project', 'contributor', 'minutes', 'status', 'at')
    if any((k not in event for k in required)):
        raise ValueError('invalid event')
    project = event['project']
    contributor = event['contributor']
    minutes = event['minutes']
    status = event['status']
    stamp = event['at']
    if not isinstance(project, str) or not project:
        raise ValueError('invalid event')
    if not isinstance(contributor, str) or not contributor:
        raise ValueError('invalid event')
    if isinstance(minutes, bool) or not isinstance(minutes, int) or (not 1 <= minutes <= 1440):
        raise ValueError('invalid event')
    if status not in {'planned', 'active', 'blocked', 'done'}:
        raise ValueError('invalid event')
    if not isinstance(stamp, str) or not stamp.endswith('Z'):
        raise ValueError('invalid event')
    try:
        parsed = datetime.fromisoformat(stamp[:-1])
    except (TypeError, ValueError):
        raise ValueError('invalid event')
    return (project, contributor, minutes, status, parsed)

def process_webhook(body: bytes, signature: str, signing_key: bytes) -> dict:
    if not verify_webhook(body, signature, signing_key):
        raise PermissionError('invalid signature')
    try:
        root = json.loads(body.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('invalid body')
    if not isinstance(root, dict) or 'events' not in root or (not isinstance(root['events'], list)):
        raise ValueError('invalid body')
    projects = {}
    total = 0
    for index, raw in enumerate(root['events']):
        project, contributor, minutes, status, stamp = _event(raw)
        total += minutes
        item = projects.setdefault(project, {'minutes': 0, 'contributors': {}, 'latest': None})
        item['minutes'] += minutes
        item['contributors'][contributor] = item['contributors'].get(contributor, 0) + minutes
        if item['latest'] is None or stamp >= item['latest'][0]:
            item['latest'] = (stamp, index, status)
    result = []
    for name, item in projects.items():
        contributors = [{'name': n, 'minutes': m} for n, m in item['contributors'].items()]
        contributors.sort(key=lambda x: (-x['minutes'], x['name']))
        result.append({'name': name, 'minutes': item['minutes'], 'status': item['latest'][2], 'contributors': contributors})
    result.sort(key=lambda x: (-x['minutes'], x['name']))
    return {'total_minutes': total, 'projects': result}

