import csv
import os
import re
import tempfile

def export_backup(records: list[dict[str, str]], directory: str, keep: int) -> str:
    if not isinstance(keep, int) or isinstance(keep, bool) or keep <= 0:
        raise ValueError('keep must be positive')
    pattern = re.compile('^backup-(\\d{4})\\.csv$')
    numbers = []
    for name in os.listdir(directory):
        match = pattern.match(name)
        if match:
            numbers.append(int(match.group(1)))
    number = max(numbers, default=0) + 1
    final_path = os.path.join(directory, f'backup-{number:04d}.csv')
    fd, temporary_path = tempfile.mkstemp(dir=directory, prefix='.backup-', suffix='.tmp')
    os.close(fd)
    try:
        with open(temporary_path, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle)
            writer.writerow(['id', 'name', 'value'])
            for record in records:
                writer.writerow([record['id'], record['name'], record['value']])
        os.replace(temporary_path, final_path)
    except Exception:
        if os.path.exists(temporary_path):
            os.unlink(temporary_path)
        raise
    backups = []
    for name in os.listdir(directory):
        match = pattern.match(name)
        if match:
            backups.append((int(match.group(1)), os.path.join(directory, name)))
    for _, path in sorted(backups)[:-keep]:
        os.unlink(path)
    return final_path

