import datetime
import xml.etree.ElementTree as ET

def _date(value):
    if not isinstance(value, str):
        raise ValueError('invalid date')
    try:
        datetime.date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid date')
    if len(value) != 10 or value[4] != '-' or value[7] != '-':
        raise ValueError('invalid date')
    return value

def parse_training_records(xml_text: str) -> list[dict]:
    if not isinstance(xml_text, str):
        raise TypeError('xml_text must be str')
    try:
        root = ET.fromstring(xml_text)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'training_feed':
        raise ValueError('wrong root')
    result = []
    for employee in root:
        if employee.tag != 'employee':
            continue
        eid = employee.get('id')
        name = employee.get('name')
        if not eid or not name:
            raise ValueError('invalid employee')
        for item in employee:
            if item.tag != 'completion':
                continue
            course = item.get('course')
            date = item.get('date')
            hours = item.get('hours')
            status = item.get('status')
            if not course or not date or hours is None or (status is None):
                raise ValueError('invalid completion')
            _date(date)
            try:
                number = int(hours)
            except ValueError as exc:
                raise ValueError('invalid hours') from exc
            if str(number) != hours or number < 0:
                raise ValueError('invalid hours')
            result.append({'employee_id': eid, 'employee_name': name, 'course': course, 'date': date, 'hours': number, 'status': status})
    return result

def compliance_report(records: list[dict], required_courses: dict[str, int], as_of: str) -> list[dict]:
    if not isinstance(records, list) or not isinstance(required_courses, dict):
        raise TypeError('invalid arguments')
    _date(as_of)
    for value in required_courses.values():
        if not isinstance(value, int) or isinstance(value, bool) or value < 0:
            raise ValueError('invalid requirement')
    people = {}
    totals = {}
    for record in records:
        eid = record['employee_id']
        if eid not in people:
            people[eid] = record['employee_name']
            totals[eid] = {course: 0 for course in required_courses}
        if record['date'] <= as_of and record['status'] == 'passed' and (record['course'] in required_courses):
            totals[eid][record['course']] += record['hours']
    required_total = sum(required_courses.values())
    result = []
    for eid in sorted(people):
        missing = sorted((course for course, need in required_courses.items() if totals[eid][course] < need))
        result.append({'employee_id': eid, 'employee_name': people[eid], 'completed_hours': sum(totals[eid].values()), 'required_hours': required_total, 'compliant': not missing, 'missing_courses': missing})
    return result

