    bad = ['a|2024-01-01|1|good|extra', 'a|2024-02-30|1|good', '|2024-01-01|1|good', 'a|2024-01-01|-1|good', 'a|2024-01-01|x|good', 'a|2024-01-01|1|bad', 'a|2024-01-01|1|good\\']
    for value in bad:
        with pytest.raises(ValueError):
            parse_observations(value)

def test_summary_groups_sorts_and_uses_window():
    observations = parse_observations('B|2024-01-03|8|watch\nA|2024-01-03|5|good\nA|2024-01-01|1|good\nA|2024-01-02|3|critical\nB|2024-01-01|4|good')
    assert summarize_inspection(observations, 2) == [{'station': 'A', 'count': 3, 'latest_date': '2024-01-03', 'latest_measurement': 5.0, 'rolling_average': 4.0, 'worst_condition': 'critical'}, {'station': 'B', 'count': 2, 'latest_date': '2024-01-03', 'latest_measurement': 8.0, 'rolling_average': 6.0, 'worst_condition': 'watch'}]

