    observations = parse_observations('z|2024-01-01|1|good\nz|2024-01-01|2|watch\nz|2024-01-02|2|good')
    assert summarize_inspection(observations) == [{'station': 'z', 'count': 3, 'latest_date': '2024-01-02', 'latest_measurement': 2.0, 'rolling_average': 1.67, 'worst_condition': 'watch'}]
    with pytest.raises(ValueError):
        summarize_inspection(observations, 0)

def test_build_urgent_order_for_owner():
    inspection = {'id': 'IN-7', 'owner_id': 'u1', 'district': 'north', 'road': 'R-9', 'observations': parse_observations('s|2024-01-01|9|critical')}
    requester = {'id': 'u1', 'role': 'inspector', 'district': 'north'}
    assert build_work_order(requester, inspection) == {'work_order_id': 'WO-IN-7', 'inspection_id': 'IN-7', 'road': 'R-9', 'district': 'north', 'stations': [{'station': 's', 'count': 1, 'latest_date': '2024-01-01', 'latest_measurement': 9.0, 'rolling_average': 9.0, 'worst_condition': 'critical'}], 'priority': 'urgent', 'due_days': 1}

