        rows = list(csv.reader(io.StringIO('\n'.join(lines))))
    except csv.Error as exc:
        raise ValueError('invalid csv') from exc
    if not rows or [x.strip().lower() for x in rows[0]] != ['awb', 'destination', 'weight', 'pieces', 'priority']:
        raise ValueError('invalid header')
    result = []
    seen = set()
    for row in rows[1:]:
        if len(row) != 5:
            raise ValueError('invalid row')
        awb, destination, weight, pieces, priority = [x.strip() for x in row]
        if not awb or not destination or awb in seen or (priority.lower() not in ('standard', 'express')):
            raise ValueError('invalid field')
        try:
            weight_value = float(weight)
            pieces_value = int(pieces)
        except ValueError as exc:
            raise ValueError('invalid number') from exc
        if not math.isfinite(weight_value) or weight_value <= 0 or pieces_value <= 0 or (str(pieces_value) != pieces):
            raise ValueError('invalid number')
        seen.add(awb)
        result.append({'awb': awb, 'destination': destination, 'weight': weight_value, 'pieces': pieces_value, 'priority': priority.lower()})
    return result

