    destination = destination.strip()
    if not destination or not math.isfinite(capacity) or capacity <= 0:
        raise ValueError('invalid flight')
    eligible = [r for r in records if r['destination'] == destination]
    eligible.sort(key=lambda r: (0 if r['priority'] == 'express' else 1, -r['weight'], r['awb']))
    chosen = []
    remaining = capacity
    for record in eligible:
        if record['weight'] <= remaining:
            chosen.append(record)
            remaining -= record['weight']
    return {'destination': destination, 'awbs': [r['awb'] for r in chosen], 'total_weight': sum((r['weight'] for r in chosen)), 'total_pieces': sum((r['pieces'] for r in chosen)), 'records': chosen}

