        awbs = plan['awbs']
        records = plan['records']
        total_weight = plan['total_weight']
        total_pieces = plan['total_pieces']
    except (KeyError, AttributeError, TypeError) as exc:
        raise ValueError('invalid booking') from exc
    if not destination or not isinstance(awbs, list) or (not isinstance(records, list)) or (len(awbs) != len(records)):
        raise ValueError('invalid booking')
    if any((r.get('awb') != a for r, a in zip(records, awbs))) or sum((r.get('weight', 0) for r in records)) != total_weight or sum((r.get('pieces', 0) for r in records)) != total_pieces:
        raise ValueError('invalid booking')
