from datetime import datetime, timezone

def parse_slot(value: str) -> datetime:
    if not isinstance(value, str):
        raise ValueError('invalid timestamp')
    text = value
    if text.endswith('Z'):
        text = text[:-1] + '+00:00'
    try:
        parsed = datetime.fromisoformat(text)
    except (TypeError, ValueError):
        raise ValueError('invalid timestamp')
    if parsed.tzinfo is None or parsed.utcoffset() is None:
        raise ValueError('timezone required')
    try:
        return parsed.astimezone(timezone.utc)
    except (OverflowError, ValueError):
        raise ValueError('invalid timestamp')

def schedule_hearing(requester: dict, case: dict, requested_start: str, duration_minutes: int, existing: list[dict]) -> dict:
    if not isinstance(requester, dict) or requester.get('tenant_id') != case.get('tenant_id'):
        raise PermissionError('not permitted')
    if requester.get('id') != case.get('owner_id') and requester.get('role') not in {'judge', 'clerk'}:
        raise PermissionError('not permitted')
    if not isinstance(duration_minutes, int) or isinstance(duration_minutes, bool) or (not 15 <= duration_minutes <= 240) or duration_minutes % 15:
        raise ValueError('invalid duration')
    start = parse_slot(requested_start)
    if start.weekday() >= 5 or start.minute % 15 or start.second or start.microsecond or (start.hour < 9) or (start.hour == 17 and start.minute > 0) or (start.hour > 17):
        raise ValueError('outside hearing hours')
    end = start.replace() + __import__('datetime').timedelta(minutes=duration_minutes)
    if end.date() != start.date() or end.hour > 17 or (end.hour == 17 and end.minute > 0):
        raise ValueError('outside hearing hours')
    for item in existing:
        if item.get('tenant_id') != case.get('tenant_id') or item.get('courtroom') != case.get('courtroom'):
            continue
        old_start = parse_slot(item['start'])
        old_end = parse_slot(item['end'])
        if old_start >= old_end:
            raise ValueError('invalid existing interval')
        if start < old_end and old_start < end:
            raise ValueError('room conflict')
    fmt = '%Y-%m-%dT%H:%M:%SZ'
    return {'case_id': case['id'], 'tenant_id': case['tenant_id'], 'courtroom': case['courtroom'], 'start': start.strftime(fmt), 'end': end.strftime(fmt), 'title': case['title']}

