import hashlib
import hmac
import math
import os

def make_credential(password: str) -> str:
    if not isinstance(password, str) or not password:
        raise ValueError('password must be non-empty')
    salt = os.urandom(16)
    derived = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return 'pbkdf2$100000$' + salt.hex() + '$' + derived.hex()

def verify_credential(stored: str, password: str) -> bool:
    if not isinstance(stored, str) or not isinstance(password, str):
        return False
    try:
        marker, count, salt_text, digest_text = stored.split('$')
        if marker != 'pbkdf2' or int(count) != 100000:
            return False
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def interpreter_workload(assignments: list[dict], language: str, page: int=1, page_size: int=10) -> list[dict]:
    if not isinstance(assignments, list) or not isinstance(language, str):
        raise ValueError('invalid arguments')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    grouped = {}
    for row in assignments:
        if not isinstance(row, dict):
            raise ValueError('invalid assignment')
        name = row.get('interpreter')
        lang = row.get('language')
        hours = row.get('hours')
        if not isinstance(name, str) or not name or (not isinstance(lang, str)):
            raise ValueError('invalid assignment')
        if isinstance(hours, bool) or not isinstance(hours, (int, float)) or (not math.isfinite(hours)) or (hours < 0):
            raise ValueError('invalid assignment')
        if lang == language:
            item = grouped.setdefault(name, [0, 0.0])
            item[0] += 1
            item[1] += hours
    ordered = sorted(grouped.items(), key=lambda x: (-x[1][1], -x[1][0], x[0]))
    start = (page - 1) * page_size
    return [{'interpreter': n, 'cases': v[0], 'hours': round(v[1], 2)} for n, v in ordered[start:start + page_size]]

