import hashlib
import hmac
import json
import pytest
from solution import build_case_payload, parse_intake_submission
SECRET = b'clinic-intake-key'

def signed(payload):
    digest = hmac.new(SECRET, payload, hashlib.sha256).hexdigest()
    return {'X-Case-Signature': 'sha256=' + digest}

def test_parses_and_normalizes_nested_submission():
    obj = {'case_id': '  C-19 ', 'client': {'name': '  Pat Doe ', 'email': ' PAT@EXAMPLE.ORG '}, 'issues': [{'category': 'housing', 'priority': 3, 'summary': 'eviction'}, {'category': 'benefits', 'priority': 5, 'summary': 'appeal'}], 'documents': [{'filename': 'z.pdf', 'content_type': 'text/plain', 'size': 9}, {'filename': 'a.pdf', 'content_type': 'application/pdf', 'size': 4}]}
    payload = json.dumps(obj, separators=(',', ':')).encode()
    assert parse_intake_submission(payload, signed(payload), SECRET) == {'case_id': 'C-19', 'client': {'name': 'Pat Doe', 'email': ' pat@example.org '}, 'issues': [{'category': 'benefits', 'priority': 5, 'summary': 'appeal'}, {'category': 'housing', 'priority': 3, 'summary': 'eviction'}], 'documents': [{'filename': 'a.pdf', 'content_type': 'application/pdf', 'size': 4}, {'filename': 'z.pdf', 'content_type': 'text/plain', 'size': 9}], 'total_document_bytes': 13}

def test_issue_tie_breaking_is_deterministic():
    obj = {'case_id': 'x', 'client': {'name': 'n', 'email': 'e'}, 'issues': [{'category': 'b', 'priority': 2, 'summary': 'z'}, {'category': 'a', 'priority': 2, 'summary': 'q'}, {'category': 'a', 'priority': 2, 'summary': 'a'}], 'documents': []}
    payload = json.dumps(obj).encode()
    result = parse_intake_submission(payload, signed(payload), SECRET)
    assert [x['summary'] for x in result['issues']] == ['a', 'q', 'z']

def test_signature_header_name_is_case_insensitive():
    payload = build_case_payload('x', 'n', 'e', [], [])
    headers = {'x-case-signature': signed(payload)['X-Case-Signature']}
    assert parse_intake_submission(payload, headers, SECRET)['total_document_bytes'] == 0

def test_rejects_bad_or_missing_signature():
    payload = build_case_payload('x', 'n', 'e', [], [])
    with pytest.raises(ValueError):
        parse_intake_submission(payload, {}, SECRET)
    with pytest.raises(ValueError):
        parse_intake_submission(payload, {'X-Case-Signature': 'sha256=' + '0' * 64}, SECRET)
    with pytest.raises(ValueError):
        parse_intake_submission(payload, {'X-Case-Signature': 'md5=abc'}, SECRET)

def test_rejects_structural_and_range_errors():
    base = {'case_id': 'x', 'client': {'name': 'n', 'email': 'e'}, 'issues': [], 'documents': []}
    for change in [{'client': {'name': 'n', 'email': 'e', 'x': 1}}, {'issues': [{'category': 'x', 'priority': True, 'summary': 's'}]}, {'documents': [{'filename': 'x', 'content_type': 'p', 'size': -1}]}, {'case_id': '   '}, {'documents': [{'filename': 'x', 'content_type': 'p', 'size': 10485761}]}]:
        item = dict(base)
        item.update(change)
        payload = json.dumps(item).encode()
        with pytest.raises(ValueError):
            parse_intake_submission(payload, signed(payload), SECRET)

def test_rejects_encoding_and_json_errors():
    for payload in [b'\xff', b'not-json']:
        with pytest.raises(ValueError):
            parse_intake_submission(payload, signed(payload), SECRET)

def test_empty_collections_and_zero_size_are_supported():
