import hashlib
import hmac
import os

def _make_hash(pin):
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return salt.hex() + '$' + value.hex()

def verify_pin(stored_hash: str, pin: str) -> bool:
    if not isinstance(stored_hash, str) or not isinstance(pin, str):
        return False
    try:
        salt_text, value_text = stored_hash.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(value_text)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def register_voters(records: list[dict], page: int=1, page_size: int=10) -> dict:
    if not isinstance(records, list):
        raise TypeError()
    if isinstance(page, bool) or isinstance(page_size, bool) or page <= 0 or (page_size <= 0):
        raise ValueError()
    seen = set()
    eligible = []
    for record in records:
        if not isinstance(record, dict):
            raise TypeError()
        if not all((key in record for key in ('voter_id', 'district', 'age', 'pin'))):
            raise TypeError()
        voter_id = record['voter_id']
        district = record['district']
        age = record['age']
        pin = record['pin']
        if not isinstance(voter_id, str) or not voter_id or (not isinstance(district, str)) or (not district) or (not isinstance(age, int)) or isinstance(age, bool) or (age < 0) or (age > 150) or (not isinstance(pin, str)) or (not pin):
            raise TypeError()
        if voter_id in seen:
            raise ValueError()
        seen.add(voter_id)
        if age >= 18:
            eligible.append({'voter_id': voter_id, 'district': district, 'pin_hash': _make_hash(pin)})
    eligible.sort(key=lambda item: (item['district'], item['voter_id']))
    districts = {}
    for item in eligible:
        districts[item['district']] = districts.get(item['district'], 0) + 1
    start = (page - 1) * page_size
    return {'total': len(records), 'eligible': len(eligible), 'districts': districts, 'voters': eligible[start:start + page_size]}

