    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return {'email': email, 'plan': plan, 'issues': issues, 'postal_code': postal_code, 'password_salt': salt.hex(), 'password_hash': digest.hex()}

