    if 'password_salt' not in record or 'password_hash' not in record:
        return False
    try:
        salt = bytes.fromhex(record['password_salt'])
        expected = bytes.fromhex(record['password_hash'])
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
