import csv
import datetime
import os
import tempfile

def _date(value):
    if not isinstance(value, str):
        raise ValueError('invalid date')
    try:
        parsed = datetime.date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid date')
    if parsed.isoformat() != value:
        raise ValueError('invalid date')
    return parsed

def build_schedule(inspections: list[dict], start_date: str, end_date: str, daily_limit: int) -> list[dict]:
    start = _date(start_date)
    end = _date(end_date)
    if start > end or not isinstance(daily_limit, int) or isinstance(daily_limit, bool) or (daily_limit <= 0):
        raise ValueError('invalid scheduling window')
    ranks = {'high': 0, 'medium': 1, 'low': 2}
    seen = set()
    prepared = []
    for item in inspections:
        if not isinstance(item, dict) or not all((k in item for k in ('inspection_id', 'facility', 'risk', 'requested_date'))):
            raise ValueError('invalid inspection')
        ident, facility, risk = (item['inspection_id'], item['facility'], item['risk'])
        if not isinstance(ident, str) or not ident or ident in seen or (not isinstance(facility, str)) or (not facility) or (risk not in ranks):
            raise ValueError('invalid inspection')
        requested = _date(item['requested_date'])
        seen.add(ident)
        prepared.append((ranks[risk], requested, ident, facility, risk, item['requested_date']))
    prepared.sort(key=lambda x: (x[0], x[1], x[2]))
    counts = {}
    result = []
    for _, requested, ident, facility, risk, requested_text in prepared:
        day = max(start, requested)
        while day <= end and counts.get(day, 0) >= daily_limit:
            day += datetime.timedelta(days=1)
        if day > end:
            raise ValueError('schedule does not fit')
        counts[day] = counts.get(day, 0) + 1
        result.append({'inspection_id': ident, 'facility': facility, 'risk': risk, 'requested_date': requested_text, 'scheduled_date': day.isoformat()})
    return result

def export_schedule(schedule: list[dict], destination: str) -> int:
    fields = ['inspection_id', 'facility', 'risk', 'requested_date', 'scheduled_date']
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent, prefix='.schedule-', suffix='.tmp')
    os.close(fd)
    try:
        with open(temporary, 'w', encoding='utf-8', newline='') as handle:
            writer = csv.DictWriter(handle, fieldnames=fields, extrasaction='ignore', lineterminator='\n')
            writer.writeheader()
            count = 0
            for row in schedule:
                if not all((field in row for field in fields)):
                    raise ValueError('missing schedule field')
                writer.writerow({field: row[field] for field in fields})
                count += 1
        os.replace(temporary, destination)
        return count
    except Exception:
        try:
            os.unlink(temporary)
        except OSError:
            pass
        raise

