    assert len(result["invite_code"]) == 12
    assert all(c in "ABCDEFGHJKLMNPQRSTUVWXYZ23456789" for c in result["invite_code"])


def test_filters_cancelled_and_other_regions_and_sorts_with_tie_breaker():
    shipments = [
        {"id": "Z9", "region": "East", "status": "ready", "eta": "2025-04-02", "weight_kg": 4.25},
        {"id": "A2", "region": "East", "status": "ready", "eta": "2025-04-01", "weight_kg": 2},
        {"id": "A1", "region": "East", "status": "in_transit", "eta": "2025-04-01", "weight_kg": 1.5},
        {"id": "C3", "region": "East", "status": "cancelled", "eta": "2025-03-01", "weight_kg": 99},
        {"id": "B4", "region": "West", "status": "ready", "eta": "2025-01-01", "weight_kg": 50},
    ]
    result = create_shipment_invite(shipments, "East", page=1, page_size=10)
    assert [x["id"] for x in result["shipments"]] == ["A1", "A2", "Z9"]
    assert result["total"] == 3
    assert result["page_count"] == 1
    assert result["total_weight_kg"] == 7.75
    assert list(result["shipments"][0]) == ["id", "region", "status", "eta", "weight_kg"]


