import secrets
_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'

def generate_invite_code(length: int=8) -> str:
    if type(length) is not int or not 4 <= length <= 32:
        raise ValueError('length must be between 4 and 32')
    return ''.join((secrets.choice(_ALPHABET) for _ in range(length)))

def _date(value: str) -> datetime.date:
    if not isinstance(value, str):
        raise ValueError('invalid date')
    try:
        parsed = datetime.date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid date')
    if parsed.isoformat() != value:
        raise ValueError('invalid date')
    return parsed

def absence_totals(records: list[dict], start: str, end: str, page: int=1, page_size: int=10) -> list[dict]:
    first = _date(start)
    last = _date(end)
    if first > last:
        raise ValueError('reversed range')
    if type(page) is not int or page < 1 or type(page_size) is not int or (page_size < 1):
        raise ValueError('invalid pagination')
    found = set()
    for record in records:
        if not all((key in record for key in ('employee', 'date', 'status'))):
            raise ValueError('invalid record')
        employee = record['employee']
        if not isinstance(employee, str) or not employee:
            raise ValueError('invalid employee')
        day = _date(record['date'])
        if record['status'] == 'approved' and first <= day <= last:
            found.add((employee, day))
    counts = {}
    for employee, day in found:
        counts[employee] = counts.get(employee, 0) + 1
    result = [{'employee': employee, 'days': days} for employee, days in counts.items()]
    result.sort(key=lambda item: (-item['days'], item['employee']))
    start_index = (page - 1) * page_size
    return result[start_index:start_index + page_size]

