import secrets
_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'

def generate_invite_code(length: int=8) -> str:
    if not isinstance(length, int) or isinstance(length, bool) or (not 4 <= length <= 32):
        raise ValueError('invalid code length')
    return ''.join((secrets.choice(_ALPHABET) for _ in range(length)))

def register_invite(team: str, registry: dict[str, str]) -> str:
    if not isinstance(team, str) or not team.strip():
        raise ValueError('invalid team')
    name = team.strip()
    for _ in range(len(_ALPHABET) ** 8):
        code = generate_invite_code()
        if code not in registry:
            registry[code] = name
            return code
    raise ValueError('no code available')

def schedule_league(teams: list[str], rounds: int, unavailable: dict[str, set[int]] | None=None) -> list[dict[str, object]]:
    if not isinstance(teams, list) or len(teams) < 2:
        raise ValueError('invalid teams')
    normalized = []
    for team in teams:
        if not isinstance(team, str) or not team.strip():
            raise ValueError('invalid team')
        normalized.append(team.strip())
    if len(set(normalized)) != len(normalized):
        raise ValueError('duplicate team')
    if not isinstance(rounds, int) or isinstance(rounds, bool) or (not 1 <= rounds <= len(normalized) - 1):
        raise ValueError('invalid rounds')
    blocked = unavailable if unavailable is not None else {}
    if not isinstance(blocked, dict) or any((k not in normalized for k in blocked)):
        raise ValueError('unknown team')
    for values in blocked.values():
        if not isinstance(values, set) or any((not isinstance(r, int) or isinstance(r, bool) or (not 1 <= r <= rounds) for r in values)):
            raise ValueError('invalid unavailable round')
    circle = sorted(normalized)
    if len(circle) % 2:
        circle.append(None)
    result = []
    for number in range(1, rounds + 1):
        for index in range(len(circle) // 2):
            left, right = (circle[index], circle[-index - 1])
            if left is None or right is None:
                continue
            if number in blocked.get(left, set()) or number in blocked.get(right, set()):
                raise ValueError('team unavailable')
            first, second = sorted((left, right))
            if (number + index) % 2 == 0:
                home, away = (first, second)
            else:
