        raise ValueError('invalid lane count')
    items = sorted(reservations, key=lambda x: (x['date'], x['start'], x['swimmer'], x['duration']))
    occupied = [[] for _ in range(lane_count + 1)]
    output = []
    for item in items:
        try:
            start = datetime.strptime(item['start'], '%H:%M')
            end = start + timedelta(minutes=item['duration'])
            if end.date() != start.date():
                raise ValueError
            chosen = item['requested_lane']
            choices = [chosen] if chosen is not None else range(1, lane_count + 1)
            if chosen is not None and (chosen < 1 or chosen > lane_count):
                raise ValueError
            for lane in choices:
                if all((end <= a or start >= b for a, b in occupied[lane])):
                    chosen = lane
                    break
            else:
                raise ValueError
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid reservation')
        occupied[chosen].append((start, end))
        value = dict(item)
        value['lane'] = chosen
        value['end'] = end.strftime('%H:%M')
        output.append(value)
    return output

