            raise ValueError('invalid order fields')
        if order['status'] not in ('queued', 'ready', 'packed', 'cancelled'):
            raise ValueError('invalid status')
        if not isinstance(order['items'], list):
            raise ValueError('malformed items')
        if order['warehouse'] != warehouse or order['status'] == 'cancelled':
            continue
        for item in order['items']:
