            groups[sku]['quantity'] += quantity
            groups[sku]['weight_g'] += quantity * weight
            groups[sku]['order_ids'].add(order['id'])
    items = []
    for value in groups.values():
        items.append({'sku': value['sku'], 'quantity': value['quantity'], 'weight_g': value['weight_g'], 'order_ids': sorted(value['order_ids'])})
