        if not line:
            continue
        if '=' not in line:
            raise ValueError('invalid line')
        name, ranges = (x.strip() for x in line.split('=', 1))
        if not name or name in result or (not ranges):
            raise ValueError('invalid table')
        parsed = []
        for item in ranges.split(','):
            parts = item.strip().split('-')
            if len(parts) != 2:
                raise ValueError('invalid range')
            start, end = (_minutes(parts[0].strip()), _minutes(parts[1].strip()))
            if end <= start:
                raise ValueError('invalid range')
            parsed.append((start, end))
        result[name] = parsed
    return result

