        raise ValueError('invalid reservation')
    begin, finish = (_minutes(start), _minutes(end))
    if finish <= begin:
        raise ValueError('invalid interval')
    for name, capacity in tables.items():
        if not isinstance(capacity, int) or isinstance(capacity, bool) or capacity < 1:
            raise ValueError('invalid table')
    choices = []
    for name, capacity in tables.items():
        if capacity < party_size:
            continue
        if all((r['table'] != name or finish <= _minutes(r['start']) or begin >= _minutes(r['end']) for r in reservations)):
            choices.append((capacity, name))
    if not choices:
        raise ValueError('no table')
    _, table = min(choices)
    used = {r['code'] for r in reservations}
    while True:
        code = ''.join((secrets.choice(_ALPHABET) for _ in range(12)))
        if code not in used:
            break
    item = {'code': code, 'customer': customer.strip(), 'party_size': party_size, 'start': start, 'end': end, 'table': table}
    reservations.append(item)
    return item

