from lxml import etree

def summarize_feedback(xml_text: str, page: int=1, page_size: int=10) -> dict:
    if type(page) is not int or type(page_size) is not int or page <= 0 or (page_size <= 0):
        raise ValueError('page and page_size must be positive integers')
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml_text.encode('utf-8'), parser=parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'feedback':
        raise ValueError('invalid root')
    groups = {}
    for child in root:
        if child.tag != 'entry':
            raise ValueError('invalid child')
        article = child.get('article')
        rating = child.get('rating')
        helpful = child.get('helpful')
        if article is None or rating is None or helpful is None:
            raise ValueError('missing attribute')
        article = article.strip()
        rating = rating.strip()
        helpful = helpful.strip()
        if not article or helpful not in ('yes', 'no'):
            raise ValueError('invalid attribute')
        try:
            value = int(rating)
        except ValueError as exc:
            raise ValueError('invalid rating') from exc
        if value < 1 or value > 5:
            raise ValueError('invalid rating')
        if article not in groups:
            groups[article] = [[], 0]
        groups[article][0].append(value)
        groups[article][1] += helpful == 'yes'
    articles = []
    for article, (ratings, helpful_count) in groups.items():
        articles.append({'article_id': article, 'responses': len(ratings), 'average_rating': round(sum(ratings) / len(ratings), 2), 'helpful_percent': round(helpful_count * 100 / len(ratings), 2)})
    articles.sort(key=lambda item: (-item['average_rating'], -item['responses'], item['article_id']))
    start = (page - 1) * page_size
    total_articles = len(articles)
    total_entries = sum((item['responses'] for item in articles))
    return {'total_articles': total_articles, 'total_entries': total_entries, 'page': page, 'page_size': page_size, 'total_pages': (total_articles + page_size - 1) // page_size if total_articles else 0, 'articles': articles[start:start + page_size]}

