import hashlib
import hmac
import json
from datetime import datetime

def verify_and_summarize(payload: str, signature: str, secret: str, start_date: str | None=None, end_date: str | None=None, offset: int=0, limit: int=10) -> dict:
    expected = hmac.new(secret.encode(), payload.encode(), hashlib.sha256).hexdigest()
    if not isinstance(signature, str) or not hmac.compare_digest(expected, signature):
        raise PermissionError('invalid signature')
    try:
        data = json.loads(payload)
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(data, dict) or not isinstance(data.get('bookings'), list):
        raise ValueError('invalid payload')

    def valid_date(value):
        if not isinstance(value, str):
            raise ValueError('invalid date')
        try:
            datetime.strptime(value, '%Y-%m-%d')
        except ValueError as exc:
            raise ValueError('invalid date') from exc
        return value
    start = valid_date(start_date) if start_date is not None else None
    end = valid_date(end_date) if end_date is not None else None
    if start is not None and end is not None and (start > end):
        raise ValueError('invalid range')
    if isinstance(offset, bool) or not isinstance(offset, int) or offset < 0:
        raise ValueError('invalid offset')
    if isinstance(limit, bool) or not isinstance(limit, int) or limit <= 0:
        raise ValueError('invalid limit')
    totals = {}
    for row in data['bookings']:
        if not isinstance(row, dict) or not all((k in row for k in ('id', 'family', 'service', 'date', 'price_cents', 'status'))):
            raise ValueError('invalid booking')
        date = valid_date(row['date'])
        if not isinstance(row['service'], str) or not row['service'] or (not isinstance(row['status'], str)):
            raise ValueError('invalid booking')
        if isinstance(row['price_cents'], bool) or not isinstance(row['price_cents'], int) or row['price_cents'] < 0:
            raise ValueError('invalid booking')
        if row['status'] == 'confirmed' and (start is None or date >= start) and (end is None or date <= end):
            item = totals.setdefault(row['service'], [0, 0])
            item[0] += 1
            item[1] += row['price_cents']
    items = [{'service': name, 'count': values[0], 'total_cents': values[1]} for name, values in totals.items()]
    items.sort(key=lambda item: (-item['total_cents'], item['service']))
    return {'items': items[offset:offset + limit], 'total_services': len(items)}

