            raise ValueError('invalid replicate')
        key = (compound, concentration, replicate)
        if key in seen:
            raise ValueError('duplicate')
        seen.add(key)
        result.append({'compound_id': compound, 'plate': plate, 'concentration': concentration, 'response': response, 'replicate': replicate})
    return result

def rank_compounds(records: list[dict], window: int=2) -> list[dict]:
    if isinstance(window, bool) or not isinstance(window, int) or window <= 0:
        raise ValueError('invalid window')
    groups = {}
    for record in records:
        groups.setdefault(record['compound_id'], []).append(record)
    output = []
    for compound, items in groups.items():
        ordered = sorted(items, key=lambda x: (x['concentration'], x['replicate']))
        values = [x['response'] for x in ordered]
        size = min(window, len(values))
        candidates = [(sum(values[i:i + size]) / size, ordered[i]['concentration']) for i in range(len(values) - size + 1)]
        best_mean, best_start = max(candidates, key=lambda x: (x[0], -x[1]))
        output.append({'compound_id': compound, 'measurements': len(values), 'mean_response': round(sum(values) / len(values), 4), 'best_window_mean': round(best_mean, 4), 'best_window_start': round(best_start, 4), 'max_response': round(max(values), 4)})
    return sorted(output, key=lambda x: (-x['best_window_mean'], -x['mean_response'], x['compound_id']))

