    if fit_preference not in ('slim', 'regular', 'relaxed'):
        raise ValueError('invalid fit preference')
    sizes = ['XS', 'S', 'M', 'L', 'XL']
    if chest_cm <= 88:
        index = 1
    elif chest_cm <= 100:
        index = 2
    elif chest_cm <= 112:
        index = 3
    else:
        index = 4
    if fit_preference == 'slim':
        index -= 1
    elif fit_preference == 'relaxed':
        index += 1
    index = max(0, min(4, index))
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    code = 'FS-' + ''.join((random.choice(alphabet) for _ in range(10)))
    return {'size': sizes[index], 'fit': fit_preference, 'code': code}

