        total += count
    prepared.sort(key=lambda x: (x[0], x[1], x[2]))
    fd, temporary = tempfile.mkstemp(prefix='radiology-', suffix='.csv', dir=os.path.dirname(os.path.abspath(destination)))
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as stream:
            writer = csv.writer(stream, lineterminator='\n')
            writer.writerow(['accession', 'patient_id', 'study_date', 'modality', 'body_parts', 'total_instances'])
            writer.writerows(prepared)
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return {'patients': len(patients), 'studies': len(prepared), 'total_instances': total, 'modalities': dict(sorted(modalities.items()))}

