import csv
import io
import os
import tempfile
from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
_HEADER = ['policy_id', 'broker', 'premium', 'rate', 'transaction_date', 'status']

def parse_commission_feed(text: str) -> list[dict]:
    try:
        rows = list(csv.reader(io.StringIO(text), strict=True))
    except csv.Error as e:
        raise ValueError('invalid csv') from e
    if not rows or rows[0] != _HEADER:
        raise ValueError('invalid header')
    result = []
    for number, row in enumerate(rows[1:], 2):
        if not row:
            if number == 2:
                continue
            raise ValueError('blank row')
        if len(row) != 6:
            raise ValueError('invalid row')
        policy, broker, premium, rate, when, status = [x.strip() for x in row]
        if not policy or not broker:
            raise ValueError('missing name')
        try:
            p = Decimal(premium)
            r = Decimal(rate)
            day = date.fromisoformat(when)
        except (InvalidOperation, ValueError):
            raise ValueError('invalid value')
        status = status.lower()
        if p < 0 or r < 0 or r > 1 or (status not in ('paid', 'void')):
            raise ValueError('invalid value')
        result.append({'policy_id': policy, 'broker': broker, 'premium': p, 'rate': r, 'transaction_date': day, 'status': status})
    return result

def summarize_commissions(records: list[dict], month: str) -> list[dict]:
    try:
        year, mon = month.split('-')
        if len(year) != 4 or len(mon) != 2 or (not 1 <= int(mon) <= 12):
            raise ValueError
    except (ValueError, AttributeError):
        raise ValueError('invalid month')
    totals = {}
    policies = {}
    for item in records:
        if item['transaction_date'].strftime('%Y-%m') != month:
            continue
        broker = item['broker']
        amount = item['premium'] * item['rate']
        totals[broker] = totals.get(broker, Decimal('0')) + (amount if item['status'] == 'paid' else -amount)
        policies.setdefault(broker, set()).add(item['policy_id'])
    output = [{'broker': b, 'month': month, 'commission': v.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP), 'policies': len(policies[b])} for b, v in totals.items()]
    return sorted(output, key=lambda x: (-x['commission'], x['broker']))

def write_commission_report(text: str, month: str, destination: str) -> int:
    rows = summarize_commissions(parse_commission_feed(text), month)
    fd, temporary = tempfile.mkstemp(dir=os.path.dirname(destination) or '.', prefix='.commission-')
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as f:
            writer = csv.writer(f)
            writer.writerow(['broker', 'month', 'commission', 'policies'])
            for row in rows:
                writer.writerow([row['broker'], row['month'], format(row['commission'], '.2f'), row['policies']])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return len(rows)

