import json, os, zipfile
from datetime import datetime, timezone
_LEVELS = {'advisory': 0, 'watch': 1, 'warning': 2, 'emergency': 3}

def _time(v):
    try:
        if not isinstance(v, str) or not v.endswith('Z'):
            raise ValueError
        return datetime.fromisoformat(v[:-1]).replace(tzinfo=timezone.utc)
    except Exception as e:
        raise ValueError from e

def _inside(base, name):
    root = os.path.realpath(base)
    target = os.path.realpath(os.path.join(root, name.replace('/', os.sep)))
    if os.path.commonpath([root, target]) != root:
        raise ValueError
    return target

def extract_warning_bundle(base_dir: str, archive_path: str) -> list[str]:
    os.makedirs(base_dir, exist_ok=True)
    with zipfile.ZipFile(archive_path) as a:
        xs = [x for x in a.infolist() if not x.is_dir() and x.filename.endswith('.json')]
        names = [x.filename for x in xs]
        if len(names) != len(set(names)):
            raise ValueError
        for x in xs:
            p = _inside(base_dir, x.filename)
            os.makedirs(os.path.dirname(p), exist_ok=True)
            with open(p, 'wb') as f:
                f.write(a.read(x))
    return sorted(names)

def summarize_warnings(base_dir: str, as_of: str) -> dict:
    now = _time(as_of)
    found = {}
    total = 0
    for root, _, files in os.walk(base_dir):
        for fn in files:
            if not fn.endswith('.json'):
                continue
            try:
                with open(os.path.join(root, fn), encoding='utf8') as f:
                    r = json.load(f)
                if not isinstance(r, dict) or not all((k in r and isinstance(r[k], str) for k in ('region', 'severity', 'issued', 'expires', 'message'))) or r['severity'] not in _LEVELS:
                    raise ValueError
                issued, expires = (_time(r['issued']), _time(r['expires']))
            except ValueError:
                raise
            except Exception as e:
                raise ValueError from e
            if issued <= now < expires:
                total += 1
                x = found.setdefault(r['region'], {'count': 0, 'latest': None, 'severity': 'advisory'})
                x['count'] += 1
                if x['latest'] is None or issued > x['latest'][0]:
                    x['latest'] = (issued, r['issued'])
                if _LEVELS[r['severity']] > _LEVELS[x['severity']]:
                    x['severity'] = r['severity']
    return {'total': total, 'regions': {k: {'severity': found[k]['severity'], 'count': found[k]['count'], 'latest_issued': found[k]['latest'][1]} for k in sorted(found)}}

