    if not tenant or len(tenant_el) or (tenant_el.tail and tenant_el.tail.strip()):
        raise ValueError
    prop, charges_el = (root.find('property'), root.find('charges'))
    units, codes = ([], set())
    if prop.text and prop.text.strip():
        raise ValueError
    for unit in prop:
        if unit.tag != 'unit' or set(unit.attrib) != {'code', 'area'} or len(unit) or (unit.tail and unit.tail.strip()):
            raise ValueError
        code = unit.get('code', '').strip()
        try:
            area = int(unit.get('area', ''))
        except ValueError:
            raise ValueError
        if not code or area <= 0 or code in codes:
            raise ValueError
        codes.add(code)
        units.append({'code': code, 'area': area})
    result_charges, months = ([], set())
    if charges_el.text and charges_el.text.strip():
        raise ValueError
    for charge in charges_el:
        if charge.tag != 'charge' or set(charge.attrib) != {'month', 'amount'} or len(charge) or (charge.tail and charge.tail.strip()):
            raise ValueError
        month, raw = (charge.get('month', ''), charge.get('amount', ''))
        if len(month) != 7 or month[4] != '-':
            raise ValueError
        try:
            mdate = date.fromisoformat(month + '-01')
            amount = Decimal(raw)
        except (ValueError, InvalidOperation):
            raise ValueError
        if mdate < date(start.year, start.month, 1) or mdate > date(end.year, end.month, 1) or amount < 0 or (amount.as_tuple().exponent < -2) or (month in months):
            raise ValueError
        cents = int(amount * 100)
        months.add(month)
        result_charges.append({'month': month, 'amount': cents})
    return {'id': attrs['id'], 'start': attrs['start'], 'end': attrs['end'], 'tenant': tenant, 'units': units, 'charges': result_charges}

def summarize_leases(documents: list[str]) -> dict:
    parsed, ids, totals, lease_sets = ([], set(), {}, {})
    for document in documents:
        lease = parse_lease_xml(document)
        if lease['id'] in ids:
            raise ValueError
        ids.add(lease['id'])
        parsed.append(lease)
        for charge in lease['charges']:
            totals[charge['month']] = totals.get(charge['month'], 0) + charge['amount']
            lease_sets.setdefault(charge['month'], set()).add(lease['id'])
    months = [{'month': m, 'total_cents': totals[m], 'leases': len(lease_sets[m])} for m in sorted(totals)]
    return {'lease_count': len(parsed), 'total_area': sum((u['area'] for l in parsed for u in l['units'])), 'total_cents': sum(totals.values()), 'months': months}

