import csv
import hashlib
import hmac
import io
import json
from datetime import date

def parse_audit_log(text: str) -> list[dict]:
    reader = csv.reader(io.StringIO(text, newline=''))
    rows = [row for row in reader if any((cell.strip() for cell in row))]
    expected = ['farm', 'region', 'inspector', 'date', 'status', 'score']
    if not rows or rows[0] != expected:
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if len(row) != 6:
            raise ValueError('invalid row')
        farm, region, inspector, raw_date, status, raw_score = row
        if not farm or not region or (not inspector) or (not raw_date) or (not status) or (not raw_score):
            raise ValueError('missing value')
        try:
            date.fromisoformat(raw_date)
            score = int(raw_score)
        except ValueError as exc:
            raise ValueError('invalid field') from exc
        if status not in {'certified', 'rejected', 'pending'} or not 0 <= score <= 100:
            raise ValueError('invalid field')
        result.append({'farm': farm, 'region': region, 'inspector': inspector, 'date': raw_date, 'status': status, 'score': score})
    return result

def summarize_audits(records: list[dict]) -> dict:
    groups = {}
    for record in records:
        groups.setdefault(record['region'], []).append(record)

    def part(items):
        return {'count': len(items), 'average_score': round(sum((x['score'] for x in items)) / len(items), 2) if items else 0.0, 'certified_count': sum((x['status'] == 'certified' for x in items))}
    overall = part(records)
    regions = {}
    for name in sorted(groups):
        items = groups[name]
        value = part(items)
        value['latest_date'] = max((x['date'] for x in items))
        regions[name] = value
    return {'overall': overall, 'regions': regions}

def export_signed_report(records: list[dict], config: dict[str, str]) -> str:
    key = config.get('audit_signing_key')
    if not key:
        raise ValueError('missing audit signing key')
    report = summarize_audits(records)
    payload = json.dumps(report, sort_keys=True, separators=(',', ':'))
    signature = hmac.new(key.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()
    return json.dumps({'report': report, 'signature': signature}, sort_keys=True, separators=(',', ':'))

