import hashlib
import hmac
import os

def create_credential(password: str) -> str:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    if password == '':
        raise ValueError('password must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 100000)
    return 'pbkdf2$' + salt.hex() + '$' + digest.hex()

def verify_credential(stored: str, password: str) -> bool:
    if not isinstance(stored, str) or not isinstance(password, str):
        return False
    parts = stored.split('$')
    if len(parts) != 3 or parts[0] != 'pbkdf2':
        return False
    try:
        salt = bytes.fromhex(parts[1])
        expected = bytes.fromhex(parts[2])
    except ValueError:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 100000)
    return hmac.compare_digest(actual, expected)

def rank_waitlist(applications: list[dict], max_income: float, page: int=1, page_size: int=10) -> list[str]:
    if max_income < 0 or page < 1 or page_size < 1:
        raise ValueError('invalid range')
    eligible = [item for item in applications if item['income'] <= max_income]
    eligible.sort(key=lambda item: (-int(item['disability']), item['income'], item['received'], item['id']))
    start = (page - 1) * page_size
    return [item['id'] for item in eligible[start:start + page_size]]

