def generate_quota_report(requester: dict, vessel: dict, catches: list[dict], season: int, page: int=1, page_size: int=20) -> dict:
    if not isinstance(season, int) or isinstance(season, bool):
        raise ValueError('invalid season')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError('invalid page size')
    roles = requester.get('roles', [])
    if not (requester.get('id') == vessel.get('owner_id') or ('quota_officer' in roles and requester.get('tenant_id') == vessel.get('tenant_id'))):
        raise PermissionError('not permitted')
    totals = {}
    counts = {}
    for item in catches:
        for key in ('vessel_id', 'season', 'species', 'weight_kg'):
            if key not in item:
                raise ValueError('invalid catch')
        if not isinstance(item['season'], int) or isinstance(item['season'], bool):
            raise ValueError('invalid catch season')
        if not isinstance(item['vessel_id'], str):
            raise ValueError('invalid vessel')
        species = item['species']
        weight = item['weight_kg']
        if not isinstance(species, str) or not species:
            raise ValueError('invalid species')
        if not isinstance(weight, (int, float)) or isinstance(weight, bool) or (not math.isfinite(weight)) or (weight < 0):
            raise ValueError('invalid weight')
        if item['vessel_id'] == vessel['vessel_id'] and item['season'] == season:
            totals[species] = totals.get(species, 0) + weight
