def fetch_flags(conn: sqlite3.Connection, environment: str, prefix: str='', sort_by: str='name', descending: bool=False, limit: int=100, offset: int=0) -> list[dict]:
    if not isinstance(environment, str) or not environment:
        raise ValueError('environment must be a non-empty string')
    if not isinstance(prefix, str):
        raise ValueError('prefix must be a string')
    if sort_by not in {'name', 'enabled', 'rollout', 'updated_at'}:
