        raise ValueError('invalid limit')
    if isinstance(offset, bool) or not isinstance(offset, int) or offset < 0:
        raise ValueError('invalid offset')
    escaped = prefix.replace('\\', '\\\\').replace('%', '\\%').replace('_', '\\_')
    direction = 'DESC' if descending else 'ASC'
    sql = f"SELECT name, enabled, rollout, updated_at FROM feature_flags WHERE environment = ? AND name LIKE ? ESCAPE '\\' ORDER BY {sort_by} {direction}, name ASC LIMIT ? OFFSET ?"
    rows = conn.execute(sql, (environment, escaped + '%', limit, offset)).fetchall()
    return [{'name': name, 'enabled': bool(enabled), 'rollout': float(rollout), 'updated_at': updated_at} for name, enabled, rollout, updated_at in rows]

