import datetime
import hashlib
import hmac
import json

def process_lease_webhook(payload: str, signature: str, shared_key: str, offset: int=0, limit: int=50) -> dict:
    if offset < 0 or limit < 1 or limit > 100:
        raise ValueError('invalid pagination')
    expected = hmac.new(shared_key.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise PermissionError('invalid signature')
    try:
        document = json.loads(payload)
    except json.JSONDecodeError as exc:
        raise ValueError('invalid JSON') from exc
    if not isinstance(document, dict) or not isinstance(document.get('payments'), list):
        raise ValueError('payments must be a list')
    groups = {}
    for payment in document['payments']:
        if not isinstance(payment, dict):
            raise ValueError('invalid payment')
        lease_id = payment.get('lease_id')
        amount = payment.get('amount_cents')
        paid_on = payment.get('paid_on')
        if not isinstance(lease_id, str) or not lease_id:
            raise ValueError('invalid lease_id')
        if isinstance(amount, bool) or not isinstance(amount, int) or amount < 0:
            raise ValueError('invalid amount')
        if not isinstance(paid_on, str):
            raise ValueError('invalid date')
        try:
            parsed = datetime.date.fromisoformat(paid_on)
        except ValueError as exc:
            raise ValueError('invalid date') from exc
        if parsed.isoformat() != paid_on:
            raise ValueError('invalid date')
        group = groups.setdefault(lease_id, {'lease_id': lease_id, 'total_cents': 0, 'payment_count': 0, 'last_paid_on': paid_on})
        group['total_cents'] += amount
        group['payment_count'] += 1
        if paid_on > group['last_paid_on']:
            group['last_paid_on'] = paid_on
    items = sorted(groups.values(), key=lambda item: (-item['total_cents'], item['lease_id']))
    return {'total_leases': len(items), 'total_payments': len(document['payments']), 'items': items[offset:offset + limit]}

