import csv
import datetime
import os
import zipfile

def parse_visit_requests(text: str) -> list[dict]:
    result = []
    for row in csv.reader(text.splitlines()):
        if not row or all((not x.strip() for x in row)):
            continue
        if len(row) != 5:
            raise ValueError('invalid record')
        visitor, inmate, date, times, priority = [x.strip() for x in row]
        try:
            datetime.date.fromisoformat(date)
            a, b = times.split('-')
            ah, am = map(int, a.split(':'))
            bh, bm = map(int, b.split(':'))
            start, end = (ah * 60 + am, bh * 60 + bm)
            p = int(priority)
        except Exception as e:
            raise ValueError('invalid record') from e
        if not (0 <= ah < 24 and 0 <= bh < 24 and (0 <= am < 60) and (0 <= bm < 60) and (start < end) and (0 <= p <= 9)):
            raise ValueError('invalid record')
        result.append({'visitor': visitor, 'inmate': inmate, 'date': date, 'start': start, 'end': end, 'priority': p})
    return result

def schedule_visits(requests: list[dict], daily_limit: int=2) -> list[dict]:
    if daily_limit < 1:
        raise ValueError('invalid limit')
    keys = {'visitor', 'inmate', 'date', 'start', 'end', 'priority'}
    work = []
    for i, r in enumerate(requests):
        if set(r) != keys or not isinstance(r['visitor'], str) or (not isinstance(r['inmate'], str)) or (not isinstance(r['date'], str)):
            raise ValueError('invalid request')
        if not isinstance(r['start'], int) or not isinstance(r['end'], int) or (not isinstance(r['priority'], int)) or (r['start'] < 0) or (r['end'] <= r['start']) or (r['end'] > 1440) or (not 0 <= r['priority'] <= 9):
            raise ValueError('invalid request')
        work.append((r, i))
    work.sort(key=lambda x: (-x[0]['priority'], x[0]['date'], x[0]['start'], x[0]['visitor'], x[0]['inmate'], x[1]))
    chosen = []
    counts = {}
    for r, _ in work:
        key = (r['visitor'], r['date'])
        if counts.get(key, 0) >= daily_limit:
            continue
        conflict = any((r['date'] == q['date'] and (r['visitor'] == q['visitor'] or r['inmate'] == q['inmate'] or (r['start'] < q['end'] and q['start'] < r['end'])) for q in chosen))
        if not conflict:
            chosen.append(r.copy())
            counts[key] = counts.get(key, 0) + 1
    chosen.sort(key=lambda r: (r['date'], r['start'], r['end'], r['visitor'], r['inmate'], -r['priority']))
    return chosen

def extract_schedule_archive(base_dir: str, archive_path: str) -> list[str]:
    try:
        with zipfile.ZipFile(archive_path) as z:
            infos = z.infolist()
            names = [i.filename for i in infos if not i.is_dir()]
            if len(names) != len(set(names)):
                raise ValueError('duplicate name')
            base = os.path.realpath(base_dir)
            os.makedirs(base, exist_ok=True)
            for info in infos:
                if info.is_dir():
                    continue
                target = os.path.realpath(os.path.join(base, info.filename))
                if os.path.commonpath([base, target]) != base:
                    raise ValueError('invalid path')
                os.makedirs(os.path.dirname(target), exist_ok=True)
                with z.open(info) as src, open(target, 'wb') as dst:
                    dst.write(src.read())
            return sorted(names)
    except ValueError:
        raise
    except (OSError, zipfile.BadZipFile, RuntimeError) as e:
        raise ValueError('invalid archive') from e

