    for item in text.split(','):
        m = re.fullmatch('\\s*([A-Za-z]+)\\s*:\\s*(\\d+)\\s*', item)
        if not m or int(m.group(2)) <= 0:
            raise ValueError('invalid scope')
        out.append((m.group(1), int(m.group(2))))
    return out

