import hashlib
import hmac
import json

def analyze_log(payload: str, signature: str, secret: bytes, start: int, end: int, page: int=0, page_size: int=10) -> dict:
    if start > end or page < 0 or page_size <= 0:
        raise ValueError('invalid range or pagination')
    expected = hmac.new(secret, payload.encode('utf-8'), hashlib.sha256).hexdigest()
    try:
        supplied = bytes.fromhex(signature)
    except (ValueError, TypeError):
        raise PermissionError('invalid signature')
    if len(supplied) != hashlib.sha256().digest_size or not hmac.compare_digest(supplied, bytes.fromhex(expected)):
        raise PermissionError('invalid signature')
    try:
        document = json.loads(payload)
    except (TypeError, json.JSONDecodeError):
        raise ValueError('invalid JSON')
    if not isinstance(document, dict) or not isinstance(document.get('events'), list):
        raise ValueError('events must be an array')
    groups = {}
    included = 0
    for event in document['events']:
        if not isinstance(event, dict):
            raise ValueError('invalid event')
        timestamp = event.get('timestamp')
        detector = event.get('detector')
        counts = event.get('counts')
        if isinstance(timestamp, bool) or not isinstance(timestamp, int) or (not isinstance(detector, str)) or (not detector) or isinstance(counts, bool) or (not isinstance(counts, int)) or (counts < 0):
            raise ValueError('invalid event')
        if start <= timestamp <= end:
            if detector not in groups:
                groups[detector] = [0, 0]
            groups[detector][0] += 1
            groups[detector][1] += counts
            included += 1
    summaries = [{'detector': name, 'events': values[0], 'counts': values[1], 'average': round(values[1] / values[0], 2)} for name, values in groups.items()]
    summaries.sort(key=lambda item: (-item['counts'], item['detector']))
    first = page * page_size
    return {'total_events': included, 'detectors': summaries[first:first + page_size]}

