        except ValueError as exc:
            raise ValueError('invalid timestamp') from exc
        seen.add(ident)
        result.append({'id': ident, 'state': state, 'priority': priority, 'labels': clean, 'updated': dt.strftime('%Y-%m-%dT%H:%M:%SZ'), 'title': title})
