from lxml import etree
from datetime import date as Date, datetime

def _read(xml_text):
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'appointments':
        raise ValueError('invalid root')
    return root

def _day(value):
    try:
        return datetime.strptime(value, '%Y-%m-%d').date()
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid date') from exc

def _clock(value):
    try:
        return datetime.strptime(value, '%H:%M').time()
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid time') from exc

def parse_appointments(xml_text: str) -> list[dict]:
    root = _read(xml_text)
    result = []
    seen = set()
    required = ('id', 'date', 'start', 'end', 'client', 'status')
    for node in root:
        if node.tag != 'appointment':
            raise ValueError('unexpected element')
        if any((not node.get(k) for k in required)):
            raise ValueError('missing attribute')
        ident = node.get('id')
        if ident in seen:
            raise ValueError('duplicate id')
        seen.add(ident)
        if node.get('status') not in ('confirmed', 'cancelled'):
            raise ValueError('invalid status')
        day = _day(node.get('date'))
        start = _clock(node.get('start'))
        end = _clock(node.get('end'))
        if end <= start:
            raise ValueError('invalid range')
        services = node.findall('service')
        notes = node.findall('notes')
        if len(services) != 1 or len(notes) > 1:
            raise ValueError('invalid children')
        service = ''.join(services[0].itertext()).strip()
        if not service or not node.get('client').strip():
            raise ValueError('missing value')
        text = ''.join(notes[0].itertext()).strip() if notes else ''
        result.append({'id': ident, 'date': day.isoformat(), 'start': node.get('start'), 'end': node.get('end'), 'client': node.get('client'), 'status': node.get('status'), 'service': service, 'notes': text})
    result.sort(key=lambda x: (x['date'], x['start'], x['id']))
    return result

def daily_totals(xml_text: str, date: str) -> dict:
    target = _day(date).isoformat()
    confirmed = cancelled = 0
    services = {}
    last = None
    for item in parse_appointments(xml_text):
        if item['date'] != target:
            continue
        minutes = int((datetime.strptime(item['end'], '%H:%M') - datetime.strptime(item['start'], '%H:%M')).total_seconds() // 60)
        if item['status'] == 'confirmed':
            confirmed += minutes
        else:
            cancelled += minutes
        services[item['service']] = services.get(item['service'], 0) + 1
        if last is None or item['end'] > last:
            last = item['end']
    return {'date': target, 'confirmed_minutes': confirmed, 'cancelled_minutes': cancelled, 'services': dict(sorted(services.items())), 'last_end': last}

