from lxml import etree

def _parse(xml_text):
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        return etree.fromstring(xml_text.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc

def _text(parent, name):
    node = parent.find(name)
    if node is None or node.text is None or (not node.text.strip()):
        raise ValueError('missing text')
    return node.text.strip()

def parse_provisioning(xml_text: str) -> list[dict]:
    root = _parse(xml_text)
    if root.tag != 'provisioning':
        raise ValueError('invalid root')
    result = []
    seen = set()
    for user in root.findall('user'):
        uid = (user.get('id') or '').strip()
        action = user.get('action')
        if not uid or uid in seen or action not in ('upsert', 'delete'):
            raise ValueError('invalid user')
        seen.add(uid)
        if action == 'delete':
            result.append({'id': uid, 'action': action, 'active': False, 'email': None, 'display_name': None, 'groups': []})
            continue
        active = user.get('active')
        if active not in ('true', 'false'):
            raise ValueError('invalid active')
        profile = user.find('profile')
        if profile is None:
            raise ValueError('missing profile')
        email = _text(profile, 'email')
        display = _text(profile, 'display-name')
        groups_node = user.find('groups')
        groups = []
        if groups_node is not None:
            for group in groups_node.findall('group'):
                if group.text is None or not group.text.strip():
                    raise ValueError('invalid group')
                groups.append(group.text.strip())
        if len(groups) != len(set(groups)):
            raise ValueError('duplicate group')
        result.append({'id': uid, 'action': action, 'active': active == 'true', 'email': email, 'display_name': display, 'groups': sorted(groups)})
    return result

def reconcile_state(state: dict[str, dict], xml_text: str) -> dict[str, dict]:
    operations = parse_provisioning(xml_text)
    result = {key: dict(value) for key, value in state.items()}
    for operation in operations:
        uid = operation['id']
        if operation['action'] == 'delete':
            result.pop(uid, None)
        else:
            result[uid] = {'active': operation['active'], 'email': operation['email'], 'display_name': operation['display_name'], 'groups': list(operation['groups'])}
    return result

