import hashlib
import hmac
import json

def process_results(payload: str, signature: str, secret: str, tournament_id: str) -> list[dict]:
    expected = hmac.new(secret.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()
    try:
        supplied = signature.encode('ascii')
    except UnicodeEncodeError:
        raise PermissionError('invalid signature')
    if not hmac.compare_digest(expected.encode('ascii'), supplied):
        raise PermissionError('invalid signature')
    try:
        document = json.loads(payload)
    except (TypeError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    if not isinstance(document, dict) or not isinstance(document.get('matches'), list):
        raise ValueError('invalid payload')
    rows = {}
    for match in document['matches']:
        if not isinstance(match, dict):
            raise ValueError('invalid match')
        required = ('tournament_id', 'team_a', 'team_b', 'score_a', 'score_b', 'completed')
        if any((key not in match for key in required)):
            raise ValueError('invalid match')
        ta, tb = (match['team_a'], match['team_b'])
        sa, sb = (match['score_a'], match['score_b'])
        if not isinstance(match['tournament_id'], str) or not isinstance(ta, str) or (not isinstance(tb, str)) or (not ta) or (not tb) or (ta == tb) or (type(sa) is not int) or (type(sb) is not int) or (sa < 0) or (sb < 0) or (type(match['completed']) is not bool):
            raise ValueError('invalid match')
        if not match['completed'] or match['tournament_id'] != tournament_id:
            continue
        for team in (ta, tb):
            rows.setdefault(team, {'team': team, 'played': 0, 'wins': 0, 'draws': 0, 'losses': 0, 'points': 0, 'scored': 0, 'conceded': 0, 'difference': 0})
        a, b = (rows[ta], rows[tb])
        a['played'] += 1
        b['played'] += 1
        a['scored'] += sa
        a['conceded'] += sb
        b['scored'] += sb
        b['conceded'] += sa
        if sa > sb:
            a['wins'] += 1
            a['points'] += 3
            b['losses'] += 1
        elif sb > sa:
            b['wins'] += 1
            b['points'] += 3
            a['losses'] += 1
        else:
            a['draws'] += 1
            b['draws'] += 1
            a['points'] += 1
            b['points'] += 1
    for row in rows.values():
        row['difference'] = row['scored'] - row['conceded']
    return sorted(rows.values(), key=lambda r: (-r['points'], -r['difference'], -r['scored'], r['team']))

