def build_search_index(documents: list[dict], output_path: str, query: str='', page: int=1, page_size: int=10) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('page must be positive')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('page_size must be positive')
    if not isinstance(query, str):
        raise ValueError('query must be a string')
    fields = ('id', 'title', 'body', 'category', 'score')
    normalized = []
    for document in documents:
        if not isinstance(document, dict) or any((field not in document for field in fields)):
            raise ValueError('invalid document')
        if any((not isinstance(document[field], str) for field in fields[:4])):
            raise ValueError('invalid document')
        score = document['score']
        if isinstance(score, bool) or not isinstance(score, (int, float)) or (not math.isfinite(score)):
            raise ValueError('invalid document')
        normalized.append({field: document[field] for field in fields})
    needle = query.casefold()
    matches = [d for d in normalized if not needle or needle in d['title'].casefold() or needle in d['body'].casefold()]
    matches.sort(key=lambda d: (-d['score'], d['title'].casefold(), d['id']))
    counts = {}
    for document in matches:
        counts[document['category']] = counts.get(document['category'], 0) + 1
    counts = dict(sorted(counts.items()))
    total = len(matches)
    pages = (total + page_size - 1) // page_size
    start = (page - 1) * page_size
    selected = matches[start:start + page_size]
    directory = os.path.dirname(os.path.abspath(output_path))
    descriptor, temporary_path = tempfile.mkstemp(dir=directory, prefix='.search-')
