import hashlib
import hmac
import json
from datetime import datetime

def _error():
    raise ValueError('invalid reservation document')

def process_reservations(document: str, secret: str) -> dict:
    if not isinstance(document, str) or not document.strip() or (not isinstance(secret, str)):
        _error()
    events = []
    ids = set()
    for raw in document.splitlines():
        if not raw.strip():
            continue
        parts = raw.split('|', 2)
        if len(parts) != 3:
            _error()
        ts_text, supplied, payload_text = parts
        if not ts_text.isdigit() or (len(supplied) != 64 or any((c not in '0123456789abcdef' for c in supplied))):
            _error()
        ts = int(ts_text)
        expected = hmac.new(secret.encode(), (ts_text + '.' + payload_text).encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(supplied, expected):
            _error()
        try:
            obj = json.loads(payload_text)
        except Exception:
            _error()
        if not isinstance(obj, dict):
            _error()
        if not isinstance(obj.get('id'), str) or not obj['id'] or obj['id'] in ids:
            _error()
        if obj.get('action') not in ('reserve', 'cancel') or not isinstance(obj.get('reservation_id'), str) or (not obj['reservation_id']):
            _error()
        if not isinstance(obj.get('occurred_at'), int) or isinstance(obj['occurred_at'], bool) or obj['occurred_at'] < 0:
            _error()
        if obj['action'] == 'reserve':
            for key in ('class_name', 'slot', 'room', 'attendee'):
                if not isinstance(obj.get(key), str) or not obj[key]:
                    _error()
            if not isinstance(obj.get('seats'), int) or isinstance(obj['seats'], bool) or obj['seats'] <= 0:
                _error()
            try:
                datetime.strptime(obj['slot'], '%Y-%m-%d %H:%M')
            except ValueError:
                _error()
        ids.add(obj['id'])
        events.append(obj)
    if not events:
        _error()
    active = {}
    for event in sorted(events, key=lambda x: (x['occurred_at'], x['id'])):
        rid = event['reservation_id']
        if event['action'] == 'cancel':
            active.pop(rid, None)
        else:
            active[rid] = {k: event[k] for k in ('reservation_id', 'class_name', 'slot', 'room', 'attendee', 'seats')}
    result = sorted(active.values(), key=lambda x: (x['slot'], x['room'], x['class_name'], x['reservation_id']))
    by_class = {}
    for item in result:
        by_class[item['class_name']] = by_class.get(item['class_name'], 0) + item['seats']
    return {'reservations': result, 'total_seats': sum((x['seats'] for x in result)), 'by_class': dict(sorted(by_class.items()))}

