def parse_telemetry(text: str) -> list[dict]:
    result = []
    for raw in text.splitlines():
        if not raw.strip() or raw.lstrip().startswith('#'):
            continue
        try:
            row = next(csv.reader([raw]))
        except csv.Error as exc:
            raise ValueError('invalid row') from exc
        if len(row) != 5:
            raise ValueError('invalid row')
        timestamp, spacecraft, sensor, value, status = row
        if not spacecraft or not sensor or status not in ('OK', 'ERR'):
            raise ValueError('invalid row')
        try:
            timestamp = int(timestamp)
            value = float(value)
        except ValueError as exc:
            raise ValueError('invalid number') from exc
        if not math.isfinite(value):
            raise ValueError('invalid number')
        result.append({'timestamp': timestamp, 'spacecraft': spacecraft, 'sensor': sensor, 'value': value, 'status': status})
    return result

def aggregate_telemetry(records: list[dict], window: int=3) -> list[dict]:
    if not isinstance(window, int) or isinstance(window, bool) or window <= 0:
        raise ValueError('invalid window')
    groups = {}
    required = {'timestamp', 'spacecraft', 'sensor', 'value', 'status'}
    for index, record in enumerate(records):
        if not required <= record.keys():
            raise ValueError('invalid record')
        key = (record['spacecraft'], record['sensor'])
        groups.setdefault(key, []).append((index, record))
    output = []
    for (spacecraft, sensor), items in sorted(groups.items()):
        items.sort(key=lambda pair: (pair[1]['timestamp'], pair[0]))
        for pos in range(0, len(items), window):
            batch = [record for _, record in items[pos:pos + window]]
            output.append({'spacecraft': spacecraft, 'sensor': sensor, 'start': batch[0]['timestamp'], 'end': batch[-1]['timestamp'], 'count': len(batch), 'average': sum((r['value'] for r in batch)) / len(batch), 'errors': sum((r['status'] == 'ERR' for r in batch))})
    return output

