import csv
import hashlib
import hmac
import io
from datetime import datetime, timezone
_HEADER = ['call_id', 'account', 'start', 'duration', 'direction', 'status']

def parse_cdr(text: str) -> list[dict]:
    if not isinstance(text, str) or not text:
        raise ValueError('invalid payload')
    try:
        rows = list(csv.reader(io.StringIO(text, newline=''), strict=True))
    except (csv.Error, TypeError):
        raise ValueError('invalid csv')
    if not rows or rows[0] != ['call_id', 'account', 'start', 'duration', 'direction', 'status']:
        raise ValueError('invalid header')
    if len(rows) == 1:
        raise ValueError('no records')
    result = []
    seen = set()
    for row in rows[1:]:
        if len(row) != 6:
            raise ValueError('invalid row')
        call_id, account, start, duration, direction, status = row
        if not call_id or not account or call_id in seen:
            raise ValueError('invalid identity')
        try:
            stamp = datetime.strptime(start, '%Y-%m-%dT%H:%M:%SZ').replace(tzinfo=timezone.utc)
            seconds = int(duration)
        except (ValueError, OverflowError):
            raise ValueError('invalid value')
        if seconds < 0 or direction not in ('in', 'out') or status not in ('completed', 'missed'):
            raise ValueError('invalid value')
        seen.add(call_id)
        result.append({'call_id': call_id, 'account': account, 'start': stamp, 'duration': seconds, 'direction': direction, 'status': status})
    return result

def build_report(records: list[dict]) -> dict:
    accounts = {}
    hours = {}
    total_calls = total_seconds = 0
    for record in records:
        if record['status'] != 'completed':
            continue
        account = record['account']
        item = accounts.setdefault(account, {'calls': 0, 'seconds': 0, 'inbound': 0, 'outbound': 0})
        item['calls'] += 1
        item['seconds'] += record['duration']
        item['inbound' if record['direction'] == 'in' else 'outbound'] += 1
        total_calls += 1
        total_seconds += record['duration']
        hour = record['start'].replace(minute=0, second=0, microsecond=0)
        hours[hour] = hours.get(hour, 0) + 1
    peak = None
    if hours:
        peak = min(hours, key=lambda value: (-hours[value], value))
        peak = peak.strftime('%Y-%m-%dT%H:00:00Z')
    return {'total_calls': total_calls, 'total_seconds': total_seconds, 'accounts': dict(sorted(accounts.items())), 'peak_hour': peak}

def process_webhook(payload: str, secret: str, signature: str) -> dict:
    expected = hmac.new(secret.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    return build_report(parse_cdr(payload))

