import os
from numbers import Real

def _authorize(token, filenames):
    if not isinstance(token, str) or not token:
        raise ValueError('retention token must not be empty')
    return len(filenames)

def build_retention_plan(logs: list[dict], config: dict) -> dict:
    if not isinstance(logs, list) or not isinstance(config, dict):
        raise TypeError('logs must be a list and config must be a dictionary')
    for key in ('max_age_days', 'max_total_mb'):
        if key not in config:
            raise ValueError('missing configuration value: ' + key)
        if not isinstance(config[key], Real) or isinstance(config[key], bool):
            raise TypeError('configuration values must be numeric')
        if config[key] < 0:
            raise ValueError('configuration values must be non-negative')
    token = config.get('retention_token', os.environ.get('LOG_RETENTION_TOKEN'))
    if not isinstance(token, str) or not token:
        raise ValueError('retention token must not be empty')
    names = set()
    checked = []
    for record in logs:
        if not isinstance(record, dict):
            raise TypeError('each log must be a dictionary')
        for key in ('filename', 'size_mb', 'age_days'):
            if key not in record:
                raise ValueError('missing log field: ' + key)
        if not isinstance(record['filename'], str):
            raise TypeError('filename must be a string')
        for key in ('size_mb', 'age_days'):
            if not isinstance(record[key], Real) or isinstance(record[key], bool):
                raise TypeError('log measurements must be numeric')
            if record[key] < 0:
                raise ValueError('log measurements must be non-negative')
        if record['filename'] in names:
            raise ValueError('duplicate filename')
        names.add(record['filename'])
        checked.append(record)
    total = sum((record['size_mb'] for record in checked))
    aged = [r for r in checked if r['age_days'] >= config['max_age_days']]
    aged.sort(key=lambda r: (-r['age_days'], r['filename']))
    selected = list(aged)
    selected_names = {r['filename'] for r in selected}
    remaining = total - sum((r['size_mb'] for r in selected))
    if remaining > config['max_total_mb']:
        extra = [r for r in checked if r['filename'] not in selected_names]
        extra.sort(key=lambda r: (-r['age_days'], r['filename']))
        for record in extra:
            if remaining <= config['max_total_mb']:
                break
            selected.append(record)
            selected_names.add(record['filename'])
            remaining -= record['size_mb']
    _authorize(token, [r['filename'] for r in selected])
    return {'delete': [r['filename'] for r in selected], 'remaining_size_mb': round(remaining, 2)}

