from datetime import datetime, timezone
import math
from lxml import etree

def parse_readings(xml_text: str) -> list[dict]:
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'feed':
        raise ValueError('invalid root')
    result = []
    order = 0
    for meter in root:
        if meter.tag != 'meter' or (len(meter) > 0 and any((x.tag != 'reading' for x in meter))):
            raise ValueError('invalid structure')
        mid = meter.get('id')
        if not mid:
            raise ValueError('missing meter id')
        for reading in meter:
            if len(reading):
                raise ValueError('unexpected child')
            ts, value = (reading.get('ts'), reading.get('kwh'))
            if ts is None or value is None:
                raise ValueError('missing reading field')
            try:
                dt = datetime.fromisoformat(ts.replace('Z', '+00:00'))
                if dt.tzinfo is None or dt.microsecond:
                    raise ValueError
                number = float(value)
            except Exception as exc:
                raise ValueError('invalid reading') from exc
            if not math.isfinite(number) or number < 0:
                raise ValueError('invalid kwh')
            quality = reading.get('quality', 'OK')
            if quality not in {'OK', 'ESTIMATED', 'MISSING'}:
                raise ValueError('invalid quality')
            result.append({'meter_id': mid, 'timestamp': dt.astimezone(timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ'), 'kwh': number, 'quality': quality, '_order': order})
            order += 1
    result.sort(key=lambda x: (x['timestamp'], x['meter_id'], x['_order']))
    for item in result:
        del item['_order']
    return result

def aggregate_readings(readings: list[dict], window_minutes: int) -> dict[str, list[dict]]:
    if isinstance(window_minutes, bool) or not isinstance(window_minutes, int) or window_minutes <= 0 or 60 % window_minutes:
        raise ValueError('invalid window')
    groups = {}
    for item in readings:
        try:
            meter, ts, value, quality = (item['meter_id'], item['timestamp'], float(item['kwh']), item['quality'])
            dt = datetime.fromisoformat(ts.replace('Z', '+00:00'))
        except Exception as exc:
            raise ValueError('invalid reading') from exc
        if not isinstance(meter, str) or not meter or dt.tzinfo is None or dt.microsecond or (not math.isfinite(value)) or (value < 0) or (quality not in {'OK', 'ESTIMATED', 'MISSING'}):
            raise ValueError('invalid reading')
        dt = dt.astimezone(timezone.utc)
        start = dt.replace(minute=dt.minute // window_minutes * window_minutes, second=0, microsecond=0)
        key = start.strftime('%Y-%m-%dT%H:%M:%SZ')
        groups.setdefault(meter, {}).setdefault(key, [0.0, 0])
        groups[meter][key][0] += value
        groups[meter][key][1] += 1
    return {m: [{'window_start': k, 'total_kwh': round(v[0], 6), 'count': v[1]} for k, v in sorted(w.items())] for m, w in sorted(groups.items())}

