    return result

def rank_waitlist(applications: list[dict], income_limit: float) -> list[dict]:
    if income_limit < 0:
        raise ValueError('invalid limit')
    required = {'application_id', 'name', 'household_size', 'annual_income', 'priority', 'submitted'}
    selected = []
    for item in applications:
        if not required <= item.keys():
            raise ValueError('invalid application')
        try:
            date.fromisoformat(item['submitted'])
            if item['household_size'] < 1 or item['annual_income'] < 0 or item['priority'] not in range(4):
