        except (ValueError, TypeError):
            raise ValueError('invalid application')
        if item['annual_income'] <= income_limit:
            copy = dict(item)
            copy['points'] = item['priority'] * 10000 + item['household_size'] * 100 - item['annual_income'] / 1000
            selected.append(copy)
    selected.sort(key=lambda x: (-x['points'], x['submitted'], x['application_id']))
    for i, item in enumerate(selected, 1):
        item['rank'] = i
    return selected

def generate_invite_code(length: int=12) -> str:
    if length < 4 or length > 64:
        raise ValueError('invalid length')
    alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
    return ''.join((random.choice(alphabet) for _ in range(length)))

def issue_invites(ranked: list[dict], limit: int) -> list[dict]:
    if limit < 0:
        raise ValueError('invalid limit')
    result = []
    for item in ranked[:limit]:
        if 'application_id' not in item or 'rank' not in item:
            raise ValueError('invalid application')
        result.append({'application_id': item['application_id'], 'rank': item['rank'], 'invite_code': generate_invite_code()})
    return result

