import hashlib
import hmac
import json
from datetime import date

def summarize_incidents(payload: bytes, signature: str, key: bytes, page: int=1, per_page: int=10) -> dict:
    if page < 1 or per_page < 1:
        raise ValueError('invalid pagination')
    expected = hmac.new(key, payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    try:
        root = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    if not isinstance(root, dict) or not isinstance(root.get('incidents'), list):
        raise ValueError('invalid incidents')
    groups = {}
    for item in root['incidents']:
        if not isinstance(item, dict) or set(item) != {'id', 'department', 'severity', 'status', 'days_open', 'reported_at'}:
            raise ValueError('invalid incident')
        if not isinstance(item['id'], str) or not isinstance(item['department'], str):
            raise ValueError('invalid incident')
        if item['severity'] not in ('low', 'medium', 'high') or item['status'] not in ('open', 'closed'):
            raise ValueError('invalid incident')
        if not isinstance(item['days_open'], int) or isinstance(item['days_open'], bool) or item['days_open'] < 0:
            raise ValueError('invalid incident')
        try:
            date.fromisoformat(item['reported_at'])
        except (TypeError, ValueError):
            raise ValueError('invalid incident')
        if item['status'] == 'open':
            g = groups.setdefault(item['department'], {'department': item['department'], 'count': 0, 'high': 0, 'medium': 0, 'low': 0, 'days': 0})
            g['count'] += 1
            g[item['severity']] += 1
            g['days'] += item['days_open']
    rows = []
    for g in groups.values():
        row = {k: g[k] for k in ('department', 'count', 'high', 'medium', 'low')}
        row['average_days_open'] = round(g['days'] / g['count'], 2)
        rows.append(row)
    rows.sort(key=lambda x: (-x['count'], x['department']))
    start = (page - 1) * per_page
    return {'total_departments': len(rows), 'total_incidents': sum((x['count'] for x in rows)), 'page': page, 'per_page': per_page, 'departments': rows[start:start + per_page]}

