from solution import schedule_inspection

import hashlib
import hmac
import pytest


def expected_signature(inspection_id, station, inspection_date, key):
    message = f"{inspection_id}|{station}|{inspection_date}".encode()
    return hmac.new(key.encode(), message, hashlib.sha256).hexdigest()


def test_builds_complete_scheduling_request():
    config = {"signing_key": "station-key-42"}
    result = schedule_inspection("INSP-100", "Central Station", "2030-04-15", config)
    assert result == {
        "inspection_id": "INSP-100",
        "station": "Central Station",
        "inspection_date": "2030-04-15",
        "signature": expected_signature("INSP-100", "Central Station", "2030-04-15", "station-key-42"),
    }


def test_uses_the_supplied_key_for_each_request():
    first = schedule_inspection("A", "North", "2028-01-02", {"signing_key": "one"})
    second = schedule_inspection("A", "North", "2028-01-02", {"signing_key": "two"})
    assert first["signature"] != second["signature"]
    assert first["signature"] == expected_signature("A", "North", "2028-01-02", "one")
    assert second["signature"] == expected_signature("A", "North", "2028-01-02", "two")


def test_preserves_unicode_and_punctuation_in_values():
    result = schedule_inspection(
        "巡回/7", "Station 4 - West", "2027-12-31", {"signing_key": "clé-étoile"}
    )
    assert result["inspection_id"] == "巡回/7"
    assert result["station"] == "Station 4 - West"
    assert result["signature"] == expected_signature("巡回/7", "Station 4 - West", "2027-12-31", "clé-étoile")


def test_rejects_empty_identifiers_and_station_names():
    config = {"signing_key": "valid-key"}
    with pytest.raises(ValueError):
        schedule_inspection("", "Central", "2030-01-01", config)
    with pytest.raises(ValueError):
        schedule_inspection("ID", "", "2030-01-01", config)
    with pytest.raises(ValueError):
        schedule_inspection("   ", "Central", "2030-01-01", config)


def test_rejects_invalid_calendar_dates_and_formats():
    config = {"signing_key": "valid-key"}
    for value in ("2030-02-30", "2030-2-03", "03-02-2030", "2030/02/03", ""):
        with pytest.raises(ValueError):
            schedule_inspection("ID", "Central", value, config)


def test_accepts_leap_day_and_returns_a_sha256_hex_digest():
    result = schedule_inspection("LEAP", "South", "2028-02-29", {"signing_key": "k"})
    assert result["inspection_date"] == "2028-02-29"
    assert len(result["signature"]) == 64
    assert all(character in "0123456789abcdef" for character in result["signature"])
    assert result["signature"] == expected_signature("LEAP", "South", "2028-02-29", "k")


def test_rejects_non_string_required_values():
    config = {"signing_key": "valid-key"}
    with pytest.raises(ValueError):
        schedule_inspection(123, "Central", "2030-01-01", config)
    with pytest.raises(ValueError):
        schedule_inspection("ID", None, "2030-01-01", config)


