import csv
import math
import os
import tempfile
_FIELDS = ['sku', 'name', 'supplier', 'category', 'price', 'quantity', 'tags']

def _check(r):
    if set(r) != set(_FIELDS):
        raise ValueError('invalid fields')
    for k in ['sku', 'name', 'supplier', 'category']:
        if not isinstance(r[k], str) or not r[k]:
            raise ValueError('invalid text')
    if isinstance(r['price'], bool) or not isinstance(r['price'], (int, float)) or (not math.isfinite(r['price'])) or (r['price'] < 0):
        raise ValueError('invalid price')
    if isinstance(r['quantity'], bool) or not isinstance(r['quantity'], int) or r['quantity'] < 0:
        raise ValueError('invalid quantity')
    if not isinstance(r['tags'], list) or any((not isinstance(x, str) for x in r['tags'])):
        raise ValueError('invalid tags')

def prepare_catalog(records):
    groups = {}
    for r in records:
        _check(r)
        if r['sku'] not in groups:
            groups[r['sku']] = dict(r)
            groups[r['sku']]['tags'] = set(r['tags'])
        else:
            g = groups[r['sku']]
            g['quantity'] += r['quantity']
            g['tags'].update(r['tags'])
            if (r['price'], r['supplier']) < (g['price'], g['supplier']):
                old_tags, quantity = (g['tags'], g['quantity'])
                g = dict(r)
                g['tags'], g['quantity'] = (old_tags, quantity)
                groups[r['sku']] = g
    out = []
    for g in groups.values():
        g['tags'] = sorted(g['tags'])
        out.append(g)
    return sorted(out, key=lambda x: (x['category'].casefold(), x['name'].casefold(), x['sku']))

def _price(v):
    return str(int(v)) if float(v).is_integer() else str(v)

def export_catalog(records, destination):
    rows = prepare_catalog(records)
    parent = os.path.dirname(os.path.abspath(destination))
    fd, tmp = tempfile.mkstemp(dir=parent, prefix='.catalog-')
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as f:
            w = csv.writer(f, lineterminator='\n')
            w.writerow(_FIELDS)
            for r in rows:
                w.writerow([r['sku'], r['name'], r['supplier'], r['category'], _price(r['price']), r['quantity'], ';'.join(r['tags'])])
        os.replace(tmp, destination)
    except Exception:
        try:
            os.unlink(tmp)
        except OSError:
            pass
        raise
    return len(rows)

def read_catalog(path):
    with open(path, encoding='utf-8', newline='') as f:
        r = csv.DictReader(f)
        if r.fieldnames != _FIELDS:
            raise ValueError('invalid header')
        out = []
        for row in r:
            if None in row:
                raise ValueError('invalid row')
            try:
                item = dict(row)
                item['price'] = float(row['price'])
                item['quantity'] = int(row['quantity'])
                item['tags'] = [] if row['tags'] == '' else row['tags'].split(';')
                _check(item)
            except (TypeError, ValueError, OverflowError):
                raise ValueError('invalid row')
            out.append(item)
        return out

