from datetime import date
import re
from typing import Any

def list_deadlines(requester: dict[str, Any], filings: list[dict[str, Any]], from_date: str, to_date: str, as_of: str, page: int=1, page_size: int=20) -> dict[str, Any]:

    def parse(value: Any) -> date:
        if not isinstance(value, str) or not re.fullmatch('\\d{4}-\\d{2}-\\d{2}', value):
            raise ValueError('invalid date')
        try:
            return date.fromisoformat(value)
        except ValueError:
            raise ValueError('invalid date')
    if not isinstance(requester, dict) or any((k not in requester for k in ('id', 'tenant_id', 'roles'))):
        raise ValueError('invalid requester')
    if not isinstance(requester['id'], str) or not isinstance(requester['tenant_id'], str) or (not isinstance(requester['roles'], list)):
        raise ValueError('invalid requester')
    if not isinstance(page, int) or isinstance(page, bool) or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (page < 1) or (page_size < 1):
        raise ValueError('invalid pagination')
    start, finish, reference = (parse(from_date), parse(to_date), parse(as_of))
    if start > finish:
        raise ValueError('invalid range')
    selected = []
    required = ('case_id', 'tenant_id', 'owner_id', 'due_date', 'title', 'status')
    for filing in filings:
        if not isinstance(filing, dict) or any((k not in filing for k in required)) or any((not isinstance(filing[k], str) for k in required)):
            raise ValueError('invalid filing')
        due = parse(filing['due_date'])
        if filing['tenant_id'] != requester['tenant_id'] or (filing['owner_id'] != requester['id'] and 'court_clerk' not in requester['roles']):
            continue
        if start <= due <= finish:
            selected.append((due, filing['case_id'], filing))
    selected.sort(key=lambda x: (x[0], x[1]))
    total = len(selected)
    begin = (page - 1) * page_size
    items = []
    for due, _, filing in selected[begin:begin + page_size]:
        items.append({'case_id': filing['case_id'], 'due_date': filing['due_date'], 'title': filing['title'], 'status': filing['status'], 'days_until': (due - reference).days})
    return {'items': items, 'total': total, 'page': page, 'page_size': page_size}

