import ast

class _Evaluator(ast.NodeVisitor):

    def __init__(self, variables):
        self.variables = variables

    def visit_Expression(self, node):
        return self.visit(node.body)

    def visit_Constant(self, node):
        if isinstance(node.value, (int, float, bool)):
            return node.value
        raise ValueError()

    def visit_Name(self, node):
        if node.id not in self.variables:
            raise ValueError()
        return self.variables[node.id]

    def visit_UnaryOp(self, node):
        value = self.visit(node.operand)
        if isinstance(node.op, ast.USub):
            return -value
        if isinstance(node.op, ast.UAdd):
            return +value
        if isinstance(node.op, ast.Not):
            return not value
        raise ValueError()

    def visit_BinOp(self, node):
        left, right = (self.visit(node.left), self.visit(node.right))
        if isinstance(node.op, ast.Add):
            return left + right
        if isinstance(node.op, ast.Sub):
            return left - right
        if isinstance(node.op, ast.Mult):
            return left * right
        if isinstance(node.op, ast.Div):
            return left / right
        raise ValueError()

    def visit_BoolOp(self, node):
        value = self.visit(node.values[0])
        for item in node.values[1:]:
            if isinstance(node.op, ast.And) and (not value):
                return value
            if isinstance(node.op, ast.Or) and value:
                return value
            value = self.visit(item)
        return value

    def visit_Compare(self, node):
        left = self.visit(node.left)
        for op, item in zip(node.ops, node.comparators):
            right = self.visit(item)
            checks = {ast.Eq: left == right, ast.NotEq: left != right, ast.Lt: left < right, ast.LtE: left <= right, ast.Gt: left > right, ast.GtE: left >= right}
            if type(op) not in checks:
                raise ValueError()
            if not checks[type(op)]:
                return False
            left = right
        return True

    def visit_Call(self, node):
        if not isinstance(node.func, ast.Name) or node.func.id not in {'min', 'max', 'round'} or node.keywords:
            raise ValueError()
        return {'min': min, 'max': max, 'round': round}[node.func.id](*(self.visit(x) for x in node.args))

    def generic_visit(self, node):
        raise ValueError()

def evaluate_rule(expression: str, variables: dict[str, object]) -> object:
    try:
        return _Evaluator(variables).visit(ast.parse(expression, mode='eval'))
    except Exception as exc:
        raise ValueError() from exc

def rank_articles(articles, feedback, expression):
    by_id = {a['id']: a for a in articles}
    totals = {a['id']: [] for a in articles}
    for item in feedback:
        if item['article_id'] in by_id and evaluate_rule(expression, {'rating': item['rating'], 'helpful': item['helpful'], 'day': item['day']}):
            totals[item['article_id']].append(item)
    result = []
    for a in articles:
        rows = totals[a['id']]
        n = len(rows)
        avg = sum((x['rating'] for x in rows)) / n if n else 0.0
        rate = sum((bool(x['helpful']) for x in rows)) / n if n else 0.0
        result.append({'id': a['id'], 'title': a['title'], 'category': a['category'], 'accepted': n, 'average_rating': avg, 'helpful_rate': rate, 'score': round(avg * rate, 2)})
    return sorted(result, key=lambda x: (-x['accepted'], -x['score'], x['id']))

