def process_scholarships(requester: dict, applications: list[dict], budget: int) -> list[dict]:
    if not isinstance(requester, dict) or not isinstance(applications, list):
        raise ValueError('invalid input')
    if type(budget) is not int or budget < 0:
        raise ValueError('invalid budget')
    if not isinstance(requester.get('tenant_id'), str) or not isinstance(requester.get('roles'), list):
        raise ValueError('invalid requester')
    if not {'reviewer', 'admin'} & set(requester['roles']):
        raise PermissionError('not permitted')
    required = {'application_id', 'applicant_id', 'tenant_id', 'status', 'score', 'requested_amount'}
    seen = set()
    valid = []
    for app in applications:
        if not isinstance(app, dict) or set(app) < required:
            raise ValueError('invalid application')
        aid = app['application_id']
        if not isinstance(aid, str) or not aid or aid in seen:
            raise ValueError('invalid application id')
        seen.add(aid)
        if not isinstance(app['applicant_id'], str) or not isinstance(app['tenant_id'], str) or (not isinstance(app['status'], str)):
            raise ValueError('invalid application')
        if type(app['score']) is not int or not 0 <= app['score'] <= 100:
            raise ValueError('invalid score')
        if type(app['requested_amount']) is not int or app['requested_amount'] <= 0:
            raise ValueError('invalid amount')
        if app['status'] == 'submitted':
            if app['tenant_id'] != requester['tenant_id']:
