import tempfile
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def generate_bid_report(bids: list[dict], agency: str, min_score: float=0.0) -> str:
    if not isinstance(bids, list):
        raise ValueError('bids must be a list')
    if isinstance(min_score, bool) or not isinstance(min_score, (int, float)) or (not 0 <= min_score <= 100):
        raise ValueError('invalid minimum score')
    groups = {}
    for bid in bids:
        if not isinstance(bid, dict):
            raise ValueError('invalid bid')
        for key in ('bid_id', 'vendor', 'agency', 'amount', 'score'):
            if key not in bid:
                raise ValueError('missing field')
        if not isinstance(bid['bid_id'], str) or not bid['bid_id']:
            raise ValueError('invalid bid id')
        if not isinstance(bid['vendor'], str) or not bid['vendor']:
            raise ValueError('invalid vendor')
        if not isinstance(bid['agency'], str) or not bid['agency']:
            raise ValueError('invalid agency')
        if isinstance(bid['amount'], bool) or not isinstance(bid['amount'], (int, float)) or bid['amount'] < 0:
            raise ValueError('invalid amount')
        if isinstance(bid['score'], bool) or not isinstance(bid['score'], (int, float)) or (not 0 <= bid['score'] <= 100):
            raise ValueError('invalid score')
        if bid['agency'] == agency and bid['score'] >= min_score:
            try:
                amount = Decimal(str(bid['amount']))
                score = Decimal(str(bid['score']))
            except (InvalidOperation, ValueError):
                raise ValueError('invalid numeric value')
            item = groups.setdefault(bid['vendor'], [0, Decimal('0'), Decimal('0')])
            item[0] += 1
            item[1] += amount
            item[2] += score
    rows = []
    for vendor, (count, total, scores) in groups.items():
        total_text = total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        average = (scores / count).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        rows.append((total, vendor, [vendor, str(count), f'{total_text:.2f}', f'{average:.2f}']))
    rows.sort(key=lambda row: (-row[0], row[1]))
    fd, path = tempfile.mkstemp()
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['vendor', 'bid_count', 'total_amount', 'average_score'])
            for _, _, row in rows:
                writer.writerow(row)
        with open(path, 'r', newline='', encoding='utf-8') as handle:
            return handle.read()
    finally:
        try:
            os.unlink(path)
        except FileNotFoundError:
            pass

