def build_vaccination_summary(records: Sequence[Mapping[str, object]], config: Mapping[str, str], start_date: str, end_date: str) -> dict[str, object]:
    try:
        start = date.fromisoformat(start_date)
        end = date.fromisoformat(end_date)
    except (TypeError, ValueError) as exc:
        raise ValueError('dates must be valid ISO calendar dates') from exc
    if start > end:
        raise ValueError('start_date must not be after end_date')
    groups: dict[str, list[float | int]] = {}
    animals: set[str] = set()
    for record in records:
        try:
            animal = record['animal_id']
            vaccine = record['vaccine']
            raw_date = record['date']
            dose = record['dose_ml']
            status = record['status']
            if not isinstance(animal, str) or not animal or (not isinstance(vaccine, str)) or (not vaccine):
                raise ValueError('animal_id and vaccine must be non-empty strings')
            if not isinstance(raw_date, str):
                raise ValueError('date must be a string')
            record_date = date.fromisoformat(raw_date)
            if status not in ('administered', 'cancelled'):
                raise ValueError('invalid status')
            if isinstance(dose, bool) or not isinstance(dose, (int, float)) or dose <= 0:
                raise ValueError('dose_ml must be positive')
        except (KeyError, TypeError, ValueError) as exc:
            raise ValueError('invalid vaccination record') from exc
        if status == 'administered' and start <= record_date <= end:
            bucket = groups.setdefault(vaccine, [0, 0.0])
            bucket[0] += 1
            bucket[1] += dose
            animals.add(animal)
    vaccines = [{'vaccine': name, 'count': values[0], 'total_dose_ml': round(values[1], 2)} for name, values in groups.items()]
    vaccines.sort(key=lambda item: (-item['count'], item['vaccine']))
    payload = {'start': start_date, 'end': end_date, 'animals': len(animals), 'vaccines': vaccines}
    try:
        key = config['signing_key']
    except KeyError as exc:
        raise KeyError('missing signing_key configuration') from exc
    encoded = json.dumps(payload, sort_keys=True, separators=(',', ':')).encode('utf-8')
    signature = hmac.new(key.encode('utf-8'), encoded, hashlib.sha256).hexdigest()
    return {**payload, 'signature': signature}

