    assert got[0] == {"id":"q2", "difficulty":3, "points":2.5, "prompt":"Capital of France?", "tags":("easy","geo"), "choices":[{"key":"a","text":"London","correct":False},{"key":"b","text":"Paris","correct":True}]}

