    x = '<question-bank version="1"><question id="x" difficulty="1" points="0.10"><prompt>A &amp; B</prompt><tags></tags><choices><choice key="1" correct="true">&lt;yes&gt;</choice><choice key="2" correct="false">no</choice></choices></question></question-bank>'
    q = parse_question_bank(x)[0]
    assert q["prompt"] == "A & B" and q["choices"][0]["text"] == "<yes>" and q["tags"] == ()

def test_parse_rejects_bad_documents():
    bad = ['<question-bank/>', '<question-bank version="2"/>', '<question-bank version="1"><question id="a" difficulty="9" points="1"/></question-bank>', '<question-bank version="1"><question id="a" difficulty="1" points="1"><prompt>x</prompt><choices><choice key="a" correct="true">x</choice></choices></question></question-bank>']
    for text in bad:
        with pytest.raises(ValueError):
            parse_question_bank(text)

def test_duplicate_and_boolean_validation():
    x = '<question-bank version="1"><question id="a" difficulty="1" points="1"><prompt>x</prompt><choices><choice key="a" correct="yes">x</choice><choice key="b" correct="false">y</choice></choices></question><question id="a" difficulty="1" points="1"><prompt>y</prompt><choices><choice key="a" correct="true">x</choice><choice key="b" correct="false">y</choice></choices></question></question-bank>'
