        except (TypeError, ValueError):
            raise ValueError('invalid record')
        amount = record['amount']
        if isinstance(amount, bool) or not isinstance(amount, (int, float)) or amount < 0:
            raise ValueError('invalid record')
        checked.append((record, filed, Decimal(str(amount))))
    matched = [x for x in checked if status is None or x[0]['status'] == status]
    matched.sort(key=lambda x: (x[1], x[0]['case_id']))
