            for record, filed, amount in selected:
                writer.writerow([record['case_id'], filed.isoformat(), record['county'], record['status'], f"{amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP):.2f}"])
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    total = sum((x[2] for x in selected), Decimal('0'))
    counties = {}
