    return {'destination': destination, 'total_matches': len(matched), 'page': page, 'page_size': page_size, 'count': len(selected), 'total_amount': float(total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)), 'by_county': dict(sorted(counties.items()))}

