        pre = (net * fraction).quantize(_CENT)
        tax = (max(pre, Decimal('0.00')) * tax_fraction).quantize(_CENT)
        payout = (pre - tax).quantize(_CENT)
        shows.append({'date': row['date'], 'venue': row['venue'], 'net': net, 'pre_tax': pre, 'tax': tax, 'payout': payout, 'tickets_sold': row['tickets_sold'], 'tickets_capacity': row['tickets_capacity']})
