        totals[2] += row['merchandise']
        totals[3] += payout
        sold += row['tickets_sold']
        capacity += row['tickets_capacity']
    sell = (Decimal(sold) / Decimal(capacity)).quantize(Decimal('0.0001')) if capacity else Decimal('0.0000')
    return {'artist': artist, 'shows': shows, 'gross_total': totals[0].quantize(_CENT), 'expenses_total': totals[1].quantize(_CENT), 'merchandise_total': totals[2].quantize(_CENT), 'payout_total': totals[3].quantize(_CENT), 'tickets_sold': sold, 'tickets_capacity': capacity, 'sell_through': sell}

