import hmac
import json

def verify_registration(raw: str, secret: bytes) -> dict:
    if not isinstance(secret, bytes):
        raise ValueError('invalid secret')
    try:
        obj = json.loads(raw)
        if not isinstance(obj, dict) or set(obj) != {'entity', 'timestamp', 'body', 'signature'}:
            raise ValueError
        entity = obj['entity']
        timestamp = obj['timestamp']
        body = obj['body']
        signature = obj['signature']
        if not isinstance(entity, str) or not entity:
            raise ValueError
        if isinstance(timestamp, bool) or not isinstance(timestamp, int):
            raise ValueError
        if not isinstance(body, dict):
            raise ValueError
        if not isinstance(signature, str) or len(signature) != 64:
            raise ValueError
        supplied = bytes.fromhex(signature)
        canonical = json.dumps(body, sort_keys=True, separators=(',', ':'), ensure_ascii=False)
        expected = hmac.new(secret, canonical.encode('utf-8'), hashlib.sha256).digest()
        if not hmac.compare_digest(expected, supplied):
            raise ValueError
        if not isinstance(body.get('name'), str) or not body['name']:
            raise ValueError
        if body.get('status') not in {'active', 'inactive', 'pending'}:
            raise ValueError
        if isinstance(body.get('employees'), bool) or not isinstance(body.get('employees'), int) or body['employees'] < 0:
            raise ValueError
        if not isinstance(body.get('tags'), list) or any((not isinstance(x, str) for x in body['tags'])):
            raise ValueError
        result = {'entity': entity, 'timestamp': timestamp}
        result.update(body)
        return result
    except (ValueError, TypeError, KeyError, json.JSONDecodeError, UnicodeError):
        raise ValueError('invalid registration')

def build_registry(envelopes: list[str], secret: bytes) -> list[dict]:
