def make_request(readings, secret=b"plant-key"):
    body = json.dumps({"readings": readings}, separators=(",", ":")).encode()
    signature = hmac.new(secret, body, hashlib.sha256).hexdigest()
    return body, signature


def test_empty_batch():
    body, signature = make_request([])
    assert process_batch(body, signature, b"plant-key") == {"sensors": [], "total": 0}


def test_groups_sorts_and_aggregates_readings():
    readings = [
