import hashlib
import hmac
import json
import math

def process_batch(body: bytes, signature: str, secret: bytes) -> dict:
    if not isinstance(signature, str):
        raise PermissionError('invalid signature')
    expected = hmac.new(secret, body, hashlib.sha256).hexdigest()
    if len(signature) != 64 or any((c not in '0123456789abcdef' for c in signature)):
        raise PermissionError('invalid signature')
    if not hmac.compare_digest(expected, signature):
        raise PermissionError('invalid signature')
    try:
        value = json.loads(body.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid JSON') from exc
    if not isinstance(value, dict) or not isinstance(value.get('readings'), list):
        raise ValueError('invalid batch')
    grouped = {}
    for reading in value['readings']:
        if not isinstance(reading, dict):
            raise ValueError('invalid reading')
        sensor = reading.get('sensor')
        ts = reading.get('ts')
        temp = reading.get('temp')
        if not isinstance(sensor, str) or not sensor:
            raise ValueError('invalid reading')
        if isinstance(ts, bool) or not isinstance(ts, int) or ts < 0:
            raise ValueError('invalid reading')
        if isinstance(temp, bool) or not isinstance(temp, (int, float)) or (not math.isfinite(temp)):
            raise ValueError('invalid reading')
        if -40 <= temp <= 125:
            grouped.setdefault(sensor, []).append((ts, temp))
    sensors = []
    total = 0
    for sensor in sorted(grouped):
        items = grouped[sensor]
        latest = items[0]
        for item in items[1:]:
            if item[0] >= latest[0]:
                latest = item
        temps = [item[1] for item in items]
        sensors.append({'sensor': sensor, 'count': len(items), 'average': round(sum(temps) / len(temps), 2), 'minimum': min(temps), 'maximum': max(temps), 'latest_ts': latest[0], 'latest_temperature': latest[1]})
        total += len(items)
    return {'sensors': sensors, 'total': total}

