import re

def parse_tide_table(text: str) -> list[dict]:
    if not text.strip():
        return []
    records = []
    fields = []
    current = []
    escaped = False
    lines = []
    for ch in text:
        if escaped:
            current.append(ch)
            escaped = False
        elif ch == '\\':
            escaped = True
        elif ch == '\n':
            lines.append(''.join(current))
            current = []
        else:
            current.append(ch)
    if escaped:
        raise ValueError('trailing escape')
    lines.append(''.join(current))
    for line in lines:
        if not line.strip():
            continue
        parts = line.split('|')
        if len(parts) != 3:
            raise ValueError('fields')
        tm, height, phase = (x.strip() for x in parts)
        if not re.fullmatch('(?:[01][0-9]|2[0-3]):[0-5][0-9]', tm) or not phase:
            raise ValueError('record')
        try:
            number = float(height)
        except ValueError:
            raise ValueError('height')
        records.append({'time': tm, 'height': number, 'phase': phase})
    return records

def _allowed(requester, assignment):
    return requester.get('tenant_id') == assignment.get('tenant_id') and (requester.get('id') == assignment.get('owner_id') or requester.get('role') in {'dispatcher', 'harbor_master'})

def rank_pilots(requester: dict, assignment_id: str, assignments: list[dict], pilots: list[dict], tide_text: str) -> list[dict]:
    assignment = next((x for x in assignments if x.get('id') == assignment_id), None)
    if assignment is None:
        raise KeyError(assignment_id)
    if not _allowed(requester, assignment):
        raise PermissionError('assignment access denied')
    tides = parse_tide_table(tide_text)
    average = sum((x['height'] for x in tides)) / len(tides) if tides else 0.0
    required = assignment['required_certification']
    limit = assignment['max_distance_nm']
    if assignment['status'] != 'open':
        return []
    result = []
    for pilot in pilots:
        if pilot['tenant_id'] == assignment['tenant_id'] and pilot['available'] and (required in pilot['certifications']) and (pilot['distance_nm'] <= limit):
            eta = round(pilot['distance_nm'] * 12 + average * 3)
            result.append({'pilot_id': pilot['id'], 'eta_minutes': eta, 'experience_years': pilot['experience_years'], 'tide_height': average})
    return sorted(result, key=lambda x: (x['eta_minutes'], -x['experience_years'], x['pilot_id']))

def cancel_assignment(requester: dict, assignment_id: str, assignments: list[dict]) -> list[dict]:
    found = next((x for x in assignments if x.get('id') == assignment_id), None)
    if found is None:
        raise KeyError(assignment_id)
    if not _allowed(requester, found):
        raise PermissionError('assignment access denied')
    if found['status'] in {'cancelled', 'completed'}:
        raise ValueError('terminal assignment')
    result = [dict(x) for x in assignments]
    for item in result:
        if item.get('id') == assignment_id:
            item['status'] = 'cancelled'
    return result

