def cancel_assignment(requester: dict, assignment_id: str, assignments: list[dict]) -> list[dict]:
    found = next((x for x in assignments if x.get('id') == assignment_id), None)
    if found is None:
        raise KeyError(assignment_id)
    if not _allowed(requester, found):
        raise PermissionError('assignment access denied')
    if found['status'] in {'cancelled', 'completed'}:
        raise ValueError('terminal assignment')
    result = [dict(x) for x in assignments]
    for item in result:
        if item.get('id') == assignment_id:
            item['status'] = 'cancelled'
    return result

