import hashlib
import hmac
import json

def parse_enrollment_text(text: str) -> list[dict]:
    result = []
    for raw in text.splitlines():
        line = raw.strip()
        if not line:
            continue
        fields = []
        current = []
        escaped = False
        for char in line:
            if escaped:
                current.append(char)
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == '|':
                fields.append(''.join(current))
                current = []
            else:
                current.append(char)
        if escaped:
            current.append('\\')
        fields.append(''.join(current))
        if len(fields) != 3:
            raise ValueError('invalid enrollment record')
        course, term, hours = (x.strip() for x in fields)
        if not course or not term or (not hours.isdecimal()) or (int(hours) <= 0):
            raise ValueError('invalid enrollment record')
        result.append({'course': course, 'term': term, 'hours': int(hours)})
    return result

def issue_license_bundle(student_id: str, enrollment_text: str, config: dict) -> str:
    if not student_id:
        raise ValueError('student_id is required')
    records = parse_enrollment_text(enrollment_text)
    combined = {}
    for record in records:
        key = (record['course'], record['term'])
        combined[key] = combined.get(key, 0) + record['hours']
    licenses = [{'course': course, 'term': term, 'hours': combined[course, term]} for course, term in sorted(combined)]
    payload = {'student_id': student_id, 'licenses': licenses, 'total_hours': sum((x['hours'] for x in licenses))}
    encoded = json.dumps(payload, separators=(',', ':'), sort_keys=True)
    key = config['signing_key'].encode()
    signature = hmac.new(key, encoded.encode(), hashlib.sha256).hexdigest()
    return encoded + '.' + signature

def validate_license_bundle(bundle: str, config: dict) -> dict:
    try:
        encoded, signature = bundle.rsplit('.', 1)
        expected = hmac.new(config['signing_key'].encode(), encoded.encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(signature, expected):
            raise ValueError('invalid signature')
        payload = json.loads(encoded)
        if set(payload) != {'student_id', 'licenses', 'total_hours'} or not isinstance(payload['student_id'], str):
            raise ValueError('invalid payload')
        licenses = payload['licenses']
        if not isinstance(licenses, list) or not all((set(x) == {'course', 'term', 'hours'} for x in licenses)):
            raise ValueError('invalid payload')
        keys = [(x['course'], x['term']) for x in licenses]
        if keys != sorted(keys) or len(keys) != len(set(keys)):
            raise ValueError('invalid ordering')
        if payload['total_hours'] != sum((x['hours'] for x in licenses)):
            raise ValueError('invalid total')
        return payload
    except (KeyError, TypeError, ValueError, json.JSONDecodeError):
        raise ValueError('invalid bundle')

