def build_survey_report(requester: dict, records: list[dict], region: str | None=None, page: int=1, page_size: int=10) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    allowed = requester.get('id') in {r.get('owner_id') for r in records} or 'admin' in requester.get('roles', []) or 'geologist_admin' in requester.get('roles', [])
    if not allowed:
        raise PermissionError('not permitted')
    required = {'id', 'owner_id', 'tenant_id', 'region', 'mineral', 'depth_m', 'quality'}
    groups = {}
    for record in records:
        if not required.issubset(record) or not isinstance(record['depth_m'], (int, float)) or isinstance(record['depth_m'], bool) or (not isinstance(record['quality'], (int, float))) or isinstance(record['quality'], bool):
            raise ValueError('invalid record')
        if record['tenant_id'] != requester.get('tenant_id') or (region is not None and record['region'] != region):
            continue
        item = groups.setdefault(record['mineral'], {'depths': [], 'qualities': []})
        item['depths'].append(record['depth_m'])
        item['qualities'].append(record['quality'])
    result = []
    for mineral in sorted(groups):
        item = groups[mineral]
        result.append({'mineral': mineral, 'count': len(item['depths']), 'average_depth_m': round(sum(item['depths']) / len(item['depths']), 2), 'maximum_quality': max(item['qualities'])})
    start = (page - 1) * page_size
    return {'page': page, 'page_size': page_size, 'total_groups': len(result), 'groups': result[start:start + page_size]}

