from datetime import datetime, timezone, timedelta

def extract_sensor_bundle(archive_path: str, output_dir: str) -> list[str]:
    with zipfile.ZipFile(archive_path) as z:
        names = [i.filename for i in z.infolist() if not i.is_dir()]
        if len(names) != len(set(names)):
            raise ValueError('duplicate archive member')
        base = os.path.realpath(output_dir)
        targets = []
        for name in names:
            if os.path.isabs(name):
                raise ValueError('invalid member')
            target = os.path.realpath(os.path.join(base, name))
            if os.path.commonpath([base, target]) != base:
                raise ValueError('invalid member')
            targets.append((name, target))
        for name, target in targets:
            os.makedirs(os.path.dirname(target), exist_ok=True)
            with z.open(name) as src, open(target, 'wb') as dst:
                dst.write(src.read())
        return sorted(names)

def read_sensor_log(path: str) -> list[dict]:
    result = []
    with open(path, newline='', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        if reader.fieldnames != ['sensor_id', 'recorded_at', 'temperature_c']:
            raise ValueError('invalid columns')
        for row in reader:
            if row is None or any((v is None for v in row.values())) or (not row['sensor_id']):
                raise ValueError('invalid row')
            text = row['recorded_at']
            if not text.endswith('Z'):
                raise ValueError('timestamp must be UTC')
            try:
                stamp = datetime.fromisoformat(text[:-1] + '+00:00')
                temp = float(row['temperature_c'])
            except Exception as e:
                raise ValueError('invalid row') from e
            if stamp.tzinfo != timezone.utc or not math.isfinite(temp):
                raise ValueError('invalid row')
            result.append({'sensor_id': row['sensor_id'], 'recorded_at': stamp, 'temperature_c': temp})
    result.sort(key=lambda x: (x['recorded_at'], x['sensor_id']))
    return result

def summarize_readings(readings: list[dict], window_minutes: int) -> list[dict]:
    if not isinstance(window_minutes, int) or isinstance(window_minutes, bool) or window_minutes <= 0:
        raise ValueError('invalid window')
    groups = {}
    epoch = datetime(1970, 1, 1, tzinfo=timezone.utc)
    size = timedelta(minutes=window_minutes)
    for r in readings:
        try:
            sensor = r['sensor_id']
            stamp = r['recorded_at']
            temp = r['temperature_c']
        except Exception as e:
            raise ValueError('invalid reading') from e
        if not isinstance(sensor, str) or not sensor or (not isinstance(stamp, datetime)) or (stamp.tzinfo != timezone.utc) or (not isinstance(temp, (int, float))) or isinstance(temp, bool) or (not math.isfinite(temp)):
            raise ValueError('invalid reading')
        start = epoch + (stamp - epoch) // size * size
        groups.setdefault((sensor, start), []).append(float(temp))
    out = []
    for (sensor, start), values in groups.items():
        out.append({'sensor_id': sensor, 'window_start': start.isoformat().replace('+00:00', 'Z'), 'count': len(values), 'minimum_c': min(values), 'maximum_c': max(values), 'average_c': sum(values) / len(values), 'alarm_count': sum((t < 2.0 or t > 8.0 for t in values))})
    out.sort(key=lambda x: (x['window_start'], x['sensor_id']))
    return out

