import sqlite3

def find_recalls(conn: sqlite3.Connection, category: str | None=None, search: str | None=None, sort: str='severity', limit: int=20) -> list[dict]:
    if sort not in {'severity', 'units', 'product', 'risk'}:
        raise ValueError('invalid sort')
    if isinstance(limit, bool) or not isinstance(limit, int) or (not 1 <= limit <= 100):
        raise ValueError('invalid limit')
    order = {'severity': 'severity DESC', 'units': 'units DESC', 'product': 'product ASC', 'risk': 'severity * units DESC'}[sort]
    clauses = []
    args = []
    if category is not None:
        clauses.append('category = ?')
        args.append(category)
    if search is not None:
        clauses.append('lower(product) LIKE lower(?)')
        args.append('%' + search + '%')
    where = ' WHERE ' + ' AND '.join(clauses) if clauses else ''
    rows = conn.execute(f'SELECT id, product, category, severity, units, status, severity * units AS risk FROM recalls{where} ORDER BY {order}, id ASC LIMIT ?', (*args, limit)).fetchall()
    return [dict(row) for row in rows]

