    if status not in {'open', 'investigating', 'contained', 'closed'}:
        raise ValueError('invalid status')
    if not isinstance(note, str) or len(note) > 200:
        raise ValueError('invalid note')
    try:
        with conn:
            cur = conn.execute('UPDATE recalls SET status = ? WHERE id = ?', (status, recall_id))
            if cur.rowcount != 1:
                raise LookupError('recall not found')
            conn.execute('INSERT INTO recall_actions (recall_id, status, note, changed_at) VALUES (?, ?, ?, ?)', (recall_id, status, note, changed_at))
    except LookupError:
        raise
    row = conn.execute('SELECT id, product, category, severity, units, status, severity * units AS risk FROM recalls WHERE id = ?', (recall_id,)).fetchone()
