    rows = conn.execute("SELECT category, COUNT(*) AS recall_count, SUM(units) AS total_units, MAX(severity) AS highest_severity, SUM(CASE WHEN status != 'closed' THEN 1 ELSE 0 END) AS open_count FROM recalls GROUP BY category ORDER BY highest_severity DESC, total_units DESC, category ASC").fetchall()
    return [dict(row) for row in rows]

