import csv
import datetime
import decimal
import os
import zipfile

def extract_repayment_archive(archive_path: str, base_dir: str) -> list[str]:
    root = os.path.realpath(base_dir)
    os.makedirs(root, exist_ok=True)
    result = []
    with zipfile.ZipFile(archive_path) as archive:
        for member in archive.infolist():
            if member.is_dir():
                continue
            target = os.path.realpath(os.path.join(root, member.filename))
            if os.path.commonpath((root, target)) != root:
                raise ValueError('archive member outside base directory')
            os.makedirs(os.path.dirname(target), exist_ok=True)
            with archive.open(member) as source, open(target, 'wb') as destination:
                destination.write(source.read())
            result.append(os.path.relpath(target, root).replace(os.sep, '/'))
    return sorted(result)

def parse_repayments(path: str) -> list[tuple[str, datetime.date, decimal.Decimal, str]]:
    with open(path, 'r', encoding='utf-8', newline='') as handle:
        reader = csv.reader(handle)
        try:
            header = next(reader)
        except StopIteration:
            raise ValueError('missing header')
        if header != ['borrower', 'date', 'amount', 'status']:
            raise ValueError('invalid header')
        result = []
        for row in reader:
            if len(row) != 4:
                raise ValueError('invalid row')
            borrower, raw_date, raw_amount, status = (part.strip() for part in row)
            if not borrower or status not in {'paid', 'missed'}:
                raise ValueError('invalid repayment')
            try:
                parsed_date = datetime.date.fromisoformat(raw_date)
                amount = decimal.Decimal(raw_amount)
            except (ValueError, decimal.InvalidOperation):
                raise ValueError('invalid repayment')
            if not amount.is_finite() or amount < 0:
                raise ValueError('invalid amount')
            result.append((borrower, parsed_date, amount, status))
        return result

def summarize_repayments(rows: list[tuple[str, datetime.date, decimal.Decimal, str]]) -> list[dict]:
    grouped = {}
    for borrower, day, amount, status in rows:
        item = grouped.setdefault(borrower, {'borrower': borrower, 'total_paid': decimal.Decimal('0'), 'missed_count': 0, 'last_date': None})
        if status == 'paid':
            item['total_paid'] += amount
        else:
            item['missed_count'] += 1
        if item['last_date'] is None or day > item['last_date']:
            item['last_date'] = day
    return sorted(grouped.values(), key=lambda x: (-x['total_paid'], x['missed_count'], x['borrower']))

