import hashlib
import hmac
import os

def create_operator_record(operator: str, password: str) -> dict:
    if not isinstance(operator, str) or not isinstance(password, str):
        raise TypeError()
    if not operator or not password:
        raise ValueError()
    salt = os.urandom(16)
    rounds = 100000
    credential = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, rounds).hex()
    return {'operator': operator, 'salt': salt.hex(), 'rounds': rounds, 'credential': credential}

def verify_operator(record: dict, password: str) -> bool:
    if not isinstance(record, dict) or not isinstance(password, str):
        return False
    try:
        operator = record['operator']
        salt = bytes.fromhex(record['salt'])
        rounds = record['rounds']
        expected = record['credential']
        if not isinstance(operator, str) or not operator or (not isinstance(rounds, int)):
            return False
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, rounds).hex()
        return hmac.compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError):
        return False

