from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from datetime import date
from lxml import etree

def summarize_customer_licenses(xml_text: str, customer_id: str, as_of: str, page: int, page_size: int) -> dict:
    if page <= 0 or page_size <= 0:
        raise ValueError('invalid pagination')
    try:
        cutoff = date.fromisoformat(as_of)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml_text.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid xml') from exc
    if root.tag != 'licenses':
        raise ValueError('invalid root')
    required = ('id', 'customer', 'product', 'expires', 'seats', 'price', 'status')
    records = []
    for node in root.findall('license'):
        if any((name not in node.attrib for name in required)):
            raise ValueError('missing attribute')
        try:
            expires = date.fromisoformat(node.get('expires'))
            seats = int(node.get('seats'))
            price = Decimal(node.get('price'))
        except (TypeError, ValueError, InvalidOperation):
            raise ValueError('invalid license')
        if seats <= 0 or price < 0:
            raise ValueError('invalid license')
        if node.get('customer') == customer_id and node.get('status') == 'active' and (expires >= cutoff):
            value = (price * seats).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
            records.append((expires, node.get('id'), {'id': node.get('id'), 'product': node.get('product'), 'expires': node.get('expires'), 'seats': seats, 'value': float(value)}, value))
    records.sort(key=lambda item: (item[0], item[1]))
    total_value = sum((item[3] for item in records), Decimal('0')).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    start = (page - 1) * page_size
    return {'total': len(records), 'total_value': float(total_value), 'items': [item[2] for item in records[start:start + page_size]]}

