def fetch_requests(conn: sqlite3.Connection, status: Optional[str], search: str, sort_by: str, descending: bool, page: int, page_size: int) -> list[dict]:
    if not isinstance(search, str):
        raise TypeError('search must be a string')
    if not isinstance(descending, bool):
        raise TypeError('descending must be a bool')
    if status is not None and status not in {'open', 'pending', 'closed'}:
        raise ValueError('invalid status')
    columns = {'created_at': 'created_at', 'id': 'id', 'priority': 'priority', 'title': 'title'}
    if sort_by not in columns:
        raise ValueError('invalid sort column')
    if page < 1:
        raise ValueError('page must be positive')
    if page_size < 1 or page_size > 100:
        raise ValueError('invalid page size')
    conditions = []
    values = []
    if status is not None:
        conditions.append('status = ?')
        values.append(status)
    if search:
        conditions.append('title LIKE ? COLLATE NOCASE')
        values.append('%' + search + '%')
    query = 'SELECT id, title, status, created_at, priority FROM requests'
    if conditions:
        query += ' WHERE ' + ' AND '.join(conditions)
    direction = 'DESC' if descending else 'ASC'
    query += ' ORDER BY ' + columns[sort_by] + ' ' + direction + ', id ASC LIMIT ? OFFSET ?'
    values.extend([page_size, (page - 1) * page_size])
    cursor = conn.execute(query, values)
    keys = [description[0] for description in cursor.description]
    return [dict(zip(keys, row)) for row in cursor.fetchall()]

