import csv
import datetime
import os
import tempfile

def export_schedule(events: list[dict], destination: str, start_date: str, end_date: str) -> dict:
    if not isinstance(events, list):
        raise ValueError('events must be a list')
    try:
        first = datetime.date.fromisoformat(start_date)
        last = datetime.date.fromisoformat(end_date)
    except (TypeError, ValueError):
        raise ValueError('invalid date range')
    if first > last:
        raise ValueError('reversed date range')
    prepared = []
    for event in events:
        if not isinstance(event, dict):
            raise TypeError('event must be a dictionary')
        if any((key not in event for key in ('date', 'start', 'end', 'candidate', 'interviewer'))):
            raise ValueError('missing event field')
        try:
            day = datetime.date.fromisoformat(event['date'])
            begin = datetime.datetime.strptime(event['start'], '%H:%M')
            finish = datetime.datetime.strptime(event['end'], '%H:%M')
        except (TypeError, ValueError):
            raise ValueError('invalid event')
        if finish <= begin:
            raise ValueError('invalid duration')
        if first <= day <= last:
            minutes = (finish - begin).seconds // 60
            prepared.append((event['date'], event['start'], event['end'], str(event['candidate']), str(event['interviewer']), minutes))
    prepared.sort(key=lambda row: (row[0], row[1], row[3], row[4]))
    counts = {}
    for row in prepared:
        counts[row[0]] = counts.get(row[0], 0) + 1
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent, prefix='.schedule-', suffix='.tmp')
    os.close(fd)
    try:
        with open(temporary, 'w', newline='', encoding='utf-8') as stream:
            writer = csv.writer(stream, lineterminator='\n')
            writer.writerow(['date', 'start', 'end', 'candidate', 'interviewer', 'duration_minutes'])
            writer.writerows(prepared)
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return {'written': len(prepared), 'total_minutes': sum((row[5] for row in prepared)), 'by_day': counts}

