    temporary = tempfile.mktemp(dir=parent, prefix='.schedule-', suffix='.tmp')
    try:
        with open(temporary, 'w', newline='', encoding='utf-8') as stream:
            writer = csv.writer(stream, lineterminator='\n')
            writer.writerow(['date', 'start', 'end', 'candidate', 'interviewer', 'duration_minutes'])
            writer.writerows(prepared)
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return {'written': len(prepared), 'total_minutes': sum((row[5] for row in prepared)), 'by_day': counts}

