import ast
from datetime import date

def _evaluate(source, values):
    tree = ast.parse(source, mode='eval').body

    def visit(node):
        if isinstance(node, ast.Constant):
            if isinstance(node.value, (int, float, str, bool)) or node.value is None:
                return node.value
            raise ValueError('invalid literal')
        if isinstance(node, ast.Name):
            if node.id not in values:
                raise NameError(node.id)
            return values[node.id]
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
            value = visit(node.operand)
            if isinstance(node.op, ast.UAdd):
                return +value
            if isinstance(node.op, ast.USub):
                return -value
            return not value
        if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
            a, b = (visit(node.left), visit(node.right))
            if isinstance(node.op, ast.Add):
                return a + b
            if isinstance(node.op, ast.Sub):
                return a - b
            if isinstance(node.op, ast.Mult):
                return a * b
            return a / b
        if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
            result = visit(node.values[0])
            for child in node.values[1:]:
                if isinstance(node.op, ast.And):
                    if not result:
                        return result
                elif result:
                    return result
                result = visit(child)
            return result
        if isinstance(node, ast.Compare):
            left = visit(node.left)
            for op, right_node in zip(node.ops, node.comparators):
                right = visit(right_node)
                if isinstance(op, ast.Eq):
                    ok = left == right
                elif isinstance(op, ast.NotEq):
                    ok = left != right
                elif isinstance(op, ast.Lt):
                    ok = left < right
                elif isinstance(op, ast.LtE):
                    ok = left <= right
                elif isinstance(op, ast.Gt):
                    ok = left > right
                elif isinstance(op, ast.GtE):
                    ok = left >= right
                else:
                    raise ValueError('invalid comparison')
                if not ok:
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
            return values[node.func.id](*[visit(a) for a in node.args])
        raise ValueError('invalid expression')
    return visit(tree)

def make_cleaning_report(records: list[dict], as_of: str, rule: str, price_expr: str) -> dict:
    try:
        as_date = date.fromisoformat(as_of)
    except Exception as exc:
        raise ValueError('invalid date') from exc
    rows = []
    for record in records:
        try:
            if not isinstance(record['id'], str) or not record['id'] or (not isinstance(record['customer'], str)):
                raise ValueError
            received = date.fromisoformat(record['received'])
            due = date.fromisoformat(record['due'])
            completed = None if record['completed'] is None else date.fromisoformat(record['completed'])
            if not isinstance(record['garments'], int) or record['garments'] < 0 or record['weight_kg'] < 0 or (record['base_price'] < 0):
                raise ValueError
        except Exception as exc:
            raise ValueError('invalid record') from exc
        late = max(0, ((completed or as_date) - due).days)
        values = {'status': record['status'], 'garments': record['garments'], 'weight': record['weight_kg'], 'base': record['base_price'], 'late_days': late, 'min': min, 'max': max, 'round': round}
        selected = _evaluate(rule, values)
        if not isinstance(selected, bool):
            raise ValueError('rule is not boolean')
        if selected:
            price = _evaluate(price_expr, values)
            if isinstance(price, bool) or not isinstance(price, (int, float)):
                raise ValueError('price is not numeric')
            rows.append({'id': record['id'], 'customer': record['customer'], 'status': record['status'], 'late_days': late, 'price': round(price, 2), 'due': due})
    rows.sort(key=lambda x: (x['due'], -x['price'], x['id']))
    orders = [{k: row[k] for k in ('id', 'customer', 'status', 'late_days', 'price')} for row in rows]
    totals = {}
    for row in rows:
        customer = row['customer']
        if customer not in totals:
            totals[customer] = [0, 0]
        totals[customer][0] += 1
        totals[customer][1] += row['price']
    customers = [{'customer': k, 'count': v[0], 'total': round(v[1], 2)} for k, v in totals.items()]
    customers.sort(key=lambda x: (-x['total'], x['customer']))
    return {'orders': orders, 'customers': customers}

