import math
import sqlite3

def enforce_rate_limit(conn: sqlite3.Connection, client_id: str, now: float, window_seconds: int, limit: int) -> dict:
    if not isinstance(client_id, str) or not client_id:
        raise ValueError('invalid client_id')
    if isinstance(now, bool) or not isinstance(now, (int, float)) or (not math.isfinite(now)):
        raise ValueError('invalid now')
    if isinstance(window_seconds, bool) or not isinstance(window_seconds, int) or window_seconds <= 0:
        raise ValueError('invalid window_seconds')
    if isinstance(limit, bool) or not isinstance(limit, int) or limit < 0:
        raise ValueError('invalid limit')
    cutoff = now - window_seconds
    row = conn.execute('SELECT COUNT(*), MIN(occurred_at) FROM requests WHERE client_id = ? AND occurred_at > ? AND occurred_at <= ?', (client_id, cutoff, now)).fetchone()
    count, earliest = row
    if count >= limit or limit == 0:
        return {'allowed': False, 'remaining': 0, 'reset_at': earliest + window_seconds if earliest is not None else now + window_seconds}
    conn.execute('INSERT INTO requests (client_id, occurred_at) VALUES (?, ?)', (client_id, now))
    conn.commit()
    new_count = count + 1
    first = earliest if earliest is not None else now
    return {'allowed': True, 'remaining': limit - new_count, 'reset_at': first + window_seconds}

