def parse_catalog(text: str) -> dict[str, str]:
    result = {}
    current_id = None
    current_value = None
    field = None

    def finish():
        nonlocal current_id, current_value, field
        if current_id is None:
            return
        if field != 'msgstr' or current_value is None:
            raise ValueError('incomplete entry')
        if current_id in result:
            raise ValueError('duplicate msgid')
