    def quote(value):
        return json.dumps(value, ensure_ascii=False)
    keys = []
    if '' in merged:
        keys.append('')
    keys.extend(sorted((key for key in merged if key), key=lambda key: (key.casefold(), key)))
    blocks = []
    for key in keys:
        blocks.append('msgid ' + quote(key) + '\nmsgstr ' + quote(merged[key]))
