from decimal import Decimal, ROUND_HALF_UP

def inventory_report(requester: dict, records: list[dict], page: int=1, page_size: int=20) -> dict:
    if not isinstance(requester, dict) or any((k not in requester for k in ('id', 'tenant_id', 'roles'))) or (not isinstance(requester['roles'], list)):
        raise ValueError('invalid requester')
    if not isinstance(records, list) or type(page) is not int or page <= 0 or (type(page_size) is not int) or (page_size <= 0):
        raise ValueError('invalid arguments')
    required = ('item_id', 'tenant_id', 'owner_id', 'category', 'quantity', 'unit_cost')
    grouped = {}
    for record in records:
        if not isinstance(record, dict) or any((k not in record for k in required)):
            raise ValueError('invalid record')
        if type(record['quantity']) is not int or record['quantity'] < 0:
            raise ValueError('invalid quantity')
        if isinstance(record['unit_cost'], bool) or not isinstance(record['unit_cost'], (int, float)) or record['unit_cost'] < 0:
            raise ValueError('invalid cost')
        if not (record['owner_id'] == requester['id'] or record['tenant_id'] == requester['tenant_id'] or 'inventory_admin' in requester['roles'] or ('warden' in requester['roles'])):
            continue
        category = record['category']
        if category not in grouped:
            grouped[category] = [0, Decimal('0')]
        grouped[category][0] += record['quantity']
        grouped[category][1] += Decimal(str(record['quantity'])) * Decimal(str(record['unit_cost']))
    entries = [{'category': k, 'quantity': v[0], 'value': float(v[1].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))} for k, v in grouped.items()]
    entries.sort(key=lambda x: (-x['quantity'], x['category']))
    total_value = sum((Decimal(str(x['value'])) for x in entries), Decimal('0')).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    start = (page - 1) * page_size
    return {'page': page, 'page_size': page_size, 'total_categories': len(entries), 'total_quantity': sum((x['quantity'] for x in entries)), 'total_value': float(total_value), 'categories': entries[start:start + page_size]}

