import requests

def collect_uptime_status(services: list[dict[str, str]], config: dict[str, str], window_minutes: int=60) -> list[dict[str, object]]:
    if not isinstance(window_minutes, int) or isinstance(window_minutes, bool) or (not 1 <= window_minutes <= 1440):
        raise ValueError('window_minutes must be between 1 and 1440')
    if 'api_token' not in config:
        raise ValueError('missing api_token')
    token = config['api_token']
    result = []
    for service in services:
        response = requests.get(service['url'], headers={'Authorization': 'Bearer ' + token}, timeout=5)
        response.raise_for_status()
        payload = response.json()
        events = payload.get('events') if isinstance(payload, dict) else None
        if not isinstance(events, list):
            raise ValueError('events must be a list')
        remaining = window_minutes
        up_minutes = 0
        incidents = 0
        for event in events:
            if not isinstance(event, dict) or event.get('status') not in ('up', 'down'):
                raise ValueError('invalid event status')
            minutes = event.get('minutes')
            if not isinstance(minutes, int) or isinstance(minutes, bool) or minutes < 0:
                raise ValueError('invalid event minutes')
            consumed = min(minutes, remaining)
            if event['status'] == 'up':
                up_minutes += consumed
            elif consumed > 0:
                incidents += 1
            remaining -= consumed
            if remaining == 0:
                break
        percent = round(up_minutes * 100 / window_minutes, 2)
        result.append({'name': service['name'], 'uptime_percent': percent, 'incidents': incidents, 'status': 'operational' if percent >= 99.0 else 'degraded'})
    result.sort(key=lambda item: (-item['uptime_percent'], item['name']))
    return result

