import datetime
import hashlib
import hmac
import json

def verify_and_summarize(payload: str, signature: str, signing_key: str) -> dict:
    if not isinstance(payload, str) or not isinstance(signature, str) or (not isinstance(signing_key, str)):
        raise TypeError('arguments must be strings')
    expected = hmac.new(signing_key.encode(), payload.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise PermissionError('invalid signature')
    try:
        records = json.loads(payload)
    except json.JSONDecodeError as exc:
        raise ValueError('invalid JSON') from exc
    if not isinstance(records, list):
        raise ValueError('top level must be a list')
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        required = ('employee', 'department', 'pages', 'signed', 'signed_at')
        if any((key not in record for key in required)):
            raise ValueError('missing field')
        employee = record['employee']
        department = record['department']
        pages = record['pages']
        signed_value = record['signed']
        date_text = record['signed_at']
        if not isinstance(employee, str) or not employee or (not isinstance(department, str)) or (not department):
            raise ValueError('invalid name')
        if isinstance(pages, bool) or not isinstance(pages, int) or pages <= 0:
            raise ValueError('invalid pages')
        if not isinstance(signed_value, bool) or not isinstance(date_text, str):
            raise ValueError('invalid record')
        try:
            datetime.date.fromisoformat(date_text)
        except ValueError as exc:
            raise ValueError('invalid date') from exc
        if not signed_value:
            continue
        group = groups.setdefault(department, {'documents': 0, 'pages': 0, 'latest_signed_at': date_text, 'employees': set()})
        group['documents'] += 1
        group['pages'] += pages
        group['latest_signed_at'] = max(group['latest_signed_at'], date_text)
        group['employees'].add(employee)
    departments = []
    for name in sorted(groups):
        group = groups[name]
        departments.append({'name': name, 'documents': group['documents'], 'pages': group['pages'], 'latest_signed_at': group['latest_signed_at'], 'employees': sorted(group['employees'])})
    return {'total_documents': sum((item['documents'] for item in departments)), 'total_pages': sum((item['pages'] for item in departments)), 'departments': departments}

