def build_review_packet(requester: dict, documents: list[dict], query: str='', status: str | None=None, page: int=1, page_size: int=20) -> dict:
    required = {'user_id', 'tenant_id', 'roles'}
    if not required.issubset(requester):
        raise ValueError('invalid requester')
    if not isinstance(documents, list):
        raise TypeError('documents must be a list')
    if not isinstance(query, str) or page < 1 or (not 1 <= page_size <= 100):
        raise ValueError('invalid arguments')
    if status not in (None, 'open', 'in_review', 'closed'):
        raise ValueError('invalid status')
