            raise TypeError('invalid document')
        if doc['tenant_id'] != requester['tenant_id']:
            continue
        if doc['owner_id'] != requester['user_id'] and 'review_lead' not in allowed:
            continue
        if query.casefold() not in doc['title'].casefold():
            continue
        if status is not None and doc['status'] != status:
            continue
        selected.append(doc)
