import hashlib
import hmac
import os

def _normalize(resources):
    if not isinstance(resources, list):
        raise ValueError('resources must be a list')
    result = []
    seen = set()
    for item in resources:
        if not isinstance(item, dict):
            raise ValueError('invalid resource')
        if set(item) != {'id', 'kind', 'version', 'settings'}:
            raise ValueError('invalid resource')
        ident = item['id']
        kind = item['kind']
        version = item['version']
        settings = item['settings']
        if not isinstance(ident, str) or not ident or (not isinstance(kind, str)) or (not kind):
            raise ValueError('invalid resource')
        if not isinstance(version, int) or isinstance(version, bool) or version < 0:
            raise ValueError('invalid resource')
        if not isinstance(settings, dict):
            raise ValueError('invalid resource')
        if ident in seen:
            raise ValueError('duplicate resource')
        seen.add(ident)
        result.append({'id': ident, 'kind': kind, 'version': version, 'settings': copy.deepcopy(settings)})
    result.sort(key=lambda x: (x['kind'], x['id']))
    return result

def create_baseline(resources: list[dict], access_pin: str) -> dict:
    if not isinstance(access_pin, str) or not access_pin:
        raise ValueError('invalid pin')
    normalized = _normalize(resources)
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', access_pin.encode(), salt, 100000)
    credential = 'pbkdf2$100000$' + salt.hex() + '$' + digest.hex()
    return {'credential': credential, 'resources': normalized}

def verify_access_pin(baseline: dict, access_pin: str) -> bool:
    if not isinstance(baseline, dict) or not isinstance(access_pin, str):
        return False
    credential = baseline.get('credential')
    if not isinstance(credential, str):
        return False
    parts = credential.split('$')
    if len(parts) != 4 or parts[0] != 'pbkdf2':
        return False
    try:
        iterations = int(parts[1])
        salt = bytes.fromhex(parts[2])
        expected = bytes.fromhex(parts[3])
        actual = hashlib.pbkdf2_hmac('sha256', access_pin.encode(), salt, iterations)
    except (ValueError, TypeError):
        return False
    return hmac.compare_digest(actual, expected)

def drift_report(baseline: dict, current_resources: list[dict]) -> list[dict]:
    if not isinstance(baseline, dict) or not isinstance(baseline.get('resources'), list):
        raise ValueError('invalid baseline')
    old = _normalize(baseline['resources'])
    current = _normalize(current_resources)
    old_map = {x['id']: x for x in old}
    new_map = {x['id']: x for x in current}
    report = []
    for ident in sorted(set(old_map) | set(new_map)):
        if ident not in old_map:
            report.append({'id': ident, 'change': 'added', 'details': {'current': copy.deepcopy(new_map[ident])}})
        elif ident not in new_map:
            report.append({'id': ident, 'change': 'removed', 'details': {'baseline': copy.deepcopy(old_map[ident])}})
        elif old_map[ident] != new_map[ident]:
            report.append({'id': ident, 'change': 'modified', 'details': {'baseline': copy.deepcopy(old_map[ident]), 'current': copy.deepcopy(new_map[ident])}})
    return report

