    if value is None:
        value = os.environ.get('ENERGY_MARKET_SIGNING_KEY')
    if not isinstance(value, str) or not value:
        raise ValueError('missing signing key')
    return value.encode()

def _body(accepted, totals):
    return json.dumps({'accepted': accepted, 'totals': totals}, sort_keys=True, separators=(',', ':')).encode()

def clear_bids(bids: list[dict], config: dict | None=None) -> dict:
    capacities = (config or {}).get('capacities', {})
    seen = set()
    groups = {}
    for b in bids:
        if not isinstance(b, dict) or set(b) != {'bid_id', 'participant', 'zone', 'delivery', 'price', 'quantity'}:
            raise ValueError('invalid bid')
        if any((not isinstance(b[x], str) or not b[x] for x in ('bid_id', 'participant', 'zone', 'delivery'))):
            raise ValueError('invalid bid')
        try:
            datetime.strptime(b['delivery'], '%Y-%m-%dT%H:%M')
        except Exception as e:
            raise ValueError('invalid delivery') from e
        if not isinstance(b['price'], (int, float)) or isinstance(b['price'], bool) or (not isinstance(b['quantity'], (int, float))) or isinstance(b['quantity'], bool) or (b['quantity'] <= 0):
            raise ValueError('invalid numeric value')
        if b['bid_id'] in seen:
            raise ValueError('duplicate bid')
        seen.add(b['bid_id'])
        groups.setdefault((b['zone'], b['delivery']), []).append(b)
    accepted = []
    totals = {}
    for group in sorted(groups):
        cap = capacities.get(group, float('inf'))
        if not isinstance(cap, (int, float)) or isinstance(cap, bool) or cap < 0:
            raise ValueError('invalid capacity')
        used = 0
        for b in sorted(groups[group], key=lambda x: (x['price'], x['participant'], x['bid_id'])):
            amount = min(b['quantity'], cap - used)
            if amount > 0:
                accepted.append({'bid_id': b['bid_id'], 'accepted_quantity': amount, 'price': b['price'], 'zone': b['zone'], 'delivery': b['delivery']})
                used += amount
        if used:
            totals[group[0] + '|' + group[1]] = used
    signature = hmac.new(_key(config), _body(accepted, totals), hashlib.sha256).hexdigest()
    return {'accepted': accepted, 'totals': totals, 'signature': signature}

