    if not isinstance(report, dict) or set(report) != {'accepted', 'totals', 'signature'} or (not isinstance(report['signature'], str)):
        raise ValueError('malformed report')
    expected = hmac.new(_key(config), _body(report['accepted'], report['totals']), hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, report['signature'])

