        raise ValueError('invalid template')
    if not isinstance(recovery_pin, str) or len(recovery_pin) != 4 or (not recovery_pin.isascii()) or (not recovery_pin.isdigit()):
        raise ValueError('invalid PIN')
    return {'user_id': user_id.strip(), 'template': template, 'pin_hash': _hash_pin(recovery_pin)}

