def get_cafeteria_receipt(requester: dict, orders: list[dict], menu: dict[str, dict], order_id: str, page: int=1, page_size: int=10) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 50):
        raise ValueError('invalid page size')
    order = next((item for item in orders if item.get('order_id') == order_id), None)
    if order is None:
        raise KeyError(order_id)
    roles = requester.get('roles', [])
    if order.get('tenant_id') != requester.get('tenant_id') or (order.get('owner_id') != requester.get('user_id') and 'cafeteria_manager' not in roles):
        raise PermissionError('order access denied')
    if order.get('status') != 'submitted':
        raise ValueError('order is not submitted')
    grouped = {}
    for entry in order.get('lines', []):
        qty = entry.get('qty')
        if not isinstance(qty, int) or isinstance(qty, bool) or qty <= 0:
            raise ValueError('invalid quantity')
        sku = entry.get('sku')
        if sku not in menu:
            raise KeyError(sku)
        item = menu[sku]
        if not item.get('available'):
            raise ValueError('item unavailable')
        grouped[sku] = grouped.get(sku, 0) + qty
    rows = []
    for sku, quantity in grouped.items():
        item = menu[sku]
        price = item['price_cents']
        rows.append({'sku': sku, 'name': item['name'], 'quantity': quantity, 'unit_price_cents': price, 'line_total_cents': price * quantity})
    rows.sort(key=lambda row: (row['name'], row['sku']))
    subtotal = sum((row['line_total_cents'] for row in rows))
    fee = (subtotal * 5 + 50) // 100
    start = (page - 1) * page_size
    return {'order_id': order_id, 'tenant_id': order['tenant_id'], 'lines': rows[start:start + page_size], 'total_lines': len(rows), 'subtotal_cents': subtotal, 'service_fee_cents': fee, 'total_cents': subtotal + fee, 'page': page, 'page_size': page_size}

