import ast
import operator

def _value(node, names):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in names:
            raise NameError("name '%s' is not defined" % node.id)
        return names[node.id]
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
        value = _value(node.operand, names)
        return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
    if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
        left = _value(node.left, names)
        right = _value(node.right, names)
        return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
    if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
        value = _value(node.values[0], names)
        for child in node.values[1:]:
            if isinstance(node.op, ast.And) and (not value) or (isinstance(node.op, ast.Or) and value):
                return value
            value = _value(child, names)
        return value
    if isinstance(node, ast.Compare):
        left = _value(node.left, names)
        for op, child in zip(node.ops, node.comparators):
            right = _value(child, names)
            if not {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}[type(op)](left, right):
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
        functions = {'min': min, 'max': max, 'round': round}
        return functions[node.func.id](*[_value(x, names) for x in node.args])
    raise ValueError('unsupported expression')

def select_talent(players: list[dict], expression: str, minimum: float, offset: int, limit: int) -> list[dict]:
    if offset < 0 or limit <= 0:
        raise ValueError('invalid paging')
    tree = ast.parse(expression, mode='eval').body
    ranked = []
    for player in players:
        names = {key: player[key] for key in ('name', 'age', 'speed', 'finishing', 'potential')}
        score = _value(tree, names)
        if score >= minimum:
