import os

def create_charging_report(records: list[dict], page: int=1, page_size: int=10, config: dict | None=None) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('page must be at least 1')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('page_size must be between 1 and 100')
    totals = {}
    for record in records:
        for name in ('scooter_id', 'station', 'started_at', 'status'):
            if not isinstance(record.get(name), str) or not record[name]:
                raise ValueError('invalid record field')
        energy = record.get('energy_kwh')
        if isinstance(energy, bool) or not isinstance(energy, (int, float)) or energy < 0:
            raise ValueError('invalid energy')
        if record['status'] == 'completed':
            station = record['station']
            if station not in totals:
                totals[station] = [0, 0.0]
            totals[station][0] += 1
            totals[station][1] += energy
    stations = [{'station': station, 'sessions': values[0], 'total_energy_kwh': round(values[1], 2)} for station, values in totals.items()]
    stations.sort(key=lambda item: (-item['total_energy_kwh'], item['station']))
    total_sessions = sum((item['sessions'] for item in stations))
    start = (page - 1) * page_size
    payload = {'page': page, 'page_size': page_size, 'total_sessions': total_sessions, 'stations': stations[start:start + page_size]}
    key = None
    if config is not None:
        key = config.get('CHARGING_SIGNING_KEY')
    if not key:
        key = os.environ.get('SCOOTER_CHARGING_SIGNING_KEY')
    if not key:
        raise RuntimeError('charging signing key is missing')
    data = json.dumps(payload, sort_keys=True, separators=(',', ':')).encode()
    payload['signature'] = hmac.new(key.encode(), data, hashlib.sha256).hexdigest()
    return payload

