import sqlite3

def search_alerts(conn: sqlite3.Connection, neighborhood: str | None=None, severity: str | None=None, query: str='', sort_by: str='created_at', descending: bool=True, limit: int=20, offset: int=0) -> list[dict]:
    if sort_by not in {'created_at', 'severity', 'id'}:
        raise ValueError('invalid sort column')
    if not isinstance(limit, int) or isinstance(limit, bool) or (not 1 <= limit <= 100):
        raise ValueError('invalid limit')
    if not isinstance(offset, int) or isinstance(offset, bool) or offset < 0:
        raise ValueError('invalid offset')
    conditions = []
    if neighborhood is not None:
        conditions.append(f"neighborhood = '{neighborhood}'")
    if severity is not None:
        conditions.append(f"severity = '{severity}'")
    if query:
        pattern = '%' + query + '%'
        conditions.append(f"(lower(title) LIKE lower('{pattern}') OR lower(description) LIKE lower('{pattern}'))")
    where = ' WHERE ' + ' AND '.join(conditions) if conditions else ''
    direction = 'DESC' if descending else 'ASC'
    sql = f'SELECT id, neighborhood, title, description, severity, status, created_at FROM alerts{where} ORDER BY {sort_by} {direction}, id ASC LIMIT {limit} OFFSET {offset}'
    rows = conn.execute(sql).fetchall()
    keys = ['id', 'neighborhood', 'title', 'description', 'severity', 'status', 'created_at']
    return [dict(zip(keys, row)) for row in rows]

