def _validate(obj):
    keys = {'candidate', 'role', 'amount', 'currency', 'timestamp', 'status'}
    if not isinstance(obj, dict) or set(obj) != keys:
        raise ValueError('invalid offer')
    if not isinstance(obj['candidate'], str) or not obj['candidate']:
        raise ValueError('invalid offer')
    if not isinstance(obj['role'], str) or not obj['role']:
        raise ValueError('invalid offer')
    if isinstance(obj['amount'], bool) or not isinstance(obj['amount'], int) or obj['amount'] < 0:
        raise ValueError('invalid offer')
    if not isinstance(obj['currency'], str) or len(obj['currency']) != 3 or (not obj['currency'].isalpha()) or (not obj['currency'].isascii()) or (obj['currency'] != obj['currency'].upper()):
        raise ValueError('invalid offer')
    if not isinstance(obj['timestamp'], str) or len(obj['timestamp']) != 20 or obj['timestamp'][-1] != 'Z':
        raise ValueError('invalid offer')
    try:
        datetime.strptime(obj['timestamp'], '%Y-%m-%dT%H:%M:%SZ')
    except ValueError:
        raise ValueError('invalid offer')
    if obj['status'] not in ('open', 'closed'):
        raise ValueError('invalid offer')

def evaluate_offers(batch: str, secret: str) -> list[dict]:
    chosen = {}
    expected_key = secret.encode('utf-8')
