            raise ValueError('invalid json') from exc
        _validate(obj)
        if obj['status'] == 'closed':
            continue
        old = chosen.get(obj['candidate'])
        if old is None or (obj['amount'], -int(datetime.strptime(obj['timestamp'], '%Y-%m-%dT%H:%M:%SZ').timestamp()), '' if obj['role'] > old['role'] else obj['role']) > (old['amount'], -int(datetime.strptime(old['timestamp'], '%Y-%m-%dT%H:%M:%SZ').timestamp()), '' if old['role'] > obj['role'] else old['role']):
            chosen[obj['candidate']] = obj
    return [chosen[k] for k in sorted(chosen)]

