import ast
import operator

def _value(node, names):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in names:
            raise ValueError()
        return names[node.id]
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
        value = _value(node.operand, names)
        if isinstance(node.op, ast.UAdd):
            return +value
        if isinstance(node.op, ast.USub):
            return -value
        return not value
    if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
        a, b = (_value(node.left, names), _value(node.right, names))
        return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](a, b)
    if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
        result = _value(node.values[0], names)
        for child in node.values[1:]:
            if isinstance(node.op, ast.And):
                if not result:
                    return result
            elif result:
                return result
            result = _value(child, names)
        return result
    if isinstance(node, ast.Compare):
        left = _value(node.left, names)
        for op, child in zip(node.ops, node.comparators):
            right = _value(child, names)
            if not isinstance(op, (ast.Lt, ast.LtE, ast.Gt, ast.GtE, ast.Eq, ast.NotEq)):
                raise ValueError()
            good = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}[type(op)](left, right)
            if not good:
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
        args = [_value(x, names) for x in node.args]
        if node.func.id == 'round' and len(args) in (1, 2):
            return round(*args)
        if node.func.id in ('min', 'max') and len(args) >= 2:
            return min(*args) if node.func.id == 'min' else max(*args)
    raise ValueError()

def _evaluate(expression, names):
    try:
        return _value(ast.parse(expression, mode='eval').body, names)
    except Exception as exc:
        raise ValueError() from exc

def rank_trains(trains: list[dict], rule: str, score: str, limit: int) -> list[dict]:
    if limit < 0:
        raise ValueError()
    chosen = []
    for train in trains:
        names = {key: train[key] for key in ('price', 'duration', 'changes', 'seats', 'departure')}
        if not isinstance(_evaluate(rule, names), bool):
            raise ValueError()
        if _evaluate(rule, names):
            value = _evaluate(score, names)
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise ValueError()
            chosen.append((value, train))
    chosen.sort(key=lambda item: (-item[0], item[1]['id']))
    return [train for _, train in chosen[:limit]]

