def prepare_custody_invites(records: list[dict], officer_id: str, page: int=1, page_size: int=20) -> list[dict]:
    if not isinstance(records, list) or not isinstance(officer_id, str) or (not officer_id):
        raise ValueError('invalid arguments')
    if not isinstance(page, int) or page < 1 or (not isinstance(page_size, int)) or (not 1 <= page_size <= 100):
        raise ValueError('invalid pagination')
    required = {'evidence_id', 'destination', 'status', 'priority', 'collected_at'}
    eligible = []
    for record in records:
        if not isinstance(record, dict) or not required.issubset(record):
            raise ValueError('invalid record')
        if not all((isinstance(record[key], str) for key in ('evidence_id', 'destination', 'status', 'collected_at'))):
            raise ValueError('invalid record')
        if not isinstance(record['priority'], int):
            raise ValueError('invalid record')
        try:
            parsed = datetime.fromisoformat(record['collected_at'])
        except ValueError as exc:
            raise ValueError('invalid record') from exc
        if record['status'] == 'awaiting_transfer' and record['destination'] == officer_id:
            eligible.append((record, parsed))
    eligible.sort(key=lambda item: (-item[0]['priority'], item[1], item[0]['evidence_id']))
    start = (page - 1) * page_size
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    result = []
    for record, _ in eligible[start:start + page_size]:
        code = ''.join((secrets.choice(alphabet) for _ in range(10)))
        result.append({'evidence_id': record['evidence_id'], 'destination': record['destination'], 'priority': record['priority'], 'collected_at': record['collected_at'], 'code': code})
    return result

