import hashlib
import hmac
import json
from decimal import Decimal, InvalidOperation, ROUND_HALF_EVEN

def create_membership_report(records: list[dict], config: dict) -> dict:
    try:
        key = config['receipt_signing_key']
    except (KeyError, TypeError):
        raise ValueError('receipt_signing_key is required')
    if not isinstance(key, str) or not key:
        raise ValueError('receipt_signing_key is required')
    groups = {}
    required = ('member_id', 'name', 'congregation', 'status', 'monthly_pledge')
    for record in records:
        if not isinstance(record, dict) or any((field not in record for field in required)):
            raise ValueError('invalid membership record')
        if any((not isinstance(record[field], str) for field in ('member_id', 'name', 'congregation', 'status'))):
            raise ValueError('invalid membership record')
        try:
            amount = Decimal(str(record['monthly_pledge']))
            if not amount.is_finite() or amount < 0:
                raise ValueError
        except (InvalidOperation, ValueError, TypeError):
            raise ValueError('invalid membership record')
        if record['status'] == 'active':
            groups.setdefault(record['congregation'], []).append((record['member_id'], record['name'], amount))
    congregations = []
    for name in sorted(groups):
        members = sorted(groups[name], key=lambda item: (-item[2], item[1], item[0]))
        listed = [{'member_id': member_id, 'name': member_name, 'monthly_pledge': f"{amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_EVEN):.2f}"} for member_id, member_name, amount in members]
        total = sum((item[2] for item in members), Decimal('0')).quantize(Decimal('0.01'), rounding=ROUND_HALF_EVEN)
        congregations.append({'name': name, 'member_count': len(members), 'monthly_total': f'{total:.2f}', 'members': listed})
    payload = json.dumps(congregations, sort_keys=True, separators=(',', ':')).encode('utf-8')
    signature = hmac.new(key.encode('utf-8'), payload, hashlib.sha256).hexdigest()
    return {'congregations': congregations, 'signature': signature}

