import os
import subprocess

def list_filing_documents(directory: str, extension: str='.pdf', page: int=1, page_size: int=10) -> list[dict]:
    if not isinstance(extension, str) or not extension or (not extension.startswith('.')):
        raise ValueError('invalid extension')
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('invalid page size')
    if not os.path.exists(directory):
        raise FileNotFoundError(directory)
    if not os.path.isdir(directory):
        raise NotADirectoryError(directory)
    result = subprocess.run(['find', directory, '-type', 'f', '-print'], capture_output=True, text=True, check=True)
    records = []
    for raw_path in result.stdout.splitlines():
        if not raw_path.endswith(extension):
            continue
        relative = os.path.relpath(raw_path, directory).replace(os.sep, '/')
        records.append({'name': os.path.basename(raw_path), 'path': relative, 'bytes': os.path.getsize(raw_path)})
    records.sort(key=lambda item: (-item['bytes'], item['path']))
    start = (page - 1) * page_size
    return records[start:start + page_size]

