def register_operator(operator_id: str, password: str) -> dict:
    if not isinstance(operator_id, str) or not isinstance(password, str):
        raise ValueError('invalid operator')
    operator_id = operator_id.strip()
    if not operator_id or len(password) < 8:
        raise ValueError('invalid operator')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return {'operator_id': operator_id, 'credential': salt.hex() + '$' + digest.hex()}

def verify_operator(record: dict, password: str) -> bool:
    if not isinstance(record, dict) or not isinstance(password, str):
        return False
    operator_id = record.get('operator_id')
    credential = record.get('credential')
    if not isinstance(operator_id, str) or not operator_id.strip() or (not isinstance(credential, str)):
        return False
    try:
        salt_hex, digest_hex = credential.split('$', 1)
        salt = bytes.fromhex(salt_hex)
        expected = bytes.fromhex(digest_hex)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def schedule_reservoir(readings: list[dict], target_mw: float, page: int=1, page_size: int=10) -> list[dict]:
    if not isinstance(readings, list) or not isinstance(target_mw, (int, float)) or isinstance(target_mw, bool) or (not math.isfinite(target_mw)) or (target_mw < 0):
        raise ValueError('invalid input')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1 or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (page_size < 1):
        raise ValueError('invalid page')
    groups = {}
    for index, item in enumerate(readings):
        if not isinstance(item, dict):
            raise ValueError('invalid reading')
        station = item.get('station')
        timestamp = item.get('timestamp')
        inflow = item.get('inflow_m3s')
        capacity = item.get('capacity_mw')
        if not isinstance(station, str) or not station or (not isinstance(timestamp, int)) or isinstance(timestamp, bool) or (not isinstance(inflow, (int, float))) or isinstance(inflow, bool) or (not math.isfinite(inflow)) or (inflow < 0) or (not isinstance(capacity, (int, float))) or isinstance(capacity, bool) or (not math.isfinite(capacity)) or (capacity <= 0):
