        groups.setdefault(station, {'inflows': [], 'latest': (timestamp, index, float(capacity))})
        groups[station]['inflows'].append(float(inflow))
        if (timestamp, index) >= groups[station]['latest'][:2]:
            groups[station]['latest'] = (timestamp, index, float(capacity))
    means = {s: sum(v['inflows']) / len(v['inflows']) for s, v in groups.items()}
