import hashlib
import hmac
import json
from datetime import date
from collections import OrderedDict

def _key(config):
    key = config.get('signing_key') if isinstance(config, dict) else None
    if not isinstance(key, str) or not key:
        raise ValueError('signing_key is required')
    return key.encode('utf-8')

def _canonical(value):
    return json.dumps(value, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode('utf-8')

def build_maintenance_report(records: list[dict], config: dict) -> dict:
    key = _key(config)
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    grouped = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        required = ('vehicle_id', 'date', 'mileage', 'action', 'cost_cents')
        if any((field not in record for field in required)):
            raise ValueError('invalid record')
        vehicle = record['vehicle_id']
        action = record['action']
        if not isinstance(vehicle, str) or not vehicle or (not isinstance(action, str)) or (not action):
            raise ValueError('invalid record')
        try:
            date.fromisoformat(record['date'])
        except (TypeError, ValueError):
            raise ValueError('invalid record')
        if not isinstance(record['mileage'], int) or isinstance(record['mileage'], bool) or record['mileage'] < 0 or (not isinstance(record['cost_cents'], int)) or isinstance(record['cost_cents'], bool) or (record['cost_cents'] < 0):
            raise ValueError('invalid record')
        grouped.setdefault(vehicle, []).append({'date': record['date'], 'mileage': record['mileage'], 'action': action, 'cost_cents': record['cost_cents']})
    vehicles = OrderedDict()
    for vehicle in sorted(grouped):
        events = sorted(grouped[vehicle], key=lambda x: (x['date'], x['mileage'], x['action']))
        counts = {event['action']: sum((1 for item in events if item['action'] == event['action'])) for event in events}
        counts = OrderedDict(((name, counts[name]) for name in sorted(counts)))
        mileages = [event['mileage'] for event in events]
        vehicles[vehicle] = {'events': events, 'total_cost_cents': sum((event['cost_cents'] for event in events)), 'distance_miles': max(mileages) - min(mileages) if len(events) > 1 else 0, 'action_counts': counts}
    payload = dict(vehicles)
    signature = hmac.new(key, _canonical(payload), hashlib.sha256).hexdigest()
    return {'vehicles': payload, 'signature': signature}

def verify_maintenance_report(report: dict, config: dict) -> bool:
    key = _key(config)
    if not isinstance(report, dict) or not isinstance(report.get('vehicles'), dict) or (not isinstance(report.get('signature'), str)):
        return False
    expected = hmac.new(key, _canonical(report['vehicles']), hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, report['signature'])

