            raise ValueError
        signers = raw['signers']
        attachments = raw['attachments']
        if not isinstance(signers, list) or not isinstance(attachments, list):
            raise ValueError
        for s in signers:
            if not isinstance(s, dict) or not isinstance(s.get('name'), str) or (not s['name']) or (not isinstance(s.get('email'), str)) or (not s['email']):
                raise ValueError
            if 'signed_at' in s and (not isinstance(s['signed_at'], str)):
                raise ValueError
        for a in attachments:
            if not isinstance(a, dict) or not isinstance(a.get('name'), str) or (not a['name']) or (not isinstance(a.get('label'), str)) or (not a['label']):
                raise ValueError
            if not isinstance(a.get('sha256'), str) or len(a['sha256']) != 64 or any((c not in '0123456789abcdef' for c in a['sha256'])):
                raise ValueError
        if len({a['name'] for a in attachments}) != len(attachments):
            raise ValueError
        return raw
    except (KeyError, TypeError):
        raise ValueError

def extract_envelope(package_path: str, output_dir: str) -> dict:
    try:
        with zipfile.ZipFile(package_path) as zf:
            try:
                raw = json.loads(zf.read('envelope.json').decode('utf-8'))
            except Exception as e:
                raise ValueError from e
            m = _manifest(raw)
            names = set(zf.namelist())
            base = Path(output_dir).resolve()
            pending = []
            for a in m['attachments']:
