                    raise ValueError
                data = zf.read(a['name'])
                if hashlib.sha256(data).hexdigest() != a['sha256']:
                    raise ValueError
                pending.append((target, a, data))
            for target, _, data in pending:
                target.parent.mkdir(parents=True, exist_ok=True)
                target.write_bytes(data)
            signers = sorted(m['signers'], key=lambda s: (s['name'].casefold(), s['email'].casefold()))
            attachments = sorted(({'name': a['name'], 'label': a['label'], 'size': len(data)} for _, a, data in pending), key=lambda a: (a['label'].casefold(), a['name'].casefold()))
