def summarize_webinars(conn: sqlite3.Connection, topic: str | None=None, min_attendees: int=0, sort_by: str='start', page: int=1, page_size: int=10) -> list[dict]:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
    if isinstance(min_attendees, bool) or not isinstance(min_attendees, int) or min_attendees < 0:
        raise ValueError('invalid attendee count')
    ordering = {'start': 'w.start_time', 'title': 'w.title', 'registered': 'registered', 'remaining': 'remaining'}
    if sort_by not in ordering:
        raise ValueError('invalid sort')
    conditions = []
    parameters = []
    if topic is not None:
        conditions.append('w.topic = ?')
        parameters.append(topic)
    where = ' WHERE ' + ' AND '.join(conditions) if conditions else ''
    offset = (page - 1) * page_size
    query = 'SELECT w.id, w.title, w.topic, w.start_time, COUNT(r.id) AS registered, w.capacity - COUNT(r.id) AS remaining FROM webinars w LEFT JOIN registrations r ON r.webinar_id = w.id' + where + ' GROUP BY w.id, w.title, w.topic, w.start_time, w.capacity HAVING COUNT(r.id) >= ? ORDER BY ' + ordering[sort_by] + ' ASC, w.id ASC LIMIT ? OFFSET ?'
    parameters.extend([min_attendees, page_size, offset])
    rows = conn.execute(query, parameters).fetchall()
    keys = ['id', 'title', 'topic', 'start_time', 'registered', 'remaining']
