    except ValueError:
        raise ValueError('invalid score')
    if not 0 <= score <= 100:
        raise ValueError('invalid score')
    return {'issuer': fields['issuer'], 'student': fields['student'], 'course': fields['course'], 'score': score, 'serial': fields['serial']}

