def generate_uplink_tokens(operators: list[dict], mission: str, limit: int=10) -> list[dict]:
    if not isinstance(operators, list):
        raise ValueError('operators must be a list')
    if not isinstance(mission, str) or not mission:
        raise ValueError('mission must be non-empty')
    if isinstance(limit, bool) or not isinstance(limit, int) or (not 0 <= limit <= 50):
        raise ValueError('invalid limit')
    valid = []
    for index, item in enumerate(operators):
        if not isinstance(item, dict):
            raise ValueError('invalid operator')
        if set(item) != {'operator', 'mission', 'clearance', 'active'}:
            raise ValueError('invalid operator fields')
        name = item['operator']
        target = item['mission']
        clearance = item['clearance']
        active = item['active']
        if not isinstance(name, str) or not name:
            raise ValueError('invalid operator name')
        if not isinstance(target, str):
            raise ValueError('invalid mission')
        if isinstance(clearance, bool) or not isinstance(clearance, int) or (not 1 <= clearance <= 5):
            raise ValueError('invalid clearance')
        if not isinstance(active, bool):
            raise ValueError('invalid active flag')
        if target == mission and active:
            valid.append((clearance, name.casefold(), index, item))
    valid.sort(key=lambda value: (-value[0], value[1], value[2]))
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    result = []
    for _, _, _, item in valid[:limit]:
        token = ''.join((secrets.choice(alphabet) for _ in range(16)))
        result.append({'operator': item['operator'], 'mission': item['mission'], 'clearance': item['clearance'], 'token': token})
    return result

