            raise ValueError('missing record field')
        buoy_id = record['buoy_id']
        timestamp = record['timestamp']
        temperature = record['temperature']
        wave_height = record['wave_height']
        if not isinstance(buoy_id, str) or not buoy_id:
            raise ValueError('invalid buoy id')
        if not isinstance(timestamp, str) or not timestamp.endswith('Z'):
            raise ValueError('invalid timestamp')
        try:
            datetime.fromisoformat(timestamp[:-1])
        except ValueError:
            raise ValueError('invalid timestamp')
        if not isinstance(temperature, Real) or isinstance(temperature, bool) or (not isinstance(wave_height, Real)) or isinstance(wave_height, bool):
            raise ValueError('invalid telemetry value')
        grouped.setdefault(buoy_id, []).append((temperature, wave_height))
    summaries = []
    for buoy_id in sorted(grouped):
        values = grouped[buoy_id]
        summaries.append({'buoy_id': buoy_id, 'count': len(values), 'average_temperature': round(sum((item[0] for item in values)) / len(values), 2), 'maximum_wave_height': round(max((item[1] for item in values)), 2)})
    payload = json.dumps(summaries, sort_keys=True, separators=(',', ':')).encode('utf-8')
    signature = hmac.new(key.encode('utf-8'), payload, hashlib.sha256).hexdigest()
    return {'summaries': summaries, 'signature': signature}

