import hashlib
import hmac
import os

def hash_password(password: str) -> str:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    if password == '':
        raise ValueError('password must not be empty')
    salt = os.urandom(16)
    iterations = 100000
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, iterations)
    return f'{iterations}${salt.hex()}${digest.hex()}'

def verify_password(password: str, stored: str) -> bool:
    if not isinstance(password, str) or not isinstance(stored, str):
        return False
    try:
        iterations_text, salt_text, digest_text = stored.split('$')
        iterations = int(iterations_text)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, iterations)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def build_operator_record(operator_id: str, password: str, role: str) -> dict:
    if not isinstance(operator_id, str) or not isinstance(password, str) or (not isinstance(role, str)):
        raise TypeError('operator_id, password, and role must be strings')
    if not operator_id or not password:
        raise ValueError('operator_id and password must not be empty')
    if role not in {'operator', 'supervisor', 'engineer'}:
        raise ValueError('unsupported role')
    return {'operator_id': operator_id, 'role': role, 'password_hash': hash_password(password)}

def production_report(batches: list[dict], page: int, page_size: int) -> list[dict]:
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid page')
    grouped = {}
    for batch in batches:
        if batch['status'] != 'complete':
            continue
        kiln = batch['kiln']
        item = grouped.setdefault(kiln, {'kiln': kiln, 'batch_count': 0, 'total_tons': 0.0, 'moisture_total': 0.0})
        item['batch_count'] += 1
