from lxml import etree

def summarize_grants(xml: str, page: int=1, page_size: int=10) -> dict:
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml.encode('utf-8'), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'grants':
        raise ValueError('invalid root')
    seen = set()
    approved = []
    for node in root:
        if node.tag != 'grant':
            continue
        values = {key: node.get(key) for key in ('id', 'agency', 'status', 'amount')}
        if any((value is None or value == '' for value in values.values())):
            raise ValueError('missing attribute')
        if values['id'] in seen:
            raise ValueError('duplicate id')
        seen.add(values['id'])
        try:
            amount = Decimal(values['amount'])
            if amount < 0 or not amount.is_finite():
                raise ValueError('invalid amount')
            amount = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        except (InvalidOperation, ValueError) as exc:
            raise ValueError('invalid amount') from exc
        if values['status'] == 'approved':
            approved.append((values['id'], values['agency'], amount))
    approved.sort(key=lambda item: (-item[2], item[0]))
    agencies = {}
    for _, agency, amount in approved:
        count, total = agencies.get(agency, (0, Decimal('0.00')))
        agencies[agency] = (count + 1, total + amount)
    grouped = [{'agency': agency, 'count': count, 'total': f'{total:.2f}'} for agency, (count, total) in agencies.items()]
    grouped.sort(key=lambda item: (-Decimal(item['total']), item['agency']))
    start = (page - 1) * page_size
    selected = approved[start:start + page_size]
