import re
from lxml import etree

def _section_key(value):
    result = []
    for part in value.split('.'):
        if part.isdigit():
            result.append((0, int(part)))
        else:
            result.append((1, part.casefold()))
    return result

def _clean(value):
    return re.sub('\\s+', ' ', value).strip()

def parse_contract(xml_text: str) -> dict:
    try:
        root = etree.fromstring(xml_text.encode(), etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False))
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'contract' or root.get('title') is None:
        raise ValueError('invalid contract')
    parties = [p.get('name', '') for p in root.iter('party')]
    clauses = []
    ids = set()
    for order, node in enumerate(root.iter('clause')):
        required = [node.get(x) for x in ('id', 'section', 'heading')]
        if any((x is None for x in required)) or required[0] in ids:
            raise ValueError('invalid clause')
        ids.add(required[0])
        try:
            priority = int(node.get('priority', '0'))
        except ValueError as exc:
            raise ValueError('invalid priority') from exc
        tags = [_clean(x.text or '') for x in node.findall('tag')]
        tags = [x for x in tags if x]
        text = _clean(''.join(node.itertext()))
        date = node.find('effective-date')
        clauses.append({'id': required[0], 'section': required[1], 'heading': required[2], 'priority': priority, 'tags': tags, 'text': text, 'effective_date': _clean(''.join(date.itertext())) if date is not None else None, '_order': order})
    clauses.sort(key=lambda x: (_section_key(x['section']), x['id'].casefold(), x['_order']))
    for clause in clauses:
        del clause['_order']
    return {'title': root.get('title'), 'parties': parties, 'clauses': clauses}

def search_clauses(contract: dict, query: str) -> list[dict]:
    normalized = _clean(query)
    tokens = re.findall('[\\w]+', normalized, re.UNICODE)
    if not tokens:
        raise ValueError('empty query')
    needle = normalized.casefold()
    matches = []
    for clause in contract['clauses']:
        content = ' '.join([clause['heading'], clause['text']] + clause['tags'])
        lowered = content.casefold()
        counts = [len(re.findall('(?<!\\w)' + re.escape(t.casefold()) + '(?!\\w)', lowered)) for t in tokens]
        if not all(counts):
            continue
        score = sum(counts) + (5 if needle.casefold() in lowered else 0) + clause['priority']
        matches.append({'id': clause['id'], 'heading': clause['heading'], 'section': clause['section'], 'text': clause['text'], 'score': score})
    matches.sort(key=lambda x: (-x['score'], _section_key(x['section']), x['id'].casefold()))
    return matches

