import subprocess
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def parse_record(line: str) -> dict:
    text = line[:-1] if line.endswith('\n') else line
    fields, current, escaped = ([], [], False)
    for char in text:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('dangling escape')
    fields.append(''.join(current))
    if len(fields) != 5 or not fields[0]:
        raise ValueError('invalid record')
    try:
        quantity = int(fields[3])
        price = Decimal(fields[4])
    except (ValueError, InvalidOperation):
        raise ValueError('invalid numeric field')
    if quantity < 0 or price < 0 or price.as_tuple().exponent < -2:
        raise ValueError('invalid numeric field')
    return {'sku': fields[0], 'name': fields[1], 'category': fields[2], 'quantity': quantity, 'unit_price': price}

def load_inventory(path: str) -> list[dict]:
    try:
        result = subprocess.run(['cat', path], capture_output=True, check=True)
    except (subprocess.CalledProcessError, OSError) as exc:
        raise FileNotFoundError(path) from exc
    rows = []
    for line in result.stdout.decode('utf-8').splitlines(True):
        if line.strip():
            rows.append(parse_record(line))
    return rows

def inventory_summary(path: str, category: str | None=None, minimum_quantity: int=0) -> list[dict]:
    if minimum_quantity < 0:
        raise ValueError('minimum_quantity')
    groups = {}
    for row in load_inventory(path):
        if category is not None and row['category'] != category:
            continue
        item = groups.setdefault(row['sku'], {'sku': row['sku'], 'name': row['name'], 'category': row['category'], 'quantity': 0, 'total_value': Decimal('0'), 'record_count': 0})
        item['quantity'] += row['quantity']
        item['total_value'] += row['unit_price'] * row['quantity']
        item['record_count'] += 1
    result = [x for x in groups.values() if x['quantity'] >= minimum_quantity]
    for item in result:
        item['total_value'] = item['total_value'].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    result.sort(key=lambda x: (x['category'], x['name'].casefold(), x['sku']))
    return result

