import hmac
import json
from datetime import datetime

def verify_record(record: str, signing_keys: dict[str, str]) -> dict | None:
    try:
        key_id, signature, payload_text = record.split('|', 2)
        key = signing_keys[key_id]
        if len(signature) != 64 or any((c not in '0123456789abcdef' for c in signature)):
            return None
        expected = hmac.new(key.encode(), payload_text.encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(signature, expected):
            return None
        payload = json.loads(payload_text)
        if not isinstance(payload, dict) or set(payload) != {'animal', 'timestamp', 'enrichment', 'grams', 'duration'}:
            return None
        if not isinstance(payload['animal'], str) or not payload['animal']:
            return None
        if not isinstance(payload['enrichment'], str) or not payload['enrichment']:
            return None
        if not isinstance(payload['timestamp'], str) or not payload['timestamp']:
            return None
        datetime.strptime(payload['timestamp'], '%Y-%m-%dT%H:%M:%SZ')
        for name in ('grams', 'duration'):
            if isinstance(payload[name], bool) or not isinstance(payload[name], int) or payload[name] <= 0:
                return None
        return payload
    except (ValueError, KeyError, TypeError, json.JSONDecodeError, UnicodeError):
        return None

