import re
import secrets
_STATES = ('queued', 'started', 'succeeded', 'failed')
_ALPHABET = 'abcdefghijklmnopqrstuvwxyz0123456789'

def make_watch_token(prefix: str='watch', length: int=24) -> str:
    if not prefix or re.fullmatch('[A-Za-z0-9_]+', prefix) is None:
        raise ValueError('invalid prefix')
    if length < len(prefix) + 2:
        raise ValueError('invalid length')
    return prefix + '_' + ''.join((secrets.choice(_ALPHABET) for _ in range(length - len(prefix) - 1)))

def parse_event_line(line: str) -> dict[str, object]:
    fields = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            if char not in '\\|':
                raise ValueError('invalid escape')
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape')
    fields.append(''.join(current))
    if len(fields) != 4:
        raise ValueError('wrong field count')
    timestamp, task_id, state, worker = fields
    if not timestamp.isdecimal() or not task_id or (not worker) or (state not in _STATES):
        raise ValueError('invalid event')
    return {'timestamp': int(timestamp), 'task_id': task_id, 'state': state, 'worker': worker}

def summarize_tasks(lines: list[str], now: int, window: int=300) -> dict[str, object]:
    if now < 0 or window < 0:
        raise ValueError('invalid range')
    latest = {}
    lower = now - window
    for index, line in enumerate(lines):
        event = parse_event_line(line)
        if lower <= event['timestamp'] <= now:
            key = event['task_id']
            old = latest.get(key)
            if old is None or event['timestamp'] >= old['timestamp']:
                latest[key] = event
    tasks = list(latest.values())
    tasks.sort(key=lambda item: (-item['timestamp'], item['task_id']))
    states = {state: 0 for state in _STATES}
    for task in tasks:
        states[task['state']] += 1
    return {'total': len(tasks), 'states': states, 'tasks': tasks}

