def _validated(meeting):
    try:
        value_date = meeting['date']
        value_start = meeting['start']
        room = meeting['room']
        title = meeting['title']
        items = meeting['items']
    except (KeyError, TypeError):
        raise ValueError('invalid meeting')
    if not isinstance(value_date, str) or not isinstance(value_start, str):
        raise ValueError('invalid meeting')
    try:
        parsed_date = date.fromisoformat(value_date)
        parsed_start = datetime.strptime(value_start, '%H:%M').time()
    except ValueError:
        raise ValueError('invalid meeting')
    if value_start != parsed_start.strftime('%H:%M'):
        raise ValueError('invalid meeting')
    if not isinstance(room, str) or not room or (not isinstance(title, str)) or (not title):
        raise ValueError('invalid meeting')
    if not isinstance(items, list) or not items or any((not isinstance(item, str) or not item for item in items)):
        raise ValueError('invalid meeting')
    return (parsed_date, parsed_start, room, title, items)

def render_agenda(meetings: list[dict]) -> str:
    prepared = []
    for index, meeting in enumerate(meetings):
        parsed_date, parsed_start, room, title, items = _validated(meeting)
        prepared.append((parsed_date, parsed_start, room, title, items, index))
    prepared.sort(key=lambda x: (x[0], x[1], x[2].casefold(), x[3].casefold(), x[5]))
    lines = ['# City Council Agenda']
    current = None
    for parsed_date, parsed_start, room, title, items, _ in prepared:
        if parsed_date != current:
            lines.extend(['', f'## {parsed_date.isoformat()}'])
            current = parsed_date
        lines.extend(['', f"### {parsed_start.strftime('%H:%M')} — {room} — {title}"])
        lines.extend((f'- {item}' for item in items))
    return '\n'.join(lines) + '\n'

def _path_inside(base_dir: str, relative_name: str) -> Path:
    base = Path(base_dir).resolve()
    if not base.is_dir():
        raise NotADirectoryError(base_dir)
    target = (base / relative_name).resolve()
    try:
        target.relative_to(base)
    except ValueError:
        raise ValueError('path outside base directory')
    return target

def publish_agenda(base_dir: str, relative_name: str, meetings: list[dict]) -> str:
    target = _path_inside(base_dir, relative_name)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(render_agenda(meetings), encoding='utf-8')
    return str(target)

def read_published_agenda(base_dir: str, relative_name: str) -> str:
    return _path_inside(base_dir, relative_name).read_text(encoding='utf-8')

