import ast

def evaluate_expression(expression: str, variables: dict[str, int | float | bool]) -> int | float | bool:
    tree = ast.parse(expression, mode='eval')

    def visit(node):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in variables:
                raise NameError(node.id)
            return variables[node.id]
        if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
            a, b = (visit(node.left), visit(node.right))
            return {ast.Add: lambda: a + b, ast.Sub: lambda: a - b, ast.Mult: lambda: a * b, ast.Div: lambda: a / b}[type(node.op)]()
        if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub, ast.Not):
            value = visit(node.operand)
            return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
        if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
            value = visit(node.values[0])
            for item in node.values[1:]:
                if isinstance(node.op, ast.And) and (not value) or (isinstance(node.op, ast.Or) and value):
                    return value
                value = visit(item)
            return value
        if isinstance(node, ast.Compare):
            left = visit(node.left)
            for op, part in zip(node.ops, node.comparators):
                right = visit(part)
                if not {ast.Eq: left == right, ast.NotEq: left != right, ast.Lt: left < right, ast.LtE: left <= right, ast.Gt: left > right, ast.GtE: left >= right}[type(op)]:
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
            args = [visit(x) for x in node.args]
            if node.func.id == 'round':
                if len(args) not in (1, 2):
                    raise ValueError('invalid arguments')
                return round(*args)
            if len(args) < 2:
                raise ValueError('invalid arguments')
            return min(args) if node.func.id == 'min' else max(args)
        raise ValueError('unsupported expression')
    return visit(tree.body)

def rank_plans(plans, eligibility, score_expression, limit):
    if limit <= 0:
        return []
    selected = []
    for plan in plans:
        if evaluate_expression(eligibility, plan):
            item = dict(plan)
            item['score'] = evaluate_expression(score_expression, plan)
            selected.append(item)
    selected.sort(key=lambda p: (-p['score'], -p['priority'], p['id']))
    return selected[:limit]

