    result = {}
    for plan in plans:
        youth = plan['youth']
        if youth not in result:
            result[youth] = {'plans': 0, 'hours': 0, 'weighted_progress': 0}
        row = result[youth]
        row['plans'] += 1
        row['hours'] += plan['hours']
        row['weighted_progress'] += plan['hours'] * plan['progress']
    return result

