                    raise ValueError()
                duration = int(b.attrib['duration'])
                if duration <= 0 or str(duration) != b.attrib['duration']:
                    raise ValueError()
            except Exception:
                raise ValueError()
            ns = [x for x in b if x.tag == 'notes']
            es = [x for x in b if x.tag == 'equipment']
            if len(ns) > 1 or len(es) > 1:
                raise ValueError()
            equipment = []
            if es:
                for item in es[0]:
                    if item.tag != 'item' or not item.attrib.get('name', '').strip():
                        raise ValueError()
                    equipment.append(item.attrib['name'].strip())
            out.append({'id': b.attrib['id'], 'date': b.attrib['date'], 'start': b.attrib['start'], 'duration': duration, 'photographer': b.attrib['photographer'], 'client': b.attrib['client'], 'notes': (ns[0].text or '').strip() if ns else '', 'equipment': equipment})
        return out
    except ValueError:
        raise
    except Exception as e:
        raise ValueError() from e

