import base64
import hashlib
import hmac
import os

def hash_password(password: str) -> str:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return '100000$' + base64.b64encode(salt).decode() + '$' + digest.hex()

def verify_password(password: str, stored_hash: str) -> bool:
    if not isinstance(password, str) or not isinstance(stored_hash, str):
        return False
    try:
        rounds, salt_text, digest_text = stored_hash.split('$')
        rounds = int(rounds)
        salt = base64.b64decode(salt_text.encode(), validate=True)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, rounds)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def moderate_reviews(reviews: list[dict], stored_password_hash: str, password: str, *, page: int=1, page_size: int=10) -> dict:
    if not verify_password(password, stored_password_hash):
        raise PermissionError('invalid password')
    if page < 1 or page_size < 1:
        raise ValueError('invalid paging')
    counts = {'pending': 0, 'approved': 0, 'rejected': 0}
    seen = set()
    pending = []
    for review in reviews:
        if not isinstance(review, dict) or not {'id', 'rating', 'text', 'status'}.issubset(review):
            raise ValueError('invalid review')
        if not isinstance(review['id'], str) or not isinstance(review['text'], str) or (not isinstance(review['rating'], int)) or isinstance(review['rating'], bool) or (not 1 <= review['rating'] <= 5) or (review['status'] not in counts) or (review['id'] in seen):
            raise ValueError('invalid review')
        seen.add(review['id'])
        counts[review['status']] += 1
        if review['status'] == 'pending':
            pending.append(review)
    pending.sort(key=lambda item: (-item['rating'], item['id']))
    start = (page - 1) * page_size
    average = round(sum((item['rating'] for item in pending)) / len(pending), 2) if pending else 0.0
    return {'reviews': pending[start:start + page_size], 'total': len(pending), 'page': page, 'page_size': page_size, 'average_rating': average, 'counts': counts}

