import hashlib
import hmac
import json
import math
from datetime import datetime

def build_telemetry_report(records: list[dict], start: str, end: str, config: dict[str, str]) -> dict:
    if not isinstance(records, list):
        raise ValueError('records must be a list')

    def parse(value):
        if not isinstance(value, str) or not value.endswith('Z'):
            raise ValueError('timestamps must be UTC strings')
        try:
            return datetime.fromisoformat(value[:-1] + '+00:00')
        except ValueError as exc:
            raise ValueError('invalid timestamp') from exc
    begin = parse(start)
    finish = parse(end)
    if finish <= begin:
        raise ValueError('end must be later than start')
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        try:
            station = record['station']
            timestamp = parse(record['timestamp'])
            values = [record['flow_lps'], record['turbidity_ntu'], record['chlorine_mg_l']]
        except (KeyError, TypeError) as exc:
            raise ValueError('invalid record') from exc
        if not isinstance(station, str) or not station:
            raise ValueError('invalid station')
        if any((isinstance(value, bool) or not isinstance(value, (int, float)) or (not math.isfinite(value)) or (value < 0) for value in values)):
            raise ValueError('invalid measurement')
        if begin <= timestamp < finish:
            groups.setdefault(station, []).append(values)
    stations = []
    for station in sorted(groups):
        rows = groups[station]
        averages = [round(sum((row[index] for row in rows)) / len(rows), 2) for index in range(3)]
        stations.append({'station': station, 'count': len(rows), 'average_flow_lps': averages[0], 'average_turbidity_ntu': averages[1], 'average_chlorine_mg_l': averages[2]})
    report = {'from': start, 'to': end, 'stations': stations}
    key = config['TELEMETRY_SIGNING_KEY']
    encoded = json.dumps(report, sort_keys=True, separators=(',', ':')).encode()
    report['signature'] = hmac.new(key.encode(), encoded, hashlib.sha256).hexdigest()
    return report

