import secrets

def build_exhibition_invite(records: list[dict], curator: str, page: int=1, page_size: int=5) -> dict:
    if not isinstance(curator, str) or not curator:
        raise ValueError('invalid curator')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 50):
        raise ValueError('invalid page size')
    required = {'accession', 'title', 'artist', 'year', 'medium', 'status'}
    seen = set()
    selected = []
    for record in records:
        if not isinstance(record, dict) or set(record) < required:
            raise ValueError('invalid record')
        if any((not isinstance(record[key], str) for key in ('accession', 'title', 'artist', 'medium', 'status'))):
            raise ValueError('invalid record')
        if isinstance(record['year'], bool) or not isinstance(record['year'], int):
            raise ValueError('invalid record')
        if record['accession'] in seen:
            raise ValueError('duplicate accession')
        seen.add(record['accession'])
        if record['status'] == 'on_display':
            selected.append(record)
    selected.sort(key=lambda item: (-item['year'], item['accession']))
    counts = {}
    for item in selected:
        counts[item['medium']] = counts.get(item['medium'], 0) + 1
    total = len(selected)
    pages = (total + page_size - 1) // page_size if total else 0
    start = (page - 1) * page_size
    items = [{key: item[key] for key in ('accession', 'title', 'artist', 'year', 'medium')} for item in selected[start:start + page_size]]
    alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
    code = ''.join((secrets.choice(alphabet) for _ in range(12)))
    return {'curator': curator, 'page': page, 'page_size': page_size, 'total': total, 'pages': pages, 'medium_counts': dict(sorted(counts.items())), 'invite_code': code, 'items': items}

