import datetime
import hashlib
import hmac
import json

def _validate(notification):
    if not isinstance(notification, dict) or not isinstance(notification.get('delivery_id'), str) or (not isinstance(notification.get('customer'), str)):
        raise ValueError('invalid payload')
    events = notification.get('events')
    if not isinstance(events, list) or not 1 <= len(events) <= 100:
        raise ValueError('invalid payload')
    for event in events:
        if not isinstance(event, dict) or not isinstance(event.get('timestamp'), str) or set(event) != {'timestamp', 'eta_minutes', 'status'}:
            raise ValueError('invalid payload')
        try:
            dt = datetime.datetime.strptime(event['timestamp'], '%Y-%m-%dT%H:%M:%SZ')
        except (ValueError, TypeError):
            raise ValueError('invalid payload')
        if dt.strftime('%Y-%m-%dT%H:%M:%SZ') != event['timestamp']:
            raise ValueError('invalid payload')
        if isinstance(event['eta_minutes'], bool) or not isinstance(event['eta_minutes'], int) or (not 0 <= event['eta_minutes'] <= 1440) or (event['status'] not in {'scheduled', 'delayed', 'arrived', 'cancelled'}):
            raise ValueError('invalid payload')
    return notification

def parse_signed_notification(payload: str, signature: str, key: bytes) -> dict:
    if not isinstance(payload, str) or not isinstance(signature, str) or (not isinstance(key, bytes)):
        raise ValueError('invalid signature')
    expected = 'sha256=' + hmac.new(key, payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(signature, expected):
        raise ValueError('invalid signature')
    try:
        value = json.loads(payload)
    except (UnicodeError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    return _validate(value)

def build_eta_report(notification: dict) -> dict:
    try:
        _validate(notification)
    except Exception:
        raise ValueError('invalid payload')
    ordered = sorted(enumerate(notification['events']), key=lambda x: (x[1]['timestamp'], x[0]))
    groups = {}
    for _, event in ordered:
        hour = event['timestamp'][:13] + ':00:00Z'
        groups.setdefault(hour, []).append(event)
    hourly = []
    for hour, events in sorted(groups.items()):
        counts = {}
        for event in events:
            counts[event['status']] = counts.get(event['status'], 0) + 1
        hourly.append({'hour': hour, 'count': len(events), 'average_eta': round(sum((e['eta_minutes'] for e in events)) / len(events), 2), 'minimum_eta': min((e['eta_minutes'] for e in events)), 'maximum_eta': max((e['eta_minutes'] for e in events)), 'status_counts': {k: counts[k] for k in sorted(counts)}})
    current = ordered[-1][1]
    return {'delivery_id': notification['delivery_id'], 'customer': notification['customer'], 'current': {k: current[k] for k in ('timestamp', 'eta_minutes', 'status')}, 'hourly': hourly}

