import os
import subprocess

def collect_equipment_sizes(directory: str, suffix: str='.csv', min_bytes: int=0, offset: int=0, limit: int | None=None) -> list[tuple[str, int]]:
    if not suffix or '/' in suffix:
        raise ValueError('invalid suffix')
    if min_bytes < 0 or offset < 0 or (limit is not None and limit <= 0):
        raise ValueError('invalid range')
    result = subprocess.run(['find', directory, '-type', 'f', '-name', f'*{suffix}'], capture_output=True, text=True, check=True)
    items = []
    for path in result.stdout.splitlines():
        size = os.stat(path).st_size
        if size >= min_bytes:
            items.append((path, size))
    items.sort(key=lambda item: (-item[1], item[0]))
    end = None if limit is None else offset + limit
    return items[offset:end]

import sqlite3

def initialize_database(conn: sqlite3.Connection) -> None:
    conn.row_factory = sqlite3.Row
    conn.execute('CREATE TABLE IF NOT EXISTS sessions (id INTEGER PRIMARY KEY AUTOINCREMENT, trainee TEXT NOT NULL, scenario TEXT NOT NULL, difficulty TEXT NOT NULL, score REAL NOT NULL, duration_seconds INTEGER NOT NULL, completed INTEGER NOT NULL)')
    conn.commit()

def add_session(conn: sqlite3.Connection, trainee: str, scenario: str, difficulty: str, score: float, duration_seconds: int, completed: bool) -> int:
    if duration_seconds < 0 or not 0 <= score <= 100:
