import csv
import copy
import io
from datetime import datetime

def parse_claim_feed(text: str) -> list[dict]:
    lines = [line for line in text.splitlines() if line.strip()]
    if not lines:
        return []
    try:
        rows = list(csv.reader(lines, delimiter='|'))
    except csv.Error as exc:
        raise ValueError('invalid feed') from exc
    required = ['claim_id', 'tenant_id', 'owner_id', 'category', 'amount_cents', 'status']
    header = rows[0]
    if len(set(header)) != len(header) or any((x not in header for x in required)):
        raise ValueError('invalid header')
    out = []
    for row in rows[1:]:
        if len(row) != len(header):
            raise ValueError('invalid row')
        item = dict(zip(header, row))
        if not item['claim_id']:
            raise ValueError('empty claim id')
        try:
            amount = int(item['amount_cents'], 10)
        except (TypeError, ValueError) as exc:
            raise ValueError('invalid amount') from exc
        item['amount_cents'] = amount
        out.append({key: item[key] for key in required})
    return out

def claim_totals(claims: list[dict]) -> dict[str, int]:
    totals = {}
    for claim in claims:
        try:
            tenant = claim['tenant_id']
            amount = int(claim['amount_cents'])
            status = claim['status']
        except (KeyError, TypeError, ValueError) as exc:
            raise ValueError('invalid claim') from exc
        if amount < 0:
            raise ValueError('negative amount')
        if status == 'approved':
            totals[tenant] = totals.get(tenant, 0) + amount
    return {key: totals[key] for key in sorted(totals)}

def record_claim_decision(requester: dict, claim: dict, decision: str, note: str, occurred_at: str) -> dict:
    if not (claim.get('tenant_id') == requester.get('tenant_id') and (claim.get('owner_id') == requester.get('id') or 'claims_adjuster' in requester.get('roles', []))):
        raise PermissionError('not permitted')
    transitions = {'submitted': {'under_review', 'withdrawn'}, 'under_review': {'approved', 'rejected', 'escalated'}, 'escalated': {'approved', 'rejected'}}
    if decision not in {'approved', 'rejected', 'withdrawn'} and decision != 'under_review':
        raise ValueError('invalid decision')
    if decision not in transitions.get(claim.get('status'), set()):
        raise ValueError('invalid transition')
    if not isinstance(note, str) or not note or len(note) > 200:
        raise ValueError('invalid note')
    if not isinstance(occurred_at, str) or not occurred_at.endswith('Z'):
        raise ValueError('invalid timestamp')
    try:
        datetime.fromisoformat(occurred_at[:-1])
    except ValueError as exc:
        raise ValueError('invalid timestamp') from exc
    history = claim.get('history', [])
    if not isinstance(history, list):
        raise ValueError('invalid history')
    result = copy.deepcopy(claim)
    result['status'] = decision
    result['history'] = copy.deepcopy(history)
    result['history'].append({'actor_id': requester['id'], 'decision': decision, 'note': note, 'occurred_at': occurred_at})
    return result

