import json
import os

def generate_inventory_report(base_dir: str, filenames: list[str], category: str | None=None, page: int=1, page_size: int=10) -> dict:
    if page < 1 or page_size < 1 or page_size > 100 or (category is not None and (not isinstance(category, str))):
        raise ValueError('invalid arguments')
    base = os.path.realpath(base_dir)
    totals = {}
    for filename in filenames:
        path = os.path.realpath(os.path.join(base, filename))
        if os.path.commonpath([base, path]) != base:
            raise ValueError('invalid filename')
        with open(path, encoding='utf-8') as handle:
            payload = json.load(handle)
        for item in payload['items']:
            if category is not None and item['category'] != category:
                continue
            key = (item['name'], item['category'])
            if key not in totals:
                totals[key] = [0, 0.0]
            totals[key][0] += item['quantity']
            totals[key][1] += item['quantity'] * item['unit_price']
    rows = [{'name': name, 'category': cat, 'quantity': values[0], 'total_value': round(values[1], 2)} for (name, cat), values in totals.items()]
    rows.sort(key=lambda row: (-row['total_value'], row['name'], row['category']))
    total_items = len(rows)
    total_pages = (total_items + page_size - 1) // page_size
    if total_items and page > total_pages:
        raise ValueError('page out of range')
    start = (page - 1) * page_size
    return {'page': page, 'page_size': page_size, 'total_items': total_items, 'total_pages': total_pages, 'items': rows[start:start + page_size]}

