def advertising_report(conn: sqlite3.Connection, campaign_id: str, start_date: str, end_date: str, sort_by: str='day', limit: int=100, offset: int=0) -> list[dict]:
    if not isinstance(start_date, str) or not isinstance(end_date, str):
        raise TypeError('dates must be strings')
    for value in (start_date, end_date):
        try:
            if date.fromisoformat(value).isoformat() != value:
                raise ValueError
        except ValueError:
            raise ValueError('invalid date')
    if start_date > end_date:
        raise ValueError('invalid date range')
    if not isinstance(campaign_id, str) or not campaign_id:
        raise ValueError('invalid campaign')
    if sort_by not in {'day', 'impressions', 'clicks', 'cost_cents', 'ctr'}:
        raise ValueError('invalid sort field')
    if limit <= 0 or offset < 0:
        raise ValueError('invalid pagination')
    ordering = {'day': 'day ASC', 'impressions': 'impressions DESC, day ASC', 'clicks': 'clicks DESC, day ASC', 'cost_cents': 'cost_cents DESC, day ASC', 'ctr': 'ctr DESC, day ASC'}[sort_by]
    query = f'SELECT substr(occurred_at, 1, 10) AS day, COUNT(*) AS impressions, SUM(clicked) AS clicks, SUM(cost_cents) AS cost_cents, CAST(SUM(clicked) AS REAL) / COUNT(*) AS ctr FROM impressions WHERE campaign_id = ? AND occurred_at >= ? AND occurred_at < ? GROUP BY day ORDER BY {ordering} LIMIT ? OFFSET ?'
    rows = conn.execute(query, (campaign_id, start_date, end_date, limit, offset)).fetchall()
    return [{'day': r[0], 'impressions': r[1], 'clicks': r[2], 'cost_cents': r[3], 'ctr': round(r[4], 4)} for r in rows]

