            regular = {n for n in names if not n.endswith('/')}
            seen = set()
            checked = []
            for loan in loans:
                if not isinstance(loan, dict) or set(loan) != {'loan_id', 'institution', 'due_date', 'urgency', 'attachment'}:
                    raise ValueError('invalid loan')
                ident = loan['loan_id']
                if not isinstance(ident, str) or not ident or ident in seen:
                    raise ValueError('duplicate loan')
                if not isinstance(loan['institution'], str) or not loan['institution']:
                    raise ValueError('invalid institution')
                try:
                    datetime.strptime(loan['due_date'], '%Y-%m-%d')
                except Exception as exc:
                    raise ValueError('invalid date') from exc
                if type(loan['urgency']) is not int or not 1 <= loan['urgency'] <= 5:
                    raise ValueError('invalid urgency')
                att = loan['attachment']
                if not isinstance(att, str) or not att or att not in regular:
                    raise ValueError('missing attachment')
                seen.add(ident)
                checked.append(loan)
            base = os.path.realpath(destination)
            os.makedirs(base, exist_ok=True)
            for info in z.infolist():
                if info.is_dir():
                    continue
                target = os.path.realpath(os.path.join(base, info.filename))
                if os.path.commonpath((base, target)) != base:
                    raise ValueError('invalid member')
                os.makedirs(os.path.dirname(target), exist_ok=True)
                with z.open(info) as src, open(target, 'wb') as dst:
                    while True:
                        block = src.read(65536)
                        if not block:
                            break
                        dst.write(block)
            result = []
            for loan in checked:
                result.append({**loan, 'size': z.getinfo(loan['attachment']).file_size})
            return sorted(result, key=lambda x: (-x['urgency'], x['due_date'], x['loan_id']))
    except ValueError:
        raise
    except Exception as exc:
        raise ValueError('invalid archive') from exc

def summarize_loans(records: list[dict]) -> list[dict]:
    groups = {}
    for record in records:
        key = (record['institution'], record['urgency'])
        if key not in groups:
            groups[key] = {'institution': key[0], 'urgency': key[1], 'count': 0, 'total_bytes': 0, 'loan_ids': []}
        group = groups[key]
        group['count'] += 1
        group['total_bytes'] += record['size']
        group['loan_ids'].append(record['loan_id'])
    for group in groups.values():
        group['loan_ids'].sort()
    return sorted(groups.values(), key=lambda x: (x['institution'], -x['urgency']))

