import datetime
import hashlib
import hmac
import json
import os
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def build_housing_application_page(applications: list[dict], page: int, page_size: int, building: str | None=None) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('page must be a positive integer')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('page_size must be a positive integer')
    key = os.environ.get('HOUSING_SIGNING_KEY')
    if not key:
        raise ValueError('HOUSING_SIGNING_KEY is required')
    selected = []
    for source in applications:
        try:
            item = {name: source[name] for name in ('student_id', 'building', 'rent', 'priority', 'submitted_at', 'status')}
            if not isinstance(item['student_id'], str) or not item['student_id'] or (not isinstance(item['building'], str)) or (not item['building']):
                raise ValueError('invalid application')
            if item['status'] not in ('pending', 'approved') or isinstance(item['priority'], bool) or (not isinstance(item['priority'], int)):
                raise ValueError('invalid application')
            if isinstance(item['rent'], bool) or not isinstance(item['rent'], (int, float)) or item['rent'] < 0:
                raise ValueError('invalid application')
            datetime.datetime.fromisoformat(item['submitted_at'].replace('Z', '+00:00'))
        except (KeyError, TypeError, ValueError, AttributeError, OverflowError):
            raise ValueError('invalid application')
        if building is None or item['building'] == building:
            selected.append(item)
    selected.sort(key=lambda x: (-x['priority'], x['submitted_at'], x['student_id']))
    start = (page - 1) * page_size
    items = selected[start:start + page_size]
    try:
        total_rent = float(sum((Decimal(str(x['rent'])) for x in selected)).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
    except (InvalidOperation, ValueError):
        raise ValueError('invalid application')
    body = {'items': items, 'page': page, 'page_size': page_size, 'total_count': len(selected), 'total_rent': total_rent}
    raw = json.dumps(body, sort_keys=True, separators=(',', ':')).encode()
    signature = hmac.new(key.encode(), raw, hashlib.sha256).hexdigest()
    return {**body, 'signature': signature}

