            if not isinstance(customer, str) or not customer or status not in {'won', 'lost', 'open'} or isinstance(amount, bool) or (not isinstance(amount, (int, float))):
                raise ValueError
            cents = int((Decimal(str(amount)) * 100).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
            if cents < 0:
