import csv
import datetime
import os
import tempfile

def _date(value):
    try:
        return datetime.date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid service date')

def summarize_housekeeping(entries: list[dict], service_date: str) -> list[dict]:
    _date(service_date)
    groups = {}
    for entry in entries:
        due = entry.get('due')
        if not isinstance(due, str) or len(due) < 11 or due[:10] != service_date:
            continue
        if due[10:11] != ' ' or len(due) != 16:
            raise ValueError('invalid due')
        try:
            datetime.datetime.strptime(due, '%Y-%m-%d %H:%M')
        except ValueError:
            raise ValueError('invalid due')
        status = entry['status']
        if status not in {'pending', 'in_progress', 'completed', 'cancelled'}:
            raise ValueError('invalid status')
        if status not in {'pending', 'in_progress'}:
            continue
        minutes = entry['minutes']
        priority = entry['priority']
        if not isinstance(minutes, int) or isinstance(minutes, bool) or minutes <= 0:
            raise ValueError('invalid minutes')
        if not isinstance(priority, int) or isinstance(priority, bool) or (not 1 <= priority <= 5):
            raise ValueError('invalid priority')
        for key in ('room', 'floor', 'task'):
            entry[key]
        room = entry['room']
        item = groups.setdefault(room, {'room': room, 'floor': entry['floor'], 'items': []})
        item['items'].append((due[11:], entry['task'], minutes, priority))
    result = []
    for item in groups.values():
        items = sorted(item['items'], key=lambda x: (x[0], x[1]))
        result.append({'room': item['room'], 'floor': item['floor'], 'scheduled': items[0][0], 'total_minutes': sum((x[2] for x in items)), 'priority': max((x[3] for x in items)), 'tasks': [x[1] for x in items]})
    result.sort(key=lambda x: (x['scheduled'], -x['priority'], x['room']))
    return result

def export_housekeeping(entries: list[dict], service_date: str, destination: str) -> int:
    rows = summarize_housekeeping(entries, service_date)
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(prefix='housekeeping-', suffix='.csv', dir=directory)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as handle:
            writer = csv.writer(handle)
            writer.writerow(['room', 'floor', 'scheduled', 'total_minutes', 'priority', 'tasks'])
            for row in rows:
                writer.writerow([row['room'], row['floor'], row['scheduled'], row['total_minutes'], row['priority'], ' | '.join(row['tasks'])])
        os.replace(temporary, destination)
        return len(rows)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise

