from datetime import datetime, timezone

def write_sms_schedule_report(base_dir: str, relative_name: str, messages: list[dict[str, str]], page: int=1, page_size: int=50) -> str:
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    base = os.path.realpath(base_dir)
    if not os.path.isdir(base):
        raise FileNotFoundError(base_dir)
    target = os.path.realpath(os.path.join(base, relative_name))
    try:
        if os.path.commonpath((base, target)) != base:
            raise ValueError('invalid output name')
    except ValueError:
        raise ValueError('invalid output name')
    selected = []
    for message in messages:
        if not isinstance(message, dict) or any((key not in message for key in ('recipient', 'body', 'scheduled_at', 'status'))):
            raise ValueError('invalid message')
        if any((not isinstance(message[key], str) for key in ('recipient', 'body', 'scheduled_at', 'status'))):
            raise ValueError('invalid message')
        try:
            stamp = datetime.fromisoformat(message['scheduled_at'])
        except (TypeError, ValueError):
            raise ValueError('invalid timestamp')
        if stamp.tzinfo is None or stamp.utcoffset() is None:
            raise ValueError('timezone required')
        if message['status'] == 'scheduled':
            selected.append((stamp.astimezone(timezone.utc), message['recipient'], message['body']))
    selected.sort(key=lambda row: (row[0], row[1], row[2]))
    total = len(selected)
    start = (page - 1) * page_size
    rows = [['date', 'recipient', 'body']]
    for stamp, recipient, body in selected[start:start + page_size]:
        rows.append([stamp.strftime('%Y-%m-%d %H:%M:%S'), recipient, body])
    rows.append(['total', str(total), ''])
    parent = os.path.dirname(target)
    os.makedirs(parent, exist_ok=True)
    with open(target, 'w', newline='', encoding='utf-8') as handle:
        csv.writer(handle).writerows(rows)
    return target

