import math
import os
import tempfile

def export_loan_report(records: list[dict], destination: str, page: int=1, page_size: int=50) -> int:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        try:
            library = record['library']
            status = record['status']
            days = record['days']
            fee = record['fee']
        except KeyError as exc:
            raise ValueError('missing field') from exc
        if not isinstance(library, str) or not library.strip():
            raise ValueError('invalid library')
        if status not in {'requested', 'fulfilled', 'returned', 'declined'}:
            raise ValueError('invalid status')
        if isinstance(days, bool) or not isinstance(days, int) or days < 0:
            raise ValueError('invalid days')
        if isinstance(fee, bool) or not isinstance(fee, (int, float)) or (not math.isfinite(fee)) or (fee < 0):
            raise ValueError('invalid fee')
        item = groups.setdefault(library, [0, 0, [], 0.0])
        item[0] += 1
        item[3] += fee
        if status in {'fulfilled', 'returned'}:
            item[1] += 1
            item[2].append(days)
    ordered = sorted(groups.items(), key=lambda pair: (pair[0].casefold(), pair[0]))
    start = (page - 1) * page_size
    selected = ordered[start:start + page_size]
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=directory, prefix='.loan-report-')
    os.close(fd)
    try:
        with open(temporary, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['library', 'requested', 'fulfilled', 'average_days', 'total_fee'])
            for library, values in selected:
                average = sum(values[2]) / values[1] if values[1] else 0
                writer.writerow([library, values[0], values[1], f'{average:.2f}', f'{values[3]:.2f}'])
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return len(selected)

