import hashlib
import hmac
import json
import math

def sync_save(payload: str, secret: bytes) -> dict:
    try:
        data = json.loads(payload)
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(data, dict) or 'signature' not in data:
        raise ValueError('invalid payload')
    signature = data.get('signature')
    if not isinstance(signature, str):
        raise ValueError('invalid signature')
    body = {k: v for k, v in data.items() if k != 'signature'}
    expected = hmac.new(secret, json.dumps(body, sort_keys=True, separators=(',', ':')).encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    if set(body) != {'player', 'page', 'page_size', 'updates'}:
        raise ValueError('invalid fields')
    player = body['player']
    page = body['page']
    page_size = body['page_size']
    updates = body['updates']
    if not isinstance(player, str) or not player:
        raise ValueError('invalid player')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    if not isinstance(updates, list):
        raise ValueError('invalid updates')
    chosen = {}
    for update in updates:
        if not isinstance(update, dict) or set(update) != {'level', 'score', 'finished_at', 'completed'}:
            raise ValueError('invalid update')
        level = update['level']
        score = update['score']
        finished_at = update['finished_at']
        completed = update['completed']
        if not isinstance(level, str) or not level:
            raise ValueError('invalid level')
        if isinstance(score, bool) or not isinstance(score, int) or score < 0:
            raise ValueError('invalid score')
        if isinstance(finished_at, bool) or not isinstance(finished_at, int) or finished_at < 0:
            raise ValueError('invalid timestamp')
        if not isinstance(completed, bool):
            raise ValueError('invalid completion')
        if completed and (level not in chosen or (score, finished_at) > (chosen[level]['score'], chosen[level]['finished_at'])):
            chosen[level] = {'level': level, 'score': score, 'finished_at': finished_at}
    levels = sorted(chosen.values(), key=lambda x: (-x['score'], x['level']))
    total = sum((x['score'] for x in levels))
    pages = math.ceil(len(levels) / page_size) if levels else 0
    start = (page - 1) * page_size
    return {'player': player, 'page': page, 'page_size': page_size, 'pages': pages, 'total_score': total, 'levels': levels[start:start + page_size]}

