def parse_light_events(text: str) -> list[tuple[str, int, int, int]]:
    result = []
    for number, raw in enumerate(text.splitlines(), 1):
        line = raw.strip()
        if not line or line.startswith('#'):
            continue
        fields = [x.strip() for x in raw.split(',')]
        if len(fields) != 4 or not fields[0] or ',' in fields[0]:
            raise ValueError(f'invalid line {number}')
        try:
            start = int(fields[1])
            duration = int(fields[2])
            brightness = int(fields[3])
        except ValueError:
            raise ValueError(f'invalid line {number}')
        if duration <= 0 or brightness < 0 or brightness > 100:
            raise ValueError(f'invalid line {number}')
        result.append((fields[0], start, duration, brightness))
    return sorted(result, key=lambda x: (x[1], x[0], x[2], x[3]))

def summarize_events(events: list[tuple[str, int, int, int]]) -> dict[str, dict[str, int]]:
    grouped = {}
    for name, start, duration, brightness in events:
        if name not in grouped:
            grouped[name] = {'count': 0, 'total_minutes': 0, 'max_brightness': brightness, 'first_start': start}
        item = grouped[name]
        item['count'] += 1
        item['total_minutes'] += duration
        item['max_brightness'] = max(item['max_brightness'], brightness)
        item['first_start'] = min(item['first_start'], start)
    return {name: grouped[name] for name in sorted(grouped)}

def extract_light_bundle(zip_path: str, base_dir: str) -> list[str]:
    root = os.path.realpath(base_dir)
    os.makedirs(root, exist_ok=True)
    written = []
    with zipfile.ZipFile(zip_path) as archive:
        for info in archive.infolist():
            if info.is_dir():
                continue
            destination = os.path.realpath(os.path.join(root, info.filename))
            try:
                relative = os.path.relpath(destination, root)
                if relative == os.pardir or relative.startswith(os.pardir + os.sep):
                    raise ValueError('archive member outside destination')
            except ValueError:
                raise ValueError('archive member outside destination')
            os.makedirs(os.path.dirname(destination), exist_ok=True)
            with archive.open(info) as source, open(destination, 'wb') as target:
                target.write(source.read())
            written.append(relative.replace(os.sep, '/'))
    return sorted(written)

