from datetime import date

def initialize_database(conn: sqlite3.Connection) -> None:
    conn.execute('CREATE TABLE IF NOT EXISTS donors (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE CHECK(length(name)>0), email TEXT NOT NULL UNIQUE CHECK(length(email)>0))')
    conn.execute('CREATE TABLE IF NOT EXISTS donations (id INTEGER PRIMARY KEY, donor_id INTEGER NOT NULL REFERENCES donors(id), amount_cents INTEGER NOT NULL, donated_on TEXT NOT NULL)')
    conn.commit()

def add_donation(conn: sqlite3.Connection, donor_id: int, amount_cents: int, donated_on: str) -> int:
    if not isinstance(amount_cents, int) or isinstance(amount_cents, bool) or amount_cents <= 0:
        raise ValueError('invalid amount')
    try:
        parsed = date.fromisoformat(donated_on)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if parsed.isoformat() != donated_on:
        raise ValueError('invalid date')
    cur = conn.execute('INSERT INTO donations(donor_id,amount_cents,donated_on) VALUES (?,?,?)', (donor_id, amount_cents, donated_on))
    conn.commit()
    return cur.lastrowid

def summarize_donors(conn: sqlite3.Connection, search: str='', minimum_cents: int=0, sort: str='total', descending: bool=False) -> list[dict]:
    if minimum_cents < 0 or sort not in {'total', 'name', 'latest', 'count'}:
        raise ValueError('invalid option')
    cols = {'total': 'total_cents', 'name': 'd.name', 'latest': 'latest_date', 'count': 'donation_count'}
    p = cols[sort]
    direction = 'DESC' if descending else 'ASC'
    nulls = ('CASE WHEN latest_date IS NULL THEN 1 ELSE 0 END, ' if descending else 'CASE WHEN latest_date IS NULL THEN 0 ELSE 1 END, ') if sort == 'latest' else ''
    sql = f'SELECT d.id,d.name,d.email,COALESCE(SUM(x.amount_cents),0) AS total_cents,COUNT(x.id) AS donation_count,MAX(x.donated_on) AS latest_date FROM donors d LEFT JOIN donations x ON x.donor_id=d.id WHERE lower(d.name) LIKE ? OR lower(d.email) LIKE ? GROUP BY d.id HAVING total_cents>=? ORDER BY {nulls}{p} {direction},d.name ASC,d.id ASC'
    keys = ['id', 'name', 'email', 'total_cents', 'donation_count', 'latest_date']
    term = '%' + search.lower() + '%'
    return [dict(zip(keys, row)) for row in conn.execute(sql, (term, term, minimum_cents))]

def monthly_totals(conn: sqlite3.Connection, donor_id: int, year: int) -> list[int]:
    if not isinstance(year, int) or isinstance(year, bool) or (not 1900 <= year <= 2100):
        raise ValueError('invalid year')
    out = [0] * 12
    for m, total in conn.execute("SELECT CAST(strftime('%m',donated_on) AS INTEGER),SUM(amount_cents) FROM donations WHERE donor_id=? AND strftime('%Y',donated_on)=? GROUP BY strftime('%m',donated_on)", (donor_id, str(year))):
        out[m - 1] = total
    return out

