from lxml import etree
import math

def parse_telemetry(xml_text: str) -> list[dict[str, object]]:
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'telemetry':
        raise ValueError('invalid root')
    result = []
    for station in root:
        if station.tag != 'station':
            raise ValueError('invalid element')
        sid = (station.get('id') or '').strip()
        if not sid:
            raise ValueError('invalid station')
        for reading in station:
            if reading.tag != 'reading':
                raise ValueError('invalid element')
            try:
                ts = int((reading.get('ts') or '').strip())
                signal = float((reading.get('signal') or '').strip())
            except Exception as exc:
                raise ValueError('invalid reading') from exc
            status = (reading.get('status') or '').strip()
            if ts < 0 or not math.isfinite(signal) or reading.get('ts') is None or (reading.get('signal') is None) or (reading.get('status') is None):
                raise ValueError('invalid reading')
            channels = {}
            for channel in reading:
                if channel.tag != 'channel':
                    raise ValueError('invalid element')
                name = (channel.get('name') or '').strip()
                if not name or name in channels or channel.get('value') is None:
                    raise ValueError('invalid channel')
                try:
                    value = float(channel.get('value').strip())
                except Exception as exc:
                    raise ValueError('invalid channel') from exc
                if not math.isfinite(value):
                    raise ValueError('invalid channel')
                channels[name] = value
            result.append({'station': sid, 'timestamp': ts, 'signal': signal, 'status': status, 'channels': channels})
    return result

def aggregate_telemetry(readings: list[dict[str, object]], window_seconds: int) -> list[dict[str, object]]:
    if isinstance(window_seconds, bool) or not isinstance(window_seconds, int) or window_seconds <= 0:
        raise ValueError('invalid window')
    groups = {}
    for item in readings:
        try:
            station = item['station']
            ts = item['timestamp']
            signal = item['signal']
            status = item['status']
            channels = item['channels']
        except Exception as exc:
            raise ValueError('invalid record') from exc
        if not isinstance(station, str) or not station or (not isinstance(ts, int)) or isinstance(ts, bool) or (ts < 0) or (not isinstance(signal, (int, float))) or isinstance(signal, bool) or (not math.isfinite(signal)) or (not isinstance(status, str)) or (not isinstance(channels, dict)):
            raise ValueError('invalid record')
        if len(channels) != len(set(channels)):
            raise ValueError('invalid channels')
        for name, value in channels.items():
            if not isinstance(name, str) or not name or (not isinstance(value, (int, float))) or isinstance(value, bool) or (not math.isfinite(value)):
                raise ValueError('invalid channels')
        key = (station, ts // window_seconds * window_seconds)
        groups.setdefault(key, []).append(item)
    output = []
    for (station, start), items in sorted(groups.items()):
        sums = {}
        counts = {}
        statuses = {}
        for item in items:
            statuses[item['status']] = statuses.get(item['status'], 0) + 1
            for name, value in item['channels'].items():
                sums[name] = sums.get(name, 0.0) + value
                counts[name] = counts.get(name, 0) + 1
        output.append({'station': station, 'window_start': start, 'window_end': start + window_seconds, 'count': len(items), 'average_signal': sum((item['signal'] for item in items)) / len(items), 'average_channels': {name: sums[name] / counts[name] for name in sorted(sums)}, 'statuses': {name: statuses[name] for name in sorted(statuses)}})
    return output

