import csv
from datetime import date

def parse_readings(text: str) -> list[tuple[str, int]]:
    result = []
    for row in csv.reader(text.splitlines()):
        if not row or all((not x.strip() for x in row)):
            continue
        if len(row) != 2:
            raise ValueError('invalid reading')
        day = row[0].strip()
        try:
            date.fromisoformat(day)
            value = int(row[1].strip())
        except Exception as exc:
            raise ValueError('invalid reading') from exc
        if value < 0:
            raise ValueError('invalid reading')
        result.append((day, value))
    if not result or len({x[0] for x in result}) != len(result):
        raise ValueError('invalid readings')
    result.sort(key=lambda x: x[0])
    return result

def calculate_invoice(account: dict, readings: list[tuple[str, int]], tariff: dict) -> dict:
    if len(readings) < 2:
        raise ValueError('not enough readings')
    tiers = tariff.get('tiers')
    if not isinstance(tiers, list) or not tiers:
        raise ValueError('invalid tariff')
    previous = 0
    for tier in tiers:
        bound = tier.get('upto')
        if bound is not None and (bound <= previous or tier.get('rate', -1) < 0):
            raise ValueError('invalid tariff')
        previous = bound if bound is not None else previous
    if tiers[-1].get('upto') is not None:
        raise ValueError('invalid tariff')
    usage = readings[-1][1] - readings[0][1]
    if usage < 0:
        raise ValueError('decreasing meter')
    left, charge, prior = (usage, 0, 0)
    for tier in tiers:
        bound = tier.get('upto')
        count = left if bound is None else min(left, bound - prior)
        charge += count * tier['rate']
        left -= count
        prior = bound if bound is not None else prior
        if not left:
            break
    subtotal = tariff['fixed'] + charge
    tax = subtotal * tariff['tax'] // 100
    credit = account.get('credit', 0)
    return {'account_id': account['account_id'], 'customer': account['customer'], 'from_date': readings[0][0], 'to_date': readings[-1][0], 'usage': usage, 'subtotal': subtotal, 'tax': tax, 'total': max(0, subtotal + tax - credit), 'credit': credit}

def record_payment(requester: dict, account_id: str, accounts: dict, ledger: list[dict], amount: int) -> dict:
    if account_id not in accounts:
        raise KeyError(account_id)
    if amount <= 0:
        raise ValueError('amount must be positive')
    account = accounts[account_id]
    if requester['tenant_id'] != account['tenant_id'] or (requester['id'] != account['owner_id'] and (not {'billing_agent', 'admin'} & set(requester.get('roles', [])))):
        raise PermissionError('not allowed')
    ledger.append({'account_id': account_id, 'amount': amount, 'requester_id': requester['id'], 'tenant_id': requester['tenant_id']})
    paid = sum((x['amount'] for x in ledger if x.get('account_id') == account_id))
    return {'account_id': account_id, 'paid': amount, 'remaining': max(0, account.get('balance', 0) - paid)}

