        raise ValueError('invalid emissions')
    stamp = value['inspected_at']
    if not isinstance(stamp, str):
        raise ValueError('invalid date')
    try:
        parsed = date.fromisoformat(stamp)
    except ValueError as exc:
        raise ValueError('invalid date') from exc
    if parsed.isoformat() != stamp:
        raise ValueError('invalid date')
    return {'permit_id': value['permit_id'], 'county': value['county'], 'status': value['status'], 'emissions': float(value['emissions']), 'inspected_at': stamp}

