    try:
        values = json.loads(text)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid JSON') from exc
    if not isinstance(values, list):
        raise ValueError('top level must be an array')
    return [_record(value) for value in values]

def aggregate_permits(records: list[dict]) -> list[dict]:
    groups = {}
    for value in records:
        item = _record(value)
        key = (item['county'], item['status'], item['inspected_at'][:7])
        entry = groups.setdefault(key, {'county': key[0], 'status': key[1], 'month': key[2], 'permit_count': 0, 'total_emissions': 0.0})
        entry['permit_count'] += 1
        entry['total_emissions'] += item['emissions']
    result = list(groups.values())
    for entry in result:
        entry['total_emissions'] = round(entry['total_emissions'], 2)
    return sorted(result, key=lambda x: (x['county'], x['status'], x['month']))

def create_dashboard_request(records: list[dict], config: dict[str, str] | None=None) -> dict:
    if config is not None and 'DASHBOARD_API_TOKEN' in config:
        token = config['DASHBOARD_API_TOKEN']
    else:
        token = os.environ.get('DASHBOARD_API_TOKEN')
    if not token:
        raise ValueError('DASHBOARD_API_TOKEN is required')
    body = json.dumps(aggregate_permits(records), separators=(',', ':'), sort_keys=True)
