import base64
import datetime
import hashlib
import hmac
import json

def _b64(data):
    return base64.urlsafe_b64encode(data).rstrip(b'=').decode('ascii')

def _date(value):
    try:
        return datetime.date.fromisoformat(value)
    except Exception as exc:
        raise ValueError('invalid date') from exc

def _records(value):
    if not isinstance(value, dict) or set(value) != {'records'} or (not isinstance(value['records'], list)):
        raise ValueError('invalid payload')
    out = []
    for record in value['records']:
        if not isinstance(record, dict) or set(record) != {'entity', 'obligation', 'due', 'status', 'amount_cents'}:
            raise ValueError('invalid record')
        if not all((isinstance(record[k], str) and record[k] for k in ('entity', 'obligation', 'due', 'status'))):
            raise ValueError('invalid record')
        _date(record['due'])
        if record['status'] not in {'met', 'overdue', 'waived'}:
            raise ValueError('invalid record')
        if isinstance(record['amount_cents'], bool) or not isinstance(record['amount_cents'], int) or record['amount_cents'] < 0:
            raise ValueError('invalid record')
        out.append(dict(record))
    return out

def make_envelope(records: list[dict], secret: bytes, timestamp: int) -> str:
    if not isinstance(secret, bytes):
        raise TypeError('secret must be bytes')
    if isinstance(timestamp, bool) or not isinstance(timestamp, int) or (not 0 <= timestamp <= 4102444800):
        raise ValueError('invalid timestamp')
    records = _records({'records': records})
    payload = _b64(json.dumps({'records': records}, separators=(',', ':')).encode())
    head = f'v1.{timestamp}.{payload}'
    mac = hmac.new(secret, head.encode('ascii'), hashlib.sha256).digest()
    return head + '.' + _b64(mac)

def verify_and_summarize(envelope: str, secret: bytes, as_of: str) -> dict:
    if not isinstance(secret, bytes):
        raise TypeError('secret must be bytes')
    day = _date(as_of)
    if not isinstance(envelope, str):
        raise ValueError('invalid envelope')
    parts = envelope.split('.')
    if len(parts) != 4 or parts[0] != 'v1' or (not parts[1].isdigit()) or (len(parts[1]) > 1 and parts[1][0] == '0'):
        raise ValueError('invalid envelope')
    timestamp = int(parts[1])
    if timestamp > 4102444800:
        raise ValueError('invalid envelope')
    try:
        raw = base64.urlsafe_b64decode(parts[2] + '=' * (-len(parts[2]) % 4))
        supplied = base64.urlsafe_b64decode(parts[3] + '=' * (-len(parts[3]) % 4))
        payload = json.loads(raw.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid envelope') from exc
    expected = hmac.new(secret, '.'.join(parts[:3]).encode('ascii'), hashlib.sha256).digest()
    if not hmac.compare_digest(expected, supplied):
        raise ValueError('invalid signature')
    records = _records(payload)
    totals = {}
    upcoming = []
    end = day + datetime.timedelta(days=30)
    for r in records:
        item = totals.setdefault(r['entity'], {'entity': r['entity'], 'met': 0, 'overdue': 0, 'waived': 0, 'amount_cents': 0})
        item[r['status']] += 1
        item['amount_cents'] += r['amount_cents']
