    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    registry[technician_id] = {'salt': salt, 'digest': digest, 'skills': list(skills), 'daily_limit': daily_limit}

def authenticate_technician(registry: dict[str, dict], technician_id: str, password: str) -> bool:
    if not isinstance(password, str) or technician_id not in registry:
        return False
    record = registry[technician_id]
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), record['salt'], 100000)
    return digest == record['digest']

