            if sid in seen or not isinstance(sid, str):
                continue
            seen.add(sid)
            if s['hours'] <= 0 or len(s['window']) != 2:
                continue
            valid.append(s)
        except (KeyError, TypeError, ValueError):
            continue
    valid.sort(key=lambda s: (s['due'], -s['priority'], s['id']))
    loads = {k: 0 for k in technicians}
    result = []
    assigned = set()
    for s in valid:
        if s['due'] > day or any((d not in assigned for d in s['depends_on'])):
            continue
        choices = []
        for tid, t in technicians.items():
            try:
                if s['skill'] in t['skills'] and t['shift'][0] <= s['window'][0] and (s['window'][1] <= t['shift'][1]) and (loads[tid] + s['hours'] <= t['daily_limit']):
                    choices.append((loads[tid], tid))
            except (KeyError, TypeError, IndexError):
                pass
        if choices:
            _, tid = min(choices)
            loads[tid] += s['hours']
            assigned.add(s['id'])
            result.append({'site_id': s['id'], 'technician_id': tid, 'hours': s['hours']})
    return result

