from datetime import datetime, timezone, timedelta
from typing import Mapping

def parse_log_line(line: str) -> dict[str, object]:
    if not isinstance(line, str) or '\n' in line or '\r' in line:
        raise ValueError('invalid log line')
    parts = line.split('|')
    if len(parts) != 4 or not parts[1] or (not parts[3]):
        raise ValueError('invalid log line')
    text, service, size_text, event_id = parts
    if not text.endswith('Z'):
        raise ValueError('timestamp must be UTC')
    try:
        stamp = datetime.fromisoformat(text[:-1] + '+00:00')
        size = int(size_text)
    except (ValueError, TypeError):
        raise ValueError('invalid log line')
    if stamp.tzinfo is None or size < 0 or str(size) != size_text:
        raise ValueError('invalid log line')
    return {'timestamp': stamp.astimezone(timezone.utc), 'service': service, 'size': size, 'event_id': event_id}

def _parse_now(now: str) -> datetime:
    if not isinstance(now, str) or not now.endswith('Z'):
        raise ValueError('invalid now')
    try:
        return datetime.fromisoformat(now[:-1] + '+00:00').astimezone(timezone.utc)
    except ValueError:
        raise ValueError('invalid now')

def summarize_retention(lines: list[str], now: str, retain_days: int) -> list[dict[str, object]]:
    if isinstance(retain_days, bool) or not isinstance(retain_days, int) or retain_days < 0:
        raise ValueError('invalid retention period')
    current = _parse_now(now)
    latest: dict[str, tuple[int, dict[str, object]]] = {}
    for position, line in enumerate(lines):
        record = parse_log_line(line)
        if record['timestamp'] > current:
            raise ValueError('future record')
        old = latest.get(record['event_id'])
        if old is None or record['timestamp'] >= old[1]['timestamp']:
            latest[record['event_id']] = (position, record)
    cutoff = current - timedelta(days=retain_days)
    groups: dict[str, list[int]] = {}
    for _, record in latest.values():
        if record['timestamp'] < cutoff:
            groups.setdefault(record['service'], [0, 0])
            groups[record['service']][0] += 1
            groups[record['service']][1] += record['size']
    return [{'service': service, 'event_count': values[0], 'total_size': values[1]} for service, values in sorted(groups.items())]

