                raise ValueError('malformed CSV row')
            if not row['reagent_id'].strip() or row['reagent_id'] in seen:
                raise ValueError('invalid or duplicate reagent_id')
            try:
                expiry = date.fromisoformat(row['expires'])
                quantity = int(row['quantity'])
            except (TypeError, ValueError) as exc:
                raise ValueError('invalid date or quantity') from exc
            if quantity < 1:
                raise ValueError('quantity must be positive')
            seen.add(row['reagent_id'])
            result.append({'reagent_id': row['reagent_id'], 'name': row['name'], 'lot': row['lot'], 'expires': expiry, 'quantity': quantity})
        return result
    except csv.Error as exc:
        raise ValueError('malformed CSV') from exc

