    lots = {}
    totals = {}
    for category, values in groups.items():
        values.sort(key=lambda x: (x[0], x[1], x[2]))
        lots[category] = [x[3] for x in values]
        totals[category] = sum((x[3]['quantity'] for x in values))
    return {'as_of': as_of, 'totals': totals, 'lots': lots}

