    key = config.get('signing_key') if config is not None and 'signing_key' in config else os.environ.get('LAB_REAGENT_SIGNING_KEY')
    if key is None:
        raise ValueError('missing signing key')
    report = build_report(parse_inventory(text), as_of)
    encoded = json.dumps(report, sort_keys=True, separators=(',', ':')).encode('utf-8')
    result = dict(report)
    result['signature'] = hmac.new(str(key).encode('utf-8'), encoded, hashlib.sha256).hexdigest()
    return result

