import csv
import math
import os
import tempfile
from decimal import Decimal, ROUND_HALF_UP

def export_fulfillment(records: list[dict[str, object]], minimum_total: float=0.0) -> str:
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    if isinstance(minimum_total, bool) or not isinstance(minimum_total, (int, float)):
        raise TypeError('minimum_total must be numeric')
    if not math.isfinite(minimum_total) or minimum_total < 0:
        raise ValueError('invalid minimum_total')
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise TypeError('record must be a dictionary')
        if not all((key in record for key in ('sponsor', 'event', 'amount'))):
            raise ValueError('missing field')
        sponsor = record['sponsor']
        event = record['event']
        amount = record['amount']
        if not isinstance(sponsor, str) or not isinstance(event, str) or isinstance(amount, bool) or (not isinstance(amount, (int, float))):
            raise TypeError('invalid field type')
        if not sponsor or not event or (not math.isfinite(amount)) or (amount < 0):
            raise ValueError('invalid field value')
        key = (sponsor, event)
        if key not in groups:
            groups[key] = [Decimal('0'), 0]
        groups[key][0] += Decimal(str(amount))
        groups[key][1] += 1
    threshold = Decimal(str(minimum_total))
    rows = [(total, sponsor, event, count) for (sponsor, event), (total, count) in groups.items() if total >= threshold]
    rows.sort(key=lambda row: (-row[0], row[1], row[2]))
    fd, path = tempfile.mkstemp()
    os.close(fd)
    try:
        with open(path, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(('sponsor', 'event', 'total_amount', 'record_count'))
            for total, sponsor, event, count in rows:
                rounded = total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
                writer.writerow((sponsor, event, format(rounded, '.2f'), count))
        with open(path, 'r', newline='', encoding='utf-8') as handle:
            return handle.read()
    finally:
        os.unlink(path)

