        if x['price_cents'] < 0 or x['quantity'] <= 0 or x['status'] not in ('completed', 'refunded') or (x['region'] not in ('EU', 'NA', 'APAC')):
            raise ValueError('invalid value')
        seen.add(x['sale_id'])
