import csv
import copy
from datetime import datetime, timezone
from io import StringIO
_FIELDS = ('id', 'tenant', 'owner_id', 'start', 'end', 'status', 'service')
_STATUSES = {'scheduled', 'completed', 'cancelled'}

def _time(value):
    try:
        result = datetime.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid timestamp')
    if result.tzinfo is None:
        raise ValueError('timestamp needs timezone')
    return result

def parse_appointments(text: str) -> list[dict]:
    if not text.strip():
        return []
    rows = csv.reader(StringIO(text.lstrip('\ufeff'), newline=''))
    result = []
    seen = set()
    try:
        for row in rows:
            if not row:
                continue
            if len(row) != 7:
                raise ValueError('wrong column count')
            item = dict(zip(_FIELDS, row))
            if any((not item[k] for k in ('id', 'tenant', 'owner_id', 'service'))):
                raise ValueError('empty field')
            if item['id'] in seen or item['status'] not in _STATUSES:
                raise ValueError('invalid record')
            start, end = (_time(item['start']), _time(item['end']))
            if end <= start:
                raise ValueError('reversed interval')
            seen.add(item['id'])
            result.append(item)
    except csv.Error as exc:
        raise ValueError('invalid csv') from exc
    return result

def _allowed(appointment, requester):
    return requester.get('tenant') == appointment['tenant'] and (requester.get('id') == appointment['owner_id'] or bool({'coordinator', 'admin'} & set(requester.get('roles', []))))

def reschedule_appointment(appointments, appointment_id, requester, new_start, new_end):
    found = next((a for a in appointments if a.get('id') == appointment_id), None)
    if found is None:
        raise KeyError(appointment_id)
    if not _allowed(found, requester):
        raise PermissionError('not permitted')
    start, end = (_time(new_start), _time(new_end))
    if end <= start:
        raise ValueError('reversed interval')
    result = copy.deepcopy(appointments)
    for item in result:
        if item.get('id') == appointment_id:
            item['start'], item['end'] = (new_start, new_end)
            break
    return result

def daily_schedule(appointments, requester, day):
    try:
        target = datetime.strptime(day, '%Y-%m-%d').date()
    except ValueError:
        raise ValueError('invalid date')
    selected = []
    for item in appointments:
        if item.get('tenant') != requester.get('tenant'):
