import base64
import hashlib
import hmac
import json

def verify_watch_event(token: str, secret: str) -> dict:
    if not isinstance(token, str) or not isinstance(secret, str) or (not secret):
        raise ValueError('invalid token')
    parts = token.split('.')
    if len(parts) != 2:
        raise ValueError('invalid token')
    payload_text, signature = parts
    if not payload_text or len(signature) != 64 or any((c not in '0123456789abcdef' for c in signature)):
        raise ValueError('invalid token')
    if '=' in payload_text:
        raise ValueError('invalid token')
    try:
        encoded = payload_text.encode('ascii')
        raw = base64.b64decode(encoded + b'=' * (-len(encoded) % 4), altchars=b'-_', validate=True)
        if base64.urlsafe_b64encode(raw).decode('ascii').rstrip('=') != payload_text:
            raise ValueError('invalid token')
        expected = hmac.new(secret.encode('utf-8'), encoded, hashlib.sha256).hexdigest()
        if not hmac.compare_digest(expected, signature):
            raise ValueError('invalid token')
        data = json.loads(raw.decode('utf-8'))
    except (ValueError, TypeError, UnicodeError, json.JSONDecodeError):
        raise ValueError('invalid token')
    if not isinstance(data, dict) or set(data) != {'video_id', 'position', 'watched_at'}:
        raise ValueError('invalid token')
    if not isinstance(data['video_id'], str) or not data['video_id']:
        raise ValueError('invalid token')
    if isinstance(data['position'], bool) or not isinstance(data['position'], int) or data['position'] < 0:
        raise ValueError('invalid token')
    if isinstance(data['watched_at'], bool) or not isinstance(data['watched_at'], int) or data['watched_at'] <= 0:
        raise ValueError('invalid token')
    return data

