import copy
import json
SEVERITIES = ('low', 'medium', 'high', 'critical')
STATUSES = ('open', 'confirmed', 'remediated', 'closed')
FIELDS = {'id', 'tenant_id', 'owner_id', 'severity', 'status', 'tags'}

def parse_report(text: str) -> list[dict]:
    result = []
    seen = set()
    for line in text.splitlines():
        if not line.strip():
            continue
        try:
            item = json.loads(line)
        except Exception as exc:
            raise ValueError('invalid json') from exc
        if not isinstance(item, dict) or set(item) != FIELDS:
            raise ValueError('invalid record fields')
        for key in ('id', 'tenant_id', 'owner_id'):
            if not isinstance(item[key], str) or not item[key]:
                raise ValueError('invalid string')
        if item['severity'] not in SEVERITIES or item['status'] not in STATUSES:
            raise ValueError('invalid value')
        if not isinstance(item['tags'], list) or not all((isinstance(x, str) for x in item['tags'])):
            raise ValueError('invalid tags')
        if item['id'] in seen:
            raise ValueError('duplicate id')
        seen.add(item['id'])
        tags = sorted({x.strip() for x in item['tags'] if x.strip()})
        result.append({k: item[k] for k in ('id', 'tenant_id', 'owner_id', 'severity', 'status')} | {'tags': tags})
    return result

def apply_update(records: list[dict], requester: dict, finding_id: str, new_status: str, note: str) -> list[dict]:
    if not isinstance(requester, dict) or not isinstance(requester.get('id'), str) or (not isinstance(requester.get('tenant_id'), str)) or (not isinstance(requester.get('roles'), list)) or (not all((isinstance(x, str) for x in requester['roles']))):
        raise ValueError('invalid requester')
    if new_status not in STATUSES or not isinstance(note, str) or (not 1 <= len(note.strip()) <= 200):
        raise ValueError('invalid update')
    result = copy.deepcopy(records)
    target = next((x for x in result if x.get('id') == finding_id), None)
    if target is None:
        raise KeyError(finding_id)
    if requester['tenant_id'] != target.get('tenant_id') or (requester['id'] != target.get('owner_id') and 'lead' not in requester['roles']):
        raise PermissionError('not permitted')
    old = target.get('status')
    allowed = {'open': 'confirmed', 'confirmed': 'remediated', 'remediated': 'closed'}
    if allowed.get(old) != new_status:
        raise ValueError('invalid transition')
    history = target.get('history', [])
