import secrets

def reserve_appointment(slots: list[dict], passport_number: str, day: str, now: datetime, hold_minutes: int=20) -> dict | None:
    if not isinstance(passport_number, str) or not passport_number:
        raise ValueError('invalid passport number')
    if not isinstance(now, datetime) or now.tzinfo is not None:
        raise ValueError('now must be naive')
    if not isinstance(hold_minutes, int) or isinstance(hold_minutes, bool) or hold_minutes <= 0:
        raise ValueError('invalid hold duration')
    try:
