    except (TypeError, ValueError):
        raise ValueError('invalid day')
    alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
    candidates = []
    for slot in slots:
        if slot['day'] != requested_day.isoformat() or slot['status'] != 'available':
            continue
        hour, minute = (int(part) for part in slot['time'].split(':'))
        appointment = datetime.combine(requested_day, time(hour, minute))
        if appointment >= now:
            candidates.append((appointment, slot['id']))
    if not candidates:
        return None
    _, selected_id = min(candidates, key=lambda item: (item[0], item[1]))
    code = ''.join((secrets.choice(alphabet) for _ in range(12)))
    return {'slot_id': selected_id, 'passport_number': passport_number, 'hold_code': code, 'expires_at': (now + timedelta(minutes=hold_minutes)).isoformat(timespec='minutes')}

