import base64
import hashlib
import hmac
import json

def _check_key_now(key, now):
    if not isinstance(key, bytes) or not isinstance(now, int) or isinstance(now, bool):
        raise ValueError('invalid arguments')

def _check_text(value):
    return isinstance(value, str) and bool(value) and (not any((ord(c) < 32 for c in value)))

def create_lease(resource: str, holder: str, issued_at: int, expires_at: int, key: bytes) -> str:
    _check_key_now(key, issued_at)
    if not _check_text(resource) or not _check_text(holder) or (not isinstance(expires_at, int)) or isinstance(expires_at, bool) or (expires_at <= issued_at):
        raise ValueError('invalid lease')
    obj = {'resource': resource, 'holder': holder, 'issued_at': issued_at, 'expires_at': expires_at}
    raw = json.dumps(obj, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode()
    payload = base64.urlsafe_b64encode(raw).decode().rstrip('=')
    digest = hmac.new(key, payload.encode(), hashlib.sha256).hexdigest()
    return payload + '.' + digest

def validate_lease(token: str, key: bytes, now: int) -> dict:
    _check_key_now(key, now)
    if not isinstance(token, str) or token.count('.') != 1:
        raise ValueError('invalid token')
    payload, supplied = token.split('.')
    if not payload or len(supplied) != 64 or any((c not in '0123456789abcdef' for c in supplied)):
        raise ValueError('invalid token')
    expected = hmac.new(key, payload.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(supplied, expected):
        raise ValueError('invalid token')
    try:
        if base64.urlsafe_b64encode(base64.urlsafe_b64decode(payload + '===')).decode().rstrip('=') != payload:
            raise ValueError
        obj = json.loads(base64.urlsafe_b64decode(payload + '===').decode())
    except Exception as exc:
        raise ValueError('invalid token') from exc
    if not isinstance(obj, dict) or set(obj) != {'resource', 'holder', 'issued_at', 'expires_at'}:
        raise ValueError('invalid lease')
    if not _check_text(obj['resource']) or not _check_text(obj['holder']):
        raise ValueError('invalid lease')
    if any((not isinstance(obj[x], int) or isinstance(obj[x], bool) for x in ('issued_at', 'expires_at'))) or obj['expires_at'] <= obj['issued_at'] or obj['issued_at'] > now or (obj['expires_at'] <= now):
        raise ValueError('invalid lease')
    return {'resource': obj['resource'], 'holder': obj['holder'], 'issued_at': obj['issued_at'], 'expires_at': obj['expires_at']}

def summarize_leases(tokens: list[str], key: bytes, now: int) -> list[dict]:
    groups = {}
    for token in tokens:
        lease = validate_lease(token, key, now)
        item = groups.setdefault(lease['resource'], {'resource': lease['resource'], 'holders': set(), 'count': 0, 'expires_at': lease['expires_at']})
        item['holders'].add(lease['holder'])
        item['count'] += 1
        item['expires_at'] = max(item['expires_at'], lease['expires_at'])
    result = [{'resource': x['resource'], 'holders': sorted(x['holders']), 'count': x['count'], 'expires_at': x['expires_at']} for x in groups.values()]
    return sorted(result, key=lambda x: (-x['expires_at'], x['resource']))

