    products = [{'id': str(i), 'price': i, 'stock': 1, 'rating': 3} for i in range(1, 6)]
    assert synchronize_catalog(products, 'stock == 1', 'price', 1, 2) == {'items': [{'id': '1', 'price': 1}, {'id': '2', 'price': 2}], 'total': 5, 'pages': 3}
    assert synchronize_catalog(products, 'stock == 1', 'price', 3, 2)['items'] == [{'id': '5', 'price': 5}]

