import os
import zipfile

def extract_calendar_archive(archive_path: str, destination_dir: str) -> list[str]:
    os.makedirs(destination_dir, exist_ok=True)
    base = os.path.realpath(destination_dir)
    files = []
    with zipfile.ZipFile(archive_path) as archive:
        for member in archive.infolist():
            if member.is_dir():
                continue
            target = os.path.realpath(os.path.join(base, member.filename))
            if os.path.commonpath([base, target]) != base:
                raise ValueError(member.filename)
            files.append(member.filename)
        with zipfile.ZipFile(archive_path) as source:
            for member in source.infolist():
                if member.is_dir():
                    continue
                target = os.path.realpath(os.path.join(base, member.filename))
                os.makedirs(os.path.dirname(target), exist_ok=True)
                with source.open(member) as input_file, open(target, 'wb') as output_file:
                    output_file.write(input_file.read())
    return sorted(files)

