import hashlib
import hmac
import math
import os

def assess_property(property_id: str, assessed_value: float, tax_rate: float) -> dict:
    if not isinstance(property_id, str) or not property_id.strip():
        raise ValueError('property_id must be a non-empty string')
    if isinstance(assessed_value, bool) or not isinstance(assessed_value, (int, float)) or (not math.isfinite(assessed_value)) or (assessed_value < 0):
        raise ValueError('assessed_value must be a finite non-negative number')
    if isinstance(tax_rate, bool) or not isinstance(tax_rate, (int, float)) or (not math.isfinite(tax_rate)) or (not 0 <= tax_rate <= 1):
        raise ValueError('tax_rate must be a finite number between 0 and 1')
    key = os.environ.get('TAX_ASSESSMENT_SIGNING_KEY')
    if not key:
        raise RuntimeError('TAX_ASSESSMENT_SIGNING_KEY is not configured')
    assessed = round(assessed_value, 2)
    rate = round(tax_rate, 6)
    due = round(assessed_value * tax_rate, 2)
    payload = f'{property_id}|{assessed:.2f}|{rate:.6f}|{due:.2f}'.encode()
    signature = hmac.new(key.encode(), payload, hashlib.sha256).hexdigest()
    return {'property_id': property_id, 'assessed_value': assessed, 'tax_rate': rate, 'tax_due': due, 'signature': signature}

