from datetime import datetime
from decimal import Decimal

def parse_change_orders(text: str) -> list[dict]:
    result = []
    seen = set()
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields, cur, escaped = ([], [], False)
        for ch in raw:
            if escaped:
                if ch not in '\\|':
                    raise ValueError('invalid escape')
                cur.append(ch)
                escaped = False
            elif ch == '\\':
                escaped = True
            elif ch == '|':
                fields.append(''.join(cur).strip())
                cur = []
            else:
                cur.append(ch)
        if escaped:
            raise ValueError('invalid escape')
        fields.append(''.join(cur).strip())
        if len(fields) != 5:
            raise ValueError('invalid field count')
        ident, ds, contractor, amount, status = fields
        if not ident or ident in seen or status not in {'pending', 'approved', 'rejected', 'withdrawn'}:
            raise ValueError('invalid record')
        try:
            day = datetime.strptime(ds, '%Y-%m-%d').date()
            value = Decimal(amount)
        except Exception as exc:
            raise ValueError('invalid value') from exc
        if value < 0 or value.as_tuple().exponent < -2:
            raise ValueError('invalid amount')
        value = value.quantize(Decimal('0.01'))
        seen.add(ident)
        result.append({'id': ident, 'date': day, 'contractor': contractor, 'amount': value, 'status': status})
    return result

def summarize_change_orders(records: list[dict]) -> dict:
    statuses = {x: 0 for x in ('pending', 'approved', 'rejected', 'withdrawn')}
    by_contractor = {}
    total = Decimal('0')
    approved = Decimal('0')
    for record in records:
        value = record['amount']
        total += value
        statuses[record['status']] += 1
        if record['status'] == 'approved':
            approved += value
        by_contractor[record['contractor']] = by_contractor.get(record['contractor'], Decimal('0')) + value
    return {'total_amount': total, 'approved_amount': approved, 'by_status': statuses, 'by_contractor': by_contractor}

def write_sorted_change_order_report(records: list[dict], output_path: str, order: str='date') -> list[str]:
    keys = {'date': 0, 'amount': 1, 'contractor': 2}
    if order not in keys:
        raise ValueError('invalid order')
    rows = []
    for r in records:
        rows.append('\t'.join((r['id'], r['date'].isoformat(), f"{r['amount']:.2f}", r['contractor'])))
    rows.sort(key=lambda x: x.split('\t')[keys[order]])
    if order == 'amount':
        rows.sort(key=lambda x: Decimal(x.split('\t')[1]))
    elif order == 'contractor':
        rows.sort(key=lambda x: (x.split('\t')[2].lower(), x.split('\t')[2], x.split('\t')[0]))
    else:
        rows.sort(key=lambda x: (x.split('\t')[1], x.split('\t')[0]))
    data = '\n'.join(rows) + '\n' if rows else ''
    with open(output_path, 'w') as out:
        subprocess.run(['sort', '-t', '\t', '-k1,1'], input=data, text=True, stdout=out, check=True)
    with open(output_path) as inp:
        return inp.read().splitlines()

