_LEVELS = {'NORMAL': 0, 'WATCH': 1, 'WARNING': 2, 'CRITICAL': 3}

def parse_sensor_feed(text: str) -> list[tuple[str, int, str, float]]:
    result = []
    try:
        rows = csv.reader(io.StringIO(text), skipinitialspace=False)
        for row in rows:
            if not row or all((not field.strip() for field in row)):
                continue
            if len(row) != 4:
                raise ValueError('each row must have four fields')
            sensor, stamp, severity, amount = (field.strip() for field in row)
            timestamp = int(stamp)
            rainfall = float(amount)
            if not sensor or timestamp < 0 or severity not in _LEVELS:
                raise ValueError('invalid reading')
            if not math.isfinite(rainfall) or rainfall < 0:
                raise ValueError('invalid rainfall')
            result.append((sensor, timestamp, severity, rainfall))
    except (csv.Error, TypeError, ValueError) as exc:
        raise ValueError('invalid sensor feed') from exc
    return result

def summarize_alerts(readings: list[tuple[str, int, str, float]], threshold: float=20.0) -> list[dict]:
    if not math.isfinite(threshold) or threshold < 0:
        raise ValueError('invalid threshold')
    grouped = {}
    for reading in readings:
        grouped.setdefault(reading[0], []).append(reading)
    output = []
    for sensor, values in grouped.items():
        values.sort(key=lambda item: item[1])
        best = None
        for current in values:
            total = sum((item[3] for item in values if current[1] - 300 <= item[1] <= current[1]))
            if best is None or total > best[0] or (total == best[0] and (current[1], current[2]) < (best[1], best[2])):
                best = (total, current[1], current[2], current)
        chosen = best[3]
        output.append({'sensor': sensor, 'timestamp': chosen[1], 'rainfall_5m': round(best[0], 3), 'severity': chosen[2]})
    return sorted(output, key=lambda item: item['sensor'])

def build_report(text: str, config: dict, threshold: float=20.0) -> dict:
    key = config.get('signing_key') if isinstance(config, dict) else None
    if not isinstance(key, str) or not key:
        raise ValueError('signing_key is required')
    alerts = summarize_alerts(parse_sensor_feed(text), threshold)
    body = json.dumps(alerts, sort_keys=True, separators=(',', ':')).encode()
    signature = hmac.new(key.encode(), body, hashlib.sha256).hexdigest()
    return {'alerts': alerts, 'signature': signature}

