            raise ValueError('unsupported expression')
        raise error

def select_and_rank(records: list[dict[str, object]], condition: str, score_expression: str, window: int=0) -> list[dict[str, object]]:
    if isinstance(window, bool) or not isinstance(window, int) or window < 0:
        raise ValueError('invalid window')
    selected = []
    for record in records:
        if evaluate_expression(condition, record):
            score = evaluate_expression(score_expression, record)
            if isinstance(score, bool) or not isinstance(score, (int, float)):
                raise TypeError('score must be numeric')
            selected.append((record, score))
    selected.sort(key=lambda item: (-item[1], item[0]['year'], item[0]['id']))
    return [{'id': record['id'], 'score': score, 'year': record['year'], 'window_count': sum((other[0]['count'] for other in selected if abs(other[0]['year'] - record['year']) <= window))} for record, score in selected]

