import copy
import math

def parse_feed_line(line: str) -> tuple[str, str, float, int, list[str]]:
    fields = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('dangling escape')
    fields.append(''.join(current))
    if len(fields) != 5 or not fields[0] or (not fields[1]):
        raise ValueError('invalid feed line')
    try:
        price = float(fields[2].strip())
        delta = int(fields[3].strip())
    except (ValueError, TypeError):
        raise ValueError('invalid number')
    if not math.isfinite(price) or price < 0:
        raise ValueError('invalid price')
    tags = []
    for tag in fields[4].split(',') if fields[4] else []:
        if tag not in tags:
            tags.append(tag)
    return (fields[0], fields[1], price, delta, tags)

def sort_products(products: dict[str, dict]) -> list[dict]:
    result = [{'sku': sku, 'name': p['name'], 'price': p['price'], 'stock': p['stock'], 'tags': list(p['tags'])} for sku, p in products.items()]
    return sorted(result, key=lambda p: (-p['stock'], p['price'], p['sku']))

def sync_catalog(requester: dict, catalog: dict, feed: str) -> dict:
    allowed = requester.get('id') == catalog.get('owner_id') or ('catalog_admin' in requester.get('roles', []) and catalog.get('tenant_id') in requester.get('tenant_ids', []))
    if not allowed:
        raise PermissionError('not permitted')
    products = copy.deepcopy(catalog['products'])
    for line in feed.splitlines():
        if not line.strip():
            continue
        sku, name, price, delta, tags = parse_feed_line(line)
        stock = products[sku]['stock'] + delta if sku in products else delta
        if stock < 0:
            raise ValueError('negative stock')
        products[sku] = {'name': name, 'price': price, 'stock': stock, 'tags': tags}
    ordered = sort_products(products)
    return {'tenant_id': catalog['tenant_id'], 'owner_id': catalog['owner_id'], 'products': ordered, 'total_stock': sum((p['stock'] for p in ordered)), 'total_value': round(sum((p['stock'] * p['price'] for p in ordered)), 2)}

