def build_member_progress_report(requester: dict, member: dict, sessions: list[dict], start_date: str, end_date: str, page: int, page_size: int) -> dict:
    if not isinstance(requester, dict) or not isinstance(member, dict):
        raise TypeError()
    for obj, fields in ((requester, ('id', 'tenant_id', 'role')), (member, ('id', 'tenant_id', 'name'))):
        if any((k not in obj for k in fields)):
            raise ValueError()
    if not isinstance(sessions, list):
        raise TypeError()
    try:
        start = date.fromisoformat(start_date)
        end = date.fromisoformat(end_date)
    except (TypeError, ValueError):
        raise ValueError()
    if start > end or not isinstance(page, int) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError()
    if requester['tenant_id'] != member['tenant_id'] or (requester['id'] != member['id'] and requester['role'] not in ('manager', 'admin')):
        raise PermissionError()
    selected = []
