            raise TypeError()
        required = ('member_id', 'date', 'class_name', 'minutes', 'calories')
        if any((k not in item for k in required)):
            raise ValueError()
        try:
            day = date.fromisoformat(item['date'])
        except (TypeError, ValueError):
            raise ValueError()
        if not isinstance(item['minutes'], int) or not isinstance(item['calories'], int) or item['minutes'] < 0 or (item['calories'] < 0):
            raise ValueError()
