def query_samples(conn: sqlite3.Connection, regions: list[str] | tuple[str, ...], min_depth: float | None, max_depth: float | None, sort_by: str, limit: int, offset: int) -> list[dict]:
    if not isinstance(regions, (list, tuple)):
        raise TypeError('regions must be a list or tuple')
    if isinstance(limit, bool) or not isinstance(limit, int) or isinstance(offset, bool) or (not isinstance(offset, int)):
        raise TypeError('limit and offset must be integers')
    if limit < 0 or offset < 0:
        raise ValueError('limit and offset must be nonnegative')
    if min_depth is not None and max_depth is not None and (min_depth > max_depth):
        raise ValueError('invalid depth range')
    ordering = {'id': 'id ASC', 'id_desc': 'id DESC', 'depth': 'depth ASC', 'depth_desc': 'depth DESC', 'grade': 'grade ASC', 'grade_desc': 'grade DESC', 'site': 'site ASC', 'site_desc': 'site DESC'}
    if sort_by not in ordering:
        raise ValueError('invalid sort order')
    clauses = []
    params = []
    if regions:
        placeholders = ','.join(('?' for _ in regions))
        clauses.append('region IN (' + placeholders + ')')
        params.extend(regions)
    if min_depth is not None:
        clauses.append('depth >= ?')
        params.append(min_depth)
    if max_depth is not None:
        clauses.append('depth <= ?')
        params.append(max_depth)
    sql = 'SELECT id, site, region, depth, mineral, grade FROM samples'
    if clauses:
        sql += ' WHERE ' + ' AND '.join(clauses)
    sql += ' ORDER BY ' + ordering[sort_by] + ', id ASC LIMIT ? OFFSET ?'
    params.extend([limit, offset])
    rows = conn.execute(sql, params).fetchall()
    return [{'id': r[0], 'site': r[1], 'region': r[2], 'depth': r[3], 'mineral': r[4], 'grade': round(r[5], 2)} for r in rows]

