def export_distribution(assignments: list[tuple[str, str, int]], output_path: str) -> int:
    rows = []
    for assignment in assignments:
        if len(assignment) != 3:
            raise ValueError('each assignment must have three values')
        family_id, pantry, portions = assignment
        if not isinstance(family_id, str) or not family_id:
            raise ValueError('invalid family_id')
        if not isinstance(pantry, str) or not pantry:
            raise ValueError('invalid pantry')
        if not isinstance(portions, int) or isinstance(portions, bool) or portions < 0:
            raise ValueError('invalid portions')
        rows.append((family_id, pantry, portions))
    rows.sort(key=lambda row: (row[1], row[0]))
    directory = os.path.dirname(os.path.abspath(output_path))
    fd, temporary_path = tempfile.mkstemp(prefix='.distribution-', suffix='.tmp', dir=directory)
    try:
        with os.fdopen(fd, 'w', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(('family_id', 'pantry', 'portions'))
            writer.writerows(rows)
        os.replace(temporary_path, output_path)
    except Exception:
        try:
            os.unlink(temporary_path)
        except FileNotFoundError:
            pass
        raise
    return len(rows)

