    end = start + duration
    query = 'SELECT 1 FROM bookings WHERE photographer = ? AND day = ? AND start < ? AND start + duration > ?'
    args = [photographer, day, end, start]
    if exclude is not None:
        query += ' AND id <> ?'
        args.append(exclude)
    return conn.execute(query, args).fetchone() is not None

def create_booking(conn: sqlite3.Connection, client: str, photographer: str, day: str, start: int, duration: int, notes: str='') -> int:
    if not isinstance(client, str) or not client or (not isinstance(photographer, str)) or (not photographer):
        raise ValueError('names required')
