    _check_time(start, duration)
    if _overlap(conn, photographer, day, start, duration):
        raise ValueError('overlap')
    cur = conn.execute('INSERT INTO bookings (client, photographer, day, start, duration, notes) VALUES (?, ?, ?, ?, ?, ?)', (client, photographer, day, start, duration, notes))
    conn.commit()
