import ast
import operator

def _evaluate(node, values):
    if isinstance(node, ast.Expression):
        return _evaluate(node.body, values)
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id in values:
            return values[node.id]
        if node.id in {'min', 'max', 'round'}:
            return {'min': min, 'max': max, 'round': round}[node.id]
        raise NameError(node.id)
    if isinstance(node, ast.BinOp) and type(node.op) in {ast.Add, ast.Sub, ast.Mult, ast.Div}:
        fn = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)]
        return fn(_evaluate(node.left, values), _evaluate(node.right, values))
    if isinstance(node, ast.UnaryOp) and type(node.op) in {ast.USub, ast.UAdd, ast.Not}:
        value = _evaluate(node.operand, values)
        if isinstance(node.op, ast.USub):
            return -value
        if isinstance(node.op, ast.UAdd):
            return +value
        return not value
    if isinstance(node, ast.BoolOp) and type(node.op) in {ast.And, ast.Or}:
        result = _evaluate(node.values[0], values)
        for child in node.values[1:]:
            if isinstance(node.op, ast.And) and (not result):
                return result
            if isinstance(node.op, ast.Or) and result:
                return result
            result = _evaluate(child, values)
        return result
    if isinstance(node, ast.Compare):
        left = _evaluate(node.left, values)
        for op, child in zip(node.ops, node.comparators):
            right = _evaluate(child, values)
            if type(op) not in {ast.Lt, ast.LtE, ast.Gt, ast.GtE, ast.Eq, ast.NotEq}:
                raise ValueError('unsupported syntax')
            fn = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}[type(op)]
            if not fn(left, right):
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max', 'round'}) and (not node.keywords):
        return _evaluate(node.func, values)(*[_evaluate(arg, values) for arg in node.args])
    raise ValueError('unsupported syntax')

def inventory_filter(records: list[dict], expression: str) -> list[str]:
    try:
        tree = ast.parse(expression, mode='eval')
    except SyntaxError as exc:
        raise ValueError('unsupported syntax') from exc
    result = []
    for record in records:
        values = {key: record[key] for key in ('id', 'quantity', 'unit_cost', 'reorder_level')}
        if _evaluate(tree, values):
            result.append(record['id'])
    return result

