import os
import tempfile

def parse_transactions(csv_text: str) -> list[dict]:
    try:
        rows = list(csv.reader(csv_text.splitlines(keepends=True), strict=True))
    except (csv.Error, TypeError):
        raise ValueError('invalid CSV')
    header = ['id', 'timestamp', 'kind', 'currency', 'amount_cents', 'category', 'note']
    if not rows or rows[0] != header or len(rows) < 2:
        raise ValueError('invalid document')
    result = []
    seen = set()
    for fields in rows[1:]:
        if len(fields) != 7:
            raise ValueError('invalid row')
        ident, stamp, kind, currency, amount, category, note = fields
        if not ident or ident in seen or kind not in ('credit', 'debit'):
            raise ValueError('invalid field')
        if len(currency) != 3 or not currency.isascii() or (not currency.isupper()) or (not currency.isalpha()):
            raise ValueError('invalid currency')
        if not amount.isdigit() or (len(amount) > 1 and amount[0] == '0'):
            raise ValueError('invalid amount')
        if not stamp.endswith('Z'):
            raise ValueError('invalid timestamp')
        try:
            dt = datetime.datetime.fromisoformat(stamp[:-1] + '+00:00')
        except ValueError:
            raise ValueError('invalid timestamp')
        if dt.tzinfo is None or dt.utcoffset() != datetime.timedelta(0):
            raise ValueError('invalid timestamp')
        normalized = dt.astimezone(datetime.timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')
        cents = int(amount)
        seen.add(ident)
        result.append({'id': ident, 'timestamp': normalized, 'kind': kind, 'currency': currency, 'amount_cents': cents, 'category': category, 'note': note, 'signed_cents': cents if kind == 'credit' else -cents})
    result.sort(key=lambda x: (x['timestamp'], x['id']))
    return result

def export_statement(csv_text: str, output_path: str) -> dict:
    transactions = parse_transactions(csv_text)
    currencies = {}
    categories = {}
    for row in transactions:
        cur = currencies.setdefault(row['currency'], {'credits_cents': 0, 'debits_cents': 0, 'balance_cents': 0, 'count': 0})
        cur['count'] += 1
        cur['balance_cents'] += row['signed_cents']
        cur['credits_cents' if row['kind'] == 'credit' else 'debits_cents'] += row['amount_cents']
        cat = categories.setdefault(row['category'], {'net_cents': 0, 'count': 0})
