import operator

def evacuation_plan(zones: list[dict], rule: str, capacity: int) -> dict:
    if isinstance(capacity, bool) or not isinstance(capacity, int) or capacity < 0:
        raise ValueError()
    if not isinstance(rule, str) or not rule.strip():
        raise ValueError()
    try:
        tree = ast.parse(rule, mode='eval').body

        def run(node, names):
            if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
                return node.value
            if isinstance(node, ast.Name):
                if node.id not in names:
                    raise ValueError()
                return names[node.id]
            if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
                op = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)]
                return op(run(node.left, names), run(node.right, names))
            if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub, ast.Not):
                value = run(node.operand, names)
                return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
            if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
                values = [run(x, names) for x in node.values]
                result = values[0]
                for value in values[1:]:
                    result = result and value if isinstance(node.op, ast.And) else result or value
                return result
            if isinstance(node, ast.Compare):
                left = run(node.left, names)
                ops = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}
