from decimal import Decimal, InvalidOperation
from datetime import datetime

def parse_payment_batch(text: str) -> list[dict]:
    result = []
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields = []
        field = []
        escaped = False
        for ch in raw:
            if escaped:
                field.append(ch)
                escaped = False
            elif ch == '\\':
                escaped = True
            elif ch == '|':
                fields.append(''.join(field))
                field = []
            else:
                field.append(ch)
        if escaped:
            raise ValueError('invalid escape')
        fields.append(''.join(field))
        if len(fields) != 5 or not fields[0] or (not fields[1]):
            raise ValueError('invalid payment')
        try:
            amount = Decimal(fields[2])
        except InvalidOperation:
            raise ValueError('invalid amount')
        if not amount.is_finite() or amount <= 0 or amount.as_tuple().exponent < -2:
            raise ValueError('invalid amount')
        if fields[3] not in {'USD', 'EUR', 'GBP'}:
            raise ValueError('invalid currency')
        result.append({'payment_id': fields[0], 'account_id': fields[1], 'amount': f'{amount:.2f}', 'currency': fields[3], 'beneficiary': fields[4]})
    return result

def release_customs_payments(text: str, requester: dict, accounts: dict, now: datetime) -> list[dict]:
    items = parse_payment_batch(text)
    if len({x['payment_id'] for x in items}) != len(items):
        raise ValueError('duplicate payment')
    checked = []
    for item in items:
        account = accounts[item['account_id']]
        if account.get('tenant') != requester.get('tenant'):
            raise PermissionError('not permitted')
        amount = Decimal(item['amount'])
        if account.get('currency') != item['currency']:
            raise ValueError('currency mismatch')
        balance = Decimal(str(account['balance']))
        limit = Decimal(str(account['daily_limit']))
        today = Decimal(str(account['released_today']))
        if amount > balance or today + amount > limit:
            raise ValueError('payment exceeds account limits')
        checked.append((item, account, amount))
    for item, account, amount in checked:
        account['balance'] = Decimal(str(account['balance'])) - amount
        account['released_today'] = Decimal(str(account['released_today'])) + amount
    return [{**item, 'released_at': now.isoformat()} for item, _, _ in checked]

