def summarize_transfer_files(paths: list[str], page: int=1, page_size: int=10) -> dict:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)):
        raise ValueError('pagination values must be integers')
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination values')
    counts = []
    for path in paths:
        if not os.path.isfile(path):
            raise FileNotFoundError(path)
        result = subprocess.run(['wc', '-l', path], check=True, capture_output=True, text=True)
        count = int(result.stdout.strip().split()[0])
        counts.append({'path': path, 'transfers': count})
    counts.sort(key=lambda item: (-item['transfers'], item['path']))
    start = (page - 1) * page_size
    return {'total_files': len(counts), 'total_transfers': sum((item['transfers'] for item in counts)), 'items': counts[start:start + page_size]}

