import csv
import copy
from datetime import datetime, timezone
from io import StringIO
HEAD = ['accession_id', 'patient_id', 'owner_id', 'tenant', 'collected_at', 'tests']
STATES = {'RECEIVED', 'PROCESSING', 'COMPLETED', 'REJECTED'}
NEXT = {'RECEIVED': {'PROCESSING', 'REJECTED'}, 'PROCESSING': {'COMPLETED', 'REJECTED'}}

def dt(value):
    if not isinstance(value, str) or not value.endswith('Z'):
        raise ValueError('timestamp')
    try:
        x = datetime.fromisoformat(value[:-1] + '+00:00')
    except Exception:
        raise ValueError('timestamp')
    if x.tzinfo != timezone.utc:
        raise ValueError('timestamp')
    return x

def parse_manifest(text: str) -> list[dict]:
    try:
        rows = list(csv.reader(StringIO(text), strict=True))
    except Exception:
        raise ValueError('csv')
    if not rows:
        return []
    if rows[0] != HEAD:
        raise ValueError('header')
    out, seen = ([], set())
    for row in rows[1:]:
        if len(row) != 6:
            raise ValueError('row')
        vals = [x.strip() for x in row[:4]] + [row[4], row[5]]
        if any((not x for x in vals[:4])) or not vals[4] or (not vals[5]):
            raise ValueError('field')
        if vals[0] in seen:
            raise ValueError('duplicate')
        dt(vals[4])
        tests = [x.strip() for x in vals[5].split(';')]
        if any((not x for x in tests)):
            raise ValueError('tests')
        seen.add(vals[0])
        out.append(dict(zip(HEAD, vals[:5] + [tests])))
    return out

class AccessionService:

    def __init__(self, records):
        self.records = {}
        for source in records:
            r = copy.deepcopy(source)
            dt(r['collected_at'])
            r['state'] = 'RECEIVED'
            r['history'] = [{'state': 'RECEIVED', 'at': r['collected_at']}]
            self.records[r['accession_id']] = r

    def get(self, accession_id):
        return copy.deepcopy(self.records[accession_id])

    def transition(self, accession_id, requester, new_state, at):
        if accession_id not in self.records:
            raise KeyError(accession_id)
        r = self.records[accession_id]
        if requester.get('tenant') != r['tenant'] and 'admin' not in requester.get('roles', []):
            raise PermissionError('tenant')
        if requester.get('id') != r['owner_id'] and (not {'accessionist', 'admin'} & set(requester.get('roles', []))):
            raise PermissionError('owner')
        if new_state not in STATES or new_state not in NEXT.get(r['state'], set()):
            raise ValueError('transition')
        stamp = dt(at)
        if stamp < dt(r['history'][-1]['at']):
            raise ValueError('order')
        r['state'] = new_state
        r['history'].append({'state': new_state, 'at': at})
        return copy.deepcopy(r)

def summarize_turnaround(records, start, end):
    a, b = (dt(start), dt(end))
    if a >= b:
        raise ValueError('bounds')
    groups = {}
    for r in records:
        c = dt(r['collected_at'])
        if a <= c < b:
            key = r['tenant'] + '/' + c.date().isoformat()
            g = groups.setdefault(key, {'specimens': 0, 'completed': 0, 'rejected': 0, 'average_hours': 0.0})
            g['specimens'] += 1
            if r.get('state') == 'COMPLETED':
                g['completed'] += 1
                g.setdefault('_hours', []).append((dt(r['history'][-1]['at']) - c).total_seconds() / 3600)
            elif r.get('state') == 'REJECTED':
                g['rejected'] += 1
    for g in groups.values():
        h = g.pop('_hours', [])
        g['average_hours'] = sum(h) / len(h) if h else 0.0
    return dict(sorted(groups.items()))

