import pytest


def test_filters_and_sorts_hostnames():
    records = [
        {"hostname": "zeta", "missing": 4, "severity": 8, "reboot_required": False},
        {"hostname": "alpha", "missing": 1, "severity": 9, "reboot_required": True},
        {"hostname": "beta", "missing": 0, "severity": 10, "reboot_required": False},
    ]
    assert patch_compliance(records, "missing > 0 and severity >= 8") == ["alpha", "zeta"]


def test_arithmetic_precedence_and_boolean_values():
    records = [
        {"hostname": "one", "missing": 2, "severity": 3, "reboot_required": False},
        {"hostname": "two", "missing": 3, "severity": 2, "reboot_required": False},
        {"hostname": "three", "missing": 1, "severity": 9, "reboot_required": True},
    ]
    assert patch_compliance(records, "missing * 2 + severity >= 8 and not reboot_required") == ["two"]


def test_functions_parentheses_and_chained_comparison():
    records = [
        {"hostname": "a", "missing": 3, "severity": 7, "reboot_required": False},
        {"hostname": "b", "missing": 6, "severity": 4, "reboot_required": False},
        {"hostname": "c", "missing": 1, "severity": 10, "reboot_required": True},
    ]
    assert patch_compliance(records, "min(missing, severity) >= 3 and 3 <= max(missing, severity) < 8") == ["a", "b"]


def test_empty_records_and_input_is_unchanged():
    records = [{"hostname": "host", "missing": 2, "severity": 5, "reboot_required": True}]
    original = [record.copy() for record in records]
    assert patch_compliance([], "missing > 0") == []
    assert patch_compliance(records, "reboot_required") == ["host"]
    assert records == original


