import ast
import operator

def patch_compliance(records: list[dict[str, object]], expression: str) -> list[str]:
    try:
        tree = ast.parse(expression, mode='eval').body
        allowed = {'missing', 'severity', 'reboot_required', 'hostname'}

        def ev(node, names):
            if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
                return node.value
            if isinstance(node, ast.Name) and node.id in allowed:
                return names[node.id]
            if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
                value = ev(node.operand, names)
                return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
            if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
                left, right = (ev(node.left, names), ev(node.right, names))
                return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
            if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
                value = ev(node.values[0], names)
                for item in node.values[1:]:
                    if isinstance(node.op, ast.And) and (not value):
                        return value
                    if isinstance(node.op, ast.Or) and value:
                        return value
                    value = ev(item, names)
                return value
            if isinstance(node, ast.Compare):
                left = ev(node.left, names)
                for op, part in zip(node.ops, node.comparators):
                    right = ev(part, names)
                    fn = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}.get(type(op))
                    if fn is None or not fn(left, right):
                        return False
                    left = right
                return True
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max'}) and (not node.keywords) and (len(node.args) >= 2):
                values = [ev(arg, names) for arg in node.args]
                return min(values) if node.func.id == 'min' else max(values)
            raise ValueError()
        result = []
        for record in records:
            if ev(tree, record):
                result.append(record['hostname'])
        return sorted(result)
    except Exception as exc:
        raise ValueError('invalid expression') from exc

