import math
import os
import tempfile

def make_log(contents):
    handle = tempfile.NamedTemporaryFile(mode='w', delete=False)
    try:
        handle.write(contents)
        return handle.name
    finally:
        handle.close()

def test_pattern_selects_only_matching_lines():
    path = make_log('a,S1,5,1\nb,S2,9,1\nc,S1,7,1\n')
    try:
        assert summarize_vibration(path, 'S1', 0, 10) == [('S1', 2, 6.0)]
    finally:
        os.unlink(path)

def test_limit_and_tie_breaking():
    path = make_log('a,A,5,1\nb,B,5,1\nc,C,5,1\n')
    try:
        assert summarize_vibration(path, '[A-C]', 0, 2) == [('A', 1, 5.0), ('B', 1, 5.0)]
    finally:
        os.unlink(path)

def test_empty_and_below_threshold_results():
    path = make_log('\nfirst,S1,1.5,2\nsecond,S2,2.0,2\n')
    try:
        assert summarize_vibration(path, 'Z', 0, 3) == []
        assert summarize_vibration(path, 'S', 2.1, 3) == []
    finally:
        os.unlink(path)

def test_invalid_limit_and_threshold():
    path = make_log('a,S1,2,3\n')
    try:
        for value in (0, -1, 1.5, True):
            try:
                summarize_vibration(path, 'S1', 0, value)
                assert False
            except ValueError:
                pass
        try:
            summarize_vibration(path, 'S1', math.nan, 1)
            assert False
        except ValueError:
            pass
    finally:
        os.unlink(path)

def test_malformed_selected_record_raises():
    path = make_log('a,S1,not-a-number,3\n')
    try:
        try:
            summarize_vibration(path, 'S1', 0, 1)
            assert False
        except ValueError:
            pass
    finally:
        os.unlink(path)

