import math
import subprocess

def summarize_vibration(path: str, sensor_pattern: str, min_rms: float, limit: int) -> list[tuple[str, int, float]]:
    if isinstance(limit, bool) or not isinstance(limit, int) or limit < 1:
        raise ValueError('limit must be a positive integer')
    if not math.isfinite(min_rms):
        raise ValueError('min_rms must be finite')
    result = subprocess.run(['grep', '-h', '-E', '--', sensor_pattern, path], capture_output=True, text=True, check=False)
    if result.returncode == 2:
        if not isinstance(path, str) or not __import__('os').path.isfile(path):
            raise FileNotFoundError(path)
        raise ValueError('grep failed')
    groups = {}
    for line in result.stdout.splitlines():
        if not line.strip():
            continue
        fields = line.split(',')
        if len(fields) != 4 or not fields[1]:
            raise ValueError('invalid record')
        try:
            rms = float(fields[2])
        except ValueError as exc:
            raise ValueError('invalid RMS') from exc
        if rms >= min_rms:
            groups.setdefault(fields[1], []).append(rms)
    rows = [(sensor, len(values), round(sum(values) / len(values), 2)) for sensor, values in groups.items()]
    rows.sort(key=lambda row: (-row[2], -row[1], row[0]))
    return rows[:limit]

