from solution import assign_variants

import hashlib
import hmac
import os
from unittest.mock import patch


def make_config():
    return {
        "checkout": {
            "variants": {
                "control": 1,
                "new_button": 2,
                "compact_flow": 1,
            }
        }
    }


def expected(users, key, experiment, variants):
    total = sum(variants.values())
    result = []
    for user in sorted(users):
        message = (experiment + ":" + user).encode()
        digest = hmac.new(key.encode(), message, hashlib.sha256).digest()
        point = int.from_bytes(digest[:8], "big") % total
        running = 0
        for name, weight in variants.items():
            running += weight
            if point < running:
                result.append((user, name))
                break
    return result


def test_assignments_are_stable_and_sorted():
    users = ["zoe", "alice", "mike", "bob"]
    config = make_config()
    with patch.dict(os.environ, {"EXPERIMENT_ASSIGNMENT_KEY": "test-key"}):
        actual = assign_variants(users, "checkout", config)
    assert actual == expected(users, "test-key", "checkout", config["checkout"]["variants"])
    assert [item[0] for item in actual] == ["alice", "bob", "mike", "zoe"]


def test_same_user_is_consistent_across_input_order():
    config = make_config()
    with patch.dict(os.environ, {"EXPERIMENT_ASSIGNMENT_KEY": "another-key"}):
        first = assign_variants(["c", "a", "b"], "checkout", config)
        second = assign_variants(["b", "c", "a"], "checkout", config)
    assert first == second


def test_offset_and_limit_are_applied_after_sorting():
    users = ["delta", "alpha", "charlie", "bravo", "echo"]
    config = make_config()
    with patch.dict(os.environ, {"EXPERIMENT_ASSIGNMENT_KEY": "page-key"}):
        full = assign_variants(users, "checkout", config)
        page = assign_variants(users, "checkout", config, offset=1, limit=2)
        tail = assign_variants(users, "checkout", config, offset=3)
    assert page == full[1:3]
    assert tail == full[3:]


def test_zero_limit_and_empty_users():
    config = make_config()
    with patch.dict(os.environ, {"EXPERIMENT_ASSIGNMENT_KEY": "empty-key"}):
        assert assign_variants([], "checkout", config) == []
        assert assign_variants(["a", "b"], "checkout", config, limit=0) == []


def test_unknown_experiment_and_malformed_configuration_raise_value_error():
    with patch.dict(os.environ, {"EXPERIMENT_ASSIGNMENT_KEY": "validation-key"}):
        try:
            assign_variants(["a"], "missing", make_config())
            assert False
        except ValueError:
            pass
        try:
            assign_variants(["a"], "checkout", {"checkout": {"variants": {"x": 0}}})
            assert False
        except ValueError:
            pass


def test_duplicate_and_invalid_user_arguments_raise_value_error():
    config = make_config()
    with patch.dict(os.environ, {"EXPERIMENT_ASSIGNMENT_KEY": "validation-key"}):
        for users in (["a", "a"], [""], [1]):
            try:
                assign_variants(users, "checkout", config)
                assert False
            except ValueError:
                pass
        for offset, limit in [(-1, None), (0, -2), (True, None)]:
            try:
                assign_variants(["a"], "checkout", config, offset=offset, limit=limit)
                assert False
            except ValueError:
                pass


def test_variant_weight_order_controls_boundaries():
    config = {"exp": {"variants": {"first": 3, "second": 1}}}
    users = ["u1", "u2", "u3", "u4"]
    with patch.dict(os.environ, {"EXPERIMENT_ASSIGNMENT_KEY": "weights"}):
        result = assign_variants(users, "exp", config)
    assert result == expected(users, "weights", "exp", config["exp"]["variants"])
    assert all(variant in {"first", "second"} for _, variant in result)


