from datetime import date, timedelta
from decimal import Decimal, InvalidOperation
import secrets
_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'

def _fields(line):
    fields, current, escaped = ([], [], False)
    for char in line:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current).strip())
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('dangling escape')
    fields.append(''.join(current).strip())
    return fields

def parse_cashflows(text: str) -> list[dict]:
    if not isinstance(text, str):
        raise TypeError('text must be a string')
    result = []
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields = _fields(raw)
        if len(fields) != 5:
            raise ValueError('wrong field count')
        datestr, desk, currency, amount, status = fields
        if not desk or not currency or status not in {'pending', 'settled'}:
            raise ValueError('invalid field')
        try:
            day = date.fromisoformat(datestr)
            value = Decimal(amount)
        except (ValueError, InvalidOperation):
            raise ValueError('invalid value')
        if not value.is_finite():
            raise ValueError('invalid amount')
        result.append({'date': day, 'desk': desk, 'currency': currency, 'amount': value, 'status': status})
    return result

def forecast_summary(records: list[dict], as_of: str, horizon_days: int) -> list[dict]:
    if not isinstance(horizon_days, int) or isinstance(horizon_days, bool) or horizon_days <= 0:
        raise ValueError('invalid horizon')
    try:
        start = date.fromisoformat(as_of)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    end = start + timedelta(days=horizon_days)
    grouped = {}
    for record in records:
        if not isinstance(record, dict) or not {'date', 'desk', 'currency', 'amount', 'status'} <= record.keys():
            raise ValueError('invalid record')
        if not isinstance(record['date'], date) or not isinstance(record['amount'], Decimal):
            raise ValueError('invalid record')
        if record['status'] == 'pending' and start <= record['date'] < end:
            key = (record['desk'], record['currency'])
            total, count = grouped.get(key, (Decimal(0), 0))
            grouped[key] = (total + record['amount'], count + 1)
    return [{'desk': d, 'currency': c, 'total': grouped[d, c][0], 'count': grouped[d, c][1]} for d, c in sorted(grouped)]

def generate_invite_code(length: int=12) -> str:
    if not isinstance(length, int) or isinstance(length, bool) or (not 8 <= length <= 64):
        raise ValueError('length must be between 8 and 64')
    return ''.join((secrets.choice(_ALPHABET) for _ in range(length)))

