import csv
import math
import os
import tempfile

def export_case_report(cases: list[dict], destination: str, status: str | None=None, page: int=1, page_size: int=50) -> dict:
    valid_statuses = {'pending', 'approved', 'denied', 'archived'}
    if status is not None and status not in valid_statuses:
        raise ValueError('invalid status')
    if page < 1 or page_size < 1 or page_size > 1000:
        raise ValueError('invalid pagination')
    selected = []
    for case in cases:
        required = ('case_id', 'applicant', 'country', 'status', 'days_pending')
        if any((key not in case for key in required)):
            raise ValueError('invalid case')
        if not all((isinstance(case[key], str) for key in required[:4])):
            raise ValueError('invalid case')
        if case['status'] not in valid_statuses:
            raise ValueError('invalid case')
        if isinstance(case['days_pending'], bool) or not isinstance(case['days_pending'], int) or case['days_pending'] < 0:
            raise ValueError('invalid case')
        if status is None or case['status'] == status:
            selected.append(case)
    selected.sort(key=lambda item: (-item['days_pending'], item['case_id']))
    total = len(selected)
    pages = math.ceil(total / page_size) if total else 0
    start = (page - 1) * page_size
    current = selected[start:start + page_size]
    average = round(sum((item['days_pending'] for item in selected)) / total, 2) if total else 0.0
    parent = os.path.dirname(os.path.abspath(destination))
    descriptor, temporary = tempfile.mkstemp(prefix='.case-report-', dir=parent, text=True)
    try:
        with os.fdopen(descriptor, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle)
            writer.writerow(['case_id', 'applicant', 'country', 'status', 'days_pending'])
            for item in current:
                writer.writerow([item[key] for key in ('case_id', 'applicant', 'country', 'status', 'days_pending')])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return {'total': total, 'page': page, 'page_size': page_size, 'pages': pages, 'average_days': average, 'case_ids': [item['case_id'] for item in current]}

