def parse_price_feed(source: str) -> list[dict[str, object]]:
    reader = csv.reader(source.splitlines())
    try:
        header = next(reader)
    except StopIteration:
        raise ValueError('missing header')
    if header != _HEADER:
        raise ValueError('invalid header')
    result = []
    for row in reader:
        if not row or all((x == '' for x in row)):
            continue
        if len(row) != 5 or not row[0] or (not row[1]):
            raise ValueError('invalid row')
        try:
            price = Decimal(row[2])
            if not price.is_finite() or price <= 0:
                raise ValueError('invalid price')
            price = price.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
            if not row[3] or datetime.date.fromisoformat(row[3]).isoformat() != row[3]:
                raise ValueError('invalid date')
        except (InvalidOperation, ValueError):
            raise ValueError('invalid value')
        active = row[4].lower()
        if active not in ('yes', 'no'):
            raise ValueError('invalid active')
        result.append({'store': row[0], 'sku': row[1], 'price': price, 'updated': row[3], 'active': active == 'yes'})
    return result

def sync_prices(source: str, destination: str) -> dict[str, int]:
    rows = parse_price_feed(source)
    latest = {}
    for row in rows:
        key = (row['store'], row['sku'])
        old = latest.get(key)
        if old is None or row['updated'] >= old['updated']:
            latest[key] = row
    selected = [r for r in latest.values() if r['active']]
    selected.sort(key=lambda r: (r['store'], r['sku']))
    directory = os.path.dirname(os.path.abspath(destination))
    temporary = tempfile.mktemp(dir=directory, prefix='.prices-')
    try:
        with open(temporary, 'w', newline='', encoding='utf-8') as f:
            writer = csv.writer(f, lineterminator='\n')
            writer.writerow(_HEADER)
            for row in selected:
                writer.writerow([row['store'], row['sku'], format(row['price'], '.2f'), row['updated'], 'yes'])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return {'input_rows': len(rows), 'retained_rows': len(selected), 'stores': len({r['store'] for r in selected})}

