def ensure_schema(conn: sqlite3.Connection) -> None:
    conn.execute('CREATE TABLE IF NOT EXISTS documents (id INTEGER PRIMARY KEY, title TEXT NOT NULL, metadata TEXT NOT NULL, size INTEGER NOT NULL, seq INTEGER NOT NULL)')
    conn.commit()

def _split_escaped(text, delimiter):
    parts = []
    current = []
    escaped = False
    for ch in text:
        if escaped:
            current.append(ch)
            escaped = False
        elif ch == '\\':
            escaped = True
        elif ch == delimiter:
            parts.append(''.join(current))
            current = []
        else:
            current.append(ch)
    if escaped:
        raise ValueError('dangling escape')
    parts.append(''.join(current))
    return parts

def parse_metadata(text: str) -> dict:
    if not isinstance(text, str):
        raise TypeError('metadata must be text')
    result = {}
    if not text:
        return result
    for segment in _split_escaped(text, ';'):
        pair = _split_escaped(segment, '=')
        if len(pair) != 2:
            raise ValueError('metadata segment must contain one equals sign')
        key, value = (pair[0].strip(), pair[1].strip())
        if not key:
            raise ValueError('empty metadata key')
        result[key] = value
    return result

