        raise TypeError('text fields must be strings')
    if isinstance(size, bool) or not isinstance(size, int):
        raise TypeError('size must be an integer')
    if size < 0:
        raise ValueError('size must be non-negative')
    metadata = parse_metadata(metadata_text)
    ensure_schema(conn)
    conn.execute('INSERT INTO documents(id,title,metadata,size,seq) VALUES(?,?,?,?,COALESCE((SELECT MAX(seq)+1 FROM documents),0)) ON CONFLICT(id) DO UPDATE SET title=excluded.title, metadata=excluded.metadata, size=excluded.size', (doc_id, title, metadata_text, size))
    conn.commit()
    return metadata

