import hashlib
import hmac
import json

def dispatch_summary(payload: bytes, digest: str, api_token: str, region: str | None=None, page: int=1, page_size: int=10) -> list[dict]:
    if not isinstance(digest, str) or not isinstance(api_token, str):
        raise ValueError('invalid digest or token')
    expected = hmac.new(api_token.encode('utf-8'), payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, digest):
        raise ValueError('invalid digest')
    if region is not None and (not isinstance(region, str)):
        raise ValueError('invalid region')
    if not isinstance(page, int) or page < 1 or (not isinstance(page_size, int)) or (not 1 <= page_size <= 100):
        raise ValueError('invalid pagination')
    try:
        document = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    if not isinstance(document, dict) or not isinstance(document.get('jobs'), list):
        raise ValueError('invalid jobs')
    seen = set()
    groups = {}
    for job in document['jobs']:
        if not isinstance(job, dict):
            raise ValueError('invalid job')
        required = ('id', 'technician', 'region', 'minutes', 'priority')
        if any((key not in job for key in required)):
            raise ValueError('invalid job')
        if not isinstance(job['id'], str) or not job['id'] or (not isinstance(job['technician'], str)) or (not job['technician']) or (not isinstance(job['region'], str)) or (not job['region']) or (not isinstance(job['minutes'], int)) or isinstance(job['minutes'], bool) or (job['minutes'] <= 0) or (not isinstance(job['priority'], int)) or isinstance(job['priority'], bool) or (not 1 <= job['priority'] <= 5) or (job['id'] in seen):
            raise ValueError('invalid job')
        seen.add(job['id'])
        if region is not None and job['region'] != region:
            continue
        name = job['technician']
        if name not in groups:
            groups[name] = {'technician': name, 'job_count': 0, 'total_minutes': 0, 'highest_priority': 0}
        group = groups[name]
        group['job_count'] += 1
        group['total_minutes'] += job['minutes']
        group['highest_priority'] = max(group['highest_priority'], job['priority'])
    result = list(groups.values())
    for group in result:
        group['average_minutes'] = round(group['total_minutes'] / group['job_count'], 2)
    result.sort(key=lambda item: (-item['total_minutes'], item['technician']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

