    direction = 'DESC' if descending else 'ASC'
    clauses, params = ([], [])
    if precinct is not None:
        clauses.append('c.precinct = ?')
        params.append(precinct)
    if search:
        clauses.append('lower(c.name) LIKE lower(?)')
        params.append('%' + search + '%')
    where = ' WHERE ' + ' AND '.join(clauses) if clauses else ''
    query = f'SELECT c.id, c.name, c.office, c.precinct, COUNT(b.candidate_id) AS votes FROM candidates c LEFT JOIN ballots b ON b.candidate_id = c.id{where} GROUP BY c.id, c.name, c.office, c.precinct ORDER BY {order} {direction}, c.name ASC, c.id ASC LIMIT ? OFFSET ?'
    params.extend([limit, offset])
    return [dict(row) for row in conn.execute(query, params).fetchall()]

