from solution import CampaignLog

def test_constructor_and_validation():
    log = CampaignLog('  Moonfall  ')
    assert log.totals() == {}
    for args in [('', 'A', 'xp', 1), ('x', '', 'xp', 1), ('x', 'A', 'bad', 1), ('x', 'A', 'xp', -1), ('x', 'A', 'xp', True)]:
        try:
            CampaignLog(*args) if len(args) == 1 else None
        except Exception:
            pass
    for bad in ['', '   ', 4, None]:
        try:
            CampaignLog(bad)
            assert False
        except ValueError:
            pass

def test_record_and_totals_are_aggregated_and_copied():
    log = CampaignLog('Moonfall')
    log.record(2, ' Aria ', 'xp', 10)
    log.record(1, 'Borin', 'gold', 7)
    log.record(3, 'Aria', 'damage', 4)
    log.record(4, 'Borin', 'xp', 2)
    assert log.totals() == {'Aria': {'xp': 10, 'gold': 0, 'damage': 4}, 'Borin': {'xp': 2, 'gold': 7, 'damage': 0}}
    snapshot = log.totals()
    snapshot['Aria']['xp'] = 999
    snapshot['new'] = {'xp': 1, 'gold': 1, 'damage': 1}
    assert log.totals()['Aria']['xp'] == 10
    assert 'new' not in log.totals()

def test_record_rejects_bad_values_without_partial_changes():
    log = CampaignLog('x')
    log.record(0, 'A', 'xp', 5)
    bad_records = [(-1, 'B', 'xp', 1), (1, 'B', 'xp', True), (1, ' ', 'xp', 1), (1, 'B', 'mana', 1), (1, 'B', 'gold', -2)]
    for item in bad_records:
        try:
            log.record(*item)
            assert False
        except ValueError:
            pass
    assert log.totals() == {'A': {'xp': 5, 'gold': 0, 'damage': 0}}

def test_leaderboard_ties_use_name_and_zero_records_are_present():
    log = CampaignLog('x')
    log.record(3, 'Charlie', 'damage', 0)
    log.record(1, 'Alice', 'gold', 0)
    log.record(2, 'Bob', 'xp', 0)
    assert log.leaderboard() == [('Alice', 0, 0, 0), ('Bob', 0, 0, 0), ('Charlie', 0, 0, 0)]

def test_invite_codes_format_length_and_validation():
    log = CampaignLog('x')
    codes = [log.invite_code() for _ in range(40)]
    assert all((len(code) == 12 for code in codes))
    assert all((all((ch in 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789' for ch in code)) for code in codes))
    assert len(set(codes)) == len(codes)
    assert len(log.invite_code(8)) == 8
    assert len(log.invite_code(32)) == 32
    for length in [7, 33, 4.0, True, '12']:
        try:
            log.invite_code(length)
            assert False
        except ValueError:
            pass

