import os
import zipfile

def extract_recovery_bundle(archive_path: str, destination: str, selected: list[str] | None=None) -> list[str]:
    os.makedirs(destination, exist_ok=True)
    base = os.path.realpath(destination)
    wanted = None if selected is None else set(selected)
    result = []
    with zipfile.ZipFile(archive_path) as archive:
        for info in archive.infolist():
            name = info.filename
            if wanted is not None and name not in wanted:
                continue
            target = os.path.realpath(os.path.join(base, name))
            if os.path.commonpath([base, target]) != base:
                raise ValueError('member outside destination')
            if info.is_dir():
                os.makedirs(target, exist_ok=True)
                continue
            os.makedirs(os.path.dirname(target), exist_ok=True)
            with archive.open(info) as source, open(target, 'wb') as dest:
                dest.write(source.read())
            result.append(name)
    return sorted(result)

def _split_fields(line):
    fields, current = ([], [])
    escaped = False
    for ch in line:
        if escaped:
            if ch not in '\\|':
                raise ValueError('invalid escape')
            current.append(ch)
            escaped = False
        elif ch == '\\':
            escaped = True
        elif ch == '|':
            fields.append(''.join(current))
