import hashlib
import hmac
import json

def process_expense_webhook(body: str, signature: str, secret: str, page: int=1, page_size: int=10) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    expected = hmac.new(secret.encode('utf-8'), body.encode('utf-8'), hashlib.sha256).hexdigest()
    if not isinstance(signature, str) or not hmac.compare_digest(expected, signature):
        raise PermissionError('invalid signature')
    try:
        document = json.loads(body)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid JSON') from exc
    if not isinstance(document, dict) or not isinstance(document.get('expenses'), list):
        raise ValueError('invalid expenses')
    seen = set()
    groups = {}
    for item in document['expenses']:
        if not isinstance(item, dict):
            raise ValueError('invalid expense')
        if set(item) != {'id', 'employee', 'amount_cents', 'status'}:
            raise ValueError('invalid expense fields')
        ident = item['id']
        employee = item['employee']
        amount = item['amount_cents']
        status = item['status']
        if not isinstance(ident, str) or not ident or ident in seen:
            raise ValueError('invalid id')
        if not isinstance(employee, str) or not employee:
            raise ValueError('invalid employee')
        if not isinstance(amount, int) or isinstance(amount, bool) or amount < 0:
            raise ValueError('invalid amount')
        if status not in {'approved', 'pending', 'rejected'}:
            raise ValueError('invalid status')
        seen.add(ident)
        if status == 'approved':
            if employee not in groups:
                groups[employee] = {'employee': employee, 'total_cents': 0, 'count': 0}
            groups[employee]['total_cents'] += amount
            groups[employee]['count'] += 1
    ordered = sorted(groups.values(), key=lambda x: (-x['total_cents'], x['employee']))
    start = (page - 1) * page_size
    return {'page': page, 'page_size': page_size, 'total_employees': len(ordered), 'employees': ordered[start:start + page_size]}

