import base64
import hashlib
import hmac
import os

def hash_access_code(code: str) -> str:
    if not isinstance(code, str):
        raise TypeError('code must be a string')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', code.encode(), salt, 100000)
    return base64.b64encode(salt).decode() + '$' + base64.b64encode(digest).decode()

def verify_access_code(code: str, stored: str) -> bool:
    if not isinstance(code, str):
        raise TypeError('code must be a string')
    try:
        salt_text, digest_text = stored.split('$', 1)
        salt = base64.b64decode(salt_text.encode(), validate=True)
        expected = base64.b64decode(digest_text.encode(), validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', code.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (AttributeError, ValueError, TypeError):
        return False

def summarize_findings(findings: list[dict], severity: str | None=None, page: int=1, page_size: int=3) -> dict:
    levels = ['critical', 'high', 'medium', 'low']
    if not isinstance(findings, list):
        raise ValueError('findings must be a list')
    if severity is not None and severity not in levels:
        raise ValueError('invalid severity')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError('invalid page size')
    required = {'id', 'title', 'severity', 'status', 'effort'}
    for item in findings:
        if not isinstance(item, dict) or not required.issubset(item) or item['severity'] not in levels or (not isinstance(item['effort'], (int, float))) or isinstance(item['effort'], bool) or (item['effort'] < 0):
            raise ValueError('invalid finding')
    selected = [x for x in findings if severity is None or x['severity'] == severity]
    counts = {level: sum((x['severity'] == level for x in selected)) for level in levels}
    ordered = sorted(selected, key=lambda x: (levels.index(x['severity']), x['id']))
    start = (page - 1) * page_size
    average = round(sum((x['effort'] for x in selected)) / len(selected), 2) if selected else 0.0
    return {'total': len(selected), 'by_severity': counts, 'average_effort': average, 'items': ordered[start:start + page_size]}

