import json
import math
import os

def _path(base_dir, relative_name):
    base = os.path.realpath(base_dir)
    candidate = os.path.realpath(os.path.join(base, relative_name))
    if candidate != base and (not candidate.startswith(base + os.sep)):
        raise ValueError('invalid path')
    return candidate

def read_event_log(base_dir: str, relative_name: str) -> list[dict]:
    path = _path(base_dir, relative_name)
    try:
        handle = open(path, 'r', encoding='utf-8')
    except (OSError, UnicodeError) as exc:
        raise ValueError('cannot read log') from exc
    result = []
    with handle:
        for number, line in enumerate(handle, 1):
            if not line.strip():
                continue
            try:
                item = json.loads(line)
                if not isinstance(item, dict):
                    raise ValueError
                user = item['user']
                feature = item['feature']
                ts = item['ts']
                duration = item['duration']
                if not isinstance(user, str) or not user or (not isinstance(feature, str)) or (not feature) or isinstance(ts, bool) or (not isinstance(ts, (int, float))) or (not math.isfinite(ts)) or isinstance(duration, bool) or (not isinstance(duration, (int, float))) or (not math.isfinite(duration)) or (duration < 0):
                    raise ValueError
            except (KeyError, TypeError, ValueError, json.JSONDecodeError) as exc:
                raise ValueError('invalid record on line ' + str(number)) from exc
            result.append(item)
    return result

def summarize_events(events: list[dict], window_seconds: int=300) -> dict:
    if isinstance(window_seconds, bool) or not isinstance(window_seconds, int) or window_seconds <= 0:
        raise ValueError('invalid window')
    features = {}
    users = {}
    pairs = {}
    total = 0.0
    for event in events:
        user, feature = (event['user'], event['feature'])
        duration = event['duration']
        total += duration
        features.setdefault(feature, {'events': 0, 'users': set(), 'duration': 0.0})
        features[feature]['events'] += 1
        features[feature]['users'].add(user)
        features[feature]['duration'] += duration
        users.setdefault(user, {'events': 0, 'features': set(), 'duration': 0.0})
        users[user]['events'] += 1
        users[user]['features'].add(feature)
        users[user]['duration'] += duration
        pairs.setdefault((user, feature), []).append(event['ts'])
    sessions = {key: sum((1 for i, ts in enumerate(sorted(values)) if i == 0 or ts - sorted(values)[i - 1] > window_seconds)) for key, values in pairs.items()}
    out_features = {}
    for name in sorted(features):
        item = features[name]
        out_features[name] = {'events': item['events'], 'users': sorted(item['users']), 'duration': round(item['duration'], 3), 'sessions': sum((sessions[u, name] for u in item['users']))}
    out_users = {name: {'events': item['events'], 'features': sorted(item['features']), 'duration': round(item['duration'], 3)} for name, item in sorted(users.items())}
    return {'total_events': len(events), 'total_duration': round(total, 3), 'features': out_features, 'users': out_users}

def build_usage_report(base_dir: str, relative_name: str, window_seconds: int=300) -> dict:
    return summarize_events(read_event_log(base_dir, relative_name), window_seconds)

