import hashlib
import hmac
SIGNING_KEY = b'coupon-batch-key-v1'

def validate_coupons(batch: str, customer_id: str, cart_total_cents: int, now: int, signature: str) -> list[dict]:
    expected = hmac.new(SIGNING_KEY, batch.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(signature, expected):
        return []
    if not customer_id or cart_total_cents < 0 or now < 0:
        raise ValueError('invalid arguments')
    records = []
    for line in batch.splitlines():
        if not line.strip():
            continue
        fields = line.split('|')
        if len(fields) != 6:
            raise ValueError('invalid coupon')
        code, category, percent_text, minimum_text, expiry_text, customer_text = fields
        if not code or not category or (not customer_text):
            raise ValueError('invalid coupon')
        try:
            percent = int(percent_text)
            minimum = int(minimum_text)
            expires = int(expiry_text)
        except ValueError as exc:
            raise ValueError('invalid coupon') from exc
        if not 1 <= percent <= 100 or minimum < 0 or expires < 0:
            raise ValueError('invalid coupon')
        if customer_text == '*':
            customers = []
            applies = True
        else:
            customers = customer_text.split(',')
            if any((not item for item in customers)):
                raise ValueError('invalid coupon')
            applies = customer_id in customers
        if applies and cart_total_cents >= minimum and (expires >= now):
            records.append({'code': code, 'category': category, 'discount_percent': percent, 'minimum_cents': minimum, 'expires_at': expires, 'customers': customers})
    records.sort(key=lambda item: (-item['discount_percent'], item['expires_at'], item['code']))
    return records

