def parse_booking_lines(lines):
    result = []
    for raw in lines:
        if not raw.strip():
            continue
        fields = []
        current = []
        i = 0
        while i < len(raw):
            if raw[i] == '|':
                if i + 1 < len(raw) and raw[i + 1] == '|':
                    current.append('|')
                    i += 2
                    continue
                fields.append(''.join(current))
                current = []
            else:
                current.append(raw[i])
            i += 1
        fields.append(''.join(current))
        if len(fields) != 5:
            raise ValueError('invalid booking line')
        member, equipment, start, end, notes = fields
        member, equipment = (member.strip(), equipment.strip())
        if not member or not equipment:
            raise ValueError('empty booking field')
        start, end = (_timestamp(start.strip()), _timestamp(end.strip()))
        if end <= start:
            raise ValueError('invalid booking range')
        if notes.startswith(' '):
            notes = notes[1:]
        if notes.endswith(' '):
            notes = notes[:-1]
        result.append({'member': member, 'equipment': equipment, 'start': start, 'end': end, 'notes': notes})
    return result

def export_booking_report(records, destination):
    prepared = []
    for record in records:
        member = record.get('member')
        equipment = record.get('equipment')
        if not isinstance(member, str) or not member.strip() or (not isinstance(equipment, str)) or (not equipment.strip()):
            raise ValueError('invalid booking')
        start, end = (_timestamp(record.get('start')), _timestamp(record.get('end')))
        if end <= start:
            raise ValueError('invalid booking range')
        prepared.append((member, equipment, start, end, record.get('notes', '')))
    prepared.sort(key=lambda x: (x[1], x[2], x[3], x[0]))
    rows = [['member', 'equipment', 'start', 'end', 'duration_minutes', 'conflict', 'notes']]
    latest = {}
    for member, equipment, start, end, notes in prepared:
        conflict = equipment in latest and start < latest[equipment]
        latest[equipment] = max(latest.get(equipment, start), end)
        rows.append([member, equipment, start.strftime('%Y-%m-%dT%H:%M'), end.strftime('%Y-%m-%dT%H:%M'), str(int((end - start).total_seconds() // 60)), 'yes' if conflict else 'no', str(notes)])
    directory = os.path.dirname(os.path.abspath(destination))
    temporary = tempfile.mktemp(dir=directory)
    try:
        with open(temporary, 'w', encoding='utf-8', newline='') as stream:
            csv.writer(stream, lineterminator='\n').writerows(rows)
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except OSError:
            pass
        raise
    return len(prepared)

