import ast

def _evaluate(node, values):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in values:
            raise ValueError('unknown name')
        return values[node.id]
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
        value = _evaluate(node.operand, values)
        if isinstance(node.op, ast.UAdd):
            return +value
        if isinstance(node.op, ast.USub):
            return -value
        return not value
    if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
        left = _evaluate(node.left, values)
        right = _evaluate(node.right, values)
        if isinstance(node.op, ast.Add):
            return left + right
        if isinstance(node.op, ast.Sub):
            return left - right
        if isinstance(node.op, ast.Mult):
            return left * right
        return left / right
    if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
        result = _evaluate(node.values[0], values)
        for child in node.values[1:]:
            if isinstance(node.op, ast.And):
                if not result:
                    return result
            elif result:
                return result
            result = _evaluate(child, values)
        return result
    if isinstance(node, ast.Compare):
        left = _evaluate(node.left, values)
        for operation, comparator in zip(node.ops, node.comparators):
            right = _evaluate(comparator, values)
            if isinstance(operation, ast.Lt):
                ok = left < right
            elif isinstance(operation, ast.LtE):
                ok = left <= right
            elif isinstance(operation, ast.Gt):
                ok = left > right
            elif isinstance(operation, ast.GtE):
                ok = left >= right
            elif isinstance(operation, ast.Eq):
                ok = left == right
            elif isinstance(operation, ast.NotEq):
                ok = left != right
            else:
                raise ValueError('unsupported comparison')
            if not ok:
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
        args = [_evaluate(arg, values) for arg in node.args]
        return {'min': min, 'max': max, 'round': round}[node.func.id](*args)
    raise ValueError('unsupported expression')

def _condition(expression, values):
    try:
        tree = ast.parse(expression, mode='eval')
        return _evaluate(tree.body, values)
    except ValueError:
        raise
    except Exception as exc:
        raise ValueError('invalid expression') from exc

def schedule_jobs(jobs: list[dict], eligibility: str, capacity: int) -> list[dict]:
    if capacity < 0:
        raise ValueError('capacity must not be negative')
    eligible = []
    for index, job in enumerate(jobs):
        values = {name: job[name] for name in ('duration', 'priority', 'due_day', 'quantity')}
        if _condition(eligibility, values):
            eligible.append((job, index))
    eligible.sort(key=lambda item: (item[0]['due_day'], -item[0]['priority'], item[0]['id'], item[1]))
    result = []
    used = 0
    for job, _ in eligible:
        if used + job['duration'] <= capacity:
            result.append(dict(job))
            used += job['duration']
    return result

