import math
import xml.etree.ElementTree as ET

def _number(value):
    try:
        number = float(value)
    except (TypeError, ValueError):
        raise ValueError('invalid number')
    if not math.isfinite(number):
        raise ValueError('non-finite number')
    return number

def parse_scan(xml_text: str) -> dict:
    if not isinstance(xml_text, str):
        raise TypeError('xml_text must be a string')
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'scan':
        raise ValueError('invalid root')
    values = {}
    for key in ('id', 'sensor', 'captured'):
        value = root.get(key)
        if value is None or value == '':
            raise ValueError('missing scan attribute')
        values[key] = value
    points = []
    for node in root:
        if node.tag != 'point':
            continue
        point = {}
        for key in ('x', 'y', 'z', 'intensity', 'time'):
            if node.get(key) is None:
                raise ValueError('missing point attribute')
            point[key] = _number(node.get(key))
        points.append(point)
    values['points'] = points
    return values

def summarize_scans(xml_documents: list[str], window: float=1.0) -> list[dict]:
    if not isinstance(window, (int, float)):
        raise TypeError('window must be numeric')
    if not math.isfinite(window) or window <= 0:
        raise ValueError('invalid window')
    summaries = []
    for position, document in enumerate(xml_documents):
        scan = parse_scan(document)
        groups = {}
        for point in scan['points']:
            index = math.floor(point['time'] / window)
            groups.setdefault(index, []).append(point)
        windows = []
        for index in sorted(groups):
            group = groups[index]
            count = len(group)
            windows.append({'index': index, 'start': index * window, 'count': count, 'centroid': {key: sum((p[key] for p in group)) / count for key in ('x', 'y', 'z')}, 'mean_intensity': sum((p['intensity'] for p in group)) / count})
        summaries.append({'id': scan['id'], 'sensor': scan['sensor'], 'captured': scan['captured'], 'windows': windows, '_position': position})
    summaries.sort(key=lambda item: (item['captured'], item['id'], item['_position']))
    for item in summaries:
        del item['_position']
    return summaries

