def write_file(directory, name, lines):
    path = os.path.join(directory, name)
    with open(path, "w", encoding="utf-8") as handle:
        handle.write("\n".join("line" for _ in range(lines)))
        if lines:
            handle.write("\n")
    return path


def test_empty_input():
    assert summarize_daily_reports([]) == {
        "total_files": 0,
        "total_lines": 0,
        "page": 1,
        "page_size": 10,
        "items": [],
    }


def test_counts_and_shooting_day_rounding():
    with tempfile.TemporaryDirectory() as directory:
        first = write_file(directory, "morning.txt", 40)
        second = write_file(directory, "afternoon.txt", 41)
        result = summarize_daily_reports([first, second])
        assert result["total_files"] == 2
        assert result["total_lines"] == 81
        assert result["items"] == [
            {"name": "afternoon.txt", "lines": 41, "shooting_days": 2},
            {"name": "morning.txt", "lines": 40, "shooting_days": 1},
        ]


