    with tempfile.TemporaryDirectory() as directory:
        zulu = write_file(directory, "zulu.txt", 12)
        alpha = write_file(directory, "alpha.txt", 12)
        small = write_file(directory, "small.txt", 11)
        result = summarize_daily_reports([zulu, small, alpha], minimum_lines=12)
        assert result["total_files"] == 2
        assert result["total_lines"] == 24
        assert [item["name"] for item in result["items"]] == ["alpha.txt", "zulu.txt"]


def test_pagination_is_applied_after_sorting():
    with tempfile.TemporaryDirectory() as directory:
        paths = [write_file(directory, name, lines) for name, lines in [
