import datetime
import hashlib
import hmac
import json

def process_payment_webhook(payload: bytes, signature: str, signing_key: bytes, page: int=1, page_size: int=10) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    expected = hmac.new(signing_key, payload, hashlib.sha256).hexdigest()
    if not isinstance(signature, str) or not signature.startswith('sha256=') or len(signature) != 71:
        raise PermissionError('invalid signature')
    supplied = signature[7:]
    if any((c not in '0123456789abcdef' for c in supplied)) or not hmac.compare_digest(supplied, expected):
        raise PermissionError('invalid signature')
    try:
        data = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(data, dict) or not isinstance(data.get('payments'), list):
        raise ValueError('invalid payments')
    totals = {}
    for payment in data['payments']:
        if not isinstance(payment, dict):
            raise ValueError('invalid payment')
        loan_id = payment.get('loan_id')
        amount = payment.get('amount_cents')
        status = payment.get('status')
        received = payment.get('received_at')
        if not isinstance(loan_id, str) or not loan_id or isinstance(amount, bool) or (not isinstance(amount, int)) or (amount < 0) or (status not in {'posted', 'pending', 'reversed'}) or (not isinstance(received, str)):
            raise ValueError('invalid payment')
        try:
            datetime.date.fromisoformat(received)
        except ValueError as exc:
            raise ValueError('invalid date') from exc
        if status == 'posted':
            total, count = totals.get(loan_id, (0, 0))
            totals[loan_id] = (total + amount, count + 1)
    rows = [{'loan_id': k, 'total_cents': v[0], 'payment_count': v[1]} for k, v in totals.items()]
    rows.sort(key=lambda row: (-row['total_cents'], row['loan_id']))
    start = (page - 1) * page_size
    return {'page': page, 'page_size': page_size, 'total_loans': len(rows), 'loans': rows[start:start + page_size]}

