        return float(Decimal(str(value)).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
    approved = [dict(x) for x in records if x['status'] == 'approved']
    for item in approved:
        item['requested_amount'] = money(item['requested_amount'])
        item['approved_amount'] = money(item['approved_amount'])
    approved.sort(key=lambda x: (-x['approved_amount'], x['id']))
    groups = {}
    for item in approved:
        entry = groups.setdefault(item['county'], [0, 0.0])
        entry[0] += 1
        entry[1] += item['approved_amount']
    county_totals = [{'county': county, 'count': values[0], 'approved_amount': money(values[1])} for county, values in groups.items()]
    county_totals.sort(key=lambda x: (-x['approved_amount'], x['county']))
    start = (page - 1) * page_size
    return {'total': len(approved), 'page': page, 'page_size': page_size, 'applications': approved[start:start + page_size], 'county_totals': county_totals}

