import json
import os

def make_feed_credential(secret: str) -> str:
    if not isinstance(secret, str):
        raise TypeError('secret must be a string')
    if not secret.strip():
        raise ValueError('secret must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def check_feed_credential(stored: str, secret: str) -> bool:
    if not isinstance(stored, str) or not isinstance(secret, str):
        return False
    try:
        salt_text, digest_text = stored.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def syndicate_listings(stored: str, secret: str, listings: list[dict]) -> str:
    if not check_feed_credential(stored, secret):
        raise PermissionError('invalid feed credential')
    if not isinstance(listings, list) or any((not isinstance(item, dict) for item in listings)):
        raise TypeError('listings must be a list of dictionaries')
    return json.dumps(listings, separators=(',', ':'), sort_keys=True)

