import csv
import datetime
import subprocess

def build_class_report(roster_path: str, attendance_path: str, start_date: str, end_date: str) -> list[dict]:
    try:
        begin = datetime.date.fromisoformat(start_date)
        finish = datetime.date.fromisoformat(end_date)
    except ValueError:
        raise ValueError('invalid date')
    if begin > finish:
        raise ValueError('reversed range')
    proc = subprocess.run(['sort', '-t,', '-k2,2', roster_path], capture_output=True, text=True, check=True)
    roster = {}
    classes = {}
    for row in csv.reader(proc.stdout.splitlines()):
        if len(row) != 3 or any((not x for x in row)):
            raise ValueError('bad roster record')
        sid, code, name = row
        if sid in roster or sid in classes:
            raise ValueError('duplicate student')
        roster[sid] = (code, name)
        classes.setdefault(code, []).append(sid)
    events = {}
    seen = set()
    with open(attendance_path, encoding='utf-8', newline='') as f:
        for row in csv.reader(f):
            if len(row) != 4 or any((not x for x in row)):
                raise ValueError('bad attendance record')
            date_text, code, sid, status = row
            try:
                date = datetime.date.fromisoformat(date_text)
            except ValueError:
                raise ValueError('invalid attendance date')
            if sid not in roster or roster[sid][0] != code or status not in 'PAL':
                raise ValueError('invalid attendance')
            if begin <= date <= finish:
                key = (code, sid, date)
                if key in seen:
                    raise ValueError('duplicate attendance')
                seen.add(key)
                events.setdefault(code, []).append((sid, date, status))
    result = []
    for code in sorted(classes):
        rows = events.get(code, [])
        dates = {x[1] for x in rows}
        totals = {'P': 0, 'A': 0, 'L': 0}
        per = {sid: {'P': 0, 'A': 0, 'L': 0} for sid in classes[code]}
        for sid, _, status in rows:
            totals[status] += 1
            per[sid][status] += 1
        sessions = len(dates)
        denom = len(classes[code]) * sessions
        students = []
        for sid in sorted(classes[code], key=lambda x: (roster[x][1].casefold(), x)):
            p = per[sid]
            students.append({'student_id': sid, 'student_name': roster[sid][1], 'present': p['P'], 'excused': p['L'], 'absent': p['A'], 'attendance_rate': (p['P'] + p['L']) / sessions if sessions else 0.0})
        result.append({'class_code': code, 'enrolled': len(classes[code]), 'sessions': sessions, 'present': totals['P'], 'excused': totals['L'], 'absent': totals['A'], 'attendance_rate': (totals['P'] + totals['L']) / denom if denom else 0.0, 'students': students})
    return result

