from collections.abc import Mapping

def build_fleet_report(records: list[dict], config: dict[str, str] | None=None) -> dict:
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    grouped = {}
    for record in records:
        if not isinstance(record, dict):
            raise TypeError('each record must be a dictionary')
        device_id = record.get('device_id')
        timestamp = record.get('timestamp')
        speed = record.get('speed_kmh')
        if not isinstance(device_id, str):
            raise TypeError('device_id must be a string')
        if not isinstance(timestamp, (int, float)) or isinstance(timestamp, bool):
            raise TypeError('timestamp must be numeric')
        if not isinstance(speed, (int, float)) or isinstance(speed, bool):
            raise TypeError('speed_kmh must be numeric')
        if not device_id:
            raise ValueError('device_id must not be empty')
        if timestamp < 0:
            raise ValueError('timestamp must not be negative')
        if speed < 0:
            raise ValueError('speed_kmh must not be negative')
        grouped.setdefault(device_id, []).append((timestamp, speed))
    devices = []
    for device_id in sorted(grouped):
        values = grouped[device_id]
        timestamps = [item[0] for item in values]
        speeds = [item[1] for item in values]
        devices.append({'device_id': device_id, 'record_count': len(values), 'average_speed_kmh': round(sum(speeds) / len(speeds), 2), 'max_speed_kmh': max(speeds), 'first_timestamp': min(timestamps), 'last_timestamp': max(timestamps)})
    report = {'devices': devices, 'record_count': len(records)}
    if config is not None and 'telemetry_signing_key' in config:
        key = config['telemetry_signing_key']
    else:
        key = os.environ.get('FLEET_TELEMETRY_KEY')
    if not key:
        raise ValueError('telemetry signing key is required')
    payload = json.dumps(report, sort_keys=True, separators=(',', ':')).encode('utf-8')
    report['signature'] = hmac.new(key.encode('utf-8'), payload, hashlib.sha256).hexdigest()
    return report

