import os
import tempfile
import pytest


def write_records(text):
    fd, path = tempfile.mkstemp(prefix="deferment_", text=True)
    with os.fdopen(fd, "w", encoding="utf-8") as handle:
        handle.write(text)
    return path


def test_empty_file_returns_empty_summary():
    path = write_records("\n  \n")
    try:
        assert build_deferment_summary(path, "2025-01-01") == {"as_of": "2025-01-01", "loans": []}
    finally:
        os.unlink(path)


def test_groups_loans_and_sorts_them():
    path = write_records(
        "loanB|2025-02-01|2025-02-03|school|25\n"
        "loanA|2025-01-10|2025-01-10|school|100\n"
    )
    try:
        result = build_deferment_summary(path, "2025-02-02")
        assert result == {
            "as_of": "2025-02-02",
            "loans": [
                {"loan_id": "loanA", "days": 1, "amount_cents": 100, "active": False},
                {"loan_id": "loanB", "days": 2, "amount_cents": 25, "active": True},
            ],
        }
    finally:
        os.unlink(path)


