        "x|2025-01-01|2025-01-03|a|10\n"
        "x|2025-01-03|2025-01-05|b|20\n"
        "x|2025-01-07|2025-01-07|c|30\n"
        "x|2025-01-06|2025-01-06|d|40\n"
