def _parse_date(value):
    try:
        parsed = date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if parsed.isoformat() != value:
        raise ValueError('invalid date')
    return parsed

def build_deferment_summary(path: str, as_of: str) -> dict:
    cutoff = _parse_date(as_of)
    result = subprocess.run(['sort', '-t', '|', '-k1,1', '-k2,2', '-k3,3', path], check=True, capture_output=True, text=True)
    groups = {}
    for line in result.stdout.splitlines():
        if not line.strip():
            continue
        fields = line.split('|')
        if len(fields) != 5:
            raise ValueError('invalid record')
        loan, start_text, end_text, reason, amount_text = [x.strip() for x in fields]
        if not loan or not reason or (not amount_text.isdigit()):
            raise ValueError('invalid record')
        start = _parse_date(start_text)
        end = _parse_date(end_text)
        if start > end:
            raise ValueError('invalid interval')
        amount = int(amount_text)
        groups.setdefault(loan, []).append((start, end, amount))
    loans = []
