        intervals = sorted(((start, end) for start, end, _ in records))
        merged = []
        for start, end in intervals:
            if merged and start <= merged[-1][1].fromordinal(merged[-1][1].toordinal() + 1):
                if end > merged[-1][1]:
                    merged[-1] = (merged[-1][0], end)
            else:
                merged.append((start, end))
        days = 0
        for start, end in merged:
            if start <= cutoff:
                finish = min(end, cutoff)
                days += (finish - start).days + 1
        active = any((start <= cutoff <= end for start, end, _ in records))
        loans.append({'loan_id': loan, 'days': days, 'amount_cents': sum((r[2] for r in records)), 'active': active})
    return {'as_of': as_of, 'loans': loans}

