import operator

def build_replenishment_plan(items: list[dict], formula: str) -> list[dict]:
    tree = ast.parse(formula, mode='eval').body

    def ev(n, env):
        if isinstance(n, ast.Constant) and isinstance(n.value, (int, float, bool)):
            return n.value
        if isinstance(n, ast.Name):
            if n.id not in env:
                raise NameError(n.id)
            return env[n.id]
        if isinstance(n, ast.BinOp) and type(n.op) in {ast.Add, ast.Sub, ast.Mult, ast.Div}:
            return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(n.op)](ev(n.left, env), ev(n.right, env))
        if isinstance(n, ast.UnaryOp) and type(n.op) in {ast.UAdd, ast.USub, ast.Not}:
            return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(n.op)](ev(n.operand, env))
        if isinstance(n, ast.BoolOp):
            value = ev(n.values[0], env)
            for child in n.values[1:]:
                if isinstance(n.op, ast.And):
                    if not value:
                        return value
                elif value:
                    return value
                value = ev(child, env)
            return value
        if isinstance(n, ast.Compare):
            left = ev(n.left, env)
            for op, right_node in zip(n.ops, n.comparators):
                right = ev(right_node, env)
                if not {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and (n.func.id in {'min', 'max', 'round'}):
            return {'min': min, 'max': max, 'round': round}[n.func.id](*[ev(x, env) for x in n.args])
        raise ValueError('unsupported expression')
    result = []
    for item in items:
        env = {k: item[k] for k in ('stock', 'minimum', 'lead_days', 'unit_cost')}
        if item['stock'] < item['minimum']:
            result.append({'sku': item['sku'], 'order_qty': item['minimum'] - item['stock'], 'score': ev(tree, env)})
