            return node.value
        if isinstance(node, ast.Name) and node.id in ('duration', 'fee', 'urgent'):
            return item[node.id]
        if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub):
            return (operator.pos if isinstance(node.op, ast.UAdd) else operator.neg)(ev(node.operand, item))
        if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
            fn = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)]
            return fn(ev(node.left, item), ev(node.right, item))
        if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
            values = [ev(x, item) for x in node.values]
            return all(values) if isinstance(node.op, ast.And) else any(values)
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.Not):
            return not ev(node.operand, item)
        if isinstance(node, ast.Compare):
            left = ev(node.left, item)
            for op, right_node in zip(node.ops, node.comparators):
                right = ev(right_node, item)
                fn = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}.get(type(op))
                if fn is None or not fn(left, right):
