        try:
            value = ev(tree, item)
        except KeyError:
            raise ValueError('invalid rule')
        if type(value) is not bool:
            raise ValueError('rule must be boolean')
        if value:
            result.append(item)
    result.sort(key=lambda x: (x['start'], x['id']))
