import math
import re
import secrets

def generate_invite_code(supplier_id: str, length: int=12) -> str:
    if not isinstance(supplier_id, str) or not supplier_id or (not re.fullmatch('[A-Za-z0-9_-]+', supplier_id)):
        raise ValueError('invalid supplier_id')
    if isinstance(length, bool) or not isinstance(length, int) or (not 8 <= length <= 32):
        raise ValueError('invalid length')
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    return supplier_id + '-' + ''.join((secrets.choice(alphabet) for _ in range(length)))

def score_suppliers(records: list[dict], page: int=1, page_size: int=10) -> list[dict]:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError('invalid pagination')
    grouped = {}
    fields = ('shipments', 'late_shipments', 'units', 'defective_units', 'spend', 'budget')
    for record in records:
        if not isinstance(record, dict) or not isinstance(record.get('supplier'), str) or (not record['supplier']) or any((k not in record for k in fields)):
            raise ValueError('invalid record')
        values = {k: record[k] for k in fields}
        if any((isinstance(v, bool) or not isinstance(v, (int, float)) or (not math.isfinite(v)) or (v < 0) for v in values.values())):
            raise ValueError('invalid numeric value')
        if values['shipments'] <= 0 or values['units'] <= 0 or values['budget'] <= 0 or (values['late_shipments'] > values['shipments']) or (values['defective_units'] > values['units']):
            raise ValueError('invalid record')
        item = grouped.setdefault(record['supplier'], {k: 0 for k in fields})
        for key in fields:
            item[key] += values[key]
    result = []
    for supplier, item in grouped.items():
        score = 100 - 40 * item['late_shipments'] / item['shipments'] - 40 * item['defective_units'] / item['units'] - 20 * abs(item['spend'] - item['budget']) / item['budget']
        result.append(dict(supplier=supplier, **item, score=round(score, 2)))
    result.sort(key=lambda x: (-x['score'], x['supplier']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

