from datetime import datetime

def initialize_database(conn: sqlite3.Connection) -> None:
    conn.execute('CREATE TABLE IF NOT EXISTS fires (fire_id INTEGER PRIMARY KEY, region TEXT NOT NULL, observed_at TEXT NOT NULL, acres REAL NOT NULL, risk INTEGER NOT NULL)')
    conn.commit()

def _checked(fire_id, region, observed_at, acres, risk):
    if not isinstance(fire_id, int) or isinstance(fire_id, bool) or fire_id <= 0:
        raise ValueError('invalid fire_id')
    if not isinstance(region, str) or not region.strip():
        raise ValueError('invalid region')
    try:
        datetime.fromisoformat(observed_at)
    except (TypeError, ValueError):
        raise ValueError('invalid timestamp')
    if not isinstance(acres, (int, float)) or isinstance(acres, bool) or (not math.isfinite(acres)) or (acres < 0):
        raise ValueError('invalid acres')
    if not isinstance(risk, int) or isinstance(risk, bool) or (not 0 <= risk <= 100):
        raise ValueError('invalid risk')
    return (fire_id, region.strip(), observed_at, float(acres), risk)

def save_fire(conn, fire_id, region, observed_at, acres, risk):
    vals = _checked(fire_id, region, observed_at, acres, risk)
    conn.execute('INSERT OR REPLACE INTO fires(fire_id,region,observed_at,acres,risk) VALUES(?,?,?,?,?)', vals)
    conn.commit()
    return dict(zip(('fire_id', 'region', 'observed_at', 'acres', 'risk'), vals))

def _row(r):
    return dict(zip(('fire_id', 'region', 'observed_at', 'acres', 'risk'), r))

def risk_map(conn, region=None, min_risk=0, sort_by='risk', descending=False):
    if not isinstance(min_risk, int) or isinstance(min_risk, bool) or (not 0 <= min_risk <= 100):
        raise ValueError('invalid minimum risk')
    allowed = {'fire_id', 'region', 'observed_at', 'acres', 'risk'}
    if sort_by not in allowed:
        raise ValueError('invalid sort field')
    query = 'SELECT fire_id,region,observed_at,acres,risk FROM fires WHERE risk >= ?'
    args = [min_risk]
    if region is not None:
        query += ' AND region = ?'
        args.append(region)
    query += ' ORDER BY ' + sort_by + (' DESC' if descending else ' ASC') + ', fire_id ASC'
    return [_row(r) for r in conn.execute(query, args)]

def daily_burn_summary(conn, region=None):
    query = 'SELECT substr(observed_at,1,10), COUNT(*), SUM(acres), MAX(risk) FROM fires'
    args = []
    if region is not None:
        query += ' WHERE region = ?'
        args.append(region)
    query += ' GROUP BY substr(observed_at,1,10) ORDER BY substr(observed_at,1,10)'
    result = []
    for date, count, total, peak in conn.execute(query, args):
        total = round(total, 2)
        rolling = round(sum((x['total_acres'] for x in (result + [{'total_acres': total}])[-3:])), 2)
        result.append({'date': date, 'fire_count': count, 'total_acres': total, 'peak_risk': peak, 'rolling_acres': rolling})
    return result

