import ast

def _run(node, names):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, str, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in names:
            raise NameError(node.id)
        return names[node.id]
    if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
        a, b = (_run(node.left, names), _run(node.right, names))
        return {ast.Add: lambda: a + b, ast.Sub: lambda: a - b, ast.Mult: lambda: a * b, ast.Div: lambda: a / b}[type(node.op)]()
    if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.Not, ast.UAdd, ast.USub):
        v = _run(node.operand, names)
        return not v if isinstance(node.op, ast.Not) else +v if isinstance(node.op, ast.UAdd) else -v
    if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
        value = _run(node.values[0], names)
        for child in node.values[1:]:
            if isinstance(node.op, ast.And):
                if not value:
                    return value
            elif value:
                return value
            value = _run(child, names)
        return value
    if isinstance(node, ast.Compare):
        left = _run(node.left, names)
        for op, child in zip(node.ops, node.comparators):
            right = _run(child, names)
            if type(op) not in (ast.Lt, ast.LtE, ast.Eq, ast.NotEq, ast.Gt, ast.GtE):
                raise ValueError()
            ok = {ast.Lt: left < right, ast.LtE: left <= right, ast.Eq: left == right, ast.NotEq: left != right, ast.Gt: left > right, ast.GtE: left >= right}[type(op)]
            if not ok:
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
        return {'min': min, 'max': max, 'round': round}[node.func.id](*[_run(x, names) for x in node.args])
    raise ValueError()

def evaluate_rule(expression: str, values: dict[str, object]) -> object:
    try:
        tree = ast.parse(expression, mode='eval').body
        return _run(tree, dict(values))
    except NameError:
        raise
    except (SyntaxError, TypeError, ValueError):
        raise ValueError()

def _selected(scenes, rule, variables):
    out = []
    for scene in scenes:
        names = dict(scene)
        names.update(variables)
        if evaluate_rule(rule, names):
            out.append(scene)
    return sorted(out, key=lambda s: (s['date'], s['start'], -s['priority'], s['id']))

def build_call_sheet(scenes: list[dict], rule: str, variables: dict[str, object]) -> list[dict]:
    keys = ('id', 'date', 'start', 'duration', 'location', 'pages', 'cast', 'priority')
    return [{k: scene[k] for k in keys} for scene in _selected(scenes, rule, variables)]

def daily_summary(scenes: list[dict], rule: str, variables: dict[str, object]) -> dict[str, dict]:
    result = {}
    for scene in _selected(scenes, rule, variables):
        day = result.setdefault(scene['date'], {'scene_count': 0, 'total_duration': 0, 'total_pages': 0, 'locations': [], 'cast': []})
        day['scene_count'] += 1
        day['total_duration'] += scene['duration']
        day['total_pages'] += scene['pages']
        if scene['location'] not in day['locations']:
            day['locations'].append(scene['location'])
        for person in scene['cast']:
            if person not in day['cast']:
                day['cast'].append(person)
    return result

