import subprocess

def parse_ticket_line(line: str) -> dict:
    fields = line[:-1] if line.endswith('\n') else line
    parts = fields.split('\t')
    if len(parts) != 6:
        raise ValueError('invalid ticket record')
    ticket_id, queue, priority, age_days, status, tag_text = parts
    if not ticket_id or not queue or (not priority) or (not age_days) or (not status):
        raise ValueError('invalid ticket record')
    try:
        priority_number = int(priority, 10)
        age_number = int(age_days, 10)
    except ValueError as exc:
        raise ValueError('invalid ticket record') from exc
    if not 1 <= priority_number <= 5 or age_number < 0 or status not in ('open', 'closed'):
        raise ValueError('invalid ticket record')
    return {'id': ticket_id, 'queue': queue, 'priority': priority_number, 'age_days': age_number, 'status': status, 'tags': [] if not tag_text else tag_text.split(',')}

def rank_ticket_queues(tickets: list[dict], queue_weights: dict[str, int]) -> list[dict]:
    groups = {}
    for ticket in tickets:
        if ticket['status'] != 'open':
            continue
        queue = ticket['queue']
        if queue not in groups:
            groups[queue] = {'queue': queue, 'count': 0, 'urgency': 0, 'oldest_age': 0, 'tags': set()}
        group = groups[queue]
        group['count'] += 1
        group['urgency'] += ticket['priority'] * queue_weights.get(queue, 1)
        group['oldest_age'] = max(group['oldest_age'], ticket['age_days'])
        group['tags'].update(ticket['tags'])
    result = []
    for group in groups.values():
        result.append({'queue': group['queue'], 'count': group['count'], 'urgency': group['urgency'], 'oldest_age': group['oldest_age'], 'tags': sorted(group['tags'])})
    result.sort(key=lambda x: (-x['urgency'], -x['count'], x['oldest_age'], x['queue']))
    return result

def triage_ticket_file(path: str, pattern: str, limit: int, queue_weights: dict[str, int]) -> list[dict]:
    if limit < 0:
        raise ValueError('negative limit')
    if limit == 0:
        return []
    completed = subprocess.run(['grep', '-E', pattern, path], capture_output=True, text=True)
    if completed.returncode not in (0, 1):
        if completed.returncode == 2:
            raise OSError(completed.stderr.strip() or 'grep failed')
        raise OSError('grep failed')
    tickets = [parse_ticket_line(line) for line in completed.stdout.splitlines()]
    return rank_ticket_queues(tickets, queue_weights)[:limit]

