import csv
import datetime
import os
import tempfile
from collections.abc import Mapping

def export_points_csv(transactions: list[dict[str, object]], output_path: str, start_date: str | None=None, end_date: str | None=None) -> dict[str, int]:

    def parse_date(value: object) -> datetime.date:
        if not isinstance(value, str):
            raise ValueError('invalid date')
        try:
            parsed = datetime.datetime.strptime(value, '%Y-%m-%d').date()
        except ValueError as exc:
            raise ValueError('invalid date') from exc
        if parsed.isoformat() != value:
            raise ValueError('invalid date')
        return parsed
    first = parse_date(start_date) if start_date is not None else None
    last = parse_date(end_date) if end_date is not None else None
    if first is not None and last is not None and (first > last):
        raise ValueError('invalid range')
    totals: dict[str, list[int]] = {}
    for transaction in transactions:
        if not isinstance(transaction, Mapping):
            raise ValueError('invalid record')
        if 'member_id' not in transaction or 'points' not in transaction or 'date' not in transaction:
            raise ValueError('invalid record')
        member = transaction['member_id']
        points = transaction['points']
        if not isinstance(member, str) or not member or (not isinstance(points, int)) or isinstance(points, bool):
            raise ValueError('invalid record')
        date = parse_date(transaction['date'])
        if first is not None and date < first or (last is not None and date > last):
            continue
        if member not in totals:
            totals[member] = [0, 0]
        totals[member][0] += points
        totals[member][1] += 1
    ordered = {member: totals[member][0] for member in sorted(totals)}
    directory = os.path.dirname(os.path.abspath(output_path))
    fd, temporary_path = tempfile.mkstemp(suffix='.csv', dir=directory)
    os.close(fd)
    try:
        with open(temporary_path, 'w', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['member_id', 'total_points', 'transactions'])
            for member in sorted(totals):
                writer.writerow([member, totals[member][0], totals[member][1]])
        os.replace(temporary_path, output_path)
    finally:
        if os.path.exists(temporary_path):
            os.unlink(temporary_path)
    return ordered

