            result = subprocess.run('cat ' + path, shell=True, check=True, capture_output=True, text=True)
        except subprocess.CalledProcessError as exc:
            raise FileNotFoundError(path) from exc
        rows = list(csv.reader(io.StringIO(result.stdout)))
        if not rows or rows[0] != header:
            raise ValueError()
        for row in rows[1:]:
            if len(row) != 4 or not row[0] or (not row[1]) or (not row[3]):
                raise ValueError()
            try:
                amount = Decimal(row[2])
            except InvalidOperation as exc:
                raise ValueError() from exc
            if not amount.is_finite() or amount < 0:
                raise ValueError()
            if category is None or row[1] == category:
                records.append({'complaint_id': row[0], 'category': row[1], 'amount': amount, 'status': row[3]})
    records.sort(key=lambda x: (-x['amount'], x['complaint_id']))
    quant = Decimal('0.01')
    total = sum((x['amount'] for x in records), Decimal('0'))
    groups = {}
    for record in records:
        groups.setdefault(record['category'], [0, Decimal('0')])
        groups[record['category']][0] += 1
        groups[record['category']][1] += record['amount']
    by_category = [{'category': key, 'count': groups[key][0], 'amount': str(groups[key][1].quantize(quant, rounding=ROUND_HALF_UP))} for key in sorted(groups)]
    start = (page - 1) * page_size
    selected = records[start:start + page_size]
    complaints = [{'complaint_id': x['complaint_id'], 'category': x['category'], 'amount': str(x['amount'].quantize(quant, rounding=ROUND_HALF_UP)), 'status': x['status']} for x in selected]
    return {'total': len(records), 'total_amount': str(total.quantize(quant, rounding=ROUND_HALF_UP)), 'by_category': by_category, 'complaints': complaints}

