    from datetime import timedelta
    cutoff -= timedelta(days=keep_days)
    seen = set()
    expired = []
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        if set(record) != {'id', 'timestamp', 'size'}:
