        clauses.append('district = ?')
        params.append(district)
    if search:
        clauses.append('LOWER(crew_name) LIKE LOWER(?)')
        params.append('%' + search + '%')
    query = 'SELECT unit_id, district, eta_minutes, fuel_pct, crew_name FROM dispatch_units WHERE ' + ' AND '.join(clauses) + ' ORDER BY ' + ordering + ', unit_id ASC LIMIT ? OFFSET ?'
    params.extend([limit, offset])
    rows = conn.execute(query, params).fetchall()
    return [dict(zip(['unit_id', 'district', 'eta_minutes', 'fuel_pct', 'crew_name'], row)) for row in rows]

