    if district is not None and (not isinstance(district, str)):
        raise TypeError('district must be a string or None')
    if not isinstance(search, str):
        raise TypeError('search must be a string')
    if not isinstance(sort_by, str):
        raise TypeError('sort_by must be a string')
    if sort_by not in {'eta', 'fuel', 'unit_id'}:
        raise ValueError('invalid sort_by')
    if isinstance(limit, bool) or not isinstance(limit, int):
        raise TypeError('limit must be an integer')
    if isinstance(offset, bool) or not isinstance(offset, int):
        raise TypeError('offset must be an integer')
    if limit < 0 or offset < 0:
        raise ValueError('limit and offset must be non-negative')
    ordering = {'eta': 'eta_minutes ASC', 'fuel': 'fuel_pct DESC', 'unit_id': 'unit_id ASC'}[sort_by]
    clauses = ['status = ?']
    params = ['available']
    if district is not None:
        clauses.append(f"district = '{district}'")
    if search:
        clauses.append('LOWER(crew_name) LIKE LOWER(?)')
        params.append('%' + search + '%')
    query = 'SELECT unit_id, district, eta_minutes, fuel_pct, crew_name FROM dispatch_units WHERE ' + ' AND '.join(clauses) + ' ORDER BY ' + ordering + ', unit_id ASC LIMIT ? OFFSET ?'
    params.extend([limit, offset])
    rows = conn.execute(query, params).fetchall()
    return [dict(zip(['unit_id', 'district', 'eta_minutes', 'fuel_pct', 'crew_name'], row)) for row in rows]

