import subprocess

def summarize_tickets(log_path: str, customer: str, page: int, page_size: int) -> list[tuple[str, int, int]]:
    if not customer or page < 1 or page_size < 1 or (page_size > 100):
        raise ValueError()
    result = subprocess.run(['grep', '-F', '--', customer, log_path], capture_output=True, text=True, check=False)
    if result.returncode == 2:
        raise FileNotFoundError(log_path)
    groups = {}
    for line in result.stdout.splitlines():
        fields = line.split('|')
        if len(fields) != 4:
            continue
        ticket_id, row_customer, priority, minutes_text = fields
        if not ticket_id or row_customer != customer or (not priority):
            continue
        try:
            minutes = int(minutes_text)
        except ValueError:
            continue
        if minutes < 0:
            continue
        count, total = groups.get(priority, (0, 0))
        groups[priority] = (count + 1, total + minutes)
    rows = [(priority, count, total) for priority, (count, total) in groups.items()]
    rows.sort(key=lambda row: (-row[1], -row[2], row[0]))
    start = (page - 1) * page_size
    return rows[start:start + page_size]

