    if not isinstance(transactions, list):
        raise TypeError('transactions must be a list')
    if isinstance(min_amount, bool) or not isinstance(min_amount, (int, float)) or (not math.isfinite(min_amount)) or (min_amount < 0):
        raise ValueError('invalid threshold')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1 or isinstance(page_size, bool) or (not isinstance(page_size, int)) or (not 1 <= page_size <= 100):
        raise ValueError('invalid paging')
    groups = {}
    for row in transactions:
        if not isinstance(row, dict) or not isinstance(row.get('country'), str) or (not row['country']) or (type(row.get('flagged')) is not bool):
            raise ValueError('invalid transaction')
        amount = row.get('amount')
        if isinstance(amount, bool) or not isinstance(amount, (int, float)) or (not math.isfinite(amount)) or (amount < 0):
            raise ValueError('invalid transaction')
        if row['flagged'] and amount >= min_amount:
            item = groups.setdefault(row['country'], [0, 0.0])
            item[0] += 1
            item[1] += amount
    result = [{'country': c, 'count': v[0], 'total': round(v[1], 2)} for c, v in groups.items()]
    result.sort(key=lambda x: (-x['total'], x['country']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

