import operator

def rank_scooters(scooters: list[dict], score_expression: str, minimum_score: float=0) -> list[dict]:
    try:
        tree = ast.parse(score_expression, mode='eval').body
    except SyntaxError as exc:
        raise ValueError('invalid expression') from exc

    def evaluate(node, values):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in values:
                raise NameError(node.id)
            return values[node.id]
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
            value = evaluate(node.operand, values)
            if isinstance(node.op, ast.UAdd):
                return +value
            if isinstance(node.op, ast.USub):
                return -value
            return not value
        if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
            a = evaluate(node.left, values)
            b = evaluate(node.right, values)
            return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](a, b)
        if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
            result = evaluate(node.values[0], values)
            for child in node.values[1:]:
                if isinstance(node.op, ast.And) and (not result) or (isinstance(node.op, ast.Or) and result):
                    return result
                result = evaluate(child, values)
            return result
        if isinstance(node, ast.Compare):
            left = evaluate(node.left, values)
            result = True
            for op, part in zip(node.ops, node.comparators):
                right = evaluate(part, values)
                result = result and {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}[type(op)](left, right)
                left = right
            return result
        if isinstance(node, ast.IfExp):
            condition = evaluate(node.test, values)
            return evaluate(node.body if condition else node.orelse, values)
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
            return {'min': min, 'max': max, 'round': round}[node.func.id](*(evaluate(arg, values) for arg in node.args))
        raise ValueError('unsupported expression')
    scored = []
    for scooter in scooters:
        try:
            score = evaluate(tree, scooter)
        except NameError:
            raise
        except (TypeError, ZeroDivisionError, KeyError, IndexError) as exc:
            raise ValueError('invalid score') from exc
        if isinstance(score, bool) or not isinstance(score, (int, float)):
            raise ValueError('score must be numeric')
        if score >= minimum_score:
            scored.append((score, scooter))
    return [scooter for _, scooter in sorted(scored, key=lambda item: (-item[0], item[1]['id']))]

