import ast
import copy

def evaluate_rule(expression: str, variables: dict[str, int | float | bool]) -> int | float | bool:
    try:
        tree = ast.parse(expression, mode='eval')
        allowed = (ast.Expression, ast.Constant, ast.Name, ast.Load, ast.UnaryOp, ast.UAdd, ast.USub, ast.Not, ast.BinOp, ast.Add, ast.Sub, ast.Mult, ast.Div, ast.Compare, ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE, ast.BoolOp, ast.And, ast.Or, ast.Call)
        if any((not isinstance(node, allowed) for node in ast.walk(tree))):
            raise ValueError
        for node in ast.walk(tree):
            if isinstance(node, ast.Constant) and (not isinstance(node.value, (int, float, bool))):
                raise ValueError
            if isinstance(node, ast.Name) and node.id not in variables and (node.id not in {'min', 'max', 'round'}):
                raise ValueError
            if isinstance(node, ast.Call) and (not isinstance(node.func, ast.Name) or node.func.id not in {'min', 'max', 'round'} or node.keywords):
                raise ValueError
        return _walk_eval(tree.body, variables)
    except Exception as exc:
        if isinstance(exc, ValueError):
            raise
        raise ValueError from exc

def _walk_eval(node, variables):
    if isinstance(node, ast.Constant):
        return node.value
    if isinstance(node, ast.Name):
        if node.id in variables:
            return variables[node.id]
        return {'min': min, 'max': max, 'round': round}[node.id]
    if isinstance(node, ast.UnaryOp):
        value = _walk_eval(node.operand, variables)
        return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
    if isinstance(node, ast.BinOp):
        a, b = (_walk_eval(node.left, variables), _walk_eval(node.right, variables))
        return {ast.Add: lambda: a + b, ast.Sub: lambda: a - b, ast.Mult: lambda: a * b, ast.Div: lambda: a / b}[type(node.op)]()
    if isinstance(node, ast.BoolOp):
        value = _walk_eval(node.values[0], variables)
        for item in node.values[1:]:
            if isinstance(node.op, ast.And) and (not value):
                return value
            if isinstance(node.op, ast.Or) and value:
                return value
            value = _walk_eval(item, variables)
        return value
    if isinstance(node, ast.Compare):
        left = _walk_eval(node.left, variables)
        for op, right_node in zip(node.ops, node.comparators):
            right = _walk_eval(right_node, variables)
            ok = {ast.Eq: left == right, ast.NotEq: left != right, ast.Lt: left < right, ast.LtE: left <= right, ast.Gt: left > right, ast.GtE: left >= right}[type(op)]
            if not ok:
                return False
            left = right
        return True
    if isinstance(node, ast.Call):
        return _walk_eval(node.func, variables)(*[_walk_eval(a, variables) for a in node.args])
    raise ValueError

def sync_preferences(local: list[dict], remote: list[dict], rule: str, now: int) -> dict:
    lm = {r['id']: r for r in local}
    rm = {r['id']: r for r in remote}
    chosen = {}
    for ident in sorted(set(lm) | set(rm)):
        if ident not in lm:
            chosen[ident] = rm[ident]
        elif ident not in rm:
            chosen[ident] = lm[ident]
        else:
            chosen[ident] = rm[ident] if rm[ident]['updated'] >= lm[ident]['updated'] else lm[ident]
    kept = []
    for ident, record in chosen.items():
        enabled = record.get('enabled', False)
        priority = record.get('priority', 0)
        changed = int(ident in rm and (ident not in lm or rm[ident] != lm[ident]))
        values = {'updated': record['updated'], 'priority': priority, 'enabled': enabled, 'age': now - record['updated'], 'changed': changed}
        if evaluate_rule(rule, values):
            kept.append(copy.copy(record))
    kept.sort(key=lambda r: (-r.get('priority', 0), -r['updated'], r['id']))
    counts = {'enabled': sum((bool(r.get('enabled', False)) for r in kept)), 'disabled': sum((not bool(r.get('enabled', False)) for r in kept))}
    weight = sum((r.get('priority', 0) * (2 if r.get('enabled', False) else 1) for r in kept))
    return {'records': kept, 'counts': counts, 'total_weight': weight}

def summarize_preferences(records: list[dict]) -> dict:
    hist = {}
    enabled, disabled = ([], [])
    total = 0
    for record in records:
        priority = record.get('priority', 0)
        total += priority
        hist[priority] = hist.get(priority, 0) + 1
        (enabled if record.get('enabled', False) else disabled).append(record['id'])
    mean = total / len(records) if records else 0
    if isinstance(mean, float) and mean.is_integer():
        mean = int(mean)
    return {'records': len(records), 'enabled_ids': enabled, 'disabled_ids': disabled, 'average_priority': mean, 'by_priority': dict(sorted(hist.items()))}

