import csv
import subprocess

def quota_report(path: str, species: str, page: int=1, page_size: int=10) -> list[dict]:
    if not species or page < 1 or page_size < 1 or (page_size > 100):
        raise ValueError('invalid arguments')
    result = subprocess.run(['grep', '-F', '--', species, path], capture_output=True, text=True)
    if result.returncode == 2:
        raise FileNotFoundError(path)
    groups = {}
    for line in result.stdout.splitlines():
        fields = [x.strip() for x in next(csv.reader([line]))]
        if len(fields) != 4:
            raise ValueError('invalid row')
        vessel, kind, quota_text, caught_text = fields
        if kind != species:
            continue
        try:
            quota = float(quota_text)
            caught = float(caught_text)
        except ValueError:
            raise ValueError('invalid number')
        if quota < 0 or caught < 0:
            raise ValueError('invalid number')
        item = groups.setdefault(vessel, [0.0, 0.0])
        item[0] += quota
        item[1] += caught
    rows = []
    for vessel, (quota, caught) in groups.items():
        remaining = quota - caught
        utilization = 0.0 if quota == 0 else caught / quota * 100
        rows.append({'vessel': vessel, 'quota': round(quota, 2), 'caught': round(caught, 2), 'remaining': round(remaining, 2), 'utilization': round(utilization, 2)})
    rows.sort(key=lambda x: (-x['remaining'], x['vessel']))
    start = (page - 1) * page_size
    return rows[start:start + page_size]

