import csv
import io
import subprocess

def _parse_lines(source):
    result = []
    for number, row in enumerate(csv.reader(source, delimiter='\t'), 1):
        if not row or all((not field for field in row)):
            continue
        if len(row) != 4:
            raise ValueError('invalid row')
        artist, title, cents_text, quantity_text = row
        artist = artist.strip()
        title = title.strip()
        if not artist or not title:
            raise ValueError('empty field')
        try:
            cents = int(cents_text)
            quantity = int(quantity_text)
        except ValueError as exc:
            raise ValueError('invalid number') from exc
        if cents < 0 or quantity <= 0:
            raise ValueError('invalid value')
        result.append({'artist': artist, 'title': title, 'cents': cents, 'quantity': quantity})
    return result

def parse_sales(path: str) -> list[dict]:
    with open(path, encoding='utf-8', newline='') as stream:
        return _parse_lines(stream)

def rank_artists(path: str, limit: int | None=None) -> list[dict]:
    if limit is not None and (type(limit) is not int or limit < 0):
        raise ValueError('invalid limit')
    completed = subprocess.run(['sort', '-t', '\t', '-k1,1', '-k3,3nr', path], text=True, capture_output=True, check=True)
    totals = {}
    for row in _parse_lines(io.StringIO(completed.stdout)):
        item = totals.setdefault(row['artist'], [0, 0, 0])
        item[0] += row['cents'] * row['quantity']
        item[1] += row['quantity']
        item[2] += 1
    result = [{'artist': artist, 'revenue_cents': values[0], 'units': values[1], 'artworks': values[2]} for artist, values in totals.items()]
    result.sort(key=lambda item: (-item['revenue_cents'], -item['units'], item['artist']))
    return result if limit is None else result[:limit]

