def write_billing(contents):
    directory = tempfile.TemporaryDirectory()
    path = Path(directory.name) / "billing.csv"
    path.write_text(contents, encoding="utf-8")
    return directory, str(path)


def test_orders_records_by_amount_and_account():
    directory, path = write_billing(
        "A300,Ada,18.25\nA100,Bea,4.50\nA200,Cleo,18.25\n"
    )
    try:
        assert order_due_accounts(path) == [
            ("A100", "Bea", 4.5),
            ("A200", "Cleo", 18.25),
            ("A300", "Ada", 18.25),
        ]
    finally:
        directory.cleanup()


def test_preserves_account_and_customer_text():
    directory, path = write_billing("009,North District,10\n001,South District,2.75\n")
    try:
        assert order_due_accounts(path) == [
            ("001", "South District", 2.75),
            ("009", "North District", 10.0),
        ]
    finally:
        directory.cleanup()


def test_empty_file_returns_empty_list():
