def order_due_accounts(path: str) -> list[tuple[str, str, float]]:
    result = subprocess.run(['sort', '-t,', '-k3,3n', '-k1,1', path], check=True, capture_output=True, text=True)
    records = []
    for line in result.stdout.splitlines():
        if not line:
            continue
        fields = line.split(',')
        if len(fields) != 3:
            raise ValueError('invalid billing record')
        try:
            amount = float(fields[2])
        except ValueError as exc:
            raise ValueError('invalid amount') from exc
        records.append((fields[0], fields[1], amount))
    return records

