import hashlib
import hmac
import json

def summarize_baggage(payload: str, carrier_key: bytes, page: int=1, page_size: int=10) -> list[dict]:
    if page < 1 or page_size < 1:
        raise ValueError('invalid paging')
    try:
        document = json.loads(payload)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(document, dict) or not isinstance(document.get('events'), list):
        raise ValueError('invalid events')
    latest = {}
    for event in document['events']:
        if not isinstance(event, dict):
            raise ValueError('invalid event')
        fields = ('bag_tag', 'flight', 'status', 'timestamp', 'weight_kg', 'signature')
        if any((field not in event for field in fields)):
            raise ValueError('invalid event')
        if not isinstance(event['bag_tag'], str) or not isinstance(event['flight'], str) or (not isinstance(event['status'], str)):
            raise ValueError('invalid event')
        if isinstance(event['timestamp'], bool) or not isinstance(event['timestamp'], int):
            raise ValueError('invalid event')
        if isinstance(event['weight_kg'], bool) or not isinstance(event['weight_kg'], (int, float)):
            raise ValueError('invalid event')
        if not isinstance(event['signature'], str):
            raise ValueError('invalid signature')
        body = {field: event[field] for field in ('bag_tag', 'flight', 'status', 'timestamp', 'weight_kg')}
        text = json.dumps(body, separators=(',', ':'), sort_keys=True)
        expected = hmac.new(carrier_key, text.encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(event['signature'], expected):
            raise ValueError('invalid signature')
        previous = latest.get(event['bag_tag'])
        if previous is None or event['timestamp'] >= previous['timestamp']:
            latest[event['bag_tag']] = event
    grouped = {}
    for event in latest.values():
        group = grouped.setdefault(event['flight'], {'weights': 0.0, 'statuses': {}})
        group['weights'] += event['weight_kg']
        status = event['status']
        group['statuses'][status] = group['statuses'].get(status, 0) + 1
    result = []
    for flight in sorted(grouped):
        group = grouped[flight]
        result.append({'flight': flight, 'bag_count': sum(group['statuses'].values()), 'total_weight_kg': round(group['weights'], 2), 'statuses': {status: group['statuses'][status] for status in sorted(group['statuses'])}})
    start = (page - 1) * page_size
    return result[start:start + page_size]

