from solution import build_authenticity_report


def signed(records, secret="atelier-key"):
    payload = json.dumps(records, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
    return hmac.new(secret.encode("utf-8"), payload, hashlib.sha256).hexdigest()


def test_groups_filters_sorts_and_rounds():
    records = [
        {"serial": "A1", "house": "Zegna", "price": 1200.125, "year": 2020, "verified": True},
        {"serial": "B2", "house": "Armani", "price": 800, "year": 2018, "verified": True},
        {"serial": "C3", "house": "Zegna", "price": 99.875, "year": 2022, "verified": True},
        {"serial": "D4", "house": "Armani", "price": 5000, "year": 2024, "verified": False},
    ]
    assert build_authenticity_report(records, signed(records), "atelier-key") == {
        "total_verified": 3,
        "houses": [
            {"house": "Zegna", "count": 2, "total_value": 1300.0, "average_year": 2021.0},
            {"house": "Armani", "count": 1, "total_value": 800.0, "average_year": 2018.0},
        ],
    }


def test_ties_are_sorted_by_house_name():
    records = [
        {"serial": "1", "house": "Boucheron", "price": 100, "year": 2000, "verified": True},
        {"serial": "2", "house": "Alaia", "price": 100, "year": 2001, "verified": True},
    ]
    assert build_authenticity_report(records, signed(records), "atelier-key")["houses"] == [
        {"house": "Alaia", "count": 1, "total_value": 100.0, "average_year": 2001.0},
        {"house": "Boucheron", "count": 1, "total_value": 100.0, "average_year": 2000.0},
    ]


def test_empty_verified_set():
    records = [{"serial": "X", "house": "Cartier", "price": 1, "year": 1900, "verified": False}]
    assert build_authenticity_report(records, signed(records), "atelier-key") == {"total_verified": 0, "houses": []}


def test_empty_records_is_invalid():
    records = []
    with pytest.raises(ValueError):
        build_authenticity_report(records, signed(records), "atelier-key")


def test_bad_signature_is_rejected_before_record_validation():
    records = [{"serial": "X", "house": "Cartier", "price": 1, "year": 1900, "verified": True}]
    with pytest.raises(PermissionError):
