        records = [dict(base, **{key: value})]
        with pytest.raises(ValueError):
            build_authenticity_report(records, signed(records), "atelier-key")


def test_unicode_values_are_supported():
    records = [{"serial": "É-1", "house": "Löwe", "price": 12.345, "year": 2100, "verified": True}]
