import hashlib
import hmac
import json
import math

def build_authenticity_report(records: list[dict], signature: str, secret: str) -> dict:
    payload = json.dumps(records, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode('utf-8')
    expected = hmac.new(secret.encode('utf-8'), payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise PermissionError('invalid signature')
    if not isinstance(records, list) or not records:
        raise ValueError('records must be non-empty')
    seen = set()
    groups = {}
    for record in records:
        if not isinstance(record, dict) or set(record) != {'serial', 'house', 'price', 'year', 'verified'}:
            raise ValueError('invalid record')
        serial, house = (record['serial'], record['house'])
        price, year, verified = (record['price'], record['year'], record['verified'])
        if not isinstance(serial, str) or not serial or (not isinstance(house, str)) or (not house):
            raise ValueError('invalid text')
        if serial in seen:
            raise ValueError('duplicate serial')
        if isinstance(price, bool) or not isinstance(price, (int, float)) or (not math.isfinite(price)) or (price <= 0):
            raise ValueError('invalid price')
        if isinstance(year, bool) or not isinstance(year, int) or (not 1900 <= year <= 2100) or (not isinstance(verified, bool)):
            raise ValueError('invalid record values')
        seen.add(serial)
        if verified:
            item = groups.setdefault(house, [0, 0.0, 0])
            item[0] += 1
            item[1] += price
            item[2] += year
    houses = [{'house': h, 'count': v[0], 'total_value': round(v[1], 2), 'average_year': round(v[2] / v[0], 1)} for h, v in groups.items()]
    houses.sort(key=lambda x: (-x['total_value'], x['house']))
    return {'total_verified': sum((x['count'] for x in houses)), 'houses': houses}

