import csv
import os
from datetime import date

def _path(base_dir, filename):
    base = os.path.realpath(base_dir)
    candidate = os.path.realpath(os.path.join(base, filename))
    if os.path.commonpath([base, candidate]) != base:
        raise ValueError('path outside base directory')
    return candidate

def _date(value):
    try:
        return date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def membership_report(base_dir: str, filenames: list[str], as_of: str) -> list[dict[str, object]]:
    current = _date(as_of)
    headers = ['member_id', 'name', 'email', 'book', 'joined', 'left', 'attended']
    records = {}
    for filename in filenames:
        with open(_path(base_dir, filename), newline='', encoding='utf-8') as handle:
            reader = csv.DictReader(handle)
            if reader.fieldnames != headers:
                raise ValueError('invalid header')
            for raw in reader:
                if raw is None or any((value is None for value in raw.values())):
                    raise ValueError('invalid row')
                values = {key: raw[key].strip() for key in headers}
                if any((not values[key] for key in ['member_id', 'name', 'email', 'book', 'joined'])):
                    raise ValueError('empty field')
                joined = _date(values['joined'])
                left = _date(values['left']) if values['left'] else None
                if left is not None and left <= joined:
                    raise ValueError('invalid membership interval')
                try:
                    attended = int(values['attended'])
                except ValueError:
                    raise ValueError('invalid attendance')
                if attended < 0 or str(attended) != values['attended']:
                    raise ValueError('invalid attendance')
                key = (values['member_id'], values['book'])
                metadata = (values['name'], values['email'], values['joined'], values['left'])
                if key in records and records[key]['metadata'] != metadata:
                    raise ValueError('conflicting membership')
                if joined <= current and (left is None or current < left):
                    if key not in records:
                        records[key] = {'metadata': metadata, 'attended': 0, 'files': set()}
                    records[key]['attended'] += attended
                    records[key]['files'].add(filename)
    result = []
    for (member_id, book), item in records.items():
        name, email, joined, left = item['metadata']
        result.append({'member_id': member_id, 'name': name, 'email': email, 'book': book, 'joined': joined, 'left': left or None, 'attended': item['attended'], 'file_count': len(item['files'])})
    return sorted(result, key=lambda x: (-x['attended'], x['joined'], x['member_id'], x['book']))

