        raise ValueError('invalid record')
    if record['state'] not in _STATES:
        raise ValueError('invalid record')
    if isinstance(record['battery'], bool) or not isinstance(record['battery'], (int, float)) or (not 0 <= record['battery'] <= 100):
        raise ValueError('invalid record')

def _path(base_dir, relative_name):
    base = os.path.realpath(base_dir)
    candidate = os.path.realpath(os.path.join(base, relative_name))
    if os.path.commonpath((base, candidate)) != base:
        raise ValueError('invalid path')
    return candidate

def load_status_log(base_dir: str, relative_name: str) -> list[dict]:
    records = []
    with open(_path(base_dir, relative_name), encoding='utf-8') as f:
        for line in f:
            if not line.strip():
                continue
            try:
                record = json.loads(line)
            except Exception as exc:
                raise ValueError('invalid JSON') from exc
            _validate(record)
            records.append(record)
