        raise ValueError('missing key')
    if not vals['context']:
        raise ValueError('context')
    try:
        layer = int(vals['layer'])
        datetime.date.fromisoformat(vals['date'])
    except Exception as e:
        raise ValueError('scalar') from e
    if layer < 0 or re.fullmatch('\\d{4}-\\d{2}-\\d{2}', vals['date']) is None:
        raise ValueError('scalar')

    def pairs(text, integer):
        out = {}
        if not text:
            return out
        for item in text.split(','):
            if '=' not in item:
                raise ValueError('pair')
            k, v = (x.strip() for x in item.split('=', 1))
            if not k or k in out:
                raise ValueError('pair')
            try:
                n = int(v) if integer else float(v)
            except Exception as e:
                raise ValueError('number') from e
            if integer and n < 0 or (not integer and (not math.isfinite(n))):
                raise ValueError('number')
            out[k] = n
        return out
    return {'context': vals['context'], 'layer': layer, 'date': vals['date'], 'finds': pairs(vals['finds'], True), 'measurements': pairs(vals['measurements'], False)}

