import hashlib
import re
import sqlite3

def anonymize_identifier(patient_id: int, salt: str) -> str:
    if not isinstance(patient_id, int) or not isinstance(salt, str):
        raise TypeError()
    return 'PAT-' + hashlib.sha256((salt + ':' + str(patient_id)).encode()).hexdigest()[:12]

def anonymize_free_text(text: str, terms: list[str]) -> str:
    if not isinstance(text, str) or not isinstance(terms, list) or any((not isinstance(x, str) for x in terms)):
        raise TypeError()
    choices = sorted({x for x in terms if x}, key=len, reverse=True)
    if not choices:
        return text
    pattern = re.compile('|'.join((re.escape(x) for x in choices)), re.IGNORECASE)
    return pattern.sub('[REDACTED]', text)

def build_anonymized_report(conn: sqlite3.Connection, department: str | None=None, name_search: str | None=None, sort_by: str='patient_id', salt: str='default') -> list[dict]:
    allowed = {'patient_id': 'p.id', 'anonymous_name': 'p.id', 'age': 'p.age', 'department': 'p.department', 'encounter_count': 'COUNT(e.id)', 'latest_encounter': 'MAX(e.encounter_date)'}
    if sort_by not in allowed:
        raise ValueError('invalid sort field')
    query = 'SELECT p.id, p.full_name, p.age, p.department, p.notes, COUNT(e.id), MAX(e.encounter_date) FROM patients p LEFT JOIN encounters e ON e.patient_id = p.id WHERE 1=1'
    values = []
    if department is not None:
        query += ' AND p.department = ?'
        values.append(department)
    if name_search is not None:
        query += ' AND lower(p.full_name) LIKE lower(?)'
        values.append('%' + name_search + '%')
    query += ' GROUP BY p.id, p.full_name, p.age, p.department, p.notes'
    rows = conn.execute(query, values).fetchall()
    result = []
    for pid, name, age, dept, notes, count, latest in rows:
        anon_name = 'Patient-' + hashlib.sha256((salt + ':name:' + str(pid)).encode()).hexdigest()[:10]
        result.append({'patient_id': pid, 'anonymous_id': anonymize_identifier(pid, salt), 'age': age, 'department': dept, 'anonymous_name': anon_name, 'encounter_count': count, 'latest_encounter': latest, 'redacted_notes': anonymize_free_text(notes, [name])})

    def key(row):
        value = row[sort_by]
        return (value is not None, value, row['patient_id']) if sort_by == 'latest_encounter' else (value, row['patient_id'])
    return sorted(result, key=key)

