import ast
import operator

def _evaluate(node, values):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id in values:
            return values[node.id]
        if node.id == 'round':
            return round
        raise NameError('name %r is not defined' % node.id)
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub)):
        value = _evaluate(node.operand, values)
        return value if isinstance(node.op, ast.UAdd) else -value
    if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
        left = _evaluate(node.left, values)
        right = _evaluate(node.right, values)
        return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
        args = [_evaluate(arg, values) for arg in node.args]
        if node.func.id == 'round':
            if len(args) not in (1, 2):
                raise TypeError('round expected 1 or 2 arguments')
            return round(*args)
        return min(*args) if node.func.id == 'min' else max(*args)
    raise ValueError('unsupported formula')

def rank_fixtures(fixtures: list[dict], formula: str, offset: int=0, limit: int | None=None) -> list[dict]:
    if isinstance(offset, bool) or not isinstance(offset, int) or offset < 0:
        raise ValueError('invalid offset')
    if limit is not None and (isinstance(limit, bool) or not isinstance(limit, int) or limit < 0):
        raise ValueError('invalid limit')
    tree = ast.parse(formula, mode='eval').body
    ranked = []
    for index, fixture in enumerate(fixtures):
        values = {'home_score': fixture['home_score'], 'away_score': fixture['away_score'], 'total': fixture['home_score'] + fixture['away_score'], 'margin': fixture['home_score'] - fixture['away_score']}
        rating = _evaluate(tree, values)
        if not isinstance(rating, (int, float)) or isinstance(rating, bool):
            raise TypeError('formula result must be numeric')
        item = dict(fixture)
        item['rating'] = rating
        ranked.append((item, index))
    ranked.sort(key=lambda pair: (-pair[0]['rating'], pair[0]['date'], pair[0]['home'], pair[0]['away'], pair[1]))
    result = [item for item, _ in ranked][offset:]
    return result if limit is None else result[:limit]

