    flags = [
        flag("on", priority=2),
        flag("disabled", enabled=False),
        flag("other-env", environments=["dev"]),
        flag("not-yet", rollout=25),
        flag("other-tenant", tenant="beta"),
    ]
    assert list_feature_flags(requester(bucket=25), flags, "prod") == [
        {"key": "on", "variant": "on", "priority": 2}
    ]


