    flags = [
        flag("zeta", priority=4),
        flag("alpha", priority=4),
        flag("middle", priority=8),
        flag("low", priority=-1),
    ]
    assert list_feature_flags(requester(), flags, "prod") == [
        {"key": "middle", "variant": "on", "priority": 8},
        {"key": "alpha", "variant": "on", "priority": 4},
        {"key": "zeta", "variant": "on", "priority": 4},
        {"key": "low", "variant": "on", "priority": -1},
    ]


