    flags = [flag("a", priority=5), flag("b", priority=4), flag("c", priority=3), flag("d", priority=2)]
    assert list_feature_flags(requester(), flags, "prod", page=1, page_size=2) == [
        {"key": "a", "variant": "on", "priority": 5},
        {"key": "b", "variant": "on", "priority": 4},
    ]
    assert list_feature_flags(requester(), flags, "prod", page=2, page_size=2) == [
        {"key": "c", "variant": "on", "priority": 3},
        {"key": "d", "variant": "on", "priority": 2},
    ]
