    if not isinstance(username, str) or not username.strip() or (not isinstance(password, str)) or (len(password) < 8):
        raise ValueError('account')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return {'username': username.strip(), 'salt': base64.b64encode(salt).decode(), 'digest': base64.b64encode(digest).decode()}

def verify_account(account: dict, password: str) -> bool:
    try:
        if not isinstance(account, dict) or not isinstance(password, str):
            return False
        salt = base64.b64decode(account['salt'], validate=True)
        expected = base64.b64decode(account['digest'], validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError):
        return False

