import csv
import math
import os
import tempfile
from decimal import Decimal, InvalidOperation

def export_license_report(records: list[dict], destination: str, region: str | None=None, page: int=1, page_size: int=50) -> int:
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('page must be positive')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('page_size must be positive')
    groups = {}
    for record in records:
        current_region = record['region']
        species = record['species']
        if not isinstance(current_region, str) or not isinstance(species, str):
            raise ValueError('invalid grouping field')
        if region is not None and current_region != region:
            continue
        raw_fee = record['fee']
        try:
            fee = Decimal(str(raw_fee))
        except (InvalidOperation, ValueError, TypeError):
            raise ValueError('invalid fee')
        if not fee.is_finite() or fee < 0:
            raise ValueError('invalid fee')
        key = (current_region, species)
        if key not in groups:
            groups[key] = [0, Decimal('0')]
        groups[key][0] += 1
        groups[key][1] += fee
    rows = []
    for (current_region, species), (count, total) in sorted(groups.items()):
        average = total / count
        rows.append([current_region, species, str(count), format(total, '.2f'), format(average, '.2f')])
    start = (page - 1) * page_size
    selected = rows[start:start + page_size]
    parent = os.path.dirname(os.path.abspath(destination)) or '.'
    fd, temporary = tempfile.mkstemp(dir=parent)
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle)
            writer.writerow(['region', 'species', 'license_count', 'total_fee', 'average_fee'])
            writer.writerows(selected)
        os.replace(temporary, destination)
    except BaseException:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return len(selected)

