from typing import Optional
import xml.etree.ElementTree as ET

def parse_checkin_manifest(xml_text: str, flight: Optional[str]=None, page: int=1, page_size: int=20) -> dict:
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid paging')
    try:
        root = ET.fromstring(xml_text)
    except (ET.ParseError, TypeError) as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'checkin':
        raise ValueError('invalid root')
    passengers = []
    seen = set()
    required = ('id', 'name', 'flight', 'seat', 'bags', 'priority')
    for element in root:
        if element.tag != 'passenger':
            raise ValueError('invalid child')
        if any((key not in element.attrib for key in required)):
            raise ValueError('missing attribute')
        values = {key: element.attrib[key] for key in required}
        if values['id'] in seen:
            raise ValueError('duplicate id')
        try:
            bags = int(values['bags'])
            priority = int(values['priority'])
        except ValueError as exc:
            raise ValueError('invalid number') from exc
        if bags < 0 or priority < 0 or priority > 9:
            raise ValueError('number out of range')
        seen.add(values['id'])
        if flight is None or values['flight'] == flight:
            passengers.append({'id': values['id'], 'name': values['name'], 'flight': values['flight'], 'seat': values['seat'], 'bags': bags, 'priority': priority})
    passengers.sort(key=lambda item: (-item['priority'], item['seat'], item['id']))
    total = len(passengers)
    start = (page - 1) * page_size
    pages = (total + page_size - 1) // page_size if total else 0
    return {'total_passengers': total, 'total_bags': sum((item['bags'] for item in passengers)), 'page': page, 'page_size': page_size, 'pages': pages, 'passengers': passengers[start:start + page_size]}

