import os
from pathlib import Path

def write_episode_notes(base_dir: str, episode_id: str, filename: str, content: str) -> str:
    if not episode_id or not filename:
        raise ValueError('episode_id and filename must not be empty')
    base = Path(base_dir).resolve()
    destination = (base / episode_id / filename).resolve()
    if destination == base or base not in destination.parents:
        raise ValueError('path is outside the base directory')
    destination.parent.mkdir(parents=True, exist_ok=True)
    destination.write_text(content, encoding='utf-8')
    return str(destination)

