import csv
import io
import subprocess
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def _read(path):
    result = subprocess.run(['cat', path], capture_output=True, text=True)
    if result.returncode != 0:
        raise FileNotFoundError(path)
    return result.stdout

def summarize_catch(path: str, species: str | None=None, limit: int=10) -> list[dict]:
    if isinstance(limit, bool) or not isinstance(limit, int) or limit <= 0:
        raise ValueError('limit')
    if species == '':
        raise ValueError('species')
    text = _read(path)
    if not text:
        return []
    reader = csv.DictReader(io.StringIO(text))
    required = ['species', 'weight_kg', 'port']
    if reader.fieldnames != required:
        raise ValueError('header')
    groups = {}
    for row in reader:
        if row is None or any((value is None for value in row.values())):
            raise ValueError('row')
        name = row['species'].strip()
        port = row['port'].strip()
        if not name or not port:
            raise ValueError('row')
        try:
            weight = Decimal(row['weight_kg'].strip())
        except (InvalidOperation, AttributeError):
            raise ValueError('weight')
        if not weight.is_finite() or weight < 0:
            raise ValueError('weight')
        if species is not None and name != species:
            continue
        key = (name, port)
        if key not in groups:
            groups[key] = [Decimal('0'), 0]
        groups[key][0] += weight
        groups[key][1] += 1
    result = []
    for (name, port), (total, count) in groups.items():
        rounded = total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        result.append({'species': name, 'port': port, 'total_kg': float(rounded), 'landings': count})
    result.sort(key=lambda item: (-item['total_kg'], item['species'], item['port']))
    return result[:limit]

