        raise RuntimeError('MODERATION_API_TOKEN is required')
    response = requests.post(endpoint, json={'images': images}, headers={'Authorization': f'Bearer {token}'}, timeout=5)
    response.raise_for_status()
    try:
        data = response.json()
        results = data['results']
    except (TypeError, KeyError, ValueError):
        raise ValueError('invalid moderation response')
    if not isinstance(data, dict) or not isinstance(results, list):
        raise ValueError('invalid moderation response')
    combined = {}
    for item in results:
        if not isinstance(item, dict) or not isinstance(item.get('id'), str) or (not isinstance(item.get('score'), (int, float))) or isinstance(item.get('score'), bool) or (not 0 <= item['score'] <= 1) or (not isinstance(item.get('categories'), list)) or (not all((isinstance(x, str) for x in item['categories']))):
            raise ValueError('invalid moderation result')
        ident = item['id']
        if ident not in combined or item['score'] > combined[ident][0]:
            combined[ident] = [item['score'], set(item['categories'])]
        else:
            combined[ident][1].update(item['categories'])
    filtered = [(ident, score, cats) for ident, (score, cats) in combined.items() if score >= 0.5]
    filtered.sort(key=lambda x: (-x[1], x[0]))
    start = (page - 1) * page_size
    return [{'id': ident, 'score': round(score, 2), 'categories': sorted(cats)} for ident, score, cats in filtered[start:start + page_size]]

