import hashlib
import hmac
import json

def sync_preferences(lines: list[str], secret: bytes, page: int=1, page_size: int=2) -> dict:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page <= 0) or (page_size <= 0):
        raise ValueError('invalid pagination')
    latest = {}
    for line in lines:
        try:
            record = json.loads(line)
        except Exception as exc:
            raise ValueError('invalid record') from exc
        if not isinstance(record, dict) or set(record) != {'user', 'name', 'value', 'timestamp', 'signature'}:
            raise ValueError('invalid record')
        user = record['user']
        name = record['name']
        value = record['value']
        timestamp = record['timestamp']
        signature = record['signature']
        if not isinstance(user, str) or not user or (not isinstance(name, str)) or (not name) or (not isinstance(value, bool)) or isinstance(timestamp, bool) or (not isinstance(timestamp, int)) or (timestamp < 0) or (not isinstance(signature, str)) or (len(signature) != 64) or any((c not in '0123456789abcdef' for c in signature)):
            raise ValueError('invalid record')
        canonical = json.dumps(value, separators=(',', ':'), sort_keys=True)
        message = f'{user}\n{name}\n{canonical}\n{timestamp}'.encode()
        expected = hmac.new(secret, message, hashlib.sha256).hexdigest()
        if not hmac.compare_digest(expected, signature):
            continue
        key = (user, name)
        if key not in latest or timestamp >= latest[key][0]:
            latest[key] = (timestamp, value)
    grouped = {}
    for (user, name), (timestamp, value) in latest.items():
        grouped.setdefault(user, []).append({'name': name, 'value': value, 'timestamp': timestamp})
    users = []
    for user in sorted(grouped):
        users.append({'user': user, 'preferences': sorted(grouped[user], key=lambda item: item['name'])})
    start = (page - 1) * page_size
    return {'total_users': len(users), 'page': page, 'page_size': page_size, 'users': users[start:start + page_size]}

