import hashlib
import hmac
import os

def hash_access_code(code: str) -> str:
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', code.encode(), salt, 100000)
    return salt.hex() + ':' + digest.hex()

def verify_access_code(code: str, stored: str) -> bool:
    try:
        salt_text, digest_text = stored.split(':', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', code.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError, UnicodeError):
        return False

def lineup_page(records: list[dict], day: str, page: int, page_size: int) -> dict:
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    selected = [record for record in records if record['day'] == day]
    selected.sort(key=lambda record: (record['start'], record['artist']))
    totals = {}
    for record in selected:
        stage = record['stage']
        totals[stage] = totals.get(stage, 0) + record['minutes']
    ordered_totals = {stage: totals[stage] for stage in sorted(totals)}
    first = (page - 1) * page_size
    last = first + page_size
    return {'performances': [record['artist'] for record in selected[first:last]], 'stage_minutes': ordered_totals}

