def fetch_endorsements(conn: sqlite3.Connection, policy_id: int, statuses: list[str] | None=None, search: str='', sort_by: str='effective_date', descending: bool=False, limit: int=50, offset: int=0) -> list[dict]:
    if statuses is not None and (not isinstance(statuses, (list, tuple))):
        raise TypeError('statuses must be a list or tuple')
    if isinstance(limit, bool) or not isinstance(limit, int) or limit <= 0:
        raise ValueError('limit must be positive')
    if isinstance(offset, bool) or not isinstance(offset, int) or offset < 0:
        raise ValueError('offset must be non-negative')
