    if sort_by not in columns:
        raise ValueError('invalid sort column')
    if statuses is not None and (not statuses):
        return []
    clauses = ['policy_id = ?']
    params = [policy_id]
    if statuses is not None:
        marks = ','.join(('?' for _ in statuses))
        clauses.append('status IN (' + marks + ')')
        params.extend(statuses)
    if search:
        clauses.append('(code LIKE ? OR description LIKE ?)')
        params.extend([f'%{search}%', f'%{search}%'])
    direction = 'DESC' if descending else 'ASC'
    sql = 'SELECT id, code, description, status, effective_date, premium_change_cents FROM endorsements WHERE ' + ' AND '.join(clauses) + f' ORDER BY {sort_by} {direction}, id ASC LIMIT ? OFFSET ?'
    params.extend([limit, offset])
    return [dict(row) for row in conn.execute(sql, params).fetchall()]

