from datetime import date

def get_show_analytics(requester: dict, events: list[dict], start_date: str, end_date: str, page: int=1, page_size: int=20) -> dict:
    if not isinstance(requester, dict):
        raise TypeError('requester must be a dictionary')
    if not isinstance(events, list):
        raise TypeError('events must be a list')
    try:
        start = date.fromisoformat(start_date)
        end = date.fromisoformat(end_date)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if start > end or not isinstance(page, int) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError('invalid range or pagination')
    grouped = {}
    for event in events:
        if not isinstance(event, dict):
            raise ValueError('invalid event')
        required = ('show_id', 'show_title', 'owner_id', 'tenant_id', 'occurred_on', 'downloads', 'listens', 'completion_rate')
        if any((key not in event for key in required)):
            raise ValueError('invalid event')
        if not all((isinstance(event[key], str) and event[key] for key in required[:5])):
            raise ValueError('invalid event')
        try:
            event_date = date.fromisoformat(event['occurred_on'])
        except ValueError:
            raise ValueError('invalid event date')
        if not isinstance(event['downloads'], int) or isinstance(event['downloads'], bool) or event['downloads'] < 0 or (not isinstance(event['listens'], int)) or isinstance(event['listens'], bool) or (event['listens'] < 0) or (not isinstance(event['completion_rate'], (int, float))) or isinstance(event['completion_rate'], bool) or (not 0 <= event['completion_rate'] <= 100):
            raise ValueError('invalid event values')
        if not start <= event_date <= end:
            continue
        if not (event['owner_id'] == requester.get('id') or ('analytics_admin' in requester.get('roles', []) and event['tenant_id'] == requester.get('tenant_id'))):
            raise PermissionError('access denied')
        row = grouped.setdefault(event['show_id'], {'show_id': event['show_id'], 'show_title': event['show_title'], 'downloads': 0, 'listens': 0, 'weighted': 0.0})
        row['downloads'] += event['downloads']
        row['listens'] += event['listens']
        row['weighted'] += event['listens'] * event['completion_rate']
    rows = []
    for row in grouped.values():
        rows.append({'show_id': row['show_id'], 'show_title': row['show_title'], 'downloads': row['downloads'], 'listens': row['listens'], 'completion_rate': round(row['weighted'] / row['listens'], 2) if row['listens'] else 0})
    rows.sort(key=lambda row: (-row['downloads'], row['show_id']))
    begin = (page - 1) * page_size
    return {'total': len(rows), 'page': page, 'page_size': page_size, 'items': rows[begin:begin + page_size]}

