    if isinstance(household_size, bool) or not isinstance(household_size, int) or household_size <= 0:
        raise ValueError('invalid household size')
    if isinstance(day, bool) or not isinstance(day, int) or day < 0:
        raise ValueError('invalid day')
    if isinstance(code_length, bool) or not isinstance(code_length, int) or (not 6 <= code_length <= 32):
        raise ValueError('invalid code length')
    usable = []
    for record in inventory:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        for key in ('category', 'item', 'quantity', 'expires'):
            if key not in record:
                raise ValueError('invalid record')
        category = record['category']
        item = record['item']
        quantity = record['quantity']
        expires = record['expires']
        if not isinstance(category, str) or not category or (not isinstance(item, str)) or (not item):
            raise ValueError('invalid record')
        if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity < 0:
            raise ValueError('invalid record')
        if isinstance(expires, bool) or not isinstance(expires, int):
            raise ValueError('invalid record')
        if quantity > 0 and expires >= day:
            usable.append((expires, category, item, quantity))
    usable.sort(key=lambda row: (row[0], row[1], row[2]))
    remaining = household_size
    selected = []
    for expires, category, item, quantity in usable:
        if remaining == 0:
