        except (InvalidOperation, ValueError, TypeError):
            raise ValueError('invalid fee')
        if fee < 0:
            raise ValueError('invalid fee')
        if app['owner_id'] == requester_id or ('passport_officer' in roles and app['tenant_id'] == tenant_id):
            selected.append((app, fee))
    selected.sort(key=lambda pair: (pair[0]['submitted_at'], pair[0]['id']))
    counts = {status: 0 for status in statuses}
    total_fee = Decimal('0')
    for app, fee in selected:
        counts[app['status']] += 1
        total_fee += fee
    total = len(selected)
    pages = (total + page_size - 1) // page_size if total else 0
    start = (page - 1) * page_size
    items = [{'id': app['id'], 'status': app['status'], 'submitted_at': app['submitted_at'], 'fee': app['fee']} for app, _ in selected[start:start + page_size]]
    rounded = total_fee.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    return {'items': items, 'total': total, 'pages': pages, 'counts': counts, 'total_fee': float(rounded)}

