import json
import os
import zipfile

def normalize_save(data: dict) -> dict:
    if not isinstance(data, dict):
        raise ValueError('invalid save')
    required = {'player', 'updated', 'level', 'score', 'items'}
    if set(data) != required:
        raise ValueError('invalid save')
    if not isinstance(data['player'], str) or not data['player']:
        raise ValueError('invalid save')
    for key in ('updated', 'level', 'score'):
        if isinstance(data[key], bool) or not isinstance(data[key], int) or data[key] < 0:
            raise ValueError('invalid save')
    if not isinstance(data['items'], list) or not all((isinstance(x, str) for x in data['items'])):
        raise ValueError('invalid save')
    return {'player': data['player'], 'updated': data['updated'], 'level': data['level'], 'score': data['score'], 'items': sorted(set(data['items']))}

def merge_save_records(records: list[dict]) -> list[dict]:
    chosen = {}
    for record in records:
        item = normalize_save(record)
        key = (item['updated'], item['level'], item['score'], item['items'])
        old = chosen.get(item['player'])
        if old is None or key > (old['updated'], old['level'], old['score'], old['items']):
            chosen[item['player']] = item
    return sorted(chosen.values(), key=lambda x: (-x['updated'], x['player']))

def sync_save_archive(archive_path: str, base_dir: str) -> dict:
    staging = os.path.join(base_dir, 'incoming')
    os.makedirs(staging, exist_ok=True)
    records = []
    with zipfile.ZipFile(archive_path) as archive:
        base = os.path.realpath(staging)
        for info in archive.infolist():
            if info.is_dir() or not info.filename.endswith('.json'):
                continue
            target = os.path.realpath(os.path.join(staging, info.filename))
            if os.path.commonpath((base, target)) != base:
                raise ValueError('invalid archive path')
            os.makedirs(os.path.dirname(target), exist_ok=True)
            with archive.open(info) as source, open(target, 'wb') as destination:
                destination.write(source.read())
            try:
                with open(target, 'r', encoding='utf-8') as stream:
                    records.append(normalize_save(json.load(stream)))
            except (OSError, UnicodeError, json.JSONDecodeError, TypeError):
                raise ValueError('invalid save file')
    return {'saves': merge_save_records(records)}

