from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from lxml import etree

def extract_purchase_orders(xml_text: str, offset: int=0, limit: int | None=None) -> list[dict]:
    if not isinstance(offset, int) or offset < 0:
        raise ValueError('invalid offset')
    if limit is not None and (not isinstance(limit, int) or limit <= 0):
        raise ValueError('invalid limit')
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml_text.encode('utf-8'), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'purchase_orders':
        raise ValueError('invalid root')
    orders = []
    try:
        for order in root.findall('order'):
            required = ('id', 'supplier', 'status', 'currency')
            if any((order.get(name) is None for name in required)):
                raise ValueError('missing order attribute')
            total = Decimal('0')
            for line in order.findall('line'):
                quantity = int(line.attrib['quantity'])
                if quantity < 0:
                    raise ValueError('negative quantity')
                total += Decimal(line.attrib['unit_price']) * quantity
            if order.get('status') == 'approved':
                total = total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
                orders.append({'id': order.get('id'), 'supplier': order.get('supplier'), 'currency': order.get('currency'), 'total': format(total, '.2f')})
    except (KeyError, ValueError, InvalidOperation, TypeError) as exc:
        raise ValueError('invalid order') from exc
    orders.sort(key=lambda item: (-Decimal(item['total']), item['id']))
    return orders[offset:] if limit is None else orders[offset:offset + limit]

