def signed(payload, key=b'company-key'):
    digest = hmac.new(key, payload.encode('utf-8'), hashlib.sha256).hexdigest()
    return 'v1=' + digest


def test_parse_signature_valid_and_strict():
    value = 'v1=' + 'a1' * 32
    assert parse_callback_signature(value) == 'a1' * 32
    for bad in ['v1=' + 'A1' * 32, 'v1=' + 'a1' * 31, 'v2=' + 'a1' * 32,
                ' v1=' + 'a1' * 32, 'v1=' + 'a1' * 32 + ' ', 'v1=x' + 'a1' * 31,
                'v1=' + 'a1' * 32 + ',v1=' + 'a1' * 32, None]:
        with pytest.raises(ValueError):
            parse_callback_signature(bad)


def test_accepts_unicode_and_counts_scalar_and_choices():
    payload = json.dumps({'survey_id': 's-9', 'response_id': 'r-1', 'submitted_at': 1700,
                          'answers': {'q2': ['yes', 'no'], 'q1': '東京'}},
                         ensure_ascii=False, separators=(',', ':'))
    state = {'seen': set(), 'totals': {}}
    result = process_survey_callback(payload, signed(payload), b'company-key', state)
    assert result == {'status': 'accepted', 'survey_id': 's-9', 'response_id': 'r-1',
                      'answered': 3, 'totals': {'q1': 1, 'q2': 2}}
    assert state == {'seen': {'r-1'}, 'totals': {'s-9': {'q1': 1, 'q2': 2}}}


def test_duplicate_does_not_change_state_or_return_alias():
    payload = json.dumps({'survey_id': 's', 'response_id': 'r', 'submitted_at': 1,
                          'answers': {'b': 2, 'a': 1}}, separators=(',', ':'))
    state = {'seen': {'r'}, 'totals': {'s': {'a': 4}}}
    before = {'seen': set(state['seen']), 'totals': {'s': dict(state['totals']['s'])}}
    result = process_survey_callback(payload, signed(payload), b'company-key', state)
    assert result == {'status': 'duplicate', 'survey_id': 's', 'response_id': 'r'}
    assert state == before


def test_accumulates_surveys_and_returns_sorted_copy():
    state = {'seen': set(), 'totals': {'old': {'z': 7}}}
    payload = json.dumps({'survey_id': 's', 'response_id': 'one', 'submitted_at': 2,
                          'answers': {'z': ['x', 'y'], 'a': 4}}, separators=(',', ':'))
    out = process_survey_callback(payload, signed(payload), b'company-key', state)
    assert out['totals'] == {'a': 1, 'z': 2}
    assert list(out['totals']) == ['a', 'z']
    out['totals']['a'] = 99
    assert state['totals']['s'] == {'a': 1, 'z': 2}
    assert state['totals']['old'] == {'z': 7}


def test_bad_signature_and_bad_json_do_not_mutate():
    state = {'seen': set(), 'totals': {}}
    with pytest.raises(ValueError):
        process_survey_callback('{}', 'v1=' + '0' * 64, b'company-key', state)
    assert state == {'seen': set(), 'totals': {}}
    payload = '{not json}'
    with pytest.raises(ValueError):
        process_survey_callback(payload, signed(payload), b'company-key', state)
    assert state == {'seen': set(), 'totals': {}}


def test_rejects_invalid_payload_shapes():
    base = {'survey_id': 's', 'response_id': 'r', 'submitted_at': 1, 'answers': {}}
    cases = [
        {**base, 'extra': 1}, {**base, 'survey_id': ''}, {**base, 'response_id': 3},
        {**base, 'submitted_at': True}, {**base, 'answers': []},
        {**base, 'answers': {'': 'x'}}, {**base, 'answers': {'q': []}},
        {**base, 'answers': {'q': True}}, {**base, 'answers': {'q': None}},
        {**base, 'answers': {'q': [1]}}, {**base, 'answers': {'q': float('inf')}}
    ]
    state = {'seen': set(), 'totals': {}}
    for item in cases:
        payload = json.dumps(item, allow_nan=False, separators=(',', ':')) if item.get('answers') != {'q': float('inf')} else '{"survey_id":"s","response_id":"r","submitted_at":1,"answers":{"q":Infinity}}'
        with pytest.raises(ValueError):
            process_survey_callback(payload, signed(payload), b'company-key', state)
    assert state == {'seen': set(), 'totals': {}}


def test_invalid_state_is_rejected():
    payload = json.dumps({'survey_id': 's', 'response_id': 'r', 'submitted_at': 1,
                          'answers': {'q': 'x'}}, separators=(',', ':'))
    for state in [{'seen': [], 'totals': {}}, {'seen': set(), 'totals': []},
