import hashlib
import hmac
import json
import math
import re

def parse_callback_signature(value: str) -> str:
    if not isinstance(value, str) or re.fullmatch('v1=[0-9a-f]{64}', value) is None:
        raise ValueError('invalid signature')
    return value[3:]

def process_survey_callback(payload: str, signature: str, key: bytes, state: dict) -> dict:
    try:
        supplied = parse_callback_signature(signature)
        expected = hmac.new(key, payload.encode('utf-8'), hashlib.sha256).hexdigest()
    except Exception as exc:
        raise ValueError('invalid callback') from exc
    if not hmac.compare_digest(expected, supplied):
        raise ValueError('invalid callback')
    try:
        obj = json.loads(payload)
        if not isinstance(obj, dict) or set(obj) != {'survey_id', 'response_id', 'submitted_at', 'answers'}:
            raise ValueError()
        sid, rid, stamp, answers = obj.values()
        if not isinstance(sid, str) or not sid or (not isinstance(rid, str)) or (not rid):
            raise ValueError()
        if isinstance(stamp, bool) or not isinstance(stamp, int) or (not isinstance(answers, dict)):
            raise ValueError()
        values = []
        for question, answer in answers.items():
            if not isinstance(question, str) or not question:
                raise ValueError()
            if isinstance(answer, list):
                if not answer or any((not isinstance(x, str) or not x for x in answer)):
                    raise ValueError()
                values.extend(((question, x) for x in answer))
            elif isinstance(answer, str) and answer:
                values.append((question, answer))
            elif isinstance(answer, (int, float)) and (not isinstance(answer, bool)) and math.isfinite(answer):
                values.append((question, answer))
            else:
                raise ValueError()
        if not isinstance(state, dict) or set(state) != {'seen', 'totals'} or (not isinstance(state['seen'], set)) or (not isinstance(state['totals'], dict)):
            raise ValueError()
        if any((not isinstance(k, str) or not isinstance(v, dict) for k, v in state['totals'].items())):
            raise ValueError()
    except Exception as exc:
        raise ValueError('invalid callback') from exc
    if rid in state['seen']:
        return {'status': 'duplicate', 'survey_id': sid, 'response_id': rid}
    current = dict(state['totals'].get(sid, {}))
    for question, _ in values:
        current[question] = current.get(question, 0) + 1
    state['seen'].add(rid)
    state['totals'][sid] = current
    ordered = {k: current[k] for k in sorted(current)}
    return {'status': 'accepted', 'survey_id': sid, 'response_id': rid, 'answered': len(values), 'totals': ordered}

