import math
import tempfile
from pathlib import Path

def write_log(contents):
    directory = tempfile.TemporaryDirectory()
    path = Path(directory.name) / 'events.txt'
    path.write_text(contents, encoding='utf-8')
    return (directory, str(path))

def test_aggregates_and_orders_feeders():
    directory, path = write_log('F2,2025-01-01T00:00:00,4.25\nF1,2025-01-01T00:01:00,3.00\nF2,2025-01-01T00:02:00,1.75\nF1,2025-01-01T00:03:00,2.00\n')
    try:
        assert rank_response_events(path, 0, 10) == [('F2', 6.0), ('F1', 5.0)]
    finally:
        directory.cleanup()

def test_threshold_is_inclusive_and_limit_is_applied_after_ordering():
    directory, path = write_log('A,one,5\nB,two,7\nC,three,9\nA,four,1\n')
    try:
        assert rank_response_events(path, 5, 2) == [('C', 9.0), ('B', 7.0)]
    finally:
        directory.cleanup()

