import subprocess

def rank_response_events(path: str, minimum_kw: float, limit: int) -> list[tuple[str, float]]:
    if not isinstance(minimum_kw, (int, float)) or isinstance(minimum_kw, bool) or (not math.isfinite(minimum_kw)) or (minimum_kw < 0):
        raise ValueError('invalid minimum')
    if not isinstance(limit, int) or isinstance(limit, bool) or limit <= 0:
        raise ValueError('invalid limit')
    result = subprocess.run(['sort', '-t,', '-k1,1', path], capture_output=True, text=True, check=True)
    totals = {}
    for raw in result.stdout.splitlines():
        if not raw.strip():
            continue
        fields = raw.split(',')
        if len(fields) != 3:
            raise ValueError('malformed record')
        feeder, timestamp, value = (field.strip() for field in fields)
        if not feeder or not timestamp:
            raise ValueError('malformed record')
        try:
            kw = float(value)
        except ValueError as exc:
            raise ValueError('malformed record') from exc
        if not math.isfinite(kw) or kw < 0:
            raise ValueError('malformed record')
        if kw >= minimum_kw:
            totals[feeder] = totals.get(feeder, 0.0) + kw
    ordered = sorted(totals.items(), key=lambda item: (-item[1], item[0]))
    return [(feeder, round(total, 2)) for feeder, total in ordered[:limit]]

