import sqlite3

def distribution_summary(conn: sqlite3.Connection, campaign_id: int, status: str | None=None, sort_by: str='region', descending: bool=False, page: int=1, page_size: int=10) -> list[dict]:
    statuses = {'pending', 'completed', 'cancelled'}
    columns = {'region': 'region', 'response_count': 'response_count', 'average_score': 'average_score', 'completion_rate': 'completion_rate'}
    if status is not None and status not in statuses:
        raise ValueError('invalid status')
    if sort_by not in columns:
        raise ValueError('invalid sort field')
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid page')
    direction = 'DESC' if descending else 'ASC'
    order = f'{columns[sort_by]} {direction}'
    if sort_by == 'region':
        order = f'region {direction}'
    else:
        order += ', region ASC'
    query = "SELECT region, COUNT(*) AS response_count, ROUND(AVG(score), 2) AS average_score, SUM(CASE WHEN status = 'completed' THEN 1 ELSE 0 END) AS completed_count, ROUND(100.0 * SUM(CASE WHEN status = 'completed' THEN 1 ELSE 0 END) / COUNT(*), 2) AS completion_rate FROM survey_responses WHERE campaign_id = ?"
    values = [campaign_id]
    if status is not None:
        query += ' AND status = ?'
        values.append(status)
    query += f' GROUP BY region ORDER BY {order} LIMIT ? OFFSET ?'
    values.extend([page_size, (page - 1) * page_size])
    rows = conn.execute(query, values).fetchall()
    return [dict(zip(('region', 'response_count', 'average_score', 'completed_count', 'completion_rate'), row)) for row in rows]

