import os
import subprocess
_STATUSES = ('pending', 'running', 'done', 'failed')

def parse_job_record(line: str) -> dict[str, object]:
    fields = line.rstrip('\r\n').split('\t')
    if len(fields) != 5 or not fields[0] or fields[4] not in _STATUSES:
        raise ValueError('invalid job record')
    try:
        priority = int(fields[1], 10)
        submitted = int(fields[2], 10)
        cores = int(fields[3], 10)
    except ValueError as exc:
        raise ValueError('invalid job record') from exc
    if submitted < 0 or cores < 0:
        raise ValueError('invalid job record')
    return {'id': fields[0], 'priority': priority, 'submitted': submitted, 'cores': cores, 'status': fields[4]}

def read_queue(path: str, limit: int | None=None) -> list[dict[str, object]]:
    if isinstance(limit, bool) or (limit is not None and (not isinstance(limit, int) or limit < 0)):
        raise ValueError('invalid limit')
    env = os.environ.copy()
    env['LC_ALL'] = 'C'
    result = subprocess.run(['sort', '-t', '\t', '-k2,2nr', '-k3,3n', '-k1,1', '--', path], check=True, capture_output=True, text=True, env=env)
    records = []
    seen = set()
    for line in result.stdout.splitlines():
        record = parse_job_record(line)
        if record['id'] in seen:
            raise ValueError('duplicate job identifier')
        seen.add(record['id'])
        records.append(record)
    if limit is not None:
        records = records[:limit]
    return records

def queue_summary(path: str, limit: int | None=None) -> dict[str, object]:
    records = read_queue(path, limit)
    counts = {status: 0 for status in _STATUSES}
    for record in records:
        counts[record['status']] += 1
    return {'jobs': len(records), 'cores': sum((record['cores'] for record in records)), 'by_status': counts}

