    output = []
    for raw in result.stdout.splitlines():
        if not raw.strip():
            continue
        fields = raw.split(',')
        if len(fields) != 3:
            raise ValueError('invalid row')
        try:
            timestamp = int(fields[0].strip())
            power = float(fields[1].strip())
            duration = float(fields[2].strip())
        except ValueError as exc:
            raise ValueError('invalid row') from exc
        if not math.isfinite(power) or not math.isfinite(duration) or duration <= 0:
            raise ValueError('invalid row')
        requested_energy = power * duration
        if requested_energy >= 0:
            accepted_energy = min(requested_energy, capacity_kwh - soc)
        else:
            accepted_energy = max(requested_energy, -soc)
        soc += accepted_energy
        output.append((timestamp, round(accepted_energy / duration, 3), round(soc, 3)))
    return output

