def read_shipments(path: str) -> list[dict]:
    result = subprocess.run(['cat', path], capture_output=True, text=True)
    if result.returncode != 0:
        raise FileNotFoundError(path)
    rows = list(csv.DictReader(io.StringIO(result.stdout)))
    expected = ['id', 'destination', 'region', 'weight', 'status', 'day']
    if not rows and result.stdout.strip() == '':
        raise ValueError('invalid header')
    reader = csv.DictReader(io.StringIO(result.stdout))
    if reader.fieldnames != expected:
        raise ValueError('invalid header')
    output = []
    seen = set()
    for row in rows:
        if None in row or any((row[k] == '' for k in expected)):
            raise ValueError('invalid row')
        if row['id'] in seen:
            raise ValueError('duplicate id')
        seen.add(row['id'])
        try:
            weight = int(row['weight'])
        except ValueError:
            raise ValueError('invalid weight')
        if weight <= 0 or row['status'] not in {'delivered', 'in_transit', 'delayed'}:
            raise ValueError('invalid row')
        try:
            date.fromisoformat(row['day'])
        except ValueError:
            raise ValueError('invalid date')
        output.append({'id': row['id'], 'destination': row['destination'], 'region': row['region'], 'weight': weight, 'status': row['status'], 'day': row['day']})
    return output

def summarize_shipments(path: str, region: str='', limit: int=10) -> list[dict]:
    if limit < 0:
        raise ValueError('negative limit')
    groups = {}
    for row in read_shipments(path):
        if region and row['region'] != region:
            continue
        item = groups.setdefault(row['destination'], [0, 0, 0, 0])
        item[0] += 1
        item[1] += row['weight']
        if row['status'] == 'delivered':
            item[2] += row['weight']
        if row['status'] == 'delayed':
            item[3] += 1
    ordered = sorted(groups.items(), key=lambda x: (-x[1][1], -x[1][2], x[0]))
    return [{'destination': k, 'shipment_count': v[0], 'total_weight': v[1], 'delivered_weight': v[2], 'delayed_count': v[3]} for k, v in ordered[:limit]]

