        raise ValueError('negative limit')
    groups = {}
    for row in read_shipments(path):
        if region and row['region'] != region:
            continue
        item = groups.setdefault(row['destination'], [0, 0, 0, 0])
        item[0] += 1
        item[1] += row['weight']
        if row['status'] == 'delivered':
            item[2] += row['weight']
        if row['status'] == 'delayed':
            item[3] += 1
    ordered = sorted(groups.items(), key=lambda x: (-x[1][1], -x[1][2], x[0]))
    return [{'destination': k, 'shipment_count': v[0], 'total_weight': v[1], 'delivered_weight': v[2], 'delayed_count': v[3]} for k, v in ordered[:limit]]

