_STATUSES = ('draft', 'reviewed', 'final', 'archived')
_SORTS = {'title': 'title', 'owner': 'owner', 'status': 'status', 'created': 'created_at', 'updated': 'updated_at'}

def _now():
    return datetime.now(timezone.utc).isoformat(timespec='microseconds')

def create_schema(conn: sqlite3.Connection) -> None:
    conn.execute('CREATE TABLE IF NOT EXISTS documents (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, owner TEXT NOT NULL, content TEXT NOT NULL, tags TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL)')
    conn.commit()

def add_document(conn: sqlite3.Connection, title: str, owner: str, content: str, tags: list[str] | tuple[str, ...]=()) -> int:
    title = title.strip()
    owner = owner.strip()
    if not title or not owner:
        raise ValueError('title and owner are required')
    clean = []
    for tag in tags:
        tag = tag.strip()
        if tag and tag not in clean:
            clean.append(tag)
    stamp = _now()
    cur = conn.execute('INSERT INTO documents(title, owner, content, tags, status, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?)', (title, owner, content, '\x1f'.join(clean), 'draft', stamp, stamp))
    conn.commit()
    return cur.lastrowid

def find_documents(conn: sqlite3.Connection, text: str='', owner: str | None=None, status: str | None=None, sort_by: str='updated', descending: bool=False, limit: int=50) -> list[dict]:
    if status is not None and status not in _STATUSES:
        raise ValueError('invalid status')
    if sort_by not in _SORTS:
        raise ValueError('invalid sort')
    if isinstance(limit, bool) or not isinstance(limit, int) or (not 1 <= limit <= 100):
        raise ValueError('invalid limit')
    clauses = []
    args = []
    if text:
        clauses.append('(lower(title) LIKE lower(?) OR lower(content) LIKE lower(?))')
