    if owner is not None:
        clauses.append('owner = ?')
        args.append(owner)
    if status is not None:
        clauses.append('status = ?')
        args.append(status)
    where = ' WHERE ' + ' AND '.join(clauses) if clauses else ''
    direction = 'DESC' if descending else 'ASC'
    sql = 'SELECT id, title, owner, content, tags, status FROM documents' + where + ' ORDER BY ' + _SORTS[sort_by] + ' ' + direction + ', id ASC LIMIT ?'
    args.append(limit)
    rows = conn.execute(sql, args).fetchall()
    result = []
    for ident, title, owner_value, content, tags, state in rows:
        excerpt = re.sub('\\s+', ' ', content).strip()
        if len(excerpt) > 80:
            excerpt = excerpt[:80] + '…'
        result.append({'id': ident, 'title': title, 'owner': owner_value, 'status': state, 'tags': tags.split('\x1f') if tags else [], 'excerpt': excerpt})
    return result

