    if status not in _STATUSES:
        raise ValueError('invalid status')
    cur = conn.execute('UPDATE documents SET status = ?, updated_at = ? WHERE id = ?', (status, _now(), document_id))
    conn.commit()
    return cur.rowcount == 1

