import csv
import math
import os

def rank_scores(base_dir: str, relative_name: str, min_score: float=0.0) -> list[dict[str, object]]:
    if not math.isfinite(min_score) or min_score < 0:
        raise ValueError('invalid minimum')
    root = os.path.realpath(base_dir)
    candidate = os.path.realpath(os.path.join(root, relative_name))
    if os.path.commonpath((root, candidate)) != root:
        raise ValueError('invalid file name')
    best = {}
    with open(candidate, 'r', encoding='utf-8', newline='') as handle:
        reader = csv.DictReader(handle)
        if reader.fieldnames != ['robot', 'score', 'penalty']:
            raise ValueError('invalid header')
        for row in reader:
            robot = row['robot'].strip()
            if not robot:
                raise ValueError('invalid robot')
            try:
                score = float(row['score'])
                penalty = float(row['penalty'])
            except (TypeError, ValueError):
                raise ValueError('invalid number')
            if not math.isfinite(score) or not math.isfinite(penalty) or score < 0 or (penalty < 0):
                raise ValueError('invalid number')
            total = score - penalty
            if robot not in best or total > best[robot]:
                best[robot] = total
    selected = [(robot, total) for robot, total in best.items() if total >= min_score]
    selected.sort(key=lambda item: (-item[1], item[0]))
    return [{'robot': robot, 'score': round(total, 2)} for robot, total in selected]

