def summarize_imagery(requester: dict, scenes: list[dict], page: int, page_size: int, max_cloud_cover: float=100.0) -> dict:
    if not isinstance(requester, dict) or not isinstance(requester.get('id'), str) or (not requester['id']):
        raise ValueError('invalid requester')
    if not isinstance(scenes, list) or not isinstance(page, int) or isinstance(page, bool) or (page < 1):
        raise ValueError('invalid input')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    if isinstance(max_cloud_cover, bool) or not isinstance(max_cloud_cover, (int, float)) or (not 0 <= max_cloud_cover <= 100):
        raise ValueError('invalid threshold')
    roles = requester.get('roles', [])
    if not isinstance(roles, list):
        raise ValueError('invalid roles')
    admin = 'imagery_admin' in roles
    checked = []
    for item in scenes:
        if not isinstance(item, dict) or any((k not in item for k in ('id', 'owner_id', 'captured_at', 'cloud_cover', 'area_km2'))):
            raise ValueError('invalid scene')
        if not isinstance(item['id'], str) or not isinstance(item['owner_id'], str) or (not item['id']):
            raise ValueError('invalid scene')
        try:
            captured = datetime.fromisoformat(item['captured_at'])
        except (TypeError, ValueError):
            raise ValueError('invalid timestamp')
        cloud = item['cloud_cover']
        area = item['area_km2']
        if isinstance(cloud, bool) or not isinstance(cloud, (int, float)) or (not 0 <= cloud <= 100):
            raise ValueError('invalid cloud cover')
        if isinstance(area, bool) or not isinstance(area, (int, float)) or area < 0:
            raise ValueError('invalid area')
        if not admin and item['owner_id'] != requester['id']:
            raise PermissionError('scene access denied')
        if cloud <= max_cloud_cover:
            checked.append((captured, item))
    checked.sort(key=lambda pair: (-pair[0].timestamp(), pair[1]['id']))
    total = len(checked)
    area_sum = sum((item['area_km2'] for _, item in checked))
    cloud_avg = sum((item['cloud_cover'] for _, item in checked)) / total if total else None
    start = (page - 1) * page_size
    output = [{k: item[k] for k in ('id', 'captured_at', 'cloud_cover', 'area_km2')} for _, item in checked[start:start + page_size]]
    return {'total': total, 'page': page, 'page_size': page_size, 'scenes': output, 'total_area_km2': round(area_sum, 2), 'average_cloud_cover': round(cloud_avg, 2) if cloud_avg is not None else None}

