import datetime
import json
import os
from pathlib import Path
import zipfile

def extract_bundle(archive_path: str, destination: str) -> list[str]:
    base = Path(destination).resolve()
    base.mkdir(parents=True, exist_ok=True)
    result = []
    with zipfile.ZipFile(archive_path) as archive:
        for info in archive.infolist():
            name = info.filename
            if name.endswith('/'):
                (base / name).resolve().mkdir(parents=True, exist_ok=True)
                continue
            target = (base / name).resolve()
            try:
                target.relative_to(base)
            except ValueError:
                raise ValueError('invalid archive member')
            target.parent.mkdir(parents=True, exist_ok=True)
            with archive.open(info) as source, open(target, 'wb') as output:
                output.write(source.read())
            result.append(name.replace('\\', '/'))
    return sorted(result)

def load_manifest(destination: str) -> list[dict]:
    try:
        with open(os.path.join(destination, 'manifest.json'), encoding='utf-8') as f:
            value = json.load(f)
    except (OSError, json.JSONDecodeError) as exc:
        raise ValueError('invalid manifest') from exc
    if not isinstance(value, dict) or not isinstance(value.get('applications'), list):
        raise ValueError('invalid manifest')
    result = []
    for item in value['applications']:
        if not isinstance(item, dict) or not all((isinstance(item.get(k), str) for k in ('merchant_id', 'submitted_at', 'status'))):
            raise ValueError('invalid application')
        if item['status'] not in {'pending', 'approved', 'rejected'}:
            raise ValueError('invalid application')
        try:
            datetime.date.fromisoformat(item['submitted_at'])
        except (TypeError, ValueError):
            raise ValueError('invalid application')
        volume = item.get('monthly_volume')
        if isinstance(volume, bool) or not isinstance(volume, (int, float)) or volume < 0:
            raise ValueError('invalid application')
        result.append(item)
    return sorted(result, key=lambda x: (x['submitted_at'], x['merchant_id']))

def rank_merchants(applications: list[dict], limit: int) -> list[str]:
    if isinstance(limit, bool) or not isinstance(limit, int) or limit < 0:
        raise ValueError('invalid limit')
    totals = {}
    for item in applications:
        if not isinstance(item, dict) or not all((k in item for k in ('merchant_id', 'submitted_at', 'status', 'monthly_volume'))):
            raise ValueError('invalid application')
        if not isinstance(item['merchant_id'], str) or item['status'] not in {'pending', 'approved', 'rejected'}:
            raise ValueError('invalid application')
        volume = item['monthly_volume']
        if isinstance(volume, bool) or not isinstance(volume, (int, float)) or volume < 0:
            raise ValueError('invalid application')
        if item['status'] == 'approved':
            total, count = totals.get(item['merchant_id'], (0, 0))
            totals[item['merchant_id']] = (total + volume, count + 1)
    ordered = sorted(totals, key=lambda m: (-totals[m][0], -totals[m][1], m))
    return ordered[:limit]

