def _eval(node, variables):
    if isinstance(node, ast.Expression):
        return _eval(node.body, variables)
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, complex)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in variables:
            raise ValueError('unknown variable')
        return variables[node.id]
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
        value = _eval(node.operand, variables)
        return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
    if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
        left, right = (_eval(node.left, variables), _eval(node.right, variables))
        if isinstance(node.op, ast.Add):
            return left + right
        if isinstance(node.op, ast.Sub):
            return left - right
        if isinstance(node.op, ast.Mult):
            return left * right
        return left / right
    if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
        value = _eval(node.values[0], variables)
        for item in node.values[1:]:
            if isinstance(node.op, ast.And) and (not value):
                return value
            if isinstance(node.op, ast.Or) and value:
                return value
            value = _eval(item, variables)
