def parse_bus_routes(xml_text: str) -> list[dict[str, object]]:
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode('utf-8'), parser)
    except (etree.XMLSyntaxError, UnicodeError) as exc:
        raise ValueError('invalid XML') from exc
    result = []
    for route in root.iter('route'):
        route_id = (route.get('id') or '').strip()
        bus = (route.get('bus') or '').strip()
        if not route_id or not bus:
            raise ValueError('route requires id and bus')
        stops = []
        for child in route:
            if child.tag == 'stop':
                stops.append((child.text or '').strip())
        result.append({'id': route_id, 'bus': bus, 'stops': stops})
    return result

