import secrets
_ALPHABET = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
_ESCAPABLE = {'\\', '|', ';', '='}

def generate_collection_id(prefix: str='ev', length: int=24) -> str:
    if isinstance(length, bool) or not isinstance(length, int) or (not 16 <= length <= 64):
        raise ValueError('invalid length')
    if not isinstance(prefix, str) or not prefix or any((c not in 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_' for c in prefix)):
        raise ValueError('invalid prefix')
    return prefix + '_' + ''.join((secrets.choice(_ALPHABET) for _ in range(length)))

def _split_escaped(value: str, separator: str) -> list[str]:
    parts = []
    current = []
    i = 0
    while i < len(value):
        char = value[i]
        if char == '\\':
            if i + 1 == len(value) or value[i + 1] not in _ESCAPABLE:
                raise ValueError('invalid escape')
            current.append(value[i + 1])
            i += 2
        elif char == separator:
            parts.append(''.join(current))
            current = []
            i += 1
        else:
            current.append(char)
            i += 1
    parts.append(''.join(current))
    return parts

def parse_evidence(text: str) -> list[dict]:
    if not isinstance(text, str):
        raise ValueError('text must be a string')
    output = []
    for raw in text.splitlines():
        if not raw:
            continue
        fields = _split_escaped(raw, '|')
        if len(fields) != 4:
            raise ValueError('wrong field count')
        timestamp, source, event, raw_attributes = fields
        if not timestamp.isdecimal() or not source or (not event):
            raise ValueError('invalid record')
        attributes = {}
        if raw_attributes:
            for item in _split_escaped(raw_attributes, ';'):
                pieces = _split_escaped(item, '=')
                if len(pieces) != 2 or not pieces[0] or pieces[0] in attributes:
                    raise ValueError('invalid attributes')
                attributes[pieces[0]] = pieces[1]
        output.append({'timestamp': int(timestamp), 'source': source, 'event': event, 'attributes': attributes})
