from lxml import etree

def parse_playlist(xml_text: str, genre: str | None=None, offset: int=0, limit: int=20) -> dict:
    if isinstance(offset, bool) or not isinstance(offset, int) or offset < 0:
        raise ValueError('invalid offset')
    if isinstance(limit, bool) or not isinstance(limit, int) or limit < 0:
        raise ValueError('invalid limit')
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml_text.encode('utf-8'), parser=parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'playlist' or 'name' not in root.attrib:
        raise ValueError('invalid playlist')
    items = []
    for node in root:
        if node.tag != 'track':
            continue
        required = ('title', 'artist', 'genre', 'duration')
        if any((key not in node.attrib for key in required)):
            raise ValueError('invalid track')
        try:
            duration = int(node.attrib['duration'])
        except Exception as exc:
            raise ValueError('invalid duration') from exc
        if duration < 0 or str(duration) != node.attrib['duration']:
            raise ValueError('invalid duration')
        item = {'title': node.attrib['title'], 'artist': node.attrib['artist'], 'genre': node.attrib['genre'], 'duration': duration}
        if genre is None or item['genre'].casefold() == genre.casefold():
            items.append(item)
    items.sort(key=lambda item: item['duration'], reverse=True)
    return {'name': root.attrib['name'], 'count': len(items), 'total_duration': sum((item['duration'] for item in items)), 'tracks': items[offset:offset + limit]}

