import pytest

from solution import index_documents


def signed(payload, secret):
    return hmac.new(secret.encode(), payload.encode(), hashlib.sha256).hexdigest()


def make_payload(documents):
    return json.dumps({"documents": documents}, separators=(",", ":"))


def test_indexes_matches_and_counts_categories():
    payload = make_payload([
        {"id": "b", "title": "Python search", "body": "Python tools", "category": "tech"},
        {"id": "a", "title": "Python", "body": "Cooking recipes", "category": "food"},
        {"id": "c", "title": "Other", "body": "Nothing relevant", "category": "tech"},
    ])
    result = index_documents(payload, signed(payload, "key"), "key", "python", 1, 10)
    assert result == {
        "total": 2,
        "results": [
            {"id": "b", "title": "Python search", "category": "tech", "score": 2},
            {"id": "a", "title": "Python", "category": "food", "score": 1},
        ],
        "categories": {"food": 1, "tech": 1},
    }


def test_sorting_ties_and_query_terms():
    payload = make_payload([
        {"id": "z", "title": "Red blue", "body": "", "category": "x"},
        {"id": "a", "title": "BLUE red", "body": "", "category": "x"},
        {"id": "m", "title": "red", "body": "blue blue", "category": "y"},
    ])
    result = index_documents(payload, signed(payload, "s"), "s", "RED blue", 1, 10)
    assert [item["id"] for item in result["results"]] == ["m", "a", "z"]
    assert [item["score"] for item in result["results"]] == [3, 2, 2]


def test_pagination_is_one_based():
    docs = [
        {"id": str(i), "title": "apple", "body": "", "category": "c"}
        for i in range(1, 6)
    ]
    payload = make_payload(docs)
    signature = signed(payload, "k")
    assert [x["id"] for x in index_documents(payload, signature, "k", "apple", 1, 2)["results"]] == ["1", "2"]
    assert [x["id"] for x in index_documents(payload, signature, "k", "apple", 3, 2)["results"]] == ["5"]
    assert index_documents(payload, signature, "k", "apple", 4, 2)["results"] == []


