import hashlib
import hmac
import json
import re

def index_documents(payload: str, signature: str, secret: str, query: str, page: int, page_size: int) -> dict:
    expected = hmac.new(secret.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise PermissionError('invalid signature')
    try:
        data = json.loads(payload)
    except json.JSONDecodeError as exc:
        raise ValueError('invalid JSON') from exc
    if not isinstance(data, dict) or not isinstance(data.get('documents'), list):
        raise ValueError('documents must be a list')
    if not isinstance(query, str) or not query.strip() or isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError('invalid arguments')
    terms = query.casefold().split()
    matches = []
    for doc in data['documents']:
        if not isinstance(doc, dict) or any((not isinstance(doc.get(k), str) for k in ('id', 'title', 'body', 'category'))):
            raise ValueError('invalid document')
        text = (doc['title'] + ' ' + doc['body']).casefold()
        words = re.findall('\\S+', text)
        counts = {term: words.count(term) for term in terms}
        if all((counts[term] for term in terms)):
            score = sum(counts.values())
            matches.append((score, doc))
    matches.sort(key=lambda item: (-item[0], item[1]['id']))
    categories = {}
    for _, doc in matches:
        categories[doc['category']] = categories.get(doc['category'], 0) + 1
    categories = dict(sorted(categories.items()))
    start = (page - 1) * page_size
    results = [{'id': doc['id'], 'title': doc['title'], 'category': doc['category'], 'score': score} for score, doc in matches[start:start + page_size]]
    return {'total': len(matches), 'results': results, 'categories': categories}

