    if not isinstance(line, str):
        raise ValueError('line must be text')
    timestamp, item, sender, receiver, note = _fields(line)
    if not item or not sender or (not receiver):
        raise ValueError('missing required field')
    if not timestamp.endswith('Z'):
        raise ValueError('timestamp must be UTC')
    try:
        parsed = datetime.fromisoformat(timestamp[:-1])
    except ValueError as exc:
        raise ValueError('invalid timestamp') from exc
    if parsed.tzinfo is not None or parsed.second > 59:
        raise ValueError('invalid timestamp')
    parsed = parsed.replace(tzinfo=timezone.utc)
    return {'timestamp': parsed, 'item_id': item, 'released_by': sender, 'received_by': receiver, 'note': note}

