    grouped: dict[str, list[tuple[int, dict[str, object]]]] = {}
    for index, line in enumerate(lines):
        if not line.strip():
            continue
        record = parse_custody_line(line)
        grouped.setdefault(record['item_id'], []).append((index, record))
    ordered = []
    for item, records in grouped.items():
        records.sort(key=lambda pair: (pair[1]['timestamp'], pair[0]))
        previous = None
        transfers = []
        for _, record in records:
            if previous is not None and previous != record['released_by']:
                raise ValueError('inconsistent custody chain')
            previous = record['received_by']
            transfers.append({'timestamp': record['timestamp'], 'from': record['released_by'], 'to': record['received_by']})
