from solution import process_proposal_webhook
import hashlib
import hmac
import json
import pytest


def make_payload(obj):
    return json.dumps(obj, ensure_ascii=False, sort_keys=True, separators=(",", ":"))


def sign(payload, secret):
    return hmac.new(secret.encode(), payload.encode(), hashlib.sha256).hexdigest()


def test_valid_payload_normalizes_and_sorts_bids():
    obj = {"firm": "Northline Studio", "bids": [{"architect": "Zed", "fee": 12000, "status": "submitted"}, {"architect": "Aster", "fee": 15000.5, "status": "shortlisted"}, {"architect": "Briar", "fee": 15000.5, "status": "shortlisted"}], "proposal_id": "P-104"}
    payload = json.dumps(obj, indent=2)
    result = process_proposal_webhook(payload, sign(make_payload(obj), "studio-key"), "studio-key")
    assert result == {"proposal_id": "P-104", "firm": "Northline Studio", "accepted_count": 2, "total_fee": 42001, "architects": [{"architect": "Aster", "fee": 15000.5, "status": "shortlisted"}, {"architect": "Briar", "fee": 15000.5, "status": "shortlisted"}, {"architect": "Zed", "fee": 12000, "status": "submitted"}]}


def test_empty_bids_are_rejected():
    obj = {"proposal_id": "P-1", "firm": "F", "bids": []}
    payload = make_payload(obj)
