from lxml import etree
from datetime import datetime, timezone

def _time(value):
    if not isinstance(value, str) or not value.endswith('Z'):
        raise ValueError('invalid timestamp')
    try:
        result = datetime.fromisoformat(value[:-1] + '+00:00')
    except ValueError as exc:
        raise ValueError('invalid timestamp') from exc
    if result.tzinfo != timezone.utc:
        raise ValueError('invalid timestamp')
    return result

def parse_invalidation_feed(xml_text: str) -> list[dict]:
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'feed':
        raise ValueError('invalid root')
    _time(root.get('generated'))
    result = []
    for node in root:
        if node.tag != 'invalidation':
            continue
        path = node.get('path')
        action = node.get('action')
        priority = node.get('priority')
        issued = node.get('issued')
        if not path or not path.startswith('/') or action not in ('purge', 'refresh'):
            raise ValueError('invalid invalidation')
        try:
            priority = int(priority)
        except (TypeError, ValueError) as exc:
            raise ValueError('invalid priority') from exc
        if not 0 <= priority <= 9:
            raise ValueError('invalid priority')
        _time(issued)
        expires = node.get('expires')
        if expires is not None:
            _time(expires)
        tags = set()
        for child in node:
            if child.tag == 'tag':
                value = (child.text or '').strip()
                if not value:
                    raise ValueError('invalid tag')
                tags.add(value)
        result.append({'path': path, 'action': action, 'priority': priority, 'issued': issued, 'expires': expires, 'tags': sorted(tags)})
    return result

def build_invalidation_plan(entries: list[dict], as_of: str) -> list[dict]:
    moment = _time(as_of)
    selected = {}
    for entry in entries:
        if entry['expires'] is not None and _time(entry['expires']) <= moment:
            continue
        old = selected.get(entry['path'])
        if old is None:
            selected[entry['path']] = entry
            continue
        key = (entry['priority'], _time(entry['issued']), entry['action'] == 'purge')
        oldkey = (old['priority'], _time(old['issued']), old['action'] == 'purge')
        if key >= oldkey:
            selected[entry['path']] = entry
    result = [dict(x, tags=list(x['tags'])) for x in selected.values()]
    result.sort(key=lambda x: (-x['priority'], x['path'], -_time(x['issued']).timestamp()))
    return result

