import sqlite3
import datetime
import math

def create_catalog(conn: sqlite3.Connection) -> None:
    conn.execute('CREATE TABLE IF NOT EXISTS specimens (id TEXT PRIMARY KEY, site TEXT NOT NULL, mineral TEXT NOT NULL, depth REAL NOT NULL, collected TEXT NOT NULL, notes TEXT NOT NULL)')
    conn.commit()

def record_specimen(conn: sqlite3.Connection, specimen_id: str, site: str, mineral: str, depth_m: float, collected_on: str, notes: str='') -> None:
    if not all((isinstance(x, str) and x for x in (specimen_id, site, mineral))) or not isinstance(notes, str):
        raise ValueError()
    if not isinstance(depth_m, (int, float)) or isinstance(depth_m, bool) or (not math.isfinite(depth_m)) or (depth_m < 0):
        raise ValueError()
    try:
        date = datetime.date.fromisoformat(collected_on)
    except (TypeError, ValueError):
        raise ValueError()
    conn.execute('INSERT INTO specimens VALUES (?, ?, ?, ?, ?, ?)', (specimen_id, site, mineral, float(depth_m), date.isoformat(), notes))
    conn.commit()

def find_specimens(conn: sqlite3.Connection, text: str='', min_depth: float | None=None, max_depth: float | None=None, sort_by: str='depth', descending: bool=False, limit: int=50) -> list[dict]:
    allowed = {'id', 'site', 'mineral', 'depth', 'collected'}
    if not isinstance(text, str) or sort_by not in allowed or (not isinstance(limit, int)) or isinstance(limit, bool) or (not 1 <= limit <= 100):
        raise ValueError()
    for value in (min_depth, max_depth):
        if value is not None and (not isinstance(value, (int, float)) or isinstance(value, bool) or (not math.isfinite(value))):
            raise ValueError()
    if min_depth is not None and max_depth is not None and (min_depth > max_depth):
        raise ValueError()
    clauses = ['(lower(site) LIKE lower(?) OR lower(mineral) LIKE lower(?) OR lower(notes) LIKE lower(?))']
    params = [f'%{text}%'] * 3
    if min_depth is not None:
        clauses.append('depth >= ?')
        params.append(min_depth)
    if max_depth is not None:
        clauses.append('depth <= ?')
        params.append(max_depth)
    direction = 'DESC' if descending else 'ASC'
    sql = 'SELECT id, site, mineral, depth, collected, notes FROM specimens WHERE ' + ' AND '.join(clauses) + f' ORDER BY {sort_by} {direction}, id ASC LIMIT ?'
    params.append(limit)
    rows = conn.execute(sql, params).fetchall()
    return [dict(zip(('id', 'site', 'mineral', 'depth', 'collected_on', 'notes'), row)) for row in rows]

def site_summary(conn: sqlite3.Connection) -> list[dict]:
    rows = conn.execute('SELECT site, COUNT(*), ROUND(AVG(depth), 3), MAX(depth) FROM specimens GROUP BY site ORDER BY COUNT(*) DESC, site ASC').fetchall()
    return [dict(zip(('site', 'specimen_count', 'average_depth', 'maximum_depth'), row)) for row in rows]

