import hmac
from datetime import date

def _fields(line):
    out = []
    cur = []
    i = 0
    while i < len(line):
        c = line[i]
        if c == '\\':
            i += 1
            if i == len(line) or line[i] not in '\\|':
                raise ValueError('bad escape')
            cur.append(line[i])
        elif c == '|':
            out.append(''.join(cur))
            cur = []
        else:
            cur.append(c)
        i += 1
    out.append(''.join(cur))
    return out

