    if not isinstance(text, str) or not isinstance(secret, bytes) or '\n' not in text:
        raise ValueError('invalid manifest')
    head, payload = text.split('\n', 1)
    h = head.split('|')
    if len(h) != 4 or h[0] != 'MANIFEST' or (not h[1]) or (len(h[3]) != 64):
        raise ValueError('invalid header')
    try:
        date.fromisoformat(h[2])
        expected = bytes.fromhex(h[3])
    except ValueError:
        raise ValueError('invalid header')
    actual = hmac.new(secret, payload.encode(), hashlib.sha256).digest()
    if not hmac.compare_digest(actual, expected) or not payload:
        raise ValueError('invalid digest')
    events = []
    seen = set()
    states = {}
    for line in payload.split('\n'):
        f = _fields(line)
        if len(f) != 6 or any((not f[i] for i in (0, 1, 2, 3))) or f[4] not in ('IN', 'OUT'):
            raise ValueError('invalid event')
        try:
            day = int(f[5])
        except ValueError:
            raise ValueError('invalid day')
        if not 1 <= day <= 31:
            raise ValueError('invalid day')
        if f[0] in seen and f[4] == 'IN':
            raise ValueError('duplicate passenger')
        st = states.get(f[0])
        if f[4] == 'IN':
            if st is not None:
                raise ValueError('invalid state')
            states[f[0]] = (f[2], day)
        else:
            if st is None or day <= st[1] or f[2] != st[0]:
                raise ValueError('invalid state')
            states[f[0]] = (st[0], st[1], day)
        if f[4] == 'IN':
            seen.add(f[0])
        events.append({'id': f[0], 'name': f[1], 'cabin': f[2], 'port': f[3], 'action': f[4], 'day': day})
