        raise ValueError('invalid manifest')
    events = manifest['events']
    if not events:
        raise ValueError('empty manifest')
    ports = {}
    cabins = {}
    people = set()
    for e in events:
        if not isinstance(e, dict) or set(e) != {'id', 'name', 'cabin', 'port', 'action', 'day'}:
            raise ValueError('invalid event')
        ports[e['port']] = ports.get(e['port'], 0) + 1
        if e['action'] == 'IN':
            people.add(e['id'])
            cabins[e['cabin']] = cabins.get(e['cabin'], 0) + 1

    def key(x):
