    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode('utf-8'), parser)
    except (etree.XMLSyntaxError, ValueError) as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'registrations':
        raise ValueError('unexpected root')
    active = []
    total_fees = 0.0
    required = ('id', 'plate', 'make', 'model', 'year', 'fee')
    for node in root.findall('registration'):
        if any((name not in node.attrib for name in required)):
            raise ValueError('missing attribute')
        owner = node.find('owner')
        status = node.find('status')
        if owner is None or status is None:
            raise ValueError('missing child')
        try:
            year = int(node.attrib['year'].strip())
            fee = round(float(node.attrib['fee'].strip()), 2)
        except (TypeError, ValueError) as exc:
            raise ValueError('invalid number') from exc
        if (status.text or '').strip() != 'active':
            continue
        item = {'id': node.attrib['id'], 'plate': node.attrib['plate'], 'owner': ''.join(owner.itertext()).strip(), 'vehicle': node.attrib['make'] + ' ' + node.attrib['model'], 'year': year, 'fee': fee}
        active.append(item)
        total_fees += fee
    active.sort(key=lambda item: (-item['year'], item['plate'], item['id']))
