    if not isinstance(tax_year, int) or isinstance(tax_year, bool) or (not 1 <= tax_year <= 9999):
        raise ValueError('invalid year')
    result = []
    for item in donations:
        try:
            d = _parsed(item)
            if item['status'] == 'settled' and d.year == tax_year:
                result.append(item.copy())
        except (KeyError, TypeError):
            raise ValueError('invalid donation')
    result.sort(key=lambda x: (x['donated_at'], x['id']))
    return result

def annual_totals(donations: list[dict], tax_year: int) -> dict[str, int]:
    totals = {}
    for item in eligible_donations(donations, tax_year):
        if not isinstance(item.get('amount_cents'), int) or isinstance(item['amount_cents'], bool) or item['amount_cents'] <= 0:
            raise ValueError('invalid amount')
        currency = item.get('currency')
        if not isinstance(currency, str):
            raise ValueError('invalid currency')
        totals[currency] = totals.get(currency, 0) + item['amount_cents']
    return {k: totals[k] for k in sorted(totals)}

def build_tax_receipt(requester: dict, donation: dict, existing_receipts: list[dict]) -> dict:
    try:
        d = _parsed(donation)
        amount = donation['amount_cents']
        if donation['status'] != 'settled' or not isinstance(amount, int) or isinstance(amount, bool) or (amount <= 0):
            raise ValueError('invalid donation')
        number = f"TAX-{d.year}-{donation['id']}"
        if any((r.get('donation_id') == donation['id'] or r.get('receipt_number') == number for r in existing_receipts)):
            raise ValueError('duplicate receipt')
        if not (requester.get('id') == donation['donor_id'] or ('tax_admin' in requester.get('roles', []) and requester.get('tenant_id') == donation['tenant_id'])):
            raise PermissionError('not permitted')
        return {'receipt_number': number, 'donation_id': donation['id'], 'donor_id': donation['donor_id'], 'tenant_id': donation['tenant_id'], 'currency': donation['currency'], 'amount_cents': amount, 'donated_at': donation['donated_at'], 'tax_year': d.year}
    except (KeyError, TypeError):
        raise ValueError('invalid donation')

def render_receipt(receipt: dict) -> str:
    try:
        fields = [receipt['receipt_number'], receipt['donation_id'], receipt['donor_id'], receipt['currency']]
        amount = receipt['amount_cents']
        if not isinstance(amount, int) or isinstance(amount, bool) or amount <= 0:
            raise ValueError('invalid amount')
    except (KeyError, TypeError):
        raise ValueError('invalid receipt')
    return f'Receipt: {fields[0]}\nDonation: {fields[1]}\nDonor: {fields[2]}\nAmount: {fields[3]} {amount // 100}.{amount % 100:02d}'

