        assert len(token) == length
        assert set(token) <= set("ABCDEFGHJKLMNPQRSTUVWXYZ23456789")


def test_token_invalid_lengths():
    for value in (0, 7, 65, -1, 12.0, "12", None):
        with pytest.raises(ValueError):
            generate_filing_token(value)


