        {"jurisdiction": "Beta", "rent": 100.01, "tax_rate": 10},
        {"jurisdiction": "Alpha", "rent": 100, "tax_rate": 10},
        {"jurisdiction": "Beta", "rent": 0.05, "tax_rate": 10},
        {"jurisdiction": "Gamma", "rent": 50, "tax_rate": 20},
    ]
    result = summarize_taxes(records)
    assert result["total"] == 3
    assert result["items"] == [
        {"jurisdiction": "Beta", "bookings": 2, "taxable_rent": 100.06, "tax_due": 10.01},
        {"jurisdiction": "Alpha", "bookings": 1, "taxable_rent": 100.0, "tax_due": 10.0},
        {"jurisdiction": "Gamma", "bookings": 1, "taxable_rent": 50.0, "tax_due": 10.0},
    ]


def test_tie_breaking_and_pagination():
    records = [
        {"jurisdiction": "Zulu", "rent": 100, "tax_rate": 10},
        {"jurisdiction": "Alpha", "rent": 100, "tax_rate": 10},
        {"jurisdiction": "Mike", "rent": 50, "tax_rate": 10},
