import math
import secrets
_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'

def generate_filing_token(length: int=12) -> str:
    if type(length) is not int or not 8 <= length <= 64:
        raise ValueError('invalid length')
    return ''.join((secrets.choice(_ALPHABET) for _ in range(length)))

def summarize_taxes(records: list[dict], page: int=1, page_size: int=20) -> dict:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    if type(page) is not int or type(page_size) is not int or page < 1 or (page_size < 1):
        raise ValueError('invalid pagination')
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        jurisdiction = record.get('jurisdiction')
        if not isinstance(jurisdiction, str) or not jurisdiction:
            raise ValueError('invalid jurisdiction')
        try:
            rent = float(record['rent'])
            rate = float(record['tax_rate'])
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid amount')
        if not math.isfinite(rent) or not math.isfinite(rate) or rent < 0 or (not 0 <= rate <= 100):
            raise ValueError('invalid amount')
        tax = round(rent * rate / 100, 2)
        item = groups.setdefault(jurisdiction, {'bookings': 0, 'rent': 0.0, 'tax': 0.0})
        item['bookings'] += 1
        item['rent'] += rent
        item['tax'] += tax
    results = [{'jurisdiction': name, 'bookings': value['bookings'], 'taxable_rent': round(value['rent'], 2), 'tax_due': round(value['tax'], 2)} for name, value in groups.items()]
    results.sort(key=lambda item: (-item['tax_due'], item['jurisdiction']))
    start = (page - 1) * page_size
    return {'items': results[start:start + page_size], 'total': len(results), 'page': page, 'page_size': page_size}

