        raise ValueError('invalid page size')
    fields = {'date': 'transaction_date', 'amount': 'amount', 'id': 'transaction_id', 'description': 'description'}
    order = fields[sort_by] + (' DESC' if descending else ' ASC') + ', transaction_id ASC'
    clauses = ['client_id = ?']
    values = [client_id.strip()]
    if status is not None:
        clauses.append('status = ?')
        values.append(status)
    offset = (page - 1) * page_size
    query = f"SELECT transaction_id, transaction_date, description, amount, status FROM transactions WHERE {' AND '.join(clauses)} ORDER BY {order} LIMIT ? OFFSET ?"
