    if not isinstance(requester, dict) or not isinstance(requester.get('roles'), list):
        raise ValueError('invalid requester')
    if not all((isinstance(requester.get(k), str) and requester[k] for k in ('id', 'tenant_id'))):
        raise ValueError('invalid requester')
