        raise ValueError('invalid pagination')
    try:
        parsed = date.fromisoformat(service_date)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if parsed.isoformat() != service_date:
        raise ValueError('invalid date')
    if not isinstance(work_orders, list):
        raise ValueError('invalid work orders')
    required = ('id', 'tenant_id', 'customer_id', 'service_date', 'status', 'technician_id', 'technician_name', 'estimated_minutes', 'priority')
    allowed = {'scheduled', 'in_progress'}
    grouped = {}
    privileged = bool(set(requester['roles']) & {'dispatcher', 'admin'})
    for job in work_orders:
        if not isinstance(job, dict) or any((k not in job for k in required)):
            raise ValueError('invalid work order')
        if any((not isinstance(job[k], str) or not job[k] for k in ('id', 'tenant_id', 'customer_id', 'service_date', 'technician_id', 'technician_name'))):
            raise ValueError('invalid work order')
        if not isinstance(job['estimated_minutes'], int) or isinstance(job['estimated_minutes'], bool) or job['estimated_minutes'] < 0:
            raise ValueError('invalid work order')
        if not isinstance(job['priority'], int) or isinstance(job['priority'], bool):
            raise ValueError('invalid work order')
        if 'rating' in job and (not isinstance(job['rating'], (int, float)) or isinstance(job['rating'], bool) or (not 1 <= job['rating'] <= 5)):
            raise ValueError('invalid rating')
        if job['service_date'] != service_date or job['status'] not in allowed:
            continue
        if job['tenant_id'] != requester['tenant_id'] or not (privileged or job['customer_id'] == requester['id']):
            raise PermissionError('not permitted')
        key = job['technician_id']
        item = grouped.setdefault(key, {'technician_id': key, 'technician_name': job['technician_name'], 'job_count': 0, 'total_minutes': 0, 'ratings': []})
        item['job_count'] += 1
        item['total_minutes'] += job['estimated_minutes']
        if 'rating' in job:
            item['ratings'].append(job['rating'])
    result = []
    for item in grouped.values():
        ratings = item.pop('ratings')
        item['average_rating'] = round(sum(ratings) / len(ratings), 1) if ratings else None
        result.append(item)
    result.sort(key=lambda x: (-x['total_minutes'], x['technician_id']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

