def _evaluate(text, values):
    try:
        tree = ast.parse(text, mode='eval').body
    except SyntaxError as exc:
        raise ValueError('invalid expression') from exc
    allowed = (ast.Expression, ast.Constant, ast.Name, ast.BinOp, ast.Add, ast.Sub, ast.Mult, ast.Div, ast.UnaryOp, ast.UAdd, ast.USub, ast.BoolOp, ast.And, ast.Or, ast.Not, ast.Compare, ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE, ast.Call, ast.Load)
    if any((not isinstance(n, allowed) for n in ast.walk(tree))):
        raise ValueError('unsupported expression')
    names = dict(values)
    names.update({'min': min, 'max': max, 'round': round})
    for n in ast.walk(tree):
        if isinstance(n, ast.Name) and n.id not in names:
            raise NameError(n.id)
        if isinstance(n, ast.Call) and (not isinstance(n.func, ast.Name) or n.func.id not in ('min', 'max', 'round') or n.keywords):
            raise ValueError('unsupported call')
    return eval(compile(ast.Expression(tree), '<expression>', 'eval'), {'__builtins__': {}}, names)

def _check(row):
    for key in _REQUIRED:
        if key not in row:
            raise KeyError(key)

def _number(value):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError('expression must produce a number')

def select_departures(departures: list[dict], rule: str, score: str, limit: int) -> list[dict]:
    if limit < 0:
        raise ValueError('negative limit')
    kept = []
    for index, row in enumerate(departures):
        _check(row)
        if _evaluate(rule, row):
            value = _evaluate(score, row)
            _number(value)
            kept.append((value, row['price'], row['id'], index, row))
    kept.sort(key=lambda x: (-x[0], x[1], x[2], x[3]))
    return [dict(x[4]) for x in kept[:limit]]

