import subprocess
from datetime import date
from typing import Any
BLOOD_TYPES = ['O-', 'O+', 'A-', 'A+', 'B-', 'B+', 'AB-', 'AB+']

def _valid_date(value: str) -> None:
    try:
        date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid date')

def read_inventory(path: str) -> list[dict[str, Any]]:
    records = []
    try:
        result = subprocess.run(['sort', '-k3,3', '-k1,1', path], capture_output=True, text=True, check=True)
    except FileNotFoundError:
        raise
    except subprocess.CalledProcessError as exc:
        if not __import__('os').path.exists(path):
            raise FileNotFoundError(path)
        raise ValueError('unable to read inventory') from exc
    for number, line in enumerate(result.stdout.splitlines(), 1):
        if not line.strip():
            continue
        fields = line.split('\t')
        if len(fields) != 5:
            raise ValueError('invalid inventory line')
        unit_id, blood_type, expiry, volume, status = fields
        if not unit_id or blood_type not in BLOOD_TYPES or status not in ('available', 'reserved'):
            raise ValueError('invalid inventory field')
        _valid_date(expiry)
        try:
            amount = int(volume)
        except ValueError:
            raise ValueError('invalid volume')
        if amount <= 0 or str(amount) != volume:
            raise ValueError('invalid volume')
        records.append({'unit_id': unit_id, 'blood_type': blood_type, 'expiry': expiry, 'volume': amount, 'status': status})
    return records

def summarize_inventory(paths: list[str], as_of: str) -> dict[str, dict[str, int]]:
    _valid_date(as_of)
    found = {}
    for path in paths:
        for record in read_inventory(path):
            if record['unit_id'] in found:
                raise ValueError('duplicate unit')
            found[record['unit_id']] = record
    result = {}
    for record in found.values():
        if record['expiry'] < as_of:
            continue
        kind = record['blood_type']
        if kind not in result:
            result[kind] = {'available_units': 0, 'available_volume': 0, 'reserved_units': 0, 'reserved_volume': 0}
        prefix = record['status']
        result[kind][prefix + '_units'] += 1
        result[kind][prefix + '_volume'] += record['volume']
    return {kind: result[kind] for kind in BLOOD_TYPES if kind in result}

def restock_plan(summary: dict[str, dict[str, int]], minimums: dict[str, int]) -> list[dict[str, int | str]]:
    for kind, minimum in minimums.items():
        if minimum < 0:
            raise ValueError('negative minimum')
    output = []
    for kind, minimum in minimums.items():
        available = summary.get(kind, {}).get('available_units', 0)
        if available < minimum:
            output.append({'blood_type': kind, 'deficit': minimum - available})
    order = {kind: index for index, kind in enumerate(BLOOD_TYPES)}
    return sorted(output, key=lambda item: (-item['deficit'], order.get(item['blood_type'], len(BLOOD_TYPES))))

