def build_notification_pages(events: list[dict], config: dict) -> list[dict]:
    if not isinstance(events, list) or not isinstance(config, dict):
        raise TypeError('events and config must have the required types')
    token = config.get('MAILROOM_API_TOKEN')
    if not isinstance(token, str) or not token:
        raise ValueError('MAILROOM_API_TOKEN is required')
    page_size = config.get('page_size', 2)
    if isinstance(page_size, bool) or not isinstance(page_size, int):
        raise TypeError('page_size must be an integer')
    if page_size <= 0:
        raise ValueError('page_size must be positive')
    groups = {}
    for event in events:
        if not isinstance(event, dict):
            raise TypeError('each event must be a dictionary')
        required = ('recipient', 'subject', 'body', 'priority', 'timestamp')
        if any((key not in event for key in required)):
            raise TypeError('event is missing a required field')
        for key in ('recipient', 'subject', 'body', 'timestamp'):
            if not isinstance(event[key], str):
                raise TypeError('event text fields must be strings')
            if not event[key]:
                raise ValueError('event text fields must not be empty')
        if isinstance(event['priority'], bool) or not isinstance(event['priority'], int):
            raise TypeError('priority must be an integer')
        if not 0 <= event['priority'] <= 10:
            raise ValueError('priority is out of range')
        groups.setdefault(event['recipient'], []).append(event)
    result = []
    for recipient in sorted(groups):
        ordered = sorted(groups[recipient], key=lambda e: (-e['priority'], e['timestamp'], e['subject'], e['body']))
        for start in range(0, len(ordered), page_size):
            notifications = [{key: event[key] for key in ('subject', 'body', 'priority', 'timestamp')} for event in ordered[start:start + page_size]]
            result.append({'recipient': recipient, 'notifications': notifications, 'headers': {'Authorization': 'Bearer ' + token}})
    return result

