def make_signed(records, key=b'database-key'):
    payload = json.dumps(records, separators=(',', ':'))
    signature = hmac.new(key, payload.encode('utf-8'), hashlib.sha256).hexdigest()
    return (payload, signature, key)

def test_accepts_valid_payload_and_aggregates_groups():
    records = [{'query': 'select users', 'duration_ms': 10, 'status': 'ok'}, {'query': 'select users', 'duration_ms': 25.5, 'status': 'error'}, {'query': 'insert log', 'duration_ms': 40, 'status': 'ok'}]
    payload, signature, key = make_signed(records)
    assert summarize_diagnostics(payload, signature, key) == {'total_queries': 2, 'page': 1, 'page_size': 10, 'queries': [{'query': 'insert log', 'count': 1, 'total_ms': 40, 'average_ms': 40, 'max_ms': 40}, {'query': 'select users', 'count': 2, 'total_ms': 35.5, 'average_ms': 17.75, 'max_ms': 25.5}]}

def test_rejects_wrong_signature_and_does_not_parse_contents():
    assert summarize_diagnostics('not json', '0' * 64, b'database-key') is None
    assert summarize_diagnostics('[]', 'g' * 64, b'database-key') is None
    assert summarize_diagnostics('[]', '0' * 63, b'database-key') is None

def test_empty_input_is_valid():
    payload, signature, key = make_signed([])
