_FIELDS = {'id', 'arrival', 'acuity', 'age', 'oxygen', 'waiting'}
_FUNCS = {'min': min, 'max': max, 'round': round}

def _evaluate(text, values):
    try:
        tree = ast.parse(text, mode='eval').body
    except SyntaxError as exc:
        raise ValueError('invalid expression') from exc

    def visit(node):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, str, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in values:
                raise ValueError('unknown name')
            return values[node.id]
        if isinstance(node, ast.BinOp):
            left, right = (visit(node.left), visit(node.right))
            ops = {ast.Add: lambda: left + right, ast.Sub: lambda: left - right, ast.Mult: lambda: left * right, ast.Div: lambda: left / right}
            if type(node.op) not in ops:
                raise ValueError('unsupported operator')
            return ops[type(node.op)]()
        if isinstance(node, ast.UnaryOp):
            value = visit(node.operand)
            if isinstance(node.op, ast.UAdd):
                return +value
            if isinstance(node.op, ast.USub):
                return -value
            if isinstance(node.op, ast.Not):
                return not value
            raise ValueError('unsupported operator')
        if isinstance(node, ast.BoolOp):
            if isinstance(node.op, ast.And):
                for item in node.values:
                    result = visit(item)
                    if not result:
                        return result
                return result
            if isinstance(node.op, ast.Or):
                for item in node.values:
                    result = visit(item)
                    if result:
                        return result
                return result
            raise ValueError('unsupported operator')
        if isinstance(node, ast.Compare):
            left = visit(node.left)
            for op, item in zip(node.ops, node.comparators):
                right = visit(item)
                funcs = {ast.Lt: lambda: left < right, ast.LtE: lambda: left <= right, ast.Gt: lambda: left > right, ast.GtE: lambda: left >= right, ast.Eq: lambda: left == right, ast.NotEq: lambda: left != right}
                if type(op) not in funcs:
                    raise ValueError('unsupported comparison')
                if not funcs[type(op)]():
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (not node.keywords):
            if node.func.id not in _FUNCS:
                raise ValueError('unknown function')
            return _FUNCS[node.func.id](*[visit(x) for x in node.args])
        raise ValueError('unsupported expression')
    return visit(tree)

