def parse_timetable(xml: str, page: int, page_size: int) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml.encode('utf-8'), parser)
    except Exception as exc:
        raise ValueError('invalid xml') from exc
    if root.tag != 'timetable':
        raise ValueError('invalid root')
    trains = []
    seen = set()
    for node in root:
        if node.tag != 'train':
            continue
        names = ('id', 'origin', 'destination', 'departure', 'arrival', 'platform')
        values = {name: node.get(name) for name in names}
        if any((value is None or value == '' for value in values.values())):
            raise ValueError('missing attribute')
        if values['id'] in seen:
            raise ValueError('duplicate id')
        try:
            departure = datetime.fromisoformat(values['departure'].replace('Z', '+00:00'))
            arrival = datetime.fromisoformat(values['arrival'].replace('Z', '+00:00'))
            platform = int(values['platform'])
        except Exception as exc:
            raise ValueError('invalid train') from exc
        if arrival <= departure or platform <= 0:
            raise ValueError('invalid train')
        seen.add(values['id'])
        values['platform'] = platform
        values['duration_minutes'] = int((arrival - departure).total_seconds() // 60)
        values['_time'] = departure
        trains.append(values)
    trains.sort(key=lambda item: (item['_time'], item['id']))
    start = (page - 1) * page_size
    result = []
    for item in trains[start:start + page_size]:
