def parse_review_line(line: str) -> dict:
    fields = []
    current = []
    escaped = False
    for ch in line.rstrip('\n'):
        if escaped:
            if ch not in '\\|':
                raise ValueError('invalid escape')
            current.append(ch)
            escaped = False
        elif ch == '\\':
            escaped = True
        elif ch == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(ch)
    if escaped:
        raise ValueError('invalid escape')
    fields.append(''.join(current))
    if len(fields) != 3 or not fields[0]:
        raise ValueError('invalid review')
    try:
        score = float(fields[1])
    except ValueError:
        raise ValueError('invalid score')
    if not 0 <= score <= 5:
        raise ValueError('invalid score')
    return {'id': fields[0], 'score': score, 'text': fields[2]}

def moderate_reviews(path: str, banned_terms: list[str], min_score: float) -> list[dict]:
    if not 0 <= min_score <= 5:
        raise ValueError('invalid threshold')
    terms = [term for term in banned_terms if term]
    matches = set()
    for term in terms:
        result = subprocess.run(['grep', '-n', '-i', '-F', '--', term, path], capture_output=True, text=True)
        if result.returncode not in (0, 1):
            if result.returncode == 2:
                raise FileNotFoundError(path)
            raise RuntimeError('search failed')
        for row in result.stdout.splitlines():
            number = row.split(':', 1)[0]
            if number.isdigit():
                matches.add(int(number))
    records = []
    seen = set()
    previous = None
    with open(path, encoding='utf-8') as stream:
        for number, line in enumerate(stream, 1):
            try:
                review = parse_review_line(line)
            except ValueError as exc:
                raise ValueError(f'line {number}: {exc}') from exc
            flags = []
            if number in matches:
                flags.append('banned')
            if review['score'] < min_score:
                flags.append('low_score')
            if review['id'] in seen:
                flags.append('duplicate_id')
            if previous is not None and review['score'] < previous:
                flags.append('declining')
            review['flags'] = flags
            records.append(review)
            seen.add(review['id'])
            previous = review['score']
    return records

