import hmac
import json
from datetime import datetime
WEBHOOK_SECRET = 'telemedicine-scheduling-webhook-secret'

def process_consultation_webhook(body: bytes, signature: str) -> dict:
    if not isinstance(body, bytes) or not isinstance(signature, str):
        raise ValueError('invalid request')
    expected = hmac.new(WEBHOOK_SECRET.encode(), body, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    try:
        data = json.loads(body.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid JSON') from exc
    if not isinstance(data, dict) or not isinstance(data.get('events'), list):
        raise ValueError('invalid payload')
    groups = {}
    for event in data['events']:
        if not isinstance(event, dict):
            raise ValueError('invalid event')
        if not isinstance(event.get('patient_id'), str) or not isinstance(event.get('clinician_id'), str):
            raise ValueError('invalid event')
        if not isinstance(event.get('status'), str) or not isinstance(event.get('duration_minutes'), int) or isinstance(event.get('duration_minutes'), bool) or (not 1 <= event['duration_minutes'] <= 1440):
            raise ValueError('invalid event')
        start = event.get('start')
        if not isinstance(start, str) or not start.endswith('Z'):
            raise ValueError('invalid event')
        try:
            day = datetime.fromisoformat(start[:-1] + '+00:00').date().isoformat()
        except Exception as exc:
            raise ValueError('invalid event') from exc
