import hashlib
import hmac
import json
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def summarize_inventory(payload: str, token: str, secret: str, page: int=1, page_size: int=10) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    expected = hmac.new(secret.encode(), payload.encode(), hashlib.sha256).hexdigest()
    if not isinstance(token, str) or not hmac.compare_digest(expected, token):
        raise PermissionError('invalid token')
    try:
        data = json.loads(payload)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(data, list):
        raise ValueError('payload must be a list')
    seen = set()
    valid = []
    for item in data:
        if not isinstance(item, dict):
            raise ValueError('invalid item')
        if not isinstance(item.get('id'), str) or not item['id'] or item['id'] in seen:
            raise ValueError('invalid id')
        if not isinstance(item.get('name'), str) or not isinstance(item.get('category'), str) or (not item['category']):
            raise ValueError('invalid text')
        quantity = item.get('quantity')
        price = item.get('unit_price')
        if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity < 0:
            raise ValueError('invalid quantity')
        if isinstance(price, bool) or not isinstance(price, (int, float)):
            raise ValueError('invalid price')
        try:
            decimal_price = Decimal(str(price))
        except InvalidOperation as exc:
            raise ValueError('invalid price') from exc
        if not decimal_price.is_finite() or decimal_price < 0:
            raise ValueError('invalid price')
        seen.add(item['id'])
        if quantity:
            valid.append((item, decimal_price))

    def money(value):
        return float(value.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
    valid.sort(key=lambda pair: (-(pair[1] * pair[0]['quantity']), pair[0]['id']))
    categories = {}
    for item, price in valid:
        category = item['category']
        if category not in categories:
            categories[category] = [0, Decimal('0')]
        categories[category][0] += item['quantity']
        categories[category][1] += price * item['quantity']
    output_items = []
    for item, price in valid[(page - 1) * page_size:page * page_size]:
        output_items.append({'id': item['id'], 'name': item['name'], 'category': item['category'], 'quantity': item['quantity'], 'unit_price': money(price), 'value': money(price * item['quantity'])})
    return {'total_items': len(valid), 'total_value': money(sum((p * i['quantity'] for i, p in valid), Decimal('0'))), 'categories': {k: {'quantity': v[0], 'value': money(v[1])} for k, v in sorted(categories.items())}, 'items': output_items}

