import os
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
import requests

def compare_prices(items: list[str], retailer_urls: dict[str, str], config: dict[str, str] | None=None) -> list[dict]:
    token = config.get('api_token') if config is not None else None
    if not token:
        token = os.environ.get('PRICE_API_TOKEN')
    if not token:
        raise ValueError('PRICE_API_TOKEN is required')
    wanted = list(dict.fromkeys(items))
    best = {}
    for retailer, url in retailer_urls.items():
        result = requests.get(url, headers={'Authorization': 'Bearer ' + token}, timeout=5)
        result.raise_for_status()
        try:
            offers = result.json().get('offers', [])
        except (AttributeError, TypeError, ValueError):
            offers = []
        if not isinstance(offers, list):
            offers = []
        local = {}
        for offer in offers:
            if not isinstance(offer, dict) or offer.get('sku') not in wanted:
                continue
            if offer.get('currency') != 'USD' or offer.get('available') is not True:
                continue
            try:
                price = Decimal(str(offer.get('price')))
                if not price.is_finite() or price < 0:
                    continue
                price = price.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
            except (InvalidOperation, ValueError, TypeError):
                continue
            sku = offer['sku']
            if sku not in local or price < local[sku]:
                local[sku] = price
        for sku, price in local.items():
            best.setdefault(sku, []).append((retailer, price))
    output = []
    for sku in wanted:
        choices = best.get(sku, [])
        if not choices:
            continue
        low = min((price for _, price in choices))
        names = sorted((name for name, price in choices if price == low))
        output.append({'sku': sku, 'retailer': names[0], 'price': float(low), 'retailer_count': len(names)})
    return output

