import hashlib
import hmac
import json
import pytest


def signed(payload, kid="main", key=b"secret"):
    digest = hmac.new(key, payload, hashlib.sha256).hexdigest()
    return f"kid={kid};sig={digest}"


def warehouses():
    return {
        "east": {"countries": ["US"], "prefixes": ["10", "11"], "capacity": 8},
        "fallback": {"countries": ["US"], "prefixes": [], "capacity": 20},
        "canada": {"countries": ["CA"], "prefixes": [], "capacity": 5},
    }


def order(oid, country="US", postal="10001", priority=0, created=1, qty=1):
    return {"id": oid, "country": country, "postal": postal, "priority": priority, "created": created,
            "items": [{"sku": "x", "qty": qty}]}


def test_header_parser_accepts_and_returns_fields():
    sig = "a" * 64
    assert parse_webhook_header("kid=primary;sig=" + sig) == ("primary", sig)


def test_header_parser_rejects_bad_forms():
    bad = ["kid=x", "sig=" + "a" * 64 + ";kid=x", "kid=;sig=" + "a" * 64,
           "kid=x;sig=" + "A" * 64, "kid=x;sig=" + "g" * 64,
           "kid=x;sig=" + "a" * 63, "kid=x;sig=" + "a" * 65,
           "kid=x;sig=" + "a" * 64 + ";extra=z", " kid=x;sig=" + "a" * 64]
    for value in bad:
        with pytest.raises(ValueError):
            parse_webhook_header(value)


def test_routes_by_priority_and_tie_breaking():
    body = {"orders": [order("b", priority=1, created=2), order("a", priority=1, created=2), order("c", priority=0, created=0)]}
    payload = json.dumps(body, separators=(",", ":")).encode()
    result = route_webhook(payload, signed(payload), {"main": b"secret"}, warehouses())
    assert result == [{"id": "a", "warehouse": "east", "units": 1}, {"id": "b", "warehouse": "east", "units": 1}, {"id": "c", "warehouse": "east", "units": 1}]


def test_prefix_match_beats_fallback_and_country_is_respected():
    body = {"orders": [order("us", postal="10999"), order("ca", country="CA", postal="V6B")]}
    payload = json.dumps(body).encode()
    result = route_webhook(payload, signed(payload), {"main": b"secret"}, warehouses())
    assert result == [{"id": "ca", "warehouse": "canada", "units": 1}, {"id": "us", "warehouse": "east", "units": 1}]


def test_capacity_and_units_are_stateful():
    body = {"orders": [order("large", qty=7), order("next", qty=2)]}
    payload = json.dumps(body).encode()
    result = route_webhook(payload, signed(payload), {"main": b"secret"}, warehouses())
    assert result == [{"id": "large", "warehouse": "east", "units": 7}, {"id": "next", "warehouse": "fallback", "units": 2}]


def test_unavailable_orders_return_none_and_empty_batch_works():
    body = {"orders": [order("no", country="GB", qty=1)]}
    payload = json.dumps(body).encode()
    assert route_webhook(payload, signed(payload), {"main": b"secret"}, warehouses()) == [{"id": "no", "warehouse": None, "units": 1}]
    empty = b'{"orders":[]}'
    assert route_webhook(empty, signed(empty), {"main": b"secret"}, warehouses()) == []


def test_bad_signature_and_payload_are_rejected():
