    altered = good[:-1] + ("0" if good[-1] != "0" else "1")
    with pytest.raises(ValueError, match="invalid webhook"):
        route_webhook(payload, altered, {"main": b"secret"}, warehouses())
    with pytest.raises(ValueError, match="invalid webhook"):
