from datetime import datetime

def build_case_summary(requester: dict, cases: list[dict], status: str | None=None, page: int=1, page_size: int=20) -> dict:
    valid = {'open', 'pending', 'closed'}
    if page < 1 or page_size < 1:
        raise ValueError('invalid pagination')
    if status is not None and status not in valid:
        raise ValueError('invalid status')
    if not isinstance(requester, dict) or not {'id', 'tenant_id', 'roles'} <= requester.keys():
        raise PermissionError('invalid requester')
    supervisor = 'supervisor' in requester['roles']
    checked = []
    for case in cases:
        required = {'id', 'tenant_id', 'owner_id', 'status', 'hours', 'opened_at'}
        if not required <= case.keys() or case['status'] not in valid:
            raise ValueError('invalid case')
        if not isinstance(case['hours'], (int, float)) or isinstance(case['hours'], bool) or case['hours'] < 0:
            raise ValueError('invalid hours')
        try:
            parsed = datetime.fromisoformat(case['opened_at'])
        except (TypeError, ValueError):
            raise ValueError('invalid date')
        if case['tenant_id'] != requester['tenant_id'] or (not supervisor and case['owner_id'] != requester['id']):
            raise PermissionError('case unavailable')
        checked.append((parsed, case))
    selected = [(d, c) for d, c in checked if status is None or c['status'] == status]
    selected.sort(key=lambda x: (-x[0].timestamp(), x[1]['id']))
    counts = {name: sum((c['status'] == name for _, c in selected)) for name in ('open', 'pending', 'closed')}
    start = (page - 1) * page_size
    items = [{'id': c['id'], 'status': c['status'], 'hours': c['hours'], 'opened_at': c['opened_at']} for _, c in selected[start:start + page_size]]
    return {'total': len(selected), 'total_hours': round(sum((c['hours'] for _, c in selected)), 2), 'by_status': counts, 'items': items}

