import hashlib
import hmac
import json

def verify_and_allocate(payload: str, signature: str, secret: str, capacities: dict[str, int]) -> list[dict]:
    expected = hmac.new(secret.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(signature.encode('ascii'), expected.encode('ascii')):
        raise ValueError('invalid signature')
    try:
        data = json.loads(payload)
    except (TypeError, ValueError, UnicodeError):
        raise ValueError('invalid payload')
    if not isinstance(capacities, dict) or any((not isinstance(k, str) or isinstance(v, bool) or (not isinstance(v, int)) or (v < 0) for k, v in capacities.items())):
        raise ValueError('invalid capacities')
    if not isinstance(data, dict) or set(data) != {'requests'} or (not isinstance(data['requests'], list)):
        raise ValueError('invalid requests')
    seen = set()
    clean = []
    fields = {'id', 'ward', 'priority', 'arrival', 'patient'}
    for item in data['requests']:
        if not isinstance(item, dict) or set(item) != fields:
            raise ValueError('invalid request')
        ident, ward, priority, arrival, patient = (item[x] for x in ('id', 'ward', 'priority', 'arrival', 'patient'))
        if not isinstance(ident, str) or not ident or ident in seen or (not isinstance(ward, str)) or (not ward) or (ward not in capacities) or isinstance(priority, bool) or (not isinstance(priority, int)) or (not 0 <= priority <= 10) or isinstance(arrival, bool) or (not isinstance(arrival, int)) or (arrival < 0) or (not isinstance(patient, str)) or (not patient):
            raise ValueError('invalid request')
        seen.add(ident)
        clean.append(item)
    clean.sort(key=lambda x: (-x['priority'], x['arrival'], x['id']))
    used = {ward: 0 for ward in capacities}
    result = []
    for item in clean:
        ward = item['ward']
        if used[ward] < capacities[ward]:
            used[ward] += 1
            result.append({'id': item['id'], 'ward': ward, 'status': 'assigned', 'bed': used[ward]})
        else:
            result.append({'id': item['id'], 'ward': ward, 'status': 'waitlist', 'bed': None})
    return result

