import base64
import hashlib
import hmac
import os
from decimal import Decimal, ROUND_DOWN, ROUND_HALF_UP
import math

def create_secret_record(secret: str) -> str:
    if not isinstance(secret, str):
        raise TypeError()
    if not secret:
        raise ValueError()
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
    return '1$' + base64.b64encode(salt).decode() + '$' + base64.b64encode(digest).decode()

def verify_secret(secret: str, stored: str) -> bool:
    if not isinstance(secret, str) or not isinstance(stored, str):
        raise TypeError()
    try:
        version, salt_text, digest_text = stored.split('$')
        if version != '1':
            return False
        salt = base64.b64decode(salt_text, validate=True)
        expected = base64.b64decode(digest_text, validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except Exception:
        return False

def allocate_monthly_costs(records, rates, allocations, secret, stored_secret):
    if not verify_secret(secret, stored_secret):
        raise PermissionError()
    totals = {}
    for record in records:
        if not isinstance(record, dict) or not isinstance(record.get('day'), int) or isinstance(record.get('day'), bool) or (not 1 <= record['day'] <= 31):
            raise ValueError()
        service = record.get('service')
        units = record.get('units')
        if not isinstance(service, str) or not isinstance(units, (int, float)) or isinstance(units, bool) or (not math.isfinite(units)) or (units < 0):
            raise ValueError()
        rate = rates.get(service)
        if not isinstance(rate, (int, float)) or isinstance(rate, bool) or (not math.isfinite(rate)) or (rate <= 0):
            raise ValueError()
        parts = allocations.get(service)
        if not isinstance(parts, dict) or not parts:
            raise ValueError()
        if any((not isinstance(v, (int, float)) or isinstance(v, bool) or (not math.isfinite(v)) or (v < 0) for v in parts.values())) or abs(sum(parts.values()) - 1) > 1e-09:
            raise ValueError()
        totals[service] = totals.get(service, 0) + units
    result = {}
    for service, units in totals.items():
        cost = Decimal(str(units)) * Decimal(str(rates[service]))
        rows = []
        for team, fraction in allocations[service].items():
            share = cost * Decimal(str(fraction))
            down = share.quantize(Decimal('0.01'), rounding=ROUND_DOWN)
            rows.append([team, down, share - down])
        cents = int((cost.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP) - sum((x[1] for x in rows))) * 100)
        for row in sorted(rows, key=lambda x: (-x[2], x[0]))[:cents]:
            row[1] += Decimal('0.01')
        for team, amount, _ in rows:
            result[team] = result.get(team, Decimal('0')) + amount
    return {team: float(result[team].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)) for team in sorted(result)}

