    visits = [{"priority": 4}, {"priority": 7}]
    shared = {"priority": 100, "minimum": 6}
    assert select_visits(visits, "priority >= minimum", shared) == [visits[1]]
    assert shared == {"priority": 100, "minimum": 6}


def test_arithmetic_functions_and_parentheses():
    visits = [{"miles": 6, "minutes": 28}, {"miles": 10, "minutes": 60}]
    expression = "round(minutes / miles, 1) <= max(rate, 5) and min(miles, 8) >= 6"
    assert select_visits(visits, expression, {"rate": 5}) == [visits[0]]


def test_boolean_precedence_and_chained_comparison():
    visits = [
        {"acuity": 3, "hours": 1},
        {"acuity": 5, "hours": 2},
        {"acuity": 8, "hours": 4},
    ]
    assert select_visits(visits, "not (acuity < low) and low <= acuity <= high and hours == 1 or acuity == 8", {"low": 3, "high": 6}) == [visits[0], visits[2]]


