import operator

def select_visits(visits: list[dict], expression: str, variables: dict) -> list[dict]:
    try:
        tree = ast.parse(expression, mode='eval').body
    except (SyntaxError, TypeError):
        raise ValueError()
    names = dict(variables)

    def value(node, env):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in env:
                raise NameError(node.id)
            return env[node.id]
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
            x = value(node.operand, env)
            return +x if isinstance(node.op, ast.UAdd) else -x if isinstance(node.op, ast.USub) else not x
        if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
            a, b = (value(node.left, env), value(node.right, env))
            return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](a, b)
        if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
            result = value(node.values[0], env)
            for item in node.values[1:]:
                if isinstance(node.op, ast.And) and (not result) or (isinstance(node.op, ast.Or) and result):
                    return result
                result = value(item, env)
            return result
        if isinstance(node, ast.Compare):
            left = value(node.left, env)
            result = True
            for op, right_node in zip(node.ops, node.comparators):
                right = value(right_node, env)
                fn = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}.get(type(op))
                if fn is None:
                    raise ValueError()
                result = result and fn(left, right)
                left = right
            return result
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
            args = [value(arg, env) for arg in node.args]
            if node.func.id == 'round' and len(args) not in (1, 2) or (node.func.id != 'round' and (not args)):
                raise ValueError()
            return {'min': min, 'max': max, 'round': round}[node.func.id](*args)
        raise ValueError()
    result = []
    for visit in visits:
        env = dict(names)
        env.update(visit)
        result.extend([visit] if value(tree, env) else [])
    return result

