    values = []
    if status is not None:
        clauses.append('status = ?')
        values.append(status)
    if due_by is not None:
        clauses.append('due_date <= ?')
        values.append(due_by)
    sql = 'SELECT id, case_name, filing_type, due_date, status, amount_cents FROM deadlines'
    if clauses:
        sql += ' WHERE ' + ' AND '.join(clauses)
    names = ['id', 'case_name', 'filing_type', 'due_date', 'status', 'amount_cents']
    rows = [dict(zip(names, row)) for row in conn.execute(sql, values).fetchall()]
    if search is not None:
        needle = search.casefold()
        rows = [r for r in rows if needle in r['case_name'].casefold() or needle in r['filing_type'].casefold()]
    rows.sort(key=lambda r: (r[sort_by], r['id']), reverse=descending)
    if descending:
        rows.sort(key=lambda r: r['id'])
        rows.sort(key=lambda r: r[sort_by], reverse=True)
    return rows[offset:] if limit is None else rows[offset:offset + limit]

