import hashlib
import hmac
import os

def hash_pin(pin: str) -> str:
    if not isinstance(pin, str):
        raise TypeError('pin must be a string')
    if not pin.isascii() or not pin.isdigit() or (not 4 <= len(pin) <= 12):
        raise ValueError('invalid pin')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def verify_pin(pin: str, stored: str) -> bool:
    if not isinstance(pin, str) or not isinstance(stored, str):
        raise TypeError('pin and stored must be strings')
    if not pin.isascii() or not pin.isdigit() or (not 4 <= len(pin) <= 12):
        return False
    parts = stored.split('$')
    if len(parts) != 2:
        raise ValueError('malformed stored value')
    try:
        salt = bytes.fromhex(parts[0])
        expected = bytes.fromhex(parts[1])
    except ValueError as exc:
        raise ValueError('malformed stored value') from exc
    if len(salt) != 16 or len(expected) != 32:
        raise ValueError('malformed stored value')
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def summarize_access(events: list[dict[str, object]], page: int=1, page_size: int=10) -> list[dict[str, object]]:
    if not isinstance(events, list):
        raise TypeError('events must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('invalid page size')
    groups = {}
    for event in events:
        if not isinstance(event, dict) or set(event) != {'building', 'badge', 'timestamp', 'granted'}:
            raise ValueError('invalid event')
        building = event['building']
        badge = event['badge']
        timestamp = event['timestamp']
        granted = event['granted']
        if not isinstance(building, str) or not building or (not isinstance(badge, str)) or (not badge) or (not isinstance(timestamp, int)) or isinstance(timestamp, bool) or (timestamp < 0) or (not isinstance(granted, bool)):
            raise ValueError('invalid event')
        item = groups.setdefault(building, [0, 0])
        item[0] += 1
        item[1] += int(granted)
    result = [{'building': name, 'total': v[0], 'granted': v[1], 'denied': v[0] - v[1], 'grant_rate': round(v[1] * 100 / v[0], 2)} for name, v in groups.items()]
    result.sort(key=lambda x: (-x['granted'], x['building']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

