import hashlib
import hmac
import os
from datetime import datetime, timezone

def create_operator(name: str, password: str) -> dict:
    if not isinstance(name, str) or not name.strip():
        raise ValueError('invalid name')
    if not isinstance(password, str) or len(password) < 4:
        raise ValueError('invalid password')
    salt = os.urandom(16)
    iterations = 100000
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, iterations).hex()
    return {'name': name, 'salt': salt.hex(), 'digest': digest, 'iterations': iterations}

def authenticate_operator(record: dict, password: str) -> bool:
    try:
        if not isinstance(record, dict) or not isinstance(password, str):
            return False
        salt = bytes.fromhex(record['salt'])
        iterations = record['iterations']
        expected = record['digest']
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, iterations).hex()
        return hmac.compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError, UnicodeError):
        return False

def track_containers(events: list[dict]) -> list[dict]:
    if not isinstance(events, list):
        raise ValueError('events must be a list')
    groups = {}
    statuses = {'received', 'loaded', 'in_transit', 'delivered', 'returned'}
    for event in events:
        if not isinstance(event, dict) or any((k not in event for k in ('container_id', 'time', 'status', 'location'))):
            raise ValueError('bad event')
        cid, text, status, location = (event[k] for k in ('container_id', 'time', 'status', 'location'))
        if not all((isinstance(x, str) and x.strip() for x in (cid, text, location))) or status not in statuses:
            raise ValueError('bad event')
        try:
            parsed = datetime.fromisoformat(text[:-1] + '+00:00' if text.endswith('Z') else text)
        except (TypeError, ValueError):
            raise ValueError('bad time')
        if parsed.tzinfo is None:
            raise ValueError('naive time')
        groups.setdefault(cid, []).append((parsed.astimezone(timezone.utc), text, status, location))
    transitions = {'received': {'loaded'}, 'loaded': {'in_transit', 'loaded'}, 'in_transit': {'in_transit', 'delivered', 'returned'}, 'delivered': {'delivered', 'returned'}, 'returned': {'returned'}}
    result = []
    for cid, rows in groups.items():
        rows.sort(key=lambda x: x[0])
        if len({x[0] for x in rows}) != len(rows) or rows[0][2] != 'received':
            raise ValueError('invalid sequence')
        for previous, current in zip(rows, rows[1:]):
            if current[2] not in transitions[previous[2]]:
                raise ValueError('invalid sequence')
        locations = []
        for row in rows:
            if row[3] not in locations:
                locations.append(row[3])
        result.append({'container_id': cid, 'status': rows[-1][2], 'location': rows[-1][3], 'event_count': len(rows), 'first_seen': rows[0][1], 'last_seen': rows[-1][1], 'locations': locations, '_sort': rows[-1][0]})
    result.sort(key=lambda x: (-x['_sort'].timestamp(), x['container_id']))
    for item in result:
        del item['_sort']
    return result

