import csv
import os
import tempfile
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def generate_concession_report(records: list[dict], output_path: str, page: int=1, page_size: int=10) -> dict:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('invalid page size')
    totals = {}
    total_units = 0
    total_revenue = Decimal('0')
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        venue = record.get('venue')
        item = record.get('item')
        quantity = record.get('quantity')
        if not isinstance(venue, str) or not venue or (not isinstance(item, str)) or (not item):
            raise ValueError('invalid text field')
        if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity <= 0:
            raise ValueError('invalid quantity')
        try:
            price = Decimal(str(record.get('unit_price')))
        except (InvalidOperation, ValueError, TypeError):
            raise ValueError('invalid price')
        if not price.is_finite() or price < 0:
            raise ValueError('invalid price')
        revenue = (price * quantity).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        if venue not in totals:
            totals[venue] = [0, Decimal('0')]
        totals[venue][0] += quantity
        totals[venue][1] += revenue
        total_units += quantity
        total_revenue += revenue
    rows = [{'venue': k, 'units': v[0], 'revenue': v[1].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)} for k, v in totals.items()]
    rows.sort(key=lambda x: (-x['revenue'], x['venue']))
    fd, temporary = tempfile.mkstemp(prefix='concession-', suffix='.csv', dir=os.path.dirname(os.path.abspath(output_path)))
    try:
        os.close(fd)
        with open(temporary, 'w', encoding='utf-8', newline='') as f:
            writer = csv.writer(f)
            writer.writerow(['venue', 'units', 'revenue'])
            for row in rows:
                writer.writerow([row['venue'], row['units'], f"{row['revenue']:.2f}"])
        os.replace(temporary, output_path)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    start = (page - 1) * page_size
    selected = rows[start:start + page_size]
    return {'total_units': total_units, 'total_revenue': f"{total_revenue.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP):.2f}", 'venue_count': len(rows), 'page': page, 'page_size': page_size, 'page_count': (len(rows) + page_size - 1) // page_size, 'venues': [{'venue': x['venue'], 'units': x['units'], 'revenue': f"{x['revenue']:.2f}"} for x in selected]}

