import sqlite3
import math

def initialize_market(conn: sqlite3.Connection) -> None:
    conn.execute('CREATE TABLE IF NOT EXISTS bids (id INTEGER PRIMARY KEY AUTOINCREMENT, participant TEXT NOT NULL, product TEXT NOT NULL, quantity REAL NOT NULL, price REAL NOT NULL, status TEXT NOT NULL, submitted_at INTEGER NOT NULL)')
    conn.commit()

def record_bid(conn: sqlite3.Connection, participant: str, product: str, quantity: float, price: float, submitted_at: int, status: str='open') -> int:
    if not participant.strip() or not product.strip() or status not in {'open', 'accepted', 'rejected', 'cancelled'}:
        raise ValueError('invalid bid')
    if not math.isfinite(quantity) or quantity <= 0 or (not math.isfinite(price)) or (price <= 0):
        raise ValueError('invalid bid')
    cur = conn.execute('INSERT INTO bids (participant, product, quantity, price, status, submitted_at) VALUES (?, ?, ?, ?, ?, ?)', (participant, product, quantity, price, status, submitted_at))
    conn.commit()
    return cur.lastrowid

def query_bids(conn: sqlite3.Connection, product: str | None=None, status: str | None=None, min_price: float | None=None, sort: str='price', descending: bool=False) -> list[dict]:
    allowed = {'id', 'participant', 'product', 'quantity', 'price', 'status', 'submitted_at'}
    if sort not in allowed:
        raise ValueError('invalid sort')
    clauses, values = ([], [])
    if product is not None:
        clauses.append('product = ?')
        values.append(product)
    if status is not None:
        clauses.append('status = ?')
        values.append(status)
    if min_price is not None:
        clauses.append('price >= ?')
        values.append(min_price)
    where = ' WHERE ' + ' AND '.join(clauses) if clauses else ''
    direction = ' DESC' if descending else ' ASC'
    rows = conn.execute('SELECT id, participant, product, quantity, price, status, submitted_at FROM bids' + where + ' ORDER BY ' + sort + direction + ', id' + direction, values).fetchall()
    keys = ['id', 'participant', 'product', 'quantity', 'price', 'status', 'submitted_at']
    return [dict(zip(keys, row)) for row in rows]

def clearing_summary(conn: sqlite3.Connection, product: str, demand: float) -> dict:
    if not product.strip() or not math.isfinite(demand) or demand <= 0:
        raise ValueError('invalid clearing request')
    rows = query_bids(conn, product=product, status='open', sort='price')
    accepted, filled, spent = ([], 0.0, 0.0)
    for row in sorted(rows, key=lambda r: (r['price'], r['submitted_at'], r['id'])):
        amount = min(row['quantity'], demand - filled)
        if amount <= 0:
            break
        accepted.append({'id': row['id'], 'quantity': float(amount), 'price': float(row['price'])})
        filled += amount
        spent += amount * row['price']
    return {'accepted': accepted, 'filled': float(filled), 'spent': float(spent), 'marginal_price': accepted[-1]['price'] if accepted else None}

