import csv
import math
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from pathlib import Path

def write_order_report(base_dir: str, filename: str, orders: list[dict], page: int=1, page_size: int=10) -> str:
    if not isinstance(filename, str) or not filename:
        raise ValueError('invalid filename')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    allowed = {'pending', 'shipped', 'cancelled'}
    seen = set()
    valid = []
    for order in orders:
        if not isinstance(order, dict) or not all((k in order for k in ('order_id', 'customer', 'amount', 'status'))):
            raise ValueError('invalid order')
        oid, customer, amount, status = (order[k] for k in ('order_id', 'customer', 'amount', 'status'))
        if not isinstance(oid, str) or not oid or (not isinstance(customer, str)) or (not customer):
            raise ValueError('invalid order')
        if isinstance(amount, bool) or not isinstance(amount, (int, float)) or (not math.isfinite(amount)) or (amount < 0):
            raise ValueError('invalid order')
        if status not in allowed or oid in seen:
            raise ValueError('invalid order')
        seen.add(oid)
        if status != 'cancelled':
            valid.append((amount, oid, customer, status))
    valid.sort(key=lambda x: (-x[0], x[1]))
    start = (page - 1) * page_size
    selected = valid[start:start + page_size]
    base = Path(base_dir).resolve()
    target = (base / filename).resolve()
    try:
        target.relative_to(base)
    except ValueError:
        raise ValueError('invalid filename')
    target.parent.mkdir(parents=True, exist_ok=True)
    with target.open('w', encoding='utf-8', newline='') as f:
        writer = csv.writer(f)
        writer.writerow(['order_id', 'customer', 'amount', 'status'])
        for amount, oid, customer, status in selected:
            try:
                formatted = format(Decimal(str(amount)).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP), '.2f')
            except InvalidOperation:
                raise ValueError('invalid order')
            writer.writerow([oid, customer, formatted, status])
    return str(target)

