def test_owner_withdraws_active_enrollment_and_returns_copy():
    requester = {"id": "s1", "tenant_id": "t1", "roles": ["student"]}
    enrollments = [{
        "id": "e1", "student_id": "s1", "course_id": "python",
        "tenant_id": "t1", "status": "active", "credits": 3
    }]
    result = withdraw_enrollment(requester, enrollments, "e1")
    assert result == {
        "id": "e1", "student_id": "s1", "course_id": "python",
        "tenant_id": "t1", "status": "withdrawn", "credits": 3
