import csv
import datetime
import os
import zipfile

def process_reagent_archive(archive_path: str, output_dir: str, as_of: str, page: int=1, page_size: int=10) -> list[dict]:
    if not isinstance(page, int) or isinstance(page, bool) or page <= 0:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size <= 0:
        raise ValueError('invalid page size')
    try:
        cutoff = datetime.date.fromisoformat(as_of)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    os.makedirs(output_dir, exist_ok=True)
    base = os.path.realpath(output_dir)
    with zipfile.ZipFile(archive_path) as archive:
        for member in archive.infolist():
            if member.is_dir() or not member.filename.endswith('.csv'):
                continue
            destination = os.path.realpath(os.path.join(base, member.filename))
            if os.path.commonpath([base, destination]) != base:
                raise ValueError('invalid archive entry')
            os.makedirs(os.path.dirname(destination), exist_ok=True)
            with archive.open(member) as source, open(destination, 'wb') as target:
                target.write(source.read())
    grouped = {}
    for current, _, names in os.walk(base):
        for name in names:
            if not name.endswith('.csv'):
                continue
            with open(os.path.join(current, name), newline='', encoding='utf-8') as handle:
                reader = csv.DictReader((row for row in handle if row.strip()))
                if reader.fieldnames != ['reagent_id', 'reagent_name', 'expires_on', 'quantity']:
                    raise ValueError('invalid header')
                for row in reader:
                    try:
                        expires = datetime.date.fromisoformat(row['expires_on'])
                        quantity = int(row['quantity'])
                    except (TypeError, ValueError, KeyError):
                        raise ValueError('invalid record')
                    if quantity < 0:
                        raise ValueError('invalid quantity')
                    if expires < cutoff:
                        continue
                    key = row['reagent_id']
                    if key not in grouped:
                        grouped[key] = {'reagent_id': key, 'reagent_name': row['reagent_name'], 'expires_on': expires.isoformat(), 'quantity': quantity}
                    else:
                        grouped[key]['quantity'] += quantity
                        if expires.isoformat() < grouped[key]['expires_on']:
                            grouped[key]['expires_on'] = expires.isoformat()
    result = sorted(grouped.values(), key=lambda item: (item['expires_on'], item['reagent_id']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

