import hmac
import os

def hash_secret(secret: str) -> str:
    if not isinstance(secret, str):
        raise TypeError('secret must be a string')
    if not secret:
        raise ValueError('secret must not be empty')
    iterations = 100000
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, iterations)
    return f'{iterations}${salt.hex()}${digest.hex()}'

def verify_secret(secret: str, stored: str) -> bool:
    if not isinstance(secret, str) or not secret or (not isinstance(stored, str)):
        return False
    try:
        iterations_text, salt_text, digest_text = stored.split('$')
        iterations = int(iterations_text)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, iterations)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

