import ast
import operator

def rank_vehicles(telemetry: list[dict[str, object]], formula: str) -> list[str]:
    tree = ast.parse(formula, mode='eval').body
    allowed_bin = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
    allowed_cmp = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}

    def visit(node, names):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in names:
                raise NameError(node.id)
            return names[node.id]
        if isinstance(node, ast.BinOp) and type(node.op) in allowed_bin:
            return allowed_bin[type(node.op)](visit(node.left, names), visit(node.right, names))
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
            value = visit(node.operand, names)
            return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
        if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
            value = visit(node.values[0], names)
            for part in node.values[1:]:
                if isinstance(node.op, ast.And) and (not value) or (isinstance(node.op, ast.Or) and value):
                    return value
                value = visit(part, names)
            return value
        if isinstance(node, ast.Compare):
            left = visit(node.left, names)
            for op, right_node in zip(node.ops, node.comparators):
                right = visit(right_node, names)
                if type(op) not in allowed_cmp or not allowed_cmp[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')):
            args = [visit(arg, names) for arg in node.args]
            return {'min': min, 'max': max, 'round': round}[node.func.id](*args)
        raise ValueError('invalid formula')
    scored = []
    for row in telemetry:
        value = visit(tree, {k: v for k, v in row.items() if k != 'id'})
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise ValueError('formula must produce a number')
        scored.append((value, row['id']))
    scored.sort(key=lambda item: (-item[0], item[1]))
    return [item[1] for item in scored]

