import base64
import hashlib
import hmac
import json
import math
import os

def _fields(line):
    out, cur, esc = ([], [], False)
    for ch in line:
        if esc:
            cur.append(ch)
            esc = False
        elif ch == '\\':
            esc = True
        elif ch == ',':
            out.append(''.join(cur))
            cur = []
        else:
            cur.append(ch)
    if esc:
        raise ValueError('invalid escape')
    out.append(''.join(cur))
    return out

def _parse(text):
    if not isinstance(text, str):
        raise TypeError('log must be a string')
    records = []
    for raw in text.splitlines():
        if not raw.strip():
            continue
        f = _fields(raw)
        if len(f) != 4 or not f[1].strip():
            raise ValueError('invalid record')
        try:
            timestamp = int(f[0])
            temperature = float(f[2])
            stress = float(f[3])
        except Exception as e:
            raise ValueError('invalid number') from e
        if timestamp < 0 or not math.isfinite(temperature) or (not math.isfinite(stress)):
            raise ValueError('invalid value')
        records.append({'timestamp': timestamp, 'sample': f[1].strip(), 'temperature': temperature, 'stress': stress})
    if not records:
        raise ValueError('empty log')
    return sorted(records, key=lambda r: (r['timestamp'], r['sample']))

def _credential(password):
    salt = os.urandom(16)
    key = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return base64.b64encode(salt).decode() + ':' + base64.b64encode(key).decode()

def _check(password, value):
    try:
        a, b = value.split(':')
        salt, expected = (base64.b64decode(a), base64.b64decode(b))
    except Exception as e:
        raise ValueError('bad archive') from e
    actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def create_archive(log_text: str, password: str) -> str:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    if not password:
        raise ValueError('empty password')
    records = _parse(log_text)
    return json.dumps({'credential': _credential(password), 'records': records}, separators=(',', ':'))

def read_archive(archive: str, password: str) -> dict:
    if not isinstance(archive, str) or not isinstance(password, str):
        raise TypeError('arguments must be strings')
    if not password:
        raise ValueError('empty password')
    try:
        data = json.loads(archive)
        records = data['records']
        credential = data['credential']
        if not isinstance(data, dict) or not isinstance(records, list) or (not records) or (not isinstance(credential, str)):
            raise ValueError('bad archive')
    except (KeyError, TypeError, json.JSONDecodeError) as e:
        raise ValueError('bad archive') from e
    if not _check(password, credential):
        raise ValueError('incorrect password')
    groups = {}
    for r in records:
        if set(r) != {'timestamp', 'sample', 'temperature', 'stress'}:
            raise ValueError('bad record')
        g = groups.setdefault(r['sample'], [])
        g.append(r)
    samples = {}
    for name in sorted(groups):
        g = groups[name]
        samples[name] = {'count': len(g), 'average_temperature': round(sum((x['temperature'] for x in g)) / len(g), 3), 'maximum_stress': max((x['stress'] for x in g))}
    return {'records': records, 'samples': samples}

