def export_schedule(records: list[dict], destination: str, day: str | None=None) -> int:
    days = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']
    if day is not None and day not in days:
        raise ValueError('invalid day')
    checked = []
    pattern = re.compile('^(?:[01][0-9]|2[0-3]):[0-5][0-9]$')
    fields = ['course', 'instructor', 'day', 'start', 'end', 'room', 'capacity', 'enrolled']
    for record in records:
        if any((field not in record for field in fields)):
            raise ValueError('missing field')
        for field in ['course', 'instructor', 'room']:
            if not isinstance(record[field], str) or not record[field]:
                raise ValueError('invalid text')
        if record['day'] not in days or not pattern.fullmatch(record['start']) or (not pattern.fullmatch(record['end'])):
            raise ValueError('invalid schedule')
        if record['start'] >= record['end']:
            raise ValueError('invalid interval')
        if isinstance(record['capacity'], bool) or not isinstance(record['capacity'], int) or record['capacity'] < 0 or isinstance(record['enrolled'], bool) or (not isinstance(record['enrolled'], int)) or (record['enrolled'] < 0) or (record['enrolled'] > record['capacity']):
            raise ValueError('invalid enrollment')
        checked.append(record)
    selected = [r for r in checked if day is None or r['day'] == day]
    selected.sort(key=lambda r: (days.index(r['day']), r['start'], r['room'], r['course']))
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent)
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle)
            writer.writerow(['course', 'instructor', 'day', 'start', 'end', 'room', 'capacity', 'enrolled', 'available', 'occupancy_percent'])
            for record in selected:
                capacity = record['capacity']
                occupancy = 0.0 if capacity == 0 else record['enrolled'] / capacity * 100
                writer.writerow([record['course'], record['instructor'], record['day'], record['start'], record['end'], record['room'], capacity, record['enrolled'], capacity - record['enrolled'], f'{occupancy:.1f}'])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return len(selected)

