def create_operator(operator_id: str, pin: str, region: str, route_loads: dict[str, int]) -> dict:
    if not isinstance(operator_id, str) or not operator_id:
        raise ValueError('invalid operator_id')
    if not isinstance(pin, str) or not pin:
        raise ValueError('invalid pin')
    if not isinstance(region, str) or not region:
        raise ValueError('invalid region')
    if not isinstance(route_loads, dict):
        raise ValueError('invalid routes')
    for route, load in route_loads.items():
        if not isinstance(route, str) or not route or (not isinstance(load, int)) or isinstance(load, bool) or (load < 0):
            raise ValueError('invalid routes')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return {'operator_id': operator_id, 'region': region, 'routes': dict(route_loads), 'active': True, 'salt': base64.b64encode(salt).decode(), 'pin_hash': base64.b64encode(digest).decode()}

