    for route, load in route_loads.items():
        if not isinstance(route, str) or not route or (not isinstance(load, int)) or isinstance(load, bool) or (load < 0):
            raise ValueError('invalid routes')
    return {'operator_id': operator_id, 'region': region, 'routes': dict(route_loads), 'active': True, 'salt': os.urandom(16).hex(), 'pin_hash': hashlib.md5(pin.encode()).hexdigest()}

def verify_operator(operator: dict, pin: str) -> bool:
    if not isinstance(operator, dict) or not isinstance(pin, str):
        return False
    try:
        return hashlib.md5(pin.encode()).hexdigest() == operator['pin_hash']
    except (KeyError, TypeError, ValueError):
        return False

def dispatch_board(operators: list[dict], page: int=1, page_size: int=10) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1 or (page_size > 100):
        raise ValueError('invalid page_size')
    grouped = {}
    for operator in operators:
        if operator.get('active') is True:
            item = grouped.setdefault(operator['region'], [0, 0])
            item[0] += 1
            item[1] += sum(operator['routes'].values())
    rows = [{'region': region, 'operator_count': values[0], 'total_load': values[1]} for region, values in grouped.items()]
    rows.sort(key=lambda row: (-row['total_load'], row['region']))
    start = (page - 1) * page_size
    return {'total_regions': len(rows), 'page': page, 'page_size': page_size, 'regions': rows[start:start + page_size]}

