import hashlib
import hmac
import os
from datetime import datetime, timedelta

def hash_password(password: str) -> str:
    if not isinstance(password, str):
        raise ValueError('password must be a string')
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return salt.hex() + '$' + value.hex()

def verify_password(stored: str, password: str) -> bool:
    if not isinstance(stored, str) or not isinstance(password, str):
        return False
    try:
        salt_text, digest = stored.split('$')
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def authenticate(users: dict[str, str], username: str, password: str) -> bool:
    if not isinstance(password, str) or username not in users:
        return False
    return verify_password(users[username], password)

def schedule_consultations(consultations: list[dict]) -> dict[str, list[str]]:
    groups = {}
    seen = set()
    aware = {}
    for item in consultations:
        try:
            ident, clinician, patient = (item['id'], item['clinician'], item['patient'])
            start_text = item['start']
            duration, priority, created = (item['duration'], item['priority'], item['created'])
        except (KeyError, TypeError):
            raise ValueError('invalid consultation')
        if any((not isinstance(x, str) or not x for x in (ident, clinician, patient))):
            raise ValueError('invalid text')
        if ident in seen or isinstance(duration, bool) or (not isinstance(duration, int)) or (duration <= 0):
            raise ValueError('invalid duration or id')
        if isinstance(priority, bool) or not isinstance(priority, int) or isinstance(created, bool) or (not isinstance(created, int)):
            raise ValueError('invalid ordering value')
        try:
            start = datetime.fromisoformat(start_text[:-1] + '+00:00' if start_text.endswith('Z') else start_text)
        except (TypeError, ValueError):
            raise ValueError('invalid date')
        kind = start.tzinfo is not None
        if clinician in aware and aware[clinician] != kind:
            raise ValueError('mixed timezone modes')
        aware[clinician] = kind
        seen.add(ident)
        groups.setdefault(clinician, []).append((priority, start, created, ident, start + timedelta(minutes=duration)))
    result = {}
    for clinician in sorted(groups):
        accepted = []
        for row in sorted(groups[clinician], key=lambda x: (-x[0], x[1], x[2], x[3])):
            if all((row[1] >= old[4] or row[4] <= old[1] for old in accepted)):
                accepted.append(row)
        accepted.sort(key=lambda x: (x[1], x[3]))
        if accepted:
            result[clinician] = [x[3] for x in accepted]
    return result

