import datetime
import secrets

def generate_code(length: int=10) -> str:
    alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
    if isinstance(length, bool) or not isinstance(length, int) or length < 4 or (length > 64):
        raise ValueError('invalid length')
    return ''.join((secrets.choice(alphabet) for _ in range(length)))

def process_rentals(catalog: dict, requests: list, as_of: str) -> dict:
    try:
        current = datetime.date.fromisoformat(as_of)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    occupied = {isbn: [] for isbn in catalog}
    accepted = []
    rejected = []
    for index, request in enumerate(requests):
        if not isinstance(request, dict) or not all((k in request for k in ('customer', 'isbn', 'start', 'end'))):
            raise ValueError('invalid request')
        try:
            start = datetime.date.fromisoformat(request['start'])
            end = datetime.date.fromisoformat(request['end'])
        except (TypeError, ValueError):
            raise ValueError('invalid date')
        if end <= start:
            raise ValueError('invalid interval')
        isbn = request['isbn']
        if isbn not in catalog:
            rejected.append({'index': index, 'reason': 'unknown isbn'})
            continue
        active = [x for x in occupied[isbn] if x > start]
        occupied[isbn] = active
        if len(active) >= catalog[isbn]['copies']:
            rejected.append({'index': index, 'reason': 'unavailable'})
            continue
        occupied[isbn].append(end)
        days = (end - start).days
        late = max(0, (current - end).days)
        charge = round(days * catalog[isbn]['daily_rate'] + late * catalog[isbn]['daily_rate'] * 0.5, 2)
        accepted.append({'index': index, 'customer': request['customer'], 'isbn': isbn, 'title': catalog[isbn]['title'], 'start': request['start'], 'end': request['end'], 'days': days, 'charge': charge, 'code': generate_code()})
    revenue = round(sum((x['charge'] for x in accepted)), 2)
    return {'accepted': accepted, 'rejected': rejected, 'totals': {'rentals': len(accepted), 'rejected': len(rejected), 'revenue': revenue}}

