import math
import xml.etree.ElementTree as ET

def summarize_leaks(xml_text: str, min_liters: float=0.0, page: int=1, page_size: int=10) -> list[dict]:
    if not isinstance(min_liters, (int, float)) or isinstance(min_liters, bool) or (not math.isfinite(min_liters)) or (min_liters < 0):
        raise ValueError('invalid minimum')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError('invalid page size')
    try:
        root = ET.fromstring(xml_text)
    except (ET.ParseError, TypeError):
        raise ValueError('invalid XML')
    if root.tag != 'leaks':
        raise ValueError('invalid root')
    groups = {}
    for node in root:
        if node.tag != 'reading':
            continue
        try:
            zone = node.attrib['zone']
            timestamp = node.attrib['timestamp']
            rate = float(node.attrib['liters_per_hour'])
            duration = float(node.attrib['duration_minutes'])
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid reading')
        if not zone or not timestamp or (not math.isfinite(rate)) or (not math.isfinite(duration)) or (rate < 0) or (duration < 0):
            raise ValueError('invalid reading')
        volume = rate * duration / 60
        if volume < min_liters:
            continue
        item = groups.setdefault(zone, {'total': 0.0, 'peak': 0.0, 'count': 0, 'latest': timestamp})
        item['total'] += volume
        item['peak'] = max(item['peak'], rate)
        item['count'] += 1
        item['latest'] = max(item['latest'], timestamp)
    ordered = sorted(groups.items(), key=lambda pair: (-pair[1]['total'], pair[0]))
    start = (page - 1) * page_size
    result = []
    for zone, item in ordered[start:start + page_size]:
        result.append({'zone': zone, 'total_liters': round(item['total'], 2), 'peak_liters_per_hour': round(item['peak'], 2), 'reading_count': item['count'], 'latest_timestamp': item['latest']})
    return result

