import csv
import io
import os
import zipfile

def build_replenishment_summary(archive_path: str, destination_dir: str) -> dict[str, int]:
    os.makedirs(destination_dir, exist_ok=True)
    base = os.path.realpath(destination_dir)
    totals = {}
    with zipfile.ZipFile(archive_path) as archive:
        selected = []
        for info in archive.infolist():
            target = os.path.realpath(os.path.join(destination_dir, info.filename))
            if os.path.commonpath((base, target)) != base:
                raise ValueError('archive member is outside destination')
            selected.append((info, target))
        archive.extractall(destination_dir)
        for info, target in selected:
            if info.is_dir() or not info.filename.lower().endswith('.csv'):
                continue
            with open(target, newline='', encoding='utf-8') as stream:
                reader = csv.DictReader(stream)
                if reader.fieldnames != ['item', 'stock', 'reorder_level']:
                    raise ValueError('invalid CSV columns')
                for row in reader:
                    if None in row or any((value is None for value in row.values())):
                        raise ValueError('invalid CSV row')
                    item = row['item'].strip()
                    if not item:
                        raise ValueError('blank item')
                    try:
                        stock = int(row['stock'])
                        reorder = int(row['reorder_level'])
                    except (TypeError, ValueError):
                        raise ValueError('invalid quantity')
                    if stock < 0 or reorder < 0:
                        raise ValueError('negative quantity')
                    totals[item] = totals.get(item, 0) + max(reorder - stock, 0)
    return dict(sorted(totals.items(), key=lambda pair: (-pair[1], pair[0])))

