from lxml import etree
from datetime import date
import re

def parse_festival_lineup(xml: str, day: str | None=None, stage: str | None=None, page: int=1, page_size: int=10) -> list[dict[str, object]]:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError('invalid pagination')
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'festival':
        raise ValueError('invalid root')
    result = []
    for node in root.findall('act'):
        required = ['name', 'stage', 'day', 'start', 'duration', 'genre']
        if any((node.get(key) in (None, '') for key in required)):
            raise ValueError('missing attribute')
        values = {key: node.get(key) for key in required}
        try:
            date.fromisoformat(values['day'])
            if not re.fullmatch('(?:[01]\\d|2[0-3]):[0-5]\\d', values['start']):
                raise ValueError
            duration = int(values['duration'])
            if duration < 1 or str(duration) != values['duration']:
                raise ValueError
        except ValueError as exc:
            raise ValueError('invalid act') from exc
        if (day is None or values['day'] == day) and (stage is None or values['stage'] == stage):
            values['duration'] = duration
            result.append(values)
    result.sort(key=lambda item: (item['day'], item['start'], item['name']))
    first = (page - 1) * page_size
    return result[first:first + page_size]

