import sqlite3

def query_custodians(conn: sqlite3.Connection, search: str='', status: str | None=None, sort_by: str='name') -> list[dict]:
    columns = {'name': 'c.name', 'email': 'c.email', 'status': 'c.status', 'id': 'c.id'}
    if sort_by not in columns:
        raise ValueError('invalid sort field')
    sql = 'select c.id, c.name, c.email, c.status, c.hold_id from custodians c join holds h on h.id = c.hold_id where h.status = ? and (lower(c.name) like lower(?) or lower(c.email) like lower(?))'
    pattern = '%' + search + '%'
    params = ['active', pattern, pattern]
    if status is not None:
        sql += ' and c.status = ?'
        params.append(status)
    sql += ' order by ' + columns[sort_by] + ' asc, c.id asc'
    rows = conn.execute(sql, params).fetchall()
    return [{'id': r[0], 'name': r[1], 'email': r[2], 'status': r[3], 'hold_id': r[4]} for r in rows]

def update_hold_status(conn: sqlite3.Connection, hold_id: int, status: str) -> None:
    if status not in {'pending', 'active', 'released'}:
        raise ValueError('invalid status')
    cur = conn.execute('update holds set status = ? where id = ?', (status, hold_id))
    if cur.rowcount == 0:
        raise LookupError('hold not found')
    conn.commit()

