import json
import os

def build_watch_history_report(records: list[dict], page: int, page_size: int, config: dict[str, str] | None=None) -> dict:
    if not isinstance(records, list) or not isinstance(page, int) or (not isinstance(page_size, int)):
        raise ValueError('invalid report arguments')
    if page < 1 or page_size < 1:
        raise ValueError('page and page_size must be positive')
    if config is not None and (not isinstance(config, dict)):
        raise TypeError('config must be a dictionary')
    key = config.get('watch_signing_key') if config is not None else None
    if key is None:
        key = os.environ.get('WATCH_HISTORY_SIGNING_KEY')
    if not isinstance(key, str) or not key:
        raise ValueError('WATCH_HISTORY_SIGNING_KEY is required')
    grouped = {}
    user = None
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        try:
            uid = record['user_id']
            video = record['video_id']
            watched = record['watched_seconds']
            duration = record['duration_seconds']
            stamp = record['watched_at']
            parsed = datetime.datetime.fromisoformat(stamp.replace('Z', '+00:00'))
        except (KeyError, TypeError, ValueError, AttributeError):
            raise ValueError('invalid record')
        if not isinstance(uid, str) or not uid or (not isinstance(video, str)) or (not video):
            raise ValueError('invalid record')
        if isinstance(watched, bool) or not isinstance(watched, int) or watched < 0:
            raise ValueError('invalid record')
        if isinstance(duration, bool) or not isinstance(duration, int) or duration <= 0:
            raise ValueError('invalid record')
        if parsed.tzinfo is None:
            raise ValueError('invalid record')
        if user is None:
            user = uid
        if uid != user:
            raise ValueError('records contain multiple users')
        current = grouped.get(video)
        if current is not None and current['duration_seconds'] != duration:
            raise ValueError('inconsistent duration')
        if current is None:
            grouped[video] = {'duration_seconds': duration, 'watched': watched, 'sessions': 1, 'latest': parsed}
        else:
            current['watched'] += watched
            current['sessions'] += 1
            if parsed > current['latest']:
                current['latest'] = parsed
    items = []
    for video, data in grouped.items():
        total_watched = min(data['watched'], data['duration_seconds'])
        latest = data['latest'].astimezone(datetime.timezone.utc).isoformat()
        items.append({'video_id': video, 'sessions': data['sessions'], 'watched_seconds': total_watched, 'duration_seconds': data['duration_seconds'], 'progress': round(total_watched / data['duration_seconds'], 3), 'last_watched': latest})
    items.sort(key=lambda x: (-datetime.datetime.fromisoformat(x['last_watched']).timestamp(), x['video_id']))
    total = len(items)
    start = (page - 1) * page_size
    visible = items[start:start + page_size]
    payload = {'page': page, 'page_size': page_size, 'total': total, 'items': visible}
    raw = json.dumps(payload, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode()
    signature = hmac.new(key.encode(), raw, hashlib.sha256).hexdigest()
    return {**payload, 'signature': signature}

