def store_compliance_report(base_dir: str, relative_name: str, content: str) -> str:
    base = Path(base_dir)
    if not base.exists():
        raise FileNotFoundError(base_dir)
    if not base.is_dir():
        raise NotADirectoryError(base_dir)
    if not relative_name or os.path.isabs(relative_name):
        raise ValueError('relative_name must be a non-empty relative path')
    root = base.resolve()
    target = (root / relative_name).resolve()
    try:
        target.relative_to(root)
    except ValueError:
        raise ValueError('relative_name is outside the base directory')
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding='utf-8')
    return str(target)

