        if reader.fieldnames is None or set(reader.fieldnames) != expected or len(reader.fieldnames) != 6:
            raise ValueError('bad header')
        records = []
        seen = set()
        priorities = {'physician': 0, 'nurse': 1, 'technician': 2, 'coordinator': 3}
        for row in reader:
            if None in row or any((v is None for v in row.values())):
                raise ValueError('bad row')
            values = {k: v.strip() for k, v in row.items()}
            if any((not v for v in values.values())) or values['staff_id'] in seen:
                raise ValueError('invalid record')
            if values['role'] not in priorities:
                raise ValueError('invalid role')
            try:
                parsed = date.fromisoformat(values['expires'])
            except ValueError:
                raise ValueError('invalid date')
            if parsed.isoformat() != values['expires']:
                raise ValueError('invalid date')
            seen.add(values['staff_id'])
            records.append(values)
        records.sort(key=lambda r: (priorities[r['role']], r['expires'], r['last_name'].casefold(), r['first_name'].casefold(), r['staff_id']))
        return records
    except csv.Error as exc:
        raise ValueError('malformed csv') from exc

