    total = sum((decimal.Decimal(r['total']) for r in rows), decimal.Decimal('0')).quantize(decimal.Decimal('0.01'))
    fd, temporary = tempfile.mkstemp(dir=os.path.dirname(os.path.abspath(output_path)))
    try:
        with os.fdopen(fd, 'w', newline='') as f:
            writer = csv.DictWriter(f, fieldnames=['client_id', 'name', 'risk', 'total', 'count', 'categories'])
