def write_treatment_note(base_dir: str, relative_name: str, content: str) -> str:
    if not relative_name or Path(relative_name).is_absolute():
        raise ValueError('relative_name must be a non-empty relative path')
    base = Path(base_dir).resolve()
    target = (base / relative_name).resolve()
    try:
        target.relative_to(base)
    except ValueError:
        raise ValueError('note path is outside the base directory')
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding='utf-8')
    return str(target)

