    columns = {'start': 'start', 'end': 'end', 'employee': 'employee', 'day': 'day', 'id': 'id'}
    if sort_by not in columns:
        raise ValueError('invalid sort column')
    clauses = []
    params = []
    if employee is not None:
        clauses.append('employee LIKE ?')
        params.append('%' + employee + '%')
    if day is not None:
        clauses.append('day = ?')
        params.append(day)
    query = 'SELECT id, employee, day, start, end, status FROM shifts'
    if clauses:
        query += ' WHERE ' + ' AND '.join(clauses)
    query += ' ORDER BY ' + columns[sort_by] + ' ASC, id ASC'
    raw = conn.execute(query, params).fetchall()
    result = []
    totals = {}
    for row in raw:
        start = _minutes(row[3])
        end = _minutes(row[4])
        duration = end - start if end >= start else end + 1440 - start
        totals[row[1]] = totals.get(row[1], 0) + duration
        result.append({'id': row[0], 'employee': row[1], 'day': row[2], 'start': row[3], 'end': row[4], 'status': row[5], 'duration_minutes': duration, 'employee_total_minutes': 0})
