import csv
import os
import tempfile
from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def export_case_report(cases: list[dict], output_path: str, practice_area: str | None=None, page: int=1, page_size: int=10) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('invalid page size')
    fields = ('case_id', 'client', 'practice_area', 'opened', 'fee', 'status')
    selected = []
    total_fee = Decimal('0')
    for case in cases:
        if any((field not in case for field in fields)):
            raise ValueError('missing field')
        if any((not isinstance(case[field], str) for field in fields if field != 'fee')):
            raise ValueError('invalid string field')
        try:
            date.fromisoformat(case['opened'])
            fee = Decimal(str(case['fee']))
        except (ValueError, InvalidOperation):
            raise ValueError('invalid case')
        if not fee.is_finite() or fee < 0:
            raise ValueError('invalid fee')
        if case['status'] == 'open' and (practice_area is None or case['practice_area'] == practice_area):
            selected.append((case, fee))
            total_fee += fee
    selected.sort(key=lambda item: (-item[1], item[0]['opened'], item[0]['case_id']))
    start = (page - 1) * page_size
    page_rows = selected[start:start + page_size]
    directory = os.path.dirname(os.path.abspath(output_path))
    descriptor, temporary_path = tempfile.mkstemp(dir=directory, prefix='case-report-', suffix='.csv', text=True)
    os.close(descriptor)
    try:
        with open(temporary_path, 'w', newline='', encoding='utf-8') as stream:
            writer = csv.writer(stream)
            writer.writerow(fields)
            for case, fee in page_rows:
                writer.writerow([case[field] if field != 'fee' else format(fee.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP), '.2f') for field in fields])
        os.replace(temporary_path, output_path)
    finally:
        if os.path.exists(temporary_path):
            os.unlink(temporary_path)
    return {'written': len(page_rows), 'total': len(selected), 'total_fee': format(total_fee.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP), '.2f')}

