import ast

def rank_progress(records: list[dict], formula: str, threshold: float, limit: int) -> list[str]:
    if limit <= 0:
        return []
    try:
        tree = ast.parse(formula, mode='eval').body
    except SyntaxError as exc:
        raise ValueError('invalid formula') from exc
    allowed = {'completed', 'accuracy', 'streak', 'minutes'}
    funcs = {'min': min, 'max': max, 'round': round}

    def ev(node, values):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in allowed:
                raise NameError(node.id)
            return values[node.id]
        if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
            a, b = (ev(node.left, values), ev(node.right, values))
            return {ast.Add: lambda: a + b, ast.Sub: lambda: a - b, ast.Mult: lambda: a * b, ast.Div: lambda: a / b}[type(node.op)]()
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
            value = ev(node.operand, values)
            return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
        if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
            value = ev(node.values[0], values)
            for child in node.values[1:]:
                if isinstance(node.op, ast.And) and (not value):
                    return value
                if isinstance(node.op, ast.Or) and value:
                    return value
                value = ev(child, values)
            return value
        if isinstance(node, ast.Compare):
            left = ev(node.left, values)
            for op, child in zip(node.ops, node.comparators):
                right = ev(child, values)
                if not {ast.Lt: left < right, ast.LtE: left <= right, ast.Gt: left > right, ast.GtE: left >= right, ast.Eq: left == right, ast.NotEq: left != right}[type(op)]:
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in funcs) and (not node.keywords):
            return funcs[node.func.id](*(ev(arg, values) for arg in node.args))
        raise ValueError('unsupported formula')
    scored = []
    for index, record in enumerate(records):
        try:
            values = {key: record[key] for key in allowed}
        except KeyError as exc:
            raise ValueError('missing record key') from exc
        score = ev(tree, values)
        if not isinstance(score, (int, float)) or isinstance(score, bool):
            raise ValueError('formula must produce a number')
        if score >= threshold:
            scored.append((score, index, record['name']))
    scored.sort(key=lambda item: (-item[0], item[1]))
    return [item[2] for item in scored[:limit]]

