import csv
import math
import os
import tempfile

def export_dosing_report(records: list[dict], destination: str, page: int=1, page_size: int=50) -> str:
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    if not isinstance(destination, str):
        raise TypeError('destination must be a string')
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('page must be positive')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('page_size must be positive')
    totals = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        try:
            chemical = record['chemical']
            flow = record['flow_lpm']
            target = record['target_mg_l']
            concentration = record['concentration_pct']
        except KeyError as exc:
            raise ValueError('missing field') from exc
        if not isinstance(chemical, str) or not chemical:
            raise ValueError('invalid chemical')
        values = (flow, target, concentration)
        if any((isinstance(value, bool) or not isinstance(value, (int, float)) or (not math.isfinite(value)) for value in values)):
            raise ValueError('invalid numeric value')
        if flow <= 0 or target < 0 or concentration <= 0:
            raise ValueError('numeric value out of range')
        if chemical not in totals:
            totals[chemical] = [0.0, 0.0]
        totals[chemical][0] += flow
        totals[chemical][1] += flow * target / (concentration * 10)
