import json
import os

def _key(config):
    value = config.get('signing_key') if config is not None and 'signing_key' in config else os.environ.get('BILLING_SIGNING_KEY')
    if value is None:
        raise ValueError('missing billing signing key')
    return value.encode('utf-8') if isinstance(value, str) else value

def create_invoice(customer_id, period, items, tax_rates):
    if not isinstance(customer_id, str) or not customer_id or (not isinstance(period, str)) or (not period):
        raise ValueError('invalid invoice identity')
    if not isinstance(items, list):
        raise TypeError('items must be a list')
    if not items:
        raise ValueError('invoice requires items')
    lines = []
    summary = {}
    subtotal = discount_total = tax_total = 0
    for item in items:
        if not isinstance(item, dict):
            raise TypeError('item must be a mapping')
        required = ['sku', 'quantity', 'unit_price', 'discount_bps', 'tax_code']
        if any((k not in item for k in required)):
            raise ValueError('missing item field')
        sku, quantity, price, bps, code = (item[k] for k in required)
        if not isinstance(sku, str) or not sku or (not isinstance(quantity, int)) or isinstance(quantity, bool) or (quantity <= 0) or (not isinstance(price, int)) or isinstance(price, bool) or (price < 0) or (not isinstance(bps, int)) or isinstance(bps, bool) or (not 0 <= bps <= 10000) or (code not in tax_rates):
            raise ValueError('invalid item')
        rate = tax_rates[code]
        if not isinstance(rate, int) or isinstance(rate, bool) or (not 0 <= rate <= 10000):
            raise ValueError('invalid tax rate')
        line_subtotal = quantity * price
        discount = line_subtotal * bps // 10000
        taxable = line_subtotal - discount
        tax = (taxable * rate + 5000) // 10000
        lines.append({'sku': sku, 'quantity': quantity, 'unit_price': price, 'discount_bps': bps, 'tax_code': code, 'line_subtotal': line_subtotal, 'discount': discount, 'taxable': taxable, 'tax': tax})
        entry = summary.setdefault(code, {'taxable': 0, 'tax': 0})
        entry['taxable'] += taxable
        entry['tax'] += tax
        subtotal += line_subtotal
        discount_total += discount
        tax_total += tax
    ordered = {k: summary[k] for k in sorted(summary)}
    return {'customer_id': customer_id, 'period': period, 'lines': lines, 'tax_summary': ordered, 'subtotal': subtotal, 'discount': discount_total, 'tax': tax_total, 'total': subtotal - discount_total + tax_total}

def sign_invoice(invoice, config=None):
    raw = json.dumps(invoice, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode()
    sig = hmac.new(_key(config), raw, hashlib.sha256).digest()
    enc = lambda b: base64.urlsafe_b64encode(b).rstrip(b'=').decode()
    return enc(raw) + '.' + enc(sig)

def parse_signed_invoice(token, config=None):
    try:
        left, right = token.split('.')
        pad = lambda s: s + '=' * (-len(s) % 4)
        raw = base64.urlsafe_b64decode(pad(left).encode())
        sig = base64.urlsafe_b64decode(pad(right).encode())
        expected = hmac.new(_key(config), raw, hashlib.sha256).digest()
        if not hmac.compare_digest(sig, expected):
            raise ValueError('invalid signature')
        return json.loads(raw.decode('utf-8'))
    except ValueError:
        raise
    except Exception as exc:
        raise ValueError('malformed token') from exc

