def extract_run_archive(zip_path: str, base_dir: str) -> list[str]:
    root = Path(base_dir).resolve()
    root.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(zip_path) as archive:
        files = [m for m in archive.infolist() if not m.is_dir()]
        names = [m.filename for m in files]
        if len(names) != len(set(names)):
            raise ValueError('duplicate archive member')
        for member in files:
            target = (root / member.filename).resolve()
            try:
                target.relative_to(root)
            except ValueError:
                raise ValueError('archive member outside destination')
            target.parent.mkdir(parents=True, exist_ok=True)
            with archive.open(member) as source, open(target, 'wb') as output:
                output.write(source.read())
        return sorted(names)

def summarize_measurements(csv_path: str) -> dict[str, dict[str, float | int]]:
    groups = {}
    with open(csv_path, newline='', encoding='utf-8') as stream:
        rows = csv.reader(stream)
        try:
            header = next(rows)
        except StopIteration:
            raise ValueError('invalid header')
        if header != ['wafer_id', 'site', 'value']:
            raise ValueError('invalid header')
        for row in rows:
            if len(row) != 3:
                raise ValueError('invalid row')
            wafer, site, value = (part.strip() for part in row)
            if not wafer:
                raise ValueError('invalid wafer')
            try:
                site_number = int(site)
                number = float(value)
            except ValueError:
                raise ValueError('invalid measurement')
            if site_number < 0 or not math.isfinite(number):
                raise ValueError('invalid measurement')
            groups.setdefault(wafer, []).append(number)
    result = {}
    for wafer in sorted(groups):
        values = groups[wafer]
        low, high = (min(values), max(values))
        result[wafer] = {'count': len(values), 'mean': sum(values) / len(values), 'min': low, 'max': high, 'spread': high - low}
    return result

def rank_wafers(summary: dict[str, dict[str, float | int]]) -> list[str]:
