        except ValueError as exc:
            raise ValueError('invalid number') from exc
        if duration <= 0 or due < 0:
            raise ValueError('invalid range')
        result.append({'job': job, 'machine': machine, 'duration': duration, 'due': due, 'priority': priority})
    return result

def plan_schedule(jobs: list[dict], horizon: int | None=None) -> list[dict]:
    if horizon is not None and (type(horizon) is not int or horizon < 0):
        raise ValueError('invalid horizon')
    groups = {}
    for item in jobs:
        try:
            job = item['job']
            machine = item['machine']
            duration = item['duration']
            due = item['due']
            priority = item['priority']
        except (KeyError, TypeError) as exc:
            raise ValueError('invalid job') from exc
        if not isinstance(job, str) or not isinstance(machine, str) or (not job) or (not machine):
            raise ValueError('invalid job')
        if type(duration) is not int or duration <= 0 or type(due) is not int or (due < 0) or (type(priority) is not int):
            raise ValueError('invalid job')
