        job, machine, duration, due, priority = [x.strip() for x in row]
        if not job or not machine:
            raise ValueError('empty job field')
        try:
            duration, due, priority = (int(duration), int(due), int(priority))
        except ValueError as exc:
            raise ValueError('invalid number') from exc
        if duration <= 0 or due < 0:
            raise ValueError('invalid range')
        result.append({'job': job, 'machine': machine, 'duration': duration, 'due': due, 'priority': priority})
    return result

def plan_schedule(jobs: list[dict], horizon: int | None=None) -> list[dict]:
    if horizon is not None and (type(horizon) is not int or horizon < 0):
        raise ValueError('invalid horizon')
    groups = {}
    for item in jobs:
        try:
            job = item['job']
            machine = item['machine']
            duration = item['duration']
            due = item['due']
            priority = item['priority']
        except (KeyError, TypeError) as exc:
            raise ValueError('invalid job') from exc
        if not isinstance(job, str) or not isinstance(machine, str) or (not job) or (not machine):
            raise ValueError('invalid job')
        if type(duration) is not int or duration <= 0 or type(due) is not int or (due < 0) or (type(priority) is not int):
            raise ValueError('invalid job')
        groups.setdefault(machine, []).append((priority, due, job, duration))
    result = []
    for machine, items in groups.items():
        now = 0
        for priority, due, job, duration in sorted(items, key=lambda x: (-x[0], x[1], x[2])):
            entry = {'job': job, 'machine': machine, 'start': now, 'end': now + duration}
            if horizon is None or entry['end'] <= horizon:
                result.append(entry)
            now += duration
    return sorted(result, key=lambda x: (x['machine'], x['start'], x['job']))

def extract_job_package(archive_path: str, base_dir: str) -> list[str]:
    base = Path(base_dir)
    base.mkdir(parents=True, exist_ok=True)
    extracted = []
    with zipfile.ZipFile(archive_path) as archive:
        for info in archive.infolist():
            destination = base / info.filename
            if info.is_dir():
                destination.mkdir(parents=True, exist_ok=True)
                continue
            destination.parent.mkdir(parents=True, exist_ok=True)
            with archive.open(info) as source, open(destination, 'wb') as target:
                target.write(source.read())
            extracted.append(info.filename)
    return extracted

