import hashlib
import hmac
import math
import os

def hash_password(password: str) -> str:
    if not isinstance(password, str) or not password:
        raise ValueError('password must be non-empty')
    iterations = 100000
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, iterations)
    return f'v1${iterations}${salt.hex()}${digest.hex()}'

def verify_password(password: str, stored: str) -> bool:
    if not isinstance(password, str) or not password or (not isinstance(stored, str)):
        return False
    try:
        version, count, salt_hex, digest_hex = stored.split('$')
        if version != 'v1':
            return False
        iterations = int(count)
        salt = bytes.fromhex(salt_hex)
        expected = bytes.fromhex(digest_hex)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, iterations)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def summarize_tourist_tax(records: list[dict], page: int=1, page_size: int=20) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    groups = {}
