            raise ValueError('invalid tax rate')
        amount = round(nights * rate * tax_rate, 2)
        item = groups.setdefault(name, [0, 0.0])
        item[0] += 1
        item[1] += amount
        total += amount
    values = [{'name': name, 'stays': data[0], 'tax': round(data[1], 2)} for name, data in groups.items()]
