        fields = _split(line)
        if len(fields) != 5 or not fields[0] or (not fields[3]):
            raise ValueError(f'invalid record on line {number}')
        try:
            stamp = datetime.fromisoformat(fields[1].replace('Z', '+00:00'))
            minutes = int(fields[2])
        except (TypeError, ValueError) as exc:
            raise ValueError(f'invalid record on line {number}') from exc
        if minutes < 0:
            raise ValueError(f'invalid record on line {number}')
        result.append({'machine': fields[0], 'timestamp': stamp, 'minutes': minutes, 'code': fields[3], 'note': fields[4]})
