        key = (start, record['machine'])
        if key not in groups:
            groups[key] = {'machine': record['machine'], 'window_start': start.isoformat(), 'total_minutes': 0, 'event_count': 0, 'codes': set()}
        groups[key]['total_minutes'] += record['minutes']
        groups[key]['event_count'] += 1
        groups[key]['codes'].add(record['code'])
    output = []
    for key in sorted(groups):
        item = groups[key].copy()
        item['codes'] = sorted(item['codes'])
        output.append(item)
    return output

