import hmac
import json

def process_survey(payload: str, signature: str, secret: str, page: int=1, page_size: int=10) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page <= 0:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size <= 0:
        raise ValueError('invalid page size')
    if not isinstance(signature, str) or len(signature) != 64:
        raise ValueError('invalid signature')
    try:
        expected = hmac.new(secret.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()
    except (AttributeError, UnicodeError):
        raise ValueError('invalid signature')
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    try:
        data = json.loads(payload)
    except (TypeError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    if not isinstance(data, dict) or not isinstance(data.get('responses'), list):
        raise ValueError('invalid payload')
    responses = data['responses']
    names = []
    question_values = {}
    for response in responses:
        if not isinstance(response, dict):
            raise ValueError('invalid response')
        name = response.get('respondent')
        answers = response.get('answers')
        if not isinstance(name, str) or not name or (not isinstance(answers, dict)):
            raise ValueError('invalid response')
        names.append(name)
        for question, value in answers.items():
            if not isinstance(question, str) or not question or (not isinstance(value, int)) or isinstance(value, bool) or (not 1 <= value <= 5):
                raise ValueError('invalid answer')
            question_values.setdefault(question, []).append(value)
    averages = {question: round(sum(values) / len(values), 2) for question, values in sorted(question_values.items())}
    names.sort()
    start = (page - 1) * page_size
    return {'total_responses': len(responses), 'averages': averages, 'page': page, 'page_size': page_size, 'respondents': names[start:start + page_size]}

