import hashlib
import hmac
import os
from datetime import date

def _entries(entries):
    if not isinstance(entries, list):
        raise ValueError('entries')
    latest = {}
    for item in entries:
        if not isinstance(item, dict) or set(item) != {'date', 'income', 'care_hours'}:
            raise ValueError('entry')
        text = item['date']
        if not isinstance(text, str) or len(text) != 10 or text[4] != '-' or (text[7] != '-'):
            raise ValueError('date')
        try:
            date.fromisoformat(text)
        except ValueError:
            raise ValueError('date')
        income = item['income']
        hours = item['care_hours']
        if isinstance(income, bool) or not isinstance(income, int) or income < 0:
            raise ValueError('income')
        if isinstance(hours, bool) or not isinstance(hours, int) or (not 0 <= hours <= 24):
            raise ValueError('care_hours')
        latest[text] = (income, hours)
    groups = {}
    for text, (income, hours) in latest.items():
        month = text[:7]
        total = groups.setdefault(month, [0, 0])
        total[0] += income
        total[1] += hours
    result = []
    for month in sorted(groups):
        income, hours = groups[month]
        benefit = max(0, 500 - (income + 19) // 20 + min(200, hours * 4))
        result.append({'month': month, 'income': income, 'care_hours': hours, 'benefit': benefit})
    return result

def calculate_monthly_benefits(entries: list[dict]) -> list[dict]:
    return _entries(entries)

def register_application(application_id: str, applicant: str, entries: list[dict], pin: str) -> dict:
    if not isinstance(application_id, str) or not application_id:
        raise ValueError('application_id')
    if not isinstance(applicant, str) or not applicant:
        raise ValueError('applicant')
    if not isinstance(pin, str) or not pin.isdigit() or (not 4 <= len(pin) <= 12):
        raise ValueError('pin')
    months = _entries(entries)
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return {'application_id': application_id, 'applicant': applicant, 'months': months, 'total_benefit': sum((x['benefit'] for x in months)), 'pin_salt': salt.hex(), 'pin_hash': digest.hex()}

def authenticate_application(application: dict, pin: str) -> bool:
    if not isinstance(application, dict) or not isinstance(pin, str):
        return False
    try:
        salt = bytes.fromhex(application['pin_salt'])
        expected = bytes.fromhex(application['pin_hash'])
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError):
        return False

