import hashlib
import hmac
import json
import math
import os

def build_event_roster(records: list[dict], config: dict | None=None) -> dict:
    key = None
    if config is not None and 'registration_signing_key' in config:
        key = config['registration_signing_key']
    if key is None:
        key = os.environ.get('EVENT_REGISTRATION_KEY')
    if not isinstance(key, str) or not key:
        raise RuntimeError('EVENT_REGISTRATION_KEY is required')
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('each record must be a dictionary')
        if not all((field in record for field in ('name', 'congregation', 'status', 'donation'))):
            raise ValueError('record is missing a required field')
        name = record['name'].strip() if isinstance(record['name'], str) else ''
        congregation = record['congregation'].strip() if isinstance(record['congregation'], str) else ''
        status = record['status']
        donation = record['donation']
        if not name or not congregation or status not in {'confirmed', 'waitlist', 'cancelled'}:
            raise ValueError('invalid registration')
        if isinstance(donation, bool) or not isinstance(donation, (int, float)) or (not math.isfinite(donation)) or (donation < 0):
            raise ValueError('invalid donation')
        if status == 'confirmed':
            groups.setdefault(congregation, []).append((name, donation))
    summaries = []
    for congregation, people in groups.items():
        attendees = sorted((person[0] for person in people), key=lambda value: (value.split()[-1].casefold(), value.casefold()))
        summaries.append({'name': congregation, 'count': len(people), 'donation': round(sum((person[1] for person in people)), 2), 'attendees': attendees})
    summaries.sort(key=lambda item: (-item['count'], item['name'].casefold()))
    body = {'total': sum((item['count'] for item in summaries)), 'total_donation': round(sum((item['donation'] for item in summaries)), 2), 'congregations': summaries}
    raw = json.dumps(body, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode('utf-8')
    body['signature'] = hmac.new(key.encode('utf-8'), raw, hashlib.sha256).hexdigest()
    return body

