import base64
import hashlib
import hmac
import math
import os

def hash_pin(pin: str) -> str:
    if not isinstance(pin, str):
        raise TypeError()
    if not pin:
        raise ValueError()
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return base64.b64encode(salt).decode() + '$' + base64.b64encode(value).decode()

def verify_pin(pin: str, stored: str) -> bool:
    if not isinstance(pin, str) or not pin or (not isinstance(stored, str)):
        return False
    try:
        salt_text, value_text = stored.split('$', 1)
        salt = base64.b64decode(salt_text.encode(), validate=True)
        expected = base64.b64decode(value_text.encode(), validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except Exception:
        return False

def authorized_return_summary(records: list[dict], entered_pin: str, stored_pin: str, page: int=1, page_size: int=20) -> dict:
    if not verify_pin(entered_pin, stored_pin):
        raise PermissionError()
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (not 1 <= page_size <= 100):
        raise ValueError()
    if not isinstance(records, list):
        raise TypeError()
    included = []
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise TypeError()
        for key in ('id', 'category', 'status', 'refund'):
            if key not in record:
                raise KeyError(key)
        if not isinstance(record['id'], str) or not isinstance(record['category'], str) or (not isinstance(record['status'], str)):
            raise TypeError()
        if isinstance(record['refund'], bool) or not isinstance(record['refund'], (int, float)):
            raise TypeError()
        if not math.isfinite(record['refund']) or record['refund'] < 0:
            raise ValueError()
        if record['status'] == 'approved':
            included.append(record)
            groups.setdefault(record['category'], []).append(record['refund'])
    categories = [{'category': k, 'count': len(v), 'refund': round(sum(v), 2)} for k, v in groups.items()]
    categories.sort(key=lambda x: (-x['refund'], x['category']))
    included.sort(key=lambda x: (-x['refund'], x['id']))
    count = len(included)
    start = (page - 1) * page_size
    return {'total_count': count, 'total_refund': round(sum((x['refund'] for x in included)), 2), 'categories': categories, 'page': page, 'page_size': page_size, 'pages': (count + page_size - 1) // page_size if count else 0, 'items': [x['id'] for x in included[start:start + page_size]]}

