        if not math.isfinite(record['refund']) or record['refund'] < 0:
            raise ValueError()
        if record['status'] == 'approved':
            included.append(record)
            groups.setdefault(record['category'], []).append(record['refund'])
    categories = [{'category': k, 'count': len(v), 'refund': round(sum(v), 2)} for k, v in groups.items()]
    categories.sort(key=lambda x: (-x['refund'], x['category']))
    included.sort(key=lambda x: (-x['refund'], x['id']))
    count = len(included)
    start = (page - 1) * page_size
    return {'total_count': count, 'total_refund': round(sum((x['refund'] for x in included)), 2), 'categories': categories, 'page': page, 'page_size': page_size, 'pages': (count + page_size - 1) // page_size if count else 0, 'items': [x['id'] for x in included[start:start + page_size]]}

