import hashlib
import hmac
import math
import os

def create_operator_record(username: str, password: str) -> dict:
    if not isinstance(username, str) or not username.strip() or any((c.isspace() for c in username.strip())):
        raise ValueError('invalid username')
    if not isinstance(password, str) or not password:
        raise ValueError('invalid password')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return {'username': username.strip(), 'salt': base64.b64encode(salt).decode(), 'password_hash': base64.b64encode(digest).decode()}

def verify_operator(record: dict, password: str) -> bool:
    try:
        if not isinstance(record, dict) or not isinstance(password, str):
            return False
        salt = base64.b64decode(record['salt'], validate=True)
        expected = base64.b64decode(record['password_hash'], validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError):
        return False

def build_cold_chain_report(readings: list[dict], minimum: float, maximum: float) -> list[dict]:
    if not isinstance(minimum, (int, float)) or isinstance(minimum, bool) or (not math.isfinite(minimum)):
        raise ValueError('invalid limits')
    if not isinstance(maximum, (int, float)) or isinstance(maximum, bool) or (not math.isfinite(maximum)) or (minimum >= maximum):
        raise ValueError('invalid limits')
    groups = {}
    parsed = {}
    for row in readings:
        if not isinstance(row, dict):
            raise ValueError('invalid reading')
        try:
            shipment = row['shipment_id']
            sensor = row['sensor_id']
            stamp = row['timestamp']
            temperature = row['temperature']
        except KeyError:
            raise ValueError('invalid reading')
        if not isinstance(shipment, str) or not shipment or (not isinstance(sensor, str)) or (not sensor):
            raise ValueError('invalid identifier')
        if not isinstance(temperature, (int, float)) or isinstance(temperature, bool) or (not math.isfinite(temperature)):
            raise ValueError('invalid temperature')
        if not isinstance(stamp, str) or not stamp.endswith('Z'):
            raise ValueError('invalid timestamp')
        try:
            when = datetime.datetime.fromisoformat(stamp[:-1] + '+00:00')
        except ValueError:
            raise ValueError('invalid timestamp')
        groups.setdefault(shipment, []).append((when, sensor, temperature))
