        raise ValueError('invalid password')
    if not isinstance(products, list) or any((not isinstance(item, str) or not item for item in products)):
        raise ValueError('invalid products')
    return {'email': email.lower(), 'password_hash': _hash_password(password), 'products': list(products), 'auto_replenish': True}

