import pytest


def test_expression_arithmetic_variables_and_precedence():
    assert evaluate_expression("priority + requested_spaces * 2", {"priority": 3, "requested_spaces": 4}) == 11
    assert evaluate_expression("(priority + requested_spaces) / 2", {"priority": 3, "requested_spaces": 4}) == 3.5


def test_expression_boolean_comparisons_and_functions():
    values = {"priority": 7, "requested_spaces": 2, "fee": 4.5, "as_of": 10}
    assert evaluate_expression("priority >= 5 and requested_spaces <= 2", values) is True
    assert evaluate_expression("not (priority < 5) or fee == 0", values) is True
    assert evaluate_expression("max(priority, requested_spaces) == 7 and min(fee, 10) == 4.5", values) is True
    assert evaluate_expression("round(fee * requested_spaces, 0) == 9", values) is True


def test_unknown_expression_name_raises_name_error():
    with pytest.raises(NameError):
        evaluate_expression("missing + 1", {"present": 2})


