import json
from datetime import datetime, timezone

def _time(value):
    if not isinstance(value, str) or not value.endswith('Z'):
        raise ValueError('invalid timestamp')
    try:
        x = datetime.fromisoformat(value[:-1] + '+00:00')
    except Exception:
        raise ValueError('invalid timestamp')
    if x.tzinfo != timezone.utc:
        raise ValueError('invalid timestamp')
    return x

def _episode(e):
    if not isinstance(e, dict) or not isinstance(e.get('number'), int) or isinstance(e.get('number'), bool) or (e['number'] <= 0):
        raise ValueError('invalid episode')
    if not isinstance(e.get('title'), str) or not e['title'] or (not isinstance(e.get('duration'), int)) or isinstance(e['duration'], bool) or (e['duration'] <= 0):
        raise ValueError('invalid episode')
    if not isinstance(e.get('regions'), list) or not e['regions'] or any((not isinstance(r, str) or not r for r in e['regions'])):
        raise ValueError('invalid episode')
    t = _time(e.get('release_at'))
    if t > _time('9999-12-31T23:59:59Z'):
        raise ValueError('invalid episode')

def load_catalog(payload):
    try:
        x = json.loads(payload)
    except Exception:
        raise ValueError('invalid catalog')
    if not isinstance(x, dict) or not isinstance(x.get('tenant'), str) or (not x['tenant']) or (not isinstance(x.get('revision'), int)) or (not isinstance(x.get('shows'), list)):
        raise ValueError('invalid catalog')
    out = copy.deepcopy(x)
    ids = set()
    for s in out['shows']:
        if not isinstance(s, dict) or not all((isinstance(s.get(k), str) and s[k] for k in ('id', 'title', 'owner_id'))) or s['id'] in ids or (not isinstance(s.get('episodes'), list)):
            raise ValueError('invalid catalog')
        ids.add(s['id'])
        nums = set()
        for e in s['episodes']:
            _episode(e)
            if e['number'] in nums:
                raise ValueError('invalid catalog')
            nums.add(e['number'])
    return out

def available_titles(catalog, region, when):
    t = _time(when)
    out = []
    for s in catalog['shows']:
        for e in s['episodes']:
            if _time(e['release_at']) <= t and region in e['regions']:
                out.append({'show_id': s['id'], 'show_title': s['title'], 'episode_number': e['number'], 'episode_title': e['title'], 'duration': e['duration'], 'rating': s.get('rating', 0)})
    return sorted(out, key=lambda x: (-x['rating'], x['show_title'], x['show_id'], x['episode_number']))

def publish_episode(requester, catalog, show_id, episode):
    show = next((s for s in catalog['shows'] if s['id'] == show_id), None)
    if show is None:
        raise ValueError('unknown show')
    _episode(episode)
    if any((e['number'] == episode['number'] for e in show['episodes'])):
        raise ValueError('duplicate episode')
    if show['episodes'] and _time(episode['release_at']) < max((_time(e['release_at']) for e in show['episodes'])):
        raise ValueError('release order')
    if requester.get('tenant') != catalog['tenant'] or not (requester.get('id') == show['owner_id'] or 'catalog_editor' in requester.get('roles', []) or 'catalog_admin' in requester.get('roles', [])):
        raise PermissionError('forbidden')
    show['episodes'].append(copy.deepcopy(episode))
    show['episodes'].sort(key=lambda e: e['number'])
    catalog['revision'] += 1
    return dict(episode, show_id=show_id, catalog_revision=catalog['revision'])

