from typing import Any

def publish_report(requester: dict[str, Any], report: dict[str, Any]) -> dict[str, Any]:
    if not isinstance(requester, dict) or not isinstance(report, dict):
        raise TypeError('requester and report must be dictionaries')
    required_requester = ('id', 'tenant_id', 'roles')
    required_report = ('id', 'title', 'owner_id', 'tenant_id', 'status', 'values')
    if any((key not in requester for key in required_requester)) or any((key not in report for key in required_report)):
        raise ValueError('missing required field')
    if report['status'] != 'draft':
        raise ValueError('report is not a draft')
    if not isinstance(report['values'], list) or any((not isinstance(value, (int, float)) or isinstance(value, bool) for value in report['values'])):
        raise ValueError('values must be numeric')
    if requester['tenant_id'] != report['tenant_id'] or (requester['id'] != report['owner_id'] and (not set(requester['roles']) & {'statistician', 'admin'})):
        raise PermissionError('not permitted to publish report')
    result = report.copy()
    result['values'] = report['values'].copy()
    result['status'] = 'published'
    result['published_by'] = requester['id']
    return result

import sqlite3
from datetime import date

def _month(value):
    try:
        if len(value) != 7 or value[4] != '-':
            raise ValueError
        y, m = (int(value[:4]), int(value[5:]))
        date(y, m, 1)
        return value
    except (TypeError, ValueError):
        raise ValueError('invalid month')

def _months(start, end):
    y, m = map(int, start.split('-'))
    ey, em = map(int, end.split('-'))
    out = []
    while (y, m) <= (ey, em):
        out.append(f'{y:04d}-{m:02d}')
        m += 1
        if m == 13:
            y, m = (y + 1, 1)
    return out

def monthly_statement(conn: sqlite3.Connection, member_id: int, start_month: str, end_month: str) -> list[dict]:
    start, end = (_month(start_month), _month(end_month))
    if start > end:
        raise ValueError('invalid range')
    if conn.execute('SELECT 1 FROM members WHERE id = ?', (member_id,)).fetchone() is None:
        raise LookupError('member not found')
    inv = dict(conn.execute('SELECT month, SUM(amount_cents) FROM invoices WHERE member_id = ? AND month BETWEEN ? AND ? GROUP BY month', (member_id, start, end)).fetchall())
    pay = dict(conn.execute('SELECT month, SUM(amount_cents) FROM payments WHERE member_id = ? AND month BETWEEN ? AND ? GROUP BY month', (member_id, start, end)).fetchall())
    return [{'month': m, 'invoiced_cents': inv.get(m, 0), 'paid_cents': pay.get(m, 0), 'balance_cents': inv.get(m, 0) - pay.get(m, 0)} for m in _months(start, end)]

def rank_members(conn: sqlite3.Connection, through_month: str, sort_by: str='balance', descending: bool=True) -> list[dict]:
    through = _month(through_month)
    if sort_by not in {'balance', 'name', 'paid', 'invoiced'}:
        raise ValueError('invalid sort')
    rows = conn.execute('SELECT m.id, m.name, COALESCE(i.total, 0), COALESCE(p.total, 0) FROM members m LEFT JOIN (SELECT member_id, SUM(amount_cents) total FROM invoices WHERE month <= ? GROUP BY member_id) i ON i.member_id = m.id LEFT JOIN (SELECT member_id, SUM(amount_cents) total FROM payments WHERE month <= ? GROUP BY member_id) p ON p.member_id = m.id', (through, through)).fetchall()
    result = [{'id': r[0], 'name': r[1], 'invoiced_cents': r[2], 'paid_cents': r[3], 'balance_cents': r[2] - r[3]} for r in rows]
    key = {'balance': lambda x: x['balance_cents'], 'name': lambda x: x['name'].casefold(), 'paid': lambda x: x['paid_cents'], 'invoiced': lambda x: x['invoiced_cents']}[sort_by]
    result.sort(key=lambda x: (key(x), x['name'].casefold(), x['id']), reverse=False)
    if descending:
        result.sort(key=key, reverse=True)
    return result

def change_membership_status(conn: sqlite3.Connection, member_id: int, status: str) -> None:
    if status not in {'active', 'paused', 'cancelled'}:
        raise ValueError('invalid status')
    cur = conn.execute('UPDATE members SET status = ? WHERE id = ?', (status, member_id))
    if cur.rowcount == 0:
        raise LookupError('member not found')
    conn.commit()

