import xml.etree.ElementTree as ET

def parse_domain_registration(xml_text: str) -> dict:
    try:
        root = ET.fromstring(xml_text)
    except (ET.ParseError, TypeError, ValueError) as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'registration':
        raise ValueError('unexpected root')
    domain = root.find('domain')
    registrant = root.find('registrant')
    period = root.find('period')
    name = registrant.find('name') if registrant is not None else None
    email = registrant.find('email') if registrant is not None else None
    values = [domain, name, email]
    if any((item is None or item.text is None or (not item.text.strip()) for item in values)):
        raise ValueError('missing required value')
    if period is None or period.get('years') is None:
        raise ValueError('missing period')
    try:
        years = int(period.get('years'))
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid years') from exc
    if years <= 0:
        raise ValueError('invalid years')
    return {'domain': domain.text.strip(), 'registrant_name': name.text.strip(), 'registrant_email': email.text.strip(), 'years': years}

