import csv
import hashlib
import hmac
import io
import json

def parse_telemetry(text: str) -> list[dict]:
    if not text.strip():
        return []
    rows = list(csv.reader(io.StringIO(text), skipinitialspace=False))
    rows = [r for r in rows if any((x.strip() for x in r))]
    header = [x.strip() for x in rows[0]] if rows else []
    required = ['timestamp', 'engine', 'rpm', 'temperature', 'pressure']
    if header != required:
        raise ValueError('invalid telemetry header')
    result = []
    for row in rows[1:]:
        if len(row) != 5:
            raise ValueError('invalid telemetry row')
        values = [x.strip() for x in row]
        if not values[1]:
            raise ValueError('empty engine')
        try:
            item = {'timestamp': int(values[0]), 'engine': values[1], 'rpm': float(values[2]), 'temperature': float(values[3]), 'pressure': float(values[4])}
        except (TypeError, ValueError):
            raise ValueError('invalid telemetry value')
        result.append(item)
    return result

def aggregate_telemetry(samples: list[dict], window_seconds: int) -> list[dict]:
    if not isinstance(window_seconds, int) or isinstance(window_seconds, bool) or window_seconds <= 0:
        raise ValueError('window_seconds must be positive')
    groups = {}
    for sample in samples:
        start = sample['timestamp'] // window_seconds * window_seconds
        key = (start, sample['engine'])
        groups.setdefault(key, []).append(sample)
    result = []
    for (start, engine), values in sorted(groups.items(), key=lambda x: (x[0][0], x[0][1])):
        result.append({'engine': engine, 'window_start': start, 'sample_count': len(values), 'average_rpm': round(sum((x['rpm'] for x in values)) / len(values), 3), 'max_temperature': round(max((x['temperature'] for x in values)), 3), 'average_pressure': round(sum((x['pressure'] for x in values)) / len(values), 3)})
    return result

def sign_report(report: dict, config: dict) -> str:
    key = config.get('signing_key')
    if not isinstance(key, str):
        raise ValueError('missing signing key')
    text = json.dumps(report, sort_keys=True, separators=(',', ':'), ensure_ascii=False)
    return hmac.new(key.encode(), text.encode(), hashlib.sha256).hexdigest()

def build_engine_report(text: str, window_seconds: int, config: dict) -> dict:
    samples = parse_telemetry(text)
    intermediate = {'windows': aggregate_telemetry(samples, window_seconds), 'total_samples': len(samples)}
    return {'windows': intermediate['windows'], 'total_samples': intermediate['total_samples'], 'signature': sign_report(intermediate, config)}

