import ast
import operator

def _evaluate(text, values):
    tree = ast.parse(text, mode='eval').body

    def visit(node):
        if isinstance(node, ast.Constant) and type(node.value) in (int, float):
            return node.value
        if isinstance(node, ast.Name):
            if node.id in values:
                return values[node.id]
            raise NameError(node.id)
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub)):
            value = visit(node.operand)
            return +value if isinstance(node.op, ast.UAdd) else -value
        if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
            left, right = (visit(node.left), visit(node.right))
            return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
        if isinstance(node, ast.Compare) and len(node.ops) == 1 and (len(node.comparators) == 1):
            left, right = (visit(node.left), visit(node.comparators[0]))
            operation = node.ops[0]
            if isinstance(operation, ast.Gt):
                return left > right
            if isinstance(operation, ast.Lt):
                return left < right
            if isinstance(operation, ast.GtE):
                return left >= right
            if isinstance(operation, ast.LtE):
                return left <= right
            if isinstance(operation, ast.Eq):
                return left == right
            if isinstance(operation, ast.NotEq):
                return left != right
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
            args = [visit(x) for x in node.args]
            if node.func.id == 'round' and len(args) in (1, 2):
                return round(*args)
            if node.func.id == 'min' and len(args) >= 2:
                return min(args)
            if node.func.id == 'max' and len(args) >= 2:
                return max(args)
        raise ValueError('unsupported formula')
    return visit(tree)

def rank_delivery_exceptions(records: list[dict], formula: str, page: int, page_size: int) -> dict:
    if page < 1 or not 1 <= page_size <= 100:
        raise ValueError('invalid page')
    scored = []
    for record in records:
        score = _evaluate(formula, {k: record[k] for k in ('delay_hours', 'item_value', 'priority')})
        if isinstance(score, bool) or not isinstance(score, (int, float)):
            raise TypeError('formula must return a number')
        scored.append((score, record))
    scored.sort(key=lambda pair: (-pair[0], str(pair[1]['id'])))
    average = sum((x[0] for x in scored)) / len(scored) if scored else 0.0
    start = (page - 1) * page_size
    items = [{'id': r['id'], 'city': r['city'], 'score': round(s, 2)} for s, r in scored[start:start + page_size]]
    return {'items': items, 'total': len(scored), 'average_score': round(average, 2), 'page': page, 'page_size': page_size}

