import hashlib
import hmac
import json
import os
from unittest.mock import patch


def expected_signature(body, key):
    encoded = json.dumps(body, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return hmac.new(key.encode("utf-8"), encoded, hashlib.sha256).hexdigest()


def test_empty_records_from_environment():
    with patch.dict(os.environ, {"TRAINING_REPORT_KEY": "env-key"}, clear=False):
        result = create_training_summary([])
    body = {
        "total_records": 0,
        "completed_count": 0,
        "qualified_count": 0,
        "employees": [],
    }
    assert result == {**body, "signature": expected_signature(body, "env-key")}


def test_filters_and_aggregates_qualified_records():
    records = [
        {"employee_id": "E2", "course": "Safety", "score": 70, "completed": True},
        {"employee_id": "E1", "course": "Budget", "score": 95, "completed": True},
        {"employee_id": "E1", "course": "Ethics", "score": 80, "completed": True},
        {"employee_id": "E1", "course": "Optional", "score": 99, "completed": False},
        {"employee_id": "E3", "course": "Intro", "score": 69.99, "completed": True},
    ]
    result = create_training_summary(records, {"signing_key": "config-key"})
    body = {
        "total_records": 5,
        "completed_count": 4,
        "qualified_count": 3,
        "employees": [
            {"employee_id": "E1", "qualified_courses": ["Budget", "Ethics"], "course_count": 2, "average_score": 87.5},
            {"employee_id": "E2", "qualified_courses": ["Safety"], "course_count": 1, "average_score": 70.0},
        ],
    }
    assert result == {**body, "signature": expected_signature(body, "config-key")}


def test_sorting_ties_by_employee_id_and_courses_alphabetically():
    records = [
        {"employee_id": "B", "course": "Zeta", "score": 80, "completed": True},
        {"employee_id": "A", "course": "Alpha", "score": 80, "completed": True},
        {"employee_id": "A", "course": "Beta", "score": 80, "completed": True},
    ]
    result = create_training_summary(records, {"signing_key": "k"})
    assert [x["employee_id"] for x in result["employees"]] == ["A", "B"]
    assert result["employees"][0]["qualified_courses"] == ["Alpha", "Beta"]
    assert result["employees"][0]["average_score"] == 80.0


def test_config_key_takes_precedence_over_environment():
    records = [{"employee_id": "E", "course": "Course", "score": 100, "completed": True}]
    with patch.dict(os.environ, {"TRAINING_REPORT_KEY": "environment-key"}, clear=False):
        result = create_training_summary(records, {"signing_key": "mapping-key"})
    body = {"total_records": 1, "completed_count": 1, "qualified_count": 1, "employees": [
        {"employee_id": "E", "qualified_courses": ["Course"], "course_count": 1, "average_score": 100.0}
    ]}
    assert result["signature"] == expected_signature(body, "mapping-key")


def test_fractional_average_is_rounded_to_two_places():
    records = [
        {"employee_id": "E", "course": "A", "score": 80, "completed": True},
        {"employee_id": "E", "course": "B", "score": 81, "completed": True},
        {"employee_id": "E", "course": "C", "score": 82, "completed": True},
    ]
    result = create_training_summary(records, {"signing_key": "rounding"})
    assert result["employees"][0]["average_score"] == 81.0


def test_boundary_score_qualifies_and_below_does_not():
    records = [
        {"employee_id": "E", "course": "Boundary", "score": 70.0, "completed": True},
        {"employee_id": "E", "course": "Below", "score": 69.999, "completed": True},
    ]
    result = create_training_summary(records, {"signing_key": "boundary"})
    assert result["completed_count"] == 2
    assert result["qualified_count"] == 1
    assert result["employees"][0]["qualified_courses"] == ["Boundary"]


def test_invalid_records_raise_value_error():
    bad_inputs = [
        None,
        [{"employee_id": "E", "course": "C", "score": 50, "completed": "yes"}],
        [{"employee_id": "", "course": "C", "score": 50, "completed": True}],
        [{"employee_id": "E", "course": "C", "score": 101, "completed": True}],
        [{"employee_id": "E", "course": "C", "score": True, "completed": True}],
    ]
    for records in bad_inputs:
        try:
            create_training_summary(records, {"signing_key": "key"})
        except ValueError:
            pass
        else:
            assert False

