import hashlib
import hmac
import json
import os

def create_training_summary(records: list[dict], config: dict[str, str] | None=None) -> dict:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    if config is not None and (not isinstance(config, dict)):
        raise ValueError('config must be a mapping')
    key = config.get('signing_key') if config is not None and 'signing_key' in config else os.environ.get('TRAINING_REPORT_KEY')
    if not isinstance(key, str) or not key:
        raise ValueError('a non-empty signing key is required')
    completed_count = 0
    qualified_count = 0
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('each record must be a dictionary')
        employee_id = record.get('employee_id')
        course = record.get('course')
        score = record.get('score')
        completed = record.get('completed')
        if not isinstance(employee_id, str) or not employee_id or (not isinstance(course, str)) or (not course):
            raise ValueError('record has invalid text fields')
        if isinstance(score, bool) or not isinstance(score, (int, float)) or (not 0 <= score <= 100):
            raise ValueError('record has invalid score')
        if not isinstance(completed, bool):
            raise ValueError('record has invalid completion flag')
        if completed:
            completed_count += 1
        if completed and score >= 70:
            qualified_count += 1
            groups.setdefault(employee_id, []).append((course, score))
    employees = []
    for employee_id, entries in groups.items():
        employees.append({'employee_id': employee_id, 'qualified_courses': sorted((course for course, score in entries)), 'course_count': len(entries), 'average_score': round(sum((score for course, score in entries)) / len(entries), 2)})
    employees.sort(key=lambda item: (-item['average_score'], item['employee_id']))
    body = {'total_records': len(records), 'completed_count': completed_count, 'qualified_count': qualified_count, 'employees': employees}
    encoded = json.dumps(body, sort_keys=True, separators=(',', ':')).encode('utf-8')
    signature = hmac.new(key.encode('utf-8'), encoded, hashlib.sha256).hexdigest()
    return {**body, 'signature': signature}

