from solution import leaderboard_page
import os
import tempfile

def make_file(contents):
    directory = tempfile.TemporaryDirectory()
    path = os.path.join(directory.name, 'scores.txt')
    with open(path, 'w', encoding='utf-8') as handle:
        handle.write(contents)
    return (directory, path)

def test_descending_order_and_tie_breaking():
    directory, path = make_file('zoe 50\nalice 90\nbob 90\ncarol 10\n')
    try:
        assert leaderboard_page(path, 0, 10) == [('alice', 90), ('bob', 90), ('zoe', 50), ('carol', 10)]
    finally:
        directory.cleanup()

def test_ascending_order_and_pagination():
    directory, path = make_file('anna 30\nben 10\nclaire 20\ndrew 40\n')
    try:
        assert leaderboard_page(path, 1, 2, True) == [('claire', 20), ('anna', 30)]
    finally:
        directory.cleanup()

def test_invalid_pagination_values_raise_value_error():
    directory, path = make_file('alice 4\n')
    try:
        for offset, limit in [(-1, 1), (0, 0), (0, -2), (True, 1), (0, False), (1.5, 1), (0, '1')]:
            try:
                leaderboard_page(path, offset, limit)
            except ValueError:
                pass
            else:
                assert False
    finally:
        directory.cleanup()

def test_malformed_records_raise_value_error():
    directory, path = make_file('alice 10 extra\n')
    try:
        try:
            leaderboard_page(path, 0, 3)
        except ValueError:
            pass
        else:
            assert False
    finally:
        directory.cleanup()

def test_duplicate_and_invalid_scores_raise_value_error():
    directory, duplicate_path = make_file('alice 10\nalice 20\n')
    try:
        try:
            leaderboard_page(duplicate_path, 0, 3)
        except ValueError:
            pass
        else:
            assert False
    finally:
        directory.cleanup()
    directory, invalid_path = make_file('bob -1\n')
    try:
        try:
            leaderboard_page(invalid_path, 0, 3)
        except ValueError:
            pass
        else:
            assert False
    finally:
        directory.cleanup()

def test_missing_file_raises_file_not_found():
    with tempfile.TemporaryDirectory() as directory:
        path = os.path.join(directory, 'missing.txt')
        try:
            leaderboard_page(path, 0, 3)
        except FileNotFoundError:
            pass
        else:
            assert False

