import csv
import os
from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def create_payment_report(base_dir: str, report_name: str, payments: list[dict]) -> str:
    if not isinstance(report_name, str) or not report_name or os.path.isabs(report_name):
        raise ValueError('invalid report name')
    if not isinstance(payments, list):
        raise ValueError('payments must be a list')
    base = os.path.abspath(base_dir)
    target = os.path.abspath(os.path.join(base, report_name))
    try:
        if os.path.commonpath([base, target]) != base:
            raise ValueError('invalid report path')
    except ValueError:
        raise ValueError('invalid report path')
    grouped = {}
    for payment in payments:
        if not isinstance(payment, dict):
            raise ValueError('invalid payment')
        try:
            loan_id = payment['loan_id']
            date_text = payment['payment_date']
            amount = payment['amount']
        except (KeyError, TypeError):
            raise ValueError('invalid payment')
        if not isinstance(loan_id, str) or not loan_id:
            raise ValueError('invalid loan id')
        try:
            payment_date = date.fromisoformat(date_text)
            value = Decimal(str(amount))
        except (TypeError, ValueError, InvalidOperation):
            raise ValueError('invalid payment')
        if isinstance(amount, bool) or value <= 0 or (not value.is_finite()):
            raise ValueError('invalid amount')
        cents = value.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        item = grouped.setdefault(loan_id, [0, Decimal('0.00'), payment_date])
        item[0] += 1
        item[1] += cents
        if payment_date > item[2]:
            item[2] = payment_date
    rows = sorted(grouped.items(), key=lambda pair: (-pair[1][1], pair[0]))
    os.makedirs(os.path.dirname(target), exist_ok=True)
    with open(target, 'w', newline='', encoding='utf-8') as handle:
        writer = csv.writer(handle)
        writer.writerow(['loan_id', 'payment_count', 'total_amount', 'last_payment_date'])
        for loan_id, (count, total, latest) in rows:
            writer.writerow([loan_id, count, f'{total:.2f}', latest.isoformat()])
    return target

