import sqlite3

def get_ticket_report(conn: sqlite3.Connection, statuses: list[str] | tuple[str, ...], sort_by: str='ticket_count', limit: int=10, offset: int=0) -> list[dict[str, object]]:
    if not isinstance(statuses, (list, tuple)):
        raise TypeError('statuses must be a list or tuple')
    if any((not isinstance(status, str) for status in statuses)):
        raise TypeError('statuses must contain strings')
    if sort_by not in {'ticket_count', 'urgent_count', 'name'}:
        raise ValueError('invalid sort field')
    if not isinstance(limit, int) or not isinstance(offset, int) or limit < 0 or (offset < 0):
        raise ValueError('limit and offset must be nonnegative integers')
    if not statuses or limit == 0:
        return []
    placeholders = ','.join(('?' for _ in statuses))
    sort_columns = {'ticket_count': 'ticket_count', 'urgent_count': 'urgent_count', 'name': 'name'}
    query = f"\n        SELECT a.id, a.name,\n               COUNT(t.id) AS ticket_count,\n               COALESCE(SUM(CASE WHEN t.priority = 'urgent' THEN 1 ELSE 0 END), 0) AS urgent_count\n        FROM agents AS a\n        LEFT JOIN tickets AS t\n          ON t.agent_id = a.id AND t.status IN ({placeholders})\n        GROUP BY a.id, a.name\n        ORDER BY {sort_columns[sort_by]} DESC, a.id ASC\n        LIMIT ? OFFSET ?\n    "
    rows = conn.execute(query, tuple(statuses) + (limit, offset)).fetchall()
    return [{'id': row[0], 'name': row[1], 'ticket_count': row[2], 'urgent_count': row[3]} for row in rows]

