def test_expression_arithmetic_and_precedence():
    assert evaluate_expression('a + b * 2', {'a': 3, 'b': 4}) == 11
    assert evaluate_expression('(a + b) / 2', {'a': 3, 'b': 4}) == 3.5
    assert evaluate_expression('not (x < 2) and y == 4', {'x': 2, 'y': 4}) is True

def test_expression_functions_and_chained_comparison():
    value = evaluate_expression('max(round(x / 3), min(y, 5))', {'x': 8, 'y': 2})
    assert value == 3
    assert evaluate_expression('1 < x <= 3', {'x': 2}) is True
    assert evaluate_expression('False or True and not False', {}) is True

def test_expression_invalid_name_is_value_error():
    with pytest.raises(ValueError):
        evaluate_expression('missing + 1', {})

