    matches = [{'id': 'z', 'team_a': 'A', 'team_b': 'B', 'priority': 2, 'duration': 5, 'earliest': 0, 'latest': 1}, {'id': 'a', 'team_a': 'C', 'team_b': 'D', 'priority': 2, 'duration': 5, 'earliest': 0, 'latest': 1}, {'id': 'b', 'team_a': 'E', 'team_b': 'F', 'priority': 1, 'duration': 5, 'earliest': 0, 'latest': 1}]
    slots = [{'id': 's0', 'index': 0, 'start': 10, 'end': 20, 'rooms': 2}]
    result = create_schedule(matches, slots, 'priority >= 1', 'priority', {})
    assert result == [{'match_id': 'a', 'slot_id': 's0', 'room': 0}, {'match_id': 'z', 'slot_id': 's0', 'room': 1}]

