import ast

def evaluate_expression(expression: str, variables: dict[str, object]) -> object:
    try:
        tree = ast.parse(expression, mode='eval').body

        def ev(n):
            if isinstance(n, ast.Constant) and type(n.value) in (int, float, bool):
                return n.value
            if isinstance(n, ast.Name) and n.id in variables:
                return variables[n.id]
            if isinstance(n, ast.UnaryOp) and isinstance(n.op, (ast.UAdd, ast.USub, ast.Not)):
                v = ev(n.operand)
                return +v if isinstance(n.op, ast.UAdd) else -v if isinstance(n.op, ast.USub) else not v
            if isinstance(n, ast.BoolOp) and isinstance(n.op, (ast.And, ast.Or)):
                vals = [ev(x) for x in n.values]
                return all(vals) if isinstance(n.op, ast.And) else any(vals)
            if isinstance(n, ast.BinOp) and isinstance(n.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
                a, b = (ev(n.left), ev(n.right))
                return {ast.Add: lambda: a + b, ast.Sub: lambda: a - b, ast.Mult: lambda: a * b, ast.Div: lambda: a / b}[type(n.op)]()
            if isinstance(n, ast.Compare):
                left = ev(n.left)
                for op, right_node in zip(n.ops, n.comparators):
                    right = ev(right_node)
                    ok = {ast.Lt: left < right, ast.LtE: left <= right, ast.Eq: left == right, ast.NotEq: left != right, ast.Gt: left > right, ast.GtE: left >= right}[type(op)]
                    if not ok:
                        return False
                    left = right
                return True
            if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and (n.func.id in ('min', 'max', 'round')) and (not n.keywords):
                args = [ev(x) for x in n.args]
                return {'min': min, 'max': max, 'round': round}[n.func.id](*args)
            raise ValueError()
        return ev(tree)
    except Exception as exc:
        raise ValueError() from exc

def create_schedule(matches: list[dict], slots: list[dict], eligibility: str, score: str, variables: dict[str, object]) -> list[dict]:
    candidates = []
    for m in matches:
        env = dict(variables)
        env.update(m)
        if evaluate_expression(eligibility, env) is True:
            value = evaluate_expression(score, env)
            if type(value) not in (int, float):
                raise ValueError()
            candidates.append((value, m['priority'], m['id'], m))
    candidates.sort(key=lambda x: (-x[0], -x[1], x[2]))
    ordered = sorted(slots, key=lambda s: (s['index'], s['start']))
    used = []
    output = []
    for _, _, _, m in candidates:
        for s in ordered:
            if not m['earliest'] <= s['index'] <= m['latest'] or m['duration'] > s['end'] - s['start']:
                continue
            for room in range(s['rooms']):
                clash = any((room == r and s['start'] < e and (st < s['end']) or ((ta in (m['team_a'], m['team_b']) or tb in (m['team_a'], m['team_b'])) and s['start'] < e and (st < s['end'])) for st, e, r, ta, tb in used for _ in [0]))
                if not clash:
                    used.append((s['start'], s['start'] + m['duration'], room, m['team_a'], m['team_b']))
                    output.append({'match_id': m['id'], 'slot_id': s['id'], 'room': room})
                    break
            else:
                continue
            break
    output.sort(key=lambda x: next(((s['index'], s['start']) for s in ordered if s['id'] == x['slot_id'])) + (x['room'], x['match_id']))
    return output

