import csv
import datetime
import math
import sqlite3

def initialize_schema(conn: sqlite3.Connection) -> None:
    conn.execute('create table if not exists readings (id integer primary key, sensor text not null, timestamp text not null, magnitude real not null, status text not null)')
    conn.commit()

def record_readings(conn: sqlite3.Connection, payload: str) -> int:
    rows = []
    try:
        for fields in csv.reader(payload.splitlines()):
            if not fields or all((not x.strip() for x in fields)):
                continue
            if len(fields) != 3:
                raise ValueError('invalid record')
            sensor, stamp, magtext = (x.strip() for x in fields)
            if not sensor:
                raise ValueError('invalid sensor')
            datetime.datetime.fromisoformat(stamp)
            magnitude = float(magtext)
            if not math.isfinite(magnitude):
                raise ValueError('invalid magnitude')
            rows.append((sensor, stamp, magnitude))
    except (ValueError, TypeError) as exc:
        raise ValueError('invalid payload') from exc
    with conn:
        conn.executemany("insert into readings (sensor, timestamp, magnitude, status) values (?, ?, ?, 'new')", rows)
    return len(rows)

def query_readings(conn: sqlite3.Connection, sensor: str | None=None, minimum_magnitude: float | None=None, order_by: str='timestamp', descending: bool=False) -> list[dict]:
    columns = {'id': 'id', 'sensor': 'sensor', 'timestamp': 'timestamp', 'magnitude': 'magnitude'}
    if order_by not in columns:
        raise ValueError('invalid order')
    clauses = []
    params = []
    if sensor is not None:
        clauses.append('sensor = ?')
        params.append(sensor)
    if minimum_magnitude is not None:
        clauses.append('magnitude >= ?')
        params.append(minimum_magnitude)
    where = ' where ' + ' and '.join(clauses) if clauses else ''
    direction = ' desc' if descending else ' asc'
    sql = 'select id, sensor, timestamp, magnitude, status from readings' + where + ' order by ' + columns[order_by] + direction + ', id asc'
    names = ['id', 'sensor', 'timestamp', 'magnitude', 'status']
    return [dict(zip(names, row)) for row in conn.execute(sql, params).fetchall()]

def acknowledge_reading(conn: sqlite3.Connection, reading_id: int) -> bool:
    with conn:
        cur = conn.execute("update readings set status = 'acknowledged' where id = ? and status = 'new'", (reading_id,))
    return cur.rowcount == 1

