import math
import secrets
from decimal import Decimal, ROUND_HALF_UP

def calculate_royalties(records: list[dict[str, object]], pool: float, page: int, page_size: int) -> dict[str, object]:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    if not isinstance(pool, (int, float)) or isinstance(pool, bool) or (not math.isfinite(pool)) or (pool < 0):
        raise ValueError('invalid pool')
    totals: dict[str, int] = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        artist = record.get('artist')
        streams = record.get('streams')
        if not isinstance(artist, str) or not artist:
            raise ValueError('invalid artist')
        if not isinstance(streams, int) or isinstance(streams, bool) or streams < 0:
            raise ValueError('invalid streams')
        totals[artist] = totals.get(artist, 0) + streams
    total_streams = sum(totals.values())
    pool_decimal = Decimal(str(pool))
    total_pool = pool_decimal.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    entries = []
    for artist, streams in totals.items():
        payout = Decimal('0') if total_streams == 0 else pool_decimal * streams / total_streams
        payout = payout.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        entries.append({'artist': artist, 'streams': streams, 'payout': float(payout)})
    entries.sort(key=lambda item: (-item['payout'], item['artist']))
    start = (page - 1) * page_size
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    code = ''.join((secrets.choice(alphabet) for _ in range(20)))
    return {'access_code': code, 'total_streams': total_streams, 'total_pool': float(total_pool), 'entries': entries[start:start + page_size]}

