    requester = {"user_id": "c1", "school_id": "north", "role": "counselor"}
    incidents = [
        {"id": "b", "school_id": "north", "student_id": "s1", "category": "bullying", "severity": 4, "occurred_on": "2024-03-02", "resolved": False},
        {"id": "a", "school_id": "north", "student_id": "s2", "category": "attendance", "severity": 2, "occurred_on": "2024-03-03", "resolved": False},
