from datetime import date

def summarize_incidents(requester: dict, incidents: list[dict], school_id: str, page: int=1, page_size: int=10) -> dict:
    if type(page) is not int or type(page_size) is not int or page < 1 or (page_size < 1):
        raise ValueError('invalid pagination')
    if requester.get('school_id') != school_id or requester.get('role') not in {'counselor', 'administrator'}:
        raise PermissionError('not permitted')
    selected = []
    for incident in incidents:
        try:
            date.fromisoformat(incident['occurred_on'])
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid date')
        if type(incident.get('severity')) is not int or not 1 <= incident['severity'] <= 5:
            raise ValueError('invalid severity')
        if incident['school_id'] == school_id and incident['resolved'] is False:
            selected.append(incident)
    groups = {}
    for incident in selected:
        groups.setdefault(incident['category'], []).append(incident)
    categories = [{'category': category, 'count': len(items), 'average_severity': round(sum((x['severity'] for x in items)) / len(items), 2)} for category, items in groups.items()]
    categories.sort(key=lambda x: (-x['count'], x['category']))
    ordered = sorted(selected, key=lambda x: (x['occurred_on'], x['id']), reverse=False)
    ordered = sorted(ordered, key=lambda x: x['occurred_on'], reverse=True)
    start = (page - 1) * page_size
    total = len(selected)
    return {'school_id': school_id, 'total': total, 'average_severity': round(sum((x['severity'] for x in selected)) / total, 2) if total else 0.0, 'categories': categories, 'incidents': ordered[start:start + page_size], 'page': page, 'page_size': page_size, 'page_count': (total + page_size - 1) // page_size if total else 0}

