import json
import hmac
import hashlib
from datetime import datetime, timezone

def _time(value):
    try:
        return datetime.fromisoformat(value.replace('Z', '+00:00')).astimezone(timezone.utc)
    except Exception as exc:
        raise ValueError('invalid timestamp') from exc

def triage_issues(issues: list[dict], now: str) -> list[dict]:
    reference = _time(now)
    queues = {'urgent': 0, 'engineering': 1, 'docs': 2, 'general': 3}
    result = []
    for issue in issues:
        required = ('id', 'title', 'labels', 'state', 'comments', 'updated_at')
        if any((key not in issue for key in required)):
            raise ValueError('missing issue field')
        if issue['state'] not in ('open', 'closed') or issue['comments'] < 0:
            raise ValueError('invalid issue')
        updated = _time(issue['updated_at'])
        if issue['state'] == 'closed':
            continue
        labels = {str(x).strip().casefold() for x in issue['labels']}
        if 'urgent' in labels:
            queue, score = ('urgent', 100)
        elif 'bug' in labels:
            queue, score = ('engineering', 40)
        elif 'docs' in labels:
            queue, score = ('docs', 10)
        else:
            queue, score = ('general', 0)
        score += min(issue['comments'], 20)
        score += min(max(0, (reference - updated).days), 30)
        result.append({'id': issue['id'], 'title': issue['title'].strip(), 'queue': queue, 'score': score, 'updated_at': issue['updated_at']})
    result.sort(key=lambda x: (queues[x['queue']], -x['score'], x['updated_at'], str(x['id'])))
    return result

def make_digest(items: list[dict]) -> dict:
    token = os.environ.get('TRIAGE_SIGNING_TOKEN')
    if not token:
        raise RuntimeError('TRIAGE_SIGNING_TOKEN is missing')
    grouped = {}
    for item in items:
        grouped.setdefault(item['queue'], []).append({'id': item['id'], 'score': item['score'], 'title': item['title'], 'updated_at': item['updated_at']})
    ordered = {queue: grouped[queue] for queue in ('urgent', 'engineering', 'docs', 'general') if queue in grouped}
    payload = json.dumps({'queues': ordered}, sort_keys=True, separators=(',', ':'))
    signature = hmac.new(token.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return {'payload': payload, 'signature': signature}

