import csv
import datetime
import os
import tempfile
_CATEGORIES = ('necessary', 'analytics', 'marketing', 'personalization')

def _time(value):
    if not isinstance(value, str):
        raise ValueError('invalid timestamp')
    try:
        return datetime.datetime.fromisoformat(value.replace('Z', '+00:00'))
    except (TypeError, ValueError):
        raise ValueError('invalid timestamp')

def aggregate_consents(events, as_of):
    cutoff = _time(as_of)
    chosen = {}
    for event in events:
        if not isinstance(event, dict):
            raise ValueError('invalid event')
        for key in ('user_id', 'category', 'status', 'timestamp'):
            if key not in event:
                raise ValueError('missing field')
        user = event['user_id']
        category = event['category']
        status = event['status']
        if not isinstance(user, str) or not user:
            raise ValueError('invalid user')
        if category not in _CATEGORIES or status not in ('granted', 'denied'):
            raise ValueError('invalid value')
        stamp = _time(event['timestamp'])
        if stamp <= cutoff:
            key = (user, category)
            old = chosen.get(key)
            if old is None or stamp >= old[0]:
                chosen[key] = (stamp, status == 'granted')
    users = sorted({key[0] for key in chosen})
    result = {}
    for user in users:
        result[user] = {category: chosen.get((user, category), (None, False))[1] for category in _CATEGORIES}
    return result

def export_consent_csv(events, destination, as_of):
    data = aggregate_consents(events, as_of)
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent, prefix='.consent-', suffix='.tmp')
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as stream:
            writer = csv.writer(stream, lineterminator='\n')
            writer.writerow(('user_id',) + _CATEGORIES)
            for user, values in data.items():
                writer.writerow((user,) + tuple(('true' if values[c] else 'false' for c in _CATEGORIES)))
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except OSError:
            pass
        raise
    return len(data)

