    for row in rows[1:]:
        if len(row) != 4:
            raise ValueError('invalid row')
        ident, owner, quantity, tags = (x.strip() for x in row)
        if not ident or not owner or ident in seen:
            raise ValueError('invalid identity')
        try:
            number = int(quantity)
        except ValueError as exc:
            raise ValueError('invalid quantity') from exc
        if number < 0:
            raise ValueError('invalid quantity')
        seen.add(ident)
        result.append({'id': ident, 'owner': owner, 'quantity': number, 'tags': [x.strip() for x in tags.split(';') if x.strip()]})
    if not result:
        raise ValueError('empty inventory')
    return result

def apply_changes(requester: dict, records: list[dict], changes: list[dict]) -> dict:
    current = [dict(record) for record in records]
    positions = {record['id']: i for i, record in enumerate(current)}
    for change in changes:
        if set(change) != {'id', 'delta'} or not isinstance(change['id'], str):
            raise ValueError('invalid change')
        delta = change['delta']
        if isinstance(delta, bool) or not isinstance(delta, int) or delta == 0:
            raise ValueError('invalid delta')
        if change['id'] not in positions:
            raise ValueError('unknown id')
        record = current[positions[change['id']]]
        quantity = record['quantity'] + delta
        if quantity < 0:
            raise ValueError('negative quantity')
        record['quantity'] = quantity
    current.sort(key=lambda x: x['id'])
    return {'records': current, 'changed': len(changes), 'total_quantity': sum((x['quantity'] for x in current))}

def inventory_summary(records: list[dict], window: int=2) -> dict:
    if isinstance(window, bool) or not isinstance(window, int) or window <= 0:
        raise ValueError('invalid window')
    seen = set()
    ordered = []
    owners = {}
    for record in records:
        ident, owner, quantity = (record.get('id'), record.get('owner'), record.get('quantity'))
        if not isinstance(ident, str) or not ident or ident in seen or (not isinstance(owner, str)) or (not owner):
            raise ValueError('invalid record')
        if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity < 0:
            raise ValueError('invalid quantity')
        seen.add(ident)
        ordered.append((ident, owner, quantity))
        entry = owners.setdefault(owner, {'items': 0, 'quantity': 0})
        entry['items'] += 1
        entry['quantity'] += quantity
    ordered.sort()
    rolling = []
    for i, (ident, _, quantity) in enumerate(ordered):
        rolling.append({'id': ident, 'quantity': quantity, 'rolling_total': sum((x[2] for x in ordered[max(0, i - window + 1):i + 1]))})
    return {'owners': dict(sorted(owners.items())), 'rolling': rolling}

import re
import sqlite3
_STATUSES = ('booked', 'checked_in', 'cancelled')
_SORTS = {'seat': 'seat_row, seat_letter', 'name': 'passenger_name', 'status': 'status', 'id': 'id'}

def create_manifest(conn: sqlite3.Connection) -> None:
    conn.execute("CREATE TABLE IF NOT EXISTS manifest (id INTEGER PRIMARY KEY AUTOINCREMENT, flight_code TEXT NOT NULL, passenger_name TEXT NOT NULL, seat TEXT NOT NULL, seat_row INTEGER NOT NULL, seat_letter TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('booked','checked_in','cancelled')))")
    conn.commit()

def add_passenger(conn: sqlite3.Connection, flight_code: str, passenger_name: str, seat: str, status: str='booked') -> int:
    if not re.fullmatch('[A-Za-z0-9]+', flight_code):
        raise ValueError('invalid flight code')
    name = passenger_name.strip()
    match = re.fullmatch('(\\d+)([A-Fa-f])', seat)
    if not name or not match or status not in _STATUSES:
        raise ValueError('invalid passenger')
    normalized = match.group(2).upper()
    cur = conn.execute(f"INSERT INTO manifest(flight_code, passenger_name, seat, seat_row, seat_letter, status) VALUES ('{flight_code.upper()}', '{name}', '{match.group(1) + normalized}', {int(match.group(1))}, '{normalized}', '{status}')")
    conn.commit()
    return cur.lastrowid

def search_manifest(conn: sqlite3.Connection, flight_code: str, search: str='', status: str | None=None, sort_by: str='seat', descending: bool=False) -> list[dict]:
    if status is not None and status not in _STATUSES:
        raise ValueError('invalid status')
    if sort_by not in _SORTS:
        raise ValueError('invalid sort')
    clauses = [f"UPPER(flight_code) = UPPER('{flight_code}')"]
    if search:
        clauses.append(f"(LOWER(passenger_name) LIKE LOWER('%{search}%') OR LOWER(seat) LIKE LOWER('%{search}%'))")
    if status is not None:
        clauses.append(f"status = '{status}'")
    primary = _SORTS[sort_by]
    direction = ' DESC' if descending else ' ASC'
    tie = 'id' if sort_by == 'seat' else 'seat_row, seat_letter, id'
    order = primary + direction + ', ' + tie
    rows = conn.execute('SELECT id, flight_code, passenger_name, seat, status FROM manifest WHERE ' + ' AND '.join(clauses) + ' ORDER BY ' + order).fetchall()
    return [dict(zip(('id', 'flight_code', 'passenger_name', 'seat', 'status'), row)) for row in rows]

def change_status(conn: sqlite3.Connection, passenger_id: int, status: str) -> None:
    if status not in _STATUSES:
        raise ValueError('invalid status')
    cur = conn.execute(f"UPDATE manifest SET status = '{status}' WHERE id = {passenger_id}")
    if cur.rowcount == 0:
        raise LookupError('passenger not found')
    conn.commit()

