def select_households(records: list[dict], formula: str, minimum: float, offset: int, limit: int) -> list[dict]:
    if isinstance(offset, bool) or isinstance(limit, bool) or (not isinstance(offset, int)) or (not isinstance(limit, int)) or (offset < 0) or (limit < 0):
        raise ValueError('offset and limit must be nonnegative integers')
    tree = ast.parse(formula, mode='eval')
    names = {'min': min, 'max': max, 'round': round}
    allowed = {'income', 'members', 'children', 'id'}

    def evaluate(node, values):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, complex)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id in values:
                return values[node.id]
            if node.id in names:
                return names[node.id]
            raise NameError("name '%s' is not defined" % node.id)
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
            value = evaluate(node.operand, values)
            return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
        if isinstance(node, ast.BinOp) and type(node.op) in {ast.Add, ast.Sub, ast.Mult, ast.Div}:
            a, b = (evaluate(node.left, values), evaluate(node.right, values))
            return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](a, b)
        if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
            result = evaluate(node.values[0], values)
            for child in node.values[1:]:
                if isinstance(node.op, ast.And) and (not result) or (isinstance(node.op, ast.Or) and result):
                    return result
                result = evaluate(child, values)
            return result
        if isinstance(node, ast.Compare):
            left = evaluate(node.left, values)
            ops = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}
            for op, part in zip(node.ops, node.comparators):
                right = evaluate(part, values)
                if not ops[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in names) and (not node.keywords):
            return names[node.func.id](*(evaluate(arg, values) for arg in node.args))
        raise ValueError('unsupported formula')
    scored = []
    for record in records:
        values = {'income': record['income'], 'members': record['members'], 'children': record.get('children', 0), 'id': record['id']}
        scored.append((evaluate(tree.body, values), record))
    selected = sorted((item for item in scored if item[0] >= minimum), key=lambda item: (-item[0], item[1]['id']))
    return [{'id': record['id'], 'score': round(float(score), 2), 'region': record['region']} for score, record in selected[offset:offset + limit]]

