def build_onboarding_batches(employee_records: list[dict], config: dict[str, str], batch_size: int=3) -> list[dict]:
    if not isinstance(batch_size, int) or isinstance(batch_size, bool) or batch_size <= 0:
        raise ValueError('batch_size must be a positive integer')
    key = config.get('workflow_key')
    if key is None or not isinstance(key, str) or key == '':
        raise ValueError('workflow_key is required')
    included = []
    required = ('employee_id', 'department', 'start_date', 'status')
    for record in employee_records:
        if not isinstance(record, dict) or any((not isinstance(record.get(field), str) or not record[field] for field in required)):
            raise ValueError('invalid employee record')
        try:
            date.fromisoformat(record['start_date'])
        except ValueError as exc:
            raise ValueError('invalid start_date') from exc
        if record['status'] == 'active':
            included.append(record)
    included.sort(key=lambda record: (record['start_date'], record['employee_id']))
    output = []
    for offset in range(0, len(included), batch_size):
        batch = included[offset:offset + batch_size]
        ids = [record['employee_id'] for record in batch]
        departments = {}
        for record in batch:
            departments[record['department']] = departments.get(record['department'], 0) + 1
        departments = {name: departments[name] for name in sorted(departments)}
        number = len(output) + 1
        start_date = batch[0]['start_date']
        department_text = ','.join((f'{name}:{departments[name]}' for name in departments))
        payload = f"{number}|{start_date}|{','.join(ids)}|{department_text}".encode()
        signature = hmac.new(key.encode(), payload, hashlib.sha256).hexdigest()
        output.append({'batch_number': number, 'employee_ids': ids, 'departments': departments, 'start_date': start_date, 'signature': signature})
    return output

