from datetime import date

def parse_complaints(payload: bytes) -> list[dict]:
    try:
        root = json.loads(payload.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid JSON') from exc
    if not isinstance(root, dict) or not isinstance(root.get('complaints'), list):
        raise ValueError('invalid batch')
    result = []
    seen = set()
    for item in root['complaints']:
        if not isinstance(item, dict):
            raise ValueError('invalid complaint')
        required = ('id', 'category', 'status', 'opened', 'priority', 'resolution_hours')
        if any((key not in item for key in required)):
            raise ValueError('missing field')
        ident, category, status, opened = (item[k] for k in ('id', 'category', 'status', 'opened'))
        priority = item['priority']
        hours = item['resolution_hours']
        if not isinstance(ident, str) or not ident or ident in seen:
            raise ValueError('invalid id')
        if not isinstance(category, str) or not category:
            raise ValueError('invalid category')
        if status not in ('open', 'pending', 'closed'):
            raise ValueError('invalid status')
        if not isinstance(opened, str):
            raise ValueError('invalid date')
        try:
            parsed_date = date.fromisoformat(opened)
        except ValueError as exc:
            raise ValueError('invalid date') from exc
        if parsed_date.isoformat() != opened:
            raise ValueError('invalid date')
        if isinstance(priority, bool) or not isinstance(priority, int) or (not 1 <= priority <= 5):
            raise ValueError('invalid priority')
        if isinstance(hours, bool) or not isinstance(hours, (int, float)) or (not math.isfinite(hours)) or (hours < 0):
            raise ValueError('invalid resolution')
        if status == 'closed' and hours == 0 or (status != 'closed' and hours != 0):
            raise ValueError('invalid resolution')
        seen.add(ident)
        result.append(dict(item))
    return result

def summarize_complaints(complaints: list[dict]) -> dict:
    groups = {}
    for item in complaints:
        valid = parse_complaints(json.dumps({'complaints': [item]}).encode())[0]
        category = valid['category']
        group = groups.setdefault(category, {'count': 0, 'closed': 0, 'hours': [], 'latest': ''})
        group['count'] += 1
        group['latest'] = max(group['latest'], valid['opened'])
        if valid['status'] == 'closed':
            group['closed'] += 1
            group['hours'].append(valid['resolution_hours'])
    rows = []
    for category, group in groups.items():
        average = round(sum(group['hours']) / len(group['hours']), 2) if group['hours'] else 0.0
        rows.append({'category': category, 'count': group['count'], 'closed': group['closed'], 'avg_resolution_hours': average, 'latest': group['latest']})
    rows.sort(key=lambda row: (-row['count'], -row['closed'], row['avg_resolution_hours'], row['category']))
    return {'total': len(complaints), 'categories': rows}

def verify_and_summarize(payload: bytes, signature: str, secret: bytes) -> dict:
    if not isinstance(payload, bytes) or not isinstance(signature, str) or (not isinstance(secret, bytes)):
        raise ValueError('invalid request')
    if len(signature) != 71 or not signature.startswith('sha256='):
        raise ValueError('invalid signature')
    supplied = signature[7:]
    if any((ch not in '0123456789abcdef' for ch in supplied)):
        raise ValueError('invalid signature')
    expected = hmac.new(secret, payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, supplied):
        raise ValueError('invalid signature')
    return summarize_complaints(parse_complaints(payload))

