    totals = {}
    for booking in bookings:
        if not isinstance(booking, dict) or set(booking) != {'desk', 'member', 'hours', 'date'}:
            raise ValueError('invalid booking')
        desk = booking['desk']
        member = booking['member']
        hours = booking['hours']
        date = booking['date']
        if not isinstance(desk, str) or not desk or (not isinstance(member, str)) or (not member):
            raise ValueError('invalid booking')
        if isinstance(hours, bool) or not isinstance(hours, (int, float)) or (not math.isfinite(hours)) or (hours <= 0):
            raise ValueError('invalid booking')
        if not isinstance(date, str):
            raise ValueError('invalid booking')
        try:
            parsed = datetime.date.fromisoformat(date)
        except ValueError:
            raise ValueError('invalid booking')
        if parsed.isoformat() != date:
            raise ValueError('invalid booking')
        if desk not in totals:
            totals[desk] = [0.0, 0]
        totals[desk][0] += float(hours)
        totals[desk][1] += 1
    ordered = sorted(totals.items(), key=lambda item: (-item[1][0], item[0]))
    result = {desk: {'total_hours': round(values[0], 2), 'booking_count': values[1]} for desk, values in ordered}
