import hashlib
import hmac
import json
import re

def _fields(line):
    out, cur, esc = ([], [], False)
    for ch in line:
        if esc:
            if ch == 'n':
                cur.append('\n')
            elif ch in '\\|':
                cur.append(ch)
            else:
                raise ValueError('escape')
            esc = False
        elif ch == '\\':
            esc = True
        elif ch == '|':
            out.append(''.join(cur))
            cur = []
        else:
            cur.append(ch)
    if esc:
        raise ValueError('escape')
    out.append(''.join(cur))
    if len(out) != 5:
        raise ValueError('fields')
    return out

def parse_report(text: str) -> list[dict]:
    if not isinstance(text, str):
        raise TypeError('text')
    result, seen = ([], set())
    for line in text.splitlines():
        if not line:
            continue
        ident, date, category, amount, note = _fields(line)
        if not re.fullmatch('[A-Z0-9-]+', ident) or ident in seen:
            raise ValueError('id')
        try:
            datetime.date.fromisoformat(date)
        except Exception:
            raise ValueError('date')
        if not category or len(category) > 30:
            raise ValueError('category')
        if not re.fullmatch('(?:0|[1-9][0-9]*)\\.[0-9]{2}', amount):
            raise ValueError('amount')
        seen.add(ident)
        result.append({'id': ident, 'date': date, 'category': category, 'cents': int(amount.replace('.', '')), 'note': note})
    return result

def canonical_report(records: list[dict]) -> bytes:
    ordered = sorted(records, key=lambda r: (r['date'], r['id']))
    return json.dumps(ordered, sort_keys=True, separators=(',', ':')).encode()

def verify_report(secret: bytes, signature: str, text: str) -> list[dict]:
    records = parse_report(text)
    if not isinstance(signature, str) or len(signature) != 64 or (not re.fullmatch('[0-9a-fA-F]{64}', signature)):
        raise ValueError('signature')
    expected = hmac.new(secret, canonical_report(records), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected.lower(), signature.lower()):
        raise ValueError('signature')
    return records

