    cats, months = ({}, {})
    for r in records:
        cats[r['category']] = cats.get(r['category'], 0) + r['cents']
        month = r['date'][:7]
        months[month] = months.get(month, 0) + r['cents']
    return {'count': len(records), 'by_category': dict(sorted(cats.items())), 'by_month': dict(sorted(months.items()))}

