import csv
import os
import tempfile
from collections import defaultdict
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def export_ancillary_report(records: list[dict], output_path: str, page: int=1, page_size: int=10) -> dict:
    if isinstance(records, (str, bytes)):
        raise TypeError('records must be a list')
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    groups = defaultdict(lambda: {'units': 0, 'revenue': Decimal('0'), 'bookings': set()})
    currency = 'USD'
    for record in records:
        if not isinstance(record, dict):
            raise TypeError('each record must be a dictionary')
        for key in ('booking_id', 'ancillary', 'quantity', 'unit_price', 'currency'):
            if key not in record:
                raise ValueError('missing field')
        if not isinstance(record['booking_id'], str) or not record['booking_id']:
            raise ValueError('invalid booking')
        if not isinstance(record['ancillary'], str) or not record['ancillary']:
            raise ValueError('invalid ancillary')
        if isinstance(record['quantity'], bool) or not isinstance(record['quantity'], int) or record['quantity'] <= 0:
            raise ValueError('invalid quantity')
        if not isinstance(record['currency'], str) or len(record['currency']) != 3 or (not record['currency'].isupper()) or (not record['currency'].isalpha()):
            raise ValueError('invalid currency')
        if currency == 'USD' and (not groups):
            currency = record['currency']
        elif record['currency'] != currency:
            raise ValueError('mixed currencies')
        try:
            price = Decimal(str(record['unit_price']))
        except (InvalidOperation, ValueError):
            raise ValueError('invalid price')
        if not price.is_finite() or price < 0:
            raise ValueError('invalid price')
        group = groups[record['ancillary']]
        group['units'] += record['quantity']
        group['revenue'] += price * record['quantity']
        group['bookings'].add(record['booking_id'])
    quant = Decimal('0.01')
    all_rows = []
    for name, group in groups.items():
        all_rows.append({'ancillary': name, 'units': group['units'], 'bookings': len(group['bookings']), 'revenue': format(group['revenue'].quantize(quant, rounding=ROUND_HALF_UP), '.2f')})
    all_rows.sort(key=lambda row: (-Decimal(row['revenue']), row['ancillary']))
    pages = (len(all_rows) + page_size - 1) // page_size
    selected = all_rows[(page - 1) * page_size:page * page_size]
    fd, temporary = tempfile.mkstemp(prefix='ancillary-', suffix='.csv')
    os.close(fd)
    try:
        with open(temporary, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle)
            writer.writerow(['ancillary', 'units', 'bookings', 'revenue'])
            for row in selected:
                writer.writerow([row['ancillary'], row['units'], row['bookings'], row['revenue']])
        os.replace(temporary, output_path)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    total_units = sum((row['units'] for row in all_rows))
    total_revenue = sum((Decimal(row['revenue']) for row in all_rows), Decimal('0')).quantize(quant)
    return {'currency': currency, 'total_units': total_units, 'total_revenue': format(total_revenue, '.2f'), 'page': page, 'pages': pages, 'rows': selected}

