def build_incident_report(requester: dict, incidents: list[dict], page: int=1, page_size: int=20) -> dict:
    if not isinstance(requester, dict) or not isinstance(incidents, list):
        raise TypeError()
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)):
        raise TypeError()
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError()
    if requester.get('role') not in ('supervisor', 'dispatcher'):
        raise PermissionError()
    allowed = []
    for item in incidents:
        if not isinstance(item, dict):
            raise TypeError()
        required = ('id', 'tenant_id', 'reported_by', 'severity', 'status', 'response_minutes', 'occurred_at')
        if any((key not in item for key in required)):
            raise ValueError()
        if item['severity'] not in ('critical', 'high', 'medium', 'low') or item['status'] not in ('open', 'contained', 'closed'):
            raise ValueError()
        if not isinstance(item['response_minutes'], (int, float)) or isinstance(item['response_minutes'], bool) or item['response_minutes'] < 0:
            raise ValueError()
        try:
            stamp = datetime.fromisoformat(item['occurred_at'].replace('Z', '+00:00'))
        except (TypeError, ValueError):
            raise ValueError()
        if item['tenant_id'] != requester.get('tenant_id'):
            continue
        if requester.get('role') != 'supervisor' and item['reported_by'] != requester.get('id'):
            continue
        allowed.append((stamp, item))
    allowed.sort(key=lambda pair: (-pair[0].timestamp(), pair[1]['id']))
    sev = {x: 0 for x in ('critical', 'high', 'medium', 'low')}
    stat = {x: 0 for x in ('open', 'contained', 'closed')}
    for _, item in allowed:
        sev[item['severity']] += 1
        stat[item['status']] += 1
    total = len(allowed)
    average = round(sum((x[1]['response_minutes'] for x in allowed)) / total, 2) if total else 0.0
    start = (page - 1) * page_size
    return {'total': total, 'page': page, 'page_size': page_size, 'incidents': [dict(x[1]) for x in allowed[start:start + page_size]], 'by_severity': sev, 'by_status': stat, 'average_response_minutes': average}

