import os
import tempfile

def export_eligibility_report(records: list[dict], as_of: str, output_path: str) -> dict:
    try:
        reference = datetime.date.fromisoformat(as_of)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    allowed = ['O-', 'O+', 'A-', 'A+', 'B-', 'B+', 'AB-', 'AB+']
    eligible = []
    for record in records:
        try:
            donor_id = record['donor_id']
            birth = datetime.date.fromisoformat(record['birth_date'])
            donation_value = record['last_donation']
            donation = None if donation_value is None else datetime.date.fromisoformat(donation_value)
            status = record['status']
            weight = record['weight_kg']
            hemoglobin = record['hemoglobin']
            blood_type = record['blood_type']
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid record')
        if not isinstance(donor_id, str) or not donor_id or (not isinstance(status, str)) or (not status):
            raise ValueError('invalid record')
        if isinstance(weight, bool) or not isinstance(weight, (int, float)) or isinstance(hemoglobin, bool) or (not isinstance(hemoglobin, (int, float))):
            raise ValueError('invalid record')
        if blood_type not in allowed or birth > reference or (donation is not None and donation > reference):
            raise ValueError('invalid record')
        age = reference.year - birth.year - ((reference.month, reference.day) < (birth.month, birth.day))
        days = None if donation is None else (reference - donation).days
        if status == 'active' and 18 <= age <= 65 and (weight >= 50) and (hemoglobin >= 12.5) and (days is None or days >= 56):
            eligible.append((donor_id, blood_type, age, days))
    eligible.sort(key=lambda row: row[0])
    counts = {}
    for donor_id, blood_type, age, days in eligible:
        counts[blood_type] = counts.get(blood_type, 0) + 1
    counts = {blood_type: counts[blood_type] for blood_type in allowed if blood_type in counts}
    temporary_path = tempfile.mktemp(prefix='eligibility-', suffix='.csv', dir=os.path.dirname(os.path.abspath(output_path)))
    try:
        with open(temporary_path, 'w', newline='', encoding='utf-8') as stream:
            writer = csv.writer(stream)
            writer.writerow(['donor_id', 'blood_type', 'age', 'days_since_last_donation'])
            for donor_id, blood_type, age, days in eligible:
                writer.writerow([donor_id, blood_type, age, '' if days is None else days])
        os.replace(temporary_path, output_path)
    finally:
        if os.path.exists(temporary_path):
            os.unlink(temporary_path)
    return {'eligible_count': len(eligible), 'by_blood_type': counts}

