from pathlib import Path

def collect_note_lines(directory: str, pattern: str) -> list[str]:
    if not pattern:
        raise ValueError('pattern must not be empty')
    root = Path(directory)
    if not root.is_dir():
        raise FileNotFoundError(directory)
    result = []
    for path in sorted(root.glob('*.txt'), key=lambda p: p.name):
        completed = subprocess.run(['grep', '-h', '-F', pattern, str(path)], capture_output=True, text=True)
        if completed.returncode not in (0, 1):
            raise OSError(completed.stderr.strip() or 'unable to read note file')
        result.extend(completed.stdout.splitlines())
    return result

def parse_case_notes(lines: list[str]) -> list[dict]:
    latest = {}
    for line in lines:
        if not line.strip():
            continue
        parts = line.split('|', 4)
        if len(parts) != 5:
            raise ValueError('malformed note')
        raw_date, case_id, raw_priority, status, note = parts
        try:
            parsed_date = date.fromisoformat(raw_date.strip())
            priority = int(raw_priority.strip())
        except (ValueError, TypeError):
            raise ValueError('malformed note')
        case_id = case_id.strip()
        status = status.strip()
        if not case_id or priority not in range(1, 6) or status not in {'open', 'monitoring', 'closed'}:
            raise ValueError('malformed note')
        record = {'date': parsed_date, 'case_id': case_id, 'priority': priority, 'status': status, 'note': note}
        previous = latest.get(case_id)
        if previous is None or parsed_date >= previous['date']:
            latest[case_id] = record
    return sorted(latest.values(), key=lambda item: (item['case_id'], item['date']))

def build_followup_queue(records: list[dict], as_of: str, window_days: int) -> list[dict]:
    try:
        cutoff = date.fromisoformat(as_of)
    except (ValueError, TypeError):
        raise ValueError('invalid date')
    if window_days < 0:
        raise ValueError('invalid window')
    selected = []
    for record in records:
        age = (cutoff - record['date']).days
        if record['status'] in {'open', 'monitoring'} and 0 <= age <= window_days:
            selected.append({'case_id': record['case_id'], 'date': record['date'].isoformat(), 'priority': record['priority'], 'status': record['status'], 'note': record['note']})
    return sorted(selected, key=lambda item: (item['priority'], item['date'], item['case_id']))

