import math

def enrollment_summary(xml_text: str, page: int=1, page_size: int=20) -> list[dict]:
    if not isinstance(xml_text, str):
        raise ValueError('xml_text must be a string')
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('page must be positive')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('page_size must be positive')
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode('utf-8'), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'enrollments':
        raise ValueError('invalid root')
    groups = {}
    for item in root:
        if item.tag != 'enrollment':
            raise ValueError('invalid enrollment')
        for name in ('course_id', 'status', 'score'):
            if name not in item.attrib:
                raise ValueError('missing attribute')
        course_id = item.attrib['course_id'].strip()
        if not course_id:
            raise ValueError('empty course')
        if item.attrib['status'] != 'completed':
            continue
        try:
            score = float(item.attrib['score'])
        except Exception as exc:
            raise ValueError('invalid score') from exc
        if not math.isfinite(score) or not 0 <= score <= 100:
            raise ValueError('invalid score')
        groups.setdefault(course_id, []).append(score)
    result = [{'course_id': key, 'completed': len(values), 'average_score': round(sum(values) / len(values), 2)} for key, values in groups.items()]
    result.sort(key=lambda row: (-row['completed'], -row['average_score'], row['course_id']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

