import hmac
import os

def make_credential(password: str) -> str:
    if not isinstance(password, str) or not password:
        raise ValueError('invalid password')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return 'p$' + salt.hex() + '$' + digest.hex()

def check_credential(password: str, stored: str) -> bool:
    if not isinstance(password, str) or not isinstance(stored, str):
        return False
    parts = stored.split('$')
    if len(parts) != 3 or parts[0] != 'p':
        return False
    try:
        salt = bytes.fromhex(parts[1])
        expected = bytes.fromhex(parts[2])
    except ValueError:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def parse_stands(text: str) -> list[dict]:
    if not isinstance(text, str) or not text.strip():
        raise ValueError('empty inventory')
    try:
        rows = list(csv.reader(text.splitlines(), delimiter=';', skipinitialspace=False))
    except csv.Error as exc:
        raise ValueError('bad csv') from exc
    while rows and (not any((x.strip() for x in rows[0]))):
        rows.pop(0)
    if not rows or rows[0] != ['id', 'species', 'hectares', 'age', 'slope', 'zone']:
        raise ValueError('bad header')
    result = []
    seen = set()
    for row in rows[1:]:
        if not row or not any((x.strip() for x in row)):
            continue
        if len(row) != 6:
            raise ValueError('bad row')
        vals = [x.strip() for x in row]
        try:
            item = {'id': vals[0], 'species': vals[1], 'hectares': float(vals[2]), 'age': int(vals[3]), 'slope': float(vals[4]), 'zone': vals[5]}
        except (ValueError, OverflowError):
            raise ValueError('bad number')
        if not item['id'] or not item['species'] or item['hectares'] <= 0 or (item['age'] < 0) or (not 0 <= item['slope'] <= 90) or (item['id'] in seen):
            raise ValueError('bad row')
        seen.add(item['id'])
        result.append(item)
    return result

def schedule_harvest(stands: list[dict], password: str, stored: str, capacity: float, minimum_age: int=40, maximum_slope: float=35.0) -> list[dict]:
    if not check_credential(password, stored):
        raise PermissionError('invalid credentials')
    if capacity < 0 or minimum_age < 0 or (not 0 <= maximum_slope <= 90):
        raise ValueError('invalid limits')
    needed = {'id', 'species', 'hectares', 'age', 'slope', 'zone'}
    candidates = []
    for source in stands:
        if not isinstance(source, dict) or not needed <= source.keys():
            raise ValueError('bad stand')
        try:
            area, age, slope = (float(source['hectares']), int(source['age']), float(source['slope']))
        except (ValueError, TypeError, OverflowError):
            raise ValueError('bad stand')
        if area <= 0 or age < 0 or (not 0 <= slope <= 90):
            raise ValueError('bad stand')
        if age >= minimum_age and slope <= maximum_slope and (str(source['zone']).lower() != 'protected'):
            candidates.append((age * area, age, area, str(source['id']), source))
