import subprocess

def _records(path):
    result = subprocess.run(['sort', '-t', '|', '-k1,1n', '-k2,2', '-k3,3', path], capture_output=True, text=True, check=True)
    records = []
    for raw in result.stdout.splitlines():
        if not raw.strip():
            continue
        fields = raw.split('|')
        if len(fields) != 5:
            raise ValueError('invalid record')
        parts = [x.strip() for x in fields]
        if not parts[1] or not parts[2]:
            raise ValueError('invalid record')
        try:
            timestamp, score, duration = (int(parts[0]), int(parts[3]), int(parts[4]))
        except ValueError as exc:
            raise ValueError('invalid record') from exc
        if timestamp < 0 or score < 0 or duration <= 0:
            raise ValueError('invalid record')
        records.append({'timestamp': timestamp, 'machine': parts[1], 'game': parts[2], 'score': score, 'duration': duration})
    return records

def read_events(path: str) -> list[dict]:
    return _records(path)

def summarize(path: str, limit: int=10) -> dict:
    if limit < 0:
        raise ValueError('negative limit')
    machines = {}
    for event in read_events(path):
        machine = machines.setdefault(event['machine'], {'plays': 0, 'score': 0, 'games': {}})
        machine['plays'] += 1
        machine['score'] += event['score']
        game = machine['games'].setdefault(event['game'], {'plays': 0, 'score': 0, 'best': 0})
        game['plays'] += 1
        game['score'] += event['score']
        game['best'] = max(game['best'], event['score'])
    ordered = {m: {'plays': machines[m]['plays'], 'score': machines[m]['score'], 'games': {g: machines[m]['games'][g] for g in sorted(machines[m]['games'])}} for m in sorted(machines)}
    board = []
    for machine in ordered:
        for game, data in ordered[machine]['games'].items():
            board.append({'machine': machine, 'game': game, **data})
    board.sort(key=lambda x: (-x['score'], -x['plays'], x['machine'], x['game']))
    return {'machines': ordered, 'leaderboard': board[:limit]}

