import secrets

def build_housekeeping_dispatch(tasks: list[dict], page: int=1, page_size: int=10) -> dict:
    if not isinstance(tasks, list):
        raise ValueError('tasks must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
    grouped = {}
    for item in tasks:
        if not isinstance(item, dict):
            raise ValueError('invalid task')
        required = {'room', 'task', 'minutes', 'priority', 'status'}
        if set(item) != required:
            raise ValueError('invalid task fields')
        room = item['room']
        task = item['task']
        minutes = item['minutes']
        priority = item['priority']
        status = item['status']
        if isinstance(room, bool) or not isinstance(room, int) or (not 1 <= room <= 9999):
            raise ValueError('invalid room')
        if not isinstance(task, str) or not task.strip():
            raise ValueError('invalid task name')
        if isinstance(minutes, bool) or not isinstance(minutes, int) or minutes <= 0:
            raise ValueError('invalid minutes')
        if isinstance(priority, bool) or not isinstance(priority, int) or (not 1 <= priority <= 5):
            raise ValueError('invalid priority')
        if status not in {'open', 'done'}:
            raise ValueError('invalid status')
        if status == 'open':
            if room not in grouped:
                grouped[room] = {'tasks': 0, 'minutes': 0, 'priority': 0}
            grouped[room]['tasks'] += 1
            grouped[room]['minutes'] += minutes
            grouped[room]['priority'] = max(grouped[room]['priority'], priority)
    ordered = sorted(grouped, key=lambda room: (-grouped[room]['priority'], room))
    start = (page - 1) * page_size
    selected = ordered[start:start + page_size]
    rooms = [{'room': room, **grouped[room]} for room in selected]
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    dispatch_id = ''.join((secrets.choice(alphabet) for _ in range(12)))
    return {'dispatch_id': dispatch_id, 'page': page, 'page_size': page_size, 'total_rooms': len(ordered), 'rooms': rooms}

