def build_certificate_report(xml_text: str, min_score: float=0.0, page: int=1, page_size: int=20) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page <= 0:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size <= 0:
        raise ValueError('invalid page size')
    if min_score < 0 or min_score > 100:
        raise ValueError('invalid minimum score')
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode('utf-8'), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'certificates':
        raise ValueError('invalid root')
    records = []
    for node in root.findall('certificate'):
        values = {}
        for name in ('learner', 'course', 'score', 'issued'):
            child = node.find(name)
            if child is None or child.text is None or (not child.text.strip()):
                raise ValueError('missing field')
            values[name] = child.text.strip()
        try:
            score = float(values['score'])
        except (TypeError, ValueError) as exc:
            raise ValueError('invalid score') from exc
        if score >= min_score:
            records.append({'learner': values['learner'], 'course': values['course'], 'score': score, 'issued': values['issued']})
