            raise ValueError('school must be a non-empty string')
        if not isinstance(grade, int) or isinstance(grade, bool) or grade not in range(9, 13):
            raise ValueError('grade must be between 9 and 12')
        if status not in {'enrolled', 'withdrawn'}:
            raise ValueError('invalid status')
        if status == 'enrolled':
