            groups[school]['count'] += 1
            groups[school]['grades'].add(grade)
    schools = [{'school': name, 'count': value['count'], 'grades': sorted(value['grades'])} for name, value in groups.items()]
    schools.sort(key=lambda item: (-item['count'], item['school']))
    start = (page - 1) * page_size
