import hashlib
import hmac
import json
import os
from collections import defaultdict
from datetime import date
from typing import Mapping, Sequence

def build_roster(assignments: Sequence[Mapping[str, str]]) -> dict:
    grouped = defaultdict(list)
    totals = defaultdict(int)
    occupied = defaultdict(list)
    for item in assignments:
        required = ('date', 'start', 'end', 'crew', 'role', 'origin', 'destination')
        if any((k not in item for k in required)):
            raise ValueError('assignment is missing a required field')
        try:
            date.fromisoformat(item['date'])
            sh, sm = map(int, item['start'].split(':'))
            eh, em = map(int, item['end'].split(':'))
        except Exception as exc:
            raise ValueError('invalid date or time') from exc
        if not (0 <= sh < 24 and 0 <= eh < 24 and (0 <= sm < 60) and (0 <= em < 60)):
            raise ValueError('invalid date or time')
        if any((not item[k] for k in ('crew', 'role', 'origin', 'destination'))):
            raise ValueError('assignment contains an empty value')
        start, end = (sh * 60 + sm, eh * 60 + em)
        if end <= start:
            end += 1440
        minutes = end - start
        if minutes > 1440:
            raise ValueError('duty exceeds 24 hours')
        key = (item['date'], item['crew'])
        for old_start, old_end in occupied[key]:
            if start < old_end and old_start < end:
                raise ValueError('crew duties overlap')
        occupied[key].append((start, end))
        shift = {'date': item['date'], 'crew': item['crew'], 'role': item['role'], 'origin': item['origin'], 'destination': item['destination'], 'start': item['start'], 'end': item['end'], 'minutes': minutes}
        grouped[item['date']].append(shift)
        totals[item['crew']] += minutes
    days = []
    for day in sorted(grouped):
        shifts = sorted(grouped[day], key=lambda x: (x['start'], x['origin'], x['destination'], x['crew'], x['role']))
        days.append({'date': day, 'shifts': shifts})
    hours = {crew: round(totals[crew] / 60, 2) for crew in sorted(totals)}
    return {'days': days, 'crew_hours': hours}

def export_roster(roster: Mapping[str, object], config: Mapping[str, str] | None=None) -> str:
    key = config.get('signing_key') if config is not None else None
    if key is None:
        key = os.environ.get('ROSTER_SIGNING_KEY')
    if not key:
        raise ValueError('missing roster signing key')
    payload = json.dumps(roster, sort_keys=True, separators=(',', ':'))
    signature = hmac.new(key.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return payload + '.' + signature

