import hmac
import json
import math

def summarize_visitors(payload: bytes, signature: str, secret: str, page: int=1, per_page: int=10) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(per_page, int) or isinstance(per_page, bool) or (not 1 <= per_page <= 100):
        raise ValueError('invalid per_page')
    expected = hmac.new(secret.encode('utf-8'), payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise PermissionError('invalid signature')
    try:
        data = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError, TypeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(data, list):
        raise ValueError('events must be a list')
    groups = {}
    for event in data:
        if not isinstance(event, dict) or set(event) != {'visitor', 'path', 'year', 'duration'}:
            raise ValueError('invalid event')
        visitor = event['visitor']
        path = event['path']
        year = event['year']
        duration = event['duration']
        if not isinstance(visitor, str) or not visitor or (not isinstance(path, str)) or (not path.startswith('/')):
            raise ValueError('invalid event')
        if isinstance(year, bool) or not isinstance(year, int) or (not 1990 <= year <= 2100):
            raise ValueError('invalid event')
        if isinstance(duration, bool) or not isinstance(duration, (int, float)) or duration < 0:
            raise ValueError('invalid event')
        if visitor not in groups:
            groups[visitor] = {'views': 0, 'seconds': 0, 'paths': set()}
        group = groups[visitor]
        group['views'] += 1
        group['seconds'] += duration
        group['paths'].add(path)
    names = sorted(groups, key=lambda name: (-groups[name]['views'], name))
    pages = math.ceil(len(names) / per_page) if names else 0
    start = (page - 1) * per_page
    rows = []
    for name in names[start:start + per_page]:
        group = groups[name]
        rows.append({'visitor': name, 'views': group['views'], 'seconds': group['seconds'], 'paths': len(group['paths']), 'average_seconds': round(group['seconds'] / group['views'], 2)})
    return {'total_events': len(data), 'total_visitors': len(names), 'page': page, 'per_page': per_page, 'pages': pages, 'visitors': rows}

