def evaluate_rule(expression: str, names: dict[str, int | float | bool]) -> bool | int | float:
    try:
        tree = ast.parse(expression, mode='eval').body
        return _rule_node(tree, names)
    except ValueError:
        raise
    except Exception as exc:
        raise ValueError('invalid expression') from exc

def _rule_node(node, names):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in names:
            raise ValueError('unknown name')
        return names[node.id]
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
        value = _rule_node(node.operand, names)
        return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
    if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
        a, b = (_rule_node(node.left, names), _rule_node(node.right, names))
        return a + b if isinstance(node.op, ast.Add) else a - b if isinstance(node.op, ast.Sub) else a * b if isinstance(node.op, ast.Mult) else a / b
    if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
        value = _rule_node(node.values[0], names)
        for part in node.values[1:]:
            if isinstance(node.op, ast.And) and (not value):
                return value
            if isinstance(node.op, ast.Or) and value:
                return value
            value = _rule_node(part, names)
        return value
    if isinstance(node, ast.Compare):
        left = _rule_node(node.left, names)
        for op, item in zip(node.ops, node.comparators):
            right = _rule_node(item, names)
            ok = {ast.Lt: left < right, ast.LtE: left <= right, ast.Gt: left > right, ast.GtE: left >= right, ast.Eq: left == right, ast.NotEq: left != right}.get(type(op))
            if ok is None:
                raise ValueError('operator not allowed')
            if not ok:
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
        if node.func.id == 'round' and len(node.args) not in (1, 2):
            raise ValueError('invalid call')
        return {'min': min, 'max': max, 'round': round}[node.func.id](*[_rule_node(x, names) for x in node.args])
    raise ValueError('unsupported expression')

def process_access_events(events, rule, variables):
    required = ('user', 'door', 'timestamp', 'granted', 'level')
    checked = []
    for i, e in enumerate(events):
        if not isinstance(e, dict) or set(e) != set(required) or (not isinstance(e['user'], str)) or (not isinstance(e['door'], str)) or (not isinstance(e['timestamp'], int)) or isinstance(e['timestamp'], bool) or (e['timestamp'] < 0) or (not isinstance(e['granted'], bool)) or (not isinstance(e['level'], int)) or isinstance(e['level'], bool):
            raise ValueError('invalid event')
        scope = dict(variables)
        scope.update(e)
        if evaluate_rule(rule, scope) and e['granted']:
            checked.append((e['timestamp'], i, e))
    accepted = []
    history = {}
    for t, i, e in sorted(checked, key=lambda x: (x[0], x[1])):
        prior = history.setdefault(e['user'], [])
        if any((d == e['door'] and t - p < 300 for p, d in prior)) or sum((t - p <= 600 for p, d in prior)) >= 2:
