import csv
import hashlib
import hmac
import math
import os

def create_operator_record(operator_id: str, password: str) -> dict:
    if not isinstance(operator_id, str) or not operator_id or (not isinstance(password, str)) or (not password):
        raise ValueError()
    salt = os.urandom(16)
    iterations = 100000
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, iterations)
    return {'operator_id': operator_id, 'salt': salt.hex(), 'iterations': iterations, 'digest': digest.hex()}

def verify_operator_password(record: dict, password: str) -> bool:
    if not isinstance(record, dict) or not isinstance(password, str):
        return False
    try:
        salt = bytes.fromhex(record['salt'])
        iterations = record['iterations']
        expected = bytes.fromhex(record['digest'])
        if not isinstance(iterations, int) or iterations < 100000:
            return False
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, iterations)
        return hmac.compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError):
        return False

def summarize_tracks(lines: list[str], window_seconds: int) -> dict:
    if not isinstance(window_seconds, int) or isinstance(window_seconds, bool) or window_seconds <= 0:
        raise ValueError()
    groups = {}
    for line in lines:
        if not isinstance(line, str):
            raise ValueError()
        if not line.strip():
            continue
        try:
            fields = next(csv.reader([line]))
        except Exception as exc:
            raise ValueError() from exc
        fields = [x.strip() for x in fields]
        if fields == ['collar_id', 'timestamp', 'latitude', 'longitude', 'battery'] and (not groups):
            continue
        if len(fields) != 5:
            raise ValueError()
        collar = fields[0]
        try:
            timestamp = int(fields[1])
            lat = float(fields[2])
            lon = float(fields[3])
            battery = float(fields[4])
        except (ValueError, OverflowError):
            raise ValueError()
        if not collar or timestamp < 0 or (not all((math.isfinite(x) for x in (lat, lon, battery)))) or (not (-90 <= lat <= 90 and -180 <= lon <= 180 and (0 <= battery <= 100))):
            raise ValueError()
        groups.setdefault(collar, []).append((timestamp, lat, lon, battery))
    output = {}
    for collar in sorted(groups):
        points = sorted(groups[collar], key=lambda x: x[0])
        distance = 0.0
        for a, b in zip(points, points[1:]):
            p, q = (math.radians(a[1]), math.radians(b[1]))
            dp = math.radians(b[1] - a[1])
            dl = math.radians(b[2] - a[2])
            z = math.sin(dp / 2) ** 2 + math.cos(p) * math.cos(q) * math.sin(dl / 2) ** 2
            distance += 6371.0 * 2 * math.asin(math.sqrt(min(1.0, z)))
        base = points[0][0]
        windows = {}
        for timestamp, lat, lon, battery in points:
            start = base + (timestamp - base) // window_seconds * window_seconds
            windows.setdefault(start, []).append((timestamp, battery))
        packed = []
        for start in sorted(windows):
            values = windows[start]
            batteries = [x[1] for x in values]
            packed.append({'start': start, 'end': max((x[0] for x in values)), 'count': len(values), 'average_battery': round(sum(batteries) / len(batteries), 2), 'minimum_battery': round(min(batteries), 2)})
        output[collar] = {'points': len(points), 'distance_km': round(distance, 3), 'windows': packed}
    return output

