import csv
import datetime
import os
import tempfile
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def build_closing_summary(records: list[dict], page: int=1, page_size: int=50) -> str:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page_size')
    grouped = {}
    for record in records:
        if not isinstance(record, dict) or not all((k in record for k in ('property_id', 'closing_date', 'net_amount', 'status'))):
            raise ValueError('invalid record')
        date_text = record['closing_date']
        try:
            datetime.date.fromisoformat(date_text)
        except (TypeError, ValueError):
            raise ValueError('invalid date')
        if record['status'] not in {'scheduled', 'completed', 'cancelled'}:
            raise ValueError('invalid status')
        try:
            amount = Decimal(str(record['net_amount']))
        except (InvalidOperation, ValueError, TypeError):
            raise ValueError('invalid amount')
        if isinstance(record['net_amount'], bool) or not amount.is_finite():
            raise ValueError('invalid amount')
        if record['status'] != 'cancelled':
            count, total = grouped.get(date_text, (0, Decimal('0')))
            grouped[date_text] = (count + 1, total + amount)
    rows = []
    for date_text in sorted(grouped):
        count, total = grouped[date_text]
        total = total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        rows.append([date_text, str(count), format(total, '.2f')])
    start = (page - 1) * page_size
    rows = rows[start:start + page_size]
    fd, path = tempfile.mkstemp(prefix='closing_summary_', suffix='.csv')
    os.close(fd)
    try:
        with open(path, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['closing_date', 'transaction_count', 'total_net_amount'])
            writer.writerows(rows)
        with open(path, 'r', newline='', encoding='utf-8') as handle:
            return handle.read()
    finally:
        try:
            os.unlink(path)
        except FileNotFoundError:
            pass

