import os

def store_matter_document(base_dir: str, matter_id: str, filename: str, content: str) -> str:
    if not matter_id or not filename:
        raise ValueError('matter_id and filename must be non-empty')
    base = os.path.realpath(base_dir)
    candidate = os.path.realpath(os.path.join(base, matter_id, filename))
    try:
        inside = os.path.commonpath((base, candidate)) == base
    except ValueError:
        inside = False
    if not inside:
        raise ValueError('filename is outside the base directory')
    os.makedirs(os.path.dirname(candidate), exist_ok=True)
    with open(candidate, 'w', encoding='utf-8') as handle:
        handle.write(content)
    return os.path.join(base_dir, matter_id, filename)

import os
from pathlib import Path

def save_member_document(base_dir: str, member_id: str, filename: str, content: str) -> str:
    if not os.path.isdir(base_dir):
        raise FileNotFoundError(base_dir)
    if not isinstance(member_id, str) or not member_id:
        raise ValueError('member_id must not be empty')
    if not isinstance(filename, str) or not filename:
        raise ValueError('filename must not be empty')
    base = Path(base_dir).resolve()
    target = (base / member_id / filename).resolve()
    try:
        target.relative_to(base)
    except ValueError:
        raise ValueError('document path is outside base directory')
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding='utf-8')
    return str(target)

