import hashlib
import hmac
import os
from typing import Any

def hash_booking_pin(pin: str) -> str:
    if not isinstance(pin, str):
        raise TypeError('pin must be a string')
    if not pin:
        raise ValueError('pin must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def verify_booking_pin(pin: str, stored: str) -> bool:
    if not isinstance(pin, str) or not isinstance(stored, str):
        return False
    try:
        salt_text, digest_text = stored.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except ValueError:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def quote_rates(records: list[dict[str, Any]], max_transit_days: int, page: int=1, page_size: int=10) -> list[dict[str, Any]]:
    if max_transit_days < 0 or page < 1 or page_size < 1:
        raise ValueError('invalid pagination or transit limit')
    best: dict[str, tuple[float, int, int, dict[str, Any]]] = {}
    for index, record in enumerate(records):
        if record['capacity'] <= 0 or record['transit_days'] > max_transit_days:
            continue
        total = round(record['rate'] * (1 + record['fuel_surcharge_pct'] / 100), 2)
        candidate = (total, record['transit_days'], index, record)
        if record['carrier'] not in best or candidate[:3] < best[record['carrier']][:3]:
            best[record['carrier']] = candidate
    selected = sorted(best.values(), key=lambda x: (x[0], x[1], x[3]['carrier']))
    start = (page - 1) * page_size
    return [{'carrier': r['carrier'], 'origin': r['origin'], 'destination': r['destination'], 'total_price': total, 'transit_days': r['transit_days']} for total, _, _, r in selected[start:start + page_size]]

