import csv
import os
import tempfile

def write_wafer_report(records: list[dict], destination: str, min_yield: float=0.0) -> dict:
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    if isinstance(min_yield, bool) or not isinstance(min_yield, (int, float)):
        raise TypeError('min_yield must be numeric')
    if not 0 <= min_yield <= 100:
        raise ValueError('invalid min_yield')
    grouped = {}
    for record in records:
        if not isinstance(record, dict):
            raise TypeError('record must be a dictionary')
        if not all((key in record for key in ('lot', 'wafer', 'passed', 'total'))):
            raise ValueError('missing field')
        lot = record['lot']
        wafer = record['wafer']
        passed = record['passed']
        total = record['total']
        if not isinstance(lot, str) or not isinstance(wafer, int) or isinstance(wafer, bool) or (not isinstance(passed, int)) or isinstance(passed, bool) or (not isinstance(total, int)) or isinstance(total, bool):
            raise TypeError('invalid field type')
        if not lot or wafer <= 0 or total <= 0 or (passed < 0) or (passed > total):
            raise ValueError('invalid record')
        if lot not in grouped:
            grouped[lot] = [0, 0]
        grouped[lot][0] += total
        grouped[lot][1] += passed
    selected = []
    for lot, (total, passed) in grouped.items():
        rate = 100 * passed / total
        if rate >= min_yield:
            selected.append((rate, lot, total, passed))
    selected.sort(key=lambda item: (-item[0], item[1]))
    directory = os.path.dirname(os.path.abspath(destination))
    descriptor, temporary = tempfile.mkstemp(prefix='.wafer-', suffix='.csv', dir=directory, text=True)
    os.close(descriptor)
    try:
        with open(temporary, 'w', encoding='utf-8', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['lot', 'total', 'passed', 'yield_percent'])
            for rate, lot, total, passed in selected:
                writer.writerow([lot, total, passed, round(rate, 2)])
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    total_wafers = sum((item[2] for item in selected))
    total_passed = sum((item[3] for item in selected))
    return {'lots': len(selected), 'wafers': total_wafers, 'passed': total_passed, 'yield_percent': round(100 * total_passed / total_wafers, 2) if total_wafers else 0.0}

