import calendar
import hashlib
import hmac
import json
import re

def _bad():
    raise ValueError('invalid document')

def summarize_grants(document: dict) -> dict:
    if not isinstance(document, dict) or set(document) != {'period', 'grants'}:
        _bad()
    period = document['period']
    if not isinstance(period, str) or not re.fullmatch('\\d{4}-\\d{2}', period):
        _bad()
    year, month = map(int, period.split('-'))
    if month < 1 or month > 12:
        _bad()
    grants = document['grants']
    if not isinstance(grants, list):
        _bad()
    seen = set()
    approved = []
    for grant in grants:
        required = {'id', 'region', 'applicant', 'amount', 'status', 'submitted', 'tags'}
        if not isinstance(grant, dict) or set(grant) != required:
            _bad()
        gid, region, applicant = (grant['id'], grant['region'], grant['applicant'])
        if not isinstance(gid, str) or not gid or gid in seen:
            _bad()
        seen.add(gid)
        if not isinstance(region, str) or not re.fullmatch('[A-Z]{2}', region):
            _bad()
        if not isinstance(applicant, str) or not applicant:
            _bad()
        amount = grant['amount']
        if isinstance(amount, bool) or not isinstance(amount, int) or amount < 0:
            _bad()
        status = grant['status']
        if status not in ('approved', 'rejected'):
            _bad()
        submitted = grant['submitted']
        if not isinstance(submitted, str) or not re.fullmatch('\\d{4}-\\d{2}-\\d{2}', submitted):
            _bad()
        sy, sm, sd = map(int, submitted.split('-'))
        if sm < 1 or sm > 12 or sd < 1 or (sd > calendar.monthrange(sy, sm)[1]) or ((sy, sm) != (year, month)):
            _bad()
        tags = grant['tags']
        if not isinstance(tags, list) or any((not isinstance(x, str) for x in tags)) or len(set(tags)) != len(tags):
            _bad()
        if status == 'approved':
            approved.append((gid, region, applicant, amount, tags))
    totals = {}
    for _, region, _, amount, _ in approved:
        entry = totals.setdefault(region, {'count': 0, 'total': 0})
        entry['count'] += 1
        entry['total'] += amount
    approved.sort(key=lambda x: (-x[3], x[0]))
    awards = [{'id': x[0], 'applicant': x[2], 'region': x[1], 'amount': x[3], 'tags': x[4]} for x in approved]
    return {'period': period, 'approved_total': sum((x[3] for x in approved)), 'by_region': dict(sorted(totals.items())), 'awards': awards}

def verify_submission(payload: bytes, signature: str, key: bytes) -> dict:
    if not isinstance(payload, bytes) or not isinstance(signature, str) or (not isinstance(key, bytes)):
        raise ValueError('invalid signature')
    if not re.fullmatch('sha256=[0-9a-f]{64}', signature):
        raise ValueError('invalid signature')
    expected = hmac.new(key, payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(signature[7:], expected):
        raise ValueError('invalid signature')
    try:
        document = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('invalid document')
    return summarize_grants(document)

