from lxml import etree
from datetime import date
import math

def _root(text):
    try:
        parser = etree.XMLParser(resolve_entities=False, load_dtd=False, no_network=True)
        return etree.fromstring(text.encode(), parser)
    except Exception as exc:
        raise ValueError from exc

def _clean(value):
    return value.strip() if value is not None else ''

def parse_claims(xml_text: str) -> list[dict]:
    root = _root(xml_text)
    if root.tag != 'claims':
        raise ValueError
    result, seen = ([], set())
    for node in root:
        if node.tag != 'claim' or (node.tail and node.tail.strip()):
            raise ValueError
        attrs = {k: _clean(node.get(k)) for k in ('id', 'policy', 'country', 'status')}
        if any((not v for v in attrs.values())) or attrs['status'] not in {'submitted', 'approved', 'denied'} or attrs['id'] in seen:
            raise ValueError
        seen.add(attrs['id'])
        children = list(node)
        travelers = [x for x in children if x.tag == 'traveler']
        groups = [x for x in children if x.tag == 'expenses']
        if len(travelers) != 1 or len(groups) != 1 or len(children) != 2:
            raise ValueError
        traveler = travelers[0]
        if list(traveler) or not _clean(traveler.text):
            raise ValueError
        expenses = []
        for e in groups[0]:
            if e.tag != 'expense' or list(e) or (not _clean(e.text)):
                raise ValueError
            d, cur, raw = (_clean(e.get('date')), _clean(e.get('currency')), _clean(e.text))
            try:
                if date.fromisoformat(d).isoformat() != d or not cur:
                    raise ValueError
                amount = float(raw)
                if not math.isfinite(amount) or amount < 0:
                    raise ValueError
            except Exception as exc:
                raise ValueError from exc
            expenses.append({'date': d, 'currency': cur, 'amount': amount})
        if not expenses:
            raise ValueError
        result.append({**attrs, 'traveler': _clean(traveler.text), 'expenses': expenses})
    return result

def claim_report(xml_text: str, exchange_rates: dict[str, float]) -> list[dict]:
    rows = {}
    for claim in parse_claims(xml_text):
        row = rows.setdefault(claim['country'], {'country': claim['country'], 'claim_count': 0, 'approved_amount': 0.0, 'total_amount': 0.0, 'latest_expense_date': None})
        row['claim_count'] += 1
        for expense in claim['expenses']:
            rate = exchange_rates.get(expense['currency'])
            if rate is None or not math.isfinite(rate) or rate <= 0:
                raise ValueError
            value = expense['amount'] * rate
            row['total_amount'] += value
            if claim['status'] == 'approved':
                row['approved_amount'] += value
            if row['latest_expense_date'] is None or expense['date'] > row['latest_expense_date']:
                row['latest_expense_date'] = expense['date']
    answer = list(rows.values())
    for row in answer:
