from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
import xml.etree.ElementTree as ET

def summarize_claims(xml_text: str, status: str | None=None, page: int=1, page_size: int=10) -> dict:
    if status == '' or page < 1 or page_size < 1:
        raise ValueError('invalid options')
    try:
        root = ET.fromstring(xml_text)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    claims = []
    for node in root.findall('claim'):
        try:
            ident = node.attrib['id']
            provider = node.attrib['provider']
            item_status = node.attrib['status']
            item_date = node.attrib['date']
            amount = Decimal(node.attrib['amount'])
            if not ident or not provider or (not item_status):
                raise ValueError
            date.fromisoformat(item_date)
            if amount < 0 or not amount.is_finite():
                raise ValueError
        except (KeyError, ValueError, InvalidOperation) as exc:
            raise ValueError('invalid claim') from exc
        if status is None or item_status == status:
            claims.append({'id': ident, 'provider': provider, 'status': item_status, 'date': item_date, 'value': amount})
    claims.sort(key=lambda x: (-date.fromisoformat(x['date']).toordinal(), x['id']))
    quant = Decimal('0.01')
    total = sum((x['value'] for x in claims), Decimal('0')).quantize(quant, rounding=ROUND_HALF_UP)
    grouped = {}
    for item in claims:
        entry = grouped.setdefault(item['provider'], [0, Decimal('0')])
        entry[0] += 1
        entry[1] += item['value']
    providers = sorted(grouped.items(), key=lambda x: (-x[1][1], x[0]))
    start = (page - 1) * page_size
    visible = claims[start:start + page_size]
    output = []
    for x in visible:
        output.append({'id': x['id'], 'provider': x['provider'], 'status': x['status'], 'date': x['date'], 'amount': format(x['value'].quantize(quant, rounding=ROUND_HALF_UP), 'f')})
    return {'claims': output, 'total': len(claims), 'total_amount': format(total, 'f'), 'providers': [{'provider': n, 'count': v[0], 'amount': format(v[1].quantize(quant, rounding=ROUND_HALF_UP), 'f')} for n, v in providers]}

