from solution import verify_shift_report
import hashlib
import hmac
import json
import pytest


def make_report(data, secret=b"line-secret"):
    payload = json.dumps(data, separators=(",", ":")).encode("utf-8")
    digest = hmac.new(secret, payload, hashlib.sha256).hexdigest()
    return payload, "sha256=" + digest


def test_valid_report_is_returned_exactly():
    report = {"worker_id": "W-104", "zone": "press-2", "compliant": True, "hours": 8}
    payload, header = make_report(report)
    assert verify_shift_report(payload, header, b"line-secret") == report


def test_false_compliance_and_boundary_hours_are_accepted():
    report = {"worker_id": "W-7", "zone": "loading", "compliant": False, "hours": 0}
    payload, header = make_report(report, b"abc")
    assert verify_shift_report(payload, header, b"abc") == report
    report2 = {"worker_id": "W-7", "zone": "loading", "compliant": True, "hours": 24}
    payload2, header2 = make_report(report2, b"abc")
    assert verify_shift_report(payload2, header2, b"abc") == report2


def test_wrong_secret_is_rejected():
    report = {"worker_id": "W-1", "zone": "welding", "compliant": True, "hours": 8}
    payload, header = make_report(report, b"correct")
    with pytest.raises(ValueError):
        verify_shift_report(payload, header, b"incorrect")


def test_changed_payload_is_rejected():
    report = {"worker_id": "W-1", "zone": "welding", "compliant": True, "hours": 8}
    payload, header = make_report(report)
    changed = payload.replace(b"welding", b"assembly")
    with pytest.raises(ValueError):
        verify_shift_report(changed, header, b"line-secret")


def test_malformed_headers_are_rejected():
    report = {"worker_id": "W-1", "zone": "yard", "compliant": True, "hours": 5}
    payload, header = make_report(report)
    for bad in ["", "sha256", "sha1=" + header[7:], header.upper(), "sha256=" + "0" * 63, "sha256=" + header[7:-1] + "G"]:
        with pytest.raises(ValueError):
            verify_shift_report(payload, bad, b"line-secret")


def test_invalid_report_shapes_are_rejected():
    cases = [
        {"worker_id": "", "zone": "x", "compliant": True, "hours": 1},
        {"worker_id": "w", "zone": "x", "compliant": 1, "hours": 1},
        {"worker_id": "w", "zone": "x", "compliant": True, "hours": 25},
        {"worker_id": "w", "zone": "x", "compliant": True},
        {"worker_id": "w", "zone": "x", "compliant": True, "hours": 1, "extra": 2},
        ["w", "x", True, 1],
    ]
    for value in cases:
        payload = json.dumps(value, separators=(",", ":")).encode()
        header = "sha256=" + hmac.new(b"s", payload, hashlib.sha256).hexdigest()
        with pytest.raises(ValueError):
            verify_shift_report(payload, header, b"s")


def test_invalid_encoding_and_json_are_rejected():
    for payload in [b"\xff", b"not-json", b"null"]:
        digest = hmac.new(b"s", payload, hashlib.sha256).hexdigest()
        with pytest.raises(ValueError):
            verify_shift_report(payload, "sha256=" + digest, b"s")

