import hashlib
import hmac
import json

def verify_shift_report(payload: bytes, digest_header: str, secret: bytes) -> dict:
    try:
        report = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('invalid report')
    if not isinstance(report, dict) or set(report) != {'worker_id', 'zone', 'compliant', 'hours'}:
        raise ValueError('invalid report')
    if not isinstance(report['worker_id'], str) or not report['worker_id']:
        raise ValueError('invalid report')
    if not isinstance(report['zone'], str) or not isinstance(report['compliant'], bool):
        raise ValueError('invalid report')
    if not isinstance(report['hours'], int) or isinstance(report['hours'], bool) or (not 0 <= report['hours'] <= 24):
        raise ValueError('invalid report')
    if not isinstance(digest_header, str) or not digest_header.startswith('sha256='):
        raise ValueError('invalid digest')
    supplied = digest_header[7:]
    if len(supplied) != 64 or any((c not in '0123456789abcdef' for c in supplied)):
        raise ValueError('invalid digest')
    expected = hmac.new(secret, payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, supplied):
        raise ValueError('invalid digest')
    return report

