_TIERS = {'free', 'supporter', 'studio'}
_MONTH = re.compile('^\\d{4}-(0[1-9]|1[0-2])$')

def _clean(value):
    return ' '.join(value.split())

def _valid_date(value):
    try:
        date.fromisoformat(value)
    except Exception:
        raise ValueError('invalid date')
    return value

def _valid_month(value):
    if not _MONTH.fullmatch(value):
        raise ValueError('invalid month')
    return value

def _amount(value):
    if not re.fullmatch('\\d+(?:\\.\\d{1,2})?', value):
        raise ValueError('invalid amount')
    whole, _, frac = value.partition('.')
    return int(whole) * 100 + int((frac + '00')[:2])

def parse_memberships(xml_text: str) -> list[dict]:
    try:
        root = ET.fromstring(xml_text)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'feed':
        raise ValueError('invalid root')
