        if len(payments_nodes) > 1 or len(benefits_nodes) > 1:
            raise ValueError('duplicate container')
        payments = []
        used = set()
        if payments_nodes:
            for p in payments_nodes[0]:
                if p.tag != 'payment':
                    raise ValueError('invalid payment')
                month = p.get('month')
                if not month or month in used:
                    raise ValueError('invalid payment')
                _valid_month(month)
                cents = _amount(p.get('amount', ''))
                used.add(month)
                payments.append({'month': month, 'cents': cents})
        benefits = []
        if benefits_nodes:
            for b in benefits_nodes[0]:
                if b.tag != 'benefit':
                    raise ValueError('invalid benefit')
                text = _clean(b.text or '')
                if not text:
                    raise ValueError('invalid benefit')
                benefits.append(text)
        payments.sort(key=lambda x: x['month'])
        result.append({'id': ident, 'name': _clean(names[0].text or ''), 'joined': joined, 'tier': tier, 'payments': payments, 'benefits': benefits})
