                active.append((record, payment['cents']))
    counts = {tier: 0 for tier in ('free', 'supporter', 'studio')}
    for record, _ in active:
        counts[record['tier']] += 1
    return {'month': month, 'total_cents': sum((x[1] for x in active)), 'active_ids': sorted((x[0]['id'] for x in active)), 'by_tier': counts}

