    if isinstance(minimum_cents, bool) or not isinstance(minimum_cents, int) or minimum_cents < 0:
        raise ValueError('invalid minimum')
    rows = []
    for record in records:
        total = sum((payment['cents'] for payment in record['payments']))
        if total >= minimum_cents:
            rows.append((record['id'], total, record['joined']))
    rows.sort(key=lambda x: (-x[1], x[2], x[0]))
    return [x[0] for x in rows]

