    try:
        ident, customer, start, end, rate, accessories = (c[k] for k in ('id', 'customer', 'start', 'end', 'daily_rate_cents', 'accessories'))
    except Exception as exc:
        raise ValueError('invalid contract') from exc
    if not isinstance(ident, str) or not isinstance(customer, str) or (not isinstance(rate, int)) or isinstance(rate, bool) or (rate < 0) or (not isinstance(accessories, list)):
        raise ValueError('invalid contract')
    a, b = (_date(start), _date(end))
    if a > b:
        raise ValueError('invalid range')
    for item in accessories:
        if not isinstance(item, dict) or not isinstance(item.get('name'), str) or (not isinstance(item.get('daily_rate_cents'), int)) or isinstance(item['daily_rate_cents'], bool) or (item['daily_rate_cents'] < 0):
            raise ValueError('invalid accessory')
    return (ident, customer, a, b, rate, accessories)

def summarize_contract(contract: dict, period_start: str, period_end: str) -> dict:
    ident, customer, start, end, rate, accessories = _check(contract)
    ps, pe = (_date(period_start), _date(period_end))
    if ps > pe:
        raise ValueError('invalid period')
    left, right = (max(start, ps), min(end, pe))
    days = max(0, (right - left).days + 1)
    rental = rate * days
    accessory = sum((x['daily_rate_cents'] for x in accessories)) * days
    base = rental + accessory
    discount = (base * 10 + 50) // 100 if days >= 30 else 0
    tax = ((base - discount) * 825 + 5000) // 10000
    return {'id': ident, 'customer': customer, 'days': days, 'rental_cents': rental, 'accessory_cents': accessory, 'discount_cents': discount, 'tax_cents': tax, 'total_cents': base - discount + tax}

