    rows = [summarize_contract(c, period_start, period_end) for c in contracts]
    rows.sort(key=lambda r: (r['customer'].casefold(), r['id']))
    columns = ['id', 'customer', 'days', 'rental_cents', 'accessory_cents', 'discount_cents', 'tax_cents', 'total_cents']
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as f:
            writer = csv.writer(f, lineterminator='\n')
            writer.writerow(columns)
            for row in rows:
                writer.writerow([row[k] for k in columns])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return {'count': len(rows), 'total_cents': sum((r['total_cents'] for r in rows))}

