    allowed = {'priority', 'submitted_at', 'applicant', 'annual_income', 'id'}
    if sort_by not in allowed:
        raise ValueError('invalid sort field')
    clauses = []
    values = []
    if status is not None:
        clauses.append('status = ?')
        values.append(status)
    if county is not None:
        clauses.append('county = ?')
        values.append(county)
    if search is not None:
        clauses.append('(lower(case_number) LIKE lower(?) OR lower(applicant) LIKE lower(?))')
        pattern = '%' + search + '%'
        values.extend([pattern, pattern])
    sql = 'SELECT id, case_number, applicant, county, status, annual_income, dependents, submitted_at FROM applications'
    if clauses:
        sql += ' WHERE ' + ' AND '.join(clauses)
    rows = conn.execute(sql, values).fetchall()
    result = []
    for row in rows:
        item = dict(row)
        item['priority'] = max(0, 100 - item['annual_income'] // 1000 + item['dependents'] * 5)
        result.append(item)
    if sort_by == 'priority':
        key = lambda x: x['priority']
    else:
        key = lambda x: x[sort_by]
    result.sort(key=lambda x: x['id'])
    result.sort(key=key, reverse=descending)
    return result

