    if minimum_dependents < 0:
        raise ValueError('minimum_dependents must not be negative')
    rows = conn.execute('SELECT county, annual_income FROM applications WHERE status = ? AND dependents >= ?', ('approved', minimum_dependents)).fetchall()
    groups = {}
    for row in rows:
        income = row[1]
        award = 12000 if income < 20000 else 8000 if income < 40000 else 4000 if income < 60000 else 0
