import csv
import io
import os
import zipfile
from datetime import date
from decimal import Decimal, ROUND_HALF_UP
import math

def extract_billing_bundle(archive_path: str, destination: str) -> list[str]:
    os.makedirs(destination, exist_ok=True)
    base = os.path.realpath(destination)
    result = []
    with zipfile.ZipFile(archive_path) as archive:
        for info in archive.infolist():
            name = info.filename
            if not name or name.endswith('/'):
                continue
            target = os.path.realpath(os.path.join(destination, name))
            if os.path.commonpath([base, target]) != base:
                raise ValueError('archive member is outside destination')
            os.makedirs(os.path.dirname(target), exist_ok=True)
            with archive.open(info) as source, open(target, 'wb') as output:
                output.write(source.read())
            result.append(os.path.relpath(target, destination))
    return sorted(result)

def parse_meter_readings(csv_text: str) -> dict[str, list[tuple[str, int]]]:
    rows = list(csv.reader(io.StringIO(csv_text)))
    if not rows or rows[0] != ['account', 'date', 'reading'] or len(rows) == 1:
        raise ValueError('invalid CSV')
    answer = {}
    seen = set()
    for row in rows[1:]:
        if len(row) != 3:
            raise ValueError('invalid row')
        account, day, value = (x.strip() for x in row)
        if not account or (account, day) in seen:
            raise ValueError('invalid account or duplicate')
        try:
            date.fromisoformat(day)
            number = int(value)
        except Exception as exc:
            raise ValueError('invalid reading') from exc
        if len(day) != 10 or number < 0:
            raise ValueError('invalid reading')
        seen.add((account, day))
        answer.setdefault(account, []).append((day, number))
    for account in answer:
        answer[account].sort(key=lambda item: item[0])
    return answer

def calculate_bills(readings: dict[str, list[tuple[str, int]]], fixed_charge: float=12.5) -> dict[str, float]:
    if not math.isfinite(fixed_charge) or fixed_charge < 0:
        raise ValueError('invalid fixed charge')
    output = {}
    for account in sorted(readings):
        entries = readings[account]
        if len(entries) < 2 or any((entries[i][0] >= entries[i + 1][0] or entries[i][1] > entries[i + 1][1] for i in range(len(entries) - 1))):
            raise ValueError('invalid readings')
        units = entries[-1][1] - entries[0][1]
        charge = min(units, 10) * Decimal('0.80')
        charge += min(max(units - 10, 0), 20) * Decimal('1.20')
        charge += max(units - 30, 0) * Decimal('2.00')
        total = charge + Decimal(str(fixed_charge))
        output[account] = float(total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
    return output

