import csv
import os
import tempfile
from datetime import date, timedelta

def export_lifecycle_report(records: list[dict[str, object]], as_of: str, destination: str, page: int=1, page_size: int=50) -> dict[str, object]:
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('invalid page size')
    try:
        cutoff = date.fromisoformat(as_of)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        required = ('bucket', 'key', 'size', 'last_modified', 'storage_class', 'expiration_days')
        if any((k not in record for k in required)):
            raise ValueError('missing field')
        bucket = record['bucket']
        key = record['key']
        storage_class = record['storage_class']
        size = record['size']
        expiration_days = record['expiration_days']
        if not isinstance(bucket, str) or not bucket or (not isinstance(key, str)) or (not key) or (not isinstance(storage_class, str)) or (not storage_class):
            raise ValueError('invalid text')
        if isinstance(size, bool) or not isinstance(size, int) or size < 0:
            raise ValueError('invalid size')
        if isinstance(expiration_days, bool) or not isinstance(expiration_days, int) or expiration_days < 0:
            raise ValueError('invalid expiration')
        try:
            modified = date.fromisoformat(record['last_modified'])
        except (TypeError, ValueError):
            raise ValueError('invalid date')
        group = groups.setdefault((bucket, storage_class), {'bucket': bucket, 'storage_class': storage_class, 'object_count': 0, 'total_bytes': 0, 'expired_count': 0})
        group['object_count'] += 1
        group['total_bytes'] += size
        if modified + timedelta(days=expiration_days) <= cutoff:
            group['expired_count'] += 1
    ordered = [groups[k] for k in sorted(groups)]
    headers = ['bucket', 'storage_class', 'object_count', 'total_bytes', 'expired_count']
    fd, temporary = tempfile.mkstemp(prefix='lifecycle-', suffix='.csv', dir=os.path.dirname(os.path.abspath(destination)) or None, text=True)
    try:
        with os.fdopen(fd, 'w', newline='') as handle:
            writer = csv.writer(handle)
            writer.writerow(headers)
            for group in ordered:
                writer.writerow([group[h] for h in headers])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    total = len(ordered)
    pages = (total + page_size - 1) // page_size if total else 0
    start = (page - 1) * page_size
    return {'total_groups': total, 'page': page, 'page_size': page_size, 'pages': pages, 'groups': ordered[start:start + page_size]}

