def extract_readings(xml_text: str, patient_id: str | None=None, min_oxygen: float=0.0, offset: int=0, limit: int | None=None) -> list[dict]:
    if not math.isfinite(min_oxygen) or offset < 0 or (limit is not None and limit < 0):
        raise ValueError('invalid pagination or threshold')
