        raise ValueError('invalid root')
    rows = []
    required = ('patient', 'timestamp', 'heart_rate', 'steps', 'oxygen')
    for node in root.findall('reading'):
        if any((name not in node.attrib for name in required)):
            raise ValueError('missing attribute')
        try:
            patient = node.attrib['patient']
            timestamp = node.attrib['timestamp']
            heart_rate = int(node.attrib['heart_rate'])
            steps = int(node.attrib['steps'])
            oxygen = float(node.attrib['oxygen'])
        except (TypeError, ValueError) as exc:
            raise ValueError('invalid reading') from exc
        if not math.isfinite(oxygen) or not 0 <= heart_rate <= 300 or steps < 0 or (not 0 <= oxygen <= 100):
            raise ValueError('reading out of range')
