def parse_policy(text: str) -> dict[str, int]:
    if not isinstance(text, str):
        raise ValueError('invalid policy')
    result = {}
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith('#'):
            continue
        left = []
        right = []
        escaped = False
        found = False
        for ch in line:
            if escaped:
                (right if found else left).append(ch)
                escaped = False
            elif ch == '\\':
                escaped = True
            elif not found and ch == '=':
                found = True
            elif not found and ch == '#':
                break
            else:
                (right if found else left).append(ch)
        if escaped or not found:
            raise ValueError('invalid policy entry')
        category = ''.join(left).strip()
        value = ''.join(right).split('#', 1)[0].strip()
        if not category or not value.isdecimal() or category in result:
            raise ValueError('invalid policy entry')
        result[category] = int(value)
    return result

def make_continuation_token(length: int=24) -> str:
    if isinstance(length, bool) or not isinstance(length, int) or length <= 0:
        raise ValueError('invalid length')
    alphabet = string.ascii_letters + string.digits
    return ''.join((secrets.choice(alphabet) for _ in range(length)))

def retention_report(records: list[dict], policy: dict[str, int] | str, as_of: str, limit: int | None=None) -> dict:
    if isinstance(policy, str):
        policy = parse_policy(policy)
