        seen.add(record['id'])
        try:
            created = date.fromisoformat(record['created'])
        except Exception as exc:
            raise ValueError('invalid date') from exc
        days = policy.get(record['category'], policy['default'])
        until = created + timedelta(days=days)
        items.append({'id': record['id'], 'category': record['category'], 'retain_until': until.isoformat(), 'action': 'delete' if until < cutoff else 'retain'})
