def analyze_maintenance_logs(paths: list[str], page: int=1, page_size: int=10) -> dict[str, Any]:
    if not isinstance(paths, list):
        raise TypeError('paths must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('page must be a positive integer')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('page_size must be between 1 and 100')
    counts = []
    for path in paths:
        result = subprocess.run(['wc', '-l', path], capture_output=True, text=True, check=True)
        counts.append((path, int(result.stdout.split()[0])))
    ordered = sorted(counts, key=lambda item: (-item[1], item[0]))
    start = (page - 1) * page_size
    selected = ordered[start:start + page_size]
    total = sum((count for _, count in counts))
    average = round(total / len(counts), 2) if counts else 0.0
    return {'total_files': len(paths), 'total_entries': total, 'average_entries': average, 'items': [{'path': path, 'entries': count} for path, count in selected]}

