import secrets

def create_wafer_transfer(wafer_ids: list[str], destination: str, expires_minutes: int) -> dict:
    if not isinstance(wafer_ids, list):
        raise TypeError('wafer_ids must be a list')
    if not isinstance(destination, str):
        raise TypeError('destination must be a string')
    if not isinstance(expires_minutes, int) or isinstance(expires_minutes, bool):
        raise TypeError('expires_minutes must be an integer')
    if not wafer_ids:
        raise ValueError('wafer_ids cannot be empty')
    if expires_minutes < 5 or expires_minutes > 10080:
        raise ValueError('expires_minutes is out of range')
    destination = destination.strip()
    if not destination:
        raise ValueError('destination cannot be blank')
    if any((not isinstance(value, str) for value in wafer_ids)):
        raise TypeError('wafer identifiers must be strings')
    if any((re.fullmatch('W\\d{6}', value) is None for value in wafer_ids)):
        raise ValueError('invalid wafer identifier')
    if len(set(wafer_ids)) != len(wafer_ids):
        raise ValueError('duplicate wafer identifier')
    wafers = sorted(wafer_ids)
    by_lot = {}
    for wafer in wafers:
        by_lot.setdefault(wafer[:4], []).append(wafer)
    alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
    code = ''.join((secrets.choice(alphabet) for _ in range(12)))
    return {'code': code, 'destination': destination, 'expires_minutes': expires_minutes, 'wafer_count': len(wafers), 'wafers': wafers, 'by_lot': dict(sorted(by_lot.items()))}

