from solution import summarize_lunch_payments, format_student_statement
import tempfile
import os
import pytest

def write_records(text):
    f = tempfile.NamedTemporaryFile(mode='w', encoding='utf-8', delete=False)
    f.write(text)
    f.close()
    return f.name

def test_empty_and_void_records():
    path = write_records('\n2025-09-02,s9,lunch,500,VOID,v1\n')
    try:
        assert summarize_lunch_payments(path, '2025-09-02') == {'day': '2025-09-02', 'paid_cents': 0, 'refund_cents': 0, 'total_cents': 0, 'students': []}
    finally:
        os.unlink(path)

def test_aggregation_filters_day_and_orders_students():
    path = write_records('2025-09-02,b2,lunch,700,PAID,t3\n2025-09-01,a1,breakfast,100,PAID,t1\n2025-09-02,a1,breakfast,300,PAID,t2\n2025-09-02,b2,snack,150,REFUND,t4\n2025-09-02,a1,lunch,50,PAID,t5\n')
    try:
        result = summarize_lunch_payments(path, '2025-09-02')
        assert result == {'day': '2025-09-02', 'paid_cents': 1050, 'refund_cents': 150, 'total_cents': 900, 'students': [{'student_id': 'a1', 'balance_cents': 350, 'meals': {'breakfast': 1, 'lunch': 1, 'snack': 0}}, {'student_id': 'b2', 'balance_cents': 550, 'meals': {'breakfast': 0, 'lunch': 1, 'snack': 0}}]}
    finally:
        os.unlink(path)

def test_statement_formats_positive_balance():
    summary = {'students': [{'student_id': 'a', 'balance_cents': 305, 'meals': {'breakfast': 2, 'lunch': 1, 'snack': 0}}]}
    assert format_student_statement(summary, 'a') == 'Student: a\nBalance: $3.05\nBreakfast: 2\nLunch: 1\nSnack: 0'

def test_statement_formats_negative_balance():
    summary = {'students': [{'student_id': 'z', 'balance_cents': -125, 'meals': {'breakfast': 0, 'lunch': 3, 'snack': 1}}]}
    assert format_student_statement(summary, 'z') == 'Student: z\nBalance: -$1.25\nBreakfast: 0\nLunch: 3\nSnack: 1'

def test_duplicate_transaction_is_rejected_across_days():
    path = write_records('2025-09-01,a,lunch,10,PAID,same\n2025-09-02,b,lunch,20,PAID,same\n')
    try:
        with pytest.raises(ValueError):
            summarize_lunch_payments(path, '2025-09-02')
    finally:
        os.unlink(path)

def test_invalid_rows_and_dates_are_rejected():
    path = write_records('2025-02-30,a,lunch,10,PAID,x\n')
    try:
        with pytest.raises(ValueError):
            summarize_lunch_payments(path, '2025-09-02')
    finally:
        os.unlink(path)
    path = write_records('2025-09-02,a,lunch,nope,PAID,x\n')
    try:
        with pytest.raises(ValueError):
            summarize_lunch_payments(path, '2025-09-02')
    finally:
        os.unlink(path)

