import csv
import datetime
import os
import subprocess

def summarize_lunch_payments(path: str, school_day: str) -> dict:
    try:
        datetime.date.fromisoformat(school_day)
    except ValueError:
        raise ValueError('invalid day')
    if not os.path.isfile(path):
        raise FileNotFoundError(path)
    result = subprocess.run(['sort', '-t,', '-k1,1', '-k2,2', '-k6,6', path], capture_output=True, text=True, check=True)
    seen = set()
    students = {}
    paid = refund = 0
    for number, line in enumerate(result.stdout.splitlines(), 1):
        if not line:
            continue
        fields = next(csv.reader([line]))
        if len(fields) != 6:
            raise ValueError('malformed row')
        day, sid, meal, amount_text, status, transaction = fields
        try:
            datetime.date.fromisoformat(day)
            amount = int(amount_text)
        except (ValueError, TypeError):
            raise ValueError('invalid row')
        if not sid or not transaction or amount < 0 or (meal not in {'breakfast', 'lunch', 'snack'}) or (status not in {'PAID', 'REFUND', 'VOID'}):
            raise ValueError('invalid row')
        if transaction in seen:
            raise ValueError('duplicate transaction')
        seen.add(transaction)
        if day != school_day or status == 'VOID':
            continue
        if sid not in students:
            students[sid] = {'student_id': sid, 'balance_cents': 0, 'meals': {'breakfast': 0, 'lunch': 0, 'snack': 0}}
        item = students[sid]
        if status == 'PAID':
            paid += amount
            item['balance_cents'] += amount
            item['meals'][meal] += 1
        else:
            refund += amount
            item['balance_cents'] -= amount
    return {'day': school_day, 'paid_cents': paid, 'refund_cents': refund, 'total_cents': paid - refund, 'students': [students[k] for k in sorted(students)]}

def format_student_statement(summary: dict, student_id: str) -> str:
    item = next((x for x in summary['students'] if x['student_id'] == student_id))
    cents = item['balance_cents']
    sign = '-$' if cents < 0 else '$'
    cents = abs(cents)
    return f"Student: {student_id}\nBalance: {sign}{cents // 100}.{cents % 100:02d}\nBreakfast: {item['meals']['breakfast']}\nLunch: {item['meals']['lunch']}\nSnack: {item['meals']['snack']}"

