import csv
import datetime
import os
import tempfile

def _checked(event):
    try:
        worker = event['worker']
        station = event['station']
        timestamp = datetime.datetime.fromisoformat(event['timestamp'])
        exposure = event['exposure']
        incident = event['incident']
    except (KeyError, TypeError, ValueError):
        raise ValueError('invalid event')
    if not isinstance(worker, str) or not worker or (not isinstance(station, str)) or (not station):
        raise ValueError('invalid event')
    if isinstance(exposure, bool) or not isinstance(exposure, (int, float)):
        raise ValueError('invalid event')
    if not isinstance(incident, bool):
        raise ValueError('invalid event')
    return (worker, timestamp, float(exposure), incident)

def build_compliance_report(events: list[dict[str, object]]) -> list[dict[str, object]]:
    groups = {}
    for event in events:
        worker, timestamp, exposure, incident = _checked(event)
        key = (worker, timestamp.date())
        groups.setdefault(key, []).append((timestamp, exposure, incident))
    result = []
    for (worker, date), readings in sorted(groups.items(), key=lambda item: item[0]):
        readings.sort(key=lambda item: item[0])
        high_pair = any((readings[i - 1][1] > 5 and readings[i][1] > 5 for i in range(1, len(readings))))
        incidents = sum((1 for _, _, incident in readings if incident))
        peak = max((item[1] for item in readings))
        status = 'REVIEW' if incidents or peak > 8 or high_pair else 'PASS'
        result.append({'worker': worker, 'date': date.isoformat(), 'readings': len(readings), 'peak_exposure': round(peak, 2), 'incidents': incidents, 'status': status})
    return result

def export_compliance_csv(events: list[dict[str, object]], destination: str) -> int:
    report = build_compliance_report(events)
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent)
    os.close(fd)
    try:
        with open(temporary, 'w', encoding='utf-8', newline='') as output:
            writer = csv.writer(output, lineterminator='\n')
            writer.writerow(['worker', 'date', 'readings', 'peak_exposure', 'incidents', 'status'])
            for row in report:
                writer.writerow([row['worker'], row['date'], row['readings'], f"{row['peak_exposure']:.2f}", row['incidents'], row['status']])
        os.replace(temporary, destination)
        return len(report)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise

