            score_num = int(score)
        except ValueError as exc:
            raise ValueError('invalid number') from exc
        if line_num <= 0 or not 0 <= score_num <= 100:
            raise ValueError('number out of range')
        if status not in ('PASS', 'FAIL'):
            raise ValueError('invalid status')
        if status == 'PASS' and defect:
            raise ValueError('pass defect')
        if status == 'FAIL' and (not defect):
            raise ValueError('missing defect')
        result.append({'item': item, 'line': line_num, 'inspector': inspector, 'status': status, 'score': score_num, 'defect': defect})
    return result

def _checked(records):
    checked = []
    for r in records:
        if set(r) != set(_FIELDS):
            raise ValueError('invalid record')
        item, inspector, status, defect = (r['item'], r['inspector'], r['status'], r['defect'])
        try:
            line, score = (int(r['line']), int(r['score']))
        except (TypeError, ValueError) as exc:
            raise ValueError('invalid number') from exc
        if not isinstance(item, str) or not isinstance(inspector, str) or (not isinstance(defect, str)):
            raise ValueError('invalid text')
        if line <= 0 or not 0 <= score <= 100 or status not in ('PASS', 'FAIL'):
            raise ValueError('invalid record')
        if (status == 'PASS') != (defect == ''):
            raise ValueError('invalid defect')
        checked.append({'item': item, 'line': line, 'inspector': inspector, 'status': status, 'score': score, 'defect': defect})
    return checked

def export_report(records: list[dict], destination: str) -> str:
    records = _checked(records)
    ordered = sorted(records, key=lambda r: (r['line'], 0 if r['status'] == 'FAIL' else 1, -r['score'], r['item']))
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent, prefix='.report-', suffix='.tmp')
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as out:
            writer = csv.writer(out)
            writer.writerow(['line', 'item', 'inspector', 'status', 'score', 'defect'])
            for r in ordered:
                writer.writerow([r['line'], r['item'], r['inspector'], r['status'], r['score'], r['defect']])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return destination

