        quantity = item.get('quantity')
        if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity <= 0:
            raise ValueError('quantity must be positive')
        item_count += quantity
    if isinstance(total_cents, bool) or not isinstance(total_cents, int) or total_cents < 0:
        raise ValueError('total_cents must be non-negative')
    key = os.environ.get('RETURN_SIGNING_KEY')
    if key is None:
        raise RuntimeError('RETURN_SIGNING_KEY is not configured')
    payload = f'{order_id}|{customer_email}|{total_cents}|{item_count}'.encode('utf-8')
