from datetime import datetime, timezone
import math
from lxml import etree

def _tree(text):
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        return etree.fromstring(text.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc

def _number(value):
    try:
        result = float(value)
    except Exception as exc:
        raise ValueError('invalid number') from exc
    if not math.isfinite(result):
        raise ValueError('invalid number')
    return result

def _time(value):
    try:
        if not value.endswith('Z'):
            raise ValueError
        parsed = datetime.fromisoformat(value[:-1] + '+00:00')
        return parsed.astimezone(timezone.utc)
    except Exception as exc:
        raise ValueError('invalid timestamp') from exc

def parse_observations(xml_text: str) -> list[dict[str, object]]:
    root = _tree(xml_text)
    if root.tag != 'weather':
        raise ValueError('invalid root')
    result = []
    for station in root:
        if station.tag != 'station' or (station.text and station.text.strip()):
            raise ValueError('invalid station')
        sid = station.get('id')
        name = station.get('name')
        if sid is None or name is None:
            raise ValueError('missing station attribute')
        for reading in station:
            if reading.tag != 'reading' or len(reading):
                raise ValueError('invalid reading')
            keys = ('timestamp', 'temperature', 'humidity', 'wind', 'rain')
            if any((reading.get(k) is None for k in keys)):
                raise ValueError('missing reading attribute')
            result.append({'station': sid, 'name': name, 'timestamp': _time(reading.get('timestamp')), 'temperature': _number(reading.get('temperature')), 'humidity': _number(reading.get('humidity')), 'wind': _number(reading.get('wind')), 'rain': _number(reading.get('rain'))})
    result.sort(key=lambda x: (x['station'], x['timestamp']))
    return result

def daily_station_report(xml_text: str) -> list[dict[str, object]]:
    groups = {}
    for row in parse_observations(xml_text):
        key = (row['station'], row['timestamp'].date())
        groups.setdefault(key, []).append(row)
    result = []
    for (station, day), rows in sorted(groups.items()):
        result.append({'station': station, 'name': rows[0]['name'], 'date': day.isoformat(), 'count': len(rows), 'average_temperature': round(sum((r['temperature'] for r in rows)) / len(rows), 2), 'minimum_humidity': round(min((r['humidity'] for r in rows)), 2), 'peak_wind': round(max((r['wind'] for r in rows)), 2), 'total_rain': round(sum((r['rain'] for r in rows)), 2)})
    return result

