    order = 0
    for document in documents:
        for reading in parse_readings(document):
            groups.setdefault(reading['sensor'], []).append((reading['timestamp'], order, reading['pressure_kpa']))
            order += 1
    alerts = []
    for sensor, rows in groups.items():
        rows.sort(key=lambda x: (x[0], x[1]))
        for i in range(len(rows) - window_size + 1):
            window = rows[i:i + window_size]
            values = [x[2] for x in window]
            low, high = (min(values), max(values))
            if high - low > limit:
                alerts.append({'sensor': sensor, 'start_timestamp': window[0][0], 'end_timestamp': window[-1][0], 'minimum_kpa': low, 'maximum_kpa': high, 'average_kpa': sum(values) / window_size})
    return sorted(alerts, key=lambda x: (x['end_timestamp'], x['sensor'], x['start_timestamp']))

