        if code not in existing_codes:
            break
    cleaned.sort()
    return {'show_id': show_id.strip(), 'seats': cleaned, 'unit_price_cents': unit_price_cents, 'total_cents': len(cleaned) * unit_price_cents, 'booking_code': code}

