import csv
import io
import os
import tempfile
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
_FIELDS = ('trade_id', 'account', 'asset', 'side', 'quantity', 'price', 'fee', 'timestamp')
_Q = Decimal('0.00000001')

def _dec(value):
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError, TypeError):
        raise ValueError('invalid decimal')

def aggregate_settlement(records: list[dict]) -> list[dict]:
    groups = {}
    seen = set()
    for r in records:
        if any((k not in r for k in _FIELDS)):
            raise ValueError('missing field')
        tid = r['trade_id']
        if not isinstance(tid, str) or not tid or tid in seen:
            raise ValueError('invalid trade id')
        seen.add(tid)
        if not isinstance(r['asset'], str) or not r['asset'] or r['side'] not in ('BUY', 'SELL'):
            raise ValueError('invalid record')
        if not isinstance(r['timestamp'], int) or isinstance(r['timestamp'], bool):
            raise ValueError('invalid timestamp')
        q, p, fee = (_dec(r[x]) for x in ('quantity', 'price', 'fee'))
        if q <= 0 or p < 0 or fee < 0:
            raise ValueError('invalid amount')
        key = (r['account'], r['asset'])
        if key not in groups:
            groups[key] = [Decimal(0), Decimal(0), Decimal(0), 0]
        g = groups[key]
        sign = Decimal(1) if r['side'] == 'BUY' else Decimal(-1)
        g[0] += sign * q
        g[1] -= sign * q * p
        g[2] += fee
        g[3] += 1

    def fmt(x):
        return format(x.quantize(_Q, rounding=ROUND_HALF_UP), '.8f')
    return [{'account': a, 'asset': s, 'base_delta': fmt(g[0]), 'quote_delta': fmt(g[1]), 'fees': fmt(g[2]), 'trade_count': g[3]} for (a, s), g in sorted(groups.items())]

def export_settlement(records: list[dict], destination: str) -> str:
    rows = aggregate_settlement(records)
    out = io.StringIO(newline='')
    writer = csv.writer(out, lineterminator='\n')
    writer.writerow(('account', 'asset', 'base_delta', 'quote_delta', 'fees', 'trade_count'))
    for row in rows:
        writer.writerow(tuple(row.values()))
    text = out.getvalue()
    directory = os.path.dirname(os.path.abspath(destination)) or '.'
    fd, temp = tempfile.mkstemp(prefix='.settlement-', dir=directory, text=True)
    try:
        with os.fdopen(fd, 'w', newline='') as f:
            f.write(text)
            f.flush()
            os.fsync(f.fileno())
        os.replace(temp, destination)
    except Exception:
        try:
            os.unlink(temp)
        except OSError:
            pass
        raise
    return text

