import hashlib
import hmac
import json

def summarize_camera_webhook(body: str, signature: str, signing_key: str, offset: int=0, limit: int=50) -> dict:
    if isinstance(offset, bool) or not isinstance(offset, int) or offset < 0:
        raise ValueError('invalid pagination')
    if isinstance(limit, bool) or not isinstance(limit, int) or limit <= 0:
        raise ValueError('invalid pagination')
    if not isinstance(signature, str) or not signature.startswith('sha256=') or len(signature) != 71:
        raise ValueError('invalid signature')
    expected = 'sha256=' + hmac.new(signing_key.encode(), body.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(signature, expected):
        raise ValueError('invalid signature')
    try:
        parsed = json.loads(body)
        if not isinstance(parsed, dict) or not isinstance(parsed.get('events'), list):
            raise ValueError
        groups = {}
        for event in parsed['events']:
            if not isinstance(event, dict):
                raise ValueError
            camera = event.get('camera')
            timestamp = event.get('timestamp')
            kind = event.get('kind')
            confidence = event.get('confidence')
            if not isinstance(camera, str) or not camera:
                raise ValueError
            if isinstance(timestamp, bool) or not isinstance(timestamp, int):
                raise ValueError
            if kind not in ('motion', 'person'):
                raise ValueError
            if isinstance(confidence, bool) or not isinstance(confidence, (int, float)) or (not 0 <= confidence <= 1):
                raise ValueError
            if kind == 'motion' and confidence >= 0.5:
                item = groups.setdefault(camera, [0, timestamp, confidence])
                item[0] += 1
                item[1] = max(item[1], timestamp)
                item[2] = max(item[2], confidence)
    except (TypeError, ValueError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    result = [{'camera': camera, 'count': data[0], 'latest': data[1], 'peak_confidence': round(data[2], 3)} for camera, data in groups.items()]
    result.sort(key=lambda x: (-x['count'], -x['latest'], x['camera']))
    return {'total': len(result), 'cameras': result[offset:offset + limit]}

