import subprocess
from collections import defaultdict

def parse_climate_rows(text: str, variable: str) -> list[tuple[str, int, float]]:
    result = []
    for row in csv.reader(text.splitlines()):
        if not row or all((x == '' for x in row)):
            continue
        if row == ['station', 'year', 'variable', 'value']:
            continue
        if len(row) != 4 or not row[0]:
            raise ValueError('malformed row')
        try:
            year = int(row[1])
            value = float(row[3])
        except (TypeError, ValueError):
            raise ValueError('malformed row')
        if row[2] == variable:
            result.append((row[0], year, value))
    return result

def analyze_dataset(path: str, variable: str, window: int) -> dict:
    if not isinstance(window, int) or isinstance(window, bool) or window <= 0:
        raise ValueError('window must be positive')
    with open(path, 'r', encoding='utf-8', newline='') as f:
        header = next(csv.reader([f.readline()]), None)
        if header != ['station', 'year', 'variable', 'value']:
            raise ValueError('invalid header')
    p = subprocess.run(['grep', '-F', '--', variable, path], capture_output=True, text=True)
    if p.returncode not in (0, 1):
        raise OSError(p.stderr.strip() or 'grep failed')
    rows = parse_climate_rows(p.stdout, variable)
    by_year = defaultdict(list)
    for station, year, value in rows:
        by_year[year].append((station, value))
    years = sorted(by_year)
    yearly = []
    rolling = []
    for year in years:
        values = [v for _, v in by_year[year]]
        yearly.append({'year': year, 'count': len(values), 'mean': round(sum(values) / len(values), 3), 'min': min(values), 'max': max(values)})
        rv = [v for y in years if year - window + 1 <= y <= year for _, v in by_year[y]]
        rolling.append({'year': year, 'count': len(rv), 'mean': round(sum(rv) / len(rv), 3)})
    return {'variable': variable, 'records': len(rows), 'stations': sorted({s for s, _, _ in rows}), 'yearly': yearly, 'rolling': rolling}

