import ast
import operator

def evaluate_expression(expression: str, variables: dict[str, int | float | bool]) -> int | float | bool:
    tree = ast.parse(expression, mode='eval')

    def visit(node):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in variables:
                raise NameError(node.id)
            return variables[node.id]
        if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub, ast.Not):
            value = visit(node.operand)
            return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
        if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
            a, b = (visit(node.left), visit(node.right))
            return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](a, b)
        if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
            value = visit(node.values[0])
            for child in node.values[1:]:
                if isinstance(node.op, ast.And) and (not value) or (isinstance(node.op, ast.Or) and value):
                    return value
                value = visit(child)
            return value
        if isinstance(node, ast.Compare):
            left = visit(node.left)
            for op, right_node in zip(node.ops, node.comparators):
                right = visit(right_node)
                if not {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
            return {'min': min, 'max': max, 'round': round}[node.func.id](*(visit(x) for x in node.args))
        raise ValueError('unsupported expression')
    return visit(tree.body)

def allocate_seats(courses: list[dict], students: list[dict]) -> dict[str, list[str]]:
    codes = [c['code'] for c in courses]
    if len(codes) != len(set(codes)) or len({s['id'] for s in students}) != len(students):
        raise ValueError('duplicate identifier')
    result = {code: [] for code in codes}
    assigned = set()
    for course in courses:
        capacity = course['capacity']
        if not isinstance(capacity, int) or isinstance(capacity, bool) or capacity < 0:
            raise ValueError('invalid capacity')
        candidates = []
        for student in students:
            if student['id'] in assigned:
                continue
            variables = student['variables']
            if evaluate_expression(course['eligibility'], variables):
                score = evaluate_expression(course['score'], variables)
                candidates.append((score, student['priority'], student['id']))
        candidates.sort(key=lambda x: (-x[0], -x[1], x[2]))
        chosen = [x[2] for x in candidates[:capacity]]
        result[course['code']] = chosen
        assigned.update(chosen)
    return result

