def parse_permits(text: str) -> list[dict]:
    required = ['permit_id', 'owner_id', 'tenant', 'area', 'risk']
    reader = csv.DictReader(io.StringIO(text))
    if reader.fieldnames != required:
        raise ValueError('invalid header')
    result = []
    for row in reader:
        try:
            permit_id = row['permit_id'].strip()
            owner_id = row['owner_id'].strip()
            tenant = row['tenant'].strip()
            area = float(row['area'].strip())
            risk = row['risk'].strip().lower()
        except (AttributeError, TypeError, ValueError):
            raise ValueError('invalid row')
        if not permit_id or not owner_id or (not tenant) or (area <= 0) or (risk not in {'low', 'medium', 'high'}):
            raise ValueError('invalid row')
        result.append({'permit_id': permit_id, 'owner_id': owner_id, 'tenant': tenant, 'area': area, 'risk': risk})
    if not result or len({x['permit_id'] for x in result}) != len(result):
        raise ValueError('invalid permits')
    return sorted(result, key=lambda x: x['permit_id'])

class PermitBook:

    def __init__(self, records: list[dict]):
        self.records = {}
        for item in records:
            r = copy.deepcopy(item)
            if any((k not in r for k in ('permit_id', 'owner_id', 'tenant', 'area', 'risk'))):
                raise ValueError('incomplete record')
            if r['permit_id'] in self.records or float(r['area']) <= 0:
                raise ValueError('invalid record')
            r['area'] = float(r['area'])
            r.setdefault('status', 'pending')
            r.setdefault('history', [])
            self.records[r['permit_id']] = r

    def decide(self, requester: dict, permit_id: str, decision: str) -> dict:
        if decision not in {'approve', 'deny'}:
            raise ValueError('invalid decision')
        if permit_id not in self.records:
            raise KeyError(permit_id)
        record = self.records[permit_id]
        if record['status'] != 'pending':
            raise ValueError('permit is not pending')
        if not (requester.get('id') == record['owner_id'] or (requester.get('role') == 'inspector' and requester.get('tenant') == record['tenant'])):
            raise PermissionError('not permitted')
        record['status'] = 'approved' if decision == 'approve' else 'denied'
        record['history'].append({'actor': requester['id'], 'decision': decision})
        return copy.deepcopy(record)

    def summary(self, tenant: str | None=None) -> list[dict]:
        groups = {}
        for r in self.records.values():
            if tenant is not None and r['tenant'] != tenant:
                continue
            g = groups.setdefault(r['tenant'], {'tenant': r['tenant'], 'total': 0, 'pending': 0, 'approved': 0, 'denied': 0, 'area': 0.0})
            g['total'] += 1
            g[r['status']] += 1
            g['area'] += r['area']
        for g in groups.values():
            g['area'] = round(g['area'], 2)
        return sorted(groups.values(), key=lambda g: (-g['area'], g['tenant']))

