import math

def parse_telemetry(xml_text: str) -> list[dict]:
    if not isinstance(xml_text, str):
        raise ValueError('invalid XML')
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'telemetry':
        raise ValueError('invalid root')
    if (root.text or '').strip():
        raise ValueError('unexpected text')
    output = []
    required = {'station', 'time', 'temp', 'smoke', 'wind'}
    for child in root:
        if child.tag != 'reading' or (child.tail or '').strip():
            raise ValueError('invalid child')
        if set(child.attrib) != required or (child.text or '').strip():
            raise ValueError('invalid reading')
        station = child.get('station', '').strip()
        try:
            stamp = child.get('time')
            if not stamp.endswith('Z'):
                raise ValueError
            dt = datetime.fromisoformat(stamp[:-1] + '+00:00')
            values = [float(child.get(x)) for x in ('temp', 'smoke', 'wind')]
        except Exception as exc:
            raise ValueError('invalid reading') from exc
        if not station or not math.isfinite(dt.timestamp()) or any((not math.isfinite(x) for x in values)) or (values[2] < 0):
            raise ValueError('invalid reading')
        output.append({'station': station, 'time': dt.timestamp(), 'temp': values[0], 'smoke': values[1], 'wind': values[2]})
    return output

def summarize_alerts(readings: list[dict], window_seconds: int=300) -> list[dict]:
    if isinstance(window_seconds, bool) or not isinstance(window_seconds, int) or window_seconds <= 0:
        raise ValueError('invalid window')
    groups = {}
    for pos, item in enumerate(readings):
        try:
            if not isinstance(item, dict) or not isinstance(item.get('station'), str) or (not item['station']):
                raise ValueError
            vals = [float(item[k]) for k in ('time', 'temp', 'smoke', 'wind')]
            if any((not math.isfinite(v) for v in vals)) or vals[3] < 0:
                raise ValueError
        except Exception as exc:
            raise ValueError('invalid reading') from exc
        groups.setdefault(item['station'], []).append((vals, pos))
    result = []
    for station, entries in groups.items():
        entries.sort(key=lambda x: (x[0][0], x[1]))
        for i, (values, _) in enumerate(entries):
            t = values[0]
            window = [x[0] for x in entries[:i + 1] if x[0][0] >= t - window_seconds]
