def extract_reservation_bundle(archive_path: str, destination_dir: str) -> list[str]:
    base = os.path.realpath(destination_dir)
    os.makedirs(base, exist_ok=True)
    result = []
    with zipfile.ZipFile(archive_path) as archive:
        for info in archive.infolist():
            name = info.filename
            if name.endswith('/'):
                continue
            target = os.path.realpath(os.path.join(base, name))
            try:
                common = os.path.commonpath((base, target))
            except ValueError:
                raise ValueError('member outside destination')
            if common != base:
                raise ValueError('member outside destination')
            os.makedirs(os.path.dirname(target), exist_ok=True)
            with archive.open(info) as source, open(target, 'wb') as dest:
                while True:
                    chunk = source.read(65536)
                    if not chunk:
                        break
                    dest.write(chunk)
            result.append(name.replace(os.sep, '/'))
    return sorted(result)

def summarize_reservations(root_dir: str) -> dict[str, dict[str, int | float]]:
    root = os.path.realpath(root_dir)
    files = []
    for current, _, names in os.walk(root):
        for name in names:
            if name.endswith('.json'):
                path = os.path.join(current, name)
                files.append((os.path.relpath(path, root).replace(os.sep, '/'), path))
    totals = {}
    seen = set()
    for _, path in sorted(files):
        try:
            with open(path, encoding='utf-8') as f:
                record = json.load(f)
        except Exception as exc:
            raise ValueError('invalid reservation') from exc
        if not isinstance(record, dict):
            raise ValueError('invalid reservation')
        required = ('id', 'property', 'check_in', 'check_out', 'nightly_rate')
        if any((k not in record for k in required)):
            raise ValueError('invalid reservation')
        if not isinstance(record['id'], str) or not isinstance(record['property'], str):
            raise ValueError('invalid reservation')
        rate = record['nightly_rate']
        if isinstance(rate, bool) or not isinstance(rate, (int, float)) or rate < 0:
            raise ValueError('invalid reservation')
        try:
            start = datetime.date.fromisoformat(record['check_in'])
            end = datetime.date.fromisoformat(record['check_out'])
        except (TypeError, ValueError) as exc:
            raise ValueError('invalid reservation') from exc
        if end <= start or record['id'] in seen:
            raise ValueError('invalid reservation')
        seen.add(record['id'])
        item = totals.setdefault(record['property'], {'reservations': 0, 'nights': 0, 'revenue': 0})
        nights = (end - start).days
        item['reservations'] += 1
        item['nights'] += nights
        item['revenue'] += nights * rate
    for item in totals.values():
