import base64
import hashlib
import hmac
import json
import pytest

def make_token(report, key=b'kitchen-key'):
    payload = json.dumps(report, separators=(',', ':'), ensure_ascii=False).encode('utf-8')
    sig = hmac.new(key, payload, hashlib.sha256).digest()
