import base64
import hashlib
import hmac
import json
from datetime import date

def _date(value):
    if not isinstance(value, str) or len(value) != 10:
        raise ValueError('invalid date')
    try:
        parsed = date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid date')
    if parsed.isoformat() != value:
        raise ValueError('invalid date')
    return parsed

def decode_report(token: str, key: bytes) -> dict:
    if not isinstance(token, str) or not isinstance(key, bytes):
        raise ValueError('invalid input')
    parts = token.split('.')
    if len(parts) != 2 or not parts[0] or (not parts[1]):
        raise ValueError('invalid token')
    try:
        payload = base64.urlsafe_b64decode(parts[0] + '=' * (-len(parts[0]) % 4))
        supplied = base64.urlsafe_b64decode(parts[1] + '=' * (-len(parts[1]) % 4))
        expected = hmac.new(key, payload, hashlib.sha256).digest()
        if not hmac.compare_digest(supplied, expected):
            raise ValueError('invalid signature')
        obj = json.loads(payload.decode('utf-8'))
    except (ValueError, TypeError, UnicodeError, json.JSONDecodeError):
        raise ValueError('invalid token')
    if not isinstance(obj, dict) or set(obj) != {'restaurant', 'grade', 'inspected', 'violations'}:
        raise ValueError('invalid report')
    if not isinstance(obj['restaurant'], str) or not obj['restaurant'] or obj['restaurant'] != obj['restaurant'].strip():
        raise ValueError('invalid restaurant')
    if obj['grade'] not in {'A', 'B', 'C'} or not isinstance(obj['grade'], str):
        raise ValueError('invalid grade')
    _date(obj['inspected'])
    if isinstance(obj['violations'], bool) or not isinstance(obj['violations'], int) or obj['violations'] < 0:
        raise ValueError('invalid violations')
    return obj

def summarize_reports(tokens: list[str], key: bytes, as_of: str) -> dict:
    cutoff = _date(as_of)
    chosen = {}
    for token in tokens:
        report = decode_report(token, key)
        if _date(report['inspected']) > cutoff:
            continue
        old = chosen.get(report['restaurant'])
        rank = (report['inspected'], -report['violations'], chr(255 - ord(report['grade'])))
        old_rank = None if old is None else (old['inspected'], -old['violations'], chr(255 - ord(old['grade'])))
        if old is None or rank > old_rank:
            chosen[report['restaurant']] = report
    restaurants = {name: {'grade': chosen[name]['grade'], 'inspected': chosen[name]['inspected'], 'violations': chosen[name]['violations']} for name in sorted(chosen)}
    counts = {'A': 0, 'B': 0, 'C': 0}
    for report in chosen.values():
        counts[report['grade']] += 1
    return {'restaurants': restaurants, 'grade_counts': counts, 'total_violations': sum((x['violations'] for x in chosen.values()))}

