def generate_drift_report(requester: dict, resources: list[dict], findings: list[dict], page: int=1, page_size: int=10) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError('invalid page_size')
    resource_map = {}
    for resource in resources:
        if not all((k in resource for k in ('id', 'name', 'owner_id', 'tenant_id'))):
            raise ValueError('invalid resource')
        if resource['id'] in resource_map:
            raise ValueError('duplicate resource')
        resource_map[resource['id']] = resource
    allowed = {}
    for resource_id, resource in resource_map.items():
        same_tenant = resource['tenant_id'] == requester.get('tenant_id')
        owner = resource['owner_id'] == requester.get('id')
        administrator = 'admin' in requester.get('roles', [])
        allowed[resource_id] = same_tenant and (owner or administrator)
    weights = {'high': 0, 'medium': 1, 'low': 2}
    selected = []
    for finding in findings:
        severity = finding.get('severity')
        if severity not in weights:
            raise ValueError('invalid severity')
        resource = resource_map.get(finding.get('resource_id'))
        if resource is None or not allowed.get(finding.get('resource_id'), False):
            continue
        selected.append({'resource_id': finding['resource_id'], 'resource_name': resource['name'], 'severity': severity, 'category': finding['category'], 'changed_at': finding['changed_at']})
    selected.sort(key=lambda x: (weights[x['severity']], -ord(x['changed_at'][0]) if x['changed_at'] else 0, x['resource_id'], x['category']))
    selected.sort(key=lambda x: x['changed_at'], reverse=True)
    selected.sort(key=lambda x: weights[x['severity']])
    counts = {'high': 0, 'medium': 0, 'low': 0}
    for item in selected:
        counts[item['severity']] += 1
    start = (page - 1) * page_size
    return {'page': page, 'page_size': page_size, 'total': len(selected), 'by_severity': counts, 'items': selected[start:start + page_size]}

