import csv
import os
import tempfile
from datetime import date

def build_enrollment_report(records: list[dict]) -> list[dict]:
    allowed = {'screened', 'enrolled', 'completed', 'withdrawn'}
    seen = set()
    groups = {}
    for record in records:
        required = {'participant_id', 'site', 'status', 'enrolled_on', 'age'}
        if set(record) != required:
            raise ValueError('invalid record fields')
        pid = record['participant_id']
        site = record['site']
        status = record['status']
        if not isinstance(pid, str) or not pid or pid in seen:
            raise ValueError('invalid participant')
        if not isinstance(site, str) or not site:
            raise ValueError('invalid site')
        if status not in allowed:
            raise ValueError('invalid status')
        age = record['age']
        if isinstance(age, bool) or not isinstance(age, int) or (not 18 <= age <= 90):
            raise ValueError('invalid age')
        try:
            if not isinstance(record['enrolled_on'], str) or date.fromisoformat(record['enrolled_on']).isoformat() != record['enrolled_on']:
                raise ValueError
        except (TypeError, ValueError):
            raise ValueError('invalid date')
        seen.add(pid)
        if site not in groups:
            groups[site] = {'site': site, 'screened': 0, 'enrolled': 0, 'completed': 0, 'withdrawn': 0}
        groups[site][status] += 1
    result = []
    for row in groups.values():
        row = dict(row)
        row['total'] = sum((row[k] for k in allowed))
        row['completion_rate'] = round(row['completed'] / row['total'], 4)
        result.append(row)
    return sorted(result, key=lambda r: (-r['enrolled'], -r['completed'], r['site']))

def export_enrollment_report(records: list[dict], destination: str) -> list[dict]:
    report = build_enrollment_report(records)
    fields = ['site', 'screened', 'enrolled', 'completed', 'withdrawn', 'total', 'completion_rate']
    fd, temporary = tempfile.mkstemp(prefix='enrollment-', suffix='.csv', dir=os.path.dirname(os.path.abspath(destination)))
    os.close(fd)
    try:
        with open(temporary, 'w', newline='', encoding='utf-8') as stream:
            writer = csv.DictWriter(stream, fieldnames=fields)
            writer.writeheader()
            writer.writerows(report)
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return report

