def parse_window(spec: str) -> int:
    if not isinstance(spec, str) or not spec:
        raise ValueError('invalid window')
    if spec[-1] not in 'smh' or not spec[:-1].isdigit():
        raise ValueError('invalid window')
    value = int(spec[:-1])
    multiplier = {'s': 1, 'm': 60, 'h': 3600}[spec[-1]]
    result = value * multiplier
    if value <= 0 or result > 2147483647:
        raise ValueError('invalid window')
    return result

def _allowed(requester, policy):
    return requester.get('tenant_id') == policy.get('tenant_id') and (requester.get('id') == policy.get('owner_id') or 'admin' in requester.get('roles', []))

def update_policy(requester: dict, policy_id: str, policies: dict, patch: dict) -> dict:
    policy = policies[policy_id]
    if not _allowed(requester, policy):
        raise PermissionError('not permitted')
    for key in patch:
        if key not in {'limit', 'window', 'burst'}:
            raise ValueError('unknown field')
    result = dict(policy)
    for key, value in patch.items():
        if key in {'limit', 'burst'}:
            if isinstance(value, bool) or not isinstance(value, int) or value <= 0:
                raise ValueError('invalid value')
        elif key == 'window':
            parse_window(value)
        result[key] = value
    return result

def usage_report(requester: dict, policy_id: str, policies: dict, events: list[dict], now: int) -> dict:
    policy = policies[policy_id]
    if not _allowed(requester, policy):
        raise PermissionError('not permitted')
    seconds = parse_window(policy['window'])
    lower = now - seconds
    totals = {}
    for event in events:
        if event.get('policy_id') != policy_id:
            continue
        if 'timestamp' not in event or 'count' not in event:
            raise ValueError('invalid event')
        timestamp = event['timestamp']
        count = event['count']
        if isinstance(timestamp, bool) or not isinstance(timestamp, int) or isinstance(count, bool) or (not isinstance(count, int)) or (count < 0):
            raise ValueError('invalid event')
        if lower < timestamp <= now:
            totals[timestamp] = totals.get(timestamp, 0) + count
    ordered = {key: totals[key] for key in sorted(totals)}
    return {'policy_id': policy_id, 'window_seconds': seconds, 'limit': policy['limit'], 'total': sum(ordered.values()), 'by_second': ordered}

