        filters.append(f"status = '{status}'")
    if search is not None:
        filters.append(f"lower(case_number) LIKE lower('%{search}%')")
    query = 'SELECT id, case_number, judge, courtroom, start_time, status FROM hearings'
    if filters:
        query += ' WHERE ' + ' AND '.join(filters)
    query += f" ORDER BY {sort_by} {('DESC' if descending else 'ASC')}"
    query += f' LIMIT {page_size} OFFSET {(page - 1) * page_size}'
    cursor = conn.execute(query)
    names = ['id', 'case_number', 'judge', 'courtroom', 'start_time', 'status']
    return [dict(zip(names, row)) for row in cursor.fetchall()]

