import ast
import operator

def _evaluate(expression, values):
    tree = ast.parse(expression, mode='eval').body

    def visit(node):
        if isinstance(node, ast.Constant) and type(node.value) in (int, float, bool):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in values:
                raise NameError(node.id)
            return values[node.id]
        if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
            left = visit(node.left)
            right = visit(node.right)
            return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.Not, ast.UAdd, ast.USub)):
            value = visit(node.operand)
            if isinstance(node.op, ast.Not):
                return not value
            return +value if isinstance(node.op, ast.UAdd) else -value
        if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
            value = visit(node.values[0])
            for item in node.values[1:]:
                if isinstance(node.op, ast.And):
                    if not value:
                        return value
                elif value:
                    return value
                value = visit(item)
            return value
        if isinstance(node, ast.Compare):
            left = visit(node.left)
            for operation, comparator in zip(node.ops, node.comparators):
                right = visit(comparator)
                functions = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}
                if type(operation) not in functions:
                    raise ValueError('unsupported expression')
                if not functions[type(operation)](left, right):
                    return False
                left = right
            return True
        raise ValueError('unsupported expression')
    return visit(tree)

def select_sessions(sessions: list[dict], condition: str, page: int, page_size: int) -> list[str]:
    if page < 1 or page_size < 1:
        raise ValueError('invalid page')
    matching = []
    for session in sessions:
        values = {key: session[key] for key in ('active', 'age_days', 'idle_minutes', 'assurance', 'failed_attempts')}
        result = _evaluate(condition, values)
        if type(result) is not bool:
            raise ValueError('condition must be boolean')
        if result:
            matching.append(session['id'])
    start = (page - 1) * page_size
    return matching[start:start + page_size]

