import secrets
DAYS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']
ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'

def parse_staff(text: str) -> list[dict]:
    out = []
    seen = set()
    for line in text.splitlines():
        if not line.strip():
            continue
        p = [x.strip() for x in line.split('|')]
        if len(p) != 4 or not p[0] or (not p[1]):
            raise ValueError('invalid staff record')
        days = {x.strip() for x in p[2].split(',') if x.strip()}
        if not days or not days <= set(DAYS):
            raise ValueError('invalid days')
        try:
            hours = int(p[3])
        except ValueError:
            raise ValueError('invalid hours')
        if hours < 0 or p[0] in seen:
            raise ValueError('invalid staff')
        seen.add(p[0])
        out.append({'name': p[0], 'role': p[1], 'days': days, 'max_hours': hours})
    return out

def parse_shifts(text: str) -> list[dict]:
    out, seen = ([], set())
    for line in text.splitlines():
        if not line.strip():
            continue
        p = [x.strip() for x in line.split('|')]
        if len(p) != 5 or not p[0] or (not p[3]) or (p[1] not in DAYS):
            raise ValueError('invalid shift')
        try:
            a, b = p[2].split('-')
            if len(a) != 5 or len(b) != 5 or a[2] != ':' or (b[2] != ':'):
                raise ValueError
            start = int(a[:2]) * 60 + int(a[3:])
            end = int(b[:2]) * 60 + int(b[3:])
            count = int(p[4])
        except ValueError:
            raise ValueError('invalid shift')
        if not (0 <= start < 1440 and 0 < end <= 1440 and (start < end) and (count > 0)):
            raise ValueError('invalid shift')
        if p[0] in seen:
            raise ValueError('duplicate id')
        seen.add(p[0])
        out.append({'id': p[0], 'day': p[1], 'start': start, 'end': end, 'role': p[3], 'count': count})
    return out

def make_invite_code(length: int=12) -> str:
    if length < 4 or length > 64:
        raise ValueError('invalid length')
    return ''.join((secrets.choice(ALPHABET) for _ in range(length)))

def make_plan(staff_text: str, shift_text: str) -> list[dict]:
    staff = parse_staff(staff_text)
    shifts = parse_shifts(shift_text)
    indexed = sorted(enumerate(shifts), key=lambda z: (DAYS.index(z[1]['day']), z[1]['start'], z[0]))
    hours = [0] * len(staff)
    bookings = [[] for _ in staff]
    result = []
    for _, sh in indexed:
        eligible = []
        for i, person in enumerate(staff):
            overlap = any((d == sh['day'] and sh['start'] < e and (sh['end'] > s) for d, s, e in bookings[i]))
            if person['role'] == sh['role'] and sh['day'] in person['days'] and (not overlap) and (hours[i] + sh['end'] - sh['start'] <= person['max_hours']):
                eligible.append(i)
        eligible.sort(key=lambda i: (hours[i], i))
        chosen = eligible[:sh['count']]
        if len(chosen) != sh['count']:
            raise ValueError('unable to staff shift')
        duration = sh['end'] - sh['start']
        for i in chosen:
            hours[i] += duration
            bookings[i].append((sh['day'], sh['start'], sh['end']))
        result.append({'id': sh['id'], 'day': sh['day'], 'start': sh['start'], 'end': sh['end'], 'role': sh['role'], 'staff': [staff[i]['name'] for i in chosen], 'code': make_invite_code()})
    return result

