def summarize_downloads(base_dir: str, relative_name: str, min_downloads: int=0) -> list[dict]:
    if min_downloads < 0:
        raise ValueError('min_downloads must not be negative')
    base = Path(base_dir).resolve()
    path = (base / relative_name).resolve()
    try:
        path.relative_to(base)
    except ValueError:
        raise ValueError('file is outside base directory')
    groups = {}
    with path.open('r', encoding='utf-8', newline='') as handle:
        reader = csv.DictReader(handle)
        if reader.fieldnames is None:
            return []
        required = {'episode', 'show', 'downloads', 'completion_pct'}
        if not required.issubset(reader.fieldnames):
            raise ValueError('missing required column')
        for row in reader:
            try:
                downloads = int(row['downloads'])
                completion = float(row['completion_pct'])
            except (TypeError, ValueError):
                raise ValueError('invalid row')
            if downloads < 0 or not 0 <= completion <= 100:
                raise ValueError('invalid row')
            show = row['show']
            if show not in groups:
                groups[show] = [0, 0, 0.0]
            groups[show][0] += downloads
            groups[show][1] += 1
            groups[show][2] += completion
    result = []
    for show, (downloads, episodes, completion_total) in groups.items():
        average = round(completion_total / episodes, 2)
        if downloads >= min_downloads:
            result.append({'show': show, 'downloads': downloads, 'episodes': episodes, 'average_completion': average})
    result.sort(key=lambda item: (-item['downloads'], -item['average_completion'], item['show']))
    return result

