import hashlib
import hmac

def parse_upload(payload: str) -> tuple[str, int, str, str]:
    if not isinstance(payload, str) or not payload.endswith('\n'):
        raise ValueError('invalid payload')
    first = payload.find('\n')
    if first <= 0:
        raise ValueError('invalid header')
    parts = payload[:first].split('|')
    if len(parts) != 3:
        raise ValueError('invalid header')
    unit, stamp_text, signature = parts
    if not unit or any((c not in 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-' for c in unit)):
        raise ValueError('invalid unit')
    try:
        stamp = int(stamp_text)
    except Exception:
        raise ValueError('invalid timestamp')
    if stamp < 0 or stamp > 4102444800 or str(stamp) != stamp_text:
        raise ValueError('invalid timestamp')
    if len(signature) != 64 or signature.lower() != signature:
        raise ValueError('invalid signature')
    try:
        bytes.fromhex(signature)
    except ValueError:
        raise ValueError('invalid signature')
    body = payload[first + 1:]
    lines = body.splitlines()
    if not lines or any((not line for line in lines)):
        raise ValueError('invalid readings')
    for line in lines:
        fields = line.split(',')
        if len(fields) != 3:
            raise ValueError('invalid reading')
        try:
            values = [int(x) for x in fields]
        except Exception:
            raise ValueError('invalid reading')
        if any((str(v) != x for v, x in zip(values, fields))):
            raise ValueError('invalid reading')
        ts, minutes, rate = values
        if ts < 0 or ts > 4102444800 or minutes < 1 or (minutes > 1440) or (rate < 0) or (rate > 100000):
            raise ValueError('reading out of range')
    return (unit, stamp, signature, body)

def verify_upload(payload: str, keys: dict[str, str], now: int, max_age: int=300) -> tuple[str, int, list[tuple[int, int, int]]]:
    if not isinstance(now, int) or not isinstance(max_age, int) or max_age < 0:
        raise ValueError('invalid options')
    unit, stamp, signature, body = parse_upload(payload)
    if unit not in keys or abs(now - stamp) > max_age:
        raise ValueError('upload rejected')
    expected = hmac.new(keys[unit].encode('utf-8'), body.encode('utf-8'), hashlib.sha256).digest()
    if not hmac.compare_digest(expected, bytes.fromhex(signature)):
        raise ValueError('upload rejected')
    readings = []
    for line in body.splitlines():
        readings.append(tuple((int(x) for x in line.split(','))))
    return (unit, stamp, readings)

def summarize_upload(payload: str, keys: dict[str, str], now: int, max_age: int=300) -> dict[str, object]:
    unit, stamp, readings = verify_upload(payload, keys, now, max_age)
    buckets = {}
    for ts, minutes, rate in readings:
        bucket = ts - ts % 300
        buckets[bucket] = buckets.get(bucket, 0) + minutes
    buckets = {str(k): buckets[k] for k in sorted(buckets)}
    return {'unit': unit, 'timestamp': stamp, 'reading_count': len(readings), 'total_minutes': sum((x[1] for x in readings)), 'total_cents': sum((x[1] * x[2] for x in readings)), 'peak_rate': max((x[2] for x in readings)), 'buckets': buckets}

