def create_distribution_request(request_id: str, participant: str, age: float, amount: float, pin: str) -> dict:
    if not isinstance(request_id, str) or not request_id:
        raise ValueError('invalid request id')
    if not isinstance(participant, str) or not participant:
        raise ValueError('invalid participant')
    if not isinstance(age, (int, float)) or isinstance(age, bool) or (not math.isfinite(age)) or (not 18 <= age <= 120):
        raise ValueError('invalid age')
    if not isinstance(amount, (int, float)) or isinstance(amount, bool) or (not math.isfinite(amount)) or (amount <= 0):
        raise ValueError('invalid amount')
    if not isinstance(pin, str) or len(pin) != 4 or (not pin.isdecimal()) or any((ord(c) > 127 for c in pin)):
        raise ValueError('invalid pin')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return {'request_id': request_id, 'participant': participant, 'age': age, 'amount': amount, 'pin_salt': salt.hex(), 'pin_hash': digest.hex()}

def verify_distribution_pin(record: dict, pin: str) -> bool:
    try:
        if not isinstance(record, dict) or not isinstance(pin, str):
            return False
        salt = bytes.fromhex(record['pin_salt'])
        expected = bytes.fromhex(record['pin_hash'])
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError):
        return False

def summarize_requests(records: list[dict], page: int=1, page_size: int=10) -> dict:
    if not isinstance(records, list) or not isinstance(page, int) or isinstance(page, bool) or (page < 1) or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (page_size < 1):
        raise ValueError('invalid pagination')
    groups = {}
    eligible_count = 0
    total = Decimal('0')
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        try:
            participant = record['participant']
            request_id = record['request_id']
            age = record['age']
            amount = record['amount']
        except KeyError:
            raise ValueError('invalid record')
        if not isinstance(participant, str) or not isinstance(request_id, str) or (not isinstance(age, (int, float))) or isinstance(age, bool) or (not math.isfinite(age)) or (not isinstance(amount, (int, float))) or isinstance(amount, bool) or (not math.isfinite(amount)):
            raise ValueError('invalid record')
        if age >= 59.5:
            eligible_count += 1
            value = Decimal(str(amount))
            total += value
            groups.setdefault(participant, []).append(value)
    summaries = []
    for participant, values in groups.items():
        amount_total = sum(values, Decimal('0')).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        summaries.append({'participant': participant, 'request_count': len(values), 'amount_total': float(amount_total)})
    summaries.sort(key=lambda x: (-x['amount_total'], x['participant']))
    start = (page - 1) * page_size
    return {'eligible_count': eligible_count, 'eligible_total': float(total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)), 'participants': summaries[start:start + page_size], 'page_count': len(summaries)}

