import csv
import datetime
import os
import tempfile

def parse_records(text: str) -> list[dict]:
    rows = list(csv.reader(text.splitlines()))
    header = ['id', 'site', 'date', 'hazard', 'severity', 'resolved']
    if not rows or rows[0] != header:
        raise ValueError('invalid header')
    result = []
    seen = set()
    for row in rows[1:]:
        if len(row) != 6:
            raise ValueError('invalid row')
        ident, site, day, hazard, severity, resolved = row
        if not ident or not site or (not hazard) or (ident in seen):
            raise ValueError('invalid field')
        try:
            parsed_day = datetime.date.fromisoformat(day)
            level = int(severity)
        except Exception as exc:
            raise ValueError('invalid value') from exc
        if level < 1 or level > 5 or resolved not in ('true', 'false'):
            raise ValueError('invalid value')
        seen.add(ident)
        result.append({'id': ident, 'site': site, 'date': parsed_day, 'hazard': hazard, 'severity': level, 'resolved': resolved == 'true'})
    return result

def _window(as_of: str, window_days: int):
    if not isinstance(window_days, int) or isinstance(window_days, bool) or window_days <= 0:
        raise ValueError('invalid window')
    try:
        end = datetime.date.fromisoformat(as_of)
    except Exception as exc:
        raise ValueError('invalid date') from exc
    return (end - datetime.timedelta(days=window_days - 1), end)

def compliance_report(records: list[dict], as_of: str, window_days: int) -> list[dict]:
    start, end = _window(as_of, window_days)
    groups = {}
    for record in records:
        if start <= record['date'] <= end:
            item = groups.setdefault(record['site'], {'incidents': 0, 'unresolved': 0, 'risk': 0, 'latest': record['date']})
            item['incidents'] += 1
            item['latest'] = max(item['latest'], record['date'])
            if not record['resolved']:
                item['unresolved'] += 1
                item['risk'] += record['severity']
