import os
import zipfile
from pathlib import Path

def _unescape(value):
    result = []
    i = 0
    while i < len(value):
        if value[i] != '\\':
            result.append(value[i])
            i += 1
            continue
        i += 1
        if i == len(value):
            raise ValueError('trailing escape')
        code = value[i]
        if code == 't':
            result.append('\t')
        elif code == 'n':
            result.append('\n')
        elif code == '\\':
            result.append('\\')
        else:
            raise ValueError('unknown escape')
        i += 1
    return ''.join(result)

def parse_annotation_lines(text: str) -> dict[str, list[tuple[int, int, str, str]]]:
    groups = {}
    for number, line in enumerate(text.splitlines(), 1):
        if not line.strip() or line.lstrip().startswith('#'):
            continue
        fields = line.split('\t')
        if len(fields) != 5:
            raise ValueError('invalid line')
        doc, begin, finish, label, value = (_unescape(x) for x in fields)
        if not doc or not label:
            raise ValueError('empty field')
        try:
            begin, finish = (int(begin), int(finish))
        except ValueError:
            raise ValueError('invalid offset')
        if begin < 0 or finish <= begin:
            raise ValueError('invalid span')
        groups.setdefault(doc, []).append((begin, finish, label, value))
    for records in groups.values():
        records.sort(key=lambda x: (x[0], x[1], x[2], x[3]))
    return groups

def load_annotation_file(path: str) -> dict[str, list[tuple[int, int, str, str]]]:
    with open(path, encoding='utf-8') as handle:
        return parse_annotation_lines(handle.read())

def extract_annotation_bundle(base_dir: str, archive_path: str) -> list[str]:
    root = Path(base_dir).resolve()
    with zipfile.ZipFile(archive_path) as archive:
        entries = []
        seen = set()
        for info in archive.infolist():
            target = (root / info.filename).resolve()
            try:
                target.relative_to(root)
            except ValueError:
                raise ValueError('member outside base')
            relative = target.relative_to(root).as_posix()
            if not info.is_dir():
                if relative in seen:
                    raise ValueError('duplicate member')
                seen.add(relative)
                entries.append((info, target, relative))
        root.mkdir(parents=True, exist_ok=True)
        for info, target, _ in entries:
            target.parent.mkdir(parents=True, exist_ok=True)
            with archive.open(info) as source, open(target, 'wb') as output:
                output.write(source.read())
        return sorted((x[2] for x in entries))

