        raise ValueError('reading must be an object')
    for name in ('meter_id', 'timestamp', 'volume', 'signature'):
        if name not in obj:
            raise ValueError('missing field')
    if not isinstance(obj['meter_id'], str) or not obj['meter_id']:
        raise ValueError('invalid meter id')
    if not isinstance(obj['timestamp'], str) or not obj['timestamp'].endswith('Z'):
        raise ValueError('invalid timestamp')
    try:
        datetime.datetime.fromisoformat(obj['timestamp'][:-1] + '+00:00')
    except Exception as exc:
        raise ValueError('invalid timestamp') from exc
    if isinstance(obj['volume'], bool) or not isinstance(obj['volume'], (int, float)):
        raise ValueError('invalid volume')
    volume = float(obj['volume'])
    if not math.isfinite(volume) or volume < 0:
        raise ValueError('invalid volume')
    sig = obj['signature']
    if not isinstance(sig, str) or len(sig) != 64 or any((c not in '0123456789abcdef' for c in sig)):
        raise ValueError('invalid signature')
    return {'meter_id': obj['meter_id'], 'timestamp': obj['timestamp'], 'volume': volume, 'signature': sig}

def aggregate_readings(lines: list[str], config: dict | None=None) -> list[dict]:
    key = config['signing_key'] if config is not None and 'signing_key' in config else os.environ.get('GAS_METER_SIGNING_KEY')
    if key is None:
        raise ValueError('missing signing key')
    groups = {}
    for line in lines:
        reading = parse_reading(line)
        message = f"{reading['meter_id']}|{reading['timestamp']}|{reading['volume']:.6f}".encode()
        expected = hmac.new(str(key).encode(), message, hashlib.sha256).hexdigest()
        if not hmac.compare_digest(reading['signature'], expected):
            raise ValueError('invalid signature')
