        group = groups.setdefault((reading['meter_id'], date), [0.0, 0.0, 0])
        group[0] += reading['volume']
        group[1] = max(group[1], reading['volume'])
        group[2] += 1
    return [{'meter_id': meter, 'date': date, 'total_volume': round(v[0], 6), 'peak_volume': round(v[1], 6), 'count': v[2]} for (meter, date), v in sorted(groups.items())]

