from datetime import datetime, timezone

def _time(value):
    try:
        parsed = datetime.fromisoformat(value.replace('Z', '+00:00'))
    except (AttributeError, TypeError, ValueError) as exc:
        raise ValueError('invalid timestamp') from exc
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)

def _allowed(requester, trip):
    return requester.get('tenant_id') == trip.get('tenant_id') and (requester.get('id') == trip.get('owner_id') or 'itinerary_admin' in requester.get('roles', []))

def _records(requester, trips, begin, finish):
    chosen = {}
    for trip in trips:
        if not _allowed(requester, trip):
            raise PermissionError('not authorized')
        for event in trip.get('events', []):
            start = _time(event.get('start'))
            end = _time(event.get('end'))
            if end <= start:
                raise ValueError('invalid event interval')
            if start >= finish or end <= begin:
                continue
            clipped_start = max(start, begin)
            clipped_end = min(end, finish)
