        if any((not isinstance(item[k], str) or not item[k] for k in ('id', 'site', 'guest', 'check_in', 'check_out'))):
            raise ValueError('invalid reservation text')
        try:
            start = date.fromisoformat(item['check_in'])
            end = date.fromisoformat(item['check_out'])
        except Exception as exc:
            raise ValueError('invalid reservation dates') from exc
        if end <= start or isinstance(item['nightly_rate'], bool) or (not isinstance(item['nightly_rate'], (int, float))) or (item['nightly_rate'] <= 0):
            raise ValueError('invalid reservation values')
        if item['id'] in seen:
            raise ValueError('duplicate reservation id')
        seen.add(item['id'])
        result.append({**item, 'nightly_rate': float(item['nightly_rate'])})
    return result

def create_campground_report(reservations: list[dict], config: dict | None=None) -> dict:
    config = config or {}
    key = config.get('signing_key') or os.environ.get('CAMPGROUND_SIGNING_KEY')
    if not key:
        raise ValueError('missing campground signing key')
    ordered = sorted(reservations, key=lambda r: (r['site'], r['check_in'], r['check_out'], r['id']))
    by_site = {}
    details = []
