    revenue = 0.0
    for r in ordered:
        start = date.fromisoformat(r['check_in'])
        end = date.fromisoformat(r['check_out'])
        site_rows = by_site.setdefault(r['site'], [])
        if site_rows and start < date.fromisoformat(site_rows[-1]['check_out']):
            raise ValueError('overlapping reservations')
        nights = (end - start).days
        amount = round(nights * r['nightly_rate'], 2)
        details.append({'id': r['id'], 'site': r['site'], 'guest': r['guest'], 'check_in': r['check_in'], 'check_out': r['check_out'], 'nights': nights, 'amount': amount})
        for i in range(nights):
