            site_rows.append({'date': d.isoformat(), 'reservation_id': r['id'], 'guest': r['guest'], 'check_out': r['check_out']})
        total_nights += nights
        revenue += amount
    occupancy = {site: [{k: x[k] for k in ('date', 'reservation_id', 'guest')} for x in rows] for site, rows in by_site.items()}
    report = {'reservations': details, 'occupancy': occupancy, 'totals': {'reservations': len(details), 'nights': total_nights, 'revenue': round(revenue, 2)}}
