import hashlib
import hmac
import os
from datetime import datetime

def _credential(password):
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def _check(password, value):
    try:
        salt_text, digest_text = value.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (AttributeError, ValueError, TypeError):
        return False

def create_shift_access(password: str, shifts: list[dict], page: int=1, page_size: int=3) -> dict:
    if not isinstance(password, str) or not isinstance(shifts, list):
        raise TypeError()
    if not password:
        raise ValueError()
    if not isinstance(page, int) or not isinstance(page_size, int):
        raise TypeError()
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError()
    valid = []
    hours = 0
    for shift in shifts:
        if not isinstance(shift, dict) or any((k not in shift or not isinstance(shift[k], str) for k in ('employee', 'start', 'end', 'status'))):
            raise ValueError()
        if shift['status'] not in ('scheduled', 'cancelled'):
            raise ValueError()
        try:
            start = datetime.fromisoformat(shift['start'].replace('Z', '+00:00'))
            end = datetime.fromisoformat(shift['end'].replace('Z', '+00:00'))
        except ValueError:
            raise ValueError()
        if end <= start:
            raise ValueError()
        if shift['status'] == 'scheduled':
            valid.append((start, shift['employee'], shift))
            hours += (end - start).total_seconds() / 3600
    valid.sort(key=lambda x: (x[0], x[1]))
    begin = (page - 1) * page_size
    return {'credential': _credential(password), 'total': len(valid), 'total_hours': round(hours, 2), 'page': page, 'page_size': page_size, 'shifts': [x[2] for x in valid[begin:begin + page_size]]}

def verify_shift_access(password: str, record: dict) -> bool:
    if not isinstance(password, str) or not password or (not isinstance(record, dict)):
        return False
    return _check(password, record.get('credential'))

