import hashlib
import hmac
import json

import pytest

from solution import verify_schedule


def make_payload(value):
    return json.dumps(value, ensure_ascii=False, separators=(",", ":"))


def sign(payload, secret):
    return hmac.new(secret.encode("utf-8"), payload.encode("utf-8"), hashlib.sha256).hexdigest()


def valid_value():
    return {
        "exhibit": "Savanna",
        "date": "2025-06-14",
        "feedings": [
            {"time": "09:30", "food": "hay"},
            {"time": "15:00", "food": "fruit"},
        ],
    }


def test_valid_schedule_is_returned_unchanged():
    payload = make_payload(valid_value())
    assert verify_schedule(payload, sign(payload, "keeper-key"), "keeper-key") == valid_value()


def test_additional_fields_and_unicode_are_preserved():
    value = {
        "exhibit": "Panda Grove",
        "date": "2025-12-01",
        "feedings": [{"time": "08:00", "food": "竹子"}],
        "keeper": "Mina",
        "notes": ["quiet morning", "indoor"] ,
    }
    payload = make_payload(value)
    assert verify_schedule(payload, sign(payload, "秘密"), "秘密") == value


def test_wrong_signature_is_rejected():
    payload = make_payload(valid_value())
    with pytest.raises(ValueError, match="^invalid signature$"):
        verify_schedule(payload, "0" * 64, "keeper-key")


def test_wrong_secret_is_rejected():
    payload = make_payload(valid_value())
    signature = sign(payload, "keeper-key")
    with pytest.raises(ValueError, match="^invalid signature$"):
        verify_schedule(payload, signature, "another-key")


def test_malformed_json_with_valid_signature_is_invalid_schedule():
    payload = '{"exhibit":"Savanna",'
    with pytest.raises(ValueError, match="^invalid schedule$"):
        verify_schedule(payload, sign(payload, "k"), "k")


def test_non_object_json_is_invalid_schedule():
    payload = make_payload([{"time": "09:00", "food": "hay"}])
    with pytest.raises(ValueError, match="^invalid schedule$"):
        verify_schedule(payload, sign(payload, "k"), "k")


def test_missing_required_fields_is_invalid_schedule():
