        {"exhibit": "", "date": "2025-06-14", "feedings": []},
        {"exhibit": "Savanna", "date": "", "feedings": []},
        {"exhibit": "Savanna", "date": "2025-06-14", "feedings": [{"time": "09:00", "food": ""}]},
