import csv
import datetime
import os
import tempfile
from decimal import Decimal, ROUND_HALF_UP

def export_incident_report(records: list[dict], destination: str, page: int=1, page_size: int=10) -> dict:
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError('invalid paging')
    fields = {'worker', 'department', 'severity', 'days_lost', 'incident_date'}
    levels = {'low': 0, 'medium': 1, 'high': 2, 'critical': 3}
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise TypeError('record must be a dictionary')
        if set(record) != fields:
            raise ValueError('invalid fields')
        if not isinstance(record['worker'], str) or not isinstance(record['department'], str):
            raise TypeError('invalid text')
        if not record['worker'] or not record['department']:
            raise ValueError('empty text')
        if record['severity'] not in levels:
            raise ValueError('invalid severity')
        if isinstance(record['days_lost'], bool) or not isinstance(record['days_lost'], int):
            raise TypeError('invalid days')
        if record['days_lost'] < 0:
            raise ValueError('invalid days')
        try:
            datetime.date.fromisoformat(record['incident_date'])
        except (TypeError, ValueError):
            raise ValueError('invalid date')
        department = record['department']
        group = groups.setdefault(department, {'incidents': 0, 'total': 0, 'highest': -1, 'latest': record['incident_date']})
        group['incidents'] += 1
        group['total'] += record['days_lost']
        group['highest'] = max(group['highest'], levels[record['severity']])
        group['latest'] = max(group['latest'], record['incident_date'])
    names = ['low', 'medium', 'high', 'critical']
    rows = []
    for department, group in groups.items():
        average = (Decimal(group['total']) / Decimal(group['incidents'])).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        rows.append({'department': department, 'incidents': group['incidents'], 'total_days_lost': group['total'], 'average_days_lost': format(average, '.2f'), 'highest_severity': names[group['highest']], 'latest_incident': group['latest']})
    rows.sort(key=lambda row: (-row['total_days_lost'], -row['incidents'], row['department']))
    parent = os.path.dirname(os.path.abspath(destination))
    os.makedirs(parent, exist_ok=True)
    fd, temporary = tempfile.mkstemp(dir=parent)
    try:
        with os.fdopen(fd, 'w', newline='') as handle:
            writer = csv.DictWriter(handle, fieldnames=['department', 'incidents', 'total_days_lost', 'average_days_lost', 'highest_severity', 'latest_incident'])
            writer.writeheader()
            writer.writerows(rows)
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    start = (page - 1) * page_size
    return {'total_departments': len(rows), 'page': page, 'page_size': page_size, 'total_pages': (len(rows) + page_size - 1) // page_size if rows else 0, 'rows': rows[start:start + page_size]}

