import sqlite3

def build_alert_report(conn: sqlite3.Connection, station_ids: list[str], min_severity: int, sort_by: str='latest', limit: int=50, offset: int=0) -> list[dict]:
    if not isinstance(station_ids, list) or any((not isinstance(x, str) or not x for x in station_ids)):
        raise ValueError('invalid station_ids')
    if not isinstance(min_severity, int) or isinstance(min_severity, bool) or (not 0 <= min_severity <= 5):
        raise ValueError('invalid severity')
    if sort_by not in {'latest', 'count', 'station'}:
        raise ValueError('invalid sort')
    if not isinstance(limit, int) or isinstance(limit, bool) or (not 0 <= limit <= 1000):
        raise ValueError('invalid limit')
    if not isinstance(offset, int) or isinstance(offset, bool) or offset < 0:
        raise ValueError('invalid offset')
    stations = list(dict.fromkeys(station_ids))
    if not stations or limit == 0:
        return []
    marks = ','.join(('?' for _ in stations))
    ordering = {'latest': 'latest_observed_at DESC, station ASC', 'count': 'alert_count DESC, station ASC', 'station': 'station ASC'}[sort_by]
    query = f'SELECT station, COUNT(*) AS alert_count, MAX(severity) AS max_severity, ROUND(AVG(severity), 2) AS average_severity, MAX(observed_at) AS latest_observed_at FROM alerts WHERE station IN ({marks}) AND severity >= ? GROUP BY station ORDER BY {ordering} LIMIT ? OFFSET ?'
    params = stations + [min_severity, limit, offset]
    rows = conn.execute(query, params).fetchall()
    return [{'station': r[0], 'alert_count': r[1], 'max_severity': r[2], 'average_severity': float(r[3]), 'latest_observed_at': r[4]} for r in rows]

