import secrets

def _clock(value):
    if not isinstance(value, str) or len(value) != 5 or value[2] != ':' or (not value[:2].isdigit()) or (not value[3:].isdigit()):
        raise ValueError('invalid time')
    hour = int(value[:2])
    minute = int(value[3:])
    if hour > 23 or minute > 59:
        raise ValueError('invalid time')
    return hour * 60 + minute

def generate_timetable_view(records: list[dict], station: str, start: str, end: str, page: int, page_size: int) -> dict:
    start_value = _clock(start)
    end_value = _clock(end)
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError('invalid page size')
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    code = ''.join((secrets.choice(alphabet) for _ in range(10)))
    selected = []
    required = {'train', 'station', 'departure', 'arrival', 'platform', 'status'}
    for record in records:
        if not isinstance(record, dict) or not required.issubset(record):
            raise ValueError('invalid record')
        if record['status'] not in {'scheduled', 'cancelled'}:
            raise ValueError('invalid status')
        departure = _clock(record['departure'])
        _clock(record['arrival'])
        if record['status'] == 'scheduled' and record['station'] == station and (start_value <= departure <= end_value):
            selected.append((departure, record['train'], record))
    selected.sort(key=lambda item: (item[0], item[1]))
    total = len(selected)
    first = (page - 1) * page_size
    trains = [{'train': item[2]['train'], 'departure': item[2]['departure'], 'arrival': item[2]['arrival'], 'platform': item[2]['platform']} for item in selected[first:first + page_size]]
    return {'code': code, 'total': total, 'trains': trains}

