            raise ValueError('invalid reservation')
        if item['status'] == 'confirmed':
            group = groups.setdefault(item['boat_type'], [0, 0, 0.0])
            group[0] += 1
            group[1] += item['nights']
            group[2] += item['total']
    result = [{'boat_type': name, 'reservation_count': values[0], 'total_nights': values[1], 'total_revenue': round(values[2], 2)} for name, values in groups.items()]
    result.sort(key=lambda item: (-item['total_revenue'], item['boat_type']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

