import hashlib
import hmac
import json
import os

def hash_secret(secret: str) -> str:
    if not isinstance(secret, str):
        raise TypeError()
    if not secret:
        raise ValueError()
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
    return salt.hex() + '$' + value.hex()

def verify_secret(secret: str, stored: str) -> bool:
    if not isinstance(secret, str) or not isinstance(stored, str) or (not secret):
        return False
    try:
        salt_text, value_text = stored.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(value_text)
        actual = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def parse_manifest(text: str) -> dict:
    if not isinstance(text, str):
        raise TypeError()
    try:
        data = json.loads(text)
    except Exception as exc:
        raise ValueError() from exc
    if not isinstance(data, dict) or not isinstance(data.get('assets'), list):
        raise ValueError()
    ids = set()
    for asset in data['assets']:
        if not isinstance(asset, dict) or not isinstance(asset.get('id'), str) or (not asset['id']) or (asset['id'] in ids):
            raise ValueError()
        ids.add(asset['id'])
        duration = asset.get('duration')
        if isinstance(duration, bool) or not isinstance(duration, (int, float)) or duration <= 0:
            raise ValueError()
        if not isinstance(asset.get('renditions'), list):
            raise ValueError()
        for r in asset['renditions']:
            if not isinstance(r, dict) or not isinstance(r.get('name'), str) or (not r['name']) or (not isinstance(r.get('codec'), str)) or (not r['codec']):
                raise ValueError()
            if any((isinstance(r.get(k), bool) or not isinstance(r.get(k), int) or r[k] <= 0 for k in ('width', 'height', 'bitrate'))):
                raise ValueError()
            if 'enabled' in r and (not isinstance(r['enabled'], bool)):
                raise ValueError()
    return data

def build_transcode_plan(manifest: dict, secret: str, stored_secret: str) -> list[dict]:
    if not verify_secret(secret, stored_secret):
        raise PermissionError()
    if not isinstance(manifest, dict):
        raise ValueError()
    checked = parse_manifest(json.dumps(manifest))
    jobs = []
    for asset in checked['assets']:
        for r in asset['renditions']:
            if r.get('enabled', True) is not False:
                priority = asset.get('priority', 0)
                if not isinstance(priority, (int, float)) or isinstance(priority, bool):
                    priority = 0
                jobs.append((-priority, -(r['width'] * r['height']), asset['id'], r['name'], asset, r))
    jobs.sort(key=lambda x: x[:4])
    out = []
    clock = 0.0
    for _, _, _, _, asset, r in jobs:
        start = round(clock, 3)
        end = clock + asset['duration']
        out.append({'asset_id': asset['id'], 'rendition': r['name'], 'codec': r['codec'], 'width': r['width'], 'height': r['height'], 'bitrate': r['bitrate'], 'start': start, 'end': round(end, 3)})
        clock = end
    return out

