from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from pathlib import Path

def build_preorder_report(base_dir: str, filename: str, orders: list[dict], page: int=1, page_size: int=10) -> str:
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('invalid page size')
    if not isinstance(filename, str) or not filename:
        raise ValueError('invalid filename')
    base = Path(base_dir).resolve()
    destination = (base / filename).resolve()
    try:
        destination.relative_to(base)
    except ValueError:
        raise ValueError('destination outside base directory')
    totals = {}
    for order in orders:
        if not isinstance(order, dict) or not all((k in order for k in ('title', 'quantity', 'unit_price'))):
            raise ValueError('invalid order')
        title, quantity, price = (order['title'], order['quantity'], order['unit_price'])
        if not isinstance(title, str) or not title.strip():
            raise ValueError('invalid title')
        if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity <= 0:
            raise ValueError('invalid quantity')
        if isinstance(price, bool) or not isinstance(price, (int, float)) or (not math.isfinite(price)) or (price < 0):
            raise ValueError('invalid price')
        try:
            amount = Decimal(str(price)) * quantity
        except (InvalidOperation, ValueError):
            raise ValueError('invalid price')
        key = title.strip()
        if key not in totals:
            totals[key] = [0, Decimal('0')]
        totals[key][0] += quantity
        totals[key][1] += amount
    rows = sorted(totals.items(), key=lambda item: (-item[1][1], item[0]))
    start = (page - 1) * page_size
    lines = ['title,total_quantity,total_revenue']
    for title, (quantity, revenue) in rows[start:start + page_size]:
        rounded = revenue.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        lines.append(f'{title},{quantity},{rounded:.2f}')
    destination.parent.mkdir(parents=True, exist_ok=True)
    destination.write_text('\n'.join(lines) + '\n', encoding='utf-8')
    return str(destination)

