import base64
import hashlib
import hmac
import os
from datetime import date

def _parsed(value):
    if not isinstance(value, str):
        raise ValueError('invalid date')
    try:
        return date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid date')

def issue_permit(applicant_id: str, plate: str, zone: str, start_date: str, end_date: str, pin: str) -> dict:
    if not isinstance(applicant_id, str) or not applicant_id.strip():
        raise ValueError('invalid applicant')
    applicant_id = applicant_id.strip()
    if not isinstance(plate, str):
        raise ValueError('invalid plate')
    normalized = ''.join((c for c in plate if c not in ' -'))
    if not normalized or len(normalized) > 8 or (not normalized.isascii()) or (not normalized.isalnum()):
        raise ValueError('invalid plate')
    if zone not in {'A', 'B', 'C'}:
        raise ValueError('invalid zone')
    start = _parsed(start_date)
    end = _parsed(end_date)
    days = (end - start).days + 1
    if days < 1 or days > 31:
        raise ValueError('invalid period')
    if not isinstance(pin, str) or not pin.isascii() or (not pin.isdigit()) or (not 4 <= len(pin) <= 8):
        raise ValueError('invalid pin')
    rates = {'A': 125, 'B': 200, 'C': 325}
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    credential = 'v1$' + base64.b64encode(salt).decode() + '$' + base64.b64encode(value).decode()
    normalized = normalized.upper()
    return {'permit_id': f'{applicant_id}:{normalized}:{start_date}', 'applicant_id': applicant_id, 'plate': normalized, 'zone': zone, 'start_date': start_date, 'end_date': end_date, 'fee_cents': days * rates[zone], 'credential': credential}

def verify_permit(permit: dict, pin: str) -> bool:
    try:
        if not isinstance(pin, str):
            return False
        version, salt_text, value_text = permit['credential'].split('$')
        if version != 'v1':
            return False
        salt = base64.b64decode(salt_text, validate=True)
        expected = base64.b64decode(value_text, validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (KeyError, ValueError, TypeError):
        return False

