import base64
import binascii
import hashlib
import hmac
import os
import re

def parse_document(document: str) -> list[dict]:
    if not isinstance(document, str) or not document:
        raise ValueError('invalid document')
    lines = document.split('\n')
    if lines and lines[-1] == '':
        lines.pop()
    result = []
    seen = set()
    for line in lines:
        if not line:
            raise ValueError('blank line')
        pos = None
        escaped = False
        for i, ch in enumerate(line):
            if escaped:
                escaped = False
            elif ch == '\\':
                escaped = True
            elif ch == '\t':
                if pos is not None:
                    raise ValueError('multiple delimiters')
                pos = i
        if escaped or pos is None:
            raise ValueError('malformed line')
        raw_id, raw_text = (line[:pos], line[pos + 1:])
        if not raw_id.isdigit() or int(raw_id) <= 0 or (not raw_text):
            raise ValueError('invalid segment')
        ident = int(raw_id)
        if ident in seen:
            raise ValueError('duplicate segment')
        seen.add(ident)
        out = []
        i = 0
        while i < len(raw_text):
            if raw_text[i] != '\\':
                out.append(raw_text[i])
            else:
                i += 1
                if i == len(raw_text) or raw_text[i] not in 'tn\\':
                    raise ValueError('invalid escape')
                out.append({'t': '\t', 'n': '\n', '\\': '\\'}[raw_text[i]])
            i += 1
        text = ''.join(out)
        if not text:
            raise ValueError('empty text')
        result.append({'id': ident, 'text': text})
    if not result:
        raise ValueError('empty document')
    return sorted(result, key=lambda x: x['id'])

def create_translation_record(case_id: str, source_language: str, target_language: str, document: str, access_secret: str) -> dict:
    if not isinstance(case_id, str) or not case_id.strip():
        raise ValueError('invalid case')
    if not isinstance(source_language, str) or not re.fullmatch('[a-z]{2}', source_language):
        raise ValueError('invalid source')
    if not isinstance(target_language, str) or not re.fullmatch('[a-z]{2}', target_language):
        raise ValueError('invalid target')
    if not isinstance(access_secret, str) or not access_secret:
        raise ValueError('invalid secret')
    segments = parse_document(document)
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', access_secret.encode(), salt, 100000)
    return {'case_id': case_id.strip(), 'source_language': source_language, 'target_language': target_language, 'segments': segments, 'statuses': {str(x['id']): 'pending' for x in segments}, 'credential': {'salt': base64.b64encode(salt).decode(), 'digest': base64.b64encode(digest).decode()}}

def authenticate_translation_record(record: dict, access_secret: str) -> bool:
    try:
        c = record['credential']
        salt = base64.b64decode(c['salt'], validate=True)
        expected = base64.b64decode(c['digest'], validate=True)
        if not isinstance(access_secret, str):
            return False
        actual = hashlib.pbkdf2_hmac('sha256', access_secret.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError, binascii.Error):
        return False

def translation_summary(record: dict) -> dict:
    try:
        segments = record['segments']
        statuses = record['statuses']
        if not isinstance(segments, list) or not isinstance(statuses, dict):
            raise ValueError
        ids = [x['id'] for x in segments]
        if any((not isinstance(x, dict) or not isinstance(x['id'], int) or (not isinstance(x['text'], str)) for x in segments)) or len(set(ids)) != len(ids):
            raise ValueError
        pending = []
        completed = chars = words = 0
        for x in segments:
            state = statuses.get(str(x['id']))
            if state not in ('pending', 'completed'):
                raise ValueError
            if state == 'completed':
                completed += 1
            else:
                pending.append(x['id'])
            chars += len(x['text'])
            words += len(re.findall("[\\w']+", x['text']))
        if set(statuses) != {str(x) for x in ids}:
            raise ValueError
        return {'segment_count': len(segments), 'completed_count': completed, 'total_characters': chars, 'word_count': words, 'pending_ids': pending}
    except (KeyError, TypeError):
        raise ValueError('malformed record')

