from lxml import etree

def parse_registration(xml_text: str) -> dict:
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode('utf-8'), parser)
    except (etree.XMLSyntaxError, UnicodeEncodeError, AttributeError) as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'registration':
        raise ValueError('unexpected root')
    attendee = root.find('attendee')
    if attendee is None:
        raise ValueError('missing attendee')
    name_node = attendee.find('name')
    email_node = attendee.find('email')
    name = name_node.text.strip() if name_node is not None and name_node.text is not None else ''
    email = email_node.text.strip() if email_node is not None and email_node.text is not None else ''
    if not name or not email:
        raise ValueError('missing attendee data')
    sessions = []
    for session in root.findall('session'):
        session_id = session.get('id')
        title_node = session.find('title')
        title = title_node.text.strip() if title_node is not None and title_node.text is not None else ''
        if not session_id or not title:
            raise ValueError('missing session data')
        sessions.append({'id': session_id, 'title': title})
    return {'name': name, 'email': email, 'sessions': sessions}

