    if re.match('^#+\\s', value):
        return True
    return len(value) >= 4 and all((c.isupper() or c.isdigit() or c in ' :-_' for c in value))

def score_manuscripts(paths: list[str], terms: list[str], top_n: int=3) -> list[dict]:
    if not isinstance(top_n, int) or isinstance(top_n, bool) or top_n <= 0:
        raise ValueError('top_n must be positive')
    if not paths or any((not isinstance(p, str) or not p for p in paths)):
        raise ValueError('invalid paths')
    if not terms or any((not isinstance(t, str) or not t for t in terms)):
        raise ValueError('invalid terms')
    if len(set(terms)) != len(terms):
        raise ValueError('duplicate terms')
    results = []
    for path in paths:
        if not os.path.isfile(path):
            raise FileNotFoundError(path)
        with open(path, encoding='utf-8') as handle:
            lines = handle.readlines()
        matches = {}
        score = 0
        for term in terms:
            completed = subprocess.run(['grep', '-n', '-i', '-F', '-H', '--', term, path], capture_output=True, text=True)
            if completed.returncode not in (0, 1):
                raise FileNotFoundError(path)
            numbers = []
            for row in completed.stdout.splitlines():
                pieces = row.split(':', 2)
                if len(pieces) >= 2:
                    numbers.append(int(pieces[1]))
            matches[term] = numbers
            for number in numbers:
                prior = 0
                checked = 0
                for index in range(number - 2, -1, -1):
                    if lines[index].strip():
                        checked += 1
                        if _heading(lines[index]):
                            prior = 1
                            break
                        if checked == 3:
                            break
                score += 1 + prior
        results.append({'path': path, 'score': score, 'matches': matches})
    results.sort(key=lambda item: (-item['score'], item['path']))
    return results[:top_n]

