import ast
import math
import operator

def _value(node, names):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, bool)):
        return node.value
    if isinstance(node, ast.Name) and node.id in names:
        return names[node.id]
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub)):
        value = _value(node.operand, names)
        return +value if isinstance(node.op, ast.UAdd) else -value
    if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
        left, right = (_value(node.left, names), _value(node.right, names))
        return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max', 'round'}) and (not node.keywords):
        args = [_value(arg, names) for arg in node.args]
        return {'min': min, 'max': max, 'round': round}[node.func.id](*args)
    raise ValueError('invalid formula')

def compute_water_bills(records: list[dict[str, object]], formula: str) -> list[tuple[str, float]]:
    try:
        tree = ast.parse(formula, mode='eval')
        result = []
        for record in records:
            value = _value(tree.body, {'usage': record['usage'], 'rate': record['rate'], 'fixed': record['fixed']})
            if isinstance(value, bool) or not isinstance(value, (int, float)) or (not math.isfinite(value)):
                raise ValueError('formula must produce a number')
            result.append((record['account'], round(value, 2)))
        return sorted(result, key=lambda item: (-item[1], item[0]))
    except Exception as exc:
        if isinstance(exc, ValueError):
            raise
        raise ValueError('invalid formula') from exc

