import csv
import os
from pathlib import Path

def write_station_session_report(base_dir: str, station_id: str, filename: str, sessions: list[dict], page: int=1, page_size: int=10) -> str:
    if not station_id or page < 1 or page_size < 1 or (page_size > 100):
        raise ValueError('invalid arguments')
    required = ('station_id', 'connector', 'energy_kwh', 'cost_cents', 'duration_min')
    groups = {}
    for session in sessions:
        if any((key not in session for key in required)):
            raise ValueError('invalid session')
        if not isinstance(session['station_id'], str) or not isinstance(session['connector'], str):
            raise ValueError('invalid session')
        if isinstance(session['energy_kwh'], bool) or not isinstance(session['energy_kwh'], (int, float)):
            raise ValueError('invalid session')
        if isinstance(session['cost_cents'], bool) or not isinstance(session['cost_cents'], int):
            raise ValueError('invalid session')
        if isinstance(session['duration_min'], bool) or not isinstance(session['duration_min'], (int, float)):
            raise ValueError('invalid session')
        if session['station_id'] != station_id:
            continue
        connector = session['connector']
        item = groups.setdefault(connector, [0, 0.0, 0, 0.0])
        item[0] += 1
        item[1] += session['energy_kwh']
        item[2] += session['cost_cents']
        item[3] += session['duration_min']
    rows = []
    for connector in sorted(groups):
        count, energy, cost, duration = groups[connector]
        rows.append([connector, count, round(energy, 2), cost, round(duration / count, 2)])
    start = (page - 1) * page_size
    rows = rows[start:start + page_size]
    base = Path(base_dir).resolve()
    target = (base / filename).resolve()
    try:
        target.relative_to(base)
    except ValueError:
        raise ValueError('invalid filename')
    target.parent.mkdir(parents=True, exist_ok=True)
    with target.open('w', newline='', encoding='utf-8') as handle:
        writer = csv.writer(handle)
        writer.writerow(['connector', 'sessions', 'energy_kwh', 'cost_cents', 'avg_duration_min'])
        writer.writerows(rows)
    return str(target)

