import sqlite3
from datetime import date
from typing import Any

def catalog(conn: sqlite3.Connection, search: str='', sort: str='title', descending: bool=False) -> list[dict[str, Any]]:
    columns = {'title': 'b.title', 'author': 'b.author', 'year': 'b.year', 'available': 'available', 'id': 'b.id'}
    if sort not in columns:
        raise ValueError('unsupported sort field')
    direction = 'DESC' if descending else 'ASC'
    sql = '\n        SELECT b.id, b.title, b.author, b.year,\n               CASE WHEN EXISTS (\n                   SELECT 1 FROM loans la WHERE la.book_id = b.id AND la.returned_on IS NULL\n               ) THEN 0 ELSE 1 END AS available\n        FROM books b\n    '
    args: list[Any] = []
    if search:
        sql += ' WHERE lower(b.title) LIKE lower(?) OR lower(b.author) LIKE lower(?)'
        pattern = '%' + search + '%'
        args.extend([pattern, pattern])
    sql += f' ORDER BY {columns[sort]} {direction}, b.id ASC'
    rows = conn.execute(sql, args).fetchall()
    return [{'id': r[0], 'title': r[1], 'author': r[2], 'year': r[3], 'available': bool(r[4])} for r in rows]

def checkout(conn: sqlite3.Connection, book_id: int, patron: str, loaned_on: str) -> int:
    try:
        date.fromisoformat(loaned_on)
    except (TypeError, ValueError):
        raise ValueError('invalid loan date')
