import os
import tempfile

def export_leaderboard(rounds: list[dict[str, object]], destination: str, page: int=1, page_size: int=20) -> list[dict[str, object]]:
    if page < 1 or page_size < 1:
        raise ValueError('page values must be positive')
    totals = {}
    for item in rounds:
        if not isinstance(item, dict) or not all((key in item for key in ('player', 'strokes', 'par'))):
            raise ValueError('invalid round')
        player = item['player']
        strokes = item['strokes']
        par = item['par']
        if not isinstance(player, str) or not player or (not isinstance(strokes, list)) or (not isinstance(par, list)) or (not strokes) or (len(strokes) != len(par)):
            raise ValueError('invalid round')
        if any((isinstance(value, bool) or not isinstance(value, int) or value <= 0 for value in strokes + par)):
            raise ValueError('invalid score')
        if player not in totals:
            totals[player] = [0, 0]
        totals[player][0] += sum(strokes)
        totals[player][1] += sum(par)
    ordered = sorted(totals.items(), key=lambda pair: (pair[1][0], pair[0]))
    leaderboard = []
    previous = None
    for index, (player, values) in enumerate(ordered, 1):
        rank = index if previous != values[0] else leaderboard[-1]['rank']
        leaderboard.append({'rank': rank, 'player': player, 'strokes': values[0], 'to_par': values[0] - values[1]})
        previous = values[0]
    start = (page - 1) * page_size
    selected = leaderboard[start:start + page_size]
    directory = os.path.dirname(os.path.abspath(destination)) or '.'
    fd, temporary = tempfile.mkstemp(prefix='leaderboard-', suffix='.csv', dir=directory)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['Rank', 'Player', 'Strokes', 'To Par'])
            for row in selected:
                writer.writerow([row['rank'], row['player'], row['strokes'], row['to_par']])
        os.replace(temporary, destination)
    except BaseException:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return selected

