import os
import requests

def score_leads(leads: list[dict], config: dict | None=None) -> list[dict]:
    config = config or {}
    page = config.get('page')
    page_size = config.get('page_size')
    if (page is not None or page_size is not None) and (not isinstance(page, int) or isinstance(page, bool) or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (page < 1) or (page_size < 1)):
        raise ValueError('invalid pagination')
    token = config.get('api_token')
    if token is None:
        token = os.environ.get('SALES_SCORING_TOKEN')
    if not token:
        raise ValueError('missing SALES_SCORING_TOKEN')
    ids = [lead.get('id') for lead in leads]
    if any(('id' not in lead for lead in leads)) or len({str(x) for x in ids}) != len(ids):
        raise ValueError('invalid lead')
    response = requests.post(config.get('url', 'https://scoring.example.test/v1/score'), json={'leads': leads}, headers={'Authorization': 'Bearer ' + token, 'Content-Type': 'application/json'}, timeout=5)
    response.raise_for_status()
    payload = response.json()
    if not isinstance(payload, dict) or not isinstance(payload.get('scores'), list):
        raise ValueError('invalid scoring response')
    scores = {}
    for entry in payload['scores']:
        if not isinstance(entry, dict) or 'id' not in entry or (not isinstance(entry.get('score'), (int, float))) or isinstance(entry.get('score'), bool):
            raise ValueError('invalid scoring response')
        scores[entry['id']] = round(entry['score'], 2)
    if any((lead['id'] not in scores for lead in leads)):
        raise ValueError('missing lead score')
    result = []
    for lead in leads:
        score = scores[lead['id']]
        if 'min_score' in config and score < config['min_score']:
            continue
        item = dict(lead)
        item['score'] = score
        item['tier'] = 'hot' if score >= 80 else 'warm' if score >= 50 else 'cold'
        result.append(item)
    result.sort(key=lambda item: (-item['score'], str(item['id'])))
    if page is not None:
        start = (page - 1) * page_size
        result = result[start:start + page_size]
    return result

