import hashlib
import hmac
import os

def parse_manifest(text: str) -> list[dict]:
    if not isinstance(text, str):
        raise ValueError('manifest')
    result = []
    for line in text.splitlines():
        if not line.strip():
            continue
        fields = []
        current = []
        escaped = False
        for ch in line:
            if escaped:
                current.append(ch)
                escaped = False
            elif ch == '\\':
                escaped = True
            elif ch == '|':
                fields.append(''.join(current))
                current = []
            else:
                current.append(ch)
        if escaped:
            raise ValueError('escape')
        fields.append(''.join(current))
        if len(fields) != 5 or not fields[0] or (not fields[1]):
            raise ValueError('fields')
        try:
            weight = float(fields[2])
            priority = int(fields[3])
            pieces = int(fields[4])
        except (TypeError, ValueError):
            raise ValueError('number')
        if weight <= 0 or priority < 0 or priority > 9 or (pieces <= 0):
            raise ValueError('range')
        result.append({'awb': fields[0], 'flight': fields[1], 'weight_kg': weight, 'priority': priority, 'pieces': pieces})
    return result

def plan_load(records: list[dict], capacity_kg: float) -> dict:
    if capacity_kg < 0:
        raise ValueError('capacity')
    checked = []
    for r in records:
        if any((k not in r for k in ('awb', 'flight', 'weight_kg', 'priority'))) or r['weight_kg'] <= 0:
            raise ValueError('record')
        checked.append(r)
    ordered = sorted(checked, key=lambda r: (-r['priority'], r['weight_kg'], r['awb'], r['flight']))
    selected = []
    total = 0.0
    for r in ordered:
        if r['weight_kg'] <= capacity_kg - total:
            selected.append(r['awb'])
            total += r['weight_kg']
    return {'selected': selected, 'total_weight': round(total, 2), 'remaining_capacity': round(capacity_kg - total, 2)}

def create_booking(awb: str, pin: str, manifest: str, capacity_kg: float) -> dict:
    if not isinstance(pin, str) or not pin:
        raise ValueError('pin')
    rows = parse_manifest(manifest)
    matches = [r for r in rows if r['awb'].lower() == awb.lower()]
    if len(matches) != 1:
        raise ValueError('awb')
    row = matches[0]
    plan = plan_load(rows, capacity_kg)
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    stored = '1$' + base64.b64encode(salt).decode() + '$' + base64.b64encode(digest).decode()
    return {'awb': row['awb'], 'flight': row['flight'], 'pieces': row['pieces'], 'selected': plan['selected'], 'total_weight': plan['total_weight'], 'pin': stored}

def verify_booking(booking: dict, pin: str) -> bool:
    if not isinstance(pin, str) or not isinstance(booking, dict) or (not isinstance(booking.get('pin'), str)):
        return False
    try:
        version, salt_text, digest_text = booking['pin'].split('$')
        if version != '1':
            return False
        salt = base64.b64decode(salt_text, validate=True)
        expected = base64.b64decode(digest_text, validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except Exception:
        return False

