import tempfile

def write_tag_report(records: list[dict], destination: str, page: int=1, page_size: int=50) -> int:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError('invalid pagination')
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        if not isinstance(record.get('id'), str) or not record['id']:
            raise ValueError('invalid record')
        if not isinstance(record.get('tag'), str) or not record['tag']:
            raise ValueError('invalid record')
        if isinstance(record.get('pages'), bool) or not isinstance(record.get('pages'), int) or record['pages'] < 0:
            raise ValueError('invalid record')
        tag = record['tag']
        groups.setdefault(tag, {'count': 0, 'pages': 0, 'ids': []})
        groups[tag]['count'] += 1
        groups[tag]['pages'] += record['pages']
        groups[tag]['ids'].append(record['id'])
    ordered = sorted(groups.items(), key=lambda item: (-item[1]['pages'], item[0]))
    start = (page - 1) * page_size
    selected = ordered[start:start + page_size]
    parent = os.path.dirname(os.path.abspath(destination))
    descriptor, temporary = tempfile.mkstemp(dir=parent)
    try:
        with os.fdopen(descriptor, 'w', encoding='utf-8', newline='') as handle:
            writer = csv.writer(handle)
            writer.writerow(['tag', 'document_count', 'total_pages', 'document_ids'])
            for tag, values in selected:
                writer.writerow([tag, values['count'], values['pages'], ';'.join(sorted(values['ids']))])
        os.replace(temporary, destination)
        temporary = None
    finally:
        if temporary is not None:
            try:
                os.unlink(temporary)
            except FileNotFoundError:
                pass
    return len(selected)

