    except (etree.XMLSyntaxError, UnicodeError) as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'transcript':
        raise ValueError('invalid root')
    required = ('student_id', 'name')
    if any((name not in root.attrib for name in required)):
        raise ValueError('missing transcript attribute')
