        raise ValueError('student mismatch')
    points = {'A': 4.0, 'A-': 3.7, 'B+': 3.3, 'B': 3.0, 'B-': 2.7, 'C+': 2.3, 'C': 2.0, 'C-': 1.7, 'D': 1.0, 'F': 0.0, 'W': 0.0}
    courses = []
    total_credits = 0
    total_points = 0.0
    for node in root:
        if node.tag != 'course':
            continue
        names = ('code', 'title', 'term', 'credits', 'grade')
        if any((name not in node.attrib for name in names)):
            raise ValueError('missing course attribute')
        try:
            credits = int(node.get('credits'))
        except (TypeError, ValueError) as exc:
            raise ValueError('invalid credits') from exc
        grade = node.get('grade')
        if credits <= 0 or grade not in points:
            raise ValueError('invalid course')
