import re
import xml.etree.ElementTree as ET

def parse_license_report(document: str) -> list[dict]:
    if not isinstance(document, str) or not document.strip():
        raise ValueError('invalid XML')
    try:
        root = ET.fromstring(document)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'report':
        raise ValueError('invalid root')
    result = []
    seen = set()
    for node in root:
        if node.tag != 'component' or (node.tail and node.tail.strip()):
            raise ValueError('invalid component')

        def attr(name):
            value = node.attrib.get(name, '').strip()
            if not value:
                raise ValueError('missing attribute')
            return value
        name, version, license_name = (attr('name'), attr('version'), attr('license'))
        if name in seen:
            raise ValueError('duplicate component')
        seen.add(name)
        deps, dep_seen = ([], set())
        if node.text and node.text.strip():
            raise ValueError('unexpected text')
        for child in node:
            if child.tag != 'dependency' or (child.tail and child.tail.strip()) or list(child):
                raise ValueError('invalid dependency')
            dn, dv = (child.attrib.get('name', '').strip(), child.attrib.get('version', '').strip())
            if not dn or not dv or dn in dep_seen:
                raise ValueError('invalid dependency')
            dep_seen.add(dn)
            deps.append({'name': dn, 'version': dv})
            if child.text and child.text.strip():
                raise ValueError('unexpected text')
        result.append({'name': name, 'version': version, 'license': license_name, 'dependencies': deps})
    if not result:
        raise ValueError('no components')
    return result

def _version(value):
    if not isinstance(value, str) or not re.fullmatch('(?:0|[1-9][0-9]*)(?:\\.(?:0|[1-9][0-9]*))*', value):
        raise ValueError('invalid version')
    return tuple((int(x) for x in value.split('.')))

def summarize_compliance(components: list[dict], approved_licenses: set[str], minimum_versions: dict[str, str]) -> dict:
    rows = []
    names = set()
    for item in components:
        if not isinstance(item, dict) or set(item) != {'name', 'version', 'license', 'dependencies'}:
            raise ValueError('invalid component')
        name, version, license_name, deps = item.values()
        if not all((isinstance(x, str) and x for x in (name, version, license_name))) or not isinstance(deps, list) or name in names:
            raise ValueError('invalid component')
        names.add(name)
        current = _version(version)
        dep_names = set()
        for dep in deps:
            if not isinstance(dep, dict) or set(dep) != {'name', 'version'} or (not isinstance(dep['name'], str)) or (not dep['name']) or (dep['name'] in dep_names):
                raise ValueError('invalid dependency')
            dep_names.add(dep['name'])
            _version(dep['version'])
        minimum = _version(minimum_versions[name]) if name in minimum_versions else None
        ok = license_name in approved_licenses and (minimum is None or current >= minimum)
        rows.append({'name': name, 'version': version, 'license': license_name, 'status': 'compliant' if ok else 'noncompliant', 'dependency_count': len(deps), '_v': current})
    rows.sort(key=lambda x: (x['name'], tuple((-n for n in x['_v'])), x['license']))
    output = [{k: row[k] for k in ('name', 'version', 'status', 'dependency_count')} for row in rows]
    compliant = sum((x['status'] == 'compliant' for x in output))
    return {'total': len(output), 'compliant': compliant, 'noncompliant': len(output) - compliant, 'dependencies': sum((x['dependency_count'] for x in output)), 'components': output}

