import csv
import io
import os
import re
import zipfile
from datetime import date
from decimal import Decimal, InvalidOperation
from pathlib import Path

def parse_ledger(text: str) -> list[dict]:
    reader = csv.reader(io.StringIO(text))
    try:
        header = next(reader)
    except StopIteration:
        raise ValueError('empty ledger')
    if header != ['date', 'client', 'category', 'amount']:
        raise ValueError('invalid header')
    result = []
    for row in reader:
        if len(row) != 4:
            raise ValueError('invalid row')
        day, client, category, amount_text = [x.strip() for x in row]
        if not client or not category or (not re.fullmatch('[+-]?\\d+\\.\\d{2}', amount_text)):
            raise ValueError('invalid field')
        try:
            date.fromisoformat(day)
            amount = Decimal(amount_text)
        except (ValueError, InvalidOperation):
            raise ValueError('invalid value')
        if amount == 0:
            raise ValueError('zero amount')
        result.append({'date': day, 'client': client, 'category': category, 'amount': amount})
    return result

def monthly_category_totals(rows: list[dict], client: str) -> list[tuple[str, str, Decimal]]:
    totals = {}
    for row in rows:
        if row['client'] == client:
            key = (row['date'][:7], row['category'])
            totals[key] = totals.get(key, Decimal('0')) + row['amount']
    return [(month, category, totals[month, category]) for month, category in sorted(totals)]

def extract_documents(base_dir: str, archive_path: str) -> list[str]:
    base = Path(base_dir).resolve()
    base.mkdir(parents=True, exist_ok=True)
    extracted = []
    with zipfile.ZipFile(archive_path) as archive:
        for info in archive.infolist():
            name = info.filename
            if not name or name.endswith('/'):
                continue
            target = (base / Path(name)).resolve()
            try:
                target.relative_to(base)
            except ValueError:
                raise ValueError('member outside base directory')
            target.parent.mkdir(parents=True, exist_ok=True)
            with archive.open(info) as source, open(target, 'wb') as destination:
                destination.write(source.read())
            extracted.append(Path(name).as_posix())
    return sorted(extracted)

