import ast
import operator

def evaluate_expression(expression: str, variables: dict[str, int | float]):
    try:
        tree = ast.parse(expression, mode='eval').body

        def run(node):
            if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, complex)):
                return node.value
            if isinstance(node, ast.Name):
                if node.id not in variables:
                    raise ValueError()
                return variables[node.id]
            if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
                value = run(node.operand)
                return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
            if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
                a, b = (run(node.left), run(node.right))
                return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](a, b)
            if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
                value = run(node.values[0])
                for item in node.values[1:]:
                    if isinstance(node.op, ast.And) and (not value):
                        return value
                    if isinstance(node.op, ast.Or) and value:
                        return value
                    value = run(item)
                return value
            if isinstance(node, ast.Compare) and len(node.ops) == len(node.comparators):
                left = run(node.left)
                for op, right_node in zip(node.ops, node.comparators):
                    right = run(right_node)
                    good = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}[type(op)](left, right)
                    if not good:
                        return False
                    left = right
                return True
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
                args = [run(x) for x in node.args]
                if node.func.id == 'round' and len(args) in (1, 2):
                    return round(*args)
                if node.func.id in ('min', 'max') and len(args) >= 2:
                    return min(args) if node.func.id == 'min' else max(args)
            raise ValueError()
        return run(tree)
    except Exception as exc:
        if isinstance(exc, ValueError):
            raise
        raise ValueError() from exc

def plan_interviews(candidates, slots, panel_size, eligibility_expression, score_expression):
    if panel_size < 1:
        raise ValueError()
    names = set()
    for c in candidates:
        if not isinstance(c.get('name'), str) or c['name'] in names:
            raise ValueError()
        names.add(c['name'])
    used, result = (set(), [])
    for slot in slots:
        available = []
        for c in candidates:
            if c['name'] in used or slot not in c.get('availability', []):
                continue
            values = {k: c[k] for k in ('rating', 'years', 'communication', 'technical')}
            if evaluate_expression(eligibility_expression, values):
                score = evaluate_expression(score_expression, values)
                available.append((score, c['name']))
        if len(available) < panel_size:
            continue
        available.sort(key=lambda x: (-x[0], x[1]))
        chosen = available[:panel_size]
        used.update((x[1] for x in chosen))
        result.append({'slot': slot, 'candidates': [x[1] for x in chosen], 'scores': [x[0] for x in chosen]})
    return result

