import hashlib
import hmac
import json

from solution import verify_order_webhook


def make_payload(status="paid", order_id="ORD-100"):
    return json.dumps({"event": "order.updated", "order_id": order_id, "status": status}, separators=(",", ":"))


def make_headers(payload, secret):
    digest = hmac.new(secret.encode("utf-8"), payload.encode("utf-8"), hashlib.sha256).hexdigest()
    return {"X-Market-Signature": "sha256=" + digest}


def test_accepts_valid_webhook():
    payload = make_payload("paid", "ORD-42")
    assert verify_order_webhook(payload, make_headers(payload, "vendor-key"), "vendor-key") is True


def test_rejects_wrong_signature():
    payload = make_payload()
    headers = {"X-Market-Signature": "sha256=" + "0" * 64}
    assert verify_order_webhook(payload, headers, "vendor-key") is False


def test_rejects_missing_signature_header():
    payload = make_payload()
    assert verify_order_webhook(payload, {}, "vendor-key") is False


def test_rejects_malformed_signature_headers():
    payload = make_payload()
    for value in ["", "sha256", "sha1=" + "a" * 64, "sha256=" + "a" * 63, "sha256=" + "g" * 64]:
        assert verify_order_webhook(payload, {"X-Market-Signature": value}, "vendor-key") is False


def test_rejects_invalid_json():
    payload = "not json"
    assert verify_order_webhook(payload, make_headers(payload, "vendor-key"), "vendor-key") is False


def test_rejects_wrong_payload_shape():
    cases = [
        {"event": "order.created", "order_id": "ORD-1", "status": "paid"},
        {"event": "order.updated", "order_id": "ORD-1", "status": "refunded"},
        {"event": "order.updated", "order_id": "", "status": "paid"},
        {"event": "order.updated", "order_id": 123, "status": "paid"},
        ["order.updated", "ORD-1", "paid"],
    ]
    for value in cases:
        payload = json.dumps(value, separators=(",", ":"))
        assert verify_order_webhook(payload, make_headers(payload, "vendor-key"), "vendor-key") is False


def test_accepts_each_supported_status():
    for status in ["pending", "paid", "shipped", "cancelled"]:
        payload = make_payload(status, "ORD-9")
        assert verify_order_webhook(payload, make_headers(payload, "vendor-key"), "vendor-key") is True


def test_signature_covers_exact_payload_text():
    payload = '{"event":"order.updated","order_id":"ORD-7","status":"paid"}'
    altered = '{ "event":"order.updated","order_id":"ORD-7","status":"paid" }'
    headers = make_headers(payload, "vendor-key")
    assert verify_order_webhook(payload, headers, "vendor-key") is True
    assert verify_order_webhook(altered, headers, "vendor-key") is False


def test_rejects_non_string_inputs():
    payload = make_payload()
    headers = make_headers(payload, "vendor-key")
    assert verify_order_webhook(None, headers, "vendor-key") is False
    assert verify_order_webhook(payload, None, "vendor-key") is False
    assert verify_order_webhook(payload, {"X-Market-Signature": None}, "vendor-key") is False
    assert verify_order_webhook(payload, headers, None) is False

