import hashlib
import hmac
import json
from typing import Mapping

def verify_order_webhook(payload: str, headers: Mapping[str, str], secret: str) -> bool:
    if not isinstance(payload, str) or not isinstance(headers, Mapping) or (not isinstance(secret, str)):
        return False
    signature = headers.get('X-Market-Signature')
    if not isinstance(signature, str) or not signature.startswith('sha256='):
        return False
    supplied = signature[7:]
