    encoded = 'pbkdf2$100000$' + base64.b64encode(salt).decode() + '$' + base64.b64encode(digest).decode()
    return {'id': technician_id, 'name': name, 'skills': sorted(set(skills)), 'password_hash': encoded}

def verify_technician(record: dict, password: str) -> bool:
