        raise TypeError()
    try:
        start, finish = (date.fromisoformat(start_date), date.fromisoformat(end_date))
    except ValueError:
        raise ValueError()
    if start > finish:
        raise ValueError()
    ids = set()
    for t in technicians:
        if not isinstance(t, dict) or not isinstance(t.get('id'), str) or (not t['id']) or (t['id'] in ids) or (not isinstance(t.get('regions'), list)) or (not t['regions']) or any((not isinstance(x, str) for x in t['regions'])) or (not isinstance(t.get('skills'), list)) or (not t['skills']) or any((not isinstance(x, str) for x in t['skills'])) or (not isinstance(t.get('daily_minutes'), int)) or isinstance(t['daily_minutes'], bool) or (t['daily_minutes'] <= 0):
            raise ValueError()
        ids.add(t['id'])
    normalized, seen = ([], set())
    for j in jobs:
        if not isinstance(j, dict) or not isinstance(j.get('id'), str) or (not j['id']) or (j['id'] in seen):
            raise ValueError()
        if any((not isinstance(j.get(k), str) or not j[k] for k in ('region', 'skill', 'due'))):
            raise ValueError()
        if not isinstance(j.get('minutes'), int) or isinstance(j['minutes'], bool) or j['minutes'] <= 0:
            raise ValueError()
        try:
            due = date.fromisoformat(j['due'])
        except ValueError:
            raise ValueError()
        if due < start:
            raise ValueError()
        priority = j.get('priority', 0)
        normalized.append((-(priority if isinstance(priority, int) else 0), due, j['id'], j))
        seen.add(j['id'])
    loads, output = ({}, [])
    for _, due, _, j in sorted(normalized):
        placed = None
        day = start
        while day <= min(due, finish) and placed is None:
            if day.weekday() < 5:
                candidates = [t for t in technicians if j['region'] in t['regions'] and j['skill'] in t['skills'] and (loads.get((t['id'], day), 0) + j['minutes'] <= t['daily_minutes'])]
                if candidates:
                    t = min(candidates, key=lambda x: (loads.get((x['id'], day), 0), x['id']))
                    loads[t['id'], day] = loads.get((t['id'], day), 0) + j['minutes']
                    placed = {'job_id': j['id'], 'technician_id': t['id'], 'date': day.isoformat(), 'minutes': j['minutes']}
            day += timedelta(days=1)
        if placed is None:
            raise ValueError()
        output.append(placed)
    return sorted(output, key=lambda x: (x['date'], x['technician_id'], x['job_id']))

