import csv
import io
import re
import secrets
from datetime import date
from decimal import Decimal, InvalidOperation
_EVENTS = {'submitted', 'payment', 'decision'}
_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'

def _cents(value):
    if value == '':
        raise ValueError('amount')
    try:
        d = Decimal(value)
    except InvalidOperation:
        raise ValueError('amount')
    if not d.is_finite() or d < 0 or d.as_tuple().exponent < -2:
        raise ValueError('amount')
    return int(d * 100)

def parse_loan_events(text: str) -> list[dict]:
    rows = list(csv.reader(io.StringIO(text)))
    rows = [r for r in rows if any((x.strip() for x in r))]
    if not rows or len(rows[0]) != 4 or [x.strip() for x in rows[0]] != ['application_id', 'event', 'occurred_at', 'amount']:
        raise ValueError('header')
    result = []
    for row in rows[1:]:
        if len(row) != 4:
            raise ValueError('row')
        ident, event, when, amount = [x.strip() for x in row]
        if not ident or event not in _EVENTS:
            raise ValueError('fields')
        try:
            day = date.fromisoformat(when)
        except ValueError:
            raise ValueError('date')
        result.append({'application_id': ident, 'event': event, 'occurred_at': day, 'amount': _cents(amount)})
    return result

def summarize_applications(events: list[dict]) -> list[dict]:
    groups = {}
    for item in events:
        if not isinstance(item, dict) or set(item) != {'application_id', 'event', 'occurred_at', 'amount'}:
            raise ValueError('event')
        ident = item['application_id']
        if not isinstance(ident, str) or not ident or item['event'] not in _EVENTS:
            raise ValueError('event')
        if not isinstance(item['occurred_at'], date) or isinstance(item['occurred_at'], __import__('datetime').datetime):
            raise ValueError('date')
        if not isinstance(item['amount'], int) or isinstance(item['amount'], bool) or item['amount'] < 0:
            raise ValueError('amount')
        groups.setdefault(ident, []).append(item)
    result = []
    for ident, items in groups.items():
        latest = max(enumerate(items), key=lambda p: (p[1]['occurred_at'], p[0]))[1]
        result.append({'application_id': ident, 'latest_event': latest['event'], 'latest_date': latest['occurred_at'], 'total_payments': sum((x['amount'] for x in items if x['event'] == 'payment'))})
    return sorted(result, key=lambda x: (-x['latest_date'].toordinal(), x['application_id']))

def generate_invite_code(application_id: str, length: int=12) -> str:
    if not isinstance(application_id, str) or not application_id or (not re.fullmatch('[A-Za-z0-9_-]+', application_id)):
        raise ValueError('application_id')
    if isinstance(length, bool) or not isinstance(length, int) or (not 8 <= length <= 64):
        raise ValueError('length')
    return application_id + '-' + ''.join((secrets.choice(_ALPHABET) for _ in range(length)))

