import json
import os

def build_review_report(base_dir: str, relative_names: list[str], page: int=1, page_size: int=10) -> dict:
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    base = os.path.realpath(base_dir)
    records = []
    seen = set()
    for name in relative_names:
        candidate = os.path.realpath(os.path.join(base, name))
        if os.path.commonpath([base, candidate]) != base:
            raise ValueError('invalid document path')
        try:
            with open(candidate, encoding='utf-8') as handle:
                item = json.load(handle)
        except Exception as exc:
            raise ValueError('invalid document') from exc
        if not isinstance(item, dict):
            raise ValueError('invalid document')
        doc_id = item.get('doc_id')
        custodian = item.get('custodian')
        pages = item.get('pages')
        responsive = item.get('responsive')
        codes = item.get('issue_codes')
        if not isinstance(doc_id, str) or not doc_id or (not isinstance(custodian, str)) or (not isinstance(pages, int)) or isinstance(pages, bool) or (pages < 0) or (not isinstance(responsive, bool)) or (not isinstance(codes, list)) or any((not isinstance(code, str) for code in codes)) or (doc_id in seen):
            raise ValueError('invalid document')
        seen.add(doc_id)
        records.append({'doc_id': doc_id, 'custodian': custodian, 'pages': pages, 'responsive': responsive, 'issue_codes': sorted(set(codes))})
    records.sort(key=lambda item: (not item['responsive'], -item['pages'], item['doc_id']))
    groups = {}
    responsive_pages = 0
    for item in records:
        group = groups.setdefault(item['custodian'], {'name': item['custodian'], 'documents': 0, 'pages': 0})
        group['documents'] += 1
        group['pages'] += item['pages']
        if item['responsive']:
            responsive_pages += item['pages']
    start = (page - 1) * page_size
    return {'total': len(records), 'responsive_pages': responsive_pages, 'custodians': [groups[key] for key in sorted(groups)], 'documents': records[start:start + page_size]}

import csv
import io
from datetime import date, timedelta

def _date(value):
    try:
        d = date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if d.isoformat() != value:
        raise ValueError('invalid date')
    return d

def build_training_report(requester: dict, employees: list[dict], courses: list[dict], completions: list[dict], employee_id: str, as_of: str) -> dict:
    today = _date(as_of)
    em = {}
    for e in employees:
        if e['id'] in em:
            raise ValueError('duplicate employee')
        em[e['id']] = e
    if employee_id not in em:
        raise KeyError(employee_id)
    target = em[employee_id]
    if requester.get('tenant_id') != target['tenant_id'] and 'compliance_admin' not in requester.get('roles', []):
        raise PermissionError('not permitted')
    if requester.get('id') != employee_id and 'compliance_admin' not in requester.get('roles', []):
        raise PermissionError('not permitted')
    cm = {}
    for c in courses:
        if c['validity_days'] < 0:
            raise ValueError('negative validity')
        key = (c['tenant_id'], c['id'])
        if key in cm:
            raise ValueError('duplicate course')
        cm[key] = c
    for x in completions:
        if x['employee_id'] not in em or (x['tenant_id'], x['course_id']) not in cm:
            raise ValueError('unknown reference')
        _date(x['completed_on'])
    latest = {}
    for x in completions:
        c = cm[x['tenant_id'], x['course_id']]
        if x['tenant_id'] != target['tenant_id'] or x['employee_id'] != employee_id or c['tenant_id'] != target['tenant_id']:
            continue
        d = _date(x['completed_on'])
        if d <= today and (x['course_id'] not in latest or d > latest[x['course_id']]):
            latest[x['course_id']] = d
    items = []
    for c in cm.values():
        if c['tenant_id'] != target['tenant_id']:
            continue
        d = latest.get(c['id'])
        expiry = d + timedelta(days=c['validity_days']) if d else None
        status = 'never' if d is None else 'compliant' if today <= expiry else 'overdue'
        items.append({'course_id': c['id'], 'title': c['title'], 'status': status, 'completed_on': d.isoformat() if d else None, 'expires_on': expiry.isoformat() if expiry else None})
    items.sort(key=lambda x: (x['title'].casefold(), x['course_id']))
    good = sum((x['status'] == 'compliant' for x in items))
    return {'employee_id': employee_id, 'employee_name': target['display_name'], 'as_of': as_of, 'required_count': len(items), 'compliant_count': good, 'compliance_percent': round(100 * good / len(items), 2) if items else 100.0, 'items': items}

def render_training_report(report: dict) -> str:
    out = io.StringIO(newline='')
    w = csv.writer(out, lineterminator='\r\n')
    w.writerow(['employee_id', 'employee_name', 'as_of', 'required_count', 'compliant_count', 'compliance_percent'])
    w.writerow([report[k] for k in ['employee_id', 'employee_name', 'as_of', 'required_count', 'compliant_count', 'compliance_percent']])
    for x in report['items']:
        w.writerow([x[k] for k in ['course_id', 'title', 'status', 'completed_on', 'expires_on']])
    return out.getvalue()

