def parse_training_xml(xml_text: str) -> list[dict]:
    try:
        root = ET.fromstring(xml_text)
    except Exception as exc:
        raise ValueError from exc
    if root.tag != 'training':
        raise ValueError
    result = []
    seen = set()
    for emp in root:
        if emp.tag != 'employee' or set(emp.attrib) != {'id', 'name'}:
            raise ValueError
        eid, name = (emp.attrib['id'].strip(), emp.attrib['name'].strip())
        if not eid or not name:
            raise ValueError
        for item in emp:
            if item.tag != 'completion' or item:
                raise ValueError
            if set(item.attrib) != {'course', 'date', 'score', 'hours'}:
                raise ValueError
            course = item.attrib['course'].strip()
            if not course:
                raise ValueError
            d = item.attrib['date']
            _day(d)
            try:
                score, hours = (float(item.attrib['score']), float(item.attrib['hours']))
            except Exception as exc:
                raise ValueError from exc
            if not 0 <= score <= 100 or hours <= 0:
                raise ValueError
            key = (eid, course, d)
            if key in seen:
                raise ValueError
            seen.add(key)
            result.append({'employee_id': eid, 'name': name, 'course': course, 'date': d, 'score': score, 'hours': hours})
    return result

def compliance_report(records: list[dict], as_of: str) -> list[dict]:
    end = _day(as_of)
    start = end - timedelta(days=89)
    employees = {}
    for r in records:
        try:
            d = _day(r['date'])
            score, hours = (float(r['score']), float(r['hours']))
            eid, course, name = (str(r['employee_id']), str(r['course']), str(r['name']))
        except Exception as exc:
            raise ValueError from exc
        if not 0 <= score <= 100 or hours <= 0:
            raise ValueError
        employees.setdefault(eid, {'name': name, 'courses': {}})['name'] = name
        old = employees[eid]['courses'].get(course)
        if d <= end and (old is None or d >= old[0]):
            employees[eid]['courses'][course] = (d, hours)
    out = []
    for eid, data in employees.items():
        chosen = [v for v in data['courses'].values() if start <= v[0] <= end]
        total = round(sum((v[1] for v in chosen)), 2)
