import csv
import math
import os
import tempfile

def parse_inventory(text: str) -> list[dict]:
    rows = list(csv.reader(text.splitlines()))
    if not rows or rows[0] != ['silo', 'grain', 'tons', 'moisture']:
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if len(row) != 4:
            raise ValueError('invalid row')
        silo, grain, tons_text, moisture_text = (x.strip() for x in row)
        if not silo or not grain:
            raise ValueError('empty field')
        try:
            tons = float(tons_text)
            moisture = float(moisture_text)
        except ValueError as exc:
            raise ValueError('invalid number') from exc
        if not math.isfinite(tons) or not math.isfinite(moisture):
            raise ValueError('non-finite number')
        if tons < 0 or not 0 <= moisture <= 100:
            raise ValueError('out of range')
        result.append({'silo': silo, 'grain': grain, 'tons': tons, 'moisture': moisture})
    return result

def summarize_inventory(records: list[dict]) -> list[dict]:
    groups = {}
    for record in records:
        silo = record['silo']
        item = groups.setdefault(silo, [0.0, 0.0])
        item[0] += record['tons']
        item[1] += record['tons'] * record['moisture']
    result = []
    for silo, (total, weighted) in groups.items():
        result.append({'silo': silo, 'total_tons': total, 'average_moisture': weighted / total if total else 0.0})
    return sorted(result, key=lambda x: (-x['total_tons'], x['silo']))

def export_report(records: list[dict], destination: str) -> list[dict]:
    summary = summarize_inventory(records)
    fd, temporary = tempfile.mkstemp(prefix='.inventory-', dir=os.path.dirname(destination) or '.')
    try:
        with os.fdopen(fd, 'w', newline='') as stream:
            writer = csv.writer(stream, lineterminator='\n')
            writer.writerow(['silo', 'total_tons', 'average_moisture'])
            for row in summary:
                writer.writerow([row['silo'], f"{row['total_tons']:.2f}", f"{row['average_moisture']:.2f}"])
