from lxml import etree
from datetime import datetime
import re

def _read(xml_text):
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        return etree.fromstring(xml_text.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc

def parse_evidence(xml_text: str) -> dict:
    root = _read(xml_text)
    if root.tag != 'case' or not root.get('id', '').strip():
        raise ValueError('invalid case')
    evidence = [x for x in root if x.tag == 'evidence']
    if len(evidence) != 1:
        raise ValueError('invalid evidence')
    exhibits = []
    exhibit_ids = set()
    record_ids = set()
    for ex in evidence[0]:
        if ex.tag != 'exhibit':
            continue
        eid = ex.get('id', '')
        typ = ex.get('type', '')
        if not eid or eid in exhibit_ids or (not typ):
            raise ValueError('invalid exhibit')
        try:
            priority = int(ex.get('priority', ''))
        except Exception as exc:
            raise ValueError('invalid priority') from exc
        if not 0 <= priority <= 9:
            raise ValueError('invalid priority')
        exhibit_ids.add(eid)
        for rec in ex:
            if rec.tag != 'record':
                continue
            rid = rec.get('id', '')
            collector = rec.get('collector', '')
            kind = rec.get('kind', '')
            stamp = rec.get('at', '')
            if not rid or rid in record_ids or (not collector) or (not kind):
                raise ValueError('invalid record')
            try:
                datetime.strptime(stamp, '%Y-%m-%dT%H:%M:%SZ')
            except Exception as exc:
                raise ValueError('invalid timestamp') from exc
            text = ''.join(rec.itertext())
            text = re.sub('\\s+', ' ', text).strip()
            if not text:
                raise ValueError('empty text')
            record_ids.add(rid)
            exhibits.append({'id': rid, 'exhibit': eid, 'type': typ, 'priority': priority, 'timestamp': stamp, 'collector': collector, 'kind': kind, 'text': text})
    exhibits.sort(key=lambda x: (x['timestamp'], -x['priority'], x['exhibit'], x['id']))
    return {'case_id': root.get('id'), 'events': exhibits}

def summarize_evidence(xml_text: str) -> dict:
    parsed = parse_evidence(xml_text)
    groups = {}
    for event in parsed['events']:
        group = groups.setdefault(event['collector'], {'collector': event['collector'], 'count': 0, 'total_priority': 0, 'first': event['timestamp'], 'last': event['timestamp'], 'kinds': set()})
        group['count'] += 1
        group['total_priority'] += event['priority']
        group['first'] = min(group['first'], event['timestamp'])
        group['last'] = max(group['last'], event['timestamp'])
        group['kinds'].add(event['kind'])
    result = []
    for name in sorted(groups):
        item = groups[name]
        item['kinds'] = sorted(item['kinds'])
        result.append(item)
    return {'case_id': parsed['case_id'], 'event_count': len(parsed['events']), 'by_collector': result}

