        raise ValueError()
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page <= 0) or (page_size <= 0):
        raise ValueError()
    if not all((key in requester for key in ('id', 'role', 'tenant_id'))):
        raise ValueError()
    allowed = requester['role'] == 'registrar' and requester['tenant_id'] == requester['tenant_id']
    allowed = allowed or (requester['role'] == 'student' and requester['id'] == student_id)
    if not allowed:
        raise PermissionError()
    rows = []
    for row in enrollments:
        if not isinstance(row, dict) or not all((key in row for key in ('student_id', 'course_code', 'term', 'score', 'credits', 'tenant_id'))):
            raise ValueError()
        try:
            score = float(row['score'])
            credits = float(row['credits'])
        except (TypeError, ValueError):
            raise ValueError()
        if row['course_code'] is None or score < 0 or score > 100 or (credits <= 0):
            raise ValueError()
        if row['student_id'] == student_id and row['term'] == term and (row['tenant_id'] == requester['tenant_id']):
            letter = 'A' if score >= 90 else 'B' if score >= 80 else 'C' if score >= 70 else 'D' if score >= 60 else 'F'
            rows.append({'course_code': row['course_code'], 'score': row['score'], 'credits': int(credits) if credits.is_integer() else credits, 'letter': letter, '_score': score, '_credits': credits})
