    total = sum((x['_credits'] for x in rows))
    average = None if not rows else float(Decimal(str(sum((x['_score'] * x['_credits'] for x in rows)) / total)).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
    start = (page - 1) * page_size
    courses = [{k: v for k, v in row.items() if not k.startswith('_')} for row in rows[start:start + page_size]]
    return {'student_id': student_id, 'term': term, 'courses': courses, 'total_courses': len(rows), 'total_credits': int(total) if total.is_integer() else total, 'average': average, 'page': page, 'page_size': page_size, 'total_pages': ceil(len(rows) / page_size) if rows else 0}

