import datetime

def prepare_visa_tracking_batch(applications: list[dict], config: dict) -> dict:
    if 'api_token' not in config or not isinstance(config['api_token'], str) or (not config['api_token']):
        raise ValueError('api_token is required')
    page_size = config.get('page_size', 50)
    if type(page_size) is not int or not 1 <= page_size <= 100:
        raise ValueError('page_size must be between 1 and 100')
    try:
        as_of = datetime.date.fromisoformat(config.get('as_of', datetime.date.today().isoformat()))
    except (TypeError, ValueError):
        raise ValueError('invalid as_of')
    statuses = ('pending', 'submitted', 'approved', 'rejected')
    seen = set()
    normalized = []
    for item in applications:
        if not isinstance(item, dict) or any((not isinstance(item.get(k), str) or not item[k] for k in ('application_id', 'country', 'submitted_at'))) or item.get('status') not in statuses:
            raise ValueError('invalid application')
        if item['application_id'] in seen:
            raise ValueError('duplicate application_id')
        try:
            submitted = datetime.date.fromisoformat(item['submitted_at'])
        except (TypeError, ValueError):
            raise ValueError('invalid application')
        if submitted > as_of:
            raise ValueError('submitted_at cannot be after as_of')
        age = (as_of - submitted).days
        normalized.append({'application_id': item['application_id'], 'country': item['country'], 'status': item['status'], 'submitted_at': item['submitted_at'], 'age_days': age, 'overdue': item['status'] != 'approved' and age > 30})
        seen.add(item['application_id'])
    normalized.sort(key=lambda x: (x['submitted_at'], x['application_id']))
    counts = {status: 0 for status in statuses}
    for item in normalized:
        counts[item['status']] += 1
    ids = [item['application_id'] for item in normalized]
    pages = [ids[i:i + page_size] for i in range(0, len(ids), page_size)]
    return {'headers': {'Authorization': 'Bearer ' + config['api_token'], 'Content-Type': 'application/json'}, 'applications': normalized, 'summary': {'total': len(normalized), 'by_status': counts, 'overdue': sum((item['overdue'] for item in normalized))}, 'pages': pages}

