import sqlite3

def get_client_report(conn: sqlite3.Connection, advisor_id: int, min_value: float=0.0, sort_by: str='client_id', descending: bool=False, page: int=1, page_size: int=20) -> list[dict]:
    if isinstance(advisor_id, bool) or not isinstance(advisor_id, int):
        raise ValueError('advisor_id must be an integer')
    if isinstance(min_value, bool) or not isinstance(min_value, (int, float)) or min_value < 0:
        raise ValueError('min_value must be non-negative and numeric')
    if sort_by not in {'client_id', 'name', 'total_value', 'position_count'}:
        raise ValueError('unsupported sort field')
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('page must be positive')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('page_size must be positive')
    if not isinstance(descending, bool):
        raise ValueError('descending must be boolean')
    columns = {'client_id': 'c.id', 'name': 'c.name', 'total_value': 'total_cents', 'position_count': 'position_count'}
    direction = 'DESC' if descending else 'ASC'
    offset = (page - 1) * page_size
    minimum_cents = round(min_value * 100)
    query = f'select c.id, c.name, coalesce(sum(p.market_value_cents), 0) as total_cents, count(p.id) as position_count from clients c left join positions p on p.client_id = c.id where c.advisor_id = ? group by c.id, c.name having coalesce(sum(p.market_value_cents), 0) >= ? order by {columns[sort_by]} {direction}, c.id asc limit ? offset ?'
    rows = conn.execute(query, (advisor_id, minimum_cents, page_size, offset)).fetchall()
    return [{'client_id': r[0], 'name': r[1], 'total_value': round(r[2] / 100, 2), 'position_count': r[3]} for r in rows]

