import math
import xml.etree.ElementTree as ET

def verify_resale_feed(xml_text: str, min_price: float, page: int, page_size: int) -> dict:
    if not isinstance(xml_text, str) or isinstance(min_price, bool) or (not isinstance(min_price, (int, float))) or (not math.isfinite(min_price)) or (min_price < 0):
        raise ValueError('invalid arguments')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid arguments')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid arguments')
    try:
        root = ET.fromstring(xml_text)
    except Exception as exc:
        raise ValueError('invalid xml') from exc
    if root.tag != 'tickets':
        raise ValueError('invalid root')
    matching = []
    for child in root:
        if child.tag != 'ticket':
            continue
        if any((name not in child.attrib for name in ('id', 'section', 'row', 'price', 'status'))):
            raise ValueError('invalid ticket')
        try:
            price = float(child.attrib['price'])
        except Exception as exc:
            raise ValueError('invalid price') from exc
        if not math.isfinite(price) or price < 0:
            raise ValueError('invalid price')
        if child.attrib['status'] == 'available' and price >= min_price:
            matching.append((price, child.attrib['id'], {'id': child.attrib['id'], 'section': child.attrib['section'], 'row': child.attrib['row'], 'price': round(price, 2)}))
    matching.sort(key=lambda item: (item[0], item[1]))
    start = (page - 1) * page_size
    selected = matching[start:start + page_size]
    average = round(sum((item[0] for item in matching)) / len(matching), 2) if matching else 0.0
    return {'total': len(matching), 'average_price': average, 'tickets': [item[2] for item in selected]}

