import hashlib
import hmac
import os
from unittest.mock import patch

def expected_signature(key, ids):
    return hmac.new(key.encode(), ','.join(ids).encode(), hashlib.sha256).hexdigest()

def test_empty_input_returns_empty_list_without_configuration():
    assert build_dispatch_plan([]) == []

def test_config_key_takes_precedence_over_environment():
    outage = {'id': 'o1', 'region': 'East', 'customers': 1, 'severity': 1, 'status': 'active'}
    with patch.dict(os.environ, {'GRID_DISPATCH_SIGNING_KEY': 'environment-key'}, clear=False):
        result = build_dispatch_plan([outage], {'dispatch_signing_key': 'config-key'})
    assert result[0]['signature'] == expected_signature('config-key', ['o1'])

def test_resolved_outages_are_excluded_and_input_is_not_mutated():
    outages = [{'id': 'active', 'region': 'West', 'customers': 4, 'severity': 4, 'status': 'active'}, {'id': 'done', 'region': 'West', 'customers': 100, 'severity': 5, 'status': 'resolved'}]
