import base64
import hashlib
import hmac
import math
import os

def create_watch_account(email: str, password: str, marks: list[str]) -> dict:
    if not isinstance(email, str):
        raise ValueError('invalid email')
    email = email.strip().lower()
    if email.count('@') != 1 or not all(email.split('@')):
        raise ValueError('invalid email')
    if not isinstance(password, str) or not password:
        raise ValueError('invalid password')
    normalized = []
    for mark in marks:
        if not isinstance(mark, str) or not mark.strip():
            raise ValueError('invalid mark')
        normalized.append(mark.strip().lower())
    normalized = sorted(set(normalized))
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    credential = base64.b64encode(salt + value).decode('ascii')
    return {'email': email, 'marks': normalized, 'credential': credential}

def authenticate_watch_account(account: dict, password: str) -> bool:
    if not isinstance(password, str) or not isinstance(account, dict):
        return False
    credential = account.get('credential')
    if not isinstance(credential, str):
        return False
    try:
        raw = base64.b64decode(credential.encode('ascii'), validate=True)
    except Exception:
        return False
    if len(raw) != 48:
        return False
    value = hashlib.pbkdf2_hmac('sha256', password.encode(), raw[:16], 100000)
    return hmac.compare_digest(value, raw[16:])

def summarize_watch_hits(hits: list[dict], page: int, page_size: int) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
    groups = {}
    for hit in hits:
        if not isinstance(hit, dict):
            raise ValueError('invalid hit')
        mark = hit.get('mark')
        country = hit.get('country')
        score = hit.get('score')
        if not isinstance(mark, str) or not mark.strip() or (not isinstance(country, str)) or (not country.strip()) or (not isinstance(score, (int, float))) or isinstance(score, bool) or (not math.isfinite(score)) or (score < 0):
            raise ValueError('invalid hit')
        key = mark.strip().lower()
        group = groups.setdefault(key, {'count': 0, 'best': score, 'countries': set()})
        group['count'] += 1
        group['best'] = max(group['best'], score)
        group['countries'].add(country.strip().lower())
    ordered = sorted(groups.items(), key=lambda item: (-item[1]['count'], -item[1]['best'], item[0]))
    items = [{'mark': mark, 'count': data['count'], 'best_score': round(data['best'], 2), 'countries': sorted(data['countries'])} for mark, data in ordered]
    start = (page - 1) * page_size
    return {'total': len(items), 'items': items[start:start + page_size]}

