import ast
import operator

def _eval(node, env):
    if isinstance(node, ast.Constant):
        if isinstance(node.value, (int, float, str, bool)) or node.value is None:
            return node.value
        raise ValueError('invalid expression')
    if isinstance(node, ast.Name):
        if node.id in env:
            return env[node.id]
        raise NameError(node.id)
    if isinstance(node, ast.BinOp):
        ops = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv, ast.Mod: operator.mod, ast.Pow: operator.pow}
        if type(node.op) not in ops:
            raise ValueError('invalid expression')
        return ops[type(node.op)](_eval(node.left, env), _eval(node.right, env))
    if isinstance(node, ast.UnaryOp):
        ops = {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}
        if type(node.op) not in ops:
            raise ValueError('invalid expression')
        return ops[type(node.op)](_eval(node.operand, env))
    if isinstance(node, ast.BoolOp):
        if isinstance(node.op, ast.And):
            value = _eval(node.values[0], env)
            for item in node.values[1:]:
                if not value:
                    return value
                value = _eval(item, env)
            return value
        if isinstance(node.op, ast.Or):
            value = _eval(node.values[0], env)
            for item in node.values[1:]:
                if value:
                    return value
                value = _eval(item, env)
            return value
        raise ValueError('invalid expression')
    if isinstance(node, ast.Compare):
        ops = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}
        left = _eval(node.left, env)
        for op, part in zip(node.ops, node.comparators):
            if type(op) not in ops:
                raise ValueError('invalid expression')
            right = _eval(part, env)
            if not ops[type(op)](left, right):
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (not node.keywords) and (node.func.id in ('min', 'max', 'round')):
        return {'min': min, 'max': max, 'round': round}[node.func.id](*[_eval(x, env) for x in node.args])
    raise ValueError('invalid expression')

def rank_incidents(incidents: list[dict], rule: str, limit: int=10) -> dict:
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 0:
        raise ValueError('limit')
    tree = ast.parse(rule, mode='eval').body
    selected = []
    for item in incidents:
        env = {key: item[key] for key in ('id', 'severity', 'score', 'age_hours', 'affected_users', 'team')}
        if _eval(tree, env):
            selected.append(item)
    selected.sort(key=lambda x: (-x['score'], -x['affected_users'], x['id']))
    counts = {}
    for item in selected:
        counts[item['severity']] = counts.get(item['severity'], 0) + 1
    counts = {key: counts[key] for key in sorted(counts)}
    shown = [{key: item[key] for key in ('id', 'severity', 'score', 'affected_users', 'team')} for item in selected[:limit]]
    return {'total': len(selected), 'by_severity': counts, 'incidents': shown}

