        if not isinstance(case, dict):
            raise TypeError()
        if case.get('status') not in statuses or case.get('priority') not in priorities:
            raise ValueError()
        if not isinstance(case.get('hours'), (int, float)) or isinstance(case.get('hours'), bool) or case['hours'] < 0:
            raise ValueError()
        try:
            datetime.fromisoformat(case['updated_at'])
        except (KeyError, TypeError, ValueError):
            raise ValueError()
        if status is None or case['status'] == status:
            selected.append(case)
    selected.sort(key=lambda c: (-priorities[c['priority']], -datetime.fromisoformat(c['updated_at']).timestamp(), c['id']))
    start = (page - 1) * page_size
    items = [{k: c[k] for k in ('id', 'title', 'status', 'priority', 'hours', 'updated_at')} for c in selected[start:start + page_size]]
    return {'items': items, 'total': len(selected), 'total_hours': round(sum((c['hours'] for c in selected)), 2), 'status_counts': {s: sum((c['status'] == s for c in selected)) for s in statuses}, 'page': page, 'page_size': page_size}

