import ast
import operator
_BIN = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
_CMP = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}
_FUNCS = {'min': min, 'max': max, 'round': round}

def evaluate_rule(expression: str, variables: dict[str, object]) -> object:
    try:
        node = ast.parse(expression, mode='eval').body
    except (SyntaxError, TypeError):
        raise ValueError('invalid expression')

    def walk(n):
        if isinstance(n, ast.Constant) and isinstance(n.value, (int, float, bool)):
            return n.value
        if isinstance(n, ast.Name):
            if n.id in ('True', 'False'):
                return n.id == 'True'
            if n.id not in variables:
                raise ValueError('unknown name')
            return variables[n.id]
        if isinstance(n, ast.UnaryOp) and isinstance(n.op, (ast.UAdd, ast.USub, ast.Not)):
            v = walk(n.operand)
            return +v if isinstance(n.op, ast.UAdd) else -v if isinstance(n.op, ast.USub) else not v
        if isinstance(n, ast.BinOp) and type(n.op) in _BIN:
            return _BIN[type(n.op)](walk(n.left), walk(n.right))
        if isinstance(n, ast.BoolOp) and isinstance(n.op, (ast.And, ast.Or)):
            v = walk(n.values[0])
            for x in n.values[1:]:
                if isinstance(n.op, ast.And) and (not v) or (isinstance(n.op, ast.Or) and v):
                    return v
                v = walk(x)
            return v
        if isinstance(n, ast.Compare):
            left = walk(n.left)
            for op, rn in zip(n.ops, n.comparators):
                if type(op) not in _CMP:
                    raise ValueError('unsupported comparison')
                right = walk(rn)
                if not _CMP[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and (not n.keywords) and (n.func.id in _FUNCS):
            return _FUNCS[n.func.id](*(walk(x) for x in n.args))
        raise ValueError('unsupported expression')
    return walk(node)

def provision_subscribers(records: list[dict[str, object]], eligibility: str, rates: dict[str, dict[str, float]]) -> list[dict[str, object]]:
    out = []
    for r in records:
        q = rates[r['plan']]
        c = round(min(q['cap'], max(0, r['usage_gb'] - q['included_gb']) * q['per_gb']), 2)
        v = dict(r)
        v['charge'] = c
        if evaluate_rule(eligibility, v):
            out.append({'id': r['id'], 'plan': r['plan'], 'usage_gb': r['usage_gb'], 'priority': r['priority'], 'charge': c})
    out.sort(key=lambda x: (-x['priority'], x['charge'], x['id']))
    return out

