import hashlib

def transcode_asset(requester: dict, asset: dict, profile: str) -> dict:
    profiles = {'mp4_720p': ('mp4', 1.0), 'mp4_1080p': ('mp4', 1.5), 'webm_720p': ('webm', 0.9)}
    if profile not in profiles:
        raise ValueError('unsupported profile')
    requester_id = requester['id']
    requester_tenant = requester['tenant_id']
    roles = requester['roles']
    asset_id = asset['id']
    owner_id = asset['owner_id']
    asset_tenant = asset['tenant_id']
    duration = asset['duration_seconds']
    size = asset['size_mb']
    if duration < 0 or size < 0:
        raise ValueError('negative media values')
    if not (requester_id == owner_id and requester_tenant == asset_tenant or ('media_admin' in roles and requester_tenant == asset_tenant)):
        raise PermissionError('not permitted')
    output_format, multiplier = profiles[profile]
    job_id = hashlib.sha256(f'{asset_id}:{profile}'.encode()).hexdigest()[:12]
    return {'job_id': job_id, 'asset_id': asset_id, 'profile': profile, 'output_format': output_format, 'status': 'queued', 'estimated_seconds': round(duration * multiplier, 2)}

import hashlib
import hmac
import json
import math
import os
from typing import Optional

def build_sensor_upload(sensor_id: str, readings: list[float], config: Optional[dict[str, str]]=None) -> dict[str, object]:
    if not isinstance(sensor_id, str) or not sensor_id.strip():
        raise ValueError('sensor_id must be a non-empty string')
    normalized_id = sensor_id.strip()
    normalized = []
    for value in readings:
        if isinstance(value, bool) or not isinstance(value, (int, float)) or (not math.isfinite(value)):
            raise ValueError('readings must contain finite numbers')
        normalized.append(float(value))
    secret = None
    if config is not None:
        secret = config.get('OCEAN_API_TOKEN')
    if secret is None:
        secret = os.environ.get('OCEAN_API_TOKEN')
    if not secret:
        raise ValueError('OCEAN_API_TOKEN is required')
    body = {'count': len(normalized), 'readings': normalized, 'sensor_id': normalized_id}
    message = json.dumps(body, sort_keys=True, separators=(',', ':')).encode()
    auth = hmac.new(secret.encode(), message, hashlib.sha256).hexdigest()
    return {**body, 'auth': auth}

