def summarize_claims(xml_text: str, status: str | None=None, page: int=1, page_size: int=10) -> dict:
    if page < 1 or page_size < 1:
        raise ValueError('invalid pagination')
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml_text.encode(), parser=parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'claims':
        raise ValueError('invalid root')
    records = []
    for node in root.findall('claim'):
        values = [node.get(key) for key in ('id', 'policy', 'status', 'date')]
        if any((value is None or value == '' for value in values)):
            raise ValueError('invalid claim')
        amounts = node.findall('amount')
        if len(amounts) != 1 or amounts[0].text is None or amounts[0].text.strip() == '':
            raise ValueError('invalid amount')
        try:
            amount = Decimal(amounts[0].text.strip())
        except (InvalidOperation, ValueError) as exc:
            raise ValueError('invalid amount') from exc
        if not amount.is_finite() or amount < 0:
            raise ValueError('invalid amount')
        if status is None or values[2] == status:
            records.append({'id': values[0], 'policy': values[1], 'status': values[2], 'date': values[3], '_amount': amount})
    records.sort(key=lambda item: (-item['_amount'], item['id']))
    total = sum((item['_amount'] for item in records), Decimal('0'))
    quantized = lambda value: float(value.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
    start = (page - 1) * page_size
    selected = records[start:start + page_size]
    claims = [{key: quantized(item['_amount']) if key == 'amount' else item[key] for key in ('id', 'policy', 'status', 'date', 'amount')} for item in selected]
