import hmac
import json

def verify_publication_webhook(payload: bytes, signature: str, key: bytes) -> dict:
    if not isinstance(payload, bytes) or not isinstance(signature, str) or (not isinstance(key, bytes)):
        raise TypeError()
    if len(signature) != 64 or any((c not in '0123456789abcdef' for c in signature)):
        raise ValueError()
    expected = hmac.new(key, payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError()
    try:
        value = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError()
    if not isinstance(value, dict):
        raise ValueError()
    title = value.get('title')
    doi = value.get('doi')
    authors = value.get('authors')
    year = value.get('year')
    if not isinstance(title, str) or not title or (not isinstance(doi, str)) or (not doi) or (not isinstance(authors, list)) or (not authors) or (not all((isinstance(a, str) for a in authors))) or (not isinstance(year, int)) or isinstance(year, bool) or (not 1000 <= year <= 9999):
        raise ValueError()
    return {'title': title, 'doi': doi, 'authors': authors, 'year': year}

