from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def export_fulfillment_manifest(subscriptions: list[dict], issue_date: str, destination: str) -> dict:
    try:
        parsed = datetime.strptime(issue_date, '%Y-%m-%d')
        if parsed.strftime('%Y-%m-%d') != issue_date:
            raise ValueError
    except ValueError:
        raise ValueError('invalid issue date')
    grouped = {}
    for item in subscriptions:
        if not isinstance(item, dict):
            raise ValueError('invalid subscription')
        fields = ('subscriber_id', 'subscriber_name', 'address', 'magazine')
        if any((not isinstance(item.get(k), str) or not item[k] for k in fields)):
            raise ValueError('invalid subscription')
        quantity = item.get('quantity')
        if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity <= 0:
            raise ValueError('invalid quantity')
        try:
            price = Decimal(str(item.get('unit_price')))
        except (InvalidOperation, ValueError, TypeError):
            raise ValueError('invalid price')
        if not price.is_finite() or price < 0:
            raise ValueError('invalid price')
        cents = price.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        key = (item['magazine'], item['subscriber_id'])
        if key in grouped and grouped[key]['cents'] != cents:
            raise ValueError('conflicting price')
        if key not in grouped:
            grouped[key] = {'item': item, 'quantity': 0, 'cents': cents}
        grouped[key]['quantity'] += quantity
    rows = []
    magazines = {}
    total_copies = 0
    total_value = Decimal('0.00')
    for magazine, subscriber_id in sorted(grouped):
        entry = grouped[magazine, subscriber_id]
        quantity = entry['quantity']
        value = (entry['cents'] * quantity).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        item = entry['item']
        rows.append([issue_date, magazine, subscriber_id, item['subscriber_name'], item['address'], str(quantity), f"{entry['cents']:.2f}", f'{value:.2f}'])
        magazines[magazine] = magazines.get(magazine, 0) + quantity
        total_copies += quantity
        total_value += value
    header = ['issue_date', 'magazine', 'subscriber_id', 'subscriber_name', 'address', 'quantity', 'unit_price', 'total_value']
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as stream:
            writer = csv.writer(stream)
            writer.writerow(header)
            writer.writerows(rows)
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return {'total_rows': len(rows), 'total_copies': total_copies, 'total_value': f'{total_value:.2f}', 'magazines': magazines}

