from datetime import date
from lxml import etree

def extract_title_transfers(xml_text: str, state: str | None=None, page: int=1, page_size: int=20) -> list[dict]:
    if not isinstance(xml_text, str) or not isinstance(state, (str, type(None))):
        raise TypeError()
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError()
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError()
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode(), parser)
    except Exception as exc:
        raise ValueError() from exc
    if root.tag != 'title_transfers':
        raise ValueError()
    records = []
    ids = set()
    for item in root:
        if item.tag != 'transfer':
            raise ValueError()
        if any((k not in item.attrib or not item.attrib[k].strip() for k in ('id', 'date', 'state'))):
            raise ValueError()
        ident, day, current = (item.attrib[k].strip() for k in ('id', 'date', 'state'))
        if ident in ids:
            raise ValueError()
        ids.add(ident)
        try:
            date.fromisoformat(day)
            amount = Decimal(item.findtext('amount', ''))
            if amount < 0 or not amount.is_finite():
                raise ValueError()
            cents = int((amount * 100).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
        except (ValueError, InvalidOperation):
            raise ValueError()
        vin = item.findtext('vin')
        amount_nodes = item.findall('amount')
        vin_nodes = item.findall('vin')
        if len(vin_nodes) != 1 or len(amount_nodes) != 1 or vin is None or (not vin.strip()):
            raise ValueError()
        records.append({'id': ident, 'date': day, 'state': current, 'vin': vin.strip(), 'amount_cents': cents})
    if state is not None:
        records = [r for r in records if r['state'].casefold() == state.casefold()]
    records.sort(key=lambda r: (-int(r['date'].replace('-', '')), r['id']))
    start = (page - 1) * page_size
    return records[start:start + page_size]

