import fnmatch
import os
import subprocess

def directory_report(root: str, pattern: str='*', min_size: int=0) -> dict:
    if not pattern:
        raise ValueError('pattern must not be empty')
    if min_size < 0:
        raise ValueError('min_size must not be negative')
    absolute = os.path.abspath(os.path.normpath(root))
    if not os.path.isdir(absolute):
        raise NotADirectoryError(absolute)
    result = subprocess.run(['find', absolute, '-type', 'f', '-print'], capture_output=True, text=True, check=True)
    groups = {}
    total_count = 0
    total_size = 0
    for path in result.stdout.splitlines():
        base = os.path.basename(path)
        if not fnmatch.fnmatchcase(base.lower(), pattern.lower()):
            continue
        try:
            if not os.path.isfile(path) or os.path.islink(path):
                continue
            size = os.stat(path).st_size
        except OSError:
            continue
        if size < min_size:
            continue
        relative = os.path.relpath(path, absolute).replace(os.sep, '/')
        parts = relative.split('/')
        department = parts[0] if len(parts) > 1 else '.'
        item = {'path': relative, 'size': size, 'extension': os.path.splitext(base)[1].lower()}
        groups.setdefault(department, []).append(item)
        total_count += 1
        total_size += size
    departments = []
    for name in sorted(groups):
        files = sorted(groups[name], key=lambda x: (-x['size'], x['path']))
        departments.append({'name': name, 'count': len(files), 'total_size': sum((x['size'] for x in files)), 'files': files})
    return {'root': absolute, 'total_count': total_count, 'total_size': total_size, 'departments': departments}

def format_directory_report(report: dict) -> str:
