import csv
import io
import math
import os
import tempfile

def parse_gradebook(text: str) -> list[tuple[str, str, float]]:
    rows = [line for line in text.splitlines() if line.strip()]
    reader = csv.reader(rows)
    try:
        header = next(reader)
    except StopIteration:
        raise ValueError('missing header')
    if header != ['student', 'assignment', 'score']:
        raise ValueError('invalid header')
    result = []
    seen = set()
    for row in reader:
        if len(row) != 3:
            raise ValueError('invalid row')
        student, assignment, raw = (row[0].strip(), row[1].strip(), row[2].strip())
        if not student or not assignment:
            raise ValueError('empty field')
        try:
            score = float(raw)
        except ValueError:
            raise ValueError('invalid score')
        if not math.isfinite(score) or not 0 <= score <= 100:
            raise ValueError('invalid score')
        key = (student, assignment)
        if key in seen:
            raise ValueError('duplicate assignment')
        seen.add(key)
        result.append((student, assignment, score))
    return result

def summarize_gradebook(records: list[tuple[str, str, float]]) -> list[dict[str, object]]:
    grouped = {}
    for student, assignment, score in records:
        grouped.setdefault(student, []).append(score)
    result = []
    for student, scores in grouped.items():
        average = round(sum(scores) / len(scores), 2)
        letter = 'A' if average >= 90 else 'B' if average >= 80 else 'C' if average >= 70 else 'D' if average >= 60 else 'F'
        result.append({'student': student, 'average': average, 'letter': letter, 'assignments': len(scores)})
    return sorted(result, key=lambda item: (-item['average'], item['student']))

def export_gradebook(records: list[tuple[str, str, float]], destination: str) -> str:
    output = io.StringIO(newline='')
    writer = csv.writer(output, lineterminator='\n')
    writer.writerow(['student', 'average', 'letter', 'assignments'])
    for item in summarize_gradebook(records):
        writer.writerow([item['student'], f"{item['average']:.2f}", item['letter'], item['assignments']])
    text = output.getvalue()
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(prefix='.gradebook-', dir=parent)
    os.close(fd)
    try:
        with open(temporary, 'w', encoding='utf-8', newline='') as handle:
            handle.write(text)
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return text

