from lxml import etree

def parse_incidents(xml_text: str) -> list[dict[str, object]]:
    if not isinstance(xml_text, str):
        raise TypeError('xml_text must be a string')
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode(), parser)
    except etree.XMLSyntaxError as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'statuspage':
        raise ValueError('unexpected root element')
    result = []
    for incident in root.findall('incident'):
        incident_id = incident.get('id')
        status = incident.get('status')
        if incident_id is None or status is None:
            raise ValueError('incident requires id and status')
        values = {}
        for name in ('title', 'updated'):
            node = incident.find(name)
            values[name] = (node.text or '').strip() if node is not None else ''
        components = []
        for component in incident.findall('component'):
            components.append({'name': (component.get('name') or '').strip(), 'status': (component.get('status') or '').strip()})
        result.append({'id': incident_id.strip(), 'status': status.strip(), 'title': values['title'], 'updated': values['updated'], 'components': components})
    return result

