import hashlib
import hmac
import re
from datetime import date

def _fields(line):
    fields = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('dangling escape')
    fields.append(''.join(current))
    return fields

def parse_expense_line(line: str) -> dict:
    fields = _fields(line)
    if len(fields) != 6:
        raise ValueError('field count')
    ident, employee, amount, day, category, status = fields
    if not ident or not employee or (not category):
        raise ValueError('empty field')
    if not re.fullmatch('[0-9]+\\.[0-9]{2}', amount) or int(amount.replace('.', '')) <= 0:
        raise ValueError('amount')
    try:
        date.fromisoformat(day)
    except ValueError:
        raise ValueError('date')
    if status not in ('approved', 'rejected'):
        raise ValueError('status')
    return {'id': ident, 'employee': employee, 'amount_cents': int(amount.replace('.', '')), 'date': day, 'category': category, 'status': status}

def parse_expense_payload(payload: str) -> list[dict]:
    lines = payload.split('\n')
    while lines and (not lines[0].strip()):
        lines.pop(0)
    while lines and (not lines[-1].strip()):
        lines.pop()
    if not lines:
        return []
    records = []
    seen = set()
    for line in lines:
        if not line.strip():
            raise ValueError('empty record')
        record = parse_expense_line(line)
        if record['id'] in seen:
            raise ValueError('duplicate id')
        seen.add(record['id'])
        records.append(record)
    return records

def verify_and_summarize(payload: str, signature: str, secret: bytes, period_start: str, period_end: str) -> dict:
    expected = hmac.new(secret, payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not isinstance(signature, str) or len(signature) != 64 or (not hmac.compare_digest(expected, signature)):
        raise PermissionError('invalid signature')
    try:
        start = date.fromisoformat(period_start)
        end = date.fromisoformat(period_end)
    except ValueError:
        raise ValueError('period')
    if start > end:
        raise ValueError('period')
    groups = {}
    count = 0
    total = 0
    for record in parse_expense_payload(payload):
        if record['status'] == 'approved' and start <= date.fromisoformat(record['date']) <= end:
            group = groups.setdefault(record['employee'], {'employee': record['employee'], 'count': 0, 'total_cents': 0})
            group['count'] += 1
            group['total_cents'] += record['amount_cents']
            count += 1
            total += record['amount_cents']
    return {'count': count, 'total_cents': total, 'by_employee': sorted(groups.values(), key=lambda x: (-x['total_cents'], x['employee']))}

