import hashlib
import hmac
import json

def generate_lab_export(records: list[dict], config: dict[str, str], page: int=1, page_size: int=50) -> dict:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    if 'signing_key' not in config:
        raise KeyError('signing_key')
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        for field in ('patient_id', 'code', 'timestamp', 'status'):
            if not isinstance(record.get(field), str) or not record[field]:
                raise ValueError('invalid record')
        if record['status'] not in ('normal', 'abnormal'):
            raise ValueError('invalid record')
        patient = groups.setdefault(record['patient_id'], {'codes': set(), 'count': 0, 'abnormal': 0, 'latest': ''})
        patient['codes'].add(record['code'])
        patient['count'] += 1
        patient['abnormal'] += record['status'] == 'abnormal'
        patient['latest'] = max(patient['latest'], record['timestamp'])
    summaries = []
    for patient_id in sorted(groups):
        value = groups[patient_id]
        summaries.append({'patient_id': patient_id, 'test_count': value['count'], 'abnormal_count': value['abnormal'], 'latest_timestamp': value['latest'], 'codes': sorted(value['codes'])})
    start = (page - 1) * page_size
    body = {'page': page, 'page_size': page_size, 'total_patients': len(summaries), 'patients': summaries[start:start + page_size]}
    data = json.dumps(body, sort_keys=True, separators=(',', ':')).encode('utf-8')
    body['signature'] = hmac.new(config['signing_key'].encode('utf-8'), data, hashlib.sha256).hexdigest()
    return body

