import hashlib
import hmac
import json
from datetime import datetime, timedelta, timezone

def _time(value):
    if not isinstance(value, str) or not value.endswith('Z'):
        raise ValueError('bad timestamp')
    raw = value[:-1]
    try:
        dt = datetime.fromisoformat(raw)
    except ValueError:
        raise ValueError('bad timestamp')
    if dt.tzinfo is not None or dt.second < 0:
        raise ValueError('bad timestamp')
    dt = dt.replace(tzinfo=timezone.utc)
    text = dt.isoformat(timespec='microseconds').replace('+00:00', 'Z')
    text = text.rstrip('0').rstrip('.') + 'Z' if '.' in text else text
    return (dt, text)

def parse_order_events(data):
    if not isinstance(data, dict) or not isinstance(data.get('orders'), list):
        raise ValueError('orders required')
    result, seen = ([], set())
    for item in data['orders']:
        if not isinstance(item, dict):
            raise ValueError('bad order')
        required = ('id', 'customer', 'cents', 'status', 'timestamp')
        if any((k not in item for k in required)):
            raise ValueError('bad order')
        if not isinstance(item['id'], str) or not item['id'] or item['id'] in seen:
            raise ValueError('bad id')
        if not isinstance(item['customer'], str) or not item['customer']:
            raise ValueError('bad customer')
        if isinstance(item['cents'], bool) or not isinstance(item['cents'], int) or item['cents'] < 0:
            raise ValueError('bad cents')
        if item['status'] not in ('pending', 'delivered', 'cancelled'):
            raise ValueError('bad status')
        dt, stamp = _time(item['timestamp'])
        copy = dict(item)
        copy['timestamp'] = stamp
        copy['_dt'] = dt
        result.append(copy)
        seen.add(item['id'])
    return result

def verify_and_summarize(payload: bytes, headers: dict[str, str], secret: bytes | str) -> dict:
    if not isinstance(secret, (bytes, str)):
        raise PermissionError('invalid credentials')
    key = secret.encode() if isinstance(secret, str) else secret
    names = [v for k, v in headers.items() if k.lower() == 'x-signature']
    if len(names) != 1 or not isinstance(names[0], str) or (not names[0].startswith('sha256=')):
        raise PermissionError('invalid signature')
    supplied = names[0][7:]
    expected = hmac.new(key, payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(supplied, expected):
        raise PermissionError('invalid signature')
    try:
        data = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    orders = parse_order_events(data)
    if not orders:
        return {'as_of': None, 'customers': []}
    latest = max((x['_dt'] for x in orders))
    cutoff = latest - timedelta(days=7)
    totals = {}
    for order in orders:
        if order['status'] == 'delivered' and cutoff <= order['_dt'] <= latest:
            row = totals.setdefault(order['customer'], [0, 0])
            row[0] += 1
            row[1] += order['cents']
    customers = [{'customer': k, 'orders': v[0], 'cents': v[1]} for k, v in totals.items()]
    customers.sort(key=lambda x: (-x['cents'], x['customer']))
    return {'as_of': max((x['timestamp'] for x in orders)), 'customers': customers}

