import sqlite3
import math
import re
from datetime import datetime, date
_schedule_keys = ('id', 'animal_id', 'animal_name', 'species', 'feed_time', 'amount', 'unit', 'note')
_total_keys = ('day', 'species', 'total_amount', 'feed_count')

def _check_species(value):
    if value is not None and (not isinstance(value, str) or not value):
        raise ValueError('invalid species')

def _check_day(value):
    if value is not None:
        if not isinstance(value, str) or re.fullmatch('\\d{4}-\\d{2}-\\d{2}', value) is None:
            raise ValueError('invalid day')
        try:
            date.fromisoformat(value)
        except ValueError:
            raise ValueError('invalid day')

def get_schedule(conn: sqlite3.Connection, day: str | None=None, species: str | None=None, sort_by: str='time') -> list[dict]:
    _check_day(day)
    _check_species(species)
    orders = {'time': 'feed_time, id', 'species': 'species, feed_time, id', 'amount': 'amount, feed_time, id'}
    if sort_by not in orders:
        raise ValueError('invalid sort')
    sql = 'SELECT id, animal_id, animal_name, species, feed_time, amount, unit, note FROM feedings'
    clauses = []
    params = []
    if day is not None:
        clauses.append('substr(feed_time, 1, 10) = ?')
        params.append(day)
    if species is not None:
        clauses.append('species = ?')
        params.append(species)
    if clauses:
        sql += ' WHERE ' + ' AND '.join(clauses)
    sql += ' ORDER BY ' + orders[sort_by]
    return [dict(zip(_schedule_keys, row)) for row in conn.execute(sql, params)]

def record_feeding(conn: sqlite3.Connection, animal_id: int, feed_time: str, amount: float, unit: str, note: str='') -> int:
    try:
        datetime.fromisoformat(feed_time)
    except (TypeError, ValueError):
        raise ValueError('invalid time')
    if not isinstance(amount, (int, float)) or not math.isfinite(amount) or amount <= 0:
        raise ValueError('invalid amount')
    if unit not in {'g', 'kg', 'ml', 'l'}:
        raise ValueError('invalid unit')
    animal = conn.execute('SELECT name, species FROM animals WHERE id = ?', (animal_id,)).fetchone()
    if animal is None:
        raise ValueError('unknown animal')
    cur = conn.execute('INSERT INTO feedings (animal_id, animal_name, species, feed_time, amount, unit, note) VALUES (?, ?, ?, ?, ?, ?, ?)', (animal_id, animal[0], animal[1], feed_time, amount, unit, note))
    conn.commit()
    return int(cur.lastrowid)

def daily_totals(conn: sqlite3.Connection, species: str | None=None) -> list[dict]:
    _check_species(species)
    sql = 'SELECT substr(feed_time, 1, 10) AS day, species, SUM(amount) AS total_amount, COUNT(*) AS feed_count FROM feedings'
    params = []
    if species is not None:
        sql += ' WHERE species = ?'
        params.append(species)
    sql += ' GROUP BY day, species ORDER BY day, species'
    return [dict(zip(_total_keys, row)) for row in conn.execute(sql, params)]

