def campaign():
    return {'id': 'spring', 'tenant_id': 't1', 'owner_id': 'u1', 'active_from': 100, 'active_until': 200, 'coupons': {'SAVE10': {'value': 10, 'stock': 5, 'per_user_limit': 3}, 'VIP': {'value': 50, 'stock': 2, 'per_user_limit': 1}, 'A=B': {'value': 7, 'stock': 4, 'per_user_limit': 4}}}

def test_parse_rejects_bad_records():
    for text in ['X', 'X=0', 'X=-1', 'X= 2', 'X=2=3', 'X\\q=1', '=1']:
        with pytest.raises(ValueError):
            parse_coupon_batch(text)

def test_owner_redeems_and_results_are_value_sorted():
    c = campaign()
    ledger = {}
    result = redeem_coupon_batch({'id': 'u1', 'tenant_id': 't1', 'roles': []}, c, 'SAVE10=2\nVIP=1', ledger, 150)
    assert result == [{'code': 'VIP', 'quantity': 1, 'value': 50, 'total': 50}, {'code': 'SAVE10', 'quantity': 2, 'value': 10, 'total': 20}]
    assert ledger == {'SAVE10': ['u1', 'u1'], 'VIP': ['u1']}

def test_manager_can_redeem_and_ties_use_code_order():
    c = campaign()
    c['coupons']['A=B']['value'] = 10
    ledger = {}
    result = redeem_coupon_batch({'id': 'm', 'tenant_id': 't1', 'roles': ['coupon_manager']}, c, 'SAVE10=1\nA\\=B=1', ledger, 100)
    assert [x['code'] for x in result] == ['A=B', 'SAVE10']
    assert ledger['A=B'] == ['m'] and ledger['SAVE10'] == ['m']

def test_limits_and_atomicity():
    c = campaign()
    ledger = {'VIP': ['u1']}
    before = {k: list(v) for k, v in ledger.items()}
    with pytest.raises(ValueError):
        redeem_coupon_batch({'id': 'u1', 'tenant_id': 't1', 'roles': []}, c, 'SAVE10=1\nVIP=1', ledger, 120)
    assert ledger == before

