import os
import json
import hmac
import hashlib
from datetime import date

def parse_inventory(records):
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    result = []
    for item in records:
        if not isinstance(item, dict):
            raise ValueError('each record must be a dictionary')
        for key in ('plant', 'variety', 'quantity', 'received'):
            if key not in item:
                raise ValueError('missing field')
        if not isinstance(item['plant'], str) or not isinstance(item['variety'], str):
            raise ValueError('names must be strings')
        if isinstance(item['quantity'], bool) or not isinstance(item['quantity'], int) or item['quantity'] < 0:
            raise ValueError('quantity must be non-negative')
        if not isinstance(item['received'], str):
            raise ValueError('date must be a string')
        try:
            date.fromisoformat(item['received'])
        except ValueError:
            raise ValueError('invalid date')
        result.append({key: item[key] for key in ('plant', 'variety', 'quantity', 'received')})
    return result

def aggregate_inventory(records):
    groups = {}
    for item in parse_inventory(records):
        key = (item['plant'], item['variety'])
        if key not in groups:
            groups[key] = {'plant': key[0], 'variety': key[1], 'quantity': 0, 'first_received': item['received'], 'lots': 0}
        group = groups[key]
        group['quantity'] += item['quantity']
        group['lots'] += 1
        group['first_received'] = min(group['first_received'], item['received'])
    return sorted(groups.values(), key=lambda x: (-x['quantity'], x['plant'], x['variety']))

def build_sync_request(records, config=None):
    config = {} if config is None else config
    if not isinstance(config, dict):
        raise ValueError('config must be a mapping')
    if 'url' in config and (not isinstance(config['url'], str)):
        raise ValueError('url must be a string')
    if 'api_token' in config and (not isinstance(config['api_token'], str)):
        raise ValueError('api_token must be a string')
    url = config.get('url', 'https://inventory.example.test/v1/sync')
    token = config.get('api_token', os.environ.get('NURSERY_API_TOKEN'))
    if not token:
        raise RuntimeError('NURSERY_API_TOKEN is required')
    body = json.dumps(aggregate_inventory(records), ensure_ascii=False, separators=(',', ':'))
    digest = hmac.new(token.encode(), body.encode(), hashlib.sha256).hexdigest()
    return {'url': url, 'headers': {'Authorization': 'Bearer ' + token, 'Content-Type': 'application/json', 'X-Payload-SHA256': digest}, 'body': body}

