def evaluate_rule(expression: str, names: dict[str, int | float | bool]) -> int | float | bool:
    try:
        tree = ast.parse(expression, mode='eval').body
        return _eval(tree, names)
    except Exception as exc:
        if isinstance(exc, ValueError):
            raise
        raise ValueError('invalid expression') from exc

def _eval(node, names):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
        if isinstance(node.value, float) and (not math.isfinite(node.value)):
            raise ValueError('invalid number')
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in names:
            raise ValueError('unknown name')
        return names[node.id]
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
        value = _eval(node.operand, names)
        return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
    if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
        a, b = (_eval(node.left, names), _eval(node.right, names))
        return {ast.Add: lambda: a + b, ast.Sub: lambda: a - b, ast.Mult: lambda: a * b, ast.Div: lambda: a / b}[type(node.op)]()
    if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
        value = _eval(node.values[0], names)
        for part in node.values[1:]:
            if isinstance(node.op, ast.And):
                if not value:
                    return value
                value = _eval(part, names)
            else:
                if value:
                    return value
                value = _eval(part, names)
        return value
    if isinstance(node, ast.Compare):
        left = _eval(node.left, names)
        for op, right_node in zip(node.ops, node.comparators):
            right = _eval(right_node, names)
            if not isinstance(op, (ast.Lt, ast.LtE, ast.Eq, ast.NotEq, ast.Gt, ast.GtE)):
                raise ValueError('invalid comparison')
            good = {ast.Lt: left < right, ast.LtE: left <= right, ast.Eq: left == right, ast.NotEq: left != right, ast.Gt: left > right, ast.GtE: left >= right}[type(op)]
            if not good:
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
        args = [_eval(x, names) for x in node.args]
        if node.func.id == 'min':
            return min(*args)
        if node.func.id == 'max':
            return max(*args)
        return round(*args)
    raise ValueError('unsupported expression')

