    if not isinstance(budget, (int, float)) or isinstance(budget, bool) or budget < 0 or (not math.isfinite(budget)):
        raise ValueError('invalid budget')
    variables = {} if variables is None else variables
    if any((not isinstance(v, (int, float, bool)) or (isinstance(v, float) and (not math.isfinite(v))) for v in variables.values())):
        raise ValueError('invalid variables')
    checked = []
    fields = {'id', 'applicant', 'amount', 'score', 'hours', 'region'}
    for r in records:
        if set(r) != fields or not isinstance(r['id'], str) or (not isinstance(r['applicant'], str)) or (not isinstance(r['region'], str)):
            raise ValueError('invalid record')
        if any((isinstance(r[x], bool) or not isinstance(r[x], (int, float)) or (not math.isfinite(r[x])) for x in ('amount', 'score', 'hours'))) or r['amount'] <= 0:
            raise ValueError('invalid record')
