        raise ValueError('invalid as_of')
    window = config.get('window_days')
    if not isinstance(window, int) or isinstance(window, bool) or window < 0:
        raise ValueError('invalid window_days')
    through = as_of + timedelta(days=window)
    grouped = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        try:
            license_id = record['license_id']
            jurisdiction = record['jurisdiction']
            expires = date.fromisoformat(record['expires'])
            fee = Decimal(str(record['fee']))
        except (KeyError, TypeError, ValueError, InvalidOperation):
            raise ValueError('invalid record')
        if not isinstance(license_id, str) or not license_id or (not isinstance(jurisdiction, str)) or (not jurisdiction) or fee.is_nan() or (fee < 0):
            raise ValueError('invalid record')
        if as_of <= expires <= through:
            normalized = fee.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
            grouped.setdefault(jurisdiction, []).append((expires, license_id, normalized))
    groups = []
    for jurisdiction in sorted(grouped):
        entries = sorted(grouped[jurisdiction], key=lambda item: (item[0], item[1]))
        licenses = [{'license_id': ident, 'expires': expiry.isoformat(), 'fee': format(fee, '.2f')} for expiry, ident, fee in entries]
