        groups.append({'jurisdiction': jurisdiction, 'licenses': licenses, 'total_fee': format(total, '.2f')})
    result = {'as_of': as_of.isoformat(), 'through': through.isoformat(), 'groups': groups}
    raw = json.dumps(result, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode('utf-8')
    result['signature'] = hmac.new(config['signing_key'].encode('utf-8'), raw, hashlib.sha256).hexdigest()
    return result

