import csv
import hashlib
import hmac
import io
import os
import base64

def make_operator(username: str, password: str, zone: str) -> dict:
    if not isinstance(username, str) or not username.strip() or (not isinstance(zone, str)) or (not zone.strip()):
        raise ValueError('invalid operator')
    if not isinstance(password, str) or len(password) < 4:
        raise ValueError('invalid password')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return {'username': username.strip(), 'zone': zone.strip(), 'salt': base64.b64encode(salt).decode(), 'digest': digest.hex()}

def authenticate_operator(record: dict, password: str) -> bool:
    try:
        if not isinstance(record, dict) or not isinstance(password, str):
            return False
        salt = base64.b64decode(record['salt'], validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000).hex()
        return hmac.compare_digest(actual, record['digest'])
    except (KeyError, TypeError, ValueError):
        return False

def aggregate_frames(csv_text: str, window_seconds: int=60) -> list[dict]:
    if not isinstance(csv_text, str) or not isinstance(window_seconds, int) or isinstance(window_seconds, bool) or (window_seconds <= 0):
        raise ValueError('invalid input')
    rows = list(csv.reader(io.StringIO(csv_text)))
    rows = [r for r in rows if any((x.strip() for x in r))]
    if not rows or rows[0] != ['frame_id', 'timestamp', 'zone', 'cloud_cover', 'altitude']:
        raise ValueError('invalid header')
    groups = {}
    seen = set()
    for row in rows[1:]:
        if len(row) != 5:
            raise ValueError('invalid row')
        fid, stamp, zone, cloud, altitude = [x.strip() for x in row]
        if not fid or not zone or fid in seen:
            raise ValueError('invalid identifier')
        try:
            stamp = int(stamp)
            cloud = float(cloud)
            altitude = float(altitude)
        except ValueError:
            raise ValueError('invalid number')
        if stamp < 0 or not 0 <= cloud <= 100 or altitude < 0:
            raise ValueError('invalid value')
        seen.add(fid)
        key = (stamp // window_seconds, zone)
        groups.setdefault(key, []).append((fid, stamp, cloud, altitude))
    result = []
    for (window, zone), values in sorted(groups.items()):
        ordered = sorted(values, key=lambda x: (x[1], x[0]))
        result.append({'window': window, 'zone': zone, 'frame_count': len(values), 'average_cloud_cover': round(sum((x[2] for x in values)) / len(values), 2), 'min_altitude': min((x[3] for x in values)), 'max_altitude': max((x[3] for x in values)), 'frame_ids': [x[0] for x in ordered]})
    return result

def authorized_summary(record: dict, password: str, csv_text: str, window_seconds: int=60) -> list[dict]:
    if not isinstance(record, dict) or not record.get('zone') or (not authenticate_operator(record, password)):
        raise PermissionError('not authorized')
    result = aggregate_frames(csv_text, window_seconds)
    if any((item['zone'] != record['zone'] for item in result)):
        raise ValueError('zone mismatch')
    return result

