import csv
import math
import os
from datetime import date

def load_rate_schedule(base_dir: str, relative_name: str) -> dict[str, list[tuple[str, float, float]]]:
    base = os.path.realpath(base_dir)
    path = os.path.realpath(os.path.join(base, relative_name))
    if os.path.commonpath([base, path]) != base:
        raise ValueError('file is outside base directory')
    result = {}
    seen = set()
    with open(path, 'r', encoding='utf-8', newline='') as handle:
        reader = csv.DictReader(handle)
        if reader.fieldnames != ['district', 'effective_from', 'factor', 'exemption_cap']:
            raise ValueError('invalid header')
        for row in reader:
            if None in row or any((value is None for value in row.values())):
                raise ValueError('invalid row')
            district = row['district'].strip()
            stamp = row['effective_from']
            try:
                date.fromisoformat(stamp)
                factor = float(row['factor'])
                cap = float(row['exemption_cap'])
            except Exception as exc:
                raise ValueError('invalid row') from exc
            if not district or not math.isfinite(factor) or (not math.isfinite(cap)):
                raise ValueError('invalid row')
            key = (district, stamp)
            if key in seen:
                raise ValueError('duplicate rate')
            seen.add(key)
            result.setdefault(district, []).append((stamp, factor, cap))
    if not result:
        raise ValueError('empty schedule')
    for values in result.values():
        values.sort(key=lambda item: item[0])
    return result

def assess_parcels(parcels: list[dict], schedule: dict[str, list[tuple[str, float, float]]], as_of: str) -> list[dict]:
    try:
        date.fromisoformat(as_of)
    except Exception as exc:
        raise ValueError('invalid date') from exc
    output = []
    for parcel in parcels:
        try:
            ident = parcel['id']
            district = parcel['district']
            land = float(parcel['land_value'])
            building = float(parcel['building_value'])
            exemption = float(parcel['exemption'])
        except Exception as exc:
            raise ValueError('invalid parcel') from exc
        if not all((math.isfinite(x) for x in (land, building, exemption))) or exemption < 0:
            raise ValueError('invalid parcel')
        choices = [item for item in schedule.get(district, []) if item[0] <= as_of]
        if not choices:
            raise ValueError('no applicable rate')
        _, factor, cap = choices[-1]
        gross = land + building
        applied = min(exemption, cap)
        taxable = max(0.0, gross - applied)
        assessed = round(taxable * factor, 2)
        output.append({'id': ident, 'district': district, 'gross_value': float(gross), 'applied_exemption': float(applied), 'taxable_value': float(taxable), 'assessed_value': float(assessed)})
    output.sort(key=lambda item: (item['district'], -item['assessed_value'], item['id']))
    return output

