import pytest

def rubric():
    return [{'criterion': 'q1', 'points': 3, 'accepted': ['Paris', 'Lyon']}, {'criterion': 'q2', 'points': 2, 'accepted': ['42']}, {'criterion': 'q3', 'points': 5, 'accepted': ['yes']}]

def teacher():
    return {'id': 't1', 'tenant_id': 'school-a', 'roles': ['teacher']}

def student():
    return {'id': 's1', 'tenant_id': 'school-a', 'roles': ['student']}

def submission(sid, student_id, when, answers, course='math'):
    return {'id': sid, 'student_id': student_id, 'course_id': course, 'tenant_id': 'school-a', 'submitted_at': when, 'answers': answers}

def test_parse_answers_handles_escaping_and_order():
    assert parse_answers('q1=Paris\\=France\nq2=  42  \n\nq3=yes') == {'q1': 'Paris=France', 'q2': '42', 'q3': 'yes'}

def test_parse_answers_rejects_malformed_and_duplicate_lines():
    with pytest.raises(ValueError):
        parse_answers('q1')
    with pytest.raises(ValueError):
        parse_answers('=value')
    with pytest.raises(ValueError):
        parse_answers('q1=one\nq1=two')

def test_grade_submission_awards_points_and_reports_missing_answers():
    result = grade_submission(teacher(), submission('sub-1', 's1', '2025-01-01T10:00:00Z', 'q1= paris \nq2=41'), rubric())
    assert result == {'submission_id': 'sub-1', 'student_id': 's1', 'course_id': 'math', 'earned_points': 3, 'possible_points': 10, 'percentage': 30.0, 'criteria': [{'criterion': 'q1', 'answer': 'paris', 'points': 3, 'matched': True}, {'criterion': 'q2', 'answer': '41', 'points': 0, 'matched': False}, {'criterion': 'q3', 'answer': None, 'points': 0, 'matched': False}]}

def test_grade_submission_compares_case_insensitively_and_preserves_points():
    rb = [{'criterion': 'a', 'points': 1.5, 'accepted': ['Correct']}, {'criterion': 'b', 'points': 0.5, 'accepted': ['TRUE']}]
    result = grade_submission(student(), submission('x', 's1', 't', 'a= correct\nb=true'), rb)
    assert result['earned_points'] == 2.0
    assert result['possible_points'] == 2.0
    assert result['percentage'] == 100.0
    assert [x['matched'] for x in result['criteria']] == [True, True]

def test_course_gradebook_empty_and_invalid_course_inputs():
    empty = course_gradebook(teacher(), [], rubric())
    assert empty == {'course_id': None, 'submissions': [], 'class_average': 0, 'letter_counts': {'A': 0, 'B': 0, 'C': 0, 'D': 0, 'F': 0}}
    other = submission('z', 's9', '2025-01-04', 'q1=Paris', course='science')
    with pytest.raises(ValueError):
        course_gradebook(teacher(), [submission('x', 's1', 't', 'q1=Paris'), other], rubric())

def test_course_gradebook_rejects_mixed_tenants():
    first = submission('x', 's1', '2025-01-01', 'q1=Paris')
    second = submission('y', 's2', '2025-01-02', 'q1=Paris')
    second['tenant_id'] = 'school-b'
    with pytest.raises(ValueError):
        course_gradebook(teacher(), [first, second], rubric())

