def parse_answers(raw: str) -> dict[str, str]:
    result = {}
    for line in raw.splitlines():
        if not line.strip():
            continue
        key = []
        value = []
        escaped = False
        separator = -1
        for i, char in enumerate(line):
            if escaped:
                (value if separator >= 0 else key).append(char)
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == '=' and separator < 0:
                separator = i
            else:
                (value if separator >= 0 else key).append(char)
        if escaped:
            (value if separator >= 0 else key).append('\\')
        if separator < 0:
            raise ValueError('malformed answer')
        k = ''.join(key).strip()
        v = ''.join(value).strip()
        if not k or k in result:
            raise ValueError('invalid answer key')
        result[k] = v
    return result

def _authorize(requester, submission):
    if requester.get('tenant_id') != submission.get('tenant_id'):
        raise PermissionError('permission denied')
    if requester.get('id') != submission.get('student_id') and 'teacher' not in requester.get('roles', []):
        raise PermissionError('permission denied')

def grade_submission(requester: dict, submission: dict, rubric: list[dict]) -> dict:
    _authorize(requester, submission)
    answers = parse_answers(submission['answers'])
    criteria = []
    earned = 0
    possible = 0
    for item in rubric:
        criterion = item['criterion']
        points = item['points']
        answer = answers.get(criterion)
        matched = answer is not None and any((answer.strip().casefold() == x.strip().casefold() for x in item['accepted']))
        awarded = points if matched else 0
        possible += points
        earned += awarded
        criteria.append({'criterion': criterion, 'answer': answer, 'points': awarded, 'matched': matched})
    percentage = round(earned * 100 / possible, 2) if possible else 0
    return {'submission_id': submission['id'], 'student_id': submission['student_id'], 'course_id': submission['course_id'], 'earned_points': earned, 'possible_points': possible, 'percentage': percentage, 'criteria': criteria}

def course_gradebook(requester: dict, submissions: list[dict], rubric: list[dict]) -> dict:
    if not submissions:
        return {'course_id': None, 'submissions': [], 'class_average': 0, 'letter_counts': {'A': 0, 'B': 0, 'C': 0, 'D': 0, 'F': 0}}
    course = submissions[0]['course_id']
    tenant = submissions[0]['tenant_id']
    if any((x['course_id'] != course or x['tenant_id'] != tenant for x in submissions)):
        raise ValueError('inconsistent submission group')
    grades = [grade_submission(requester, x, rubric) for x in submissions]
    grades.sort(key=lambda x: (-x['percentage'], next((s['submitted_at'] for s in submissions if s['id'] == x['submission_id'])), x['submission_id']))
    counts = {'A': 0, 'B': 0, 'C': 0, 'D': 0, 'F': 0}
    for grade in grades:
        p = grade['percentage']
        counts['A' if p >= 90 else 'B' if p >= 80 else 'C' if p >= 70 else 'D' if p >= 60 else 'F'] += 1
    return {'course_id': course, 'submissions': grades, 'class_average': round(sum((x['percentage'] for x in grades)) / len(grades), 2), 'letter_counts': counts}

