from datetime import datetime, timezone
import math
from lxml import etree

def parse_readings(xml_text: str) -> list[tuple[str, str, int, float]]:
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml_text.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'feed':
        raise ValueError('wrong root')
    result = []
    for shipment in root.findall('shipment'):
        sid = shipment.get('id')
        if not sid:
            raise ValueError('missing shipment id')
        for node in shipment.findall('reading'):
            sensor = node.get('sensor')
            stamp = node.get('at')
            temp_text = node.get('temp')
            if not sensor or not stamp or (not temp_text):
                raise ValueError('missing reading attribute')
            if not stamp.endswith('Z'):
                raise ValueError('invalid timestamp')
            try:
                dt = datetime.fromisoformat(stamp[:-1] + '+00:00')
                if dt.tzinfo is None or dt.utcoffset() != timezone.utc.utcoffset(dt):
                    raise ValueError
                temp = float(temp_text)
            except Exception as exc:
                raise ValueError('invalid reading') from exc
            if not math.isfinite(temp):
                raise ValueError('invalid temperature')
            result.append((sid, sensor, int(dt.timestamp()), temp))
    return result

def aggregate_readings(readings: list[tuple[str, str, int, float]], window_seconds: int) -> list[dict]:
    if not isinstance(window_seconds, int) or isinstance(window_seconds, bool) or window_seconds <= 0:
        raise ValueError('invalid window')
    groups = {}
    for shipment, sensor, timestamp, temperature in readings:
        key = (shipment, timestamp - timestamp % window_seconds)
        groups.setdefault(key, []).append(temperature)
    result = []
    for (shipment, start), values in sorted(groups.items()):
        result.append({'shipment': shipment, 'window_start': start, 'count': len(values), 'average': sum(values) / len(values), 'minimum': min(values), 'maximum': max(values)})
    return result

def classify_shipments(readings: list[tuple[str, str, int, float]]) -> list[dict]:
    groups = {}
    for shipment, sensor, timestamp, temperature in readings:
        groups.setdefault(shipment, []).append(temperature)
    result = []
    for shipment in sorted(groups):
        values = groups[shipment]
        result.append({'shipment': shipment, 'status': 'ALERT' if any((v < 2.0 or v > 8.0 for v in values)) else 'OK', 'count': len(values), 'minimum': min(values), 'maximum': max(values)})
    return result

