import json
import os
import tempfile
import zipfile


def make_archive(files):
    temp = tempfile.NamedTemporaryFile(suffix=".zip", delete=False)
    temp.close()
    with zipfile.ZipFile(temp.name, "w") as archive:
        for name, value in files.items():
            if isinstance(value, str):
                data = value
            else:
                data = json.dumps(value)
