from datetime import date
from decimal import Decimal, ROUND_HALF_UP

def reservation_report(requester: dict, museum: dict, reservations: list[dict], start: str, end: str, page: int=1, page_size: int=20) -> dict:
    if page <= 0 or page_size <= 0:
        raise ValueError('invalid pagination')
    try:
        first = date.fromisoformat(start)
        last = date.fromisoformat(end)
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid date range') from exc
    if first > last:
        raise ValueError('invalid date range')
    if requester.get('tenant_id') != museum.get('tenant_id') and requester.get('role') != 'museum_admin':
        raise PermissionError('not permitted')
    grouped = {}
    for reservation in reservations:
        try:
            day = date.fromisoformat(reservation['date'])
        except (KeyError, TypeError, ValueError) as exc:
            raise ValueError('invalid reservation date') from exc
        try:
            count = reservation['ticket_count']
            price = Decimal(str(reservation['unit_price']))
        except (KeyError, TypeError, ValueError, ArithmeticError) as exc:
            raise ValueError('invalid reservation amount') from exc
        if count < 0 or price <= 0:
            raise ValueError('invalid reservation amount')
        if reservation.get('museum_id') != museum.get('id') or reservation.get('status') != 'confirmed' or (not first <= day <= last):
            continue
        amount = Decimal(count) * price
        entry = grouped.setdefault(reservation['date'], [0, Decimal('0')])
        entry[0] += count
        entry[1] += amount
    total_tickets = sum((value[0] for value in grouped.values()))
    total_revenue = sum((value[1] for value in grouped.values()), Decimal('0'))
    days = []
    for key in sorted(grouped):
        count, revenue = grouped[key]
        days.append({'date': key, 'ticket_count': count, 'revenue': float(revenue.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))})
    start_index = (page - 1) * page_size
    return {'museum_id': museum['id'], 'museum_name': museum['name'], 'start': start, 'end': end, 'total_tickets': total_tickets, 'total_revenue': float(total_revenue.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)), 'days': days[start_index:start_index + page_size], 'page': page, 'page_size': page_size, 'total_days': len(days)}

