import csv
import io
from datetime import datetime
_HEADER = ['passenger_id', 'booking', 'fare', 'loyalty', 'requested_at', 'status']
_FARES = {'Y': 1, 'W': 2, 'J': 3, 'F': 4}

def parse_waitlist(text: str) -> list[dict]:
    rows = list(csv.reader(io.StringIO(text), skipinitialspace=False))
    if not rows:
        raise ValueError('missing header')
    if rows[0] != _HEADER:
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if not row:
            continue
        if len(row) != 6:
            raise ValueError('invalid row')
        item = dict(zip(_HEADER, row))
        if not item['passenger_id']:
            raise ValueError('blank passenger')
        try:
            int(item['loyalty'])
        except ValueError as exc:
            raise ValueError('invalid loyalty') from exc
        if item['status'] not in ('WAITING', 'CANCELLED'):
            raise ValueError('invalid status')
        result.append(item)
    return result

def create_upgrade_plan(requester: dict, flight: dict, waitlist_text: str, seats: int) -> dict:
    if not isinstance(seats, int) or isinstance(seats, bool) or seats < 0:
        raise ValueError('invalid seats')
    if requester.get('tenant') != flight.get('tenant'):
        raise PermissionError('not permitted')
    if requester.get('id') != flight.get('owner_id') and 'dispatcher' not in requester.get('roles', []):
        raise PermissionError('not permitted')
    records = parse_waitlist(waitlist_text)
    seen = set()
    candidates = []
    for record in records:
        booking = record['booking']
        if booking in seen:
            raise ValueError('duplicate booking')
        seen.add(booking)
        if record['status'] != 'WAITING':
            continue
        if record['fare'] not in _FARES:
            raise ValueError('invalid fare')
        try:
            when = datetime.fromisoformat(record['requested_at'])
        except ValueError as exc:
            raise ValueError('invalid timestamp') from exc
        candidates.append((-_FARES[record['fare']], -int(record['loyalty']), when, record['passenger_id']))
    candidates.sort(key=lambda x: x[0:])
    selected = [item[3] for item in candidates[:seats]]
    return {'flight_id': flight['flight_id'], 'tenant': flight['tenant'], 'upgraded': selected, 'remaining': seats - len(selected)}

