from datetime import date

def _read_date(value):
    if not re.fullmatch('\\d{4}-\\d{2}-\\d{2}', value):
        raise ValueError('invalid date')
    try:
        return date.fromisoformat(value)
    except ValueError as exc:
        raise ValueError('invalid date') from exc

def generate_lending_report(path: str, as_of: str) -> list[dict]:
    reference = _read_date(as_of)
    try:
        completed = subprocess.run(['sort', '-t', '\t', '-k1,1', '-k2,2', '-k3,3', '-k4,4', '-k5,5', path], check=True, capture_output=True, text=True, encoding='utf-8')
    except (OSError, subprocess.CalledProcessError, UnicodeError) as exc:
        raise ValueError('unable to read ledger') from exc
    groups = {}
    for raw in completed.stdout.splitlines():
        if not raw.strip():
            continue
        fields = raw.split('\t')
        if len(fields) != 5:
            raise ValueError('malformed record')
        member, checkout_text, due_text, isbn, title = fields
        if not member or not checkout_text or (not due_text) or (not isbn) or (not title.strip()):
            raise ValueError('empty field')
        checkout = _read_date(checkout_text)
        due = _read_date(due_text)
        if due < checkout:
            raise ValueError('invalid lending interval')
        record = (checkout, isbn, title, due)
