from datetime import date

def load_payments(path: str) -> list[dict]:
    with open(path, encoding='utf-8') as handle:
        lines = handle.readlines()
    header_seen = False
    rows = []
    for line in lines:
        line = line.rstrip('\n\r')
        if not line.strip():
            continue
        if not header_seen:
            if line != 'borrower,date,principal,interest':
                raise ValueError('invalid header')
            header_seen = True
            continue
        fields = line.split(',')
        if len(fields) != 4:
            raise ValueError('invalid row')
        borrower, dates, principal, interest = fields
        if not borrower:
            raise ValueError('invalid borrower')
        try:
            parsed = date.fromisoformat(dates)
            p = int(principal)
            i = int(interest)
        except Exception as exc:
            raise ValueError('invalid row') from exc
        if parsed.isoformat() != dates or p < 0 or i < 0:
            raise ValueError('invalid row')
        rows.append({'borrower': borrower, 'date': dates, 'principal': p, 'interest': i})
    if not header_seen or not rows:
        raise ValueError('empty payment file')
    rows.sort(key=lambda row: (row['borrower'], row['date']))
    return rows

def mortgage_report(path: str, borrower: str | None=None) -> list[dict]:
    groups = {}
    for row in load_payments(path):
        if borrower is not None and row['borrower'] != borrower:
            continue
        key = (row['borrower'], row['date'][:7])
        item = groups.setdefault(key, {'principal': 0, 'interest': 0, 'payment_count': 0})
        item['principal'] += row['principal']
        item['interest'] += row['interest']
        item['payment_count'] += 1
    output = []
    for (name, month), item in sorted(groups.items()):
        principal = item['principal']
        interest = item['interest']
        output.append({'borrower': name, 'month': month, 'principal': principal, 'interest': interest, 'total': principal + interest, 'payment_count': item['payment_count']})
    return output

