import csv
import os
import tempfile


def make_csv(rows, headers=("application_id", "region", "requested_amount")):
    handle = tempfile.NamedTemporaryFile(mode="w", encoding="utf-8", newline="", delete=False)
    try:
        writer = csv.DictWriter(handle, fieldnames=headers)
        writer.writeheader()
        for row in rows:
            writer.writerow(row)
        return handle.name
    finally:
        handle.close()


def test_empty_header_only_file_returns_empty_list():
    path = make_csv([])
    try:
        assert rank_applications(path) == []
    finally:
        os.unlink(path)


def test_orders_by_amount_and_id_tie_breaker():
    path = make_csv([
