import subprocess

def rank_applications(path: str, region: str | None=None, page: int=1, page_size: int=10) -> list[dict]:
    if page < 1 or page_size < 1:
        raise ValueError('page and page_size must be positive')
    result = subprocess.run(['wc', '-l', path], capture_output=True, text=True, check=True)
    if int(result.stdout.split()[0]) == 0:
        return []
    with open(path, newline='', encoding='utf-8') as stream:
        reader = csv.DictReader(stream)
        required = {'application_id', 'region', 'requested_amount'}
        if not reader.fieldnames or not required.issubset(reader.fieldnames):
            raise ValueError('missing required column')
        records = []
        for row in reader:
            if region is not None and row['region'] != region:
                continue
            try:
                amount = float(row['requested_amount'])
            except (TypeError, ValueError) as exc:
                raise ValueError('invalid amount') from exc
            records.append({'application_id': row['application_id'], 'region': row['region'], 'requested_amount': round(amount, 2), '_amount': amount})
    records.sort(key=lambda item: (-item['_amount'], item['application_id']))
    start = (page - 1) * page_size
    result = records[start:start + page_size]
    return [{key: item[key] for key in ('application_id', 'region', 'requested_amount')} for item in result]

