import os
import shutil
import zipfile
from pathlib import Path

def process_shipment_archive(archive_path: str, destination_dir: str) -> list[tuple[str, float]]:
    base = Path(destination_dir).resolve()
    base.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(archive_path) as archive:
        for info in archive.infolist():
            member = Path(info.filename)
            if info.is_dir():
                continue
            target = (base / member).resolve()
            try:
                target.relative_to(base)
            except ValueError:
                raise ValueError('archive member is outside destination')
            target.parent.mkdir(parents=True, exist_ok=True)
            with archive.open(info) as source, open(target, 'wb') as output:
                shutil.copyfileobj(source, output)
    csv_path = base / 'shipments.csv'
    if not csv_path.is_file():
        raise ValueError('shipments.csv is required')
    totals = {}
    with csv_path.open(newline='', encoding='utf-8') as handle:
        reader = csv.reader(handle)
        try:
            header = next(reader)
        except StopIteration:
            raise ValueError('invalid CSV header')
        if header != ['shipment_id', 'quarry', 'weight_kg', 'status']:
            raise ValueError('invalid CSV header')
        for row in reader:
            if len(row) != 4:
                raise ValueError('invalid shipment row')
            shipment_id, quarry, weight_text, status = (part.strip() for part in row)
            try:
                weight = float(weight_text)
            except ValueError:
                raise ValueError('invalid shipment row')
            if not shipment_id or not quarry or (not math.isfinite(weight)) or (weight < 0) or (status not in {'delivered', 'in_transit', 'cancelled'}):
                raise ValueError('invalid shipment row')
            if status == 'delivered':
                totals[quarry] = totals.get(quarry, 0.0) + weight
    result = [(quarry, round(weight, 2)) for quarry, weight in totals.items()]
    result.sort(key=lambda item: (-item[1], item[0]))
    return result

