import subprocess
from datetime import date
from collections import defaultdict

def _parse(line):
    parts = line.rstrip('\n').split('|')
    if len(parts) != 4 or not parts[1]:
        raise ValueError('invalid record')
    try:
        date.fromisoformat(parts[0])
        reps = int(parts[2])
        pain = int(parts[3])
    except (ValueError, TypeError):
        raise ValueError('invalid record')
    if reps < 0 or pain < 0 or pain > 10:
        raise ValueError('invalid record')
    return (parts[0], parts[1], reps, pain)

def summarize_exercise(log_path: str, exercise: str, window: int=3) -> dict:
    if not exercise or not isinstance(window, int) or isinstance(window, bool) or (window <= 0):
        raise ValueError('invalid argument')
    completed = subprocess.run(['grep', '-F', '-e', exercise, '--', log_path], capture_output=True, text=True, check=False)
    if completed.returncode not in (0, 1):
        if completed.returncode == 2:
            raise FileNotFoundError(log_path)
        raise ValueError('command failed')
    records = []
    for line in completed.stdout.splitlines():
        record = _parse(line)
        if record[1] == exercise:
            records.append(record)
    records.sort(key=lambda item: item[0])
    reps = [item[2] for item in records]
    best = max((sum(reps[i:i + window]) for i in range(len(reps))), default=0)
    return {'exercise': exercise, 'sessions': len(records), 'total_repetitions': sum(reps), 'average_pain': round(sum((item[3] for item in records)) / len(records), 2) if records else 0.0, 'best_window_repetitions': best, 'dates': [item[0] for item in records]}

def rank_exercises(log_path: str, limit: int=3) -> list[tuple[str, int, int]]:
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 0:
        raise ValueError('invalid limit')
    with open(log_path, encoding='utf-8') as source:
        totals = defaultdict(lambda: [0, 0])
        for line in source:
            if line.strip():
                _, name, reps, _ = _parse(line)
                totals[name][0] += reps
                totals[name][1] += 1
    result = [(name, values[0], values[1]) for name, values in totals.items()]
    result.sort(key=lambda item: (-item[1], item[0]))
    return result[:limit]

