from collections.abc import Mapping
_FIELDS = ('patient_id', 'medication', 'requested_date', 'quantity', 'priority', 'status')

def normalize_refill_requests(records: list[dict]) -> list[dict]:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    grouped = {}
    for item in records:
        if not isinstance(item, Mapping):
            raise ValueError('record must be a mapping')
        try:
            patient = item['patient_id']
            medication = item['medication']
            date = item['requested_date']
            quantity = item['quantity']
            priority = item['priority']
            status = item['status']
        except (KeyError, TypeError):
            raise ValueError('missing field')
        if not isinstance(patient, str) or not patient or (not isinstance(medication, str)) or (not medication):
            raise ValueError('invalid text')
        if not isinstance(date, str):
            raise ValueError('invalid date')
        try:
            datetime.date.fromisoformat(date)
        except ValueError:
            raise ValueError('invalid date')
        if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity <= 0:
            raise ValueError('invalid quantity')
        if isinstance(priority, bool) or not isinstance(priority, int) or (not 1 <= priority <= 5):
            raise ValueError('invalid priority')
        if status not in ('pending', 'approved', 'denied'):
            raise ValueError('invalid status')
        if status == 'denied':
            continue
        key = (patient, medication, date)
        if key not in grouped:
            grouped[key] = {'patient_id': patient, 'medication': medication, 'requested_date': date, 'quantity': quantity, 'priority': priority, 'status': status}
        else:
            row = grouped[key]
            row['quantity'] += quantity
            row['priority'] = max(row['priority'], priority)
            if status == 'approved':
                row['status'] = 'approved'
    return sorted(grouped.values(), key=lambda x: (-x['priority'], x['requested_date'], x['patient_id'], x['medication']))

def export_refill_requests(records: list[dict], output_path: str) -> str:
    rows = normalize_refill_requests(records)
    with tempfile.NamedTemporaryFile(mode='w', encoding='utf-8', newline='', dir=os.path.dirname(os.path.abspath(output_path)), delete=False) as f:
        writer = csv.DictWriter(f, fieldnames=_FIELDS, lineterminator='\n')
        writer.writeheader()
        writer.writerows(rows)
        temporary = f.name
    try:
        with open(temporary, encoding='utf-8', newline='') as f:
            text = f.read()
        os.replace(temporary, output_path)
        return text
    except Exception:
        try:
            os.unlink(temporary)
        except OSError:
            pass
        raise

