import hashlib
import hmac
import json
from datetime import date

def verify_and_summarize(payload: str, signature: str, secret: str, offset: int=0, limit: int=50) -> list[dict]:
    expected = hmac.new(secret.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not isinstance(signature, str) or not hmac.compare_digest(expected, signature):
        raise PermissionError('invalid signature')
    if not isinstance(offset, int) or isinstance(offset, bool) or offset < 0:
        raise ValueError('invalid offset')
    if not isinstance(limit, int) or isinstance(limit, bool) or (not 1 <= limit <= 100):
        raise ValueError('invalid limit')
    try:
        data = json.loads(payload)
    except Exception as exc:
        raise ValueError('invalid JSON') from exc
    if not isinstance(data, dict) or not isinstance(data.get('trial_id'), str) or (not data['trial_id']):
        raise ValueError('invalid trial')
    visits = data.get('visits')
    if not isinstance(visits, list):
        raise ValueError('invalid visits')
    grouped = {}
    for visit in visits:
        if not isinstance(visit, dict):
            raise ValueError('invalid visit')
        required = ('participant_id', 'site', 'date', 'status', 'minutes')
        if any((key not in visit for key in required)):
            raise ValueError('invalid visit')
        if not isinstance(visit['participant_id'], str) or not visit['participant_id'] or (not isinstance(visit['site'], str)) or (not visit['site']) or (visit['status'] not in ('completed', 'scheduled')) or (not isinstance(visit['minutes'], int)) or isinstance(visit['minutes'], bool) or (visit['minutes'] < 0):
            raise ValueError('invalid visit')
        try:
            date.fromisoformat(visit['date'])
        except (TypeError, ValueError) as exc:
            raise ValueError('invalid date') from exc
        if visit['status'] != 'completed':
            continue
        participant = visit['participant_id']
        item = grouped.setdefault(participant, {'participant_id': participant, 'trial_id': data['trial_id'], 'sites': set(), 'completed_visits': 0, 'total_minutes': 0, 'latest_visit': ''})
        item['sites'].add(visit['site'])
        item['completed_visits'] += 1
        item['total_minutes'] += visit['minutes']
        item['latest_visit'] = max(item['latest_visit'], visit['date'])
    result = []
    for item in grouped.values():
        item['sites'] = sorted(item['sites'])
        result.append(item)
    result.sort(key=lambda item: (-item['total_minutes'], item['participant_id']))
    return result[offset:offset + limit]

