import secrets
_SCOPE = re.compile('^[A-Za-z0-9_.-]+$')
_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'

def _date(value):
    if not isinstance(value, str):
        raise ValueError('invalid timestamp')
    try:
        parsed = datetime.strptime(value.strip(), '%Y-%m-%dT%H:%M:%SZ')
    except ValueError:
        raise ValueError('invalid timestamp')
    if parsed.strftime('%Y-%m-%dT%H:%M:%SZ') != value.strip():
        raise ValueError('invalid timestamp')
    return parsed

def _scopes(values):
    if not isinstance(values, list):
        raise ValueError('invalid scopes')
    result = set()
    for item in values:
        if not isinstance(item, str):
            raise ValueError('invalid scope')
        item = item.strip()
        if not item or not _SCOPE.fullmatch(item):
            raise ValueError('invalid scope')
        result.add(item)
    if not result:
        raise ValueError('no scopes')
    return sorted(result)

def issue_deletion_request(user_id: str, scopes: list[str], created_at: str) -> dict:
    if not isinstance(user_id, str):
        raise ValueError('invalid user')
    user_id = user_id.strip()
    if not user_id or '|' in user_id:
        raise ValueError('invalid user')
    _date(created_at)
    alphabet = _ALPHABET
    request_id = ''.join((secrets.choice(alphabet) for _ in range(20)))
    code = ''.join((str(secrets.randbelow(10)) for _ in range(6)))
    return {'user_id': user_id, 'scopes': _scopes(scopes), 'created_at': created_at.strip(), 'request_id': request_id, 'confirmation_code': code, 'state': 'pending'}

def summarize_deletion_requests(requests: list[dict], as_of: str) -> list[dict]:
    cutoff = _date(as_of)
    groups = {}
    for item in requests:
        if not isinstance(item, dict):
            raise ValueError('invalid request')
        required = {'user_id', 'scopes', 'created_at', 'request_id', 'state'}
        if not required <= set(item) or not isinstance(item['user_id'], str) or (not isinstance(item['request_id'], str)) or (not item['request_id']) or (item['state'] != 'pending'):
            raise ValueError('invalid request')
        when = _date(item['created_at'])
        if when > cutoff:
            raise ValueError('future request')
        scopes = _scopes(item['scopes'])
