import hashlib
import os

def _hash_password(password):
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return salt.hex() + ':' + value.hex()

def _check_password(password, stored):
    salt_text, digest = stored.split(':', 1)
    salt = bytes.fromhex(salt_text)
    value = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return value.hex() == digest

def create_customer(store, username, password):
    if not isinstance(username, str) or not isinstance(password, str) or (not username) or (len(password) < 4):
        raise ValueError('invalid customer')
    store.setdefault('customers', {})
    store.setdefault('bookings', [])
    if username in store['customers']:
        raise ValueError('duplicate customer')
    store['customers'][username] = _hash_password(password)

def authenticate_customer(store, username, password):
    customer = store.get('customers', {}).get(username)
    if customer is None or not isinstance(password, str):
        return False
    return _check_password(password, customer)

def _minutes(value):
    if not isinstance(value, str) or len(value) != 5 or value[2] != ':':
        raise ValueError('invalid time')
    if not value[:2].isdigit() or not value[3:].isdigit():
        raise ValueError('invalid time')
    hour, minute = (int(value[:2]), int(value[3:]))
    if hour > 23 or minute not in (0, 15, 30, 45):
        raise ValueError('invalid time')
    return hour * 60 + minute

def book_installation(store, username, password, day, duration, windows):
    if not authenticate_customer(store, username, password):
        raise PermissionError('authentication failed')
    if not isinstance(day, str) or not day or (not isinstance(duration, int)) or isinstance(duration, bool) or (duration <= 0) or duration % 15:
        raise ValueError('invalid booking')
    if not isinstance(windows, dict):
        raise ValueError('invalid windows')
    parsed = []
    for start, end in windows.get(day, []):
        a, b = (_minutes(start), _minutes(end))
        if b <= a:
            raise ValueError('invalid window')
        parsed.append((a, b))
    parsed.sort()
    for previous, current in zip(parsed, parsed[1:]):
        if current[0] <= previous[1]:
            raise ValueError('overlapping windows')
    occupied = []
    for booking in store.get('bookings', []):
        if booking['day'] == day:
            occupied.append((_minutes(booking['start']), _minutes(booking['end'])))
    occupied.sort()
    for start, end in parsed:
        candidate = start
        while candidate + duration <= end:
            if all((candidate + duration <= a or candidate >= b for a, b in occupied)):
                result = {'customer': username, 'day': day, 'start': f'{candidate // 60:02d}:{candidate % 60:02d}', 'end': f'{(candidate + duration) // 60:02d}:{(candidate + duration) % 60:02d}'}
                store.setdefault('bookings', []).append(result)
                return result
            candidate += 15
    raise ValueError('no available slot')

