def create_user(user_id: str, password: str) -> dict:
    if not isinstance(user_id, str) or not isinstance(password, str):
        raise TypeError()
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return {'user_id': user_id, 'credential': salt.hex() + '$' + digest.hex()}

