import secrets

def generate_invite_code(length: int=10) -> str:
    if isinstance(length, bool) or not isinstance(length, int) or length <= 0:
        raise ValueError('invalid length')
    alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
    return ''.join((secrets.choice(alphabet) for _ in range(length)))

def prepare_call_sheet(records: list[dict], shoot_date: str, page: int=1, page_size: int=20) -> dict:
    try:
        datetime.date.fromisoformat(shoot_date)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('invalid page size')
    selected = []
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        required = ('date', 'name', 'department', 'call_time', 'duration_minutes', 'status')
        if any((key not in record for key in required)):
            raise ValueError('invalid record')
        try:
            datetime.date.fromisoformat(record['date'])
            parsed_time = datetime.datetime.strptime(record['call_time'], '%H:%M').time()
        except (TypeError, ValueError):
            raise ValueError('invalid record')
        if not isinstance(record['name'], str) or not record['name'] or (not isinstance(record['department'], str)) or (not record['department']) or isinstance(record['duration_minutes'], bool) or (not isinstance(record['duration_minutes'], int)) or (record['duration_minutes'] < 0) or (record['status'] not in ('confirmed', 'tentative', 'cancelled')):
            raise ValueError('invalid record')
        if record['date'] == shoot_date and record['status'] != 'cancelled':
            selected.append((parsed_time, record))
    selected.sort(key=lambda pair: (pair[0], pair[1]['name']))
    total = len(selected)
    pages = (total + page_size - 1) // page_size
    if total and page > pages:
        raise ValueError('page out of range')
    counts = {}
    for _, record in selected:
        counts[record['department']] = counts.get(record['department'], 0) + 1
    entries = []
    for _, record in selected[(page - 1) * page_size:page * page_size]:
        entries.append({key: record[key] for key in ('name', 'department', 'call_time', 'duration_minutes', 'status')})
    return {'date': shoot_date, 'total': total, 'pages': pages, 'page': page, 'page_size': page_size, 'entries': entries, 'departments': dict(sorted(counts.items())), 'invite_code': generate_invite_code()}

