def export_seat_allocations(seats: list[dict], section: str | None=None, min_price: float=0.0, page: int=1, page_size: int=10) -> str:
    if not isinstance(seats, list):
        raise ValueError('seats')
    if section is not None and (not isinstance(section, str) or not section):
        raise ValueError('section')
    if isinstance(min_price, bool) or not isinstance(min_price, (int, float)) or (not math.isfinite(min_price)) or (min_price < 0):
        raise ValueError('min_price')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('page_size')
    selected = []
    for item in seats:
        if not isinstance(item, dict):
            raise ValueError('record')
        for key in ('section', 'row', 'seat', 'price', 'status'):
            if key not in item:
                raise ValueError('record')
        if not isinstance(item['section'], str) or not item['section']:
            raise ValueError('section')
        if not isinstance(item['status'], str) or not item['status'] or item['status'] not in ('available', 'reserved'):
            raise ValueError('status')
        if isinstance(item['row'], bool) or not isinstance(item['row'], int) or item['row'] < 1:
            raise ValueError('row')
        if isinstance(item['seat'], bool) or not isinstance(item['seat'], int) or item['seat'] < 1:
            raise ValueError('seat')
        if isinstance(item['price'], bool) or not isinstance(item['price'], (int, float)) or (not math.isfinite(item['price'])) or (item['price'] < 0):
            raise ValueError('price')
        if item['status'] == 'available' and (section is None or item['section'] == section) and (item['price'] >= min_price):
            selected.append(item)
    selected.sort(key=lambda x: (x['price'], x['section'], x['row'], x['seat']))
    start = (page - 1) * page_size
    selected = selected[start:start + page_size]
    fd, path = tempfile.mkstemp(text=True)
    try:
        with os.fdopen(fd, 'w', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(('section', 'row', 'seat', 'price'))
            for item in selected:
                writer.writerow((item['section'], item['row'], item['seat'], f"{item['price']:.2f}"))
        with open(path, 'r', newline='') as handle:
            return handle.read()
    finally:
        try:
            os.unlink(path)
        except FileNotFoundError:
            pass

