from lxml import etree

def parse_volunteer_shifts(xml_text: str) -> list[dict[str, str]]:
    parser = etree.XMLParser(resolve_entities=False, load_dtd=False, no_network=True)
    try:
        root = etree.fromstring(xml_text.encode('utf-8'), parser)
    except (etree.XMLSyntaxError, UnicodeError) as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'festival':
        raise ValueError('unexpected root')
    shifts = root.find('shifts')
    if shifts is None:
        raise ValueError('missing shifts')
    result = []
    for node in shifts:
        if node.tag != 'shift':
            continue
        values = {key: (node.get(key) or '').strip() for key in ('id', 'start', 'end')}
        volunteer = node.find('volunteer')
        task = node.find('task')
        values['volunteer'] = (volunteer.text if volunteer is not None and volunteer.text else '').strip()
        values['task'] = (task.text if task is not None and task.text else '').strip()
        if not all(values.values()):
            raise ValueError('incomplete shift')
        result.append({'id': values['id'], 'volunteer': values['volunteer'], 'task': values['task'], 'start': values['start'], 'end': values['end']})
    return result

