import hashlib
import hmac
import json

def generate_application_export(applications: list[dict], config: dict[str, str]) -> dict[str, object]:
    key = config.get('export_key')
    if not isinstance(key, str) or not key:
        raise ValueError('config must contain a non-empty export_key')
    offset = config.get('offset', 0)
    limit = config.get('limit', 50)
    if isinstance(offset, bool) or not isinstance(offset, int) or offset < 0:
        raise ValueError('offset must be a non-negative integer')
    if isinstance(limit, bool) or not isinstance(limit, int) or limit < 0:
        raise ValueError('limit must be a non-negative integer')
    selected = []
    for application in applications:
        if not isinstance(application, dict):
            raise ValueError('application must be a dictionary')
        required = ('id', 'department', 'score', 'status')
        if any((field not in application for field in required)):
            raise ValueError('application is missing a required field')
        ident = application['id']
        department = application['department']
        score = application['score']
        status = application['status']
        if not isinstance(ident, str) or not ident or (not isinstance(department, str)) or (not department) or isinstance(score, bool) or (not isinstance(score, int)) or (score < 0) or (score > 100) or (status not in ('applied', 'withdrawn', 'hired')):
            raise ValueError('invalid application')
        if status in ('applied', 'hired'):
            selected.append({'id': ident, 'department': department, 'score': score})
    selected.sort(key=lambda item: (-item['score'], item['department'], item['id']))
    total = len(selected)
    items = selected[offset:offset + limit]
    body = {'total': total, 'items': items}
    encoded = json.dumps(body, separators=(',', ':')).encode()
    signature = hmac.new(key.encode(), encoded, hashlib.sha256).hexdigest()
    return {'total': total, 'items': items, 'signature': signature}

