import os
import json
from datetime import datetime, timezone, timedelta

def _time(value):
    if not isinstance(value, str) or len(value) != 20 or (not value.endswith('Z')):
        raise ValueError('invalid timestamp')
    try:
        return datetime.strptime(value, '%Y-%m-%dT%H:%M:%SZ').replace(tzinfo=timezone.utc)
    except ValueError:
        raise ValueError('invalid timestamp')

def _path(base, name):
    root = os.path.realpath(base)
    candidate = os.path.realpath(os.path.join(root, name))
    if os.path.commonpath([root, candidate]) != root:
        raise ValueError('invalid path')
    return candidate

def load_container_plan(base_dir: str, relative_name: str) -> list[dict]:
    with open(_path(base_dir, relative_name), encoding='utf-8') as f:
        try:
            value = json.load(f)
        except Exception as e:
            raise ValueError('invalid json') from e
    if not isinstance(value, dict) or set(value) != {'containers'} or (not isinstance(value['containers'], list)):
        raise ValueError('invalid plan')
    fields = {'container_id', 'vessel', 'priority', 'ready', 'due', 'crane_minutes', 'destination'}
    for item in value['containers']:
        if not isinstance(item, dict) or set(item) != fields:
            raise ValueError('invalid container')
        for k in ('container_id', 'vessel', 'destination'):
            if not isinstance(item[k], str) or not item[k]:
                raise ValueError('invalid container')
        if not isinstance(item['priority'], int) or isinstance(item['priority'], bool):
            raise ValueError('invalid container')
        if not isinstance(item['crane_minutes'], int) or isinstance(item['crane_minutes'], bool) or item['crane_minutes'] <= 0:
            raise ValueError('invalid container')
        if _time(item['due']) <= _time(item['ready']):
            raise ValueError('invalid interval')
    return value['containers']

def schedule_containers(plans: list[dict], window_start: str, window_end: str, crane_count: int) -> list[dict]:
    start = _time(window_start)
    finish = _time(window_end)
    if finish <= start or not isinstance(crane_count, int) or isinstance(crane_count, bool) or (crane_count <= 0):
        raise ValueError('invalid window')
    free = [start] * crane_count
    result = []
    ordered = sorted(plans, key=lambda p: (-p['priority'], _time(p['due']), p['container_id']))
    for p in ordered:
        ready, due = (_time(p['ready']), _time(p['due']))
        crane = min(range(crane_count), key=lambda i: (free[i], i))
        begin = max(free[crane], ready, start)
        end = begin + timedelta(minutes=p['crane_minutes'])
        if end > due or end > finish:
            raise ValueError('container cannot be scheduled')
        free[crane] = end
        result.append({'container_id': p['container_id'], 'vessel': p['vessel'], 'destination': p['destination'], 'crane': crane + 1, 'start': begin.strftime('%Y-%m-%dT%H:%M:%SZ'), 'end': end.strftime('%Y-%m-%dT%H:%M:%SZ'), 'priority': p['priority']})
    return sorted(result, key=lambda x: (x['start'], x['crane'], x['container_id']))

def write_schedule(base_dir: str, relative_name: str, schedule: list[dict]) -> str:
    path = _path(base_dir, relative_name)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'w', encoding='utf-8') as f:
        f.write(json.dumps({'schedule': schedule}, indent=2) + '\n')
    return path

