import os

def hash_notebook_password(password: str) -> str:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return salt.hex() + ':' + digest.hex()

def verify_notebook_password(password: str, stored: str) -> bool:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    if not isinstance(stored, str):
        return False
    try:
        salt_text, digest_text = stored.split(':')
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return actual == expected

def summarize_notebooks(records: list[dict], page: int=1, page_size: int=10, tag: str | None=None) -> list[dict]:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page <= 0) or (page_size <= 0):
        raise ValueError('page and page_size must be positive integers')
    groups = {}
    for record in records:
        if tag is not None and tag not in record['tags']:
            continue
        owner = record['owner']
        if owner not in groups:
            groups[owner] = [0, 0, 0]
        groups[owner][0] += 1
        groups[owner][1] += record['views']
        groups[owner][2] += record['downloads']
    result = [{'owner': owner, 'notebook_count': values[0], 'total_views': values[1], 'average_downloads': round(values[2] / values[0], 2)} for owner, values in groups.items()]
    result.sort(key=lambda item: (-item['total_views'], item['owner']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

