    return parsed

def setup_database(conn):
    conn.execute('CREATE TABLE IF NOT EXISTS readings (customer_id TEXT NOT NULL, reading_date TEXT NOT NULL, therms REAL NOT NULL, PRIMARY KEY (customer_id, reading_date))')
    conn.commit()

def add_reading(conn, customer_id, reading_date, therms):
    if not isinstance(customer_id, str) or not customer_id.strip():
        raise ValueError('invalid customer')
    _date(reading_date)
    if isinstance(therms, bool) or not isinstance(therms, (int, float)):
        raise TypeError('therms must be numeric')
    if not math.isfinite(therms) or therms < 0:
        raise ValueError('invalid therms')
    conn.execute('INSERT OR REPLACE INTO readings(customer_id, reading_date, therms) VALUES (?, ?, ?)', (customer_id, reading_date, float(therms)))
    conn.commit()

