import csv
import io

def parse_sample_sheet(text: str) -> list[dict]:
    try:
        rows = list(csv.DictReader(io.StringIO(text, newline='')))
    except (csv.Error, TypeError) as exc:
        raise ValueError('invalid csv') from exc
    if not rows:
        if text and 'sample_id' not in text.splitlines()[0].split(','):
            raise ValueError('missing columns')
        return []
    required = {'sample_id', 'owner_id', 'tenant_id', 'measurements'}
    if set(rows[0].keys()) != required:
        raise ValueError('missing columns')
    result = []
    for row in rows:
        if not row['sample_id']:
            raise ValueError('blank sample')
        measurements = []
        if row['measurements'] == '':
            raise ValueError('bad measurement')
        for item in row['measurements'].split(';'):
            parts = item.split('=')
            if len(parts) != 2:
                raise ValueError('bad measurement')
            try:
                depth = int(parts[0])
                value = float(parts[1])
            except ValueError as exc:
                raise ValueError('bad measurement') from exc
            if depth < 0 or value < 0:
                raise ValueError('negative measurement')
            measurements.append({'depth': depth, 'value': value})
        if len({x['depth'] for x in measurements}) != len(measurements):
            raise ValueError('duplicate depth')
        measurements.sort(key=lambda x: x['depth'])
        result.append({'sample_id': row['sample_id'], 'owner_id': row['owner_id'], 'tenant_id': row['tenant_id'], 'measurements': measurements})
    return sorted(result, key=lambda x: x['sample_id'])

def summarize_samples(requester: dict, samples: list[dict], window: int=3) -> dict:
    if not isinstance(window, int) or isinstance(window, bool) or window <= 0:
        raise ValueError('invalid window')
    result = {}
    for sample in samples:
        allowed = sample['owner_id'] == requester['id'] or ('supervisor' in requester.get('roles', []) and sample['tenant_id'] == requester['tenant_id']) or 'admin' in requester.get('roles', [])
        if not allowed:
            raise PermissionError('not permitted')
        measurements = sample['measurements']
        if not measurements or any((a['depth'] >= b['depth'] for a, b in zip(measurements, measurements[1:]))):
            raise ValueError('invalid measurements')
        points = []
        for i, item in enumerate(measurements):
            values = [x['value'] for x in measurements[max(0, i - window):min(len(measurements), i + window + 1)]]
            average = round(sum(values) / len(values), 2)
            points.append({'depth': item['depth'], 'average': average, 'classification': 'elevated' if average >= 100.0 else 'normal'})
        result[sample['sample_id']] = {'owner_id': sample['owner_id'], 'tenant_id': sample['tenant_id'], 'points': points}
    return {key: result[key] for key in sorted(result)}

def format_summary(summary: dict) -> str:
    lines = []
    for sample_id in sorted(summary):
        item = summary[sample_id]
        points = ', '.join((f"{p['depth']}={p['average']:.2f}({p['classification']})" for p in item['points']))
        lines.append(f"{sample_id}: {item['owner_id']}/{item['tenant_id']}; {points}")
    return ''.join((line + '\n' for line in lines))

