        raise ValueError('limit must be positive')
    result = subprocess.run(['find', directory, '-maxdepth', '1', '-type', 'f', '-name', pattern, '-print'], capture_output=True, text=True, check=True)
    rows = []
    for path in result.stdout.splitlines():
