        with open(path, 'r', encoding='utf-8') as handle:
            for raw in handle:
                line = raw.strip()
                if not line:
                    continue
                fields = line.split(',')
                if len(fields) != 2:
                    raise ValueError('malformed record')
                try:
                    value = float(fields[1].strip())
                except ValueError as exc:
                    raise ValueError('invalid moisture reading') from exc
                if not 0 <= value <= 100:
                    raise ValueError('moisture reading out of range')
                values.append(value)
        if values:
            mean = round(sum(values) / len(values), 2)
            rows.append((os.path.basename(path), mean, len(values)))
    rows.sort(key=lambda item: (-item[1], item[0]))
    return rows[:limit]

