import hashlib
import hmac
import os
from decimal import Decimal, ROUND_HALF_UP

def hash_password(password: str) -> str:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def verify_password(password: str, stored: str) -> bool:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    if not isinstance(stored, str) or '$' not in stored:
        return False
    try:
        salt_text, digest_text = stored.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except ValueError:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def summarize_grades(records: list[dict], page: int=1, page_size: int=10) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    groups = {}
    for record in records:
        if not isinstance(record, dict) or set(record) != {'student', 'score'}:
            raise ValueError('invalid record')
        student = record['student']
        score = record['score']
        if not isinstance(student, str) or not student.strip():
            raise ValueError('invalid student')
        if isinstance(score, bool) or not isinstance(score, (int, float)) or (not 0 <= score <= 100):
            raise ValueError('invalid score')
        groups.setdefault(student, []).append(Decimal(str(score)))
    results = []
    for student, scores in groups.items():
        average = (sum(scores) / len(scores)).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        results.append({'student': student, 'average': float(average), 'attempts': len(scores)})
    results.sort(key=lambda item: (-item['average'], item['student']))
    start = (page - 1) * page_size
    return {'total_students': len(results), 'page': page, 'page_size': page_size, 'results': results[start:start + page_size]}

