import csv
import datetime
import re
import subprocess

def parse_reservation_line(line: str) -> tuple[str, str, int, int, str]:
    try:
        fields = next(csv.reader([line.rstrip('\r\n')]))
    except Exception as exc:
        raise ValueError('invalid reservation') from exc
    if len(fields) != 5:
        raise ValueError('invalid reservation')
    date, desk, start, end, employee = [x.strip() for x in fields]
    if not re.fullmatch('\\d{4}-\\d{2}-\\d{2}', date):
        raise ValueError('invalid reservation')
    try:
        datetime.date.fromisoformat(date)
        start_num = int(start)
        end_num = int(end)
    except Exception as exc:
        raise ValueError('invalid reservation') from exc
    if not desk or not employee or start_num >= end_num:
        raise ValueError('invalid reservation')
    return (date, desk, start_num, end_num, employee)

def build_desk_report(path: str, day: str, opening: int=9, closing: int=18) -> dict:
    try:
        datetime.date.fromisoformat(day)
    except Exception as exc:
        raise ValueError('invalid day') from exc
    if opening >= closing:
        raise ValueError('invalid window')
    completed = subprocess.run(['sort', '-t,', '-k1,1', '-k2,2', '-k3,3n', path], capture_output=True, text=True, check=True)
    reservations = []
    for line in completed.stdout.splitlines():
        if line.strip():
            record = parse_reservation_line(line)
            if record[2] < opening or record[3] > closing:
                raise ValueError('reservation outside window')
            reservations.append(record)
    groups = {}
    for date, desk, start, end, employee in reservations:
        if date == day:
            groups.setdefault(desk, []).append((start, end))
    desks = {}
    for desk in sorted(groups):
        intervals = sorted(groups[desk])
        merged = []
        for start, end in intervals:
            if merged and start <= merged[-1][1]:
                merged[-1] = (merged[-1][0], max(merged[-1][1], end))
            else:
                merged.append((start, end))
        minutes = sum((end - start for start, end in merged))
        desks[desk] = {'reservations': len(intervals), 'minutes': minutes, 'free_minutes': closing - opening - minutes}
    total = sum((item['minutes'] for item in desks.values()))
    busiest = min(desks, key=lambda name: (-desks[name]['minutes'], name)) if desks else None
    return {'day': day, 'opening': opening, 'closing': closing, 'desks': desks, 'total_minutes': total, 'busiest': busiest}

