import ast
import operator

def _evaluate(expression, values):
    tree = ast.parse(expression, mode='eval').body
    allowed = {'height', 'diameter', 'condition', 'days_since_trim'}

    def visit(node):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in allowed:
                raise NameError(node.id)
            return values[node.id]
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
            value = visit(node.operand)
            return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
        if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
            a, b = (visit(node.left), visit(node.right))
            return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](a, b)
        if isinstance(node, ast.BoolOp):
            if isinstance(node.op, ast.And):
                result = visit(node.values[0])
                for part in node.values[1:]:
                    if not result:
                        return result
                    result = visit(part)
                return result
            result = visit(node.values[0])
            for part in node.values[1:]:
                if result:
                    return result
                result = visit(part)
            return result
        if isinstance(node, ast.Compare):
            left = visit(node.left)
            for op, right_node in zip(node.ops, node.comparators):
                right = visit(right_node)
                result = {ast.Lt: left < right, ast.LtE: left <= right, ast.Gt: left > right, ast.GtE: left >= right, ast.Eq: left == right, ast.NotEq: left != right}[type(op)]
                if not result:
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max', 'round'}) and (not node.keywords):
            return {'min': min, 'max': max, 'round': round}[node.func.id](*(visit(arg) for arg in node.args))
        raise ValueError('unsupported expression')
    return visit(tree)

def plan_tree_work(trees: list[dict], expression: str, page: int=1, page_size: int=10) -> dict:
    if page < 1 or page_size < 1:
        raise ValueError('invalid pagination')
    selected = []
    for tree in trees:
        score = _evaluate(expression, tree)
        if score:
            selected.append((tree['id'], score))
    selected.sort(key=lambda item: (-item[1], item[0]))
    total = len(selected)
    pages = (total + page_size - 1) // page_size if total else 0
    start = (page - 1) * page_size
    items = [{'id': ident, 'score': round(score, 2)} for ident, score in selected[start:start + page_size]]
    return {'total': total, 'page': page, 'pages': pages, 'items': items}

