import csv
import os
import zipfile
from decimal import Decimal, InvalidOperation

def process_registration_bundle(zip_path: str, destination: str, members: list[str]) -> list[dict[str, object]]:
    if not isinstance(members, list) or not members:
        if members == []:
            return []
        raise ValueError('members must be a non-empty list')
    if any((not isinstance(member, str) or not member for member in members)):
        raise ValueError('invalid member')
    base = os.path.abspath(destination)
    os.makedirs(base, exist_ok=True)
    totals = {}
    with zipfile.ZipFile(zip_path) as archive:
        available = set(archive.namelist())
        for member in members:
            if member not in available:
                raise ValueError('missing member')
            target = os.path.abspath(os.path.join(base, member))
            if os.path.commonpath([base, target]) != base:
                raise ValueError('invalid member path')
            os.makedirs(os.path.dirname(target), exist_ok=True)
            data = archive.read(member)
            with open(target, 'wb') as output:
                output.write(data)
            try:
                text = data.decode('utf-8')
                rows = list(csv.reader(text.splitlines()))
            except (UnicodeDecodeError, csv.Error):
                raise ValueError('invalid CSV')
            if not rows or rows[0] != ['attendee', 'track', 'fee']:
                raise ValueError('invalid header')
            for row in rows[1:]:
                if len(row) != 3:
                    raise ValueError('invalid row')
                attendee, track, raw_fee = (part.strip() for part in row)
                if not attendee or not track:
                    raise ValueError('invalid row')
                try:
                    fee = Decimal(raw_fee)
                except InvalidOperation:
                    raise ValueError('invalid fee')
                if fee < 0 or fee.as_tuple().exponent < -2:
                    raise ValueError('invalid fee')
                item = totals.setdefault(track, [0, Decimal('0')])
                item[0] += 1
                item[1] += fee
    result = [{'track': track, 'count': values[0], 'total_fee': f'{values[1]:.2f}'} for track, values in totals.items()]
    result.sort(key=lambda item: (-Decimal(item['total_fee']), item['track']))
    return result

