import hashlib
import os
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def hash_password(password: str) -> str:
    salt = os.urandom(16)
    iterations = 100000
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, iterations)
    return f'{iterations}${salt.hex()}${digest.hex()}'

def verify_password(password: str, stored: str) -> bool:
    try:
        iterations_text, salt_text, digest_text = stored.split('$')
        iterations = int(iterations_text)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        raise ValueError('invalid stored password')
    actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, iterations)
    return actual == expected

def settlement_page(records: list[dict], page: int, page_size: int, password: str, stored_password: str) -> list[dict]:
    if not verify_password(password, stored_password):
        raise PermissionError('invalid password')
    if page < 1 or not 1 <= page_size <= 100:
        raise ValueError('invalid pagination')
    groups = {}
    for record in records:
        if record['status'] != 'settled':
            continue
        try:
            amount = Decimal(str(record['amount']))
        except (InvalidOperation, ValueError, TypeError):
            raise ValueError('invalid amount')
        key = (record['account'], record['currency'])
        total, count = groups.get(key, (Decimal('0'), 0))
        groups[key] = (total + amount, count + 1)
    rows = []
    for (account, currency), (total, count) in groups.items():
        rounded = total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        rows.append({'account': account, 'currency': currency, 'total': f'{rounded:.2f}', 'trade_count': count})
    rows.sort(key=lambda row: (-Decimal(row['total']), row['account'], row['currency']))
    start = (page - 1) * page_size
    return rows[start:start + page_size]

