import hashlib
import hmac
import json
import pytest


def signed(value, secret=b"town-secret"):
    payload = json.dumps(value, separators=(",", ":")).encode()
    digest = hmac.new(secret, payload, hashlib.sha256).hexdigest()
    return payload, "sha256=" + digest


def test_verify_valid_payload_and_preserves_structure():
    value = {"applications": [{"id": "Z-1", "nested": {"x": [1, 2]}}], "version": 3}
