    payload, signature = signed({"applications": []})
    for candidate in ["", "sha1=" + signature[7:], signature[:-1], signature.upper(), "sha256=" + "0" * 64]:
        with pytest.raises(ValueError, match="^invalid signature$"):
            verify_webhook(payload, candidate, b"town-secret")


