    payload = b"not json"
    signature = "sha256=" + hmac.new(b"town-secret", payload, hashlib.sha256).hexdigest()
    with pytest.raises(ValueError, match="^invalid payload$"):
        verify_webhook(payload, signature, b"town-secret")


