import datetime
import hashlib
import hmac
import json

def verify_webhook(payload: bytes, signature: str, secret: bytes) -> dict:
    if not isinstance(signature, str) or len(signature) != 71 or (not signature.startswith('sha256=')):
        raise ValueError('invalid signature')
    value = signature[7:]
    if any((c not in '0123456789abcdef' for c in value)):
        raise ValueError('invalid signature')
    expected = hmac.new(secret, payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(value, expected):
        raise ValueError('invalid signature')
    try:
        result = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    if not isinstance(result, dict) or not isinstance(result.get('applications'), list):
        raise ValueError('invalid payload')
    return result

def summarize_applications(applications: list[dict]) -> dict:
    seen = set()
    groups = {}
    ordered = []
    ranks = {'accepted': 0, 'pending': 1, 'denied': 2}
    for app in applications:
        try:
            ident = app['id']
            district = app['district']
            status = app['status']
            units = app['units']
            submitted = app['submitted']
            fees = app['fees']
            if not isinstance(app, dict) or not isinstance(ident, str) or (not ident) or (ident in seen) or (not isinstance(district, str)) or (not district) or (status not in ranks) or isinstance(units, bool) or (not isinstance(units, int)) or (units < 0) or (not isinstance(submitted, str)) or (len(submitted) != 10) or (datetime.date.fromisoformat(submitted).isoformat() != submitted) or (not isinstance(fees, list)) or any((isinstance(x, bool) or not isinstance(x, (int, float)) for x in fees)):
                raise ValueError
        except (KeyError, TypeError, ValueError, OverflowError):
            raise ValueError('invalid application')
        seen.add(ident)
        group = groups.setdefault(district, {'applications': 0, 'units': 0, 'fees': 0.0})
        group['applications'] += 1
        group['units'] += units
        group['fees'] += sum(fees)
        ordered.append((ranks[status], -units, submitted, ident))
    by_district = {}
    for district in sorted(groups):
        group = groups[district]
        by_district[district] = {'applications': group['applications'], 'units': group['units'], 'fees': round(group['fees'], 2)}
    ordered.sort()
    return {'by_district': by_district, 'priority': [x[3] for x in ordered]}

