_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'

def generate_ack_code(length: int=10) -> str:
    if isinstance(length, bool) or not isinstance(length, int) or length < 4 or (length > 64):
        raise ValueError('invalid length')
    return ''.join((secrets.choice(_ALPHABET) for _ in range(length)))

def parse_donation(line: str) -> dict[str, object]:
    try:
        rows = list(csv.reader(io.StringIO(line), strict=True))
    except (csv.Error, TypeError):
        raise ValueError('invalid CSV')
    if len(rows) != 1 or len(rows[0]) != 4:
        raise ValueError('invalid donation')
    donor, campaign, amount_text, date_text = (x.strip() for x in rows[0])
    if not donor or not campaign:
        raise ValueError('blank name')
    try:
        amount = Decimal(amount_text)
    except (InvalidOperation, ValueError):
        raise ValueError('invalid amount')
    if not amount.is_finite() or amount <= 0 or amount.as_tuple().exponent < -2:
        raise ValueError('invalid amount')
    try:
        parsed_date = date.fromisoformat(date_text)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    return {'donor': donor, 'campaign': campaign, 'amount': amount, 'date': parsed_date}

def summarize_donations(lines: list[str], as_of: str, window_days: int=30) -> list[dict[str, object]]:
    try:
        end = date.fromisoformat(as_of)
    except (TypeError, ValueError):
        raise ValueError('invalid as_of')
    if isinstance(window_days, bool) or not isinstance(window_days, int) or (not 0 <= window_days <= 3650):
        raise ValueError('invalid window')
    start = end - timedelta(days=window_days)
    groups = {}
    for line in lines:
        item = parse_donation(line)
        if not start <= item['date'] <= end:
            continue
        key = item['donor'].casefold()
        if key not in groups:
            groups[key] = {'donor': item['donor'], 'total': Decimal('0'), 'count': 0, 'campaigns': [], 'latest': item['date']}
        group = groups[key]
        group['total'] += item['amount']
        group['count'] += 1
        if item['campaign'] not in group['campaigns']:
            group['campaigns'].append(item['campaign'])
        if item['date'] > group['latest']:
            group['latest'] = item['date']
    return sorted(groups.values(), key=lambda x: (-x['total'], x['donor'].casefold(), x['donor']))

