def load_applications(data: str) -> list[dict]:
    required = ['application_id', 'applicant_id', 'tenant_id', 'submitted', 'bedrooms', 'household_size', 'priority', 'status']
    if not data:
        return []
    try:
        reader = csv.DictReader(io.StringIO(data))
        if reader.fieldnames is None or any((x not in reader.fieldnames for x in required)):
            raise ValueError('missing column')
        result = []
        for raw in reader:
            if None in raw:
                raise ValueError('malformed row')
            row = {k: raw[k].strip() for k in required}
            if not row['application_id']:
                raise ValueError('blank id')
            try:
                row['submitted'] = date.fromisoformat(row['submitted'])
                row['bedrooms'] = int(row['bedrooms'])
                row['household_size'] = int(row['household_size'])
                row['priority'] = int(row['priority'])
            except (TypeError, ValueError):
                raise ValueError('bad field')
            result.append(row)
        return result
    except csv.Error as exc:
        raise ValueError('malformed csv') from exc

def rank_waitlist(applications: list[dict], as_of: date) -> list[dict]:
    selected = []
    for item in applications:
        try:
            fields = (item['submitted'], item['priority'], item['household_size'], item['application_id'], item['status'])
        except KeyError as exc:
            raise ValueError('missing ranking field') from exc
        if fields[4] == 'pending' and fields[0] <= as_of:
            selected.append(dict(item))
    selected.sort(key=lambda x: (-x['priority'], x['submitted'], -x['household_size'], x['application_id']))
    return selected

def allocate_unit(requester: dict, application_id: str, applications: list[dict], units: list[dict]) -> dict:
    app = next((x for x in applications if x.get('application_id') == application_id), None)
    if app is None:
        raise KeyError(application_id)
    if app.get('status') != 'pending':
        raise ValueError('application is not pending')
    if not isinstance(app.get('bedrooms'), int) or app['bedrooms'] <= 0:
        raise ValueError('invalid bedrooms')
    if not (requester.get('tenant_id') == app.get('tenant_id') and (requester.get('id') == app.get('applicant_id') or 'caseworker' in requester.get('roles', []) or 'admin' in requester.get('roles', []))):
        raise PermissionError('not permitted')
    seen = set()
    choices = []
    for unit in units:
        try:
            uid, tenant, bedrooms, rent, available = (unit['unit_id'], unit['tenant_id'], unit['bedrooms'], unit['rent'], unit['available'])
            if uid in seen or not isinstance(bedrooms, int) or (not isinstance(rent, (int, float))):
                raise ValueError('invalid unit')
            seen.add(uid)
        except KeyError as exc:
            raise ValueError('invalid unit') from exc
        if available is True and tenant == app.get('tenant_id') and (bedrooms >= app['bedrooms']):
            choices.append(unit)
    if not choices:
        raise LookupError('no unit')
    unit = min(choices, key=lambda x: (x['bedrooms'] - app['bedrooms'], x['rent'], str(x['unit_id'])))
    unit['available'] = False
    app['status'] = 'offered'
    app['unit_id'] = unit['unit_id']
    app['offered_to'] = app['applicant_id']
    return {'application_id': application_id, 'unit_id': unit['unit_id'], 'applicant_id': app['applicant_id'], 'rent': unit['rent']}

