import ast
import operator

def _evaluate(node, names):
    if isinstance(node, ast.Expression):
        return _evaluate(node.body, names)
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in names:
            raise NameError(node.id)
        return names[node.id]
    if isinstance(node, ast.BinOp) and type(node.op) in {ast.Add, ast.Sub, ast.Mult, ast.Div}:
        left = _evaluate(node.left, names)
        right = _evaluate(node.right, names)
        return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
    if isinstance(node, ast.UnaryOp) and type(node.op) in {ast.UAdd, ast.USub, ast.Not}:
        value = _evaluate(node.operand, names)
        return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
    if isinstance(node, ast.BoolOp) and type(node.op) in {ast.And, ast.Or}:
        value = _evaluate(node.values[0], names)
        for item in node.values[1:]:
            if isinstance(node.op, ast.And) and (not value) or (isinstance(node.op, ast.Or) and value):
                return value
            value = _evaluate(item, names)
        return value
    if isinstance(node, ast.Compare):
        left = _evaluate(node.left, names)
        for op, part in zip(node.ops, node.comparators):
            right = _evaluate(part, names)
            if not {ast.Lt, ast.LtE, ast.Gt, ast.GtE, ast.Eq, ast.NotEq}.__contains__(type(op)):
                raise ValueError('unsupported expression')
            if not {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}[type(op)](left, right):
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max', 'round'}) and (not node.keywords):
        return {'min': min, 'max': max, 'round': round}[node.func.id](*[_evaluate(x, names) for x in node.args])
    raise ValueError('unsupported expression')

def rank_exchange_rates(records: list[dict], rule: str, page: int=1, page_size: int=10) -> list[dict]:
    if not isinstance(page, int) or isinstance(page, bool) or page <= 0 or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (page_size <= 0):
        raise ValueError('page and page_size must be positive integers')
    try:
        tree = ast.parse(rule, mode='eval')
    except (SyntaxError, TypeError) as exc:
        raise ValueError('invalid rule') from exc
    selected = []
    for record in records:
        names = {key: record[key] for key in ('rate', 'amount', 'fee')}
        if _evaluate(tree, names):
            item = {key: record[key] for key in ('pair', 'rate', 'amount', 'fee')}
            item['proceeds'] = round(record['amount'] * record['rate'] - record['fee'], 2)
            selected.append(item)
    selected.sort(key=lambda item: (-item['proceeds'], item['pair']))
    start = (page - 1) * page_size
