def _fields(line):
    out = []
    cur = []
    escaped = False
    for ch in line:
        if escaped:
            if ch not in ('\\', '|'):
                raise ValueError('invalid escape')
            cur.append(ch)
            escaped = False
        elif ch == '\\':
            escaped = True
        elif ch == '|':
            out.append(''.join(cur))
            cur = []
        else:
            cur.append(ch)
    if escaped:
        raise ValueError('invalid escape')
    out.append(''.join(cur))
    return out

def parse_itinerary(text: str) -> list[dict]:
    if not isinstance(text, str):
        raise TypeError('text must be a string')
