def parse_requests(text: str) -> list[dict]:
    out = []
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith('#'):
            continue
        fields = [x.strip() for x in line.split(',')]
        if len(fields) != 5 or not fields[0]:
            raise ValueError('invalid request')
        try:
            start = int(fields[1])
            duration = int(fields[2])
            priority = int(fields[3])
            requested = None if fields[4] == '' else int(fields[4])
        except ValueError as exc:
            raise ValueError('invalid request') from exc
        if start < 0 or duration <= 0:
            raise ValueError('invalid interval')
        out.append({'service': fields[0], 'start': start, 'duration': duration, 'priority': priority, 'requested_port': requested})
    return out

def schedule_requests(requests: list[dict], port_start: int, port_end: int) -> list[dict]:
    if port_start > port_end:
        raise ValueError('invalid port range')
    used = {}
    assigned = []
    order = sorted(enumerate(requests), key=lambda x: (x[1]['start'], -x[1]['priority'], x[0]))
    for _, req in order:
        begin = req['start']
        finish = begin + req['duration']
        candidates = [req['requested_port']] if req['requested_port'] is not None else []
        candidates += list(range(port_start, port_end + 1))
        port = None
        for candidate in candidates:
            if candidate < port_start or candidate > port_end or (candidate in used and any((begin < end and start < finish for start, end in used[candidate]))):
                continue
            port = candidate
            break
        if port is None:
            raise ValueError('no available port')
        used.setdefault(port, []).append((begin, finish))
        assigned.append({'service': req['service'], 'start': begin, 'duration': req['duration'], 'priority': req['priority'], 'port': port})
    return sorted(assigned, key=lambda x: (x['start'], x['port'], x['service']))

