import ast

def _evaluate(node, names):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in names:
            raise NameError(node.id)
        return names[node.id]
    if isinstance(node, ast.BinOp):
        a = _evaluate(node.left, names)
        b = _evaluate(node.right, names)
        ops = {ast.Add: lambda: a + b, ast.Sub: lambda: a - b, ast.Mult: lambda: a * b, ast.Div: lambda: a / b, ast.Mod: lambda: a % b}
        for kind, operation in ops.items():
            if isinstance(node.op, kind):
                return operation()
    if isinstance(node, ast.UnaryOp):
        value = _evaluate(node.operand, names)
        if isinstance(node.op, ast.USub):
            return -value
        if isinstance(node.op, ast.UAdd):
            return value
        if isinstance(node.op, ast.Not):
            return not value
    if isinstance(node, ast.BoolOp):
        if isinstance(node.op, ast.And):
            value = True
            for item in node.values:
                value = _evaluate(item, names)
                if not value:
                    return value
            return value
        value = False
        for item in node.values:
            value = _evaluate(item, names)
            if value:
                return value
        return value
    if isinstance(node, ast.Compare):
        left = _evaluate(node.left, names)
        for operation, right_node in zip(node.ops, node.comparators):
            right = _evaluate(right_node, names)
            checks = {ast.Eq: left == right, ast.NotEq: left != right, ast.Lt: left < right, ast.LtE: left <= right, ast.Gt: left > right, ast.GtE: left >= right}
            matched = next((value for kind, value in checks.items() if isinstance(operation, kind)), None)
            if matched is None:
                raise ValueError('unsupported expression')
            if not matched:
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max', 'round'}) and (not node.keywords):
        args = [_evaluate(arg, names) for arg in node.args]
        return {'min': min, 'max': max, 'round': round}[node.func.id](*args)
    raise ValueError('unsupported expression')

