def _parse_time(value):
    if not isinstance(value, str):
        raise ValueError('invalid time')
    try:
        return datetime.datetime.strptime(value, '%H:%M').time()
    except (TypeError, ValueError):
        raise ValueError('invalid time')

def normalize_shifts(records):
    result = []
    seen = set()
    try:
        iterator = iter(records)
    except TypeError:
        raise ValueError('records must be iterable')
    for item in iterator:
        if not hasattr(item, '__getitem__'):
            raise ValueError('invalid record')
        try:
            employee = item['employee']
            date = item['date']
            start = item['start']
            end = item['end']
            role = item['role']
        except (KeyError, TypeError):
            raise ValueError('missing field')
        if not isinstance(employee, str) or not employee or (not isinstance(role, str)) or (not role):
            raise ValueError('invalid text')
        if not isinstance(date, str):
            raise ValueError('invalid date')
        try:
            datetime.datetime.strptime(date, '%Y-%m-%d')
        except ValueError:
            raise ValueError('invalid date')
        st = _parse_time(start)
        en = _parse_time(end)
        sm = st.hour * 60 + st.minute
        em = en.hour * 60 + en.minute
        if em <= sm:
            raise ValueError('end must follow start')
        key = (employee, date, start)
        if key in seen:
            raise ValueError('duplicate shift')
        seen.add(key)
