    rows = normalize_shifts(records)
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as handle:
            writer = csv.DictWriter(handle, fieldnames=['employee', 'date', 'start', 'end', 'role', 'duration_minutes'])
            writer.writeheader()
            writer.writerows(rows)
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return sum((row['duration_minutes'] for row in rows))

