def create_credential(password: str) -> str:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    if not password:
        raise ValueError('password must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return 'v1$' + base64.b64encode(salt).decode() + '$' + digest.hex()

def verify_credential(stored: str, password: str) -> bool:
    if not isinstance(stored, str) or not isinstance(password, str) or (not password):
        return False
    try:
