        if version != 'v1':
            return False
        salt = base64.b64decode(salt_text, validate=True)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def trace_summary(records: list[dict], stored: str, password: str) -> list[dict]:
    if not verify_credential(stored, password):
        raise PermissionError('authentication failed')
    groups = {}
    seen = set()
    statuses = {'harvested', 'inspected', 'packed', 'released'}
