def analyze_soil_samples(xml_text: str, page: int=1, page_size: int=10) -> dict:
    if not isinstance(xml_text, str):
        raise ValueError('xml_text must be a string')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml_text.encode('utf-8'), parser=parser)
        if root.tag != 'samples':
            raise ValueError('invalid root')
        rows = []
        seen = set()
        for node in root:
            if node.tag != 'sample':
                raise ValueError('invalid child')
            required = {'id', 'field', 'depth_cm', 'ph', 'nitrogen_mg_kg'}
            if set(node.attrib) != required:
                raise ValueError('invalid attributes')
            ident = node.attrib['id']
            field = node.attrib['field']
            if not ident or not field or ident in seen:
                raise ValueError('invalid id or field')
            depth = float(node.attrib['depth_cm'])
            ph = float(node.attrib['ph'])
            nitrogen = float(node.attrib['nitrogen_mg_kg'])
            if not all((math.isfinite(x) for x in (depth, ph, nitrogen))) or not 0 <= depth <= 100 or nitrogen < 0:
                raise ValueError('invalid number')
            seen.add(ident)
            rows.append({'id': ident, 'field': field, 'depth_cm': depth, 'ph': ph, 'nitrogen_mg_kg': nitrogen})
    except ValueError:
        raise
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    rows.sort(key=lambda x: (-x['nitrogen_mg_kg'], x['id']))
    count = len(rows)
    total_pages = (count + page_size - 1) // page_size
    start = (page - 1) * page_size
    return {'samples': rows[start:start + page_size], 'count': count, 'average_ph': round(sum((x['ph'] for x in rows)) / count, 2) if count else None, 'total_nitrogen_mg_kg': round(sum((x['nitrogen_mg_kg'] for x in rows)), 2), 'page': page, 'page_size': page_size, 'total_pages': total_pages}

