import pytest


def signed(payload, secret):
    return hmac.new(secret, payload, hashlib.sha256).hexdigest()


def make_payload(tasks):
    return json.dumps({"tasks": tasks}, separators=(",", ":")).encode()


def test_sorts_filters_and_aggregates_all_tasks():
    tasks = [
        {"id": "b", "crew": "Earthworks", "start": "2025-04-03", "duration": 2.5, "status": "scheduled"},
        {"id": "a", "crew": "Earthworks", "start": "2025-04-03", "duration": 1.25, "status": "completed"},
        {"id": "z", "crew": "Concrete", "start": "2025-04-01", "duration": 4, "status": "cancelled"},
        {"id": "c", "crew": "Concrete", "start": "2025-04-02", "duration": 3.333, "status": "in_progress"},
    ]
    payload = make_payload(tasks)
    result = process_schedule(payload, signed(payload, b"key"), b"key")
    assert result == {
        "total": 3,
        "page": 1,
        "page_size": 20,
        "tasks": [
            {"id": "c", "crew": "Concrete", "start": "2025-04-02", "duration": 3.333, "status": "in_progress"},
            {"id": "a", "crew": "Earthworks", "start": "2025-04-03", "duration": 1.25, "status": "completed"},
            {"id": "b", "crew": "Earthworks", "start": "2025-04-03", "duration": 2.5, "status": "scheduled"},
        ],
        "crew_hours": {"Concrete": 3.33, "Earthworks": 3.75},
    }


def test_pagination_and_page_beyond_end():
    tasks = [
        {"id": str(i), "crew": "Crew", "start": "2025-01-%02d" % (i + 1), "duration": 1, "status": "scheduled"}
        for i in range(5)
    ]
    payload = make_payload(tasks)
    signature = signed(payload, b"s")
    result = process_schedule(payload, signature, b"s", page=2, page_size=2)
    assert result["page"] == 2
    assert result["page_size"] == 2
    assert [task["id"] for task in result["tasks"]] == ["2", "3"]
    assert result["total"] == 5
    assert result["crew_hours"] == {"Crew": 5.0}
    result = process_schedule(payload, signature, b"s", page=4, page_size=2)
    assert result["tasks"] == []


def test_empty_schedule():
    payload = make_payload([])
    result = process_schedule(payload, signed(payload, b"empty"), b"empty")
    assert result == {"total": 0, "page": 1, "page_size": 20, "tasks": [], "crew_hours": {}}


def test_invalid_signature_is_rejected():
    payload = make_payload([])
    with pytest.raises(ValueError):
        process_schedule(payload, "0" * 64, b"secret")


