import datetime
import hashlib
import hmac
import json
import math

def process_schedule(payload: bytes, signature: str, secret: bytes, page: int=1, page_size: int=20) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('invalid pagination')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('invalid pagination')
    if not isinstance(payload, bytes) or not isinstance(signature, str) or (not isinstance(secret, bytes)):
        raise ValueError('invalid input')
    expected = hmac.new(secret, payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    try:
        document = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    if not isinstance(document, dict) or not isinstance(document.get('tasks'), list):
        raise ValueError('invalid tasks')
    tasks = []
    for item in document['tasks']:
        if not isinstance(item, dict):
            raise ValueError('invalid task')
        if not isinstance(item.get('id'), str) or not item['id']:
            raise ValueError('invalid id')
        if not isinstance(item.get('crew'), str) or not item['crew']:
            raise ValueError('invalid crew')
        start = item.get('start')
        if not isinstance(start, str):
            raise ValueError('invalid date')
        try:
            datetime.date.fromisoformat(start)
        except ValueError:
            raise ValueError('invalid date')
        duration = item.get('duration')
        if isinstance(duration, bool) or not isinstance(duration, (int, float)) or (not math.isfinite(duration)) or (duration <= 0):
            raise ValueError('invalid duration')
        if item.get('status') not in {'scheduled', 'in_progress', 'completed', 'cancelled'}:
            raise ValueError('invalid status')
        if item['status'] != 'cancelled':
            tasks.append({'id': item['id'], 'crew': item['crew'], 'start': start, 'duration': duration, 'status': item['status']})
    tasks.sort(key=lambda x: (x['start'], x['id']))
    totals = {}
    for task in tasks:
        totals[task['crew']] = totals.get(task['crew'], 0) + task['duration']
    first = (page - 1) * page_size
    selected = tasks[first:first + page_size]
    return {'total': len(tasks), 'page': page, 'page_size': page_size, 'tasks': selected, 'crew_hours': {k: round(totals[k], 2) for k in sorted(totals)}}

