        group[item['status'] + '_cases'] += 1
        group['total_hours'] += item['hours']
        group['tags'].update(item['tags'])
    result = []
    for worker, group in grouped.items():
        result.append({'worker': worker, 'open_cases': group['open_cases'], 'closed_cases': group['closed_cases'], 'total_hours': group['total_hours'], 'tags': sorted(group['tags'])})
