import subprocess
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def available_entry_slots(schedule_path: str, max_price: float, page: int, page_size: int) -> list[dict]:
    if not isinstance(max_price, (int, float)) or not math.isfinite(max_price) or max_price < 0:
        raise ValueError('invalid max price')
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    result = subprocess.run(['sort', '-t', '|', '-k2,2', '-k1,1', schedule_path], capture_output=True, text=True, check=True)
    limit = Decimal(str(max_price))
    records = []
    for raw in result.stdout.splitlines():
        if not raw.strip():
            continue
        fields = raw.split('|')
        if len(fields) != 4:
            raise ValueError('malformed record')
        attraction, time, capacity_text, price_text = fields
        parts = time.split(':')
        if len(parts) != 2 or len(parts[0]) != 2 or len(parts[1]) != 2:
            raise ValueError('invalid time')
        try:
            hour, minute = (int(parts[0]), int(parts[1]))
            capacity = int(capacity_text)
            price = Decimal(price_text)
        except (ValueError, InvalidOperation):
            raise ValueError('invalid record')
        if hour > 23 or minute > 59 or capacity < 0 or (not price.is_finite()) or (price < 0):
            raise ValueError('invalid record')
        if capacity > 0 and price <= limit:
            records.append({'attraction': attraction, 'time': time, 'capacity': capacity, 'price': float(price.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))})
    start = (page - 1) * page_size
    return records[start:start + page_size]

