import csv
import os
import tempfile

def export_route_summary(deliveries: list[dict], output_path: str, min_stops: int=0) -> str:
    if isinstance(min_stops, bool) or not isinstance(min_stops, int) or min_stops < 0:
        raise ValueError('min_stops must be a non-negative integer')
    routes = {}
    fields = {'route_id', 'driver', 'distance_km', 'stops', 'revenue', 'completed'}
    for record in deliveries:
        if not isinstance(record, dict) or set(record) != fields:
            raise ValueError('invalid delivery record')
        route_id = record['route_id']
        driver = record['driver']
        distance = record['distance_km']
        stops = record['stops']
        revenue = record['revenue']
        completed = record['completed']
        if not isinstance(route_id, str) or not route_id or (not isinstance(driver, str)) or (not driver):
            raise ValueError('invalid delivery record')
        if isinstance(distance, bool) or not isinstance(distance, (int, float)) or distance < 0:
            raise ValueError('invalid delivery record')
        if isinstance(revenue, bool) or not isinstance(revenue, (int, float)) or revenue < 0:
            raise ValueError('invalid delivery record')
        if isinstance(stops, bool) or not isinstance(stops, int) or stops < 0 or (not isinstance(completed, bool)):
            raise ValueError('invalid delivery record')
        if route_id not in routes:
            routes[route_id] = [driver, 0, 0.0, 0.0, 0, 0]
        row = routes[route_id]
        if row[0] != driver:
            raise ValueError('inconsistent driver')
        row[1] += stops
        row[2] += distance
        row[3] += revenue
        row[4] += 1
        row[5] += int(completed)
    rows = [['route_id', 'driver', 'stops', 'distance_km', 'revenue', 'completion_rate']]
    for route_id in sorted(routes):
        driver, stops, distance, revenue, count, complete = routes[route_id]
        if stops >= min_stops:
            rows.append([route_id, driver, str(stops), f'{distance:.2f}', f'{revenue:.2f}', f'{complete / count * 100:.2f}'])
    directory = os.path.dirname(os.path.abspath(output_path))
    fd, temporary_path = tempfile.mkstemp(dir=directory, prefix='.route-summary-')
    os.close(fd)
    try:
        with open(temporary_path, 'w', encoding='utf-8', newline='') as handle:
            csv.writer(handle, lineterminator='\n').writerows(rows)
        os.replace(temporary_path, output_path)
    finally:
        if os.path.exists(temporary_path):
            os.unlink(temporary_path)
    return output_path

