    if not isinstance(requester, dict) or not isinstance(hospitals, list) or (not isinstance(hospital_id, str)) or (not isinstance(beds, int)) or isinstance(beds, bool):
        raise TypeError()
    if not hospital_id or beds <= 0:
        raise ValueError()
    hospital = next((item for item in hospitals if isinstance(item, dict) and item.get('hospital_id') == hospital_id), None)
    if hospital is None:
        raise ValueError()
    if not all((isinstance(hospital.get(key), int) and (not isinstance(hospital.get(key), bool)) for key in ('capacity', 'occupied'))):
        raise ValueError()
    capacity = hospital['capacity']
    occupied = hospital['occupied']
    if capacity <= 0 or occupied < 0 or occupied > capacity:
        raise ValueError()
    if requester.get('tenant_id') != hospital.get('tenant_id'):
        raise PermissionError()
    if requester.get('user_id') != hospital.get('owner_user_id') and requester.get('role') not in {'capacity_manager', 'regional_dispatcher'}:
        raise PermissionError()
    if occupied + beds > capacity:
        raise ValueError()
    hospital['occupied'] = occupied + beds
    available = capacity - hospital['occupied']
    return {'hospital_id': hospital_id, 'occupied': hospital['occupied'], 'available': available, 'utilization': round(hospital['occupied'] / capacity, 3)}

