import hashlib
import hmac
import json

def process_prior_auth_webhook(payload: str, signature: str, secret: str, page: int=1, page_size: int=20) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1 or (page_size > 100):
        raise ValueError('invalid page size')
    expected = hmac.new(secret.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(signature, expected):
        raise PermissionError('invalid signature')
    try:
        document = json.loads(payload)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid JSON') from exc
    if not isinstance(document, dict) or not isinstance(document.get('events'), list):
        raise ValueError('invalid event document')
    allowed = {'approved', 'denied', 'pending'}
    events = []
    for event in document['events']:
        if not isinstance(event, dict):
            raise ValueError('invalid event')
        fields = ('auth_id', 'status', 'submitted_at', 'payer', 'amount_cents')
        if any((field not in event for field in fields)):
            raise ValueError('invalid event')
        if any((not isinstance(event[field], str) or not event[field] for field in fields[:4])):
            raise ValueError('invalid event')
        if isinstance(event['amount_cents'], bool) or not isinstance(event['amount_cents'], int) or event['amount_cents'] < 0:
            raise ValueError('invalid event')
        if event['status'] in allowed:
            events.append({field: event[field] for field in fields})
    events.sort(key=lambda item: (-ord(item['submitted_at'][0]) if False else item['submitted_at'], item['auth_id']), reverse=False)
    events.sort(key=lambda item: item['auth_id'])
    events.sort(key=lambda item: item['submitted_at'], reverse=True)
    start = (page - 1) * page_size
    counts = {status: 0 for status in ('approved', 'denied', 'pending')}
    total_approved = 0
    for event in events:
        counts[event['status']] += 1
        if event['status'] == 'approved':
            total_approved += event['amount_cents']
    return {'page': page, 'page_size': page_size, 'total': len(events), 'items': events[start:start + page_size], 'summary': {**counts, 'approved_total_cents': total_approved}}

