    if name.endswith('.'):
        name = name[:-1]
    if not name or len(name) > 253 or '.' not in name:
        raise ValueError('invalid domain')
    name = name.lower()
    parts = name.split('.')
    if any((not p or len(p) > 63 or (not re.fullmatch('[a-z0-9](?:[a-z0-9-]*[a-z0-9])?', p)) for p in parts)):
        raise ValueError('invalid domain')
    return name

def process_domain_changes(requester: dict, registry: dict, changes: list[dict]) -> tuple[dict, list[dict]]:
    if not isinstance(requester, dict) or not isinstance(registry, dict) or (not isinstance(changes, list)):
        raise ValueError('invalid input')
    work = {}
    for key, value in registry.items():
        domain = canonical_domain(key)
        if domain in work or not isinstance(value, dict):
            raise ValueError('invalid registry')
        needed = ('owner', 'tenant', 'expires', 'nameservers', 'auto_renew')
        if any((k not in value for k in needed)) or not isinstance(value['owner'], str) or (not isinstance(value['tenant'], str)) or (not isinstance(value['auto_renew'], bool)):
            raise ValueError('invalid record')
        try:
            datetime.date.fromisoformat(value['expires'])
        except Exception:
            raise ValueError('invalid date')
        if not isinstance(value['nameservers'], list):
            raise ValueError('invalid nameservers')
        for ns in value['nameservers']:
            canonical_domain(ns)
        work[domain] = copy.deepcopy(value)
    for change in changes:
        if not isinstance(change, dict) or 'action' not in change or 'domain' not in change:
            raise ValueError('invalid change')
        domain = canonical_domain(change['domain'])
        if domain not in work:
            raise ValueError('unknown domain')
        record = work[domain]
        action = change['action']
        receipt = {'action': action, 'domain': domain}
        if action == 'renew':
            years = change.get('years')
            if type(years) is not int or not 1 <= years <= 10:
                raise ValueError('invalid years')
            old = datetime.date.fromisoformat(record['expires'])
            try:
                new = old.replace(year=old.year + years)
            except ValueError:
                new = old.replace(year=old.year + years, day=28)
            record['expires'] = new.isoformat()
            receipt['expires'] = record['expires']
        elif action == 'nameservers':
            servers = change.get('nameservers')
            if not isinstance(servers, list) or not 2 <= len(servers) <= 8:
                raise ValueError('invalid nameservers')
            servers = sorted((canonical_domain(x) for x in servers))
            if len(set(servers)) != len(servers):
                raise ValueError('duplicate nameservers')
            record['nameservers'] = servers
            receipt['nameservers'] = servers
        elif action == 'auto_renew':
            if type(change.get('enabled')) is not bool:
                raise ValueError('invalid setting')
            record['auto_renew'] = change['enabled']
            receipt['enabled'] = change['enabled']
        else:
            raise ValueError('unknown action')
        if action not in ('renew', 'nameservers', 'auto_renew'):
            raise ValueError('unknown action')
        if not isinstance(receipt, dict):
            raise ValueError('invalid receipt')
        if action == 'nameservers' and len(record['nameservers']) < 2:
            raise ValueError('invalid nameservers')
        if 'receipts' not in locals():
            receipts = []
        receipts.append(receipt)
    return ({k: work[k] for k in sorted(work)}, locals().get('receipts', []))

