import csv
from datetime import datetime

def parse_flight_log(text: str) -> list[dict]:
    lines = [x for x in text.splitlines() if x.strip()]
    if not lines or lines[0] != 'timestamp,flight,phase,fuel':
        raise ValueError('invalid header')
    out = []
    for f in csv.reader(lines[1:]):
        if len(f) != 4:
            raise ValueError('invalid row')
        stamp, flight, phase, fuel = f
        if not flight or not phase:
            raise ValueError('empty field')
        try:
            ts = datetime.fromisoformat(stamp[:-1] + '+00:00' if stamp.endswith('Z') else stamp)
            value = float(fuel)
        except (TypeError, ValueError):
            raise ValueError('invalid value')
        if value < 0:
            raise ValueError('negative fuel')
        out.append({'timestamp': ts, 'flight': flight, 'phase': phase, 'fuel': value})
    return out

def build_flight_report(requester: dict, aircraft: dict, text: str) -> dict:
    if requester['tenant_id'] != aircraft['tenant_id'] and 'safety_manager' not in requester['roles'] or (requester['id'] != aircraft['owner_id'] and 'safety_manager' not in requester['roles']):
        raise PermissionError('not permitted')
    groups = {}
    for r in parse_flight_log(text):
        groups.setdefault(r['flight'], []).append(r)
    fs = []
    for name, items in groups.items():
        v = [x for _, x in sorted(enumerate(items), key=lambda z: (z[1]['timestamp'], z[0]))]
        a, b = (v[0], v[-1])
        fs.append({'flight': name, 'start': a['timestamp'].isoformat().replace('+00:00', 'Z'), 'end': b['timestamp'].isoformat().replace('+00:00', 'Z'), 'duration_seconds': int((b['timestamp'] - a['timestamp']).total_seconds()), 'fuel_used': round(a['fuel'] - b['fuel'], 3), 'phases': [x['phase'] for x in v]})
    fs.sort(key=lambda x: (x['start'], x['flight']))
    return {'aircraft_id': aircraft['id'], 'model': aircraft['model'], 'flights': fs}

