def aggregate_workouts(conn, athlete_id, start_date, end_date, sort_by='date', limit=50, offset=0):
    if not isinstance(athlete_id, str):
        raise TypeError('athlete_id must be a string')
    if type(limit) is not int or type(offset) is not int:
        raise TypeError('limit and offset must be integers')
    if limit < 0 or offset < 0:
        raise ValueError('limit and offset must not be negative')
    try:
        start = datetime.date.fromisoformat(start_date)
        end = datetime.date.fromisoformat(end_date)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if start > end:
        raise ValueError('reversed date range')
    columns = {'date': 'workout_date', 'sessions': 'sessions', 'duration': 'total_minutes', 'calories': 'total_calories'}
    if sort_by not in columns:
        raise ValueError('invalid sort')
    query = f'SELECT workout_date AS date, COUNT(*) AS sessions,\n        SUM(duration_minutes) AS total_minutes,\n        SUM(calories) AS total_calories\n        FROM workouts\n        WHERE athlete_id = ? AND workout_date >= ? AND workout_date <= ?\n        GROUP BY workout_date\n        ORDER BY {columns[sort_by]} ASC, workout_date ASC\n        LIMIT ? OFFSET ?'
    rows = conn.execute(query, (athlete_id, start_date, end_date, limit, offset)).fetchall()
    return [dict(zip(('date', 'sessions', 'total_minutes', 'total_calories'), row)) for row in rows]

