import csv
import io
import math
import os
import zipfile
from datetime import datetime

def parse_trace_rows(text: str) -> list[dict]:
    reader = csv.reader(io.StringIO(text))
    rows = [r for r in reader if any((x.strip() for x in r))]
    if not rows or rows[0] != ['batch_id', 'timestamp', 'quantity_kg', 'temperature_c']:
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if len(row) != 4:
            raise ValueError('invalid row')
        batch, stamp, quantity, temperature = row
        batch = batch.strip()
        if not batch:
            raise ValueError('invalid batch')
        try:
            dt = datetime.fromisoformat(stamp[:-1] + '+00:00' if stamp.endswith('Z') else stamp)
            q = int(quantity)
            t = float(temperature)
        except (ValueError, TypeError):
            raise ValueError('invalid value')
        if q < 0 or not math.isfinite(t):
            raise ValueError('invalid value')
        result.append({'batch_id': batch, 'timestamp': dt.isoformat(), 'quantity_kg': q, 'temperature_c': t})
    return result

def summarize_batches(records: list[dict]) -> list[dict]:
    groups = {}
    for record in records:
        groups.setdefault(record['batch_id'], []).append(record)
    result = []
    for batch in sorted(groups):
        values = groups[batch]
        temperatures = [r['temperature_c'] for r in values]
        result.append({'batch_id': batch, 'total_quantity_kg': sum((r['quantity_kg'] for r in values)), 'average_temperature_c': round(sum(temperatures) / len(temperatures), 2), 'peak_temperature_c': max(temperatures), 'event_count': len(values)})
    return result

def process_trace_archive(base_dir: str, archive_path: str) -> list[dict]:
    base = os.path.realpath(base_dir)
    records = []
    with zipfile.ZipFile(archive_path) as archive:
        for info in sorted(archive.infolist(), key=lambda x: x.filename):
            if info.is_dir() or not info.filename.lower().endswith('.csv'):
                continue
            destination = os.path.realpath(os.path.join(base, info.filename))
            if os.path.commonpath([base, destination]) != base:
                raise ValueError('archive member outside base directory')
            os.makedirs(os.path.dirname(destination), exist_ok=True)
            with open(destination, 'wb') as output:
                output.write(archive.read(info))
            with open(destination, 'r', encoding='utf-8', newline='') as source:
                records.extend(parse_trace_rows(source.read()))
    return summarize_batches(records)

