    spans = [
        {"trace_id": "x", "span_id": "1", "service": "api", "duration_ms": 4, "owner_id": "u", "tenant_id": "t"},
        {"trace_id": "x", "span_id": "2", "service": "db", "duration_ms": 9, "owner_id": "u", "tenant_id": "t"},
