def summarize_traces(requester: dict, spans: list[dict], service: str | None=None, page: int=1, page_size: int=20) -> dict:
    if not isinstance(requester, dict) or not isinstance(spans, list):
        raise ValueError('invalid input')
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    for key in ('id', 'tenant_id', 'role'):
        if not isinstance(requester.get(key), str) or not requester[key]:
            raise ValueError('invalid requester')
    groups = {}
    for span in spans:
        if not isinstance(span, dict):
            raise ValueError('invalid span')
        for key in ('trace_id', 'span_id', 'service', 'owner_id', 'tenant_id'):
            if not isinstance(span.get(key), str) or not span[key]:
                raise ValueError('invalid span')
        duration = span.get('duration_ms')
        if isinstance(duration, bool) or not isinstance(duration, (int, float)) or duration < 0:
            raise ValueError('invalid duration')
        if service is not None and span['service'] != service:
            continue
        if span['tenant_id'] != requester['tenant_id'] or (requester['role'] != 'admin' and span['owner_id'] != requester['id']):
            raise PermissionError('not permitted')
        group = groups.setdefault(span['trace_id'], {'duration': 0, 'count': 0, 'services': set()})
        group['duration'] += duration
        group['count'] += 1
        group['services'].add(span['service'])
    rows = [{'trace_id': key, 'span_count': value['count'], 'duration_ms': round(value['duration'], 2), 'services': sorted(value['services'])} for key, value in groups.items()]
    rows.sort(key=lambda row: (-row['duration_ms'], row['trace_id']))
    start = (page - 1) * page_size
    return {'total_traces': len(rows), 'page': page, 'page_size': page_size, 'traces': rows[start:start + page_size]}

