import base64
import hashlib
import hmac
import os

def hash_access_secret(secret: str) -> str:
    if not isinstance(secret, str):
        raise TypeError('secret must be a string')
    if not secret:
        raise ValueError('secret must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
    return base64.b64encode(salt + digest).decode('ascii')

def verify_access_secret(stored: str, candidate: str) -> bool:
    if not isinstance(stored, str) or not isinstance(candidate, str):
        return False
    try:
        raw = base64.b64decode(stored.encode('ascii'), validate=True)
        if len(raw) != 48:
            return False
        salt, expected = (raw[:16], raw[16:])
        actual = hashlib.pbkdf2_hmac('sha256', candidate.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, UnicodeEncodeError):
        return False

def summarize_print_orders(records: list[dict], page: int, page_size: int) -> list[dict]:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    groups = {}
    required = {'id', 'publication', 'pages', 'rate', 'status'}
    for record in records:
        if not isinstance(record, dict) or set(record) != required:
            raise ValueError('invalid record')
