            raise ValueError('invalid record')
        if isinstance(record['pages'], bool) or not isinstance(record['pages'], int) or record['pages'] <= 0:
            raise ValueError('invalid record')
        if isinstance(record['rate'], bool) or not isinstance(record['rate'], (int, float)):
            raise ValueError('invalid record')
        if record['status'] == 'approved':
            name = record['publication']
            item = groups.setdefault(name, [0, 0, 0.0])
            item[0] += 1
            item[1] += record['pages']
