import hashlib
import hmac
import json
import math
import os

def hash_sync_secret(secret: str) -> str:
    if not isinstance(secret, str):
        raise TypeError('secret must be a string')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def verify_sync_secret(secret: str, stored: str) -> bool:
    if not isinstance(secret, str):
        raise TypeError('secret must be a string')
    if not isinstance(stored, str) or '$' not in stored:
        return False
    salt_text, digest_text = stored.split('$', 1)
    try:
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except ValueError:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def sync_catalog(payload: str, category: str | None=None, page: int=1, page_size: int=2) -> dict:
    if category is not None and (not isinstance(category, str)):
        raise TypeError('category must be a string or None')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
    try:
        records = json.loads(payload)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid JSON') from exc
    if not isinstance(records, list):
        raise ValueError('catalog must be a list')
    required = {'id', 'name', 'category', 'price', 'stock'}
    for item in records:
        if not isinstance(item, dict) or not required.issubset(item):
