import string

def generate_invite_code(length: int=10) -> str:
    if not isinstance(length, int) or isinstance(length, bool) or (not 6 <= length <= 64):
        raise ValueError('invalid length')
    alphabet = string.ascii_uppercase + string.digits
    return ''.join((secrets.choice(alphabet) for _ in range(length)))

def build_shift_invites(shifts: list[dict], employee_ids: list[str], page: int=1, page_size: int=20) -> list[dict]:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    records = []
    required = {'id', 'employee_id', 'start', 'end', 'status'}
    for shift in shifts:
        if not isinstance(shift, dict) or not required.issubset(shift):
            raise ValueError('invalid shift')
        if not all((isinstance(shift[key], str) for key in required)):
            raise ValueError('invalid shift')
        try:
            start = datetime.datetime.fromisoformat(shift['start'].replace('Z', '+00:00'))
            end = datetime.datetime.fromisoformat(shift['end'].replace('Z', '+00:00'))
        except (TypeError, ValueError):
            raise ValueError('invalid datetime')
        if end <= start:
            raise ValueError('invalid duration')
        if shift['status'] == 'open' and shift['employee_id'] in employee_ids:
            hours = round((end - start).total_seconds() / 3600, 2)
