import hashlib
import hmac

def verify_record(payload: bytes, signature: str, secret: bytes) -> bool:
    if not isinstance(signature, str) or not signature.startswith('sha256='):
        return False
    text = signature[7:]
    if len(text) != 64 or any((c not in '0123456789abcdef' for c in text)):
        return False
    try:
        supplied = bytes.fromhex(text)
    except ValueError:
        return False
    expected = hmac.new(secret, payload, hashlib.sha256).digest()
    return hmac.compare_digest(supplied, expected)

def _fields(payload: str) -> list[str]:
    fields = []
    current = []
    i = 0
    while i < len(payload):
        c = payload[i]
        if c == '\\':
            i += 1
            if i == len(payload):
                raise ValueError('escape')
            c = payload[i]
            if c == '|':
                current.append('|')
            elif c == '\\':
                current.append('\\')
            elif c == 'n':
                current.append('\n')
            else:
                raise ValueError('escape')
        elif c == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(c)
        i += 1
    fields.append(''.join(current))
    if len(fields) != 4:
        raise ValueError('fields')
    return fields

def process_delivery_feed(feed: str, secret: bytes) -> list[dict[str, object]]:
    latest = {}
    statuses = {'PICKED', 'IN_TRANSIT', 'DELIVERED', 'FAILED'}
    for line in feed.splitlines():
        if not line:
            continue
        if line.count('\t') != 1:
            raise ValueError('line')
        signature, payload = line.split('\t')
        if not verify_record(payload.encode('utf-8'), signature, secret):
            raise ValueError('signature')
        timestamp, package_id, status, note = _fields(payload)
        if not timestamp.isdigit() or package_id == '' or status not in statuses:
            raise ValueError('record')
        record = {'timestamp': int(timestamp), 'package_id': package_id, 'status': status, 'note': note}
        old = latest.get(package_id)
        if old is None or record['timestamp'] >= old['timestamp']:
            latest[package_id] = record
    return sorted(latest.values(), key=lambda r: (r['timestamp'], r['package_id']))

