        if end > 1440:
            raise ValueError('late assignment')
        record['_start'] = start
        record['_end'] = end
        records.append(record)
    by_vehicle = {}
    for record in records:
        prior = by_vehicle.setdefault(record['vehicle'], [])
        if any((record['_start'] < x['_end'] and x['_start'] < record['_end'] for x in prior)):
