_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
_HEADER = ['order_id', 'senior', 'zone', 'window', 'items']
_WINDOW = re.compile('^(\\d{2}):(\\d{2})-(\\d{2}):(\\d{2})$')

def generate_invite_code(length: int=10) -> str:
    if type(length) is not int or not 6 <= length <= 32:
        raise ValueError('invalid code length')
    return ''.join((secrets.choice(_ALPHABET) for _ in range(length)))

def _time_value(value: str) -> int:
    match = _WINDOW.fullmatch(value)
    if not match:
        raise ValueError('invalid window')
    h1, m1, h2, m2 = (int(x) for x in match.groups())
    start = h1 * 60 + m1
    end = h2 * 60 + m2
    if h1 > 23 or h2 > 23 or m1 > 59 or (m2 > 59) or (end <= start):
        raise ValueError('invalid window')
