    for record in records:
        required = {'order_id', 'sku', 'category', 'returned_at', 'quantity', 'refund_cents', 'reason'}
        if set(record) != required:
            raise ValueError('invalid record')
        for key in ('order_id', 'sku', 'category', 'reason'):
            if not isinstance(record[key], str) or not record[key]:
                raise ValueError('invalid record')
        if isinstance(record['quantity'], bool) or not isinstance(record['quantity'], int) or record['quantity'] <= 0:
            raise ValueError('invalid quantity')
        if isinstance(record['refund_cents'], bool) or not isinstance(record['refund_cents'], int) or record['refund_cents'] < 0:
            raise ValueError('invalid refund')
        day = _date(record['returned_at'])
        if start <= day <= end:
            key = (record['category'], record['reason'])
            item = groups.setdefault(key, {'category': key[0], 'reason': key[1], 'return_count': 0, 'units': 0, 'refund_cents': 0})
            item['return_count'] += 1
            item['units'] += record['quantity']
            item['refund_cents'] += record['refund_cents']
    return sorted(groups.values(), key=lambda x: (-x['units'], -x['refund_cents'], x['category'], x['reason']))

