import os
import tempfile


def make_file(contents):
    handle = tempfile.NamedTemporaryFile(mode="w", encoding="utf-8", delete=False)
    try:
        handle.write(contents)
        return handle.name
    finally:
        handle.close()


def test_filters_day_and_cancelled_records():
    path = make_file(
        "2025-04-02\t09:00\tMilo\tAnn\tscheduled\n"
        "2025-04-01\t10:00\tPip\tBob\tscheduled\n"
        "2025-04-02\t11:00\tRex\tCara\tcancelled\n"
        "2025-04-02\t12:00\tLuna\tDan\tconfirmed\n"
    )
    try:
        assert list_appointments(path, "2025-04-02", 10) == [
            {"date": "2025-04-02", "time": "09:00", "pet": "Milo", "owner": "Ann", "status": "scheduled"},
            {"date": "2025-04-02", "time": "12:00", "pet": "Luna", "owner": "Dan", "status": "confirmed"},
        ]
    finally:
        os.unlink(path)


def test_sorts_by_time_then_pet():
    path = make_file(
        "2025-04-02\t14:00\tZed\tO1\tscheduled\n"
        "2025-04-02\t08:30\tBoo\tO2\tscheduled\n"
        "2025-04-02\t08:30\tAce\tO3\tscheduled\n"
    )
    try:
        result = list_appointments(path, "2025-04-02", 5)
        assert [(item["time"], item["pet"]) for item in result] == [
            ("08:30", "Ace"), ("08:30", "Boo"), ("14:00", "Zed")
        ]
    finally:
        os.unlink(path)


def test_limit_and_zero_boundary():
    path = make_file(
        "2025-04-02\t09:00\tA\tO\tscheduled\n"
        "2025-04-02\t10:00\tB\tO\tscheduled\n"
        "2025-04-02\t11:00\tC\tO\tscheduled\n"
    )
    try:
        assert [x["pet"] for x in list_appointments(path, "2025-04-02", 2)] == ["A", "B"]
        assert list_appointments(path, "2025-04-02", 0) == []
        assert len(list_appointments(path, "2025-04-02", 10)) == 3
    finally:
        os.unlink(path)


def test_blank_file_and_blank_lines():
    path = make_file("\n  \n")
    try:
        assert list_appointments(path, "2025-04-02", 4) == []
    finally:
        os.unlink(path)


def test_invalid_record_raises_value_error():
    path = make_file("2025-04-02\t09:00\tMilo\tAnn\n")
    try:
        try:
            list_appointments(path, "2025-04-02", 4)
            assert False
        except ValueError:
            pass
    finally:
        os.unlink(path)


def test_invalid_day_and_limit_raise_value_error():
    path = make_file("2025-04-02\t09:00\tMilo\tAnn\tscheduled\n")
