        for day in ("2025-02-30", "04-02-2025", ""):
            try:
                list_appointments(path, day, 1)
                assert False
            except ValueError:
                pass
        for limit in (-1, 1.5, True):
            try:
                list_appointments(path, "2025-04-02", limit)
                assert False
            except ValueError:
                pass
    finally:
        os.unlink(path)


