        fields = line.split('\t')
        if len(fields) != 5:
            raise ValueError('invalid record')
        record = dict(zip(('date', 'time', 'pet', 'owner', 'status'), fields))
        if record['date'] == day and record['status'] != 'cancelled':
            appointments.append(record)
    return appointments[:limit]

