import base64
import hashlib
import hmac
import os
from datetime import date
from decimal import Decimal, InvalidOperation

def hash_password(password: str) -> str:
    if not isinstance(password, str) or not password:
        raise ValueError('password must be non-empty')
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return base64.b64encode(salt).decode() + '$' + base64.b64encode(value).decode()

def verify_password(password: str, stored: str) -> bool:
    if not isinstance(password, str) or not password:
        raise ValueError('password must be non-empty')
    try:
        salt_text, value_text = stored.split('$', 1)
        salt = base64.b64decode(salt_text.encode(), validate=True)
        expected = base64.b64decode(value_text.encode(), validate=True)
    except (AttributeError, ValueError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def build_client_report(records: list[dict], start_date: str, end_date: str, page: int, page_size: int) -> list[dict]:
    try:
        start = date.fromisoformat(start_date)
        end = date.fromisoformat(end_date)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if end < start or isinstance(page, bool) or isinstance(page_size, bool) or (page <= 0) or (page_size <= 0):
        raise ValueError('invalid range or pagination')
    grouped = {}
    for record in records:
        try:
            client = record['client']
            record_date = date.fromisoformat(record['date'])
            amount = Decimal(str(record['amount']))
            if not isinstance(client, str) or not client or isinstance(record['amount'], bool) or (amount < 0) or (not amount.is_finite()):
                raise ValueError
        except (KeyError, TypeError, ValueError, InvalidOperation):
            raise ValueError('invalid record')
        if start <= record_date <= end:
            item = grouped.setdefault(client, [Decimal('0'), 0])
            item[0] += amount
            item[1] += 1
    ordered = sorted(grouped.items(), key=lambda pair: (-pair[1][0], pair[0]))
    first = (page - 1) * page_size
    return [{'client': name, 'transaction_count': data[1], 'total': f'{data[0]:.2f}'} for name, data in ordered[first:first + page_size]]

