from datetime import date, timedelta
import math

def _permit(permits, pid):
    if pid not in permits:
        raise KeyError(pid)
    p = permits[pid]
    if not isinstance(p, dict) or not isinstance(p.get('withdrawals'), list) or (not isinstance(p.get('daily_limit'), (int, float))) or (not math.isfinite(p['daily_limit'])) or (p['daily_limit'] <= 0):
        raise ValueError('invalid permit')
    return p

def _day(value):
    try:
        return date.fromisoformat(value)
    except Exception as exc:
        raise ValueError('invalid date') from exc

def _allowed(requester, p):
    return requester.get('tenant_id') == p.get('tenant_id') and (requester.get('id') == p.get('owner_id') or requester.get('role') == 'water_officer')

def record_withdrawal(requester, permits, permit_id, volume, day):
    p = _permit(permits, permit_id)
    if not _allowed(requester, p):
        raise PermissionError('not permitted')
    d = _day(day)
    if not isinstance(volume, (int, float)) or isinstance(volume, bool) or (not math.isfinite(volume)) or (volume <= 0):
        raise ValueError('invalid volume')
    if p.get('status') != 'active':
        raise ValueError('inactive permit')
    entries = p['withdrawals']
    daily = sum((x['volume'] for x in entries if _day(x['day']) == d)) + volume
    weekly = sum((x['volume'] for x in entries if d - timedelta(days=6) <= _day(x['day']) <= d)) + volume
    if daily > p['daily_limit'] or weekly > 7 * p['daily_limit']:
        raise ValueError('limit exceeded')
    entries.append({'day': day, 'volume': volume})
    return {'permit_id': permit_id, 'day': day, 'volume': volume, 'daily_total': daily, 'seven_day_total': weekly}

def compliance_report(requester, permits, start, end):
    lo, hi = (_day(start), _day(end))
    if lo > hi:
        raise ValueError('invalid range')
    out = []
    for pid, p in permits.items():
        _permit(permits, pid)
        if not _allowed(requester, p):
            continue
        selected = [(x['day'], x['volume']) for x in p['withdrawals'] if lo <= _day(x['day']) <= hi]
        totals = {}
        for day, volume in selected:
            totals[day] = totals.get(day, 0) + volume
        peak = min(totals, key=lambda x: (-totals[x], x)) if totals else None
        out.append({'permit_id': pid, 'owner_id': p['owner_id'], 'tenant_id': p['tenant_id'], 'withdrawal_count': len(selected), 'total_volume': sum((x[1] for x in selected)), 'peak_day': peak})
    return sorted(out, key=lambda x: (-x['total_volume'], x['permit_id']))

def transfer_permit(requester, permits, permit_id, new_owner_id):
    p = _permit(permits, permit_id)
    if not _allowed(requester, p):
        raise PermissionError('not permitted')
    if not isinstance(new_owner_id, str) or not new_owner_id:
        raise ValueError('invalid owner')
    previous = p.get('owner_id')
    if not previous:
        raise KeyError('owner_id')
    p['owner_id'] = new_owner_id
    return {'permit_id': permit_id, 'previous_owner_id': previous, 'owner_id': new_owner_id}

