import datetime
import xml.etree.ElementTree as ET

def _date(value):
    try:
        return datetime.date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def _text(parent, tag):
    node = parent.find(tag)
    if node is None or node.text is None or (not node.text.strip()):
        raise ValueError('missing field')
    return node.text.strip()

def _integer(value, low, high):
    try:
        if not value or str(int(value)) != value:
            raise ValueError
        number = int(value)
    except (TypeError, ValueError):
        raise ValueError('invalid number')
    if not low <= number <= high:
        raise ValueError('number out of range')
    return number

def parse_application(xml_text: str) -> dict:
    try:
        root = ET.fromstring(xml_text)
    except Exception as exc:
        raise ValueError('invalid xml') from exc
    if root.tag != 'application' or not root.get('id'):
        raise ValueError('invalid application')
    veteran = root.find('veteran')
    if veteran is None:
        raise ValueError('missing veteran')
    name = _text(veteran, 'name')
    service = veteran.find('service')
    if service is None or not service.get('start') or (not service.get('end')):
        raise ValueError('missing service')
    start, end = (_date(service.get('start')), _date(service.get('end')))
    days = (end - start).days
    if days <= 0:
        raise ValueError('invalid service interval')
    dependents = root.find('dependents')
    if dependents is None:
        raise ValueError('missing dependents')
    dep_count = minor_count = 0
    today = datetime.date(2025, 1, 1)
    for node in dependents.findall('dependent'):
        birth = _date(node.get('birth'))
        if birth > today:
            raise ValueError('invalid birth date')
        age = today.year - birth.year - ((today.month, today.day) < (birth.month, birth.day))
        dep_count += 1
        minor_count += age < 18
    conditions_node = root.find('conditions')
    if conditions_node is None:
        raise ValueError('missing conditions')
    conditions, seen = ([], set())
    for node in conditions_node.findall('condition'):
        code = node.get('code', '').strip()
        if not code or code in seen:
            raise ValueError('invalid condition')
        seen.add(code)
        conditions.append({'code': code, 'rating': _integer(node.get('rating'), 0, 100)})
    conditions.sort(key=lambda x: x['code'])
    combined = 0
    for item in sorted(conditions, key=lambda x: x['rating']):
        combined += round((100 - combined) * item['rating'] / 100)
    request = root.find('request')
    if request is None or not request.get('type', '').strip():
