import datetime
import hashlib
import hmac
import json
import math

def _nps(counts):
    total = sum(counts.values())
    if total == 0:
        return 0
    value = (counts['promoters'] - counts['detractors']) * 100 / total
    return math.floor(value + 0.5) if value >= 0 else math.ceil(value - 0.5)

def aggregate_nps(records: list[dict], config: dict[str, str]) -> dict:
    latest = {}
    for index, record in enumerate(records):
        if not isinstance(record, dict):
            raise ValueError('record is missing a required field')
        try:
            respondent = record['respondent']
            score = record['score']
            segment = record['segment']
            raw_time = record['timestamp']
        except KeyError:
            raise ValueError('record is missing a required field')
        if not isinstance(respondent, str) or not respondent:
            raise ValueError('respondent must be non-empty')
        if not isinstance(segment, str) or not segment:
            raise ValueError('segment must be non-empty')
        if isinstance(score, bool) or not isinstance(score, int) or (not 0 <= score <= 10):
            raise ValueError('score must be an integer from 0 through 10')
        if not isinstance(raw_time, str) or (not raw_time.endswith('Z') and '+' not in raw_time and ('-' not in raw_time[10:])):
            raise ValueError('timestamp must be ISO 8601')
        try:
            parsed = datetime.datetime.fromisoformat(raw_time[:-1] + '+00:00' if raw_time.endswith('Z') else raw_time)
        except ValueError:
            raise ValueError('timestamp must be ISO 8601')
        if parsed.tzinfo is None:
            raise ValueError('timestamp must include a timezone')
        item = (parsed, index, score, segment)
        if respondent not in latest or (parsed, index) >= latest[respondent][:2]:
            latest[respondent] = item
    groups = {}
    overall = {'promoters': 0, 'passives': 0, 'detractors': 0}
    for parsed, index, score, segment in latest.values():
        bucket = 'promoters' if score >= 9 else 'passives' if score >= 7 else 'detractors'
        groups.setdefault(segment, {'promoters': 0, 'passives': 0, 'detractors': 0})[bucket] += 1
        overall[bucket] += 1
    result = {'respondents': len(latest), **overall, 'nps': _nps(overall), 'segments': []}
    for name in sorted(groups):
        counts = groups[name]
        result['segments'].append({'name': name, 'respondents': sum(counts.values()), **counts, 'nps': _nps(counts)})
    return result

def sign_nps_report(records: list[dict], config: dict[str, str]) -> str:
    if 'NPS_SIGNING_KEY' not in config:
        raise ValueError('NPS_SIGNING_KEY is required')
    report = aggregate_nps(records, config)
    encoded = json.dumps(report, separators=(',', ':'), ensure_ascii=False)
    signature = hmac.new(config['NPS_SIGNING_KEY'].encode('utf-8'), encoded.encode('utf-8'), hashlib.sha256).hexdigest()
    return json.dumps({'report': report, 'signature': signature}, separators=(',', ':'), ensure_ascii=False)

