import math
import os

def hash_password(password: str) -> str:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    if not password:
        raise ValueError('password must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return salt.hex() + ':' + digest.hex()

def verify_password(password: str, stored: str) -> bool:
    if not isinstance(password, str) or not isinstance(stored, str):
        raise TypeError('arguments must be strings')
    try:
        salt_text, digest_text = stored.split(':')
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def allocate_utilities(records: list[dict], budget: float, page: int=1, page_size: int=10) -> list[dict]:
    if not isinstance(budget, (int, float)) or isinstance(budget, bool) or (not math.isfinite(budget)) or (budget < 0):
        raise ValueError('invalid budget')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
