import math
import pytest


def test_register_and_authenticate_round_trip():
    users = {}
    register_user(users, "alice", "correct horse", 51.5, -0.1, 10.0, 2)
    assert authenticate(users, "alice", "correct horse") is True
    assert authenticate(users, "alice", "wrong horse") is False
    assert authenticate(users, "missing", "correct horse") is False


def test_registration_validation_and_duplicate():
    users = {}
    with pytest.raises(ValueError):
        register_user(users, "", "abcdefgh", 0, 0, 1, 1)
    with pytest.raises(ValueError):
        register_user(users, "a b", "abcdefgh", 0, 0, 1, 1)
    with pytest.raises(ValueError):
        register_user(users, "a", "short", 0, 0, 1, 1)
    with pytest.raises(ValueError):
        register_user(users, "a", "abcdefgh", 91, 0, 1, 1)
    with pytest.raises(ValueError):
        register_user(users, "a", "abcdefgh", 0, 181, 1, 1)
    with pytest.raises(ValueError):
        register_user(users, "a", "abcdefgh", 0, 0, -1, 1)
    with pytest.raises(ValueError):
        register_user(users, "a", "abcdefgh", 0, 0, 1, 6)
    register_user(users, "a", "abcdefgh", 0, 0, 1, 1)
    with pytest.raises(ValueError):
        register_user(users, "a", "abcdefgh", 0, 0, 1, 1)


def test_alert_distance_severity_and_window():
    users = {}
    register_user(users, "near", "password1", 0, 0, 20, 3)
    events = [
        {"id": "low", "timestamp": 10, "latitude": 0, "longitude": 0, "severity": 2},
        {"id": "near", "timestamp": 11, "latitude": 0, "longitude": 0.1, "severity": 3},
        {"id": "far", "timestamp": 12, "latitude": 1, "longitude": 1, "severity": 5},
        {"id": "end", "timestamp": 20, "latitude": 0, "longitude": 0, "severity": 5},
    ]
    assert process_alerts(users, events, 10, 20) == [(11, "near", "near", 3)]


def test_ordering_uses_timestamp_username_and_distance():
    users = {}
    register_user(users, "zeta", "password1", 0, 0, 100, 1)
    register_user(users, "alpha", "password2", 0, 0, 100, 1)
    events = [
        {"id": "b", "timestamp": 5, "latitude": 0, "longitude": 0.2, "severity": 1},
        {"id": "a", "timestamp": 5, "latitude": 0, "longitude": 0.1, "severity": 1},
    ]
    assert process_alerts(users, events, 0, 10) == [
        (5, "alpha", "a", 1), (5, "zeta", "a", 1),
        (5, "alpha", "b", 1), (5, "zeta", "b", 1)
    ]


def test_alerts_are_not_repeated_across_calls():
    users = {}
    register_user(users, "u", "password1", 0, 0, 5, 1)
    event = {"id": "x", "timestamp": 3, "latitude": 0, "longitude": 0, "severity": 5}
    assert process_alerts(users, [event], 0, 10) == [(3, "u", "x", 5)]
    assert process_alerts(users, [event], 0, 10) == []


def test_duplicate_ids_choose_first_chronological_match():
    users = {}
    register_user(users, "u", "password1", 0, 0, 10, 1)
    events = [
        {"id": "x", "timestamp": 8, "latitude": 0, "longitude": 0, "severity": 2},
        {"id": "x", "timestamp": 4, "latitude": 0, "longitude": 0, "severity": 4},
    ]
    assert process_alerts(users, events, 0, 10) == [(4, "u", "x", 4)]


