    bad = {"id": "bad", "timestamp": 2, "latitude": 0, "longitude": 0, "severity": 9}
    with pytest.raises(ValueError):
        process_alerts(users, [good, bad], 0, 10)
    assert process_alerts(users, [good], 0, 10) == [(1, "u", "good", 1)]


