    fields = {'published_at': 'published_at', 'title': 'title', 'duration_seconds': 'duration_seconds', 'id': 'id'}
    if sort_by not in fields:
        raise ValueError('invalid sort field')
    sql = "SELECT id, show_id, title, description, status, published_at, duration_seconds FROM episodes WHERE status IN ('ready','published')"
    args = []
    if show_id is not None:
        sql += ' AND show_id = ?'
        args.append(show_id)
    if search:
        sql += ' AND (lower(title) LIKE lower(?) OR lower(description) LIKE lower(?))'
        args.extend(['%' + search + '%', '%' + search + '%'])
    direction = ' DESC' if descending else ' ASC'
    null_order = '(published_at IS NULL) ASC, ' if sort_by == 'published_at' else ''
    sql += ' ORDER BY ' + null_order + fields[sort_by] + direction + ', id ASC'
