def summarize_translation_project(xml_text: str, target_language: str, page: int=1, page_size: int=10) -> dict:
    if not isinstance(xml_text, str) or not isinstance(target_language, str) or (not target_language):
        raise ValueError('invalid arguments')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError('invalid page size')
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml_text.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'project' or root.get('name') is None:
        raise ValueError('invalid project')
    selected = []
    for document in root.findall('document'):
        document_name = document.get('name')
        if document_name is None:
            raise ValueError('invalid document')
        for unit in document.findall('unit'):
            if unit.get('id') is None:
                raise ValueError('invalid unit')
            if unit.get('status', '') != 'complete':
                continue
            match = next((x for x in unit.findall('translation') if x.get('language') == target_language), None)
            if match is None:
                continue
            value = match.get('words')
            try:
                words = int(value) if value is not None else None
            except (TypeError, ValueError):
                words = None
            if words is None or words < 0 or str(words) != value:
                raise ValueError('invalid words')
            selected.append({'id': unit.get('id'), 'document': document_name, 'words': words})
    selected.sort(key=lambda item: (-item['words'], item['id']))
    total = len(selected)
    total_words = sum((item['words'] for item in selected))
