def build_wind_forecast_schedule(user: dict, sites: list[dict], forecasts: list[dict], start_hour: int, horizon: int) -> list[dict]:
    if type(start_hour) is not int or start_hour < 0 or start_hour > 23:
        raise ValueError('invalid start_hour')
    if type(horizon) is not int or horizon < 0 or horizon > 48:
        raise ValueError('invalid horizon')
    if not isinstance(user, dict) or not isinstance(sites, list) or (not isinstance(forecasts, list)):
        raise ValueError('invalid input')
    required_user = ('id', 'tenant_id', 'roles')
    if any((k not in user for k in required_user)) or not isinstance(user['roles'], list):
        raise ValueError('invalid user')
    site_map = {}
    for site in sites:
        if not isinstance(site, dict) or any((k not in site for k in ('id', 'tenant_id', 'owner_id'))):
            raise ValueError('invalid site')
        if site['id'] in site_map:
            raise ValueError('duplicate site')
        site_map[site['id']] = site
    grouped = {}
    for forecast in forecasts:
        if not isinstance(forecast, dict) or any((k not in forecast for k in ('site_id', 'hour', 'wind_kph', 'direction'))):
            raise ValueError('invalid forecast')
        if forecast['site_id'] not in site_map or type(forecast['hour']) is not int or (not 0 <= forecast['hour'] <= 23):
            raise ValueError('invalid forecast')
        if isinstance(forecast['wind_kph'], bool) or not isinstance(forecast['wind_kph'], (int, float)):
            raise ValueError('invalid wind')
        site = site_map[forecast['site_id']]
        allowed = site['owner_id'] == user['id'] or ('planner' in user['roles'] and site['tenant_id'] == user['tenant_id'])
        if not allowed:
            continue
        if start_hour <= forecast['hour'] < start_hour + horizon:
            key = (forecast['site_id'], forecast['hour'])
            grouped.setdefault(key, []).append(forecast)
    result = []
    for site_id, hour in sorted(grouped):
        items = grouped[site_id, hour]
        average = round(sum((x['wind_kph'] for x in items)) / len(items), 1)
        peak = max((x['wind_kph'] for x in items))
        direction = next((x['direction'] for x in items if x['wind_kph'] == peak))
        risk = 'HIGH' if average >= 40 else 'MEDIUM' if average >= 20 else 'LOW'
        result.append({'site_id': site_id, 'hour': hour, 'wind_kph': average, 'direction': direction, 'risk': risk})
    return result

