import hashlib
import hmac
import json

def verify_webhook(payload: str, signature: str, secret: str) -> dict:
    if len(signature) != 64 or any((c not in '0123456789abcdef' for c in signature)):
        raise ValueError('invalid signature')
    expected = hmac.new(secret.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    try:
        value = json.loads(payload)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(value, dict) or not isinstance(value.get('events'), list):
        raise ValueError('invalid payload')
    return value

def dispatch_rides(payload: str, signature: str, secret: str, now: int) -> list[dict]:
    data = verify_webhook(payload, signature, secret)
    best = {}
    for event in data['events']:
        if not isinstance(event, dict):
            continue
        required = ('ride_id', 'driver_id', 'eta_minutes', 'distance_km', 'status', 'timestamp')
        if any((key not in event for key in required)):
            continue
        ride = event['ride_id']
        driver = event['driver_id']
        eta = event['eta_minutes']
        distance = event['distance_km']
        timestamp = event['timestamp']
        if not isinstance(ride, str) or not ride or (not isinstance(driver, str)) or (not driver):
            continue
        if event['status'] != 'available':
            continue
        if isinstance(timestamp, bool) or not isinstance(timestamp, int) or (not now - 300 <= timestamp <= now):
            continue
        if isinstance(eta, bool) or not isinstance(eta, int) or (not 1 <= eta <= 60):
            continue
        if isinstance(distance, bool) or not isinstance(distance, (int, float)) or distance <= 0:
            continue
        candidate = (eta, distance, driver, {'ride_id': ride, 'driver_id': driver, 'eta_minutes': eta, 'distance_km': distance})
        if ride not in best or candidate[:3] < best[ride][:3]:
            best[ride] = candidate
    chosen = []
    used = set()
    for candidate in sorted(best.values(), key=lambda x: (x[0], x[1], x[3]['ride_id'], x[2])):
        if candidate[2] not in used:
            used.add(candidate[2])
            chosen.append(candidate[3])
    return sorted(chosen, key=lambda x: x['ride_id'])

