import hashlib
import json

def issue_credential(requester: dict, subject_id: str, requested_claims: list[str], identities: list[dict]) -> dict:
    if not isinstance(subject_id, str) or not subject_id:
        raise ValueError('invalid subject')
    if not isinstance(requested_claims, list):
        raise TypeError('claims must be a list')
    if not requested_claims:
        raise ValueError('claims cannot be empty')
    if any((not isinstance(name, str) for name in requested_claims)):
        raise TypeError('claim names must be strings')
    if any((not name for name in requested_claims)):
        raise ValueError('claim names cannot be empty')
    if len(set(requested_claims)) != len(requested_claims):
        raise ValueError('duplicate claim')
    matches = [item for item in identities if item.get('id') == subject_id]
    if len(matches) != 1:
        raise ValueError('identity not unique')
    identity = matches[0]
    if identity.get('status') != 'active':
        raise ValueError('identity is not active')
    roles = requester.get('roles', [])
    same_tenant = requester.get('tenant_id') == identity.get('tenant_id')
    is_owner = requester.get('id') == identity.get('owner_id')
    is_issuer = 'issuer' in roles and same_tenant
    if not (is_owner or is_issuer):
        raise PermissionError('not permitted')
    claims = {}
    for name in requested_claims:
        if name not in identity.get('attributes', {}):
            raise KeyError(name)
        claims[name] = identity['attributes'][name]
    payload = {'issuer_id': requester['id'], 'subject_id': subject_id, 'tenant_id': identity['tenant_id'], 'claims': claims}
    credential_id = hashlib.sha256(json.dumps(payload, sort_keys=True, separators=(',', ':')).encode('utf-8')).hexdigest()
    return {'credential_id': credential_id, 'issuer_id': requester['id'], 'subject_id': subject_id, 'tenant_id': identity['tenant_id'], 'claims': claims}

