        rid, prop, guest, start, end, cents = row
        if rid in seen:
            raise ValueError('duplicate id')
        try:
            first = date.fromisoformat(start)
            last = date.fromisoformat(end)
            rate = int(cents)
        except Exception as exc:
            raise ValueError('invalid value') from exc
        if last <= first or rate < 0:
            raise ValueError('invalid reservation')
        seen.add(rid)
        result.append({'reservation_id': rid, 'property': prop, 'guest': guest, 'check_in': first, 'check_out': last, 'nightly_cents': rate})
    return result

