    for record in records:
        current = record['check_in']
        while current < record['check_out']:
            key = (record['property'], current.strftime('%Y-%m'))
            if key not in totals:
                totals[key] = [0, 0]
            totals[key][0] += 1
            totals[key][1] += record['nightly_cents']
