            for row in summary:
                writer.writerow([row['property'], row['month'], row['nights'], row['revenue_cents']])
        os.replace(temporary, output_path)
        return len(summary)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise

