import subprocess
from pathlib import Path

def load_location_alerts(directory: str, phrase: str, minimum_level: str='low', page: int=1, page_size: int=10) -> list[dict]:
    levels = {'low': 0, 'medium': 1, 'high': 2, 'critical': 3}
    if not phrase or minimum_level not in levels or page < 1 or (page_size < 1):
        raise ValueError()
    root = Path(directory)
    if not root.exists():
        raise FileNotFoundError(directory)
    if not root.is_dir():
        raise NotADirectoryError(directory)
    files = sorted((p for p in root.iterdir() if p.is_file() and p.name.endswith('.alert')))
    if not files:
        return []
    result = subprocess.run(['grep', '-F', '-H', '-n', phrase, '--', *[str(p) for p in files]], capture_output=True, text=True, check=False)
    if result.returncode not in (0, 1):
        raise ValueError()
    found = []
    for raw in result.stdout.splitlines():
        filename, number, content = raw.split(':', 2)
        fields = content.split(',', 4)
        if len(fields) != 5:
            raise ValueError()
        timestamp, latitude, longitude, level, message = fields
        if level not in levels:
            raise ValueError()
        try:
            latitude = float(latitude)
            longitude = float(longitude)
        except ValueError as exc:
            raise ValueError() from exc
        if levels[level] < levels[minimum_level]:
            continue
        found.append((timestamp, -levels[level], filename, int(number), {'timestamp': timestamp, 'latitude': latitude, 'longitude': longitude, 'level': level, 'message': message}))
    found.sort(key=lambda item: item[:4])
    start = (page - 1) * page_size
    return [item[4] for item in found[start:start + page_size]]

