import csv
import datetime
import os
import zipfile
from collections import defaultdict

def _inside(base, name):
    b = os.path.realpath(base)
    p = os.path.realpath(os.path.join(b, name))
    if os.path.commonpath([b, p]) != b:
        raise ValueError('path outside base')
    return p

def extract_daily_reports(base_dir: str, archive_name: str, destination_name: str) -> list[str]:
    archive = _inside(base_dir, archive_name)
    destination = _inside(base_dir, destination_name)
    os.makedirs(destination, exist_ok=True)
    names = []
    with zipfile.ZipFile(archive) as z:
        for info in z.infolist():
            if info.is_dir():
                continue
            target = _inside(destination, info.filename)
            os.makedirs(os.path.dirname(target), exist_ok=True)
            with z.open(info) as src, open(target, 'wb') as dst:
                dst.write(src.read())
            names.append(info.filename.replace('\\', '/'))
    return sorted(names)

def summarize_production(base_dir: str, report_names: list[str], window_days: int=3) -> list[dict[str, object]]:
    if window_days <= 0:
        raise ValueError('window')
    data = {}
    for name in report_names:
        path = _inside(base_dir, name)
        with open(path, newline='') as f:
            rows = list(csv.reader(f))
        if not rows or [x.strip() for x in rows[0]] != ['date', 'well', 'oil', 'water', 'gas']:
            raise ValueError('header')
        for row in rows[1:]:
            if len(row) != 5:
                raise ValueError('row')
            date, well = (row[0].strip(), row[1].strip())
            try:
                datetime.date.fromisoformat(date)
                values = [float(x.strip()) for x in row[2:]]
            except Exception as e:
                raise ValueError('value') from e
            if not well or any((x < 0 for x in values)):
                raise ValueError('value')
            key = (date, well)
            if key in data:
                raise ValueError('duplicate')
            data[key] = values
    result = []
    by_well = defaultdict(list)
    for (date, well), values in sorted(data.items()):
        by_well[well].append((date, values))
    rolling = {}
    for well, entries in by_well.items():
        for i, (date, values) in enumerate(entries):
            rolling[date, well] = sum((x[1][0] for x in entries[max(0, i - window_days + 1):i + 1])) / min(window_days, i + 1)
    for (date, well), values in sorted(data.items()):
        result.append({'date': date, 'well': well, 'oil_total': float(values[0]), 'water_total': float(values[1]), 'gas_total': float(values[2]), 'oil_rolling': float(rolling[date, well])})
    return result

