from solution import build_inspection_agenda
import hashlib
import hmac
import json
import pytest


def make_payload(records):
    return json.dumps({"inspections": records}, separators=(",", ":"))


def signed(payload, key="building-key"):
    digest = hmac.new(key.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return "sha256=" + digest


def record(identifier, address="10 Main St", inspector="Lee", date="2025-04-10", status="scheduled"):
    return {"id": identifier, "address": address, "inspector": inspector, "date": date, "status": status}


def test_filters_date_range_and_status():
    payload = make_payload([
        record("a", date="2025-04-01"),
        record("b", date="2025-04-10", status="cancelled"),
        record("c", date="2025-04-20"),
        record("d", date="2025-04-30"),
    ])
    result = build_inspection_agenda(payload, signed(payload), "building-key", "2025-04-10", "2025-04-20")
    assert result == [
        {"id": "c", "address": "10 Main St", "inspector": "Lee", "date": "2025-04-20"}
    ]


def test_sorting_date_inspector_casefold_then_id():
    records = [
        record("z", inspector="zoe", date="2025-05-02"),
        record("b", inspector="alice", date="2025-05-01"),
        record("a", inspector="Alice", date="2025-05-01"),
        record("c", inspector="Bob", date="2025-05-01"),
    ]
    payload = make_payload(records)
    result = build_inspection_agenda(payload, signed(payload), "building-key", "2025-05-01", "2025-05-02")
    assert [x["id"] for x in result] == ["a", "b", "c", "z"]


def test_empty_list_and_boundary_dates():
    payload = make_payload([
        record("first", date="2025-01-01"),
        record("last", date="2025-12-31"),
    ])
    assert build_inspection_agenda(payload, signed(payload), "building-key", "2025-01-01", "2025-12-31") == [
        {"id": "first", "address": "10 Main St", "inspector": "Lee", "date": "2025-01-01"},
        {"id": "last", "address": "10 Main St", "inspector": "Lee", "date": "2025-12-31"},
    ]
    empty = make_payload([])
    assert build_inspection_agenda(empty, signed(empty), "building-key", "2025-01-01", "2025-12-31") == []


def test_bad_signature_is_rejected():
    payload = make_payload([record("a")])
    with pytest.raises(PermissionError):
        build_inspection_agenda(payload, signed(payload, "other-key"), "building-key", "2025-01-01", "2025-12-31")


def test_header_format_errors():
    payload = make_payload([])
    for header in ["", "sha256=abc", "sha1=" + "0" * 64, "sha256=" + "A" * 64, "sha256=" + "0" * 63 + "g"]:
        with pytest.raises(ValueError):
            build_inspection_agenda(payload, header, "building-key", "2025-01-01", "2025-12-31")


def test_invalid_json_and_schema():
    for payload in ["not json", "[]", json.dumps({}), json.dumps({"inspections": "x"}), json.dumps({"inspections": [record("a", date="2025-02-30")]})]:
