def test_duplicate_ids_and_date_range_errors():
    payload = make_payload([record("same"), record("same", address="Other")])
    with pytest.raises(ValueError):
        build_inspection_agenda(payload, signed(payload), "building-key", "2025-01-01", "2025-12-31")
    payload = make_payload([])
    with pytest.raises(ValueError):
        build_inspection_agenda(payload, signed(payload), "building-key", "2025-02-01", "2025-01-01")
