def issue_certificates(records: list[dict], issuer: str, page: int=1, page_size: int=10) -> list[dict]:
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    if not isinstance(issuer, str):
        raise TypeError('issuer must be a string')
    if not issuer.strip():
        raise ValueError('issuer must not be empty')
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('invalid page size')
    chosen = {}
    for record in records:
        if not isinstance(record, dict):
            raise TypeError('record must be a dictionary')
        try:
            name, course, issued_at = (record['name'], record['course'], record['issued_at'])
            score = record['score']
        except KeyError as exc:
            raise ValueError('missing field') from exc
        if not all((isinstance(x, str) and x.strip() for x in (name, course, issued_at))):
            raise ValueError('invalid text field')
        if isinstance(score, bool) or not isinstance(score, Real) or (not 0 <= score <= 100):
            raise ValueError('invalid score')
        name, course, issued_at = (name.strip(), course.strip(), issued_at.strip())
        if score < 60:
            continue
