    ordered = sorted(chosen.values(), key=lambda x: (-x['score'], x['name'].casefold(), x['course'].casefold(), x['issued_at']), reverse=False)
    ordered.sort(key=lambda x: x['issued_at'], reverse=False)
    ordered.sort(key=lambda x: x['course'].casefold())
    ordered.sort(key=lambda x: x['name'].casefold())
    ordered.sort(key=lambda x: x['score'], reverse=True)
    start = (page - 1) * page_size
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    result = []
    for item in ordered[start:start + page_size]:
        result.append({'certificate_id': ''.join((secrets.choice(alphabet) for _ in range(12))), 'recipient': item['name'], 'course': item['course'], 'score': round(item['score'], 1), 'issued_at': item['issued_at'], 'issuer': issuer.strip()})
    return result

