import pytest


def test_parse_basic_entries_and_order():
    text = '# header\n\nmsgid "hello"\nmsgstr "Bonjour"\nmsgid "bye"\nmsgstr "Au revoir"\n'
    result = parse_catalog(text)
    assert list(result.items()) == [('hello', 'Bonjour'), ('bye', 'Au revoir')]


def test_parse_escapes_and_whitespace_comments():
    text = '  # ignored\nmsgid "say \\"hi\\""\nmsgstr "ligne\\nseconde"\n\nmsgid "path"\nmsgstr "C:\\\\tmp"\n'
    assert parse_catalog(text) == {'say "hi"': 'ligne\nseconde', 'path': 'C:\\tmp'}


def test_parse_rejects_structural_errors():
    bad_inputs = [
        'msgstr "x"',
        'msgid "x"',
        'msgid "x"\nmsgstr "a"\nmsgstr "b"',
        'msgid "x"\nmsgstr "a"\nmsgid "x"\nmsgstr "b"',
        'msgid x\nmsgstr "a"',
        'ordinary text',
    ]
    for text in bad_inputs:
        with pytest.raises(ValueError):
            parse_catalog(text)


