def load_expenses(paths: list[str]) -> list[tuple[str, str, str, Decimal]]:
    records = []
    for path_index, path in enumerate(paths):
        try:
            result = subprocess.run(['sort', '-t,', '-k1,1', '-k2,2', path], capture_output=True, text=True, check=True)
        except (OSError, subprocess.CalledProcessError) as exc:
            raise ValueError('unable to read expense file') from exc
        for line_index, line in enumerate(result.stdout.splitlines()):
