import hmac
import math

def _fields(line):
    out = []
    cur = []
    escaped = False
    for ch in line:
        if escaped:
            if ch not in '|\\':
                raise ValueError('invalid escape')
            cur.append(ch)
            escaped = False
        elif ch == '\\':
            escaped = True
        elif ch == '|':
            out.append(''.join(cur))
            cur = []
        else:
            cur.append(ch)
    if escaped:
        raise ValueError('invalid escape')
    out.append(''.join(cur))
    return out

def process_signed_log(text: str, secret: bytes) -> dict:
    if not isinstance(text, str) or not isinstance(secret, bytes):
        raise TypeError('invalid argument type')
    if not text.endswith('\n') or '\n' not in text:
        raise ValueError('invalid input')
    header, body = text.split('\n', 1)
    if not header.startswith('signature:') or len(header) != 74:
        raise ValueError('invalid header')
    supplied = header[10:]
    if any((c not in '0123456789abcdef' for c in supplied)):
        raise ValueError('invalid signature')
    expected = hmac.new(secret, body.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(supplied, expected):
        raise ValueError('invalid signature')
    animals = {}
    lines = body.splitlines()
    for line in lines:
        if not line:
            raise ValueError('empty record')
        parts = _fields(line)
        if len(parts) != 5:
            raise ValueError('field count')
        date, animal, medication, dose_text, status = parts
        try:
            parsed = datetime.date.fromisoformat(date)
            dose = float(dose_text)
        except (ValueError, TypeError):
            raise ValueError('invalid record')
        if not animal or not medication or (not math.isfinite(dose)) or (dose <= 0):
            raise ValueError('invalid record')
        if status not in ('administered', 'missed'):
            raise ValueError('invalid status')
        item = animals.setdefault(animal, {'name': animal, 'total_dose': 0.0, 'missed': 0, 'last_date': parsed})
        if status == 'administered':
            item['total_dose'] += dose
        else:
            item['missed'] += 1
        if parsed > item['last_date']:
            item['last_date'] = parsed
    result = []
    for item in animals.values():
        result.append({'name': item['name'], 'total_dose': round(item['total_dose'], 3), 'missed': item['missed'], 'last_date': item['last_date'].isoformat()})
    result.sort(key=lambda x: (-x['total_dose'], x['name']))
    return {'record_count': len(lines), 'animals': result}

