import csv
import datetime
import math
import os
import tempfile

def export_availability(records: list[dict], destination: str, nights: int=1) -> dict:
    if isinstance(nights, bool) or not isinstance(nights, int) or nights <= 0:
        raise ValueError('nights must be positive')
    groups = {}
    for record in records:
        try:
            hotel = record['hotel']
            room_type = record['room_type']
            start = datetime.date.fromisoformat(record['check_in'])
            end = datetime.date.fromisoformat(record['check_out'])
            rate = float(record['nightly_rate'])
            rooms = record['rooms']
        except (KeyError, TypeError, ValueError, OverflowError):
            raise ValueError('invalid record')
        if not isinstance(hotel, str) or not hotel or (not isinstance(room_type, str)) or (not room_type) or (end <= start) or (not math.isfinite(rate)) or (rate < 0) or isinstance(rooms, bool) or (not isinstance(rooms, int)) or (rooms < 0):
            raise ValueError('invalid record')
        if rooms and (end - start).days >= nights:
            key = (hotel, room_type)
            if key not in groups:
                groups[key] = [0, rate, start]
            groups[key][0] += rooms
            groups[key][1] = min(groups[key][1], rate)
            groups[key][2] = min(groups[key][2], start)
    rows = []
    for (hotel, room_type), (rooms, rate, start) in sorted(groups.items()):
        rows.append([hotel, room_type, str(rooms), f'{rate:.2f}', start.isoformat()])
    parent = os.path.dirname(os.path.abspath(destination))
    descriptor, temporary = tempfile.mkstemp(dir=parent, prefix='.availability-')
    os.close(descriptor)
    try:
        with open(temporary, 'w', encoding='utf-8', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['hotel', 'room_type', 'rooms', 'nightly_rate', 'earliest_check_in'])
            writer.writerows(rows)
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return {'groups': len(rows), 'rooms': sum((item[0] for item in groups.values())), 'lowest_rate': min((item[1] for item in groups.values()), default=None)}

