import copy
import xml.etree.ElementTree as ET

def parse_orders(xml_text: str) -> list[dict]:
    try:
        root = ET.fromstring(xml_text)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'orders':
        raise ValueError('invalid root')
    result = []
    seen = set()
    for node in root:
        if node.tag != 'order':
            raise ValueError('invalid child')
        required = ('id', 'channel', 'region', 'created')
        if any((not node.get(k) for k in required)):
            raise ValueError('missing attribute')
        oid = node.get('id')
        if oid in seen:
            raise ValueError('duplicate id')
        seen.add(oid)
        if node.get('channel') not in {'web', 'store', 'marketplace'}:
            raise ValueError('invalid channel')
        try:
            priority = int(node.get('priority', '0'))
        except Exception as exc:
            raise ValueError('invalid priority') from exc
        lines = []
        for line in node:
            if line.tag != 'line' or not line.get('sku'):
                raise ValueError('invalid line')
            try:
                qty = int(line.get('qty', ''))
            except Exception as exc:
                raise ValueError('invalid quantity') from exc
            if qty <= 0 or str(qty) != line.get('qty'):
                raise ValueError('invalid quantity')
            lines.append({'sku': line.get('sku'), 'qty': qty})
        if not lines:
            raise ValueError('empty order')
        result.append({'id': oid, 'channel': node.get('channel'), 'region': node.get('region'), 'priority': priority, 'created': node.get('created'), 'lines': lines})
    return result

def route_orders(xml_text: str, stock: dict[str, dict]) -> dict:
    orders = parse_orders(xml_text)
    remaining = {}
    for name, data in stock.items():
        if not isinstance(data, dict) or not isinstance(data.get('regions'), list) or (not isinstance(data.get('items'), dict)):
            raise ValueError('invalid stock')
        items = {}
        for sku, qty in data['items'].items():
            if type(qty) is not int or qty < 0:
                raise ValueError('invalid stock quantity')
            items[sku] = qty
        remaining[name] = {'regions': list(data['regions']), 'items': items}
    orders.sort(key=lambda x: (-x['priority'], x['created'], x['id']))
    fulfilled, backordered = ([], [])
    for order in orders:
        choices = []
        for name, data in remaining.items():
            if order['region'] not in data['regions']:
                continue
            needed = {}
            for line in order['lines']:
                needed[line['sku']] = needed.get(line['sku'], 0) + line['qty']
            if all((data['items'].get(sku, 0) >= qty for sku, qty in needed.items())):
                choices.append(name)
        if not choices:
            backordered.append(order['id'])
            continue
        name = min(choices)
        for line in order['lines']:
            remaining[name]['items'][line['sku']] -= line['qty']
        fulfilled.append({'id': order['id'], 'warehouse': name})
    return {'fulfilled': fulfilled, 'backordered': backordered, 'remaining': remaining}

