import sqlite3
from datetime import datetime
from typing import Optional

def find_reservations(conn: sqlite3.Connection, window_start: str, window_end: str, category: Optional[str]=None, status: Optional[str]=None, sort_by: str='start') -> list[dict]:
    if window_start >= window_end:
        raise ValueError('invalid window')
    columns = {'start': 'r.start', 'end': 'r.end', 'customer': 'r.customer', 'category': 'v.category', 'vehicle_id': 'r.vehicle_id'}
    if sort_by not in columns:
        raise ValueError('invalid sort')
    sql = 'SELECT r.id, r.vehicle_id, v.registration, v.category, r.customer, r.start, r.end, r.status FROM reservations r JOIN vehicles v ON v.id = r.vehicle_id WHERE r.start < ? AND r.end > ?'
    args = [window_end, window_start]
    if category is not None:
        sql += ' AND v.category = ?'
        args.append(category)
    if status is not None:
        sql += ' AND r.status = ?'
        args.append(status)
    sql += ' ORDER BY ' + columns[sort_by] + ', r.id'
    rows = conn.execute(sql, args).fetchall()
    keys = ['id', 'vehicle_id', 'registration', 'category', 'customer', 'start', 'end', 'status']
    return [dict(zip(keys, row)) for row in rows]

def vehicle_usage(conn: sqlite3.Connection, vehicle_id: int) -> dict:
    if vehicle_id < 0:
        raise ValueError('invalid vehicle')
    if conn.execute('SELECT 1 FROM vehicles WHERE id = ?', (vehicle_id,)).fetchone() is None:
        return {'vehicle_id': vehicle_id, 'reservation_count': 0, 'completed_count': 0, 'booked_minutes': 0}
    rows = conn.execute('SELECT start, end, status FROM reservations WHERE vehicle_id = ?', (vehicle_id,)).fetchall()
    booked = 0
    completed = 0
    for start, end, status in rows:
        if status == 'completed':
            completed += 1
        elif status == 'booked':
