import datetime
import math
import xml.etree.ElementTree as ET

def summarize_heating_load(xml_text: str, target_date: str, page: int=1, page_size: int=24) -> list[dict[str, str | float]]:
    if page <= 0 or page_size <= 0:
        raise ValueError('invalid pagination')
    try:
        datetime.date.fromisoformat(target_date)
    except Exception as exc:
        raise ValueError('invalid date') from exc
    try:
        root = ET.fromstring(xml_text)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'forecast':
        raise ValueError('invalid root')
    groups = {}
    for node in root.iter('reading'):
        try:
            timestamp = node.attrib['timestamp']
            if not timestamp.startswith(target_date + 'T'):
                continue
            datetime.datetime.fromisoformat(timestamp)
            load = float(node.attrib['load_kw'])
            outdoor = float(node.attrib['outdoor_c'])
            if not math.isfinite(load) or not math.isfinite(outdoor):
                raise ValueError('non-finite value')
        except Exception as exc:
            raise ValueError('invalid reading') from exc
        if timestamp not in groups:
            groups[timestamp] = [0.0, 0.0, 0]
        groups[timestamp][0] += load
        groups[timestamp][1] += outdoor
        groups[timestamp][2] += 1
    result = []
    for timestamp in sorted(groups):
        load, outdoor, count = groups[timestamp]
        result.append({'timestamp': timestamp, 'load_kw': round(load / count, 2), 'outdoor_c': round(outdoor / count, 1)})
    start = (page - 1) * page_size
    return result[start:start + page_size]

