import math
import secrets

def create_equipment_booking(equipment: str, member: str, hours: float, existing_codes: list[str] | None=None) -> dict:
    if not isinstance(equipment, str) or not isinstance(member, str):
        raise TypeError('equipment and member must be strings')
    equipment = equipment.strip()
    member = member.strip()
    if not equipment or not member:
        raise ValueError('text fields cannot be empty')
    if isinstance(hours, bool) or not isinstance(hours, (int, float)):
        raise TypeError('hours must be numeric')
    if not math.isfinite(hours) or hours <= 0 or hours > 12:
        raise ValueError('hours out of range')
    rates = {'laser_cutter': 18.5, '3d_printer': 7.25, 'cnc_router': 22.0, 'soldering_station': 4.75}
    if equipment.lower() not in rates:
        raise ValueError('unknown equipment')
    if existing_codes is None:
        existing_codes = []
    if not isinstance(existing_codes, list) or not all((isinstance(x, str) for x in existing_codes)):
        raise TypeError('existing_codes must be a list of strings')
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    while True:
        code = 'MS-' + ''.join((secrets.choice(alphabet) for _ in range(8)))
        if code not in existing_codes:
            break
    return {'equipment': equipment, 'member': member, 'hours': hours, 'fee': round(rates[equipment.lower()] * hours, 2), 'code': code}

def booking_summary(bookings: list[dict], page: int=1, page_size: int=10) -> list[dict]:
    if not isinstance(page, int) or isinstance(page, bool) or page <= 0:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size <= 0:
        raise ValueError('invalid page size')
    groups = {}
    for record in bookings:
        equipment = record['equipment']
        hours = record['hours']
        fee = record['fee']
        if not isinstance(equipment, str) or not isinstance(hours, (int, float)) or isinstance(hours, bool) or (not isinstance(fee, (int, float))) or isinstance(fee, bool):
            raise TypeError('malformed booking')
        if not math.isfinite(hours) or not math.isfinite(fee) or hours <= 0 or (fee <= 0):
            raise ValueError('invalid booking values')
        item = groups.setdefault(equipment, [0, 0.0, 0.0])
        item[0] += 1
        item[1] += hours
        item[2] += fee
    result = [{'equipment': k, 'bookings': v[0], 'hours': round(v[1], 2), 'revenue': round(v[2], 2)} for k, v in groups.items()]
    result.sort(key=lambda x: (-x['revenue'], x['equipment']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

