import csv
import io
import os
import tempfile
from datetime import datetime, timezone

def parse_audit_log(text: str) -> list[dict]:
    if not text.strip():
        raise ValueError('empty input')
    try:
        rows = list(csv.reader(io.StringIO(text), strict=True))
    except csv.Error as exc:
        raise ValueError('invalid csv') from exc
    rows = [row for row in rows if any((field.strip() for field in row))]
    if not rows or rows[0] != ['timestamp', 'badge', 'door', 'action']:
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if len(row) != 4:
            raise ValueError('invalid row')
        stamp, badge, door, action = row
        if not badge or not door or action not in ('ENTER', 'EXIT'):
            raise ValueError('invalid field')
        if not stamp.endswith('Z'):
            raise ValueError('invalid timestamp')
        try:
            value = datetime.fromisoformat(stamp[:-1] + '+00:00')
        except ValueError as exc:
            raise ValueError('invalid timestamp') from exc
        if value.tzinfo is None:
            raise ValueError('invalid timestamp')
        result.append({'timestamp': value.astimezone(timezone.utc), 'badge': badge, 'door': door, 'action': action})
    return result

def summarize_access(records: list[dict]) -> list[dict]:
    states = {}
    ordered = sorted(enumerate(records), key=lambda item: (item[1]['timestamp'], item[0]))
    for _, record in ordered:
        key = (record['badge'], record['door'])
        state = states.setdefault(key, {'entries': 0, 'completed': 0, 'seconds': 0, 'open_at': None})
        if record['action'] == 'ENTER':
            state['entries'] += 1
            state['open_at'] = record['timestamp']
        elif state['open_at'] is not None:
            state['completed'] += 1
            state['seconds'] += int((record['timestamp'] - state['open_at']).total_seconds())
            state['open_at'] = None
    output = []
    for badge, door in sorted(states):
        state = states[badge, door]
        output.append({'badge': badge, 'door': door, 'entries': state['entries'], 'completed': state['completed'], 'seconds': state['seconds'], 'open': state['open_at'] is not None})
    return output

def export_report(records: list[dict], destination: str) -> str:
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(prefix='.audit-', suffix='.csv', dir=directory, text=True)
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['badge', 'door', 'entries', 'completed', 'seconds', 'open'])
            for row in summarize_access(records):
                writer.writerow([row['badge'], row['door'], row['entries'], row['completed'], row['seconds'], row['open']])
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return destination

