def _date(value):
    if not isinstance(value, str):
        raise ValueError('invalid date')
    try:
        result = datetime.date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid date')
    if result.isoformat() != value:
        raise ValueError('invalid date')
    return result

def summarize_loans(records: list[dict], as_of: str) -> list[dict]:
    today = _date(as_of)
    output = []
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        for key in ('member_id', 'title', 'checked_out', 'due', 'renewals'):
            if key not in record:
                raise ValueError('missing field')
        if not isinstance(record['member_id'], str) or not record['member_id']:
            raise ValueError('invalid member')
        if not isinstance(record['title'], str) or not record['title']:
            raise ValueError('invalid title')
        if isinstance(record['renewals'], bool) or not isinstance(record['renewals'], int) or record['renewals'] < 0:
            raise ValueError('invalid renewals')
        checked = _date(record['checked_out'])
        due = _date(record['due'])
        returned = record.get('returned')
        returned_date = None if returned is None else _date(returned)
        if checked > due or (returned_date is not None and returned_date < checked):
            raise ValueError('invalid date order')
        if returned_date is not None:
            status, late = ('returned', 0)
        elif due < today:
            status, late = ('overdue', (today - due).days)
        else:
            status, late = ('on_loan', 0)
        output.append({'member_id': record['member_id'], 'title': record['title'], 'status': status, 'days_overdue': late, 'renewals': record['renewals']})
    priority = {'overdue': 0, 'on_loan': 1, 'returned': 2}
    output.sort(key=lambda x: (priority[x['status']], -x['days_overdue'], x['member_id'], x['title']))
    return output

def export_report(records: list[dict], as_of: str, destination: str) -> int:
    rows = summarize_loans(records, as_of)
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=directory, prefix='.lending-')
    os.close(fd)
    try:
        with open(temporary, 'w', encoding='utf-8', newline='') as stream:
            writer = csv.DictWriter(stream, fieldnames=['member_id', 'title', 'status', 'days_overdue', 'renewals'])
            writer.writeheader()
            writer.writerows(rows)
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return len(rows)

