from solution import evaluate_rule, summarize_returns
import pytest

def test_evaluate_arithmetic_and_comparisons():
    variables = {'cost': 12.5, 'value': 40, 'days': 12, 'weight': 2}
    assert evaluate_rule('value - cost >= 20 and days < 30', variables) is True
    assert evaluate_rule('weight * 2 == 4 and not (days > 20)', variables) is True
    assert evaluate_rule('1 < weight < 3', variables) is True

def test_evaluate_functions_and_boolean_results():
    variables = {'value': 18.126, 'cost': 4.0, 'days': 40}
    assert evaluate_rule('round(value - cost, 2) == 14.13', variables) is True
    assert evaluate_rule('max(value, 20) == 20 or min(cost, 3) == 3', variables) is True
    assert evaluate_rule('0', variables) is False
    assert evaluate_rule('1', variables) is True

def test_evaluate_invalid_inputs():
    with pytest.raises(ValueError):
        evaluate_rule('missing > 2', {})
    with pytest.raises(ValueError):
        evaluate_rule('value +', {'value': 2})
    with pytest.raises(ValueError):
        evaluate_rule('abs(value) > 1', {'value': 2})
    with pytest.raises(ValueError):
        evaluate_rule('1 / 0 > 2', {})

