from datetime import date
import xml.etree.ElementTree as ET

def parse_referrals(xml_text: str, page: int=1, page_size: int=10) -> list[dict]:
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    try:
        root = ET.fromstring(xml_text)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'referrals':
        raise ValueError('invalid root')
    weights = {'high': 0, 'medium': 1, 'low': 2}
    required = ('id', 'patient', 'clinic', 'urgency', 'created', 'estimated_days', 'status')
    seen = set()
    records = []
    try:
        for node in root:
            if node.tag != 'referral':
                continue
            if any((name not in node.attrib for name in required)):
                raise ValueError('missing attribute')
            values = node.attrib
            ident = values['id']
            if ident in seen:
                raise ValueError('duplicate id')
            seen.add(ident)
            urgency = values['urgency']
            if urgency not in weights:
                raise ValueError('invalid urgency')
            date.fromisoformat(values['created'])
            days = int(values['estimated_days'])
            if days < 0:
                raise ValueError('invalid estimate')
            if values['status'] == 'open':
                records.append({'id': ident, 'patient': values['patient'], 'clinic': values['clinic'], 'urgency': urgency, 'created': values['created'], 'estimated_days': days})
        records.sort(key=lambda item: (weights[item['urgency']], item['created'], item['id']))
        start = (page - 1) * page_size
        return records[start:start + page_size]
    except (KeyError, TypeError, ValueError) as exc:
        raise ValueError('invalid referral') from exc

