import hashlib
import hmac
import json
import os

def build_compliance_report(records: list[dict], department: str | None, page: int, page_size: int) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('page must be a positive integer')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('page_size must be a positive integer')
    filtered = []
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        for field in ('employee_id', 'department', 'course', 'completed', 'score'):
            if field not in record:
                raise ValueError('invalid record')
        if any((not isinstance(record[field], str) or not record[field] for field in ('employee_id', 'department', 'course'))):
            raise ValueError('invalid record')
        if not isinstance(record['completed'], bool):
            raise ValueError('invalid record')
        if isinstance(record['score'], bool) or not isinstance(record['score'], (int, float)) or (not 0 <= record['score'] <= 100):
            raise ValueError('invalid record')
        if department is None or record['department'] == department:
            filtered.append(record)
    grouped = {}
    for record in filtered:
        if record['completed']:
            grouped.setdefault(record['course'], []).append(record['score'])
    courses = [{'course': name, 'completions': len(scores), 'average_score': round(sum(scores) / len(scores), 2)} for name, scores in grouped.items()]
    courses.sort(key=lambda item: (-item['completions'], item['course']))
    start = (page - 1) * page_size
    unsigned = {'department': department, 'total_records': len(filtered), 'completed_records': sum((len(v) for v in grouped.values())), 'courses': courses[start:start + page_size], 'page': page, 'page_size': page_size}
    key = os.environ.get('TRAINING_SIGNING_KEY')
    if key is None:
        raise RuntimeError('TRAINING_SIGNING_KEY is required')
    raw = json.dumps(unsigned, sort_keys=True, separators=(',', ':')).encode('utf-8')
    return {**unsigned, 'signature': hmac.new(key.encode('utf-8'), raw, hashlib.sha256).hexdigest()}

