    for name, definition in flags.items():
        if not isinstance(name, str) or not name or (not isinstance(definition, dict)) or (set(definition) != {'default', 'rules'}):
            raise ValueError('invalid flag')
        if type(definition['default']) is not bool or not isinstance(definition['rules'], list):
            raise ValueError('invalid flag')
        for rule in definition['rules']:
            if not isinstance(rule, dict) or set(rule) - {'if', 'rollout', 'value'} or type(rule.get('value')) is not bool or (('if' in rule) == ('rollout' in rule)):
                raise ValueError('invalid rule')
            if 'if' in rule and (not isinstance(rule['if'], dict) or not rule['if'] or any((not isinstance(k, str) for k in rule['if']))):
                raise ValueError('invalid rule')
            if 'rollout' in rule:
                r = rule['rollout']
                if not isinstance(r, dict) or set(r) != {'percent', 'salt'} or (not isinstance(r['salt'], str)) or (not r['salt']) or isinstance(r['percent'], bool) or (not isinstance(r['percent'], (int, float))) or (not 0 <= r['percent'] <= 100):
                    raise ValueError('invalid rule')
    protected = data.get('protected', {})
    if not isinstance(protected, dict) or any((k not in flags or not isinstance(v, str) for k, v in protected.items())):
        raise ValueError('invalid protected flags')
    return data

def resolve_flags(config: dict, user_id: str, attributes: dict, secret: str | None=None) -> dict[str, bool]:
    if not isinstance(user_id, str) or not isinstance(attributes, dict):
        raise TypeError('invalid arguments')
    result = {}
    for name, definition in config['flags'].items():
        if name in config.get('protected', {}) and (secret is None or not verify_secret(config['protected'][name], secret)):
            result[name] = definition['default']
            continue
        value = definition['default']
        for rule in definition['rules']:
            matched = 'if' in rule and all((attributes.get(k) == v for k, v in rule['if'].items()))
            if 'rollout' in rule:
                r = rule['rollout']
                n = int.from_bytes(hashlib.sha256((user_id + ':' + r['salt']).encode()).digest()[:4], 'big') % 10000
                matched = n < r['percent'] * 100
            if matched:
                value = rule['value']
                break
        result[name] = value
    return result

def hash_secret(secret: str) -> str:
    if not isinstance(secret, str):
        raise TypeError('secret must be a string')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def verify_secret(stored: str, candidate: str) -> bool:
    if not isinstance(stored, str) or not isinstance(candidate, str):
        return False
    try:
        salt_hex, digest_hex = stored.split('$')
        salt = bytes.fromhex(salt_hex)
        expected = bytes.fromhex(digest_hex)
        actual = hashlib.pbkdf2_hmac('sha256', candidate.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except Exception:
        return False

