    )
    try:
        assert find_schedule_entries(path, "Monday") == (
            "Monday, 09:00, Alice\nMonday, 14:00, Cara\n"
        )
    finally:
        directory.cleanup()


def test_matching_is_case_sensitive_and_uses_substrings():
    directory, path = make_schedule(
        "Monday, 09:00, Alice\nMONDAY, 10:00, Bob\nMondayish, 11:00, Cara\n"
    )
    try:
        assert find_schedule_entries(path, "Monday") == (
            "Monday, 09:00, Alice\nMondayish, 11:00, Cara\n"
        )
    finally:
        directory.cleanup()


