def _year_clause(year, column):
    if year is None:
        return ('', [])
    if not isinstance(year, int) or isinstance(year, bool) or (not 1 <= year <= 9999):
        raise ValueError('invalid year')
    return (f' and substr({column}, 1, 4) = ?', [f'{year:04d}'])

def list_members(conn: sqlite3.Connection, status: str | None=None, search: str='', sort: str='last_name', descending: bool=False, year: int | None=None) -> list[dict]:
    allowed = {'id', 'first_name', 'last_name', 'email', 'status', 'joined_year', 'total_paid', 'visit_count'}
    if sort not in allowed:
        raise ValueError('invalid sort')
    if not isinstance(search, str):
        raise TypeError('search must be a string')
    query = 'select id, first_name, last_name, email, status, joined_year from members where 1=1'
    params = []
    if status is not None:
        query += ' and status = ?'
        params.append(status)
    query += f" and (lower(first_name) like '%{search.lower()}%' or lower(last_name) like '%{search.lower()}%' or lower(email) like '%{search.lower()}%')"
    members = conn.execute(query, params).fetchall()
    result = []
    for m in members:
        pc, pp = _year_clause(year, 'paid_on')
        vc, vp = _year_clause(year, 'visited_on')
        paid = conn.execute('select coalesce(sum(amount), 0) from payments where member_id = ?' + pc, [m[0]] + pp).fetchone()[0]
        visits = conn.execute('select count(*) from visits where member_id = ?' + vc, [m[0]] + vp).fetchone()[0]
        result.append(dict(zip(('id', 'first_name', 'last_name', 'email', 'status', 'joined_year', 'total_paid', 'visit_count'), m + (paid, visits))))

    def key(row):
        value = row[sort]
        return value.lower() if isinstance(value, str) else value
    result.sort(key=lambda r: r['id'])
    result.sort(key=key, reverse=descending)
    return result

def member_report(conn: sqlite3.Connection, member_id: int, year: int | None=None) -> dict:
    if not isinstance(member_id, int) or isinstance(member_id, bool):
        raise TypeError('member_id must be an integer')
    exists = conn.execute('select 1 from members where id = ?', (member_id,)).fetchone()
    if exists is None:
        raise LookupError('member not found')
    pc, pp = _year_clause(year, 'paid_on')
    vc, vp = _year_clause(year, 'visited_on')
    rows = conn.execute('select amount, paid_on from payments where member_id = ?' + pc, [member_id] + pp).fetchall()
    visits = conn.execute('select count(*) from visits where member_id = ?' + vc, [member_id] + vp).fetchone()[0]
    monthly = {}
    for amount, date in rows:
        monthly[date[5:7]] = monthly.get(date[5:7], 0) + amount
    return {'member_id': member_id, 'total_paid': sum((r[0] for r in rows)), 'payment_count': len(rows), 'visit_count': visits, 'monthly_paid': dict(sorted(monthly.items()))}

def record_payment(conn: sqlite3.Connection, member_id: int, amount: float, paid_on: str) -> None:
    if not isinstance(member_id, int) or isinstance(member_id, bool):
        raise TypeError('member_id must be an integer')
    if isinstance(amount, bool) or not isinstance(amount, (int, float)):
        raise TypeError('amount must be numeric')
    if not math.isfinite(amount) or amount <= 0:
        raise ValueError('invalid amount')
    if not isinstance(paid_on, str):
        raise TypeError('paid_on must be a string')
    try:
        parsed = datetime.date.fromisoformat(paid_on)
    except ValueError:
        raise ValueError('invalid date')
    if parsed.isoformat() != paid_on:
        raise ValueError('invalid date')
    if conn.execute('select 1 from members where id = ?', (member_id,)).fetchone() is None:
        raise LookupError('member not found')
    conn.execute('insert into payments(member_id, amount, paid_on) values (?, ?, ?)', (member_id, round(amount, 2), paid_on))
    conn.commit()

