from lxml import etree

def extract_mentions(xml_text: str, min_reach: int=0, page: int=1, page_size: int=20) -> list[dict]:
    if min_reach < 0 or page < 1 or page_size < 1:
        raise ValueError('invalid arguments')
    try:
        root = etree.fromstring(xml_text.encode('utf-8'), parser=etree.XMLParser(resolve_entities=False, load_dtd=False, no_network=True))
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'feed':
        raise ValueError('invalid root')
    names = ('outlet', 'headline', 'sentiment', 'reach', 'published')
    records = []
    for node in root.findall('mention'):
        children = {child.tag: child for child in node}
        if any((name not in children for name in names)):
            raise ValueError('incomplete mention')
        values = {name: (children[name].text or '').strip() for name in names}
        if values['sentiment'] not in ('positive', 'neutral', 'negative') or not values['reach'].isdigit():
            raise ValueError('invalid record')
        reach = int(values['reach'])
        if reach >= min_reach:
            records.append({'outlet': values['outlet'], 'headline': values['headline'], 'sentiment': values['sentiment'], 'reach': reach, 'published': values['published']})
    records.sort(key=lambda x: x['outlet'])
    records.sort(key=lambda x: x['published'], reverse=True)
    records.sort(key=lambda x: x['reach'], reverse=True)
    start = (page - 1) * page_size
    return records[start:start + page_size]

