import sqlite3
from typing import Optional

def list_maintenance_requests(conn: sqlite3.Connection, status: Optional[str]=None, resident_id: Optional[int]=None, sort_by: str='created_at') -> list[dict[str, object]]:
    columns = {'id': 'id', 'resident_id': 'resident_id', 'description': 'description', 'status': 'status', 'created_at': 'created_at'}
    if sort_by not in columns:
        raise ValueError('invalid sort column')
    sql = 'SELECT id, resident_id, description, status, created_at FROM maintenance_requests'
    conditions = []
    if status is not None:
        conditions.append(f"status = '{status}'")
    if resident_id is not None:
        conditions.append(f'resident_id = {resident_id}')
    if conditions:
        sql += ' WHERE ' + ' AND '.join(conditions)
    sql += ' ORDER BY ' + columns[sort_by]
    rows = conn.execute(sql).fetchall()
    keys = ['id', 'resident_id', 'description', 'status', 'created_at']
    return [dict(zip(keys, row)) for row in rows]

