import sqlite3

def fetch_approval_report(conn: sqlite3.Connection, campaign_id: str, status: str | None=None, sort_by: str='submitted_at', limit: int=20, offset: int=0) -> list[dict]:
    if not isinstance(campaign_id, str) or not campaign_id:
        raise ValueError('invalid campaign_id')
    if status is not None and status not in {'approved', 'rejected', 'pending'}:
        raise ValueError('invalid status')
    sort_columns = {'submitted_at': 'c.submitted_at', 'title': 'c.title', 'approved_reviews': 'approved_reviews', 'rejected_reviews': 'rejected_reviews', 'id': 'c.id'}
    if sort_by not in sort_columns:
        raise ValueError('invalid sort_by')
    if isinstance(limit, bool) or not isinstance(limit, int) or (not 1 <= limit <= 100):
        raise ValueError('invalid limit')
    if isinstance(offset, bool) or not isinstance(offset, int) or offset < 0:
        raise ValueError('invalid offset')
    query = "\n        SELECT c.id, c.title, c.submitted_at,\n               COUNT(a.id) AS total_reviews,\n               COALESCE(SUM(CASE WHEN a.decision = 'approved' THEN 1 ELSE 0 END), 0) AS approved_reviews,\n               COALESCE(SUM(CASE WHEN a.decision = 'rejected' THEN 1 ELSE 0 END), 0) AS rejected_reviews,\n               COALESCE(SUM(CASE WHEN a.decision = 'pending' THEN 1 ELSE 0 END), 0) AS pending_reviews\n        FROM creatives c\n        LEFT JOIN approvals a ON a.creative_id = c.id\n        WHERE c.campaign_id = ?\n        GROUP BY c.id, c.title, c.submitted_at\n    "
    params = [campaign_id]
    if status is not None:
        query += ' HAVING SUM(CASE WHEN a.decision = ? THEN 1 ELSE 0 END) > 0'
        params.append(status)
    query += f' ORDER BY {sort_columns[sort_by]}, c.id LIMIT ? OFFSET ?'
    params.extend([limit, offset])
    rows = conn.execute(query, params).fetchall()
    keys = ['id', 'title', 'submitted_at', 'total_reviews', 'approved_reviews', 'rejected_reviews', 'pending_reviews']
    return [dict(zip(keys, row)) for row in rows]

