from solution import enroll_cashier, authenticate_cashier, summarize_register
import pytest


def test_enroll_returns_copy_and_stores_record():
    original = {"old": {"digest": "x"}}
    result = enroll_cashier(" alice ", "0427", original)
    assert result is not original
    assert result["old"] == original["old"]
    assert "alice" in result
    assert "pin" not in result["alice"]
    assert result["alice"] != {"pin": "0427"}
    assert original == {"old": {"digest": "x"}}


def test_enroll_validation():
    for pin in ["", "123", "123456789", "12a4", 1234, "１２３４"]:
        with pytest.raises(ValueError):
            enroll_cashier("x", pin)
    with pytest.raises(ValueError):
        enroll_cashier("   ", "1234")
    with pytest.raises(ValueError):
        enroll_cashier("x", "1234", {"x": {}})


def test_authentication_round_trip_and_failures():
    employees = enroll_cashier("bob", "987654", {})
    assert authenticate_cashier("bob", "987654", employees)
    assert not authenticate_cashier("bob", "987653", employees)
    assert not authenticate_cashier("nobody", "987654", employees)
    assert not authenticate_cashier("bob", 987654, employees)
    assert not authenticate_cashier("bob", "", employees)
    assert not authenticate_cashier("bad", "1", {"bad": {"digest": "not-valid"}})


def test_summary_filters_and_aggregates():
    rows = [
        {"cashier": "a", "time": "09:00", "cents": 1000, "tax_cents": 100, "category": " Food "},
        {"cashier": "a", "time": "10:15", "cents": 2500, "tax_cents": 250, "category": "Drink"},
        {"cashier": "a", "time": "11:59", "cents": 300, "tax_cents": 30, "category": "Food", "voided": True},
        {"cashier": "b", "time": "10:30", "cents": 999, "tax_cents": 9, "category": "Food"},
    ]
    assert summarize_register(rows, "a", 9, 11) == {
        "count": 2, "gross_cents": 3500, "tax_cents": 350,
        "by_category": {
            "Drink": {"gross_cents": 2500, "tax_cents": 250},
            "Food": {"gross_cents": 1000, "tax_cents": 100},
        },
    }


def test_summary_boundaries_order_and_empty():
    rows = [
        {"cashier": "a", "time": "00:00", "cents": 1, "tax_cents": 0, "category": "z"},
        {"cashier": "a", "time": "02:00", "cents": 2, "tax_cents": 1, "category": "a"},
        {"cashier": "a", "time": "01:59", "cents": 3, "tax_cents": 1, "category": "a"},
    ]
    assert summarize_register(rows, "a", 0, 2) == {
        "count": 2, "gross_cents": 4, "tax_cents": 1,
        "by_category": {"a": {"gross_cents": 3, "tax_cents": 1}, "z": {"gross_cents": 1, "tax_cents": 0}},
    }
    assert summarize_register(rows, "x", 2, 3) == {"count": 0, "gross_cents": 0, "tax_cents": 0, "by_category": {}}
    with pytest.raises(ValueError):
        summarize_register([], "a", 4, 4)


def test_summary_rejects_bad_rows():
    base = {"cashier": "a", "time": "12:00", "cents": 1, "tax_cents": 0, "category": "x"}
    bads = [
        {**base, "time": "12:60"}, {**base, "time": "1:00"}, {**base, "cents": True},
        {**base, "tax_cents": -1}, {**base, "category": "   "}, {**base, "voided": 1},
        {**base, "cashier": 3}, [],
    ]
    for row in bads:
        with pytest.raises(ValueError):
            summarize_register([row], "a", 0, 24)


