import hashlib
import hmac
import os
import re

def enroll_cashier(cashier_id: str, pin: str, employees: dict[str, dict] | None=None) -> dict[str, dict]:
    if not isinstance(cashier_id, str) or not cashier_id.strip():
        raise ValueError('invalid cashier id')
    cashier_id = cashier_id.strip()
    if not isinstance(pin, str) or not re.fullmatch('[0-9]{4,8}', pin):
        raise ValueError('invalid pin')
    result = dict(employees or {})
    if cashier_id in result:
        raise ValueError('duplicate cashier')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    result[cashier_id] = {'salt': salt.hex(), 'digest': digest.hex()}
    return result

def authenticate_cashier(cashier_id: str, pin: str, employees: dict[str, dict]) -> bool:
    if not isinstance(pin, str) or not isinstance(employees, dict):
        return False
    record = employees.get(cashier_id)
    if not isinstance(record, dict):
        return False
    try:
        salt = bytes.fromhex(record['salt'])
        expected = bytes.fromhex(record['digest'])
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError):
        return False

def summarize_register(transactions: list[dict], cashier_id: str, start_hour: int, end_hour: int) -> dict:
    if not isinstance(start_hour, int) or isinstance(start_hour, bool) or (not isinstance(end_hour, int)) or isinstance(end_hour, bool) or (not 0 <= start_hour < end_hour <= 24):
        raise ValueError('invalid interval')
    result = {'count': 0, 'gross_cents': 0, 'tax_cents': 0, 'by_category': {}}
    for row in transactions:
        if not isinstance(row, dict) or not isinstance(row.get('cashier'), str):
            raise ValueError('invalid transaction')
        time = row.get('time')
        if not isinstance(time, str) or not re.fullmatch('(?:[01][0-9]|2[0-3]):[0-5][0-9]', time):
            raise ValueError('invalid time')
