def verify_credential(stored: str, candidate: str) -> bool:
    if not isinstance(stored, str) or not isinstance(candidate, str):
        return False
    try:
        salt_text, digest_text = stored.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    if len(salt) != 16 or len(expected) != 32:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', candidate.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def plan_route(stops: list[dict], capacity: int=10) -> list[str]:
    if not isinstance(stops, list):
        raise TypeError('stops must be a list')
    if not isinstance(capacity, int) or isinstance(capacity, bool):
        raise TypeError('capacity must be an integer')
    if capacity <= 0:
        raise ValueError('capacity must be positive')
    required = {'id', 'x', 'y', 'service', 'window', 'demand', 'priority'}
    remaining = []
    ids = set()
    for stop in stops:
        if not isinstance(stop, dict) or not required.issubset(stop):
            raise TypeError('invalid stop')
        ident = stop['id']
        numeric = [stop['x'], stop['y'], stop['service'], stop['demand'], stop['priority']]
        if not isinstance(ident, str) or not ident or any((not isinstance(v, int) or isinstance(v, bool) for v in numeric)):
            raise TypeError('invalid stop field')
        window = stop['window']
        if not isinstance(window, (tuple, list)) or len(window) != 2 or any((not isinstance(v, int) or isinstance(v, bool) for v in window)):
            raise TypeError('invalid window')
        if ident in ids or stop['service'] < 0 or stop['demand'] < 0 or (stop['demand'] > capacity) or (window[0] > window[1]):
            raise ValueError('invalid stop')
        ids.add(ident)
        remaining.append(stop)
    result = []
    now = 0
    x = y = 0
    while remaining:
        candidates = []
        for stop in remaining:
            if stop['demand'] > capacity:
                continue
            arrival = now + abs(x - stop['x']) + abs(y - stop['y'])
            start = max(arrival, stop['window'][0])
            if start <= stop['window'][1]:
