        raise ValueError('invalid length')
    alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
    return ''.join((secrets.choice(alphabet) for _ in range(length)))

def rank_standings(records: list[dict], page: int=1, per_page: int=10) -> list[dict]:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(per_page, bool) or not isinstance(per_page, int) or per_page < 1:
        raise ValueError('invalid page size')
    required = {'team', 'played', 'wins', 'draws', 'losses', 'scored', 'conceded'}
    seen = set()
    rows = []
    for record in records:
        if not isinstance(record, dict) or not required <= record.keys():
            raise ValueError('invalid record')
        team = record['team']
        if not isinstance(team, str) or not team or team in seen:
            raise ValueError('invalid team')
        seen.add(team)
        values = [record[key] for key in ('played', 'wins', 'draws', 'losses', 'scored', 'conceded')]
        if any((isinstance(value, bool) or not isinstance(value, int) or value < 0 for value in values)):
            raise ValueError('invalid statistic')
        played, wins, draws, losses, scored, conceded = values
        if wins + draws + losses != played:
            raise ValueError('invalid matches')
