import csv
import os
import tempfile


def write_csv(directory, name, rows, fieldnames=("name", "email", "company")):
    path = os.path.join(directory, name)
    parent = os.path.dirname(path)
    os.makedirs(parent, exist_ok=True)
    with open(path, "w", encoding="utf-8", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=fieldnames)
        writer.writeheader()
        writer.writerows(rows)
    return path


def test_imports_and_normalizes_rows():
    with tempfile.TemporaryDirectory() as directory:
        write_csv(directory, "incoming/leads.csv", [
            {"name": " Alice ", "email": " Alice@Example.COM ", "company": " Acme "},
            {"name": "Bob", "email": "bob@example.com", "company": "Beta"},
        ])
        assert import_leads(directory, "incoming/leads.csv") == [
            {"name": "Alice", "email": "alice@example.com", "company": "Acme"},
            {"name": "Bob", "email": "bob@example.com", "company": "Beta"},
        ]


def test_deduplicates_case_insensitively_and_keeps_first():
    with tempfile.TemporaryDirectory() as directory:
        write_csv(directory, "leads.csv", [
            {"name": "First", "email": "Person@Example.com", "company": "One"},
            {"name": "Second", "email": " person@example.COM ", "company": "Two"},
            {"name": "Third", "email": "third@example.com", "company": "Three"},
        ])
        assert import_leads(directory, "leads.csv") == [
            {"name": "First", "email": "person@example.com", "company": "One"},
            {"name": "Third", "email": "third@example.com", "company": "Three"},
        ]


def test_ignores_rows_with_blank_emails():
    with tempfile.TemporaryDirectory() as directory:
        write_csv(directory, "leads.csv", [
            {"name": "No Email", "email": "   ", "company": "Unknown"},
            {"name": "Valid", "email": "valid@example.com", "company": "Known"},
        ])
        assert import_leads(directory, "leads.csv") == [
            {"name": "Valid", "email": "valid@example.com", "company": "Known"}
        ]


def test_preserves_empty_non_email_fields_after_stripping():
    with tempfile.TemporaryDirectory() as directory:
        write_csv(directory, "leads.csv", [
            {"name": "  Dana  ", "email": "dana@example.com", "company": "   "},
        ])
        assert import_leads(directory, "leads.csv") == [
            {"name": "Dana", "email": "dana@example.com", "company": ""}
        ]


def test_rejects_unexpected_columns():
    with tempfile.TemporaryDirectory() as directory:
        write_csv(directory, "bad.csv", [], fieldnames=("name", "email", "phone"))
