import zipfile

def summarize_production_archive(base_dir: str, archive_name: str, min_total_tons: float=0.0, page: int=1, page_size: int=10) -> list[dict]:
    if min_total_tons < 0 or isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError('invalid arguments')
    base = os.path.realpath(base_dir)
    archive = os.path.realpath(os.path.join(base, archive_name))
    if os.path.commonpath((base, archive)) != base:
        raise ValueError('invalid archive path')
    totals = {}
    with zipfile.ZipFile(archive) as zf, tempfile.TemporaryDirectory(dir=base) as work:
        for info in zf.infolist():
            target = os.path.realpath(os.path.join(base, work[len(base) + 1:], info.filename))
            if os.path.commonpath((base, target)) != base:
                raise ValueError('invalid member path')
        zf.extractall(work)
        for info in zf.infolist():
            if not info.filename.lower().endswith('.csv') or info.is_dir():
                continue
            with open(os.path.join(work, info.filename), newline='', encoding='utf-8') as f:
                reader = csv.DictReader(f)
                if reader.fieldnames != ['timestamp', 'kiln', 'tons', 'energy_kwh', 'quality']:
                    raise ValueError('invalid header')
                for row in reader:
                    try:
                        datetime.datetime.fromisoformat(row['timestamp'])
                        kiln = row['kiln']
                        tons = float(row['tons'])
                        energy = float(row['energy_kwh'])
                        quality = row['quality']
                    except Exception as e:
                        raise ValueError('invalid row') from e
                    if not kiln or not math.isfinite(tons) or (not math.isfinite(energy)) or (tons <= 0) or (energy < 0) or (quality not in ('PASS', 'FAIL')):
                        raise ValueError('invalid row')
                    item = totals.setdefault(kiln, [0.0, 0.0, 0, 0])
                    item[0] += tons
                    item[1] += energy
                    item[2] += 1
                    item[3] += quality == 'PASS'
    result = []
    for kiln, (tons, energy, count, passed) in totals.items():
        if tons >= min_total_tons:
            result.append({'kiln': kiln, 'total_tons': round(tons, 2), 'avg_energy_per_ton': round(energy / tons, 3), 'batches': count, 'quality_rate': round(passed * 100 / count, 1)})
    result.sort(key=lambda x: (-x['total_tons'], x['kiln']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

