import subprocess
from decimal import Decimal, ROUND_HALF_UP

def attribution_report(path: str, campaign: str | None, page: int, page_size: int) -> list[dict[str, object]]:
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    if campaign is None:
        result = subprocess.run(['cat', '--', path], capture_output=True, text=True)
    else:
        result = subprocess.run(['grep', '-F', '--', campaign, path], capture_output=True, text=True)
    if result.returncode == 2:
        raise FileNotFoundError(path)
    if result.returncode not in (0, 1):
        raise OSError(result.stderr)
    totals = {}
    for line in result.stdout.splitlines():
        if not line.strip():
            continue
        fields = line.split(',')
        if len(fields) != 5:
            raise ValueError('invalid record')
        _, record_campaign, channel, conversions_text, revenue_text = fields
        if campaign is not None and record_campaign != campaign:
            continue
        try:
            conversions = int(conversions_text)
            revenue = Decimal(revenue_text)
        except Exception as exc:
            raise ValueError('invalid number') from exc
        if conversions < 0 or revenue < 0:
            raise ValueError('negative number')
        if channel not in totals:
            totals[channel] = [0, Decimal('0')]
        totals[channel][0] += conversions
        totals[channel][1] += revenue
    rows = [{'channel': channel, 'conversions': values[0], 'revenue': float(values[1].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))} for channel, values in totals.items()]
    rows.sort(key=lambda row: (-row['conversions'], -row['revenue'], row['channel']))
    start = (page - 1) * page_size
    return rows[start:start + page_size]

