    conn.executescript('CREATE TABLE IF NOT EXISTS payments (id INTEGER PRIMARY KEY, reference TEXT NOT NULL UNIQUE, currency TEXT NOT NULL, amount INTEGER NOT NULL, status TEXT NOT NULL, value_date TEXT NOT NULL, counterparty TEXT NOT NULL); CREATE TABLE IF NOT EXISTS settlement_batches (batch_id TEXT PRIMARY KEY, created_at TEXT NOT NULL); CREATE TABLE IF NOT EXISTS settled_payments (payment_id INTEGER PRIMARY KEY, batch_id TEXT NOT NULL REFERENCES settlement_batches(batch_id));')

def settlement_report(conn: sqlite3.Connection, statuses: tuple[str, ...]=(), currency: str | None=None, min_amount: int=0, sort_by: str='value_date') -> list[dict]:
    allowed = {'pending', 'approved', 'rejected', 'settled'}
    orders = {'reference': 'reference ASC', 'currency': 'currency ASC', 'amount': 'amount ASC', 'amount_desc': 'amount DESC', 'value_date': 'value_date ASC', 'counterparty': 'counterparty ASC'}
    if any((s not in allowed for s in statuses)) or not isinstance(min_amount, int) or isinstance(min_amount, bool) or (min_amount < 0) or (currency is not None and (not isinstance(currency, str) or not currency)) or (sort_by not in orders):
        raise ValueError('invalid report arguments')
    where = ['amount >= ?']
    params = [min_amount]
    if statuses:
        where.append('status IN (' + ','.join(('?' for _ in statuses)) + ')')
        params.extend(statuses)
    if currency is not None:
        where.append('currency = ?')
        params.append(currency)
    rows = conn.execute('SELECT id,reference,currency,amount,status,value_date,counterparty FROM payments WHERE ' + ' AND '.join(where) + ' ORDER BY ' + orders[sort_by] + ', reference ASC, id ASC', params).fetchall()
    keys = ('id', 'reference', 'currency', 'amount', 'status', 'value_date', 'counterparty')
    return [dict(zip(keys, row)) for row in rows]

def settle_batch(conn: sqlite3.Connection, payment_ids: tuple[int, ...], batch_id: str, created_at: str) -> dict:
    if not payment_ids or any((not isinstance(x, int) or isinstance(x, bool) or x <= 0 for x in payment_ids)) or len(set(payment_ids)) != len(payment_ids) or (not isinstance(batch_id, str)) or (not batch_id) or (not isinstance(created_at, str)) or (not created_at):
        raise ValueError('invalid batch')
    try:
        p = ','.join(('?' for _ in payment_ids))
        rows = conn.execute('SELECT id,amount,status FROM payments WHERE id IN (' + p + ')', payment_ids).fetchall()
        if len(rows) != len(payment_ids) or any((r[2] != 'approved' for r in rows)) or conn.execute('SELECT 1 FROM settled_payments WHERE payment_id IN (' + p + ')', payment_ids).fetchone():
            raise ValueError('payments cannot be settled')
        conn.execute('INSERT INTO settlement_batches VALUES (?,?)', (batch_id, created_at))
        conn.executemany('INSERT INTO settled_payments VALUES (?,?)', [(x, batch_id) for x in payment_ids])
        conn.execute("UPDATE payments SET status='settled' WHERE id IN (" + p + ')', payment_ids)
        conn.commit()
        return {'batch_id': batch_id, 'payment_ids': payment_ids, 'total': sum((r[1] for r in rows))}
    except ValueError:
        conn.rollback()
        raise
    except Exception:
        conn.rollback()
        raise ValueError('batch could not be stored')

