import csv
import datetime
import subprocess
_HEADER = ['date', 'time', 'student', 'instructor', 'status', 'duration']

def _date(value):
    try:
        return datetime.date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid date')

def _parse(data):
    result = []
    for row in csv.reader(data.splitlines(), delimiter='\t'):
        if not row:
            continue
        if row == _HEADER and (not result):
            continue
        if len(row) != 6:
            raise ValueError('invalid row')
        d, t, student, instructor, status, duration = row
        _date(d)
        try:
            datetime.datetime.strptime(t, '%H:%M')
        except ValueError:
            raise ValueError('invalid time')
        if not student or not instructor or status not in ('confirmed', 'cancelled'):
            raise ValueError('invalid booking')
        try:
            duration = int(duration)
        except ValueError:
            raise ValueError('invalid duration')
        if duration <= 0:
            raise ValueError('invalid duration')
        result.append({'date': d, 'time': t, 'student': student, 'instructor': instructor, 'status': status, 'duration': duration})
    return result

def read_bookings(path: str) -> list[dict]:
    try:
        r = subprocess.run(['cat', path], capture_output=True, text=True, check=True)
    except subprocess.CalledProcessError:
        raise FileNotFoundError(path)
    return _parse(r.stdout)

def schedule_for_date(path: str, date: str) -> list[dict]:
    _date(date)
    rows = [x for x in read_bookings(path) if x['date'] == date and x['status'] == 'confirmed']
    rows.sort(key=lambda x: (x['time'], x['instructor'], x['student']))
    return [{k: x[k] for k in ('time', 'student', 'instructor', 'duration')} for x in rows]

def utilization_report(path: str, start_date: str, end_date: str, instructor: str | None=None) -> list[dict]:
    start, end = (_date(start_date), _date(end_date))
    if start > end:
        raise ValueError('reversed range')
    groups = {}
    for x in read_bookings(path):
        d = _date(x['date'])
        if x['status'] == 'confirmed' and start <= d <= end and (instructor is None or x['instructor'] == instructor):
            key = (x['date'], x['instructor'])
            g = groups.setdefault(key, {'date': x['date'], 'instructor': x['instructor'], 'lessons': 0, 'minutes': 0, 'students': set()})
            g['lessons'] += 1
            g['minutes'] += x['duration']
            g['students'].add(x['student'])
    out = []
    for key in sorted(groups):
        g = groups[key]
        g['students'] = sorted(g['students'])
        out.append(g)
    return out

