def build_delivery_manifest(requester: dict, parcels: list[dict], hub_id: str, page: int, page_size: int) -> dict:
    if not isinstance(requester, dict) or not isinstance(hub_id, str):
        raise ValueError()
    if not isinstance(page, int) or isinstance(page, bool) or page <= 0 or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (page_size <= 0):
        raise ValueError()
    if not isinstance(parcels, list):
        raise TypeError()
    required = {'id', 'hub_id', 'tenant_id', 'route_id', 'status', 'priority', 'delivery_window', 'address', 'weight_kg'}
    selected = []
    for parcel in parcels:
        if not required.issubset(parcel):
            raise ValueError()
        if parcel['hub_id'] == hub_id and parcel['status'] in ('assigned', 'out_for_delivery'):
            selected.append(parcel)
    if selected and requester.get('role') not in ('dispatcher', 'supervisor') and any((p['tenant_id'] != requester.get('tenant_id') for p in selected)):
        raise PermissionError()
    groups = {}
    for p in selected:
        groups.setdefault(p['route_id'], []).append(p)
    routes = []
    for route_id in sorted(groups):
        items = sorted(groups[route_id], key=lambda p: (-p['priority'], p['delivery_window'], p['id']))
        routes.append({'route_id': route_id, 'parcels': [{'id': p['id'], 'address': p['address'], 'weight_kg': p['weight_kg'], 'priority': p['priority']} for p in items], 'total_weight_kg': round(sum((p['weight_kg'] for p in items)), 2)})
    start = (page - 1) * page_size
    return {'hub_id': hub_id, 'page': page, 'page_size': page_size, 'total': len(routes), 'routes': routes[start:start + page_size]}

