import os
import subprocess

def read_publication_config(path: str) -> list[dict[str, str]]:
    result = []
    with open(path, encoding='utf-8') as f:
        for raw in f:
            line = raw.rstrip('\n\r')
            if not line:
                continue
            parts = line.split('\t')
            if len(parts) != 4 or any((not x for x in parts)) or parts[2] not in ('csv', 'jsonl'):
                raise ValueError('invalid configuration line')
            result.append({'slug': parts[0], 'title': parts[1], 'format': parts[2], 'path': parts[3]})
    return result

def publish_catalog(root: str, datasets: list[dict[str, str]], query: str='') -> list[dict[str, object]]:
    if not isinstance(datasets, list) or '\n' in query or '\r' in query:
        raise ValueError('invalid input')
    seen = set()
    output = []
    for item in datasets:
        if not isinstance(item, dict):
            raise ValueError('invalid dataset')
        try:
            slug, title, fmt, rel = (item[k] for k in ('slug', 'title', 'format', 'path'))
        except KeyError:
            raise ValueError('invalid dataset')
        if any((not isinstance(x, str) or not x for x in (slug, title, fmt, rel))) or fmt not in ('csv', 'jsonl') or slug in seen:
            raise ValueError('invalid dataset')
        seen.add(slug)
        path = os.path.join(root, rel)
        os.path.getsize(path)
        wc = subprocess.run(['wc', '-l', '--', path], capture_output=True, text=True, check=True)
        lines = int(wc.stdout.split()[0])
        grep = subprocess.run(['grep', '-F', '-c', '--', query, path], capture_output=True, text=True)
        if grep.returncode not in (0, 1):
            raise subprocess.CalledProcessError(grep.returncode, grep.args)
        matches = int(grep.stdout.strip() or '0')
        output.append({'slug': slug, 'title': title, 'format': fmt, 'rows': max(0, lines - 1) if fmt == 'csv' else lines, 'matching_lines': matches, 'bytes': os.path.getsize(path)})
    output.sort(key=lambda x: (x['title'].casefold(), x['slug']))
    return output

