import hashlib
import hmac
import json
import math

def summarize_signed_assessments(payload: str, signature: str, secret: str, year: int) -> list[dict]:
    expected = hmac.new(secret.encode(), payload.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(signature, expected):
        raise PermissionError('invalid signature')
    try:
        data = json.loads(payload)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid JSON') from exc
    if not isinstance(data, list):
        raise ValueError('records must be a list')
    seen = set()
    groups = {}
    for record in data:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        required = {'parcel_id', 'municipality', 'year', 'assessed_value', 'exemption'}
        if set(record) != required:
            raise ValueError('invalid record')
        parcel_id = record['parcel_id']
        municipality = record['municipality']
        record_year = record['year']
        assessed = record['assessed_value']
        exemption = record['exemption']
        if not isinstance(parcel_id, str) or not parcel_id:
            raise ValueError('invalid parcel id')
        if not isinstance(municipality, str) or not municipality:
            raise ValueError('invalid municipality')
        if not isinstance(record_year, int) or isinstance(record_year, bool):
            raise ValueError('invalid year')
        if isinstance(assessed, bool) or not isinstance(assessed, (int, float)) or isinstance(exemption, bool) or (not isinstance(exemption, (int, float))) or (not math.isfinite(assessed)) or (not math.isfinite(exemption)) or (assessed < 0) or (exemption < 0):
            raise ValueError('invalid amount')
        if parcel_id in seen:
            raise ValueError('duplicate parcel')
        seen.add(parcel_id)
        if record_year == year:
            taxable = max(0, round(assessed - exemption, 2))
            group = groups.setdefault(municipality, [0, 0.0])
            group[0] += 1
            group[1] += taxable
    result = [{'municipality': name, 'parcel_count': values[0], 'taxable_total': round(values[1], 2)} for name, values in groups.items()]
    return sorted(result, key=lambda item: (-item['taxable_total'], item['municipality']))

