import sqlite3
from datetime import datetime

def create_schema(conn: sqlite3.Connection) -> None:
    conn.execute('create table if not exists access_events (id integer primary key autoincrement, member_id text not null, facility text not null, entered_at text not null, exited_at text not null)')
    conn.commit()

def record_access(conn: sqlite3.Connection, member_id: str, facility: str, entered_at: str, exited_at: str) -> int:
    if not member_id.strip() or not facility.strip():
        raise ValueError('empty value')
    try:
        start = datetime.fromisoformat(entered_at)
        end = datetime.fromisoformat(exited_at)
    except (TypeError, ValueError):
        raise ValueError('invalid timestamp')
    if end < start:
        raise ValueError('reversed interval')
    cur = conn.execute('insert into access_events (member_id, facility, entered_at, exited_at) values (?, ?, ?, ?)', (member_id, facility, entered_at, exited_at))
    conn.commit()
    return int(cur.lastrowid)

def access_report(conn: sqlite3.Connection, member_id: str | None=None, facility: str | None=None, since: str | None=None, until: str | None=None, order: str='visits') -> list[dict]:
    if order not in {'visits', 'duration', 'last_seen', 'member'}:
        raise ValueError('invalid order')
    try:
        start = datetime.fromisoformat(since) if since is not None else None
        end = datetime.fromisoformat(until) if until is not None else None
    except (TypeError, ValueError):
        raise ValueError('invalid timestamp')
    if start is not None and end is not None and (start > end):
        raise ValueError('invalid range')
    clauses = []
    args = []
    for column, value in (('member_id', member_id), ('facility', facility)):
        if value is not None:
            clauses.append(column + ' = ?')
            args.append(value)
    if since is not None:
        clauses.append('entered_at >= ?')
        args.append(since)
    if until is not None:
        clauses.append('entered_at < ?')
        args.append(until)
    query = 'select member_id, facility, entered_at, exited_at from access_events'
    if clauses:
        query += ' where ' + ' and '.join(clauses)
    groups = {}
    for mid, fac, entered, exited in conn.execute(query, args):
        key = (mid, fac)
        a = datetime.fromisoformat(entered)
        b = datetime.fromisoformat(exited)
        if key not in groups:
            groups[key] = {'member_id': mid, 'facility': fac, 'visits': 0, 'total_minutes': 0.0, 'first_seen': entered, 'last_seen': entered}
        row = groups[key]
        row['visits'] += 1
        row['total_minutes'] += (b - a).total_seconds() / 60
        if entered < row['first_seen']:
            row['first_seen'] = entered
        if entered > row['last_seen']:
            row['last_seen'] = entered
    result = list(groups.values())
    for row in result:
        row['total_minutes'] = round(row['total_minutes'], 2)
    primary = {'visits': lambda r: (-r['visits'],), 'duration': lambda r: (-r['total_minutes'],), 'last_seen': lambda r: (r['last_seen'],), 'member': lambda r: (r['member_id'], r['facility'])}[order]
    result.sort(key=lambda r: primary(r) + (-r['visits'], -r['total_minutes'], r['last_seen'], r['member_id'], r['facility']))
    return result

