        row['visits'] += 1
        row['total_minutes'] += (b - a).total_seconds() / 60
        if entered < row['first_seen']:
            row['first_seen'] = entered
        if entered > row['last_seen']:
            row['last_seen'] = entered
    result = list(groups.values())
    for row in result:
        row['total_minutes'] = round(row['total_minutes'], 2)
    primary = {'visits': lambda r: (-r['visits'],), 'duration': lambda r: (-r['total_minutes'],), 'last_seen': lambda r: (r['last_seen'],), 'member': lambda r: (r['member_id'], r['facility'])}[order]
    result.sort(key=lambda r: primary(r) + (-r['visits'], -r['total_minutes'], r['last_seen'], r['member_id'], r['facility']))
    return result

