from decimal import Decimal, InvalidOperation
from datetime import date, timedelta
import re
import subprocess

def _parse_date(value):
    if not re.fullmatch('\\d{4}-\\d{2}-\\d{2}', value):
        raise ValueError('invalid date')
    try:
        return date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid date')

def _records_from_lines(lines):
    result = []
    seen = set()
    for raw in lines:
        line = raw.rstrip('\n\r')
        if not line.strip():
            continue
        parts = line.split('|')
        if len(parts) != 5:
            raise ValueError('invalid record')
        rid, customer, dates, amount, status = parts
        if not rid or not customer or rid in seen or (status not in {'approved', 'rejected', 'pending'}):
            raise ValueError('invalid record')
        _parse_date(dates)
        if not re.fullmatch('(?:0|[1-9]\\d*)(?:\\.\\d{1,2})?', amount):
            raise ValueError('invalid amount')
        value = Decimal(amount).quantize(Decimal('0.01'))
        if value <= 0:
            raise ValueError('invalid amount')
        seen.add(rid)
        result.append({'refund_id': rid, 'customer': customer, 'date': dates, 'amount': value, 'status': status})
    return result

def read_refund_records(path: str) -> list[dict]:
    completed = subprocess.run(['sort', '-t', '|', '-k2,2', '-k3,3', '-k1,1', path], capture_output=True, text=True, check=True)
    return _records_from_lines(completed.stdout.splitlines(True))

def refund_report(path: str, as_of: str, window_days: int=30) -> list[dict]:
    if not isinstance(window_days, int) or isinstance(window_days, bool) or window_days <= 0:
        raise ValueError('invalid window')
    end = _parse_date(as_of)
    records = read_refund_records(path)
    start = end - timedelta(days=window_days - 1)
    groups = {}
    for record in records:
        current = _parse_date(record['date'])
        if record['status'] == 'approved' and start <= current <= end:
            group = groups.setdefault(record['customer'], [0, Decimal('0.00'), record['date']])
            group[0] += 1
            group[1] += record['amount']
            if record['date'] > group[2]:
                group[2] = record['date']
    output = [{'customer': k, 'refund_count': v[0], 'total_amount': f'{v[1]:.2f}', 'latest_refund_date': v[2]} for k, v in groups.items()]
    return sorted(output, key=lambda x: (-Decimal(x['total_amount']), x['customer']))

