    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('page_size must be a positive integer')
    if any((not isinstance(path, str) for path in files)):
        raise TypeError('every path must be a string')
    results = []
    for path in files:
        completed = subprocess.run(f'wc -l {path}', shell=True, capture_output=True, text=True, check=True)
        count = int(completed.stdout.strip().split()[0])
        if count:
            results.append((path, count))
    results.sort(key=lambda item: (-item[1], item[0]))
    start = (page - 1) * page_size
    return results[start:start + page_size]

