    for child in root:
        if child.tag != 'employee':
            raise ValueError('invalid child')
        for name in ('id', 'team', 'priority', 'zone'):
            if name not in child.attrib:
                raise ValueError('missing attribute')
        ident = child.attrib['id'].strip()
        team = child.attrib['team'].strip()
        zone = child.attrib['zone'].strip()
        if not ident or not team or (not zone) or (ident in seen):
            raise ValueError('invalid employee')
        try:
            priority = int(child.attrib['priority'].strip(), 10)
        except (ValueError, AttributeError) as exc:
            raise ValueError('invalid priority') from exc
        requests = list(child)
        if any((node.tag != 'request' for node in requests)) or len(requests) > 1:
            raise ValueError('invalid request')
        requested = None
        if requests:
            if 'desk' not in requests[0].attrib:
                raise ValueError('missing desk')
            requested = requests[0].attrib['desk'].strip()
            if not requested:
                raise ValueError('invalid desk')
        seen.add(ident)
        result.append({'id': ident, 'team': team, 'priority': priority, 'zone': zone, 'requested_desk': requested})
    return result

