    employees = load_requests(xml_text)
    ordered = sorted(employees, key=lambda x: (-x['priority'], x['team'], x['id']))
    free = set(available_desks)
    result = {}
    for employee in ordered:
        wanted = employee['requested_desk']
        if wanted in free and available_desks[wanted] == employee['zone']:
            chosen = wanted
        else:
            choices = sorted((desk for desk in free if available_desks[desk] == employee['zone']))
            chosen = choices[0] if choices else None
        result[employee['id']] = chosen
        if chosen is not None:
            free.remove(chosen)
    return result

def allocation_summary(assignments: dict[str, str | None], available_desks: dict[str, str]) -> dict[str, object]:
    counts = {zone: 0 for zone in sorted(set(available_desks.values()))}
    assigned = 0
    for desk in assignments.values():
        if desk is None:
            continue
        if not isinstance(desk, str) or desk not in available_desks:
            raise ValueError('unknown desk')
        assigned += 1
        counts[available_desks[desk]] += 1
    return {'assigned': assigned, 'unassigned': len(assignments) - assigned, 'by_zone': counts}

