import csv
import io
import os
import tempfile
from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def export_reservation_report(reservations: list[dict[str, object]], period_start: str, period_end: str) -> bytes:
    try:
        start = date.fromisoformat(period_start)
        end = date.fromisoformat(period_end)
    except (TypeError, ValueError):
        raise ValueError('invalid period')
    if start > end:
        raise ValueError('invalid period')
    totals: dict[str, list[object]] = {}
    for item in reservations:
        try:
            campground = item['campground']
            check_in = date.fromisoformat(item['check_in'])
            check_out = date.fromisoformat(item['check_out'])
            guests = item['guests']
            if not isinstance(campground, str) or not isinstance(guests, int) or isinstance(guests, bool) or (guests <= 0):
                raise ValueError
            if check_out <= check_in:
                raise ValueError
            rate = Decimal(str(item['nightly_rate']))
            if rate < 0 or not rate.is_finite():
                raise ValueError
        except (KeyError, TypeError, ValueError, InvalidOperation):
            raise ValueError('invalid reservation')
        if check_in >= start and check_out <= end:
            nights = (check_out - check_in).days
            if campground not in totals:
                totals[campground] = [0, 0, 0, Decimal('0')]
            row = totals[campground]
            row[0] += 1
            row[1] += nights
            row[2] += guests
            row[3] += rate * nights * guests
    rows = [(name, *values) for name, values in totals.items()]
    rows.sort(key=lambda r: (-r[4], r[0]))
    output = io.StringIO(newline='')
    writer = csv.writer(output, lineterminator='\n')
    writer.writerow(['campground', 'reservations', 'nights', 'guests', 'revenue'])
    for name, count, nights, guests, revenue in rows:
        amount = revenue.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        writer.writerow([name, count, nights, guests, format(amount, '.2f')])
    fd, path = tempfile.mkstemp()
    try:
        with os.fdopen(fd, 'wb') as handle:
            handle.write(output.getvalue().encode('utf-8'))
        with open(path, 'rb') as handle:
            return handle.read()
    finally:
        try:
            os.unlink(path)
        except FileNotFoundError:
            pass

