import csv
import io
from datetime import date
from typing import Any

def parse_registration_feed(text: str) -> list[dict[str, str]]:
    if not text:
        raise ValueError('empty feed')
    rows = list(csv.reader(io.StringIO(text), strict=True))
    if not rows or rows[0] != ['voter_id', 'effective_date', 'status']:
        raise ValueError('invalid header')
    result = []
    seen = set()
    for row in rows[1:]:
        if not row:
            raise ValueError('blank row')
        if len(row) != 3 or any((x == '' for x in row)):
            raise ValueError('invalid row')
        if row[0] in seen:
            raise ValueError('duplicate voter')
        try:
            date.fromisoformat(row[1])
        except ValueError:
            raise ValueError('invalid date')
        if row[2] not in {'pending', 'approved', 'rejected'}:
            raise ValueError('invalid status')
        seen.add(row[0])
        result.append({'voter_id': row[0], 'effective_date': row[1], 'status': row[2]})
    return result

def apply_registration_batch(requester: dict[str, Any], registry: dict[str, dict[str, Any]], feed: str) -> dict[str, Any]:
    updates = parse_registration_feed(feed)
    for item in updates:
        voter = registry.get(item['voter_id'])
        if voter is None:
            raise KeyError(item['voter_id'])
        if voter.get('tenant_id') != requester.get('tenant_id'):
            raise PermissionError('tenant')
        allowed = {'administrator', 'registrar'} & set(requester.get('roles', []))
        if not allowed and voter.get('owner_id') != requester.get('id'):
            raise PermissionError('permission')
        history = voter.get('history', [])
        if history and item['effective_date'] < history[-1]['effective_date']:
            raise ValueError('earlier update')
    ordered = sorted(updates, key=lambda x: (x['effective_date'], x['voter_id']))
    counts = {'pending': 0, 'approved': 0, 'rejected': 0}
    for item in ordered:
        voter = registry[item['voter_id']]
        voter['status'] = item['status']
        voter.setdefault('history', []).append({'effective_date': item['effective_date'], 'status': item['status']})
        counts[item['status']] += 1
    return {'updated': len(updates), 'by_status': counts, 'ids': sorted({x['voter_id'] for x in updates})}

