import csv
import math
import os
import tempfile
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from typing import Any

def export_rental_report(records: list[dict[str, Any]], destination: str, page: int=1, page_size: int=50) -> dict[str, Any]:
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('page must be positive')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('page_size must be positive')
    groups: dict[tuple[str, str], dict[str, Any]] = {}
    for record in records:
        if not isinstance(record, dict):
            raise TypeError('each record must be a dictionary')
        title = record.get('title')
        category = record.get('category')
        days = record.get('days')
        rate = record.get('daily_rate')
        returned = record.get('returned')
        if not isinstance(title, str) or not title:
            raise ValueError('invalid title')
        if not isinstance(category, str) or not category:
            raise ValueError('invalid category')
        if isinstance(days, bool) or not isinstance(days, int) or days < 1:
            raise ValueError('invalid days')
        if isinstance(rate, bool) or not isinstance(rate, (int, float)) or rate < 0:
            raise ValueError('invalid rate')
        if not isinstance(returned, bool):
            raise ValueError('invalid returned value')
        if returned:
            try:
                amount = Decimal(str(days)) * Decimal(str(rate))
            except InvalidOperation:
                raise ValueError('invalid rate')
            key = (title, category)
            if key not in groups:
                groups[key] = {'title': title, 'category': category, 'rental_count': 0, 'amount': Decimal('0')}
            groups[key]['rental_count'] += 1
            groups[key]['amount'] += amount
    rows = []
    for item in groups.values():
        revenue = item['amount'].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        rows.append({'title': item['title'], 'category': item['category'], 'rental_count': item['rental_count'], 'revenue': revenue})
    rows.sort(key=lambda item: (-item['revenue'], item['title'], item['category']))
    total = sum((item['revenue'] for item in rows), Decimal('0')).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    pages = math.ceil(len(rows) / page_size) if rows else 0
    start = (page - 1) * page_size
    selected = rows[start:start + page_size]
    public_rows = [{**item, 'revenue': float(item['revenue'])} for item in selected]
    directory = os.path.dirname(os.path.abspath(destination)) or '.'
    fd, temporary = tempfile.mkstemp(dir=directory, prefix='.rental-')
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as handle:
            writer = csv.writer(handle)
            writer.writerow(['title', 'category', 'rental_count', 'revenue'])
            for item in rows:
                writer.writerow([item['title'], item['category'], item['rental_count'], f"{item['revenue']:.2f}"])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return {'total_rentals': sum((item['rental_count'] for item in rows)), 'total_revenue': float(total), 'rows': public_rows, 'page': page, 'page_size': page_size, 'pages': pages}

