                raise ValueError('invalid vehicle')
            self.vehicles[item['id']] = deepcopy(item)
        self.records = {}
        self.next_id = 1

    def _requester(self, requester):
        if not isinstance(requester, dict) or not isinstance(requester.get('id'), str) or (not isinstance(requester.get('tenant_id'), str)) or (not isinstance(requester.get('roles'), list)):
            raise ValueError('invalid requester')

    def _time(self, value):
        try:
            result = datetime.fromisoformat(value)
        except (TypeError, ValueError):
            raise ValueError('invalid timestamp')
        if result.tzinfo is not None:
            raise ValueError('timezone not supported')
        return result

    def reserve(self, requester, vehicle_id, start, end):
        self._requester(requester)
        if vehicle_id not in self.vehicles:
            raise KeyError(vehicle_id)
        vehicle = self.vehicles[vehicle_id]
        if requester['tenant_id'] != vehicle['tenant_id']:
            raise ValueError('tenant mismatch')
        begin, finish = (self._time(start), self._time(end))
        if finish <= begin:
            raise ValueError('invalid interval')
        for old in self.records.values():
            if old['status'] == 'active' and old['vehicle_id'] == vehicle_id and (begin < old['_end']) and (finish > old['_start']):
                raise ValueError('overlap')
        rid = 'R%04d' % self.next_id
        self.next_id += 1
        minutes = (finish - begin).total_seconds() / 60
        record = {'id': rid, 'vehicle_id': vehicle_id, 'tenant_id': vehicle['tenant_id'], 'requester_id': requester['id'], 'start': start, 'end': end, 'cost_cents': (int(minutes) + 59) // 60 * vehicle['rate_cents_per_hour'], 'status': 'active', '_start': begin, '_end': finish}
        self.records[rid] = record
        return {k: v for k, v in record.items() if not k.startswith('_')}

    def cancel(self, requester, reservation_id):
        self._requester(requester)
        if reservation_id not in self.records:
            raise KeyError(reservation_id)
        record = self.records[reservation_id]
        if record['status'] != 'active':
            raise ValueError('already cancelled')
        if requester['tenant_id'] != record['tenant_id'] and 'fleet_manager' not in requester['roles']:
            raise PermissionError('not allowed')
        if requester['id'] != record['requester_id'] and 'fleet_manager' not in requester['roles']:
            raise PermissionError('not allowed')
        record['status'] = 'cancelled'
        return {k: v for k, v in record.items() if not k.startswith('_')}

    def utilization(self, tenant_id, start, end):
        begin, finish = (self._time(start), self._time(end))
        if finish <= begin:
            raise ValueError('invalid interval')
        result = []
        for vehicle_id in sorted((v for v, x in self.vehicles.items() if x['tenant_id'] == tenant_id)):
            total = count = 0
            for record in self.records.values():
                left, right = (max(begin, record['_start']), min(finish, record['_end']))
                if record['status'] == 'active' and record['vehicle_id'] == vehicle_id and (right > left):
                    total += int((right - left).total_seconds() // 60)
                    count += 1
