import hashlib
import hmac
import os

def create_case(parcel_id: str, investigator: str, pin: str, loss_cents: int) -> dict:
    if not isinstance(parcel_id, str) or not parcel_id.strip():
        raise ValueError('invalid parcel_id')
    if not isinstance(investigator, str) or not investigator.strip():
        raise ValueError('invalid investigator')
    if not isinstance(pin, str) or not 4 <= len(pin) <= 12 or (not all(('0' <= c <= '9' for c in pin))):
        raise ValueError('invalid pin')
    if isinstance(loss_cents, bool) or not isinstance(loss_cents, int):
        raise TypeError('loss_cents must be an integer')
    if loss_cents < 0:
        raise ValueError('invalid loss')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return {'parcel_id': parcel_id, 'investigator': investigator, 'loss_cents': loss_cents, 'pin_record': salt.hex() + '$' + digest.hex()}

def verify_pin(case: dict, pin: str) -> bool:
    if not isinstance(pin, str) or not isinstance(case, dict):
        return False
    record = case.get('pin_record')
    if not isinstance(record, str) or '$' not in record:
        return False
    try:
        salt_text, digest_text = record.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except ValueError:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def summarize_cases(cases: list[dict], page: int=1, page_size: int=10) -> list[dict]:
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('invalid page_size')
    grouped = {}
    for case in cases:
        name = case['investigator']
