def review_summary(documents: list[dict]) -> dict:
    statuses = {'pending': 0, 'reviewed': 0, 'privileged': 0, 'redacted': 0}
    custodians = {}
    tags = {}
    seen = set()
    total = 0
    for doc in documents:
        if not isinstance(doc, dict):
            raise ValueError('invalid document')
        if not isinstance(doc.get('id'), str) or not doc['id'] or doc['id'] in seen:
            raise ValueError('invalid id')
        seen.add(doc['id'])
        status = doc.get('status')
        custodian = doc.get('custodian')
        size = doc.get('size')
        tag_list = doc.get('tags')
        if status not in statuses or not isinstance(custodian, str) or (not custodian):
            raise ValueError('invalid metadata')
        if not isinstance(size, int) or isinstance(size, bool) or size < 0:
            raise ValueError('invalid size')
        if not isinstance(tag_list, list) or any((not isinstance(x, str) or not x for x in tag_list)):
            raise ValueError('invalid tags')
        statuses[status] += 1
        total += size
        item = custodians.setdefault(custodian, [0, 0])
        item[0] += 1
        item[1] += size
        for tag in tag_list:
            tags[tag] = tags.get(tag, 0) + 1
    return {'documents': len(documents), 'bytes': total, 'statuses': statuses, 'custodians': [{'name': n, 'documents': custodians[n][0], 'bytes': custodians[n][1]} for n in sorted(custodians)], 'tags': [{'tag': n, 'count': c} for n, c in sorted(tags.items(), key=lambda x: (-x[1], x[0]))]}

