        parts = signature_header.split(';')
        if len(parts) != 2 or not parts[0].startswith('kid=') or (not parts[1].startswith('sig=')):
            raise ValueError('header')
        kid = parts[0][4:]
        text = parts[1][4:]
        if not kid or len(text) != 64 or text != text.lower() or any((c not in '0123456789abcdef' for c in text)):
            raise ValueError('signature')
        if kid not in secrets:
            raise ValueError('key')
        supplied = bytes.fromhex(text)
        expected = hmac.new(secrets[kid], payload, hashlib.sha256).digest()
        if not hmac.compare_digest(expected, supplied):
            raise ValueError('signature')
        event = json.loads(payload.decode('utf-8'))
        if not isinstance(event, dict) or not isinstance(event.get('event_id'), str) or (not event['event_id']):
            raise ValueError('event')
        if not isinstance(event.get('documents'), list):
            raise ValueError('documents')
        summary = review_summary(event['documents'])
        return {'event': event, 'summary': summary}
    except ValueError:
        raise
    except (TypeError, UnicodeError, json.JSONDecodeError, KeyError):
        raise ValueError('invalid webhook')

