        if not isinstance(ident, str) or not ident or (not isinstance(weight, int)) or isinstance(weight, bool) or (weight <= 0) or (not isinstance(minutes, int)) or isinstance(minutes, bool) or (minutes <= 0) or (not isinstance(priority, int)) or isinstance(priority, bool):
            raise ValueError('invalid stop')
