import csv
import datetime
import os
import tempfile

def parse_visits(text: str) -> list[dict[str, object]]:
    try:
        rows = list(csv.DictReader(text.splitlines()))
    except csv.Error as e:
        raise ValueError('invalid csv') from e
    if not text.strip():
        return []
    expected = ['inmate', 'visitor', 'date', 'start', 'duration', 'status']
    if not rows and text.splitlines()[0].split(',') != expected:
        raise ValueError('header')
    if not rows and text.splitlines()[0] == ','.join(expected):
        return []
    if rows and list(rows[0].keys()) != expected:
        raise ValueError('header')
    out = []
    for row in rows:
        if None in row or any((row[k] is None for k in expected)):
            raise ValueError('row')
        vals = {k: row[k].strip() for k in expected}
        if not vals['inmate'] or not vals['visitor'] or vals['status'] not in ('approved', 'pending'):
            raise ValueError('value')
        try:
            datetime.date.fromisoformat(vals['date'])
            datetime.datetime.strptime(vals['start'], '%H:%M')
            duration = int(vals['duration'])
        except (ValueError, TypeError) as e:
            raise ValueError('value') from e
        if len(vals['start']) != 5 or not 15 <= duration <= 120:
            raise ValueError('value')
        out.append({'inmate': vals['inmate'], 'visitor': vals['visitor'], 'date': vals['date'], 'start': vals['start'], 'duration': duration, 'status': vals['status']})
    return out

def build_schedule(records: list[dict[str, object]], day: str, rooms: list[str]) -> list[dict[str, object]]:
    try:
        datetime.date.fromisoformat(day)
    except ValueError as e:
        raise ValueError('day') from e
    if not rooms or any((not isinstance(r, str) or not r for r in rooms)) or len(set(rooms)) != len(rooms):
        raise ValueError('rooms')
    chosen = [r for r in records if r['date'] == day and r['status'] == 'approved']
    chosen.sort(key=lambda r: (r['start'], r['inmate'], r['visitor']))
    seen = set()
    occupied = {r: [] for r in rooms}
    result = []
    for r in chosen:
        key = (r['inmate'], r['visitor'], r['date'], r['start'])
        if key in seen:
            raise ValueError('duplicate')
        seen.add(key)
        start = datetime.datetime.strptime(r['start'], '%H:%M')
        end = start + datetime.timedelta(minutes=int(r['duration']))
        if end.date() != start.date():
            raise ValueError('midnight')
        room = next((x for x in rooms if all((end <= a or start >= b for a, b in occupied[x]))), None)
        if room is None:
            raise ValueError('capacity')
        occupied[room].append((start, end))
        result.append({'inmate': r['inmate'], 'visitor': r['visitor'], 'date': day, 'start': r['start'], 'end': end.strftime('%H:%M'), 'room': room})
    return result

def export_schedule(schedule: list[dict[str, object]], destination: str) -> str:
    fields = ['inmate', 'visitor', 'date', 'start', 'end', 'room']
    fd, temporary = tempfile.mkstemp(dir=os.path.dirname(destination) or '.', text=True)
    os.close(fd)
    try:
        with open(temporary, 'w', newline='') as f:
            writer = csv.DictWriter(f, fieldnames=fields)
            writer.writeheader()
            for row in schedule:
                if set(row) != set(fields):
                    raise ValueError('row')
                try:
                    a = datetime.datetime.strptime(str(row['start']), '%H:%M')
                    b = datetime.datetime.strptime(str(row['end']), '%H:%M')
                except ValueError as e:
                    raise ValueError('time') from e
                if b <= a:
                    raise ValueError('time')
                writer.writerow(row)
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return destination

