from solution import generate_claim_verification_code

import re
import pytest


def test_generates_code_with_expected_format():
    code = generate_claim_verification_code("CLM-123456")
    assert re.fullmatch(r"CLM-123456:[A-Z0-9]{8}", code)


def test_preserves_different_valid_claim_ids():
    first = generate_claim_verification_code("CLM-000001")
    second = generate_claim_verification_code("CLM-987654")
    assert first.startswith("CLM-000001:")
    assert second.startswith("CLM-987654:")
    assert len(first) == len("CLM-000001:") + 8
    assert len(second) == len("CLM-987654:") + 8


def test_suffix_uses_only_allowed_characters():
    for _ in range(10):
        code = generate_claim_verification_code("CLM-246810")
        suffix = code.split(":", 1)[1]
        assert len(suffix) == 8
        assert all(character in "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789" for character in suffix)


def test_repeated_calls_produce_distinct_codes():
    codes = {generate_claim_verification_code("CLM-111111") for _ in range(20)}
    assert len(codes) == 20


def test_rejects_invalid_claim_id_formats():
    invalid_values = ["", "CLM-12345", "CLM-1234567", "CLAIM-123456", "CLM-12A456", "clm-123456", "123456"]
    for value in invalid_values:
        with pytest.raises(ValueError):
            generate_claim_verification_code(value)


def test_rejects_non_string_claim_ids():
    for value in (None, 123456, b"CLM-123456", ["CLM-123456"]):
        with pytest.raises(ValueError):
            generate_claim_verification_code(value)

