from lxml import etree

def summarize_client_plan(xml_text: str, client_id: str, week: int=1, page: int=1, page_size: int=10) -> dict:
    if not client_id or week < 1 or page < 1 or (page_size < 1):
        raise ValueError('invalid argument')
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'plan':
        raise ValueError('invalid root')
    chosen = None
    for client in root.findall('client'):
        if client.get('id') is None:
            raise ValueError('missing client id')
        if client.get('id') == client_id:
            chosen = client
    groups = {}
    if chosen is not None:
        for session in chosen.findall('session'):
            required = ('week', 'type', 'duration', 'calories', 'completed')
            if any((session.get(name) is None for name in required)):
                raise ValueError('missing session attribute')
            try:
                session_week = int(session.get('week'))
                duration = int(session.get('duration'))
                calories = float(session.get('calories'))
            except (TypeError, ValueError) as exc:
                raise ValueError('invalid session value') from exc
            if session_week < 0 or duration < 0 or calories < 0:
                raise ValueError('invalid session value')
            if session_week != week or session.get('completed') != 'true':
                continue
            kind = session.get('type')
            if not kind:
                raise ValueError('invalid session type')
            item = groups.setdefault(kind, [0, 0, 0.0])
            item[0] += 1
            item[1] += duration
            item[2] += calories
    activities = [{'type': kind, 'sessions': vals[0], 'minutes': vals[1], 'calories': round(vals[2], 1)} for kind, vals in groups.items()]
    activities.sort(key=lambda item: (-item['calories'], item['type']))
    start = (page - 1) * page_size
    selected = activities[start:start + page_size]
    return {'client': client_id, 'week': week, 'total_sessions': sum((x['sessions'] for x in activities)), 'total_minutes': sum((x['minutes'] for x in activities)), 'total_calories': round(sum((x['calories'] for x in activities)), 1), 'activities': selected}

