import hmac
import json

def verify_training_webhook(payload: bytes, signature: str, secret: str) -> dict:
    if not isinstance(signature, str) or not signature.startswith('sha256='):
        raise ValueError('invalid signature')
    supplied = signature[7:]
    if len(supplied) != 64 or any((c not in '0123456789abcdef' for c in supplied)):
        raise ValueError('invalid signature')
    expected = hmac.new(secret.encode('utf-8'), payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(supplied, expected):
        raise ValueError('invalid signature')
    try:
        value = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    if not isinstance(value, dict) or value.get('event') != 'training_job' or (not isinstance(value.get('job_id'), str)) or (not value['job_id']) or (value.get('status') not in {'queued', 'running', 'completed', 'failed'}):
        raise ValueError('invalid payload')
    return value

