from xml.etree import ElementTree as ET

def _bad():
    raise ValueError('invalid save')

def parse_save(xml: str) -> dict:
    try:
        root = ET.fromstring(xml)
    except Exception:
        _bad()
    if root.tag != 'save' or set(root.attrib) != {'player', 'tick'} or (not root.attrib['player']):
        _bad()
    try:
        tick = int(root.attrib['tick'])
    except Exception:
        _bad()
    if tick < 0 or (root.text and root.text.strip()):
        _bad()
    parts = {x.tag: x for x in root}
    if set(parts) != {'inventory', 'quests', 'stats'} or len(parts) != 3:
        _bad()
    out = {'player': root.attrib['player'], 'tick': tick, 'inventory': {}, 'quests': {}, 'stats': {}}
    for x in root:
        if x.tail and x.tail.strip():
            _bad()
    for e in parts['inventory']:
        if e.tag != 'item' or set(e.attrib) != {'id', 'qty', 'equipped'} or (not e.attrib['id']) or (e.attrib['id'] in out['inventory']) or (e.text and e.text.strip()):
            _bad()
        try:
            q = int(e.attrib['qty'])
        except Exception:
            _bad()
        if q < 0 or e.attrib['equipped'] not in ('0', '1'):
            _bad()
        out['inventory'][e.attrib['id']] = {'qty': q, 'equipped': e.attrib['equipped'] == '1'}
    for e in parts['quests']:
        if e.tag != 'quest' or set(e.attrib) != {'id', 'progress', 'status'} or (not e.attrib['id']) or (e.attrib['id'] in out['quests']) or (e.attrib['status'] not in ('locked', 'active', 'completed')):
            _bad()
        try:
            p = int(e.attrib['progress'])
        except Exception:
            _bad()
        if p < 0:
            _bad()
        out['quests'][e.attrib['id']] = {'progress': p, 'status': e.attrib['status']}
    for e in parts['stats']:
        if e.tag != 'stat' or set(e.attrib) != {'name', 'value'} or (not e.attrib['name']) or (e.attrib['name'] in out['stats']) or (e.text and e.text.strip()):
            _bad()
        try:
            v = int(e.attrib['value'])
        except Exception:
            _bad()
        if v < 0:
            _bad()
        out['stats'][e.attrib['name']] = v
    for k in ('inventory', 'quests', 'stats'):
        out[k] = {x: out[k][x] for x in sorted(out[k])}
    return out

def merge_saves(local: dict, remote: dict) -> dict:
    if local['player'] != remote['player']:
        raise ValueError('different players')
    r = {'player': local['player'], 'tick': max(local['tick'], remote['tick']), 'inventory': {}, 'quests': {}, 'stats': {}}
    for k in set(local['inventory']) | set(remote['inventory']):
        a, b = (local['inventory'].get(k), remote['inventory'].get(k))
        r['inventory'][k] = {'qty': max((a or {}).get('qty', 0), (b or {}).get('qty', 0)), 'equipped': (a or {}).get('equipped', False) or (b or {}).get('equipped', False)}
    rank = {'locked': 0, 'active': 1, 'completed': 2}
    for k in set(local['quests']) | set(remote['quests']):
        a, b = (local['quests'].get(k), remote['quests'].get(k))
        r['quests'][k] = dict(a or b) if not a or not b else dict(a if (a['progress'], rank[a['status']]) >= (b['progress'], rank[b['status']]) else b)
    for k in set(local['stats']) | set(remote['stats']):
        r['stats'][k] = max(local['stats'].get(k, 0), remote['stats'].get(k, 0))
    for k in ('inventory', 'quests', 'stats'):
        r[k] = {x: r[k][x] for x in sorted(r[k])}
    return r

def synchronize(local_xml: str, remote_xml: str) -> str:
    d = merge_saves(parse_save(local_xml), parse_save(remote_xml))
    root = ET.Element('save', player=d['player'], tick=str(d['tick']))
    inv = ET.SubElement(root, 'inventory')
    for k, v in d['inventory'].items():
        ET.SubElement(inv, 'item', id=k, qty=str(v['qty']), equipped='1' if v['equipped'] else '0')
    qs = ET.SubElement(root, 'quests')
    for k, v in d['quests'].items():
        ET.SubElement(qs, 'quest', id=k, progress=str(v['progress']), status=v['status'])
    st = ET.SubElement(root, 'stats')
    for k, v in d['stats'].items():
        ET.SubElement(st, 'stat', name=k, value=str(v))
    return ET.tostring(root, encoding='unicode', short_empty_elements=True).replace(' />', '/>')

