import csv
import os
import tempfile

def parse_manifest(text: str) -> list[dict[str, str]]:
    rows = list(csv.reader((line for line in text.splitlines() if line.strip())))
    if not rows or [x.strip() for x in rows[0]] != ['package', 'version', 'license', 'usage']:
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if len(row) != 4:
            raise ValueError('invalid row')
        values = [x.strip() for x in row]
        if not all(values[:3]):
            raise ValueError('empty field')
        try:
            usage = int(values[3])
        except ValueError:
            raise ValueError('invalid usage')
        if not 0 <= usage <= 100 or str(usage) != values[3].lstrip('+'):
            raise ValueError('invalid usage')
        result.append(dict(zip(['package', 'version', 'license', 'usage'], values)))
    if not result:
        raise ValueError('empty manifest')
    return result

def _version(value: str) -> tuple[int, ...]:
    parts = value.split('.')
    if not all((p.isdigit() for p in parts)):
        raise ValueError('invalid version')
    return tuple((int(p) for p in parts))

def write_compliance_report(manifest_text: str, approved: set[str], destination: str) -> dict[str, int]:
    records = parse_manifest(manifest_text)
    counts = {'COMPLIANT': 0, 'NONCOMPLIANT': 0}
    prepared = []
    for record in records:
        status = 'COMPLIANT' if record['license'] in approved and int(record['usage']) <= 80 else 'NONCOMPLIANT'
        counts[status] += 1
        prepared.append((status, record))
    prepared.sort(key=lambda item: (item[0] != 'NONCOMPLIANT', item[1]['package'].casefold(), tuple((-x for x in _version(item[1]['version']))), item[1]['license']))
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=directory, prefix='.license-', suffix='.csv')
    try:
        with os.fdopen(fd, 'w', newline='') as stream:
            writer = csv.writer(stream, lineterminator='\n')
            writer.writerow(['package', 'version', 'license', 'usage', 'status'])
            for status, record in prepared:
                writer.writerow([record['package'], record['version'], record['license'], record['usage'], status])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return counts

