import datetime
import hashlib
import hmac
import json
import math

def sign_fueling_webhook(body: bytes, secret: bytes) -> str:
    return hmac.new(secret, body, hashlib.sha256).hexdigest()

def _record(value):
    if not isinstance(value, dict) or set(value) != {'event_id', 'vehicle_id', 'station', 'occurred_at', 'liters', 'price_per_liter'}:
        raise ValueError('invalid record')
    for key in ('event_id', 'vehicle_id', 'station'):
        if not isinstance(value[key], str) or not value[key]:
            raise ValueError('invalid text')
    stamp = value['occurred_at']
    if not isinstance(stamp, str) or not stamp.endswith('Z'):
        raise ValueError('invalid time')
    try:
        parsed = datetime.datetime.strptime(stamp, '%Y-%m-%dT%H:%M:%SZ')
    except ValueError:
        raise ValueError('invalid time')
    result = {}
    for key in ('liters', 'price_per_liter'):
        number = value[key]
        if isinstance(number, bool) or not isinstance(number, (int, float)) or (not math.isfinite(number)):
            raise ValueError('invalid number')
        result[key] = float(number)
    if result['liters'] <= 0 or result['liters'] > 1000 or result['price_per_liter'] < 0:
        raise ValueError('invalid amount')
    result.update(event_id=value['event_id'], vehicle_id=value['vehicle_id'], station=value['station'], occurred_at=parsed.strftime('%Y-%m-%dT%H:%M:%SZ'))
    return result

def verify_fueling_webhook(body: bytes, signature: str, secret: bytes) -> dict:
    try:
        supplied = signature.encode('ascii')
    except (AttributeError, UnicodeEncodeError):
        raise ValueError('invalid signature')
    expected = hmac.new(secret, body, hashlib.sha256).hexdigest().encode('ascii')
    if len(supplied) != len(expected) or not hmac.compare_digest(expected, supplied):
        raise ValueError('invalid signature')
    try:
        value = json.loads(body.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('invalid body')
    return _record(value)

def summary_fueling(records: list[dict]) -> list[dict]:
    groups = {}
    seen = set()
    for raw in records:
        item = _record(raw)
        if item['event_id'] in seen:
            raise ValueError('duplicate event')
        seen.add(item['event_id'])
        key = (item['vehicle_id'], item['occurred_at'][:10])
        group = groups.setdefault(key, {'liters': 0.0, 'cost': 0.0, 'count': 0, 'stations': set()})
        group['liters'] += item['liters']
        group['cost'] += item['liters'] * item['price_per_liter']
        group['count'] += 1
        group['stations'].add(item['station'])
    output = []
    for vehicle, date in sorted(groups):
        group = groups[vehicle, date]
        output.append({'vehicle_id': vehicle, 'date': date, 'total_liters': round(group['liters'], 3), 'total_cost': round(group['cost'], 2), 'event_count': group['count'], 'stations': sorted(group['stations'])})
    return output

