import ast
import operator

def _evaluate(expression, variables):
    try:
        tree = ast.parse(expression, mode='eval')
    except SyntaxError as exc:
        raise ValueError('invalid expression') from exc

    def visit(node):
        if isinstance(node, ast.Expression):
            return visit(node.body)
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in variables:
                raise NameError(node.id)
            return variables[node.id]
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
            value = visit(node.operand)
            return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
        if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
            left, right = (visit(node.left), visit(node.right))
            return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
        if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
            values = [visit(v) for v in node.values]
            result = values[0]
            for value in values[1:]:
                result = value if result and isinstance(node.op, ast.And) or (not result and isinstance(node.op, ast.Or)) else result
            return result
        if isinstance(node, ast.Compare):
            left = visit(node.left)
            for op, comparator in zip(node.ops, node.comparators):
                right = visit(comparator)
                functions = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}
                if type(op) not in functions:
                    raise ValueError('unsupported expression')
                if not functions[type(op)](left, right):
                    return False
                left = right
            return True
        raise ValueError('unsupported expression')
    return visit(tree)

def rank_maintenance(records: list[dict[str, object]], rule: str, score: str) -> list[str]:
    names = ('vibration', 'temperature', 'hours_since_service', 'criticality')
    ranked = []
    for position, record in enumerate(records):
        values = {name: record[name] for name in names}
        if _evaluate(rule, values):
            ranked.append((-_evaluate(score, values), position, record['id']))
    ranked.sort(key=lambda item: (item[0], item[1]))
    return [item[2] for item in ranked]

