    try:
        root = etree.fromstring(xml_text.encode('utf-8'), parser)
    except Exception as exc:
        raise ValueError from exc
    if root.tag != 'leases' or not len(root):
        raise ValueError
    result, ids = ([], set())
    for node in root:
        if node.tag != 'lease' or node.get('id') is None or node.get('tenant') is None:
            raise ValueError
        ident = node.get('id')
        if not ident or ident in ids:
            raise ValueError
        ids.add(ident)
        terms = [x for x in node if x.tag == 'term']
        if len(terms) != 1 or len(node) != 1:
            raise ValueError
        term = terms[0]
        try:
            start, end = (date.fromisoformat(term.get('start')), date.fromisoformat(term.get('end')))
        except Exception as exc:
            raise ValueError from exc
        if start > end:
            raise ValueError
        rents = [x for x in term if x.tag == 'rent']
        if len(rents) != 1 or rents[0].get('currency') != 'USD':
            raise ValueError
        base = _money(rents[0].text or '')
        groups = [x for x in term if x.tag == 'adjustments']
        if len(groups) > 1 or any((x.tag not in ('rent', 'adjustments') for x in term)):
            raise ValueError
        adjustments = []
        if groups:
            for a in groups[0]:
                if a.tag != 'adjustment' or a.get('date') is None or a.get('amount') is None:
                    raise ValueError
                try:
                    d = date.fromisoformat(a.get('date'))
                except Exception as exc:
                    raise ValueError from exc
                if d < start or d > end or (adjustments and d <= adjustments[-1][0]):
                    raise ValueError
                adjustments.append((d, _money(a.get('amount'))))
        result.append({'id': ident, 'tenant': node.get('tenant'), 'start': start, 'end': end, 'base_cents': base, 'adjustments': adjustments})
    return result

def summarize_lease_rent(leases: list[dict], year: int) -> dict[str, dict[str, int]]:
    if not isinstance(year, int) or isinstance(year, bool) or (not 1 <= year <= 9999) or (not isinstance(leases, list)):
        raise ValueError
    totals = {}
    for lease in leases:
        try:
            ident, tenant, start, end = (lease['id'], lease['tenant'], lease['start'], lease['end'])
            base, adjustments = (lease['base_cents'], lease['adjustments'])
        except (KeyError, TypeError) as exc:
            raise ValueError from exc
        if not isinstance(start, date) or not isinstance(end, date) or start > end or (not isinstance(tenant, str)):
            raise ValueError
        for d, amount in adjustments:
            if not isinstance(d, date) or not isinstance(amount, int):
                raise ValueError
        total, count = (0, 0)
        for month in range(1, 13):
            first = date(year, month, 1)
            if start <= first <= end:
                amount = base + sum((v for d, v in adjustments if d <= first))
                total += amount
                count = 1
        if count:
            item = totals.setdefault(tenant, {'leases': 0, 'total_cents': 0})
            item['leases'] += 1
            item['total_cents'] += total
    return {k: totals[k] for k in sorted(totals)}

