import re
import secrets

def normalize_address(raw: str) -> str:
    if not isinstance(raw, str):
        raise ValueError('invalid address')
    fields = []
    current = []
    escaped = False
    for char in raw:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == ',':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('invalid address')
    fields.append(''.join(current))
    if len(fields) != 3:
        raise ValueError('invalid address')
    street, city, region = [re.sub('\\s+', ' ', x.strip()).upper().replace('.', '') for x in fields]
    if not street or not city:
        raise ValueError('invalid address')
    match = re.fullmatch('([A-Z]{2})\\s+(\\d{5}(?:-\\d{4})?)', region)
    if not match:
        raise ValueError('invalid address')
    return f'{street}|{city}|{match.group(1)}|{match.group(2)}'

def verify_addresses(records: list[dict]) -> list[dict]:
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    normalized = []
    counts = {}
    for record in records:
        value = record.get('address') if isinstance(record, dict) else None
        try:
            item = normalize_address(value)
        except ValueError:
            item = None
        normalized.append(item)
        if item is not None:
            counts[item] = counts.get(item, 0) + 1
    result = []
    for record, item in zip(records, normalized):
        ident = record.get('id') if isinstance(record, dict) else None
        result.append({'id': ident, 'normalized': item, 'status': 'duplicate' if item and counts[item] > 1 else 'unique' if item else 'invalid'})
    return result

def generate_invite_code(length: int=10, prefix: str='') -> str:
    alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
    if isinstance(length, bool) or not isinstance(length, int) or (not 1 <= length <= 64):
        raise ValueError('invalid length')
    if not isinstance(prefix, str) or len(prefix) > 16 or (not re.fullmatch('[A-Z0-9]*', prefix)):
        raise ValueError('invalid prefix')
    return prefix + ''.join((secrets.choice(alphabet) for _ in range(length)))

