import hashlib
import hmac
import json
import math
import os

def build_permit_manifest(applications: list[dict], page: int, page_size: int) -> dict:
    if not isinstance(applications, list):
        raise TypeError('applications must be a list')
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    key = os.environ.get('PERMIT_SIGNING_KEY')
    if key is None:
        raise RuntimeError('PERMIT_SIGNING_KEY is not configured')
    included = []
    for application in applications:
        if not isinstance(application, dict):
            raise TypeError('each application must be a dictionary')
        for field in ('id', 'city', 'status'):
            if not isinstance(application.get(field), str):
                raise TypeError(field + ' must be a string')
        fee = application.get('fee')
        if isinstance(fee, bool) or not isinstance(fee, (int, float)) or (not math.isfinite(fee)) or (fee < 0):
            raise ValueError('fee must be a finite non-negative number')
        if application['status'] not in ('approved', 'pending', 'rejected'):
            raise ValueError('unsupported status')
        if application['status'] != 'rejected':
            included.append({'id': application['id'], 'city': application['city'], 'fee': round(fee, 2)})
    included.sort(key=lambda item: (-item['fee'], item['id']))
    totals = {}
    for item in included:
        city = item['city']
        if city not in totals:
            totals[city] = [0, 0.0]
        totals[city][0] += 1
        totals[city][1] += item['fee']
    city_totals = [{'city': city, 'count': totals[city][0], 'total_fee': round(totals[city][1], 2)} for city in sorted(totals)]
    start = (page - 1) * page_size
    unsigned = {'page': page, 'page_size': page_size, 'total': len(included), 'applications': included[start:start + page_size], 'city_totals': city_totals}
    data = json.dumps(unsigned, sort_keys=True, separators=(',', ':')).encode('utf-8')
    return {**unsigned, 'signature': hmac.new(key.encode('utf-8'), data, hashlib.sha256).hexdigest()}

