import secrets
ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'

def generate_invite_code(length: int=10) -> str:
    if isinstance(length, bool) or not isinstance(length, int) or (not 8 <= length <= 32):
        raise ValueError('invalid length')
    return ''.join((secrets.choice(ALPHABET) for _ in range(length)))

def issue_invites(claim_ids: list[str], length: int=10) -> list[dict[str, str]]:
    if not isinstance(claim_ids, list) or not claim_ids:
        raise ValueError('invalid claim ids')
    if any((not isinstance(x, str) or not x for x in claim_ids)):
        raise ValueError('invalid claim ids')
    if len(set(claim_ids)) != len(claim_ids):
        raise ValueError('duplicate claim id')
    return [{'claim_id': claim_id, 'code': generate_invite_code(length)} for claim_id in claim_ids]

def summarize_claims(records: list[dict], page: int=1, page_size: int=20) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('invalid page size')
    approved = []
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        if any((key not in record for key in ('claim_id', 'category', 'status', 'payout'))):
            raise ValueError('invalid record')
        claim_id, category, status, payout = (record[k] for k in ('claim_id', 'category', 'status', 'payout'))
        if not isinstance(claim_id, str) or not claim_id or (not isinstance(category, str)) or (not category) or (not isinstance(status, str)) or (not status) or isinstance(payout, bool) or (not isinstance(payout, (int, float))) or (not math.isfinite(payout)) or (payout < 0):
            raise ValueError('invalid record')
        if status == 'approved':
            approved.append((claim_id, category, payout))
    approved.sort(key=lambda x: (-x[2], x[0]))
    by_category = {}
    for _, category, payout in approved:
        by_category[category] = by_category.get(category, 0) + payout
    by_category = {k: round(by_category[k], 2) for k in sorted(by_category)}
    start = (page - 1) * page_size
    claims = [{'claim_id': x[0], 'category': x[1], 'payout': round(x[2], 2)} for x in approved[start:start + page_size]]
    return {'total': len(approved), 'total_payout': round(sum((x[2] for x in approved)), 2), 'by_category': by_category, 'claims': claims}

