import json
import os

def build_incident_report(records: list[dict], page: int=1, page_size: int=20, severity: str | None=None) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('page must be a positive integer')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError('page_size must be a positive integer')
    if severity is not None and (not isinstance(severity, str)):
        raise ValueError('severity must be a string or None')
    filtered = []
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('each record must be a dictionary')
        for field in ('id', 'team', 'severity', 'reported_at'):
            if not isinstance(record.get(field), str) or not record[field]:
                raise ValueError('invalid record')
        hours = record.get('hours_lost')
        if isinstance(hours, bool) or not isinstance(hours, (int, float)) or hours < 0:
            raise ValueError('invalid hours_lost')
        if severity is None or record['severity'] == severity:
            filtered.append(record)
    filtered.sort(key=lambda item: (-0, item['id']))
    filtered.sort(key=lambda item: item['reported_at'], reverse=True)
    summary = {}
    for record in filtered:
        item = summary.setdefault(record['severity'], {'count': 0, 'hours_lost': 0.0})
        item['count'] += 1
        item['hours_lost'] += record['hours_lost']
    for item in summary.values():
        item['hours_lost'] = round(item['hours_lost'], 2)
    ordered_summary = {key: summary[key] for key in sorted(summary)}
    start = (page - 1) * page_size
    body = {'incidents': filtered[start:start + page_size], 'page': page, 'page_size': page_size, 'total': len(filtered), 'summary': ordered_summary}
    key = os.environ.get('INCIDENT_SIGNING_KEY')
    if not key:
        raise RuntimeError('INCIDENT_SIGNING_KEY is not configured')
    encoded = json.dumps(body, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode('utf-8')
    body['signature'] = hmac.new(key.encode('utf-8'), encoded, hashlib.sha256).hexdigest()
    return body

