from solution import grant_report
import os
import tempfile
import pytest

def make_file(contents):
    directory = tempfile.TemporaryDirectory()
    path = os.path.join(directory.name, 'grants.txt')
    with open(path, 'w', encoding='utf-8') as handle:
        handle.write(contents)
    return (directory, path)

def test_filters_status_threshold_and_formats_amounts():
    directory, path = make_file('g1,Kenya,125.5,approved\ng2,Ghana,200.00,rejected\ng3,Kenya,100,approved\ng4,Peru,99.99,approved\n')
    try:
        result = grant_report(path, 100)
        assert result == {'total': 2, 'page': 1, 'page_size': 10, 'grants': [{'grant_id': 'g1', 'country': 'Kenya', 'amount': '125.50'}, {'grant_id': 'g3', 'country': 'Kenya', 'amount': '100.00'}], 'country_totals': {'Kenya': '225.50'}}
    finally:
        directory.cleanup()

def test_pagination_boundaries():
    directory, path = make_file('g1,A,10,approved\ng2,A,20,approved\ng3,A,30,approved\ng4,A,40,approved\ng5,A,50,approved\n')
    try:
        result = grant_report(path, page=2, page_size=2)
        assert result['total'] == 5
        assert result['page'] == 2
        assert result['page_size'] == 2
        assert [item['grant_id'] for item in result['grants']] == ['g3', 'g2']
        assert grant_report(path, page=3, page_size=2)['grants'] == [{'grant_id': 'g1', 'country': 'A', 'amount': '10.00'}]
        assert grant_report(path, page=4, page_size=2)['grants'] == []
    finally:
        directory.cleanup()

def test_empty_file_and_blank_lines():
    directory, path = make_file('\n  \n')
    try:
        assert grant_report(path) == {'total': 0, 'page': 1, 'page_size': 10, 'grants': [], 'country_totals': {}}
    finally:
        directory.cleanup()

def test_invalid_arguments_raise_value_error():
    directory, path = make_file('g1,A,10,approved\n')
    try:
        for kwargs in ({'page': 0}, {'page_size': 0}, {'minimum_amount': -1}):
            with pytest.raises(ValueError):
                grant_report(path, **kwargs)
    finally:
        directory.cleanup()

def test_invalid_rows_raise_value_error():
    cases = ['g1,A,10\n', 'g1,A,nope,approved\n', 'g1,A,-2,approved\n', 'g1,A,2,pending\n']
    for contents in cases:
        directory, path = make_file(contents)
        try:
            with pytest.raises(ValueError):
                grant_report(path)
        finally:
            directory.cleanup()

