import os
import subprocess
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def grant_report(path: str, minimum_amount: float=0, page: int=1, page_size: int=10) -> dict:
    if page < 1 or page_size < 1 or minimum_amount < 0:
        raise ValueError('invalid pagination or threshold')
    if not os.path.isfile(path):
        raise FileNotFoundError(path)
    try:
        threshold = Decimal(str(minimum_amount))
    except InvalidOperation as exc:
        raise ValueError('invalid threshold') from exc
    completed = subprocess.run(['sort', path], capture_output=True, text=True, check=True)
    rows = []
    for raw in completed.stdout.splitlines():
        if not raw.strip():
            continue
        fields = raw.split(',')
        if len(fields) != 4 or not fields[0] or (not fields[1]):
            raise ValueError('invalid row')
        grant_id, country, amount_text, status = fields
        try:
            amount = Decimal(amount_text)
        except InvalidOperation as exc:
            raise ValueError('invalid amount') from exc
        if amount < 0 or status not in ('approved', 'rejected'):
            raise ValueError('invalid row')
        if status == 'approved' and amount >= threshold:
            rows.append((grant_id, country, amount))
    rows.sort(key=lambda row: (-row[2], row[0]))
    totals = {}
    for _, country, amount in rows:
        totals[country] = totals.get(country, Decimal('0')) + amount
    quantized = lambda value: str(value.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
    start = (page - 1) * page_size
    selected = rows[start:start + page_size]
    return {'total': len(rows), 'page': page, 'page_size': page_size, 'grants': [{'grant_id': i, 'country': c, 'amount': quantized(a)} for i, c, a in selected], 'country_totals': {country: quantized(totals[country]) for country in sorted(totals)}}

