from decimal import Decimal, InvalidOperation
from lxml import etree

def extract_invoice(xml_text: str) -> dict:
    if not isinstance(xml_text, str):
        raise TypeError('xml_text must be a string')
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode('utf-8'), parser)
    except etree.XMLSyntaxError as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'invoice':
        raise ValueError('root must be invoice')
    invoice_id = root.get('id')
    vendor = root.findtext('vendor')
    total_text = root.findtext('total')
    if not invoice_id or not vendor or (not vendor.strip()) or (total_text is None):
        raise ValueError('missing invoice field')
    try:
        total_decimal = Decimal(total_text.strip())
    except InvalidOperation as exc:
        raise ValueError('invalid total') from exc
    if not total_decimal.is_finite():
        raise ValueError('invalid total')
    total = float(total_decimal)
    items = root.find('items')
    line_count = len(items.findall('item')) if items is not None else 0
    return {'invoice_id': invoice_id, 'vendor': vendor.strip(), 'currency': root.get('currency', 'USD'), 'total': total, 'line_count': line_count, 'high_value': total_decimal >= Decimal('10000')}

