def assess_appeal_webhook(payload: bytes, headers: dict[str, str], secret: str) -> dict[str, object]:
    header = headers.get('X-Appeal-Signature')
    expected = hmac.new(secret.encode('utf-8'), payload, hashlib.sha256).hexdigest()
    if not isinstance(header, str) or not header.startswith('sha256=') or (not hmac.compare_digest(header[7:], expected)):
        raise PermissionError('invalid signature')
    try:
