    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    required = {'taxpayer_id', 'county', 'assessed_value', 'market_value', 'filed_date', 'grounds'}
    if not isinstance(data, dict) or set(data) != required:
        raise ValueError('invalid fields')
    if not all((isinstance(data[k], str) and data[k].strip() for k in ('taxpayer_id', 'county', 'grounds'))):
        raise ValueError('invalid text')
    if any((isinstance(data[k], bool) or not isinstance(data[k], (int, float)) or data[k] <= 0 for k in ('assessed_value', 'market_value'))):
        raise ValueError('invalid values')
    try:
        filed = datetime.date.fromisoformat(data['filed_date'])
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid date') from exc
    if filed.isoformat() != data['filed_date']:
        raise ValueError('invalid date')
    ratio = round(data['assessed_value'] / data['market_value'] * 100, 2)
    classification = 'low' if ratio <= 80 else 'moderate' if ratio <= 100 else 'high'
    return {'taxpayer_id': data['taxpayer_id'].strip(), 'county': data['county'].strip(), 'assessed_value': data['assessed_value'], 'market_value': data['market_value'], 'filed_date': data['filed_date'], 'grounds': data['grounds'].strip(), 'ratio_percent': ratio, 'classification': classification, 'deadline': (filed + datetime.timedelta(days=30)).isoformat()}

