def select_delivery_slots(deliveries: list[dict], expression: str, page: int=1, page_size: int=10) -> list[dict]:
    if type(page) is not int or type(page_size) is not int or page < 1 or (page_size < 1):
        raise ValueError('invalid page')
    try:
        tree = ast.parse(expression, mode='eval').body
    except Exception as exc:
        raise ValueError('invalid expression') from exc

    def evaluate(node, values):
        if isinstance(node, ast.Constant) and type(node.value) in (int, float, bool):
            return node.value
        if isinstance(node, ast.Name) and node.id in values:
            return values[node.id]
        if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
            a, b = (evaluate(node.left, values), evaluate(node.right, values))
            return {ast.Add: lambda: a + b, ast.Sub: lambda: a - b, ast.Mult: lambda: a * b, ast.Div: lambda: a / b}[type(node.op)]()
        if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub, ast.Not):
            value = evaluate(node.operand, values)
            return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
        if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
            result = evaluate(node.values[0], values)
            for child in node.values[1:]:
                if isinstance(node.op, ast.And) and (not result) or (isinstance(node.op, ast.Or) and result):
                    return result
                result = evaluate(child, values)
            return result
        if isinstance(node, ast.Compare) and len(node.ops) == len(node.comparators):
            left = evaluate(node.left, values)
            for op, right_node in zip(node.ops, node.comparators):
                right = evaluate(right_node, values)
                if type(op) not in (ast.Lt, ast.LtE, ast.Gt, ast.GtE, ast.Eq, ast.NotEq):
                    raise ValueError('invalid expression')
                if not {ast.Lt: left < right, ast.LtE: left <= right, ast.Gt: left > right, ast.GtE: left >= right, ast.Eq: left == right, ast.NotEq: left != right}[type(op)]:
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords) and (1 <= len(node.args) <= 2):
            return {'min': min, 'max': max, 'round': round}[node.func.id](*[evaluate(arg, values) for arg in node.args])
        raise ValueError('invalid expression')
    selected = []
    for item in deliveries:
        values = {name: item[name] for name in ('weight', 'distance', 'priority', 'fee')}
        values['True'] = True
        try:
            if evaluate(tree, values):
                selected.append(item)
