        raise ValueError('invalid date')
    try:
        date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid date')
    return value

def _money(value):
    if not re.fullmatch('\\d+(?:\\.\\d{1,2})?', value):
        raise ValueError('invalid money')
    try:
        return int(Decimal(value) * 100)
    except (InvalidOperation, ValueError):
        raise ValueError('invalid money')

def parse_refunds(xml_text: str) -> list[dict]:
    try:
        parser = etree.XMLParser(resolve_entities=True, load_dtd=True)
        root = etree.fromstring(xml_text.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'refunds':
        raise ValueError('invalid root')
    result, ids = ([], set())
    for node in root:
        if node.tag != 'refund':
            raise ValueError('invalid child')
        required = ['id', 'order', 'currency', 'status', 'created']
        if any((node.get(k) is None or node.get(k) == '' for k in required)):
            raise ValueError('missing attribute')
        rid, order, currency, status, created = [node.get(k) for k in required]
        if rid in ids or not re.fullmatch('[A-Z]{3}', currency) or status not in {'pending', 'approved', 'denied'}:
            raise ValueError('invalid refund')
        _date(created)
        reason_node = node.find('reason')
        lines_node = node.find('lines')
        reason = ''.join(reason_node.itertext()).strip() if reason_node is not None else ''
        if not reason or lines_node is None or (not list(lines_node)):
            raise ValueError('missing content')
        lines = []
        for line in lines_node:
            if line.tag != 'line' or any((line.get(k) is None for k in ['sku', 'qty', 'unit'])) or (not line.get('sku').strip()) or (not re.fullmatch('[1-9]\\d*', line.get('qty'))):
                raise ValueError('invalid line')
            unit = _money(line.get('unit'))
            qty = int(line.get('qty'))
            lines.append({'sku': line.get('sku'), 'qty': qty, 'unit_cents': unit, 'total_cents': qty * unit})
        ids.add(rid)
        result.append({'id': rid, 'order': order, 'currency': currency, 'status': status, 'created': created, 'reason': reason, 'lines': lines})
    return sorted(result, key=lambda x: (x['created'], x['id']))

def summarize_refunds(xml_text: str, as_of: str) -> dict:
    _date(as_of)
    refunds = [r for r in parse_refunds(xml_text) if r['created'] <= as_of]
    approved = [r for r in refunds if r['status'] == 'approved']
    totals = {}
    for refund in approved:
        totals[refund['currency']] = totals.get(refund['currency'], 0) + sum((x['total_cents'] for x in refund['lines']))
    totals = {k: totals[k] for k in sorted(totals)}
    largest = min(approved, key=lambda r: (-sum((x['total_cents'] for x in r['lines'])), r['id']))['id'] if approved else None
    return {'count': len(refunds), 'approved_count': sum((r['status'] == 'approved' for r in refunds)), 'pending_count': sum((r['status'] == 'pending' for r in refunds)), 'denied_count': sum((r['status'] == 'denied' for r in refunds)), 'totals_by_currency': totals, 'largest_approved_id': largest, 'approved_ids': [r['id'] for r in approved]}

