                children['tags'] = True
                for tag in child:
                    if tag.tag != 'tag' or not (tag.text or '').strip():
                        raise ValueError('invalid tag')
                    tags.append(tag.text.strip())
            elif child.tag in ('headline', 'reporter'):
                if child.tag in children or not (child.text or '').strip():
