                children[child.tag] = child.text.strip()
            else:
                raise ValueError('unknown child')
        if 'headline' not in children or 'reporter' not in children:
            raise ValueError('missing field')
        seen.add(vals['id'])
        result.append({'id': vals['id'], 'desk': vals['desk'], 'priority': priority, 'minutes': minutes, 'slot': vals['slot'], 'headline': children['headline'], 'reporter': children['reporter'], 'tags': tags})
    return result

