import hashlib
import hmac
import json
import pytest


def signed(data, secret="arena-key"):
    raw = json.dumps(data, separators=(",", ":")).encode()
    sig = hmac.new(secret.encode(), raw, hashlib.sha256).hexdigest()
    return raw, sig


def test_empty_orders_and_pagination_metadata():
    raw, sig = signed({"orders": []})
    assert verify_and_summarize(raw, sig, "arena-key") == {
        "page": 1,
        "page_size": 2,
        "total_venues": 0,
        "venues": [],
    }


def test_groups_paid_items_and_counts_distinct_orders():
    data = {
        "orders": [
            {"status": "paid", "items": [
                {"venue": "East Stand", "name": "Pretzel", "quantity": 2, "unit_price_cents": 350},
                {"venue": "East Stand", "name": "Water", "quantity": 1, "unit_price_cents": 200},
            ]},
            {"status": "paid", "items": [
                {"venue": "East Stand", "name": "Nachos", "quantity": 1, "unit_price_cents": 700},
                {"venue": "North Gate", "name": "Tea", "quantity": 2, "unit_price_cents": 250},
            ]},
            {"status": "pending", "items": [
                {"venue": "North Gate", "name": "Tea", "quantity": 9, "unit_price_cents": 999}
            ]},
        ]
    }
    raw, sig = signed(data)
    assert verify_and_summarize(raw, sig, "arena-key") == {
        "page": 1,
        "page_size": 2,
        "total_venues": 2,
        "venues": [
            {"venue": "East Stand", "revenue_cents": 1600, "order_count": 2},
            {"venue": "North Gate", "revenue_cents": 500, "order_count": 1},
        ],
    }


def test_ties_are_sorted_by_venue_and_pagination_is_one_based():
    data = {"orders": [
        {"status": "paid", "items": [{"venue": "Zeta", "name": "x", "quantity": 1, "unit_price_cents": 100}]},
        {"status": "paid", "items": [{"venue": "Alpha", "name": "x", "quantity": 1, "unit_price_cents": 100}]},
        {"status": "paid", "items": [{"venue": "Beta", "name": "x", "quantity": 1, "unit_price_cents": 100}]},
    ]}
    raw, sig = signed(data)
    assert verify_and_summarize(raw, sig, "arena-key", 2, 1)["venues"] == [{"venue": "Beta", "revenue_cents": 100, "order_count": 1}]


def test_invalid_signature_is_rejected():
    raw, sig = signed({"orders": []})
    with pytest.raises(ValueError):
        verify_and_summarize(raw, "0" * 64, "arena-key")


def test_wrong_secret_and_malformed_signature_are_rejected():
    raw, sig = signed({"orders": []})
    with pytest.raises(ValueError):
        verify_and_summarize(raw, sig, "different")
    with pytest.raises(ValueError):
        verify_and_summarize(raw, sig[:-1] + "G", "arena-key")


