def parse_assessments(xml_text: str, page: int=1, page_size: int=10, minimum_score: float=0.0) -> dict:
    if not isinstance(xml_text, str) or not isinstance(page, int) or isinstance(page, bool) or (not isinstance(page_size, int)) or isinstance(page_size, bool):
        raise ValueError('invalid arguments')
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    try:
        minimum_score = float(minimum_score)
    except (TypeError, ValueError):
        raise ValueError('invalid minimum score')
    if not math.isfinite(minimum_score) or minimum_score < 0:
        raise ValueError('invalid minimum score')
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml_text.encode('utf-8'), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'assessments':
        raise ValueError('invalid root')
    records = []
    for node in root:
        if node.tag != 'assessment':
            raise ValueError('invalid child')
        values = [node.get(name) for name in ('site', 'category', 'score', 'area', 'status')]
        if any((value is None or value == '' for value in values)):
            raise ValueError('missing attribute')
        site, category, raw_score, area, status = values
        if status not in ('complete', 'draft'):
            raise ValueError('invalid status')
        try:
            score = float(raw_score)
        except ValueError as exc:
            raise ValueError('invalid score') from exc
        if not math.isfinite(score) or not 0 <= score <= 100:
            raise ValueError('invalid score')
        if status == 'complete' and score >= minimum_score:
            records.append({'site': site, 'category': category, 'score': score, 'area': area})
    records.sort(key=lambda item: (-item['score'], item['site'], item['category']))
    totals = {}
    for item in records:
        totals[item['category']] = totals.get(item['category'], 0.0) + item['score']
    start = (page - 1) * page_size
    return {'total': len(records), 'page': page, 'page_size': page_size, 'items': records[start:start + page_size], 'average_score': round(sum((item['score'] for item in records)) / len(records), 2) if records else 0.0, 'category_totals': {key: round(totals[key], 2) for key in sorted(totals)}}

