import secrets

def generate_schedule_invite_code(program_id: str, length: int=12) -> str:
    if not isinstance(program_id, str):
        raise ValueError('program_id must be a string')
    if isinstance(length, bool) or not isinstance(length, int) or (not 8 <= length <= 32):
        raise ValueError('length must be between 8 and 32')
    characters = [character for character in program_id.strip().upper() if character.isascii() and character.isalnum()]
    if not characters:
        raise ValueError('program_id must contain a letter or digit')
    prefix = ''.join(characters[:3]).ljust(3, 'X')
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    return prefix + ''.join((secrets.choice(alphabet) for _ in range(length - 3)))

