import hashlib
import hmac
import math
import os

def register_operator(registry: dict, operator_id: str, password: str, clearance: int) -> None:
    if not isinstance(operator_id, str) or not operator_id.strip():
        raise ValueError('invalid operator')
    if not isinstance(password, str) or len(password) < 4:
        raise ValueError('invalid password')
    if not isinstance(clearance, int) or isinstance(clearance, bool) or (not 1 <= clearance <= 5):
        raise ValueError('invalid clearance')
    key = operator_id.strip()
    if key in registry:
        raise KeyError(key)
    salt = os.urandom(16)
    registry[key] = {'clearance': clearance, 'salt': salt, 'digest': hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)}

def authenticate_operator(registry: dict, operator_id: str, password: str) -> bool:
    if not isinstance(operator_id, str) or not isinstance(password, str):
        return False
    entry = registry.get(operator_id.strip())
    if entry is None:
        return False
    return hmac.compare_digest(hashlib.pbkdf2_hmac('sha256', password.encode(), entry['salt'], 100000), entry['digest'])

def pressure_report(records: list[dict], window: int) -> list[dict]:
    if not isinstance(window, int) or isinstance(window, bool) or window <= 0:
        raise ValueError('invalid window')
    groups = {}
    for pos, record in enumerate(records):
        if not isinstance(record, dict) or set(record) != {'timestamp', 'segment', 'pressure', 'status'}:
            raise ValueError('invalid record')
        t, segment, pressure, status = (record['timestamp'], record['segment'], record['pressure'], record['status'])
        if not isinstance(t, int) or isinstance(t, bool) or t < 0:
            raise ValueError('invalid timestamp')
        if not isinstance(segment, str) or not segment:
            raise ValueError('invalid segment')
        if isinstance(pressure, bool) or not isinstance(pressure, (int, float)) or (not math.isfinite(pressure)) or (pressure < 0):
            raise ValueError('invalid pressure')
        if status not in ('OK', 'ALERT'):
            raise ValueError('invalid status')
        groups.setdefault(segment, []).append((t, pos, float(pressure), status))
    output = []
    for segment, items in groups.items():
        items.sort(key=lambda x: (x[0], x[1]))
        for i, (t, pos, _, _) in enumerate(items):
            part = items[max(0, i - window + 1):i + 1]
            values = [x[2] for x in part]
            output.append((t, segment, pos, {'segment': segment, 'timestamp': t, 'average': round(sum(values) / len(values), 2), 'minimum': round(min(values), 2), 'maximum': round(max(values), 2), 'alert_count': sum((x[3] == 'ALERT' for x in part))}))
    output.sort(key=lambda x: (x[0], x[1], x[2]))
    return [x[3] for x in output]

