from datetime import datetime

def summarize_access_log(base_dir: str, relative_name: str, day: str | None=None, page: int=1, page_size: int=10) -> list[dict[str, object]]:
    if not isinstance(page, int) or isinstance(page, bool) or page <= 0:
        raise ValueError('page must be positive')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size <= 0:
        raise ValueError('page_size must be positive')
    selected_day = None
    if day is not None:
        try:
            selected_day = datetime.strptime(day, '%Y-%m-%d').date()
        except (TypeError, ValueError) as exc:
            raise ValueError('invalid day') from exc
    base = os.path.realpath(base_dir)
    path = os.path.realpath(os.path.join(base, relative_name))
    if path != base and (not path.startswith(base + os.sep)):
        raise ValueError('file is outside base directory')
    totals = {}
    with open(path, newline='', encoding='utf-8') as handle:
        reader = csv.DictReader(handle)
        required = {'employee', 'timestamp', 'duration_minutes', 'status'}
        if reader.fieldnames is None or not required.issubset(reader.fieldnames):
            raise ValueError('missing columns')
        for row in reader:
            try:
                stamp = datetime.fromisoformat(row['timestamp'])
                duration = float(row['duration_minutes'])
                status = row['status']
                employee = row['employee']
            except (TypeError, ValueError, KeyError) as exc:
                raise ValueError('malformed row') from exc
            if status not in {'granted', 'denied'} or duration < 0:
                raise ValueError('invalid row')
            if status != 'granted' or (selected_day is not None and stamp.date() != selected_day):
                continue
            count, total = totals.get(employee, (0, 0.0))
            totals[employee] = (count + 1, total + duration)
    result = [{'employee': employee, 'granted_count': count, 'total_hours': round(total / 60, 2)} for employee, (count, total) in totals.items()]
    result.sort(key=lambda item: (-item['total_hours'], item['employee']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

