import hashlib
import hmac
import json
import math
import os
from datetime import date, timedelta
from collections.abc import Mapping

def generate_shift_report(shifts: list[dict], week_start: str, config: dict[str, str] | None=None) -> dict:
    try:
        start = date.fromisoformat(week_start)
    except (TypeError, ValueError):
        raise ValueError('week_start must be an ISO date')
    end = start + timedelta(days=7)
    totals = {}
    count = 0
    for shift in shifts:
        if not isinstance(shift, Mapping):
            raise ValueError('each shift must be a mapping')
        if not all((key in shift for key in ('worker', 'date', 'hours'))):
            raise ValueError('shift is missing a required field')
        worker = shift['worker']
        if not isinstance(worker, str) or not worker:
            raise ValueError('worker must be a non-empty string')
        try:
            shift_date = date.fromisoformat(shift['date'])
        except (TypeError, ValueError):
            raise ValueError('shift date must be an ISO date')
        hours = shift['hours']
        if isinstance(hours, bool) or not isinstance(hours, (int, float)) or (not math.isfinite(hours)) or (hours < 0):
            raise ValueError('hours must be a finite non-negative number')
        if start <= shift_date < end:
            totals[worker] = totals.get(worker, 0) + hours
            count += 1
    workers = [{'worker': worker, 'hours': round(hours, 2)} for worker, hours in totals.items()]
    workers.sort(key=lambda item: (-item['hours'], item['worker']))
    payload = {'week_start': week_start, 'week_end': (end - timedelta(days=1)).isoformat(), 'total_shifts': count, 'workers': workers}
    key = config.get('report_key') if config is not None and 'report_key' in config else os.environ.get('WORKFORCE_REPORT_KEY')
    if not isinstance(key, str) or not key:
        raise ValueError('report key is missing')
    body = json.dumps(payload, sort_keys=True, separators=(',', ':')).encode()
    payload['signature'] = hmac.new(key.encode(), body, hashlib.sha256).hexdigest()
    return payload

