from solution import verify_turbine_webhook
import hashlib
import hmac
import json
import pytest


def make_message(data, secret=b"field-key"):
    payload = json.dumps(data, separators=(",", ":")).encode("utf-8")
    digest = hmac.new(secret, payload, hashlib.sha256).hexdigest()
    return payload, {"X-Turbine-Signature": "sha256=" + digest}


def test_valid_webhook_returns_original_object():
    data = {"turbine_id": "WT-17", "timestamp": 1712345678, "readings": [{"rpm": 14.2, "vibration": 0.03}]}
    payload, headers = make_message(data)
    assert verify_turbine_webhook(payload, headers, b"field-key") == data


def test_valid_empty_readings_are_allowed():
    data = {"turbine_id": "N-02", "timestamp": 0, "readings": []}
    payload, headers = make_message(data)
    assert verify_turbine_webhook(payload, headers, b"field-key") == data


def test_missing_signature_returns_none():
    data = {"turbine_id": "WT-1", "timestamp": 10, "readings": []}
    payload, _ = make_message(data)
    assert verify_turbine_webhook(payload, {}, b"field-key") is None


def test_wrong_signature_returns_none():
    data = {"turbine_id": "WT-1", "timestamp": 10, "readings": []}
    payload, headers = make_message(data)
    headers["X-Turbine-Signature"] = "sha256=" + "0" * 64
    assert verify_turbine_webhook(payload, headers, b"field-key") is None


def test_signature_header_format_is_strict():
    data = {"turbine_id": "WT-1", "timestamp": 10, "readings": []}
    payload, headers = make_message(data)
    digest = headers["X-Turbine-Signature"][7:]
    for value in (digest, "SHA256=" + digest, "sha256:" + digest, "sha256=" + digest.upper(), "sha256=" + digest + "extra"):
        assert verify_turbine_webhook(payload, {"X-Turbine-Signature": value}, b"field-key") is None


def test_invalid_json_raises_value_error_after_matching_header():
    payload = b"not-json"
    digest = hmac.new(b"field-key", payload, hashlib.sha256).hexdigest()
    with pytest.raises(ValueError):
        verify_turbine_webhook(payload, {"X-Turbine-Signature": "sha256=" + digest}, b"field-key")


def test_required_fields_are_validated():
    cases = [
        {"timestamp": 1, "readings": []},
        {"turbine_id": "WT-1", "readings": []},
        {"turbine_id": "WT-1", "timestamp": 1},
        {"turbine_id": "", "timestamp": 1, "readings": []},
        {"turbine_id": "WT-1", "timestamp": True, "readings": []},
        {"turbine_id": "WT-1", "timestamp": 1, "readings": {}},
    ]
    for data in cases:
        payload, headers = make_message(data)
        with pytest.raises(ValueError):
            verify_turbine_webhook(payload, headers, b"field-key")


