import hmac
import json

def verify_turbine_webhook(payload: bytes, headers: dict[str, str], secret: bytes) -> dict | None:
    value = headers.get('X-Turbine-Signature')
    if value is None or not value.startswith('sha256='):
        return None
    supplied = value[7:]
    if len(supplied) != 64:
        return None
    try:
        int(supplied, 16)
    except ValueError:
        return None
    expected = hmac.new(secret, payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(supplied, expected):
        return None
    try:
        result = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(result, dict) or not isinstance(result.get('turbine_id'), str) or (not result['turbine_id']) or (not isinstance(result.get('timestamp'), int)) or isinstance(result['timestamp'], bool) or (not isinstance(result.get('readings'), list)):
        raise ValueError('invalid telemetry')
    return result

