    conn.execute('create index if not exists idx_bookings_route on bookings(origin, destination)')
    conn.commit()

def add_booking(conn: sqlite3.Connection, booking_ref: str, flight_no: str, origin: str, destination: str, weight_kg: float, status: str='BOOKED') -> int:
    if any((not isinstance(x, str) or not x.strip() for x in (booking_ref, flight_no, origin, destination))) or weight_kg <= 0 or status not in _STATUSES:
        raise ValueError('invalid booking')
    cur = conn.execute('insert into bookings(booking_ref,flight_no,origin,destination,weight_kg,status,created_at) values(?,?,?,?,?,?,?)', (booking_ref, flight_no, origin, destination, weight_kg, status, datetime.now(timezone.utc).isoformat()))
    conn.commit()
    return cur.lastrowid

