        raise ValueError('invalid sort')
    clauses, values = ([], [])
    for name, value in (('origin', origin), ('destination', destination), ('status', status)):
        if value is not None:
            clauses.append(name + ' = ?')
            values.append(value)
    where = ' where ' + ' and '.join(clauses) if clauses else ''
    direction = ' desc' if descending else ' asc'
    rows = conn.execute('select id,booking_ref,flight_no,origin,destination,weight_kg,status,created_at from bookings' + where + ' order by ' + _SORTS[sort_by] + direction + ', booking_ref asc', values).fetchall()
    return [{key: row[key] for key in _KEYS} for row in rows]

def update_booking_status(conn: sqlite3.Connection, booking_id: int, status: str) -> bool:
    if status not in _STATUSES:
        raise ValueError('invalid status')
    cur = conn.execute('update bookings set status=? where id=?', (status, booking_id))
