def export_connection_report(records: list[dict[str, Any]], destination: str) -> int:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    grouped: dict[str, list[float | int]] = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        if set(record) != {'service', 'status', 'latency_ms', 'bytes_sent'}:
            raise ValueError('invalid record')
        service = record['service']
        status = record['status']
        latency = record['latency_ms']
        sent = record['bytes_sent']
        if not isinstance(service, str) or not service:
            raise ValueError('invalid service')
        if status not in ('success', 'failed'):
            raise ValueError('invalid status')
        if isinstance(latency, bool) or not isinstance(latency, (int, float)) or latency < 0:
            raise ValueError('invalid latency')
        if isinstance(sent, bool) or not isinstance(sent, int) or sent < 0:
            raise ValueError('invalid bytes')
        if status == 'success':
            if service not in grouped:
                grouped[service] = [0, 0, 0.0]
            grouped[service][0] += 1
            grouped[service][1] += sent
            grouped[service][2] += latency
    rows = []
    for service, values in grouped.items():
        rows.append((service, int(values[0]), int(values[1]), values[2] / values[0]))
    rows.sort(key=lambda row: (-row[2], row[0]))
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent)
    os.close(fd)
    try:
        with open(temporary, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle)
            writer.writerow(['service', 'successful_connections', 'total_bytes', 'average_latency_ms'])
            for service, count, total, average in rows:
                writer.writerow([service, count, total, f'{average:.2f}'])
        os.replace(temporary, destination)
    except Exception:
        if os.path.exists(temporary):
            os.unlink(temporary)
        raise
    return len(rows)

