import datetime, json, hashlib, hmac

def _date(x):
    try:
        return datetime.date.fromisoformat(x)
    except Exception as e:
        raise ValueError('invalid date') from e

def parse_reservations(text: str) -> list[dict]:
    try:
        rows = json.loads(text)
    except Exception as e:
        raise ValueError('invalid JSON') from e
    if not isinstance(rows, list):
        raise ValueError('reservations must be a list')
    out = []
    ids = set()
    for r in rows:
        if not isinstance(r, dict):
            raise ValueError('invalid reservation')
        try:
            i = r['id'].strip()
            a = r['area'].strip()
            d = r['checkout']
            u = r['units']
        except Exception as e:
            raise ValueError('invalid reservation') from e
        if not isinstance(i, str) or not i or (not isinstance(a, str)) or (not a) or (not isinstance(d, str)) or (_date(d).isoformat() != d) or isinstance(u, bool) or (not isinstance(u, int)) or (u <= 0) or (i in ids):
            raise ValueError('invalid reservation')
        ids.add(i)
        out.append({'id': i, 'checkout': d, 'area': a, 'units': u})
    return sorted(out, key=lambda x: (x['checkout'], x['id']))

def assign_cleanings(reservations: list[dict], cleaners: list[dict], service_date: str) -> list[dict]:
    _date(service_date)
    names = set()
    state = []
    for x in cleaners:
        try:
            n, cap, areas = (x['name'], x['capacity'], x['areas'])
        except Exception as e:
            raise ValueError('invalid cleaner') from e
        if not isinstance(n, str) or not n or n in names or isinstance(cap, bool) or (not isinstance(cap, int)) or (cap <= 0) or (not isinstance(areas, list)) or (not areas) or (not all((isinstance(a, str) and a for a in areas))):
            raise ValueError('invalid cleaner')
        names.add(n)
        state.append({'name': n, 'capacity': cap, 'areas': set(areas), 'load': 0})
    selected = [r for r in reservations if r.get('checkout') == service_date]
    selected.sort(key=lambda r: (-r['units'], r['area'], r['id']))
    out = []
    for r in selected:
        q = [c for c in state if r['area'] in c['areas'] and c['load'] + r['units'] <= c['capacity']]
        if not q:
            raise ValueError('reservation cannot be assigned')
        c = min(q, key=lambda x: (x['load'], x['name']))
        c['load'] += r['units']
        out.append({'reservation_id': r['id'], 'cleaner': c['name'], 'area': r['area'], 'units': r['units']})
    return out

def build_dispatch(assignments: list[dict], config: dict) -> dict:
    k = config.get('dispatch_signing_key') if isinstance(config, dict) else None
    if not isinstance(k, str) or not k:
        raise ValueError('missing dispatch signing key')
    for a in assignments:
        if not isinstance(a, dict) or set(a) != {'reservation_id', 'cleaner', 'area', 'units'} or any((not isinstance(a[x], str) or not a[x] for x in ('reservation_id', 'cleaner', 'area'))) or isinstance(a['units'], bool) or (not isinstance(a['units'], int)) or (a['units'] <= 0):
            raise ValueError('invalid assignment')
    p = json.dumps(assignments, ensure_ascii=False, separators=(',', ':'), sort_keys=True)
    return {'assignment_count': len(assignments), 'payload': p, 'signature': hmac.new(k.encode(), p.encode(), hashlib.sha256).hexdigest()}

