        vals = {k: node.get(k, '').strip() for k in required}
        if any((not vals[k] for k in required)) or vals['status'] not in {'pass', 'fail', 'review'}:
            raise ValueError('invalid inspection')
        try:
            date.fromisoformat(vals['date'])
        except ValueError as exc:
            raise ValueError('invalid date') from exc
        containers = [x for x in node if x.tag == 'measurements']
        if len(containers) != 1 or len(list(node)) != 1:
            raise ValueError('invalid measurements')
        measurements = []
        names = set()
        for m in containers[0]:
            if m.tag != 'measurement':
                raise ValueError('unexpected element')
            name, unit, raw = (m.get(k, '').strip() for k in ('name', 'unit', 'value'))
            if not name or not unit or name in names:
                raise ValueError('invalid measurement')
            try:
                value = float(raw)
            except ValueError as exc:
                raise ValueError('invalid value') from exc
            if not math.isfinite(value):
                raise ValueError('invalid value')
            names.add(name)
            measurements.append({'name': name, 'unit': unit, 'value': value})
        result['inspections'].append({**vals, 'measurements': measurements})
    return result

def summarize_inspections(xml_documents: list[str]) -> list[dict]:
    if not isinstance(xml_documents, list):
        raise TypeError('documents must be a list')
    if not xml_documents:
        raise ValueError('no documents')
    all_items = []
    ids = set()
    for text in xml_documents:
        if not isinstance(text, str):
            raise TypeError('document must be a string')
        for item in parse_inspection_report(text)['inspections']:
            if item['id'] in ids:
                raise ValueError('duplicate id')
            ids.add(item['id'])
            all_items.append(item)
    grouped = {}
    for item in all_items:
        g = grouped.setdefault(item['inspector'], {'items': [], 'measurements': {}})
        g['items'].append(item)
        for m in item['measurements']:
            old = g['measurements'].setdefault(m['name'], {'unit': m['unit'], 'values': []})
            if old['unit'] != m['unit']:
                raise ValueError('unit conflict')
            old['values'].append(m['value'])
    out = []
    for inspector, g in grouped.items():
        items = g['items']
        counts = {s: sum((x['status'] == s for x in items)) for s in ('pass', 'fail', 'review')}
        avgs = {n: {'unit': v['unit'], 'average': round(sum(v['values']) / len(v['values']), 4)} for n, v in sorted(g['measurements'].items())}
        out.append({'inspector': inspector, 'total': len(items), 'passed': counts['pass'], 'failed': counts['fail'], 'review': counts['review'], 'pass_rate': round(counts['pass'] / len(items), 4), 'average_measurements': avgs})
    return sorted(out, key=lambda x: (-x['pass_rate'], -x['total'], x['inspector']))

