import secrets
from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
_CENT = Decimal('0.01')

def generate_access_code(length: int=12) -> str:
    if isinstance(length, bool) or not isinstance(length, int) or (not 8 <= length <= 32):
        raise ValueError('invalid length')
    return ''.join((secrets.choice(_ALPHABET) for _ in range(length)))

def build_statement(transactions: list[dict], page: int=1, page_size: int=20) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    parsed = []
    monthly = {}
    balance = Decimal('0')
    for item in transactions:
        try:
            raw_date = item['date']
            description = item['description']
            raw_amount = item['amount']
            if not isinstance(raw_date, str) or not isinstance(description, str):
                raise ValueError
            parsed_date = date.fromisoformat(raw_date)
            if parsed_date.isoformat() != raw_date:
                raise ValueError
            amount = Decimal(str(raw_amount))
            if not amount.is_finite():
                raise ValueError
        except (KeyError, TypeError, ValueError, InvalidOperation):
            raise ValueError('invalid transaction')
        parsed.append((parsed_date, raw_date, description, amount))
        balance += amount
        month = raw_date[:7]
        monthly[month] = monthly.get(month, Decimal('0')) + amount
    parsed.sort(key=lambda x: x[0], reverse=True)
    start = (page - 1) * page_size
    selected = parsed[start:start + page_size]
    money = lambda value: str(value.quantize(_CENT, rounding=ROUND_HALF_UP))
    return {'transactions': [{'date': d, 'description': text, 'amount': money(amount)} for _, d, text, amount in selected], 'total': len(parsed), 'page': page, 'page_size': page_size, 'balance': money(balance), 'monthly_totals': {key: money(monthly[key]) for key in sorted(monthly)}}

