            raise ValueError('duplicate id')
        seen.add(row[0])
        if row[6].lower() not in ('true', 'false'):
            raise ValueError('bad boolean')
        try:
            hours = json.loads(row[7])
        except Exception as e:
            raise ValueError('bad hours') from e
        if not isinstance(hours, dict):
            raise ValueError('bad hours')
        for day, value in hours.items():
            if day not in _DAYS or not isinstance(value, list) or len(value) != 2 or any((not isinstance(x, str) or not _TIME.fullmatch(x) for x in value)) or (value[0] >= value[1]):
                raise ValueError('bad hours')
        result.append({'id': row[0], 'name': row[1], 'tenant': row[2], 'owner_id': row[3], 'state': row[4], 'specialties': [x.strip() for x in row[5].split(';') if x.strip()], 'accepting': row[6].lower() == 'true', 'hours': hours})
    return result

def _allowed(requester, record):
    return 'directory_admin' in requester.get('roles', []) or (requester.get('tenant') == record.get('tenant') and requester.get('id') == record.get('owner_id'))

def search_directory(requester: dict, records: list[dict], query: str='', states: tuple[str, ...]=(), limit: int=50) -> list[dict]:
    if limit < 0:
        raise ValueError('negative limit')
    q = query.casefold()
    out = [r for r in records if _allowed(requester, r) and r.get('accepting') and (not states or r.get('state') in states) and (not q or q in r.get('name', '').casefold() or any((q in s.casefold() for s in r.get('specialties', []))))]
    out.sort(key=lambda r: (r.get('name', '').casefold(), r.get('id', '')))
    return copy.deepcopy(out[:limit])

