        values = {}
        for child in contact:
            if child.tag not in values:
                values[child.tag] = (child.text or '').strip()
        email = values.get('email', '').lower()
        name = values.get('name', '')
        if not email or not name or 'updated' not in values:
            raise ValueError('invalid contact')
        try:
            updated = int(values['updated'])
        except Exception as exc:
            raise ValueError('invalid updated value') from exc
        if updated < 0 or str(updated) != values['updated']:
            raise ValueError('invalid updated value')
        item = {'email': email, 'name': name, 'company': values.get('company', ''), 'updated': updated}
        if email not in selected or updated > selected[email]['updated']:
            selected[email] = item
    result = [selected[email] for email in sorted(selected)]
