import csv
import io
import subprocess
from decimal import Decimal, InvalidOperation
HEADER = ['interval', 'participant', 'product', 'side', 'quantity', 'price', 'trade_id']
OUT_HEADER = ['interval', 'participant', 'product', 'net_quantity', 'net_cash', 'trade_count']

def dec_text(value):
    try:
        d = Decimal(value)
    except (InvalidOperation, ValueError):
        raise ValueError('invalid decimal')
    if not d.is_finite():
        raise ValueError('invalid decimal')
    if d == d.to_integral():
        return format(d, '.1f')
    return format(d, 'f').rstrip('0').rstrip('.')

def settle_file(path: str, fee_rate: str='0') -> list[dict[str, str]]:
    try:
        fee = Decimal(fee_rate)
    except (InvalidOperation, ValueError):
        raise ValueError('invalid fee')
    if not fee.is_finite() or fee < 0:
        raise ValueError('invalid fee')
    try:
        with open(path, 'r', encoding='utf-8', newline='') as f:
            first = f.readline().rstrip('\r\n')
    except OSError:
        raise ValueError('unreadable file')
    if first != ','.join(HEADER):
        raise ValueError('bad header')
    try:
        result = subprocess.run(['sort', '-t,', '-k1,1', '-k2,2', '-k3,3', '-k7,7', path], capture_output=True, text=True, check=False)
    except OSError:
        raise ValueError('sorting failed')
    if result.returncode:
        raise ValueError('sorting failed')
    groups = {}
    reader = csv.reader(io.StringIO(result.stdout))
    for row in reader:
        if row == HEADER:
            continue
        if len(row) != 7 or any((x == '' for x in row[:3] + row[3:4] + row[6:])):
            raise ValueError('bad row')
        interval, participant, product, side, qs, ps, trade_id = row
        if side not in ('BUY', 'SELL'):
            raise ValueError('bad side')
        try:
            quantity = Decimal(qs)
            price = Decimal(ps)
        except (InvalidOperation, ValueError):
            raise ValueError('bad number')
        if not quantity.is_finite() or not price.is_finite() or quantity <= 0 or (price < 0):
            raise ValueError('bad number')
        key = (interval, participant, product)
        if key not in groups:
            groups[key] = [Decimal('0'), Decimal('0'), 0]
        sign = Decimal('1') if side == 'SELL' else Decimal('-1')
        groups[key][0] += sign * quantity
        groups[key][1] += sign * quantity * price
        groups[key][2] += 1
    output = []
    for (interval, participant, product), (qty, cash, count) in sorted(groups.items()):
        net = cash - abs(cash) * fee
        output.append({'interval': interval, 'participant': participant, 'product': product, 'net_quantity': dec_text(qty), 'net_cash': dec_text(net), 'trade_count': str(count)})
    return output

def format_settlement(rows: list[dict[str, str]]) -> str:
    out = io.StringIO()
    writer = csv.writer(out, lineterminator='\n')
    writer.writerow(OUT_HEADER)
    for row in rows:
        if list(row.keys()) != OUT_HEADER or any((not isinstance(row[k], str) for k in OUT_HEADER)):
            raise ValueError('bad settlement row')
        writer.writerow([row[k] for k in OUT_HEADER])
    return out.getvalue()

