from datetime import datetime

def parse_metadata(text: str) -> dict:
    out = {}
    required = {'patient_id', 'study_uid', 'series_uid', 'tenant_id', 'owner_id', 'acquired', 'modality', 'slices'}
    for line in text.splitlines():
        if not line:
            continue
        parts = []
        buf = []
        escaped = False
        for ch in line:
            if escaped:
                buf.append(ch)
                escaped = False
            elif ch == '\\':
                escaped = True
            elif ch == '=':
                parts.append(''.join(buf))
                buf = []
            else:
                buf.append(ch)
        if escaped:
            raise ValueError('trailing escape')
        parts.append(''.join(buf))
        if len(parts) != 2 or not parts[0] or parts[0] in out:
            raise ValueError('invalid metadata')
        out[parts[0]] = parts[1]
    if not required <= set(out):
        raise ValueError('missing metadata')
    try:
        out['acquired'] = datetime.fromisoformat(out['acquired'])
        values = out['slices'].split(',')
        if any((x == '' for x in values)):
            raise ValueError
        out['slices'] = [int(x) for x in values]
        if any((x < 0 for x in out['slices'])):
            raise ValueError
    except (TypeError, ValueError):
        raise ValueError('invalid typed metadata')
    return out

class MetadataCatalog:

    def __init__(self):
        self.records = {}

    def _allowed(self, requester, record):
        return requester.get('tenant_id') == record['tenant_id'] and (requester.get('id') == record['owner_id'] or bool(set(requester.get('roles', [])) & {'radiologist', 'admin'}))

    def add_series(self, requester: dict, text: str) -> dict:
        record = parse_metadata(text)
        if record['series_uid'] in self.records:
            raise ValueError('duplicate series')
        if requester.get('tenant_id') != record['tenant_id']:
            raise PermissionError('not permitted')
        self.records[record['series_uid']] = dict(record, slices=list(record['slices']))
        return dict(record, slices=list(record['slices']))

    def study_timeline(self, requester: dict, study_uid: str) -> list[dict]:
        rows = [r for r in self.records.values() if r['study_uid'] == study_uid]
        if rows and any((not self._allowed(requester, r) for r in rows)):
            raise PermissionError('not permitted')
        rows.sort(key=lambda r: (r['acquired'], r['series_uid']))
        result = []
        previous = None
        for row in rows:
            item = dict(row, slices=list(row['slices']))
            item['slice_count'] = len(row['slices'])
            item['duration_seconds'] = 0.0 if previous is None else (row['acquired'] - previous).total_seconds()
            result.append(item)
            previous = row['acquired']
        return result

    def revise_series(self, requester: dict, series_uid: str, updates: dict) -> dict:
        if series_uid not in self.records:
            raise ValueError('unknown series')
        record = self.records[series_uid]
        if not self._allowed(requester, record):
            raise PermissionError('not permitted')
        forbidden = {'patient_id', 'study_uid', 'series_uid', 'tenant_id', 'owner_id', 'acquired'}
        if any((k in forbidden or k not in record for k in updates)):
            raise ValueError('invalid update')
        if 'modality' in updates and (not isinstance(updates['modality'], str)):
            raise ValueError('invalid update')
        if 'slices' in updates and (not isinstance(updates['slices'], (list, tuple)) or any((not isinstance(x, int) or x < 0 for x in updates['slices']))):
            raise ValueError('invalid update')
        for key, value in updates.items():
            record[key] = list(value) if key == 'slices' else value
        return dict(record, slices=list(record['slices']))

