import csv
import datetime
import math
import os
import tempfile
from decimal import Decimal, InvalidOperation, ROUND_HALF_EVEN

def export_title_search(records: list[dict], output_path: str, county: str | None=None, page: int=1, page_size: int=50) -> int:
    if page < 1 or page_size < 1 or page_size > 1000:
        raise ValueError('invalid pagination')
    groups = {}
    for record in records:
        try:
            parcel = record['parcel_id']
            owner = record['owner']
            record_county = record['county']
            record['lien_type']
            raw_amount = record['amount']
            raw_date = record['recorded_date']
        except (KeyError, TypeError):
            raise ValueError('invalid record')
        if any((not isinstance(x, str) or not x for x in (parcel, owner, record_county, record['lien_type']))):
            raise ValueError('invalid record')
        try:
            amount = Decimal(str(raw_amount))
            date = datetime.date.fromisoformat(raw_date)
        except (InvalidOperation, ValueError, TypeError):
            raise ValueError('invalid record')
        if not amount.is_finite() or amount < 0:
            raise ValueError('invalid record')
        if county is not None and record_county != county:
            continue
        key = (record_county, parcel, owner)
        if key not in groups:
            groups[key] = [0, Decimal('0'), date]
        groups[key][0] += 1
        groups[key][1] += amount
        if date > groups[key][2]:
            groups[key][2] = date
    ordered = sorted(groups.items(), key=lambda item: (-item[1][1], item[0][1], item[0][2]))
    start = (page - 1) * page_size
    selected = ordered[start:start + page_size]
    rows = [['county', 'parcel_id', 'owner', 'lien_count', 'total_amount', 'latest_recorded_date']]
    for (record_county, parcel, owner), (count, total, latest) in selected:
        value = total.quantize(Decimal('0.01'), rounding=ROUND_HALF_EVEN)
        rows.append([record_county, parcel, owner, str(count), format(value, '.2f'), latest.isoformat()])
    directory = os.path.dirname(os.path.abspath(output_path))
    fd, temporary = tempfile.mkstemp(dir=directory, prefix='.title-')
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as handle:
            csv.writer(handle, lineterminator='\n').writerows(rows)
        os.replace(temporary, output_path)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return len(selected)

