        {'estate_id':'E1','beneficiary':'Bob','email':'b@example.com','amount_cents':125,'due_date':'2026-04-02','channel':'letter','signature':sig('unit-key','E1','b@example.com',125,'2026-04-02','letter')},
        {'estate_id':'E2','beneficiary':'Amy','email':'z@example.com','amount_cents':1000,'due_date':'2026-05-01','channel':'email','signature':sig('unit-key','E2','z@example.com',1000,'2026-05-01','email')}]


