    assert [(x['due_date'],x['estate_id'],x['email']) for x in r]==[('2025-12-31','C','c@x'),('2026-01-01','A','a@x'),('2026-01-01','A','z@x'),('2026-01-01','B','z@x')]


def test_channel_priority_and_beneficiary_tiebreak():
    es=[{'estate_id':'E','beneficiary':'Zed','email':'x@y','amount_cents':2,'due_date':'2026-02-01','channel':'letter'},{'estate_id':'E','beneficiary':'Ada','email':'x@y','amount_cents':3,'due_date':'2026-03-01','channel':'sms'},{'estate_id':'E','beneficiary':'Mia','email':'x@y','amount_cents':4,'due_date':'2026-04-01','channel':'email'}]
