import hashlib
from datetime import date

def create_notifications(events: list[dict], config: dict[str, str] | None=None) -> list[dict]:
    if not events:
        raise ValueError('events must not be empty')
    settings = {} if config is None else config
    key = settings.get('NOTIFICATION_SIGNING_KEY')
    if key is None:
        key = os.environ.get('NOTIFICATION_SIGNING_KEY')
    if not key:
        raise ValueError('NOTIFICATION_SIGNING_KEY is missing')
    priorities = {'email': 0, 'sms': 1, 'letter': 2}
    groups = {}
    for event in events:
        fields = ('estate_id', 'beneficiary', 'email', 'amount_cents', 'due_date', 'channel')
        if any((field not in event for field in fields)):
            raise ValueError('malformed event')
        estate, beneficiary, email = (event['estate_id'], event['beneficiary'], event['email'])
        amount, due, channel = (event['amount_cents'], event['due_date'], event['channel'])
        if not all((isinstance(x, str) and x for x in (estate, beneficiary, email))):
            raise ValueError('malformed event')
        if isinstance(amount, bool) or not isinstance(amount, int) or amount <= 0:
            raise ValueError('malformed event')
        if not isinstance(due, str):
            raise ValueError('malformed event')
        try:
            date.fromisoformat(due)
        except ValueError:
            raise ValueError('malformed event')
        if channel not in priorities:
            raise ValueError('malformed event')
        k = (estate, email)
        if k not in groups:
            groups[k] = {'estate_id': estate, 'beneficiary': beneficiary, 'email': email, 'amount_cents': amount, 'due_date': due, 'channel': channel}
        else:
            x = groups[k]
