            escaped = False
        elif ch == '\\':
            escaped = True
        elif ch == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(ch)
    if escaped:
        raise ValueError('invalid escape')
    fields.append(''.join(current))
    return fields

