import hmac
import json

def process_alerts(body: str, signature: str, secret: str) -> list[dict]:
    expected = hmac.new(secret.encode(), body.encode(), hashlib.sha256).hexdigest()
    if not isinstance(signature, str) or not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    try:
        doc = json.loads(body)
        alerts = doc['alerts']
        if not isinstance(doc, dict) or set(doc) != {'alerts'} or (not isinstance(alerts, list)):
            raise ValueError
        parsed = []
        ids = set()
        for a in alerts:
            if not isinstance(a, dict) or set(a) != {'id', 'neighborhood', 'kind', 'severity', 'residents', 'timestamp'}:
                raise ValueError
            if any((not isinstance(a[k], str) or not a[k] for k in ('id', 'neighborhood', 'kind'))):
                raise ValueError
            if a['id'] in ids or isinstance(a['severity'], bool) or (not isinstance(a['severity'], int)) or (not 1 <= a['severity'] <= 5):
                raise ValueError
            if isinstance(a['residents'], bool) or not isinstance(a['residents'], int) or a['residents'] < 0:
                raise ValueError
            t = a['timestamp']
            if not isinstance(t, str) or not t.endswith('Z'):
                raise ValueError
            dt = datetime.datetime.fromisoformat(t[:-1] + '+00:00')
            if dt.tzinfo is None or dt.utcoffset() != datetime.timedelta(0):
                raise ValueError
            ids.add(a['id'])
            parsed.append((dt.timestamp(), a))
    except Exception as e:
        if isinstance(e, ValueError) and str(e) == 'invalid document':
            raise
        raise ValueError('invalid document')
    groups = {}
    for t, a in parsed:
        groups.setdefault(a['neighborhood'], []).append((t, a))
    out = []
    for name, vals in groups.items():
        vals.sort(key=lambda x: (x[0], x[1]['id']))
        weights = [a['severity'] * a['residents'] for _, a in vals]
        best = left = total = 0
        for right, (t, _) in enumerate(vals):
            total += weights[right]
            while t - vals[left][0] > 3600:
                total -= weights[left]
                left += 1
            best = max(best, total)
        out.append({'neighborhood': name, 'alert_count': len(vals), 'resident_count': sum((a['residents'] for _, a in vals)), 'severity_total': sum(weights), 'peak_severity': max((a['severity'] for _, a in vals)), 'window_score': best})
    return sorted(out, key=lambda x: (-x['window_score'], -x['severity_total'], x['neighborhood']))

