import re
import secrets

def _fields(line):
    fields = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('dangling escape')
    fields.append(''.join(current))
    return fields

def parse_trip_log(text: str) -> list[dict]:
    result = []
    for line in text.splitlines():
        if not line.strip():
            continue
        fields = _fields(line)
        if len(fields) != 5 or not fields[1] or (not fields[2]):
            raise ValueError('invalid record')
        try:
            timestamp = int(fields[0], 10)
            fare = float(fields[4])
        except (TypeError, ValueError):
            raise ValueError('invalid number')
        if timestamp < 0 or fields[3] not in ('pickup', 'dropoff') or (not math.isfinite(fare)) or (fare < 0):
            raise ValueError('invalid record')
        result.append({'timestamp': timestamp, 'vehicle': fields[1], 'zone': fields[2], 'status': fields[3], 'fare': fare})
    return result

def build_dispatch_summary(records: list[dict]) -> dict[str, dict]:
    result = {}
    counts = {}
    for record in records:
        try:
            vehicle = record['vehicle']
            zone = record['zone']
            status = record['status']
            fare = float(record['fare'])
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid record')
        if not isinstance(vehicle, str) or not vehicle or (not isinstance(zone, str)) or (not zone):
            raise ValueError('invalid record')
        if status not in ('pickup', 'dropoff') or not math.isfinite(fare) or fare < 0:
            raise ValueError('invalid record')
        if zone not in result:
            result[zone] = {'pickup_count': 0, 'dropoff_count': 0, 'revenue': 0.0, 'vehicles': []}
            counts[zone] = {}
        result[zone][status + '_count'] += 1
        if status == 'dropoff':
            result[zone]['revenue'] += fare
        counts[zone][vehicle] = counts[zone].get(vehicle, 0) + 1
        if vehicle not in result[zone]['vehicles']:
            result[zone]['vehicles'].append(vehicle)
    for zone, value in result.items():
        value['revenue'] = round(value['revenue'], 2)
        value['vehicles'].sort(key=lambda v: (-counts[zone][v], v))
    return result

