from datetime import datetime
import xml.etree.ElementTree as ET

def parse_itinerary(xml: str) -> dict:
    try:
        root = ET.fromstring(xml)
        if root.tag != 'itinerary' or not root.get('traveler'):
            raise ValueError
        items = []
        for pos, node in enumerate(root):
            if node.tag != 'segment':
                continue
            required = ['kind', 'start', 'end', 'origin', 'destination']
            if any((not node.get(k) for k in required)):
                raise ValueError
            start = datetime.fromisoformat(node.get('start'))
            end = datetime.fromisoformat(node.get('end'))
            if end <= start:
                raise ValueError
            note_node = node.find('note')
            note = '' if note_node is None else ' '.join(''.join(note_node.itertext()).split())
            items.append({'kind': node.get('kind'), 'start': node.get('start'), 'end': node.get('end'), 'origin': node.get('origin'), 'destination': node.get('destination'), 'ref': node.get('ref', ''), 'note': note, 'duration_minutes': int((end - start).total_seconds() // 60), '_start': start, '_end': end, '_pos': pos})
        if not items:
            raise ValueError
        items.sort(key=lambda x: (x['_start'], x['_end'], x['_pos']))
        for item in items:
            item.pop('_start')
            item.pop('_end')
            item.pop('_pos')
        return {'traveler': root.get('traveler'), 'segments': items}
    except Exception as exc:
        if isinstance(exc, ValueError):
            raise
        raise ValueError from exc

def itinerary_stats(itinerary: dict) -> dict:
    segments = itinerary['segments']
    counts = {}
    routes = []
    seen = {}
    total = 0
    for segment in segments:
        counts[segment['kind']] = counts.get(segment['kind'], 0) + 1
        total += segment['duration_minutes']
        key = (segment['origin'], segment['destination'])
        if key not in seen:
            seen[key] = len(routes)
            routes.append({'origin': key[0], 'destination': key[1], 'count': 0})
        routes[seen[key]]['count'] += 1
    return {'traveler': itinerary['traveler'], 'segment_count': len(segments), 'total_duration_minutes': total, 'kinds': {k: counts[k] for k in sorted(counts)}, 'routes': routes}

def render_manifest(itinerary: dict) -> str:
    lines = [f"Traveler: {itinerary['traveler']}"]
    for i, s in enumerate(itinerary['segments'], 1):
        lines.append(f"{i}. {s['kind']} {s['origin']} -> {s['destination']} | {s['start']} to {s['end']} | {s['duration_minutes']} min | {s['ref']} | {s['note']}")
    return '\n'.join(lines)

