import hmac
import json

def canonical_message(issued: int, trains: list[dict]) -> bytes:
    return json.dumps({'issued': issued, 'trains': trains}, sort_keys=True, separators=(',', ':')).encode('utf-8')

def _time(value):
    if not isinstance(value, str) or len(value) != 5 or value[2] != ':' or (not value[:2].isdigit()) or (not value[3:].isdigit()):
        raise ValueError('invalid time')
    hour, minute = (int(value[:2]), int(value[3:]))
    if hour > 23 or minute > 59:
        raise ValueError('invalid time')
    return hour * 60 + minute

def summarize_timetable(document: str, shared_key: bytes) -> list[dict]:
    try:
        obj = json.loads(document)
        if not isinstance(obj, dict) or set(obj) != {'issued', 'trains', 'signature'}:
            raise ValueError('shape')
        issued, trains, signature = (obj['issued'], obj['trains'], obj['signature'])
        if not isinstance(issued, int) or isinstance(issued, bool) or issued < 0 or (not isinstance(trains, list)) or (not isinstance(signature, str)):
            raise ValueError('fields')
        expected = hmac.new(shared_key, canonical_message(issued, trains), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(signature, expected):
            raise ValueError('signature')
        if len(signature) != 64:
            raise ValueError('signature')
        results, identifiers = ([], set())
        for item in trains:
            if not isinstance(item, dict) or set(item) != {'train', 'origin', 'destination', 'departure', 'arrival', 'stops'}:
                raise ValueError('train')
            name, origin, destination = (item['train'], item['origin'], item['destination'])
            if any((not isinstance(x, str) or not x for x in (name, origin, destination))) or name in identifiers:
                raise ValueError('train')
            identifiers.add(name)
            dep, arr = (_time(item['departure']), _time(item['arrival']))
            if dep >= arr or not isinstance(item['stops'], list):
                raise ValueError('sequence')
            previous = dep
            for stop in item['stops']:
                if not isinstance(stop, dict) or set(stop) != {'station', 'time'} or (not isinstance(stop['station'], str)) or (not stop['station']):
                    raise ValueError('stop')
                current = _time(stop['time'])
                if current <= previous or current >= arr:
                    raise ValueError('sequence')
                previous = current
            results.append({'train': name, 'origin': origin, 'destination': destination, 'departure': item['departure'], 'arrival': item['arrival'], 'duration': arr - dep, 'stop_count': len(item['stops'])})
        results.sort(key=lambda x: (int(x['departure'][:2]) * 60 + int(x['departure'][3:]), x['destination'], x['train']))
        return results
    except (json.JSONDecodeError, TypeError, UnicodeError, KeyError, ValueError):
        raise ValueError('invalid timetable')

