import os
import json
import hashlib
import hmac
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from datetime import date

def parse_claim_feed(payload: str) -> list[dict]:
    try:
        data = json.loads(payload)
    except Exception as exc:
        raise ValueError('invalid JSON') from exc
    if not isinstance(data, dict) or not isinstance(data.get('claims'), list):
        raise ValueError('claims must be a list')
    out = []
    seen = set()
    for raw in data['claims']:
        if not isinstance(raw, dict):
            raise ValueError('invalid claim')
        try:
            ident, model, status = (raw['id'], raw['model'], raw['status'])
            amount, submitted = (raw['amount'], raw['submitted'])
        except KeyError as exc:
            raise ValueError('missing claim field') from exc
        if not all((isinstance(x, str) and x for x in (ident, model, status))):
            raise ValueError('invalid text field')
        if status not in {'approved', 'denied', 'pending'} or ident in seen:
            raise ValueError('invalid status or duplicate id')
        if isinstance(amount, bool):
            raise ValueError('invalid amount')
        try:
            cents = int((Decimal(str(amount)) * 100).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
        except (InvalidOperation, ValueError, TypeError):
            raise ValueError('invalid amount')
        if cents < 0:
            raise ValueError('invalid amount')
        try:
            date.fromisoformat(submitted)
        except (TypeError, ValueError):
            raise ValueError('invalid date')
        if len(submitted) != 10:
            raise ValueError('invalid date')
        seen.add(ident)
        out.append({'id': ident, 'model': model, 'status': status, 'amount_cents': cents, 'submitted': submitted})
    return sorted(out, key=lambda x: (x['submitted'], x['id']))

def build_warranty_summary(claims: list[dict]) -> dict:
    groups = {}
    for claim in claims:
        if not isinstance(claim, dict) or set(claim) != {'id', 'model', 'status', 'amount_cents', 'submitted'}:
            raise ValueError('invalid normalized claim')
        if not isinstance(claim['amount_cents'], int) or isinstance(claim['amount_cents'], bool) or claim['amount_cents'] < 0 or (claim['status'] not in {'approved', 'denied', 'pending'}):
            raise ValueError('invalid normalized claim')
        model = claim['model']
        if not isinstance(model, str) or not model:
            raise ValueError('invalid model')
        group = groups.setdefault(model, {'model': model, 'claim_count': 0, 'status_counts': {'approved': 0, 'denied': 0, 'pending': 0}, 'approved_cents': 0, 'latest_submission': None})
        group['claim_count'] += 1
        group['status_counts'][claim['status']] += 1
        if claim['status'] == 'approved':
            group['approved_cents'] += claim['amount_cents']
        if group['latest_submission'] is None or claim['submitted'] > group['latest_submission']:
            group['latest_submission'] = claim['submitted']
    return {'total_claims': len(claims), 'by_model': [groups[k] for k in sorted(groups)]}

def sign_warranty_summary(summary: dict) -> str:
    key = os.environ.get('WARRANTY_SIGNING_KEY')
    if key is None:
        raise RuntimeError('WARRANTY_SIGNING_KEY is required')
    data = json.dumps(summary, sort_keys=True, separators=(',', ':')).encode('utf-8')
    return hmac.new(key.encode('utf-8'), data, hashlib.sha256).hexdigest()

