import secrets
from datetime import datetime, timezone
_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'

def create_invite_code(length: int=12) -> str:
    if type(length) is not int or not 8 <= length <= 64:
        raise ValueError('invalid length')
    return ''.join((secrets.choice(_ALPHABET) for _ in range(length)))

def _timestamp(value: str) -> datetime:
    if not isinstance(value, str) or not value.endswith('Z'):
        raise ValueError('invalid timestamp')
    try:
        result = datetime.fromisoformat(value[:-1] + '+00:00')
    except (TypeError, ValueError):
        raise ValueError('invalid timestamp')
    if result.tzinfo is None or result.utcoffset() != timezone.utc.utcoffset(result):
        raise ValueError('invalid timestamp')
    return result.astimezone(timezone.utc)

def _fields(line: str) -> list[str]:
    fields, current, escaped = ([], [], False)
    for char in line:
        if escaped:
            if char not in '\\|':
                raise ValueError('invalid escape')
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('invalid escape')
    fields.append(''.join(current))
    return fields

def parse_membership_events(lines: list[str]) -> list[dict[str, object]]:
    result = []
    for index, line in enumerate(lines):
        fields = _fields(line)
        if len(fields) != 4 or not fields[1]:
            raise ValueError('invalid record')
        timestamp = _timestamp(fields[0])
        action = fields[2]
        if action not in {'join', 'renew', 'cancel'}:
            raise ValueError('invalid action')
        try:
            months = int(fields[3])
        except (TypeError, ValueError):
            raise ValueError('invalid months')
        if action == 'cancel':
            if fields[3] != '0':
                raise ValueError('invalid months')
        elif months <= 0 or fields[3] != str(months):
            raise ValueError('invalid months')
        result.append({'timestamp': timestamp, 'member': fields[1], 'action': action, 'months': months, '_index': index})
    result.sort(key=lambda event: (event['timestamp'], event['_index']))
    for event in result:
        del event['_index']
    return result

def membership_snapshot(lines: list[str], as_of: str) -> dict[str, dict[str, object]]:
    cutoff = _timestamp(as_of)
    states = {}
    for event in parse_membership_events(lines):
        if event['timestamp'] > cutoff:
            continue
        member = event['member']
        state = states.setdefault(member, {'active': False, 'months': 0, 'joined_at': None, 'last_action': None})
        action = event['action']
        if action == 'join':
            if state['active']:
                raise ValueError('invalid transition')
            state['active'] = True
            if state['joined_at'] is None:
                state['joined_at'] = event['timestamp']
            state['months'] += event['months']
        elif action == 'renew':
            if not state['active']:
                raise ValueError('invalid transition')
            state['months'] += event['months']
        else:
            if not state['active']:
                raise ValueError('invalid transition')
            state['active'] = False
        state['last_action'] = action
    return {member: states[member] for member in sorted(states)}

