def export_material_summary(records: list[dict], destination: str, max_contamination: float=5.0) -> int:
    if isinstance(max_contamination, bool) or not isinstance(max_contamination, (int, float)) or (not math.isfinite(max_contamination)) or (not 0 <= max_contamination <= 100):
        raise ValueError('invalid contamination limit')
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        material = record.get('material')
        weight = record.get('weight_kg')
        contamination = record.get('contamination_pct')
        if not isinstance(material, str) or not material:
            raise ValueError('invalid material')
        if isinstance(weight, bool) or not isinstance(weight, (int, float)) or (not math.isfinite(weight)) or (weight <= 0):
            raise ValueError('invalid weight')
        if isinstance(contamination, bool) or not isinstance(contamination, (int, float)) or (not math.isfinite(contamination)) or (not 0 <= contamination <= 100):
            raise ValueError('invalid contamination')
        if contamination <= max_contamination:
            total, weighted, count = groups.get(material, (0.0, 0.0, 0))
            groups[material] = (total + weight, weighted + weight * contamination, count + 1)
    rows = sorted(groups.items(), key=lambda item: (-item[1][0], item[0]))
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent, suffix='.csv')
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['material', 'total_weight_kg', 'average_contamination_pct', 'loads'])
            for material, (total, weighted, count) in rows:
                writer.writerow([material, f'{total:.2f}', f'{weighted / total:.2f}', count])
        os.replace(temporary, destination)
    except BaseException:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return len(rows)

