import datetime
import re
import subprocess

def read_delivery_log(path: str) -> list[dict]:
    result = subprocess.run(['sort', '--', path], check=True, capture_output=True, text=True)
    records = []
    for raw in result.stdout.splitlines():
        if not raw.strip():
            continue
        fields = raw.split('\t')
        if len(fields) != 4:
            raise ValueError('malformed row')
        subscriber, date, copies_text, cents_text = fields
        if not subscriber or '\n' in subscriber or '\r' in subscriber:
            raise ValueError('invalid subscriber')
        try:
            datetime.date.fromisoformat(date)
            copies = int(copies_text)
            cents = int(cents_text)
        except (ValueError, TypeError):
            raise ValueError('invalid row')
        if copies < 0 or cents < 0 or '\t' in subscriber:
            raise ValueError('invalid row')
        records.append({'subscriber': subscriber, 'date': date, 'copies': copies, 'cents': cents})
    return records

def make_monthly_report(path: str, month: str) -> list[dict]:
    if not re.fullmatch('\\d{4}-\\d{2}', month) or not 1 <= int(month[5:]) <= 12:
        raise ValueError('invalid month')
    totals = {}
    for record in read_delivery_log(path):
        if record['date'][:7] != month:
            continue
        name = record['subscriber']
        if name not in totals:
            totals[name] = {'subscriber': name, 'deliveries': 0, 'copies': 0, 'total_cents': 0}
        item = totals[name]
        item['deliveries'] += 1
        item['copies'] += record['copies']
        item['total_cents'] += record['copies'] * record['cents']
    return [totals[name] for name in sorted(totals)]

