def maintenance_summary(xml_text: str, page: int, page_size: int, min_cost: float=0.0) -> dict:
    if page < 1 or page_size < 1 or page_size > 100 or (min_cost < 0):
        raise ValueError('invalid pagination or cost')
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml_text.encode(), parser=parser)
        if root.tag != 'report':
            raise ValueError('invalid root')
        groups = {}
        for event in root.findall('.//event'):
            values = [event.get(name) for name in ('turbine', 'date', 'status', 'downtime_hours', 'cost')]
            if any((value is None for value in values)):
                raise ValueError('missing attribute')
            turbine, date, status, downtime_text, cost_text = values
            downtime = float(downtime_text)
            cost = float(cost_text)
            if cost < min_cost:
                continue
            group = groups.setdefault(turbine, {'events': 0, 'downtime': 0.0, 'cost': 0.0, 'date': '', 'status': ''})
