import sqlite3

def create_schema(conn: sqlite3.Connection) -> None:
    conn.execute('CREATE TABLE IF NOT EXISTS referrals (\n        id INTEGER PRIMARY KEY AUTOINCREMENT,\n        employee_id INTEGER NOT NULL,\n        service TEXT NOT NULL,\n        urgency INTEGER NOT NULL,\n        note TEXT NOT NULL,\n        status TEXT NOT NULL,\n        created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n    )')
    conn.commit()

def record_referral(conn: sqlite3.Connection, employee_id: int, service: str, urgency: int, note: str) -> int:
    if not isinstance(employee_id, int) or employee_id <= 0:
        raise ValueError('invalid employee')
    if not isinstance(service, str) or not service.strip():
        raise ValueError('invalid service')
    if not isinstance(urgency, int) or not 1 <= urgency <= 5:
        raise ValueError('invalid urgency')
    if not isinstance(note, str):
        raise ValueError('invalid note')
    cur = conn.execute('INSERT INTO referrals(employee_id,service,urgency,note,status) VALUES (?,?,?,?,?)', (employee_id, service, urgency, note, 'pending'))
    conn.commit()
    return cur.lastrowid

def find_referrals(conn: sqlite3.Connection, employee_id: int | None=None, status: str | None=None, search: str='', sort_by: str='created', descending: bool=False) -> list[dict]:
    if employee_id is not None and (not isinstance(employee_id, int) or employee_id <= 0):
        raise ValueError('invalid employee')
    if status is not None and status not in ('pending', 'active', 'closed'):
        raise ValueError('invalid status')
    columns = {'created': 'created_at', 'employee': 'employee_id', 'urgency': 'urgency', 'status': 'status', 'service': 'service'}
    if sort_by not in columns:
        raise ValueError('invalid sort')
    clauses, values = ([], [])
    if employee_id is not None:
        clauses.append('employee_id = ?')
        values.append(employee_id)
    if status is not None:
        clauses.append('status = ?')
        values.append(status)
    if not isinstance(search, str):
        raise ValueError('invalid search')
    if search:
        clauses.append('(lower(service) LIKE lower(?) OR lower(note) LIKE lower(?))')
        values.extend(['%' + search + '%', '%' + search + '%'])
    where = ' WHERE ' + ' AND '.join(clauses) if clauses else ''
    direction = ' DESC' if descending else ' ASC'
    sql = 'SELECT id,employee_id,service,urgency,note,status,created_at FROM referrals' + where
    sql += ' ORDER BY ' + columns[sort_by] + direction + ', id ASC'
    rows = conn.execute(sql, values).fetchall()
    names = ['id', 'employee_id', 'service', 'urgency', 'note', 'status', 'created_at']
    return [dict(zip(names, row)) for row in rows]

def update_referral_status(conn: sqlite3.Connection, referral_id: int, status: str) -> bool:
    if not isinstance(referral_id, int) or referral_id <= 0:
        raise ValueError('invalid id')
    if status not in ('pending', 'active', 'closed'):
        raise ValueError('invalid status')
    cur = conn.execute('UPDATE referrals SET status = ? WHERE id = ?', (status, referral_id))
    conn.commit()
    return cur.rowcount == 1

def employee_summary(conn: sqlite3.Connection) -> list[dict]:
    rows = conn.execute("SELECT employee_id, COUNT(*),\n        SUM(CASE WHEN status IN ('pending','active') THEN 1 ELSE 0 END),\n        SUM(CASE WHEN status IN ('pending','active') AND urgency >= 4 THEN 1 ELSE 0 END)\n        FROM referrals GROUP BY employee_id ORDER BY employee_id").fetchall()
    return [dict(zip(('employee_id', 'total', 'open_count', 'urgent_open'), row)) for row in rows]

