import csv
import math
import os
import tempfile
from collections import Counter
from io import StringIO

def parse_observations(text: str) -> list[dict]:
    rows = list(csv.reader(StringIO(text)))
    while rows and (not any(rows[-1])):
        rows.pop()
    if not rows or rows[0] != ['timestamp', 'spacecraft', 'signal', 'mode']:
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if not any(row):
            continue
        if len(row) != 4 or not row[0] or (not row[1]) or (not row[2]) or (not row[3]):
            raise ValueError('invalid row')
        try:
            timestamp = int(row[0])
            signal = float(row[2])
        except ValueError:
            raise ValueError('invalid value')
        if not math.isfinite(signal):
            raise ValueError('invalid signal')
        result.append({'timestamp': timestamp, 'spacecraft': row[1], 'signal': signal, 'mode': row[3]})
    return result

def aggregate_passes(observations: list[dict], max_gap: int=90) -> list[dict]:
    if isinstance(max_gap, bool) or not isinstance(max_gap, int) or max_gap < 0:
        raise ValueError('invalid gap')
    grouped = {}
    for index, item in enumerate(observations):
        grouped.setdefault(item['spacecraft'], []).append((item, index))
    result = []
    for spacecraft in sorted(grouped):
        ordered = sorted(grouped[spacecraft], key=lambda x: (x[0]['timestamp'], x[1]))
        passes = []
        for item, _ in ordered:
            if not passes or item['timestamp'] - passes[-1][-1]['timestamp'] > max_gap:
                passes.append([])
            passes[-1].append(item)
        for number, batch in enumerate(passes, 1):
            signals = [x['signal'] for x in batch]
            modes = Counter((x['mode'] for x in batch))
            mode = min(modes, key=lambda x: (-modes[x], x))
            result.append({'spacecraft': spacecraft, 'pass': number, 'start': batch[0]['timestamp'], 'end': batch[-1]['timestamp'], 'samples': len(batch), 'avg_signal': round(sum(signals) / len(signals), 3), 'peak_signal': round(max(signals), 3), 'mode': mode})
    return result

def export_pass_report(observations: list[dict], output_path: str, max_gap: int=90) -> list[dict]:
    rows = aggregate_passes(observations, max_gap)
    fd, temporary = tempfile.mkstemp(dir=os.path.dirname(os.path.abspath(output_path)), text=True)
    try:
        with os.fdopen(fd, 'w', newline='') as handle:
            writer = csv.writer(handle)
            writer.writerow(['spacecraft', 'pass', 'start', 'end', 'samples', 'avg_signal', 'peak_signal', 'mode'])
            for row in rows:
                writer.writerow([row['spacecraft'], row['pass'], row['start'], row['end'], row['samples'], row['avg_signal'], row['peak_signal'], row['mode']])
        os.replace(temporary, output_path)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return rows

