from datetime import date

def assign_interpreter(requester: dict, hearing: dict, interpreters: list[dict]) -> dict:
    if not isinstance(hearing.get('duration_minutes'), int) or isinstance(hearing.get('duration_minutes'), bool) or hearing['duration_minutes'] <= 0:
        raise ValueError('duration_minutes must be a positive integer')
    try:
        date.fromisoformat(hearing['scheduled_date'])
    except (KeyError, TypeError, ValueError):
        raise ValueError('scheduled_date must be an ISO date')
    if hearing.get('status') != 'scheduled':
        raise ValueError('hearing is not schedulable')
    if hearing.get('assigned_interpreter_id') is not None:
        raise ValueError('hearing is already assigned')
    allowed = requester.get('tenant_id') == hearing.get('tenant_id') and (requester.get('id') == hearing.get('created_by') or 'court_admin' in requester.get('roles', []))
    if not allowed:
        raise PermissionError('requester cannot assign this hearing')
    duration = hearing['duration_minutes']
    candidates = []
