import hashlib
import hmac
import json
import pytest


def make_signature(payload, key):
    return hmac.new(key.encode(), payload.encode(), hashlib.sha256).hexdigest()


def test_aggregates_unacknowledged_events_and_rounds():
    payload = json.dumps({"events": [
        {"sensor": "front-door", "severity": "high", "duration_seconds": 61, "acknowledged": False},
        {"sensor": "front-door", "severity": "critical", "duration_seconds": 59, "acknowledged": False},
        {"sensor": "garage", "severity": "low", "duration_seconds": 30, "acknowledged": True},
        {"sensor": "garage", "severity": "medium", "duration_seconds": 90, "acknowledged": False}
    ]}, separators=(",", ":"))
    result = summarize_alarm_events(payload, make_signature(payload, "k"), "k")
    assert result == {
        "total_events": 3,
        "total_duration_minutes": 3.5,
        "sensors": [
            {"sensor": "front-door", "count": 2, "duration_minutes": 2.0, "highest_severity": "critical"},
            {"sensor": "garage", "count": 1, "duration_minutes": 1.5, "highest_severity": "medium"}
        ]
    }


def test_sensor_order_uses_name_for_count_ties():
    payload = json.dumps({"events": [
        {"sensor": "zeta", "severity": "low", "duration_seconds": 1, "acknowledged": False},
        {"sensor": "alpha", "severity": "critical", "duration_seconds": 2, "acknowledged": False},
        {"sensor": "beta", "severity": "high", "duration_seconds": 3, "acknowledged": False},
        {"sensor": "alpha", "severity": "low", "duration_seconds": 4, "acknowledged": False}
    ]})
    result = summarize_alarm_events(payload, make_signature(payload, "key"), "key")
    assert [x["sensor"] for x in result["sensors"]] == ["alpha", "beta", "zeta"]
    assert result["total_duration_minutes"] == 0.17


def test_empty_and_all_acknowledged_events():
    for events in [[], [{"sensor": "hall", "severity": "critical", "duration_seconds": 20, "acknowledged": True}]]:
        payload = json.dumps({"events": events})
        assert summarize_alarm_events(payload, make_signature(payload, "x"), "x") == {
            "total_events": 0, "total_duration_minutes": 0.0, "sensors": []
        }


def test_bad_signature_is_rejected():
    payload = json.dumps({"events": []})
    with pytest.raises(PermissionError):
        summarize_alarm_events(payload, "0" * 64, "correct-key")


def test_bad_signature_precedes_payload_parsing():
    with pytest.raises(PermissionError):
        summarize_alarm_events("not json", "wrong", "key")


