import hashlib
import hmac
import json

def summarize_alarm_events(payload: str, signature: str, shared_key: str) -> dict:
    expected = hmac.new(shared_key.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise PermissionError('invalid signature')
    try:
        data = json.loads(payload)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(data, dict) or 'events' not in data or (not isinstance(data['events'], list)):
        raise ValueError('invalid events')
    ranks = {'low': 0, 'medium': 1, 'high': 2, 'critical': 3}
    grouped = {}
    for event in data['events']:
        if not isinstance(event, dict):
            raise ValueError('invalid event')
        if set(event) != {'sensor', 'severity', 'duration_seconds', 'acknowledged'}:
            raise ValueError('invalid event')
        sensor = event['sensor']
        severity = event['severity']
        duration = event['duration_seconds']
        acknowledged = event['acknowledged']
        if not isinstance(sensor, str) or not sensor or severity not in ranks:
            raise ValueError('invalid event')
        if isinstance(duration, bool) or not isinstance(duration, int) or duration < 0:
            raise ValueError('invalid event')
        if not isinstance(acknowledged, bool):
            raise ValueError('invalid event')
        if acknowledged:
            continue
        item = grouped.setdefault(sensor, {'count': 0, 'duration': 0, 'severity': 'low'})
        item['count'] += 1
        item['duration'] += duration
        if ranks[severity] > ranks[item['severity']]:
            item['severity'] = severity
    sensors = []
    total_count = 0
    total_duration = 0
    for sensor, item in grouped.items():
        total_count += item['count']
        total_duration += item['duration']
        sensors.append({'sensor': sensor, 'count': item['count'], 'duration_minutes': round(item['duration'] / 60, 2), 'highest_severity': item['severity']})
    sensors.sort(key=lambda x: (-x['count'], x['sensor']))
    return {'total_events': total_count, 'total_duration_minutes': round(total_duration / 60, 2), 'sensors': sensors}

