def extract_application_archive(base_dir: str, archive_path: str, application_id: str) -> list[str]:
    base = os.path.abspath(base_dir)
    root = os.path.abspath(os.path.join(base, application_id))
    os.makedirs(root, exist_ok=True)
    result = []
    with zipfile.ZipFile(archive_path) as archive:
        for member in archive.infolist():
            if member.is_dir():
                continue
            target = os.path.abspath(os.path.join(root, member.filename))
            if os.path.commonpath([root, target]) != root:
                raise ValueError('invalid archive member')
            os.makedirs(os.path.dirname(target), exist_ok=True)
            with archive.open(member) as source, open(target, 'wb') as destination:
                destination.write(source.read())
            result.append(os.path.relpath(target, base).replace(os.sep, '/'))
    return sorted(result)

def parse_rate_sheet(text: str) -> dict[str, list[tuple[int, float, float]]]:
    output = {}
    seen = set()
    for line in text.splitlines():
        if not line.strip():
            continue
        try:
            row = next(csv.reader([line], delimiter='|', escapechar='\\', strict=True))
        except (csv.Error, StopIteration):
            raise ValueError('invalid row')
        if len(row) != 4 or not row[0]:
            raise ValueError('invalid row')
        try:
            term = int(row[1])
            rate = float(row[2])
            points = float(row[3])
        except ValueError:
            raise ValueError('invalid number')
        if term <= 0 or rate < 0 or points < 0 or (not all((math.isfinite(x) for x in (rate, points)))):
            raise ValueError('invalid value')
        key = (row[0], term)
        if key in seen:
            raise ValueError('duplicate term')
        seen.add(key)
        output.setdefault(row[0], []).append((term, rate, points))
    for values in output.values():
        values.sort(key=lambda x: (x[0], x[1]))
    return output

def rank_applications(records: list[dict[str, object]]) -> list[dict[str, object]]:
    required = {'applicant', 'income', 'monthly_debt', 'loan_amount', 'credit_score'}
    result = []
    for record in records:
        if not required.issubset(record) or not isinstance(record['applicant'], str):
            raise ValueError('invalid application')
        income = record['income']
        debt = record['monthly_debt']
        amount = record['loan_amount']
        credit = record['credit_score']
        if isinstance(credit, bool) or not isinstance(credit, int) or (not 300 <= credit <= 850):
            raise ValueError('invalid credit score')
        if any((isinstance(x, bool) or not isinstance(x, (int, float)) or (not math.isfinite(x)) for x in (income, debt, amount))):
            raise ValueError('invalid numeric value')
        if income <= 0 or debt < 0 or amount <= 0:
            raise ValueError('invalid range')
        score = credit / 850 - debt * 12 / income - amount / (income * 10)
        item = dict(record)
        item['score'] = round(score, 6)
        result.append(item)
    result.sort(key=lambda x: (-x['score'], -x['credit_score'], x['applicant']))
    return result

