def process_moderation(requester: dict, reviews: list[dict], event_log: str) -> dict:
    states = {r['id']: {**r, 'status': 'pending', 'reason': None, 'history': []} for r in reviews}

    def apply(line):
        line = line.strip()
        if not line:
            return
        fields, field, escaped = ([], [], False)
        for ch in line:
            if escaped:
                field.append(ch)
                escaped = False
            elif ch == '\\':
                escaped = True
            elif ch == '|':
                fields.append(''.join(field))
                field = []
            else:
                field.append(ch)
        if escaped:
            raise ValueError('dangling escape')
        fields.append(''.join(field))
        if len(fields) != 3:
            raise ValueError('malformed record')
        rid, action, reason = fields
        if rid not in states:
            raise KeyError(rid)
        if action not in {'approve', 'reject', 'hold'}:
            raise ValueError('invalid action')
        if (action == 'reject') == (reason == ''):
            raise ValueError('invalid reason')
        stored = reason if action == 'reject' else None
        status = {'approve': 'approved', 'reject': 'rejected', 'hold': 'held'}[action]
        states[rid]['status'] = status
        states[rid]['reason'] = stored
        states[rid]['history'].append({'action': action, 'reason': stored})
    for line in event_log.splitlines():
        apply(line)
    for item in states.values():
        if not (item['author_id'] == requester['id'] or (requester['role'] == 'moderator' and requester['tenant'] == item['tenant'])):
            raise PermissionError('not permitted')
    order = {'rejected': 0, 'pending': 1, 'held': 2, 'approved': 3}
    result = sorted(states.values(), key=lambda x: (order[x['status']], -x['priority'], x['created_at'], x['id']))
    return {'reviews': result, 'summary': {k: sum((x['status'] == k for x in result)) for k in order}}

