import datetime
import json
import os
import tempfile

def _timestamp(value):
    if not isinstance(value, str) or not value.endswith('Z'):
        raise ValueError('invalid timestamp')
    try:
        parsed = datetime.datetime.fromisoformat(value[:-1])
    except (TypeError, ValueError):
        raise ValueError('invalid timestamp')
    if parsed.tzinfo is not None:
        raise ValueError('invalid timestamp')
    return parsed.replace(tzinfo=datetime.timezone.utc)

def _validated(records, now, quota):
    if isinstance(quota, bool) or not isinstance(quota, int) or quota < 0:
        raise ValueError('invalid quota')
    current = _timestamp(now)
    lower = current - datetime.timedelta(days=7)
    seen = set()
    prepared = []
    for item in records:
        if not isinstance(item, dict):
            raise ValueError('invalid record')
        for key in ('event_id', 'camera', 'captured_at', 'size'):
            if key not in item:
                raise ValueError('invalid record')
        event_id = item['event_id']
        camera = item['camera']
        size = item['size']
        if not isinstance(event_id, str) or not event_id or (not isinstance(camera, str)) or (not camera):
            raise ValueError('invalid record')
        if isinstance(size, bool) or not isinstance(size, int) or size < 0:
            raise ValueError('invalid record')
        if event_id in seen:
            raise ValueError('duplicate event')
        seen.add(event_id)
        stamp = _timestamp(item['captured_at'])
        if lower <= stamp <= current:
            prepared.append((stamp, camera, event_id, item))
    prepared.sort(key=lambda x: (-x[0].timestamp(), x[1], x[2]))
    selected = []
    used = 0
    for stamp, camera, event_id, item in prepared:
        if used + item['size'] <= quota:
            selected.append(dict(item))
            used += item['size']
    return selected

def select_retained(records: list[dict], now: str, quota: int) -> list[dict]:
    return _validated(records, now, quota)

def export_retention(records: list[dict], now: str, quota: int, destination: str) -> int:
    selected = _validated(records, now, quota)
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8') as stream:
            for item in selected:
                stream.write(json.dumps(item, separators=(',', ':'), ensure_ascii=False) + '\n')
        os.replace(temporary, destination)
    except BaseException:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return len(selected)

