import datetime
import hashlib
import hmac
import json
import re
from typing import Any

def parse_intake_request(raw: bytes, signature: str, signing_key: bytes) -> dict[str, Any]:
    if not isinstance(raw, bytes) or not isinstance(signature, str) or (not isinstance(signing_key, bytes)):
        raise ValueError('invalid signature')
    if re.fullmatch('sha256=[0-9a-f]{64}', signature) is None:
        raise ValueError('invalid signature')
    expected = hmac.new(signing_key, raw, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(signature[7:], expected):
        raise ValueError('invalid signature')
    try:
        value = json.loads(raw.decode('utf-8'))
        required = {'client_id', 'region', 'urgency', 'services', 'submitted_at'}
        if not isinstance(value, dict) or set(value) != required:
            raise ValueError
        if not isinstance(value['client_id'], str) or not value['client_id']:
            raise ValueError
        if not isinstance(value['region'], str) or not value['region']:
            raise ValueError
        if isinstance(value['urgency'], bool) or not isinstance(value['urgency'], int) or (not 1 <= value['urgency'] <= 5):
            raise ValueError
        services = value['services']
        if not isinstance(services, list) or not services or any((not isinstance(x, str) or not x for x in services)) or (len(set(services)) != len(services)):
            raise ValueError
        stamp = value['submitted_at']
        if not isinstance(stamp, str) or re.fullmatch('\\d{4}-\\d\\d-\\d\\dT\\d\\d:\\d\\d:\\d\\dZ', stamp) is None:
            raise ValueError
        datetime.datetime.strptime(stamp, '%Y-%m-%dT%H:%M:%SZ')
        return {'client_id': value['client_id'], 'region': value['region'], 'urgency': value['urgency'], 'services': sorted(services), 'submitted_at': stamp}
    except (ValueError, TypeError, KeyError, json.JSONDecodeError, UnicodeDecodeError, OverflowError):
        raise ValueError('invalid intake')

def rank_intakes(records: list[dict[str, Any]], limit: int) -> list[dict[str, Any]]:
    if isinstance(limit, bool) or not isinstance(limit, int) or limit <= 0:
        raise ValueError('invalid limit')
    required = {'client_id', 'region', 'urgency', 'services', 'submitted_at'}
    unique = []
    seen = set()
    for record in records:
        if not isinstance(record, dict) or not required.issubset(record):
            raise ValueError('invalid intake')
        if record['client_id'] not in seen:
            seen.add(record['client_id'])
            unique.append(record)
    unique.sort(key=lambda x: (-x['urgency'], x['submitted_at'], x['region'], x['client_id']))
    return [{**x, 'services': list(x['services'])} for x in unique[:limit]]

