import pytest


def test_pin_round_trip_for_valid_values():
    for pin in ["1234", "0000", "987654321012"]:
        stored = hash_pin(pin)
        assert isinstance(stored, str)
        assert verify_pin(stored, pin)


def test_pin_rejects_wrong_values_and_invalid_inputs():
    stored = hash_pin("2468")
    assert not verify_pin(stored, "2469")
    assert not verify_pin(stored, "24680")
    for value in ["", "123", "1234567890123", "12a4", "１２３４"]:
        with pytest.raises(ValueError):
            hash_pin(value)
        assert not verify_pin(stored, value)
    with pytest.raises(TypeError):
        hash_pin(1234)
    assert not verify_pin(stored, 1234)


