def hash_pin(pin: str) -> str:
    if not isinstance(pin, str):
        raise TypeError()
    if not pin.isascii() or not pin.isdigit() or (not 4 <= len(pin) <= 12):
        raise ValueError()
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return salt.hex() + '$' + value.hex()

def verify_pin(stored: str, pin: str) -> bool:
    if not isinstance(stored, str) or not isinstance(pin, str):
        return False
    if not pin.isascii() or not pin.isdigit() or (not 4 <= len(pin) <= 12):
        return False
    try:
        salt_text, value_text = stored.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(value_text)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def active_contract_totals(contracts: list[dict], as_of: str) -> list[dict]:
