        raise TypeError()
    if not isinstance(as_of, str):
        raise TypeError()
    try:
        point = date.fromisoformat(as_of)
    except ValueError:
        raise ValueError()
    seen = set()
    result = []
    for contract in contracts:
        if not isinstance(contract, dict):
            raise ValueError()
        try:
            ident = contract['id']
            supplier = contract['supplier']
            start = date.fromisoformat(contract['start'])
            end = date.fromisoformat(contract['end'])
