import base64
import hashlib
import hmac
import os

def hash_password(password: str) -> str:
    if not isinstance(password, str) or not password:
        raise ValueError('password must be non-empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return 'pbkdf2$' + base64.b64encode(salt).decode() + '$' + base64.b64encode(digest).decode()

def verify_password(password: str, stored_hash: str) -> bool:
    if not isinstance(password, str) or not password or (not isinstance(stored_hash, str)):
        return False
    try:
        kind, salt_text, digest_text = stored_hash.split('$', 2)
        if kind != 'pbkdf2':
            return False
        salt = base64.b64decode(salt_text.encode(), validate=True)
        expected = base64.b64decode(digest_text.encode(), validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def create_account(username: str, password: str, ticket_ids: list[str] | None=None) -> dict:
    if not isinstance(username, str) or not username.strip():
        raise ValueError('username must be non-empty')
    return {'username': username.strip(), 'password_hash': hash_password(password), 'ticket_ids': list(ticket_ids or []), 'active': True}

