import hashlib
import hmac
import json
from datetime import datetime

def process_schedule_webhook(body: str, signature: str, secret: str, page: int=1, page_size: int=10) -> dict:
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    if len(signature) != 71 or not signature.startswith('sha256='):
        raise ValueError('invalid signature')
    supplied = signature[7:]
    if any((c not in '0123456789abcdef' for c in supplied)):
        raise ValueError('invalid signature')
    expected = hmac.new(secret.encode(), body.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(supplied, expected):
        raise PermissionError('signature mismatch')
    try:
        data = json.loads(body)
    except Exception as exc:
        raise ValueError('invalid JSON') from exc
    if not isinstance(data, dict) or not isinstance(data.get('sessions'), list):
        raise ValueError('invalid sessions')
    sessions = []
    ids = set()
    for item in data['sessions']:
        if not isinstance(item, dict) or set(item) != {'id', 'participant', 'start', 'duration', 'modality'}:
            raise ValueError('invalid session')
        if any((not isinstance(item[k], str) or not item[k] for k in ('id', 'participant', 'modality'))):
            raise ValueError('invalid session')
        if not isinstance(item['duration'], int) or isinstance(item['duration'], bool) or item['duration'] <= 0:
            raise ValueError('invalid session')
        if not item['start'].endswith('Z'):
            raise ValueError('invalid session')
        try:
            start = datetime.fromisoformat(item['start'][:-1])
        except ValueError as exc:
            raise ValueError('invalid session') from exc
        if item['id'] in ids:
            raise ValueError('duplicate id')
        ids.add(item['id'])
        sessions.append((start, item))
    sessions.sort(key=lambda x: (x[0], x[1]['id']))
    totals = {}
    for _, item in sessions:
        entry = totals.setdefault(item['modality'], [0, 0])
        entry[0] += 1
        entry[1] += item['duration']
    first = (page - 1) * page_size
    return {'total': len(sessions), 'sessions': [x[1] for x in sessions[first:first + page_size]], 'by_modality': [{'modality': k, 'count': v[0], 'minutes': v[1]} for k, v in sorted(totals.items())]}

