    if type(page) is not int or type(page_size) is not int or page <= 0 or (page_size <= 0):
        raise ValueError('invalid pagination')
    try:
        parser = etree.XMLParser(resolve_entities=True, load_dtd=True)
        root = etree.fromstring(xml_text.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'applications':
        raise ValueError('invalid root')
    rows = []
    for node in root.findall('application'):
        try:
            ident = (node.get('id') or '').strip()
            values = {}
            for name in ('student', 'gpa', 'income', 'status', 'requested'):
                child = node.find(name)
                if child is None or child.text is None:
                    raise ValueError('missing field')
                values[name] = child.text.strip()
            if not ident or not values['student']:
                raise ValueError('blank field')
            gpa = Decimal(values['gpa'])
            income = Decimal(values['income'])
            requested = Decimal(values['requested'])
            if requested < 0:
                raise ValueError('negative request')
        except (InvalidOperation, ValueError) as exc:
            raise ValueError('invalid application') from exc
        if values['status'] == 'submitted' and gpa >= Decimal('3.0') and (income <= Decimal('50000')):
            award = (requested / Decimal('100')).quantize(Decimal('1'), rounding=ROUND_HALF_UP) * 100
            award = min(award, Decimal('4000'))
            rows.append((gpa, income, ident, {'id': ident, 'student': values['student'], 'award': int(award)}))
    rows.sort(key=lambda item: (-item[0], item[1], item[2]))
    start = (page - 1) * page_size
    return [item[3] for item in rows[start:start + page_size]]

