    if not isinstance(conn, sqlite3.Connection):
        raise TypeError('conn must be a sqlite connection')
    if not isinstance(app_id, int) or isinstance(app_id, bool):
        raise TypeError('app_id must be an integer')
    if status is not None and (not isinstance(status, str)):
        raise TypeError('status must be a string or None')
    if not isinstance(search, str) or not isinstance(sort_by, str):
