    if status is not None and status not in {'draft', 'testing', 'active', 'retired'}:
        raise ValueError('invalid status')
    columns = {'version', 'rollout', 'released_at', 'id'}
    if sort_by not in columns:
        raise ValueError('invalid sort key')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    clauses = ['app_id = ?', '(version LIKE ? COLLATE NOCASE OR channel LIKE ? COLLATE NOCASE)']
    params = [app_id, f'%{search}%', f'%{search}%']
    if status is not None:
        clauses.append('status = ?')
        params.append(status)
    offset = (page - 1) * page_size
    query = f"SELECT id, app_id, version, channel, status, rollout, released_at FROM releases WHERE {' AND '.join(clauses)} ORDER BY {sort_by} ASC, id ASC LIMIT ? OFFSET ?"
    params.extend([page_size, offset])
    rows = conn.execute(query, params).fetchall()
    keys = ['id', 'app_id', 'version', 'channel', 'status', 'rollout', 'released_at']
    return [dict(zip(keys, row)) for row in rows]

