from solution import apply_webhook
import hashlib
import hmac
import json
import pytest

def signed(secret, payload):
    digest = hmac.new(secret, payload.encode(), hashlib.sha256).hexdigest()
    return 'sha256=' + digest

def test_equal_revision_does_not_replace_existing_record():
    secret = b's'
    state = {'a': {'article_id': 'a', 'revision': 2, 'title': 'Keep', 'status': 'draft', 'tags': ['x'], 'updated_at': 1}}
    event = {'id': 'e', 'article_id': 'a', 'revision': 2, 'title': 'Replace', 'status': 'published', 'tags': [], 'updated_at': 999}
    payload = json.dumps({'events': [event]})
    apply_webhook(secret, payload, signed(secret, payload), state)
    assert state['a']['title'] == 'Keep'
    assert state['a']['updated_at'] == 1

def test_bad_signature_and_bad_format_do_not_mutate_state():
    secret = b'secret'
    state = {}
    payload = json.dumps({'events': []})
    with pytest.raises(ValueError, match='invalid signature'):
        apply_webhook(secret, payload, 'sha256=' + '0' * 64, state)
    assert state == {}
    with pytest.raises(ValueError, match='invalid signature'):
        apply_webhook(secret, payload, 'wrong', state)
    assert state == {}

def test_malformed_event_is_rejected_before_any_change():
    secret = b's'
    state = {'existing': {'article_id': 'existing', 'revision': 1, 'title': 'E', 'status': 'draft', 'tags': [], 'updated_at': 3}}
    events = [{'id': 'ok', 'article_id': 'new', 'revision': 1, 'title': 'N', 'status': 'draft', 'tags': [], 'updated_at': 4}, {'id': 'bad', 'article_id': 'x', 'revision': 0, 'title': 'X', 'status': 'draft', 'tags': [], 'updated_at': 5}]
    payload = json.dumps({'events': events})
    with pytest.raises(ValueError):
        apply_webhook(secret, payload, signed(secret, payload), state)
    assert list(state) == ['existing']

def test_validation_rejects_wrong_types_and_duplicate_tags():
    secret = b's'
    base = {'id': 'e', 'article_id': 'a', 'revision': 1, 'title': 'T', 'status': 'draft', 'tags': ['x', 'x'], 'updated_at': 1}
    for change in ({'tags': ['x', '']}, {'status': 'live'}, {'revision': True}, {'article_id': ''}, {'tags': 'x'}):
        event = dict(base)
        event.update(change)
        payload = json.dumps({'events': [event]})
        with pytest.raises(ValueError):
            apply_webhook(secret, payload, signed(secret, payload), {})

def test_returned_tags_are_copies_and_empty_payload_is_supported():
    secret = b's'
    payload = json.dumps({'events': []})
    state = {}
    result = apply_webhook(secret, payload, signed(secret, payload), state)
    assert result == []
    state['a'] = {'article_id': 'a', 'revision': 1, 'title': 'A', 'status': 'draft', 'tags': ['q'], 'updated_at': 1}
    result = apply_webhook(secret, payload, signed(secret, payload), state)
    result[0]['tags'].append('changed')
    assert state['a']['tags'] == ['q']

