import hashlib
import hmac
import json

def apply_webhook(secret: bytes, payload: str, signature: str, state: dict[str, dict]) -> list[dict]:
    if not isinstance(secret, bytes) or not isinstance(payload, str) or (not isinstance(signature, str)):
        raise ValueError('invalid signature')
    expected = hmac.new(secret, payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not signature.startswith('sha256=') or len(signature) != 71 or any((c not in '0123456789abcdef' for c in signature[7:])) or (not hmac.compare_digest(expected, signature[7:])):
        raise ValueError('invalid signature')
    try:
        document = json.loads(payload)
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(document, dict) or not isinstance(document.get('events'), list):
        raise ValueError('invalid payload')
    checked = []
    required = {'id', 'article_id', 'revision', 'title', 'status', 'tags', 'updated_at'}
    for event in document['events']:
        if not isinstance(event, dict) or set(event) != required:
            raise ValueError('invalid event')
        if any((not isinstance(event[k], str) or not event[k] for k in ('id', 'article_id', 'title'))):
            raise ValueError('invalid event')
        if isinstance(event['revision'], bool) or not isinstance(event['revision'], int) or event['revision'] <= 0:
            raise ValueError('invalid event')
        if isinstance(event['updated_at'], bool) or not isinstance(event['updated_at'], int) or event['updated_at'] < 0:
            raise ValueError('invalid event')
        if event['status'] not in {'draft', 'published', 'archived'}:
            raise ValueError('invalid event')
        if not isinstance(event['tags'], list) or any((not isinstance(x, str) or not x for x in event['tags'])):
            raise ValueError('invalid event')
        if len(set(event['tags'])) != len(event['tags']):
            raise ValueError('invalid event')
        checked.append({'article_id': event['article_id'], 'revision': event['revision'], 'title': event['title'], 'status': event['status'], 'tags': sorted(event['tags']), 'updated_at': event['updated_at']})
    for record in checked:
        old = state.get(record['article_id'])
        if old is None or record['revision'] > old['revision']:
            state[record['article_id']] = record
    return [dict(((k, list(v) if k == 'tags' else v) for k, v in record.items())) for record in sorted(state.values(), key=lambda x: (-x['updated_at'], x['article_id']))]

