from solution import verify_and_plan
import hashlib
import hmac
import json
import pytest

def signed(payload, secret='key'):
    return hmac.new(secret.encode(), payload.encode(), hashlib.sha256).hexdigest()

def make_payload(obj):
    return json.dumps(obj, separators=(',', ':'))

def test_balanced_portfolio_has_expected_order():
    payload = make_payload({'cash': 100, 'holdings': {'AAA': {'shares': 5, 'price': 100}}, 'targets': {'AAA': 1}})
    assert verify_and_plan(payload, signed(payload), 'key') == {'orders': [{'symbol': 'AAA', 'side': 'buy', 'shares': 1, 'price': 100}], 'cash_remaining': 0}

def test_order_ties_are_sorted_by_symbol_with_sells_first():
    obj = {'cash': 0, 'holdings': {'Z': {'shares': 10, 'price': 10}, 'A': {'shares': 0, 'price': 10}, 'M': {'shares': 0, 'price': 10}}, 'targets': {'Z': 0.4, 'A': 0.3, 'M': 0.3}}
    payload = make_payload(obj)
    result = verify_and_plan(payload, signed(payload), 'key')
    assert result['orders'] == [{'symbol': 'Z', 'side': 'sell', 'shares': 6, 'price': 10}, {'symbol': 'A', 'side': 'buy', 'shares': 3, 'price': 10}, {'symbol': 'M', 'side': 'buy', 'shares': 3, 'price': 10}]
    assert result['cash_remaining'] == 0

def test_exact_payload_bytes_are_signed_and_whitespace_is_preserved():
    payload = '{ "cash": 10, "holdings": {"A": {"shares": 1, "price": 10}}, "targets": {"A": 1} }'
    assert verify_and_plan(payload, signed(payload), 'key') == {'orders': [{'symbol': 'A', 'side': 'buy', 'shares': 1, 'price': 10}], 'cash_remaining': 0}

def test_bad_signatures_are_rejected():
    payload = make_payload({'cash': 0, 'holdings': {'A': {'shares': 0, 'price': 5}}, 'targets': {'A': 1}})
    for sig in ['0' * 64, 'f' * 63, 'g' * 64, signed(payload, 'other').upper()]:
        with pytest.raises(ValueError):
            verify_and_plan(payload, sig, 'key')

def test_invalid_json_and_schema_are_rejected():
    with pytest.raises(ValueError):
        verify_and_plan('not json', signed('not json'), 'key')
    base = {'cash': 0, 'holdings': {'A': {'shares': 0, 'price': 5}}, 'targets': {'A': 1}}
    cases = [{**base, 'extra': 1}, {**base, 'cash': -1}, {**base, 'holdings': {'A': {'shares': 0, 'price': 0}}}, {**base, 'targets': {'A': 0.9}}, {**base, 'targets': {'B': 1}}, {**base, 'cash': True}]
    for obj in cases:
        payload = make_payload(obj)
        with pytest.raises(ValueError):
            verify_and_plan(payload, signed(payload), 'key')

