import hashlib
import hmac
import json
import math

def verify_and_plan(payload: str, signature: str, secret: str) -> dict:
    if not all((isinstance(x, str) for x in (payload, signature, secret))):
        raise ValueError()
    if len(signature) != 64 or any((c not in '0123456789abcdef' for c in signature)):
        raise ValueError()
    expected = hmac.new(secret.encode(), payload.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError()
    try:
        data = json.loads(payload)
    except Exception as e:
        raise ValueError() from e
    if not isinstance(data, dict) or set(data) != {'cash', 'holdings', 'targets'}:
        raise ValueError()
    cash, holdings, targets = (data['cash'], data['holdings'], data['targets'])
    if isinstance(cash, bool) or not isinstance(cash, (int, float)) or (not math.isfinite(cash)) or (cash < 0):
        raise ValueError()
    if not isinstance(holdings, dict) or not holdings or (not isinstance(targets, dict)) or (set(holdings) != set(targets)):
        raise ValueError()
    total = float(cash)
    for s, h in holdings.items():
        if not isinstance(s, str) or not s or (not isinstance(h, dict)) or (set(h) != {'shares', 'price'}):
            raise ValueError()
        n, p = (h['shares'], h['price'])
        if isinstance(n, bool) or not isinstance(n, int) or n < 0 or isinstance(p, bool) or (not isinstance(p, (int, float))) or (not math.isfinite(p)) or (p <= 0):
            raise ValueError()
        total += n * p
    weights = 0
    for s, w in targets.items():
        if not isinstance(s, str) or not isinstance(w, (int, float)) or isinstance(w, bool) or (not math.isfinite(w)) or (w < 0):
            raise ValueError()
        weights += w
    if abs(weights - 1) > 1e-09:
        raise ValueError()
    orders = []
    remaining = float(cash)
    for s, h in holdings.items():
        d = math.floor(total * targets[s] / h['price']) - h['shares']
        if d:
            orders.append({'symbol': s, 'side': 'buy' if d > 0 else 'sell', 'shares': abs(d), 'price': h['price']})
            remaining -= d * h['price']
    orders.sort(key=lambda x: (x['side'] != 'sell', x['symbol']))
    return {'orders': orders, 'cash_remaining': round(remaining, 2)}

