from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from datetime import datetime
import xml.etree.ElementTree as ET

def summarize_meter_readings(xml_text: str, page: int=1, page_size: int=50) -> list[dict[str, object]]:
    if type(page) is not int or type(page_size) is not int or page <= 0 or (page_size <= 0):
        raise ValueError('invalid pagination')
    try:
        root = ET.fromstring(xml_text)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'readings':
        raise ValueError('invalid root')
    totals: dict[tuple[str, str], Decimal] = {}
    for item in root:
        if item.tag != 'reading':
            raise ValueError('invalid child')
        meter = item.get('meter')
        timestamp = item.get('timestamp')
        value = item.get('kwh')
        if not meter or not timestamp or value is None:
            raise ValueError('missing attribute')
        try:
            parsed = datetime.fromisoformat(timestamp)
            if 'T' not in timestamp and 't' not in timestamp:
                raise ValueError
            amount = Decimal(value)
        except (ValueError, InvalidOperation):
            raise ValueError('invalid reading')
        if amount < 0:
            raise ValueError('invalid reading')
        key = (parsed.date().isoformat(), meter)
        totals[key] = totals.get(key, Decimal('0')) + amount
    result = []
    for (date, meter), amount in sorted(totals.items()):
        rounded = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        result.append({'meter_id': meter, 'date': date, 'kwh': float(rounded)})
    start = (page - 1) * page_size
    return result[start:start + page_size]

