import csv
import datetime
import io
import os
import tempfile
_FIELDS = ['mark', 'jurisdiction', 'class', 'status', 'date', 'owner']
_STATUSES = {'new', 'renewal', 'opposition', 'expired'}
_OUT = ['mark', 'jurisdiction', 'class', 'total', 'active', 'latest_date', 'owners']

def _date(value):
    try:
        return datetime.date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def parse_notifications(text: str) -> list[dict]:
    if not text.strip():
        return []
    try:
        rows = list(csv.reader(io.StringIO(text)))
    except Exception as exc:
        raise ValueError('invalid csv') from exc
    rows = [r for r in rows if any((x.strip() for x in r))]
    if not rows or rows[0] != _FIELDS:
        if not rows:
            return []
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if len(row) != 6:
            raise ValueError('invalid row')
        row = [x.strip() for x in row]
        if row[3] not in _STATUSES:
            raise ValueError('invalid status')
        _date(row[4])
        result.append(dict(zip(_FIELDS, row)))
    return result

def summarize_notifications(records: list[dict], as_of: str) -> list[dict]:
    cutoff = _date(as_of)
    groups = {}
    for r in records:
        if any((k not in r for k in _FIELDS)):
            raise ValueError('missing field')
        if r['status'] not in _STATUSES:
            raise ValueError('invalid status')
        date = _date(r['date'])
        if not r['class'] or not r['class'].isdigit():
            raise ValueError('invalid class')
        if date <= cutoff:
            groups.setdefault((r['mark'], r['jurisdiction'], r['class']), []).append(r)
    out = []
    for (mark, jurisdiction, cls), rows in groups.items():
        owners = sorted({r['owner'] for r in rows}, key=lambda x: (x.lower(), x))
        out.append({'mark': mark, 'jurisdiction': jurisdiction, 'class': cls, 'total': len(rows), 'active': sum((r['status'] != 'expired' for r in rows)), 'latest_date': max((r['date'] for r in rows)), 'owners': ','.join(owners)})
    out.sort(key=lambda r: (r['mark'].lower(), r['jurisdiction'].lower(), int(r['class']), r['mark'], r['jurisdiction'], r['class']))
    return out

def export_digest(records: list[dict], destination: str, as_of: str) -> int:
    summary = summarize_notifications(records, as_of)
    fd, temporary = tempfile.mkstemp(dir=os.path.dirname(os.path.abspath(destination)), prefix='.digest-')
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as f:
            writer = csv.DictWriter(f, fieldnames=_OUT)
            writer.writeheader()
            writer.writerows(summary)
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return len(summary)

