import pytest


def make_order():
    return {
        "ord-1": {
            "order_id": "ord-1",
            "tenant_id": "tenant-a",
            "restaurant_id": "user-restaurant",
            "status": "ready",
            "courier_id": None,
        }
    }


def test_dispatcher_can_dispatch_ready_order():
    orders = make_order()
    requester = {"id": "dispatcher-1", "role": "dispatcher", "tenant_id": "tenant-a"}
    result = dispatch_order("ord-1", requester, orders, "courier-7")
    assert result == {
        "order_id": "ord-1",
        "tenant_id": "tenant-a",
        "restaurant_id": "user-restaurant",
        "status": "assigned",
        "courier_id": "courier-7",
        "dispatched_by": "dispatcher-1",
    }


def test_restaurant_owner_can_dispatch_own_order():
    orders = make_order()
    requester = {"id": "user-restaurant", "role": "restaurant", "tenant_id": "tenant-a"}
    result = dispatch_order("ord-1", requester, orders, "courier-2")
    assert result["status"] == "assigned"
    assert result["courier_id"] == "courier-2"
    assert result["dispatched_by"] == "user-restaurant"


def test_dispatch_mutates_original_order():
    orders = make_order()
    requester = {"id": "manager-1", "role": "manager", "tenant_id": "tenant-a"}
    returned = dispatch_order("ord-1", requester, orders, "courier-3")
    assert orders["ord-1"]["status"] == "assigned"
    assert orders["ord-1"]["courier_id"] == "courier-3"
    assert orders["ord-1"]["dispatched_by"] == "manager-1"
    assert returned is not orders["ord-1"]


def test_unknown_order_raises_key_error():
    orders = make_order()
    requester = {"id": "dispatcher-1", "role": "dispatcher", "tenant_id": "tenant-a"}
    with pytest.raises(KeyError):
        dispatch_order("missing", requester, orders, "courier-1")


def test_non_ready_order_raises_value_error():
    orders = make_order()
    orders["ord-1"]["status"] = "assigned"
    requester = {"id": "dispatcher-1", "role": "dispatcher", "tenant_id": "tenant-a"}
    with pytest.raises(ValueError):
        dispatch_order("ord-1", requester, orders, "courier-1")


