import csv
import io
from datetime import date

def _day(value):
    try:
        return date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def parse_membership_feed(text: str) -> list[dict]:
    fields = ['membership_id', 'creator_id', 'member_id', 'tenant_id', 'started', 'ended', 'status', 'monthly_cents']
    if not text:
        return []
    reader = csv.DictReader(io.StringIO(text))
    if reader.fieldnames != fields:
        raise ValueError('invalid header')
    result = []
    seen = set()
    for row in reader:
        if any((row.get(k) is None for k in fields)):
            raise ValueError('invalid row')
        if row['membership_id'] in seen:
            raise ValueError('duplicate membership')
        seen.add(row['membership_id'])
        _day(row['started'])
        if row['ended']:
            _day(row['ended'])
        if row['status'] not in ('active', 'cancelled'):
            raise ValueError('invalid status')
        try:
            cents = int(row['monthly_cents'])
        except ValueError:
            raise ValueError('invalid price')
        if cents <= 0:
            raise ValueError('invalid price')
        result.append({**row, 'ended': row['ended'] or None, 'monthly_cents': cents})
    return result

def creator_summary(requester: dict, memberships: list[dict], creator_id: str, from_date: str, to_date: str) -> dict:
    start, end = (_day(from_date), _day(to_date))
    if start > end:
        raise ValueError('reversed range')
    chosen = []
    for m in memberships:
        if m['creator_id'] != creator_id or m['tenant_id'] != requester['tenant_id']:
            continue
        if _day(m['started']) <= end and (m['ended'] is None or _day(m['ended']) >= start):
            chosen.append(m)
    ids = sorted({m['member_id'] for m in chosen})
    return {'creator_id': creator_id, 'from_date': from_date, 'to_date': to_date, 'member_count': len(ids), 'active_count': sum((m['status'] == 'active' for m in chosen)), 'cancelled_count': sum((m['status'] == 'cancelled' for m in chosen)), 'monthly_cents': sum((m['monthly_cents'] for m in chosen)), 'member_ids': ids}

def change_membership_status(requester: dict, memberships: list[dict], membership_id: str, new_status: str) -> dict:
    if new_status not in ('active', 'cancelled'):
        raise ValueError('invalid status')
    for m in memberships:
        if m['membership_id'] == membership_id:
            allowed = m['tenant_id'] == requester['tenant_id'] and (m['creator_id'] == requester.get('creator_id') or 'manager' in requester.get('roles', []))
            if not allowed:
                raise PermissionError('not permitted')
            m['status'] = new_status
            return m
    raise KeyError(membership_id)

