import hashlib
import hmac
import json

def summarize_webhook(body: bytes, signature: str, secret: str, page: int=1, page_size: int=2) -> dict:
    if not isinstance(signature, str) or not signature.startswith('sha256=') or len(signature) != 71:
        return None
    expected = 'sha256=' + hmac.new(secret.encode('utf-8'), body, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        return None
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    try:
        value = json.loads(body.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid body') from exc
    if not isinstance(value, dict) or not isinstance(value.get('events'), list):
        raise ValueError('invalid payload')
    grouped = {}
    for event in value['events']:
        if not isinstance(event, dict):
            raise ValueError('invalid event')
        category = event.get('category')
        amount = event.get('amount_cents')
        status = event.get('status')
        if not isinstance(category, str) or not category or (not isinstance(amount, int)) or isinstance(amount, bool) or (amount < 0) or (not isinstance(status, str)):
            raise ValueError('invalid event')
        if status in ('paid', 'refunded'):
            item = grouped.setdefault(category, [0, 0])
            item[0] += amount if status == 'paid' else -amount
            item[1] += 1
    rows = [{'category': key, 'total_cents': data[0], 'events': data[1]} for key, data in grouped.items()]
    rows.sort(key=lambda row: (-row['total_cents'], row['category']))
    start = (page - 1) * page_size
    return {'page': page, 'page_size': page_size, 'total_categories': len(rows), 'categories': rows[start:start + page_size]}

