            raise ValueError('payment exceeds balance')
        payment = {'payment_id': self._next_payment, 'amount': cents, 'idempotency_key': idempotency_key}
        self._next_payment += 1
        item['payments'].append(payment)
        if cents == remaining:
            item['status'] = 'paid'
        return self._receipt(item, payment)

