        paid = sum((p['amount'] for p in item['payments']))
        return {'payment_id': payment['payment_id'], 'citation_id': item['citation_id'], 'plate': item['plate'], 'amount': payment['amount'], 'remaining': item['amount_due'] - paid, 'status': item['status']}

    def balance(self, citation_id: str) -> int:
        item = self._citations[citation_id]
        return item['amount_due'] - sum((p['amount'] for p in item['payments']))

