import math
import subprocess

def read_sorted_readings(path: str) -> list[tuple[str, int, float]]:
    result = subprocess.run(['sort', '-t,', '-k1,1', '-k2,2n', path], capture_output=True, text=True, env={'PATH': '/usr/bin:/bin', 'LC_ALL': 'C'})
    if result.returncode != 0:
        raise FileNotFoundError(path)
    readings = []
    for number, line in enumerate(result.stdout.splitlines(), 1):
        if not line.strip():
            continue
        fields = line.split(',')
        if len(fields) != 3 or not fields[0]:
            raise ValueError(f'invalid line {number}')
        try:
            timestamp = int(fields[1])
            pressure = float(fields[2])
        except ValueError as exc:
            raise ValueError(f'invalid line {number}') from exc
        if not math.isfinite(pressure):
            raise ValueError(f'invalid line {number}')
        readings.append((fields[0], timestamp, pressure))
    return readings

def summarize_pressure(path: str, window: int=3, alert: float=100.0) -> dict[str, dict[str, int | float]]:
    if window < 1 or not math.isfinite(alert):
        raise ValueError('invalid options')
    readings = read_sorted_readings(path)
    groups = {}
    for station, timestamp, pressure in readings:
        groups.setdefault(station, []).append((timestamp, pressure))
    output = {}
    for station, values in groups.items():
        values.sort(key=lambda item: item[0])
        pressures = [item[1] for item in values]
        rises = [pressures[i] - pressures[i - 1] for i in range(1, len(pressures))]
        alerts = sum((all((value >= alert for value in pressures[i:i + window])) for i in range(max(0, len(pressures) - window + 1))))
        output[station] = {'count': len(pressures), 'minimum': min(pressures), 'maximum': max(pressures), 'average': round(sum(pressures) / len(pressures), 2), 'alert_windows': alerts, 'maximum_rise': round(max([rise for rise in rises if rise > 0] or [0.0]), 2)}
    return output

