import ast
import operator

def evaluate_expression(expression: str, variables: dict[str, object]) -> object:
    tree = ast.parse(expression, mode='eval')
    values = {'True': True, 'False': False, 'None': None}
    values.update(variables)
    binops = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
    cmps = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}

    def visit(n):
        if isinstance(n, ast.Constant) and (n.value is None or isinstance(n.value, (int, float, bool))):
            return n.value
        if isinstance(n, ast.Name):
            if n.id not in values:
                raise NameError(n.id)
            return values[n.id]
        if isinstance(n, ast.BinOp) and type(n.op) in binops:
            return binops[type(n.op)](visit(n.left), visit(n.right))
        if isinstance(n, ast.UnaryOp) and isinstance(n.op, (ast.UAdd, ast.USub, ast.Not)):
            v = visit(n.operand)
            return +v if isinstance(n.op, ast.UAdd) else -v if isinstance(n.op, ast.USub) else not v
        if isinstance(n, ast.BoolOp) and isinstance(n.op, (ast.And, ast.Or)):
            result = visit(n.values[0])
            for child in n.values[1:]:
                if isinstance(n.op, ast.And) and (not result) or (isinstance(n.op, ast.Or) and result):
                    return result
                result = visit(child)
            return result
        if isinstance(n, ast.Compare):
            left = visit(n.left)
            for op, right_node in zip(n.ops, n.comparators):
                right = visit(right_node)
                if type(op) not in cmps:
                    raise ValueError()
                if not cmps[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and (n.func.id in {'min', 'max', 'round'}) and (not n.keywords):
            return {'min': min, 'max': max, 'round': round}[n.func.id](*(visit(x) for x in n.args))
        raise ValueError()
    return visit(tree.body)

def build_export(records, rule, metric, limit=None):
    if limit is not None and (type(limit) is not int or limit < 0):
        raise ValueError()
    seen = set()
    output = []
    for r in records:
        if set(r) != {'id', 'name', 'region', 'active', 'orders'} or type(r['id']) is not int or r['id'] < 0 or (not isinstance(r['name'], str)) or (not isinstance(r['region'], str)) or (type(r['active']) is not bool) or (r['id'] in seen):
            raise ValueError()
        seen.add(r['id'])
        total = refunds = 0
        for o in r['orders']:
            if set(o) != {'amount', 'status'} or type(o['amount']) not in (int, float) or type(o['amount']) is bool or (o['status'] not in ('paid', 'refunded')):
                raise ValueError()
            if o['status'] == 'paid':
                total += o['amount']
            else:
                refunds += o['amount']
        v = {'total': total, 'refunds': refunds, 'count': len(r['orders']), 'active': r['active']}
        if type(evaluate_expression(rule, v)) is not bool:
            raise ValueError()
        if not evaluate_expression(rule, v):
            continue
        m = evaluate_expression(metric, v)
        if type(m) not in (int, float):
            raise ValueError()
        output.append({'id': r['id'], 'name': r['name'], 'region': r['region'], 'total': total, 'refunds': refunds, 'count': len(r['orders']), 'metric': m})
    output.sort(key=lambda x: (-x['metric'], x['id']))
    return output if limit is None else output[:limit]

