    root = _tree(xml_text)
    if root.tag != 'manifest' or not len(root):
        raise ValueError('invalid manifest')
    records = []
    for shipment in root:
        if shipment.tag != 'shipment':
            raise ValueError('invalid shipment')
        sid = shipment.get('id')
        when = shipment.get('date')
        location = shipment.get('location')
        if not sid or not when or (not location):
            raise ValueError('missing shipment attribute')
        if len(when) != 10 or when[4] != '-' or when[7] != '-':
            raise ValueError('invalid date')
        try:
            date.fromisoformat(when)
        except ValueError as exc:
            raise ValueError('invalid date') from exc
        if not len(shipment):
            raise ValueError('shipment has no items')
        for item in shipment:
            if item.tag != 'item':
                raise ValueError('invalid item')
            sku = item.get('sku')
            quantity = item.get('quantity')
            if not sku or quantity is None or (not quantity.isdigit()) or (int(quantity) <= 0):
                raise ValueError('invalid item')
            description = ' '.join(''.join(item.itertext()).split())
            records.append({'shipment': sid, 'date': when, 'location': location, 'sku': sku, 'quantity': int(quantity), 'description': description})
