    if start_date > end_date:
        raise ValueError('start must not be later than end')
    groups = {}
    for donation in donations:
        try:
            donor = donation['donor']
            raw_date = donation['date']
            district = donation['district']
            raw_amount = donation['amount']
        except (KeyError, TypeError) as exc:
            raise ValueError('invalid donation') from exc
        if not isinstance(donor, str) or not donor or (not isinstance(district, str)) or (not district):
            raise ValueError('invalid donation')
        if not isinstance(raw_date, str) or not date_re.fullmatch(raw_date):
            raise ValueError('invalid donation date')
        try:
            donation_date = datetime.date.fromisoformat(raw_date)
        except ValueError as exc:
            raise ValueError('invalid donation date') from exc
        try:
            amount = Decimal(str(raw_amount))
        except (InvalidOperation, ValueError) as exc:
            raise ValueError('invalid amount') from exc
        if not amount.is_finite() or amount < 0 or amount != amount.quantize(Decimal('0.01')):
            raise ValueError('invalid amount')
        if start_date <= donation_date <= end_date:
            entry = groups.setdefault(district, [0, 0])
            entry[0] += 1
            entry[1] += int(amount * 100)
    rows = [{'district': district, 'donation_count': values[0], 'total_cents': values[1]} for district, values in groups.items()]
    rows.sort(key=lambda row: (-row['total_cents'], row['district']))
    result = {'start': start, 'end': end, 'rows': rows}
    key = os.environ.get('CAMPAIGN_SIGNING_KEY')
    if not key:
        raise RuntimeError('CAMPAIGN_SIGNING_KEY is required')
    payload = json.dumps(result, separators=(',', ':'), sort_keys=True).encode()
    result['signature'] = hmac.new(key.encode(), payload, hashlib.sha256).hexdigest()
    return result

