import csv
import os
from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from pathlib import Path

def write_invoice(entries: list[dict], base_dir: str, relative_name: str) -> str:
    if not isinstance(relative_name, str) or not relative_name:
        raise ValueError('invalid output name')
    base = Path(base_dir).resolve()
    target = (base / relative_name).resolve()
    try:
        target.relative_to(base)
    except ValueError:
        raise ValueError('invalid output name')
    rows = []
    total = Decimal('0')
    for entry in entries:
        required = ('matter', 'date', 'description', 'hours', 'rate', 'billable')
        if not isinstance(entry, dict) or any((k not in entry for k in required)):
            raise ValueError('invalid entry')
        if not isinstance(entry['matter'], str) or not entry['matter']:
            raise ValueError('invalid entry')
        if not isinstance(entry['description'], str) or not isinstance(entry['billable'], bool):
            raise ValueError('invalid entry')
        try:
            parsed_date = date.fromisoformat(entry['date'])
            hours = Decimal(str(entry['hours']))
            rate = Decimal(str(entry['rate']))
        except (ValueError, TypeError, InvalidOperation):
            raise ValueError('invalid entry')
        if parsed_date.isoformat() != entry['date'] or hours <= 0 or rate < 0:
            raise ValueError('invalid entry')
        if entry['billable']:
            amount = (hours * rate).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
            rows.append((entry['matter'], entry['date'], entry['description'], hours, rate, amount))
            total += amount
    rows.sort(key=lambda row: (row[0], row[1], row[2]))
    target.parent.mkdir(parents=True, exist_ok=True)
    with target.open('w', encoding='utf-8', newline='') as handle:
        writer = csv.writer(handle)
        writer.writerow(['matter', 'date', 'description', 'hours', 'rate', 'amount'])
