import os
import tempfile

def read_visits(text: str) -> list[dict]:
    rows = list(csv.reader((line for line in text.splitlines() if line.strip())))
    if not rows or rows[0] != ['visitor', 'company', 'arrival', 'departure']:
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if len(row) != 4:
            raise ValueError('invalid row')
        visitor, company, arrival, departure = (x.strip() for x in row)
        if not visitor or not company:
            raise ValueError('blank field')
        try:
            a = datetime.datetime.fromisoformat(arrival)
            b = datetime.datetime.fromisoformat(departure)
        except Exception as e:
            raise ValueError('invalid timestamp') from e
        if a.tzinfo is not None or b.tzinfo is not None or b < a:
            raise ValueError('invalid interval')
        result.append({'visitor': visitor, 'company': company, 'arrival': a, 'departure': b})
    return result

def daily_report(records: list[dict], day: str) -> list[tuple[str, int, int]]:
    try:
        target = datetime.date.fromisoformat(day)
    except Exception as e:
        raise ValueError('invalid day') from e
    totals = {}
    for record in records:
        if record['arrival'].date() != target:
            continue
        minutes = (record['departure'] - record['arrival']).seconds // 60
        company = record['company']
        count, total = totals.get(company, (0, 0))
        totals[company] = (count + 1, total + minutes)
    return sorted(((c, n, m) for c, (n, m) in totals.items()), key=lambda x: (-x[1], -x[2], x[0]))

def export_report(records: list[dict], path: str, day: str) -> int:
    report = daily_report(records, day)
    directory = os.path.dirname(os.path.abspath(path))
    fd, temporary = tempfile.mkstemp(prefix='.report-', dir=directory, text=True)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as f:
            writer = csv.writer(f, lineterminator='\n')
            writer.writerow(['company', 'visit_count', 'total_minutes'])
            writer.writerows(report)
        os.replace(temporary, path)
    except Exception:
        try:
            os.unlink(temporary)
        except OSError:
            pass
        raise
    return len(report)

