def parse_flags(text: str) -> dict:
    try:
        value = json.loads(text)
    except Exception as exc:
        raise ValueError('invalid configuration') from exc
    if not isinstance(value, dict) or not isinstance(value.get('flags'), dict):
        raise ValueError('invalid configuration')
    flags = {}
    for name, item in value['flags'].items():
        if not isinstance(name, str) or not isinstance(item, dict) or (not isinstance(item.get('default'), bool)):
            raise ValueError('invalid flag')
        rules = item.get('rules', [])
        percentage = item.get('percentage', None)
        if not isinstance(rules, list):
            raise ValueError('invalid rules')
        if percentage is not None and (isinstance(percentage, bool) or not isinstance(percentage, int) or (not 0 <= percentage <= 100)):
            raise ValueError('invalid percentage')
        normalized = []
        for rule in rules:
            if not isinstance(rule, dict) or not isinstance(rule.get('enabled'), bool):
                raise ValueError('invalid rule')
            when = rule.get('when', {})
            if not isinstance(when, dict):
                raise ValueError('invalid condition')
            for key, val in when.items():
                if not isinstance(key, str) or not (val is None or isinstance(val, (str, int, bool))) or isinstance(val, float):
                    raise ValueError('invalid condition')
            normalized.append({'when': when, 'enabled': rule['enabled']})
        flags[name] = {'default': item['default'], 'rules': normalized, 'percentage': percentage}
    return {'flags': flags}

def evaluate_flag(config: dict, name: str, attributes: dict) -> bool:
    if name not in config['flags']:
        raise KeyError(name)
    if not isinstance(attributes, dict):
        raise ValueError('attributes must be a dictionary')
    flag = config['flags'][name]
    for rule in flag['rules']:
        if all((key in attributes and attributes[key] == val for key, val in rule['when'].items())):
            return rule['enabled']
    if flag['percentage'] is not None and 'user_id' in attributes:
        digest = hashlib.sha256((name + ':' + str(attributes['user_id'])).encode()).hexdigest()
        if int(digest, 16) % 100 < flag['percentage']:
            return True
    return flag['default']

def export_flags(config: dict, destination: str) -> int:
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent, prefix='.flags-')
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as stream:
            writer = csv.writer(stream, lineterminator='\n')
            writer.writerow(['name', 'default', 'percentage', 'rules'])
            for name in sorted(config['flags']):
                flag = config['flags'][name]
                rules = json.dumps(flag['rules'], separators=(',', ':'), ensure_ascii=False)
                writer.writerow([name, str(flag['default']).lower(), '' if flag['percentage'] is None else flag['percentage'], rules])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return len(config['flags'])

