from solution import export_appointments

import csv
import os
import tempfile


def sample_appointments():
    return [
        {"id": 3, "pet": "Milo", "owner": "Ana", "veterinarian": "Dr Lee", "date": "2025-04-03", "time": "09:00", "fee": 45},
        {"id": 1, "pet": "Bella", "owner": "Jon, Jr", "veterinarian": "Dr Smith", "date": "2025-04-01", "time": "10:30", "fee": 60.5},
        {"id": 2, "pet": "Rex", "owner": "Sam", "veterinarian": "Dr Smith", "date": "2025-04-01", "time": "10:30", "fee": 25.125},
        {"id": 4, "pet": "Luna", "owner": "Kai", "veterinarian": "Dr Lee", "date": "2025-04-02", "time": "08:15", "fee": 0},
    ]


def read_rows(path):
    with open(path, newline="", encoding="utf-8") as handle:
        return list(csv.reader(handle))


def test_sorted_csv_and_summary():
    with tempfile.TemporaryDirectory() as directory:
        path = os.path.join(directory, "report.csv")
        result = export_appointments(sample_appointments(), path)
        assert result == {"total": 4, "page": 1, "pages": 1, "count": 4, "total_fee": 130.62, "appointment_ids": [1, 2, 4, 3]}
        assert read_rows(path) == [
            ["id", "pet", "owner", "veterinarian", "date", "time", "fee"],
            ["1", "Bella", "Jon, Jr", "Dr Smith", "2025-04-01", "10:30", "60.50"],
            ["2", "Rex", "Sam", "Dr Smith", "2025-04-01", "10:30", "25.12"],
            ["4", "Luna", "Kai", "Dr Lee", "2025-04-02", "08:15", "0.00"],
            ["3", "Milo", "Ana", "Dr Lee", "2025-04-03", "09:00", "45.00"],
        ]


def test_filter_and_pagination():
    with tempfile.TemporaryDirectory() as directory:
        path = os.path.join(directory, "report.csv")
        result = export_appointments(sample_appointments(), path, "Dr Smith", 2, 1)
        assert result == {"total": 2, "page": 2, "pages": 2, "count": 1, "total_fee": 85.62, "appointment_ids": [2]}
        assert read_rows(path)[1][0] == "2"


def test_empty_filter_creates_header():
    with tempfile.TemporaryDirectory() as directory:
        path = os.path.join(directory, "report.csv")
        result = export_appointments(sample_appointments(), path, "Dr Nobody")
        assert result == {"total": 0, "page": 1, "pages": 0, "count": 0, "total_fee": 0.0, "appointment_ids": []}
        assert read_rows(path) == [["id", "pet", "owner", "veterinarian", "date", "time", "fee"]]


def test_existing_file_is_replaced():
    with tempfile.TemporaryDirectory() as directory:
        path = os.path.join(directory, "report.csv")
        with open(path, "w", encoding="utf-8") as handle:
            handle.write("old content")
        export_appointments(sample_appointments()[:1], path)
        assert "old content" not in open(path, encoding="utf-8").read()
        assert read_rows(path)[1][0] == "3"


def test_invalid_pagination_and_page_raise():
    with tempfile.TemporaryDirectory() as directory:
        path = os.path.join(directory, "report.csv")
        for page, size in [(0, 1), (1, 0), (3, 2)]:
            try:
                export_appointments(sample_appointments(), path, page=page, page_size=size)
            except ValueError:
                pass
            else:
                assert False


def test_invalid_records_raise_value_error():
    with tempfile.TemporaryDirectory() as directory:
        path = os.path.join(directory, "report.csv")
        bad = dict(sample_appointments()[0])
        del bad["date"]
        try:
            export_appointments([bad], path)
        except ValueError:
            pass
        else:
            assert False
        bad = dict(sample_appointments()[0])
        bad["fee"] = -1
        try:
            export_appointments([bad], path)
        except ValueError:
            pass
        else:
            assert False


def test_special_csv_values_are_quoted_and_ids_are_string_sorted_on_ties():
    appointments = [
        {"id": "10", "pet": "A\nB", "owner": "Owner", "veterinarian": "Dr X", "date": "2025-01-01", "time": "09:00", "fee": 1},
        {"id": "2", "pet": "Cat", "owner": "Owner", "veterinarian": "Dr X", "date": "2025-01-01", "time": "09:00", "fee": 2},
