import secrets

def generate_invite_code(length: int=8) -> str:
    if not isinstance(length, int) or isinstance(length, bool):
        raise TypeError('length must be an integer')
    if length < 6 or length > 32:
        raise ValueError('length out of range')
    alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
    return ''.join((secrets.choice(alphabet) for _ in range(length)))

def summarize_audits(records: list[dict], page: int=1, page_size: int=20, min_intensity: float | None=None) -> dict:
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    if not isinstance(page, int) or isinstance(page, bool) or (not isinstance(page_size, int)) or isinstance(page_size, bool):
        raise TypeError('pagination values must be integers')
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    if min_intensity is not None and (not isinstance(min_intensity, numbers.Real) or isinstance(min_intensity, bool)):
        raise TypeError('min_intensity must be numeric')
    if min_intensity is not None and min_intensity < 0:
        raise ValueError('min_intensity must be non-negative')
    selected = []
    for record in records:
        if not isinstance(record, dict):
            raise TypeError('each record must be a dictionary')
        if 'building' not in record or 'annual_kwh' not in record or 'area_m2' not in record:
            raise ValueError('missing record field')
        building = record['building']
        annual_kwh = record['annual_kwh']
        area_m2 = record['area_m2']
        if not isinstance(building, str) or not isinstance(annual_kwh, numbers.Real) or isinstance(annual_kwh, bool) or (not isinstance(area_m2, numbers.Real)) or isinstance(area_m2, bool):
            raise TypeError('invalid record field type')
        if not building or annual_kwh < 0 or area_m2 <= 0:
            raise ValueError('invalid record field value')
        intensity = annual_kwh / area_m2
        if min_intensity is None or intensity >= min_intensity:
            selected.append((intensity, building, annual_kwh, area_m2))
    selected.sort(key=lambda row: (-row[0], row[1]))
    total_area = sum((row[3] for row in selected))
    total_kwh = sum((row[2] for row in selected))
    start = (page - 1) * page_size
    items = [{'building': row[1], 'annual_kwh': row[2], 'area_m2': row[3], 'intensity': round(row[0], 2)} for row in selected[start:start + page_size]]
    return {'total': len(selected), 'page': page, 'page_size': page_size, 'average_intensity': round(total_kwh / total_area, 2) if selected else 0.0, 'items': items}

