import hashlib
import hmac
import os

def hash_retention_pin(pin: str) -> str:
    if not isinstance(pin, str):
        raise TypeError('pin must be a string')
    if not pin:
        raise ValueError('pin must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def verify_retention_pin(pin: str, stored: str) -> bool:
    if not isinstance(pin, str) or not isinstance(stored, str):
        return False
    try:
        salt_text, digest_text = stored.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def list_retained_backups(backups: list[dict], today: int, keep_days: int, page: int=1, page_size: int=10) -> dict:
    if not isinstance(backups, list):
        raise TypeError('backups must be a list')
    if isinstance(today, bool) or not isinstance(today, int):
        raise ValueError('today must be an integer')
    if isinstance(keep_days, bool) or not isinstance(keep_days, int) or keep_days < 1:
        raise ValueError('keep_days must be positive')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('page must be positive')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('page_size must be positive')
    cutoff = today - keep_days + 1
    retained = []
    for backup in backups:
        if not isinstance(backup, dict) or set(backup) != {'id', 'created_day', 'size_mb'}:
            raise ValueError('invalid backup')
        if not isinstance(backup['id'], str) or not backup['id']:
            raise ValueError('invalid backup')
        if isinstance(backup['created_day'], bool) or not isinstance(backup['created_day'], int):
            raise ValueError('invalid backup')
        if isinstance(backup['size_mb'], bool) or not isinstance(backup['size_mb'], int) or backup['size_mb'] < 0:
            raise ValueError('invalid backup')
        if backup['created_day'] >= cutoff:
            retained.append(backup)
    retained.sort(key=lambda item: (-item['created_day'], item['id']))
    start = (page - 1) * page_size
    return {'total_count': len(retained), 'total_size_mb': sum((x['size_mb'] for x in retained)), 'backups': retained[start:start + page_size]}

