import hashlib
import hmac
import json
import pytest


def make_payload(events):
    return json.dumps({"events": events}, separators=(",", ":")).encode()


def signature(payload, secret=b"camp-secret"):
    return "sha256=" + hmac.new(secret, payload, hashlib.sha256).hexdigest()


def test_reservations_and_cancellations_are_applied_in_order():
    events = [
        {"id": "a", "action": "reserve", "site": "pine", "nights": 2},
        {"id": "b", "action": "cancel", "site": "pine", "nights": 1},
        {"id": "c", "action": "reserve", "site": "lake", "nights": 1},
    ]
    payload = make_payload(events)
    inventory = {"pine": 5, "lake": 3, "ridge": 0}
    seen = set()
    result = process_webhook(payload, signature(payload), b"camp-secret", inventory, seen)
    assert result == {"lake": 2, "pine": 4, "ridge": 0}
    assert inventory == {"pine": 4, "lake": 2, "ridge": 0}
    assert seen == {"a", "b", "c"}


def test_duplicate_ids_are_ignored_even_within_one_batch():
    events = [
        {"id": "same", "action": "reserve", "site": "oak", "nights": 2},
        {"id": "same", "action": "cancel", "site": "oak", "nights": 9},
        {"id": "old", "action": "reserve", "site": "oak", "nights": 4},
    ]
    payload = make_payload(events)
    inventory = {"oak": 7}
    seen = {"old"}
    assert process_webhook(payload, signature(payload), b"camp-secret", inventory, seen) == {"oak": 5}
    assert inventory == {"oak": 5}
    assert seen == {"old", "same"}


def test_insufficient_availability_is_atomic():
    events = [
        {"id": "ok", "action": "reserve", "site": "oak", "nights": 2},
        {"id": "too-much", "action": "reserve", "site": "oak", "nights": 5},
    ]
    inventory = {"oak": 3}
    seen = {"already"}
    with pytest.raises(ValueError, match="^insufficient availability$"):
        process_webhook(make_payload(events), signature(make_payload(events)), b"camp-secret", inventory, seen)
    assert inventory == {"oak": 3}
    assert seen == {"already"}


def test_bad_signature_does_not_parse_or_modify_state():
    inventory = {"oak": 4}
    seen = set()
    with pytest.raises(ValueError, match="^invalid signature$"):
        process_webhook(b"not-json", "sha256=" + "0" * 64, b"camp-secret", inventory, seen)
    assert inventory == {"oak": 4}
    assert seen == set()


def test_signature_format_and_secret_are_checked():
    payload = make_payload([])
    for supplied in ["", "sha256=", "sha256=" + "A" * 64, "md5=" + "0" * 32, "sha256=" + "0" * 63]:
        with pytest.raises(ValueError, match="^invalid signature$"):
            process_webhook(payload, supplied, b"camp-secret", {}, set())
    with pytest.raises(ValueError, match="^invalid signature$"):
        process_webhook(payload, signature(payload, b"other-secret"), b"camp-secret", {}, set())


def test_payload_schema_errors_are_atomic():
    inventory = {"oak": 3}
    seen = set()
    bad_payloads = [
        b"not json",
        json.dumps({"events": {}}).encode(),
        json.dumps({"events": [{"id": "x", "action": "reserve", "site": "oak", "nights": True}]}).encode(),
        json.dumps({"events": [{"id": "x", "action": "reserve", "site": "oak", "nights": 0}]}).encode(),
        json.dumps({"events": [{"id": "x", "action": "reserve", "site": "oak", "nights": 1, "extra": 2}]}).encode(),
    ]
    for payload in bad_payloads:
        with pytest.raises(ValueError, match="^invalid payload$"):
            process_webhook(payload, signature(payload), b"camp-secret", inventory, seen)
        assert inventory == {"oak": 3}
        assert seen == set()


def test_empty_batch_and_result_ordering():
    payload = make_payload([])
    inventory = {"zulu": 2, "alpha": 8, "middle": 1}
    seen = {"prior"}
    result = process_webhook(payload, signature(payload), b"camp-secret", inventory, seen)
    assert list(result) == ["alpha", "middle", "zulu"]
    assert result == inventory
