import hashlib
import hmac
import json

def process_webhook(payload: bytes, signature: str, secret: bytes, inventory: dict[str, int], seen_ids: set[str]) -> dict[str, int]:
    if not isinstance(signature, str) or not signature.startswith('sha256=') or len(signature) != 71:
        raise ValueError('invalid signature')
    supplied = signature[7:]
    if any((c not in '0123456789abcdef' for c in supplied)):
        raise ValueError('invalid signature')
    expected = hmac.new(secret, payload, hashlib.sha256).hexdigest().encode()
    if not hmac.compare_digest(expected, supplied.encode()):
        raise ValueError('invalid signature')
    try:
        value = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    if not isinstance(value, dict) or set(value) != {'events'} or (not isinstance(value['events'], list)):
        raise ValueError('invalid payload')
    changes = dict(inventory)
    new_ids = []
    for event in value['events']:
        if not isinstance(event, dict) or set(event) != {'id', 'action', 'site', 'nights'}:
            raise ValueError('invalid payload')
        ident = event['id']
        action = event['action']
        site = event['site']
        nights = event['nights']
        if not isinstance(ident, str) or not ident or (not isinstance(site, str)) or (not site) or (action not in ('reserve', 'cancel')) or (not isinstance(nights, int)) or isinstance(nights, bool) or (nights <= 0):
            raise ValueError('invalid payload')
        if ident in seen_ids or ident in new_ids:
            continue
        if site not in changes:
            changes[site] = 0
        if action == 'reserve':
            changes[site] -= nights
            if changes[site] < 0:
                raise ValueError('insufficient availability')
        else:
            changes[site] += nights
        new_ids.append(ident)
    inventory.clear()
    inventory.update(changes)
    seen_ids.update(new_ids)
    return dict(sorted(changes.items()))

