def list_appointments(conn: sqlite3.Connection, practitioner: str | None=None, appointment_date: str | None=None, status: str | None=None, search: str='', sort_by: str='start', limit: int=20, offset: int=0) -> list[dict]:
    if appointment_date is not None:
        try:
            datetime.strptime(appointment_date, '%Y-%m-%d')
        except ValueError:
            raise ValueError('invalid appointment date')
    if sort_by not in {'start', 'client', 'status'}:
        raise ValueError('invalid sort key')
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 0:
        raise ValueError('invalid limit')
    if not isinstance(offset, int) or isinstance(offset, bool) or offset < 0:
        raise ValueError('invalid offset')
    clauses = []
    params = []
    if practitioner is not None:
        clauses.append('practitioner = ?')
        params.append(practitioner)
    if appointment_date is not None:
        clauses.append('appointment_date = ?')
        params.append(appointment_date)
    if status is not None:
        clauses.append('status = ?')
        params.append(status)
    term = search.strip()
    if term:
        clauses.append('LOWER(client_name) LIKE LOWER(?)')
        params.append('%' + term + '%')
    where = ' WHERE ' + ' AND '.join(clauses) if clauses else ''
    order = {'start': 'appointment_date, start_time', 'client': 'LOWER(client_name)', 'status': 'status'}[sort_by]
    query = 'SELECT id, client_name, practitioner, appointment_date, start_time, duration_minutes, status FROM appointments' + where + ' ORDER BY ' + order + ', id LIMIT ? OFFSET ?'
    params.extend([limit, offset])
    rows = conn.execute(query, params).fetchall()
    result = []
    for row in rows:
        start = datetime.strptime(row[4], '%H:%M')
        end = (start + timedelta(minutes=row[5])).strftime('%H:%M')
        result.append({'id': row[0], 'client': row[1], 'practitioner': row[2], 'date': row[3], 'start': row[4], 'end': end, 'status': row[6]})
    return result

