def get_expiration_alerts(xml_text: str, as_of: date, within_days: int=30) -> list[dict]:
    if within_days < 0:
        raise ValueError('within_days must be non-negative')
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'inventory':
        raise ValueError('invalid root')
    result = []
    for item in root.findall('item'):
        values = {}
        for key in ('sku', 'name', 'expires', 'quantity'):
            node = item.find(key)
            if node is None or node.text is None:
                raise ValueError('missing field')
            values[key] = node.text.strip()
        try:
            expiration = date.fromisoformat(values['expires'])
            quantity = int(values['quantity'])
        except Exception as exc:
            raise ValueError('invalid field') from exc
        if quantity < 0:
            raise ValueError('invalid quantity')
        days = (expiration - as_of).days
        if quantity and days <= within_days:
            result.append({'sku': values['sku'], 'name': values['name'], 'expires': values['expires'], 'quantity': quantity, 'days_remaining': days})
    result.sort(key=lambda entry: (entry['expires'], entry['sku']))
