import os
import tempfile


def test_empty_directory():
    with tempfile.TemporaryDirectory() as directory:
        assert list_storage_files(directory) == {
            "total": 0,
            "total_bytes": 0,
            "items": [],
        }


def test_orders_by_size_then_name():
    with tempfile.TemporaryDirectory() as directory:
        files = {
            "zeta": b"1234",
            "alpha": b"5678",
            "small": b"x",
            "medium": b"abc",
        }
        for name, data in files.items():
            with open(os.path.join(directory, name), "wb") as handle:
                handle.write(data)
        result = list_storage_files(directory)
        assert result == {
            "total": 4,
            "total_bytes": 12,
            "items": [
                {"name": "alpha", "size_bytes": 4},
                {"name": "zeta", "size_bytes": 4},
                {"name": "medium", "size_bytes": 3},
                {"name": "small", "size_bytes": 1},
            ],
        }


def test_excludes_subdirectories():
    with tempfile.TemporaryDirectory() as directory:
        with open(os.path.join(directory, "outside"), "wb") as handle:
            handle.write(b"12345")
        nested = os.path.join(directory, "nested")
        os.mkdir(nested)
        with open(os.path.join(nested, "inside"), "wb") as handle:
            handle.write(b"123456789")
        result = list_storage_files(directory)
        assert result["total"] == 1
        assert result["total_bytes"] == 5
        assert result["items"] == [{"name": "outside", "size_bytes": 5}]


def test_pagination_and_totals():
    with tempfile.TemporaryDirectory() as directory:
