                handle.write(b"x" * size)
        assert list_storage_files(directory, page=1, page_size=2) == {
            "total": 5,
            "total_bytes": 15,
            "items": [
                {"name": "file4", "size_bytes": 5},
                {"name": "file3", "size_bytes": 4},
