import csv
import io
from collections import defaultdict
from copy import deepcopy
from datetime import datetime
from decimal import Decimal, ROUND_HALF_UP

def _check(requester, lease):
    if 'admin' not in requester.get('roles', []) and (not (requester.get('tenant_id') == lease.get('tenant_id') and requester.get('user_id') == lease.get('manager_id'))):
        raise PermissionError('not permitted')

def parse_readings(text: str) -> list[dict]:
    rows = list(csv.reader(io.StringIO(text)))
    if not rows or rows[0] != ['tower_id', 'timestamp', 'kwh']:
        raise ValueError('invalid header')
    out = []
    for row in rows[1:]:
        if not row or all((x == '' for x in row)):
            continue
        if len(row) != 3 or not row[0]:
            raise ValueError('invalid row')
        try:
            stamp = datetime.fromisoformat(row[1])
            value = Decimal(row[2])
        except Exception as exc:
            raise ValueError('invalid reading') from exc
        if value < 0:
            raise ValueError('negative reading')
        out.append({'tower_id': row[0], 'timestamp': stamp, 'kwh': value})
    return sorted(out, key=lambda x: (x['timestamp'], x['tower_id']))

def _money(x):
    return Decimal(x).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

def build_monthly_statement(requester: dict, lease: dict, readings_text: str, payments: list[dict], cutoff: str) -> dict:
    _check(requester, lease)
    try:
        end = datetime.fromisoformat(cutoff).date()
    except Exception as exc:
        raise ValueError('invalid cutoff') from exc
    grouped = defaultdict(Decimal)
    for row in parse_readings(readings_text):
        if row['tower_id'] == lease['tower_id'] and row['timestamp'].date() <= end:
            key = row['timestamp'].strftime('%Y-%m')
            grouped[key] += row['kwh']
    months = []
    for month in sorted(grouped):
        usage = grouped[month].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        charge = _money(lease['monthly_base_fee']) + _money(usage * Decimal(lease['per_kwh_rate']))
        months.append({'month': month, 'usage': usage, 'charge_num': charge})
    paid_total = Decimal('0')
    for payment in payments:
        try:
            date = datetime.fromisoformat(payment['date']).date()
            amount = _money(payment['amount'])
        except Exception as exc:
            raise ValueError('invalid payment') from exc
        if amount < 0:
            raise ValueError('negative payment')
        if date <= end:
            paid_total += amount
    remaining = paid_total
    result_months = []
    total_charge = Decimal('0')
    for item in months:
        applied = min(remaining, item['charge_num'])
        remaining -= applied
        balance = item['charge_num'] - applied
        total_charge += item['charge_num']
        result_months.append({'month': item['month'], 'usage_kwh': f"{item['usage']:.2f}", 'charge': f"{item['charge_num']:.2f}", 'paid': f'{applied:.2f}', 'balance': f'{balance:.2f}'})
    total_usage = sum((x['usage'] for x in months), Decimal('0'))
    return {'lease_id': lease['lease_id'], 'tower_id': lease['tower_id'], 'cutoff': cutoff, 'months': result_months, 'total_usage_kwh': f'{total_usage:.2f}', 'total_charges': f'{total_charge:.2f}', 'total_paid': f'{paid_total:.2f}', 'balance': f"{max(total_charge - paid_total, Decimal('0')):.2f}"}

def approve_lease_change(requester: dict, lease: dict, change: dict) -> dict:
    _check(requester, lease)
    allowed = {'effective_date', 'version', 'monthly_base_fee', 'per_kwh_rate', 'manager_id'}
    if set(change) - allowed or 'effective_date' not in change or 'version' not in change or (change['version'] != lease['version']):
        raise ValueError('invalid change')
    try:
        datetime.fromisoformat(change['effective_date']).date()
    except Exception as exc:
        raise ValueError('invalid date') from exc
    result = deepcopy(lease)
    for key in set(change) - {'effective_date', 'version'}:
        if key != 'manager_id' and Decimal(change[key]) < 0:
            raise ValueError('negative value')
        result[key] = change[key]
    result['version'] += 1
    return result

