                current = []
            else:
                current.append(char)
        if escaped:
            raise ValueError('invalid tags')
        parts.append(''.join(current))
    else:
        raise ValueError('invalid tags')
    return [item.strip() for item in parts if item.strip()]

def prepare_manifest(records: list[dict], photographer: str, min_rating: int=0, required_tags: tuple[str, ...]=()) -> dict:
    if not isinstance(photographer, str) or type(min_rating) is not int or (not 0 <= min_rating <= 5):
        raise ValueError('invalid arguments')
    if not isinstance(required_tags, (tuple, list)) or not all((isinstance(x, str) for x in required_tags)):
        raise ValueError('invalid arguments')
    required = {x.strip() for x in required_tags}
    seen = set()
    photos = []
    for record in records:
        if not isinstance(record, dict) or not all((key in record for key in ('filename', 'title', 'year', 'rating', 'tags'))):
            raise ValueError('invalid record')
        filename, title = (record['filename'], record['title'])
        year, rating = (record['year'], record['rating'])
        if not isinstance(filename, str) or not isinstance(title, str) or type(year) is not int or (type(rating) is not int):
            raise ValueError('invalid record')
        filename, title = (filename.strip(), title.strip())
        if not filename or year < 1 or (not 0 <= rating <= 5):
