        if filename in seen:
            raise ValueError('duplicate filename')
        seen.add(filename)
        tags = _tags(record['tags'])
        if rating >= min_rating and required.issubset(tags):
            photos.append({'file': filename, 'title': title, 'year': year, 'rating': rating, 'tags': tags})
    photos.sort(key=lambda p: (-p['rating'], p['year'], p['file'].casefold(), p['file']))
    years = {}
    for photo in photos:
        years[photo['year']] = years.get(photo['year'], 0) + 1
    years = {str(year): years[year] for year in sorted(years)}
    return {'photographer': photographer, 'photos': photos, 'summary': {'count': len(photos), 'top_rating': photos[0]['rating'] if photos else None, 'years': years}}

