import os
import tempfile
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def export_purchase_orders(orders: list[dict], destination: str, *, minimum_total: int | float=0) -> int:
    try:
        minimum = Decimal(str(minimum_total))
    except (InvalidOperation, ValueError, TypeError):
        raise ValueError('invalid minimum_total')
    if minimum < 0:
        raise ValueError('invalid minimum_total')
    prepared = []
    for order in orders:
        if not isinstance(order, dict) or not isinstance(order.get('id'), str) or (not order['id']) or (not isinstance(order.get('vendor'), str)) or (not order['vendor']) or (not isinstance(order.get('items'), list)):
            raise ValueError('invalid order')
        total = Decimal('0')
        for item in order['items']:
            if not isinstance(item, dict) or not isinstance(item.get('sku'), str) or (not item['sku']) or (type(item.get('quantity')) is not int) or (item['quantity'] <= 0):
                raise ValueError('invalid item')
            try:
                price = Decimal(str(item['unit_price']))
            except (InvalidOperation, ValueError, TypeError):
                raise ValueError('invalid item')
            if price < 0:
                raise ValueError('invalid item')
            total += item['quantity'] * price
        total = total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        if total >= minimum:
            prepared.append((total, order['vendor'], order['id'], len(order['items'])))
    prepared.sort(key=lambda row: (-row[0], row[1].casefold(), row[2]))
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent, prefix='.purchase-', suffix='.tmp', text=True)
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['order_id', 'vendor', 'total', 'item_count'])
            for total, vendor, order_id, count in prepared:
                writer.writerow([order_id, vendor, f'{total:.2f}', count])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return len(prepared)

