                raise ValueError
        except Exception as exc:
            raise ValueError('invalid payload') from exc
        if type(entry['amount']) is not int or entry['amount'] <= 0 or entry['type'] not in ('credit', 'debit'):
            raise ValueError('invalid payload')
        if entry['id'] in ids:
            raise ValueError('invalid payload')
        ids.add(entry['id'])
        result.append(dict(entry))
    return result

def reconcile(entries: list[dict], opening_balances: dict[str, int]) -> dict:
    grouped = {account: [] for account in sorted(opening_balances)}
    for entry in entries:
        if entry['account'] not in opening_balances:
            raise ValueError('unknown account')
        grouped[entry['account']].append(entry)
    accounts = {}
    for account in grouped:
        balance = opening_balances[account]
        output = []
        for entry in sorted(grouped[account], key=lambda x: (x['date'], x['id'])):
            balance += entry['amount'] if entry['type'] == 'credit' else -entry['amount']
            output.append({'id': entry['id'], 'date': entry['date'], 'type': entry['type'], 'amount': entry['amount'], 'balance': balance})
        accounts[account] = {'opening': opening_balances[account], 'closing': balance, 'entries': output}
    return {'accounts': accounts}

def verify_and_reconcile(payload: str, signature: str, secret: str, opening_balances: dict[str, int]) -> dict:
    if not isinstance(signature, str) or not signature.startswith('sha256='):
        raise ValueError('invalid signature')
