    if len(supplied) != 64 or any((c not in '0123456789abcdef' for c in supplied)) or (not hmac.compare_digest(supplied, expected)):
        raise ValueError('invalid signature')
    result = reconcile(parse_payload(payload), opening_balances)
    return {'accepted': True, 'accounts': result['accounts']}

