import hashlib
import hmac
import math
import os

def hash_pin(pin: str) -> str:
    if not isinstance(pin, str) or not pin.isdigit() or (not 4 <= len(pin) <= 12):
        raise ValueError('invalid PIN')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return salt.hex() + ':' + digest.hex()

def check_pin(pin: str, stored: str) -> bool:
    if not isinstance(pin, str) or not pin.isdigit() or (not 4 <= len(pin) <= 12):
        return False
    try:
        salt_text, digest_text = stored.split(':')
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (AttributeError, ValueError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def summarize_claims(claims: list[dict], page: int=1, page_size: int=10) -> dict:
    if not isinstance(claims, list) or isinstance(page, bool) or (not isinstance(page, int)) or (page < 1) or isinstance(page_size, bool) or (not isinstance(page_size, int)) or (not 1 <= page_size <= 100):
        raise ValueError('invalid pagination or claims')
