        amount = claim['amount']
        if not isinstance(vehicle, str) or not vehicle or isinstance(amount, bool) or (not isinstance(amount, (int, float))) or (not math.isfinite(amount)) or (amount < 0) or (not isinstance(claim['status'], str)):
            raise ValueError('invalid claim')
        if claim['status'] == 'approved':
            approved += 1
            count, total = groups.get(vehicle, (0, 0))
            groups[vehicle] = (count + 1, total + amount)
    vehicles = [{'vehicle_id': v, 'claim_count': c, 'total_amount': round(t, 2)} for v, (c, t) in groups.items()]
