import zipfile
from datetime import date, timedelta
from pathlib import Path

def extract_evidence(archive_path: str, destination: str) -> list[str]:
    with zipfile.ZipFile(archive_path) as zf:
        infos = zf.infolist()
        names = [i.filename for i in infos]
        if len(names) != len(set(names)):
            raise ValueError('duplicate archive member')
        base = Path(destination).resolve()
        for info in infos:
            target = (base / info.filename).resolve()
            if target != base and base not in target.parents:
                raise ValueError('invalid member path')
        result = []
        for info in infos:
            target = base / info.filename
            if info.is_dir():
                target.mkdir(parents=True, exist_ok=True)
            else:
                target.parent.mkdir(parents=True, exist_ok=True)
                with zf.open(info) as src, open(target, 'wb') as dst:
                    dst.write(src.read())
                result.append(info.filename.replace('\\', '/'))
        return sorted(result)

def rank_sites(findings: list[dict], as_of: str, window_days: int=30) -> list[dict]:
    try:
        end = date.fromisoformat(as_of)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if isinstance(window_days, bool) or not isinstance(window_days, int) or window_days <= 0:
        raise ValueError('invalid window')
    start = end - timedelta(days=window_days - 1)
    grouped = {}
    for row in findings:
        if set(row) != {'site', 'date', 'severity', 'status'}:
            raise ValueError('invalid finding')
        if not isinstance(row['site'], str) or not row['site']:
            raise ValueError('invalid site')
        try:
            day = date.fromisoformat(row['date'])
        except (TypeError, ValueError):
            raise ValueError('invalid date')
        if isinstance(row['severity'], bool) or not isinstance(row['severity'], int) or (not 1 <= row['severity'] <= 5):
            raise ValueError('invalid severity')
        if row['status'] not in ('open', 'closed'):
            raise ValueError('invalid status')
        if row['status'] == 'open' and start <= day <= end:
            grouped.setdefault(row['site'], []).append((day, row['severity']))
    result = []
    for site, rows in grouped.items():
        result.append({'site': site, 'open_count': len(rows), 'max_severity': max((x[1] for x in rows)), 'weighted_score': sum((x[1] * x[1] for x in rows)), 'latest_date': max((x[0] for x in rows)).isoformat()})
    return sorted(result, key=lambda x: (-x['weighted_score'], -x['max_severity'], -x['open_count'], x['site']))

