    if not isinstance(device_id, str) or not isinstance(admin_pin, str):
        raise TypeError('device_id and admin_pin must be strings')
    if not device_id or not admin_pin:
        raise ValueError('device_id and admin_pin must not be empty')
    return {'device_id': device_id, 'pin_record': hash_pin(admin_pin)}

def can_apply_firmware_update(device: dict[str, str], admin_pin: str, current_version: str, target_version: str) -> bool:
    if not isinstance(device, dict) or not isinstance(admin_pin, str):
        return False
    if not isinstance(current_version, str) or not isinstance(target_version, str):
        return False
    if set(device) != {'device_id', 'pin_record'} or not isinstance(device['pin_record'], str):
        return False

