def generate_flag_report(flags: list[dict], users: list[dict], output_dir: str, filename: str, page: int=1, page_size: int=10) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page <= 0 or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (page_size <= 0):
        raise ValueError('invalid pagination')
    names = set()
    for flag in flags:
        if not isinstance(flag, dict) or not isinstance(flag.get('name'), str) or (not isinstance(flag.get('enabled'), bool)) or (not isinstance(flag.get('rollout'), (int, float))) or isinstance(flag.get('rollout'), bool) or (not 0 <= flag['rollout'] <= 100) or ('segment' in flag and (not isinstance(flag['segment'], str))):
            raise ValueError('invalid flag')
        if flag['name'] in names:
            raise ValueError('duplicate flag')
        names.add(flag['name'])
    ids = set()
    for user in users:
        if not isinstance(user, dict) or not isinstance(user.get('id'), str) or (not isinstance(user.get('attributes'), dict)) or (user['id'] in ids):
            raise ValueError('invalid user')
        ids.add(user['id'])
    rows = []
    for flag in flags:
        count = 0
        for user in users:
            attrs = user['attributes']
            if flag.get('segment') is not None and attrs.get('segment') != flag['segment']:
                continue
            score = sum(map(ord, flag['name'] + ':' + user['id'])) % 100
            if flag['enabled'] and score < flag['rollout']:
                count += 1
        percentage = round(count * 100 / len(users), 2) if users else 0.0
        rows.append({'name': flag['name'], 'matched_users': count, 'percentage': percentage})
    rows.sort(key=lambda row: (-row['matched_users'], row['name']))
    start = (page - 1) * page_size
    report = {'page': page, 'page_size': page_size, 'total_flags': len(flags), 'total_users': len(users), 'flags': rows[start:start + page_size]}
    base = Path(output_dir).resolve()
    target = (base / filename).resolve()
    if target != base and base not in target.parents:
        raise ValueError('invalid filename')
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(json.dumps(report, sort_keys=True) + '\n', encoding='utf-8')
    return report

import hashlib
import hmac
import json

def generate_release_notes(payload: str, signature: str, secret: str) -> str:
    if not secret or not isinstance(signature, str) or len(signature) != 71 or (not signature.startswith('sha256=')):
        raise ValueError('invalid signature')
