from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from datetime import datetime

def build_settlement_report(requester: dict, trades: list[dict], page: int=1, page_size: int=20) -> dict:
    if not isinstance(requester, dict) or not isinstance(requester.get('id'), str) or (not isinstance(requester.get('tenant_id'), str)):
        raise ValueError('invalid requester')
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError('invalid pagination')
    required = {'id', 'owner_id', 'tenant_id', 'status', 'currency', 'quantity', 'unit_price', 'fee', 'executed_at'}
    rows = {}
    roles = requester.get('roles', [])
    manager = isinstance(roles, list) and 'settlement_manager' in roles
    try:
        for trade in trades:
            if not isinstance(trade, dict) or not required.issubset(trade):
                raise ValueError('invalid trade')
            datetime.fromisoformat(trade['executed_at'].replace('Z', '+00:00'))
            if trade['status'] != 'settled':
                continue
            if not (trade['owner_id'] == requester['id'] or (manager and trade['tenant_id'] == requester['tenant_id'])):
                raise PermissionError('not authorized')
            q = Decimal(str(trade['quantity']))
            price = Decimal(str(trade['unit_price']))
            fee = Decimal(str(trade['fee']))
            cur = trade['currency']
            if not isinstance(cur, str):
                raise ValueError('invalid trade')
            item = rows.setdefault(cur, [0, Decimal('0'), Decimal('0')])
            item[0] += 1
            item[1] += q * price
            item[2] += fee
    except (InvalidOperation, TypeError, ValueError) as exc:
        if isinstance(exc, ValueError) and str(exc) == 'invalid trade':
            raise
        raise ValueError('invalid trade') from exc
    result = []
    quant = Decimal('0.01')
    for cur in sorted(rows):
        count, gross, fees = rows[cur]
        gross = gross.quantize(quant, rounding=ROUND_HALF_UP)
        fees = fees.quantize(quant, rounding=ROUND_HALF_UP)
        result.append({'currency': cur, 'trade_count': count, 'gross_value': f'{gross:.2f}', 'fees': f'{fees:.2f}', 'net_value': f'{(gross - fees).quantize(quant, rounding=ROUND_HALF_UP):.2f}'})
    start = (page - 1) * page_size
    return {'page': page, 'page_size': page_size, 'total_rows': len(result), 'rows': result[start:start + page_size]}

