def summarize_downloads(events: list[dict], start: str, end: str) -> list[dict]:
    begin = _time(start)
    finish = _time(end)
    if begin >= finish:
        raise ValueError('invalid interval')
    grouped = {}
    for item in events:
        try:
            moment = _time(item['timestamp'])
            episode = item['episode']
            listener = item['listener']
            size = item['bytes']
            listened = item['seconds_listened']
            duration = item['duration_seconds']
        except (KeyError, TypeError):
            raise ValueError('invalid event')
        if moment < begin or moment >= finish:
            continue
        if not isinstance(episode, str) or not episode or (not isinstance(listener, str)) or (not listener):
            raise ValueError('invalid event')
        if not isinstance(size, int) or isinstance(size, bool) or size < 0 or (duration <= 0) or (listened < 0):
            raise ValueError('invalid event')
        grouped.setdefault(episode, []).append((moment, listener, size, listened, duration))
    result = []
    for episode in sorted(grouped):
        rows = sorted(grouped[episode], key=lambda x: x[0])
        last = {}
        accepted = []
        for moment, listener, size, listened, duration in rows:
            previous = last.get(listener)
            if previous is not None and (moment - previous).total_seconds() < 30:
                continue
            last[listener] = moment
            accepted.append((listener, size, min(listened / duration, 1.0)))
        result.append({'episode': episode, 'downloads': len(accepted), 'unique_listeners': len({x[0] for x in accepted}), 'total_bytes': sum((x[1] for x in accepted)), 'average_completion': round(sum((x[2] for x in accepted)) / len(accepted), 3) if accepted else 0.0})
    return result

