import csv
import math
import os
import tempfile

def export_observation_schedule(records: list[dict], output_path: str, night_start: float, night_end: float) -> dict:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    if not isinstance(night_start, (int, float)) or isinstance(night_start, bool) or (not math.isfinite(night_start)):
        raise ValueError('invalid night bounds')
    if not isinstance(night_end, (int, float)) or isinstance(night_end, bool) or (not math.isfinite(night_end)) or (night_start >= night_end):
        raise ValueError('invalid night bounds')
    selected = []
    for record in records:
        try:
            target = record['target']
            ra = record['ra']
            dec = record['dec']
            start = record['start']
            duration = record['duration']
            priority = record['priority']
        except (KeyError, TypeError):
            raise ValueError('invalid record')
        numbers = (ra, dec, start, duration)
        if not isinstance(target, str) or not target or any((isinstance(value, bool) or not isinstance(value, (int, float)) or (not math.isfinite(value)) for value in numbers)) or isinstance(priority, bool) or (not isinstance(priority, int)) or (duration <= 0):
            raise ValueError('invalid record')
        if start >= night_start and start + duration <= night_end:
            selected.append((target, float(ra), float(dec), float(start), float(duration), priority))
    selected.sort(key=lambda row: (-row[5], row[3], row[0]))
    directory = os.path.dirname(os.path.abspath(output_path))
    fd, temporary_path = tempfile.mkstemp(prefix='.schedule-', suffix='.csv', dir=directory)
    os.close(fd)
    try:
        with open(temporary_path, 'w', encoding='utf-8', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['target', 'ra', 'dec', 'start', 'duration', 'priority'])
            for target, ra, dec, start, duration, priority in selected:
                writer.writerow([target, f'{ra:.6f}', f'{dec:.6f}', f'{start:.6f}', f'{duration:.6f}', priority])
        os.replace(temporary_path, output_path)
    finally:
        if os.path.exists(temporary_path):
            os.unlink(temporary_path)
    return {'scheduled_count': len(selected), 'total_hours': round(sum((row[4] for row in selected)) / 60, 2), 'targets': [row[0] for row in selected]}

