import math
import subprocess

def rank_volunteers(log_path: str, page: int=1, page_size: int=10) -> list[dict[str, object]]:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page <= 0) or (page_size <= 0):
        raise ValueError('invalid pagination')
    with open(log_path, encoding='utf-8'):
        pass
    result = subprocess.run(['sort', log_path], capture_output=True, text=True, check=True)
    totals = {}
    first_names = {}
    for raw in result.stdout.splitlines():
        if not raw.strip():
            continue
        fields = raw.split(',')
        if len(fields) != 2:
            raise ValueError('malformed record')
        name = fields[0].strip()
        if not name:
            raise ValueError('empty name')
        try:
            hours = float(fields[1].strip())
        except ValueError as exc:
            raise ValueError('invalid hours') from exc
        if not math.isfinite(hours) or hours < 0:
            raise ValueError('invalid hours')
        if name not in totals:
            totals[name] = 0.0
            first_names[name] = name
        totals[name] += hours
    ranked = sorted(totals, key=lambda name: (-totals[name], name))
    start = (page - 1) * page_size
    return [{'name': first_names[name], 'hours': round(totals[name], 2)} for name in ranked[start:start + page_size]]

