def export_alert_report(alerts: list[dict], output_path: str, min_magnitude: float=0.0) -> dict:
    if not isinstance(alerts, list) or not isinstance(min_magnitude, (int, float)) or (not math.isfinite(min_magnitude)) or (min_magnitude < 0):
        raise ValueError('invalid input')
    selected = []
    for alert in alerts:
        if not isinstance(alert, dict):
            raise ValueError('invalid alert')
        try:
            ident = alert['id']
            station = alert['station']
            timestamp = alert['timestamp']
            magnitude = alert['magnitude']
            latitude = alert['latitude']
            longitude = alert['longitude']
            parsed = datetime.datetime.fromisoformat(timestamp.replace('Z', '+00:00'))
        except (KeyError, TypeError, ValueError, AttributeError):
            raise ValueError('invalid alert')
        if not isinstance(ident, str) or not ident or (not isinstance(station, str)) or (not station):
            raise ValueError('invalid alert')
        if not all((isinstance(value, (int, float)) and math.isfinite(value) for value in (magnitude, latitude, longitude))):
            raise ValueError('invalid alert')
        if magnitude < 0 or not -90 <= latitude <= 90 or (not -180 <= longitude <= 180):
            raise ValueError('invalid alert')
        if magnitude >= min_magnitude:
            selected.append((ident, station, timestamp, parsed, magnitude, latitude, longitude))
    selected.sort(key=lambda row: (-row[4], row[3], row[0]))
    stations = {}
    for row in selected:
        stations.setdefault(row[1], []).append(row[4])
    summary = {'count': len(selected), 'stations': {}}
    for station in sorted(stations):
        values = stations[station]
        summary['stations'][station] = {'count': len(values), 'average_magnitude': round(sum(values) / len(values), 2), 'max_magnitude': max(values)}
    directory = os.path.dirname(os.path.abspath(output_path))
    fd, temporary = tempfile.mkstemp(dir=directory, prefix='.alert-')
    try:
        with os.fdopen(fd, 'w', newline='') as handle:
            writer = csv.writer(handle)
            writer.writerow(['alert_id', 'station', 'timestamp', 'magnitude', 'latitude', 'longitude'])
            for ident, station, timestamp, _, magnitude, latitude, longitude in selected:
                writer.writerow([ident, station, timestamp, f'{magnitude:.3f}', f'{latitude:.4f}', f'{longitude:.4f}'])
        os.replace(temporary, output_path)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return summary

