import secrets

def issue_access_code(code: str) -> str:
    if not isinstance(code, str) or code == '':
        raise ValueError('code must be a non-empty string')
    salt = secrets.token_bytes(16)
    digest = hashlib.pbkdf2_hmac('sha256', code.encode('utf-8'), salt, 100000)
    return salt.hex() + ':' + digest.hex()

def check_access_code(code: str, stored: str) -> bool:
    if not isinstance(code, str) or code == '' or (not isinstance(stored, str)):
        return False
    try:
        salt_text, digest_text = stored.split(':', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', code.encode('utf-8'), salt, 100000)
    return secrets.compare_digest(actual, expected)

