import secrets
_ALPHABET = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'

def new_snapshot_id() -> str:
    return ''.join((secrets.choice(_ALPHABET) for _ in range(20)))

def _split_line(line: str) -> list[str]:
    fields = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            if char not in '|\\':
                raise ValueError('invalid escape')
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('unfinished escape')
    fields.append(''.join(current))
    return fields

def parse_offer_feed(text: str) -> list[dict]:
    result = []
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields = _split_line(raw)
        if len(fields) != 5:
            raise ValueError('wrong field count')
        seller, sku, price_text, currency, stock_text = fields
        if not seller or not sku or (not price_text) or (not currency):
            raise ValueError('empty field')
        try:
            price = Decimal(price_text)
            stock = int(stock_text)
        except Exception as exc:
            raise ValueError('invalid number') from exc
        if not price.is_finite() or price <= 0 or stock < 0 or (str(stock) != stock_text):
            raise ValueError('invalid value')
        result.append({'seller': seller, 'sku': sku, 'price': price, 'currency': currency, 'stock': stock})
    return result

def build_price_comparison(feeds: list[str], rates: dict[str, float], limit: int | None=None) -> dict:
    if limit is not None and (not isinstance(limit, int) or isinstance(limit, bool) or limit < 0):
        raise ValueError('invalid limit')
    best_by_pair = {}
