                continue
            if offer['currency'] not in rates or rates[offer['currency']] <= 0:
                raise ValueError('invalid rate')
            converted = offer['price'] * Decimal(str(rates[offer['currency']]))
            key = (offer['sku'], offer['seller'])
            if key not in best_by_pair or converted < best_by_pair[key]:
                best_by_pair[key] = converted
    chosen = {}
    for (sku, seller), price in best_by_pair.items():
        rounded = price.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        candidate = (rounded, seller)
        if sku not in chosen or candidate < chosen[sku][0]:
            chosen[sku] = (candidate, seller)
