    grouped = {}
    for destination, start, end, cost in rows:
        item = grouped.setdefault(destination, {'destination': destination, 'trip_count': 0, 'total_cost': 0.0, 'earliest_start': start, 'latest_end': end})
        item['trip_count'] += 1
        item['total_cost'] += float(cost)
        item['earliest_start'] = min(item['earliest_start'], start)
        item['latest_end'] = max(item['latest_end'], end)
