import csv
import os
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def _path(base_dir, name):
    base = os.path.realpath(base_dir)
    candidate = os.path.realpath(os.path.join(base, name))
    if os.path.commonpath([base, candidate]) != base:
        raise ValueError('invalid path')
    return candidate

def _decimal(value):
    try:
        result = Decimal(value)
    except (InvalidOperation, ValueError):
        raise ValueError('invalid number')
    if not result.is_finite():
        raise ValueError('invalid number')
    return result

def load_rate_table(base_dir: str, relative_name: str) -> list[dict]:
    try:
        with open(_path(base_dir, relative_name), newline='', encoding='utf-8') as handle:
            reader = csv.reader(handle)
            header = next(reader)
            if header != ['region', 'tier', 'base_rate', 'age_factor']:
                raise ValueError('invalid header')
            rows = []
            for row in reader:
                if len(row) != 4 or not row[0] or (not row[1]):
                    raise ValueError('invalid row')
                rows.append({'region': row[0], 'tier': row[1], 'base_rate': _decimal(row[2]), 'age_factor': _decimal(row[3])})
            if not rows:
                raise ValueError('empty file')
            return rows
    except (OSError, StopIteration, csv.Error):
        raise ValueError('invalid rate file')

def calculate_quote(base_dir: str, rate_file: str, claims_file: str, applicant: dict) -> dict:
    required = ['region', 'tier', 'age', 'term', 'deductible']
    if any((key not in applicant for key in required)):
        raise ValueError('invalid applicant')
    if not isinstance(applicant['region'], str) or not isinstance(applicant['tier'], str):
        raise ValueError('invalid applicant')
    if type(applicant['age']) is not int or applicant['age'] <= 0 or type(applicant['term']) is not int or (not 0 < applicant['term'] <= 10):
        raise ValueError('invalid applicant')
    deductible = _decimal(applicant['deductible'])
    if deductible < 0:
        raise ValueError('invalid applicant')
    rates = load_rate_table(base_dir, rate_file)
    selected = next((r for r in rates if r['region'] == applicant['region'] and r['tier'] == applicant['tier']), None)
    if selected is None:
        raise ValueError('no matching rate')
    claims = Decimal('0')
    try:
        with open(_path(base_dir, claims_file), newline='', encoding='utf-8') as handle:
            reader = csv.reader(handle)
            if next(reader) != ['year', 'amount']:
                raise ValueError('invalid header')
            for row in reader:
                if len(row) != 2 or not row[0] or (not row[1]):
                    raise ValueError('invalid claim')
                year = int(row[0])
                amount = _decimal(row[1])
                if amount < 0:
                    raise ValueError('invalid claim')
                if 2020 <= year <= 2022:
                    claims += amount
    except (OSError, StopIteration, ValueError, csv.Error):
        raise ValueError('invalid claims file')
    annual = selected['base_rate'] * (1 + selected['age_factor'] * (applicant['age'] - 30) / 100) * (1 + claims / 10000) * (1 - min(deductible, Decimal('10000')) / 100000)
    if annual < 0:
        raise ValueError('negative quote')
    cents = int((annual * 100).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
    return {'region': applicant['region'], 'tier': applicant['tier'], 'annual_cents': cents, 'total_cents': cents * applicant['term'], 'claims_3yr': claims}

