from datetime import date
from lxml import etree

def aggregate_campaign_attribution(xml_text: str, start_date: str | None=None, end_date: str | None=None, page: int=1, page_size: int=10) -> list[dict[str, object]]:
    if not isinstance(xml_text, str):
        raise ValueError('xml_text must be a string')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
    try:
        first = date.fromisoformat(start_date) if start_date is not None else None
        last = date.fromisoformat(end_date) if end_date is not None else None
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if first is not None and last is not None and (first > last):
        raise ValueError('invalid date range')
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode(), parser)
    except (etree.XMLSyntaxError, UnicodeError):
        raise ValueError('invalid XML')
    if root.tag != 'report':
        raise ValueError('unexpected root')
    groups = {}
    for node in root:
        if node.tag != 'attribution':
            continue
        source = node.get('source')
        raw_date = node.get('date')
        status = node.get('status')
        raw_revenue = node.get('revenue')
        if not source or status not in {'approved', 'pending', 'rejected'} or raw_date is None or (raw_revenue is None):
            raise ValueError('invalid attribution')
        try:
            event_date = date.fromisoformat(raw_date)
            revenue = Decimal(raw_revenue)
        except (ValueError, InvalidOperation):
            raise ValueError('invalid attribution')
        if not revenue.is_finite() or revenue < 0:
            raise ValueError('invalid attribution')
        if status != 'approved' or (first is not None and event_date < first) or (last is not None and event_date > last):
            continue
        count, total = groups.get(source, (0, Decimal('0')))
        groups[source] = (count + 1, total + revenue)
    rows = [{'source': source, 'conversions': count, 'revenue': str(total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))} for source, (count, total) in groups.items()]
    rows.sort(key=lambda row: (-Decimal(row['revenue']), -row['conversions'], row['source']))
    start = (page - 1) * page_size
    return rows[start:start + page_size]

