        "message": "disk\\watch|x",
    }]


def test_parse_sorting_with_ties_and_blank_lines():
    text = (
        "2024-01-01T00:00:01Z|low|z|last\n"
        "\n"
        "2024-01-01T00:00:00Z|low|b|bee\n"
        "2024-01-01T00:00:00Z|critical|z|crit\n"
        "2024-01-01T00:00:00Z|high|a|high\n"
    )
