        parsed = date.fromisoformat(observed_on)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if not isinstance(observed_on, str) or parsed.isoformat() != observed_on:
        raise ValueError('invalid date')
    if not isinstance(retreat_m, (int, float)) or isinstance(retreat_m, bool) or (not math.isfinite(retreat_m)) or (retreat_m < 0):
        raise ValueError('invalid retreat')
    if not isinstance(note, str):
        raise ValueError('invalid note')
    if conn.execute('SELECT 1 FROM sites WHERE site_id = ?', (site_id,)).fetchone() is None:
        raise ValueError('unknown site')
    conn.execute('INSERT INTO observations VALUES (?, ?, ?, ?)', (site_id, observed_on, float(retreat_m), note))
    conn.commit()

def erosion_report(conn, region=None, min_observations=1, sort_by='rate'):
    if not isinstance(min_observations, int) or isinstance(min_observations, bool) or min_observations < 1:
        raise ValueError('invalid minimum')
    if region is not None and (not isinstance(region, str)):
        raise ValueError('invalid region')
    if sort_by not in {'rate', 'total', 'latest', 'site_id'}:
        raise ValueError('invalid sort')
    sql = 'SELECT s.site_id, s.region, o.observed_on, o.retreat_m FROM sites s JOIN observations o ON o.site_id = s.site_id'
    args = []
    if region is not None:
        sql += ' WHERE s.region = ?'
        args.append(region)
    rows = conn.execute(sql, args).fetchall()
    grouped = {}
    for site_id, site_region, observed_on, amount in rows:
        grouped.setdefault((site_id, site_region), []).append((observed_on, amount))
    result = []
    for (site_id, site_region), values in grouped.items():
