from collections import defaultdict
from decimal import Decimal, ROUND_HALF_UP

def export_mineral_rights_report(records: list[dict], destination: str, minimum_royalty: float=0.0) -> list[dict]:
    if isinstance(minimum_royalty, bool) or not isinstance(minimum_royalty, (int, float)) or (not math.isfinite(minimum_royalty)) or (minimum_royalty < 0):
        raise ValueError('invalid minimum royalty')
    required = ('parcel_id', 'county', 'owner', 'acres', 'royalty', 'status')
    groups = defaultdict(lambda: [0, Decimal('0'), Decimal('0')])
    for record in records:
        if not isinstance(record, dict) or any((k not in record for k in required)):
            raise ValueError('invalid record')
        for key in ('parcel_id', 'county', 'owner', 'status'):
            if not isinstance(record[key], str):
                raise ValueError('invalid record')
        acres, royalty = (record['acres'], record['royalty'])
        if isinstance(acres, bool) or isinstance(royalty, bool) or (not isinstance(acres, (int, float))) or (not isinstance(royalty, (int, float))) or (not math.isfinite(acres)) or (not math.isfinite(royalty)) or (acres < 0) or (royalty < 0):
            raise ValueError('invalid record')
        if record['status'] == 'active' and royalty >= minimum_royalty:
            item = groups[record['owner']]
            item[0] += 1
            item[1] += Decimal(str(acres))
            item[2] += Decimal(str(royalty))

    def rounded(value):
        return float(value.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
    result = [{'owner': owner, 'parcel_count': vals[0], 'total_acres': rounded(vals[1]), 'total_royalty': rounded(vals[2])} for owner, vals in groups.items()]
    result.sort(key=lambda x: (-x['total_royalty'], x['owner']))
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(prefix='.rights-', suffix='.csv', dir=directory, text=True)
    try:
        with os.fdopen(fd, 'w', newline='') as f:
            writer = csv.writer(f)
            writer.writerow(['owner', 'parcel_count', 'total_acres', 'total_royalty'])
            for row in result:
                writer.writerow([row['owner'], row['parcel_count'], f"{row['total_acres']:.2f}", f"{row['total_royalty']:.2f}"])
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return result

