    except ET.ParseError as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'applications':
        raise ValueError('invalid root')
    records = []
    for item in root:
        if item.tag != 'application' or list(item):
            raise ValueError('invalid application')
        required = ('student_id', 'name', 'year', 'priority', 'submitted', 'eligible')
        if any((key not in item.attrib for key in required)):
            raise ValueError('missing attribute')
        sid = item.attrib['student_id']
        name = item.attrib['name']
        submitted = item.attrib['submitted']
        if not sid or not name or (not submitted):
            raise ValueError('empty attribute')
        try:
            year = int(item.attrib['year'])
            priority = int(item.attrib['priority'])
        except ValueError as exc:
            raise ValueError('invalid number') from exc
        if not 1 <= year <= 8 or not 0 <= priority <= 100:
            raise ValueError('out of range')
        if item.attrib['eligible'] not in ('yes', 'no'):
            raise ValueError('invalid eligibility')
        if item.attrib['eligible'] == 'yes':
