import xml.etree.ElementTree as ET

def _text(value, label):
    if value is None or value == '':
        raise ValueError(label)
    return value

def parse_manifest(xml: str) -> dict:
    try:
        root = ET.fromstring(xml)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'build':
        raise ValueError('root')
    result = {'id': _text(root.get('id'), 'id'), 'commit': _text(root.get('commit'), 'commit'), 'created': _text(root.get('created'), 'created'), 'artifacts': [], 'dependencies': []}
    for child in root:
        if child.tag == 'artifact':
            item = {}
            for key in ('name', 'path', 'sha256'):
                item[key] = _text(child.get(key), key)
            raw_size = _text(child.get('size'), 'size')
            try:
                item['size'] = int(raw_size, 10)
            except Exception as exc:
                raise ValueError('size') from exc
            if item['size'] < 0:
                raise ValueError('size')
            for key in ('platform', 'kind'):
                if child.get(key) is not None:
                    item[key] = child.get(key)
            result['artifacts'].append(item)
        elif child.tag == 'dependency':
            result['dependencies'].append({'name': _text(child.get('name'), 'name'), 'version': _text(child.get('version'), 'version')})
    result['artifacts'].sort(key=lambda x: (x['name'], x['path']))
    result['dependencies'].sort(key=lambda x: (x['name'], x['version']))
    return result

def summarize_builds(manifests: list[str]) -> list[dict]:
    seen = set()
    totals = {}
    for source in manifests:
        manifest = parse_manifest(source)
        build_id = manifest['id']
        if build_id in seen:
            raise ValueError('duplicate build')
        seen.add(build_id)
        for artifact in manifest['artifacts']:
            name = artifact['name']
            if name not in totals:
                totals[name] = {'name': name, 'count': 0, 'total_size': 0, 'builds': []}
            entry = totals[name]
            entry['count'] += 1
            entry['total_size'] += artifact['size']
            if build_id not in entry['builds']:
                entry['builds'].append(build_id)
    return [totals[name] for name in sorted(totals)]

def select_artifacts(manifest: dict, platform: str | None=None, kind: str | None=None) -> list[dict]:
    selected = []
    for artifact in manifest.get('artifacts', []):
        if platform is not None and artifact.get('platform') != platform:
            continue
        if kind is not None and artifact.get('kind') != kind:
            continue
        selected.append(artifact)
    return sorted(selected, key=lambda x: (-x['size'], x['name'], x['path']))

