import hashlib
import hmac
import os
from datetime import date, datetime

def _split_escaped(text, separator):
    parts = []
    current = []
    escaped = False
    for char in text:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == separator:
            parts.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape')
    parts.append(''.join(current))
    return parts

def parse_license_bundle(text: str) -> list[dict]:
    if not isinstance(text, str) or not text:
        raise ValueError('empty bundle')
    records = []
    seen = set()
    for raw in _split_escaped(text, ';'):
        fields = _split_escaped(raw, ',')
        if len(fields) != 5 or any((not x for x in fields)):
            raise ValueError('invalid record')
        state, number, issued_text, expires_text, category = fields
        if len(state) != 2 or not state.isascii() or (not state.isupper()) or (not state.isalpha()):
            raise ValueError('invalid state')
        try:
            issued = date.fromisoformat(issued_text)
            expires = date.fromisoformat(expires_text)
        except ValueError:
            raise ValueError('invalid date')
        if issued > expires or (state, number) in seen:
            raise ValueError('invalid license')
        seen.add((state, number))
        records.append({'state': state, 'number': number, 'issued': issued, 'expires': expires, 'category': category})
    return sorted(records, key=lambda x: (x['state'], x['number']))

def _password_record(password):
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return (salt, value)

def register_contractor(registry: dict, contractor_id: str, name: str, bundle: str, password: str) -> None:
    if not isinstance(contractor_id, str) or not contractor_id.strip() or (not isinstance(name, str)) or (not name.strip()) or (not isinstance(password, str)) or (not password):
        raise ValueError('invalid contractor')
    if contractor_id in registry:
        raise ValueError('duplicate contractor')
    licenses = parse_license_bundle(bundle)
    salt, password_value = _password_record(password)
    registry[contractor_id] = {'name': name, 'licenses': licenses, 'salt': salt, 'password': password_value}

def verify_contractor(registry: dict, contractor_id: str, password: str) -> bool:
    item = registry.get(contractor_id)
    if item is None or not isinstance(password, str):
        return False
    value = hashlib.pbkdf2_hmac('sha256', password.encode(), item['salt'], 100000)
    return hmac.compare_digest(value, item['password'])

def eligible_contractors(registry: dict, on_date: date, state: str | None=None) -> list[str]:
    if not isinstance(on_date, date) or isinstance(on_date, datetime):
        raise TypeError('invalid date')
    if state is not None and (len(state) != 2 or not state.isascii() or (not state.isupper()) or (not state.isalpha())):
        raise ValueError('invalid state')
    ranked = []
    for contractor_id, item in registry.items():
        matches = [x for x in item['licenses'] if x['issued'] <= on_date <= x['expires'] and (state is None or x['state'] == state)]
        if matches:
            ranked.append((-len(matches), item['name'].casefold(), contractor_id))
    ranked.sort()
    return [x[2] for x in ranked]

