import ast
from datetime import datetime

def evaluate_expression(expression: str, variables: dict[str, int | float | bool]) -> int | float | bool:
    tree = ast.parse(expression, mode='eval')

    def visit(node):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id in ('True', 'False'):
                return node.id == 'True'
            if node.id not in variables:
                raise NameError(node.id)
            return variables[node.id]
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
            value = visit(node.operand)
            return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
        if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div, ast.Mod)):
            a, b = (visit(node.left), visit(node.right))
            return {ast.Add: lambda: a + b, ast.Sub: lambda: a - b, ast.Mult: lambda: a * b, ast.Div: lambda: a / b, ast.Mod: lambda: a % b}[type(node.op)]()
        if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
            value = visit(node.values[0])
            for child in node.values[1:]:
                if isinstance(node.op, ast.And) and (not value):
                    return value
                if isinstance(node.op, ast.Or) and value:
                    return value
                value = visit(child)
            return value
        if isinstance(node, ast.Compare):
            left = visit(node.left)
            for op, part in zip(node.ops, node.comparators):
                right = visit(part)
                ok = {ast.Eq: left == right, ast.NotEq: left != right, ast.Lt: left < right, ast.LtE: left <= right, ast.Gt: left > right, ast.GtE: left >= right}[type(op)]
                if not ok:
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
            args = [visit(x) for x in node.args]
            if node.func.id == 'round' and len(args) in (1, 2):
                return round(*args)
            if node.func.id == 'min' and len(args) >= 2:
                return min(*args)
            if node.func.id == 'max' and len(args) >= 2:
                return max(*args)
        raise ValueError('unsupported expression')
    return visit(tree.body)

def schedule_reservations(records: list[dict], rule: str, capacity: int) -> list[str]:
    if not isinstance(capacity, int) or capacity < 0:
        raise ValueError('invalid capacity')
    parsed = []
    for record in records:
        try:
            start = datetime.strptime(record['start'], '%Y-%m-%d %H:%M')
            end = datetime.strptime(record['end'], '%Y-%m-%d %H:%M')
            if end <= start or not isinstance(record['id'], str) or (not isinstance(record['equipment'], str)) or (not isinstance(record['priority'], int)):
                raise ValueError('invalid record')
        except (KeyError, TypeError, ValueError) as exc:
            raise ValueError('invalid record') from exc
