            continue
        points = {start, end}
        for _, s, e in accepted:
            if s < end and e > start:
                points.add(max(s, start))
        if any((sum((s <= point < e for _, s, e in accepted)) >= capacity for point in points)):
            continue
        accepted.append((record, start, end))
    accepted.sort(key=lambda x: (x[1], x[2], x[0]['id']))
    return [x[0]['id'] for x in accepted]

