def parse_event(line: str) -> dict:
    fields = []
    key = []
    value = []
    in_value = False
    escaped = False
    for char in line + ';':
        if escaped:
            (value if in_value else key).append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif not in_value and char == '=':
            in_value = True
        elif char == ';':
