                raise ValueError('malformed field')
            fields.append((''.join(key), ''.join(value)))
            key, value, in_value = ([], [], False)
        else:
            (value if in_value else key).append(char)
    if escaped or len(fields) != 5:
        raise ValueError('malformed record')
    data = dict(fields)
    if len(data) != 5 or set(data) != {'id', 'site', 'time', 'state', 'customers'}:
        raise ValueError('invalid fields')
    if not data['id'] or not data['site'] or data['state'] not in {'OPEN', 'RESTORED'}:
        raise ValueError('invalid value')
    try:
        datetime.fromisoformat(data['time'].replace('Z', '+00:00'))
        customers = int(data['customers'])
    except Exception as exc:
        raise ValueError('invalid record') from exc
    if not data['time'].endswith('Z') or customers < 0 or (str(customers) != data['customers'].lstrip('0') and (not set(data['customers']) <= {'0'})):
        raise ValueError('invalid record')
    return {'id': data['id'], 'site': data['site'], 'time': data['time'], 'state': data['state'], 'customers': customers}

