    try:
        end = datetime.fromisoformat(as_of.replace('Z', '+00:00'))
    except Exception as exc:
        raise ValueError('invalid time') from exc
    groups = {}
    for line in lines:
        event = parse_event(line)
        stamp = datetime.fromisoformat(event['time'].replace('Z', '+00:00'))
        item = groups.setdefault(event['id'], {'first': stamp, 'event': event})
        if stamp < item['first']:
            item['first'] = stamp
        old_stamp = datetime.fromisoformat(item['event']['time'].replace('Z', '+00:00'))
        if stamp >= old_stamp:
            item['event'] = event
    result = []
    for ident, item in groups.items():
        event = item['event']
        if event['state'] == 'OPEN':
            if end < item['first']:
                raise ValueError('as_of precedes outage')
            age = int((end - item['first']).total_seconds() // 60)
            result.append({'id': ident, 'site': event['site'], 'started': item['first'].isoformat().replace('+00:00', 'Z'), 'customers': event['customers'], 'age_minutes': age})
    result.sort(key=lambda x: (-x['customers'], x['started'], x['id']))
    return result

def generate_dispatch_codes(outage_ids: list[str], prefix: str='') -> dict[str, str]:
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    if len(prefix) > 11 or any((c not in alphabet for c in prefix)):
        raise ValueError('invalid prefix')
    return {ident: prefix + ''.join((secrets.choice(alphabet) for _ in range(12 - len(prefix)))) for ident in outage_ids}

