from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from datetime import date
from lxml import etree

def summarize_toll_account(xml_text: str, account_id: str, page: int=1, page_size: int=10) -> dict:
    if not account_id or page <= 0 or page_size <= 0:
        raise ValueError('invalid arguments')
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode('utf-8'), parser)
    except (etree.XMLSyntaxError, UnicodeError):
        raise ValueError('invalid XML')
    if root.tag != 'statement':
        raise ValueError('invalid root')
    account = None
    for item in root:
        if item.tag == 'account' and item.get('id') == account_id:
            account = item
            break
    tolls = []
    if account is not None:
        for item in account:
            if item.tag != 'toll':
                continue
            values = [item.get(name) for name in ('id', 'date', 'plaza', 'amount')]
            if any((value is None for value in values)):
                raise ValueError('missing toll attribute')
            toll_id, toll_date, plaza, amount_text = values
            try:
                parsed_date = date.fromisoformat(toll_date)
                amount = Decimal(amount_text).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
            except (ValueError, InvalidOperation):
                raise ValueError('invalid toll')
            tolls.append((parsed_date, toll_id, plaza, amount))
    tolls.sort(key=lambda item: (item[0], item[1]))
    total = sum((item[3] for item in tolls), Decimal('0')).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    start = (page - 1) * page_size
    selected = tolls[start:start + page_size]
    charges = [{'id': toll_id, 'date': toll_date.isoformat(), 'plaza': plaza, 'amount': f'{amount:.2f}'} for toll_date, toll_id, plaza, amount in selected]
    return {'account_id': account_id, 'total': f'{total:.2f}', 'count': len(tolls), 'charges': charges}

