import re
import xml.etree.ElementTree as ET
from datetime import date

def _date(s):
    if not isinstance(s, str) or not re.fullmatch('\\d{4}-\\d{2}-\\d{2}', s):
        raise ValueError('invalid date')
    try:
        date.fromisoformat(s)
    except ValueError:
        raise ValueError('invalid date')
    return s

def parse_catalog(xml: str) -> list[dict]:
    if not isinstance(xml, str):
        raise ValueError('invalid XML')
    try:
        root = ET.fromstring(xml)
    except Exception as e:
        raise ValueError('invalid XML') from e
    if root.tag != 'library':
        raise ValueError('wrong root')
    result, ids = ([], set())
    for node in root:
        if node.tag != 'book':
            continue
        ident = node.get('id', '').strip()
        if not ident or ident in ids:
            raise ValueError('invalid id')
        ids.add(ident)
        fields = {}
        for child in node:
            if child.tag in ('title', 'year', 'copies'):
                if child.tag in fields:
                    raise ValueError('duplicate field')
                fields[child.tag] = child.text or ''
        if not all((x in fields for x in ('title', 'year', 'copies'))):
            raise ValueError('missing field')
        title = fields['title'].strip()
        if not title:
            raise ValueError('empty title')
        try:
            year, copies = (int(fields['year'].strip()), int(fields['copies'].strip()))
        except Exception as e:
            raise ValueError('invalid number') from e
        if not 0 <= year <= 9999 or copies < 0:
            raise ValueError('invalid number')
        authors, tags, loans = ([], [], [])
        for child in node:
            if child.tag in ('author', 'tag'):
                text = (child.text or '').strip()
                if not text:
                    raise ValueError('empty text')
                (authors if child.tag == 'author' else tags).append(text)
            elif child.tag == 'loan':
                user, due = (child.get('user', '').strip(), child.get('due', ''))
                if not user:
                    raise ValueError('invalid loan')
                _date(due)
                loans.append({'user': user, 'due': due})
        result.append({'id': ident, 'title': title, 'year': year, 'copies': copies, 'authors': authors, 'tags': tags, 'loans': loans})
    return result

def build_access_index(records: list[dict], as_of: str, limit: int | None=None) -> list[dict]:
    _date(as_of)
    if limit is not None and (not isinstance(limit, int) or isinstance(limit, bool) or limit < 0):
        raise ValueError('invalid limit')
    out = []
    for b in records:
        overdue = sum((x['due'] < as_of for x in b['loans']))
        out.append({'id': b['id'], 'title': b['title'], 'authors': list(b['authors']), 'year': b['year'], 'available': max(b['copies'] - len(b['loans']), 0), 'overdue': overdue, 'tags': list(b['tags'])})
    out.sort(key=lambda x: (-x['available'], -x['year'], x['title'].strip().casefold(), x['id']))
    return out if limit is None else out[:limit]

