def _fields(line):
    fields = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape')
    fields.append(''.join(current))
    if len(fields) != 4:
        raise ValueError('invalid event')
    return fields

def build_task_report(requester: dict, project: dict, event_lines: list[str]) -> dict:
    if requester.get('tenant_id') != project.get('tenant_id'):
        raise PermissionError('project access denied')
    roles = set(requester.get('roles', []))
    if requester.get('id') != project.get('owner_id') and (not roles.intersection({'editor', 'admin'})):
        raise PermissionError('project access denied')
    task_data = {}
    for task in project['tasks']:
        task_data[task['id']] = {'id': task['id'], 'name': task['name'], 'priority': task['priority'], 'status': 'pending', 'worked_seconds': 0, 'notes': [], 'opened': None, 'completed': False}
    previous = -1
    for line in event_lines:
        timestamp, task_id, kind, value = _fields(line)
        if not timestamp or not task_id:
            raise ValueError('invalid event')
        try:
            timestamp = int(timestamp)
        except ValueError:
            raise ValueError('invalid timestamp')
        if timestamp < 0 or timestamp < previous:
            raise ValueError('invalid timestamp')
        previous = timestamp
        if task_id not in task_data or kind not in {'start', 'stop', 'note'}:
            raise ValueError('invalid event')
        task = task_data[task_id]
        if kind == 'start':
            if value or task['opened'] is not None:
                raise ValueError('invalid start')
            task['opened'] = timestamp
            task['status'] = 'running'
        elif kind == 'stop':
            if value or task['opened'] is None:
                raise ValueError('invalid stop')
            task['worked_seconds'] += timestamp - task['opened']
            task['opened'] = None
            task['completed'] = True
            task['status'] = 'done'
        else:
            task['notes'].append(value)
    output = []
    for task in task_data.values():
        if task['opened'] is not None:
            task['status'] = 'running'
        item = {key: task[key] for key in ('id', 'name', 'priority', 'status', 'worked_seconds', 'notes')}
        output.append(item)
    output.sort(key=lambda item: (-item['priority'], item['id']))
    return {'project_id': project['id'], 'tasks': output, 'total_worked_seconds': sum((x['worked_seconds'] for x in output))}

