import hashlib
import hmac
import json
import os
from datetime import datetime

def summarize_points(events):
    seen = set()
    data = {}
    for event in events:
        for field in ('member', 'points', 'occurred_at', 'id'):
            if field not in event:
                raise ValueError('missing event field')
        member = event['member']
        ident = event['id']
        points = event['points']
        if not isinstance(member, str) or not member or (not isinstance(ident, str)) or (not ident):
            raise ValueError('invalid event text')
        if isinstance(points, bool) or not isinstance(points, int):
            raise ValueError('points must be an integer')
        stamp = event['occurred_at']
        if not isinstance(stamp, str):
            raise ValueError('invalid timestamp')
        try:
            parsed = datetime.fromisoformat(stamp[:-1] + '+00:00' if stamp.endswith('Z') else stamp)
        except (TypeError, ValueError):
            raise ValueError('invalid timestamp')
        if ident in seen:
            raise ValueError('duplicate event id')
        seen.add(ident)
        month = parsed.strftime('%Y-%m')
        if member not in data:
            data[member] = {'balance': 0, 'monthly': {}}
        data[member]['balance'] += points
        data[member]['monthly'][month] = data[member]['monthly'].get(month, 0) + points
    return {member: {'balance': data[member]['balance'], 'monthly': dict(sorted(data[member]['monthly'].items()))} for member in sorted(data)}

def signed_statement(events, config):
    members = summarize_points(events)
    key = config.get('signing_key') if 'signing_key' in config else os.environ.get('LOYALTY_SIGNING_KEY')
    if key is None:
        raise ValueError('missing signing key')
    payload_obj = {'members': members, 'event_count': len(events)}
    payload = json.dumps(payload_obj, sort_keys=True, separators=(',', ':'))
    signature = hmac.new(str(key).encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()
    return json.dumps({'members': members, 'event_count': len(events), 'signature': signature}, separators=(',', ':'))

