import base64
import hashlib
import hmac
import os

def hash_pin(pin: str) -> str:
    if not isinstance(pin, str):
        raise TypeError('pin must be a string')
    if not pin:
        raise ValueError('pin must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 120000)
    return base64.urlsafe_b64encode(salt).decode() + ':' + digest.hex()

def verify_pin(pin: str, stored: str) -> bool:
    if not isinstance(pin, str):
        raise TypeError('pin must be a string')
    if not pin or not isinstance(stored, str):
        return False
    try:
        salt_text, digest_text = stored.split(':', 1)
        salt = base64.urlsafe_b64decode(salt_text.encode())
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 120000)
    return hmac.compare_digest(actual, expected)

