from solution import process_refund_webhook
import hashlib
import hmac
import json
import pytest

def make_payload(obj):
    return json.dumps(obj, separators=(',', ':'), ensure_ascii=False).encode()

def sign(payload, secret=b'merchant-key'):
    return hmac.new(secret, payload, hashlib.sha256).hexdigest()

def test_tie_sorting_and_empty_approved_result():
    obj = {'batch_id': 'x', 'refunds': [{'id': '2', 'country': 'ZZ', 'status': 'rejected', 'entries': [{'customs_value': 1, 'duty_rate': 1}]}, {'id': '1', 'country': 'AA', 'status': 'rejected', 'entries': [{'customs_value': 2, 'duty_rate': 2}]}]}
    p = make_payload(obj)
    assert process_refund_webhook(p, sign(p), b'merchant-key') == {'batch_id': 'x', 'total_refund_cents': 0, 'by_country': []}

def test_signature_rejection():
    p = make_payload({'batch_id': 'x', 'refunds': []})
    with pytest.raises(PermissionError):
        process_refund_webhook(p, '0' * 64, b'merchant-key')

def test_signature_is_over_exact_bytes():
    p = b'{"batch_id":"x","refunds":[]}'
    altered = b'{"batch_id": "x","refunds":[]}'
    with pytest.raises(PermissionError):
        process_refund_webhook(altered, sign(p), b'merchant-key')

def test_malformed_and_structural_inputs():
    p = b'not json'
    with pytest.raises(ValueError):
        process_refund_webhook(p, sign(p), b'merchant-key')
    obj = {'batch_id': 'x', 'refunds': [{'id': 'a', 'country': 'D', 'status': 'approved', 'entries': [{'customs_value': 1, 'duty_rate': 1}]}]}
    p = make_payload(obj)
    with pytest.raises(ValueError):
        process_refund_webhook(p, sign(p), b'merchant-key')

def test_duplicate_ids_and_invalid_numbers():
    base = {'batch_id': 'x', 'refunds': [{'id': 'a', 'country': 'US', 'status': 'approved', 'entries': [{'customs_value': 1, 'duty_rate': 1}]}, {'id': 'a', 'country': 'CA', 'status': 'approved', 'entries': [{'customs_value': 2, 'duty_rate': 2}]}]}
