import hashlib
import hmac
import json

def process_refund_webhook(payload: bytes, signature: str, secret: bytes) -> dict:
    expected = hmac.new(secret, payload, hashlib.sha256).hexdigest()
    if not isinstance(signature, str) or not hmac.compare_digest(expected, signature):
        raise PermissionError('invalid signature')
    try:
        data = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(data, dict) or set(data) != {'batch_id', 'refunds'}:
        raise ValueError('invalid batch')
    if not isinstance(data['batch_id'], str) or not data['batch_id']:
        raise ValueError('invalid batch id')
    if not isinstance(data['refunds'], list):
        raise ValueError('invalid refunds')
    seen = set()
    totals = {}
    total = 0
