import io
import secrets
from datetime import date

def parse_orders(text: str) -> list[dict]:
    if not isinstance(text, str):
        raise ValueError('input must be text')
    lines = [line for line in text.splitlines() if line.strip()]
    if not lines:
        raise ValueError('empty input')
    try:
        rows = list(csv.reader(io.StringIO('\n'.join(lines)), skipinitialspace=False))
    except csv.Error as exc:
        raise ValueError('invalid csv') from exc
    header = [x.strip() for x in rows[0]]
    wanted = ['order_id', 'client', 'copies', 'size', 'run_date', 'status']
    if header != wanted:
        raise ValueError('invalid header')
    result = []
    seen = set()
    statuses = {'pending', 'approved', 'printed', 'cancelled'}
    for row in rows[1:]:
        if len(row) != 6:
            raise ValueError('invalid row')
        values = [x.strip() for x in row]
        ident, client, copies, size, run_date, status = values
        if not ident or not client or ident in seen:
            raise ValueError('invalid order id')
        try:
            copies = int(copies)
            year, month, day = map(int, run_date.split('-'))
            date(year, month, day)
            width, height = map(int, size.split('x'))
        except (ValueError, TypeError):
            raise ValueError('invalid value')
        if copies <= 0 or width <= 0 or height <= 0 or (len(run_date) != 10) or (status not in statuses):
            raise ValueError('invalid value')
        seen.add(ident)
        result.append({'order_id': ident, 'client': client, 'copies': copies, 'width': width, 'height': height, 'run_date': run_date, 'status': status})
    if not result:
        raise ValueError('no orders')
    return result

def summarize_orders(orders: list[dict]) -> dict:
    clients = {}
    statuses = {}
    for order in orders:
        if order['status'] == 'cancelled':
            continue
        clients[order['client']] = clients.get(order['client'], 0) + order['copies']
        statuses[order['status']] = statuses.get(order['status'], 0) + 1
    ordered_clients = {key: clients[key] for key in sorted(clients)}
    ordered_statuses = {key: statuses[key] for key in ('pending', 'approved', 'printed', 'cancelled') if key in statuses}
    return {'total_orders': sum(ordered_statuses.values()), 'total_copies': sum(ordered_clients.values()), 'by_client': ordered_clients, 'by_status': ordered_statuses}

def create_order_batch(text: str) -> dict:
    orders = parse_orders(text)
    active = [order for order in orders if order['status'] != 'cancelled']
    summary = summarize_orders(orders)
    return {**summary, 'orders': active, 'batch_code': 'PA-' + ''.join((secrets.choice('ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789') for _ in range(12)))}

