def process_tee_time_webhook(payload: bytes, signature: str, secret: bytes, offset: int=0, limit: int | None=None) -> dict:
    if not isinstance(payload, bytes) or not isinstance(signature, str) or (not isinstance(secret, bytes)):
        raise ValueError('invalid input')
    expected = hmac.new(secret, payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(signature, expected):
        raise ValueError('invalid signature')
    if not isinstance(offset, int) or isinstance(offset, bool) or offset < 0:
        raise ValueError('invalid pagination')
    if limit is not None and (not isinstance(limit, int) or isinstance(limit, bool) or limit < 0):
        raise ValueError('invalid pagination')
    try:
        root = json.loads(payload.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(root, dict) or not isinstance(root.get('tee_times'), list):
        raise ValueError('invalid payload')
    groups = {}
    for item in root['tee_times']:
        if not isinstance(item, dict):
            raise ValueError('invalid entry')
        keys = ('id', 'course', 'start', 'capacity', 'booked', 'price_cents', 'status')
        if any((k not in item for k in keys)) or not isinstance(item['id'], str) or (not isinstance(item['course'], str)) or (not isinstance(item['start'], str)) or (item['status'] not in ('active', 'cancelled')):
            raise ValueError('invalid entry')
        if any((not isinstance(item[k], int) or isinstance(item[k], bool) or item[k] < 0 for k in ('capacity', 'booked', 'price_cents'))) or item['booked'] > item['capacity']:
            raise ValueError('invalid entry')
        try:
            dt = datetime.strptime(item['start'], '%Y-%m-%dT%H:%M')
        except ValueError as exc:
            raise ValueError('invalid entry') from exc
        if item['status'] == 'cancelled':
            continue
        key = (dt.date().isoformat(), item['course'])
        groups.setdefault(key, []).append((dt, item))
    output = []
    for (date, course), values in sorted(groups.items()):
        values.sort(key=lambda x: (x[0], x[1]['id']))
        total = sum((x[1]['capacity'] - x[1]['booked'] for x in values))
        prices = sum((x[1]['price_cents'] for x in values))
        output.append({'date': date, 'course': course, 'tee_ids': [x[1]['id'] for x in values], 'total_slots': total, 'average_price_cents': (prices * 2 + len(values)) // (2 * len(values))})
    return {'total_groups': len(output), 'total_tee_times': sum((len(v) for v in groups.values())), 'groups': output[offset:] if limit is None else output[offset:offset + limit]}

