from datetime import datetime

def build_qualification_report(requester: dict, supplier: dict, assessments: list[dict], page: int=1, page_size: int=10) -> dict:
    if page < 1 or page_size < 1 or page_size > 50:
        raise ValueError('invalid pagination')
    if not all((k in requester for k in ('user_id', 'tenant_id', 'roles'))):
        raise ValueError('invalid requester')
    if not all((k in supplier for k in ('supplier_id', 'owner_id', 'tenant_id'))):
        raise ValueError('invalid supplier')
    if requester['tenant_id'] != supplier['tenant_id'] or (requester['user_id'] != supplier['owner_id'] and 'qualification_manager' not in requester['roles']):
        raise PermissionError('not permitted')
    chosen = {}
    required = ('assessment_id', 'supplier_id', 'criterion', 'score', 'weight', 'submitted_at')
    for item in assessments:
        if not all((k in item for k in required)):
            raise ValueError('invalid assessment')
        if item['supplier_id'] != supplier['supplier_id']:
            continue
        if not isinstance(item['score'], (int, float)) or not 0 <= item['score'] <= 100:
            raise ValueError('invalid score')
        if not isinstance(item['weight'], (int, float)) or item['weight'] <= 0:
            raise ValueError('invalid weight')
        try:
            stamp = datetime.strptime(item['submitted_at'], '%Y-%m-%dT%H:%M:%SZ')
        except (TypeError, ValueError):
            raise ValueError('invalid timestamp')
        old = chosen.get(item['criterion'])
        if old is None or (stamp, item['assessment_id']) > (old[0], old[1]['assessment_id']):
            chosen[item['criterion']] = (stamp, item)
    rows = []
    for criterion in sorted(chosen):
        item = chosen[criterion][1]
        rows.append({k: item[k] for k in ('criterion', 'score', 'weight', 'submitted_at', 'assessment_id')})
    total_weight = sum((x['weight'] for x in rows))
    weighted = round(sum((x['score'] * x['weight'] for x in rows)) / total_weight, 2) if rows else 0.0
