from lxml import etree

def summarize_work_orders(xml_text: str, page: int=1, page_size: int=10) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    if not isinstance(xml_text, str):
        raise ValueError('invalid xml')
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode('utf-8'), parser)
    except Exception as exc:
        raise ValueError('invalid xml') from exc
    if root.tag != 'vegetation_work_orders':
        raise ValueError('invalid root')
    records = []
    for node in root:
        if node.tag != 'work_order':
            raise ValueError('invalid work order')
        try:
            ident = node.get('id')
            corridor = node.get('corridor')
            status = node.get('status')
            trees_node = node.find('trees')
            cost_node = node.find('estimated_cost')
            if not ident or not corridor or (not status) or (trees_node is None) or (cost_node is None):
                raise ValueError('missing field')
            if trees_node.text is None or cost_node.text is None:
                raise ValueError('missing value')
            trees = int(trees_node.text.strip())
            cost = Decimal(cost_node.text.strip())
            if trees < 0 or not cost.is_finite() or cost < 0:
                raise ValueError('invalid value')
        except (ValueError, InvalidOperation, AttributeError) as exc:
            raise ValueError('invalid work order') from exc
        if status == 'scheduled':
            records.append((ident, corridor, status, trees, cost))
    records.sort(key=lambda record: (-record[4], record[0]))
    total_cost = sum((record[4] for record in records), Decimal('0'))
    start = (page - 1) * page_size
    selected = records[start:start + page_size]
    items = [{'id': ident, 'corridor': corridor, 'status': status, 'trees': trees, 'estimated_cost': float(cost.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))} for ident, corridor, status, trees, cost in selected]
    return {'total': len(records), 'page': page, 'page_size': page_size, 'total_cost': float(total_cost.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)), 'items': items}

