from solution import verify_admission_webhook

import hashlib
import hmac
import json
import pytest


def make_payload(value):
    return json.dumps(value, separators=(",", ":"), ensure_ascii=False)


def signature(payload, secret):
    return hmac.new(secret.encode("utf-8"), payload.encode("utf-8"), hashlib.sha256).hexdigest()


def test_valid_admission_is_returned_with_extra_fields():
    value = {
        "patient_id": "P-1042",
        "ward": "cardiology",
        "admission_date": "2025-03-08",
        "priority": "urgent",
    }
    payload = make_payload(value)
    assert verify_admission_webhook(payload, signature(payload, "shared-key"), "shared-key") == value


def test_unicode_payload_is_processed():
    value = {
        "patient_id": "患者-7",
        "ward": "oncology",
        "admission_date": "2024-02-29",
        "notes": "München",
    }
    payload = make_payload(value)
    assert verify_admission_webhook(payload, signature(payload, "clé"), "clé") == value


def test_wrong_signature_is_rejected():
    value = {"patient_id": "P-1", "ward": "ICU", "admission_date": "2025-01-01"}
    payload = make_payload(value)
    with pytest.raises(ValueError):
        verify_admission_webhook(payload, "0" * 64, "shared-key")


def test_wrong_secret_is_rejected():
    value = {"patient_id": "P-2", "ward": "ward-3", "admission_date": "2025-06-30"}
    payload = make_payload(value)
    with pytest.raises(ValueError):
        verify_admission_webhook(payload, signature(payload, "one"), "two")


def test_malformed_payload_and_non_object_are_rejected():
    with pytest.raises(ValueError):
        verify_admission_webhook("{", "0" * 64, "key")
    payload = "[1, 2, 3]"
    with pytest.raises(ValueError):
        verify_admission_webhook(payload, signature(payload, "key"), "key")


def test_required_fields_and_date_are_validated():
    cases = [
        {"ward": "ICU", "admission_date": "2025-01-01"},
        {"patient_id": "P-1", "ward": "", "admission_date": "2025-01-01"},
        {"patient_id": "P-1", "ward": "ICU", "admission_date": "2025-02-30"},
        {"patient_id": "P-1", "ward": "ICU", "admission_date": "01-02-2025"},
    ]
    for value in cases:
        payload = make_payload(value)
        with pytest.raises(ValueError):
            verify_admission_webhook(payload, signature(payload, "key"), "key")


def test_signature_format_and_argument_types_are_validated():
    value = {"patient_id": "P-3", "ward": "ER", "admission_date": "2025-12-31"}
    payload = make_payload(value)
    for supplied in ["A" * 64, "g" * 64, "0" * 63, "0" * 65]:
        with pytest.raises(ValueError):
            verify_admission_webhook(payload, supplied, "key")
    with pytest.raises(ValueError):
        verify_admission_webhook(b"not-text", "0" * 64, "key")
    with pytest.raises(ValueError):
        verify_admission_webhook(payload, signature(payload, "key"), b"key")

