import datetime
import hashlib
import hmac
import json

def verify_admission_webhook(payload: str, signature: str, secret: str) -> dict:
    if not isinstance(payload, str) or not isinstance(signature, str) or (not isinstance(secret, str)):
        raise ValueError('invalid argument type')
    if len(signature) != 64 or any((c not in '0123456789abcdef' for c in signature)):
        raise ValueError('invalid signature format')
    expected = hmac.new(secret.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    try:
        value = json.loads(payload)
    except (TypeError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    if not isinstance(value, dict):
        raise ValueError('invalid payload')
    for field in ('patient_id', 'ward', 'admission_date'):
        if not isinstance(value.get(field), str) or not value[field]:
            raise ValueError('invalid admission')
    try:
        parsed = datetime.date.fromisoformat(value['admission_date'])
    except ValueError:
        raise ValueError('invalid admission date')
    if parsed.isoformat() != value['admission_date']:
        raise ValueError('invalid admission date')
    return value

