        raise ValueError('invalid date')
    return value

def setup_database(conn):
    conn.executescript('\n        create table if not exists members (\n            id integer primary key, name text not null, email text not null unique,\n            tier text not null, joined text not null\n        );\n        create table if not exists visits (\n            member_id integer not null references members(id),\n            visit_date text not null, primary key(member_id, visit_date)\n        );\n    ')
    conn.commit()

def add_member(conn, member_id, name, email, tier, joined):
    if not isinstance(member_id, int) or isinstance(member_id, bool):
        raise ValueError('invalid id')
    if tier not in _TIERS:
        raise ValueError('invalid tier')
    joined = _date(joined)
    conn.execute('insert into members(id,name,email,tier,joined) values(?,?,?,?,?)', (member_id, name, email, tier, joined))
    conn.commit()

def record_visit(conn, member_id, visit_date):
    visit_date = _date(visit_date)
    if conn.execute('select 1 from members where id=?', (member_id,)).fetchone() is None:
        raise ValueError('unknown member')
    try:
        conn.execute('insert into visits(member_id,visit_date) values(?,?)', (member_id, visit_date))
    except sqlite3.IntegrityError:
        raise ValueError('duplicate visit')
    conn.commit()

def member_report(conn, search='', tier=None, sort_by='name', descending=False):
    if tier is not None and tier not in _TIERS:
        raise ValueError('invalid tier')
    if sort_by not in _SORTS:
        raise ValueError('invalid sort')
    clauses = []
    args = []
    if search:
        clauses.append('(lower(m.name) like lower(?) or lower(m.email) like lower(?))')
        pattern = '%' + search + '%'
        args.extend([pattern, pattern])
    if tier is not None:
        clauses.append('m.tier=?')
        args.append(tier)
    where = ' where ' + ' and '.join(clauses) if clauses else ''
    direction = ' desc' if descending else ' asc'
    sql = 'select m.id,m.name,m.email,m.tier,count(v.visit_date) as visit_count,max(v.visit_date) as last_visit from members m left join visits v on v.member_id=m.id' + where + ' group by m.id ' + 'order by ' + _SORTS[sort_by] + direction + ', m.id asc'
    rows = conn.execute(sql, args).fetchall()
    return [{'id': r[0], 'name': r[1], 'email': r[2], 'tier': r[3], 'visit_count': r[4], 'last_visit': r[5]} for r in rows]

