import os
from unittest.mock import patch


def expected_digest(finding, key):
    payload = json.dumps(finding, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode('utf-8')
    return hmac.new(key.encode('utf-8'), payload, hashlib.sha256).hexdigest()


def test_digest_uses_environment_key():
    finding = {'id': 'F-100', 'severity': 'high', 'status': 'open'}
    with patch.dict(os.environ, {'AUDIT_SIGNING_KEY': 'env-key'}, clear=False):
        assert create_finding_digest(finding) == expected_digest(finding, 'env-key')


def test_config_key_takes_precedence_over_environment():
    finding = {'id': 'F-101', 'severity': 'low'}
    with patch.dict(os.environ, {'AUDIT_SIGNING_KEY': 'environment-key'}, clear=False):
        assert create_finding_digest(finding, {'audit_signing_key': 'config-key'}) == expected_digest(finding, 'config-key')


def test_nested_values_and_key_order_are_canonical():
    first = {
        'metadata': {'owner': 'alice', 'tags': ['pci', 'quarterly']},
        'id': 'F-102',
        'severity': 'medium'
    }
    second = {
        'severity': 'medium',
        'id': 'F-102',
        'metadata': {'tags': ['pci', 'quarterly'], 'owner': 'alice'}
    }
    assert create_finding_digest(first, {'audit_signing_key': 'k'}) == create_finding_digest(second, {'audit_signing_key': 'k'})


