    finding = {'id': 'F-103', 'title': 'Accès contrôlé', 'owner': '李明'}
    assert create_finding_digest(finding, {'audit_signing_key': 'clé-é'}) == expected_digest(finding, 'clé-é')


def test_empty_dictionary_is_valid():
    assert create_finding_digest({}, {'audit_signing_key': 'empty-case'}) == expected_digest({}, 'empty-case')


def test_digest_changes_when_finding_changes():
    base = {'id': 'F-104', 'severity': 'low'}
    changed = {'id': 'F-104', 'severity': 'high'}
    key = {'audit_signing_key': 'change-test'}
