import secrets
_ALPHABET = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'

def _fields(line):
    fields = []
    current = []
    i = 0
    while i < len(line):
        ch = line[i]
        if ch == '\t':
            fields.append(''.join(current))
            current = []
        elif ch == '\\':
            i += 1
            if i == len(line):
                raise ValueError('trailing escape')
            esc = line[i]
            if esc == 't':
                current.append('\t')
            elif esc == 'n':
                current.append('\n')
            elif esc == '\\':
                current.append('\\')
            else:
                raise ValueError('unknown escape')
        else:
            current.append(ch)
        i += 1
    fields.append(''.join(current))
    return fields

def parse_annotations(text: str) -> list[dict]:
    result = []
    for line in text.splitlines():
        if not line or line[0] == '#':
            continue
        fields = _fields(line)
        if len(fields) != 5 or not fields[0] or (not fields[3]):
            raise ValueError('invalid annotation')
        try:
            start = int(fields[1])
            end = int(fields[2])
        except ValueError:
            raise ValueError('invalid offset')
        if fields[1] != str(start) or fields[2] != str(end) or start < 0 or (start >= end):
            raise ValueError('invalid span')
        result.append({'doc': fields[0], 'start': start, 'end': end, 'label': fields[3], 'text': fields[4]})
    return result

def aggregate_labels(records: list[dict]) -> dict:
    groups = {}
    for record in records:
        group = groups.setdefault(record['doc'], {'annotations': 0, 'labels': {}, 'spans': []})
        group['annotations'] += 1
        label = record['label']
        group['labels'][label] = group['labels'].get(label, 0) + 1
        group['spans'].append((record['start'], record['end']))
    output = {}
    for doc in sorted(groups):
        group = groups[doc]
        spans = sorted(group['spans'])
        covered = 0
        left = right = None
        for start, end in spans:
            if left is None:
                left, right = (start, end)
            elif start > right:
                covered += right - left
                left, right = (start, end)
            else:
                right = max(right, end)
        if left is not None:
            covered += right - left
        output[doc] = {'annotations': group['annotations'], 'covered': covered, 'labels': dict(sorted(group['labels'].items()))}
    return output

