    if not isinstance(annotator, str) or not annotator:
        raise ValueError('invalid annotator')
    items = [dict(record) for record in records]
    items.sort(key=lambda r: (-(r['end'] - r['start']), r['doc'], r['start'], r['end'], r['label']))
    token = ''.join((secrets.choice(_ALPHABET) for _ in range(24)))
    return {'annotator': annotator, 'token': token, 'items': items}

