import datetime

def _split(line):
    fields = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape')
    fields.append(''.join(current))
    return fields

def parse_event_log(text: str) -> list[dict]:
    result = []
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields = _split(raw)
        if len(fields) != 3 or any((not x for x in fields)):
            raise ValueError('malformed event')
        date, kind, value = fields
        try:
            datetime.date.fromisoformat(date)
        except ValueError:
            raise ValueError('invalid date')
        if kind not in {'amendment', 'vote', 'status'}:
            raise ValueError('invalid kind')
        if kind == 'vote' and value not in {'yes', 'no', 'abstain'}:
            raise ValueError('invalid vote')
        result.append({'date': date, 'kind': kind, 'value': value})
    return result

def _check_event(event):
    if set(event) != {'date', 'kind', 'value'}:
        raise ValueError('malformed event')
    parsed = parse_event_log('|'.join((str(event[x]) for x in ('date', 'kind', 'value'))))
    return parsed[0]

def summarize_bill(requester: dict, bill: dict, events: list[dict]) -> dict:
    requester['id']
    requester['tenant']
    requester['role']
    bill['id']
    bill['tenant']
    bill['owner_id']
    bill['status']
    if requester['tenant'] != bill['tenant'] or (requester['id'] != bill['owner_id'] and requester['role'] not in {'clerk', 'committee_chair'}):
        raise PermissionError('not permitted')
    checked = [_check_event(event) for event in events]
    votes = {'yes': 0, 'no': 0, 'abstain': 0}
    days = {}
    amendments = 0
    for event in checked:
        days[event['date']] = days.get(event['date'], 0) + 1
        if event['kind'] == 'amendment':
            amendments += 1
        elif event['kind'] == 'vote':
            votes[event['value']] += 1
    ordered = sorted(days)
    return {'bill_id': bill['id'], 'status': bill['status'], 'total_events': len(checked), 'amendments': amendments, 'votes': votes, 'latest_event': max(ordered) if ordered else None, 'by_day': [{'date': d, 'count': days[d]} for d in ordered]}

def render_bill_report(requester: dict, bill: dict, events: list[dict]) -> str:
    summary = summarize_bill(requester, bill, events)
    days = ', '.join((f"{x['date']}={x['count']}" for x in summary['by_day'])) or 'none'
    v = summary['votes']
    return '\n'.join([f"Bill: {summary['bill_id']}", f"Status: {summary['status']}", f"Events: {summary['total_events']}", f"Amendments: {summary['amendments']}", f"Votes: yes={v['yes']}, no={v['no']}, abstain={v['abstain']}", f"Latest event: {summary['latest_event']}", f'By day: {days}'])

