from pathlib import Path
import csv

def write_transaction_history(base_dir: str, relative_name: str, transactions: list[dict[str, str]]) -> str:
    if not relative_name or not relative_name.endswith('.csv'):
        raise ValueError('invalid output name')
    base = Path(base_dir).resolve()
    target = (base / relative_name).resolve()
    try:
        target.relative_to(base)
    except ValueError:
        raise ValueError('output is outside base directory')
    target.parent.mkdir(parents=True, exist_ok=True)
    with target.open('w', newline='') as handle:
        writer = csv.writer(handle, lineterminator='\n')
        writer.writerow(['timestamp', 'merchant', 'amount', 'currency'])
        for transaction in transactions:
            writer.writerow([transaction['timestamp'], transaction['merchant'], transaction['amount'], transaction['currency']])
    return str(target)

import csv
import io
import math
from datetime import datetime, timezone, timedelta

def _time(s):
    if not isinstance(s, str) or not s.endswith('Z'):
        raise ValueError('invalid timestamp')
    try:
        x = datetime.fromisoformat(s[:-1] + '+00:00')
    except Exception as e:
        raise ValueError('invalid timestamp') from e
    if x.tzinfo is None:
        raise ValueError('invalid timestamp')
    return x.astimezone(timezone.utc)

def parse_sensor_log(text: str) -> list[dict]:
    if not text:
        return []
    try:
        rows = list(csv.reader(io.StringIO(text), strict=True))
    except Exception as e:
        raise ValueError('invalid csv') from e
    if not rows:
        return []
    if rows[0] != ['machine_id', 'timestamp', 'meters', 'defects', 'temperature']:
        raise ValueError('invalid header')
    out = []
    for row in rows[1:]:
        if not row or all((v == '' for v in row)):
            continue
        if len(row) != 5 or not row[0]:
            raise ValueError('invalid row')
        try:
            meters = float(row[2])
            defects_f = float(row[3])
            temperature = float(row[4])
            if not all((math.isfinite(x) for x in (meters, defects_f, temperature))) or defects_f != int(defects_f) or meters < 0 or (defects_f < 0):
                raise ValueError
            out.append({'machine_id': row[0], 'timestamp': _time(row[1]), 'meters': meters, 'defects': int(defects_f), 'temperature': temperature})
        except Exception as e:
            raise ValueError('invalid value') from e
    return out

def build_production_report(requester: dict, machines: list[dict], log_text: str, start: str, end: str, window_minutes: int=15) -> dict:
    st, en = (_time(start), _time(end))
    if en <= st or not isinstance(window_minutes, int) or window_minutes <= 0 or 60 % window_minutes:
        raise ValueError('invalid interval')
    if len({m['id'] for m in machines}) != len(machines):
        raise ValueError('duplicate machine')
    allowed = []
    for m in machines:
        if m['tenant_id'] != requester['tenant_id'] or not (m['owner_id'] == requester['id'] or {'supervisor', 'manager'}.intersection(requester.get('roles', []))):
            raise PermissionError('not permitted')
        allowed.append(m)
    byid = {m['id']: [] for m in allowed}
    for x in parse_sensor_log(log_text):
        if x['machine_id'] in byid and st <= x['timestamp'] < en:
            byid[x['machine_id']].append(x)
    step = timedelta(minutes=window_minutes)
    result = []
    for m in sorted(allowed, key=lambda z: (z['line'], z['id'])):
        xs = byid[m['id']]
        cur = st
        windows = []
        while cur < en:
            nxt = min(cur + step, en)
            ys = [x for x in xs if cur <= x['timestamp'] < nxt]
            windows.append({'start': cur.strftime('%Y-%m-%dT%H:%M:%SZ'), 'end': nxt.strftime('%Y-%m-%dT%H:%M:%SZ'), 'meters': round(sum((x['meters'] for x in ys)), 2), 'defects': round(sum((x['defects'] for x in ys)), 2)})
            cur = nxt
        result.append({'id': m['id'], 'line': m['line'], 'sample_count': len(xs), 'meters': round(sum((x['meters'] for x in xs)), 2), 'defects': round(sum((x['defects'] for x in xs)), 2), 'average_temperature': round(sum((x['temperature'] for x in xs)) / len(xs), 2) if xs else None, 'windows': windows})
    return {'start': start, 'end': end, 'window_minutes': window_minutes, 'machines': result}

