            raise ValueError('invalid row')
        try:
            meters = float(row[2])
            defects_f = float(row[3])
            temperature = float(row[4])
            if not all((math.isfinite(x) for x in (meters, defects_f, temperature))) or defects_f != int(defects_f) or meters < 0 or (defects_f < 0):
                raise ValueError
            out.append({'machine_id': row[0], 'timestamp': _time(row[1]), 'meters': meters, 'defects': int(defects_f), 'temperature': temperature})
        except Exception as e:
            raise ValueError('invalid value') from e
    return out

def build_production_report(requester: dict, machines: list[dict], log_text: str, start: str, end: str, window_minutes: int=15) -> dict:
    st, en = (_time(start), _time(end))
    if en <= st or not isinstance(window_minutes, int) or window_minutes <= 0 or 60 % window_minutes:
        raise ValueError('invalid interval')
    if len({m['id'] for m in machines}) != len(machines):
        raise ValueError('duplicate machine')
    allowed = list(machines)
    byid = {m['id']: [] for m in allowed}
    for x in parse_sensor_log(log_text):
        if x['machine_id'] in byid and st <= x['timestamp'] < en:
            byid[x['machine_id']].append(x)
    step = timedelta(minutes=window_minutes)
    result = []
    for m in sorted(allowed, key=lambda z: (z['line'], z['id'])):
        xs = byid[m['id']]
        cur = st
        windows = []
        while cur < en:
            nxt = min(cur + step, en)
            ys = [x for x in xs if cur <= x['timestamp'] < nxt]
            windows.append({'start': cur.strftime('%Y-%m-%dT%H:%M:%SZ'), 'end': nxt.strftime('%Y-%m-%dT%H:%M:%SZ'), 'meters': round(sum((x['meters'] for x in ys)), 2), 'defects': round(sum((x['defects'] for x in ys)), 2)})
            cur = nxt
        result.append({'id': m['id'], 'line': m['line'], 'sample_count': len(xs), 'meters': round(sum((x['meters'] for x in xs)), 2), 'defects': round(sum((x['defects'] for x in xs)), 2), 'average_temperature': round(sum((x['temperature'] for x in xs)) / len(xs), 2) if xs else None, 'windows': windows})
    return {'start': start, 'end': end, 'window_minutes': window_minutes, 'machines': result}

