import csv
import datetime
import os
import tempfile
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def export_expense_report(expenses: list[dict], destination: str, department: str | None=None, page: int=1, page_size: int=50) -> dict:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page <= 0) or (page_size <= 0):
        raise ValueError('invalid pagination')
    required = {'employee', 'department', 'date', 'amount', 'status'}
    rows = []
    for item in expenses:
        if not isinstance(item, dict) or not required.issubset(item):
            raise ValueError('invalid expense')
        try:
            date_value = item['date']
            parsed = datetime.date.fromisoformat(date_value)
            if parsed.isoformat() != date_value:
                raise ValueError
            if not all((isinstance(item[k], str) for k in ('employee', 'department', 'status'))) or item['status'] not in ('approved', 'pending'):
                raise ValueError
            if isinstance(item['amount'], bool):
                raise ValueError
            amount = Decimal(str(item['amount']))
            if not amount.is_finite() or amount < 0:
                raise ValueError
        except (TypeError, ValueError, InvalidOperation):
            raise ValueError('invalid expense')
        amount = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        if item['status'] == 'approved' and (department is None or item['department'] == department):
            rows.append((item['employee'], item['department'], item['date'], amount))
    rows.sort(key=lambda r: (r[2], r[3], r[0]))
    totals = {}
    for row in rows:
        totals[row[1]] = totals.get(row[1], Decimal('0')) + row[3]
    total = sum((r[3] for r in rows), Decimal('0'))
    pages = (len(rows) + page_size - 1) // page_size if rows else 0
    selected = rows[(page - 1) * page_size:page * page_size]
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(prefix='.expense-', suffix='.csv', dir=parent)
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle)
            writer.writerow(['employee', 'department', 'date', 'amount'])
            writer.writerows([[r[0], r[1], r[2], f'{r[3]:.2f}'] for r in selected])
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return {'count': len(rows), 'total': f'{total:.2f}', 'by_department': {k: f'{totals[k]:.2f}' for k in sorted(totals)}, 'page': page, 'page_size': page_size, 'pages': pages, 'rows': len(selected)}

