import datetime, hashlib, hmac, json, os

def _key(config):
    v = config.get('signing_key') or os.environ.get('DELIVERY_SIGNING_KEY')
    if not v:
        raise ValueError('signing key is required')
    return v.encode()

def _timestamp(v):
    if not isinstance(v, str) or not v.endswith('Z'):
        raise ValueError('invalid occurred_at')
    try:
        p = datetime.datetime.fromisoformat(v[:-1] + '+00:00')
    except ValueError:
        raise ValueError('invalid occurred_at')
    if p.tzinfo is None:
        raise ValueError('invalid occurred_at')
    p = p.astimezone(datetime.timezone.utc)
    s = p.isoformat(timespec='microseconds')[:-6]
    if s.endswith('.000000'):
        s = s[:-7]
    else:
        s = s.rstrip('0').rstrip('.')
    return (p, s + 'Z')

def _canonical(e, s):
    return json.dumps({'exceptions': e, 'summary': s}, separators=(',', ':'), sort_keys=True).encode()

def make_exception_report(events: list[dict], config: dict[str, str]) -> dict:
    chosen = {}
    for i, x in enumerate(events):
        req = ('tracking_id', 'kind', 'status', 'hub', 'occurred_at')
        if not isinstance(x, dict) or any((f not in x for f in req)):
            raise ValueError('invalid event')
        if any((not isinstance(x[f], str) or not x[f] for f in req)):
            raise ValueError('invalid event')
        if x['status'] not in ('open', 'resolved'):
            raise ValueError('unsupported status')
        p, n = _timestamp(x['occurred_at'])
        k = (x['tracking_id'], x['kind'])
        if k not in chosen or p >= chosen[k][0]:
            chosen[k] = (p, i, x, n)
    out = [{'tracking_id': x['tracking_id'], 'kind': x['kind'], 'hub': x['hub'], 'occurred_at': n} for p, i, x, n in chosen.values() if x['status'] == 'open']
    out.sort(key=lambda x: (x['hub'], x['kind'], x['tracking_id']))
    bh = {}
    for x in out:
        bh[x['hub']] = bh.get(x['hub'], 0) + 1
    s = {'total_open': len(out), 'by_hub': dict(sorted(bh.items()))}
    return {'exceptions': out, 'summary': s, 'signature': hmac.new(_key(config), _canonical(out, s), hashlib.sha256).hexdigest()}

def verify_exception_report(report: dict, config: dict[str, str]) -> bool:
    try:
        if not isinstance(report, dict) or set(report) != {'exceptions', 'summary', 'signature'}:
            return False
        z = hmac.new(_key(config), _canonical(report['exceptions'], report['summary']), hashlib.sha256).hexdigest()
        return isinstance(report['signature'], str) and hmac.compare_digest(z, report['signature'])
    except (ValueError, TypeError, KeyError):
        return False

