import csv
import io
import json
import os
import zipfile

def collect_survey(zip_path: str, base_dir: str, survey_id: str) -> dict:
    target = os.path.abspath(os.path.join(base_dir, survey_id))
    os.makedirs(target, exist_ok=True)
    with zipfile.ZipFile(zip_path) as archive:
        names = archive.namelist()
        if 'survey.json' not in names or 'responses.csv' not in names:
            raise ValueError('missing required file')
        for member in archive.infolist():
            destination = os.path.abspath(os.path.join(target, member.filename))
            if os.path.commonpath((target, destination)) != target:
                raise ValueError('invalid member path')
            if member.is_dir():
                os.makedirs(destination, exist_ok=True)
            else:
                os.makedirs(os.path.dirname(destination), exist_ok=True)
                with open(destination, 'wb') as output:
                    output.write(archive.read(member))
    try:
        with open(os.path.join(target, 'survey.json'), encoding='utf-8') as handle:
            metadata = json.load(handle)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid metadata') from exc
    if not isinstance(metadata, dict) or not isinstance(metadata.get('title'), str):
        raise ValueError('invalid metadata')
    regions = {}
    respondents = set()
    with open(os.path.join(target, 'responses.csv'), newline='', encoding='utf-8') as handle:
        reader = csv.reader(handle, skipinitialspace=True)
        try:
            header = next(reader)
        except StopIteration as exc:
            raise ValueError('invalid header') from exc
        if [x.strip() for x in header] != ['region', 'respondent', 'question', 'value', 'weight']:
            raise ValueError('invalid header')
        for row in reader:
            if not row or all((not x.strip() for x in row)):
                continue
            if len(row) != 5:
                raise ValueError('invalid row')
            region, respondent, question, value_text, weight_text = [x.strip() for x in row]
            if not region or not respondent or (not question):
                raise ValueError('invalid row')
            try:
                value = float(value_text)
                weight = float(weight_text)
            except ValueError as exc:
                raise ValueError('invalid row') from exc
            if weight <= 0:
                raise ValueError('invalid row')
            respondents.add(respondent)
            item = regions.setdefault(region, [0, 0.0, 0.0])
            item[0] += 1
            item[1] += value * weight
            item[2] += weight
    result_regions = [{'name': name, 'responses': regions[name][0], 'weighted_mean': round(regions[name][1] / regions[name][2], 2)} for name in sorted(regions)]
    return {'survey_id': survey_id, 'title': metadata['title'], 'respondents': len(respondents), 'regions': result_regions}

def rank_regions(summary: dict) -> list[dict]:
    return [dict(item) for item in sorted(summary.get('regions', []), key=lambda x: (-x['weighted_mean'], -x['responses'], x['name']))]

