import math
import os
import tempfile

def generate_award_report(proposals: list[dict], destination: str, page: int=1, page_size: int=10) -> dict:
    if not isinstance(proposals, list):
        raise ValueError('proposals must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
    groups = {}
    for proposal in proposals:
        if not isinstance(proposal, dict):
            raise ValueError('invalid proposal')
        if set(proposal) != {'institution', 'requested', 'score', 'status'}:
            raise ValueError('invalid proposal fields')
        institution = proposal['institution']
        requested = proposal['requested']
        score = proposal['score']
        status = proposal['status']
        if not isinstance(institution, str) or not institution:
            raise ValueError('invalid institution')
        if isinstance(requested, bool) or not isinstance(requested, (int, float)) or (not math.isfinite(requested)) or (requested <= 0):
            raise ValueError('invalid requested amount')
        if isinstance(score, bool) or not isinstance(score, (int, float)) or (not math.isfinite(score)) or (not 0 <= score <= 100):
            raise ValueError('invalid score')
        if status not in ('approved', 'rejected'):
            raise ValueError('invalid status')
        if status == 'approved':
            group = groups.setdefault(institution, [0, 0.0, 0.0])
            group[0] += 1
            group[1] += requested
            group[2] += score
    items = []
    for institution, (count, total, scores) in groups.items():
        items.append({'institution': institution, 'proposal_count': count, 'total_requested': round(total, 2), 'average_score': round(scores / count, 2)})
    items.sort(key=lambda item: (-item['total_requested'], item['institution']))
    start = (page - 1) * page_size
    selected = items[start:start + page_size]
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent)
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle)
            writer.writerow(['institution', 'proposal_count', 'total_requested', 'average_score'])
            for item in selected:
                writer.writerow([item['institution'], item['proposal_count'], f"{item['total_requested']:.2f}", f"{item['average_score']:.2f}"])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return {'total': len(items), 'page': page, 'page_size': page_size, 'items': selected}

