from lxml import etree

def occupancy_report(xml_text: str, min_duration: int=0) -> dict:
    if not isinstance(xml_text, str) or isinstance(min_duration, bool) or (not isinstance(min_duration, int)) or (min_duration < 0):
        raise ValueError()
    try:
        root = etree.fromstring(xml_text.encode())
    except Exception as exc:
        raise ValueError() from exc
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode(), parser)
    except Exception as exc:
        raise ValueError() from exc
    seen = set()
    rows = []
    for node in root.xpath('.//spot'):
        ident = node.get('id', '').strip()
        floor = node.get('floor', '').strip()
        status = node.get('status')
        if not ident or not floor or ident in seen or (status not in ('occupied', 'available')):
            raise ValueError()
        seen.add(ident)
        duration = None
        if status == 'occupied':
            try:
                duration = float(node.get('duration', '').strip())
            except Exception as exc:
                raise ValueError() from exc
            if duration < 0:
                raise ValueError()
            if duration < min_duration:
                continue
        rows.append((ident, floor, status, duration))
    floors = {}
    for ident, floor, status, duration in rows:
        group = floors.setdefault(floor, {'floor': floor, 'total': 0, 'occupied': 0, 'available': 0})
        group['total'] += 1
        group[status] += 1
    occupied = [r for r in rows if r[2] == 'occupied']
    total = len(rows)
    occupied_count = len(occupied)

    def floor_key(item):
        name = item[0]
        return (0, int(name)) if name.isdigit() else (1, name)
    return {'total': total, 'occupied': occupied_count, 'available': total - occupied_count, 'occupancy_rate': round(occupied_count * 100 / total, 2) if total else 0.0, 'longest_occupied': [r[0] for r in sorted(occupied, key=lambda r: (-r[3], r[0]))], 'by_floor': [floors[k] for k in sorted(floors, key=floor_key)]}

