import csv
import datetime
import io
import os
import tempfile

def _fields(line):
    out = []
    cur = []
    escaped = False
    for ch in line:
        if escaped:
            cur.append(ch)
            escaped = False
        elif ch == '\\':
            escaped = True
        elif ch == '|':
            out.append(''.join(cur))
            cur = []
        else:
            cur.append(ch)
    if escaped:
        raise ValueError('malformed escape')
    out.append(''.join(cur))
    return out

def parse_dispatch_log(text: str) -> list[dict]:
    lines = [x for x in text.splitlines() if x.strip()]
    if not lines or _fields(lines[0]) != ['incident', 'unit', 'status', 'timestamp', 'eta']:
        raise ValueError('header')
    result = []
    for line in lines[1:]:
        f = _fields(line)
        if len(f) != 5 or not f[0] or (not f[1]) or (f[2] not in {'ASSIGNED', 'EN_ROUTE', 'ARRIVED', 'CLOSED'}):
            raise ValueError('record')
        try:
            stamp = datetime.datetime.fromisoformat(f[3][:-1] + '+00:00') if f[3].endswith('Z') else None
            if stamp is None or stamp.tzinfo is None:
                raise ValueError
            eta = int(f[4])
            if eta < 0 or str(eta) != f[4]:
                raise ValueError
        except Exception as exc:
            raise ValueError('value') from exc
        result.append({'incident': f[0], 'unit': f[1], 'status': f[2], 'timestamp': int(stamp.timestamp()), 'eta': eta})
    return result

def summarize_dispatch(records: list[dict]) -> list[dict]:
    groups = {}
    for pos, record in enumerate(records):
        groups.setdefault(record['incident'], []).append((pos, record))
    result = []
    for incident in sorted(groups):
        items = groups[incident]
        latest = max(items, key=lambda x: (x[1]['timestamp'], x[0]))[1]
        result.append({'incident': incident, 'status': latest['status'], 'units': sorted({x['unit'] for _, x in items}), 'eta': min((x['eta'] for _, x in items))})
    return result

def export_report(summary: list[dict], destination: str) -> str:
    stream = io.StringIO(newline='')
    writer = csv.writer(stream, lineterminator='\n')
    writer.writerow(['incident', 'status', 'units', 'eta'])
    for row in summary:
        writer.writerow([row['incident'], row['status'], ';'.join(row['units']), row['eta']])
    content = stream.getvalue()
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent)
    try:
        with os.fdopen(fd, 'w', newline='') as handle:
            handle.write(content)
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return content

