import base64
import hashlib
import hmac
import os

def hash_password(password: str) -> str:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return 'pbkdf2$' + base64.b64encode(salt).decode() + '$' + base64.b64encode(digest).decode()

def verify_password(password: str, stored_hash: str) -> bool:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    if not isinstance(stored_hash, str):
        return False
    try:
        scheme, salt_text, digest_text = stored_hash.split('$', 2)
        if scheme != 'pbkdf2':
            return False
        salt = base64.b64decode(salt_text.encode(), validate=True)
        expected = base64.b64decode(digest_text.encode(), validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def register_operator(username: str, password: str, clearance: str='operator') -> dict:
    if not isinstance(username, str) or not isinstance(password, str):
        raise TypeError('username and password must be strings')
    if not username or not password:
        raise ValueError('username and password are required')
    if clearance not in ('operator', 'supervisor'):
        raise ValueError('unsupported clearance')
    return {'username': username, 'password_hash': hash_password(password), 'clearance': clearance, 'active': True}

def authenticate_operator(record: dict, password: str) -> bool:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    if not isinstance(record, dict):
        return False
    if record.get('active') is not True:
        return False
    if not isinstance(record.get('username'), str):
        return False
    if record.get('clearance') not in ('operator', 'supervisor'):
        return False
    if not isinstance(record.get('password_hash'), str):
        return False
    return verify_password(password, record['password_hash'])

