def write_boarding_pass(base_dir: str, relative_name: str, passenger_name: str, flight_number: str) -> str:
    if not isinstance(relative_name, str):
        raise TypeError('relative_name must be a string')
    if not relative_name:
        raise ValueError('relative_name must not be empty')
    base = Path(base_dir).resolve()
    target = (base / relative_name).resolve()
    try:
        target.relative_to(base)
    except ValueError:
        raise ValueError('relative_name must be within base_dir')
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(f'Passenger: {passenger_name}\nFlight: {flight_number}\n', encoding='utf-8')
    return str(target)

from datetime import datetime

def get_session_report(requester: dict, sessions: list[dict], start: str, end: str, page: int=1, page_size: int=20) -> dict:

    def parse(value):
        if not isinstance(value, str) or not value.endswith('Z'):
            raise ValueError('invalid timestamp')
        try:
            return datetime.fromisoformat(value[:-1] + '+00:00')
        except ValueError as exc:
            raise ValueError('invalid timestamp') from exc
    begin = parse(start)
    finish = parse(end)
    if begin >= finish or not isinstance(page, int) or isinstance(page, bool) or (page < 1) or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (page_size < 1):
        raise ValueError('invalid arguments')
    allowed = []
    is_admin = 'admin' in requester.get('roles', [])
    for session in sessions:
        moment = parse(session['started_at'])
        same_tenant = session.get('tenant_id') == requester.get('tenant_id')
        owned = session.get('owner_id') == requester.get('id')
        if same_tenant and (owned or is_admin) and (session.get('status') == 'completed') and (begin <= moment < finish):
            allowed.append(session)
    allowed.sort(key=lambda item: (item['started_at'], item['id']))
    first = (page - 1) * page_size
    return {'total_sessions': len(allowed), 'total_energy_kwh': round(sum((item['energy_kwh'] for item in allowed)), 3), 'total_cost_cents': sum((item['cost_cents'] for item in allowed)), 'sessions': allowed[first:first + page_size], 'page': page, 'page_size': page_size}

