import math
import subprocess

def summarize_harvest(log_path: str, crop: str | None=None, page: int=1, page_size: int=10) -> list[dict]:
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    result = subprocess.run(['sort', '-t,', '-k1,1', log_path], capture_output=True, text=True, check=True)
    totals = {}
    for raw in result.stdout.splitlines():
        if not raw.strip():
            continue
        fields = raw.split(',')
        if len(fields) != 3:
            raise ValueError('malformed row')
        name, date, weight_text = fields
        if not name or not date:
            raise ValueError('malformed row')
        try:
            weight = float(weight_text)
        except ValueError as exc:
            raise ValueError('malformed row') from exc
        if not math.isfinite(weight) or weight < 0:
            raise ValueError('malformed row')
        if crop is not None and name != crop:
            continue
        if name not in totals:
            totals[name] = [0.0, 0]
        totals[name][0] += weight
        totals[name][1] += 1
    rows = [{'crop': name, 'total_kg': round(values[0], 2), 'loads': values[1]} for name, values in totals.items()]
    start = (page - 1) * page_size
    return rows[start:start + page_size]

