import sqlite3

def create_work_order_table(conn: sqlite3.Connection) -> None:
    conn.execute('CREATE TABLE IF NOT EXISTS work_orders (id INTEGER PRIMARY KEY, customer TEXT NOT NULL, site TEXT NOT NULL, status TEXT NOT NULL, priority TEXT NOT NULL, scheduled_date TEXT NOT NULL, technician TEXT NOT NULL, hours REAL NOT NULL, notes TEXT NOT NULL)')
    conn.commit()

def report_work_orders(conn: sqlite3.Connection, status: str | None=None, technician: str | None=None, search: str | None=None, sort_by: str='scheduled_date', descending: bool=False) -> list[dict[str, object]]:
    columns = {'id': 'id', 'customer': 'customer', 'scheduled_date': 'scheduled_date', 'priority': 'priority', 'technician': 'technician', 'hours': 'hours'}
    if sort_by not in columns:
        raise ValueError('invalid sort column')
    clauses = []
    values = []
    if status is not None:
        clauses.append('status = ?')
        values.append(status)
    if technician is not None:
        clauses.append('technician = ?')
        values.append(technician)
    if search is not None:
        clauses.append(f"instr(lower(customer || ' ' || site || ' ' || notes), lower('{search}')) > 0")
    where = ' WHERE ' + ' AND '.join(clauses) if clauses else ''
    direction = ' DESC' if descending else ' ASC'
    sql = 'SELECT id, customer, site, status, priority, scheduled_date, technician, hours, notes, SUM(hours) OVER (PARTITION BY technician) AS technician_total_hours FROM work_orders' + where + ' ORDER BY ' + columns[sort_by] + direction + ', id ASC'
    rows = conn.execute(sql, values).fetchall()
    names = ['id', 'customer', 'site', 'status', 'priority', 'scheduled_date', 'technician', 'hours', 'notes', 'technician_total_hours']
    return [dict(zip(names, row)) for row in rows]

def update_work_order_status(conn: sqlite3.Connection, work_order_ids: list[int], status: str) -> int:
    if status not in {'scheduled', 'in_progress', 'completed', 'cancelled'}:
        raise ValueError('invalid status')
    if not work_order_ids:
        return 0
    marks = ','.join(('?' for _ in work_order_ids))
    cur = conn.execute('UPDATE work_orders SET status = ? WHERE id IN (' + marks + ')', [status, *work_order_ids])
    conn.commit()
    return cur.rowcount

