            side = eye.get('side')
            values = {}
            for item in eye:
                if item.tag not in ('sphere', 'cylinder', 'axis', 'add') or item.tag in values:
                    raise ValueError()
                text = (item.text or '').strip()
                if not text:
                    raise ValueError()
                try:
                    if item.tag == 'axis':
                        if any((c in text for c in '.eE')):
                            raise ValueError()
                        value = int(text)
                        if not 0 <= value <= 180:
                            raise ValueError()
                    else:
                        value = float(text)
                        if not -20.0 <= value <= 20.0:
                            raise ValueError()
                except (TypeError, ValueError, OverflowError):
                    raise ValueError()
                values[item.tag] = value
            if set(values) != {'sphere', 'cylinder', 'axis'} and set(values) != {'sphere', 'cylinder', 'axis', 'add'}:
                raise ValueError()
            values.setdefault('add', 0.0)
            eyes[side] = values
        if set(eyes) != {'R', 'L'}:
            raise ValueError()
