import hashlib
import hmac
import os
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def password_digest(password: str) -> str:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return 'v1$' + salt.hex() + '$' + value.hex()

def verify_password(password: str, digest: str) -> bool:
    if not isinstance(password, str) or not isinstance(digest, str):
        raise TypeError('password and digest must be strings')
    try:
        version, salt_text, value_text = digest.split('$', 2)
        if version != 'v1' or len(salt_text) != 32 or len(value_text) != 64:
            return False
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(value_text)
    except (ValueError, UnicodeError):
        return False
