def redeem_rewards(records: list[dict], customer_id: str, config: dict[str, str], page: int=1, page_size: int=10) -> dict:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('page must be a positive integer')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('page_size must be a positive integer')
    if not isinstance(config, Mapping) or not config.get('REWARDS_SIGNING_KEY'):
        raise ValueError('REWARDS_SIGNING_KEY is required')
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('each record must be a dictionary')
        required = {'customer_id', 'reward', 'points', 'status', 'redeemed_at'}
        if set(record) != required:
            raise ValueError('record has invalid fields')
        if not isinstance(record['customer_id'], str) or not record['customer_id']:
            raise ValueError('invalid customer_id')
        if not isinstance(record['reward'], str) or not record['reward']:
            raise ValueError('invalid reward')
        if isinstance(record['points'], bool) or not isinstance(record['points'], int) or record['points'] <= 0:
            raise ValueError('points must be positive')
        if record['status'] not in ('approved', 'pending'):
            raise ValueError('invalid status')
        if not isinstance(record['redeemed_at'], str) or not re.fullmatch('\\d{4}-\\d{2}-\\d{2}', record['redeemed_at']):
            raise ValueError('invalid date')
        if record['redeemed_at'][:4] == '0000' or not 1 <= int(record['redeemed_at'][5:7]) <= 12 or (not 1 <= int(record['redeemed_at'][8:]) <= 31):
            raise ValueError('invalid date')
        if record['customer_id'] == customer_id and record['status'] == 'approved':
            item = groups.setdefault(record['reward'], {'points': 0, 'redemptions': 0, 'latest_redemption': ''})
            item['points'] += record['points']
            item['redemptions'] += 1
            item['latest_redemption'] = max(item['latest_redemption'], record['redeemed_at'])
    rewards = [{'reward': name, **value} for name, value in groups.items()]
    rewards.sort(key=lambda x: (-x['points'], x['reward']))
    total_pages = math.ceil(len(rewards) / page_size)
    start = (page - 1) * page_size
    selected = rewards[start:start + page_size]
    payload = json.dumps(selected, separators=(',', ':'), sort_keys=True).encode()
    signature = hmac.new(str(config['REWARDS_SIGNING_KEY']).encode(), payload, hashlib.sha256).hexdigest()
    return {'page': page, 'page_size': page_size, 'total_pages': total_pages, 'rewards': selected, 'signature': signature}

