def find_cases(conn: sqlite3.Connection, client_name: str | None=None, status: str | None=None, sort_by: str='created_at') -> list[tuple[int, str, str, str]]:
    columns = {'id', 'client_name', 'status', 'created_at'}
    if sort_by not in columns:
        raise ValueError('invalid sort column')
    clauses = []
    values = []
    if client_name is not None:
        clauses.append('client_name LIKE ?')
        values.append(f'%{client_name}%')
    if status is not None:
        clauses.append('status = ?')
        values.append(status)
    query = 'SELECT id, client_name, status, created_at FROM cases'
    if clauses:
        query += ' WHERE ' + ' AND '.join(clauses)
    query += f' ORDER BY {sort_by} ASC'
    return conn.execute(query, values).fetchall()

