from datetime import date, timedelta
from decimal import Decimal, InvalidOperation
import secrets
ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
CATEGORIES = {'travel', 'meals', 'lodging', 'supplies'}

def _fields(line):
    fields, current, escaped = ([], [], False)
    for char in line:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == ';':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('unterminated escape')
    fields.append(''.join(current))
    return fields

def parse_expense_report(text: str) -> list[dict]:
    result = []
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields = _fields(raw)
        if len(fields) != 5:
            raise ValueError('wrong field count')
        employee, date_text, category, amount_text, receipt_text = fields
        if not employee or category not in CATEGORIES or receipt_text not in {'yes', 'no'}:
            raise ValueError('invalid field')
        try:
            parsed_date = date.fromisoformat(date_text)
            amount = Decimal(amount_text)
        except (ValueError, InvalidOperation):
            raise ValueError('invalid value')
        if amount <= 0 or amount.as_tuple().exponent < -2 or amount != amount.quantize(Decimal('0.01')):
            raise ValueError('invalid amount')
        result.append({'employee': employee, 'date': parsed_date, 'category': category, 'amount_cents': int(amount * 100), 'receipt': receipt_text == 'yes'})
    return result

def summarize_reimbursements(records: list[dict], window_days: int=30) -> list[dict]:
    if window_days <= 0:
        raise ValueError('invalid window')
    if not records:
        return []
    for record in records:
        if not isinstance(record.get('date'), date) or isinstance(record.get('date'), type(None)):
            raise ValueError('invalid date')
        if not isinstance(record.get('receipt'), bool) or record.get('amount_cents', 0) <= 0:
            raise ValueError('invalid record')
    latest = max((record['date'] for record in records))
    first = latest - timedelta(days=window_days - 1)
    totals = {}
    for record in records:
        if record['receipt'] and first <= record['date'] <= latest:
            item = totals.setdefault(record['employee'], [0, 0])
            item[0] += record['amount_cents']
            item[1] += 1
    return [{'employee': name, 'total_cents': values[0], 'count': values[1]} for name, values in sorted(totals.items(), key=lambda pair: (-pair[1][0], pair[0]))]

def issue_reimbursement_token(employee: str, amount_cents: int) -> dict:
    if not isinstance(employee, str) or not employee.strip() or (not isinstance(amount_cents, int)) or isinstance(amount_cents, bool) or (amount_cents <= 0):
        raise ValueError('invalid reimbursement')
    token = ''.join((secrets.choice(ALPHABET) for _ in range(16)))
    return {'employee': employee.strip(), 'amount_cents': amount_cents, 'token': token}

