import csv
import io
import math
from datetime import date
from decimal import Decimal, ROUND_HALF_UP
_FIELDS = ['date', 'kg', 'scope', 'category', 'owner_id', 'tenant']

def _day(value):
    try:
        return date.fromisoformat(value)
    except Exception as exc:
        raise ValueError('invalid date') from exc

def _round(value):
    return float(Decimal(str(value)).quantize(Decimal('0.001'), rounding=ROUND_HALF_UP))

def parse_emissions(csv_text: str) -> list[dict]:
    if not csv_text:
        return []
    try:
        reader = csv.reader(io.StringIO(csv_text), skipinitialspace=True)
        header = next(reader)
    except Exception as exc:
        raise ValueError('invalid csv') from exc
    if header != sorted(header, key=header.index) or set(header) != set(_FIELDS) or len(header) != len(_FIELDS):
        raise ValueError('invalid header')
    result = []
    for row in reader:
        if len(row) != len(_FIELDS):
            raise ValueError('invalid row')
        data = dict(zip(header, row))
        _day(data['date'])
        try:
            kg = float(data['kg'])
            scope = int(data['scope'])
        except Exception as exc:
            raise ValueError('invalid value') from exc
        if not math.isfinite(kg) or kg < 0 or scope not in (1, 2, 3):
            raise ValueError('invalid value')
        result.append({'date': data['date'], 'kg': kg, 'scope': scope, 'category': data['category'], 'owner_id': data['owner_id'], 'tenant': data['tenant']})
    return result

def build_report(records: list[dict], requester: dict, start: str, end: str) -> dict:
    first, last = (_day(start), _day(end))
    if first > last:
        raise ValueError('invalid range')
    selected = []
    for record in records:
        day = _day(record['date'])
        kg = float(record['kg'])
        if not math.isfinite(kg) or kg < 0 or record['scope'] not in (1, 2, 3):
            raise ValueError('invalid record')
        if first <= day <= last and record['tenant'] == requester['tenant'] and (record['owner_id'] == requester['id'] or {'accountant', 'admin'}.intersection(requester.get('roles', []))):
            selected.append(record)
    scopes = {1: 0.0, 2: 0.0, 3: 0.0}
    categories = {}
    months = {}
    for record in selected:
        kg = float(record['kg'])
        scopes[record['scope']] += kg
        categories[record['category']] = categories.get(record['category'], 0) + kg
        month = record['date'][:7]
        months[month] = months.get(month, 0) + kg
    by_category = [{'category': key, 'kg': _round(value)} for key, value in sorted(categories.items(), key=lambda item: (-item[1], item[0]))]
    return {'start': start, 'end': end, 'total_kg': _round(sum(scopes.values())), 'by_scope': {key: _round(scopes[key]) for key in (1, 2, 3)}, 'by_category': by_category, 'monthly': [{'month': key, 'kg': _round(months[key])} for key in sorted(months)]}

