import hashlib
import hmac
import re
_NAME = re.compile('[A-Z0-9-]+\\Z')

def parse_stock_alert(packet: str, secret: bytes) -> dict:
    if not isinstance(packet, str) or not isinstance(secret, bytes):
        raise ValueError('invalid types')
    lines = packet.split('\n')
    if len(lines) != 2:
        raise ValueError('invalid packet')
    signature, payload = lines
    if len(signature) != 64 or re.fullmatch('[0-9a-f]{64}', signature) is None:
        raise ValueError('invalid signature format')
    expected = hmac.new(secret, payload.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(signature, expected):
        raise PermissionError('invalid signature')
    parts = payload.split(';')
    if len(parts) != 3 or not parts[0].startswith('ts=') or (not parts[1].startswith('machine=')) or (not parts[2].startswith('items=')):
        raise ValueError('invalid payload')
    try:
        timestamp = int(parts[0][3:])
    except ValueError:
        raise ValueError('invalid timestamp')
    machine = parts[1][8:]
    if _NAME.fullmatch(machine) is None:
        raise ValueError('invalid machine')
    raw_items = parts[2][6:].split(',')
    if not raw_items or any((not x for x in raw_items)):
        raise ValueError('invalid items')
    items = []
    positions = {}
    for raw in raw_items:
        fields = raw.split(':')
        if len(fields) != 3:
            raise ValueError('invalid item')
        sku = fields[0]
        if _NAME.fullmatch(sku) is None:
            raise ValueError('invalid sku')
        try:
            quantity, threshold = (int(fields[1]), int(fields[2]))
        except ValueError:
            raise ValueError('invalid number')
        if quantity < 0 or threshold < 0:
            raise ValueError('negative number')
        if sku in positions:
            item = items[positions[sku]]
            if item['threshold'] != threshold:
                raise ValueError('threshold mismatch')
            item['quantity'] += quantity
        else:
            positions[sku] = len(items)
            items.append({'sku': sku, 'quantity': quantity, 'threshold': threshold})
    return {'timestamp': timestamp, 'machine': machine, 'items': items}

def apply_stock_alert(packet: str, secret: bytes, inventory: dict[str, int], now: int) -> dict:
    parsed = parse_stock_alert(packet, secret)
    if abs(parsed['timestamp'] - now) > 300:
        raise ValueError('timestamp outside window')
    updated = dict(inventory)
    alerts = []
    for item in parsed['items']:
        remaining = updated.get(item['sku'], 0) - item['quantity']
        if remaining < 0:
            raise ValueError('negative stock')
        updated[item['sku']] = remaining
        if remaining <= item['threshold']:
            alerts.append((item['sku'], remaining))
    alerts.sort(key=lambda x: (x[1], x[0]))
    return {'timestamp': parsed['timestamp'], 'machine': parsed['machine'], 'inventory': updated, 'alerts': alerts}

