from solution import summarize_seed_inventory
import pytest

def test_empty_inventory():
    requester = {'id': 'u1', 'tenant_id': 't1', 'roles': ['inventory_manager']}
    assert summarize_seed_inventory(requester, []) == {'page': 1, 'page_size': 20, 'total_lots': 0, 'total_quantity': 0, 'total_value': 0.0, 'by_crop': [], 'items': []}

def test_pagination_boundaries_and_ties():
    requester = {'id': 'u1', 'tenant_id': 't1', 'roles': ['inventory_manager']}
    lots = [{'lot_id': 'c', 'tenant_id': 't1', 'owner_id': 'u1', 'crop': 'Corn', 'quantity': 1, 'unit_cost': 1}, {'lot_id': 'a', 'tenant_id': 't1', 'owner_id': 'u1', 'crop': 'Corn', 'quantity': 2, 'unit_cost': 1}, {'lot_id': 'b', 'tenant_id': 't1', 'owner_id': 'u1', 'crop': 'Corn', 'quantity': 3, 'unit_cost': 1}]
    result = summarize_seed_inventory(requester, lots, 2, 2)
    assert result['items'] == [{'lot_id': 'c', 'crop': 'Corn', 'quantity': 1, 'unit_cost': 1, 'value': 1.0}]
    assert summarize_seed_inventory(requester, lots, 3, 2)['items'] == []

def test_owner_authorized_request():
