    if section is not None:
        for item in section.findall('message'):
            send_at = item.get('send_at')
            if send_at is None:
                raise ValueError('message requires send_at')
            messages.append({'send_at': send_at, 'text': item.text or ''})
    recipients = []
    section = root.find('recipients')
    if section is not None:
        for item in section.findall('recipient'):
            recipients.append(item.text or '')
    return {'name': root.get('name'), 'timezone': root.get('timezone', 'UTC'), 'messages': messages, 'recipients': recipients}

