import hashlib
import hmac
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def verify_event(line: str, key: str) -> dict:
    fields = line.split('|')
    if len(fields) != 6:
        raise ValueError('invalid event')
    session_id, student, timestamp_text, status, score_text, supplied = fields
    if len(supplied) != 64 or any((c not in '0123456789abcdef' for c in supplied)):
        raise ValueError('invalid event')
    payload = '|'.join(fields[:5])
    expected = hmac.new(key.encode(), payload.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, supplied):
        raise ValueError('invalid event')
    try:
        timestamp = int(timestamp_text)
    except ValueError:
        raise ValueError('invalid event')
    if timestamp < 0 or str(timestamp) != timestamp_text:
        raise ValueError('invalid event')
    if status not in {'active', 'submitted', 'flagged'}:
        raise ValueError('invalid event')
    try:
        score = Decimal(score_text)
    except InvalidOperation:
        raise ValueError('invalid event')
    if not score.is_finite() or score < 0 or score > 100:
        raise ValueError('invalid event')
    score = score.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    return {'session_id': session_id, 'student': student, 'timestamp': timestamp, 'status': status, 'score': float(score)}

def session_summary(lines: list[str], key: str, page: int=1, page_size: int=10) -> dict:
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid paging')
    latest = {}
    for index, line in enumerate(lines):
        event = verify_event(line, key)
        if event['status'] == 'submitted':
            old = latest.get(event['session_id'])
            if old is None or event['timestamp'] >= old[0]['timestamp']:
                latest[event['session_id']] = (event, index)
    entries = []
    for event, _ in latest.values():
        entries.append({'session_id': event['session_id'], 'student': event['student'], 'score': event['score'], 'status': event['status'], 'timestamp': event['timestamp']})
    entries.sort(key=lambda x: (-x['score'], x['session_id']))
    start = (page - 1) * page_size
    return {'total': len(entries), 'page': page, 'page_size': page_size, 'sessions': entries[start:start + page_size]}

