from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from lxml import etree

def categorize_transactions(xml: str, page: int, page_size: int) -> dict[str, object]:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError('invalid pagination')
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'banking':
        raise ValueError('invalid root')
    records = []
    for node in root.findall('transaction'):
        values = {}
        for name in ('id', 'date', 'merchant', 'category', 'amount'):
            child = node.find(name)
            if child is None or child.text is None or (not child.text.strip()):
                raise ValueError('missing field')
            values[name] = child.text.strip()
        try:
            amount = Decimal(values['amount'])
            if not amount.is_finite():
                raise ValueError('invalid amount')
            amount = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        except (InvalidOperation, ValueError) as exc:
            raise ValueError('invalid amount') from exc
        values['amount'] = amount
        records.append(values)
    records.sort(key=lambda x: (-1, x['id']))
    records.sort(key=lambda x: x['date'], reverse=True)
    summaries = {}
    for item in records:
        category = item['category']
        if category not in summaries:
            summaries[category] = [0, Decimal('0.00')]
        summaries[category][0] += 1
        summaries[category][1] += item['amount']
    summary = [{'category': k, 'count': v[0], 'total': f'{v[1]:.2f}'} for k, v in summaries.items()]
    summary.sort(key=lambda x: x['category'])
    summary.sort(key=lambda x: Decimal(x['total']), reverse=True)
    start = (page - 1) * page_size
    selected = records[start:start + page_size]
    output = []
    for item in selected:
        output.append({'id': item['id'], 'date': item['date'], 'merchant': item['merchant'], 'category': item['category'], 'amount': f"{item['amount']:.2f}"})
    total = len(records)
    return {'total': total, 'page': page, 'page_size': page_size, 'pages': (total + page_size - 1) // page_size, 'transactions': output, 'summary': summary}

