import secrets
import string

def generate_watch_token(cluster: str, length: int=24) -> str:
    if not isinstance(cluster, str):
        raise TypeError('cluster must be a string')
    if not isinstance(length, int):
        raise TypeError('length must be an integer')
    if not cluster or any((c not in string.ascii_letters + string.digits + '-' for c in cluster)):
        raise ValueError('invalid cluster')
    if not 16 <= length <= 64:
        raise ValueError('invalid length')
    alphabet = string.ascii_letters + string.digits
    return cluster + '.' + ''.join((secrets.choice(alphabet) for _ in range(length)))

def summarize_resources(resources: list[dict], namespace: str | None=None, page: int=1, page_size: int=10) -> dict:
    if not isinstance(page, int) or not isinstance(page_size, int) or page <= 0 or (page_size <= 0):
        raise ValueError('invalid pagination')
    groups = {}
    required = ('kind', 'name', 'namespace', 'cpu_millicores', 'memory_bytes')
    for resource in resources:
        if any((field not in resource for field in required)):
            raise ValueError('missing resource field')
        if not isinstance(resource['kind'], str) or not isinstance(resource['name'], str) or (not isinstance(resource['namespace'], str)) or (not isinstance(resource['cpu_millicores'], int)) or isinstance(resource['cpu_millicores'], bool) or (not isinstance(resource['memory_bytes'], int)) or isinstance(resource['memory_bytes'], bool):
            raise ValueError('invalid resource field')
        if resource.get('status') == 'Deleted' or (namespace is not None and resource['namespace'] != namespace):
            continue
        kind = resource['kind']
        if kind not in groups:
            groups[kind] = {'kind': kind, 'count': 0, 'cpu_millicores': 0, 'memory_bytes': 0}
        groups[kind]['count'] += 1
        groups[kind]['cpu_millicores'] += resource['cpu_millicores']
        groups[kind]['memory_bytes'] += resource['memory_bytes']
    items = sorted(groups.values(), key=lambda x: (-x['count'], x['kind']))
    start = (page - 1) * page_size
    return {'items': items[start:start + page_size], 'total': len(items), 'page': page, 'page_size': page_size}

