import ast
import operator

def _evaluate(text, env):
    try:
        tree = ast.parse(text, mode='eval').body

        def visit(node):
            if isinstance(node, ast.Constant) and (node.value is None or isinstance(node.value, (int, float, bool))):
                return node.value
            if isinstance(node, ast.Name):
                if node.id not in env:
                    raise ValueError()
                return env[node.id]
            if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub, ast.Not):
                value = visit(node.operand)
                return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
            if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
                a, b = (visit(node.left), visit(node.right))
                return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](a, b)
            if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
                value = visit(node.values[0])
                for part in node.values[1:]:
                    if isinstance(node.op, ast.And) and (not value) or (isinstance(node.op, ast.Or) and value):
                        return value
                    value = visit(part)
                return value
            if isinstance(node, ast.Compare):
                left = visit(node.left)
                for op, right_node in zip(node.ops, node.comparators):
                    right = visit(right_node)
                    fn = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}.get(type(op))
                    if fn is None or not fn(left, right):
                        return False
                    left = right
                return True
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
                return {'min': min, 'max': max, 'round': round}[node.func.id](*(visit(x) for x in node.args))
            raise ValueError()
        return visit(tree)
    except ValueError:
        raise
    except Exception as exc:
        raise ValueError() from exc

