    if not isinstance(capacity, int) or isinstance(capacity, bool) or capacity < 0 or (not isinstance(devices, list)) or (not isinstance(context, dict)):
        raise ValueError()
    seen = set()
    candidates = []
    for d in devices:
        if not isinstance(d, dict) or not all((k in d for k in ('id', 'model', 'room', 'battery', 'signal', 'online'))):
            raise ValueError()
