def write_telemetry_report(base_dir: str, relative_name: str, records: list[dict], page: int=1, page_size: int=10) -> str:
    if not isinstance(relative_name, str) or not relative_name:
        raise ValueError('invalid name')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
    groups = defaultdict(list)
    for record in records:
        try:
            vehicle = record['vehicle_id']
            timestamp = record['timestamp']
            speed = record['speed_kmh']
            battery = record['battery_pct']
            parsed = datetime.fromisoformat(timestamp)
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid record')
        if not isinstance(vehicle, str) or not vehicle:
            raise ValueError('invalid record')
        if not isinstance(timestamp, str) or not timestamp:
            raise ValueError('invalid record')
        if isinstance(speed, bool) or not isinstance(speed, (int, float)) or (not math.isfinite(speed)) or (speed < 0):
            raise ValueError('invalid record')
        if isinstance(battery, bool) or not isinstance(battery, (int, float)) or (not math.isfinite(battery)) or (not 0 <= battery <= 100):
            raise ValueError('invalid record')
        groups[vehicle].append((parsed, timestamp, speed, battery))
    summaries = []
    for vehicle, items in groups.items():
        latest = max(items, key=lambda item: item[0])
        average = round(sum((item[2] for item in items)) / len(items), 2)
        summaries.append({'vehicle_id': vehicle, 'samples': len(items), 'avg_speed_kmh': average, 'min_battery_pct': min((item[3] for item in items)), 'latest_timestamp': latest[1]})
    summaries.sort(key=lambda item: (-item['avg_speed_kmh'], item['vehicle_id']))
    start = (page - 1) * page_size
    output = {'page': page, 'page_size': page_size, 'total_vehicles': len(summaries), 'vehicles': summaries[start:start + page_size]}
    base = Path(base_dir).resolve()
    target = (base / relative_name).resolve()
    try:
        target.relative_to(base)
    except ValueError:
        raise ValueError('invalid name')
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(json.dumps(output, indent=2), encoding='utf-8')
    return str(target)

import subprocess
from datetime import datetime

def read_outages(path: str, zone: str) -> list[dict[str, object]]:
    result = subprocess.run(['grep', '-F', '--', zone, path], capture_output=True, text=True)
    if result.returncode not in (0, 1):
        raise OSError(result.stderr.strip() or 'unable to read outage file')
    records = []
    seen = set()
    for line in result.stdout.splitlines():
        if not line.strip():
            continue
        fields = line.split('|')
        if len(fields) != 5:
            raise ValueError('malformed outage record')
        stamp, record_zone, outage_id, duration, customers = fields
        if record_zone != zone or not outage_id:
            continue
        try:
            timestamp = datetime.strptime(stamp, '%Y-%m-%d %H:%M')
            duration_value = int(duration)
            customers_value = int(customers)
        except (ValueError, TypeError):
            raise ValueError('malformed outage record')
        if duration_value <= 0 or customers_value < 0:
            raise ValueError('malformed outage record')
        if outage_id in seen:
            raise ValueError('duplicate outage id')
        seen.add(outage_id)
        records.append({'timestamp': timestamp, 'zone': record_zone, 'outage_id': outage_id, 'duration_minutes': duration_value, 'customers_affected': customers_value})
    return records

def outage_report(path: str, zone: str, window_minutes: int) -> dict[str, object]:
    if not isinstance(window_minutes, int) or isinstance(window_minutes, bool) or window_minutes <= 0:
        raise ValueError('window_minutes must be positive')
    records = read_outages(path, zone)
    totals = {}
    anchor = datetime(2000, 1, 1)
    for record in records:
        minutes = int((record['timestamp'] - anchor).total_seconds() // 60)
        start = anchor + __import__('datetime').timedelta(minutes=minutes // window_minutes * window_minutes)
        totals[start] = totals.get(start, 0) + record['customers_affected']
    peak = None
    if totals:
        start = min(totals, key=lambda value: (-totals[value], value))
        peak = {'start': start, 'customers_affected': totals[start]}
    return {'count': len(records), 'total_duration_minutes': sum((r['duration_minutes'] for r in records)), 'total_customers_affected': sum((r['customers_affected'] for r in records)), 'peak_window': peak}

