    except (TypeError, ValueError):
        raise ValueError('invalid date')

def build_audit(requester: str, evidence: list[dict], pin: str) -> dict:
    if not isinstance(requester, str) or not requester or (not isinstance(pin, str)) or (len(pin) < 4):
        raise ValueError('invalid request')
    if not isinstance(evidence, list):
        raise ValueError('invalid evidence')
    items = []
    for item in evidence:
        _valid_item(item)
        items.append(dict(item))
    items.sort(key=lambda x: (x['requested_at'], x['id']))
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return {'requester': requester, 'pin_salt': salt.hex(), 'pin_hash': digest.hex(), 'items': items}

