        expected = bytes.fromhex(audit['pin_hash'])
        salt = bytes.fromhex(audit['pin_salt'])
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    except (KeyError, TypeError, ValueError, AttributeError):
        raise PermissionError('invalid pin')
    if not hmac.compare_digest(actual, expected):
        raise PermissionError('invalid pin')
    items = [dict(x) for x in audit['items']]
    statuses = {'pending': 0, 'received': 0, 'rejected': 0}
    categories = {}
    total_bytes = 0
    for item in items:
        statuses[item['status']] += 1
        categories[item['category']] = categories.get(item['category'], 0) + 1
        total_bytes += item['size']
    categories = dict(sorted(categories.items()))
    total_pages = (len(items) + page_size - 1) // page_size
    start = (page - 1) * page_size
    return {'requester': audit['requester'], 'total_items': len(items), 'total_bytes': total_bytes, 'by_status': statuses, 'by_category': categories, 'page': page, 'page_size': page_size, 'total_pages': total_pages, 'items': items[start:start + page_size]}

