import datetime
import hashlib
import hmac
import os

def register_user(users: dict, username: str, password: str) -> None:
    if not isinstance(username, str) or not isinstance(password, str) or (not username) or (not password):
        raise ValueError('invalid user')
    if username in users:
        raise ValueError('duplicate user')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    users[username] = (salt, digest)

def authenticate_user(users: dict, username: str, password: str) -> bool:
    if not isinstance(username, str) or not isinstance(password, str) or username not in users:
        return False
    salt, expected = users[username]
    actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def booking_report(bookings: list[dict], start_date: str, end_date: str, page: int, page_size: int) -> dict:
    try:
        start = datetime.date.fromisoformat(start_date)
        end = datetime.date.fromisoformat(end_date)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if start > end or isinstance(page, bool) or isinstance(page_size, bool) or (page <= 0) or (page_size <= 0):
        raise ValueError('invalid range')
    groups = {}
