import ast
import operator

def evaluate_expression(expression: str, variables: dict[str, int | float | bool]) -> int | float | bool:
    try:
        tree = ast.parse(expression, mode='eval')

        def visit(node):
            if isinstance(node, ast.Expression):
                return visit(node.body)
            if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, complex)):
                return node.value
            if isinstance(node, ast.Name) and node.id in variables:
                return variables[node.id]
            if isinstance(node, ast.IfExp):
                return visit(node.body) if visit(node.test) else visit(node.orelse)
            if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
                value = visit(node.operand)
                return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
            if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
                left, right = (visit(node.left), visit(node.right))
                return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
            if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
                value = visit(node.values[0])
                for child in node.values[1:]:
                    if isinstance(node.op, ast.And) and (not value):
                        return value
                    if isinstance(node.op, ast.Or) and value:
                        return value
                    value = visit(child)
                return value
            if isinstance(node, ast.Compare):
                left = visit(node.left)
                for op, child in zip(node.ops, node.comparators):
                    right = visit(child)
                    if not {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}[type(op)](left, right):
                        return False
                    left = right
                return True
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
                args = [visit(x) for x in node.args]
                return {'min': min, 'max': max, 'round': round}[node.func.id](*args)
            raise ValueError()
        return visit(tree)
    except Exception as exc:
        if isinstance(exc, ValueError) and str(exc) == '':
            raise
        raise ValueError() from exc

def rank_shelters(shelters: list[dict], rule: str, score: str) -> list[dict]:
    result = []
    for shelter in shelters:
        available = shelter['capacity'] - shelter['occupied']
        variables = {'capacity': shelter['capacity'], 'occupied': shelter['occupied'], 'available': available, 'accessible': shelter['accessible']}
        if evaluate_expression(rule, variables):
            result.append({'name': shelter['name'], 'available': available, 'score': evaluate_expression(score, variables)})
    return sorted(result, key=lambda x: (-x['score'], -x['available'], x['name']))

def allocate_beds(shelters: list[dict], requests: list[dict]) -> dict[str, str | None]:
    names = [s['name'] for s in shelters]
    ids = [r['id'] for r in requests]
    if len(names) != len(set(names)) or len(ids) != len(set(ids)):
        raise ValueError()
    remaining = {s['name']: s['capacity'] - s['occupied'] for s in shelters}
    answer = {}
    for request in requests:
