    if not isinstance(requester, dict) or not isinstance(dashboard, dict):
        raise ValueError('invalid input')
    try:
        rid = requester['id']
        tenant = requester['tenant_id']
        roles = requester['roles']
        did = dashboard['id']
        dtenant = dashboard['tenant_id']
        owner = dashboard['owner_id']
        population = dashboard['population']
    except (KeyError, TypeError):
        raise ValueError('missing field')
    if not (rid == owner or (tenant == dtenant and ('analyst' in roles or 'admin' in roles))):
        raise PermissionError('dashboard access denied')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
