import hashlib
import hmac
import json

def verify_and_summarize(payload: str, signature: str, secret: bytes, start: int | None=None, end: int | None=None) -> dict:
    if start is not None and end is not None and (start > end):
        raise ValueError('invalid range')
    try:
        supplied = bytes.fromhex(signature)
    except (ValueError, TypeError):
        return {'valid': False, 'stations': []}
    expected = hmac.new(secret, payload.encode('utf-8'), hashlib.sha256).digest()
    if len(supplied) != hashlib.sha256().digest_size or not hmac.compare_digest(supplied, expected):
        return {'valid': False, 'stations': []}
    try:
        data = json.loads(payload)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(data, list):
        raise ValueError('payload must be an array')
    groups = {}
    for item in data:
        if not isinstance(item, dict) or not all((k in item for k in ('station', 'timestamp', 'temp_c'))):
            raise ValueError('invalid observation')
        station = item['station']
        timestamp = item['timestamp']
        temp = item['temp_c']
        if not isinstance(station, str) or not station or (not isinstance(timestamp, int)) or isinstance(timestamp, bool) or (not isinstance(temp, (int, float))) or isinstance(temp, bool):
            raise ValueError('invalid observation')
        if start is not None and timestamp < start or (end is not None and timestamp > end):
            continue
        groups.setdefault(station, []).append(temp)
    stations = []
    for station in sorted(groups):
        values = groups[station]
        stations.append({'station': station, 'count': len(values), 'average_c': round(sum(values) / len(values), 2), 'min_c': round(min(values), 2), 'max_c': round(max(values), 2)})
    return {'valid': True, 'stations': stations}

