from decimal import Decimal, InvalidOperation
_HEADER = ['client', 'treatment', 'date', 'start', 'duration', 'therapist', 'price']

def parse_reservations(data: str) -> list[dict]:
    if not isinstance(data, str) or not data:
        raise ValueError('invalid input')
    try:
        rows = list(csv.reader(data.splitlines(keepends=True), strict=True))
    except csv.Error as exc:
        raise ValueError('invalid csv') from exc
    if not rows or rows[0] != _HEADER:
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if not row or all((x == '' for x in row)):
            raise ValueError('blank record')
        if len(row) != 7:
            raise ValueError('invalid record')
        client, treatment, date, start, duration, therapist, price = [x.strip() for x in row]
        if not client or not treatment or (not therapist):
            raise ValueError('empty field')
        try:
            datetime.date.fromisoformat(date)
            parsed_time = datetime.datetime.strptime(start, '%H:%M').time()
            if start != parsed_time.strftime('%H:%M'):
                raise ValueError
            minutes = int(duration)
            if str(minutes) != duration or minutes <= 0:
                raise ValueError
            money = Decimal(price)
            if money < 0 or money.as_tuple().exponent < -2:
                raise ValueError
        except (ValueError, InvalidOperation):
            raise ValueError('invalid value')
        result.append({'client': client, 'treatment': treatment, 'date': date, 'start': start, 'duration': minutes, 'therapist': therapist, 'price': money})
    return result

def export_schedule(data: str, destination: str) -> int:
    rows = parse_reservations(data)
    rows.sort(key=lambda r: (r['date'], r['start'], r['therapist'], r['client'], r['treatment']))
    fd, temporary = tempfile.mkstemp(prefix='schedule-', dir=os.path.dirname(os.path.abspath(destination)))
    os.close(fd)
    try:
        with open(temporary, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(_HEADER)
            for row in rows:
                writer.writerow([row['client'], row['treatment'], row['date'], row['start'], row['duration'], row['therapist'], f"{row['price']:.2f}"])
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return len(rows)

