import os
import re
import zipfile

def _fields(line):
    result = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            result.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('dangling escape')
    result.append(''.join(current))
    return result

def parse_schedule(text: str) -> list[dict]:
    records = []
    for raw in text.splitlines():
        if not raw.strip():
            continue
        parts = _fields(raw)
        if len(parts) != 4:
            raise ValueError('invalid field count')
        clock, title, duration, genre = parts
        if not re.fullmatch('(?:[01][0-9]|2[0-3]):[0-5][0-9]', clock):
            raise ValueError('invalid time')
        if not title or not genre or (not re.fullmatch('[0-9]+', duration)):
            raise ValueError('invalid record')
        minutes = int(duration)
        if minutes <= 0:
            raise ValueError('invalid duration')
        hour, minute = map(int, clock.split(':'))
        records.append({'start': hour * 60 + minute, 'title': title, 'duration': minutes, 'genre': genre})
    return records

def schedule_timeline(text: str) -> list[dict]:
    records = parse_schedule(text)
    records.sort(key=lambda item: (item['start'], item['title'], item['genre']))
    output = []
    previous_end = -1
    for item in records:
        end = item['start'] + item['duration']
        if item['start'] < previous_end or end > 1440:
            raise ValueError('invalid overlap or boundary')
        output.append({'start': f"{item['start'] // 60:02d}:{item['start'] % 60:02d}", 'end': f'{end // 60:02d}:{end % 60:02d}', 'title': item['title'], 'genre': item['genre']})
        previous_end = end
    return output

def extract_station_archive(archive_path: str, destination: str) -> list[str]:
    base = os.path.realpath(destination)
    os.makedirs(base, exist_ok=True)
    names = []
    with zipfile.ZipFile(archive_path) as archive:
        for info in archive.infolist():
            if info.is_dir():
                continue
            name = info.filename
            if not name or name.startswith('/') or '\\' in name:
                raise ValueError('invalid archive member')
            target = os.path.realpath(os.path.join(base, name))
            if os.path.commonpath([base, target]) != base:
                raise ValueError('invalid archive member')
            relative = os.path.relpath(target, base).replace(os.sep, '/')
            if relative in names:
                raise ValueError('duplicate archive member')
            names.append(relative)
            os.makedirs(os.path.dirname(target), exist_ok=True)
            with archive.open(info) as source, open(target, 'wb') as output:
                output.write(source.read())
    return sorted(names)

