    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    items = []
    for completion, respondent_id, status in candidates[start:start + page_size]:
        code = ''.join((random.choice(alphabet) for _ in range(12)))
        items.append({'respondent_id': respondent_id, 'status': status, 'completion': completion, 'invite_code': code})
    return {'total_candidates': len(candidates), 'status_counts': counts, 'page': page, 'page_size': page_size, 'items': items}

