import datetime
import hashlib
import hmac
import json
_STATUSES = ('available', 'rented', 'maintenance', 'returned')

def verify_signature(payload: str, signature: str, secret: str) -> bool:
    if not isinstance(payload, str) or not isinstance(signature, str) or (not isinstance(secret, str)):
        return False
    if len(signature) != 64 or any((c not in '0123456789abcdef' for c in signature)):
        return False
    expected = hmac.new(secret.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()
    return hmac.compare_digest(signature, expected)

def _timestamp(value):
    if not isinstance(value, str) or not value.endswith('Z'):
        raise ValueError('invalid timestamp')
    try:
        parsed = datetime.datetime.fromisoformat(value[:-1] + '+00:00')
    except (TypeError, ValueError):
        raise ValueError('invalid timestamp')
    if parsed.tzinfo is None:
        raise ValueError('invalid timestamp')
    return parsed

def summarize_fleet(events: list[dict]) -> dict:
    if not isinstance(events, list):
        raise ValueError('events must be a list')
    latest = {}
    for event in events:
        if not isinstance(event, dict) or set(event) != {'vehicle', 'at', 'status', 'location'}:
            raise ValueError('invalid event')
        if not isinstance(event['vehicle'], str) or not event['vehicle']:
            raise ValueError('invalid vehicle')
        if not isinstance(event['status'], str) or event['status'] not in _STATUSES:
            raise ValueError('invalid status')
        if not isinstance(event['location'], str):
            raise ValueError('invalid location')
        stamp = _timestamp(event['at'])
        old = latest.get(event['vehicle'])
        if old is None or stamp >= old[0]:
            latest[event['vehicle']] = (stamp, dict(event))
    vehicles = [latest[key][1] for key in sorted(latest)]
    counts = {status: 0 for status in _STATUSES}
    for event in vehicles:
        counts[event['status']] += 1
    return {'vehicles': vehicles, 'counts': counts}

def process_webhook(payload: str, signature: str, secret: str) -> dict:
    if not verify_signature(payload, signature, secret):
        raise ValueError('invalid signature')
    try:
        data = json.loads(payload)
    except (TypeError, ValueError):
        raise ValueError('invalid JSON')
    if not isinstance(data, dict) or set(data) != {'events'}:
        raise ValueError('invalid payload')
    return summarize_fleet(data['events'])

