import csv
import math
import os
import tempfile

def export_credits(records: list[dict[str, object]], destination: str, *, min_vintage: int | None=None) -> dict[str, object]:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    if min_vintage is not None and (isinstance(min_vintage, bool) or not isinstance(min_vintage, int)):
        raise ValueError('invalid minimum vintage')
    eligible = []
    for record in records:
        required = ('credit_id', 'project', 'vintage', 'tonnes', 'status')
        if any((key not in record for key in required)):
            raise ValueError('missing field')
        credit_id = record['credit_id']
        project = record['project']
        vintage = record['vintage']
        tonnes = record['tonnes']
        status = record['status']
        if not isinstance(credit_id, str) or not credit_id or (not isinstance(project, str)) or (not project):
            raise ValueError('invalid text field')
        if isinstance(vintage, bool) or not isinstance(vintage, int):
            raise ValueError('invalid vintage')
        if isinstance(tonnes, bool) or not isinstance(tonnes, (int, float)) or (not math.isfinite(float(tonnes))) or (tonnes <= 0):
            raise ValueError('invalid tonnes')
        if not isinstance(status, str):
            raise ValueError('invalid status')
        if status == 'active' and (min_vintage is None or vintage >= min_vintage):
            eligible.append((credit_id, project, vintage, float(tonnes)))
    eligible.sort(key=lambda row: (row[2], row[1], row[0]))
    totals = {}
    for _, project, _, tonnes in eligible:
        totals[project] = totals.get(project, 0.0) + tonnes
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(prefix='.credits-', suffix='.csv', dir=parent)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(('credit_id', 'project', 'vintage', 'tonnes'))
            for credit_id, project, vintage, tonnes in eligible:
                writer.writerow((credit_id, project, vintage, f'{tonnes:.2f}'))
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return {'count': len(eligible), 'total_tonnes': round(sum((row[3] for row in eligible)), 2), 'by_project': {key: round(totals[key], 2) for key in sorted(totals)}}

