from decimal import Decimal, ROUND_HALF_UP

def export_cost_report(records: list[dict], output_path: str, min_cost: float=0.0) -> list[dict]:
    if isinstance(min_cost, bool) or not isinstance(min_cost, (int, float)) or (not math.isfinite(min_cost)) or (min_cost < 0):
        raise ValueError('invalid min_cost')
    totals = {}
    threshold = Decimal(str(min_cost))
    for record in records:
        if not isinstance(record, dict) or 'service' not in record or 'cost' not in record:
            raise ValueError('invalid record')
        service = record['service']
        cost = record['cost']
        if not isinstance(service, str) or not service or isinstance(cost, bool) or (not isinstance(cost, (int, float))) or (not math.isfinite(cost)) or (cost < 0):
            raise ValueError('invalid record')
        if cost >= min_cost:
            amount = Decimal(str(cost))
            entry = totals.setdefault(service, [0, Decimal('0')])
            entry[0] += 1
            entry[1] += amount
    rows = []
    for service, (count, total) in totals.items():
        rounded = total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        rows.append({'service': service, 'count': count, 'total_cost': float(rounded)})
    rows.sort(key=lambda row: (-row['total_cost'], row['service']))
    parent = os.path.dirname(os.path.abspath(output_path))
    fd, temporary = tempfile.mkstemp(dir=parent)
    try:
