            writer = csv.writer(handle)
            writer.writerow(['service', 'count', 'total_cost'])
            for row in rows:
                writer.writerow([row['service'], row['count'], f"{row['total_cost']:.2f}"])
        os.replace(temporary, output_path)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return rows

