def export_deduplicated_contacts(contacts: list[dict[str, str]], output_path: str) -> int:
    if not isinstance(contacts, list):
        raise TypeError('contacts must be a list')
    rows = []
    seen = set()
    for contact in contacts:
        if not isinstance(contact, dict):
            raise TypeError('contact must be a dictionary')
        name = contact['name']
        email = contact['email']
        phone = contact['phone']
        if not all((isinstance(value, str) for value in (name, email, phone))):
            raise TypeError('contact fields must be strings')
        key = email.strip().casefold()
        if not key:
            raise ValueError('email cannot be empty')
        if key not in seen:
            seen.add(key)
            rows.append((name, email, phone))
    directory = os.path.dirname(os.path.abspath(output_path))
    descriptor, temporary_path = tempfile.mkstemp(prefix='.contacts-', suffix='.csv', dir=directory)
    os.close(descriptor)
    try:
        with open(temporary_path, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle)
            writer.writerow(('name', 'email', 'phone'))
            writer.writerows(rows)
        os.replace(temporary_path, output_path)
    except Exception:
        if os.path.exists(temporary_path):
            os.unlink(temporary_path)
        raise
    return len(rows)

