def list_claims(conn: sqlite3.Connection, status: str | None=None, product: str | None=None, min_amount: float | None=None, max_amount: float | None=None, sort_by: str='purchase_date', descending: bool=False, limit: int=100, offset: int=0) -> list[dict]:
    allowed = {'id', 'customer', 'product', 'purchase_date', 'status', 'amount'}
    if sort_by not in allowed or limit < 0 or offset < 0:
        raise ValueError('invalid query options')
    clauses = []
    values = []
    if status is not None:
        clauses.append('status = ?')
        values.append(status)
    if product is not None:
        clauses.append('product = ?')
        values.append(product)
    if min_amount is not None:
        clauses.append('amount >= ?')
        values.append(min_amount)
    if max_amount is not None:
        clauses.append('amount <= ?')
        values.append(max_amount)
    where = ' WHERE ' + ' AND '.join(clauses) if clauses else ''
    direction = ' DESC' if descending else ' ASC'
    query = 'SELECT id, customer, product, purchase_date, status, amount, description FROM claims' + where + ' ORDER BY ' + sort_by + direction + ', id ASC LIMIT ? OFFSET ?'
    values.extend([limit, offset])
    return [_row(row) for row in conn.execute(query, values)]

def search_claims(conn: sqlite3.Connection, terms: str, limit: int=20) -> list[dict]:
    if limit < 0:
        raise ValueError('invalid limit')
    words = terms.strip().split()
    if not words or limit == 0:
        return []
    rows = []
    for row in conn.execute('SELECT id, customer, product, purchase_date, status, amount, description FROM claims'):
        fields = [row[1].casefold(), row[2].casefold(), row[6].casefold()]
        if all((any((word.casefold() in field for field in fields)) for word in words)):
            score = sum((any((word.casefold() in field for word in words)) for field in fields))
            rows.append((-score, row[0], row))
    rows.sort(key=lambda item: (item[0], item[1]))
    return [_row(item[2]) for item in rows[:limit]]

def advance_claim(conn: sqlite3.Connection, claim_id: int, new_status: str) -> bool:
    statuses = {'submitted', 'approved', 'rejected', 'fulfilled'}
    transitions = {'submitted': {'approved', 'rejected'}, 'approved': {'fulfilled'}}
    if new_status not in statuses:
        raise ValueError('invalid status')
    current = conn.execute('SELECT status FROM claims WHERE id = ?', (claim_id,)).fetchone()
    if current is None or new_status not in transitions.get(current[0], set()):
        return False
    conn.execute('UPDATE claims SET status = ? WHERE id = ? AND status = ?', (new_status, claim_id, current[0]))
    conn.commit()
    return True

