def search_claims(conn: sqlite3.Connection, terms: str, limit: int=20) -> list[dict]:
    if limit < 0:
        raise ValueError('invalid limit')
    words = terms.strip().split()
    if not words or limit == 0:
        return []
    rows = []
    for row in conn.execute('SELECT id, customer, product, purchase_date, status, amount, description FROM claims'):
