        if all((any((word.casefold() in field for field in fields)) for word in words)):
            score = sum((any((word.casefold() in field for word in words)) for field in fields))
            rows.append((-score, row[0], row))
    rows.sort(key=lambda item: (item[0], item[1]))
    return [_row(item[2]) for item in rows[:limit]]

def advance_claim(conn: sqlite3.Connection, claim_id: int, new_status: str) -> bool:
    statuses = {'submitted', 'approved', 'rejected', 'fulfilled'}
    transitions = {'submitted': {'approved', 'rejected'}, 'approved': {'fulfilled'}}
    if new_status not in statuses:
        raise ValueError('invalid status')
    current = conn.execute('SELECT status FROM claims WHERE id = ?', (claim_id,)).fetchone()
    if current is None or new_status not in transitions.get(current[0], set()):
        return False
    conn.execute('UPDATE claims SET status = ? WHERE id = ? AND status = ?', (new_status, claim_id, current[0]))
    conn.commit()
    return True

