import yaml
from datetime import datetime, timedelta, timezone

def _time(value):
    try:
        return datetime.fromisoformat(value.replace('Z', '+00:00')).astimezone(timezone.utc)
    except Exception as exc:
        raise ValueError('invalid timestamp') from exc

def parse_campaign(spec: str) -> dict:
    try:
        raw = yaml.safe_load(spec)
    except Exception as exc:
        raise ValueError('invalid campaign') from exc
    if not isinstance(raw, dict) or not all((isinstance(raw.get(k), str) and raw[k] for k in ('campaign_id', 'tenant_id', 'owner_id'))):
        raise ValueError('invalid campaign')
    rules = raw.get('rules')
    if not isinstance(rules, dict):
        raise ValueError('invalid rules')
    minimum, days = (rules.get('min_opens'), rules.get('window_days'))
    if isinstance(minimum, bool) or not isinstance(minimum, int) or minimum < 0 or isinstance(days, bool) or (not isinstance(days, int)) or (days <= 0):
        raise ValueError('invalid rules')
    tag = rules.get('required_tag')
    if tag is not None and (not isinstance(tag, str)):
        raise ValueError('invalid tag')
    return {'campaign_id': raw['campaign_id'], 'tenant_id': raw['tenant_id'], 'owner_id': raw['owner_id'], 'rules': {'min_opens': minimum, 'window_days': days, 'required_tag': tag}}

def _allowed(requester, campaign):
    return requester.get('tenant_id') == campaign['tenant_id'] and (requester.get('id') == campaign['owner_id'] or 'admin' in requester.get('roles', []))

def segment_contacts(requester: dict, campaign: dict, contacts: list[dict], events: list[dict], now: str) -> list[dict]:
    if not _allowed(requester, campaign):
        raise PermissionError('not permitted')
    end = _time(now)
    start = end - timedelta(days=campaign['rules']['window_days'])
    known = {c['id']: c for c in contacts}
    stats = {}
    for event in events:
        timestamp = _time(event['timestamp'])
        if event.get('type') == 'open' and start <= timestamp <= end and (event.get('contact_id') in known):
            item = stats.setdefault(event['contact_id'], [0, None])
            item[0] += 1
            if item[1] is None or timestamp > item[1][0]:
                item[1] = (timestamp, event['timestamp'])
    tag = campaign['rules']['required_tag']
    result = []
    for contact in contacts:
        tags = {str(x).casefold() for x in contact.get('tags', [])}
        item = stats.get(contact['id'], [0, None])
        if contact.get('status') == 'subscribed' and (tag is None or tag.casefold() in tags) and (item[0] >= campaign['rules']['min_opens']):
            result.append({'id': contact['id'], 'email': contact['email'], 'opens': item[0], 'last_open': None if item[1] is None else item[1][1]})
    result.sort(key=lambda x: (-x['opens'], -(0 if x['last_open'] is None else _time(x['last_open']).timestamp()), x['email'].casefold(), x['id']))
    return result

def summarize_segment(requester: dict, campaign: dict, contacts: list[dict], events: list[dict], now: str) -> dict:
    selected = segment_contacts(requester, campaign, contacts, events, now)
    counts = {}
    for item in selected:
        domain = item['email'].rsplit('@', 1)[1].casefold() if '@' in item['email'] else ''
        counts[domain] = counts.get(domain, 0) + 1
    ordered = sorted(counts.items(), key=lambda pair: (-pair[1], pair[0]))
    return {'campaign_id': campaign['campaign_id'], 'count': len(selected), 'contacts': selected, 'domains': dict(ordered)}

