import csv
import os
import tempfile
from decimal import Decimal, ROUND_HALF_UP

def export_succession_csv(records: list[dict], min_readiness: float=0.0, page: int=1, page_size: int=50) -> str:
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    if isinstance(min_readiness, bool) or not isinstance(min_readiness, (int, float)) or (not 0 <= min_readiness <= 1):
        raise ValueError('invalid minimum readiness')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 1000):
        raise ValueError('invalid page size')
    selected = []
    for item in records:
        if not isinstance(item, dict):
            raise ValueError('invalid record')
        employee = item.get('employee')
        role = item.get('role')
        readiness = item.get('readiness')
        criticality = item.get('criticality')
        if not isinstance(employee, str) or not employee or (not isinstance(role, str)) or (not role):
            raise ValueError('invalid text field')
        if isinstance(readiness, bool) or not isinstance(readiness, (int, float)) or (not 0 <= readiness <= 1):
            raise ValueError('invalid readiness')
        if isinstance(criticality, bool) or not isinstance(criticality, int) or (not 1 <= criticality <= 5):
            raise ValueError('invalid criticality')
        if readiness >= min_readiness:
            selected.append((role, employee, readiness, criticality))
    selected.sort(key=lambda x: (x[0], -x[2], x[1]))
    rows = [['role', 'employee', 'readiness_percent', 'criticality', 'rank']]
    ranks = {}
    for role, employee, readiness, criticality in selected:
        ranks[role] = ranks.get(role, 0) + 1
        percent = (Decimal(str(readiness)) * Decimal('100')).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        rows.append([role, employee, f'{percent:.2f}', str(criticality), str(ranks[role])])
    start = 1 + (page - 1) * page_size
    output_rows = rows[:1] + rows[start:start + page_size]
    fd, path = tempfile.mkstemp()
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerows(output_rows)
        with open(path, 'r', newline='', encoding='utf-8') as handle:
            return handle.read()
    finally:
        try:
            os.unlink(path)
        except FileNotFoundError:
            pass

