def expected_signature(key, certificate_id, quantity, price, buyer, seller):
    payload = {
        "certificate_id": certificate_id,
        "quantity": quantity,
        "price": price,
        "buyer": buyer,
        "seller": seller,
    }
    encoded = json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return hmac.new(key.encode("utf-8"), encoded, hashlib.sha256).hexdigest()


def test_creates_order_with_integer_price():
    with patch.dict(os.environ, {"CERT_TRADING_SIGNING_KEY": "alpha-key"}, clear=False):
        result = create_certificate_order("REC-100", 12, 7, "Green Buyer", "Solar Farm")
    assert result == {
        "certificate_id": "REC-100",
        "quantity": 12,
        "price": 7,
        "buyer": "Green Buyer",
        "seller": "Solar Farm",
        "total_value": 84,
        "signature": expected_signature("alpha-key", "REC-100", 12, 7, "Green Buyer", "Solar Farm"),
    }


def test_creates_order_with_fractional_price():
    with patch.dict(os.environ, {"CERT_TRADING_SIGNING_KEY": "price-key"}, clear=False):
        result = create_certificate_order("WIND-9", 3, 12.5, "Buyer", "Seller")
    assert result["total_value"] == 37.5
    assert result["signature"] == expected_signature("price-key", "WIND-9", 3, 12.5, "Buyer", "Seller")


def test_signature_changes_when_order_fields_change():
    with patch.dict(os.environ, {"CERT_TRADING_SIGNING_KEY": "same-key"}, clear=False):
        first = create_certificate_order("REC-1", 1, 10, "B", "S")
        second = create_certificate_order("REC-1", 2, 10, "B", "S")
    assert first["signature"] != second["signature"]
    assert first["total_value"] == 10
    assert second["total_value"] == 20


def test_empty_text_fields_are_rejected():
    with patch.dict(os.environ, {"CERT_TRADING_SIGNING_KEY": "key"}, clear=False):
        for args in [("", 1, 1, "B", "S"), ("C", 1, 1, "", "S"), ("C", 1, 1, "B", "")]:
            try:
                create_certificate_order(*args)
                assert False
            except ValueError as exc:
                assert str(exc) == "text fields must be non-empty strings"


def test_invalid_quantities_are_rejected():
    with patch.dict(os.environ, {"CERT_TRADING_SIGNING_KEY": "key"}, clear=False):
        for quantity in [0, -1, 1.5, True, "2"]:
            try:
                create_certificate_order("C", quantity, 1, "B", "S")
                assert False
