                assert str(exc) == "quantity must be a positive integer"


def test_invalid_prices_are_rejected():
    with patch.dict(os.environ, {"CERT_TRADING_SIGNING_KEY": "key"}, clear=False):
        for price in [0, -2, True, "4", None]:
            try:
                create_certificate_order("C", 1, price, "B", "S")
                assert False
