                assert str(exc) == "price must be a positive number"


def test_text_arguments_must_be_strings():
    with patch.dict(os.environ, {"CERT_TRADING_SIGNING_KEY": "key"}, clear=False):
        for args in [(None, 1, 1, "B", "S"), ("C", 1, 1, 4, "S"), ("C", 1, 1, "B", [])]:
            try:
                create_certificate_order(*args)
                assert False
            except ValueError as exc:
