def parse_reservoir_report(xml_text: str) -> dict:
    try:
        parser = etree.XMLParser(resolve_entities=False, load_dtd=False, no_network=True)
        root = etree.fromstring(xml_text.encode(), parser)
        if root.tag != 'report':
            raise ValueError()
        reservoir = root.get('reservoir')
        generated = root.get('generated')
        if not reservoir or not generated:
            raise ValueError()
        datetime.fromisoformat(generated)
        readings = []
        for node in root:
            if node.tag != 'reading':
                raise ValueError()
            values = {key: node.get(key) for key in ('station', 'timestamp', 'level', 'inflow', 'gate')}
            if any((value is None or value == '' for value in values.values())):
                raise ValueError()
            timestamp = datetime.fromisoformat(values['timestamp']).isoformat()
            level, inflow, gate = (float(values[key]) for key in ('level', 'inflow', 'gate'))
            if level < 0 or inflow < 0 or (not 0 <= gate <= 100):
                raise ValueError()
            readings.append({'station': values['station'], 'timestamp': timestamp, 'level': level, 'inflow': inflow, 'gate': gate})
        return {'reservoir': reservoir, 'generated': generated, 'readings': readings}
    except (ValueError, TypeError, OverflowError, etree.XMLSyntaxError) as exc:
        raise ValueError('invalid report') from exc

def station_statistics(report: dict, minimum_readings: int=1) -> list[dict]:
    if isinstance(minimum_readings, bool) or not isinstance(minimum_readings, int) or minimum_readings <= 0:
        raise ValueError('invalid minimum')
    groups = defaultdict(list)
    for reading in report.get('readings', []):
        groups[reading['station']].append(reading)
    result = []
    for station, rows in groups.items():
        if len(rows) < minimum_readings:
            continue
        result.append({'station': station, 'count': len(rows), 'average_level': round(sum((x['level'] for x in rows)) / len(rows), 2), 'peak_inflow': round(max((x['inflow'] for x in rows)), 2), 'total_inflow': round(sum((x['inflow'] for x in rows)), 2), 'gate_changes': sum((a['gate'] != b['gate'] for a, b in zip(rows, rows[1:])))})
    return sorted(result, key=lambda x: (-x['total_inflow'], x['station']))

def rolling_inflow(report: dict, window_minutes: int) -> list[dict]:
    if isinstance(window_minutes, bool) or not isinstance(window_minutes, int) or window_minutes <= 0:
        raise ValueError('invalid window')
