    for index, reading in enumerate(report.get('readings', [])):
        groups[reading['station']].append((datetime.fromisoformat(reading['timestamp']), index, reading))
    result = []
    delta = timedelta(minutes=window_minutes)
    for station, rows in groups.items():
        rows.sort(key=lambda x: (x[0], x[1]))
        start = rows[0][0]
        buckets = defaultdict(list)
        for timestamp, _, reading in rows:
            buckets[(timestamp - start) // delta].append(reading)
        for number, values in buckets.items():
