import csv
import os
import tempfile

def write_subscriber_report(subscribers: list[dict[str, object]], destination: str) -> int:
    totals = {}
    for subscriber in subscribers:
        email = subscriber['email']
        opens = subscriber['opens']
        clicks = subscriber['clicks']
        if opens < 0 or clicks < 0:
            raise ValueError('metrics cannot be negative')
        if email not in totals:
            totals[email] = [0, 0]
        totals[email][0] += opens
        totals[email][1] += clicks
    directory = os.path.dirname(destination) or '.'
    fd, temporary = tempfile.mkstemp(dir=directory, prefix='.newsletter-', suffix='.tmp')
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['email', 'total_opens', 'total_clicks', 'click_rate'])
            for email in sorted(totals):
                opens, clicks = totals[email]
                rate = clicks / opens if opens else 0
                writer.writerow([email, opens, clicks, f'{rate:.2f}'])
        os.replace(temporary, destination)
    except Exception:
        if os.path.exists(temporary):
            os.unlink(temporary)
        raise
    return len(totals)

