import ast
import operator

def find_rooms(rooms: list[dict], rule: str) -> list[str]:
    try:
        tree = ast.parse(rule, mode='eval').body
    except SyntaxError as exc:
        raise ValueError('invalid rule') from exc
    allowed = {'id', 'capacity', 'floor', 'rate', 'accessible', 'available'}
    binary = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
    compare = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}

    def evaluate(node, values):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
            return node.value
        if isinstance(node, ast.Name) and node.id in allowed:
            return values[node.id]
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
            value = evaluate(node.operand, values)
            return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
        if isinstance(node, ast.BinOp) and type(node.op) in binary:
            return binary[type(node.op)](evaluate(node.left, values), evaluate(node.right, values))
        if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
            value = evaluate(node.values[0], values)
            for item in node.values[1:]:
                if isinstance(node.op, ast.And) and (not value) or (isinstance(node.op, ast.Or) and value):
                    return value
                value = evaluate(item, values)
            return value
        if isinstance(node, ast.Compare):
            left = evaluate(node.left, values)
            for op, part in zip(node.ops, node.comparators):
                if type(op) not in compare or not compare[type(op)](left, evaluate(part, values)):
                    return False
                left = evaluate(part, values)
            return True
        raise ValueError('unsupported rule')
    result = []
    for room in rooms:
        if room['available'] and evaluate(tree, room):
            result.append(room['id'])
    return sorted(result, key=lambda room_id: next((r['capacity'] for r in rooms if r['id'] == room_id)), reverse=True)

