import hmac
import json

def verify_batch_webhook(payload: bytes, signature: str, secret: str) -> dict:
    if not isinstance(signature, str) or len(signature) != 71 or (not signature.startswith('sha256=')):
        raise ValueError('invalid signature')
    supplied = signature[7:]
    if any((char not in '0123456789abcdef' for char in supplied)):
        raise ValueError('invalid signature')
    expected = hmac.new(secret.encode('utf-8'), payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, supplied):
        raise ValueError('invalid signature')
    try:
        value = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    if not isinstance(value, dict) or set(value) != {'event', 'batch_id', 'quantity', 'unit'}:
