import ast

def _value(node, names):
    if isinstance(node, ast.Constant) and (node.value is None or isinstance(node.value, (bool, int, float))):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in names:
            raise ValueError('invalid name')
        return names[node.id]
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
        value = _value(node.operand, names)
        if isinstance(node.op, ast.UAdd):
            return +value
        if isinstance(node.op, ast.USub):
            return -value
        return not value
    if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
        left = _value(node.left, names)
        right = _value(node.right, names)
        if isinstance(node.op, ast.Add):
            return left + right
        if isinstance(node.op, ast.Sub):
            return left - right
        if isinstance(node.op, ast.Mult):
            return left * right
        return left / right
    if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
        result = _value(node.values[0], names)
        for child in node.values[1:]:
            if isinstance(node.op, ast.And):
                if not result:
                    return result
            elif result:
                return result
            result = _value(child, names)
        return result
    if isinstance(node, ast.Compare):
        left = _value(node.left, names)
        for operation, child in zip(node.ops, node.comparators):
            right = _value(child, names)
            if isinstance(operation, ast.Eq):
                ok = left == right
            elif isinstance(operation, ast.NotEq):
                ok = left != right
            elif isinstance(operation, ast.Lt):
                ok = left < right
            elif isinstance(operation, ast.LtE):
                ok = left <= right
            elif isinstance(operation, ast.Gt):
                ok = left > right
            elif isinstance(operation, ast.GtE):
                ok = left >= right
            else:
                raise ValueError('invalid operator')
            if not ok:
                return False
            left = right
        return True
    raise ValueError('invalid expression')

def rank_permits(records: list[dict], rule: str, page: int, page_size: int) -> list[str]:
    if page < 1 or page_size < 1:
        raise ValueError('invalid page')
    try:
        tree = ast.parse(rule, mode='eval').body
    except Exception as exc:
        raise ValueError('invalid expression') from exc
    matches = []
    for position, record in enumerate(records):
        try:
            if _value(tree, record):
                matches.append((record['id'], record['priority'], record['distance_km'], position))
        except Exception as exc:
            raise ValueError('invalid expression') from exc
    matches.sort(key=lambda item: (-item[1], item[2], item[3]))
    start = (page - 1) * page_size
    return [item[0] for item in matches[start:start + page_size]]

