def index_transcript(xml: str) -> dict[str, object]:
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    root = etree.fromstring(xml, parser)
    if root.tag != 'transcript':
        raise ValueError('invalid root')
    case_id = root.get('case_id', '')
    if not case_id.strip():
        raise ValueError('missing case id')
    sessions = []
    speaker_word_counts = {}
    total_utterances = 0
    for session_node in root:
        if session_node.tag != 'session':
            continue
        date = session_node.get('date', '')
        if not date.strip():
            raise ValueError('missing date')
        utterances = []
        for utterance_node in session_node:
            if utterance_node.tag != 'utterance':
                continue
            speaker = utterance_node.get('speaker', '')
            if not speaker.strip():
                raise ValueError('missing speaker')
            text = ' '.join(''.join(utterance_node.itertext()).split())
            utterances.append({'speaker': speaker, 'text': text})
            speaker_word_counts.setdefault(speaker, 0)
            speaker_word_counts[speaker] += len(text.split())
            total_utterances += 1
        sessions.append({'date': date, 'utterances': utterances})
    return {'case_id': case_id, 'sessions': sessions, 'total_utterances': total_utterances, 'speaker_word_counts': speaker_word_counts}

