def update_annotation(project: dict, requester: dict, annotation_id: str, label: str, confidence: float) -> dict:
    if not isinstance(label, str) or not label:
        raise ValueError('invalid label')
    if isinstance(confidence, bool) or not isinstance(confidence, (int, float)) or (not 0 <= confidence <= 1):
        raise ValueError('invalid confidence')
    found = next((a for a in project.get('annotations', []) if a.get('id') == annotation_id), None)
    if found is None:
        raise KeyError(annotation_id)
    allowed_role = requester.get('role') in {'annotation_admin', 'research_lead'}
    if requester.get('tenant_id') != project.get('tenant_id') or (requester.get('id') != found.get('annotator_id') and (not allowed_role)):
        raise PermissionError('not allowed')
    result = deepcopy(project)
    target = next((a for a in result['annotations'] if a.get('id') == annotation_id))
    target['label'] = label
    target['confidence'] = confidence
    target['updated_by'] = requester.get('id')
    result['revision'] = project.get('revision', 0) + 1
    return result

