    image_ids = {image['id'] for image in project.get('images', [])}
    groups = {}
    for annotation in project.get('annotations', []):
        if annotation.get('image_id') not in image_ids:
            continue
        label = annotation.get('label')
        confidence = annotation.get('confidence')
        if not isinstance(label, str) or isinstance(confidence, bool) or (not isinstance(confidence, (int, float))) or (not 0 <= confidence <= 1):
            raise ValueError('invalid annotation')
        groups.setdefault(annotation['image_id'], {}).setdefault(label, []).append(annotation)
    output = []
    for image_id in sorted(groups):
        labels = groups[image_id]
        label = min(labels, key=lambda k: (-len(labels[k]), -sum((a['confidence'] for a in labels[k])), k))
        selected = sorted(labels[label], key=lambda a: (a['created_at'], a['id']))
        output.append({'image_id': image_id, 'label': label, 'count': len(selected), 'mean_confidence': round(sum((a['confidence'] for a in selected)) / len(selected), 3), 'annotations': [a['id'] for a in selected]})
    return output

