from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from datetime import date
from lxml import etree

def parse_invoice_feed(xml_text: str, page: int=1, page_size: int=20) -> dict:
    if page < 1 or page_size < 1:
        raise ValueError('invalid pagination')
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml_text.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid xml') from exc
    if root.tag != 'invoices':
        raise ValueError('invalid root')
    allowed = {'pending', 'approved', 'paid', 'cancelled'}
    seen = set()
    rows = []
    for node in root.findall('invoice'):
        ident = node.get('id')
        vendor = node.get('vendor')
        status = node.get('status')
        amount_node = node.find('amount')
        due_node = node.find('due')
        if not ident or vendor is None or status not in allowed or (amount_node is None) or (due_node is None) or (amount_node.get('currency') is None) or (amount_node.text is None) or (due_node.text is None) or (ident in seen):
            raise ValueError('invalid invoice')
        seen.add(ident)
        try:
            amount = Decimal(amount_node.text.strip())
            due = date.fromisoformat(due_node.text.strip()).isoformat()
        except (InvalidOperation, ValueError) as exc:
            raise ValueError('invalid invoice') from exc
        if not amount.is_finite():
            raise ValueError('invalid invoice')
        if status in {'pending', 'approved'}:
            rows.append({'id': ident, 'vendor': vendor, 'status': status, 'amount': amount, 'due': due, 'currency': amount_node.get('currency')})
    rows.sort(key=lambda x: (x['due'], x['id']))
    quant = Decimal('0.01')

    def money(value):
        return str(value.quantize(quant, rounding=ROUND_HALF_UP))
    vendors = {}
    for row in rows:
        item = vendors.setdefault(row['vendor'], [0, Decimal('0')])
        item[0] += 1
        item[1] += row['amount']
    start = (page - 1) * page_size
    shown = rows[start:start + page_size]
    output_rows = [{**r, 'amount': money(r['amount'])} for r in shown]
    result_vendors = [{'vendor': name, 'count': values[0], 'total': money(values[1])} for name, values in sorted(vendors.items())]
    count = len(rows)
    return {'count': count, 'page': page, 'page_size': page_size, 'pages': (count + page_size - 1) // page_size if count else 0, 'invoices': output_rows, 'by_vendor': result_vendors}

