import csv
import os
import tempfile

def write_telemetry_csv(records: list[dict], destination: str) -> int:
    required = {'timestamp', 'device_id', 'temperature', 'humidity'}
    checked = []
    for record in records:
        if set(record) != required:
            raise ValueError('invalid record fields')
        if not isinstance(record['timestamp'], str) or not isinstance(record['device_id'], str):
            raise ValueError('invalid text field')
        if isinstance(record['temperature'], bool) or not isinstance(record['temperature'], (int, float)):
            raise ValueError('invalid temperature')
        if isinstance(record['humidity'], bool) or not isinstance(record['humidity'], (int, float)):
            raise ValueError('invalid humidity')
        checked.append(record)
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(prefix='telemetry-', suffix='.tmp', dir=directory)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['timestamp', 'device_id', 'temperature', 'humidity'])
            for record in checked:
                writer.writerow([record['timestamp'], record['device_id'], record['temperature'], record['humidity']])
        os.replace(temporary, destination)
    except BaseException:
