import hashlib
import hmac
import os

def hash_secret(secret: str) -> str:
    if not isinstance(secret, str):
        raise TypeError('secret must be a string')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
    return salt.hex() + ':' + digest.hex()

def verify_secret(secret: str, stored: str) -> bool:
    if not isinstance(secret, str) or not isinstance(stored, str):
        return False
    try:
        salt_text, digest_text = stored.split(':', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def release_catalog(episodes: list[dict], editor_secret: str, stored_secret: str, page: int=1, page_size: int=10) -> dict:
    if not verify_secret(editor_secret, stored_secret):
        raise PermissionError('editor authorization failed')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
    published = []
    for item in episodes:
        if not isinstance(item, dict) or not all((k in item for k in ('title', 'duration', 'plays', 'published'))):
            raise ValueError('invalid episode')
        if not isinstance(item['title'], str) or isinstance(item['duration'], bool) or (not isinstance(item['duration'], (int, float))) or (item['duration'] < 0) or isinstance(item['plays'], bool) or (not isinstance(item['plays'], int)) or (item['plays'] < 0) or (not isinstance(item['published'], bool)):
            raise ValueError('invalid episode')
        if item['published']:
            published.append(item)
    published.sort(key=lambda x: (-x['plays'], x['title']))
    start = (page - 1) * page_size
    selected = published[start:start + page_size]
