def summarize_donations(records: list[dict], start_date: str, end_date: str) -> list[dict]:
    start = _date(start_date)
    end = _date(end_date)
    if start > end:
        raise ValueError('invalid range')
    donors = {}
    for record in records:
        try:
            donor_id = record['donor_id']
            donor_name = record['donor_name']
            campaign = record['campaign']
            amount = record['amount_cents']
            raw_date = record['donated_on']
        except (KeyError, TypeError):
            raise ValueError('invalid record')
        if not all((isinstance(x, str) and x for x in (donor_id, donor_name, campaign))):
            raise ValueError('invalid record')
        if isinstance(amount, bool) or not isinstance(amount, int) or amount < 0:
            raise ValueError('invalid amount')
        day = _date(raw_date)
        if not start <= day <= end:
            continue
        item = donors.setdefault(donor_id, {'donor_id': donor_id, 'donor_name': donor_name, 'total_cents': 0, 'gift_count': 0, 'latest_date': raw_date, 'campaigns': {}})
        item['total_cents'] += amount
        item['gift_count'] += 1
        if raw_date > item['latest_date']:
            item['latest_date'] = raw_date
