        campaign_item['total_cents'] += amount
        campaign_item['gift_count'] += 1
    result = []
    for item in donors.values():
        total = item['total_cents']
        tier = 'benefactor' if total >= 100000 else 'patron' if total >= 25000 else 'supporter'
