        expected = base64.b64decode(record['digest'], validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
        return record['operator_id'] == operator_id and hmac.compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError):
        return False

