import base64
import datetime
import hashlib
import hmac
import os

def hash_secret(secret: str) -> str:
    if not isinstance(secret, str):
        raise TypeError()
    if not secret:
        raise ValueError()
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
    return 'pbkdf2$' + base64.b64encode(salt).decode() + '$' + base64.b64encode(value).decode()

def verify_secret(stored: str, secret: str) -> bool:
    if not isinstance(stored, str) or not isinstance(secret, str):
        raise TypeError()
    try:
        kind, salt_text, value_text = stored.split('$')
        if kind != 'pbkdf2':
            return False
        salt = base64.b64decode(salt_text.encode(), validate=True)
        expected = base64.b64decode(value_text.encode(), validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def _fields(line):
    result, part, escaped = ([], [], False)
    for char in line:
        if escaped:
            if char not in '\\|':
                raise ValueError()
            part.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            result.append(''.join(part).strip())
            part = []
        else:
            part.append(char)
    if escaped:
        raise ValueError()
    result.append(''.join(part).strip())
    return result

def _money(value):
    if not value or value.count('.') > 1:
        raise ValueError()
    whole, dot, fraction = value.partition('.')
    if not whole.isdigit() or (dot and (not fraction.isdigit() or len(fraction) > 2)):
        raise ValueError()
    return int(whole) * 100 + int((fraction + '00')[:2])

def parse_portfolio(text: str) -> list[dict]:
    if not isinstance(text, str):
        raise TypeError()
    output = []
    for line in text.splitlines():
        if not line.strip():
            continue
        fields = _fields(line)
        if len(fields) != 5 or not fields[0] or (not fields[1]) or (not fields[3]):
            raise ValueError()
        try:
            due = datetime.date.fromisoformat(fields[2])
        except ValueError:
            raise ValueError()
        if fields[3] not in {'pending', 'grace', 'closed'}:
            raise ValueError()
        output.append({'application': fields[0], 'jurisdiction': fields[1], 'due': due, 'status': fields[3], 'fee_cents': _money(fields[4])})
    return output

def renewal_schedule(records: list[dict], as_of: datetime.date) -> list[dict]:
    if not isinstance(records, list):
        raise TypeError()
    if not isinstance(as_of, datetime.date):
        raise TypeError()
    selected = []
    end = as_of + datetime.timedelta(days=180)
    for record in records:
        try:
            application = record['application']
            jurisdiction = record['jurisdiction']
            due = record['due']
            status = record['status']
            fee = record['fee_cents']
        except (KeyError, TypeError):
            raise ValueError()
        if not isinstance(application, str) or not application or (not isinstance(jurisdiction, str)) or (not jurisdiction) or (not isinstance(due, datetime.date)) or (not isinstance(status, str)) or (status not in {'pending', 'grace', 'closed'}) or (not isinstance(fee, int)) or isinstance(fee, bool) or (fee < 0):
            raise ValueError()
        if status != 'closed' and as_of <= due <= end:
            selected.append({'application': application, 'jurisdiction': jurisdiction, 'due': due, 'fee_cents': fee, 'priority': 0 if status == 'pending' else 1})
    return sorted(selected, key=lambda x: (x['due'], x['priority'], -x['fee_cents'], x['application'], x['jurisdiction']))

