import hashlib
import hmac
import json
from datetime import date
import pytest


def make_payload(effective="2025-04-01", payments=None):
    if payments is None:
        payments = [
            {"member": "ABC123", "pence": 1250, "kind": "employee"},
            {"member": "XYZ999", "pence": 800, "kind": "employer"},
        ]
    return json.dumps({"effective": effective, "payments": payments}, separators=(",", ":")).encode()


def signed(payload, secret=b"pension-secret"):
    return hmac.new(secret, payload, hashlib.sha256).hexdigest()


def test_verify_signature_accepts_valid_digest():
    payload = b'{"effective":"2025-01-01","payments":[]}'
    secret = b"abc123"
    assert verify_signature(payload, signed(payload, secret), secret) is True


def test_verify_signature_rejects_changed_payload_or_digest():
    payload = b'{"effective":"2025-01-01","payments":[]}'
    secret = b"abc123"
    good = signed(payload, secret)
    assert verify_signature(payload + b" ", good, secret) is False
    assert verify_signature(payload, "0" * 64, secret) is False
    assert verify_signature(payload, good.upper(), secret) is False


def test_verify_signature_rejects_malformed_arguments():
    payload = b"data"
    assert verify_signature(payload, "short", b"x") is False
    assert verify_signature(payload, "g" * 64, b"x") is False
    assert verify_signature(payload, signed(payload, b"x"), b"") is False
    assert verify_signature("data", signed(payload, b"x"), b"x") is False
    assert verify_signature(payload, None, b"x") is False


def test_process_aggregates_updates_and_sorts():
    payload = make_payload(payments=[
        {"member": "ZZZ", "pence": 400, "kind": "employee"},
        {"member": "AAA", "pence": 700, "kind": "employer"},
        {"member": "ZZZ", "pence": 800, "kind": "employer"},
        {"member": "BBB", "pence": 700, "kind": "employee"},
    ])
    ledger = {"ZZZ": 1000, "OLD": 55}
    result = process_pension_batch(payload, signed(payload), b"pension-secret", ledger)
    assert result == [("ZZZ", 1200), ("AAA", 700), ("BBB", 700)]
    assert ledger == {"ZZZ": 2200, "OLD": 55, "AAA": 700, "BBB": 700}


def test_process_empty_batch_preserves_ledger():
    payload = make_payload(payments=[])
    ledger = {"ABC": 19}
    assert process_pension_batch(payload, signed(payload), b"pension-secret", ledger) == []
    assert ledger == {"ABC": 19}


def test_process_bad_signature_does_not_parse_or_mutate():
    payload = b"not json"
    ledger = {"ABC": 10}
    with pytest.raises(ValueError, match="^invalid signature$"):
        process_pension_batch(payload, "0" * 64, b"pension-secret", ledger)
    assert ledger == {"ABC": 10}


def test_process_rejects_invalid_date_and_payment_atomically():
    payload = make_payload(effective="2025-02-30")
    ledger = {"ABC": 10}
    with pytest.raises(ValueError):
        process_pension_batch(payload, signed(payload), b"pension-secret", ledger)
    assert ledger == {"ABC": 10}

