        {"member": "ABC", "pence": 20, "kind": "employee"},
        {"member": "bad-id", "pence": 30, "kind": "employer"},
    ]
    payload = make_payload(payments=payments)
    with pytest.raises(ValueError):
        process_pension_batch(payload, signed(payload), b"pension-secret", ledger)
    assert ledger == {"ABC": 10}


def test_process_rejects_wrong_shapes_and_boolean_amounts():
    base = {"effective": "2025-01-01", "payments": []}
    cases = [
        {"effective": "2025-01-01"},
        {"effective": "2025-01-01", "payments": "x"},
        {"effective": "2025-01-01", "payments": [{"member": "ABC", "pence": True, "kind": "employee"}]},
        {"effective": "2025-01-01", "payments": [{"member": "ABC", "pence": 1, "kind": "other"}]},
        {"effective": "2025-01-01", "payments": [{"member": "ABC", "pence": 1, "kind": "employee", "extra": 2}]},
