import hashlib
import hmac
import json
import re
from datetime import datetime

def verify_signature(payload: bytes, signature: str, secret: bytes) -> bool:
    if not isinstance(payload, bytes) or not isinstance(signature, str) or (not isinstance(secret, bytes)) or (not secret):
        return False
    if len(signature) != 64 or any((c not in '0123456789abcdef' for c in signature)):
        return False
    expected = hmac.new(secret, payload, hashlib.sha256).hexdigest()
    return hmac.compare_digest(signature, expected)

def process_pension_batch(payload: bytes, signature: str, secret: bytes, ledger: dict[str, int]) -> list[tuple[str, int]]:
    if not verify_signature(payload, signature, secret):
        raise ValueError('invalid signature')
    try:
        obj = json.loads(payload.decode('utf-8'))
        if not isinstance(obj, dict) or set(obj) != {'effective', 'payments'}:
            raise ValueError
        effective = obj['effective']
        datetime.strptime(effective, '%Y-%m-%d')
        if not isinstance(effective, str) or len(effective) != 10:
            raise ValueError
        payments = obj['payments']
        if not isinstance(payments, list):
            raise ValueError
        totals = {}
        for payment in payments:
            if not isinstance(payment, dict) or set(payment) != {'member', 'pence', 'kind'}:
                raise ValueError
            member, pence, kind = (payment['member'], payment['pence'], payment['kind'])
            if not isinstance(member, str) or not re.fullmatch('[A-Z0-9]{3,8}', member):
                raise ValueError
            if isinstance(pence, bool) or not isinstance(pence, int) or pence <= 0:
                raise ValueError
            if kind not in ('employee', 'employer'):
                raise ValueError
            totals[member] = totals.get(member, 0) + pence
    except (UnicodeDecodeError, json.JSONDecodeError, TypeError, ValueError, OverflowError):
        raise ValueError('invalid batch')
    result = sorted(totals.items(), key=lambda item: (-item[1], item[0]))
    for member, amount in result:
        ledger[member] = ledger.get(member, 0) + amount
    return result

