import sqlite3
from datetime import datetime

def _date(value):
    try:
        return datetime.strptime(value, '%Y-%m-%dT%H:%M').strftime('%Y-%m-%dT%H:%M')
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def initialize(conn: sqlite3.Connection) -> None:
    conn.execute('CREATE TABLE IF NOT EXISTS reservations (id INTEGER PRIMARY KEY, plate TEXT NOT NULL, airport TEXT NOT NULL, start TEXT NOT NULL, end TEXT NOT NULL, status TEXT NOT NULL, created INTEGER NOT NULL)')
    conn.commit()

def add_reservation(conn: sqlite3.Connection, plate: str, airport: str, start: str, end: str) -> int:
    if not isinstance(plate, str) or not plate or (not isinstance(airport, str)) or (not airport):
        raise ValueError('empty value')
    start = _date(start)
