from solution import parse_inventory, summary_inventory, make_invite_code
import pytest

def test_parse_basic_records_and_order():
    text = 'Rose|Red|12|350\nTomato|Cherry|4|125\n'
    assert parse_inventory(text) == [{'species': 'Rose', 'variety': 'Red', 'quantity': 12, 'unit_price_cents': 350}, {'species': 'Tomato', 'variety': 'Cherry', 'quantity': 4, 'unit_price_cents': 125}]

def test_parse_rejects_bad_lines_with_line_number():
    cases = [('A|B|1', 1), ('A|B|-1|2', 1), ('A|B|x|2', 1), ('|B|1|2', 1), ('A|B|1|2\\', 1), ('\nA|B|1|2\nC|D|1', 3)]
    for text, line in cases:
        with pytest.raises(ValueError) as exc:
            parse_inventory(text)
        assert str(line) in str(exc.value)

def test_summary_aggregates_values_and_distinct_varieties():
    records = [{'species': 'Rose', 'variety': 'Red', 'quantity': 3, 'unit_price_cents': 100}, {'species': 'Rose', 'variety': 'White', 'quantity': 2, 'unit_price_cents': 150}, {'species': 'Rose', 'variety': 'Red', 'quantity': 4, 'unit_price_cents': 90}, {'species': 'Fern', 'variety': 'Boston', 'quantity': 9, 'unit_price_cents': 40}]
    original = [dict(x) for x in records]
    assert summary_inventory(records) == [{'species': 'Fern', 'quantity': 9, 'value_cents': 360, 'varieties': 1}, {'species': 'Rose', 'quantity': 9, 'value_cents': 960, 'varieties': 2}]
    assert records == original

