    records = [{'species': 'Zinnia', 'variety': 'A', 'quantity': 2, 'unit_price_cents': 1}, {'species': 'Aster', 'variety': 'A', 'quantity': 2, 'unit_price_cents': 2}]
    assert [x['species'] for x in summary_inventory(records)] == ['Aster', 'Zinnia']
    assert summary_inventory([]) == []

