import secrets

def parse_inventory(text: str) -> list[dict]:
    result = []
    for number, raw in enumerate(text.splitlines(), 1):
        if not raw.strip() or raw.lstrip().startswith('#'):
            continue
        fields = []
        current = []
        escaped = False
        for char in raw:
            if escaped:
                current.append(char)
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == '|':
                fields.append(''.join(current))
                current = []
            else:
                current.append(char)
        if escaped:
            raise ValueError(f'line {number}: unterminated escape')
        fields.append(''.join(current))
        if len(fields) != 4 or not fields[0]:
            raise ValueError(f'line {number}: expected four fields')
        try:
            quantity = int(fields[2])
            price = int(fields[3])
        except ValueError:
            raise ValueError(f'line {number}: invalid number')
        if quantity < 0 or price < 0 or fields[2] == '' or (fields[3] == ''):
            raise ValueError(f'line {number}: invalid number')
        result.append({'species': fields[0], 'variety': fields[1], 'quantity': quantity, 'unit_price_cents': price})
    return result

def summary_inventory(records: list[dict]) -> list[dict]:
    grouped = {}
    for record in records:
        species = record['species']
        item = grouped.setdefault(species, {'species': species, 'quantity': 0, 'value_cents': 0, 'variety_set': set()})
        item['quantity'] += record['quantity']
        item['value_cents'] += record['quantity'] * record['unit_price_cents']
        item['variety_set'].add(record['variety'])
    result = []
    for item in grouped.values():
        result.append({'species': item['species'], 'quantity': item['quantity'], 'value_cents': item['value_cents'], 'varieties': len(item['variety_set'])})
    return sorted(result, key=lambda x: (-x['quantity'], x['species']))

