def list_voters(conn: sqlite3.Connection, search: str='', county: str | None=None, status: str | None=None, sort_by: str='last_name', descending: bool=False, limit: int=50, offset: int=0) -> list[dict]:
    allowed_statuses = {'active', 'inactive', 'pending'}
    allowed_columns = {'id', 'first_name', 'last_name', 'county', 'status', 'registered_year'}
    if status is not None and status not in allowed_statuses:
        raise ValueError('invalid status')
    if sort_by not in allowed_columns:
        raise ValueError('invalid sort column')
    if isinstance(limit, bool) or not isinstance(limit, int) or (not 1 <= limit <= 100):
        raise ValueError('invalid limit')
    if isinstance(offset, bool) or not isinstance(offset, int) or offset < 0:
        raise ValueError('invalid offset')
    if not isinstance(search, str) or (county is not None and (not isinstance(county, str))):
        raise ValueError('invalid filter')
    direction = 'DESC' if descending else 'ASC'
    clauses = ['(first_name LIKE ? COLLATE NOCASE OR last_name LIKE ? COLLATE NOCASE)']
    params = [f'%{search}%', f'%{search}%']
    if county is not None:
        clauses.append('county = ?')
        params.append(county)
    if status is not None:
        clauses.append('status = ?')
        params.append(status)
    query = 'SELECT id, first_name, last_name, county, status, registered_year FROM voters WHERE ' + ' AND '.join(clauses)
    query += f' ORDER BY {sort_by} {direction}, id {direction} LIMIT ? OFFSET ?'
    params.extend([limit, offset])
    rows = conn.execute(query, params).fetchall()
    names = ['id', 'first_name', 'last_name', 'county', 'status', 'registered_year']
    return [dict(zip(names, row)) for row in rows]

