import hashlib
import hmac
import os
from datetime import date

def _parsed_date(value):
    if not isinstance(value, str):
        raise ValueError('invalid date')
    try:
        parsed = date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid date')
    if parsed.isoformat() != value:
        raise ValueError('invalid date')
    return parsed

def create_case(case_id: str, executor: str, access_code: str, events: list[dict]) -> dict:
    if not all((isinstance(x, str) and x for x in (case_id, executor, access_code))):
        raise ValueError('invalid case')
    if not isinstance(events, list):
        raise ValueError('invalid events')
    normalized = []
    for event in events:
        if not isinstance(event, dict) or not all((k in event for k in ('date', 'type', 'value'))):
            raise ValueError('invalid event')
        _parsed_date(event['date'])
        if event['type'] not in ('asset', 'expense', 'distribution'):
            raise ValueError('invalid type')
        if isinstance(event['value'], bool) or not isinstance(event['value'], int) or event['value'] < 0:
            raise ValueError('invalid value')
        copied = dict(event)
        if event['type'] == 'distribution':
            if not isinstance(event.get('beneficiary'), str) or not event['beneficiary']:
                raise ValueError('invalid beneficiary')
        normalized.append(copied)
    normalized.sort(key=lambda e: _parsed_date(e['date']))
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', access_code.encode(), salt, 100000)
    return {'case_id': case_id, 'executor': executor, 'access_salt': salt.hex(), 'access_hash': digest.hex(), 'events': normalized}

def verify_access(case: dict, access_code: str) -> bool:
    if not isinstance(access_code, str):
        return False
    try:
        salt = bytes.fromhex(case['access_salt'])
        expected = case['access_hash']
    except (KeyError, TypeError, ValueError):
        raise ValueError('invalid case')
    actual = hashlib.pbkdf2_hmac('sha256', access_code.encode(), salt, 100000).hex()
    return hmac.compare_digest(actual, expected)

def estate_report(case: dict, cutoff: str | None=None) -> dict:
    limit = _parsed_date(cutoff) if cutoff is not None else None
    gross = expenses = distributions = 0
    by_name = {}
    for event in case['events']:
        if limit is not None and _parsed_date(event['date']) > limit:
            continue
        value = event['value']
        if event['type'] == 'asset':
            gross += value
        elif event['type'] == 'expense':
            expenses += value
        else:
            distributions += value
            name = event['beneficiary']
            by_name[name] = by_name.get(name, 0) + value
    beneficiaries = [{'name': n, 'amount': a} for n, a in by_name.items()]
    beneficiaries.sort(key=lambda x: (-x['amount'], x['name']))
    return {'case_id': case['case_id'], 'executor': case['executor'], 'gross_assets': gross, 'expenses': expenses, 'distributions': distributions, 'net_estate': gross - expenses - distributions, 'beneficiaries': beneficiaries}

