from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from datetime import date
import math
from lxml import etree

def summarize_shipments(xml_text: str, status: str | None=None, page: int=1, page_size: int=10) -> dict:
    statuses = {'pending', 'in_transit', 'delivered', 'cancelled'}
    if status is not None and status not in statuses:
        raise ValueError('invalid status')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode('utf-8'), parser=parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'shipments':
        raise ValueError('invalid root')
    records = []
    seen = set()
    for node in root:
        if node.tag != 'shipment':
            raise ValueError('invalid child')
        required = ('id', 'destination', 'status', 'weight_kg')
        if any((node.get(key) is None for key in required)):
            raise ValueError('missing attribute')
        ident, destination, current = (node.get('id'), node.get('destination'), node.get('status'))
        if not ident or not destination or current not in statuses or (ident in seen):
            raise ValueError('invalid shipment')
        seen.add(ident)
        try:
            weight = Decimal(node.get('weight_kg'))
        except (InvalidOperation, TypeError):
            raise ValueError('invalid weight')
        if not weight.is_finite() or weight < 0:
            raise ValueError('invalid weight')
        delivered = node.get('delivered_date')
        if current == 'delivered':
            if delivered is None:
                raise ValueError('missing date')
            try:
                date.fromisoformat(delivered)
            except ValueError as exc:
                raise ValueError('invalid date') from exc
        elif delivered is not None:
            raise ValueError('unexpected date')
        records.append({'id': ident, 'destination': destination, 'status': current, 'weight': weight, 'delivered_date': delivered})
    records = [r for r in records if status is None or r['status'] == status]
    records.sort(key=lambda r: (-r['weight'], r['id']))

    def rounded(value):
        return float(value.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
    grouped = {}
    for record in records:
        grouped[record['destination']] = grouped.get(record['destination'], Decimal('0')) + record['weight']
    grouped = {key: rounded(grouped[key]) for key in sorted(grouped)}
    start = (page - 1) * page_size
    selected = records[start:start + page_size]
    return {'total': len(records), 'total_weight_kg': rounded(sum((r['weight'] for r in records), Decimal('0'))), 'by_destination': grouped, 'shipments': [{'id': r['id'], 'destination': r['destination'], 'status': r['status'], 'weight_kg': float(r['weight']), 'delivered_date': r['delivered_date']} for r in selected]}

