def _split_escaped(line, sep=';'):
    out, cur, escaped = ([], [], False)
    for ch in line:
        if escaped:
            cur.append(ch)
            escaped = False
        elif ch == '\\':
            escaped = True
        elif ch == sep:
            out.append(''.join(cur))
            cur = []
        else:
            cur.append(ch)
    if escaped:
        raise ValueError('dangling escape')
    out.append(''.join(cur))
    return out

def _frames(value):
    result = []
    for part in value.split(','):
        part = part.strip()
        if not part:
            raise ValueError('invalid frame')
        if '-' in part:
            bits = part.split('-')
            if len(bits) != 2 or not all((x.isdigit() for x in bits)):
                raise ValueError('invalid frame')
            start, end = map(int, bits)
            if start <= 0 or end < start:
                raise ValueError('invalid frame')
            result.extend(range(start, end + 1))
        elif part.isdigit() and int(part) > 0:
            result.append(int(part))
        else:
            raise ValueError('invalid frame')
    if len(result) != len(set(result)):
        raise ValueError('duplicate frame')
    return sorted(result)

def parse_manifest(text: str, tenant_id: str, owner_id: str) -> list[dict]:
    jobs, seen = ([], set())
    for raw in text.splitlines():
        if not raw.strip() or raw.lstrip().startswith('#'):
            continue
        fields = _split_escaped(raw)
        if len(fields) != 5:
            raise ValueError('field count')
        ident, frame_text, priority, tags, renderer = fields
        if not ident or not renderer or ident in seen:
            raise ValueError('invalid job')
        try:
            priority = int(priority)
        except ValueError:
            raise ValueError('invalid priority')
        if not 0 <= priority <= 100:
            raise ValueError('invalid priority')
        tag_list = []
        for tag in tags.split(','):
            tag = tag.strip()
            if tag and tag not in tag_list:
                tag_list.append(tag)
        jobs.append({'id': ident, 'frames': _frames(frame_text), 'priority': priority, 'tags': tag_list, 'renderer': renderer, 'tenant_id': tenant_id, 'owner_id': owner_id, 'status': 'queued'})
        seen.add(ident)
    return jobs

def queue_order(jobs: list[dict]) -> list[dict]:
    ranks = {'running': 0, 'queued': 1, 'paused': 2, 'cancelled': 3}
    for job in jobs:
        if job.get('status') not in ranks:
            raise ValueError('unknown status')
    return sorted(jobs, key=lambda j: (ranks[j['status']], -j['priority'], len(j['frames']), j['id']))

def cancel_render(requester: dict, jobs: list[dict], job_id: str) -> dict:
    job = next((j for j in jobs if j.get('id') == job_id), None)
    if job is None:
        raise KeyError(job_id)
    if job['status'] in ('completed', 'running'):
        raise ValueError('cannot cancel')
    same_tenant = requester.get('tenant_id') == job.get('tenant_id')
    allowed = requester.get('id') == job.get('owner_id') or ('farm_admin' in requester.get('roles', []) and same_tenant)
    if not allowed:
        raise PermissionError('not permitted')
    job['status'] = 'cancelled'
    return job

