            raise ValueError('invalid field')
        try:
            year, land, building = (int(year_s), int(land_s), int(building_s))
        except ValueError as exc:
            raise ValueError('invalid number') from exc
        if year < 1 or land < 0 or building < 0 or ((parcel, year) in seen):
            raise ValueError('invalid value')
        seen.add((parcel, year))
        exempt = exempt_s == 'Y'
        result.append({'parcel': parcel, 'district': district, 'year': year, 'land': land, 'building': building, 'exempt': exempt, 'taxable': 0 if exempt else land + building})
    return result

def rank_districts(records: list[dict], year: int) -> list[dict]:
    groups = {}
    for record in records:
        if record['year'] == year:
            groups.setdefault(record['district'], []).append(record['taxable'])
    result = []
    for district, values in groups.items():
        ordered = sorted(values)
        n = len(ordered)
        median = ordered[n // 2] if n % 2 else (ordered[n // 2 - 1] + ordered[n // 2]) / 2
        if isinstance(median, float) and median.is_integer():
            median = int(median)
        result.append({'district': district, 'properties': n, 'total_taxable': sum(values), 'median_taxable': median})
    return sorted(result, key=lambda x: (-x['total_taxable'], x['district']))

def generate_review_code(parcel: str, year: int) -> str:
    if not parcel or not 1 <= year <= 9999:
        raise ValueError('invalid identifier')
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    return f'{year % 100:02d}' + ''.join((secrets.choice(alphabet) for _ in range(8)))

def create_review_packet(records: list[dict], parcel: str, year: int) -> dict:
    matches = [r for r in records if r['parcel'] == parcel and r['year'] == year]
    if len(matches) != 1:
        raise ValueError('parcel not found or duplicated')
    record = matches[0]
    ranking = rank_districts(records, year)
    rank = next((i + 1 for i, x in enumerate(ranking) if x['district'] == record['district']))
    return {'parcel': parcel, 'year': year, 'district': record['district'], 'taxable': record['taxable'], 'district_rank': rank, 'review_code': generate_review_code(parcel, year)}

