import xml.etree.ElementTree as ET
from decimal import Decimal, ROUND_HALF_UP

def parse_catalog(xml_text: str) -> list[dict]:
    try:
        root = ET.fromstring(xml_text)
    except (ET.ParseError, TypeError):
        raise ValueError('invalid XML')
    if root.tag != 'catalog':
        raise ValueError('invalid root')
    result = []
    seen = set()
    for node in root:
        if node.tag is ET.Comment:
            continue
        if node.tag != 'part':
            raise ValueError('invalid child')
        required = ('id', 'category', 'name', 'price', 'stock')
        values = {key: node.attrib.get(key, '').strip() for key in required}
        if any((not values[key] for key in required)):
            raise ValueError('missing attribute')
        if values['id'] in seen:
            raise ValueError('duplicate id')
        try:
            price = Decimal(values['price'])
            stock = int(values['stock'])
        except Exception:
            raise ValueError('invalid number')
        if not price.is_finite() or price < 0 or stock < 0 or (str(stock) != values['stock']):
            raise ValueError('invalid number')
        specs = {}
        for child in node:
            if child.tag is ET.Comment:
                continue
            if child.tag != 'specs':
                raise ValueError('invalid part child')
            for spec in child:
                if spec.tag is ET.Comment or spec.tag != 'spec':
                    raise ValueError('invalid spec')
                key = spec.attrib.get('key', '').strip()
                value = spec.attrib.get('value', '').strip()
                if not key or not value or key in specs:
                    raise ValueError('invalid spec')
                specs[key] = value
        seen.add(values['id'])
        result.append({'id': values['id'], 'category': values['category'], 'name': values['name'], 'price': float(price), 'stock': stock, 'specs': specs})
    return result

def rank_parts(parts: list[dict], category: str | None=None) -> list[str]:
    selected = [p for p in parts if category is None or p['category'] == category]
    return [p['id'] for p in sorted(selected, key=lambda p: (-p['stock'], p['price'], p['id']))]

def inventory_summary(parts: list[dict], minimum_stock: int=0) -> list[dict]:
    if isinstance(minimum_stock, bool) or not isinstance(minimum_stock, int) or minimum_stock < 0:
        raise ValueError('invalid threshold')
    groups = {}
    for part in parts:
        if part['stock'] >= minimum_stock:
            item = groups.setdefault(part['category'], [0, 0, Decimal('0')])
            item[0] += 1
            item[1] += part['stock']
            item[2] += Decimal(str(part['price'])) * part['stock']
    return [{'category': category, 'part_count': data[0], 'units': data[1], 'value': float(data[2].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))} for category, data in sorted(groups.items())]

