import re
from datetime import date
from lxml import etree

def _name(element):
    return etree.QName(element).localname

def _children(element, name):
    return [child for child in element if _name(child) == name]

def parse_document(xml: str) -> dict:
    if not isinstance(xml, str):
        raise ValueError('xml must be a string')
    try:
        root = etree.fromstring(xml.encode(), parser=etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False))
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if _name(root) != 'document':
        raise ValueError('invalid root')
    ident, created = (root.get('id'), root.get('created'))
    if not ident or not created or (not re.fullmatch('\\d{4}-\\d{2}-\\d{2}', created)):
        raise ValueError('invalid document attributes')
    try:
        date.fromisoformat(created)
    except ValueError as exc:
        raise ValueError('invalid date') from exc
    pages = []
    seen = set()
    for page in _children(root, 'page'):
        try:
            number = int(page.get('number', ''))
        except ValueError as exc:
            raise ValueError('invalid page number') from exc
        if number <= 0 or number in seen:
            raise ValueError('invalid page number')
        seen.add(number)
        texts = _children(page, 'text')
        if len(texts) != 1:
            raise ValueError('invalid text')
        text = ' '.join(''.join(texts[0].itertext()).split())
        if not text:
            raise ValueError('empty text')
        amounts = []
        for amount in _children(page, 'amount'):
            currency = amount.get('currency', '')
            if not re.fullmatch('[A-Za-z]{3}', currency):
                raise ValueError('invalid currency')
            try:
                value = float((amount.text or '').strip())
            except ValueError as exc:
                raise ValueError('invalid amount') from exc
            amounts.append({'currency': currency, 'value': value})
        pages.append({'number': number, 'text': text, 'amounts': amounts})
    pages.sort(key=lambda item: item['number'])
    total = sum((item['value'] for page in pages for item in page['amounts']))
    return {'id': ident, 'created': created, 'pages': pages, 'total': round(total, 2)}

def aggregate_documents(documents: list[str], window: int=2) -> dict:
    if not documents or window < 1:
        raise ValueError('invalid arguments')
    parsed = sorted((parse_document(item) for item in documents), key=lambda item: (item['created'], item['id']))
    currencies = {}
    for document in parsed:
        for page in document['pages']:
            for amount in page['amounts']:
                currencies[amount['currency']] = currencies.get(amount['currency'], 0.0) + amount['value']
    by_currency = {key: round(currencies[key], 2) for key in sorted(currencies)}
    windows = []
    for start in range(0, len(parsed), window):
        group = parsed[start:start + window]
        windows.append({'ids': [item['id'] for item in group], 'pages': sum((len(item['pages']) for item in group)), 'total': round(sum((item['total'] for item in group)), 2)})
    return {'documents': len(parsed), 'total': round(sum((item['total'] for item in parsed)), 2), 'by_currency': by_currency, 'windows': windows}

