def aggregate_documents(documents: list[str], window: int=2) -> dict:
    if not documents or window < 1:
        raise ValueError('invalid arguments')
    parsed = sorted((parse_document(item) for item in documents), key=lambda item: (item['created'], item['id']))
    currencies = {}
    for document in parsed:
        for page in document['pages']:
            for amount in page['amounts']:
                currencies[amount['currency']] = currencies.get(amount['currency'], 0.0) + amount['value']
    by_currency = {key: round(currencies[key], 2) for key in sorted(currencies)}
    windows = []
    for start in range(0, len(parsed), window):
        group = parsed[start:start + window]
        windows.append({'ids': [item['id'] for item in group], 'pages': sum((len(item['pages']) for item in group)), 'total': round(sum((item['total'] for item in group)), 2)})
    return {'documents': len(parsed), 'total': round(sum((item['total'] for item in parsed)), 2), 'by_currency': by_currency, 'windows': windows}

