from datetime import date
from lxml import etree

def _read(xml_text: str) -> list[dict[str, object]]:
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml_text.encode(), parser=parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'league':
        raise ValueError('invalid root')
    found = []
    seen = set()
    for node in root:
        if node.tag != 'fixture':
            raise ValueError('invalid child')
        required = ('id', 'date', 'home', 'away', 'home_score', 'away_score')
        if any((name not in node.attrib for name in required)):
            raise ValueError('missing attribute')
        item = {name: node.attrib[name] for name in required}
        if item['id'] in seen:
            raise ValueError('duplicate id')
        seen.add(item['id'])
        try:
            date.fromisoformat(item['date'])
            hs = int(item['home_score'])
            ass = int(item['away_score'])
        except Exception as exc:
            raise ValueError('invalid fixture') from exc
        if hs < 0 or ass < 0 or item['home'] == item['away']:
            raise ValueError('invalid fixture')
        item['home_score'] = hs
        item['away_score'] = ass
        found.append(item)
    found.sort(key=lambda x: (x['date'], x['id']))
    return found

def parse_fixtures(xml_text: str) -> list[dict[str, object]]:
    return _read(xml_text)

def standings(xml_text: str) -> list[dict[str, object]]:
    table = {}
    for match in _read(xml_text):
        for team in (match['home'], match['away']):
            table.setdefault(team, {'team': team, 'played': 0, 'won': 0, 'drawn': 0, 'lost': 0, 'goals_for': 0, 'goals_against': 0, 'points': 0})
        home, away = (table[match['home']], table[match['away']])
        hs, ass = (match['home_score'], match['away_score'])
        home['played'] += 1
        away['played'] += 1
        home['goals_for'] += hs
        home['goals_against'] += ass
        away['goals_for'] += ass
        away['goals_against'] += hs
        if hs > ass:
            home['won'] += 1
            home['points'] += 3
            away['lost'] += 1
        elif hs < ass:
            away['won'] += 1
            away['points'] += 3
            home['lost'] += 1
        else:
            home['drawn'] += 1
            away['drawn'] += 1
            home['points'] += 1
            away['points'] += 1
    return sorted(table.values(), key=lambda x: (-x['points'], -(x['goals_for'] - x['goals_against']), -x['goals_for'], x['team']))

def weekly_schedule(xml_text: str) -> dict[str, list[str]]:
    result = {}
    for match in _read(xml_text):
        d = date.fromisoformat(match['date'])
        key = f'{d.isocalendar().year:04d}-W{d.isocalendar().week:02d}'
        result.setdefault(key, []).append(match['id'])
    return result

