import hashlib
import hmac
import os

def _password_record(password):
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def create_technician(technicians: dict, technician_id: str, password: str, skills: list[str], zones: list[str], available_from: int=0) -> None:
    if not isinstance(technician_id, str) or not technician_id:
        raise ValueError('invalid technician')
    if not isinstance(password, str):
        raise TypeError('password')
    if not password or not isinstance(available_from, int) or isinstance(available_from, bool) or (available_from < 0):
        raise ValueError('invalid technician')
    if technician_id in technicians:
        raise ValueError('duplicate technician')

    def clean(values):
        if not isinstance(values, list) or not values or any((not isinstance(x, str) or not x for x in values)):
            raise ValueError('invalid list')
        return list(dict.fromkeys(values))
    technicians[technician_id] = {'password_hash': _password_record(password), 'skills': clean(skills), 'zones': clean(zones), 'available_from': available_from}

def authenticate_technician(technicians: dict, technician_id: str, password: str) -> bool:
    if technician_id not in technicians or not isinstance(password, str):
        return False
    salt, expected = technicians[technician_id]['password_hash'].split('$')
    actual = hashlib.pbkdf2_hmac('sha256', password.encode(), bytes.fromhex(salt), 100000).hex()
    return hmac.compare_digest(actual, expected)

def dispatch_jobs(jobs: list[dict], technicians: dict, now: int=0) -> list[dict]:
    if not isinstance(now, int) or isinstance(now, bool) or now < 0:
        raise ValueError('invalid now')
    seen = set()
    checked = []
    required = {'id', 'zone', 'skill', 'priority', 'window', 'duration'}
    for job in jobs:
        if set(job) != required or not all((isinstance(job[k], str) and job[k] for k in ('id', 'zone', 'skill'))):
            raise ValueError('invalid job')
        if job['id'] in seen or any((not isinstance(job[k], int) or isinstance(job[k], bool) or job[k] < 0 for k in ('priority', 'duration'))):
            raise ValueError('invalid job')
        w = job['window']
        if not isinstance(w, list) or len(w) != 2 or any((not isinstance(x, int) or isinstance(x, bool) for x in w)) or (not 0 <= w[0] < w[1]):
            raise ValueError('invalid job')
        seen.add(job['id'])
        checked.append(job)
    order = sorted(checked, key=lambda j: (-j['priority'], j['window'][1], j['window'][0], j['id']))
    avail = {k: max(v['available_from'], now) for k, v in technicians.items()}
    result = []
    for job in order:
        candidates = [k for k, v in technicians.items() if job['zone'] in v['zones'] and job['skill'] in v['skills']]
        candidates.sort(key=lambda k: (avail[k], k))
        for tid in candidates:
            start = max(avail[tid], job['window'][0])
            end = start + job['duration']
            if end <= job['window'][1]:
                result.append({'job_id': job['id'], 'technician_id': tid, 'start': start, 'end': end})
                avail[tid] = end
                break
    return result

