from datetime import datetime
from copy import deepcopy
_STATUSES = {'picked_up', 'in_transit', 'out_for_delivery', 'delivered', 'exception'}

def _time(value):
    if not isinstance(value, str) or not value.endswith('Z'):
        raise ValueError('invalid timestamp')
    try:
        return datetime.strptime(value, '%Y-%m-%dT%H:%M:%SZ')
    except ValueError:
        raise ValueError('invalid timestamp')

def _allowed(requester, parcel):
    return requester.get('tenant') == parcel['tenant'] and (requester.get('id') == parcel['owner_id'] or 'supervisor' in requester.get('roles', []))

def record_event(store: dict, requester: dict, parcel_id: str, event: dict) -> dict:
    parcel = store['parcels'][parcel_id]
    if not _allowed(requester, parcel):
        raise PermissionError('not permitted')
    if not isinstance(event, dict) or set(event) != {'at', 'status', 'lat', 'lon', 'courier_id'}:
        raise ValueError('invalid event')
    stamp = _time(event['at'])
    if event['status'] not in _STATUSES or not isinstance(event['courier_id'], str):
        raise ValueError('invalid event')
    if isinstance(event['lat'], bool) or not isinstance(event['lat'], (int, float)) or (not -90 <= event['lat'] <= 90):
        raise ValueError('invalid latitude')
    if isinstance(event['lon'], bool) or not isinstance(event['lon'], (int, float)) or (not -180 <= event['lon'] <= 180):
        raise ValueError('invalid longitude')
    if parcel['events'] and stamp < _time(parcel['events'][-1]['at']):
        raise ValueError('out of order')
    parcel['events'].append(deepcopy(event))
    return {'tenant': parcel['tenant'], 'owner_id': parcel['owner_id'], 'events': deepcopy(parcel['events'])}

def route_report(store: dict, requester: dict, tenant: str, day: str) -> list[dict]:
    try:
        datetime.strptime(day, '%Y-%m-%d')
    except ValueError:
        raise ValueError('invalid day')
    parcels = store['parcels']
    if not any((parcel['tenant'] == tenant for parcel in parcels.values())):
        raise KeyError(tenant)
    rows = []
    for pid, parcel in parcels.items():
        if parcel['tenant'] != tenant:
            continue
        chosen = {}
        for event in parcel['events']:
            if event['at'][:10] == day:
                chosen[event['at']] = event
        if not chosen:
            continue
        events = [chosen[k] for k in sorted(chosen)]
        first, last = (_time(events[0]['at']), _time(events[-1]['at']))
        rows.append({'parcel_id': pid, 'courier_id': events[-1]['courier_id'], 'first_at': events[0]['at'], 'last_at': events[-1]['at'], 'final_status': events[-1]['status'], 'stops': len(events), 'elapsed_seconds': int((last - first).total_seconds())})
    return sorted(rows, key=lambda row: (row['first_at'], row['parcel_id']))

