def summarize_client_plan(requester: dict, plan: dict, week_start: str) -> dict:
    try:
        client_id = plan['client_id']
        plan['trainer_id']
        workouts = plan['workouts']
        start = date.fromisoformat(week_start)
    except (KeyError, TypeError, ValueError):
        raise ValueError('invalid plan or week')
    if start.weekday() != 0 or not isinstance(workouts, list):
        raise ValueError('invalid week or workouts')
    if not isinstance(requester, dict) or (requester.get('id') != client_id and requester.get('role') not in {'trainer', 'admin'}):
        raise PermissionError('access denied')
