    end = start + timedelta(days=7)
    for item in workouts:
        if not isinstance(item, dict):
            raise ValueError('invalid workout')
        try:
            d = date.fromisoformat(item['date'])
            name = item['exercise']
            sets = item['sets']
            reps = item['reps']
            weight = item['weight']
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid workout')
        if not isinstance(name, str) or not name or isinstance(sets, bool) or isinstance(reps, bool) or (not isinstance(sets, int)) or (not isinstance(reps, int)) or (not isinstance(weight, (int, float))) or isinstance(weight, bool) or (sets < 0) or (reps < 0) or (weight < 0):
            raise ValueError('invalid workout')
        if start <= d < end:
            grouped.setdefault(d.isoformat(), {})[name] = grouped.setdefault(d.isoformat(), {}).get(name, 0) + sets * reps * weight
    days = []
    for d in sorted(grouped):
        exercises = [{'name': n, 'volume': round(v, 2)} for n, v in grouped[d].items()]
        exercises.sort(key=lambda x: (-x['volume'], x['name']))
