def build_tracking_report(events: list[dict], config: dict[str, str]) -> dict:
    if not isinstance(events, list) or not isinstance(config, dict):
        raise TypeError('events and config have invalid types')
    if 'endpoint' not in config or 'api_token' not in config:
        raise ValueError('endpoint and api_token are required')
    if not isinstance(config['endpoint'], str) or not isinstance(config['api_token'], str):
        raise ValueError('endpoint and api_token must be strings')
    allowed = {'created', 'picked_up', 'in_transit', 'out_for_delivery', 'delivered', 'exception'}
    grouped = {}
    for index, item in enumerate(events):
        if not isinstance(item, dict):
            raise TypeError('each event must be a dictionary')
        for field in ('shipment_id', 'status', 'timestamp'):
            if field not in item or not isinstance(item[field], str):
                raise ValueError('required event fields are invalid')
        if item['status'] not in allowed:
            raise ValueError('unsupported status')
        text = item['timestamp']
        try:
            stamp = datetime.fromisoformat(text[:-1] + '+00:00' if text.endswith('Z') else text)
        except ValueError as exc:
            raise ValueError('invalid timestamp') from exc
        if stamp.tzinfo is None:
            raise ValueError('invalid timestamp')
        for field in ('location', 'note'):
            if field in item and (not isinstance(item[field], str)):
                raise ValueError('optional event fields must be strings')
        copied = {'status': item['status'], 'timestamp': item['timestamp']}
        for field in ('location', 'note'):
            if field in item:
                copied[field] = item[field]
        grouped.setdefault(item['shipment_id'], []).append((stamp, index, copied))
    shipments = []
    for shipment_id in sorted(grouped):
        nested = [x[2] for x in sorted(grouped[shipment_id], key=lambda x: (x[0], x[1]))]
        shipments.append({'id': shipment_id, 'status': nested[-1]['status'], 'events': nested, 'first_seen': nested[0]['timestamp'], 'last_seen': nested[-1]['timestamp']})
    request = {'method': 'POST', 'url': config['endpoint'] + '/bulk', 'headers': {'Authorization': 'Bearer ' + config['api_token'], 'Content-Type': 'application/json'}, 'body': {'shipments': shipments}}
    return {'shipments': shipments, 'request': request}

