import os

def encode_access_pin(pin: str) -> str:
    if not isinstance(pin, str) or not pin.isascii() or (not pin.isdigit()) or (not 4 <= len(pin) <= 12):
        raise ValueError('invalid PIN')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def check_access_pin(pin: str, stored: str) -> bool:
    if not isinstance(pin, str) or not isinstance(stored, str):
        return False
    try:
        salt_text, digest_text = stored.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def summarize_vibrations(readings: list[dict], page: int=1, page_size: int=20) -> list[dict]:
    if not isinstance(readings, list):
        raise ValueError('readings must be a list')
