        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
    groups = {}
    for reading in readings:
        if not isinstance(reading, dict) or not all((k in reading for k in ('timestamp', 'segment', 'rms'))):
            raise ValueError('invalid reading')
        timestamp, segment, rms = (reading['timestamp'], reading['segment'], reading['rms'])
        if isinstance(timestamp, bool) or not isinstance(timestamp, int) or timestamp < 0:
            raise ValueError('invalid timestamp')
        if not isinstance(segment, str) or not segment:
            raise ValueError('invalid segment')
        if isinstance(rms, bool) or not isinstance(rms, (int, float)) or (not math.isfinite(rms)) or (rms < 0):
            raise ValueError('invalid RMS')
        groups.setdefault(segment, []).append(float(rms))
    result = []
