        values = groups[segment]
        result.append({'segment': segment, 'count': len(values), 'average_rms': round(sum(values) / len(values), 2), 'peak_rms': round(max(values), 2), 'alarm_count': sum((v >= 8.0 for v in values))})
    start = (page - 1) * page_size
    return result[start:start + page_size]

