        node = root.find(path)
        text = '' if node is None or node.text is None else node.text.strip()
        if not text:
            raise ValueError('missing value')
        return text
    result = {'request_id': root.get('request_id'), 'employee_id': value('employee/id'), 'employee_name': value('employee/name'), 'document_title': value('document/title'), 'deadline': value('document/deadline'), 'signers': []}
    signers = root.find('signers')
    if signers is None:
        raise ValueError('missing signers')
