import os
from decimal import Decimal, ROUND_HALF_UP

def hash_pin(pin: str) -> str:
    if not isinstance(pin, str) or not pin:
        raise ValueError('pin must be a non-empty string')
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return 'v1$' + base64.b64encode(salt).decode() + '$' + value.hex()

def verify_pin(pin: str, stored: str) -> bool:
    if not isinstance(pin, str) or not pin or (not isinstance(stored, str)):
        return False
    try:
        version, salt_text, expected = stored.split('$', 2)
        if version != 'v1':
            return False
        salt = base64.b64decode(salt_text.encode(), validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000).hex()
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def summarize_expenses(records: list[dict], page: int=1, page_size: int=10) -> list[dict]:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    grouped = {}
    for record in records:
        if not isinstance(record, dict) or set(record) != {'employee', 'amount', 'status'}:
            raise ValueError('invalid record')
        employee, amount, status = (record['employee'], record['amount'], record['status'])
        if not isinstance(employee, str) or not employee or status not in ('approved', 'rejected'):
