def parse_measurements(text: str) -> list[tuple[datetime, str, float, float, str]]:
    result = []
    for raw in text.splitlines():
        if not raw.strip():
            continue
        parts = raw.split(',')
        if len(parts) != 5:
            raise ValueError('invalid record')
        stamp, name, level, flow, status = (p.strip() for p in parts)
        if not name or status not in {'NORMAL', 'WATCH', 'ALERT'}:
            raise ValueError('invalid record')
        try:
            if not (stamp.endswith('Z') or '+' in stamp[10:] or '-' in stamp[10:]):
                raise ValueError
            dt = datetime.fromisoformat(stamp[:-1] + '+00:00' if stamp.endswith('Z') else stamp)
            if dt.tzinfo is None:
                raise ValueError
            dt = dt.astimezone(timezone.utc)
            lev, fl = (float(level), float(flow))
            if not math.isfinite(lev) or not math.isfinite(fl):
                raise ValueError
        except Exception as exc:
            raise ValueError('invalid record') from exc
        result.append((dt, name, lev, fl, status))
    return result

def summarize_reservoirs(records: list[tuple[datetime, str, float, float, str]], limit: int | None=None) -> list[dict[str, object]]:
    if limit is not None and (isinstance(limit, bool) or not isinstance(limit, int) or limit <= 0):
        raise ValueError('invalid limit')
    groups = {}
    for stamp, name, level, flow, status in records:
        groups.setdefault(name, []).append((stamp, level, flow, status))
    result = []
    for name, rows in groups.items():
        latest = max(rows, key=lambda x: x[0])
        result.append({'reservoir': name, 'samples': len(rows), 'average_flow': round(sum((x[2] for x in rows)) / len(rows), 3), 'maximum_level': round(max((x[1] for x in rows)), 3), 'latest_timestamp': latest[0], 'alert_count': sum((x[3] != 'NORMAL' for x in rows))})
    result.sort(key=lambda x: (-x['alert_count'], -x['maximum_level'], x['reservoir']))
    return result if limit is None else result[:limit]

def generate_maintenance_code(reservoir: str, length: int=12) -> str:
    if not isinstance(reservoir, str) or not re.fullmatch('[A-Za-z0-9_]+', reservoir.strip()):
        raise ValueError('invalid reservoir')
    if isinstance(length, bool) or not isinstance(length, int) or (not 8 <= length <= 32):
        raise ValueError('invalid length')
    alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
    return reservoir.strip().upper() + '-' + ''.join((secrets.choice(alphabet) for _ in range(length)))

