import os
import zipfile

def extract_survey(base_dir: str, archive_file: str) -> list[str]:
    root = os.path.realpath(base_dir)
    os.makedirs(root, exist_ok=True)
    result = []
    with zipfile.ZipFile(archive_file) as zf:
        for info in zf.infolist():
            if info.is_dir():
                continue
            target = os.path.realpath(os.path.join(root, info.filename))
            if os.path.commonpath((root, target)) != root:
                raise ValueError('archive member outside base directory')
            os.makedirs(os.path.dirname(target), exist_ok=True)
            with zf.open(info) as source, open(target, 'wb') as dest:
                while True:
                    chunk = source.read(65536)
                    if not chunk:
                        break
                    dest.write(chunk)
            result.append(info.filename)
    return sorted(result)

def summarize_register(base_dir: str, relative_name: str) -> list[dict[str, object]]:
