import zipfile
from pathlib import Path
from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def extract_settlement_files(archive_path: str, output_dir: str) -> list[str]:
    base = Path(output_dir).resolve()
    base.mkdir(parents=True, exist_ok=True)
    result = []
    with zipfile.ZipFile(archive_path) as zf:
        for info in zf.infolist():
            if info.is_dir() or info.filename.endswith('/'):
                continue
            target = (base / info.filename).resolve()
            if target != base and base not in target.parents:
                raise ValueError('invalid archive member')
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(zf.read(info))
            result.append(info.filename)
    return sorted(result)

def aggregate_settlements(csv_text: str) -> list[dict[str, str]]:
    expected = ['trade_id', 'delivery_date', 'mwh', 'price', 'participant']
    rows = csv.reader(io.StringIO(csv_text))
    try:
        header = next(rows)
    except StopIteration:
        raise ValueError('missing header')
    if header != expected:
        raise ValueError('invalid header')
    seen = set()
    totals = {}
    for row in rows:
        if len(row) != 5 or any((x == '' for x in row)):
            raise ValueError('invalid row')
        trade, day, mwh_s, price_s, participant = row
        if trade in seen:
            raise ValueError('duplicate trade')
        seen.add(trade)
        try:
            date.fromisoformat(day)
            mwh = Decimal(mwh_s)
            price = Decimal(price_s)
        except (ValueError, InvalidOperation):
            raise ValueError('invalid value')
        if mwh <= 0 or price < 0:
            raise ValueError('invalid amount')
        key = (day, participant)
        total, weighted = totals.get(key, (Decimal('0'), Decimal('0')))
        totals[key] = (total + mwh, weighted + mwh * price)
    answer = []
    for (day, participant), (mwh, weighted) in sorted(totals.items()):
        average = (weighted / mwh).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        answer.append({'participant': participant, 'delivery_date': day, 'mwh': format(mwh, 'f').rstrip('0').rstrip('.') + ('0' if '.' not in format(mwh, 'f') else ''), 'average_price': format(average, '.2f')})
    return answer

