    r = build_delivery_manifest(o, {'DELIVERY_SIGNING_KEY': 'k'})
    assert [x['slot'] for x in r] == ['08:30-09:30', '10:00-10:30'] and r[1]['order_ids'] == ['A', 'Y', 'Z']

