        total = sum((x[1] for x in a))
        if total > 100:
            raise ValueError('slot capacity exceeded')
        a.sort(key=lambda x: (-x[2], x[0]))
        ids = [x[0] for x in a]
        wt = round(total, 2)
        fee = round(12 + 1.5 * len(a) + 0.75 * wt, 2)
        text = f"{slot}|{','.join(ids)}|{wt:.2f}|{fee:.2f}"
        out.append({'slot': slot, 'order_ids': ids, 'total_weight_kg': wt, 'fee': fee, 'signature': hmac.new(str(key).encode(), text.encode(), hashlib.sha256).hexdigest()})
    out.sort(key=lambda x: tuple(map(int, re.findall('\\d+', x['slot']))))
    return out

