def screen_compounds(records: list[dict], config: dict[str, str], page: int=1, page_size: int=10) -> dict:
    if not isinstance(records, list) or not isinstance(config, Mapping):
        raise ValueError('records and config must have valid types')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('page must be positive')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError('page_size must be positive')
    selected = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('each record must be a dictionary')
        if any((key not in record for key in ('id', 'target', 'score', 'viability'))):
            raise ValueError('record is missing a required field')
        ident, target = (record['id'], record['target'])
        score, viability = (record['score'], record['viability'])
        if not isinstance(ident, str) or not ident or (not isinstance(target, str)) or (not target):
            raise ValueError('id and target must be non-empty strings')
        if isinstance(score, bool) or not isinstance(score, (int, float)) or (not 0 <= score <= 1):
            raise ValueError('score must be between zero and one')
        if isinstance(viability, bool) or not isinstance(viability, (int, float)) or (not 0 <= viability <= 1):
            raise ValueError('viability must be between zero and one')
        if score < 0.7 or viability < 0.5:
            continue
        old = selected.get(target)
        candidate = (score, viability, ident)
        if old is None or candidate[:2] > old[:2] or (candidate[:2] == old[:2] and ident < old[2]):
            selected[target] = candidate
    ordered = sorted(selected.items(), key=lambda item: (-item[1][0], -item[1][1], item[1][2]))
    items_all = [{'id': ident, 'target': target, 'score': round(values[0], 3), 'viability': round(values[1], 3)} for target, values in ordered for ident in [values[2]]]
    start = (page - 1) * page_size
    items = items_all[start:start + page_size]
    payload = {'total': len(items_all), 'page': page, 'page_size': page_size, 'items': items}
    key = os.environ.get('SCREENING_SIGNING_KEY')
    if not key:
        raise ValueError('SCREENING_SIGNING_KEY is required')
    encoded = json.dumps(payload, sort_keys=True, separators=(',', ':')).encode('utf-8')
    signature = hmac.new(key.encode('utf-8'), encoded, hashlib.sha256).hexdigest()
    return {**payload, 'signature': signature}

