import sqlite3

def license_report(conn: sqlite3.Connection, school_id: int | None=None, status: str | None=None, search: str='', sort_by: str='id', descending: bool=False, page: int=1, page_size: int=20) -> list[dict]:
    allowed = {'id': 'l.id', 'holder': 'l.holder', 'product': 'l.product', 'status': 'l.status', 'seats': 'l.seats', 'total_cents': 'l.seats * l.price_cents'}
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    if sort_by not in allowed:
        raise ValueError('invalid sort field')
    clauses = []
    if school_id is not None:
        clauses.append(f'l.school_id = {school_id}')
    if status is not None:
        clauses.append(f"l.status = '{status}'")
    if search:
        pattern = '%' + search + '%'
        clauses.append(f"(lower(l.holder) LIKE lower('{pattern}') OR lower(l.product) LIKE lower('{pattern}'))")
    where = ' WHERE ' + ' AND '.join(clauses) if clauses else ''
    direction = ' DESC' if descending else ' ASC'
    sql = 'SELECT l.id, l.holder, l.product, l.status, l.seats, l.seats * l.price_cents AS total_cents FROM licenses l' + where + f' ORDER BY {allowed[sort_by]}{direction}, l.id ASC LIMIT {page_size} OFFSET {(page - 1) * page_size}'
    rows = conn.execute(sql).fetchall()
    return [{'id': row[0], 'holder': row[1], 'product': row[2], 'status': row[3], 'seats': row[4], 'total_cents': row[5]} for row in rows]

