def parse_duty_refund_invoice(xml_text: str) -> dict:
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml_text.encode('utf-8'), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'invoice':
        raise ValueError('invalid root')
    number = (root.get('number') or '').strip()
    currency = (root.get('currency') or '').strip()
    exporter_node = root.find('exporter')
    exporter = (exporter_node.text or '').strip() if exporter_node is not None else ''
    items_node = root.find('items')
    if not number or not currency or (not exporter) or (items_node is None):
        raise ValueError('missing invoice data')
    items = []
    for node in items_node.findall('item'):
        code = (node.get('code') or '').strip()
        if not code:
            raise ValueError('missing item code')
        try:
            quantity_text = (node.get('quantity') or '').strip()
            if not quantity_text or str(int(quantity_text)) != quantity_text:
                raise ValueError
            quantity = int(quantity_text)
            unit_value = float((node.get('unit_value') or '').strip())
            duty = float((node.get('duty') or '').strip())
        except Exception as exc:
            raise ValueError('invalid item number') from exc
        if quantity <= 0 or unit_value < 0 or duty < 0:
            raise ValueError('invalid item number')
        items.append({'code': code, 'quantity': quantity, 'unit_value': unit_value, 'duty': duty})
    if not items:
        raise ValueError('no items')
    return {'number': number, 'currency': currency, 'exporter': exporter, 'items': items, 'total_duty': sum((item['duty'] for item in items))}

