import ast

def _evaluate(node, values):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, str, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in values:
            raise ValueError()
        return values[node.id]
    if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
        a, b = (_evaluate(node.left, values), _evaluate(node.right, values))
        return {ast.Add: lambda: a + b, ast.Sub: lambda: a - b, ast.Mult: lambda: a * b, ast.Div: lambda: a / b}[type(node.op)]()
    if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.Not, ast.USub, ast.UAdd):
        value = _evaluate(node.operand, values)
        return not value if isinstance(node.op, ast.Not) else -value if isinstance(node.op, ast.USub) else +value
    if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
        result = _evaluate(node.values[0], values)
        for child in node.values[1:]:
            if isinstance(node.op, ast.And) and (not result):
                return result
            if isinstance(node.op, ast.Or) and result:
                return result
            result = _evaluate(child, values)
        return result
    if isinstance(node, ast.Compare):
        left = _evaluate(node.left, values)
        for op, child in zip(node.ops, node.comparators):
            right = _evaluate(child, values)
            if not {ast.Eq: left == right, ast.NotEq: left != right, ast.Lt: left < right, ast.LtE: left <= right, ast.Gt: left > right, ast.GtE: left >= right}[type(op)]:
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
        return {'min': min, 'max': max, 'round': round}[node.func.id](*[_evaluate(x, values) for x in node.args])
    raise ValueError()

def build_badge_roster(visitors: list[dict], rule: str, page: int=1, page_size: int=20) -> list[dict]:
