        tree = ast.parse(rule, mode='eval').body
    except Exception as exc:
        raise ValueError() from exc
    selected = []
    for visitor in visitors:
        values = {k: visitor[k] for k in ('id', 'name', 'company', 'host', 'arrival', 'clearance', 'vip')}
        try:
