import hashlib
import hmac
import os
from datetime import date

def hash_reviewer_pin(pin: str) -> str:
    if not isinstance(pin, str) or not pin:
        raise ValueError('invalid pin')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def verify_reviewer_pin(pin: str, stored: str) -> bool:
    if not isinstance(pin, str) or not pin or (not isinstance(stored, str)):
        return False
    try:
        salt_hex, digest_hex = stored.split('$', 1)
        salt = bytes.fromhex(salt_hex)
        expected = bytes.fromhex(digest_hex)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def summarize_renewals(records: list[dict], page: int=1, page_size: int=10) -> dict:
    if not isinstance(records, list) or isinstance(page, bool) or isinstance(page_size, bool) or (page < 1) or (page_size < 1):
        raise ValueError('invalid arguments')
    groups = {}
    for record in records:
        if not isinstance(record, dict) or set(record) != {'candidate', 'certification', 'credits', 'submitted', 'status'}:
            raise ValueError('invalid record')
        candidate = record['candidate']
        certification = record['certification']
        credits = record['credits']
        submitted = record['submitted']
        status = record['status']
        if not isinstance(candidate, str) or not candidate or (not isinstance(certification, str)) or (not certification):
            raise ValueError('invalid record')
        if isinstance(credits, bool) or not isinstance(credits, int) or credits < 0 or (status not in {'pending', 'approved', 'denied'}):
            raise ValueError('invalid record')
        try:
            parsed = date.fromisoformat(submitted)
        except (TypeError, ValueError):
            raise ValueError('invalid record')
        if parsed.isoformat() != submitted:
            raise ValueError('invalid record')
        if status == 'approved':
            item = groups.setdefault(candidate, [0, submitted, 0])
            item[0] += credits
            item[1] = max(item[1], submitted)
            item[2] += 1
    items = [{'candidate': k, 'total_credits': v[0], 'latest_submission': v[1], 'renewal_count': v[2]} for k, v in groups.items()]
