import csv
import io
import os
import tempfile

def parse_declarations(text: str) -> list[dict]:
    if not text:
        raise ValueError('empty input')
    try:
        rows = list(csv.reader(io.StringIO(text, newline='')))
    except csv.Error as exc:
        raise ValueError('invalid csv') from exc
    header = ['declaration_id', 'country', 'weight_kg', 'value_usd', 'priority']
    if not rows or rows[0] != header:
        raise ValueError('invalid header')
    result = []
    seen = set()
    for row in rows[1:]:
        if not row or all((not x for x in row)):
            raise ValueError('blank row')
        if len(row) != 5:
            raise ValueError('invalid row')
        ident, country, weight, value, priority = [x.strip() for x in row]
        if not ident or not country or ident in seen:
            raise ValueError('invalid identifier')
        try:
            weight_n = float(weight)
            value_n = float(value)
            priority_n = int(priority)
        except (TypeError, ValueError) as exc:
            raise ValueError('invalid number') from exc
        if weight_n <= 0 or value_n < 0 or priority_n not in range(1, 6):
            raise ValueError('out of range')
        seen.add(ident)
        result.append({'declaration_id': ident, 'country': country.upper(), 'weight_kg': weight_n, 'value_usd': value_n, 'priority': priority_n})
    result.sort(key=lambda x: (x['country'], -x['priority'], x['declaration_id']))
    return result

def build_report(text: str) -> str:
    records = parse_declarations(text)
    groups = {}
    for record in records:
        group = groups.setdefault(record['country'], [0, 0.0, 0.0, 0])
        group[0] += 1
        group[1] += record['weight_kg']
        group[2] += record['value_usd']
        group[3] += record['priority'] >= 4
    output = io.StringIO(newline='')
    writer = csv.writer(output, lineterminator='\n')
    writer.writerow(['country', 'declaration_count', 'total_weight_kg', 'total_value_usd', 'high_priority_count'])
    for country in sorted(groups):
        count, weight, value, high = groups[country]
        writer.writerow([country, count, f'{weight:.3f}', f'{value:.2f}', high])
    return output.getvalue()

def export_report(text: str, destination: str) -> None:
    data = build_report(text)
    fd, temporary = tempfile.mkstemp(prefix='.customs-', dir=os.path.dirname(os.path.abspath(destination)))
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as handle:
            fd = None
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, destination)
        temporary = None
    finally:
        if fd is not None:
            os.close(fd)
        if temporary is not None:
            try:
                os.unlink(temporary)
            except FileNotFoundError:
                pass

