import base64
import hashlib
import hmac
import json
from datetime import datetime, timedelta, timezone

def _decode(value):
    if not value or any((c not in 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_' for c in value)):
        raise ValueError('invalid encoding')
    try:
        return base64.urlsafe_b64decode(value + '=' * (-len(value) % 4))
    except Exception as exc:
        raise ValueError('invalid encoding') from exc

def verify_visit_token(token: str, secret: str, now: datetime) -> dict:
    if not isinstance(token, str) or token.count('.') != 1:
        raise ValueError('invalid token')
    if not isinstance(now, datetime) or now.tzinfo is None or now.utcoffset() != timedelta(0):
        raise ValueError('invalid time')
    encoded, supplied = token.split('.')
    payload_bytes = _decode(encoded)
    signature = _decode(supplied)
    expected = hmac.new(secret.encode('utf-8'), encoded.encode('ascii'), hashlib.sha256).digest()
    if not hmac.compare_digest(signature, expected):
        raise ValueError('invalid signature')
    try:
        data = json.loads(payload_bytes.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(data, dict) or set(data) != {'visitor', 'host', 'arrival', 'duration', 'badge'}:
        raise ValueError('invalid fields')
    visitor, host, badge = (data['visitor'], data['host'], data['badge'])
    if not all((isinstance(x, str) for x in (visitor, host, badge))):
        raise ValueError('invalid fields')
    visitor, host = (visitor.strip(), host.strip())
    if not visitor or not host or (not 3 <= len(badge) <= 10) or (not badge.isascii()) or (not badge.isalnum()) or (badge != badge.upper()):
        raise ValueError('invalid fields')
    duration = data['duration']
    if isinstance(duration, bool) or not isinstance(duration, int) or (not 15 <= duration <= 480):
        raise ValueError('invalid duration')
    arrival_text = data['arrival']
    if not isinstance(arrival_text, str) or len(arrival_text) != 20 or (not arrival_text.endswith('Z')):
        raise ValueError('invalid arrival')
    try:
        arrival = datetime.strptime(arrival_text, '%Y-%m-%dT%H:%M:%SZ').replace(tzinfo=timezone.utc)
    except ValueError as exc:
        raise ValueError('invalid arrival') from exc
    expires = arrival + timedelta(minutes=duration)
    if not arrival <= now < expires:
        raise ValueError('inactive')
    return {'visitor': visitor, 'host': host, 'arrival': arrival.strftime('%Y-%m-%dT%H:%M:%SZ'), 'duration': duration, 'badge': badge, 'expires': expires.strftime('%Y-%m-%dT%H:%M:%SZ')}

