def generate_label_manifest(shipments: list[dict], destination: str, page_size: int=50) -> dict:
    if not isinstance(shipments, list):
        raise ValueError('shipments must be a list')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('page_size must be positive')
    included = []
    for shipment in shipments:
        if not isinstance(shipment, dict):
            raise ValueError('invalid shipment')
        required = {'tracking', 'recipient', 'weight_kg', 'zone', 'status'}
        if set(shipment) != required:
            raise ValueError('invalid shipment')
        tracking = shipment['tracking']
        recipient = shipment['recipient']
        weight = shipment['weight_kg']
        zone = shipment['zone']
        status = shipment['status']
        if not isinstance(tracking, str) or not tracking:
            raise ValueError('invalid tracking')
        if not isinstance(recipient, str):
            raise ValueError('invalid recipient')
        if isinstance(weight, bool) or not isinstance(weight, (int, float)) or weight <= 0:
