        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['tracking', 'recipient', 'weight_kg', 'zone'])
            for tracking, recipient, weight, zone in included:
                writer.writerow([tracking, recipient, weight, zone])
        os.replace(temporary, destination)
    except BaseException:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    zones = {}
    for _, _, _, zone in included:
