import json
import os

def summarize_rental_catalog(base_dir: str, relative_name: str, min_daily_rate: float=0, page: int=1, page_size: int=10) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('page must be positive')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('page_size must be positive')
    if min_daily_rate < 0:
        raise ValueError('min_daily_rate must not be negative')
    base = os.path.realpath(base_dir)
    path = os.path.realpath(os.path.join(base, relative_name))
    try:
        inside = os.path.commonpath([base, path]) == base
    except ValueError:
        inside = False
    if not inside:
        raise ValueError('file is outside base directory')
    with open(path, 'r', encoding='utf-8') as handle:
        records = json.load(handle)
    selected = [item for item in records if item['available'] and item['daily_rate'] >= min_daily_rate]
    selected.sort(key=lambda item: (item['category'], item['daily_rate'], item['item_id']))
    total = len(selected)
    average = round(sum((item['daily_rate'] for item in selected)) / total, 2) if total else 0.0
    start = (page - 1) * page_size
    return {'total': total, 'average_daily_rate': average, 'items': selected[start:start + page_size]}

