import subprocess
from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def summarize_meter_readings(path: str, month: str, top_n: int) -> list[tuple[str, float]]:
    if len(month) != 7 or month[4] != '-':
        raise ValueError('invalid month')
    try:
        year = int(month[:4])
        month_number = int(month[5:])
        if not 1 <= month_number <= 12:
            raise ValueError
    except ValueError:
        raise ValueError('invalid month')
    if not isinstance(top_n, int) or isinstance(top_n, bool) or top_n <= 0:
        raise ValueError('invalid limit')
    output = subprocess.run(['cat', path], capture_output=True, text=True, check=True).stdout
    totals = {}
    for raw in output.splitlines():
        if not raw.strip():
            continue
        fields = raw.split(',')
        if len(fields) != 3:
            raise ValueError('invalid record')
        date_text, meter, reading_text = (field.strip() for field in fields)
        try:
            record_date = date.fromisoformat(date_text)
            reading = Decimal(reading_text)
        except (ValueError, InvalidOperation):
            raise ValueError('invalid record')
        if not meter or not reading.is_finite():
            raise ValueError('invalid record')
        if record_date.year == year and record_date.month == month_number:
            totals[meter] = totals.get(meter, Decimal('0')) + reading
    result = []
    for meter, total in totals.items():
        rounded = total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        result.append((meter, float(rounded)))
    result.sort(key=lambda item: (-item[1], item[0]))
    return result[:top_n]

