def verify_rotation_token(token: str, payload: str, current_secret: str, previous_secret: str | None) -> bool:
    if not token or not payload or (not token.startswith('hmac-sha256:')):
        return False
    digest = token[len('hmac-sha256:'):]
    if len(digest) != 64 or any((c not in '0123456789abcdef' for c in digest)):
