    expected = hmac.new(current_secret.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if hmac.compare_digest(digest, expected):
        return True
    if previous_secret is not None:
        expected = hmac.new(previous_secret.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()
        if hmac.compare_digest(digest, expected):
