import secrets
_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'

def _split_fields(line):
    fields = []
    current = []
    escaped = False
    for char in line.rstrip('\r\n'):
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape')
    fields.append(''.join(current))
    if len(fields) != 5:
        raise ValueError('wrong field count')
    return fields

def parse_prescriptions(text: str) -> list[dict]:
    records = []
    for line in text.splitlines():
        if not line.strip():
            continue
        fields = _split_fields(line)
        drug, patient, quantity, priority, refill = fields
        drug = drug.strip().lower()
        patient = patient.strip()
        quantity = quantity.strip()
        priority = priority.strip()
        refill = refill.strip()
        if not drug or not patient or (not quantity.isdecimal()) or (not priority.isdecimal()):
            raise ValueError('invalid prescription')
        quantity_value = int(quantity)
        priority_value = int(priority)
        if quantity_value <= 0 or priority_value > 9 or refill not in ('Y', 'N'):
            raise ValueError('invalid prescription')
        records.append({'drug': drug, 'patient': patient, 'quantity': quantity_value, 'priority': priority_value, 'refill': refill == 'Y'})
    return records

def fulfill_prescriptions(text: str, inventory: dict[str, int]) -> list[dict]:
    for value in inventory.values():
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            raise ValueError('invalid inventory')
    records = parse_prescriptions(text)
    ordered = sorted(enumerate(records), key=lambda item: (-item[1]['priority'], item[1]['drug'], item[0]))
    result = []
    for _, record in ordered:
        available = inventory.get(record['drug'], 0)
        status = 'filled' if available >= record['quantity'] else 'backorder'
        if status == 'filled':
            inventory[record['drug']] = available - record['quantity']
        result.append({**record, 'status': status, 'token': ''.join((secrets.choice(_ALPHABET) for _ in range(12)))})
    return result

