                raise ValueError('invalid manifest') from exc
            if not isinstance(manifest, dict):
                raise ValueError('invalid manifest')
            title = manifest.get('title')
            duration = manifest.get('duration')
            chapters = manifest.get('chapters')
            if not isinstance(title, str) or not title or (not isinstance(duration, int)) or isinstance(duration, bool) or (duration < 0) or (not isinstance(chapters, list)):
                raise ValueError('invalid manifest')
            checked = []
            for chapter in chapters:
                if not isinstance(chapter, dict) or not isinstance(chapter.get('start'), int) or isinstance(chapter.get('start'), bool) or (chapter['start'] < 0) or (not isinstance(chapter.get('title'), str)) or (not chapter['title']):
                    raise ValueError('invalid chapter')
                if duration == 0 or chapter['start'] >= duration:
                    raise ValueError('invalid chapter')
                checked.append(chapter)
            checked.sort(key=lambda item: item['start'])
            if any((a['start'] == b['start'] for a, b in zip(checked, checked[1:]))):
                raise ValueError('duplicate chapter')
            paths = []
            for info in archive.infolist():
                if info.is_dir():
                    continue
                target = os.path.abspath(os.path.join(destination, info.filename))
                if os.path.commonpath([destination, target]) != destination:
                    raise ValueError('invalid member')
                paths.append((info, target))
            os.makedirs(destination, exist_ok=True)
            for info, target in paths:
                os.makedirs(os.path.dirname(target), exist_ok=True)
                with archive.open(info) as source, open(target, 'wb') as output:
                    output.write(source.read())
            files = sorted((info.filename.replace('\\', '/') for info, _ in paths if info.filename != 'manifest.json'))
            return {'episode_id': episode_id, 'title': title, 'duration': duration, 'chapters': checked, 'files': files}
    except ValueError:
        raise
    except (OSError, zipfile.BadZipFile) as exc:
        raise ValueError('invalid archive') from exc

