import hashlib
import hmac
import os
from datetime import date

def normalize_application(application: dict) -> dict:
    if not isinstance(application, dict):
        raise TypeError('application must be a dictionary')
    if set(application) != {'spouse_a', 'spouse_b', 'marriage_date', 'witnesses', 'registrar_id'}:
        raise ValueError('invalid application fields')

    def clean(value):
        if not isinstance(value, str):
            raise ValueError('text required')
        value = ' '.join(value.split())
        if not value:
            raise ValueError('empty text')
        return value
    a = clean(application['spouse_a'])
    b = clean(application['spouse_b'])
    if a == b:
        raise ValueError('spouses must differ')
    d = application['marriage_date']
    if not isinstance(d, str) or len(d) != 10 or d[4] != '-' or (d[7] != '-'):
        raise ValueError('invalid date')
    try:
        date.fromisoformat(d)
    except ValueError:
        raise ValueError('invalid date')
    registrar = clean(application['registrar_id']).upper()
    witnesses = application['witnesses']
    if not isinstance(witnesses, list) or not 2 <= len(witnesses) <= 4:
        raise ValueError('invalid witnesses')
    result = []
    seen = set()
    for witness in witnesses:
        if not isinstance(witness, dict) or set(witness) != {'name', 'id'}:
            raise ValueError('invalid witness')
        name = clean(witness['name'])
        wid = clean(witness['id']).upper()
        if wid in seen or wid == registrar:
            raise ValueError('duplicate witness')
        seen.add(wid)
        result.append({'name': name, 'id': wid})
    result.sort(key=lambda x: (x['id'], x['name']))
    return {'spouse_a': a, 'spouse_b': b, 'marriage_date': d, 'registrar_id': registrar, 'witnesses': result}

def _pin_record(pin: str, context: str) -> str:
    salt = os.urandom(16)
    rounds = 100000
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt + context.encode(), rounds).hex()
    return f'{rounds}${salt.hex()}${digest}'

def _check_pin(pin: str, record: str, context: str) -> bool:
    try:
        rounds, salt, digest = record.split('$')
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), bytes.fromhex(salt) + context.encode(), int(rounds)).hex()
        return hmac.compare_digest(actual, digest)
    except (ValueError, TypeError):
        return False

def issue_certificate(application: dict, registrar_pin: str, registry: dict[str, dict]) -> dict:
    if not isinstance(registrar_pin, str) or not registrar_pin.isascii() or (not registrar_pin.isdigit()) or (not 4 <= len(registrar_pin) <= 12):
        raise ValueError('invalid PIN')
    if not isinstance(registry, dict):
        raise ValueError('invalid registry')
    data = normalize_application(application)
    prefix = data['marriage_date'].replace('-', '') + '-' + data['registrar_id']
    sequence = 1
    while f'{prefix}-{sequence:04d}' in registry:
        if not isinstance(registry[f'{prefix}-{sequence:04d}'], dict):
            raise ValueError('invalid registry entry')
        sequence += 1
    number = f'{prefix}-{sequence:04d}'
    certificate = {'certificate_number': number, **data, 'pin_record': _pin_record(registrar_pin, number)}
    registry[number] = certificate
    return certificate

def verify_certificate(certificate: dict, registrar_pin: str) -> bool:
    try:
        if not isinstance(certificate, dict) or not isinstance(registrar_pin, str):
            return False
        required = {'certificate_number', 'spouse_a', 'spouse_b', 'marriage_date', 'registrar_id', 'witnesses', 'pin_record'}
        if set(certificate) != required:
            return False
        canonical = normalize_application({k: certificate[k] for k in ('spouse_a', 'spouse_b', 'marriage_date', 'registrar_id', 'witnesses')})
        if any((certificate[k] != canonical[k] for k in canonical)):
            return False
        prefix, suffix = certificate['certificate_number'].rsplit('-', 1)
        expected = certificate['marriage_date'].replace('-', '') + '-' + certificate['registrar_id']
        if prefix != expected or len(suffix) != 4 or (not suffix.isdigit()) or (int(suffix) < 1):
            return False
        return _check_pin(registrar_pin, certificate['pin_record'], certificate['certificate_number'])
    except (TypeError, ValueError, KeyError):
        return False

