    trains = [{'id': 'A', 'delay': 4, 'platform': 2, 'passengers': 80, 'cancelled': False}, {'id': 'B', 'delay': 0, 'platform': 1, 'passengers': 120, 'cancelled': False}, {'id': 'C', 'delay': 9, 'platform': 3, 'passengers': 40, 'cancelled': True}]
