import operator

def filter_trains(trains: list[dict[str, object]], rule: str) -> list[dict[str, object]]:
    tree = ast.parse(rule, mode='eval').body
    functions = {'min': min, 'max': max, 'round': round}
    binary = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
    comparisons = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}

    def calculate(node, values):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in values:
                raise ValueError('unknown name')
            return values[node.id]
        if isinstance(node, ast.BinOp) and type(node.op) in binary:
            return binary[type(node.op)](calculate(node.left, values), calculate(node.right, values))
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
            value = calculate(node.operand, values)
            return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
        if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
            result = calculate(node.values[0], values)
            for item in node.values[1:]:
                if isinstance(node.op, ast.And) and (not result):
                    return result
                if isinstance(node.op, ast.Or) and result:
                    return result
                result = calculate(item, values)
            return result
        if isinstance(node, ast.Compare):
            left = calculate(node.left, values)
            for op, right_node in zip(node.ops, node.comparators):
                right = calculate(right_node, values)
                if type(op) not in comparisons or not comparisons[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in functions) and (not node.keywords):
            return functions[node.func.id](*(calculate(arg, values) for arg in node.args))
        raise ValueError('invalid rule')
    result = []
    for train in trains:
        if calculate(tree, train):
            result.append(train)
    return result

