import os
import tempfile

def export_accommodation_plan(records: list[dict], page: int=1, page_size: int=10) -> str:
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('page must be positive')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('page_size must be positive')
    grouped = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        required = {'student_id', 'student_name', 'accommodation', 'minutes', 'active'}
        if set(record) != required:
            raise ValueError('invalid record')
        student_id = record['student_id']
        name = record['student_name']
        accommodation = record['accommodation']
        minutes = record['minutes']
        active = record['active']
        if not isinstance(student_id, str) or not student_id:
            raise ValueError('invalid record')
        if not isinstance(name, str) or not isinstance(accommodation, str) or (not accommodation):
            raise ValueError('invalid record')
        if isinstance(minutes, bool) or not isinstance(minutes, int) or minutes < 0:
            raise ValueError('invalid record')
        if not isinstance(active, bool):
            raise ValueError('invalid record')
        if student_id not in grouped:
            grouped[student_id] = [name, set(), 0]
        elif grouped[student_id][0] != name:
            raise ValueError('inconsistent student name')
        if active:
            grouped[student_id][1].add(accommodation)
            grouped[student_id][2] += minutes
    rows = [(sid, value[0], '; '.join(sorted(value[1])), value[2]) for sid, value in grouped.items() if value[1]]
    rows.sort(key=lambda row: (-row[3], row[1], row[0]))
    start = (page - 1) * page_size
    selected = rows[start:start + page_size]
    fd, path = tempfile.mkstemp()
    os.close(fd)
    try:
        with open(path, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['student_id', 'student_name', 'accommodations', 'total_minutes'])
            writer.writerows(selected)
        with open(path, 'r', newline='', encoding='utf-8') as handle:
            return handle.read()
    finally:
        os.unlink(path)

