import hashlib
import hmac
import json
import os

def sign_production_report(report: dict[str, object]) -> str:
    key = os.environ.get('SOLAR_MONITOR_SIGNING_KEY')
    if not key:
        raise RuntimeError('SOLAR_MONITOR_SIGNING_KEY is required')
    payload = json.dumps(report, sort_keys=True, separators=(',', ':'), ensure_ascii=False)
    return hmac.new(key.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()

