    payload = b'A\tapple\td2\t3\nA\tapple\td1\t3\nA\tpear\td9\t1\nA\tapple\td2\t4\n'
    original = {'old': [('z', 2.0)], 'apple': [('d0', 1.0)]}
    result = apply_signed_updates(original, secret, payload, sign(secret, payload))
    assert result == {'apple': [('d2', 4.0), ('d1', 3.0), ('d0', 1.0)], 'old': [('z', 2.0)], 'pear': [('d9', 1.0)]}
    assert original == {'old': [('z', 2.0)], 'apple': [('d0', 1.0)]}

