    secret = b's'
    payload = b'D\tkeep\td1\t-\nD\tmissing\td2\t-\nA\tnew\td\t0.25\n'
    index = {'keep': [('d1', 2.0)], 'missing': [('d0', 1.0)]}
    assert apply_signed_updates(index, secret, payload, sign(secret, payload)) == {'missing': [('d0', 1.0)], 'new': [('d', 0.25)]}

def test_signature_and_utf8_errors():
    secret = b'abc'
    payload = b''
    good = sign(secret, payload)
    assert apply_signed_updates({}, secret, payload, good) == {}
    for sig in [good[:-1], good.upper(), 'g' * 64, '0' * 64]:
        with pytest.raises(ValueError):
            apply_signed_updates({}, secret, payload, sig)
    with pytest.raises(ValueError):
        apply_signed_updates({}, secret, b'\xff', sign(secret, b'\xff'))

def test_invalid_existing_index_is_rejected():
    secret = b'x'
    payload = b''
    cases = [{'t': [('d', 1.0), ('d', 2.0)]}, {'t': [('d', float('nan'))]}, {'t': [('d', '1')]}, {'t': ['bad']}]
