import hashlib
import hmac
import math

def _fields(line):
    out = []
    cur = []
    escaped = False
    for ch in line:
        if escaped:
            if ch == 't':
                cur.append('\t')
            elif ch == 'n':
                cur.append('\n')
            elif ch == '\\':
                cur.append('\\')
            else:
                raise ValueError('escape')
            escaped = False
        elif ch == '\\':
            escaped = True
        elif ch == '\t':
            out.append(''.join(cur))
            cur = []
        else:
            cur.append(ch)
    if escaped:
        raise ValueError('escape')
    out.append(''.join(cur))
    return out

def parse_update(line):
    fields = _fields(line)
    if len(fields) != 4 or fields[0] not in ('A', 'D') or (not fields[1]) or (not fields[2]):
        raise ValueError('record')
    if fields[0] == 'D':
        if fields[3] != '-':
            raise ValueError('delete')
        return ('D', fields[1], fields[2], None)
    try:
        score = float(fields[3])
    except (TypeError, ValueError):
        raise ValueError('score')
    if not math.isfinite(score):
        raise ValueError('score')
    return ('A', fields[1], fields[2], score)

