    if not hmac.compare_digest(supplied, expected):
        raise ValueError('signature')
    try:
        text = payload.decode('utf-8')
    except UnicodeDecodeError:
        raise ValueError('utf8')
    state = {}
    for term, entries in index.items():
        if not isinstance(term, str) or not isinstance(entries, list):
            raise ValueError('index')
        state[term] = {}
        for item in entries:
            if not isinstance(item, tuple) or len(item) != 2:
                raise ValueError('index')
            doc, score = item
            if not isinstance(doc, str) or not isinstance(score, (int, float)) or isinstance(score, bool) or (not math.isfinite(score)) or (doc in state[term]):
                raise ValueError('index')
            state[term][doc] = float(score)
    lines = text.split('\n')
    if lines and lines[-1] == '':
        lines.pop()
    for line in lines:
        if not line:
            continue
        op, term, doc, score = parse_update(line)
        bucket = state.setdefault(term, {})
        if op == 'A':
            bucket[doc] = score
        else:
            bucket.pop(doc, None)
    result = {}
    for term in sorted(state):
        if state[term]:
            result[term] = sorted(state[term].items(), key=lambda x: (-x[1], x[0]))
    return result

