    frac = parts[1] if len(parts) == 2 else ''
    if frac and (not frac.isdigit()) or len(frac) > 2:
        raise ValueError('invalid income')
    result = int(whole)
    if frac and int(frac.ljust(2, '0')) >= 50:
        result += 1
    return result

