import json
import pytest


def make_payload(precinct="P-101", name="Central Library", address="10 Main Street"):
    return json.dumps({
        "precinct": precinct,
        "polling_place": {"name": name, "address": address},
    }, separators=(",", ":"))


def make_signature(payload, secret="county-key"):
    return hmac.new(secret.encode(), payload.encode(), hashlib.sha256).hexdigest()


def test_valid_request_returns_expected_record():
    payload = make_payload()
    result = lookup_polling_place(payload, make_signature(payload), "county-key")
    assert result == {
        "precinct": "P-101",
        "polling_place": {"name": "Central Library", "address": "10 Main Street"},
    }


def test_valid_request_preserves_unicode_and_punctuation():
    payload = make_payload("Ward-é", "St. Mary's Hall", "4½ Oak Avenue, Suite 2")
    result = lookup_polling_place(payload, make_signature(payload, "clé"), "clé")
    assert result["precinct"] == "Ward-é"
    assert result["polling_place"] == {
        "name": "St. Mary's Hall",
        "address": "4½ Oak Avenue, Suite 2",
    }


