            coordinate = {'lat': _number(coords[0].get('lat')), 'lon': _number(coords[0].get('lon'))}
        hazards = []
        if hazards_nodes:
            for h in hazards_nodes[0]:
                if h.tag != 'hazard' or h.get('code') is None or h.get('severity') is None:
                    raise ValueError('invalid hazard')
                hazards.append({'code': h.get('code'), 'severity': h.get('severity')})
        result.append({'id': node.get('id'), 'volcano': node.get('volcano'), 'level': level, 'issued': dt.isoformat().replace('+00:00', 'Z'), 'message': message, 'ash_height_m': ash, 'coordinates': coordinate, 'hazards': hazards})
