    chosen = [(a, d) for a, d in parsed if d.timestamp() >= start]
    counts = {x: 0 for x in _LEVELS}
    groups = {}
    for a, d in chosen:
        counts[a['level']] += 1
        groups.setdefault(a['volcano'], []).append((a, d))
    out = []
    for name, items in groups.items():
        latest = max(items, key=lambda x: (x[1], x[0]['id']))[0]
