import sqlite3

def fetch_grants(conn: sqlite3.Connection, statuses: tuple[str, ...]=(), min_amount: float | None=None, search: str='', sort_by: str='awarded_on') -> list[dict]:
    allowed = {'id', 'organization', 'program', 'amount', 'status', 'awarded_on'}
    if sort_by not in allowed:
        raise ValueError('invalid sort column')
    if not statuses:
        if statuses == ():
            pass
        else:
            return []
    clauses = []
    params = []
    if statuses:
        clauses.append('status IN (' + ','.join(('?' for _ in statuses)) + ')')
        params.extend(statuses)
    if min_amount is not None:
        clauses.append('amount >= ?')
        params.append(min_amount)
    if search:
        term = search.replace('\\', '\\\\').replace('%', '\\%').replace('_', '\\_')
        clauses.append("(lower(organization) LIKE lower(?) ESCAPE '\\' OR lower(program) LIKE lower(?) ESCAPE '\\')")
        params.extend([f'%{term}%', f'%{term}%'])
    where = ' WHERE ' + ' AND '.join(clauses) if clauses else ''
    query = f'SELECT id, organization, program, amount, status, awarded_on FROM grants{where} ORDER BY {sort_by} ASC, id ASC'
    cur = conn.execute(query, params)
    names = [d[0] for d in cur.description]
    return [dict(zip(names, row)) for row in cur.fetchall()]

def summarize_grants(conn: sqlite3.Connection, statuses: tuple[str, ...]=(), min_amount: float | None=None, search: str='') -> dict[str, dict]:
    rows = fetch_grants(conn, statuses, min_amount, search, 'program')
    groups = {}
    for row in rows:
        group = groups.setdefault(row['program'], {'count': 0, 'total': 0.0, 'statuses': {}})
        group['count'] += 1
        group['total'] += row['amount']
        group['statuses'][row['status']] = group['statuses'].get(row['status'], 0) + 1
    result = {}
    for program in sorted(groups):
        group = groups[program]
        total = round(group['total'], 2)
        result[program] = {'count': group['count'], 'total_amount': total, 'average_amount': round(total / group['count'], 2), 'statuses': dict(sorted(group['statuses'].items()))}
    return result

