import datetime
import os
import zipfile

def extract_points_archive(base_dir: str, archive_path: str) -> list[str]:
    os.makedirs(base_dir, exist_ok=True)
    base = os.path.realpath(base_dir)
    result = []
    with zipfile.ZipFile(archive_path) as archive:
        for info in archive.infolist():
            if info.is_dir() or not info.filename.endswith('.pts'):
                continue
            destination = os.path.realpath(os.path.join(base, info.filename))
            if os.path.commonpath([base, destination]) != base:
                raise ValueError('archive member is outside base directory')
            os.makedirs(os.path.dirname(destination), exist_ok=True)
            with archive.open(info) as source, open(destination, 'wb') as target:
                target.write(source.read())
            result.append(destination)
    return sorted(result)

def parse_points_file(path: str) -> list[tuple[str, str, int, str]]:
    result = []
    with open(path, encoding='utf-8') as handle:
        for raw in handle:
            line = raw.strip()
            if not line or line.startswith('#'):
                continue
            fields = [part.strip() for part in line.split('|')]
            if len(fields) != 4 or not fields[0] or (not fields[1]):
                raise ValueError('invalid statement line')
            try:
                datetime.date.fromisoformat(fields[2])
                points = int(fields[3])
            except (ValueError, TypeError):
                raise ValueError('invalid statement line')
            result.append((fields[0], fields[1], fields[2], points))
    return result

def rank_accounts(records: list[tuple[str, str, str, int]], as_of: str) -> list[tuple[str, int, int]]:
    try:
        end = datetime.date.fromisoformat(as_of)
    except ValueError:
        raise ValueError('invalid date')
    start = end - datetime.timedelta(days=29)
    totals = {}
    for _, account, date_text, points in records:
        try:
            date = datetime.date.fromisoformat(date_text)
        except ValueError:
            raise ValueError('invalid date')
        if start <= date <= end:
            total, count = totals.get(account, (0, 0))
            totals[account] = (total + points, count + 1)
    result = [(account, total, count) for account, (total, count) in totals.items() if total != 0]
    return sorted(result, key=lambda item: (-item[1], -item[2], item[0]))

