import string
import pytest


def test_creates_reservation_and_updates_stock():
    stock = {"SKU-RED": 10}
    result = create_reservation("SKU-RED", 3, stock)
    assert set(result) == {"sku", "quantity", "reservation_code", "remaining"}
    assert result["sku"] == "SKU-RED"
    assert result["quantity"] == 3
    assert result["remaining"] == 7
    assert stock == {"SKU-RED": 7}
    assert len(result["reservation_code"]) == 12
    assert all(char in string.ascii_uppercase + string.digits for char in result["reservation_code"])


def test_custom_code_length_and_full_quantity():
    stock = {"SKU-BLUE": 4}
    result = create_reservation("SKU-BLUE", 4, stock, 8)
    assert result["reservation_code"] is not None
    assert len(result["reservation_code"]) == 8
    assert result["remaining"] == 0
    assert stock["SKU-BLUE"] == 0


def test_codes_are_distinct_across_reservations():
    stock = {"SKU-GREEN": 200}
    codes = {
        create_reservation("SKU-GREEN", 1, stock, 16)["reservation_code"]
        for _ in range(100)
    }
    assert len(codes) == 100
    assert stock["SKU-GREEN"] == 100


def test_missing_sku_does_not_change_stock():
    stock = {"SKU-RED": 5}
    with pytest.raises(ValueError):
        create_reservation("SKU-NONE", 1, stock)
    assert stock == {"SKU-RED": 5}


def test_insufficient_stock_does_not_change_stock():
    stock = {"SKU-RED": 2}
    with pytest.raises(ValueError):
        create_reservation("SKU-RED", 3, stock)
    assert stock == {"SKU-RED": 2}


def test_invalid_quantity_values():
    stock = {"SKU-RED": 5}
    with pytest.raises(TypeError):
        create_reservation("SKU-RED", 1.5, stock)
    with pytest.raises(TypeError):
        create_reservation("SKU-RED", True, stock)
    with pytest.raises(ValueError):
