import json
import os
from datetime import datetime

def generate_acknowledgement_report(base_dir: str, filenames: list[str], page: int, page_size: int) -> dict:
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    base = os.path.realpath(base_dir)
    latest = {}
    sequence = 0
    for name in filenames:
        path = os.path.realpath(os.path.join(base, name))
        if os.path.commonpath([base, path]) != base:
            raise ValueError('invalid filename')
        with open(path, encoding='utf-8') as handle:
            try:
                records = json.load(handle)
            except Exception as exc:
                raise ValueError('invalid JSON') from exc
        if not isinstance(records, list):
            raise ValueError('records must be a list')
        for record in records:
            if not isinstance(record, dict):
                raise ValueError('invalid record')
            fields = ('user', 'policy', 'version', 'acknowledged_at', 'acknowledged')
            if any((field not in record for field in fields)):
                raise ValueError('invalid record')
            if any((not isinstance(record[field], str) or not record[field] for field in fields[:4])):
                raise ValueError('invalid record')
            if type(record['acknowledged']) is not bool:
                raise ValueError('invalid record')
            try:
                stamp = datetime.fromisoformat(record['acknowledged_at'])
            except ValueError as exc:
                raise ValueError('invalid timestamp') from exc
            if record['acknowledged']:
                key = (record['user'], record['policy'])
                if key not in latest or (stamp, sequence) >= latest[key][0]:
                    latest[key] = ((stamp, sequence), record)
            sequence += 1
    items = [dict(value[1]) for value in latest.values()]
    items.sort(key=lambda item: (item['policy'], item['user'], item['version'], item['acknowledged_at']))
    total = len(items)
    pages = (total + page_size - 1) // page_size if total else 0
    start = (page - 1) * page_size
    policies = {}
    for item in items:
        policies.setdefault(item['policy'], []).append(item['user'])
    by_policy = [{'policy': policy, 'count': len(users), 'users': sorted(users)} for policy, users in sorted(policies.items())]
    return {'total': total, 'page': page, 'page_size': page_size, 'pages': pages, 'items': items[start:start + page_size], 'by_policy': by_policy}

