import base64
import datetime
import hashlib
import hmac
import os

def make_secret_record(secret: str) -> str:
    if not isinstance(secret, str):
        raise TypeError('secret must be a string')
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
    return base64.b64encode(salt + value).decode('ascii')

def check_secret(record: str, candidate: str) -> bool:
    if not isinstance(record, str) or not isinstance(candidate, str):
        return False
    try:
        raw = base64.b64decode(record.encode('ascii'), validate=True)
        if len(raw) != 48:
            return False
        salt, expected = (raw[:16], raw[16:])
        actual = hashlib.pbkdf2_hmac('sha256', candidate.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, UnicodeError):
        return False

def renewal_report(certificates: list[dict], today: str, page: int, page_size: int) -> dict:
    try:
        current = datetime.date.fromisoformat(today)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    selected = []
    for item in certificates:
        if not isinstance(item, dict) or any((key not in item for key in ('name', 'issuer', 'expires', 'auto_renew'))):
            raise ValueError('invalid certificate')
        if not all((isinstance(item[key], str) for key in ('name', 'issuer', 'expires'))) or not isinstance(item['auto_renew'], bool):
            raise ValueError('invalid certificate')
        try:
            expiry = datetime.date.fromisoformat(item['expires'])
        except ValueError:
            raise ValueError('invalid date')
        if item['auto_renew'] and expiry <= current + datetime.timedelta(days=30):
            selected.append((expiry, item['name'], item['issuer']))
    selected.sort(key=lambda row: (row[0], row[1]))
    counts = {}
    for _, _, issuer in selected:
        counts[issuer] = counts.get(issuer, 0) + 1
    counts = dict(sorted(counts.items()))
    start = (page - 1) * page_size
    entries = [{'name': name, 'issuer': issuer, 'expires': expiry.isoformat(), 'days_remaining': (expiry - current).days} for expiry, name, issuer in selected[start:start + page_size]]
    return {'total': len(selected), 'page': page, 'page_size': page_size, 'issuer_counts': counts, 'certificates': entries}

