import hmac
import json
from collections import defaultdict

def verify_webhook(payload: bytes, signature: str, secret: bytes) -> list[dict]:
    if not isinstance(payload, bytes) or not isinstance(secret, bytes):
        raise TypeError()
    expected = 'sha256=' + hmac.new(secret, payload, hashlib.sha256).hexdigest()
    if not isinstance(signature, str) or not hmac.compare_digest(signature, expected):
        raise ValueError('invalid signature')
    try:
        value = json.loads(payload.decode('utf-8'))
        reports = value['reports']
        if not isinstance(value, dict) or not isinstance(reports, list):
            raise ValueError()
        result = []
        for report in reports:
            if not isinstance(report, dict) or set(report) != {'facility', 'period', 'emissions_kg', 'status'}:
                raise ValueError()
            if not isinstance(report['facility'], str) or not report['facility']:
                raise ValueError()
            if not isinstance(report['period'], str) or len(report['period']) != 7 or report['period'][4] != '-' or (not report['period'][:4].isdigit()) or (not report['period'][5:].isdigit()):
                raise ValueError()
            amount = report['emissions_kg']
            if isinstance(amount, bool) or not isinstance(amount, (int, float)) or amount < 0:
                raise ValueError()
            if report['status'] not in ('accepted', 'rejected'):
                raise ValueError()
            result.append(report)
        return result
    except (ValueError, TypeError, KeyError, UnicodeError, json.JSONDecodeError):
        raise ValueError('invalid payload')

def summarize_reports(reports: list[dict], page: int=1, page_size: int=10) -> dict:
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError()
    grouped = defaultdict(lambda: [0, 0.0])
    for report in reports:
        if report['status'] == 'accepted':
            grouped[report['facility']][0] += 1
            grouped[report['facility']][1] += report['emissions_kg']
    entries = [{'facility': name, 'report_count': data[0], 'total_emissions': round(data[1], 2)} for name, data in grouped.items()]
    entries.sort(key=lambda item: (-item['total_emissions'], item['facility']))
    start = (page - 1) * page_size
    return {'total_reports': sum((item['report_count'] for item in entries)), 'facilities': entries[start:start + page_size], 'page': page, 'page_size': page_size}

