    for category in sorted(totals):
        lines.append(f'CATEGORY {category}: {_fmt(totals[category], True)}')
    lines.append(f'CLOSING BALANCE: {_fmt(balance)}')
    return '\n'.join(lines)

def write_statement(base_dir: str, filename: str, account_id: str, opening_balance: str, transactions: list[dict[str, str]], month: str) -> str:
    if not filename:
        raise ValueError('empty filename')
    base = Path(base_dir).resolve()
    target = Path(os.path.join(str(base), filename))
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(generate_statement(account_id, opening_balance, transactions, month))
    return str(target)

