from typing import Any, Mapping

def parse_activity_log(text: str) -> list[dict[str, Any]]:
    result = []
    for raw in text.splitlines():
        if not raw.strip():
            continue
        parts, current, escaped = ([], [], False)
        for char in raw:
            if escaped:
                if char not in '|\\':
                    raise ValueError('invalid escape')
                current.append(char)
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == '|':
                parts.append(''.join(current).strip())
                current = []
            else:
                current.append(char)
        if escaped:
            raise ValueError('trailing escape')
        parts.append(''.join(current).strip())
        if len(parts) != 3 or not parts[1]:
            raise ValueError('malformed activity')
        try:
            parsed_date = date.fromisoformat(parts[0])
            credits = int(parts[2])
        except Exception as exc:
            raise ValueError('malformed activity') from exc
        if credits <= 0:
            raise ValueError('credits must be positive')
        result.append({'date': parsed_date, 'category': parts[1], 'credits': credits})
    return result

def build_renewal_receipt(candidate_id: str, activity_log: str, as_of: str, config: Mapping[str, Any]) -> dict[str, Any]:
    if not candidate_id:
        raise ValueError('candidate_id is required')
    try:
        end = date.fromisoformat(as_of)
    except Exception as exc:
        raise ValueError('invalid as_of') from exc
    key = config.get('signing_key')
    if not isinstance(key, str) or not key:
        raise ValueError('missing signing key')
    minimum = config.get('minimum_credits', 30)
    per_category = config.get('minimum_category_credits', 1)
    required = config.get('required_categories', [])
    if not isinstance(minimum, int) or minimum <= 0 or (not isinstance(per_category, int)) or (per_category <= 0):
        raise ValueError('invalid thresholds')
    start = end - timedelta(days=730)
    totals, dates = ({}, [])
    for item in parse_activity_log(activity_log):
        if start <= item['date'] <= end:
            totals[item['category']] = totals.get(item['category'], 0) + item['credits']
            dates.append(item['date'])
    totals = {k: totals[k] for k in sorted(totals)}
    total = sum(totals.values())
    eligible = total >= minimum and all((totals.get(k, 0) >= per_category for k in required))
    receipt = {'candidate_id': candidate_id, 'as_of': as_of, 'eligible': eligible, 'total_credits': total, 'credits_by_category': totals, 'valid_from': min(dates).isoformat() if dates else None, 'valid_until': (end + timedelta(days=730)).isoformat() if eligible else None, 'signature': ''}
    payload = json.dumps(receipt, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode()
    receipt['signature'] = hmac.new(key.encode(), payload, hashlib.sha256).hexdigest()
    return receipt

