    for record in records:
        if not isinstance(record, dict) or not isinstance(record.get('vessel'), str) or (not record['vessel']) or (not isinstance(record.get('species'), str)) or (not record['species']):
            raise ValueError('invalid record')
        if type(record.get('kg')) not in (int, float) or record['kg'] <= 0:
            raise ValueError('invalid record')
        try:
            current = date.fromisoformat(record['date'])
        except (TypeError, ValueError):
            raise ValueError('invalid record date')
        if start <= current <= end:
            species = record['species']
            totals[species] = totals.get(species, 0) + record['kg']
            counts[species] = counts.get(species, 0) + 1
    groups = [{'species': species, 'total_kg': round(total, 2), 'record_count': counts[species]} for species, total in totals.items()]
    groups.sort(key=lambda item: (-item['total_kg'], item['species']))
    offset = (page - 1) * page_size
    payload = {'start_date': start_date, 'end_date': end_date, 'page': page, 'page_size': page_size, 'total_groups': len(groups), 'groups': groups[offset:offset + page_size]}
