        if item['status'] not in ('success', 'failed'):
            raise ValueError('invalid status')
        if not isinstance(item['duration_seconds'], (int, float)) or isinstance(item['duration_seconds'], bool) or item['duration_seconds'] < 0:
            raise ValueError('invalid duration')
        if not isinstance(item['timestamp'], int) or isinstance(item['timestamp'], bool) or item['timestamp'] < 0:
            raise ValueError('invalid timestamp')
        group = groups.setdefault(item['release'], {'count': 0, 'success': 0, 'duration': 0, 'latest': 0})
        group['count'] += 1
        group['success'] += item['status'] == 'success'
        group['duration'] += item['duration_seconds']
        group['latest'] = max(group['latest'], item['timestamp'])
    rows = []
    for release, group in groups.items():
        rows.append({'release': release, 'deployments': group['count'], 'successful': group['success'], 'success_rate': round(group['success'] / group['count'] * 100, 2), 'average_duration_seconds': round(group['duration'] / group['count'], 2), 'latest_timestamp': group['latest']})
    rows.sort(key=lambda row: (-row['latest_timestamp'], row['release']))
