    record = {'visitor': visitor.strip(), 'visit_date': visit_date, 'lines': lines, 'total': total}
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'x', encoding='utf-8') as handle:
        json.dump(record, handle, ensure_ascii=False, separators=(',', ':'))
    return path

def read_ticket(base_dir: str, filename: str) -> dict:
    path = _path(base_dir, filename)
    try:
        with open(path, encoding='utf-8') as handle:
            value = json.load(handle)
    except json.JSONDecodeError as exc:
        raise ValueError('invalid ticket') from exc
    if not isinstance(value, dict) or set(value) != {'visitor', 'visit_date', 'lines', 'total'}:
        raise ValueError('invalid ticket')
    return value

def ticket_report(base_dir: str, filenames: list[str]) -> list[dict]:
    groups = {}
    for filename in filenames:
        ticket = read_ticket(base_dir, filename)
        key = ticket['visit_date']
        if key not in groups:
            groups[key] = {'visit_date': key, 'ticket_count': 0, 'visitors': set(), 'total': 0.0, 'exhibits': {}}
        group = groups[key]
        group['ticket_count'] += 1
        group['visitors'].add(ticket['visitor'])
        group['total'] += ticket['total']
        for line in ticket['lines']:
            name = line['exhibit']
            group['exhibits'][name] = group['exhibits'].get(name, 0) + line['quantity']
    result = []
    for group in sorted(groups.values(), key=lambda item: item['visit_date']):
        ordered = dict(sorted(group['exhibits'].items(), key=lambda pair: (-pair[1], pair[0])))
        result.append({'visit_date': group['visit_date'], 'ticket_count': group['ticket_count'], 'visitor_count': len(group['visitors']), 'total': group['total'], 'exhibits': ordered})
    return result

