from lxml import etree

def publish_article(xml_text: str) -> dict:
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode('utf-8'), parser)
    except (etree.XMLSyntaxError, UnicodeError) as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'article':
        raise ValueError('root must be article')

    def text_of(node):
        return ''.join(node.itertext()).strip() if node is not None else ''
    title_node = root.find('title')
    body_node = root.find('body')
    title = text_of(title_node)
    body = text_of(body_node)
    if not title or not body:
        raise ValueError('title and body are required')
    author = text_of(root.find('author'))
    tags_node = root.find('tags')
    tags = [] if tags_node is None else [text_of(node) for node in tags_node.findall('tag')]
    tags = [tag for tag in tags if tag]
    return {'title': title, 'author': author, 'tags': tags, 'body': body}

