import ast

def _evaluate(node, values):
    if isinstance(node, ast.Constant):
        if isinstance(node.value, (int, float, str, bool)) or node.value is None:
            return node.value
        raise ValueError()
    if isinstance(node, ast.Name):
        if node.id in values:
            return values[node.id]
        if node.id in ('min', 'max', 'round'):
            return node.id
        raise NameError(node.id)
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
        value = _evaluate(node.operand, values)
        return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
    if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
        left, right = (_evaluate(node.left, values), _evaluate(node.right, values))
        if isinstance(node.op, ast.Add):
            return left + right
        if isinstance(node.op, ast.Sub):
            return left - right
        if isinstance(node.op, ast.Mult):
            return left * right
        return left / right
    if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
        result = _evaluate(node.values[0], values)
        for item in node.values[1:]:
            if isinstance(node.op, ast.And) and (not result) or (isinstance(node.op, ast.Or) and result):
                return result
            result = _evaluate(item, values)
        return result
    if isinstance(node, ast.Compare):
        left = _evaluate(node.left, values)
        for op, part in zip(node.ops, node.comparators):
            right = _evaluate(part, values)
            if not isinstance(op, (ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE)):
                raise ValueError()
            good = {ast.Eq: left == right, ast.NotEq: left != right, ast.Lt: left < right, ast.LtE: left <= right, ast.Gt: left > right, ast.GtE: left >= right}[type(op)]
            if not good:
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
        args = [_evaluate(x, values) for x in node.args]
        if node.func.id == 'min' and len(args) >= 2:
            return min(*args)
        if node.func.id == 'max' and len(args) >= 2:
            return max(*args)
        if node.func.id == 'round' and 1 <= len(args) <= 3:
            return round(*args)
    raise ValueError()

