    keys = ('id', 'organism', 'reads', 'mean_quality', 'contamination')
    if sort_by not in keys:
        raise KeyError(sort_by)
    if limit is not None and (not isinstance(limit, int) or isinstance(limit, bool) or limit < 0):
        raise ValueError()
    try:
