_HEADER = ['slide', 'specimen', 'channel', 'x', 'y', 'intensity']

def _unescape(value):
    out = []
    i = 0
    while i < len(value):
        if value[i] != '\\':
            out.append(value[i])
            i += 1
        else:
            i += 1
            if i == len(value) or value[i] not in 'tn\\':
                raise ValueError('bad escape')
            out.append({'t': '\t', 'n': '\n', '\\': '\\'}[value[i]])
            i += 1
    return ''.join(out)

def _fields(line):
    fields, cur, i = ([], [], 0)
    while i < len(line):
        if line[i] == '\t':
            fields.append(_unescape(''.join(cur)))
            cur = []
        else:
            cur.append(line[i])
        i += 1
    fields.append(_unescape(''.join(cur)))
    return fields

def parse_manifest(text: str) -> list[dict]:
    if not isinstance(text, str):
        raise ValueError('text')
    lines = text.splitlines()
    if not lines or _fields(lines[0]) != _HEADER:
        raise ValueError('header')
    result, seen = ([], set())
    for line in lines[1:]:
        if not line:
            continue
        f = _fields(line)
        if len(f) != 6 or any((x == '' for x in f[:3])):
            raise ValueError('row')
        try:
            x, y = (int(f[3]), int(f[4]))
            intensity = float(f[5])
        except Exception as exc:
            raise ValueError('number') from exc
        if x < 0 or y < 0 or (not 0 <= intensity <= 1):
            raise ValueError('range')
        key = (f[0], x, y, f[2])
        if key in seen:
            raise ValueError('duplicate')
        seen.add(key)
        result.append({'slide': f[0], 'specimen': f[1], 'channel': f[2], 'x': x, 'y': y, 'intensity': intensity})
    if not result:
        raise ValueError('empty')
    return result

def verify_and_index(payload: bytes, signature: str, secret: bytes) -> list[dict]:
    try:
        expected = hmac.new(secret, payload, hashlib.sha256).hexdigest()
        valid = hmac.compare_digest(expected, signature)
    except Exception:
        valid = False
    if not valid:
        raise PermissionError('signature')
    try:
        text = payload.decode('utf-8')
    except UnicodeDecodeError as exc:
        raise ValueError('utf8') from exc
    groups = {}
    for row in parse_manifest(text):
        key = (row['specimen'], row['channel'])
