import re
import secrets
from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def make_editor_invite_code(length: int=12) -> str:
    if length < 1:
        raise ValueError('length must be positive')
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    return ''.join((secrets.choice(alphabet) for _ in range(length)))

def build_royalty_report(entries: list[dict], rates: dict[str, object], period: str) -> list[dict]:
    match = re.fullmatch('(\\d{4})-Q([1-4])', period)
    if not match:
        raise ValueError('invalid period')
    year, quarter = (int(match.group(1)), int(match.group(2)))
    grouped = {}
    for item in entries:
        try:
            author, title, channel = (item['author'], item['title'], item['channel'])
            units, price, raw_date = (item['units'], item['price'], item['date'])
        except (KeyError, TypeError):
            raise ValueError('invalid entry')
        if not isinstance(author, str) or not author or (not isinstance(title, str)) or (not title) or (not isinstance(channel, str)) or (not channel):
            raise ValueError('invalid text')
        if isinstance(units, bool) or not isinstance(units, int) or units < 0:
            raise ValueError('invalid units')
        try:
            value = Decimal(str(price))
            rate = Decimal(str(rates[channel]))
            parsed = date.fromisoformat(raw_date)
        except (KeyError, TypeError, ValueError, InvalidOperation):
            raise ValueError('invalid value')
        if value < 0 or rate < 0 or rate > 100 or (parsed.year != int(raw_date[:4])) or (len(raw_date) != 10):
            raise ValueError('invalid value')
        if (parsed.month - 1) // 3 + 1 != quarter or parsed.year != year:
            continue
        gross = (Decimal(units) * value * rate / Decimal(100)).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        author_data = grouped.setdefault(author, {})
        title_data = author_data.setdefault(title, [0, Decimal('0.00')])
        title_data[0] += units
        title_data[1] += gross
    result = []
    for author, titles in grouped.items():
        rows = [{'title': t, 'units': v[0], 'gross': f'{v[1]:.2f}'} for t, v in titles.items()]
        rows.sort(key=lambda x: (-Decimal(x['gross']), x['title']))
        total_units = sum((x['units'] for x in rows))
        total = sum((Decimal(x['gross']) for x in rows), Decimal('0.00'))
        result.append({'author': author, 'units': total_units, 'gross': f'{total:.2f}', 'titles': rows})
    result.sort(key=lambda x: (-Decimal(x['gross']), x['author']))
    return result

