        {"job_id": "A-9", "machine": "M1", "duration": 2, "due_day": 1},
        {"job_id": "A-1", "machine": "M3", "duration": 5, "due_day": 1},
        {"job_id": "B-4", "machine": "M2", "duration": 1, "due_day": 2},
    ]
    assert build_production_schedule(jobs) == (
        "job_id,machine,duration,due_day\n"
        "A-1,M3,5,1\n"
        "A-9,M1,2,1\n"
        "B-4,M2,1,2\n"
        "Z-2,M2,4,3\n"
    )


def test_csv_fields_are_quoted_correctly():
    jobs = [{
        "job_id": "J,7",
        "machine": 'Line "A"',
        "duration": 8,
        "due_day": 4,
    }]
    assert build_production_schedule(jobs) == (
        "job_id,machine,duration,due_day\n"
        '"J,7","Line ""A""",8,4\n'
    )


def test_newlines_in_text_fields_are_preserved_as_csv_fields():
