from datetime import date, datetime
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def parse_application(row):
    try:
        values = {k: row[k] for k in ('id', 'country', 'category', 'submitted', 'status', 'fee')}
    except (KeyError, TypeError):
        raise ValueError('missing field')
    for key in ('id', 'country', 'category', 'status'):
        if not isinstance(values[key], str) or not values[key].strip():
            raise ValueError('invalid text')
    status = values['status'].strip().lower()
    if status not in {'pending', 'approved', 'denied'}:
        raise ValueError('invalid status')
    submitted = values['submitted']
    if not isinstance(submitted, str) or len(submitted) != 10:
        raise ValueError('invalid date')
    try:
        datetime.strptime(submitted, '%Y-%m-%d')
    except ValueError:
        raise ValueError('invalid date')
    try:
        fee = Decimal(str(values['fee'])).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    except (InvalidOperation, ValueError, TypeError):
        raise ValueError('invalid fee')
    if fee < 0:
        raise ValueError('invalid fee')
    return {'id': values['id'].strip(), 'country': values['country'].strip().upper(), 'category': values['category'].strip(), 'submitted': submitted, 'status': status, 'fee': fee}

def build_report(rows, as_of):
    if not isinstance(as_of, str) or len(as_of) != 10:
        raise ValueError('invalid date')
    try:
        cutoff = datetime.strptime(as_of, '%Y-%m-%d').date()
    except ValueError:
        raise ValueError('invalid date')
    result = []
    seen = set()
    for row in rows:
        item = parse_application(row)
        if item['id'] in seen:
            raise ValueError('duplicate id')
        seen.add(item['id'])
        submitted = date.fromisoformat(item['submitted'])
        if submitted > cutoff:
            raise ValueError('future application')
        item['age_days'] = (cutoff - submitted).days
        result.append(item)
    result.sort(key=lambda x: (x['country'], x['submitted'], x['id']))
    return result

def export_report(rows, destination, as_of):
    report = build_report(rows, as_of)
    counts = {'pending': 0, 'approved': 0, 'denied': 0}
    total = Decimal('0.00')
    fd, temporary = tempfile.mkstemp(prefix='visa-', suffix='.csv', dir=os.path.dirname(os.path.abspath(destination)))
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['id', 'country', 'category', 'submitted', 'status', 'fee', 'age_days'])
            for item in report:
                writer.writerow([item['id'], item['country'], item['category'], item['submitted'], item['status'], format(item['fee'], '.2f'), item['age_days']])
                counts[item['status']] += 1
                total += item['fee']
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return {'rows': len(report), 'by_status': counts, 'total_fee': format(total, '.2f')}

