def get_release_summary(project: str, config: dict | None=None) -> dict:
    if config is not None:
        token = config.get('api_token')
    else:
        token = os.environ.get('RELEASE_API_TOKEN')
    if not isinstance(token, str) or not token:
        raise ValueError('missing deployment API token')
    response = requests.get(f"https://deployments.example.test/api/projects/{quote(project, safe='')}/releases", headers={'Authorization': f'Bearer {token}'}, timeout=5)
    response.raise_for_status()
    try:
        body = response.json()
        releases = body['releases']
        if not isinstance(body, dict) or not isinstance(releases, list):
            raise ValueError
        for item in releases:
            if not isinstance(item, dict):
                raise ValueError
            if not all((isinstance(item.get(k), str) for k in ('version', 'status', 'environment', 'deployed_at'))):
                raise ValueError
            if isinstance(item.get('duration_seconds'), bool) or not isinstance(item.get('duration_seconds'), (int, float)):
                raise ValueError
    except (KeyError, TypeError, ValueError):
        raise ValueError('invalid release data')
    production = [r for r in releases if r['environment'] == 'production']
    successful = [r for r in production if r['status'] == 'success']
    ordered = sorted(successful, key=lambda r: (r['deployed_at'], r['version']), reverse=True)
    average = round(sum((r['duration_seconds'] for r in successful)) / len(successful), 2) if successful else 0.0
    return {'project': project, 'total': len(production), 'successful': len(successful), 'average_duration_seconds': average, 'latest_version': ordered[0]['version'] if ordered else None, 'recent_versions': [r['version'] for r in ordered[:5]]}

