def alt(name, price, available=True):
    return {"name": name, "price_cents": price, "available": available}


def test_owner_gets_sorted_available_options_with_calculations():
    requester = {"id": "u1", "role": "customer", "tenant_id": "t1"}
    orders = [order("o2", "u1", "t1", items=[item("Milk", 500, [alt("Organic", 425), alt("Unavailable", 300, False)])]),
              order("o1", "u1", "t1", items=[item("Bread", 300, [alt("Wholegrain", 250)])])]
    assert list_substitution_options(requester, orders) == [
        {"order_id": "o2", "item_name": "Milk", "alternative_name": "Organic", "requested_price_cents": 500, "price_cents": 425, "savings_cents": 75, "savings_percent": 15.0},
        {"order_id": "o1", "item_name": "Bread", "alternative_name": "Wholegrain", "requested_price_cents": 300, "price_cents": 250, "savings_cents": 50, "savings_percent": 16.67},
    ]


def test_manager_can_list_orders_in_same_tenant():
    requester = {"id": "staff", "role": "manager", "tenant_id": "shop"}
    orders = [order("x", "another-user", "shop", items=[item("Eggs", 999, [alt("Large", 800)])])]
    result = list_substitution_options(requester, orders)
    assert result[0]["order_id"] == "x"
    assert result[0]["savings_percent"] == 19.92


def test_closed_orders_and_unavailable_alternatives_are_omitted():
    requester = {"id": "u", "role": "customer", "tenant_id": "t"}
    orders = [order("closed", "u", "t", "closed", [item("A", 100, [alt("B", 50)])]),
              order("open", "u", "t", items=[item("C", 100, [alt("D", 50, False)])])]
    assert list_substitution_options(requester, orders) == []


def test_ties_use_all_secondary_sort_keys():
    requester = {"id": "u", "role": "customer", "tenant_id": "t"}
    orders = [order("b", "u", "t", items=[item("Z", 100, [alt("A", 50)])]),
