    assert [x["order_id"] for x in list_substitution_options(requester, orders, 2, 2)] == ["3", "2"]
    assert list_substitution_options(requester, orders, 4, 2) == []


def test_empty_orders_return_empty_list():
    assert list_substitution_options({"id": "u", "role": "customer", "tenant_id": "t"}, []) == []


def test_invalid_pagination_raises_value_error():
