import os
import tempfile


def make_file(contents: str) -> str:
    handle = tempfile.NamedTemporaryFile(mode="w", encoding="utf-8", delete=False)
    try:
        handle.write(contents)
        return handle.name
    finally:
        handle.close()


def test_sorts_by_surname_and_preserves_complete_lines():
    path = make_file(
        "B003,Zimmer,Alan,18000\n"
        "B001,Adams,Ruth,24000\n"
        "B002,Brown,Lee,21000\n"
    )
    try:
        assert sort_beneficiaries(path) == [
            "B001,Adams,Ruth,24000",
            "B002,Brown,Lee,21000",
            "B003,Zimmer,Alan,18000",
        ]
    finally:
        os.unlink(path)


def test_reverse_sorting():
    path = make_file(
        "B1,Adams,Ruth,10\n"
        "B2,Clark,Jo,20\n"
        "B3,Baker,Sam,30\n"
    )
