    args = [min_available, '%' + search + '%', '%' + search + '%']
    if genre is not None:
        sql += ' AND e.genre=?'
        args.append(genre)
    sql += ' ORDER BY ' + ordering[sort_by]
    rows = conn.execute(sql, args).fetchall()
