def generate_overtime_report(requester: dict, entries: list[dict], start_date: str, end_date: str, page: int=1, page_size: int=50) -> dict:
    if type(page) is not int or page <= 0 or type(page_size) is not int or (page_size <= 0):
        raise ValueError('invalid pagination')
    try:
        begin = date.fromisoformat(start_date)
        finish = date.fromisoformat(end_date)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
