import hashlib
import hmac
import json

def _key(config):
    value = config.get('signing_key')
    if not isinstance(value, str):
        raise ValueError('signing_key is required')
    return value.encode('utf-8')

def _payload(assignments, unassigned):
    return json.dumps({'assignments': assignments, 'unassigned': unassigned}, sort_keys=True, separators=(',', ':')).encode('utf-8')

def _signature(assignments, unassigned, key):
    return hmac.new(key, _payload(assignments, unassigned), hashlib.sha256).hexdigest()

def allocate_rail_cars(cars: list[dict], requests: list[dict], config: dict) -> dict:
    key = _key(config)
    seen = set()
    available = []
    for car in cars:
        if not all((x in car for x in ('id', 'capacity', 'available'))):
            raise ValueError('invalid car')
        if not isinstance(car['id'], str) or car['id'] in seen or (not isinstance(car['capacity'], int)) or (car['capacity'] < 0) or (not isinstance(car['available'], bool)):
            raise ValueError('invalid car')
        seen.add(car['id'])
        if car['available']:
            available.append((car['id'], car['capacity']))
    seen = set()
    checked = []
    for request in requests:
        if not all((x in request for x in ('id', 'weight', 'priority', 'destination'))):
            raise ValueError('invalid request')
        if not isinstance(request['id'], str) or request['id'] in seen or (not isinstance(request['weight'], int)) or (request['weight'] < 0) or (not isinstance(request['priority'], int)) or (not isinstance(request['destination'], str)):
            raise ValueError('invalid request')
        seen.add(request['id'])
        checked.append(request)
    checked.sort(key=lambda x: (-x['priority'], x['id']))
    assignments = []
    unassigned = []
    for request in checked:
        choices = [(capacity, car_id) for car_id, capacity in available if capacity >= request['weight']]
        if not choices:
            unassigned.append(request['id'])
            continue
        capacity, car_id = min(choices)
        available.remove((car_id, capacity))
        assignments.append({'request_id': request['id'], 'car_id': car_id, 'weight': request['weight'], 'destination': request['destination']})
    return {'assignments': assignments, 'unassigned': unassigned, 'signature': _signature(assignments, unassigned, key)}

def verify_manifest(manifest: dict, config: dict) -> bool:
    key = _key(config)
    if not isinstance(manifest, dict) or set(manifest) != {'assignments', 'unassigned', 'signature'}:
        return False
    if not isinstance(manifest['assignments'], list) or not isinstance(manifest['unassigned'], list) or (not isinstance(manifest['signature'], str)):
        return False
    expected = _signature(manifest['assignments'], manifest['unassigned'], key)
    return hmac.compare_digest(manifest['signature'], expected)

