    allowed = (ast.Expression, ast.Constant, ast.Name, ast.UnaryOp, ast.UAdd, ast.USub, ast.BinOp, ast.Add, ast.Sub, ast.Mult, ast.Div, ast.Call, ast.Load)
    for node in ast.walk(tree):
