import hmac
import os

def create_backup_record(backup_id: str, operator: str, passphrase: str, size: int, checksum: str) -> dict:
    if not isinstance(backup_id, str) or not backup_id:
        raise ValueError('invalid backup_id')
    if not isinstance(operator, str) or not operator:
        raise ValueError('invalid operator')
    if not isinstance(passphrase, str) or not passphrase:
        raise ValueError('invalid passphrase')
    if not isinstance(checksum, str) or not checksum:
        raise ValueError('invalid checksum')
    if isinstance(size, bool) or not isinstance(size, int) or size < 0:
        raise ValueError('invalid size')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', passphrase.encode(), salt, 100000)
    return {'backup_id': backup_id, 'operator': operator, 'size': size, 'checksum': checksum, 'passphrase_hash': digest.hex(), 'salt': salt.hex()}

def verify_backup_record(record: dict, passphrase: str, size: int, checksum: str) -> bool:
    try:
        if not isinstance(record, dict) or not isinstance(passphrase, str) or (not isinstance(size, int)) or isinstance(size, bool) or (size < 0) or (not isinstance(checksum, str)):
            return False
        required = {'backup_id', 'operator', 'size', 'checksum', 'passphrase_hash', 'salt'}
        if set(record) != required or record['size'] != size or record['checksum'] != checksum:
            return False
        salt = bytes.fromhex(record['salt'])
        expected = hashlib.pbkdf2_hmac('sha256', passphrase.encode(), salt, 100000).hex()
        return hmac.compare_digest(expected, record['passphrase_hash'])
    except (TypeError, ValueError, KeyError):
        return False

