            if call['call_id'] == call_id and call['status'] == 'assigned' and (call['assigned_to'] == agent_id):
                call['status'] = 'completed'
                return True
        return False

    def snapshot(self) -> list[dict]:
        return [dict(x) for x in self.calls]

