import os
import tempfile

def _checked(events):
    indexed = []
    for pos, event in enumerate(events):
        required = ('sku', 'name', 'category', 'quantity', 'price_cents', 'timestamp', 'operation')
        if any((k not in event for k in required)):
            raise ValueError('missing field')
        if not isinstance(event['sku'], str) or not event['sku'] or (not isinstance(event['category'], str)) or (not event['category']):
            raise ValueError('invalid text')
        if not isinstance(event['name'], str) or not isinstance(event['quantity'], int) or isinstance(event['quantity'], bool) or (event['quantity'] < 0):
            raise ValueError('invalid quantity')
        if not isinstance(event['price_cents'], int) or isinstance(event['price_cents'], bool) or event['price_cents'] < 0:
            raise ValueError('invalid price')
        if event['operation'] not in ('add', 'remove', 'set'):
            raise ValueError('invalid operation')
        text = event['timestamp'].replace('Z', '+00:00')
        try:
            stamp = datetime.datetime.fromisoformat(text)
        except ValueError as exc:
            raise ValueError('invalid timestamp') from exc
        indexed.append((stamp, pos, event))
    indexed.sort(key=lambda x: (x[0], x[1]))
    states = {}
    for _, _, event in indexed:
        sku = event['sku']
        old = states.get(sku, {'quantity': 0})['quantity']
        amount = event['quantity']
        if event['operation'] == 'add':
            quantity = old + amount
        elif event['operation'] == 'remove':
            quantity = old - amount
        else:
            quantity = amount
        if quantity < 0:
            raise ValueError('negative inventory')
        states[sku] = {'sku': sku, 'name': event['name'], 'category': event['category'], 'quantity': quantity, 'price_cents': event['price_cents']}
    return sorted(states.values(), key=lambda x: (x['category'], x['sku']))

def summarize_inventory(events: list[dict]) -> list[dict]:
    return _checked(events)

def export_inventory(events: list[dict], destination: str, *, category: str | None=None) -> int:
    rows = _checked(events)
    if category is not None:
        rows = [row for row in rows if row['category'] == category]
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(prefix='.inventory-', suffix='.csv', dir=parent)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as stream:
            writer = csv.DictWriter(stream, fieldnames=['sku', 'name', 'category', 'quantity', 'price_cents'])
            writer.writeheader()
            writer.writerows(rows)
        os.replace(temporary, destination)
        temporary = None
        return len(rows)
    finally:
        if temporary is not None:
            try:
                os.unlink(temporary)
            except FileNotFoundError:
                pass

