def load_bookings(text: str) -> list[dict]:
    if not text.strip():
        return []
    try:
        rows = list(csv.reader(io.StringIO(text), strict=True))
    except csv.Error as exc:
        raise ValueError('invalid CSV') from exc
    rows = [r for r in rows if any((x.strip() for x in r))]
    header = [x.strip() for x in rows[0]] if rows else []
    expected = ['client', 'issue', 'date', 'pages', 'rate', 'status']
    if header != expected:
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if len(row) != 6:
            raise ValueError('invalid row')
        client, issue, dates, pages, rate, status = [x.strip() for x in row]
        if not client or not issue or status not in ('booked', 'cancelled'):
            raise ValueError('invalid field')
        try:
            day = date.fromisoformat(dates)
            if pages.startswith('+') or not pages.isdigit() or int(pages) <= 0:
                raise ValueError
            dec = Decimal(rate)
            if not dec.is_finite() or dec < 0 or abs(dec.as_tuple().exponent) > 2:
                raise ValueError
            number = float(dec)
            if not math.isfinite(number):
                raise ValueError
        except (ValueError, InvalidOperation):
            raise ValueError('invalid value')
        result.append({'client': client, 'issue': issue, 'date': day, 'pages': int(pages), 'rate': number, 'status': status})
    return result

def rank_issues(bookings: list[dict], year: int, month: int) -> list[dict]:
    if not 1 <= month <= 12:
        raise ValueError('invalid month')
    totals = {}
    for item in bookings:
        if item['status'] == 'booked' and item['date'].year == year and (item['date'].month == month):
            entry = totals.setdefault(item['issue'], [0, 0.0])
            entry[0] += item['pages']
            entry[1] += item['pages'] * item['rate']
    answer = [{'issue': k, 'pages': v[0], 'revenue': round(v[1], 2)} for k, v in totals.items()]
    return sorted(answer, key=lambda x: (-x['revenue'], -x['pages'], x['issue']))

def make_invite_code(prefix: str='AD', length: int=10) -> str:
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    if not prefix or any((c not in alphabet for c in prefix)) or length < len(prefix):
        raise ValueError('invalid code arguments')
    return prefix + ''.join((secrets.choice(alphabet) for _ in range(length - len(prefix))))

