        raise TypeError('records must be a list')
    if not isinstance(site, str):
        raise TypeError('site must be a string')
    if isinstance(page, bool) or isinstance(page_size, bool) or page < 1 or (page_size < 1):
        raise ValueError('invalid pagination')
    try:
        first = datetime.date.fromisoformat(start)
        last = datetime.date.fromisoformat(end)
    except Exception as exc:
        raise ValueError('invalid date') from exc
    if start != first.isoformat() or end != last.isoformat() or first > last:
        raise ValueError('invalid date range')
    totals = {}
    for record in records:
        try:
            record_site = record['site']
            stamp = record['timestamp']
            amount = record['kwh']
            moment = datetime.datetime.fromisoformat(stamp)
        except Exception as exc:
            raise ValueError('invalid record') from exc
        if isinstance(amount, bool) or not isinstance(amount, (int, float)) or amount < 0:
            raise ValueError('invalid generation')
        day = moment.date()
        if record_site == site and first <= day <= last:
            key = day.isoformat()
            totals[key] = totals.get(key, 0) + amount
    rows = [{'date': key, 'kwh': round(totals[key], 2)} for key in sorted(totals)]
    offset = (page - 1) * page_size
