import hashlib
import hmac
import json

def _checked(packet, secret, now):
    if not isinstance(secret, bytes):
        raise TypeError('secret must be bytes')
    try:
        obj = json.loads(packet)
    except Exception as exc:
        raise ValueError('invalid packet') from exc
    if not isinstance(obj, dict) or set(obj) != {'session', 'timestamp', 'events', 'signature'}:
        raise ValueError('invalid fields')
    session, timestamp, events, signature = obj.values()
    if not isinstance(session, str) or not session or type(timestamp) is not int or (not isinstance(events, list)):
        raise ValueError('invalid values')
    if timestamp < now - 86400 or timestamp > now:
        raise ValueError('timestamp out of range')
    if not isinstance(signature, str) or len(signature) != 64 or any((c not in '0123456789abcdef' for c in signature)):
        raise ValueError('invalid signature')
    for event in events:
        if not isinstance(event, dict) or set(event) != {'start', 'end', 'module', 'score'}:
            raise ValueError('invalid event')
        start, end, module, score = event.values()
        if type(start) is not int or type(end) is not int or (not isinstance(module, str)) or (not module) or isinstance(score, bool) or (not isinstance(score, (int, float))) or (start < 0) or (end <= start) or (score < 0) or (score > 100):
            raise ValueError('invalid event')
    body = {'session': session, 'timestamp': timestamp, 'events': events}
    raw = json.dumps(body, sort_keys=True, separators=(',', ':')).encode()
    expected = hmac.new(secret, raw, hashlib.sha256).hexdigest().encode()
    if not hmac.compare_digest(signature.encode(), expected):
        raise ValueError('invalid signature')
    intervals = sorted(((e['start'], e['end']) for e in events))
    total = 0
    if intervals:
        left, right = intervals[0]
        for start, end in intervals[1:]:
            if start > right:
                total += right - left
                left, right = (start, end)
            else:
                right = max(right, end)
        total += right - left
    modules = sorted({e['module'] for e in events})
    average = round(sum((e['score'] for e in events)) / len(events), 2) if events else 0.0
    return {'session': session, 'timestamp': timestamp, 'event_count': len(events), 'active_seconds': total, 'average_score': average, 'modules': modules}

def verify_and_summarize(packet: str, secret: bytes, now: int) -> dict:
    return _checked(packet, secret, now)

def aggregate_packets(packets: list[str], secret: bytes, now: int) -> list[dict]:
    groups = {}
    for packet in packets:
        item = _checked(packet, secret, now)
        if item['timestamp'] < now - 3600:
            continue
        group = groups.setdefault(item['session'], {'session': item['session'], 'packets': 0, 'event_count': 0, 'active_seconds': 0, 'score': 0, 'modules': set()})
        group['packets'] += 1
        group['event_count'] += item['event_count']
        group['active_seconds'] += item['active_seconds']
        group['score'] += item['average_score'] * item['event_count']
        group['modules'].update(item['modules'])
    result = []
    for group in groups.values():
        count = group.pop('event_count')
        group['event_count'] = count
        group['average_score'] = round(group.pop('score') / count, 2) if count else 0.0
        group['modules'] = sorted(group['modules'])
