def write_degree_audit(base_dir: str, relative_path: str, completed: list[dict], requirements: dict[str, int]) -> dict:
    if not isinstance(completed, list) or not isinstance(requirements, dict):
        raise ValueError('invalid input')
    for category, required in requirements.items():
        if not isinstance(category, str) or not category or isinstance(required, bool) or (not isinstance(required, int)) or (required < 0):
            raise ValueError('invalid requirement')
    seen = set()
    normalized = []
    for course in completed:
        if not isinstance(course, dict) or set(course) != {'code', 'category', 'credits', 'grade'}:
            raise ValueError('invalid course')
        code = course['code']
        category = course['category']
        credits = course['credits']
        grade = course['grade']
        if not isinstance(code, str) or not code or code in seen:
            raise ValueError('invalid course')
        if not isinstance(category, str) or not category or category not in requirements:
            raise ValueError('invalid course')
        if isinstance(credits, bool) or not isinstance(credits, int) or credits <= 0 or (grade not in {'A', 'B', 'C', 'D', 'F'}):
            raise ValueError('invalid course')
        seen.add(code)
        normalized.append({'code': code, 'category': category, 'credits': credits, 'grade': grade})
    earned = {category: 0 for category in requirements}
    for course in normalized:
        if course['grade'] != 'F':
            earned[course['category']] += course['credits']
    categories = []
    for category in sorted(requirements):
        required = requirements[category]
        amount = earned[category]
        categories.append({'category': category, 'required': required, 'earned': amount, 'remaining': max(required - amount, 0), 'complete': amount >= required})
    report = {'complete': all((item['complete'] for item in categories)), 'categories': categories, 'courses': sorted(normalized, key=lambda item: (item['category'], item['code']))}
    base = os.path.realpath(base_dir)
    target = os.path.realpath(os.path.join(base, relative_path))
