import tempfile
import os
import pytest

def write_file(text):
    f = tempfile.NamedTemporaryFile(mode='w', encoding='utf-8', delete=False)
    try:
        f.write(text)
        return f.name
    finally:
        f.close()

def test_aggregates_and_sorts_taxpayers_and_channels():
    path = write_file('Zeta,2024-02-01,10.50,delivered,email\nAlpha,2024-12-31,2.00,pending,portal\nZeta,2024-01-03,1.25,failed,portal\nAlpha,2023-01-01,99.99,delivered,email\nZeta,2024-02-01,3.25,delivered,portal\n')
    try:
        assert build_delivery_report(path, 2024) == [{'taxpayer': 'Alpha', 'delivered': 0, 'failed': 0, 'pending': 1, 'total_cents': 200, 'channels': {'portal': 1}, 'last_date': '2024-12-31'}, {'taxpayer': 'Zeta', 'delivered': 2, 'failed': 1, 'pending': 0, 'total_cents': 1500, 'channels': {'email': 1, 'portal': 2}, 'last_date': '2024-02-01'}]
    finally:
        os.unlink(path)

def test_blank_lines_year_filter_and_tie_dates():
    path = write_file('\nBob,2022-05-01,1.00,failed,mail\nBob,2022-05-01,2.00,pending,mail\nAnn,2021-01-01,5.00,delivered,box\n   \n')
    try:
        assert build_delivery_report(path, 2022) == [{'taxpayer': 'Bob', 'delivered': 0, 'failed': 1, 'pending': 1, 'total_cents': 300, 'channels': {'mail': 2}, 'last_date': '2022-05-01'}]
    finally:
        os.unlink(path)

def test_format_report_exact_output():
    report = [{'taxpayer': 'A', 'delivered': 2, 'failed': 1, 'pending': 0, 'total_cents': 425, 'channels': {'email': 2, 'portal': 1}, 'last_date': '2024-03-02'}, {'taxpayer': 'B', 'delivered': 0, 'failed': 0, 'pending': 1, 'total_cents': 99, 'channels': {'fax': 1}, 'last_date': None}]
    assert format_delivery_report(report) == 'A | delivered=2 failed=1 pending=0 total_cents=425 last_date=2024-03-02 | channels=email:2,portal:1\nB | delivered=0 failed=0 pending=1 total_cents=99 last_date=None | channels=fax:1\n'

def test_empty_report_format():
