    cases = ['A,2024-01-01,1.00,unknown,email\n', 'A,2024-01-01,1.0,delivered,email\n', 'A,2024-02-30,1.00,delivered,email\n', 'A,2024-01-01,-1.00,delivered,email\n', 'A,2024-01-01,1.00,delivered,\n', 'A,2024-01-01,1.00,delivered,email,extra\n']
