            raise ValueError('invalid flight')
        seen.add(flight)
        checked.append((arrival, departure, flight, terminal))
    checked.sort(key=lambda x: (x[0], x[1], x[2]))
    active = {}
    free = {}
    next_number = {}
    result = {}
    for arrival, departure, flight, terminal in checked:
        available = active.setdefault(terminal, [])
        reusable = free.setdefault(terminal, [])
        while available and available[0][0] <= arrival:
            _, gate = heapq.heappop(available)
            heapq.heappush(reusable, gate)
