            gate = next_number.get(terminal, 0) + 1
            next_number[terminal] = gate
        heapq.heappush(available, (departure, gate))
        result[flight] = {'flight': flight, 'terminal': terminal, 'gate': gate}
    return [result[f] for _, _, f, _ in sorted(checked, key=lambda x: (x[3], x[0], x[1], x[2]))]

