import csv
import math
import numbers
from decimal import Decimal, ROUND_HALF_EVEN
from pathlib import Path

def write_replenishment_report(records: list[dict], output_dir: str, filename: str, page: int=1, page_size: int=50) -> str:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError('invalid page size')
    groups = {}
    for record in records:
        required = ('sku', 'on_hand', 'reorder_point', 'pack_size', 'unit_cost')
        if any((key not in record for key in required)):
            raise ValueError('malformed record')
        sku = record['sku']
        on_hand = record['on_hand']
        reorder = record['reorder_point']
        pack = record['pack_size']
        cost = record['unit_cost']
        if not isinstance(sku, str) or not sku or (not isinstance(on_hand, int)) or isinstance(on_hand, bool) or (on_hand < 0) or (not isinstance(reorder, int)) or isinstance(reorder, bool) or (reorder < 0) or (not isinstance(pack, int)) or isinstance(pack, bool) or (pack < 1) or (not isinstance(cost, numbers.Real)) or isinstance(cost, bool) or (cost < 0) or (not math.isfinite(cost)):
            raise ValueError('malformed record')
        if sku in groups:
            item = groups[sku]
            if item['pack'] != pack or item['cost'] != cost:
                raise ValueError('inconsistent record')
            item['on_hand'] += on_hand
            item['reorder'] = max(item['reorder'], reorder)
        else:
            groups[sku] = {'on_hand': on_hand, 'reorder': reorder, 'pack': pack, 'cost': cost}
    rows = []
    for sku, item in groups.items():
        if item['on_hand'] < item['reorder']:
            quantity = math.ceil((item['reorder'] - item['on_hand']) / item['pack']) * item['pack']
            rows.append((quantity, sku, item))
    rows.sort(key=lambda row: (-row[0], row[1]))
    start = (page - 1) * page_size
    selected = rows[start:start + page_size]
    base = Path(output_dir).resolve()
    target = (base / filename).resolve()
    try:
        target.relative_to(base)
    except ValueError:
        raise ValueError('filename outside output directory')
    target.parent.mkdir(parents=True, exist_ok=True)
    with target.open('w', newline='', encoding='utf-8') as handle:
        writer = csv.writer(handle)
        writer.writerow(['sku', 'on_hand', 'reorder_point', 'pack_size', 'unit_cost', 'order_qty', 'order_cost'])
        for quantity, sku, item in selected:
            cost = Decimal(str(quantity * item['cost'])).quantize(Decimal('0.01'), rounding=ROUND_HALF_EVEN)
            writer.writerow([sku, item['on_hand'], item['reorder'], item['pack'], item['cost'], quantity, format(cost, '.2f')])
    return str(target)

