        return datetime.datetime.strptime(value, '%Y-%m').strftime('%Y-%m')
    except (TypeError, ValueError):
        raise ValueError('invalid month')

def summarize_emissions(records: list[dict], factors: dict[str, float], start_month: str, end_month: str) -> list[dict]:
    start = _month(start_month)
    end = _month(end_month)
    if end < start:
        raise ValueError('invalid range')
    for key, value in factors.items():
        if not isinstance(value, (int, float)) or isinstance(value, bool) or value < 0:
            raise ValueError('invalid factor')
    grouped = {}
    for record in records:
        try:
            entity = record['entity']
            date = datetime.datetime.strptime(record['date'], '%Y-%m-%d')
            scope = record['scope']
            unit = record['unit']
            activity = record['activity']
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid record')
        month = date.strftime('%Y-%m')
        if not start <= month <= end:
            continue
        if not isinstance(activity, (int, float)) or isinstance(activity, bool) or activity < 0:
            raise ValueError('invalid activity')
        key = str(scope) + ':' + str(unit)
        if key not in factors:
            raise ValueError('missing factor')
