        rounded = {key: round(value, 3) for key, value in scopes.items()}
        result.append({'entity': entity, 'month': month, 'total_kg': round(sum(rounded.values()), 3), 'scopes': rounded})
    return sorted(result, key=lambda item: (-item['total_kg'], item['entity'], item['month']))

def generate_share_token(entity: str, month: str) -> str:
    if not isinstance(entity, str) or not entity or _month(month) != month:
        raise ValueError('invalid share details')
    return ''.join((secrets.choice(_ALPHABET) for _ in range(32)))

