import csv
import math
import subprocess
from collections import defaultdict
from pathlib import Path

def summarize_permits(path: str, city: str | None=None, min_fee: float=0.0, page: int=1, page_size: int=10) -> list[dict]:
    if min_fee < 0 or page < 1 or page_size < 1:
        raise ValueError('invalid argument')
    source = Path(path)
    if not source.is_file():
        raise FileNotFoundError(path)
    result = subprocess.run(['cat', str(source)], check=True, capture_output=True, text=True)
    groups = defaultdict(list)
    reader = csv.DictReader(result.stdout.splitlines())
    for row in reader:
        try:
            fee = float(row['fee'])
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid fee')
        if not math.isfinite(fee) or fee < 0:
            raise ValueError('invalid fee')
        if (city is None or row['city'] == city) and fee >= min_fee:
            groups[row['category']].append(fee)
    output = []
    for category, fees in groups.items():
        total = round(sum(fees), 2)
        output.append({'category': category, 'count': len(fees), 'total_fee': total, 'average_fee': round(total / len(fees), 2)})
    output.sort(key=lambda item: (-item['count'], -item['total_fee'], item['category']))
    start = (page - 1) * page_size
    return output[start:start + page_size]

