import csv
import io
from datetime import date
from decimal import Decimal, InvalidOperation

def _date(s):
    try:
        return date.fromisoformat(s)
    except ValueError:
        raise ValueError('invalid date')

def parse_ledger(text: str) -> list[dict]:
    result = []
    for row in csv.reader(io.StringIO(text)):
        if not row or not any((x.strip() for x in row)):
            continue
        if len(row) != 5:
            raise ValueError('invalid record')
        iid, pid, ds, amount, kind = [x.strip() for x in row]
        _date(ds)
        try:
            d = Decimal(amount)
        except InvalidOperation:
            raise ValueError('invalid amount')
        if d < 0 or d != d.quantize(Decimal('0.01')):
            raise ValueError('invalid amount')
        if kind not in ('payment', 'adjustment'):
            raise ValueError('invalid type')
        result.append({'invoice_id': iid, 'patient_id': pid, 'date': ds, 'cents': int(d * 100), 'type': kind})
    return sorted(result, key=lambda x: (x['date'], x['invoice_id'], x['type']))

def build_statement(requester: dict, patient_id: str, invoices: list[dict], ledger: list[dict], as_of: str) -> dict:
    end = _date(as_of)
    chosen = []
    for inv in invoices:
        if inv['patient_id'] != patient_id or _date(inv['date']) > end:
            continue
        if not (requester['role'] == 'billing_admin' and requester['tenant_id'] == inv['tenant_id'] or requester['id'] == inv['owner_id']):
            raise PermissionError('not permitted')
        chosen.append(inv)
    by_id = {x['id']: x for x in chosen}
    sums = {x['id']: 0 for x in chosen}
    for entry in ledger:
        if _date(entry['date']) > end:
            continue
        if entry['invoice_id'] not in by_id:
            raise ValueError('unknown invoice')
        if entry['patient_id'] != patient_id:
            raise ValueError('wrong patient')
        sums[entry['invoice_id']] += entry['cents']
    items = []
    totals = {'charge_cents': 0, 'paid_cents': 0, 'balance_cents': 0, 'buckets': {'current': 0, '31-60': 0, '61-90': 0, '91+': 0}}
    for inv in sorted(chosen, key=lambda x: (x['date'], x['id'])):
        age = (end - _date(inv['date'])).days
        bucket = 'current' if age <= 30 else '31-60' if age <= 60 else '61-90' if age <= 90 else '91+'
        paid = sums[inv['id']]
        balance = max(0, inv['amount_cents'] - paid)
        item = {'invoice_id': inv['id'], 'date': inv['date'], 'charge_cents': inv['amount_cents'], 'paid_cents': paid, 'balance_cents': balance, 'age_days': age, 'bucket': bucket}
        items.append(item)
        totals['charge_cents'] += inv['amount_cents']
        totals['paid_cents'] += paid
        totals['balance_cents'] += balance
        totals['buckets'][bucket] += balance
    return {'patient_id': patient_id, 'items': items, 'totals': totals}

