def make_access_code_hash(code: str) -> str:
    if not isinstance(code, str):
        raise TypeError('code must be a string')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', code.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def verify_access_code(code: str, stored_hash: str) -> bool:
    if not isinstance(code, str) or not isinstance(stored_hash, str):
        raise TypeError('arguments must be strings')
    try:
        salt_text, digest_text = stored_hash.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', code.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def summarize_openings(openings: list[dict], code: str, stored_hash: str, page: int=1, page_size: int=10) -> list[dict]:
    if not verify_access_code(code, stored_hash):
        raise PermissionError('invalid access code')
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError('invalid pagination')
