def parse_intake(text: str) -> list[dict]:
    if not text:
        raise ValueError('empty input')
    try:
        rows = list(csv.reader(io.StringIO(text)))
    except Exception as exc:
        raise ValueError('invalid csv') from exc
    if not rows or rows[0] != _FIELDS or len(rows) == 1:
        raise ValueError('invalid header or no records')
    result = []
    seen = set()
    for row in rows[1:]:
        if len(row) != 5:
            raise ValueError('invalid row')
        row = [item.strip() for item in row]
        client_id, household, status, hours, opened = row
        if not client_id or not household or status not in ('active', 'closed') or (client_id in seen):
            raise ValueError('invalid field')
        try:
            number = int(hours, 10)
            date = datetime.date.fromisoformat(opened)
        except Exception as exc:
            raise ValueError('invalid field') from exc
        if number < 0 or date.isoformat() != opened:
            raise ValueError('invalid field')
        seen.add(client_id)
        result.append({'client_id': client_id, 'household': household, 'status': status, 'hours': number, 'opened': opened})
    return result

def summarize_intake(records: list[dict]) -> list[dict]:
    grouped = {}
    for record in records:
        name = record['household']
        item = grouped.setdefault(name, {'household': name, 'active_clients': 0, 'total_hours': 0, 'latest_opened': ''})
        item['active_clients'] += record['status'] == 'active'
        item['total_hours'] += record['hours']
        item['latest_opened'] = max(item['latest_opened'], record['opened'])
    return sorted(grouped.values(), key=lambda x: (-x['active_clients'], -x['total_hours'], x['household']))

def export_intake(records: list[dict], destination: str) -> int:
    parent = os.path.dirname(os.path.abspath(destination))
    if not os.path.isdir(parent):
        raise FileNotFoundError(parent)
    fd, temporary = tempfile.mkstemp(prefix='.intake-', dir=parent, text=True)
    os.close(fd)
    try:
        rows = summarize_intake(records)
        with open(temporary, 'w', encoding='utf-8', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['household', 'active_clients', 'total_hours', 'latest_opened'])
            for row in rows:
                writer.writerow([row['household'], row['active_clients'], row['total_hours'], row['latest_opened']])
        os.replace(temporary, destination)
        return len(rows)
    except Exception:
        if os.path.exists(temporary):
            os.unlink(temporary)
