def assign_gates(requester: dict, flights: list[dict], gates: list[dict]) -> list[dict]:
    if not isinstance(requester, dict) or not all((k in requester for k in ('id', 'airline_id', 'roles'))) or (not isinstance(requester['roles'], list)):
        raise ValueError('malformed requester')
    if not isinstance(flights, list) or not isinstance(gates, list):
        raise ValueError('malformed input')
    checked = []
    for f in flights:
        required = ('id', 'airline_id', 'terminal', 'passengers', 'international', 'start', 'end')
        if not isinstance(f, dict) or any((k not in f for k in required)):
            raise ValueError('malformed flight')
        if not isinstance(f['passengers'], int) or f['passengers'] < 0 or f['start'] >= f['end']:
            raise ValueError('invalid flight')
        if requester['airline_id'] != f['airline_id'] and 'gate_manager' not in requester['roles']:
            raise PermissionError('not permitted')
        checked.append(f)
    for g in gates:
        if not isinstance(g, dict) or any((k not in g for k in ('id', 'terminal', 'capacity', 'international', 'reservations'))):
            raise ValueError('malformed gate')
        if not isinstance(g['capacity'], int) or g['capacity'] < 0:
            raise ValueError('invalid gate')
    used = {g['id']: [] for g in gates}
    result = []
    for f in sorted(checked, key=lambda x: (x['start'], x['id'])):
        choices = []
        for g in gates:
            if g['terminal'] != f['terminal'] or g['capacity'] < f['passengers'] or (f['international'] and (not g['international'])):
                continue
            intervals = list(g['reservations']) + used[g['id']]
            if any((f['start'] < r['end'] and r['start'] < f['end'] for r in intervals)):
                continue
            choices.append(g)
        if not choices:
            raise ValueError('no suitable gate')
        chosen = min(choices, key=lambda g: (g['capacity'], g['id']))
        used[chosen['id']].append({'start': f['start'], 'end': f['end']})
        result.append({'flight_id': f['id'], 'gate_id': chosen['id']})
    return result

