import hmac
import os

def encode_pin(pin: str) -> str:
    if not isinstance(pin, str) or not pin:
        raise ValueError('pin must be a non-empty string')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return base64.urlsafe_b64encode(salt + digest).decode('ascii')

def check_pin(pin: str, encoded: str) -> bool:
    if not isinstance(pin, str) or not pin or (not isinstance(encoded, str)):
        return False
    try:
        raw = base64.urlsafe_b64decode(encoded.encode('ascii'))
        if len(raw) != 48:
            return False
        salt, expected = (raw[:16], raw[16:])
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError, UnicodeError):
        return False

