import sqlite3
OUTCOMES = ('completed', 'abandoned', 'transferred', 'failed')
SORTS = {'started_at': 'c.started_at', 'duration': 'c.duration', 'caller_name': 'p.name', 'id': 'c.id'}

def setup_database(conn: sqlite3.Connection) -> None:
    conn.executescript('CREATE TABLE IF NOT EXISTS callers (id INTEGER PRIMARY KEY, name TEXT NOT NULL, phone TEXT NOT NULL, language TEXT NOT NULL); CREATE TABLE IF NOT EXISTS calls (id INTEGER PRIMARY KEY AUTOINCREMENT, caller_id INTEGER NOT NULL REFERENCES callers(id), started_at TEXT NOT NULL, outcome TEXT NOT NULL, duration INTEGER NOT NULL, menu_path TEXT NOT NULL)')
    conn.commit()

def parse_menu_path(path: str) -> list[str]:
    if not isinstance(path, str):
        raise TypeError()
    if not path:
        return []
    parts, current, escaped = ([], [], False)
    for char in path:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '>':
            if not current:
                raise ValueError()
            parts.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped or not current:
        raise ValueError()
    parts.append(''.join(current))
    return parts

def log_call(conn: sqlite3.Connection, caller_id: int, started_at: str, outcome: str, duration: int, menu_path: str) -> int:
    if outcome not in OUTCOMES or not isinstance(duration, int) or isinstance(duration, bool) or (duration < 0) or (not isinstance(started_at, str)) or (not started_at) or (not isinstance(menu_path, str)):
        raise ValueError()
    parse_menu_path(menu_path)
    cur = conn.execute('INSERT INTO calls(caller_id, started_at, outcome, duration, menu_path) VALUES (?, ?, ?, ?, ?)', (caller_id, started_at, outcome, duration, menu_path))
    conn.commit()
    return cur.lastrowid

def list_calls(conn: sqlite3.Connection, caller_id: int | None=None, outcome: str | None=None, search: str='', sort: str='started_at', reverse: bool=False, limit: int=100) -> list[dict]:
    if outcome is not None and outcome not in OUTCOMES:
        raise ValueError()
    if sort not in SORTS or not isinstance(limit, int) or isinstance(limit, bool) or (not 0 <= limit <= 1000):
        raise ValueError()
    if limit == 0:
        return []
    clauses, values = ([], [])
    if caller_id is not None:
        clauses.append('c.caller_id = ?')
        values.append(caller_id)
    if outcome is not None:
        clauses.append('c.outcome = ?')
        values.append(outcome)
    if search:
        clauses.append('(lower(p.name) LIKE lower(?) OR lower(p.phone) LIKE lower(?))')
        values.extend([f'%{search}%', f'%{search}%'])
    where = ' WHERE ' + ' AND '.join(clauses) if clauses else ''
    direction = ' DESC' if reverse else ' ASC'
    sql = 'SELECT c.id, c.caller_id, p.name, p.phone, c.started_at, c.outcome, c.duration, c.menu_path FROM calls c JOIN callers p ON p.id = c.caller_id' + where + ' ORDER BY ' + SORTS[sort] + direction + ', c.id ASC LIMIT ?'
    values.append(limit)
    rows = conn.execute(sql, values).fetchall()
    keys = ('id', 'caller_id', 'caller_name', 'phone', 'started_at', 'outcome', 'duration', 'menu_path')
    return [dict(zip(keys, row)) for row in rows]

def caller_stats(conn: sqlite3.Connection, caller_id: int) -> dict:
    if conn.execute('SELECT 1 FROM callers WHERE id = ?', (caller_id,)).fetchone() is None:
        raise ValueError()
    rows = conn.execute('SELECT outcome, COUNT(*), COALESCE(SUM(duration), 0) FROM calls WHERE caller_id = ? GROUP BY outcome', (caller_id,)).fetchall()
    counts = {name: 0 for name in OUTCOMES}
    total = 0
    number = 0
    for outcome, count, subtotal in rows:
        counts[outcome] = count
        number += count
        total += subtotal
    return {'caller_id': caller_id, 'call_count': number, 'total_duration': total, 'average_duration': total / number if number else None, 'outcomes': counts}

