import datetime
import re
import xml.etree.ElementTree as ET

def _date(value):
    try:
        return datetime.date.fromisoformat(value)
    except Exception as exc:
        raise ValueError('invalid date') from exc

def _time(value):
    if not isinstance(value, str) or not re.fullmatch('(?:[01]\\d|2[0-3]):[0-5]\\d', value):
        raise ValueError('invalid time')
    return int(value[:2]) * 60 + int(value[3:])

def parse_playlist(xml: str) -> list[dict[str, object]]:
    try:
        root = ET.fromstring(xml)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'playlist':
        raise ValueError('invalid root')
    station = (root.get('station') or '').strip()
    if not station:
        raise ValueError('invalid station')
    result = []
    ids = set()
    for day in root.findall('day'):
        date_text = day.get('date')
        date = _date(date_text) if date_text else (_ for _ in ()).throw(ValueError('missing date'))
        previous_end = -1
        for item in day.findall('item'):
            ident = (item.get('id') or '').strip()
            if not ident or ident in ids:
                raise ValueError('invalid id')
            ids.add(ident)
            start_text = item.get('start')
            duration_text = item.get('duration')
            start = _time(start_text) if start_text else (_ for _ in ()).throw(ValueError('missing start'))
            try:
                duration = int(duration_text)
            except Exception as exc:
                raise ValueError('invalid duration') from exc
            if duration < 1 or duration > 1440 or start + duration > 1440 or (start < previous_end):
                raise ValueError('invalid interval')
            previous_end = start + duration
            title_node = item.find('title')
            artist_node = item.find('artist')
            title = (title_node.text or '').strip() if title_node is not None else ''
            artist = (artist_node.text or '').strip() if artist_node is not None else ''
            if not title or not artist:
                raise ValueError('missing text')
            tags = []
            tags_node = item.find('tags')
            if tags_node is not None:
                for tag in tags_node.findall('tag'):
                    value = (tag.text or '').strip()
                    if not value:
                        raise ValueError('blank tag')
                    tags.append(value)
            result.append({'id': ident, 'station': station, 'date': date.isoformat(), 'start': start_text, 'duration': duration, 'title': title, 'artist': artist, 'tags': tags})
    result.sort(key=lambda x: (x['date'], x['start'], x['id']))
    return result

def build_schedule(items: list[dict[str, object]], first_date: str, last_date: str) -> dict[str, object]:
    first = _date(first_date)
    last = _date(last_date)
    if first > last:
        raise ValueError('invalid range')
    days = {}
    current = first
    while current <= last:
        days[current.isoformat()] = {'plays': 0, 'seconds': 0}
        current += datetime.timedelta(days=1)
    artists = {}
    for item in items:
        date = item.get('date')
        if date in days:
            seconds = int(item['duration']) * 60
            days[date]['plays'] += 1
            days[date]['seconds'] += seconds
            name = item['artist']
            if name not in artists:
                artists[name] = [0, 0]
            artists[name][0] += 1
            artists[name][1] += seconds
    ordered = sorted(artists.items(), key=lambda x: (-x[1][1], -x[1][0], x[0]))
    return {'days': days, 'artists': [{'artist': name, 'plays': values[0], 'seconds': values[1]} for name, values in ordered]}

