    current = first
    while current <= last:
        days[current.isoformat()] = {'plays': 0, 'seconds': 0}
        current += datetime.timedelta(days=1)
    artists = {}
    for item in items:
        date = item.get('date')
        if date in days:
            seconds = int(item['duration']) * 60
            days[date]['plays'] += 1
            days[date]['seconds'] += seconds
            name = item['artist']
            if name not in artists:
                artists[name] = [0, 0]
            artists[name][0] += 1
            artists[name][1] += seconds
    ordered = sorted(artists.items(), key=lambda x: (-x[1][1], -x[1][0], x[0]))
    return {'days': days, 'artists': [{'artist': name, 'plays': values[0], 'seconds': values[1]} for name, values in ordered]}

