from solution import build_rollout_page

def signed(manifest, secret='firmware-key'):
    return hmac.new(secret.encode(), manifest.encode(), hashlib.sha256).hexdigest()

def manifest_with(devices):
    return json.dumps({'devices': devices}, separators=(',', ':'))

def device(device_id, region, current='1.0', target='2.0', status='online', battery=80):
    return {'device_id': device_id, 'region': region, 'current_version': current, 'target_version': target, 'status': status, 'battery': battery}

def test_filters_and_sorts_devices():
    text = manifest_with([device('z9', 'west'), device('a2', 'east'), device('a1', 'east'), device('low', 'east', battery=29), device('same', 'north', current='2.0'), device('offline', 'west', status='offline')])
    result = build_rollout_page(text, signed(text), 'firmware-key', page=1, page_size=10)
    assert result == {'total': 3, 'page': 1, 'page_size': 10, 'pages': 1, 'devices': [{'device_id': 'a1', 'region': 'east', 'target_version': '2.0'}, {'device_id': 'a2', 'region': 'east', 'target_version': '2.0'}, {'device_id': 'z9', 'region': 'west', 'target_version': '2.0'}], 'by_region': {'east': 2, 'west': 1}}

def test_empty_manifest_has_zero_pages():
    text = manifest_with([])
    assert build_rollout_page(text, signed(text), 'firmware-key') == {'total': 0, 'page': 1, 'page_size': 2, 'pages': 0, 'devices': [], 'by_region': {}}

def test_invalid_signature_is_rejected():
    text = manifest_with([device('one', 'east')])
    with pytest.raises(PermissionError):
        build_rollout_page(text, '0' * 64, 'firmware-key')

def test_malformed_json_raises_value_error_after_valid_signature():
    text = 'not json'
    with pytest.raises(ValueError):
        build_rollout_page(text, signed(text), 'firmware-key')

def test_duplicate_ids_and_bad_pagination_raise_value_error():
    text = manifest_with([device('same', 'a'), device('same', 'b')])
    with pytest.raises(ValueError):
        build_rollout_page(text, signed(text), 'firmware-key')
    empty = manifest_with([])
    with pytest.raises(ValueError):
        build_rollout_page(empty, signed(empty), 'firmware-key', page=0)
    with pytest.raises(ValueError):
        build_rollout_page(empty, signed(empty), 'firmware-key', page_size=-1)

def test_invalid_device_shape_and_boundaries():
