    with pytest.raises(ValueError):
        build_rollout_page(bad_battery, signed(bad_battery), 'firmware-key')
    boundary = manifest_with([device('low', 'a', battery=30), device('zero', 'b', battery=0), device('full', 'c', battery=100)])
    result = build_rollout_page(boundary, signed(boundary), 'firmware-key', page_size=10)
