import hashlib
import hmac
import json
import math

def build_rollout_page(manifest: str, signature: str, secret: str, page: int=1, page_size: int=2) -> dict:
    if type(page) is not int or type(page_size) is not int or page < 1 or (page_size < 1):
        raise ValueError('invalid pagination')
    expected = hmac.new(secret.encode('utf-8'), manifest.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise PermissionError('invalid signature')
    try:
        root = json.loads(manifest)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid manifest') from exc
    if not isinstance(root, dict) or not isinstance(root.get('devices'), list):
        raise ValueError('invalid manifest')
    selected = []
    seen = set()
    for item in root['devices']:
        if not isinstance(item, dict):
            raise ValueError('invalid device')
        required = ('device_id', 'region', 'current_version', 'target_version', 'status')
        if any((not isinstance(item.get(k), str) for k in required)):
            raise ValueError('invalid device')
        battery = item.get('battery')
        if isinstance(battery, bool) or not isinstance(battery, (int, float)) or (not 0 <= battery <= 100):
            raise ValueError('invalid battery')
        device_id = item['device_id']
        if device_id in seen:
            raise ValueError('duplicate device')
        seen.add(device_id)
        if item['status'] == 'online' and battery >= 30 and (item['current_version'] != item['target_version']):
            selected.append(item)
    selected.sort(key=lambda x: (x['region'], x['device_id']))
    by_region = {}
    for item in selected:
        by_region[item['region']] = by_region.get(item['region'], 0) + 1
    total = len(selected)
    pages = math.ceil(total / page_size) if total else 0
    start = (page - 1) * page_size
    page_items = selected[start:start + page_size]
    return {'total': total, 'page': page, 'page_size': page_size, 'pages': pages, 'devices': [{'device_id': x['device_id'], 'region': x['region'], 'target_version': x['target_version']} for x in page_items], 'by_region': by_region}

