import ast
import operator

def rank_storage_options(options: list[dict], formula: str, limit: int) -> list[dict]:
    if limit < 0:
        raise ValueError('limit')
    tree = ast.parse(formula, mode='eval')

    def run(node, env):
        if isinstance(node, ast.Expression):
            return run(node.body, env)
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in env:
                raise NameError(node.id)
            return env[node.id]
        if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub, ast.Not):
            return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](run(node.operand, env))
        if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
            return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](run(node.left, env), run(node.right, env))
        if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
            vals = [run(x, env) for x in node.values]
            return all(vals) if isinstance(node.op, ast.And) else any(vals)
        if isinstance(node, ast.Compare):
            left = run(node.left, env)
            return all(({ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}[type(op)](left, right) for op, right in ((op, run(r, env)) for op, r in zip(node.ops, node.comparators))))
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')):
            return {'min': min, 'max': max, 'round': round}[node.func.id](*[run(a, env) for a in node.args])
        raise ValueError('invalid expression')
    result = []
    for item in options:
        env = {k: item.get(k, 1) for k in ('price', 'capacity', 'distance', 'hours', 'bags')}
        score = run(tree, env)
        if not isinstance(score, (int, float)) or isinstance(score, bool):
            raise ValueError('score')
        if score > 0:
            result.append({'name': item['name'], 'score': score})
    result.sort(key=lambda x: (-x['score'], x['name']))
    return result[:limit]

