import hashlib
import hmac
import json
import os

def create_alarm_code_record(pin: str) -> str:
    if not isinstance(pin, str) or not pin.isdigit() or (not 4 <= len(pin) <= 12):
        raise ValueError('invalid PIN')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return json.dumps({'salt': salt.hex(), 'hash': digest.hex()}, separators=(',', ':'))

def verify_alarm_code(pin: str, record: str) -> bool:
    if not isinstance(pin, str):
        raise ValueError('invalid PIN')
    try:
        value = json.loads(record)
        salt = bytes.fromhex(value['salt'])
        expected = bytes.fromhex(value['hash'])
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (TypeError, ValueError, KeyError, json.JSONDecodeError):
        return False

def summarize_alarms(alarms: list[dict], minimum_severity: int=1, page: int=1, page_size: int=10) -> list[dict]:
    if not isinstance(alarms, list):
        raise ValueError('alarms must be a list')
    if not isinstance(minimum_severity, int) or not 1 <= minimum_severity <= 5:
        raise ValueError('invalid severity')
    if not isinstance(page, int) or page < 1 or (not isinstance(page_size, int)) or (page_size < 1):
        raise ValueError('invalid pagination')
    groups = {}
    for alarm in alarms:
        if not isinstance(alarm, dict) or 'id' not in alarm:
            raise ValueError('invalid alarm')
        floor = alarm.get('floor')
        severity = alarm.get('severity')
        acknowledged = alarm.get('acknowledged')
        if not isinstance(floor, str) or not floor or (not isinstance(severity, int)) or (not 1 <= severity <= 5) or (not isinstance(acknowledged, bool)):
            raise ValueError('invalid alarm')
        if severity < minimum_severity:
            continue
        item = groups.setdefault(floor, {'floor': floor, 'count': 0, 'open_count': 0, 'max_severity': 0})
        item['count'] += 1
        item['open_count'] += not acknowledged
        item['max_severity'] = max(item['max_severity'], severity)
    result = sorted(groups.values(), key=lambda x: (-x['count'], x['floor']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

