_LEVELS = {'LOW': 0, 'MEDIUM': 1, 'HIGH': 2, 'CRITICAL': 3}

def parse_event(line: str) -> dict:
    parts = line.split('|')
    if len(parts) != 4:
        raise ValueError('malformed event')
    try:
        timestamp = datetime.strptime(parts[0].strip(), '%Y-%m-%dT%H:%M')
        volcano = parts[1].strip()
        level = parts[2].strip()
        ash = float(parts[3].strip())
    except (ValueError, TypeError):
        raise ValueError('malformed event')
    if not volcano or level not in _LEVELS or ash < 0:
        raise ValueError('malformed event')
    return {'timestamp': timestamp, 'volcano': volcano, 'level': level, 'ash_tonnes': ash}

def summarize_activity(path: str, pattern: str, window_minutes: int) -> dict:
    if isinstance(window_minutes, bool) or not isinstance(window_minutes, int) or window_minutes <= 0:
        raise ValueError('window_minutes must be positive')
    try:
        with open(path, encoding='utf-8') as handle:
            lines = handle.readlines()
    except (OSError, UnicodeError) as exc:
        raise FileNotFoundError(path) from exc
    count = sum((1 for line in lines if line.strip()))
    matched = sum((1 for line in lines if line.strip() and pattern in line))
    events = [parse_event(line.rstrip('\n')) for line in lines if line.strip()]
    if not events:
        return {'line_count': len(lines), 'matched_count': matched, 'latest': None, 'volcanoes': {}}
    latest = max((event['timestamp'] for event in events))
    cutoff = latest.timestamp() - window_minutes * 60
    selected = [event for event in events if event['timestamp'].timestamp() >= cutoff]
    grouped = {}
    for event in selected:
        item = grouped.setdefault(event['volcano'], {'count': 0, 'ash_tonnes': 0.0, 'highest_level': 'LOW'})
        item['count'] += 1
        item['ash_tonnes'] += event['ash_tonnes']
        if _LEVELS[event['level']] > _LEVELS[item['highest_level']]:
            item['highest_level'] = event['level']
    for item in grouped.values():
        item['ash_tonnes'] = round(item['ash_tonnes'], 2)
    return {'line_count': len(lines), 'matched_count': matched, 'latest': latest, 'volcanoes': dict(sorted(grouped.items()))}

def rank_volcanoes(summary: dict) -> list[dict]:
    result = [{'volcano': name, **data} for name, data in summary['volcanoes'].items()]
    return sorted(result, key=lambda x: (-_LEVELS[x['highest_level']], -x['count'], -x['ash_tonnes'], x['volcano']))

