def export_application_log(records: list[dict[str, object]], destination: str) -> dict[str, object]:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    prepared = []
    total_acres = Decimal('0')
    total_amount = Decimal('0')
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('record must be a dictionary')
        try:
            date = record['date']
            field = record['field']
            product = record['product']
            acres = record['acres']
            rate = record['rate']
        except KeyError as exc:
            raise ValueError('missing field') from exc
        if not isinstance(date, str):
            raise ValueError('invalid date')
        try:
            parsed_date = datetime.date.fromisoformat(date)
        except (ValueError, TypeError):
            raise ValueError('invalid date')
        if parsed_date.isoformat() != date:
            raise ValueError('invalid date')
        if not isinstance(field, str) or not field.strip():
            raise ValueError('invalid field')
        if not isinstance(product, str) or not product.strip():
            raise ValueError('invalid product')
        if isinstance(acres, bool) or isinstance(rate, bool):
            raise ValueError('invalid number')
        try:
            acres_d = Decimal(str(acres))
            rate_d = Decimal(str(rate))
        except (InvalidOperation, ValueError):
            raise ValueError('invalid number')
        if not acres_d.is_finite() or not rate_d.is_finite() or acres_d <= 0 or (rate_d <= 0):
            raise ValueError('invalid number')
        amount = acres_d * rate_d
        prepared.append((date, field.strip(), product.strip(), acres_d, rate_d, amount))
        total_acres += acres_d
        total_amount += amount
    prepared.sort(key=lambda row: (row[0], row[1], row[2]))
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent, prefix='.applications-')
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['date', 'field', 'product', 'acres', 'rate', 'amount'])
            for date, field, product, acres, rate, amount in prepared:
                writer.writerow([date, field, product, format_number(acres), format_number(rate), format(amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP), '.2f')])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return {'rows': len(prepared), 'acres': float(total_acres.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)), 'amount': float(total_amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))}

def format_number(value: Decimal) -> str:
    text = format(value, 'f').rstrip('0').rstrip('.')
    return text if text else '0'

