import hashlib
import hmac
import os
import base64
from numbers import Real

def hash_station_secret(secret: str) -> str:
    if not isinstance(secret, str):
        raise TypeError('secret must be a string')
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
    return base64.b64encode(salt).decode() + '$' + base64.b64encode(value).decode()

def verify_station_secret(secret: str, stored: str) -> bool:
    if not isinstance(secret, str) or not isinstance(stored, str):
        raise TypeError('arguments must be strings')
    try:
        salt_text, value_text = stored.split('$', 1)
        salt = base64.b64decode(salt_text.encode(), validate=True)
        expected = base64.b64decode(value_text.encode(), validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def summarize_readings(readings: list[dict], start: int, end: int, page: int=1, page_size: int=10) -> list[dict]:
    if start > end or page <= 0 or page_size <= 0:
        raise ValueError('invalid range or pagination')
    groups = {}
    for reading in readings:
        try:
            station = reading['station']
            timestamp = reading['timestamp']
            temperature = reading['temperature_c']
            humidity = reading['humidity']
        except (KeyError, TypeError):
            raise ValueError('invalid reading')
        if not isinstance(station, str) or not isinstance(timestamp, int) or isinstance(timestamp, bool) or (not isinstance(temperature, Real)) or isinstance(temperature, bool) or (not isinstance(humidity, Real)) or isinstance(humidity, bool):
            raise ValueError('invalid reading')
        if start <= timestamp <= end:
            groups.setdefault(station, []).append((temperature, humidity))
    result = []
    for station, values in groups.items():
        temperatures = [x[0] for x in values]
        humidities = [x[1] for x in values]
        result.append({'station': station, 'count': len(values), 'average_temperature_c': round(sum(temperatures) / len(values), 2), 'minimum_temperature_c': min(temperatures), 'maximum_temperature_c': max(temperatures), 'average_humidity': round(sum(humidities) / len(values), 2)})
    result.sort(key=lambda x: (-x['average_temperature_c'], x['station']))
    offset = (page - 1) * page_size
    return result[offset:offset + page_size]

