                counts[post['platform']] = counts.get(post['platform'], 0) + 1
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return {'count': len(rows), 'by_platform': {key: counts[key] for key in sorted(counts)}}

