from datetime import datetime, timezone
import hashlib
import json

def parse_timestamp(value: str) -> datetime:
    if not isinstance(value, str) or len(value) != 20 or value[-1] != 'Z':
        raise ValueError('invalid timestamp')
    try:
        result = datetime.strptime(value, '%Y-%m-%dT%H:%M:%SZ')
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid timestamp') from exc
    return result.replace(tzinfo=timezone.utc)

def canonical_digest(record: dict) -> str:
    data = json.dumps(record, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode('utf-8')
    return hashlib.sha256(data).hexdigest()

class EvidenceRegistry:

    def __init__(self, cases: dict):
        self.cases = {key: dict(value) for key, value in cases.items()}
        self.transfers = {key: [] for key in cases}

    def add_transfer(self, requester: dict, case_id: str, transfer: dict) -> dict:
        if case_id not in self.cases:
            raise KeyError(case_id)
        case = self.cases[case_id]
        if case.get('status') != 'open':
            raise ValueError('case is not open')
        if requester.get('tenant') != case.get('tenant') or (requester.get('id') != case.get('owner') and 'evidence_admin' not in requester.get('roles', [])):
            raise PermissionError('not permitted')
        required = {'item_id', 'from_person', 'to_person', 'timestamp', 'location'}
        if set(transfer) != required or any((not isinstance(transfer[k], str) or not transfer[k] for k in required - {'timestamp'})):
            raise ValueError('invalid transfer')
        stamp = parse_timestamp(transfer['timestamp'])
        previous = [x for x in self.transfers[case_id] if x['item_id'] == transfer['item_id']]
        if previous and stamp <= parse_timestamp(previous[-1]['timestamp']):
            raise ValueError('timestamps must increase')
        stored = dict(transfer, sequence=len(self.transfers[case_id]) + 1)
        stored['digest'] = canonical_digest(stored)
        self.transfers[case_id].append(stored)
        return dict(stored)

    def case_report(self, case_id: str) -> dict:
        if case_id not in self.cases:
            raise KeyError(case_id)
        records = sorted(self.transfers[case_id], key=lambda x: (parse_timestamp(x['timestamp']), x['item_id'], x['sequence']))
        items = {}
        for record in records:
            items[record['item_id']] = items.get(record['item_id'], 0) + 1
        return {'case_id': case_id, 'transfer_count': len(records), 'items': items, 'transfers': [dict(x) for x in records]}

