import hashlib
import hmac
import os
import math

def create_operator(name: str, pin: str) -> dict:
    if not isinstance(name, str) or not isinstance(pin, str):
        raise TypeError()
    name = name.strip()
    if not name or not pin:
        raise ValueError()
    salt = os.urandom(16)
    credential = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000).hex()
    return {'name': name, 'credential': credential, 'salt': salt.hex()}

def verify_operator(operator: dict, pin: str) -> bool:
    if not isinstance(pin, str):
        raise TypeError()
    try:
        salt = bytes.fromhex(operator['salt'])
        expected = operator['credential']
    except (KeyError, TypeError, ValueError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000).hex()
    return hmac.compare_digest(actual, expected)

def rental_report(rentals: list[dict], status: str='all', page: int=1, page_size: int=10) -> dict:
    statuses = {'reserved', 'active', 'completed', 'cancelled'}
    if status != 'all' and status not in statuses:
        raise ValueError()
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError()
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError()
    groups = {}
    total_hours = 0
    total_revenue = 0
    for item in rentals:
        if not isinstance(item, dict) or not isinstance(item.get('equipment'), str) or (not item.get('equipment')) or (item.get('status') not in statuses):
            raise ValueError()
        hours, rate = (item.get('hours'), item.get('rate'))
        if isinstance(hours, bool) or isinstance(rate, bool) or (not isinstance(hours, (int, float))) or (not isinstance(rate, (int, float))) or (hours < 0) or (rate < 0):
            raise ValueError()
        if status != 'all' and item['status'] != status:
            continue
        equipment = item['equipment']
        if equipment not in groups:
            groups[equipment] = [0, 0, 0]
        groups[equipment][0] += 1
        groups[equipment][1] += hours
        groups[equipment][2] += hours * rate
        total_hours += hours
        total_revenue += hours * rate
    items = [{'equipment': k, 'rentals': v[0], 'hours': v[1], 'revenue': round(v[2], 2)} for k, v in groups.items()]
    items.sort(key=lambda x: (-x['revenue'], x['equipment']))
    pages = math.ceil(len(items) / page_size) if items else 0
    start = (page - 1) * page_size
    return {'items': items[start:start + page_size], 'total_items': len(items), 'total_hours': total_hours, 'total_revenue': round(total_revenue, 2), 'pages': pages}

