def optimize_schedule(prices: list[float], capacity: int, initial: int, max_rate: int, target: int=0) -> list[int]:
    if not prices or capacity <= 0 or max_rate <= 0:
        raise ValueError('invalid battery parameters')
    if not 0 <= initial <= capacity or not 0 <= target <= capacity:
        raise ValueError('invalid state')
    if any((not math.isfinite(float(p)) for p in prices)):
        raise ValueError('invalid price')
    states = {initial: (0.0, ())}
    for price in prices:
        next_states = {}
        for state, (cost, actions) in states.items():
            for action in range(-max_rate, max_rate + 1):
                new_state = state + action
                if not 0 <= new_state <= capacity:
                    continue
                candidate = (cost + float(price) * action, actions + (action,))
                old = next_states.get(new_state)
                if old is None or candidate[0] < old[0] or (candidate[0] == old[0] and candidate[1] < old[1]):
                    next_states[new_state] = candidate
        states = next_states
    if target not in states:
        raise ValueError('target is unreachable')
    return list(states[target][1])

