def test_groups_filters_and_sorts_results():
    path = make_log("2024-01-01T10:00,c2,AA1,71\n2024-01-01T10:01,c1,BB2,80\n2024-01-01T10:02,c2,CC3,75\n2024-01-01T10:03,c1,DD4,90\n2024-01-01T10:04,c3,EE5,70\n")
    try:
        assert camera_violation_report(path, 75) == [
            {"camera": "c1", "count": 2, "max_speed": 90, "average_speed": 85.0},
            {"camera": "c2", "count": 1, "max_speed": 75, "average_speed": 75.0},
        ]
    finally:
        os.unlink(path)


def test_ties_are_sorted_by_camera_name():
    path = make_log("t,c3,p,50\nt,c1,p,60\nt,c2,p,55\n")
    try:
        result = camera_violation_report(path, 0)
        assert [item["camera"] for item in result] == ["c1", "c2", "c3"]
    finally:
        os.unlink(path)


def test_average_is_rounded_and_blank_lines_are_ignored():
    path = make_log("t,c1,p1,1\n\nt,c1,p2,2\nt,c1,p3,2\n")
