import subprocess

def camera_violation_report(path: str, min_speed: int, offset: int=0, limit: int=10) -> list[dict]:
    if min_speed < 0 or offset < 0 or limit <= 0:
        raise ValueError('invalid numeric argument')
    result = subprocess.run(['cat', path], capture_output=True, text=True, check=True)
    groups = {}
    for raw in result.stdout.splitlines():
        if not raw.strip():
            continue
        fields = raw.split(',')
        if len(fields) != 4:
            raise ValueError('malformed row')
        timestamp, camera, plate, speed_text = fields
        if not timestamp or not camera or (not plate):
            raise ValueError('malformed row')
        try:
            speed = int(speed_text)
        except ValueError as exc:
            raise ValueError('malformed row') from exc
        if speed < min_speed:
            continue
        item = groups.setdefault(camera, {'count': 0, 'total': 0, 'max_speed': speed})
        item['count'] += 1
        item['total'] += speed
        item['max_speed'] = max(item['max_speed'], speed)
    output = []
    for camera, item in groups.items():
        output.append({'camera': camera, 'count': item['count'], 'max_speed': item['max_speed'], 'average_speed': round(item['total'] / item['count'], 2)})
    output.sort(key=lambda item: (-item['count'], item['camera']))
    return output[offset:offset + limit]

