        raise ValueError('invalid timestamp')
    if not isinstance(rx_kbps, (int, float)) or not math.isfinite(rx_kbps) or rx_kbps < 0:
        raise ValueError('invalid rx')
    if not isinstance(tx_kbps, (int, float)) or not math.isfinite(tx_kbps) or tx_kbps < 0:
        raise ValueError('invalid tx')
    conn.execute('insert into samples (device_id, timestamp, rx_kbps, tx_kbps) values (?, ?, ?, ?)', (device_id, timestamp, rx_kbps, tx_kbps))
    conn.commit()

def summarize_bandwidth(conn: sqlite3.Connection, device_id: str, start: int, end: int, bucket_seconds: int) -> list[dict[str, object]]:
    if start >= end or bucket_seconds <= 0:
        raise ValueError('invalid interval')
    rows = conn.execute('select timestamp, rx_kbps, tx_kbps from samples where device_id = ? and timestamp >= ? and timestamp < ? order by timestamp', (device_id, start, end)).fetchall()
    groups = {}
    for timestamp, rx, tx in rows:
        bucket = start + (timestamp - start) // bucket_seconds * bucket_seconds
        groups.setdefault(bucket, []).append((rx, tx))
    result = []
    for bucket in sorted(groups):
        values = groups[bucket]
        result.append({'start': bucket, 'end': bucket + bucket_seconds, 'samples': len(values), 'avg_rx_kbps': round(sum((x[0] for x in values)) / len(values), 2), 'avg_tx_kbps': round(sum((x[1] for x in values)) / len(values), 2), 'peak_total_kbps': round(max((x[0] + x[1] for x in values)), 2)})
    return result

