    columns = {'device': 'device_id', 'avg_total': 'avg_total_kbps', 'samples': 'samples', 'last_seen': 'last_seen'}
    if sort_by not in columns:
        raise ValueError('invalid sort')
    rows = conn.execute('select device_id, count(*), avg(rx_kbps + tx_kbps), max(timestamp) from samples where device_id like ? group by device_id', ('%' + search + '%',)).fetchall()
