from lxml import etree
import re
_DAYS = {'mon': 0, 'tue': 1, 'wed': 2, 'thu': 3, 'fri': 4, 'sat': 5, 'sun': 6}
_TIME = re.compile('^(?:[01]\\d|2[0-3]):[0-5]\\d$')

def _minutes(value):
    if not isinstance(value, str) or not _TIME.fullmatch(value):
        raise ValueError('invalid time')
    return int(value[:2]) * 60 + int(value[3:])

def _day(value):
    if not isinstance(value, str) or value.casefold() not in _DAYS:
        raise ValueError('invalid day')
    return value.casefold()

def parse_roster(xml_text: str) -> list[dict]:
    try:
        root = etree.fromstring(xml_text.encode(), etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False))
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'roster':
        raise ValueError('invalid root')
    result, ids = ([], set())
    for node in root:
        if node.tag != 'volunteer' or not node.get('id') or (not node.get('name')) or (node.get('id') in ids):
            raise ValueError('invalid volunteer')
        ids.add(node.get('id'))
        skills = set()
        availability = []
        for child in node:
            if child.tag == 'skill':
                text = (child.text or '').strip().casefold()
                if not text:
                    raise ValueError('invalid skill')
                skills.add(text)
            elif child.tag == 'availability':
                day, start, end = (_day(child.get('day')), child.get('start'), child.get('end'))
                if _minutes(end) <= _minutes(start):
                    raise ValueError('invalid interval')
                availability.append((day, start, end))
            else:
                raise ValueError('invalid volunteer child')
        if not skills:
            raise ValueError('missing skill')
        result.append({'id': node.get('id'), 'name': node.get('name'), 'skills': sorted(skills), 'availability': availability})
    return result

def assign_volunteers(xml_text: str, shifts: list[dict]) -> dict[str, list[str]]:
    volunteers = parse_roster(xml_text)
    seen = set()
    checked = []
    required = {'id', 'day', 'start', 'end', 'skill', 'capacity'}
    for shift in shifts:
        if set(shift) != required or not isinstance(shift['id'], str) or (not shift['id']) or (shift['id'] in seen) or (not isinstance(shift['skill'], str)) or (not shift['skill']) or (not isinstance(shift['capacity'], int)) or isinstance(shift['capacity'], bool) or (shift['capacity'] < 0):
            raise ValueError('invalid shift')
        day = _day(shift['day'])
        start, end = (shift['start'], shift['end'])
        if _minutes(end) <= _minutes(start):
            raise ValueError('invalid interval')
        seen.add(shift['id'])
        checked.append((shift, day))
    counts = {v['id']: 0 for v in volunteers}
    answer = {s['id']: [] for s, _ in checked}
    for shift, day in sorted(checked, key=lambda x: (_DAYS[x[1]], _minutes(x[0]['start']), _minutes(x[0]['end']), x[0]['id'])):
        eligible = []
        for v in volunteers:
            if shift['skill'].casefold() not in v['skills']:
                continue
            if any((d == day and a <= shift['start'] and (e >= shift['end']) for d, a, e in v['availability'])):
                eligible.append(v)
        eligible.sort(key=lambda v: (counts[v['id']], v['id']))
        chosen = eligible[:shift['capacity']]
        answer[shift['id']] = [v['id'] for v in chosen]
        for v in chosen:
            counts[v['id']] += 1
    return answer

