            raise ValueError('invalid bill structure')
        account = bill.get('account')
        due = bill.get('due')
        currency = bill.get('currency')
        if not account or not due or (not currency) or (account in seen):
            raise ValueError('invalid bill attributes')
        try:
            date.fromisoformat(due)
        except ValueError:
            raise ValueError('invalid date')
        seen.add(account)
        customer = None
        charges = []
        for child in bill:
            if child.tail and child.tail.strip():
                raise ValueError('invalid bill structure')
            if child.tag == 'customer' and customer is None:
                customer = (child.text or '').strip()
                if not customer:
                    raise ValueError('invalid customer')
            elif child.tag == 'charge':
                category = child.get('category')
                if not category or len(child):
