import re
import secrets

def parse_observation_plan(text: str) -> list[dict]:
    result = []
    for number, raw in enumerate(text.splitlines(), 1):
        line = raw.strip()
        if not line or line.startswith('#'):
            continue
        fields, current, escaped = ([], [], False)
        for char in line:
            if escaped:
                current.append(char)
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == '|':
                fields.append(''.join(current).strip())
                current = []
            else:
                current.append(char)
        if escaped:
            raise ValueError(f'invalid line {number}')
        fields.append(''.join(current).strip())
        if len(fields) != 4 or not fields[0] or (not fields[3]):
            raise ValueError(f'invalid line {number}')
        try:
            priority, duration = (int(fields[1]), int(fields[2]))
        except ValueError:
            raise ValueError(f'invalid line {number}')
        if not 0 <= priority <= 9 or not 1 <= duration <= 1440:
            raise ValueError(f'invalid line {number}')
        result.append({'target': fields[0], 'priority': priority, 'duration': duration, 'filter': fields[3]})
    return result

def _minutes(value):
    if not isinstance(value, str) or not re.fullmatch('(?:[01]\\d|2[0-3]):[0-5]\\d', value):
        raise ValueError('invalid time')
    hour, minute = value.split(':')
    return int(hour) * 60 + int(minute)

def schedule_observations(observations: list[dict], start: str, end: str) -> list[dict]:
    begin, finish = (_minutes(start), _minutes(end))
    if finish <= begin:
        raise ValueError('invalid window')
    prepared = []
    for index, item in enumerate(observations):
        try:
            target, priority, duration, filt = (item['target'], item['priority'], item['duration'], item['filter'])
        except (KeyError, TypeError):
