        if item['status'] != 'withdrawn' and item['annual_income'] <= limit:
            eligible.append(item)
    eligible.sort(key=lambda x: (x['submitted_on'], x['application_id']))
    return {'eligible_count': len(eligible), 'ineligible_count': len(applications) - len(eligible), 'eligible_income_total': sum((x['annual_income'] for x in eligible)), 'eligible_application_ids': [x['application_id'] for x in eligible], 'by_status': dict(sorted(statuses.items()))}

