import hashlib
import hmac
import os

def hash_password(password: str) -> str:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    if password == '':
        raise ValueError('password cannot be empty')
    salt = os.urandom(16)
    rounds = 100000
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, rounds)
    return 'pbkdf2$%d$%s$%s' % (rounds, salt.hex(), digest.hex())

def verify_password(password: str, stored: str) -> bool:
    if not isinstance(password, str) or not isinstance(stored, str):
        return False
    try:
        kind, rounds_text, salt_text, digest_text = stored.split('$')
        if kind != 'pbkdf2':
            return False
        rounds = int(rounds_text)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, rounds)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def plan_production(jobs: list[dict], machine_capacity: dict[str, int], operators: dict[str, str], username: str, password: str) -> list[dict]:
    if username not in operators or not verify_password(password, operators[username]):
        raise PermissionError('invalid operator credentials')
    for machine, capacity in machine_capacity.items():
        if not isinstance(machine, str) or isinstance(capacity, bool) or (not isinstance(capacity, int)) or (capacity <= 0):
            raise ValueError('invalid machine capacity')
    seen = set()
    grouped = {machine: [] for machine in machine_capacity}
    for job in jobs:
        if not isinstance(job, dict) or set(job) != {'id', 'machine', 'duration', 'priority', 'due'}:
            raise ValueError('invalid job')
        ident, machine = (job['id'], job['machine'])
        if not isinstance(ident, str) or not isinstance(machine, str) or ident in seen:
            raise ValueError('invalid or duplicate job id')
        if isinstance(job['duration'], bool) or not isinstance(job['duration'], int) or job['duration'] <= 0:
            raise ValueError('invalid duration')
        if isinstance(job['priority'], bool) or not isinstance(job['priority'], int) or isinstance(job['due'], bool) or (not isinstance(job['due'], int)):
            raise ValueError('invalid job numbers')
        if machine not in grouped:
            raise ValueError('unknown machine')
        seen.add(ident)
        grouped[machine].append(job)
    result = []
    for machine in sorted(grouped):
        lanes = [0] * machine_capacity[machine]
        ordered = sorted(grouped[machine], key=lambda j: (-j['priority'], j['due'], j['id']))
        for job in ordered:
            lane = min(range(len(lanes)), key=lambda n: (lanes[n], n))
            start = lanes[lane]
            end = start + job['duration']
            lanes[lane] = end
            result.append({'id': job['id'], 'machine': machine, 'lane': lane, 'start': start, 'end': end})
    return sorted(result, key=lambda x: (x['machine'], x['start'], x['lane'], x['id']))

