import ast
import operator

def _evaluate(expression, values):
    tree = ast.parse(expression, mode='eval').body
    binary = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
    compare = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}

    def visit(node):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in values:
                raise NameError(node.id)
            return values[node.id]
        if isinstance(node, ast.BinOp) and type(node.op) in binary:
            return binary[type(node.op)](visit(node.left), visit(node.right))
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
            value = visit(node.operand)
            return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
        if isinstance(node, ast.BoolOp):
            if isinstance(node.op, ast.And):
                value = visit(node.values[0])
                for part in node.values[1:]:
                    if not value:
                        return value
                    value = visit(part)
                return value
            value = visit(node.values[0])
            for part in node.values[1:]:
                if value:
                    return value
                value = visit(part)
            return value
        if isinstance(node, ast.Compare):
            left = visit(node.left)
            for op, right_node in zip(node.ops, node.comparators):
                if type(op) not in compare:
                    raise ValueError('unsupported expression')
                right = visit(right_node)
                if not compare[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max', 'round'}) and (not node.keywords):
            return {'min': min, 'max': max, 'round': round}[node.func.id](*(visit(arg) for arg in node.args))
        raise ValueError('unsupported expression')
    return visit(tree)

def rank_seafarers(records: list[dict[str, object]], expression: str, page: int, page_size: int) -> list[dict[str, object]]:
    if page < 1 or page_size < 1:
        raise ValueError('invalid pagination')
    selected = []
    for record in records:
        values = {key: record[key] for key in ('sea_days', 'score', 'training_hours', 'medical_valid')}
        value = _evaluate(expression, values)
        if value > 0:
            selected.append((record['name'], value))
    selected.sort(key=lambda item: (-item[1], item[0]))
    start = (page - 1) * page_size
    return [{'name': name, 'value': value} for name, value in selected[start:start + page_size]]

