import hashlib
import hmac
import os

def hash_secret(secret: str) -> str:
    if not isinstance(secret, str) or not secret.strip():
        raise ValueError('secret must not be empty')
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
    return 'pbkdf2$' + salt.hex() + '$' + value.hex()

def verify_secret(stored: str, candidate: str) -> bool:
    if not isinstance(stored, str) or not isinstance(candidate, str) or (not candidate):
        return False
    parts = stored.split('$')
    if len(parts) != 3 or parts[0] != 'pbkdf2':
        return False
    try:
        salt = bytes.fromhex(parts[1])
        expected = bytes.fromhex(parts[2])
    except ValueError:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', candidate.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def parse_fastq(text: str) -> list[dict]:
    if not isinstance(text, str):
        raise ValueError('text must be a string')
    lines = text.splitlines()
    if not any((line.strip() for line in lines)):
        return []
    if len(lines) % 4:
        raise ValueError('incomplete record')
    result = []
    seen = set()
    for i in range(0, len(lines), 4):
        header, sequence, plus, quality = lines[i:i + 4]
        if not header.startswith('@') or not header[1:].strip() or plus != '+':
            raise ValueError('invalid record')
        ident = header[1:].split()[0]
        if ident in seen:
            raise ValueError('duplicate id')
        seen.add(ident)
        if len(sequence) != len(quality) or any((c.upper() not in 'ACGTN' for c in sequence)):
            raise ValueError('invalid sequence')
        if any((not 0 <= ord(c) - 33 <= 93 for c in quality)):
            raise ValueError('invalid quality')
        fields = header[1:].split()
        sample = next((x[7:] for x in fields if x.startswith('sample=')), 'unknown')
        result.append({'id': ident, 'sample': sample, 'sequence': sequence, 'length': len(sequence), 'mean_quality': round(sum((ord(c) - 33 for c in quality)) / len(quality), 3) if quality else 0.0})
    return result

def summarize_reads(records: list[dict]) -> dict:
    total = gc = quality = 0
    samples = {}
    for record in records:
        if not all((k in record for k in ('id', 'sample', 'sequence', 'length', 'mean_quality'))):
            raise ValueError('missing field')
        sequence = record['sequence']
        if not isinstance(record['length'], int) or record['length'] < 0 or record['length'] != len(sequence):
            raise ValueError('invalid length')
        total += record['length']
        gc += sum((c.upper() in 'GC' for c in sequence))
        quality += record['length'] * record['mean_quality']
        samples[record['sample']] = samples.get(record['sample'], 0) + 1
    return {'read_count': len(records), 'base_count': total, 'gc_count': gc, 'gc_percent': round(gc * 100 / total, 2) if total else 0.0, 'mean_quality': round(quality / total, 3) if total else 0.0, 'samples': dict(sorted(samples.items()))}

