import copy
import hashlib
import hmac
import os
from datetime import date

def _parse_date(value):
    if not isinstance(value, str):
        raise ValueError('invalid date')
    try:
        return date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid date')

def _check_inspection(item):
    if not isinstance(item, dict) or set(item) != {'date', 'station', 'severity', 'violations'}:
        raise ValueError('invalid inspection')
    _parse_date(item['date'])
    if not isinstance(item['station'], str) or not item['station']:
        raise ValueError('invalid inspection')
    if isinstance(item['severity'], bool) or not isinstance(item['severity'], int) or (not 1 <= item['severity'] <= 5):
        raise ValueError('invalid inspection')
    if not isinstance(item['violations'], list) or any((not isinstance(x, str) for x in item['violations'])):
        raise ValueError('invalid inspection')

def create_inspector_record(inspector_id: str, password: str, inspections: list[dict]) -> dict:
    if not isinstance(inspector_id, str) or not inspector_id or (not isinstance(password, str)) or (not password):
        raise ValueError('invalid credentials')
    if not isinstance(inspections, list):
        raise ValueError('invalid inspections')
    for item in inspections:
        _check_inspection(item)
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return {'inspector_id': inspector_id, 'salt': salt.hex(), 'password_hash': digest.hex(), 'inspections': copy.deepcopy(inspections)}

def verify_inspector(record: dict, password: str) -> bool:
    if not isinstance(password, str) or not isinstance(record, dict):
        return False
    try:
        salt = bytes.fromhex(record['salt'])
        expected = bytes.fromhex(record['password_hash'])
    except (KeyError, ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def inspection_report(records: list[dict], start_date: str, end_date: str) -> list[dict]:
    start, end = (_parse_date(start_date), _parse_date(end_date))
    if start > end:
        raise ValueError('invalid range')
    groups = {}
    for record in records:
        if not isinstance(record, dict) or not isinstance(record.get('inspections'), list):
            raise ValueError('invalid record')
        for item in record['inspections']:
            _check_inspection(item)
            current = _parse_date(item['date'])
            if start <= current <= end:
                group = groups.setdefault(item['station'], [0, 0, {}])
                group[0] += 1
                group[1] += item['severity']
                for name in item['violations']:
                    group[2][name] = group[2].get(name, 0) + 1
    result = []
    for station, (count, total, violations) in groups.items():
        result.append({'station': station, 'inspections': count, 'average_severity': round(total / count, 2), 'violations': [{'name': n, 'count': c} for n, c in sorted(violations.items(), key=lambda x: (-x[1], x[0]))]})
    return sorted(result, key=lambda x: (-x['inspections'], -x['average_severity'], x['station']))

