import xml.etree.ElementTree as ET

def summarize_vaccination_report(xml_text: str, min_doses: int=0, page: int=1, page_size: int=10) -> dict:
    if min_doses < 0 or page < 1 or page_size < 1 or (page_size > 100):
        raise ValueError('invalid pagination or filter')
    try:
        root = ET.fromstring(xml_text)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'vaccination_campaign':
        raise ValueError('invalid root')
    groups = {}
    total_records = 0
    total_doses = 0
    try:
        for clinic in root.findall('clinic'):
            clinic_name = clinic.attrib['name']
            if not clinic_name:
                raise ValueError('empty clinic')
            for item in clinic.findall('vaccination'):
                vaccine = item.attrib['vaccine']
                date.fromisoformat(item.attrib['date'])
                doses = int(item.attrib['doses'])
                if not vaccine or doses < 0:
                    raise ValueError('invalid record')
                if doses < min_doses:
                    continue
                total_records += 1
                total_doses += doses
                group = groups.setdefault(vaccine, {'doses': 0, 'records': 0, 'clinics': set()})
                group['doses'] += doses
                group['records'] += 1
                group['clinics'].add(clinic_name)
    except (KeyError, TypeError, ValueError) as exc:
        raise ValueError('invalid record') from exc
    entries = []
    for vaccine, group in groups.items():
        entries.append({'vaccine': vaccine, 'doses': group['doses'], 'records': group['records'], 'clinics': sorted(group['clinics'])})
    entries.sort(key=lambda item: (-item['doses'], item['vaccine']))
    start = (page - 1) * page_size
    return {'total_records': total_records, 'total_doses': total_doses, 'items': entries[start:start + page_size]}

