import csv
import math
import os
import tempfile

def export_fuel_report(records: list[dict], output_path: str, min_distance: float=0, page: int=1, page_size: int=50) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('invalid page_size')
    if isinstance(min_distance, bool) or not isinstance(min_distance, (int, float)) or (not math.isfinite(min_distance)) or (min_distance < 0):
        raise ValueError('invalid min_distance')
    totals = {}
    for record in records:
        if not isinstance(record, dict) or not isinstance(record.get('vessel'), str) or (not record['vessel']):
            raise ValueError('invalid record')
        fuel = record.get('fuel_tons')
        distance = record.get('distance_nm')
        if isinstance(fuel, bool) or not isinstance(fuel, (int, float)) or (not math.isfinite(fuel)) or (fuel < 0):
            raise ValueError('invalid fuel')
        if isinstance(distance, bool) or not isinstance(distance, (int, float)) or (not math.isfinite(distance)) or (distance <= 0):
            raise ValueError('invalid distance')
        if distance >= min_distance:
            item = totals.setdefault(record['vessel'], [0.0, 0.0])
