    current = []
    escaped = False
    for char in text:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape')
    fields.append(''.join(current))
    return fields

def parse_job(text: str) -> dict:
    fields = _split_fields(text)
    if len(fields) != 5 or not fields[0]:
        raise ValueError('invalid job')
    material = fields[1].strip().upper()
    if material not in {'PLA', 'ABS', 'PETG'}:
        raise ValueError('invalid material')
    try:
        grams = int(fields[2].strip())
        priority = int(fields[3].strip())
        duration = int(fields[4].strip())
    except ValueError as exc:
        raise ValueError('invalid number') from exc
    if grams <= 0 or not 0 <= priority <= 9 or duration <= 0:
        raise ValueError('invalid range')
    return {'name': fields[0], 'material': material, 'grams': grams, 'priority': priority, 'duration': duration}

class PrinterQueue:

    def __init__(self):
        self._jobs = {}
        self._next = 1
        self._sequence = 0

    def enqueue(self, user: dict, description: str) -> str:
        parsed = parse_job(description)
        jid = 'job-' + str(self._next)
        self._next += 1
        self._sequence += 1
        self._jobs[jid] = {**parsed, 'id': jid, 'status': 'queued', 'owner_id': user['id'], 'tenant': user['tenant'], 'sequence': self._sequence}
        return jid

    def _allowed(self, user, job):
        return job['tenant'] == user['tenant'] and (job['owner_id'] == user['id'] or 'operator' in user.get('roles', []))

    def cancel(self, user: dict, job_id: str) -> bool:
        job = self._jobs[job_id]
        if not self._allowed(user, job):
            raise PermissionError('not permitted')
        if job['status'] != 'queued':
            return False
        job['status'] = 'cancelled'
        return True

    def _ordered(self):
        queued = [j for j in self._jobs.values() if j['status'] == 'queued']
        completed = [j for j in self._jobs.values() if j['status'] == 'completed']
        queued.sort(key=lambda j: (-j['priority'], j['duration'], j['sequence']))
        completed.sort(key=lambda j: j['sequence'])
        return queued + completed

    def snapshot(self, user: dict) -> list[dict]:
        result = []
        for job in self._ordered():
            if job['tenant'] != user['tenant']:
