            result.append({k: job[k] for k in ('id', 'name', 'material', 'grams', 'priority', 'duration', 'status', 'owner_id', 'tenant')})
        return result

    def complete_next(self) -> str | None:
        ordered = self._ordered()
        for job in ordered:
            if job['status'] == 'queued':
                job['status'] = 'completed'
                return job['id']
        return None

