import os

def create_operator_pin(pin: str) -> str:
    if not isinstance(pin, str) or not pin.isdigit() or (not 4 <= len(pin) <= 12):
        raise ValueError('invalid PIN')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return salt.hex() + ':' + digest.hex()

def verify_operator_pin(pin: str, stored: str) -> bool:
    if not isinstance(pin, str) or not pin.isdigit() or (not 4 <= len(pin) <= 12):
        return False
    try:
        salt_text, digest_text = stored.split(':', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (AttributeError, ValueError):
        return False

def summarize_traceability(records: list[dict], status: str | None=None, page: int=1, page_size: int=10) -> list[dict]:
    statuses = ('harvested', 'in_transit', 'delivered', 'recalled')
    if status is not None and status not in statuses:
        raise ValueError('invalid status')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    groups = {}
    for record in records:
        if status is not None and record['status'] != status:
            continue
        quantity = record['quantity_kg']
        if quantity < 0:
            raise ValueError('negative quantity')
        key = (record['farm'], record['product'])
        if key not in groups:
            groups[key] = {name: 0 for name in statuses}
            groups[key]['quantity'] = 0
            groups[key]['count'] = 0
        groups[key]['quantity'] += quantity
        groups[key]['count'] += 1
        groups[key][record['status']] += 1
    result = []
