import csv
import datetime
import math
import os
import tempfile
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from io import StringIO
_FIELDS = ['species', 'cultivar', 'quantity', 'unit_price', 'greenhouse', 'received']

def parse_inventory(text: str) -> list[dict]:
    try:
        reader = csv.reader(StringIO(text, newline=''))
        header = next(reader)
    except (StopIteration, csv.Error) as exc:
        raise ValueError('invalid CSV') from exc
    if header != _FIELDS:
        raise ValueError('invalid header')
    result = []
    try:
        for row in reader:
            if len(row) != len(_FIELDS) or any((x == '' for x in row)):
                raise ValueError('invalid row')
            try:
                quantity = int(row[2])
                price = float(row[3])
                datetime.date.fromisoformat(row[5])
            except (ValueError, OverflowError):
                raise ValueError('invalid value')
            if quantity < 0 or price < 0 or (not math.isfinite(price)):
                raise ValueError('invalid value')
            result.append(dict(zip(_FIELDS, [row[0], row[1], quantity, price, row[4], row[5]])))
    except csv.Error as exc:
        raise ValueError('invalid CSV') from exc
    return result

def aggregate_inventory(records: list[dict]) -> list[dict]:
    groups = {}
    for r in records:
        try:
            species, cultivar = (r['species'], r['cultivar'])
            quantity = r['quantity']
            price = r['unit_price']
            received = r['received']
            if not isinstance(species, str) or not isinstance(cultivar, str) or (not isinstance(quantity, int)) or isinstance(quantity, bool) or (quantity < 0) or (not isinstance(price, (int, float))) or isinstance(price, bool) or (not math.isfinite(price)) or (price < 0):
                raise ValueError
            datetime.date.fromisoformat(received)
            value = Decimal(str(price)) * quantity
        except (KeyError, TypeError, ValueError, InvalidOperation):
            raise ValueError('invalid record')
        key = (species, cultivar)
        if key not in groups:
            groups[key] = [0, Decimal('0'), received]
        groups[key][0] += quantity
        groups[key][1] += value
        groups[key][2] = min(groups[key][2], received)
    result = []
    for (species, cultivar), (quantity, value, first) in groups.items():
        result.append({'species': species, 'cultivar': cultivar, 'quantity': quantity, 'total_value': str(value.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)), 'first_received': first})
    return sorted(result, key=lambda x: (-x['quantity'], x['species'], x['cultivar']))

def export_inventory(records: list[dict], destination: str) -> list[dict]:
    aggregated = aggregate_inventory(records)
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(prefix='.nursery-', dir=directory, text=True)
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as f:
            writer = csv.DictWriter(f, fieldnames=['species', 'cultivar', 'quantity', 'total_value', 'first_received'])
            writer.writeheader()
            writer.writerows(aggregated)
            f.flush()
            os.fsync(f.fileno())
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return aggregated

