from lxml import etree
from datetime import datetime

def build_retention_report(xml_text: str, page: int=1, page_size: int=20) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('page must be positive')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('page_size must be positive')
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml_text.encode('utf-8'), parser)
        if root.tag != 'recordings':
            raise ValueError('invalid root')
        grouped = {}
        for node in root.findall('call'):
            for name in ('id', 'agent', 'status', 'duration_seconds', 'started'):
                if name not in node.attrib:
                    raise ValueError('missing attribute')
            duration = int(node.attrib['duration_seconds'])
            if duration < 0:
                raise ValueError('invalid duration')
            datetime.fromisoformat(node.attrib['started'].replace('Z', '+00:00'))
            if node.attrib['status'] == 'completed' and duration >= 30:
                agent = node.attrib['agent']
                item = grouped.setdefault(agent, [0, 0])
                item[0] += 1
                item[1] += duration
    except ValueError:
        raise
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    ordered = sorted(grouped.items(), key=lambda pair: (-pair[1][1], pair[0]))
    total_calls = sum((value[0] for value in grouped.values()))
    total_seconds = sum((value[1] for value in grouped.values()))
    total_pages = (len(ordered) + page_size - 1) // page_size if ordered else 0
    start = (page - 1) * page_size
    agents = []
    for agent, (calls, seconds) in ordered[start:start + page_size]:
        agents.append({'agent': agent, 'calls': calls, 'seconds': seconds, 'average_seconds': round(seconds / calls, 2)})
    return {'total_calls': total_calls, 'total_seconds': total_seconds, 'total_pages': total_pages, 'page': page, 'page_size': page_size, 'agents': agents}

