from solution import parse_telemetry_packet, summarize_telemetry
import json
import pytest


def packet(spacecraft_id, timestamp, readings, **extra):
    value = {"spacecraft_id": spacecraft_id, "timestamp": timestamp, "readings": readings}
    value.update(extra)
    return json.dumps(value)


def test_parse_packet_keeps_only_supported_fields():
    result = parse_telemetry_packet(packet("ORION-1", "2030-01-01T00:00:01Z", {"temp": 12.5}, sequence=9))
    assert result == {
        "spacecraft_id": "ORION-1",
        "timestamp": "2030-01-01T00:00:01Z",
        "readings": {"temp": 12.5},
    }


def test_parse_packet_accepts_fractional_timestamp_and_multiple_numbers():
    result = parse_telemetry_packet(packet("O", "2030-01-01T00:00:00.125Z", {"x": -2, "y": 4.0}))
    assert result["timestamp"] == "2030-01-01T00:00:00.125Z"
    assert result["readings"] == {"x": -2, "y": 4.0}


def test_parse_packet_rejects_bad_shapes():
    bad_packets = [
        "not json",
        json.dumps({"timestamp": "2030-01-01T00:00:00Z", "readings": {}}),
        json.dumps({"spacecraft_id": "O", "timestamp": "2030-01-01T00:00:00", "readings": {}}),
        json.dumps({"spacecraft_id": "O", "timestamp": "2030-01-01T00:00:00Z", "readings": []}),
        json.dumps({"spacecraft_id": "O", "timestamp": "2030-01-01T00:00:00Z", "readings": {"x": True}}),
    ]
    for value in bad_packets:
        with pytest.raises(ValueError):
            parse_telemetry_packet(value)


def test_summary_groups_out_of_order_packets_and_calculates_statistics():
    requester = {"id": "u1", "tenant_id": "t1", "roles": []}
    craft = {"id": "ORION-1", "owner_id": "u1", "tenant_id": "t1"}
    packets = [
        packet("ORION-1", "2030-01-01T00:00:11Z", {"temp": 8}),
        packet("ORION-1", "2030-01-01T00:00:02Z", {"temp": 2}),
        packet("ORION-1", "2030-01-01T00:00:07.500Z", {"temp": 6}),
    ]
    result = summarize_telemetry(requester, craft, packets, "temp", 10)
    assert result == {
        "spacecraft_id": "ORION-1",
        "metric": "temp",
        "window_seconds": 10,
        "windows": [
            {"start": "2030-01-01T00:00:00Z", "count": 2, "average": 4.0, "minimum": 2.0, "maximum": 6.0},
            {"start": "2030-01-01T00:00:10Z", "count": 1, "average": 8.0, "minimum": 8.0, "maximum": 8.0},
        ],
    }


def test_summary_handles_empty_input_and_millisecond_output():
    requester = {"id": "u", "tenant_id": "t", "roles": ["flight_controller"]}
    craft = {"id": "O", "owner_id": "other", "tenant_id": "t"}
    assert summarize_telemetry(requester, craft, [], "x", 5)["windows"] == []
    result = summarize_telemetry(
        requester, craft,
        [packet("O", "2030-01-01T00:00:00.125Z", {"x": 1.25})], "x", 5
    )
    assert result["windows"][0]["start"] == "2030-01-01T00:00:00Z"
    assert result["windows"][0]["average"] == 1.25


def test_summary_rejects_invalid_arguments_and_packets():
    requester = {"id": "u", "tenant_id": "t", "roles": []}
    craft = {"id": "O", "owner_id": "u", "tenant_id": "t"}
    with pytest.raises(ValueError):
        summarize_telemetry(requester, craft, [packet("X", "2030-01-01T00:00:00Z", {"x": 1})], "x", 10)
    with pytest.raises(ValueError):
        summarize_telemetry(requester, craft, [], "", 10)
    with pytest.raises(ValueError):
        summarize_telemetry(requester, craft, [], "x", 0)
    with pytest.raises(ValueError):
        summarize_telemetry(requester, craft, [packet("O", "2030-01-01T00:00:00Z", {"y": 1})], "x", 10)


