        raise ValueError('invalid packet')
    if not value['timestamp'].endswith('Z'):
        raise ValueError('invalid timestamp')
    try:
        datetime.fromisoformat(value['timestamp'][:-1]).replace(tzinfo=timezone.utc)
    except ValueError as exc:
        raise ValueError('invalid timestamp') from exc
    readings = value.get('readings')
    if not isinstance(readings, dict):
        raise ValueError('invalid readings')
    if any((not isinstance(v, (int, float)) or isinstance(v, bool) for v in readings.values())):
        raise ValueError('invalid readings')
    return {'spacecraft_id': value['spacecraft_id'], 'timestamp': value['timestamp'], 'readings': readings}

