    except (SyntaxError, TypeError, ZeroDivisionError):
        raise ValueError()

def build_maintenance_plan(vehicles: list[dict], rule: str, horizon_days: int) -> list[dict]:
    if horizon_days < 0:
        raise ValueError()
    result = []
    names = ('id', 'mileage', 'engine_hours', 'age_years', 'downtime_days', 'critical', 'service_cost', 'last_service_days')
    for vehicle in vehicles:
        if evaluate_rule(rule, {k: vehicle[k] for k in names}) and vehicle['last_service_days'] > horizon_days:
            priority = (100 if vehicle['critical'] else 0) + 2 * vehicle['last_service_days'] + vehicle['mileage'] // 1000 + vehicle['engine_hours'] // 100 - vehicle['downtime_days']
