def export_flood_sensor_report(readings: list[dict], destination: str, alert_threshold: float=2.0) -> dict:
    if not isinstance(readings, list) or not readings:
        raise ValueError('readings must be a non-empty list')
    if isinstance(alert_threshold, bool) or not isinstance(alert_threshold, (int, float)) or (not math.isfinite(alert_threshold)) or (alert_threshold < 0):
        raise ValueError('invalid threshold')
    groups = {}
    for reading in readings:
        if not isinstance(reading, dict) or not isinstance(reading.get('sensor'), str) or (not reading['sensor']) or (not isinstance(reading.get('region'), str)) or (not reading['region']):
            raise ValueError('invalid reading')
        level = reading.get('level')
        if isinstance(level, bool) or not isinstance(level, (int, float)) or (not math.isfinite(level)):
            raise ValueError('invalid level')
        sensor = reading['sensor']
        region = reading['region']
        if sensor in groups and groups[sensor]['region'] != region:
            raise ValueError('conflicting region')
        if sensor not in groups:
            groups[sensor] = {'region': region, 'levels': []}
        groups[sensor]['levels'].append(float(level))
    rows = []
    for sensor, group in groups.items():
        levels = group['levels']
        rows.append({'sensor': sensor, 'region': group['region'], 'reading_count': len(levels), 'average_level': round(sum(levels) / len(levels), 2), 'max_level': round(max(levels), 2), 'alert_count': sum((level >= alert_threshold for level in levels))})
    rows.sort(key=lambda row: (-row['max_level'], row['sensor']))
    fd, temporary = tempfile.mkstemp(prefix='.flood-report-', suffix='.csv', dir=os.path.dirname(os.path.abspath(destination)))
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['sensor', 'region', 'reading_count', 'average_level', 'max_level', 'alert_count'])
            for row in rows:
                writer.writerow([row['sensor'], row['region'], row['reading_count'], f"{row['average_level']:.2f}", f"{row['max_level']:.2f}", row['alert_count']])
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return {'reading_count': len(readings), 'sensor_count': len(rows), 'alert_count': sum((row['alert_count'] for row in rows)), 'rows': rows}

