import subprocess
from datetime import datetime
_STATUSES = ('loaded', 'shipped', 'delayed', 'cancelled')

def parse_shipment(line: str) -> dict[str, object]:
    parts = line.rstrip('\n').split('|')
    if len(parts) != 6:
        raise ValueError('invalid shipment')
    ident, quarry, destination, tons, status, timestamp = parts
    if not ident or not quarry or (not destination) or (not timestamp):
        raise ValueError('invalid shipment')
    if status not in _STATUSES:
        raise ValueError('invalid shipment')
    if not tons.isdigit() or int(tons) <= 0:
        raise ValueError('invalid shipment')
    try:
        datetime.strptime(timestamp, '%Y-%m-%dT%H:%M:%S')
    except ValueError as exc:
        raise ValueError('invalid shipment') from exc
    return {'id': ident, 'quarry': quarry, 'destination': destination, 'tons': int(tons), 'status': status, 'timestamp': timestamp}

def sorted_shipments(manifest_path: str) -> list[dict[str, object]]:
    result = subprocess.run(['sort', '-t|', '-k6,6', '-k1,1', manifest_path], capture_output=True, text=True, check=True)
    return [parse_shipment(line) for line in result.stdout.splitlines() if line.strip()]

def summarize_shipments(manifest_path: str, destination: str) -> dict[str, object]:
    records = [x for x in sorted_shipments(manifest_path) if x['destination'] == destination]
    counts = {status: 0 for status in _STATUSES}
    daily = {}
    for record in records:
        counts[record['status']] += 1
        day = record['timestamp'][:10]
        daily[day] = daily.get(day, 0) + record['tons']
    return {'destination': destination, 'count': len(records), 'total_tons': sum((x['tons'] for x in records)), 'latest_timestamp': records[-1]['timestamp'] if records else None, 'status_counts': counts, 'daily_tons': daily}

