import os
from pathlib import Path

def write_rental_receipt(base_dir: str, relative_name: str, renter: str, book_title: str, days: int, daily_rate: float) -> str:
    if not relative_name or os.path.isabs(relative_name):
        raise ValueError('invalid receipt name')
    if not isinstance(days, int) or isinstance(days, bool) or days < 0:
        raise ValueError('days must be non-negative')
    base = Path(base_dir).resolve()
    target = (base / relative_name).resolve()
    try:
        target.relative_to(base)
    except ValueError:
        raise ValueError('receipt is outside base directory')
    target.parent.mkdir(parents=True, exist_ok=True)
    total = days * daily_rate
    text = f'Renter: {renter}\nBook: {book_title}\nDays: {days}\nDaily rate: ${daily_rate:.2f}\nTotal: ${total:.2f}\n'
    target.write_text(text, encoding='utf-8')
    return str(target)

