def summarize_responses(rows: list[dict], page: int=1, page_size: int=10) -> dict:
    if not isinstance(rows, list):
        raise ValueError('rows must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
    groups = {}
    for row in rows:
        if not isinstance(row, dict):
            raise ValueError('invalid row')
        district = row.get('district')
        completed = row.get('completed')
        if not isinstance(district, str) or not district or type(completed) is not bool:
            raise ValueError('invalid row')
        if district not in groups:
            groups[district] = [0, 0]
        groups[district][0] += 1
        groups[district][1] += int(completed)
