import hmac
import os

def create_signer_record(signer_name: str, pin: str) -> dict:
    if not isinstance(signer_name, str) or not signer_name.strip():
        raise ValueError('invalid signer name')
    if not isinstance(pin, str) or not pin.isdigit() or (not 4 <= len(pin) <= 8):
        raise ValueError('invalid PIN')
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return {'signer_name': signer_name, 'pin_proof': salt.hex() + '$' + value.hex()}

def verify_signer_pin(record: dict, pin: str) -> bool:
    try:
        if not isinstance(record, dict) or not isinstance(pin, str):
            return False
        salt_text, value_text = record['pin_proof'].split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(value_text)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError):
        return False

def sign_document(document_id: str, record: dict, pin: str) -> dict:
    if not isinstance(document_id, str) or not document_id.strip():
        raise ValueError('invalid document ID')
    if not verify_signer_pin(record, pin):
        raise PermissionError('approval denied')
    return {'document_id': document_id, 'signer_name': record['signer_name'], 'status': 'signed'}

