            raise ValueError('unsupported expression')
        if isinstance(node, ast.Constant) and (not isinstance(node.value, (int, float))):
            raise ValueError('unsupported constant')
        if isinstance(node, ast.Name) and node.id not in variables and (node.id not in {'min', 'max', 'round'}):
            raise NameError(node.id)
        if isinstance(node, ast.Call) and (not isinstance(node.func, ast.Name) or node.func.id not in {'min', 'max', 'round'} or node.keywords):
            raise ValueError('unsupported call')
    return _compute(tree.body, variables)

def _compute(node, env):
    if isinstance(node, ast.Constant):
        return node.value
    if isinstance(node, ast.Name):
        return env[node.id]
    if isinstance(node, ast.BinOp):
        return {ast.Add: lambda a, b: a + b, ast.Sub: lambda a, b: a - b, ast.Mult: lambda a, b: a * b, ast.Div: lambda a, b: a / b}[type(node.op)](_compute(node.left, env), _compute(node.right, env))
    if isinstance(node, ast.UnaryOp):
        return {ast.UAdd: lambda x: +x, ast.USub: lambda x: -x, ast.Not: lambda x: not x}[type(node.op)](_compute(node.operand, env))
    if isinstance(node, ast.BoolOp):
        value = _compute(node.values[0], env)
        for child in node.values[1:]:
            if isinstance(node.op, ast.And):
                if not value:
                    return value
            elif value:
                return value
            value = _compute(child, env)
        return value
    if isinstance(node, ast.Compare):
        left = _compute(node.left, env)
        for op, rightnode in zip(node.ops, node.comparators):
            right = _compute(rightnode, env)
            good = {ast.Eq: left == right, ast.NotEq: left != right, ast.Lt: left < right, ast.LtE: left <= right, ast.Gt: left > right, ast.GtE: left >= right}[type(op)]
            if not good:
                return False
            left = right
        return True
    return {'min': min, 'max': max, 'round': round}[node.func.id](*[_compute(x, env) for x in node.args])

