def evaluate_rule(expression: str, variables: dict[str, int | float | bool]) -> bool:
    try:
        tree = ast.parse(expression, mode='eval').body

        def ev(n):
            if isinstance(n, ast.Constant) and isinstance(n.value, (int, float, bool)):
                return n.value
            if isinstance(n, ast.Name):
                if n.id not in variables:
                    raise ValueError()
                return variables[n.id]
            if isinstance(n, ast.UnaryOp) and isinstance(n.op, (ast.UAdd, ast.USub, ast.Not)):
                v = ev(n.operand)
                return +v if isinstance(n.op, ast.UAdd) else -v if isinstance(n.op, ast.USub) else not v
            if isinstance(n, ast.BoolOp):
                if isinstance(n.op, ast.And):
                    v = True
                    for x in n.values:
                        v = ev(x)
                        if not v:
                            return v
                    return v
                v = False
                for x in n.values:
                    v = ev(x)
                    if v:
                        return v
                return v
            if isinstance(n, ast.BinOp) and isinstance(n.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
                a, b = (ev(n.left), ev(n.right))
                return a + b if isinstance(n.op, ast.Add) else a - b if isinstance(n.op, ast.Sub) else a * b if isinstance(n.op, ast.Mult) else a / b
            if isinstance(n, ast.Compare):
                left = ev(n.left)
                for op, part in zip(n.ops, n.comparators):
                    right = ev(part)
                    ok = left < right if isinstance(op, ast.Lt) else left <= right if isinstance(op, ast.LtE) else left > right if isinstance(op, ast.Gt) else left >= right if isinstance(op, ast.GtE) else left == right if isinstance(op, ast.Eq) else left != right if isinstance(op, ast.NotEq) else (_ for _ in ()).throw(ValueError())
                    if not ok:
                        return False
                    left = right
                return True
            if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and (n.func.id in ('min', 'max', 'round')) and (not n.keywords):
                args = [ev(x) for x in n.args]
                return {'min': min, 'max': max, 'round': round}[n.func.id](*args)
            raise ValueError()
        result = ev(tree)
        if not isinstance(result, bool):
            raise ValueError()
        return result
    except Exception as exc:
        if isinstance(exc, ValueError):
            raise
        raise ValueError() from exc

def provision_accounts(accounts: list[dict], rule: str, variables: dict[str, int | float | bool]) -> list[dict]:
    try:
        md, mb = (variables['max_disk_gb'], variables['max_bandwidth_gb'])
        if isinstance(md, bool) or isinstance(mb, bool) or (not math.isfinite(md)) or (not math.isfinite(mb)) or (md <= 0) or (mb < 0):
            raise ValueError()
        seen, candidates = (set(), [])
        keys = {'id', 'disk_gb', 'bandwidth_gb', 'users', 'priority', 'requested'}
