from solution import route_incident_batch
import hashlib
import hmac
import json
import pytest


def make_payload(tickets, teams):
    return json.dumps({"tickets": tickets, "teams": teams}, separators=(",", ":")).encode()


def sign(payload, key_id="primary", key=b"secret"):
    digest = hmac.new(key, payload, hashlib.sha256).hexdigest()
    return key_id + ":" + digest


def ticket(i, team="payments", severity="medium", created="2025-01-01T00:00:00Z", tags=None):
    return {"id": i, "team": team, "severity": severity, "created": created, "tags": [] if tags is None else tags}


def test_routes_and_sorts_by_all_tiebreakers():
    teams = {"payments": "queue-b", "auth": "queue-a"}
    data = [
        ticket("z", "payments", "low", "2025-01-01T00:00:01Z"),
        ticket("b", "auth", "critical", "2025-01-02T00:00:00Z", ["prod"]),
        ticket("a", "auth", "critical", "2025-01-01T00:00:00Z"),
        ticket("h", "payments", "high"),
    ]
    payload = make_payload(data, teams)
    result = route_incident_batch(payload, sign(payload), {"primary": b"secret"})
    assert [x["id"] for x in result["tickets"]] == ["a", "b", "h", "z"]
    assert result["tickets"][0]["queue"] == "queue-a"
    assert result["tickets"][0]["sla_hours"] == 1
    assert result["tickets"][2]["sla_hours"] == 4
    assert result["tickets"][3]["sla_hours"] == 72
    assert result["tickets"][1]["tags"] == ["prod"]


def test_summary_includes_empty_queues_and_is_sorted():
    payload = make_payload([ticket("1", "z")], {"z": "zz", "a": "aa", "m": "mm"})
    result = route_incident_batch(payload, sign(payload), {"primary": b"secret"})
    assert result["summary"] == {"aa": 0, "mm": 0, "zz": 1}
    assert list(result) == ["tickets", "summary"]


def test_multiple_keys_and_exact_signature_format():
    payload = make_payload([], {})
    secrets = {"old": b"one", "new": b"two"}
    assert route_incident_batch(payload, sign(payload, "new", b"two"), secrets) == {"tickets": [], "summary": {}}
    with pytest.raises(ValueError):
        route_incident_batch(payload, sign(payload, "old", b"one").upper(), secrets)


def test_signature_and_decoding_errors():
    payload = make_payload([], {})
    for sig in ["bad", "x:y:z", "missing:" + "0" * 64, "unknown:" + "0" * 64]:
        with pytest.raises(ValueError):
            route_incident_batch(payload, sig, {"primary": b"secret"})
    with pytest.raises(ValueError):
        route_incident_batch(b"\xff", "primary:" + "0" * 64, {"primary": b"secret"})


def test_validation_rejects_bad_ticket_shapes_and_dates():
    cases = [
        ticket("1", severity="urgent"),
        ticket("1", created="2025-02-30T00:00:00Z"),
        ticket("1", tags=["ok", 3]),
        {"id": "1", "team": "payments", "severity": "low", "created": "2025-01-01T00:00:00Z"},
        ticket("1", "unknown"),
    ]
    for bad in cases:
        payload = make_payload([bad], {"payments": "q"})
        with pytest.raises(ValueError):
            route_incident_batch(payload, sign(payload), {"primary": b"secret"})


def test_duplicate_ids_and_top_level_errors():
    payload = make_payload([ticket("same"), ticket("same")], {"payments": "q"})
