import hashlib
import hmac
import os

def hash_password(password: str) -> str:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    salt = os.urandom(16)
    iterations = 100000
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, iterations)
    return f'{iterations}${salt.hex()}${digest.hex()}'

def verify_password(password: str, stored: str) -> bool:
    if not isinstance(password, str) or not isinstance(stored, str):
        return False
    try:
        count_text, salt_text, digest_text = stored.split('$')
        count = int(count_text)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, count)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def buoy_summary(records: list[dict], password: str, stored_password: str, start: int, end: int, page: int=1, page_size: int=20) -> list[dict]:
    if start > end or page < 1 or page_size < 1:
        raise ValueError('invalid range or pagination')
    if not verify_password(password, stored_password):
        raise PermissionError('invalid password')
    groups = {}
    for record in records:
        if start <= record['timestamp'] <= end:
            item = groups.setdefault(record['buoy_id'], [])
            item.append((record['temperature'], record['wave_height']))
    result = []
    for buoy_id in sorted(groups):
        values = groups[buoy_id]
        result.append({'buoy_id': buoy_id, 'count': len(values), 'average_temperature': round(sum((x[0] for x in values)) / len(values), 2), 'maximum_wave_height': max((x[1] for x in values))})
    first = (page - 1) * page_size
    return result[first:first + page_size]

