import xml.etree.ElementTree as ET

def read_gradebook(xml_text: str) -> dict:
    if not isinstance(xml_text, str):
        raise ValueError('xml_text must be a string')
    try:
        root = ET.fromstring(xml_text)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'gradebook':
        raise ValueError('wrong root')
    assignments = []
    assignment_ids = set()
    for node in root.findall('assignment'):
        ident = node.get('id')
        if not ident or ident in assignment_ids:
            raise ValueError('invalid assignment')
        try:
            maximum = int(node.get('max', ''))
        except Exception as exc:
            raise ValueError('invalid maximum') from exc
        if maximum <= 0:
            raise ValueError('invalid maximum')
        assignment_ids.add(ident)
        assignments.append({'id': ident, 'max': maximum})
    students = []
    student_ids = set()
    for node in root.findall('student'):
        ident, name = (node.get('id'), node.get('name'))
        if not ident or name is None or ident in student_ids:
            raise ValueError('invalid student')
        scores = {}
        for score in node.findall('score'):
            aid, raw = (score.get('assignment'), score.get('value'))
            if not aid or aid in scores or aid not in assignment_ids or (raw is None):
                raise ValueError('invalid score')
            try:
                value = float(raw)
            except Exception as exc:
                raise ValueError('invalid score') from exc
            maximum = next((a['max'] for a in assignments if a['id'] == aid))
            if value < 0 or value > maximum:
                raise ValueError('invalid score')
            scores[aid] = int(value) if value.is_integer() else value
        student_ids.add(ident)
        students.append({'id': ident, 'name': name, 'scores': scores})
    return {'assignments': assignments, 'students': students}

def student_summary(data: dict, drop_lowest: int=0) -> list[dict]:
    if not isinstance(data, dict) or not isinstance(drop_lowest, int) or isinstance(drop_lowest, bool):
        raise ValueError('invalid arguments')
    assignments, students = (data.get('assignments'), data.get('students'))
    if not isinstance(assignments, list) or not isinstance(students, list) or drop_lowest < 0 or (drop_lowest > len(assignments)):
        raise ValueError('invalid data')
    seen = set()
    parsed = []
    for a in assignments:
        if not isinstance(a, dict) or set(a) != {'id', 'max'} or (not isinstance(a['id'], str)) or (a['id'] in seen) or (not isinstance(a['max'], int)) or (a['max'] <= 0):
            raise ValueError('invalid assignment')
        seen.add(a['id'])
        parsed.append(a)
    output, student_seen = ([], set())
    for s in students:
        if not isinstance(s, dict) or set(s) != {'id', 'name', 'scores'} or s['id'] in student_seen or (not isinstance(s['scores'], dict)):
            raise ValueError('invalid student')
        student_seen.add(s['id'])
        if any((k not in seen for k in s['scores'])):
            raise ValueError('unknown score')
        ranked = []
        for a in parsed:
            value = s['scores'].get(a['id'], 0)
            if not isinstance(value, (int, float)) or isinstance(value, bool) or value < 0 or (value > a['max']):
                raise ValueError('invalid score')
            ranked.append((value / a['max'], a['id'], value, a['max']))
        ranked.sort(key=lambda x: (x[0], x[1]))
        kept = ranked[drop_lowest:]
        earned, possible = (sum((x[2] for x in kept)), sum((x[3] for x in kept)))
        output.append({'id': s['id'], 'name': s['name'], 'earned': earned, 'possible': possible, 'percentage': round(earned * 100 / possible, 2) if possible else 0.0})
    output.sort(key=lambda x: (-x['percentage'], x['name'].casefold(), x['id']))
    return output

def gradebook_report(xml_text: str, drop_lowest: int=0) -> list[dict]:
    return student_summary(read_gradebook(xml_text), drop_lowest)

