import json
import math
import os
import zipfile

def synchronize_inventory(base_dir: str, archive_path: str, player_id: str, page: int=1, page_size: int=3) -> dict:
    if page < 1 or page_size < 1:
        raise ValueError('invalid pagination')
    root = os.path.realpath(os.path.join(base_dir, 'incoming'))
    os.makedirs(root, exist_ok=True)
    try:
        archive = zipfile.ZipFile(archive_path)
    except (OSError, zipfile.BadZipFile) as exc:
        raise ValueError('invalid archive') from exc
    try:
        for member in archive.infolist():
            if not member.filename.lower().endswith('.json'):
                continue
            target = os.path.realpath(os.path.join(root, member.filename))
            if os.path.commonpath((root, target)) != root:
                raise ValueError('invalid member path')
            os.makedirs(os.path.dirname(target), exist_ok=True)
            with archive.open(member) as source, open(target, 'wb') as destination:
                destination.write(source.read())
    finally:
        archive.close()
    grouped = {}
    for current, _, names in os.walk(root):
        for name in names:
            if not name.lower().endswith('.json'):
                continue
            try:
                with open(os.path.join(current, name), encoding='utf-8') as handle:
                    record = json.load(handle)
            except (OSError, json.JSONDecodeError, UnicodeDecodeError) as exc:
                raise ValueError('invalid record') from exc
            if not isinstance(record, dict):
                raise ValueError('invalid record')
            player = record.get('player')
            item = record.get('item')
            quantity = record.get('quantity')
            unit_weight = record.get('unit_weight')
            if not isinstance(player, str) or not isinstance(item, str) or (not item) or isinstance(quantity, bool) or (not isinstance(quantity, int)) or (quantity < 0) or isinstance(unit_weight, bool) or (not isinstance(unit_weight, (int, float))) or (not math.isfinite(unit_weight)) or (unit_weight < 0):
                raise ValueError('invalid record')
            if player == player_id:
                entry = grouped.setdefault(item, [0, 0.0])
                entry[0] += quantity
                entry[1] += quantity * unit_weight
    items = [{'name': name, 'quantity': values[0], 'weight': round(values[1], 2)} for name, values in grouped.items()]
    items.sort(key=lambda value: (-value['quantity'], value['name']))
    total = round(sum((value['weight'] for value in items)), 2)
    pages = (len(items) + page_size - 1) // page_size if items else 0
    start = (page - 1) * page_size
    return {'player': player_id, 'items': items[start:start + page_size], 'total_weight': total, 'page': page, 'pages': pages}

