import csv
import re
import subprocess
from collections import defaultdict

def _records(path, pattern):
    try:
        re.compile(pattern)
    except re.error as exc:
        raise ValueError(str(exc))
    try:
        result = subprocess.run(['grep', '-E', pattern, path], capture_output=True, text=True)
    except FileNotFoundError:
        raise
    if result.returncode not in (0, 1):
        raise FileNotFoundError(path)
    rows = []
    for line in result.stdout.splitlines():
        if not line.strip():
            continue
        fields = next(csv.reader([line]))
        if len(fields) != 3:
            raise ValueError('invalid record')
        try:
            timestamp = float(fields[0])
            duration = float(fields[1])
        except ValueError:
            raise ValueError('invalid numeric field')
        if timestamp < 0 or duration < 0 or (not fields[2]):
            raise ValueError('invalid record')
        timestamp = int(timestamp) if timestamp.is_integer() else timestamp
        duration = int(duration) if duration.is_integer() else duration
        rows.append((timestamp, duration, fields[2]))
    return rows

def summarize_trace(path: str, event_pattern: str, window_ms: int, top_n: int) -> list[dict]:
    if not isinstance(window_ms, int) or isinstance(window_ms, bool) or window_ms <= 0:
        raise ValueError('window_ms')
    if not isinstance(top_n, int) or isinstance(top_n, bool) or top_n <= 0:
        raise ValueError('top_n')
    groups = defaultdict(lambda: [0, 0])
    for timestamp, duration, event in _records(path, event_pattern):
        key = (int(timestamp // window_ms) * window_ms, event)
        groups[key][0] += 1
        groups[key][1] += duration
    answer = [{'window_start_ms': k[0], 'event': k[1], 'count': v[0], 'total_duration_ms': v[1]} for k, v in groups.items()]
    answer.sort(key=lambda x: (-x['total_duration_ms'], -x['count'], x['window_start_ms'], x['event']))
    return answer[:top_n]

def trace_percentile(path: str, event_pattern: str, percentile: float) -> float | None:
    if not isinstance(percentile, (int, float)) or isinstance(percentile, bool) or (not 0 <= percentile <= 100):
        raise ValueError('percentile')
    values = sorted((duration for _, duration, _ in _records(path, event_pattern)))
    if not values:
        return None
    position = (len(values) - 1) * percentile / 100
    low = int(position)
    high = min(low + 1, len(values) - 1)
    result = values[low] + (values[high] - values[low]) * (position - low)
    return int(result) if result.is_integer() else result

