import hmac
import json
import math

def aggregate_sensor_payload(payload: str, signature: str, key: bytes) -> list[dict]:
    try:
        supplied = bytes.fromhex(signature)
    except (TypeError, ValueError):
        raise ValueError('invalid signature')
    if len(supplied) != hashlib.sha256().digest_size:
        raise ValueError('invalid signature')
    expected = hmac.new(key, payload.encode('utf-8'), hashlib.sha256).digest()
    if not hmac.compare_digest(expected, supplied):
        raise ValueError('invalid signature')
    try:
        document = json.loads(payload)
    except (TypeError, ValueError):
        raise ValueError('invalid payload')
    if not isinstance(document, dict) or not isinstance(document.get('readings'), list):
        raise ValueError('invalid payload')
    groups = {}
    for reading in document['readings']:
        if not isinstance(reading, dict):
            raise ValueError('invalid reading')
        sensor = reading.get('sensor')
        timestamp = reading.get('timestamp')
        pm25 = reading.get('pm25')
        if not isinstance(sensor, str) or not sensor or isinstance(timestamp, bool) or (not isinstance(timestamp, int)) or (timestamp < 0) or isinstance(pm25, bool) or (not isinstance(pm25, (int, float))) or (not math.isfinite(pm25)) or (pm25 < 0) or (pm25 > 500):
            raise ValueError('invalid reading')
        group = groups.setdefault(sensor, {'values': [], 'latest': timestamp})
        group['values'].append(float(pm25))
        group['latest'] = max(group['latest'], timestamp)
    result = []
    for sensor, group in groups.items():
        result.append({'sensor': sensor, 'count': len(group['values']), 'average_pm25': round(sum(group['values']) / len(group['values']), 2), 'latest_timestamp': group['latest']})
    return sorted(result, key=lambda item: (-item['latest_timestamp'], item['sensor']))

