import csv
import io
import re
import secrets
from datetime import date

def parse_disclosures(text: str) -> list[dict]:
    rows = [r for r in csv.reader(io.StringIO(text)) if any((x.strip() for x in r))]
    header = [x.strip() for x in rows[0]] if rows else []
    expected = ['disclosure_id', 'title', 'filing_year', 'claim_count', 'priority_date']
    if header != expected or len(rows) < 2:
        raise ValueError('invalid document')
    result, seen = ([], set())
    for row in rows[1:]:
        if len(row) != 5:
            raise ValueError('invalid row')
        ident, title, year, claims, priority = [x.strip() for x in row]
        if not re.fullmatch('D-\\d{4}', ident) or not title or ident in seen:
            raise ValueError('invalid disclosure')
        try:
            year_i, claims_i = (int(year), int(claims))
            priority_d = date.fromisoformat(priority)
        except Exception as exc:
            raise ValueError('invalid value') from exc
        if not 1900 <= year_i <= 2100 or claims_i < 0:
            raise ValueError('invalid value')
        seen.add(ident)
        result.append({'disclosure_id': ident, 'title': title, 'filing_year': year_i, 'claim_count': claims_i, 'priority_date': priority_d})
    return result

def rank_disclosures(disclosures: list[dict], current_year: int) -> list[dict]:
    if not 1900 <= current_year <= 2100:
        raise ValueError('invalid year')
    needed = {'disclosure_id', 'title', 'filing_year', 'claim_count', 'priority_date'}
    output = []
    for item in disclosures:
        if not needed.issubset(item):
            raise ValueError('incomplete disclosure')
        copy = dict(item)
        copy['priority_score'] = item['claim_count'] * 2 + max(0, 10 - (current_year - item['filing_year']))
        output.append(copy)
    return sorted(output, key=lambda x: (-x['priority_score'], x['priority_date'], x['disclosure_id']))

