import sqlite3
from datetime import date

def search_loans(conn: sqlite3.Connection, search: str='', statuses: tuple[str, ...]=(), sort_by: str='due_date', descending: bool=False) -> list[tuple]:
    allowed = {'id', 'borrower', 'item', 'checked_out', 'due_date', 'status'}
    if sort_by not in allowed:
        raise ValueError('invalid sort column')
    if any((value not in {'active', 'returned'} for value in statuses)):
        raise ValueError('invalid status')
    clauses = []
    params = []
    if search:
        clauses.append('(lower(borrower) like lower(?) or lower(item) like lower(?))')
        pattern = '%' + search + '%'
        params.extend([pattern, pattern])
    if statuses:
        clauses.append('status in (' + ','.join(('?' for _ in statuses)) + ')')
        params.extend(statuses)
    query = 'select id, borrower, item, checked_out, due_date, returned_on, status from loans'
    if clauses:
        query += ' where ' + ' and '.join(clauses)
    query += ' order by ' + sort_by + (' desc' if descending else ' asc') + ', id asc'
    return conn.execute(query, params).fetchall()

def loan_totals(conn: sqlite3.Connection) -> dict[str, dict[str, int]]:
    result = {}
    rows = conn.execute('select borrower, status, count(*) from loans group by borrower, status order by borrower').fetchall()
    for borrower, status, count in rows:
        if borrower not in result:
            result[borrower] = {'total': 0, 'active': 0, 'returned': 0}
        result[borrower][status] = count
        result[borrower]['total'] += count
    return result

def close_loan(conn: sqlite3.Connection, loan_id: int, returned_on: str) -> None:
    try:
        parsed = date.fromisoformat(returned_on)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if parsed.isoformat() != returned_on:
        raise ValueError('invalid date')
    row = conn.execute('select status from loans where id = ?', (loan_id,)).fetchone()
    if row is None:
        raise KeyError(loan_id)
    if row[0] == 'returned':
        raise ValueError('loan already returned')
    conn.execute("update loans set returned_on = ?, status = 'returned' where id = ?", (returned_on, loan_id))
    conn.commit()

