def _evaluate(node, values):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, str, bool)):
        return node.value
    if isinstance(node, ast.Name) and node.id in values:
        return values[node.id]
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
        value = _evaluate(node.operand, values)
        if isinstance(node.op, ast.UAdd):
            return +value
        if isinstance(node.op, ast.USub):
            return -value
        return not value
    if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
        left, right = (_evaluate(node.left, values), _evaluate(node.right, values))
        return {ast.Add: lambda: left + right, ast.Sub: lambda: left - right, ast.Mult: lambda: left * right, ast.Div: lambda: left / right}[type(node.op)]()
    if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
        result = _evaluate(node.values[0], values)
        for part in node.values[1:]:
            result = _evaluate(part, values) if isinstance(node.op, ast.And) and result or (isinstance(node.op, ast.Or) and (not result)) else result
        return result
    if isinstance(node, ast.Compare):
        left = _evaluate(node.left, values)
        for op, part in zip(node.ops, node.comparators):
            right = _evaluate(part, values)
            if not {ast.Eq: lambda: left == right, ast.NotEq: lambda: left != right, ast.Lt: lambda: left < right, ast.LtE: lambda: left <= right, ast.Gt: lambda: left > right, ast.GtE: lambda: left >= right}.get(type(op), lambda: False)():
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max', 'round'}) and (not node.keywords):
        return getattr(__builtins__, node.func.id)(*[_evaluate(x, values) for x in node.args])
    raise ValueError('invalid rule')

def select_consultations(records: list[dict], rule: str, page: int=1, page_size: int=10) -> dict:
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid page')
    try:
        tree = ast.parse(rule, mode='eval').body
        chosen = []
        for record in records:
            value = _evaluate(tree, {key: record[key] for key in ('id', 'surgeon', 'price', 'wait_days', 'rating')})
            if not isinstance(value, bool):
                raise ValueError('rule must be boolean')
            if value:
                chosen.append(record)
    except Exception as exc:
        if isinstance(exc, ValueError) and str(exc) == 'rule must be boolean':
            raise
        raise ValueError('invalid rule') from exc
    chosen.sort(key=lambda x: (-x['rating'], x['wait_days'], x['id']))
    start = (page - 1) * page_size
    items = [dict(x) for x in chosen[start:start + page_size]]
    average = round(sum((x['price'] for x in chosen)) / len(chosen), 2) if chosen else None
    return {'total': len(chosen), 'average_price': average, 'items': items}

