from datetime import datetime, timezone
from collections import defaultdict

def build_calibration_report(requester: dict, sensors: list[dict], readings: list[dict], page: int=1, page_size: int=10) -> list[dict]:
    if not isinstance(page, int) or not isinstance(page_size, int):
        raise TypeError()
    if page < 1 or page_size < 1:
        raise ValueError()
    if not isinstance(requester, dict) or not all((k in requester for k in ('id', 'tenant_id', 'roles'))):
        raise ValueError()
    grouped = defaultdict(list)
    for reading in readings:
        if not all((k in reading for k in ('sensor_id', 'timestamp', 'raw', 'reference'))):
            raise ValueError()
        try:
            parsed = datetime.fromisoformat(reading['timestamp'])
        except (TypeError, ValueError):
            raise ValueError()
        if parsed.tzinfo is None:
            comparable = parsed.replace(tzinfo=timezone.utc)
        else:
            comparable = parsed.astimezone(timezone.utc)
        grouped[reading['sensor_id']].append((comparable, reading['timestamp'], reading['raw'], reading['reference']))
    rows = []
    for sensor in sensors:
        if not all((k in sensor for k in ('id', 'tenant_id', 'owner_id', 'status'))):
            raise ValueError()
        if sensor['status'] != 'active':
            continue
        if sensor['tenant_id'] != requester['tenant_id'] or (sensor['owner_id'] != requester['id'] and 'calibration_admin' not in requester['roles']):
            raise PermissionError()
        items = grouped.get(sensor['id'], [])
        if not items:
            continue
        raw_mean = sum((x[2] for x in items)) / len(items)
        if raw_mean == 0:
            raise ValueError()
        offset = sum((x[3] - x[2] for x in items)) / len(items)
        latest = max(items, key=lambda x: x[0])
        rows.append({'sensor_id': sensor['id'], 'sample_count': len(items), 'offset': round(offset, 3), 'gain': round(sum((x[3] for x in items)) / len(items) / raw_mean, 3), 'last_timestamp': latest[1]})
    rows.sort(key=lambda x: (-x['sample_count'], x['sensor_id']))
    start = (page - 1) * page_size
    return rows[start:start + page_size]

