import hashlib
import hmac
import os

def hash_password(password: str) -> str:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    iterations = 100000
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, iterations)
    return f'{iterations}${salt.hex()}${digest.hex()}'

def verify_password(stored: str, password: str) -> bool:
    if not isinstance(stored, str) or not isinstance(password, str):
        raise TypeError('arguments must be strings')
    try:
        count, salt_hex, digest_hex = stored.split('$')
        iterations = int(count)
        salt = bytes.fromhex(salt_hex)
        expected = bytes.fromhex(digest_hex)
        if iterations <= 0 or not salt or (not expected):
            return False
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, iterations)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def parse_job(spec: str) -> dict[str, object]:
    if not isinstance(spec, str):
        raise TypeError('spec must be a string')
    fields, current, escaped = ([], [], False)
    for char in spec:
        if escaped:
            if char not in '\\|':
                raise ValueError('invalid escape')
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape')
    fields.append(''.join(current))
    if len(fields) != 5 or not fields[0] or (not fields[4]):
        raise ValueError('invalid job')
    try:
        priority, duration = (int(fields[2]), int(fields[3]))
    except ValueError:
        raise ValueError('invalid numbers')
    if not 0 <= priority <= 9 or duration <= 0:
        raise ValueError('invalid numbers')
    return {'id': fields[0], 'owner': fields[1], 'priority': priority, 'duration': duration, 'material': fields[4]}

def build_queue(specs: list[str], printers: dict[str, list[str] | set[str]]) -> list[dict[str, object]]:
    jobs = [parse_job(spec) for spec in specs]
    if len({job['id'] for job in jobs}) != len(jobs):
        raise ValueError('duplicate job')
    counts = {name: 0 for name in printers}
    result = []
    for job in sorted(jobs, key=lambda x: (-x['priority'], x['duration'], x['id'])):
        choices = [name for name, materials in printers.items() if job['material'] in materials]
        if not choices:
            raise ValueError('no compatible printer')
        printer = min(choices, key=lambda name: (counts[name], name))
        counts[printer] += 1
        result.append({**job, 'printer': printer})
    return result

