from solution import rank_shifts


def test_ranks_by_shift_fields():
    shifts = [
        {"id": "A", "hours": 8, "skill": 3},
        {"id": "B", "hours": 6, "skill": 5},
        {"id": "C", "hours": 4, "skill": 1},
    ]
    assert rank_shifts(shifts, "hours * skill", {}) == [("B", 30), ("A", 24), ("C", 4)]


def test_uses_variables_and_filters_nonpositive_results():
    shifts = [
        {"id": "early", "hours": 8},
        {"id": "late", "hours": 4},
        {"id": "off", "hours": 0},
    ]
    assert rank_shifts(shifts, "hours - minimum", {"minimum": 5}) == [("early", 3)]


def test_ties_keep_input_order():
    shifts = [
        {"id": "first", "hours": 4},
        {"id": "second", "hours": 8},
        {"id": "third", "hours": 6},
    ]
    assert rank_shifts(shifts, "min(hours, 4)", {}) == [("first", 4), ("second", 4), ("third", 4)]


def test_parentheses_comparisons_and_boolean_expression():
    shifts = [
        {"id": "one", "hours": 8, "night": 1},
        {"id": "two", "hours": 5, "night": 0},
        {"id": "three", "hours": 10, "night": 1},
    ]
    assert rank_shifts(shifts, "(hours >= 8 and night == 1) * hours", {}) == [("three", 10), ("one", 8)]


def test_round_and_division():
    shifts = [
        {"id": "A", "hours": 7},
        {"id": "B", "hours": 3},
    ]
    assert rank_shifts(shifts, "round(hours / divisor, 1)", {"divisor": 2}) == [("A", 3.5), ("B", 1.5)]


def test_empty_input_and_original_data_unchanged():
    shifts = [{"id": "A", "hours": 8}]
    original = [dict(item) for item in shifts]
    assert rank_shifts([], "hours", {}) == []
    assert rank_shifts(shifts, "hours", {}) == [("A", 8)]
    assert shifts == original


def test_unknown_name_raises_name_error():
    try:
        rank_shifts([{"id": "A", "hours": 8}], "missing + 1", {})
    except NameError:
        pass
    else:
        assert False

