from lxml import etree
import math

def rank_mission_telemetry(xml_text: str, page: int=1, page_size: int=10) -> list[dict[str, object]]:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError('invalid pagination')
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml_text.encode('utf-8'), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'telemetry':
        raise ValueError('invalid root')
    groups = {}
    for node in root:
        if node.tag != 'record':
            continue
        attrs = node.attrib
        try:
            mission = attrs['mission']
            timestamp = int(attrs['timestamp'], 10)
            signal = float(attrs['signal'])
            status = attrs['status']
        except (KeyError, TypeError, ValueError) as exc:
            raise ValueError('invalid record') from exc
        if not mission or not math.isfinite(signal):
            raise ValueError('invalid record')
        if status != 'nominal':
            continue
        if mission not in groups:
            groups[mission] = {'values': [], 'latest': timestamp}
        group = groups[mission]
        group['values'].append(signal)
        group['latest'] = max(group['latest'], timestamp)
    result = []
    for mission, group in groups.items():
        values = group['values']
        average = sum(values) / len(values)
        result.append({'mission': mission, 'average_signal': round(average, 2), 'peak_signal': round(max(values), 2), 'latest_timestamp': group['latest'], 'samples': len(values), '_average': average})
    result.sort(key=lambda item: (-item['_average'], item['mission']))
    start = (page - 1) * page_size
    selected = result[start:start + page_size]
    for item in selected:
        del item['_average']
    return selected

