def handle_membership_webhook(payload: bytes, signature: str, secret: str, page: int=1, page_size: int=3) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid pagination')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid pagination')
    if not isinstance(payload, bytes) or not isinstance(signature, str) or (not isinstance(secret, str)):
