    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'rateSheet':
        raise ValueError('invalid root')
    rows = []
    rates = root.findall('rate')
    if not rates:
        raise ValueError('no rates')
    for rate_node in rates:
        effective = _day(rate_node.get('effective'))
        lanes = rate_node.findall('lane')
        if not lanes:
            raise ValueError('no lanes')
        for lane in lanes:
            origin, destination = (lane.get('origin'), lane.get('destination'))
            transit = lane.get('transit_days')
            if not origin or not destination or transit is None:
                raise ValueError('missing lane data')
            try:
