            except ValueError:
                raise ValueError('invalid transit')
            if transit_i < 0:
                raise ValueError('invalid transit')
            tiers = lane.findall('tier')
            if not tiers:
                raise ValueError('no tiers')
            for tier in tiers:
                try:
                    lo, hi = (int(tier.get('min_kg')), int(tier.get('max_kg')))
                except (TypeError, ValueError):
                    raise ValueError('invalid range')
                if lo < 0 or hi < lo or (not tier.get('currency')):
                    raise ValueError('invalid tier')
                surcharges = []
                for s in tier.findall('surcharge'):
                    code, amount = (s.get('code'), s.get('amount'))
                    if not code or amount is None:
                        raise ValueError('invalid surcharge')
                    surcharges.append({'code': code, 'amount': _number(amount)})
                rows.append({'effective': effective, 'origin': origin, 'destination': destination, 'transit_days': transit_i, 'min_kg': lo, 'max_kg': hi, 'rate': _number(tier.get('rate')), 'currency': tier.get('currency'), 'surcharges': surcharges})
    return rows

def quote_shipment(xml: str, origin: str, destination: str, weight_kg: float, as_of: str, currency: str='USD') -> dict[str, Any]:
    if not isinstance(origin, str) or not origin or (not isinstance(destination, str)) or (not destination) or (not isinstance(currency, str)) or (not currency):
