    surcharge = round(sum((s['amount'] for s in chosen['surcharges'])), 2)
    return {'origin': origin, 'destination': destination, 'effective': chosen['effective'], 'currency': currency, 'weight_kg': weight_kg, 'base': base, 'surcharges': surcharge, 'total': round(base + surcharge, 2), 'transit_days': chosen['transit_days']}

