                rows.append({'effective': effective, 'origin': origin, 'destination': destination, 'transit_days': transit_i, 'min_kg': lo, 'max_kg': hi, 'rate': _number(tier.get('rate')), 'currency': tier.get('currency'), 'surcharges': surcharges})
    return rows

def quote_shipment(xml: str, origin: str, destination: str, weight_kg: float, as_of: str, currency: str='USD') -> dict[str, Any]:
    if not isinstance(origin, str) or not origin or (not isinstance(destination, str)) or (not destination) or (not isinstance(currency, str)) or (not currency):
        raise ValueError('invalid argument')
    if not isinstance(weight_kg, (int, float)) or not isfinite(weight_kg) or weight_kg <= 0:
        raise ValueError('invalid weight')
    cutoff = _day(as_of)
    rows = [r for r in parse_rate_sheet(xml) if r['origin'] == origin and r['destination'] == destination and (r['effective'] <= cutoff)]
    if not rows:
        raise ValueError('no matching rate')
    newest = max((r['effective'] for r in rows))
    rows = [r for r in rows if r['effective'] == newest and r['currency'] == currency and (r['min_kg'] <= weight_kg <= r['max_kg'])]
    if not rows:
        raise ValueError('no suitable tier')
    chosen = min(rows, key=lambda r: round(weight_kg * r['rate'], 2) + round(sum((s['amount'] for s in r['surcharges'])), 2))
    base = round(weight_kg * chosen['rate'], 2)
    surcharge = round(sum((s['amount'] for s in chosen['surcharges'])), 2)
    return {'origin': origin, 'destination': destination, 'effective': chosen['effective'], 'currency': currency, 'weight_kg': weight_kg, 'base': base, 'surcharges': surcharge, 'total': round(base + surcharge, 2), 'transit_days': chosen['transit_days']}

