def build_energy_histogram(requester: dict, dataset: dict, bin_width: float, offset: int=0, limit: int | None=None) -> dict:
    if not isinstance(requester, dict) or not isinstance(dataset, dict):
        raise TypeError('requester and dataset must be dictionaries')
    if not isinstance(dataset.get('events'), list):
        raise TypeError('events must be a list')
    if not isinstance(bin_width, (int, float)) or isinstance(bin_width, bool) or (not math.isfinite(bin_width)) or (bin_width <= 0):
        raise ValueError('invalid bin width')
    if not isinstance(offset, int) or isinstance(offset, bool) or offset < 0:
        raise ValueError('invalid offset')
    if limit is not None and (not isinstance(limit, int) or isinstance(limit, bool) or limit < 0):
        raise ValueError('invalid limit')
    if not (requester.get('id') == dataset.get('owner_id') or ('analyst' in requester.get('roles', []) and requester.get('tenant_id') == dataset.get('tenant_id'))):
        raise PermissionError('dataset access denied')
    events = dataset['events']
    parsed = []
    for event in events:
        if not isinstance(event, dict) or 'energy' not in event or 'weight' not in event:
            raise ValueError('invalid event')
        energy = event['energy']
        weight = event['weight']
        if not isinstance(energy, (int, float)) or isinstance(energy, bool) or (not math.isfinite(energy)) or (energy < 0) or (not isinstance(weight, (int, float))) or isinstance(weight, bool) or (not math.isfinite(weight)) or (weight <= 0):
            raise ValueError('invalid event')
        parsed.append((float(energy), float(weight)))
    count = 0 if not parsed else int(math.floor(max((e for e, _ in parsed)) / bin_width)) + 1
    weights = [0.0] * count
    for energy, weight in parsed:
        weights[min(int(math.floor(energy / bin_width)), count - 1)] += weight
    bins = [{'start': round(i * bin_width, 6), 'end': round((i + 1) * bin_width, 6), 'weight': round(w, 6)} for i, w in enumerate(weights)]
    selected = bins[offset:] if limit is None else bins[offset:offset + limit]
    return {'dataset_id': dataset.get('id'), 'total_events': len(parsed), 'total_weight': round(sum((w for _, w in parsed)), 6), 'bins': selected}

