import csv
import math
import subprocess

def read_bids(path: str) -> list[dict[str, object]]:
    try:
        with open(path, encoding='utf-8', newline='') as f:
            rows = list(csv.reader(f))
    except FileNotFoundError:
        raise
    if not rows or rows[0] != ['bid_id', 'zone', 'price_mwh', 'quantity_mwh', 'timestamp']:
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if len(row) != 5 or any((x == '' for x in row[:2])):
            raise ValueError('invalid row')
        try:
            price = float(row[2])
            quantity = float(row[3])
        except ValueError:
            raise ValueError('invalid number')
        if not math.isfinite(price) or not math.isfinite(quantity) or quantity <= 0:
            raise ValueError('invalid number')
        result.append({'bid_id': row[0], 'zone': row[1], 'price_mwh': price, 'quantity_mwh': quantity, 'timestamp': row[4]})
    return result

def rank_bids(path: str, zone: str, limit: int) -> list[dict[str, object]]:
    if isinstance(limit, bool) or not isinstance(limit, int) or limit < 0:
        raise ValueError('invalid limit')
    bids = read_bids(path)
    completed = subprocess.run(['sort', '-t,', '-k3,3n', '-k5,5', '-k1,1', path], capture_output=True, text=True, check=True)
    result = []
    for line in completed.stdout.splitlines():
        if line == 'bid_id,zone,price_mwh,quantity_mwh,timestamp':
            continue
        fields = next((b for b in bids if ','.join([str(b['bid_id']), str(b['zone']), str(b['price_mwh']), str(b['quantity_mwh']), str(b['timestamp'])]) == line), None)
        if fields is not None and fields['zone'] == zone:
            result.append(dict(fields))
    return result[:limit]

def summarize_market(path: str, zone: str, limit: int, target_quantity: float) -> dict[str, object]:
    if not math.isfinite(target_quantity) or target_quantity < 0:
        raise ValueError('invalid target')
    ranked = rank_bids(path, zone, limit)
    accepted = []
    remaining = target_quantity
    total = 0.0
    value = 0.0
    for bid in ranked:
        if remaining <= 0:
            break
        used = min(float(bid['quantity_mwh']), remaining)
        total += used
        value += used * float(bid['price_mwh'])
        accepted.append(dict(bid))
        remaining -= used
    return {'accepted_bids': accepted, 'accepted_quantity': round(total, 6), 'weighted_average_price': round(value / total, 6) if total else None, 'marginal_price': accepted[-1]['price_mwh'] if accepted else None}

