from datetime import datetime

def parse_event_time(value: str) -> tuple[str, int]:
    if not isinstance(value, str):
        raise ValueError('invalid timestamp')
    try:
        parsed = datetime.strptime(value, '%Y-%m-%dT%H:%M:%SZ')
    except (TypeError, ValueError):
        raise ValueError('invalid timestamp')
    return (parsed.strftime('%Y-%m-%d'), parsed.hour)

def aggregate_metrics(rows: list[dict[str, object]]) -> list[dict[str, object]]:
    groups = {}
    for row in rows:
        try:
            date, hour = parse_event_time(row['timestamp'])
            team = row['team']
            metric = row['metric']
            status = row['status']
        except (KeyError, TypeError):
            raise ValueError('invalid row')
        if not isinstance(team, str) or not team or isinstance(metric, bool) or (not isinstance(metric, (int, float))) or (metric < 0) or (status not in ('ok', 'error')):
            raise ValueError('invalid row')
        key = (date, team, hour)
        item = groups.setdefault(key, [0, 0, 0])
        item[0] += 1
        item[1] += status == 'error'
        item[2] += metric
    result = []
    for (date, team, hour), (count, errors, total) in sorted(groups.items()):
        result.append({'date': date, 'team': team, 'hour': hour, 'count': count, 'errors': errors, 'total': total, 'average': round(total / count, 2)})
    return result

def refresh_dashboard(config: dict[str, object], rows: list[dict[str, object]]) -> dict[str, object]:
    endpoint = config.get('endpoint')
    tenant = config.get('tenant')
    token = config.get('token')
    revision = config.get('revision')
    if not isinstance(endpoint, str) or not endpoint or (not isinstance(tenant, str)) or (not tenant) or (not isinstance(token, str)) or (not token) or isinstance(revision, bool) or (not isinstance(revision, int)) or (revision < 0):
        raise ValueError('invalid dashboard configuration')
    return {'method': 'POST', 'url': endpoint.rstrip('/') + '/v1/tenants/' + tenant + '/dashboard/refresh', 'headers': {'Content-Type': 'application/json', 'Authorization': 'Bearer ' + token}, 'json': {'revision': revision, 'groups': aggregate_metrics(rows)}}

