import json
import math
import os
import tempfile
from decimal import Decimal, ROUND_HALF_UP

def build_ad_report(episodes: list[dict], campaigns: list[dict], page: int=1, page_size: int=20) -> list[dict]:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError('invalid page size')

    def valid_text(value):
        return isinstance(value, str) and bool(value)
    for ep in episodes:
        if not valid_text(ep.get('id')) or not isinstance(ep.get('category'), str):
            raise ValueError('invalid episode')
        if not isinstance(ep.get('duration'), int) or isinstance(ep.get('duration'), bool) or ep['duration'] < 0:
            raise ValueError('invalid duration')
    for ca in campaigns:
        if not valid_text(ca.get('id')) or not isinstance(ca.get('category'), str):
            raise ValueError('invalid campaign')
        if any((not isinstance(ca.get(k), int) or isinstance(ca.get(k), bool) or ca[k] < 0 for k in ('active_from', 'active_to'))):
            raise ValueError('invalid range')
        if ca['active_from'] > ca['active_to'] or isinstance(ca.get('rate'), bool) or (not isinstance(ca.get('rate'), (int, float))) or (not math.isfinite(ca['rate'])) or (ca['rate'] < 0):
            raise ValueError('invalid rate')
    fd, path = tempfile.mkstemp()
    os.close(fd)
    try:
        rows = []
        for i, ep in enumerate(episodes):
            count = min(3, ep['duration'] // 300)
            eligible = [c for c in campaigns if c['category'] == ep['category'] and c['active_from'] <= i <= c['active_to']]
            if count and eligible:
                chosen = min(eligible, key=lambda c: (-c['rate'], c['id']))
                rows.append({'campaign_id': chosen['id'], 'episode_id': ep['id'], 'placements': count, 'rate': chosen['rate']})
        with open(path, 'w', encoding='utf-8') as f:
            json.dump(rows, f)
        with open(path, encoding='utf-8') as f:
            rows = json.load(f)
    finally:
        os.unlink(path)
    grouped = {}
    for row in rows:
        g = grouped.setdefault(row['campaign_id'], {'campaign_id': row['campaign_id'], 'placements': 0, 'revenue': Decimal('0'), 'episode_ids': []})
        g['placements'] += row['placements']
        g['revenue'] += Decimal(str(row['rate'])) * row['placements']
        if row['episode_id'] not in g['episode_ids']:
            g['episode_ids'].append(row['episode_id'])
    result = []
    for g in grouped.values():
        result.append({'campaign_id': g['campaign_id'], 'placements': g['placements'], 'revenue': float(g['revenue'].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)), 'episode_ids': g['episode_ids']})
    result.sort(key=lambda x: (-x['revenue'], x['campaign_id']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

