import hashlib
import hmac
import json
from datetime import datetime
WEBHOOK_SECRET = 'district-heating-forecast-secret'

def process_forecast_webhook(payload: str, signature: str) -> dict:
    if not isinstance(payload, str) or not isinstance(signature, str):
        raise ValueError('invalid signature')
    expected = hmac.new(WEBHOOK_SECRET.encode(), payload.encode(), hashlib.sha256).hexdigest()
    if len(signature) != 64 or not hmac.compare_digest(signature, expected):
        raise ValueError('invalid signature')
    try:
        body = json.loads(payload)
        readings = body['readings']
        if not isinstance(body, dict) or not isinstance(readings, list):
            raise ValueError
        totals = {}
        counts = {}
        for reading in readings:
            if not isinstance(reading, dict):
                raise ValueError
            district = reading['district']
            timestamp = reading['timestamp']
            load = reading['load_mwh']
            if not isinstance(district, str) or not district:
                raise ValueError
            if not isinstance(timestamp, str) or not timestamp.endswith('Z'):
                raise ValueError
            datetime.fromisoformat(timestamp[:-1] + '+00:00')
            if isinstance(load, bool) or not isinstance(load, (int, float)) or load < 0:
                raise ValueError
            totals[district] = totals.get(district, 0) + load
            counts[district] = counts.get(district, 0) + 1
    except (ValueError, TypeError, KeyError, json.JSONDecodeError, OverflowError):
        raise ValueError('invalid payload')
    ordered = sorted(totals, key=lambda district: (-totals[district], district))
    return {'total_mwh': round(sum(totals.values()), 2), 'peak_district': ordered[0] if ordered else None, 'districts': [{'district': district, 'readings': counts[district], 'total_mwh': round(totals[district], 2)} for district in ordered]}

