import csv
import datetime
import io
import os
import zipfile

def parse_claim_manifest(text: str) -> list[dict]:
    rows = [r for r in csv.reader(io.StringIO(text)) if any((x.strip() for x in r))]
    header = ['filename', 'category', 'amount_cents', 'incurred_date']
    if not rows:
        return []
    if rows[0] != header:
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if len(row) != 4:
            raise ValueError('invalid row')
        filename, category, amount, date = (x.strip() for x in row)
        if not filename or not category:
            raise ValueError('empty field')
        try:
            amount = int(amount)
            datetime.date.fromisoformat(date)
        except Exception as exc:
            raise ValueError('invalid value') from exc
        if amount < 0:
            raise ValueError('invalid amount')
        result.append({'filename': filename, 'category': category, 'amount_cents': amount, 'incurred_date': date})
    return result

def extract_claim_files(base_dir: str, claim_id: str, archive_data: bytes) -> list[str]:
    root = os.path.abspath(os.path.join(base_dir, claim_id))
    os.makedirs(root, exist_ok=True)
    names = []
    with zipfile.ZipFile(io.BytesIO(archive_data)) as archive:
        for info in archive.infolist():
            target = os.path.abspath(os.path.join(root, info.filename))
            if os.path.commonpath((root, target)) != root:
                raise ValueError('invalid member')
            if info.is_dir():
                os.makedirs(target, exist_ok=True)
            else:
                os.makedirs(os.path.dirname(target), exist_ok=True)
                with open(target, 'wb') as handle:
                    handle.write(archive.read(info))
                names.append(info.filename.replace('\\', '/'))
    return sorted(names)

def process_claim(base_dir: str, claim_id: str, archive_data: bytes, manifest_text: str) -> dict:
    files = extract_claim_files(base_dir, claim_id, archive_data)
    rows = parse_claim_manifest(manifest_text)
    root = os.path.join(base_dir, claim_id)
    for row in rows:
        if row['filename'] not in files:
            raise ValueError('missing file')
    result_rows = []
    totals = {}
    for row in rows:
        path = os.path.join(root, *row['filename'].replace('\\', '/').split('/'))
        size = os.path.getsize(path)
        item = dict(row)
        item['size'] = size
        result_rows.append(item)
        totals[row['category']] = totals.get(row['category'], 0) + row['amount_cents']
    result_rows.sort(key=lambda x: (x['incurred_date'], x['filename'], x['category']))
    return {'files': files, 'total_cents': sum((x['amount_cents'] for x in rows)), 'by_category': dict(sorted(totals.items())), 'rows': result_rows}

