_ORGANS = {'heart', 'kidney', 'liver', 'lung'}
_BLOOD = {'O', 'A', 'B', 'AB'}

def parse_waitlist_csv(text: str) -> list[dict]:
    try:
        rows = list(csv.reader(io.StringIO(text, newline='')))
    except csv.Error as exc:
        raise ValueError('invalid csv') from exc
    if not rows or rows[0] != _FIELDS or len(rows) == 1:
        raise ValueError('invalid header or empty data')
    result = []
    seen = set()
    for row in rows[1:]:
        if len(row) != 5:
            raise ValueError('wrong field count')
        vals = [x.strip() for x in row]
        pid, organ, blood, urgency, listed = vals
        if not pid or pid in seen or organ not in _ORGANS or (blood not in _BLOOD):
            raise ValueError('invalid row')
        try:
            level = int(urgency)
            parsed = datetime.strptime(listed, '%Y-%m-%d').date()
        except Exception as exc:
            raise ValueError('invalid row') from exc
        if not 1 <= level <= 5 or parsed.strftime('%Y-%m-%d') != listed:
            raise ValueError('invalid row')
        seen.add(pid)
        result.append({'patient_id': pid, 'organ': organ, 'blood_type': blood, 'urgency': level, 'listed_date': parsed})
