import csv
import datetime
import os
import zipfile

def process_meter_archive(archive_path: str, output_dir: str, meter_ids: list[str] | None=None, page: int=1, page_size: int=10) -> list[dict]:
    if page < 1 or page_size < 1:
        raise ValueError('invalid pagination')
    os.makedirs(output_dir, exist_ok=True)
    base = os.path.abspath(output_dir)
    with zipfile.ZipFile(archive_path) as archive:
        for member in archive.infolist():
            target = os.path.abspath(os.path.join(base, member.filename))
            if os.path.commonpath([base, target]) != base:
                raise ValueError('invalid archive member')
            if member.is_dir():
                os.makedirs(target, exist_ok=True)
            else:
                os.makedirs(os.path.dirname(target), exist_ok=True)
                with archive.open(member) as source, open(target, 'wb') as dest:
                    dest.write(source.read())
    wanted = None if meter_ids is None else set(meter_ids)
    grouped = {}
    for root, _, names in os.walk(output_dir):
        for name in names:
            if not name.endswith('.csv'):
                continue
            with open(os.path.join(root, name), newline='', encoding='utf-8') as handle:
                reader = csv.DictReader(handle)
                required = {'meter_id', 'timestamp', 'kwh'}
                if not reader.fieldnames or not required.issubset(reader.fieldnames):
                    raise ValueError('missing column')
                for row in reader:
                    if not row.get('meter_id') or not row.get('timestamp') or (not row.get('kwh')):
                        raise ValueError('missing field')
                    meter = row['meter_id']
                    if wanted is not None and meter not in wanted:
                        continue
                    try:
                        timestamp = datetime.datetime.fromisoformat(row['timestamp'])
                        value = float(row['kwh'])
                    except (TypeError, ValueError):
                        raise ValueError('invalid reading')
                    item = grouped.setdefault(meter, {'values': [], 'latest': (timestamp, row['timestamp'])})
                    item['values'].append(value)
                    if timestamp > item['latest'][0]:
                        item['latest'] = (timestamp, row['timestamp'])
    result = []
    for meter, item in grouped.items():
        total = sum(item['values'])
        result.append({'meter_id': meter, 'reading_count': len(item['values']), 'total_kwh': round(total, 2), 'average_kwh': round(total / len(item['values']), 2), 'latest_timestamp': item['latest'][1]})
    result.sort(key=lambda x: (-x['total_kwh'], x['meter_id']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

