import csv
import io
from datetime import datetime
_STATUSES = {'pending', 'approved', 'rejected'}

def _time(value):
    try:
        return datetime.fromisoformat(value.replace('Z', '+00:00'))
    except (AttributeError, ValueError):
        raise ValueError('invalid timestamp')

def parse_registration_batch(text: str) -> list[dict]:
    if not text:
        raise ValueError('empty input')
    try:
        rows = list(csv.reader(io.StringIO(text), strict=True))
    except csv.Error as exc:
        raise ValueError('malformed csv') from exc
    while rows and (not any((x.strip() for x in rows[-1]))):
        rows.pop()
    if not rows or rows[0] != ['voter_id', 'precinct', 'status', 'submitted_at']:
        raise ValueError('bad header')
    result, seen = ([], set())
    for row in rows[1:]:
        if not any((x.strip() for x in row)):
            continue
        if len(row) != 4:
            raise ValueError('bad row')
        voter, precinct, status, submitted = row
        voter, precinct = (voter.strip(), precinct.strip())
        if not voter or not precinct or status not in _STATUSES or (voter in seen):
            raise ValueError('invalid row')
        _time(submitted)
        seen.add(voter)
        result.append({'voter_id': voter, 'precinct': precinct, 'status': status, 'submitted_at': submitted})
    if not result:
        raise ValueError('no data')
    return result

def summarize_registrations(records: list[dict]) -> list[dict]:
    groups = {}
    for record in records:
        if any((k not in record for k in ('voter_id', 'tenant_id', 'owner_id', 'precinct', 'status', 'updated_at'))) or record['status'] not in _STATUSES:
            raise ValueError('invalid record')
        _time(record['updated_at'])
        group = groups.setdefault(record['precinct'], {'precinct': record['precinct'], 'total': 0, 'pending': 0, 'approved': 0, 'rejected': 0})
        group['total'] += 1
        group[record['status']] += 1
    return sorted(groups.values(), key=lambda x: (-x['total'], x['precinct']))

def apply_registration_updates(requester: dict, records: list[dict], changes: list[dict]) -> list[dict]:
    by_id = {}
    for record in records:
        if any((k not in record for k in ('voter_id', 'tenant_id', 'owner_id', 'precinct', 'status', 'updated_at'))) or record['status'] not in _STATUSES or record['voter_id'] in by_id:
            raise ValueError('invalid record')
        _time(record['updated_at'])
        by_id[record['voter_id']] = record
    checked = {}
    for change in changes:
        if set(change) != {'voter_id', 'status', 'updated_at'} or change['voter_id'] in checked or change['voter_id'] not in by_id or (change['status'] not in _STATUSES):
            raise ValueError('invalid change')
        new_time = _time(change['updated_at'])
        if new_time < _time(by_id[change['voter_id']]['updated_at']):
            raise ValueError('old timestamp')
        record = by_id[change['voter_id']]
        if not (requester.get('user_id') == record['owner_id'] or ('registrar_admin' in requester.get('roles', []) and requester.get('tenant_id') == record['tenant_id'])):
            raise PermissionError('not allowed')
        checked[change['voter_id']] = change
    result = [dict(record) for record in records]
    for record in result:
        if record['voter_id'] in checked:
            change = checked[record['voter_id']]
            record['status'] = change['status']
            record['updated_at'] = change['updated_at']
    return result

