    trip = {'id': 't1', 'employee_id': 'u1', 'tenant_id': 'acme', 'destination': 'Paris', 'cost': 1200, 'status': 'pending'}
    result = authorize_trip(requester, trip, 'approve')
    assert result == {'id': 't1', 'employee_id': 'u1', 'tenant_id': 'acme', 'destination': 'Paris', 'cost': 1200, 'status': 'approved', 'decided_by': 'u1'}

def test_travel_admin_can_reject_pending_trip():
