    trip = {'id': 't2', 'employee_id': 'u9', 'tenant_id': 'acme', 'destination': 'Tokyo', 'cost': 2500, 'status': 'pending'}
    result = authorize_trip(requester, trip, 'reject')
    assert result['status'] == 'rejected'
    assert result['decided_by'] == 'admin7'
