from datetime import datetime, timezone

def _time(value):
    try:
        d = datetime.fromisoformat(value.replace('Z', '+00:00'))
    except Exception as e:
        raise ValueError('invalid timestamp') from e
    if d.tzinfo is None:
        raise ValueError('invalid timestamp')
    return d.astimezone(timezone.utc)

def _fields(line):
    out, cur, escaped = ([], [], False)
    for ch in line:
        if escaped:
            cur.append(ch)
            escaped = False
        elif ch == '\\':
            escaped = True
        elif ch == '|':
            out.append(''.join(cur))
            cur = []
        else:
            cur.append(ch)
    if escaped:
        raise ValueError('bad escape')
    out.append(''.join(cur))
    return out

def parse_bookings(text: str) -> list[dict]:
    result = []
    for line in text.splitlines():
        if not line.strip():
            continue
        f = _fields(line)
        if len(f) != 6 or _time(f[3]) <= _time(f[2]):
            raise ValueError('invalid booking')
        result.append(dict(zip(('id', 'room_id', 'start', 'end', 'owner_id', 'title'), f)))
    return result

def _interval(start, end):
    a, b = (_time(start), _time(end))
    if b <= a:
        raise ValueError('invalid interval')
    return (a, b)

def available_rooms(rooms, bookings, start, end):
    a, b = _interval(start, end)
    used = {x['room_id'] for x in bookings if x['room_id'] in rooms and _time(x['start']) < b and (a < _time(x['end']))}
    return sorted((r for r in rooms if r not in used), key=lambda r: (-rooms[r]['capacity'], r))

def create_booking(rooms, bookings, requester, room_id, start, end, title):
    if room_id not in rooms:
        raise KeyError(room_id)
    if not title:
        raise ValueError('empty title')
    a, b = _interval(start, end)
    for x in bookings:
        if x['room_id'] == room_id and _time(x['start']) < b and (a < _time(x['end'])):
            raise ValueError('overlap')
    used = {x['id'] for x in bookings}
    n = 1
    while 'b' + str(n) in used:
        n += 1
    item = {'id': 'b' + str(n), 'room_id': room_id, 'start': start, 'end': end, 'owner_id': requester['id'], 'title': title}
    bookings.append(item)
    return item

def cancel_booking(bookings, requester, booking_id):
    for i, item in enumerate(bookings):
        if item['id'] == booking_id:
            if item['owner_id'] != requester['id'] and 'librarian' not in requester.get('roles', []):
                raise PermissionError('not permitted')
            del bookings[i]
            return None
    raise KeyError(booking_id)

