import datetime
import hashlib
import hmac

def calculate_balances(events: list[dict]) -> dict[str, int]:
    if not isinstance(events, list):
        raise TypeError('events must be a list')
    seen = set()
    totals = {}
    for event in events:
        if not isinstance(event, dict):
            raise TypeError('each event must be a dictionary')
        for key in ('id', 'member', 'kind', 'amount', 'at'):
            if key not in event:
                raise ValueError('missing event field')
        ident, member, kind, amount, stamp = (event['id'], event['member'], event['kind'], event['amount'], event['at'])
        if not isinstance(ident, str) or not ident or (not isinstance(member, str)) or (not member):
            raise ValueError('invalid event identity')
        if kind not in ('purchase', 'return'):
            raise ValueError('invalid event kind')
        if isinstance(amount, bool) or not isinstance(amount, int) or amount < 0:
            raise ValueError('invalid amount')
        if not isinstance(stamp, str) or not stamp:
            raise ValueError('invalid timestamp')
        try:
            datetime.datetime.fromisoformat(stamp)
        except ValueError:
            raise ValueError('invalid timestamp')
        if ident in seen:
            continue
        seen.add(ident)
        points = amount // 100
        totals[member] = totals.get(member, 0) + (points if kind == 'purchase' else -points)
    return {key: totals[key] for key in sorted(totals)}

def make_loyalty_receipt(member_id: str, balance: int, config: dict[str, str]) -> str:
    if not isinstance(config, dict):
        raise TypeError('config must be a dictionary')
    if not isinstance(member_id, str) or not member_id:
        raise ValueError('invalid member')
    if isinstance(balance, bool) or not isinstance(balance, int):
        raise ValueError('invalid balance')
    if 'receipt_key' not in config or config['receipt_key'] is None or str(config['receipt_key']) == '':
        raise ValueError('missing receipt key')
    payload = f'{member_id}|{balance}'
    digest = hmac.new(str(config['receipt_key']).encode(), payload.encode(), hashlib.sha256).hexdigest()
    return f'{payload}|{digest}'

