def parse_adoption_records(text: str) -> list[dict]:
    try:
        rows = list(csv.reader(io.StringIO(text, newline='')))
    except csv.Error as exc:
        raise ValueError('invalid CSV') from exc
    expected = ['animal_id', 'species', 'age_months', 'adopted_on', 'fee', 'outcome']
    if not rows or rows[0] != expected:
        raise ValueError('invalid header')
    result = []
    seen = set()
    for row in rows[1:]:
        if len(row) != len(expected):
            raise ValueError('invalid row')
        animal_id, species, age_text, date_text, fee_text, outcome = row
        if not animal_id or animal_id in seen or (not species):
            raise ValueError('invalid identity')
        try:
            age = int(age_text)
            adopted_on = date.fromisoformat(date_text)
            fee = Decimal(fee_text)
        except (ValueError, InvalidOperation):
            raise ValueError('invalid value')
        if age < 0 or fee < 0 or fee.as_tuple().exponent < -2 or (outcome not in ('adopted', 'returned')):
            raise ValueError('invalid value')
        seen.add(animal_id)
        result.append({'animal_id': animal_id, 'species': species, 'age_months': age, 'adopted_on': adopted_on, 'fee': fee, 'outcome': outcome})
    return result

def adoption_summary(records: list[dict], species: str | None=None) -> dict[str, dict[str, object]]:
    result = {}
    for record in records:
        if species is not None and record['species'] != species:
            continue
        key = record['adopted_on'].strftime('%Y-%m')
        if key not in result:
            result[key] = {'adopted': 0, 'returned': 0, 'fees': Decimal('0')}
        result[key][record['outcome']] += 1
        if record['outcome'] == 'adopted':
            result[key]['fees'] += record['fee']
    return dict(sorted(result.items()))

def extract_documents(base_dir: str, archive_path: str, animal_id: str) -> list[str]:
    base = Path(base_dir).resolve()
    extracted = []
    prefix = animal_id + '/'
    with zipfile.ZipFile(archive_path) as archive:
        for member in archive.infolist():
            if not member.filename.startswith(prefix):
                continue
            target = (base / member.filename).resolve()
            try:
                target.relative_to(base)
            except ValueError:
                raise ValueError('document path is outside base directory')
            if member.is_dir():
                target.mkdir(parents=True, exist_ok=True)
                continue
            target.parent.mkdir(parents=True, exist_ok=True)
            with archive.open(member) as source, open(target, 'wb') as destination:
                destination.write(source.read())
            extracted.append(str(Path(member.filename)))
    return sorted(extracted)

