import csv
import io
import re
from datetime import date
_HEADERS = ['donation_id', 'donor_id', 'tenant_id', 'donation_date', 'amount_cents', 'campaign']

def _date(value):
    if not isinstance(value, str) or not re.fullmatch('\\d{4}-\\d{2}-\\d{2}', value):
        raise ValueError('invalid date')
    try:
        return date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid date')

def parse_donation_feed(text: str) -> list[dict]:
    try:
        rows = csv.reader(io.StringIO(text), skipinitialspace=True, strict=True)
        header = next(rows)
    except (StopIteration, csv.Error):
        raise ValueError('invalid feed')
    if [x.strip() for x in header] != _HEADERS:
        raise ValueError('invalid header')
    result = []
    try:
        for row in rows:
            if not row or all((not x.strip() for x in row)):
                continue
            if len(row) != 6:
                raise ValueError('invalid row')
            values = [x.strip() for x in row]
            if any((not values[i] for i in (0, 1, 2, 3, 5))):
                raise ValueError('missing value')
            _date(values[3])
            if not re.fullmatch('\\d+', values[4]):
                raise ValueError('invalid amount')
            result.append(dict(zip(_HEADERS, values[:4] + [int(values[4]), values[5]])))
    except csv.Error:
        raise ValueError('invalid feed')
    return result

def summarize_donations(donations: list[dict], requester: dict, start_date: str, end_date: str) -> dict:
    first = _date(start_date)
    last = _date(end_date)
    if first > last:
        raise ValueError('invalid range')
    staff = 'finance' in requester.get('roles', []) or 'admin' in requester.get('roles', [])
    total = 0
    count = 0
    months = {}
    campaigns = {}
    for item in donations:
        if item['tenant_id'] != requester['tenant_id']:
            continue
        if not staff and item['donor_id'] != requester['id']:
            continue
        current = _date(item['donation_date'])
        if first <= current <= last:
            amount = item['amount_cents']
            total += amount
            count += 1
            months[item['donation_date'][:7]] = months.get(item['donation_date'][:7], 0) + amount
            campaigns[item['campaign']] = campaigns.get(item['campaign'], 0) + amount
    return {'total_cents': total, 'donation_count': count, 'by_month': dict(sorted(months.items())), 'by_campaign': dict(sorted(campaigns.items()))}

