import base64
import hashlib
import hmac
import math
import os
from collections import defaultdict

def hash_receipt_pin(pin: str) -> str:
    if not isinstance(pin, str):
        raise TypeError('pin must be a string')
    if not pin:
        raise ValueError('pin must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return base64.b64encode(salt).decode() + '$' + base64.b64encode(digest).decode()

def verify_receipt_pin(stored: str, pin: str) -> bool:
    if not isinstance(stored, str) or not isinstance(pin, str):
        return False
    try:
        salt_text, digest_text = stored.split('$', 1)
        salt = base64.b64decode(salt_text.encode(), validate=True)
        expected = base64.b64decode(digest_text.encode(), validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except Exception:
        return False

def summarize_receipts(receipts: list[dict], category: str | None=None, page: int=1, page_size: int=10) -> dict:
    if not isinstance(category, (str, type(None))) or not isinstance(page, int) or isinstance(page, bool) or (page < 1) or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid options')
    filtered = []
    for receipt in receipts:
        if not isinstance(receipt, dict) or not all((k in receipt for k in ('merchant', 'amount', 'category', 'date'))):
            raise ValueError('invalid receipt')
