        if not isinstance(merchant, str) or not merchant or (not isinstance(kind, str)) or (not kind) or (not isinstance(date, str)) or (not date) or isinstance(amount, bool) or (not isinstance(amount, (int, float))) or (not math.isfinite(amount)) or (amount < 0):
            raise ValueError('invalid receipt')
        if category is None or kind == category:
            filtered.append(receipt)
    ordered = sorted(enumerate(filtered), key=lambda x: (-int(x[1]['date'].replace('-', '')), x[1]['merchant'], x[0]))
    selected = [r for _, r in ordered][(page - 1) * page_size:page * page_size]
    groups = defaultdict(float)
    for r in filtered:
