                        return False
                    left = right
                return True
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
                return {'min': min, 'max': max, 'round': round}[node.func.id](*[visit(x) for x in node.args])
            raise ValueError()
        return visit(tree)
    except Exception as exc:
        raise ValueError() from exc

def parse_ocr(text: str) -> list[dict]:
    result = []
    for line in text.splitlines():
        if not line.strip():
            continue
        fields = []
        current = []
        escaped = False
        for char in line:
            if escaped:
                if char not in 'tnr\\':
                    raise ValueError()
                current.append({'t': '\t', 'n': '\n', 'r': '\r', '\\': '\\'}[char])
                escaped = False
