                current.append({'t': '\t', 'n': '\n', 'r': '\r', '\\': '\\'}[char])
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == '\t':
                fields.append(''.join(current))
                current = []
            else:
                current.append(char)
        if escaped:
            raise ValueError()
        fields.append(''.join(current))
        if len(fields) != 4:
            raise ValueError()
        try:
            page, block, confidence = (int(fields[0]), int(fields[1]), float(fields[2]))
        except Exception as exc:
            raise ValueError() from exc
        if page < 0 or block < 0 or (not 0 <= confidence <= 1):
            raise ValueError()
        value = fields[3]
        result.append({'page': page, 'block': block, 'confidence': confidence, 'text': value, 'words': len(value.split()), 'chars': len(value)})
    return result

def select_and_rank(records: list[dict], rule: str, score: str, variables=None) -> list[dict]:
    names = {} if variables is None else dict(variables)
    chosen = []
    for index, record in enumerate(records):
        scope = {k: record[k] for k in ('page', 'block', 'confidence', 'words', 'chars')}
        scope.update(names)
        if _evaluate(rule, scope):
            item = dict(record)
            item['score'] = _evaluate(score, scope)
            chosen.append((item, index))
    chosen.sort(key=lambda p: (-p[0]['score'], p[0]['page'], p[0]['block'], p[1]))
    return [x for x, _ in chosen]

def confidence_windows(records: list[dict], size: int) -> list[dict]:
    if isinstance(size, bool) or not isinstance(size, int) or size <= 0:
        raise ValueError()
    return [{'start_page': c[0]['page'], 'end_page': c[-1]['page'], 'average_confidence': sum((x['confidence'] for x in c)) / len(c), 'total_words': sum((x['words'] for x in c))} for i in range(0, len(records), size) if (c := records[i:i + size])]

