def generate_quality_report(records: list[dict], page: int=1, page_size: int=10) -> dict:
    if not isinstance(records, list) or isinstance(page, bool) or (not isinstance(page, int)) or (page < 1) or isinstance(page_size, bool) or (not isinstance(page_size, int)) or (not 1 <= page_size <= 100):
        raise ValueError('invalid arguments')
    required = ('call_id', 'codec', 'mos', 'jitter_ms', 'packet_loss_pct', 'duration_sec')
    clean = []
    for record in records:
        if not isinstance(record, dict) or any((key not in record for key in required)):
            raise ValueError('invalid record')
        if not isinstance(record['call_id'], str) or not record['call_id'] or (not isinstance(record['codec'], str)) or (not record['codec']):
            raise ValueError('invalid record')
        numeric = (record['mos'], record['jitter_ms'], record['packet_loss_pct'], record['duration_sec'])
        if any((isinstance(value, bool) or not isinstance(value, Real) or (not math.isfinite(value)) for value in numeric)):
            raise ValueError('invalid record')
        mos, jitter, loss, duration = numeric
        if not 1 <= mos <= 5 or jitter < 0 or (not 0 <= loss <= 100) or (duration <= 0):
            raise ValueError('invalid record')
