    alphabet = string.ascii_letters + string.digits
    token = ''.join((secrets.choice(alphabet) for _ in range(24)))
    total = len(clean)
    groups = {}
    for item in clean:
        groups.setdefault(item['codec'], []).append(item)
    by_codec = []
    for codec in sorted(groups):
        group = groups[codec]
        by_codec.append({'codec': codec, 'calls': len(group), 'average_mos': round(sum((x['mos'] for x in group)) / len(group), 2), 'average_jitter_ms': round(sum((x['jitter_ms'] for x in group)) / len(group), 2), 'average_packet_loss_pct': round(sum((x['packet_loss_pct'] for x in group)) / len(group), 2)})
    ordered = sorted(clean, key=lambda x: (-x['mos'], x['call_id']))
    start = (page - 1) * page_size
