import os

def write_eligibility_notice(base_dir: str, relative_name: str, notice: str) -> str:
    if relative_name == '':
        raise ValueError('relative_name must not be empty')
    base = os.path.abspath(base_dir)
    target = os.path.abspath(os.path.join(base, relative_name))
    try:
        inside = os.path.commonpath((base, target)) == base
    except ValueError:
        inside = False
    if not inside:
        raise ValueError('file location is outside base directory')
    os.makedirs(os.path.dirname(target), exist_ok=True)
    with open(target, 'w', encoding='utf-8') as handle:
        handle.write(notice)
    return target

from lxml import etree

def parse_earthquake_alerts(xml_text: str) -> list[dict[str, object]]:
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode('utf-8'), parser)
        if root.tag != 'alertFeed':
            raise ValueError('invalid root')
        result = []
        for event in root.findall('event'):
            if 'id' not in event.attrib:
                raise ValueError('missing id')
            values = {}
            for name in ('magnitude', 'place', 'latitude', 'longitude', 'depthKm'):
                child = event.find(name)
                if child is None or child.text is None:
                    raise ValueError('missing field')
                values[name] = child.text.strip()
            result.append({'id': event.attrib['id'], 'magnitude': float(values['magnitude']), 'place': values['place'], 'latitude': float(values['latitude']), 'longitude': float(values['longitude']), 'depth_km': float(values['depthKm'])})
        return result
    except (etree.XMLSyntaxError, ValueError):
        raise ValueError('invalid earthquake alert document')

