import secrets

def _split_escaped(text, separator):
    parts = []
    current = []
    escaped = False
    for char in text:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == separator:
            parts.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape')
    parts.append(''.join(current))
    return parts

def parse_case(text: str) -> dict:
    if not isinstance(text, str) or not text:
        raise ValueError('invalid record')
    fields = {}
    for item in _split_escaped(text, ';'):
        pair = _split_escaped(item, '=')
        if len(pair) != 2:
            raise ValueError('invalid field')
        key, value = (pair[0].strip(), pair[1])
        if key not in {'case', 'income', 'assets', 'members'} or key in fields:
            raise ValueError('invalid field')
        fields[key] = value
    if set(fields) != {'case', 'income', 'assets', 'members'} or not fields['case']:
        raise ValueError('missing field')
    try:
        income = [int(x.strip()) for x in fields['income'].split(',')]
        assets = int(fields['assets'].strip())
    except Exception as exc:
        raise ValueError('invalid number') from exc
    if len(income) != 6 or any((x < 0 for x in income)) or assets < 0:
        raise ValueError('invalid number')
    members = []
    for item in fields['members'].split(','):
        pair = item.split(':')
        if len(pair) != 2 or not pair[0].strip():
            raise ValueError('invalid member')
        try:
            age = int(pair[1].strip())
        except Exception as exc:
            raise ValueError('invalid member') from exc
        if not 0 <= age <= 120:
            raise ValueError('invalid age')
        members.append({'name': pair[0].strip(), 'age': age})
    if not members:
        raise ValueError('no members')
    return {'case': fields['case'], 'income': income, 'assets': assets, 'members': members}

def screen_case(case: dict, monthly_limit: int=1800, asset_limit: int=5000) -> dict:
    average = round(sum(case['income'][-3:]) / 3, 2)
    size = len(case['members'])
    children = sum((member['age'] < 18 for member in case['members']))
    benefits = []
    if average <= 1400 + 250 * size and case['assets'] <= asset_limit:
        benefits.append('food')
    if average <= monthly_limit + 400 * children:
        benefits.append('medical')
    if average <= 2200 + 300 * size:
        benefits.append('housing')
    return {'case': case['case'], 'average_income': average, 'household_size': size, 'children': children, 'benefits': benefits}

def issue_invite(text: str, registry: set[str]) -> dict:
    case = parse_case(text)
    screened = screen_case(case)
    if not screened['benefits']:
        raise ValueError('no benefits')
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
