def occupancy_report(requester: dict, stays: list[dict], start: str, end: str, page: int=1, page_size: int=20) -> dict:

    def parse(value):
        try:
            return date.fromisoformat(value)
        except (TypeError, ValueError):
            raise ValueError('invalid date')
    first = parse(start)
    last = parse(end)
    if first >= last:
        raise ValueError('invalid range')
    if type(page) is not int or type(page_size) is not int or page < 1 or (page_size < 1):
        raise ValueError('invalid pagination')
    if not isinstance(requester, dict):
        raise ValueError('invalid requester')
    try:
        requester_id = requester['id']
        tenant_id = requester['tenant_id']
        role = requester['role']
    except (KeyError, TypeError):
        raise ValueError('invalid requester')
    grouped = {}
    for stay in stays:
        try:
            check_in = parse(stay['check_in'])
            check_out = parse(stay['check_out'])
            status = stay['status']
            room = stay['room']
            allowed = stay['tenant_id'] == tenant_id and (role == 'manager' or stay['owner_id'] == requester_id)
        except (KeyError, TypeError):
            raise ValueError('invalid stay')
        if not allowed or status == 'cancelled':
            continue
        left = max(first, check_in)
        right = min(last, check_out)
        nights = (right - left).days
        if nights <= 0:
            continue
        if room not in grouped:
            grouped[room] = [0, 0]
        grouped[room][0] += nights
        grouped[room][1] += 1
    ordered = sorted(grouped.items(), key=lambda item: (-item[1][0], item[0]))
    offset = (page - 1) * page_size
    rooms = [{'room': room, 'nights': values[0], 'stays': values[1]} for room, values in ordered[offset:offset + page_size]]
    return {'total_nights': sum((values[0] for _, values in ordered)), 'rooms': rooms, 'page': page, 'page_size': page_size, 'total_rooms': len(ordered)}

