import math
import re
import subprocess

def parse_billing_record(line: str) -> tuple[str, str, int]:
    value = line.strip()
    fields = value.split('|')
    if len(fields) != 3:
        raise ValueError('malformed record')
    tenant, month, kwh_text = fields
    if not tenant or re.fullmatch('\\d{4}-(0[1-9]|1[0-2])', month) is None:
        raise ValueError('malformed record')
    if re.fullmatch('\\d+', kwh_text) is None:
        raise ValueError('malformed record')
    return (tenant, month, int(kwh_text))

def calculate_tenant_billing(files: list[str], rates: dict[str, float], month: str) -> list[dict[str, object]]:
    if re.fullmatch('\\d{4}-(0[1-9]|1[0-2])', month) is None:
        raise ValueError('invalid month')
    base = rates['base']
    included = rates['included_kwh']
    overage = rates['overage_rate']
    if isinstance(included, bool) or not isinstance(included, int) or included < 0:
        raise ValueError('invalid included kwh')
    if any((not isinstance(x, (int, float)) or isinstance(x, bool) or (not math.isfinite(x)) or (x < 0) for x in (base, overage))):
        raise ValueError('invalid rate')
    command = ['sort', '-t', '|', '-k1,1'] + list(files)
    completed = subprocess.run(command, capture_output=True, text=True, check=True)
    totals = {}
    for line in completed.stdout.splitlines():
        tenant, record_month, kwh = parse_billing_record(line)
        if record_month == month:
            totals[tenant] = totals.get(tenant, 0) + kwh
    return [{'tenant': tenant, 'kwh': total, 'charge': round(base + max(0, total - included) * overage, 2)} for tenant, total in sorted(totals.items())]

