    if not isinstance(patch, dict):
        raise TypeError('patch must be a dictionary')
    if not isinstance(updated_at, int) or isinstance(updated_at, bool) or updated_at < 0:
        raise ValueError('updated_at must be a non-negative integer')
    allowed = {'status', 'metadata'}
    if any((key not in allowed for key in patch)):
        raise ValueError('unsupported patch field')
    if 'status' in patch and patch['status'] not in {'online', 'offline', 'maintenance'}:
        raise ValueError('invalid status')
    if 'metadata' in patch and (not isinstance(patch['metadata'], dict)):
        raise TypeError('metadata must be a dictionary')
    asset = next((item for item in assets if item.get('id') == asset_id), None)
    if asset is None:
        raise KeyError(asset_id)
    if not (requester.get('tenant_id') == asset.get('tenant_id') and (requester.get('id') == asset.get('owner_id') or 'twin_admin' in requester.get('roles', []))):
        raise PermissionError('requester cannot update this asset')
    result = dict(asset)
    result['metadata'] = dict(asset.get('metadata', {}))
    if 'status' in patch:
        result['status'] = patch['status']
    if 'metadata' in patch:
        result['metadata'] = dict(patch['metadata'])
    result['updated_at'] = updated_at
    return result

