import os
import tempfile

def write_file(contents):
    handle = tempfile.NamedTemporaryFile(mode='w', delete=False)
    try:
        handle.write(contents)
        return handle.name
    finally:
        handle.close()

def test_empty_file_returns_empty_list():
    path = write_file('')
    try:
        assert calculate_commissions(path, 0.1) == []
    finally:
        os.unlink(path)

def test_blank_lines_are_ignored():
    path = write_file('\n  \nAlice,100\n\n')
    try:
        assert calculate_commissions(path, 0.2) == [('Alice', 20.0)]
    finally:
        os.unlink(path)

def test_records_are_grouped_and_sorted():
    path = write_file('Zoe,10\nAlice,100\nZoe,20.50\nBob,5\nAlice,25.25\n')
    try:
        assert calculate_commissions(path, 0.1) == [('Alice', 12.53), ('Bob', 0.5), ('Zoe', 3.05)]
    finally:
        os.unlink(path)

def test_zero_rate_produces_zero_commissions():
    path = write_file('Alice,12.34\nBob,999.99\n')
    try:
        assert calculate_commissions(path, 0.0) == [('Alice', 0.0), ('Bob', 0.0)]
    finally:
        os.unlink(path)

