def calculate_commissions(file_path: str, commission_rate: float) -> list[tuple[str, float]]:
    if commission_rate < 0 or commission_rate > 1:
        raise ValueError('commission rate must be between 0 and 1')
    result = subprocess.run(['sort', '-t,', '-k1,1', file_path], capture_output=True, text=True, check=True)
    totals = {}
    for line in result.stdout.splitlines():
        if not line.strip():
            continue
        if line.count(',') != 1:
            raise ValueError('invalid record')
        name, value = line.split(',')
        if not name:
            raise ValueError('invalid salesperson')
        try:
            amount = float(value)
        except ValueError:
            raise ValueError('invalid amount')
        if amount < 0:
            raise ValueError('invalid amount')
        totals[name] = totals.get(name, 0.0) + amount
    return [(name, round(totals[name] * commission_rate, 2)) for name in sorted(totals)]

