        totals[department] = totals.get(department, 0) + count
    rows = []
    for (department, category), count in grouped.items():
        total = totals[department]
        share = round(count * 100 / total, 2) if total else 0.0
        rows.append({'department': department, 'category': category, 'count': count, 'share': share})
    rows.sort(key=lambda row: (row['department'], -row['count'], row['category']))
    start = (page - 1) * page_size
    return rows[start:start + page_size]

