import ast
import operator

def _value(node, names):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in names:
            raise NameError(node.id)
        return names[node.id]
    if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub, ast.Not):
        value = _value(node.operand, names)
        return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
    if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
        values = [_value(x, names) for x in node.values]
        return all(values) if isinstance(node.op, ast.And) else any(values)
    if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
        left, right = (_value(node.left, names), _value(node.right, names))
        return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
    if isinstance(node, ast.Compare):
        left = _value(node.left, names)
        for op, item in zip(node.ops, node.comparators):
            right = _value(item, names)
            if not {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}[type(op)](left, right):
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')):
        args = [_value(x, names) for x in node.args]
        if node.keywords:
            raise SyntaxError('keywords')
        if node.func.id == 'round':
            if len(args) not in (1, 2, 3):
                raise TypeError('round')
            return round(*args)
        if len(args) < 2:
            raise TypeError(node.func.id)
        return min(args) if node.func.id == 'min' else max(args)
    raise SyntaxError('unsupported expression')

def _rule(text, names):
    tree = ast.parse(text, mode='eval')
    result = _value(tree.body, names)
    if type(result) is not bool:
        raise TypeError('rule must return bool')
    return result

def analyze_damages(records: list[dict], rule: str) -> list[dict]:
    groups = {}
    for record in records:
        for key in ('claim_id', 'vehicle', 'status', 'estimated_cost', 'days_out', 'severity', 'deductible'):
            record[key]
        if not isinstance(record['claim_id'], str) or not isinstance(record['vehicle'], str):
            raise TypeError('text fields')
        if record['status'] != 'open':
            continue
        names = {'cost': record['estimated_cost'], 'days': record['days_out'], 'severity': record['severity'], 'deductible': record['deductible']}
        if _rule(rule, names):
            groups.setdefault(record['vehicle'], []).append(record)
    result = []
    for vehicle, items in groups.items():
        result.append({'vehicle': vehicle, 'claims': sorted((x['claim_id'] for x in items)), 'total_cost': sum((x['estimated_cost'] for x in items)), 'average_severity': round(sum((x['severity'] for x in items)) / len(items), 2), 'count': len(items)})
    return sorted(result, key=lambda x: (-x['total_cost'], x['vehicle']))

