import secrets

def create_herd_invite_code(farm_id: str, length: int=10) -> str:
    if not isinstance(farm_id, str):
        raise TypeError('farm_id must be a string')
    if not isinstance(length, int) or isinstance(length, bool):
        raise TypeError('length must be an integer')
    if not 6 <= length <= 32:
        raise ValueError('length must be between 6 and 32')
