_HEADER = ['applicant', 'property', 'year', 'measure', 'kwh_saved', 'cost_cents']
_OUT_HEADER = ['applicant', 'property', 'total_kwh', 'total_cost_cents', 'rebate_cents', 'measures']

def summarize_rebates(csv_text: str, year: int) -> list[dict]:
    if not isinstance(year, int) or isinstance(year, bool) or year <= 0:
        raise ValueError('invalid year')
    if csv_text == '':
        return []
    rows = csv.reader(io.StringIO(csv_text))
    try:
        header = next(rows)
    except StopIteration:
        return []
    if header != _HEADER:
        raise ValueError('invalid header')
    groups = {}
    for row in rows:
        if len(row) != 6:
            raise ValueError('invalid row')
        applicant, prop, row_year, measure, kwh, cost = [x.strip() for x in row]
        if not applicant or not prop or (not measure):
            raise ValueError('empty field')
        try:
            ry, saved, cents = (int(row_year), int(kwh), int(cost))
        except ValueError:
            raise ValueError('invalid number')
        if ry != year or saved <= 0 or cents < 0:
            raise ValueError('invalid row')
        key = (prop, applicant)
        if key not in groups:
            groups[key] = {'applicant': applicant, 'property': prop, 'total_kwh': 0, 'total_cost_cents': 0, 'measures': []}
        item = groups[key]
        item['total_kwh'] += saved
        item['total_cost_cents'] += cents
        if measure not in item['measures']:
            item['measures'].append(measure)
    result = []
    for item in groups.values():
        item = dict(item)
        item['rebate_cents'] = min(item['total_cost_cents'], item['total_kwh'] * 12) if item['total_kwh'] >= 100 else 0
        result.append(item)
    return sorted(result, key=lambda x: (x['property'], x['applicant']))

def export_summary(records: list[dict], destination: str) -> int:
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=directory)
    os.close(fd)
    try:
        with open(temporary, 'w', newline='', encoding='utf-8') as f:
            writer = csv.writer(f)
            writer.writerow(_OUT_HEADER)
            for item in records:
                writer.writerow([item['applicant'], item['property'], item['total_kwh'], item['total_cost_cents'], item['rebate_cents'], '|'.join(item['measures'])])
        os.replace(temporary, destination)
        return len(records)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise

def load_and_export(csv_text: str, year: int, destination: str) -> int:
    return export_summary(summarize_rebates(csv_text, year), destination)

