        raise ValueError('unexpected root')
    result = []
    for ride in root.findall('ride'):
        values = {}
        for key in ('id', 'status'):
            value = ride.get(key)
            if value is None or not value.strip():
                raise ValueError('missing ride value')
            values[key] = value.strip()
