import json
from datetime import date, datetime, timezone

def summarize_webhook(payload: str, signature: str, secret: str, day: str) -> dict:
    try:
        if not isinstance(payload, str) or not isinstance(signature, str) or (not isinstance(secret, str)):
            raise ValueError
        if not signature.startswith('sha256=') or len(signature) != 71:
            raise ValueError
        supplied = signature[7:].encode('ascii')
        if hmac.new(secret.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest().encode('ascii') != supplied:
            raise ValueError
    except (ValueError, UnicodeError):
        raise ValueError('invalid signature')
    try:
        requested = date.fromisoformat(day)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    try:
        data = json.loads(payload)
        if not isinstance(data, dict) or not isinstance(data.get('posts'), list):
            raise ValueError
        groups = {}
        for item in data['posts']:
            if not isinstance(item, dict) or any((not isinstance(item.get(k), str) for k in ('id', 'platform', 'scheduled_at', 'status', 'text'))):
                raise ValueError
            if item['status'] != 'scheduled':
                continue
            stamp = datetime.fromisoformat(item['scheduled_at'].replace('Z', '+00:00'))
            if stamp.tzinfo is None:
                raise ValueError
            utc_stamp = stamp.astimezone(timezone.utc)
            if utc_stamp.date() != requested:
                continue
            groups.setdefault(item['platform'], []).append((utc_stamp, item['id'], item['text']))
    except (ValueError, TypeError, json.JSONDecodeError, OverflowError):
        raise ValueError('invalid payload')
    result = {'date': day, 'platforms': []}
    for platform in sorted(groups):
        entries = sorted(groups[platform], key=lambda x: (x[0], x[1]))
        result['platforms'].append({'platform': platform, 'count': len(entries), 'characters': sum((len(x[2]) for x in entries)), 'post_ids': [x[1] for x in entries]})
    return result

