from lxml import etree

def parse_attendance_xml(xml_text: str) -> list[dict[str, str]]:
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode('utf-8'), parser=parser)
    except (etree.XMLSyntaxError, UnicodeError) as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'attendance':
        raise ValueError('invalid root')
    records = []
    seen = set()
    for child in root:
        if not isinstance(child.tag, str):
            continue
        if child.tag != 'student':
            raise ValueError('unexpected element')
        values = {key: (child.get(key) or '').strip() for key in ('id', 'name', 'date', 'status')}
        if any((not value for value in values.values())):
            raise ValueError('missing attribute')
        if values['status'] not in {'present', 'absent', 'late', 'excused'}:
            raise ValueError('invalid status')
        try:
            date.fromisoformat(values['date'])
        except ValueError as exc:
            raise ValueError('invalid date') from exc
        if values['id'] in seen:
            raise ValueError('duplicate id')
        seen.add(values['id'])
        records.append(values)
    return records

