import secrets

def generate_maintenance_access_code(work_order_id: str, length: int=8) -> str:
    if not isinstance(work_order_id, str):
        raise TypeError('work_order_id must be a string')
    normalized = work_order_id.strip().upper()
    if not normalized or any((not ('A' <= character <= 'Z' or '0' <= character <= '9' or character == '-') for character in normalized)):
        raise ValueError('invalid work_order_id')
    if type(length) is not int or not 6 <= length <= 32:
        raise ValueError('length must be between 6 and 32')
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    code = ''.join((secrets.choice(alphabet) for _ in range(length)))
    return f'{normalized}:{code}'

