import sqlite3

def find_resolutions(conn: sqlite3.Connection, phrase: str='', status: str | None=None, sort: str='adopted_year', descending: bool=False, limit: int=20) -> list[dict]:
    if sort not in {'adopted_year', 'title', 'id'}:
        raise ValueError('invalid sort')
    if isinstance(limit, bool) or not isinstance(limit, int) or (not 0 <= limit <= 100):
        raise ValueError('invalid limit')
    direction = 'DESC' if descending else 'ASC'
    sql = "SELECT r.id, r.title, r.adopted_year, r.status,\n        COALESCE(SUM(CASE WHEN v.choice='yes' THEN 1 ELSE 0 END),0),\n        COALESCE(SUM(CASE WHEN v.choice='no' THEN 1 ELSE 0 END),0),\n        COALESCE(SUM(CASE WHEN v.choice='abstain' THEN 1 ELSE 0 END),0)\n        FROM resolutions r LEFT JOIN votes v ON v.resolution_id=r.id\n        WHERE r.title LIKE ? COLLATE NOCASE"
    args = ['%' + phrase + '%']
    if status is not None:
        sql += ' AND r.status = ?'
        args.append(status)
    sql += f' GROUP BY r.id ORDER BY r.{sort} {direction}, r.id {direction} LIMIT ?'
    args.append(limit)
    out = []
    for rid, title, year, state, yes, no, abstain in conn.execute(sql, args):
        total = yes + no
        out.append({'id': rid, 'title': title, 'adopted_year': year, 'status': state, 'yes': yes, 'no': no, 'abstain': abstain, 'approval': round(100 * yes / total, 2) if total else 0.0})
    return out

def cast_vote(conn: sqlite3.Connection, resolution_id: int, member: str, choice: str) -> dict:
    if choice not in {'yes', 'no', 'abstain'} or not member:
        raise ValueError('invalid vote')
    if conn.execute('SELECT 1 FROM resolutions WHERE id=?', (resolution_id,)).fetchone() is None:
        raise KeyError(resolution_id)
    conn.execute('INSERT INTO votes VALUES (?, ?, ?) ON CONFLICT(resolution_id, member) DO UPDATE SET choice=excluded.choice', (resolution_id, member, choice))
    conn.commit()
    counts = {x: 0 for x in ('yes', 'no', 'abstain')}
    for value, count in conn.execute('SELECT choice, COUNT(*) FROM votes WHERE resolution_id=? GROUP BY choice', (resolution_id,)):
        counts[value] = count
    return {'resolution_id': resolution_id, **counts}

def archive_stats(conn: sqlite3.Connection, year_from: int, year_to: int) -> dict[int, dict[str, int]]:
    if year_from > year_to:
        raise ValueError('invalid range')
    result = {year: {'resolutions': 0, 'yes': 0, 'no': 0, 'abstain': 0} for year in range(year_from, year_to + 1)}
    for year, resolutions, yes, no, abstain in conn.execute("SELECT r.adopted_year, COUNT(DISTINCT r.id),\n        COALESCE(SUM(v.choice='yes'),0), COALESCE(SUM(v.choice='no'),0), COALESCE(SUM(v.choice='abstain'),0)\n        FROM resolutions r LEFT JOIN votes v ON v.resolution_id=r.id\n        WHERE r.adopted_year BETWEEN ? AND ? GROUP BY r.adopted_year", (year_from, year_to)):
        result[year] = {'resolutions': resolutions, 'yes': yes, 'no': no, 'abstain': abstain}
    return result

