import re
from lxml import etree
_amount = re.compile('^-?[0-9]+$')

def parse_payroll_feed(xml: str) -> list[dict]:
    try:
        root = etree.fromstring(xml.encode(), parser=etree.XMLParser(resolve_entities=False, load_dtd=False, no_network=True))
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'payroll':
        raise ValueError('invalid root')
    result = []
    for employee in root:
        if employee.tag != 'employee' or not employee.get('id'):
            raise ValueError('invalid employee')
        eid = employee.get('id')
        for payment in employee:
            if payment.tag != 'payment':
                raise ValueError('invalid payment')
            ds, gs, ps = (payment.get('date'), payment.get('gross'), payment.get('pension'))
            if ds is None or gs is None or ps is None:
                raise ValueError('missing payment attribute')
            if not _amount.fullmatch(gs) or not _amount.fullmatch(ps):
                raise ValueError('invalid amount')
            try:
                day = date.fromisoformat(ds)
            except ValueError as exc:
                raise ValueError('invalid date') from exc
            adjustments = []
            for child in payment:
                if child.tag != 'adjustment' or not child.get('code') or child.get('amount') is None:
                    raise ValueError('invalid adjustment')
                amount = child.get('amount')
                if not _amount.fullmatch(amount):
                    raise ValueError('invalid amount')
                adjustments.append({'code': child.get('code'), 'amount_cents': int(amount)})
            result.append({'employee_id': eid, 'date': day, 'gross_cents': int(gs), 'pension_cents': int(ps), 'adjustments': adjustments})
    return result

def aggregate_payroll(records: list[dict], start: date, end: date) -> dict[str, dict]:
    if start > end:
        raise ValueError('invalid range')
    totals = {}
    for record in records:
        if start <= record['date'] <= end:
            eid = record['employee_id']
            if eid not in totals:
                totals[eid] = {'payment_count': 0, 'gross_cents': 0, 'pension_cents': 0, 'net_cents': 0}
            item = totals[eid]
            adjustment_total = sum((x['amount_cents'] for x in record['adjustments']))
            item['payment_count'] += 1
            item['gross_cents'] += record['gross_cents']
            item['pension_cents'] += record['pension_cents']
            item['net_cents'] += record['gross_cents'] - record['pension_cents'] + adjustment_total
    return dict(sorted(totals.items()))

def rank_employees(summary: dict[str, dict]) -> list[dict]:
    keys = sorted(summary, key=lambda eid: (-summary[eid]['net_cents'], -summary[eid]['gross_cents'], eid))
    return [{'employee_id': eid, **summary[eid]} for eid in keys]

