import hashlib
import hmac
import os
from datetime import datetime

def make_credential(password: str) -> str:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    if not password:
        raise ValueError('password must not be empty')
    rounds = 120000
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, rounds)
    return f'pbkdf2${rounds}${salt.hex()}${digest.hex()}'

def verify_credential(stored: str, password: str) -> bool:
    if not isinstance(stored, str) or not isinstance(password, str):
        return False
    try:
        kind, rounds, salt, digest = stored.split('$')
        if kind != 'pbkdf2':
            return False
        rounds = int(rounds)
        raw = bytes.fromhex(salt)
        expected = bytes.fromhex(digest)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), raw, rounds)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def assign_marina_docks(reservations: list[dict], docks: list[dict]) -> list[tuple[str, str]]:
    if not isinstance(reservations, list) or not isinstance(docks, list):
        raise TypeError('lists required')
    required = {'id', 'boat', 'length', 'arrival', 'departure', 'priority'}
    parsed = []
    for r in reservations:
        if not required.issubset(r):
            raise ValueError('missing reservation field')
        try:
            a = datetime.fromisoformat(r['arrival'])
            d = datetime.fromisoformat(r['departure'])
        except (TypeError, ValueError):
            raise ValueError('invalid datetime')
        if d < a:
            raise ValueError('departure precedes arrival')
        parsed.append((a, -r['priority'], r['id'], d, r))
    for d in docks:
        if not {'id', 'length'}.issubset(d):
            raise ValueError('missing dock field')
    parsed.sort(key=lambda x: x[:3])
    active = {}
    result = []
    for arrival, _, rid, departure, r in parsed:
        for key in list(active):
            if active[key] <= arrival:
                del active[key]
        choices = [d for d in docks if d['id'] not in active and d['length'] >= r['length']]
        if choices:
            dock = min(choices, key=lambda d: (d['length'], d['id']))
            active[dock['id']] = departure
            result.append((rid, dock['id']))
    return result

