        fields = _fields(line)
        if len(fields) != 4 or not fields[0] or (not fields[1]):
            raise ValueError(f'bad line {number}')
        try:
            minutes, seconds = fields[2].split(':')
            if len(minutes) == 0 or len(seconds) != 2:
                raise ValueError
            duration = int(minutes) * 60 + int(seconds)
            priority = int(fields[3])
            if int(minutes) < 0 or not 0 <= int(seconds) <= 59 or (not 0 <= priority <= 9):
                raise ValueError
        except (ValueError, TypeError):
            raise ValueError(f'bad line {number}')
        result.append({'title': fields[0], 'artist': fields[1], 'duration': duration, 'priority': priority})
    return result

