    result.sort(key=lambda x: (0 if 'vip' in x['tags'].split(';') else 1, x['name'].casefold(), x['email']))
    return result

def normalize_subscriptions(records: Iterable[Mapping[str, str]]) -> list[dict[str, str]]:
    return _parse(records)

def subscription_rows(records: Iterable[Mapping[str, str]]) -> list[dict[str, str]]:
    return [{'email': x['email'], 'name': x['name'], 'tags': x['tags'], 'subscribed_at': x['subscribed_at'], 'segment': 'vip' if 'vip' in x['tags'].split(';') else 'standard'} for x in _parse(records)]

def export_subscriptions(records: Iterable[Mapping[str, str]], destination: str) -> int:
    rows = subscription_rows(records)
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(prefix='newsletter-', suffix='.csv', dir=directory)
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.DictWriter(handle, fieldnames=['email', 'name', 'tags', 'subscribed_at', 'segment'])
            writer.writeheader()
