def build_equipment_report(requester: dict, equipment: dict, readings: list[dict], start_date: str, end_date: str) -> dict:
    try:
        first = date.fromisoformat(start_date)
        last = date.fromisoformat(end_date)
    except Exception as exc:
        raise ValueError('invalid date') from exc
    if first > last:
        raise ValueError('invalid range')
    if requester.get('tenant_id') != equipment.get('tenant_id') or (requester.get('id') != equipment.get('owner_id') and requester.get('role') != 'supervisor'):
        raise PermissionError('not permitted')
    groups = {}
    for reading in readings:
        if not all((key in reading for key in ('timestamp', 'engine_hours', 'fuel_liters', 'fault_code'))):
            raise ValueError('incomplete reading')
        try:
            stamp = datetime.strptime(reading['timestamp'], '%Y-%m-%dT%H:%M:%SZ')
            hours = float(reading['engine_hours'])
            fuel = float(reading['fuel_liters'])
        except Exception as exc:
            raise ValueError('invalid reading') from exc
        if hours < 0 or fuel < 0:
            raise ValueError('negative reading')
        day = stamp.date()
        if first <= day <= last:
            groups.setdefault(day, []).append((stamp, hours, fuel, str(reading['fault_code'])))
    days = []
    total_samples = total_hours = total_fuel = 0
    total_faults = {}
    current = first
    while current <= last:
        rows = sorted(groups.get(current, []), key=lambda row: row[0])
        faults = {}
        for _, _, _, code in rows:
            if code:
                faults[code] = faults.get(code, 0) + 1
                total_faults[code] = total_faults.get(code, 0) + 1
        hours = rows[-1][1] - rows[0][1] if len(rows) > 1 else 0
        fuel = sum((row[2] for row in rows))
        hours = round(hours, 2)
        fuel = round(fuel, 2)
        days.append({'date': current.isoformat(), 'samples': len(rows), 'engine_hours': hours, 'fuel_liters': fuel, 'faults': [{'code': code, 'count': faults[code]} for code in sorted(faults)]})
        total_samples += len(rows)
        total_hours += hours
        total_fuel += fuel
        current += timedelta(days=1)
    return {'equipment_id': equipment['id'], 'from': start_date, 'to': end_date, 'days': days, 'totals': {'samples': total_samples, 'engine_hours': round(total_hours, 2), 'fuel_liters': round(total_fuel, 2), 'faults': [{'code': code, 'count': total_faults[code]} for code in sorted(total_faults)]}}

