import io
import os
import tempfile
_FIELDS = ['notice_id', 'brand', 'model', 'category', 'severity', 'units', 'issued', 'status']
_LEVELS = {'low': 0, 'medium': 1, 'high': 2, 'critical': 3}

def _date(value):
    try:
        return datetime.date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def parse_recall_feed(text: str) -> list[dict]:
    try:
        rows = list(csv.reader(io.StringIO(text)))
    except Exception as exc:
        raise ValueError('invalid csv') from exc
    if not rows or [x.strip() for x in rows[0]] != _FIELDS:
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if len(row) != len(_FIELDS):
            raise ValueError('invalid row')
        values = [x.strip() for x in row]
        severity = values[4].lower()
        status = values[7].lower()
        if severity not in _LEVELS or status not in {'open', 'pending', 'closed'}:
            raise ValueError('invalid value')
        if not values[5] or any((ch < '0' or ch > '9' for ch in values[5])):
            raise ValueError('invalid units')
        units = int(values[5])
        _date(values[6])
        result.append(dict(zip(_FIELDS, [values[0], values[1], values[2], values[3], severity, units, values[6], status])))
    return result

def summarize_recalls(records: list[dict], as_of: str) -> list[dict]:
    cutoff = _date(as_of)
    groups = {}
    for record in records:
        issued = _date(record['issued'])
        if issued > cutoff or record['status'] not in {'open', 'pending'}:
            continue
        key = (record['category'], record['brand'])
        item = groups.setdefault(key, {'category': key[0], 'brand': key[1], 'notice_count': 0, 'units': 0, 'latest_issued': record['issued'], 'highest_severity': record['severity']})
        item['notice_count'] += 1
        item['units'] += record['units']
        if record['issued'] > item['latest_issued']:
            item['latest_issued'] = record['issued']
        if _LEVELS[record['severity']] > _LEVELS[item['highest_severity']]:
            item['highest_severity'] = record['severity']
    return sorted(groups.values(), key=lambda x: (-_LEVELS[x['highest_severity']], -x['units'], x['category'], x['brand']))

def export_recall_report(text: str, destination: str, as_of: str) -> int:
    rows = summarize_recalls(parse_recall_feed(text), as_of)
    fd, path = tempfile.mkstemp(dir=os.path.dirname(destination) or '.', text=True)
    try:
        with os.fdopen(fd, 'w', newline='') as handle:
            writer = csv.writer(handle)
            writer.writerow(['category', 'brand', 'notice_count', 'units', 'latest_issued', 'highest_severity'])
            for row in rows:
                writer.writerow([row[x] for x in ['category', 'brand', 'notice_count', 'units', 'latest_issued', 'highest_severity']])
        os.replace(path, destination)
    except Exception:
        try:
            os.unlink(path)
        except FileNotFoundError:
            pass
        raise
    return len(rows)

