import secrets
from datetime import datetime

def generate_invite_code(length: int=10) -> str:
    if type(length) is not int or length < 6 or length > 32:
        raise ValueError('invalid length')
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    return ''.join((secrets.choice(alphabet) for _ in range(length)))

def summarize_energy(readings: list[dict], start: str | None=None, end: str | None=None, page: int=1, page_size: int=10) -> list[dict]:
    if type(page) is not int or page < 1 or type(page_size) is not int or (page_size < 1):
        raise ValueError('invalid pagination')
    try:
        start_dt = datetime.fromisoformat(start) if start is not None else None
        end_dt = datetime.fromisoformat(end) if end is not None else None
    except (TypeError, ValueError):
        raise ValueError('invalid boundary')
    if start_dt is not None and end_dt is not None and (start_dt > end_dt):
        raise ValueError('invalid range')
    groups = {}
    for record in readings:
        try:
            meter = record['meter']
            timestamp = datetime.fromisoformat(record['timestamp'])
            kwh = record['kwh']
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid record')
        if not isinstance(meter, str) or not meter or isinstance(kwh, bool) or (not isinstance(kwh, (int, float))) or (kwh < 0):
            raise ValueError('invalid record')
        if start_dt is not None and timestamp < start_dt or (end_dt is not None and timestamp > end_dt):
            continue
        total, count = groups.get(meter, (0, 0))
        groups[meter] = (total + kwh, count + 1)
    result = [{'meter': meter, 'total_kwh': round(total, 2), 'reading_count': count} for meter, (total, count) in groups.items()]
    result.sort(key=lambda item: (-item['total_kwh'], item['meter']))
    begin = (page - 1) * page_size
    return result[begin:begin + page_size]

