import hmac

def parse_order_lines(text: str) -> list[dict]:
    records = []
    seen = set()
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields = []
        current = []
        escaped = False
        for char in raw:
            if escaped:
                current.append(char)
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == '|':
                fields.append(''.join(current))
                current = []
            else:
                current.append(char)
        if escaped:
            raise ValueError('trailing escape')
        fields.append(''.join(current))
        if len(fields) != 5:
            raise ValueError('invalid record')
        ident, priority, created, channels, total = fields
        if not ident or not created or (not channels):
            raise ValueError('missing field')
        if ident in seen:
            raise ValueError('duplicate id')
        parts = channels.split(',')
        if any((not part for part in parts)):
            raise ValueError('empty channel')
        try:
            priority = int(priority)
            total = int(total)
        except ValueError as exc:
            raise ValueError('invalid number') from exc
        seen.add(ident)
        records.append({'id': ident, 'priority': priority, 'created_at': created, 'channels': parts, 'total': total})
    if not records:
        raise ValueError('no records')
    return records

def route_orders(orders: list[dict], config: dict) -> list[dict]:
    token = config.get('routing_token')
    if not isinstance(token, str):
        raise ValueError('missing routing token')
    capacities = config.get('capacities')
    if not isinstance(capacities, dict):
        raise ValueError('invalid capacities')
    remaining = {}
    for channel, capacity in capacities.items():
        if not isinstance(channel, str) or not isinstance(capacity, int) or isinstance(capacity, bool) or (capacity < 0):
            raise ValueError('invalid capacity')
        remaining[channel] = capacity
    ordered = sorted(orders, key=lambda x: (-x['priority'], x['created_at'], x['id']))
    result = []
    for order in ordered:
        if not isinstance(order.get('id'), str) or not isinstance(order.get('priority'), int) or (not isinstance(order.get('created_at'), str)) or (not isinstance(order.get('channels'), list)):
            raise ValueError('invalid order')
        for channel in order['channels']:
            if channel not in remaining:
                raise ValueError('unknown channel')
        available = [c for c in order['channels'] if remaining[c] > 0]
        if not available:
            continue
        digest = hmac.new(token.encode(), order['id'].encode(), hashlib.sha256).hexdigest()
