def summarize_requests(xml_text: str, status: str | None=None, page: int=1, page_size: int=10) -> dict:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError('invalid paging')
    try:
        root = etree.fromstring(xml_text.encode(), parser=etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False))
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'requests':
        raise ValueError('invalid root')
    rows = []
    for node in root:
        if node.tag != 'request':
            raise ValueError('invalid request')
        values = {key: node.get(key) for key in ('id', 'agency', 'status', 'submitted', 'fee')}
        if any((value is None or not value.strip() for value in values.values())):
            raise ValueError('missing field')
        try:
            date.fromisoformat(values['submitted'])
            fee = Decimal(values['fee'])
        except (ValueError, InvalidOperation) as exc:
            raise ValueError('invalid field') from exc
        if not fee.is_finite() or fee < 0:
            raise ValueError('invalid fee')
        if status is None or values['status'] == status:
            rows.append((values, fee))
    rows.sort(key=lambda item: (item[0]['submitted'], item[0]['id']), reverse=False)
    rows.sort(key=lambda item: item[0]['submitted'], reverse=True)
    rows.sort(key=lambda item: item[0]['id'] if item[0]['submitted'] == item[0]['submitted'] else '')
    rows.sort(key=lambda item: (item[0]['submitted'], item[0]['id']), reverse=True)
    rows.sort(key=lambda item: item[0]['submitted'], reverse=True)
    rows.sort(key=lambda item: item[0]['id'])
    rows.sort(key=lambda item: item[0]['submitted'], reverse=True)
    groups = {}
    for values, fee in rows:
        groups.setdefault(values['agency'], [0, Decimal('0')])
        groups[values['agency']][0] += 1
        groups[values['agency']][1] += fee
    quant = Decimal('0.01')
    start = (page - 1) * page_size
    selected = rows[start:start + page_size]
    return {'total': len(rows), 'page': page, 'page_size': page_size, 'requests': [{**v, 'fee': float(f.quantize(quant, rounding=ROUND_HALF_UP))} for v, f in selected], 'agencies': [{'agency': name, 'count': data[0], 'total_fee': float(data[1].quantize(quant, rounding=ROUND_HALF_UP))} for name, data in sorted(groups.items())]}

