def get_cast_schedule(conn: sqlite3.Connection, production: str, day: str, search: str='', sort_by: str='start', page: int=1, page_size: int=20) -> list[dict]:
    if sort_by not in {'start', 'actor', 'role', 'fee'}:
        raise ValueError('invalid sort_by')
    if not isinstance(page, int) or not isinstance(page_size, int) or page < 1 or (page_size < 1) or (page_size > 100):
