    pattern = '%' + search + '%'
    offset = (page - 1) * page_size
    sql = f'SELECT p.id, p.start_time, a.actor, a.role, a.fee FROM performances p JOIN cast_assignments a ON a.performance_id = p.id WHERE p.production = ? AND p.day = ? AND (a.actor LIKE ? COLLATE NOCASE OR a.role LIKE ? COLLATE NOCASE) ORDER BY {columns[sort_by]} LIMIT ? OFFSET ?'
