import json
import math
import pytest

from solution import verify_reservations


SECRET = b"park-office-secret"


def make_payload(reservations):
    return json.dumps({"reservations": reservations}, separators=(",", ":")).encode("utf-8")


def signed(payload):
    return hmac.new(SECRET, payload, hashlib.sha256).hexdigest()


def test_confirmed_reservations_are_aggregated_and_sorted():
    payload = make_payload([
        {"campground": "Pine Ridge", "site": "A1", "nights": 2, "guests": 4, "nightly_rate": 35.5, "status": "confirmed"},
        {"campground": "Lake View", "site": "B2", "nights": 3, "guests": 2, "nightly_rate": 50, "status": "confirmed"},
        {"campground": "Pine Ridge", "site": "A3", "nights": 1, "guests": 1, "nightly_rate": 40, "status": "confirmed"},
    ])
    assert verify_reservations(payload, signed(payload), SECRET) == {
        "total_nights": 6,
        "total_guests": 7,
        "total_revenue": 261,
        "campgrounds": [
            {"name": "Lake View", "nights": 3, "guests": 2, "revenue": 150, "reservations": 1},
            {"name": "Pine Ridge", "nights": 3, "guests": 5, "revenue": 111, "reservations": 2},
        ],
    }


def test_cancelled_reservations_are_excluded():
    payload = make_payload([
        {"campground": "Cedar", "site": "1", "nights": 4, "guests": 4, "nightly_rate": 99, "status": "cancelled"},
        {"campground": "Cedar", "site": "2", "nights": 1, "guests": 2, "nightly_rate": 12.25, "status": "confirmed"},
    ])
    result = verify_reservations(payload, signed(payload), SECRET)
    assert result["total_nights"] == 1
    assert result["total_guests"] == 2
    assert result["total_revenue"] == 12.25
    assert result["campgrounds"] == [{"name": "Cedar", "nights": 1, "guests": 2, "revenue": 12.25, "reservations": 1}]


def test_equal_revenue_uses_name_as_tie_breaker():
    payload = make_payload([
        {"campground": "Zulu", "site": "1", "nights": 2, "guests": 1, "nightly_rate": 10, "status": "confirmed"},
        {"campground": "Alpha", "site": "1", "nights": 1, "guests": 1, "nightly_rate": 20, "status": "confirmed"},
    ])
    assert [x["name"] for x in verify_reservations(payload, signed(payload), SECRET)["campgrounds"]] == ["Alpha", "Zulu"]


def test_empty_reservations_have_zero_result():
    payload = make_payload([])
    assert verify_reservations(payload, signed(payload), SECRET) == {
        "total_nights": 0, "total_guests": 0, "total_revenue": 0, "campgrounds": []
    }


def test_invalid_signature_raises_value_error():
    payload = make_payload([])
    with pytest.raises(ValueError):
        verify_reservations(payload, "0" * 64, SECRET)


def test_invalid_json_raises_value_error_with_valid_signature():
    payload = b"not-json"
    with pytest.raises(ValueError):
        verify_reservations(payload, signed(payload), SECRET)


def test_invalid_reservation_values_raise_value_error():
