        {"campground": "Pine", "site": "A", "nights": True, "guests": 1, "nightly_rate": 5, "status": "confirmed"}
    ]
    payload = make_payload(reservations)
    with pytest.raises(ValueError):
        verify_reservations(payload, signed(payload), SECRET)


def test_fractional_revenue_is_rounded_to_two_places():
    payload = make_payload([
        {"campground": "Meadow", "site": "1", "nights": 3, "guests": 1, "nightly_rate": 0.335, "status": "confirmed"},
    ])
    assert verify_reservations(payload, signed(payload), SECRET)["total_revenue"] == 1.01

