def parse_matter_line(line: str) -> dict:
    text = line.strip()
    if not text:
        raise ValueError('blank record')
    parts = text.split('|')
    if len(parts) != 4 or any((not x for x in parts)):
        raise ValueError('invalid record')
    matter_id, date, status, hours = parts
    try:
        datetime.date.fromisoformat(date)
        value = float(hours)
    except ValueError as exc:
        raise ValueError('invalid record') from exc
    if status not in {'OPEN', 'PENDING', 'CLOSED'} or value < 0:
