def plan_dispatch(readings: list[dict], capacity_kwh: int, initial_soc: int, config: dict) -> list[dict]:
    if not isinstance(capacity_kwh, int) or capacity_kwh <= 0:
        raise ValueError('capacity_kwh must be positive')
    if not isinstance(initial_soc, int) or not 0 <= initial_soc <= capacity_kwh:
        raise ValueError('initial_soc out of bounds')
    max_power = config.get('max_power')
    charge_price = config.get('charge_price')
    discharge_price = config.get('discharge_price')
    if not all((isinstance(x, int) for x in (max_power, charge_price, discharge_price))) or max_power <= 0:
        raise ValueError('invalid configuration')
    soc = initial_soc
    result = []
    for reading in readings:
        if not all((key in reading for key in ('hour', 'load', 'solar', 'price'))):
            raise ValueError('reading is missing a field')
        hour, load, solar, price = (reading[k] for k in ('hour', 'load', 'solar', 'price'))
        if not all((isinstance(x, int) for x in (hour, load, solar, price))) or load < 0 or solar < 0:
            raise ValueError('invalid reading')
        charge = discharge = grid = 0
        if solar >= load:
            charge = min(solar - load, max_power, capacity_kwh - soc)
            soc += charge
        else:
            deficit = load - solar
            if price >= discharge_price:
                discharge = min(deficit, max_power, soc)
                soc -= discharge
            elif price <= charge_price:
                charge = min(max_power, capacity_kwh - soc)
                soc += charge
            grid = deficit - discharge + charge
        result.append({'hour': hour, 'charge': charge, 'discharge': discharge, 'soc': soc, 'grid_import': grid})
    return result

