    key = os.environ.get('BATTERY_SIGNING_KEY')
    if key is None:
        raise ValueError('BATTERY_SIGNING_KEY is required')
    return hmac.new(key.encode('utf-8'), dispatch_payload(plan).encode('utf-8'), hashlib.sha256).hexdigest()

