    if new_status not in {'submitted', 'approved', 'rejected', 'paid'}:
        raise ValueError('invalid status')
    cur = conn.execute('UPDATE claims SET status = ? WHERE claim_id = ?', (new_status, claim_id))
    if cur.rowcount == 0:
        raise KeyError(claim_id)
    conn.commit()

