import hashlib
import hmac
import os

def _password_hash(password: str) -> str:
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def verify_archive_password(stored_password: str, curator_password: str) -> bool:
    if not isinstance(stored_password, str) or not isinstance(curator_password, str):
        return False
    try:
        salt_text, digest_text = stored_password.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', curator_password.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def build_archive_report(records: list[dict], curator_password: str, page: int, page_size: int) -> dict:
    if not isinstance(records, list) or not isinstance(curator_password, str) or (not curator_password):
        raise ValueError('invalid input')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    included = []
    for record in records:
        if not isinstance(record, dict) or set(record) != {'id', 'title', 'year', 'pages', 'digitized'}:
            raise ValueError('invalid record')
        if not isinstance(record['id'], str) or not record['id'] or (not isinstance(record['title'], str)) or (not isinstance(record['year'], int)) or isinstance(record['year'], bool) or (not 1000 <= record['year'] <= 2100) or (not isinstance(record['pages'], int)) or isinstance(record['pages'], bool) or (record['pages'] < 0) or (not isinstance(record['digitized'], bool)):
            raise ValueError('invalid record')
        if record['digitized']:
            included.append(record)
    included.sort(key=lambda r: (r['year'], r['id']))
    groups = {}
    for record in included:
        decade = record['year'] // 10 * 10
        count, pages = groups.get(decade, (0, 0))
        groups[decade] = (count + 1, pages + record['pages'])
    start = (page - 1) * page_size
    items = [{k: record[k] for k in ('id', 'title', 'year', 'pages')} for record in included[start:start + page_size]]
    return {'password_hash': _password_hash(curator_password), 'total': len(included), 'total_pages': sum((r['pages'] for r in included)), 'page': page, 'page_size': page_size, 'items': items, 'decades': [{'decade': d, 'count': groups[d][0], 'pages': groups[d][1]} for d in sorted(groups)]}

