import hashlib
import hmac
import json
import pytest

def make_body(appointments, **extra):
    value = {'appointments': appointments, **extra}
    return json.dumps(value, separators=(',', ':')).encode()

def sign(body, secret=b'office-key'):
    return 'sha256=' + hmac.new(secret, body, hashlib.sha256).hexdigest()

def appointment(date='2025-04-14', start='09:00', minutes=30, notary='Ava', client='C'):
    return {'date': date, 'start': start, 'minutes': minutes, 'notary': notary, 'client': client}

def test_verify_accepts_valid_request_and_preserves_extra_fields():
    body = make_body([appointment()], request_id='r7', source='desk')
    result = verify_request(body, sign(body), b'office-key')
    assert result == {'appointments': [appointment()], 'request_id': 'r7', 'source': 'desk'}

def test_verify_rejects_bad_signature_forms_and_wrong_secret():
    body = make_body([])
    for value in ['', 'sha256', 'sha1=' + 'a' * 64, 'sha256=' + 'A' * 64, 'sha256=' + '0' * 63]:
        with pytest.raises(ValueError):
            verify_request(body, value, b'office-key')
    with pytest.raises(ValueError):
        verify_request(body, sign(body, b'other'), b'office-key')

def test_verify_rejects_bad_encoding_json_and_shape():
    with pytest.raises(ValueError):
        verify_request(b'\xff', 'sha256=' + '0' * 64, b'x')
    body = b'[]'
    with pytest.raises(ValueError):
        verify_request(body, sign(body, b'x'), b'x')
    body = make_body([appointment()], bad=True)
    body = body.replace(b'"appointments":[{', b'"appointments":[{"extra":1,')
    with pytest.raises(ValueError):
        verify_request(body, sign(body, b'office-key'), b'office-key')

