    data = {'appointments': [appointment(start='09:30', minutes=30, notary='Zed'), appointment(start='10:00', minutes=30, notary='Zed'), appointment(start='12:00', minutes=30, notary='Zed')]}
    assert summary_appointments(data, '2025-04-14') == [{'notary': 'Zed', 'free': [('09:00', '09:30'), ('10:30', '12:00'), ('12:30', '17:00')]}]

def test_summary_sorts_notaries_clips_working_hours_and_ignores_other_days():
    data = {'appointments': [appointment(start='08:00', minutes=120, notary='Beta'), appointment(start='16:30', minutes=120, notary='Beta'), appointment(start='09:00', minutes=480, notary='Alpha'), appointment(date='2025-04-15', notary='Aardvark')]}
