import datetime
import hashlib
import hmac
import json
import re

def _appointments(value):
    if not isinstance(value, dict) or not isinstance(value.get('appointments'), list):
        raise ValueError('invalid document')
    for item in value['appointments']:
        if not isinstance(item, dict) or set(item) != {'date', 'start', 'minutes', 'notary', 'client'}:
            raise ValueError('invalid appointment')
        try:
            day = datetime.date.fromisoformat(item['date'])
            hour, minute = map(int, item['start'].split(':'))
        except (ValueError, TypeError, AttributeError):
            raise ValueError('invalid appointment')
        if not re.fullmatch('\\d{4}-\\d{2}-\\d{2}', item['date']) or not re.fullmatch('\\d{2}:\\d{2}', item['start']):
            raise ValueError('invalid appointment')
        if hour > 23 or minute > 59 or minute % 15 or (item['minutes'] < 15) or (item['minutes'] > 480) or item['minutes'] % 15:
            raise ValueError('invalid appointment')
        if not isinstance(item['minutes'], int) or isinstance(item['minutes'], bool) or (not isinstance(item['notary'], str)) or (not item['notary']) or (not isinstance(item['client'], str)) or (not item['client']):
            raise ValueError('invalid appointment')
        if hour * 60 + minute + item['minutes'] > 1440:
            raise ValueError('invalid appointment')
        if day.isoformat() != item['date']:
            raise ValueError('invalid appointment')
    return value['appointments']

def verify_request(body: bytes, signature: str, secret: bytes) -> dict:
    if not isinstance(signature, str) or not re.fullmatch('sha256=[0-9a-f]{64}', signature):
        raise ValueError('invalid signature')
    expected = hmac.new(secret, body, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(signature[7:], expected):
        raise ValueError('invalid signature')
    try:
        value = json.loads(body.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('invalid body')
    _appointments(value)
    return value

def summary_appointments(document: dict, day: str) -> list[dict]:
    try:
        wanted = datetime.date.fromisoformat(day)
    except (ValueError, TypeError):
        raise ValueError('invalid day')
    if wanted.isoformat() != day:
        raise ValueError('invalid day')
    groups = {}
    for item in _appointments(document):
        if item['date'] == day:
            start = int(item['start'][:2]) * 60 + int(item['start'][3:])
            groups.setdefault(item['notary'], []).append((start, start + item['minutes']))
    result = []
    for name in sorted(groups):
        busy = []
        for start, end in sorted(groups[name]):
            start, end = (max(start, 540), min(end, 1020))
            if start >= end:
                continue
            if busy and start <= busy[-1][1]:
                busy[-1] = (busy[-1][0], max(busy[-1][1], end))
            else:
                busy.append((start, end))
        free = []
        cursor = 540
        for start, end in busy:
            if start - cursor >= 15:
                free.append((f'{cursor // 60:02d}:{cursor % 60:02d}', f'{start // 60:02d}:{start % 60:02d}'))
            cursor = max(cursor, end)
        if 1020 - cursor >= 15:
            free.append((f'{cursor // 60:02d}:{cursor % 60:02d}', '17:00'))
        result.append({'notary': name, 'free': free})
    return result

