import os

def save_order_receipt(base_dir: str, relative_name: str, content: str) -> str:
    if not relative_name or os.path.isabs(relative_name):
        raise ValueError('relative_name must be a nonempty relative path')
    base = os.path.realpath(base_dir)
    destination = os.path.realpath(os.path.join(base, relative_name))
    try:
        common = os.path.commonpath([base, destination])
    except ValueError:
        raise ValueError('receipt path is outside base directory')
    if common != base:
        raise ValueError('receipt path is outside base directory')
    os.makedirs(os.path.dirname(destination), exist_ok=True)
    with open(destination, 'w', encoding='utf-8') as handle:
        handle.write(content)
    return destination

