import ast
import operator

def _evaluate(text, names):
    tree = ast.parse(text, mode='eval').body

    def visit(node):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in names:
                raise NameError(node.id)
            return names[node.id]
        if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub, ast.Not):
            value = visit(node.operand)
            return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
        if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div, ast.Mod, ast.Pow):
            a, b = (visit(node.left), visit(node.right))
            return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv, ast.Mod: operator.mod, ast.Pow: operator.pow}[type(node.op)](a, b)
        if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
            value = visit(node.values[0])
            for child in node.values[1:]:
                if isinstance(node.op, ast.And) and (not value) or (isinstance(node.op, ast.Or) and value):
                    return value
                value = visit(child)
            return value
        if isinstance(node, ast.Compare):
            left = visit(node.left)
            ops = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}
            for op, child in zip(node.ops, node.comparators):
                right = visit(child)
                if not ops[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
            return {'min': min, 'max': max, 'round': round}[node.func.id](*(visit(x) for x in node.args))
        raise ValueError('invalid expression')
    return visit(tree)

def schedule_reservoir(records: list[dict], filter_expression: str, score_expression: str, variables: dict[str, float], limit: int) -> list[dict]:
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 0:
        raise ValueError('invalid limit')
    result = []
    inflows = []
    for index, record in enumerate(records):
        if not isinstance(record, dict) or any((k not in record for k in ('timestamp', 'inflow', 'level', 'demand', 'capacity'))):
            raise ValueError('invalid record')
        if not isinstance(record['timestamp'], str) or any((not isinstance(record[k], (int, float)) or isinstance(record[k], bool) for k in ('inflow', 'level', 'demand', 'capacity'))):
            raise ValueError('invalid record')
        inflows.append(record['inflow'])
        rolling = sum(inflows[-3:])
        names = dict(variables)
        names.update({k: record[k] for k in ('inflow', 'level', 'demand', 'capacity')})
        names['rolling_inflow'] = rolling
        if not isinstance(_evaluate(filter_expression, names), bool):
            raise ValueError('filter must be boolean')
        if _evaluate(filter_expression, names):
            score = _evaluate(score_expression, names)
            if not isinstance(score, (int, float)) or isinstance(score, bool):
                raise ValueError('score must be numeric')
            result.append((score, record['timestamp'], index, {'timestamp': record['timestamp'], 'rolling_inflow': rolling, 'score': score}))
    result.sort(key=lambda x: (-x[0], x[1], x[2]))
    return [x[3] for x in result[:limit]]

