def build_subscription_invoice(requester: dict, subscription: dict, usage_records: list[dict], period: str) -> dict:
    if not isinstance(period, str) or not re.fullmatch('\\d{4}-(0[1-9]|1[0-2])', period):
        raise ValueError('invalid period')
    try:
        year, month = map(int, period.split('-'))
    except Exception as exc:
        raise ValueError('invalid period') from exc
    required = ('id', 'owner_id', 'tenant_id', 'plan', 'monthly_fee_cents', 'included_units', 'overage_cents_per_unit')
    if any((key not in subscription for key in required)):
        raise ValueError('invalid subscription')
    for key in ('monthly_fee_cents', 'included_units', 'overage_cents_per_unit'):
        value = subscription[key]
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            raise ValueError('invalid subscription')
    if requester.get('id') != subscription['owner_id'] and (not (requester.get('role') == 'billing_admin' and requester.get('tenant_id') == subscription['tenant_id'])):
        raise PermissionError('not permitted')
    used = 0
    for record in usage_records:
        if record.get('subscription_id') != subscription['id']:
            continue
        if not all((key in record for key in ('subscription_id', 'date', 'units'))):
            raise ValueError('invalid usage record')
        try:
            current = date.fromisoformat(record['date'])
        except Exception as exc:
            raise ValueError('invalid usage record') from exc
        units = record['units']
        if isinstance(units, bool) or not isinstance(units, int) or units < 0:
            raise ValueError('invalid usage record')
        if current.year == year and current.month == month:
            used += units
    overage_units = max(0, used - subscription['included_units'])
    overage = overage_units * subscription['overage_cents_per_unit']
    return {'subscription_id': subscription['id'], 'period': period, 'plan': subscription['plan'], 'base_cents': subscription['monthly_fee_cents'], 'included_units': subscription['included_units'], 'used_units': used, 'overage_units': overage_units, 'overage_cents': overage, 'total_cents': subscription['monthly_fee_cents'] + overage}

