import ast
import operator

def select_telehealth_records(records: list[dict], rule: str, limit: int=10) -> list[dict]:
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 0:
        raise ValueError('invalid limit')
    try:
        tree = ast.parse(rule, mode='eval').body
    except Exception as exc:
        raise ValueError('invalid expression') from exc

    def evaluate(node, env):
        if isinstance(node, ast.Constant):
            if isinstance(node.value, (int, float, bool)) and (not isinstance(node.value, complex)):
                return node.value
            raise ValueError('invalid expression')
        if isinstance(node, ast.Name):
            if node.id in env:
                return env[node.id]
            raise NameError(node.id)
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
            value = evaluate(node.operand, env)
            if isinstance(node.op, ast.UAdd):
                return +value
            if isinstance(node.op, ast.USub):
                return -value
            return not value
        if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
            value = evaluate(node.values[0], env)
            for part in node.values[1:]:
                if isinstance(node.op, ast.And) and (not value):
                    return value
                if isinstance(node.op, ast.Or) and value:
                    return value
                value = evaluate(part, env)
            return value
        if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
            left = evaluate(node.left, env)
            right = evaluate(node.right, env)
            funcs = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
            return funcs[type(node.op)](left, right)
        if isinstance(node, ast.Compare):
            left = evaluate(node.left, env)
            funcs = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}
            for op, comparator in zip(node.ops, node.comparators):
                if type(op) not in funcs:
                    raise ValueError('invalid expression')
                right = evaluate(comparator, env)
                if not funcs[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
            if any((isinstance(arg, ast.Starred) for arg in node.args)):
                raise ValueError('invalid expression')
            args = [evaluate(arg, env) for arg in node.args]
            return {'min': min, 'max': max, 'round': round}[node.func.id](*args)
        raise ValueError('invalid expression')
    selected = []
    for record in records:
        env = {key: record[key] for key in ('id', 'patient', 'age', 'systolic', 'diastolic', 'risk')}
        try:
            if evaluate(tree, env):
                selected.append(record)
        except NameError as exc:
            raise ValueError('unknown name') from exc
        except ValueError:
            raise
        except Exception as exc:
            raise ValueError('invalid expression') from exc
    selected.sort(key=lambda item: (-item['risk'], item['id']))
    return selected[:limit]

