from typing import Any
from lxml import etree
_STATUSES = ('received', 'processing', 'complete', 'rejected')

def _time(value: str) -> datetime:
    try:
        parsed = datetime.fromisoformat(value[:-1] + '+00:00' if value.endswith('Z') else value)
    except Exception as exc:
        raise ValueError('invalid timestamp') from exc
    if parsed.tzinfo is None:
        raise ValueError('timestamp needs timezone')
    return parsed.astimezone(timezone.utc)

def _time_text(value: str) -> str:
    parsed = _time(value)
    text = parsed.isoformat(timespec='microseconds').replace('+00:00', 'Z')
    return text[:-7] + 'Z' if text.endswith('.000000Z') else text

def parse_samples(xml_text: str) -> list[dict[str, Any]]:
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode(), parser=parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'lab':
        raise ValueError('invalid root')
    result = []
    seen = set()
    for node in root:
        if node.tag != 'sample':
            raise ValueError('invalid structure')
        sid = node.get('id')
        collected = node.get('collected')
        status = node.get('status')
        if not sid or collected is None or status not in _STATUSES or (sid in seen):
            raise ValueError('invalid sample')
        received = node.get('received')
        ctime = _time(collected)
        rtime = _time(received) if received is not None else None
        if rtime is not None and rtime < ctime:
            raise ValueError('invalid ordering')
        tests_node = None
        for child in node:
            if child.tag == 'tests':
                if tests_node is not None:
                    raise ValueError('invalid structure')
                tests_node = child
            else:
                raise ValueError('invalid structure')
        tests = []
        if tests_node is not None:
            for test in tests_node:
                if test.tag != 'test' or not test.get('code') or test.get('result') is None:
                    raise ValueError('invalid test')
                tests.append({'code': test.get('code'), 'result': test.get('result'), 'unit': test.get('unit', '')})
        seen.add(sid)
        result.append({'id': sid, 'status': status, 'collected': _time_text(collected), 'received': _time_text(received) if received is not None else None, 'tests': tests})
    return result

def summarize_samples(records: list[dict[str, Any]]) -> dict[str, Any]:
    counts = {status: 0 for status in _STATUSES}
    code_counts = {}
    total_hours = 0.0
    timed = 0
    for record in records:
        try:
            status = record['status']
            if status not in counts:
                raise ValueError
            counts[status] += 1
            collected = _time(record['collected'])
            received = record['received']
            if received is not None:
                delta = (_time(received) - collected).total_seconds() / 3600
                if delta < 0:
                    raise ValueError
                total_hours += delta
                timed += 1
            for test in record['tests']:
                code = test['code']
                if not isinstance(code, str) or not code:
                    raise ValueError
                code_counts[code] = code_counts.get(code, 0) + 1
        except (KeyError, TypeError, ValueError) as exc:
            raise ValueError('invalid records') from exc
    ordered = dict(sorted(code_counts.items(), key=lambda item: (-item[1], item[0])))
    return {'sample_count': len(records), 'status_counts': counts, 'test_count': sum(code_counts.values()), 'average_turnaround_hours': round(total_hours / timed, 2) if timed else None, 'test_code_counts': ordered}

