import hashlib
import hmac
import json
import pytest


def make_report(secret, module, files):
    payload = {"module": module, "files": files}
    raw = json.dumps(payload, sort_keys=True, separators=(",", ":")).encode()
    sig = hmac.new(secret.encode(), raw, hashlib.sha256).hexdigest()
    return json.dumps({"module": module, "files": files, "signature": sig})


def test_empty_input():
    assert aggregate_reports([], "key") == {
        "files": {},
        "summary": {"covered": 0, "total": 0, "percent": 0.0},
    }


