    report = make_report("key", "core", {
        "z.py": {"10": 0, "2": 3},
        "a.py": {"3": 1, "1": 0},
    })
    assert aggregate_reports([report], "key") == {
        "files": {
            "a.py": {"lines": {"1": 0, "3": 1}, "covered": 1, "total": 2},
            "z.py": {"lines": {"2": 3, "10": 0}, "covered": 1, "total": 2},
        },
        "summary": {"covered": 2, "total": 4, "percent": 50.0},
    }


def test_merges_duplicate_files_using_maximum_counts():
    first = make_report("s", "one", {"x.py": {"1": 2, "4": 0}, "b.py": {"8": 1}})
    second = make_report("s", "two", {"x.py": {"1": 7, "4": 3, "9": 0}})
