import hashlib
import hmac
import json

def aggregate_reports(reports: list[str], secret: str) -> dict:
    if not isinstance(secret, str):
        raise ValueError('invalid secret')
    merged = {}
    for text in reports:
        try:
            item = json.loads(text)
        except Exception as exc:
            raise ValueError('invalid report') from exc
        if not isinstance(item, dict) or set(item) != {'module', 'files', 'signature'}:
            raise ValueError('invalid report')
        module = item['module']
        files = item['files']
        signature = item['signature']
        if not isinstance(module, str) or not module or (not isinstance(files, dict)) or (not isinstance(signature, str)):
            raise ValueError('invalid report')
        for name, lines in files.items():
            if not isinstance(name, str) or not isinstance(lines, dict):
                raise ValueError('invalid files')
            for line, count in lines.items():
                if not isinstance(line, str) or not line.isdigit() or int(line) <= 0:
                    raise ValueError('invalid line')
                if isinstance(count, bool) or not isinstance(count, int) or count < 0:
                    raise ValueError('invalid count')
        payload = {'module': module, 'files': files}
        raw = json.dumps(payload, sort_keys=True, separators=(',', ':')).encode()
        expected = hmac.new(secret.encode(), raw, hashlib.sha256).hexdigest()
        if not hmac.compare_digest(signature, expected):
            raise ValueError('invalid signature')
        for name, lines in files.items():
            target = merged.setdefault(name, {})
            for line, count in lines.items():
                target[line] = max(target.get(line, 0), count)
    output_files = {}
    total = covered = 0
    for name in sorted(merged):
        lines = {k: merged[name][k] for k in sorted(merged[name], key=int)}
        hit = sum((value > 0 for value in lines.values()))
        count = len(lines)
        output_files[name] = {'lines': lines, 'covered': hit, 'total': count}
        covered += hit
        total += count
    percent = round(covered * 100 / total, 2) if total else 0.0
    return {'files': output_files, 'summary': {'covered': covered, 'total': total, 'percent': percent}}

