import math
import os
import tempfile


def make_file(contents):
    handle = tempfile.NamedTemporaryFile(mode="w", encoding="utf-8", delete=False)
    try:
        handle.write(contents)
        return handle.name
    finally:
        handle.close()


def test_empty_paths_returns_empty():
    assert rank_solar_quotes([]) == []


def test_combines_sorts_and_rounds_records():
    first = make_file("Sunrise Solar,12000.456\n\nBright Energy,8500\n")
    second = make_file("Green Roofs,8500.004\nPeak Panels,15000.999\n")
    try:
        assert rank_solar_quotes([first, second]) == [
            ("Bright Energy", 8500.0),
            ("Green Roofs", 8500.0),
            ("Sunrise Solar", 12000.46),
            ("Peak Panels", 15001.0),
        ]
    finally:
        os.unlink(first)
        os.unlink(second)


def test_ties_use_vendor_name_order():
    path = make_file("Zulu,100\nAlpha,100\nMiddle,99.999\n")
    try:
        assert rank_solar_quotes([path]) == [
            ("Middle", 100.0),
            ("Alpha", 100.0),
            ("Zulu", 100.0),
        ]
    finally:
        os.unlink(path)


def test_pagination_boundaries():
    path = make_file("A,1\nB,2\nC,3\nD,4\nE,5\n")
    try:
        assert rank_solar_quotes([path], 1, 2) == [("A", 1.0), ("B", 2.0)]
        assert rank_solar_quotes([path], 2, 2) == [("C", 3.0), ("D", 4.0)]
        assert rank_solar_quotes([path], 3, 2) == [("E", 5.0)]
        assert rank_solar_quotes([path], 4, 2) == []
    finally:
        os.unlink(path)


def test_blank_lines_are_ignored():
    path = make_file("\n  \nInstaller,42.50\n\n")
    try:
        assert rank_solar_quotes([path]) == [("Installer", 42.5)]
    finally:
        os.unlink(path)


