    path = make_file("A,1\n")
    try:
        for page, size in [(0, 10), (-1, 10), (1, 0), (1, 101), (True, 10), (1, False)]:
            try:
                rank_solar_quotes([path], page, size)
            except ValueError:
                pass
            else:
                assert False
    finally:
        os.unlink(path)


