        "Vendor,inf\n",
        "Vendor,1,extra\n",
    ]
    for contents in cases:
        path = make_file(contents)
        try:
            try:
                rank_solar_quotes([path])
            except ValueError:
                pass
            else:
                assert False
        finally:
