from pathlib import Path

def build_inventory_report(records: list[dict[str, object]], relative_name: str, base_dir: str, min_impressions: int=0, limit: int | None=None) -> str:
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    if not isinstance(relative_name, str) or not relative_name:
        raise ValueError('relative_name must not be empty')
    if not isinstance(min_impressions, int) or isinstance(min_impressions, bool) or min_impressions < 0:
        raise ValueError('invalid minimum')
    if limit is not None and (not isinstance(limit, int) or isinstance(limit, bool) or limit <= 0):
        raise ValueError('invalid limit')
    grouped = {}
    for record in records:
        if not isinstance(record, dict):
            raise TypeError('record must be a dictionary')
        for key in ('channel', 'impressions', 'cpm', 'booked'):
            if key not in record:
                raise ValueError('missing field')
        channel = record['channel']
        impressions = record['impressions']
        cpm = record['cpm']
        booked = record['booked']
        if not isinstance(channel, str) or not isinstance(impressions, int) or isinstance(impressions, bool) or (impressions < 0) or (not isinstance(cpm, (int, float))) or isinstance(cpm, bool) or (cpm < 0) or (not isinstance(booked, bool)):
            raise ValueError('invalid record')
        if booked:
            item = grouped.setdefault(channel, [0, 0, 0.0, 0.0])
            item[0] += 1
            item[1] += impressions
            item[2] += cpm
            item[3] += impressions * cpm / 1000
    rows = []
    for channel, (spots, total, cpm_sum, cost) in grouped.items():
        if total >= min_impressions:
            rows.append((total, channel, [channel, spots, total, round(cpm_sum / spots, 2), round(cost, 2)]))
    rows.sort(key=lambda item: (-item[0], item[1]))
    if limit is not None:
        rows = rows[:limit]
    base = Path(base_dir).resolve()
    target = (base / relative_name).resolve()
    try:
        target.relative_to(base)
    except ValueError:
        raise ValueError('output path is outside base directory')
    target.parent.mkdir(parents=True, exist_ok=True)
    with target.open('w', newline='', encoding='utf-8') as handle:
        writer = csv.writer(handle, lineterminator='\n')
        writer.writerow(['channel', 'spots', 'total_impressions', 'average_cpm', 'total_cost'])
        for _, _, row in rows:
            writer.writerow(row)
    return str(target)

