from datetime import date

def export_vaccination_summary(records: list[dict[str, object]], output_path: str) -> str:
    rows = []
    for record in records:
        try:
            patient_id = record['patient_id']
            vaccine = record['vaccine']
            dose_date = record['dose_date']
            dose_number = record['dose_number']
        except (KeyError, TypeError):
            raise ValueError('invalid record')
        if not isinstance(patient_id, str) or not patient_id or (not isinstance(vaccine, str)) or (not vaccine) or (not isinstance(dose_date, str)) or (not isinstance(dose_number, int)) or isinstance(dose_number, bool) or (dose_number <= 0):
            raise ValueError('invalid record')
        try:
            parsed_date = date.fromisoformat(dose_date)
        except ValueError:
            raise ValueError('invalid record')
        if parsed_date.isoformat() != dose_date:
            raise ValueError('invalid record')
        rows.append((patient_id, vaccine, dose_date, dose_number))
    rows.sort(key=lambda row: (row[2], row[0], row[3], row[1]))
    directory = os.path.dirname(os.path.abspath(output_path))
    fd, temporary_path = tempfile.mkstemp(dir=directory, prefix='vaccination-')
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle)
            writer.writerow(['patient_id', 'vaccine', 'dose_date', 'dose_number'])
            writer.writerows(rows)
        os.replace(temporary_path, output_path)
    except Exception:
        try:
            os.unlink(temporary_path)
        except FileNotFoundError:
            pass
        raise
    return output_path

