def extract_docket_bundle(archive_path: str, output_dir: str) -> list[str]:
    base = Path(output_dir).resolve()
    base.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(archive_path) as archive:
        files = [m for m in archive.infolist() if not m.is_dir()]
        destinations = []
        for member in files:
            target = (base / member.filename).resolve()
            try:
                target.relative_to(base)
            except ValueError:
                raise ValueError('archive member is outside output directory')
            destinations.append((member, target))
        for member, target in destinations:
            target.parent.mkdir(parents=True, exist_ok=True)
            with archive.open(member) as source, open(target, 'wb') as dest:
                while True:
                    chunk = source.read(65536)
                    if not chunk:
                        break
                    dest.write(chunk)
    return sorted((str(target.relative_to(base)).replace(os.sep, '/') for _, target in destinations))

def parse_docket_log(text: str) -> list[dict]:
    result = []
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields, current, escaped = ([], [], False)
        for char in raw:
            if escaped:
                current.append(char)
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == '|':
                fields.append(''.join(current))
                current = []
            else:
                current.append(char)
        if escaped:
            raise ValueError('trailing escape')
        fields.append(''.join(current))
        if len(fields) != 3 or any((not x.strip() for x in fields)):
            raise ValueError('malformed docket line')
        try:
            parsed_date = date.fromisoformat(fields[0].strip())
            priority = int(fields[1].strip())
        except Exception as exc:
            raise ValueError('invalid docket line') from exc
        if not 1 <= priority <= 5:
            raise ValueError('invalid priority')
        result.append({'date': parsed_date, 'priority': priority, 'title': fields[2].strip()})
    return sorted(result, key=lambda x: (x['date'], -x['priority'], x['title']))

def rank_deadlines(records: list[dict], as_of: date, window_days: int=30) -> list[dict]:
    if window_days < 0:
        raise ValueError('negative window')
    end = as_of + timedelta(days=window_days)
    result = []
    for record in records:
        if as_of <= record['date'] <= end:
            days = (record['date'] - as_of).days
            result.append({'date': record['date'], 'priority': record['priority'], 'title': record['title'], 'days_remaining': days, 'urgency': 'urgent' if days <= 7 else 'normal'})
    return sorted(result, key=lambda x: (x['date'], -x['priority'], x['title']))

