def make_member_record(member_id: str, password: str, display_name: str, role: str='member') -> dict:
    if not isinstance(member_id, str) or not member_id or (not isinstance(password, str)) or (not password) or (not isinstance(display_name, str)) or (not display_name):
        raise ValueError('invalid member')
    if role not in ('member', 'leader'):
        raise ValueError('invalid role')
    salt = os.urandom(16)
    return {'member_id': member_id, 'display_name': display_name, 'role': role, 'salt': salt.hex(), 'password_hash': hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000).hex()}

def verify_member(record: dict, password: str) -> bool:
    try:
        if not isinstance(password, str):
            return False
        salt = bytes.fromhex(record['salt'])
        expected = bytes.fromhex(record['password_hash'])
        return hmac.compare_digest(hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000), expected)
    except (KeyError, TypeError, ValueError):
        return False

def _parsed(s, kind):
    try:
        if kind == 'date':
            return date.fromisoformat(s)
        if len(s) != 5 or s[2] != ':':
            raise ValueError
        h, m = (int(s[:2]), int(s[3:]))
        if not 0 <= h <= 23 or not 0 <= m <= 59:
            raise ValueError
        return h * 60 + m
    except (TypeError, ValueError):
        raise ValueError('invalid calendar value')

def expand_events(events: list[dict], start_date: str, end_date: str) -> list[dict]:
    first, last = (_parsed(start_date, 'date'), _parsed(end_date, 'date'))
    if first > last:
        raise ValueError('invalid range')
    out = []
    for e in events:
        if not isinstance(e, dict) or not isinstance(e.get('title'), str) or (not e['title']):
            raise ValueError('invalid event')
        d = _parsed(e.get('date'), 'date')
        begin, finish = (_parsed(e.get('start'), 'time'), _parsed(e.get('end'), 'time'))
        if finish <= begin or not isinstance(e.get('room', ''), str):
            raise ValueError('invalid event')
        rec = e.get('recurrence')
        count = e.get('occurrences', 1)
        if rec not in (None, 'weekly') or isinstance(count, bool) or (not isinstance(count, int)) or (not 1 <= count <= 52):
            raise ValueError('invalid recurrence')
        for i in range(count):
            od = d + timedelta(days=7 * i if rec == 'weekly' else 0)
            if first <= od <= last:
                x = {k: v for k, v in e.items() if k not in ('recurrence', 'occurrences')}
                x['date'] = od.isoformat()
                x.setdefault('room', '')
                out.append(x)
    return sorted(out, key=lambda x: (x['date'], x['start'], x['room'], x['title']))

def visible_events(record: dict, password: str, events: list[dict], start_date: str, end_date: str) -> list[dict]:
    if not verify_member(record, password):
        raise PermissionError('authentication failed')
    for e in events:
        if e.get('audience', 'all') not in ('all', 'members', 'leaders'):
            raise ValueError('invalid audience')
    result = expand_events(events, start_date, end_date)
    role = record.get('role')
    return [x for x in result if x.get('audience', 'all') != 'leaders' or role == 'leader']

