import hashlib
import hmac
import json
import pytest

def manifest():
    return {'publisher': 'Acme', 'files': [{'name': 'widget-1.2.3.tar.gz', 'size': 17, 'sha256': 'a' * 64}, {'name': 'widget-1.2.3.whl.tar.gz', 'size': 29, 'sha256': 'b' * 64}], 'version': '1.2.3'}

def proof_for(value, key=b'registry-key'):
    return hmac.new(key, canonical_manifest(value), hashlib.sha256).hexdigest()

def test_canonical_manifest_is_deterministic_and_utf8():
    value = {'z': 'é', 'a': {'y': 2, 'x': 1}}
    assert canonical_manifest(value) == b'{"a":{"x":1,"y":2},"z":"\xc3\xa9"}'
    original = {'b': 1, 'a': 2}
    before = dict(original)
    canonical_manifest(original)
    assert original == before

def test_parse_download_url_rejects_bad_forms():
    bad = ['http://registry.example/packages/a/1/a.tar.gz', 'https://registry.example/packages/a/1/a.tar.gz?x=1', 'https://registry.example/packages/a/1/a.tar.gz#part', 'https://registry.example/packages/a/1/a.zip', 'https://registry.example/packages/a/1/../a.tar.gz', 'https://registry.example/packages//1/a.tar.gz', 'https://registry.example/packages/a/1/a/b.tar.gz']
    for url in bad:
        with pytest.raises(ValueError):
            parse_download_url(url)

def test_verify_rejects_wrong_proof_and_wrong_key():
    value = manifest()
    url = 'https://registry.example/packages/widget/1.2.3/widget-1.2.3.tar.gz'
    for proof, key in [('0' * 64, b'registry-key'), (proof_for(value), b'other')]:
        with pytest.raises(ValueError):
            verify_download(proof, key, value, url)

def test_verify_rejects_malformed_proofs():
    value = manifest()
    url = 'https://registry.example/packages/widget/1.2.3/widget-1.2.3.tar.gz'
    for proof in ['', '0' * 63, '0' * 65, 'G' * 64, proof_for(value).upper()]:
        with pytest.raises(ValueError):
            verify_download(proof, b'registry-key', value, url)

def test_verify_rejects_bad_or_unlisted_manifest_entries():
    url = 'https://registry.example/packages/widget/1.2.3/widget-1.2.3.tar.gz'
