    if p.scheme != 'https' or p.netloc != 'registry.example' or p.query or p.fragment:
        raise ValueError('invalid URL')
    bits = p.path.split('/')
    if len(bits) != 6 or bits[1] != 'packages' or (not all(bits[2:])):
        raise ValueError('invalid URL')
    values = tuple((unquote(x) for x in bits[2:]))
    if any((any((c in x for c in '/\\\x00')) for x in values)) or not values[2].endswith('.tar.gz'):
