import hashlib
import hmac
import json
import os

def build_production_report(records: list[dict], start: str, end: str, page: int, page_size: int) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page <= 0:
        raise ValueError('page must be positive')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size <= 0:
        raise ValueError('page_size must be positive')
    try:
        start_dt = datetime.datetime.fromisoformat(start)
        end_dt = datetime.datetime.fromisoformat(end)
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid date range') from exc
    grouped = {}
    for record in records:
        try:
            timestamp = datetime.datetime.fromisoformat(record['timestamp'])
            line = record['line']
            meters = record['meters']
            defects = record['defects']
        except (KeyError, TypeError, ValueError) as exc:
            raise ValueError('invalid record') from exc
        if not isinstance(line, str) or not line or meters < 0 or (defects < 0) or (defects > meters):
            raise ValueError('invalid record')
        if start_dt <= timestamp <= end_dt:
            item = grouped.setdefault(line, [0, 0])
            item[0] += meters
            item[1] += defects
    lines = []
    for line, (meters, defects) in grouped.items():
        efficiency = 0.0 if meters == 0 else round((meters - defects) / meters * 100, 2)
        lines.append({'line': line, 'meters': meters, 'defects': defects, 'efficiency': efficiency})
    lines.sort(key=lambda item: (-item['meters'], item['line']))
    total_lines = len(lines)
    first = (page - 1) * page_size
    body = {'start': start, 'end': end, 'page': page, 'page_size': page_size, 'total_lines': total_lines, 'lines': lines[first:first + page_size]}
    key = os.environ.get('TEXTILE_MONITORING_SIGNING_KEY')
    if key is None:
        raise ValueError('TEXTILE_MONITORING_SIGNING_KEY is required')
    encoded = json.dumps(body, sort_keys=True, separators=(',', ':')).encode()
    body['signature'] = hmac.new(key.encode(), encoded, hashlib.sha256).hexdigest()
    return body

