from solution import verify_and_parse_report
import hashlib
import hmac
import json
import math
import pytest


def make_payload(report):
    return json.dumps(report, separators=(",", ":")).encode("utf-8")


def make_signature(payload, key=b"campaign-key"):
    return hmac.new(key, payload, hashlib.sha256).hexdigest()


def test_valid_report_is_returned():
    report = {"campaign_id": "cmp-42", "impressions": 1200, "clicks": 37, "spend": 91.5}
    payload = make_payload(report)
    assert verify_and_parse_report(payload, make_signature(payload), b"campaign-key") == report


def test_valid_zero_values_are_accepted():
    report = {"campaign_id": "zero", "impressions": 0, "clicks": 0, "spend": 0}
    payload = make_payload(report)
    assert verify_and_parse_report(payload, make_signature(payload), b"campaign-key") == report


def test_wrong_signature_is_rejected():
    report = {"campaign_id": "cmp-1", "impressions": 3, "clicks": 1, "spend": 2.25}
    payload = make_payload(report)
    signature = make_signature(payload)
    replacement = ("0" if signature[0] != "0" else "1") + signature[1:]
    with pytest.raises(ValueError):
        verify_and_parse_report(payload, replacement, b"campaign-key")


def test_signature_from_different_key_is_rejected():
    report = {"campaign_id": "cmp-2", "impressions": 4, "clicks": 2, "spend": 8}
    payload = make_payload(report)
    with pytest.raises(ValueError):
        verify_and_parse_report(payload, make_signature(payload, b"other-key"), b"campaign-key")


def test_malformed_json_is_rejected_after_signature_check():
    payload = b'{"campaign_id":"cmp-3",'
    with pytest.raises(ValueError):
        verify_and_parse_report(payload, make_signature(payload), b"campaign-key")


def test_missing_or_extra_fields_are_rejected():
    missing = {"campaign_id": "cmp-4", "impressions": 1, "clicks": 0}
    payload = make_payload(missing)
    with pytest.raises(ValueError):
        verify_and_parse_report(payload, make_signature(payload), b"campaign-key")
    extra = {"campaign_id": "cmp-4", "impressions": 1, "clicks": 0, "spend": 1, "region": "US"}
    payload = make_payload(extra)
    with pytest.raises(ValueError):
        verify_and_parse_report(payload, make_signature(payload), b"campaign-key")


def test_invalid_field_values_are_rejected():
    cases = [
        {"campaign_id": "", "impressions": 1, "clicks": 1, "spend": 1},
        {"campaign_id": "x", "impressions": -1, "clicks": 1, "spend": 1},
        {"campaign_id": "x", "impressions": True, "clicks": 1, "spend": 1},
        {"campaign_id": "x", "impressions": 1, "clicks": 1.5, "spend": 1},
        {"campaign_id": "x", "impressions": 1, "clicks": 1, "spend": -0.1},
        {"campaign_id": "x", "impressions": 1, "clicks": 1, "spend": float("nan")},
    ]
    for report in cases:
        payload = make_payload(report)
        with pytest.raises(ValueError):
            verify_and_parse_report(payload, make_signature(payload), b"campaign-key")


def test_signature_format_and_input_edges_are_rejected():
    report = {"campaign_id": "cmp-5", "impressions": 1, "clicks": 1, "spend": 1}
    payload = make_payload(report)
    valid = make_signature(payload)
    for signature in ("", valid[:-2], "z" + valid[1:]):
        with pytest.raises(ValueError):
            verify_and_parse_report(payload, signature, b"campaign-key")
    with pytest.raises(ValueError):
        verify_and_parse_report(payload, valid, b"")
    with pytest.raises(ValueError):
        verify_and_parse_report("not-bytes", valid, b"campaign-key")

