import hashlib
import hmac
import json
import os
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def process_dividends(records: list[dict], config: dict | None=None) -> dict:
    key = None
    if config is not None:
        key = config.get('signing_key')
    if key is None:
        key = os.environ.get('DIVIDEND_SIGNING_KEY')
    if not key:
        raise ValueError('DIVIDEND_SIGNING_KEY is required')
    payouts = []
    total = Decimal('0')
    for record in records:
        if not isinstance(record, dict) or set(record) != {'symbol', 'shares', 'dividend_per_share'}:
            raise ValueError('invalid dividend record')
        symbol = record['symbol']
        shares = record['shares']
        if not isinstance(symbol, str) or not symbol:
            raise ValueError('invalid dividend record')
        if isinstance(shares, bool) or not isinstance(shares, int) or shares <= 0:
            raise ValueError('invalid dividend record')
        try:
            rate = Decimal(str(record['dividend_per_share']))
            if not rate.is_finite() or rate <= 0:
                raise ValueError
        except (InvalidOperation, ValueError, TypeError):
            raise ValueError('invalid dividend record')
        rate = rate.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        payment = (rate * shares).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        item = {'symbol': symbol, 'shares': shares, 'dividend_per_share': f'{rate:.2f}', 'payment': f'{payment:.2f}'}
        payouts.append(item)
        total += payment
    payload = json.dumps(payouts, sort_keys=True, separators=(',', ':')).encode('utf-8')
    signature = hmac.new(str(key).encode('utf-8'), payload, hashlib.sha256).hexdigest()
    return {'payouts': payouts, 'total': f'{total:.2f}', 'signature': signature}

