import secrets
_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
_DAYS = {'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'}

def _entries(entries):
    if not isinstance(entries, list):
        raise ValueError()
    totals = {}
    for item in entries:
        if not isinstance(item, dict):
            raise ValueError()
        category = item.get('category')
        minutes = item.get('minutes')
        frequency = item.get('frequency')
        days = item.get('days')
        if not isinstance(category, str) or not category:
            raise ValueError()
        if isinstance(minutes, bool) or not isinstance(minutes, int) or minutes <= 0:
            raise ValueError()
        if isinstance(frequency, bool) or not isinstance(frequency, int) or frequency <= 0:
            raise ValueError()
        if not isinstance(days, list) or not days or len(set(days)) != len(days) or any((x not in _DAYS for x in days)):
            raise ValueError()
        value = minutes * frequency * len(days)
        if category not in totals:
            totals[category] = [0, 0]
        totals[category][0] += value
        totals[category][1] += 1
    return [{'category': k, 'weekly_minutes': v[0], 'entries': v[1]} for k, v in sorted(totals.items(), key=lambda x: (-x[1][0], x[0]))]

def summarize_accommodations(entries: list[dict]) -> list[dict]:
    return _entries(entries)

def create_plan_invite(plan_id: str, student_id: str, entries: list[dict], now: datetime | None=None, valid_days: int=7) -> dict:
    if not isinstance(plan_id, str) or not plan_id or (not isinstance(student_id, str)) or (not student_id):
        raise ValueError()
    if isinstance(valid_days, bool) or not isinstance(valid_days, int) or (not 1 <= valid_days <= 30):
        raise ValueError()
    if now is None:
        now = datetime.now(timezone.utc)
    if not isinstance(now, datetime) or now.tzinfo is None:
        raise ValueError()
    summary = _entries(entries)
    expiry = now.astimezone(timezone.utc) + timedelta(days=valid_days)
    token = ''.join((secrets.choice(_ALPHABET) for _ in range(24)))
    return {'plan_id': plan_id, 'student_id': student_id, 'summary': summary, 'expires_at': expiry.strftime('%Y-%m-%dT%H:%M:%SZ'), 'token': token}

def validate_plan_invite(invite: dict, now: datetime | None=None) -> bool:
    try:
        if not isinstance(invite, dict) or set(invite) != {'plan_id', 'student_id', 'summary', 'expires_at', 'token'}:
            return False
        if not isinstance(invite['plan_id'], str) or not invite['plan_id'] or (not isinstance(invite['student_id'], str)) or (not invite['student_id']):
            return False
        token = invite['token']
        if not isinstance(token, str) or len(token) != 24 or any((c not in _ALPHABET for c in token)):
            return False
        summary = invite['summary']
        if not isinstance(summary, list):
            return False
        previous = None
        seen = set()
        for item in summary:
            if not isinstance(item, dict) or set(item) != {'category', 'weekly_minutes', 'entries'}:
                return False
            c, w, n = (item['category'], item['weekly_minutes'], item['entries'])
            if not isinstance(c, str) or not c or c in seen or isinstance(w, bool) or (not isinstance(w, int)) or (w <= 0) or isinstance(n, bool) or (not isinstance(n, int)) or (n < 0):
                return False
            key = (-w, c)
            if previous is not None and key < previous:
                return False
            previous, _ = (key, seen.add(c))
        if not isinstance(invite['expires_at'], str) or not invite['expires_at'].endswith('Z'):
            return False
        expiry = datetime.fromisoformat(invite['expires_at'][:-1] + '+00:00')
        if now is None:
            now = datetime.now(timezone.utc)
        if not isinstance(now, datetime) or now.tzinfo is None:
            return False
        return expiry > now.astimezone(timezone.utc)
    except (ValueError, TypeError, OverflowError):
        return False

