        if not isinstance(invite['plan_id'], str) or not invite['plan_id'] or (not isinstance(invite['student_id'], str)) or (not invite['student_id']):
            return False
        token = invite['token']
        if not isinstance(token, str) or len(token) != 24 or any((c not in _ALPHABET for c in token)):
            return False
        summary = invite['summary']
        if not isinstance(summary, list):
            return False
        previous = None
        seen = set()
        for item in summary:
            if not isinstance(item, dict) or set(item) != {'category', 'weekly_minutes', 'entries'}:
                return False
            c, w, n = (item['category'], item['weekly_minutes'], item['entries'])
            if not isinstance(c, str) or not c or c in seen or isinstance(w, bool) or (not isinstance(w, int)) or (w <= 0) or isinstance(n, bool) or (not isinstance(n, int)) or (n < 0):
                return False
            key = (-w, c)
            if previous is not None and key < previous:
                return False
            previous, _ = (key, seen.add(c))
        if not isinstance(invite['expires_at'], str) or not invite['expires_at'].endswith('Z'):
