import hashlib
import os

def _digest(secret, salt=None):
    if salt is None:
        salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
    return salt.hex() + ':' + value.hex()

def _check(secret, stored):
    try:
        salt_text, value = stored.split(':', 1)
        salt = bytes.fromhex(salt_text)
    except (ValueError, AttributeError):
        return False
    return hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000).hex() == value

def make_certificate(serial: str, subject: str, issuer: str, not_before: int, not_after: int, secret: str) -> dict:
    if not all((isinstance(x, str) and x for x in (serial, subject, issuer, secret))):
        raise ValueError('invalid certificate text')
    if not isinstance(not_before, int) or not isinstance(not_after, int) or not_before >= not_after:
        raise ValueError('invalid certificate interval')
    return {'serial': serial, 'subject': subject, 'issuer': issuer, 'not_before': not_before, 'not_after': not_after, 'verifier': _digest(secret)}

def verify_certificate_report(certificates: list[dict], secret: str, at_time: int, page: int=1, page_size: int=10) -> dict:
    if not isinstance(certificates, list) or not isinstance(secret, str) or (not isinstance(at_time, int)):
        raise ValueError('invalid report input')
    if not isinstance(page, int) or not isinstance(page_size, int) or page < 1 or (page_size < 1) or (page_size > 100):
        raise ValueError('invalid pagination')
    valid = []
    for item in certificates:
        if not isinstance(item, dict) or any((k not in item for k in ('serial', 'subject', 'issuer', 'not_before', 'not_after', 'verifier'))):
            raise ValueError('malformed certificate')
        if not all((isinstance(item[k], str) and item[k] for k in ('serial', 'subject', 'issuer', 'verifier'))) or not all((isinstance(item[k], int) for k in ('not_before', 'not_after'))):
            raise ValueError('malformed certificate')
        if item['not_before'] >= item['not_after']:
            raise ValueError('malformed certificate')
        if _check(secret, item['verifier']) and item['not_before'] <= at_time <= item['not_after']:
            valid.append(item)
    valid.sort(key=lambda x: (x['not_after'], x['issuer'], x['serial']))
    issuers = {}
    for item in valid:
        issuers[item['issuer']] = issuers.get(item['issuer'], 0) + 1
    issuers = dict(sorted(issuers.items()))
    start = (page - 1) * page_size
    return {'total': len(certificates), 'valid_count': len(valid), 'issuers': issuers, 'certificates': valid[start:start + page_size]}

