def create_rental_invoice(requester: dict, rental: dict, rates: dict) -> dict:
    if not isinstance(requester, dict) or not isinstance(rental, dict) or (not isinstance(rates, dict)):
        raise ValueError('invalid input')
    if not isinstance(requester.get('roles'), list):
        raise ValueError('invalid requester')
    for key in ('rental_id', 'owner_id', 'deposit', 'items'):
