            quantity, days, late = (item['quantity'], item['days'], item['late_days'])
            rate = rates[sku]
            if not isinstance(sku, str) or not sku or any((not isinstance(x, int) or isinstance(x, bool) or x < 0 for x in (quantity, days, late))) or (quantity == 0):
                raise ValueError('invalid item')
            daily, late_rate = (Decimal(str(rate['daily'])), Decimal(str(rate['late'])))
            if daily < 0 or late_rate < 0:
                raise ValueError('negative rate')
        except (KeyError, TypeError, InvalidOperation, ValueError):
            raise ValueError('invalid item')
        if sku in grouped:
            grouped[sku][0] += quantity
            grouped[sku][1] += days
            grouped[sku][2] += late
        else:
            grouped[sku] = [quantity, days, late, daily, late_rate]
    lines = []
    for sku in sorted(grouped):
        quantity, days, late, daily, late_rate = grouped[sku]
        amount = money(quantity * (days * daily + late * late_rate))
        lines.append({'sku': sku, 'quantity': quantity, 'days': days, 'late_days': late, 'amount': f'{amount:.2f}'})
    subtotal = sum((Decimal(x['amount']) for x in lines), Decimal('0.00'))
    return {'rental_id': rental['rental_id'], 'lines': lines, 'subtotal': f'{subtotal:.2f}', 'deposit': f'{deposit:.2f}', 'total': f'{subtotal + deposit:.2f}'}

