def generate_invite_code(length: int=10) -> str:
    alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
    if type(length) is not int or not 6 <= length <= 32:
        raise ValueError('length must be between 6 and 32')
    return ''.join((secrets.choice(alphabet) for _ in range(length)))

def route_tickets(tickets: list[dict], agent_loads: dict[str, int], page: int=1, page_size: int=20) -> list[dict]:
    if type(page) is not int or page < 1 or type(page_size) is not int or (page_size < 1):
        raise ValueError('invalid pagination')
    for name, load in agent_loads.items():
        if not isinstance(name, str) or not name or type(load) is not int or (load < 0):
            raise ValueError('invalid agent')
    eligible = []
    for ticket in tickets:
        try:
            identifier = ticket['id']
            category = ticket['category']
            priority = ticket['priority']
            status = ticket['status']
        except (KeyError, TypeError):
            raise ValueError('invalid ticket')
        if not isinstance(identifier, str) or not isinstance(category, str) or type(priority) is not int or (not 1 <= priority <= 5) or (not isinstance(status, str)):
            raise ValueError('invalid ticket')
        if status in ('open', 'pending'):
            eligible.append((identifier, category, priority))
    if eligible and (not agent_loads):
        raise ValueError('no agents')
    eligible.sort(key=lambda item: (-item[2], item[1], item[0]))
    loads = dict(agent_loads)
    result = []
    for identifier, category, priority in eligible:
        agent = min(loads, key=lambda name: (loads[name], name))
        result.append({'id': identifier, 'agent': agent})
        loads[agent] += 1
    start = (page - 1) * page_size
    return result[start:start + page_size]

