from collections.abc import Mapping

def build_leaderboard(entries: list[dict], page: int=1, page_size: int=10, config: Mapping[str, str] | None=None) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('page must be a positive integer')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('page_size must be a positive integer')
    if config is not None and 'signing_key' in config:
        key = config['signing_key']
    else:
        key = os.environ.get('LEADERBOARD_SIGNING_KEY')
    if not isinstance(key, str) or not key:
        raise ValueError('missing signing key')
    best = {}
    for item in entries:
        if not isinstance(item, dict):
            raise ValueError('invalid entry')
        if set(item) != {'player', 'score', 'timestamp'}:
            raise ValueError('invalid entry')
        player, score, timestamp = (item['player'], item['score'], item['timestamp'])
        if not isinstance(player, str) or not player or (not isinstance(score, int)) or isinstance(score, bool) or (score < 0) or (not isinstance(timestamp, str)) or (not timestamp):
            raise ValueError('invalid entry')
        old = best.get(player)
        if old is None or score > old['score'] or (score == old['score'] and timestamp < old['timestamp']):
            best[player] = {'player': player, 'score': score, 'timestamp': timestamp}
    ordered = sorted(best.values(), key=lambda x: (-x['score'], x['timestamp'], x['player']))
    rows = []
    previous = None
    for position, item in enumerate(ordered, 1):
        if item['score'] != previous:
            rank = position
            previous = item['score']
