    unsigned = {'page': page, 'page_size': page_size, 'total_players': len(rows), 'rows': rows[start:start + page_size]}
    body = json.dumps(unsigned, sort_keys=True, separators=(',', ':')).encode()
    unsigned['signature'] = hmac.new(key.encode(), body, hashlib.sha256).hexdigest()
    return unsigned

