    rows = list(csv.reader(io.StringIO(text)))
    if not rows or rows[0] != ['name', 'duration', 'width', 'height', 'tags']:
        raise ValueError('invalid header')
    result = []
    seen = set()
    for row in rows[1:]:
        if not row or all((not x for x in row)):
            continue
        if len(row) != 5:
            raise ValueError('invalid row')
        name, duration, width, height, tags = row
        if not name or name in seen:
            raise ValueError('invalid name')
        try:
            d = float(duration)
            w = int(width)
            h = int(height)
        except (TypeError, ValueError):
            raise ValueError('invalid number')
        if d < 0 or w <= 0 or h <= 0:
            raise ValueError('invalid value')
        seen.add(name)
        result.append({'name': name, 'duration': d, 'width': w, 'height': h, 'tags': [x.strip() for x in tags.split(';') if x.strip()]})
    return result

def build_transcode_plan(records: list[dict], max_pixels: int) -> dict:
    if not isinstance(max_pixels, int) or isinstance(max_pixels, bool) or max_pixels <= 0:
        raise ValueError('invalid limit')
    items = []
    for r in records:
        try:
            name, d, w, h, tags = (r[k] for k in ('name', 'duration', 'width', 'height', 'tags'))
        except (KeyError, TypeError):
            raise ValueError('invalid record')
        if not isinstance(name, str) or not name or (not isinstance(d, (int, float))) or isinstance(d, bool) or (d < 0):
            raise ValueError('invalid record')
        if not all((isinstance(x, int) and (not isinstance(x, bool)) and (x > 0) for x in (w, h))) or not isinstance(tags, list):
            raise ValueError('invalid record')
        pixels = w * h
        if pixels <= max_pixels:
            items.append({'name': name, 'duration': float(d), 'width': w, 'height': h, 'pixels': pixels, 'tags': list(tags)})
    items.sort(key=lambda x: (-x['duration'], -x['pixels'], x['name']))
    return {'total_duration': float(sum((x['duration'] for x in items))), 'total_pixels': sum((x['pixels'] for x in items)), 'assets': items}

def extract_assets(zip_path: str, output_dir: str, manifest_text: str) -> list[str]:
    records = parse_manifest(manifest_text)
    base = Path(output_dir).resolve()
    base.mkdir(parents=True, exist_ok=True)
    result = []
    with zipfile.ZipFile(zip_path) as archive:
        members = {x.filename: x for x in archive.infolist()}
        for record in records:
            name = record['name']
            if name not in members:
                raise FileNotFoundError(name)
            info = members[name]
            if info.is_dir():
                raise ValueError('directory member')
            target = (base / name).resolve()
            try:
                target.relative_to(base)
            except ValueError:
                raise ValueError('path outside output')
            target.parent.mkdir(parents=True, exist_ok=True)
            with archive.open(info) as source, open(target, 'wb') as dest:
                while True:
                    chunk = source.read(65536)
                    if not chunk:
                        break
                    dest.write(chunk)
            result.append(str(target))
    return result

