import os
import tempfile
import pytest


def write_records(text):
    fd, path = tempfile.mkstemp()
    with os.fdopen(fd, "w") as f:
        f.write(text)
    return path


def test_parse_episode_line_trims_fields():
    assert parse_episode_line("  90 | 45 | Evening News  ") == (90, 45, "Evening News")


def test_parse_episode_line_rejects_bad_records():
    for line in ("", "1|2", "1|2|", "x|2|Show", "1|x|Show", "1|0|Show", "1|-3|Show", "1|2|A|B"):
        with pytest.raises(ValueError):
            parse_episode_line(line)


def test_schedule_orders_and_selects_nonoverlapping_records():
    path = write_records("30|20|Later\n0|30|Alpha\n20|15|Overlap\n50|10|Final\n")
    try:
        assert schedule_episodes(path, 0, 70) == [(0, 30, "Alpha"), (30, 50, "Later"), (50, 60, "Final")]
    finally:
        os.unlink(path)


def test_schedule_uses_title_as_tie_breaker():
    path = write_records("10|5|Zulu\n10|5|Alpha\n15|5|End\n")
    try:
