import os
import subprocess

def parse_episode_line(line: str) -> tuple[int, int, str]:
    fields = line.split('|')
    if len(fields) != 3:
        raise ValueError('invalid episode record')
    try:
        start = int(fields[0].strip())
        duration = int(fields[1].strip())
    except ValueError as exc:
        raise ValueError('invalid episode record') from exc
    title = fields[2].strip()
    if not title or duration <= 0:
        raise ValueError('invalid episode record')
    return (start, duration, title)

def schedule_episodes(path: str, day_start: int, day_end: int) -> list[tuple[int, int, str]]:
    if day_start > day_end:
        raise ValueError('invalid window')
    if not os.path.isfile(path):
        raise FileNotFoundError(path)
    result = subprocess.run(['sort', '-t|', '-k1,1n', '-k3,3', path], capture_output=True, text=True, check=True)
    selected = []
    previous_end = None
    for raw in result.stdout.splitlines():
        if not raw.strip():
            continue
        start, duration, title = parse_episode_line(raw)
        end = start + duration
        if start < day_start or end > day_end:
            continue
        if previous_end is None or start >= previous_end:
            selected.append((start, end, title))
            previous_end = end
    return selected

def schedule_summary(path: str, day_start: int, day_end: int) -> dict[str, int | None]:
    episodes = schedule_episodes(path, day_start, day_end)
    if not episodes:
        return {'count': 0, 'total_minutes': 0, 'first_start': None, 'last_end': None}
    return {'count': len(episodes), 'total_minutes': sum((end - start for start, end, _ in episodes)), 'first_start': episodes[0][0], 'last_end': episodes[-1][1]}

