def create_agent(agent_id: str, password: str) -> dict:
    if not isinstance(agent_id, str) or not agent_id.strip() or (not isinstance(password, str)) or (not password.strip()):
        raise ValueError('invalid agent')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return {'agent_id': agent_id.strip(), 'credential': salt.hex() + ':' + digest.hex()}

def authenticate_agent(record: dict, agent_id: str, password: str) -> bool:
    if not isinstance(record, dict) or not isinstance(agent_id, str) or (not isinstance(password, str)):
        return False
    try:
        stored = record['credential'].split(':')
        if len(stored) != 2 or record['agent_id'] != agent_id.strip():
            return False
        salt = bytes.fromhex(stored[0])
        expected = bytes.fromhex(stored[1])
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (KeyError, AttributeError, ValueError, TypeError):
        return False

def _time(value):
    if not isinstance(value, str) or not value.endswith('Z'):
        raise ValueError('invalid timestamp')
    try:
        result = datetime.fromisoformat(value[:-1] + '+00:00')
    except ValueError:
        raise ValueError('invalid timestamp')
    if result.tzinfo is None:
        raise ValueError('invalid timestamp')
    return result.astimezone(timezone.utc)

def summarize_baggage(events: list[dict], cutoff: str) -> list[dict]:
    if not isinstance(events, list):
