        if any((not isinstance(event[k], str) for k in event)):
            raise ValueError('invalid event')
        bag = event['bag_id'].strip()
        flight = event['flight'].strip()
        station = event['station'].strip()
        if not bag or not flight or (not station) or (event['status'] not in {'checked', 'loaded', 'delivered', 'exception'}):
            raise ValueError('invalid event')
        moment = _time(event['timestamp'])
        if moment <= limit and (bag not in latest or moment >= latest[bag][0]):
            latest[bag] = (moment, index, flight, station, event['status'])
    groups = {}
    for bag, (_, _, flight, station, status) in latest.items():
        groups.setdefault(flight, []).append({'bag_id': bag, 'station': station, 'status': status})
    result = []
    for flight in sorted(groups):
        bags = sorted(groups[flight], key=lambda x: x['bag_id'])
        row = {'flight': flight, 'checked': 0, 'loaded': 0, 'delivered': 0, 'exception': 0, 'bags': bags}
        for bag in bags:
            row[bag['status']] += 1
        result.append(row)
    return result

