import hashlib
import hmac
import json
import math
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from typing import Any

def process_enrollment_webhook(body: str, signature: str, secret: bytes) -> dict[str, Any]:
    expected = hmac.new(secret, body.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    data = json.loads(body)
    if not isinstance(data, dict) or not isinstance(data.get('enrollments'), list):
        raise ValueError('invalid enrollment data')
    seen = set()
    groups: dict[str, list[Decimal]] = {}
    for item in data['enrollments']:
        if not isinstance(item, dict):
            raise ValueError('invalid enrollment record')
        if not all((isinstance(item.get(k), str) and item[k] for k in ('employee_id', 'plan', 'status'))):
            raise ValueError('invalid enrollment record')
        employee = item['employee_id']
        if employee in seen:
            raise ValueError('duplicate employee')
        seen.add(employee)
        premium = item.get('monthly_premium')
        if isinstance(premium, bool) or not isinstance(premium, (int, float)) or (not math.isfinite(premium)) or (premium < 0):
            raise ValueError('invalid premium')
        try:
            amount = Decimal(str(premium))
        except (InvalidOperation, ValueError):
            raise ValueError('invalid premium')
        if item['status'] == 'active':
            groups.setdefault(item['plan'], []).append(amount)

    def money(value: Decimal) -> float:
        return float(value.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
    plans = []
    grand = Decimal('0')
    count = 0
    for name in sorted(groups):
        total = sum(groups[name], Decimal('0'))
        plans.append({'name': name, 'enrolled': len(groups[name]), 'monthly_total': money(total)})
        grand += total
        count += len(groups[name])
    return {'plans': plans, 'employee_count': count, 'monthly_total': money(grand)}

