import subprocess

def summarize_robot_status(directory: str, status: str, page: int, page_size: int) -> list[dict]:
    if status not in {'IDLE', 'RUNNING', 'FAULT'}:
        raise ValueError('unsupported status')
    if page < 1 or page_size < 1 or page > 10000 or (page_size > 10000):
        raise ValueError('invalid pagination')
    root = Path(directory)
    if not root.exists():
        raise FileNotFoundError(directory)
    if not root.is_dir():
        raise NotADirectoryError(directory)
    files = sorted((p for p in root.iterdir() if p.is_file() and p.name.endswith('.log')))
    if not files:
        return []
    result = subprocess.run(['grep', '-h', '--', status, *[str(p) for p in files]], capture_output=True, text=True)
    if result.returncode not in (0, 1):
        raise RuntimeError(result.stderr)
    grouped = {}
    for line in result.stdout.splitlines():
        fields = line.split(',')
        if len(fields) != 4 or fields[2] != status:
            continue
        try:
            duration = float(fields[3])
        except ValueError:
            continue
        if duration < 0:
            continue
        robot = fields[0]
        if not robot:
            continue
        item = grouped.setdefault(robot, [0, 0.0])
        item[0] += 1
        item[1] += duration
    rows = []
    for robot, (count, total) in grouped.items():
        rounded_total = round(total, 2)
        rows.append({'robot': robot, 'count': count, 'total_seconds': rounded_total, 'average_seconds': round(total / count, 2)})
    rows.sort(key=lambda x: (-x['total_seconds'], x['robot']))
    start = (page - 1) * page_size
    return rows[start:start + page_size]

