    bad = ['a|b|9:00|2', 'a|b|09:00|0', 'a|b|24:00|2', 'a|b|12:60|2', '|b|12:00|2', 'a| |12:00|2', 'a|b|12:00|-2', 'a|b|12:00|2|extra', 'a|b|12:00|2\\']
    for value in bad:
        with pytest.raises(ValueError):
            parse_registrations(value)

def test_invite_code_shape_and_length_validation():
    alphabet = set('ABCDEFGHJKLMNPQRSTUVWXYZ23456789')
    for length in (6, 10, 32):
        code = generate_invite_code(length)
        assert len(code) == length
        assert set(code) <= alphabet
    for length in (0, 5, 33, -1):
        with pytest.raises(ValueError):
            generate_invite_code(length)

