        current = []
        escaped = False
        for char in raw:
            if escaped:
                current.append(char)
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == '|':
                fields.append(''.join(current).strip())
                current = []
            else:
                current.append(char)
        if escaped:
            raise ValueError('trailing escape')
