            raise ValueError('invalid time')
        if not re.fullmatch('[0-9]+', fields[3]) or int(fields[3]) <= 0:
            raise ValueError('invalid duration')
        hour, minute = map(int, fields[2].split(':'))
        result.append({'name': fields[0], 'company': fields[1], 'arrival': hour * 60 + minute, 'duration': int(fields[3])})
    return result

def generate_invite_code(length: int=10) -> str:
    if not isinstance(length, int) or isinstance(length, bool) or (not 6 <= length <= 32):
        raise ValueError('invalid length')
    alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
    return ''.join((random.choice(alphabet) for _ in range(length)))

def plan_visits(records: list[dict], room_count: int) -> list[dict]:
    if not isinstance(room_count, int) or isinstance(room_count, bool) or room_count <= 0:
        raise ValueError('invalid room count')
    required = {'name', 'company', 'arrival', 'duration'}
    prepared = []
    for record in records:
        if not isinstance(record, dict) or set(record) != required:
            raise ValueError('invalid record')
        if not isinstance(record['name'], str) or not isinstance(record['company'], str) or (not isinstance(record['arrival'], int)) or (not isinstance(record['duration'], int)) or isinstance(record['arrival'], bool) or isinstance(record['duration'], bool) or (record['arrival'] < 0) or (record['arrival'] >= 1440) or (record['duration'] <= 0):
            raise ValueError('invalid record')
        prepared.append(record)
    prepared.sort(key=lambda x: (x['arrival'], -x['duration'], x['name'], x['company']))
    ends = [0] * room_count
    output = []
    for record in prepared:
        choices = [i for i, end in enumerate(ends) if end <= record['arrival']]
        if not choices:
            raise ValueError('no room')
        room = min(choices)
        ends[room] = record['arrival'] + record['duration']
        output.append({**record, 'room': room + 1})
    return output

