import sqlite3

def create_claims_table(conn):
    conn.execute('CREATE TABLE IF NOT EXISTS claims (id INTEGER PRIMARY KEY, claimant TEXT NOT NULL, status TEXT NOT NULL, amount REAL NOT NULL, filed_at TEXT NOT NULL, description TEXT NOT NULL)')
    conn.commit()

def add_claims(conn, claims):
    allowed = {'pending', 'approved', 'rejected', 'paid'}
    req = ('claimant', 'status', 'amount', 'filed_at', 'description')
    vals = []
    try:
        for x in claims:
            if any((k not in x for k in req)):
                raise ValueError()
            a, s, n, f, d = (x[k] for k in req)
            if not isinstance(a, str) or not a.strip() or (not isinstance(d, str)) or (not isinstance(f, str)):
                raise ValueError()
            if not isinstance(s, str) or s not in allowed or isinstance(n, bool) or (not isinstance(n, (int, float))) or (n < 0):
                raise ValueError()
            vals.append((a, s, float(n), f, d))
        conn.executemany('INSERT INTO claims (claimant,status,amount,filed_at,description) VALUES (?,?,?,?,?)', vals)
        conn.commit()
    except Exception:
        conn.rollback()
        raise

def list_claims(conn, statuses=(), search='', minimum_amount=None, maximum_amount=None, sort_by='filed_at'):
    allowed = {'pending', 'approved', 'rejected', 'paid'}
    cols = {'id', 'claimant', 'status', 'amount', 'filed_at'}
    if any((not isinstance(s, str) or s not in allowed for s in statuses)) or sort_by not in cols:
        raise ValueError()
    if any((v is not None and (isinstance(v, bool) or not isinstance(v, (int, float))) for v in (minimum_amount, maximum_amount))):
        raise ValueError()
    if minimum_amount is not None and maximum_amount is not None and (minimum_amount > maximum_amount):
        raise ValueError()
    w = []
    p = []
    if statuses:
        w.append('status IN (' + ','.join(('?' for _ in statuses)) + ')')
        p += list(statuses)
    if search:
        w.append('(lower(claimant) LIKE lower(?) OR lower(description) LIKE lower(?))')
        p += ['%' + search + '%'] * 2
    if minimum_amount is not None:
        w.append('amount >= ?')
        p.append(minimum_amount)
    if maximum_amount is not None:
        w.append('amount <= ?')
        p.append(maximum_amount)
    q = 'SELECT id,claimant,status,amount,filed_at,description FROM claims' + (' WHERE ' + ' AND '.join(w) if w else '') + ' ORDER BY ' + sort_by + ', id'
    return [dict(zip(('id', 'claimant', 'status', 'amount', 'filed_at', 'description'), r)) for r in conn.execute(q, p)]

