import ast

def evaluate_expression(expression: str, variables: dict[str, int | float | bool]) -> int | float | bool:
    try:
        tree = ast.parse(expression, mode='eval')
        allowed = (ast.Expression, ast.Constant, ast.Name, ast.BinOp, ast.UnaryOp, ast.BoolOp, ast.Compare, ast.Call, ast.Load, ast.Add, ast.Sub, ast.Mult, ast.Div, ast.UAdd, ast.USub, ast.Not, ast.And, ast.Or, ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE)
        for node in ast.walk(tree):
            if not isinstance(node, allowed):
                raise ValueError()
            if isinstance(node, ast.Constant) and (not isinstance(node.value, (int, float, bool))):
                raise ValueError()
            if isinstance(node, ast.Name) and node.id not in variables and (node.id not in {'min', 'max', 'round'}):
                raise ValueError()

        def run(node):
            if isinstance(node, ast.Expression):
                return run(node.body)
            if isinstance(node, ast.Constant):
                return node.value
            if isinstance(node, ast.Name):
                return variables[node.id] if node.id in variables else node.id
            if isinstance(node, ast.BinOp):
                a, b = (run(node.left), run(node.right))
                return {ast.Add: lambda: a + b, ast.Sub: lambda: a - b, ast.Mult: lambda: a * b, ast.Div: lambda: a / b}[type(node.op)]()
            if isinstance(node, ast.UnaryOp):
                a = run(node.operand)
                return +a if isinstance(node.op, ast.UAdd) else -a if isinstance(node.op, ast.USub) else not a
            if isinstance(node, ast.BoolOp):
                value = run(node.values[0])
                for item in node.values[1:]:
                    if isinstance(node.op, ast.And) and (not value):
                        return value
                    if isinstance(node.op, ast.Or) and value:
                        return value
                    value = run(item)
                return value
            if isinstance(node, ast.Compare):
                left = run(node.left)
                for op, part in zip(node.ops, node.comparators):
                    right = run(part)
                    if not {ast.Eq: lambda: left == right, ast.NotEq: lambda: left != right, ast.Lt: lambda: left < right, ast.LtE: lambda: left <= right, ast.Gt: lambda: left > right, ast.GtE: lambda: left >= right}[type(op)]():
                        return False
                    left = right
                return True
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (not node.keywords) and (node.func.id in {'min', 'max', 'round'}):
                args = [run(x) for x in node.args]
                if node.func.id == 'round' and len(args) not in (1, 2) or (node.func.id != 'round' and (not args)):
                    raise ValueError()
                return {'min': min, 'max': max, 'round': round}[node.func.id](*args)
            raise ValueError()
        result = run(tree)
        return round(result, 12) if isinstance(result, float) else result
    except Exception as exc:
        if isinstance(exc, ValueError):
            raise
        raise ValueError() from exc

def build_review_report(reviews: list[dict], expression: str, minimum_score: int | float=0) -> dict:
    kept = []
    for review in reviews:
        scores = review['scores']
        if not scores:
            raise ValueError()
        env = dict(scores)
        env['overall'] = sum(scores.values()) / len(scores)
        score = evaluate_expression(expression, env)
        if isinstance(score, bool) or not isinstance(score, (int, float)):
            raise ValueError()
        if score >= minimum_score:
            kept.append({'employee': review['employee'], 'department': review['department'], 'status': review['status'], 'score': score})
