def parse_lift_log(text: str) -> list[dict]:
    result = []
    for line in text.splitlines():
        if not line.strip():
            continue
        try:
            fields = next(csv.reader([line]))
        except (csv.Error, StopIteration) as exc:
            raise ValueError('malformed row') from exc
        if len(fields) != 4:
            raise ValueError('malformed row')
        ticket, date, lift, minutes = fields
        ticket = ticket.strip()
        lift = lift.strip()
        if not ticket or not lift or len(date) != 10:
            raise ValueError('invalid field')
        try:
            datetime.date.fromisoformat(date)
            value = int(minutes.strip())
        except (ValueError, TypeError) as exc:
            raise ValueError('invalid field') from exc
        if value <= 0 or str(value) != minutes.strip():
            raise ValueError('invalid minutes')
        result.append({'ticket_id': ticket, 'date': date, 'lift': lift, 'minutes': value})
    return result

def summarize_lift_usage(text: str, config: dict | None=None) -> list[dict]:
    rows = parse_lift_log(text)
    groups = {}
    for row in rows:
        group = groups.setdefault(row['ticket_id'], {'days': set(), 'total_minutes': 0, 'lifts': {}})
        group['days'].add(row['date'])
        group['total_minutes'] += row['minutes']
        group['lifts'][row['lift']] = group['lifts'].get(row['lift'], 0) + 1
    if config is not None and 'api_secret' in config:
