        key = os.environ.get('HEALTH_REPORT_KEY')
    if not isinstance(key, str) or not key:
        raise ValueError('missing signing key')
    entries = []
    counts = {}
    for resource in resources:
        metadata = resource.get('metadata')
        if not isinstance(metadata, dict) or not isinstance(metadata.get('name'), str) or (not metadata['name']):
            raise ValueError('resource metadata.name is required')
        namespace = metadata.get('namespace') if isinstance(metadata.get('namespace'), str) and metadata.get('namespace') else 'default'
        kind = resource.get('kind') if isinstance(resource.get('kind'), str) and resource.get('kind') else 'Unknown'
        state = classify_resource(resource)
        entries.append({'namespace': namespace, 'kind': kind, 'name': metadata['name'], 'status': state})
        bucket = counts.setdefault(namespace, {'healthy': 0, 'unhealthy': 0, 'unknown': 0, 'total': 0})
        bucket[state] += 1
        bucket['total'] += 1
    entries.sort(key=lambda x: (x['namespace'], x['kind'], x['name']))
    totals = {'healthy': 0, 'unhealthy': 0, 'unknown': 0, 'total': 0}
    for bucket in counts.values():
        for field in totals:
            totals[field] += bucket[field]
    report = {'resources': entries, 'namespaces': counts, 'totals': totals}
    raw = json.dumps(report, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode('utf-8')
    report['signature'] = hmac.new(key.encode('utf-8'), raw, hashlib.sha256).hexdigest()
    return report

