def _value(node, env):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, str, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id in env:
            return env[node.id]
        raise NameError(node.id)
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
        v = _value(node.operand, env)
        return +v if isinstance(node.op, ast.UAdd) else -v if isinstance(node.op, ast.USub) else not v
    if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div, ast.Mod, ast.Pow):
        a, b = (_value(node.left, env), _value(node.right, env))
        return {ast.Add: lambda: a + b, ast.Sub: lambda: a - b, ast.Mult: lambda: a * b, ast.Div: lambda: a / b, ast.Mod: lambda: a % b, ast.Pow: lambda: a ** b}[type(node.op)]()
    if isinstance(node, ast.BoolOp):
        vals = [_value(x, env) for x in node.values]
        if isinstance(node.op, ast.And):
            return next((x for x in vals if not x), vals[-1])
        return next((x for x in vals if x), vals[-1])
    if isinstance(node, ast.Compare):
