    try:
        tree = ast.parse(text, mode='eval')
    except SyntaxError as e:
        raise ValueError('invalid expression') from e
    return _value(tree.body, env)

def analyze(readings: list[dict], rule: str, score: str, variables: dict) -> list[dict]:
