from pathlib import Path


def make_route(contents):
    handle = tempfile.NamedTemporaryFile(mode="w", encoding="utf-8", delete=False)
    try:
        handle.write(contents)
        return handle.name
    finally:
        handle.close()


def test_sorts_stop_names_and_keeps_duplicates():
    path = make_route("Maple Street\nElm Street\nMaple Street\nOak Avenue\n")
    try:
        assert sorted_bus_stops(path, 10) == [
            "Elm Street",
            "Maple Street",
            "Maple Street",
            "Oak Avenue",
        ]
    finally:
        Path(path).unlink()


def test_omits_empty_lines():
    path = make_route("\nPine Road\n\nAsh Lane\n\n")
    try:
        assert sorted_bus_stops(path, 10) == ["Ash Lane", "Pine Road"]
    finally:
        Path(path).unlink()


