def moderate_posts(posts: list[dict], page: int=1, page_size: int=10, config: dict | None=None) -> dict:
    if not isinstance(posts, list):
        raise TypeError('posts must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('invalid page size')
    token = None if config is None else config.get('api_token')
    if token is None:
        token = os.environ.get('MODERATION_API_TOKEN')
    if not token:
        raise ValueError('missing moderation API token')
    seen = set()
    results = []
    for post in posts:
        if not isinstance(post, dict):
            raise TypeError('post must be a dictionary')
        ident = post.get('id')
        text = post.get('text')
        if not isinstance(ident, str) or not ident or (not isinstance(text, str)) or (not text):
            raise ValueError('invalid post')
        if ident in seen:
            raise ValueError('duplicate id')
        seen.add(ident)
        response = requests.post('https://moderation.example.test/v1/classify', json={'text': text}, headers={'Authorization': 'Bearer ' + str(token)})
        response.raise_for_status()
        data = response.json()
        label = data.get('label') if isinstance(data, dict) else None
        score = data.get('score') if isinstance(data, dict) else None
        if label not in {'safe', 'review', 'remove'} or isinstance(score, bool) or (not isinstance(score, (int, float))) or (not 0 <= score <= 1):
            raise ValueError('invalid API result')
        results.append({'id': ident, 'text': text, 'label': label, 'score': round(score, 3)})
