    chosen = {}
    for item in records:
        required = ('animal_id', 'vaccine', 'administered', 'interval_days', 'dose')
        if any((key not in item for key in required)):
            raise ValueError('missing field')
        animal = item['animal_id']
        vaccine = item['vaccine']
        interval = item['interval_days']
        dose = item['dose']
        if not isinstance(animal, str) or not animal or (not isinstance(vaccine, str)) or (not vaccine):
            raise ValueError('invalid text')
        if isinstance(interval, bool) or not isinstance(interval, int) or interval < 0:
            raise ValueError('invalid interval')
        if isinstance(dose, bool) or not isinstance(dose, int) or dose <= 0:
            raise ValueError('invalid dose')
        try:
            administered = date.fromisoformat(item['administered'])
        except (TypeError, ValueError):
            raise ValueError('invalid date')
        key = (animal, vaccine, dose)
        if key not in chosen or administered > chosen[key][0]:
            chosen[key] = (administered, interval)
    result = []
    for (animal, vaccine, dose), (administered, interval) in chosen.items():
        due = administered + timedelta(days=interval)
        status = 'overdue' if due < target else 'due' if due == target else 'current'
        result.append({'animal_id': animal, 'vaccine': vaccine, 'dose': dose, 'administered': administered.isoformat(), 'due_date': due.isoformat(), 'status': status})
    result.sort(key=lambda row: (row['animal_id'], row['vaccine'], row['dose']))
    return result

