import json
import os

def _split_fields(line):
    fields = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            current.append('\x00' if char == ',' else char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('dangling escape')
    fields.append(''.join(current))
    return fields

def parse_menu(text: str) -> list[dict]:
    result = []
    for line in text.splitlines():
        if not line.strip():
            continue
        fields = _split_fields(line)
        if len(fields) != 4:
            raise ValueError('invalid menu row')
        name, dietary, price_text, tags_text = fields
        if dietary not in {'vegan', 'vegetarian', 'standard'}:
            raise ValueError('invalid dietary category')
        try:
            price = round(float(price_text), 2)
        except (TypeError, ValueError):
            raise ValueError('invalid price')
        if price <= 0:
            raise ValueError('invalid price')
        tags = sorted((x.replace('\x00', ',').strip().lower() for x in tags_text.split(',') if x.strip()))
        result.append({'name': name, 'dietary': dietary, 'price': price, 'tags': tags})
    return result

def plan_menu(guests: list[dict], dishes: list[dict], budget: float) -> dict:
    if budget < 0:
        raise ValueError('invalid budget')
    names = set()
    selected = []
    for guest in guests:
        if guest['name'] in names:
            raise ValueError('duplicate guest')
        names.add(guest['name'])
        diet = guest['diet']
        allowed = {'vegan'} if diet == 'vegan' else {'vegan', 'vegetarian'} if diet == 'vegetarian' else {'vegan', 'vegetarian', 'standard'}
        allergies = {str(x).lower() for x in guest.get('allergies', [])}
        choices = [(d['price'], d['name'], i, d) for i, d in enumerate(dishes) if d['dietary'] in allowed and (not allergies.intersection(d['tags']))]
        if not choices:
            raise ValueError('no suitable dish')
        selected.append((min(choices), guest['name']))
    total = round(sum((choice[0][0] for choice in selected)), 2)
    if total > budget + 0.005:
        raise ValueError('budget exceeded')
    grouped = {}
    for choice, guest_name in selected:
        grouped.setdefault(choice[1], [choice[3], []])[1].append(guest_name)
    items = []
    for name in sorted(grouped):
        dish, guest_names = grouped[name]
        items.append({'dish': name, 'guests': guest_names, 'quantity': len(guest_names), 'unit_price': dish['price']})
    return {'items': items, 'total': total}

def sign_plan(plan: dict, config: dict | None=None) -> dict:
    key = None if config is None else config.get('signing_key')
    if not key:
        key = os.environ.get('MENU_SIGNING_KEY')
    if not key:
        raise ValueError('missing signing key')
    raw = json.dumps(plan, sort_keys=True, separators=(',', ':')).encode('utf-8')
    digest = hmac.new(str(key).encode('utf-8'), raw, hashlib.sha256).hexdigest()
    return {'plan': plan, 'signature': digest}

