import tempfile

def parse_report(text: str) -> list[dict]:
    lines = [line for line in text.splitlines() if line.strip()]
    if not lines:
        raise ValueError('empty report')
    try:
        rows = list(csv.reader(lines, skipinitialspace=False, strict=True))
    except csv.Error as exc:
        raise ValueError('invalid csv') from exc
    expected = ['sample_id', 'depth_cm', 'n', 'p', 'k', 'ph']
    if len(rows[0]) != 6 or [x.strip() for x in rows[0]] != expected:
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if len(row) != 6:
            raise ValueError('invalid row')
        row = [x.strip() for x in row]
        if not row[0]:
            raise ValueError('empty sample')
        try:
            values = [float(x) for x in row[1:]]
        except ValueError as exc:
            raise ValueError('invalid number') from exc
        if any((not math.isfinite(x) for x in values)):
            raise ValueError('nonfinite number')
        if values[0] < 0 or any((x < 0 for x in values[1:4])) or (not 0 <= values[4] <= 14):
            raise ValueError('out of range')
        result.append(dict(zip(expected, [row[0]] + values)))
    return result

def aggregate_samples(records: list[dict]) -> list[dict]:
    groups = {}
    for record in records:
        groups.setdefault(record['sample_id'], []).append(record)
    result = []
    for sample_id, rows in groups.items():
        result.append({'sample_id': sample_id, 'readings': len(rows), 'avg_n': round(sum((x['n'] for x in rows)) / len(rows), 2), 'avg_p': round(sum((x['p'] for x in rows)) / len(rows), 2), 'avg_k': round(sum((x['k'] for x in rows)) / len(rows), 2), 'median_ph': round(statistics.median((x['ph'] for x in rows)), 2), 'max_depth': round(max((x['depth_cm'] for x in rows)), 2)})
    return sorted(result, key=lambda x: (-x['avg_n'], str(x['sample_id'])))

def write_summary(records: list[dict], destination: str) -> None:
    fields = ['sample_id', 'readings', 'avg_n', 'avg_p', 'avg_k', 'median_ph', 'max_depth']
    fd, temporary = tempfile.mkstemp(prefix='.summary-', dir=os.path.dirname(os.path.abspath(destination)))
    try:
        with os.fdopen(fd, 'w', newline='') as stream:
            writer = csv.DictWriter(stream, fieldnames=fields, lineterminator='\n')
            writer.writeheader()
            writer.writerows(aggregate_samples(records))
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise

