import hashlib
import hmac
import json

def verify_webhook(raw: str, secret: bytes) -> dict:
    try:
        if raw.count('\n\n') != 1:
            raise ValueError()
        header, body = raw.split('\n\n')
        if not header.startswith('v1 ') or len(header) != 67:
            raise ValueError()
        supplied = header[3:]
        if any((c not in '0123456789abcdef' for c in supplied)):
            raise ValueError()
        expected = hmac.new(secret, body.encode('utf-8'), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(supplied, expected):
            raise ValueError()
        value = json.loads(body)
        if not isinstance(value, dict) or not isinstance(value.get('events'), list):
            raise ValueError()
        for event in value['events']:
            if not isinstance(event, dict) or set(event) != {'case_id', 'action', 'occurred_at', 'priority'}:
                raise ValueError()
            if not isinstance(event['case_id'], str) or not event['case_id']:
                raise ValueError()
            if not isinstance(event['occurred_at'], str) or not event['occurred_at']:
                raise ValueError()
            if event['action'] not in ('open', 'note', 'close'):
                raise ValueError()
            if type(event['priority']) is not int or not 1 <= event['priority'] <= 5:
                raise ValueError()
        return value
    except (UnicodeError, json.JSONDecodeError, TypeError, ValueError):
        raise ValueError()

def summarize_cases(events: list[dict]) -> list[dict]:
    ordered = sorted(enumerate(events), key=lambda p: (p[1]['occurred_at'], p[0]))
    states = {}
    for _, event in ordered:
        case_id = event['case_id']
        action = event['action']
        if action == 'open':
            states[case_id] = {'case_id': case_id, 'status': 'open', 'priority': event['priority'], 'notes': 0, 'last_at': event['occurred_at']}
        elif case_id in states:
            state = states[case_id]
            state['priority'] = event['priority']
            state['last_at'] = event['occurred_at']
            if action == 'note':
                state['notes'] += 1
            else:
                state['status'] = 'closed'
    return sorted(states.values(), key=lambda x: (-x['priority'], x['case_id']))

