        if isinstance(order['promised_minute'], bool) or not isinstance(order['promised_minute'], int) or order['promised_minute'] < 0:
            raise ValueError('invalid order')
        distance = order['distance_km']
        if isinstance(distance, bool) or not isinstance(distance, (int, float)) or distance < 0:
            raise ValueError('invalid order')
        seen.add(oid)
        groups.setdefault(zone, []).append(order)
    result = []
    for zone in sorted(groups):
        entries = sorted(groups[zone], key=lambda x: (-x['priority'], x['promised_minute'], x['distance_km'], x['order_id']))
        batches = []
        for order in entries:
            if not batches or len(batches[-1]) >= capacity or order['promised_minute'] - batches[-1][0]['promised_minute'] > max_window:
