    return result

def _path(base_dir, relative_name):
    if not isinstance(relative_name, str) or not relative_name:
        raise ValueError('invalid name')
    return os.path.join(base_dir, relative_name)

def save_dispatch_plan(base_dir: str, relative_name: str, plan: list[dict]) -> str:
    target = _path(base_dir, relative_name)
    os.makedirs(os.path.dirname(target), exist_ok=True)
    with open(target, 'w', encoding='utf-8') as handle:
        json.dump(plan, handle, indent=2, sort_keys=True)
        handle.write('\n')
    return target

def load_dispatch_plan(base_dir: str, relative_name: str) -> list[dict]:
    target = _path(base_dir, relative_name)
    with open(target, encoding='utf-8') as handle:
        return json.load(handle)

