import base64
import hashlib
import hmac
import os

def make_curator_record(username: str, password: str, joined_year: int) -> dict:
    if not isinstance(username, str) or not username or (not isinstance(password, str)) or (not password):
        raise ValueError
    if not isinstance(joined_year, int) or isinstance(joined_year, bool) or (not 1000 <= joined_year <= 9999):
        raise ValueError
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    credential = base64.b64encode(salt).decode() + '$' + value.hex()
    return {'username': username, 'credential': credential, 'joined_year': joined_year}

def verify_curator_password(record: dict, password: str) -> bool:
    if not isinstance(password, str) or not isinstance(record, dict):
        return False
    try:
        salt_text, digest = record['credential'].split('$', 1)
        salt = base64.b64decode(salt_text, validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000).hex()
        return hmac.compare_digest(actual, digest)
    except (KeyError, ValueError, TypeError, UnicodeError):
        return False

def parse_catalog(text: str) -> list[dict]:
    if not isinstance(text, str):
        raise ValueError
    result = []
    seen = set()
    for line in text.splitlines():
        if not line.strip():
            continue
        fields, current, escaped = ([], [], False)
        for char in line:
            if escaped:
                if char not in '|\\':
                    raise ValueError
                current.append(char)
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == '|':
                fields.append(''.join(current))
                current = []
            else:
                current.append(char)
        if escaped:
            raise ValueError
        fields.append(''.join(current))
        if len(fields) != 4 or not fields[0] or (not fields[1]) or (fields[0] in seen):
            raise ValueError
        try:
            year, visits = (int(fields[2].strip()), int(fields[3].strip()))
        except ValueError:
            raise ValueError
        if not 1000 <= year <= 9999 or visits < 0:
            raise ValueError
        seen.add(fields[0])
        result.append({'id': fields[0], 'title': fields[1], 'year': year, 'visits': visits})
    return result

def catalog_summary(records: list[dict], first_year: int, last_year: int) -> list[dict]:
    if first_year > last_year:
        raise ValueError
    totals = {year: [0, 0] for year in range(first_year, last_year + 1)}
    for record in records:
        year = record['year']
        if year in totals:
            totals[year][0] += 1
            totals[year][1] += record['visits']
    return [{'year': year, 'exhibits': totals[year][0], 'visits': totals[year][1]} for year in totals]

