import hashlib
import hmac
import json

def rank_signed_reputation(payload: str, signature: str, secret: str, page: int=1, page_size: int=3) -> list[dict]:
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('invalid page size')
    if not isinstance(payload, str) or not isinstance(signature, str) or (not isinstance(secret, str)):
        raise ValueError('invalid input')
    expected = hmac.new(secret.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if len(signature) != 64 or any((c not in '0123456789abcdef' for c in signature)) or (not hmac.compare_digest(expected, signature)):
        raise ValueError('invalid signature')
    try:
        document = json.loads(payload)
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(document, dict) or not isinstance(document.get('votes'), list):
        raise ValueError('invalid payload')
    totals = {}
    for vote in document['votes']:
        if not isinstance(vote, dict):
            raise ValueError('invalid vote')
        username = vote.get('username')
        post_id = vote.get('post_id')
        value = vote.get('value')
        if not isinstance(username, str) or username == '':
            raise ValueError('invalid username')
        if isinstance(post_id, bool) or not isinstance(post_id, int) or post_id <= 0:
            raise ValueError('invalid post id')
        if isinstance(value, bool) or not isinstance(value, int) or value not in (-1, 1):
            raise ValueError('invalid value')
        if post_id not in totals:
            totals[post_id] = [0, 0]
        totals[post_id][0] += value
        totals[post_id][1] += 1
    ordered = sorted(totals.items(), key=lambda item: (-item[1][0], item[0]))
    results = [{'post_id': post_id, 'score': values[0], 'votes': values[1]} for post_id, values in ordered]
    start = (page - 1) * page_size
    return results[start:start + page_size]

