from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from lxml import etree

def summarize_bids(xml: str, page: int=1, page_size: int=10, min_cpm: float=0.0) -> list[dict]:
    if page < 1 or page_size < 1 or min_cpm < 0:
        raise ValueError('invalid paging or threshold')
    try:
        threshold = Decimal(str(min_cpm))
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml.encode(), parser=parser)
    except (etree.XMLSyntaxError, InvalidOperation, UnicodeError) as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'bidFeed':
        raise ValueError('invalid root')
    groups = {}
    for node in root.findall('bid'):
        if node.get('status') != 'active':
            continue
        try:
            campaign = node.attrib['campaign']
            bidder = node.attrib['bidder']
            cpm = Decimal(node.attrib['cpm'])
            impressions = int(node.attrib['impressions'])
            if not campaign or not bidder or cpm < 0 or (impressions < 0):
                raise ValueError
        except (KeyError, ValueError, InvalidOperation):
            raise ValueError('invalid bid')
        if cpm < threshold:
            continue
        if campaign not in groups:
            groups[campaign] = {'impressions': 0, 'bids': 0, 'bidders': set(), 'spend': Decimal('0')}
        group = groups[campaign]
        group['impressions'] += impressions
        group['bids'] += 1
        group['bidders'].add(bidder)
        group['spend'] += cpm * impressions / Decimal('1000')
    rows = []
    for campaign, group in groups.items():
        spend = group['spend'].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        rows.append({'campaign': campaign, 'impressions': group['impressions'], 'bids': group['bids'], 'unique_bidders': len(group['bidders']), 'spend': float(spend)})
    rows.sort(key=lambda row: (-row['spend'], row['campaign']))
    start = (page - 1) * page_size
    return rows[start:start + page_size]

