_FIELDS = {'app', 'version', 'channel', 'status', 'submitted_at', 'notes'}
_CHANNELS = {'internal': 0, 'beta': 1, 'stable': 2}
_STATUSES = ('queued', 'building', 'released', 'failed')
_VERSION = re.compile('^(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)(?:-([0-9A-Za-z]+(?:\\.[0-9A-Za-z]+)*))?$')

def parse_version(version: str) -> tuple[int, int, int, tuple[str, ...]]:
    if not isinstance(version, str):
        raise ValueError('invalid version')
    match = _VERSION.fullmatch(version)
    if not match:
        raise ValueError('invalid version')
    tail = tuple(match.group(4).split('.')) if match.group(4) else ()
    return (int(match.group(1)), int(match.group(2)), int(match.group(3)), tail)

def _timestamp(value):
    if not isinstance(value, str) or not re.fullmatch('\\d{4}-\\d\\d-\\d\\dT\\d\\d:\\d\\d:\\d\\d(?:\\.\\d+)?Z', value):
        raise ValueError('invalid timestamp')
    try:
        return datetime.datetime.fromisoformat(value[:-1]).replace(tzinfo=datetime.timezone.utc)
    except ValueError:
        raise ValueError('invalid timestamp')

def export_release_train(records: list[dict[str, str]], destination: str) -> dict[str, object]:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    parent = os.path.dirname(os.path.abspath(destination))
    if not os.path.isdir(parent):
        raise FileNotFoundError(parent)
    checked = []
    for record in records:
        if not isinstance(record, dict) or set(record) != _FIELDS or any((not isinstance(v, str) for v in record.values())):
            raise ValueError('invalid record')
        parsed = parse_version(record['version'])
        if record['channel'] not in _CHANNELS or record['status'] not in _STATUSES:
            raise ValueError('invalid category')
        stamp = _timestamp(record['submitted_at'])
        checked.append((record, parsed, stamp))
    checked.sort(key=lambda x: (x[0]['app'], tuple((-n for n in x[1][:3])), 0 if x[1][3] == () else 1, _CHANNELS[x[0]['channel']], x[2]))
    fd, temporary = tempfile.mkstemp(dir=parent, prefix='.release-')
    os.close(fd)
    try:
        with open(temporary, 'w', newline='', encoding='utf-8') as stream:
            writer = csv.DictWriter(stream, fieldnames=['app', 'version', 'channel', 'status', 'submitted_at', 'notes'], lineterminator='\n')
            writer.writeheader()
            writer.writerows((item[0] for item in checked))
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    status = {name: 0 for name in _STATUSES}
    channel = {name: 0 for name in _CHANNELS}
    for record, _, _ in checked:
        status[record['status']] += 1
        channel[record['channel']] += 1
    return {'rows': len(checked), 'apps': sorted({item[0]['app'] for item in checked}), 'by_status': status, 'by_channel': channel}

