from copy import deepcopy
from datetime import date, datetime
from pathlib import Path

def _within(base, name):
    root = Path(base).resolve()
    candidate = (root / name).resolve()
    try:
        candidate.relative_to(root)
    except ValueError:
        raise ValueError('path outside base directory')
    return str(candidate)

def _time(value):
    try:
        return datetime.strptime(value, '%H:%M')
    except ValueError:
        raise ValueError('invalid time')

def _date(value):
    try:
        date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid date')

def assign_staff(roster, shifts):
    people = deepcopy(roster)
    seen = set()
    for person in people:
        if set(person) != {'id', 'name', 'certifications', 'availability', 'hours'}:
            raise ValueError('invalid roster')
        if person['id'] in seen or person['hours'] < 0:
            raise ValueError('invalid roster')
        seen.add(person['id'])
        person['certifications'] = {x.strip() for x in person['certifications'].split(',') if x.strip()}
        person['availability'] = {x.strip() for x in person['availability'].split(',') if x.strip()}
        for value in person['availability']:
            _date(value)
    ordered = []
    for shift in shifts:
        if set(shift) != {'date', 'start', 'end', 'required_cert', 'slots'}:
            raise ValueError('invalid shift')
        _date(shift['date'])
        start, end = (_time(shift['start']), _time(shift['end']))
        if end <= start or not isinstance(shift['slots'], int) or shift['slots'] <= 0:
            raise ValueError('invalid shift')
        ordered.append((shift, (shift['date'], shift['start'], shift['end'], shift['required_cert']), (end - start).seconds / 3600))
    ordered.sort(key=lambda x: x[1])
    result = []
    for shift, _, duration in ordered:
        eligible = [p for p in people if shift['date'] in p['availability'] and shift['required_cert'] in p['certifications']]
        eligible.sort(key=lambda p: (p['hours'], p['name'].lower(), p['id']))
        if len(eligible) < shift['slots']:
            raise ValueError('not enough staff')
        chosen = eligible[:shift['slots']]
        for p in chosen:
            p['hours'] += duration
        result.append({'date': shift['date'], 'start': shift['start'], 'end': shift['end'], 'required_cert': shift['required_cert'], 'staff_ids': [p['id'] for p in chosen]})
    return result

def generate_report(base_dir, roster_name, report_name, shifts):
    roster_path = _within(base_dir, roster_name)
    report_path = _within(base_dir, report_name)
    with open(roster_path, newline='', encoding='utf-8') as f:
        rows = list(csv.DictReader(f))
    assignments = assign_staff([{**r, 'hours': float(r['hours'])} for r in rows], shifts)
    lines = ['Airport Security Staffing Report']
    lines += [f"{a['date']} {a['start']}-{a['end']} {a['required_cert']}: {','.join(a['staff_ids'])}" for a in assignments]
    text = '\n'.join(lines) + '\n'
    Path(report_path).parent.mkdir(parents=True, exist_ok=True)
