from datetime import date, datetime, timedelta
_FIELDS = ('patient_id', 'clinician_id', 'specialty', 'started_at', 'duration_minutes', 'status')
_STATUSES = {'completed', 'cancelled', 'no_show'}

def _check_date(value):
    try:
        return date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def build_consultation_report(records, start_date, end_date):
    first, last = (_check_date(start_date), _check_date(end_date))
    if first > last:
        raise ValueError('invalid range')
    days = {}
    groups = {}
    current = first
    while current <= last:
        key = current.isoformat()
        days[key] = {'date': key, 'consultations': 0, 'completed': 0, 'completed_minutes': 0}
        current += timedelta(days=1)
    total = 0
    minutes = 0
    for record in records:
        if any((field not in record for field in _FIELDS)):
            raise ValueError('missing field')
        try:
            stamp = datetime.fromisoformat(record['started_at'].replace('Z', '+00:00'))
            day = stamp.date()
            duration = record['duration_minutes']
            specialty = record['specialty']
            status = record['status']
        except (TypeError, ValueError, AttributeError):
            raise ValueError('invalid record')
        if stamp.tzinfo is None or not isinstance(duration, int) or isinstance(duration, bool) or (duration < 0) or (status not in _STATUSES):
            raise ValueError('invalid record')
        if day < first or day > last:
            continue
        key = day.isoformat()
        days[key]['consultations'] += 1
        total += 1
        item = groups.setdefault(specialty, [0, 0, 0])
        item[0] += 1
        if status == 'completed':
            days[key]['completed'] += 1
            days[key]['completed_minutes'] += duration
            minutes += duration
            item[1] += duration
            item[2] += 1
    specialties = []
    for name, (count, done_minutes, done_count) in groups.items():
        specialties.append({'specialty': name, 'consultations': count, 'completed_minutes': done_minutes, 'average_completed_minutes': round(done_minutes / done_count, 2) if done_count else 0.0})
    specialties.sort(key=lambda x: (-x['completed_minutes'], x['specialty']))
    return {'total_consultations': total, 'completed_minutes': minutes, 'by_specialty': specialties, 'daily': list(days.values())}

def sign_consultation_report(records, start_date, end_date, config=None):
    report = build_consultation_report(records, start_date, end_date)
    key = config.get('signing_key') if config is not None else None
    if not key:
        key = os.environ.get('TELEMEDICINE_SIGNING_KEY')
    if not isinstance(key, str) or not key:
        raise ValueError('missing signing key')
    encoded = json.dumps(report, sort_keys=True, separators=(',', ':'))
    signature = hmac.new(key.encode(), encoded.encode(), hashlib.sha256).hexdigest()
    return json.dumps({'report': report, 'signature': signature}, sort_keys=True, separators=(',', ':'))

