import os

def hash_pin(pin: str) -> str:
    if not isinstance(pin, str):
        raise TypeError()
    if not pin:
        raise ValueError()
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return 'pbkdf2$100000$' + salt.hex() + '$' + value.hex()

def verify_pin(pin: str, stored: str) -> bool:
    if not isinstance(pin, str) or not pin or (not isinstance(stored, str)):
        return False
    parts = stored.split('$')
    if len(parts) != 4 or parts[0] != 'pbkdf2':
        return False
    try:
        rounds = int(parts[1])
        salt = bytes.fromhex(parts[2])
        expected = bytes.fromhex(parts[3])
    except ValueError:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, rounds)
    return actual == expected

