import hashlib, hmac, json, pytest

def make_report(body, secret="audit-key"):
    if isinstance(body, dict):
        body = json.dumps(body, separators=(",", ":"), ensure_ascii=False)
    key = secret.encode() if isinstance(secret, str) else secret
    sig = hmac.new(key, body.encode("utf-8"), hashlib.sha256).hexdigest()
    return "signature=" + sig + "\n" + body

def test_empty_report_has_stable_shape():
    assert verify_report(make_report({"findings": []}), "audit-key") == {"total": 0, "by_severity": {"critical": 0, "high": 0, "medium": 0, "low": 0}, "open_controls": [], "findings": []}

def test_summary_normalizes_and_sorts_nested_data():
    body = {"findings": [{"id": "B-2", "severity": "low", "status": "open", "control": "C9", "tags": ["z", "a", "z"]}, {"id": "A-2", "severity": "critical", "status": "closed", "control": "C2", "tags": []}, {"id": "A-1", "severity": "critical", "status": "open", "control": "C1", "tags": ["b", "a"]}, {"id": "M-1", "severity": "medium", "status": "open", "control": "C9", "tags": ["x"]}]}
    result = verify_report(make_report(body), "audit-key")
    assert result["total"] == 4
    assert result["by_severity"] == {"critical": 2, "high": 0, "medium": 1, "low": 1}
    assert result["open_controls"] == ["C1", "C9"]
    assert result["findings"] == [{"id": "A-1", "severity": "critical", "status": "open", "control": "C1", "tags": ["a", "b"]}, {"id": "A-2", "severity": "critical", "status": "closed", "control": "C2", "tags": []}, {"id": "M-1", "severity": "medium", "status": "open", "control": "C9", "tags": ["x"]}, {"id": "B-2", "severity": "low", "status": "open", "control": "C9", "tags": ["a", "z"]}]

def test_ties_use_id_then_control():
    findings = [{"id": "same", "severity": "high", "status": "closed", "control": "Z"}, {"id": "same", "severity": "high", "status": "closed", "control": "A"}]
    with pytest.raises(ValueError, match="invalid report"):
        summarize_findings({"findings": findings})
    findings[1]["id"] = "alpha"
