import hashlib
import hmac
import json
_SEVERITIES = ('critical', 'high', 'medium', 'low')
_STATUSES = {'open', 'closed'}

def _invalid():
    raise ValueError('invalid report')

def _validated(report):
    if not isinstance(report, dict) or not isinstance(report.get('findings'), list):
        _invalid()
    seen = set()
    normalized = []
    for item in report['findings']:
        if not isinstance(item, dict) or set(item) - {'id', 'severity', 'status', 'control', 'tags'} or (not all((key in item for key in ('id', 'severity', 'status', 'control')))):
            _invalid()
        ident, control, severity, status = (item['id'], item['control'], item['severity'], item['status'])
        if not isinstance(ident, str) or not ident or (not isinstance(control, str)) or (not control) or (severity not in _SEVERITIES) or (status not in _STATUSES) or (ident in seen):
            _invalid()
        tags = item.get('tags', [])
        if not isinstance(tags, list) or not all((isinstance(tag, str) for tag in tags)):
            _invalid()
        seen.add(ident)
        normalized.append({'id': ident, 'severity': severity, 'status': status, 'control': control, 'tags': sorted(set(tags))})
    return normalized

def summarize_findings(report: dict) -> dict:
    findings = _validated(report)
    ordered = sorted(findings, key=lambda x: (_SEVERITIES.index(x['severity']), x['id'], x['control']))
    counts = {level: 0 for level in _SEVERITIES}
    controls = set()
    for item in findings:
        counts[item['severity']] += 1
        if item['status'] == 'open':
            controls.add(item['control'])
    return {'total': len(findings), 'by_severity': counts, 'open_controls': sorted(controls), 'findings': ordered}

def verify_report(raw: str, secret: str | bytes) -> dict:
    if not isinstance(raw, str) or '\n' not in raw:
        _invalid()
    header, body = raw.split('\n', 1)
    if not header.startswith('signature=') or len(header) != 74:
        _invalid()
    supplied = header[10:]
    try:
        actual = bytes.fromhex(supplied)
        if len(actual) != 32:
            _invalid()
        key = secret.encode('utf-8') if isinstance(secret, str) else secret
        if not isinstance(key, bytes) or not hmac.compare_digest(actual, hmac.new(key, body.encode('utf-8'), hashlib.sha256).digest()):
            _invalid()
        report = json.loads(body)
    except (UnicodeError, TypeError, ValueError, json.JSONDecodeError):
        _invalid()
    return summarize_findings(report)

