import hmac
import json

def _quarter(date):
    return f'{date.year}-Q{(date.month - 1) // 3 + 1}'

def _payload(records):
    groups = {}
    total = 0
    for r in records:
        if set(r) != {'date', 'category', 'amount', 'deductible'}:
            raise ValueError('invalid record')
        if not isinstance(r['date'], str) or not isinstance(r['category'], str) or (not r['category']):
            raise ValueError('invalid record')
        if not isinstance(r['amount'], int) or isinstance(r['amount'], bool) or r['amount'] < 0:
            raise ValueError('invalid record')
        if not isinstance(r['deductible'], bool):
            raise ValueError('invalid record')
        try:
            d = datetime.date.fromisoformat(r['date'])
        except (ValueError, TypeError):
            raise ValueError('invalid record')
        q = _quarter(d)
        groups.setdefault(q, {})
        item = groups[q].setdefault(r['category'], [0, 0])
        item[0] += r['amount']
        if r['deductible']:
            item[1] += r['amount']
        total += r['amount']
    quarters = []
    for q in sorted(groups):
        cats = [{'name': n, 'total': groups[q][n][0]} for n in sorted(groups[q])]
        quarters.append({'quarter': q, 'categories': cats, 'deductible_total': sum((x[1] for x in groups[q].values()))})
    return {'version': 1, 'total': total, 'quarters': quarters}

def _encode(data):
    raw = json.dumps(data, sort_keys=True, separators=(',', ':')).encode()
    return base64.urlsafe_b64encode(raw).decode().rstrip('=')

def build_return(records: list[dict], key_id: str, signing_key: bytes) -> str:
    if not isinstance(signing_key, bytes):
        raise TypeError('key')
    if not isinstance(key_id, str) or not key_id or '|' in key_id:
        raise ValueError('key id')
    payload = _encode(_payload(records))
    sig = hmac.new(signing_key, payload.encode(), hashlib.sha256).digest()
    return 'TR1|' + key_id + '|' + base64.urlsafe_b64encode(sig).decode().rstrip('=') + '|' + payload

def verify_return(packet: str, signing_keys: dict[str, bytes]) -> dict:
    if not isinstance(packet, str):
        raise ValueError('packet')
    p = packet.split('|')
    if len(p) != 4 or p[0] != 'TR1' or (not p[1]) or (p[1] not in signing_keys) or (not isinstance(signing_keys[p[1]], bytes)):
        raise ValueError('packet')
    try:
        sig = base64.urlsafe_b64decode(p[2] + '=' * (-len(p[2]) % 4))
        raw = base64.urlsafe_b64decode(p[3] + '=' * (-len(p[3]) % 4))
        obj = json.loads(raw.decode())
    except Exception:
        raise ValueError('packet')
    expected = hmac.new(signing_keys[p[1]], p[3].encode(), hashlib.sha256).digest()
    if not hmac.compare_digest(sig, expected):
        raise ValueError('signature')
    if _encode(obj) != p[3] or obj != _payload_from_payload(obj):
        raise ValueError('payload')
    return obj

def _payload_from_payload(obj):
    if not isinstance(obj, dict) or set(obj) != {'version', 'total', 'quarters'} or obj['version'] != 1:
        raise ValueError('payload')
    if not isinstance(obj['total'], int) or not isinstance(obj['quarters'], list):
        raise ValueError('payload')
    total = 0
    last = ''
    for q in obj['quarters']:
        if set(q) != {'quarter', 'categories', 'deductible_total'} or not isinstance(q['quarter'], str) or q['quarter'] <= last or (not isinstance(q['categories'], list)):
            raise ValueError('payload')
        last = q['quarter']
        names = []
        for c in q['categories']:
