        if not required_run.issubset(run) or run['status'] not in {'success', 'failure'}:
            raise ValueError('invalid run')
        if isinstance(run['duration_seconds'], bool) or not isinstance(run['duration_seconds'], (int, float)):
            raise ValueError('invalid duration')
    roles = requester.get('roles', [])
    visible = [p for p in pipelines if 'warehouse_admin' in roles or (p['tenant_id'] == requester.get('tenant_id') and p['owner_id'] == requester.get('id'))]
    rows = []
    for pipeline in visible:
        matching = [r for r in runs if r['pipeline_id'] == pipeline['id']]
        successes = sum((r['status'] == 'success' for r in matching))
        failures = sum((r['status'] == 'failure' for r in matching))
        average = round(sum((r['duration_seconds'] for r in matching)) / len(matching), 2) if matching else 0.0
        latest = max((r['started_at'] for r in matching), default=None)
        rows.append({'pipeline_id': pipeline['id'], 'name': pipeline['name'], 'success_count': successes, 'failure_count': failures, 'average_duration_seconds': average, 'last_started_at': latest})
