def record_trip(conn: sqlite3.Connection, truck_id: int, shift: str, tons: float, started_at: str, ended_at: str) -> int:
    if tons <= 0:
        raise ValueError('tons must be positive')
    try:
        start = datetime.fromisoformat(started_at)
        end = datetime.fromisoformat(ended_at)
    except (TypeError, ValueError):
        raise ValueError('invalid timestamp')
    if end <= start:
        raise ValueError('end must follow start')
    cur = conn.execute('insert into trips(truck_id, shift, tons, started_at, ended_at) values (?, ?, ?, ?, ?)', (truck_id, shift, tons, started_at, ended_at))
    conn.commit()
    return int(cur.lastrowid)

def dispatch_report(conn: sqlite3.Connection, shift: str, sort_key: str='total_tons') -> list[dict]:
    columns = {'truck_id': 't.id', 'truck_name': 't.name', 'trips': 'count(r.id)', 'total_tons': 'coalesce(sum(r.tons), 0)', 'average_cycle_minutes': 'avg((julianday(r.ended_at) - julianday(r.started_at)) * 1440.0)'}
    if sort_key not in columns:
        raise ValueError('unknown sort key')
    query = 'select t.id, t.name, count(r.id), coalesce(sum(r.tons), 0),\n        avg((julianday(r.ended_at) - julianday(r.started_at)) * 1440.0)\n        from trucks t left join trips r on r.truck_id = t.id and r.shift = ?\n        group by t.id, t.name'
    rows = conn.execute(query, (shift,)).fetchall()
    result = [{'truck_id': r[0], 'truck_name': r[1], 'trips': r[2], 'total_tons': r[3], 'average_cycle_minutes': r[4]} for r in rows]
    result.sort(key=lambda r: (r[sort_key] is None, r[sort_key], r['truck_id']))
    return result

