import hashlib
import hmac
import os

def register_agent(username: str, password: str) -> dict[str, str]:
    if not isinstance(username, str) or not username.strip():
        raise ValueError('invalid username')
    if not isinstance(password, str) or len(password) < 4:
        raise ValueError('invalid password')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return {'username': username.strip(), 'salt': base64.b64encode(salt).decode(), 'password_hash': digest.hex()}

def verify_agent(agent: dict[str, str], password: str) -> bool:
    if not isinstance(agent, dict) or any((key not in agent for key in ('username', 'salt', 'password_hash'))):
        raise ValueError('invalid agent')
    if not isinstance(password, str):
        raise ValueError('invalid password')
    try:
        salt = base64.b64decode(agent['salt'], validate=True)
        expected = bytes.fromhex(agent['password_hash'])
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (KeyError, ValueError, TypeError):
        return False

