    if not isinstance(tickets, list):
        raise ValueError('tickets must be a list')
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError('invalid pagination')
    priorities = {'urgent': 0, 'high': 1, 'normal': 2, 'low': 3}
    allowed = {'open', 'pending', 'escalated', 'closed', 'resolved'}
    chosen = []
    for ticket in tickets:
        if not isinstance(ticket, dict) or any((not isinstance(ticket.get(k), str) for k in ('id', 'status', 'priority', 'created_at'))):
