        if ticket['status'] not in allowed or ticket['priority'] not in priorities:
            raise ValueError('invalid ticket value')
        if ticket['status'] not in {'closed', 'resolved'}:
            chosen.append(ticket)
    chosen.sort(key=lambda t: (priorities[t['priority']], t['created_at'], t['id']))
    start = (page - 1) * page_size
    return [t['id'] for t in chosen[start:start + page_size]]

