import os
from decimal import Decimal, ROUND_HALF_UP

def create_attendance_report(records: list[dict], start: str, end: str, config: dict[str, str] | None=None) -> dict:
    try:
        start_date = datetime.date.fromisoformat(start)
        end_date = datetime.date.fromisoformat(end)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if start_date > end_date or not isinstance(records, list):
        raise ValueError('invalid input')
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        try:
            employee = record['employee_id']
            date_text = record['date']
            minutes = record['minutes']
            status = record['status']
            record_date = datetime.date.fromisoformat(date_text)
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid record')
        if not isinstance(employee, str) or not employee or (not isinstance(date_text, str)) or (not isinstance(minutes, int)) or isinstance(minutes, bool) or (minutes < 0) or (status not in ('approved', 'rejected')):
            raise ValueError('invalid record')
        if status == 'approved' and start_date <= record_date <= end_date:
            item = groups.setdefault(employee, {'minutes': 0, 'dates': set()})
            item['minutes'] += minutes
            item['dates'].add(date_text)
    employees = []
    for employee in sorted(groups):
        total = groups[employee]['minutes']
        hours = float((Decimal(total) / Decimal(60)).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
        employees.append({'employee_id': employee, 'total_minutes': total, 'total_hours': hours, 'dates': sorted(groups[employee]['dates'])})
    body = {'start': start, 'end': end, 'employees': employees}
    key = config.get('ATTENDANCE_SIGNING_KEY') if config is not None and 'ATTENDANCE_SIGNING_KEY' in config else os.environ.get('ATTENDANCE_SIGNING_KEY')
    if not key:
        raise ValueError('missing signing key')
    encoded = json.dumps(body, sort_keys=True, separators=(',', ':')).encode()
    body['signature'] = hmac.new(key.encode(), encoded, hashlib.sha256).hexdigest()
    return body

