    if isinstance(n, ast.BinOp) and type(n.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
        a, b = (_ev(n.left, env), _ev(n.right, env))
        return {ast.Add: lambda: a + b, ast.Sub: lambda: a - b, ast.Mult: lambda: a * b, ast.Div: lambda: a / b}[type(n.op)]()
    if isinstance(n, ast.UnaryOp) and type(n.op) in (ast.UAdd, ast.USub, ast.Not):
        v = _ev(n.operand, env)
        return +v if isinstance(n.op, ast.UAdd) else -v if isinstance(n.op, ast.USub) else not v
