        if not isinstance(entry, dict):
            raise TypeError('each entry must be a dictionary')
        if not all((name in entry for name in ('sku', 'shelf', 'quantity', 'day'))):
            raise ValueError('entry is missing a field')
        sku, shelf, quantity, day = (entry['sku'], entry['shelf'], entry['quantity'], entry['day'])
        if not isinstance(sku, str) or not sku or (not isinstance(shelf, str)) or (not shelf):
