    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    if not isinstance(project, dict) or not isinstance(requester, dict):
        raise ValueError('invalid input')
    required_project = ('id', 'owner_id', 'tenant_id')
    if any((not isinstance(project.get(k), str) for k in required_project)):
        raise ValueError('invalid project')
    if not isinstance(requester.get('id'), str) or not isinstance(requester.get('tenant_id'), str):
        raise ValueError('invalid requester')
    roles = requester.get('roles', [])
    if not isinstance(roles, list) or any((not isinstance(x, str) for x in roles)):
        raise ValueError('invalid roles')
    if requester['tenant_id'] != project['tenant_id'] or (requester['id'] != project['owner_id'] and 'project_manager' not in roles):
        raise PermissionError('not permitted')
    if not isinstance(segments, list):
        raise ValueError('invalid segments')
    groups = {}
    total_words = 0
    total_translated = 0
    total_segments = 0
    for item in segments:
        if not isinstance(item, dict) or item.get('project_id') != project['id']:
