        if any((k not in item for k in ('project_id', 'locale', 'status', 'words', 'translated_words'))):
            raise ValueError('invalid segment')
        if not isinstance(item['locale'], str) or item['status'] not in ('pending', 'translated', 'reviewed'):
            raise ValueError('invalid segment')
