        group[0] += 1
        group[1] += item['words']
        group[2] += item['translated_words']
        total_segments += 1
        total_words += item['words']
        total_translated += item['translated_words']

    def percent(done, total):
        return round(done * 100 / total, 2) if total else 0.0
    locales = [{'locale': locale, 'segments': v[0], 'words': v[1], 'translated_words': v[2], 'completion_percent': percent(v[2], v[1])} for locale, v in sorted(groups.items())]
    start = (page - 1) * page_size
    return {'project_id': project['id'], 'total_segments': total_segments, 'total_words': total_words, 'translated_words': total_translated, 'completion_percent': percent(total_translated, total_words), 'locales': locales[start:start + page_size], 'page': page, 'page_size': page_size, 'total_locales': len(locales)}

