def _decode(value):
    out = []
    current = []
    escaped = False
    for char in value:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape')
    return ''.join(current)

def parse_request(payload: str) -> dict:
    if not isinstance(payload, str) or not payload:
        raise ValueError('invalid payload')
    allowed = {'id', 'requester', 'received', 'due_days', 'topics', 'status'}
    data = {}
    for line in payload.splitlines():
        if not line:
            raise ValueError('empty line')
        left = []
        escaped = False
        split = -1
        for i, char in enumerate(line):
            if escaped:
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == '=':
                split = i
                break
        if split < 1:
            raise ValueError('bad line')
        key = _decode(line[:split])
