    if matching:
        same_tenant = all((r.get('tenant_id') == requester.get('tenant_id') for r in matching))
        manager = requester.get('role') == 'manager' and same_tenant
        owner = all((r.get('owner_id') == requester.get('id') for r in matching)) and same_tenant
        if not (manager or owner):
            raise PermissionError('report access denied')
    counts = {'pending': 0, 'converted': 0, 'rejected': 0}
