        if item.get('status') not in counts:
            raise ValueError('invalid status')
        if not isinstance(item.get('reward_cents'), int) or isinstance(item.get('reward_cents'), bool) or item['reward_cents'] < 0:
            raise ValueError('invalid reward')
        try:
            datetime.fromisoformat(item['created_at'].replace('Z', '+00:00'))
        except (AttributeError, TypeError, ValueError):
            raise ValueError('invalid timestamp')
        counts[item['status']] += 1
    ordered = sorted(matching, key=lambda r: (-datetime.fromisoformat(r['created_at'].replace('Z', '+00:00')).timestamp(), r['id']))
