import csv
import io
import os
from pathlib import Path
import zipfile

def import_ballots(archive_path: str, output_dir: str, page: int, page_size: int) -> list[tuple[str, int]]:
    if page <= 0 or page_size <= 0:
        raise ValueError('page and page_size must be positive')
    base = Path(output_dir).resolve()
    base.mkdir(parents=True, exist_ok=True)
    totals = {}
    with zipfile.ZipFile(archive_path) as archive:
        for info in archive.infolist():
            if info.is_dir() or not info.filename.lower().endswith('.csv'):
                continue
            target = (base / info.filename).resolve()
            if target != base and base not in target.parents:
                raise ValueError('archive member is outside output directory')
            target.parent.mkdir(parents=True, exist_ok=True)
            data = archive.read(info)
            target.write_bytes(data)
            try:
                rows = csv.reader(io.StringIO(data.decode('utf-8')))
                for row in rows:
                    if len(row) != 2:
                        raise ValueError('invalid ballot row')
                    candidate = row[0].strip()
                    if not candidate:
                        raise ValueError('invalid candidate')
                    try:
                        votes = int(row[1].strip())
                    except ValueError:
                        raise ValueError('invalid vote count')
                    if votes < 0:
                        raise ValueError('invalid vote count')
                    totals[candidate] = totals.get(candidate, 0) + votes
            except UnicodeDecodeError:
                raise ValueError('invalid ballot file')
    ordered = sorted(totals.items(), key=lambda item: (-item[1], item[0]))
    start = (page - 1) * page_size
    return ordered[start:start + page_size]

