    conn.commit()

def build_route_report(conn: sqlite3.Connection, driver_id: str | None, start_date: str, end_date: str, sort_by: str='route') -> list[dict]:
    try:
        start = date.fromisoformat(start_date)
        end = date.fromisoformat(end_date)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if start > end or sort_by not in {'route', 'miles', 'count', 'mpg'}:
        raise ValueError('invalid arguments')
    clauses = ['status = ?', 'started_at >= ?', 'started_at < ?']
    params = ['completed', start_date + 'T00:00:00', end_date + 'T00:00:00']
    if driver_id is not None:
        clauses.append('driver_id = ?')
        params.append(driver_id)
    rows = conn.execute('SELECT origin, destination, miles, fuel_gallons FROM trips WHERE ' + ' AND '.join(clauses), params).fetchall()
    grouped = {}
    for origin, destination, miles, fuel in rows:
        key = (origin, destination)
        item = grouped.setdefault(key, [origin, destination, 0, 0.0, 0.0])
        item[2] += 1
        item[3] += miles
        item[4] += fuel
    result = []
    for origin, destination, count, miles, fuel in grouped.values():
        result.append({'origin': origin, 'destination': destination, 'trip_count': count, 'total_miles': round(miles, 2), 'total_fuel_gallons': round(fuel, 2), 'miles_per_gallon': round(miles / fuel, 2)})
    if sort_by == 'route':
        result.sort(key=lambda x: (x['origin'], x['destination']))
    elif sort_by == 'miles':
        result.sort(key=lambda x: (-x['total_miles'], x['origin'], x['destination']))
    elif sort_by == 'count':
        result.sort(key=lambda x: (-x['trip_count'], x['origin'], x['destination']))
    else:
        result.sort(key=lambda x: (-x['miles_per_gallon'], x['origin'], x['destination']))
    return result

