            raise ValueError('invalid record')
        name, hours_text, completed = fields
        if not name or completed not in ('yes', 'no'):
            raise ValueError('invalid record')
        try:
            hours = int(hours_text)
        except ValueError:
            raise ValueError('invalid record')
        if hours < 0:
            raise ValueError('invalid record')
