import hashlib
import hmac

def provision_devices(devices: list[dict], config: dict[str, str]) -> list[dict]:
    if not isinstance(devices, list):
        raise ValueError('devices must be a list')
    if not isinstance(config, dict) or 'PROVISIONING_TOKEN' not in config:
        raise ValueError('PROVISIONING_TOKEN is required')
    token = config['PROVISIONING_TOKEN']
    if not isinstance(token, str):
        raise ValueError('PROVISIONING_TOKEN must be a string')
    prepared = []
    for device in devices:
        if not isinstance(device, dict):
            raise ValueError('each device must be a dictionary')
        required = ('id', 'room', 'model', 'battery', 'priority')
        if any((key not in device for key in required)):
            raise ValueError('device is missing a required field')
        if any((not isinstance(device[key], str) for key in ('id', 'room', 'model'))) or any((device[key] == '' for key in ('id', 'room', 'model'))):
            raise ValueError('invalid text field')
        if isinstance(device['battery'], bool) or not isinstance(device['battery'], int) or (not 0 <= device['battery'] <= 100):
            raise ValueError('invalid battery')
        if isinstance(device['priority'], bool) or not isinstance(device['priority'], int):
            raise ValueError('invalid priority')
        if device['battery'] >= 20:
            prepared.append(device)
    prepared.sort(key=lambda d: (-d['priority'], d['room'], d['id']))
    result = []
    for index, device in enumerate(prepared):
        batch = index // 2 + 1
        text = f"{device['id']}|{device['room']}|{device['model']}|{batch}"
        result.append({'device_id': device['id'], 'room': device['room'], 'model': device['model'], 'batch': batch, 'signature': hmac.new(token.encode(), text.encode(), hashlib.sha256).hexdigest()})
    return result

