from datetime import date

class CoursePortal:

    def __init__(self) -> None:
        self._accounts = {}
        self._subscriptions = []

    def _email(self, email: str) -> str:
        if not isinstance(email, str):
            raise ValueError('invalid email')
        value = email.strip().lower()
        if value.count('@') != 1 or not all(value.split('@')):
            raise ValueError('invalid email')
        return value

    def _day(self, value: str) -> date:
        if not isinstance(value, str):
            raise ValueError('invalid date')
        try:
            parsed = date.fromisoformat(value)
        except ValueError:
            raise ValueError('invalid date')
        if parsed.isoformat() != value:
            raise ValueError('invalid date')
        return parsed

    def _hash(self, password: str) -> str:
        salt = os.urandom(16)
        digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return salt.hex() + '$' + digest.hex()

    def _check(self, password: str, stored: str) -> bool:
        salt, expected = stored.split('$', 1)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), bytes.fromhex(salt), 100000).hex()
        return actual == expected

    def register(self, email: str, password: str) -> bool:
        key = self._email(email)
        if not isinstance(password, str) or len(password) < 4:
            raise ValueError('invalid password')
        if key in self._accounts:
            return False
        self._accounts[key] = self._hash(password)
        return True

    def authenticate(self, email: str, password: str) -> bool:
        key = self._email(email)
        return key in self._accounts and isinstance(password, str) and self._check(password, self._accounts[key])

    def add_subscription(self, email: str, course: str, starts: str, ends: str, price_cents: int) -> bool:
        key = self._email(email)
        if key not in self._accounts:
            return False
        name = course.strip() if isinstance(course, str) else ''
        begin, finish = (self._day(starts), self._day(ends))
        if not name or finish <= begin or (not isinstance(price_cents, int)) or isinstance(price_cents, bool) or (price_cents < 0):
            raise ValueError('invalid subscription')
        for item in self._subscriptions:
            if item[0] == key and item[1] == name and (begin < item[3]) and (item[2] < finish):
                return False
        self._subscriptions.append((key, name, begin, finish, price_cents))
        return True

    def report(self, as_of: str) -> list[dict[str, object]]:
        moment = self._day(as_of)
        grouped = {}
        for email, course, begin, finish, price in self._subscriptions:
            if begin <= moment < finish:
                grouped.setdefault(course, [set(), 0])
                grouped[course][0].add(email)
                grouped[course][1] += price
        result = [{'course': course, 'subscribers': len(values[0]), 'revenue_cents': values[1]} for course, values in grouped.items()]
        return sorted(result, key=lambda row: (-row['revenue_cents'], -row['subscribers'], row['course']))

