import hashlib
import hmac
import json

def _fields(text):
    out = []
    cur = []
    quoted = False
    for ch in text:
        if quoted:
            cur.append(ch)
            quoted = False
        elif ch == '\\':
            quoted = True
        elif ch == '|':
            out.append(''.join(cur))
            cur = []
        else:
            cur.append(ch)
    if quoted:
        raise ValueError('invalid envelope')
    out.append(''.join(cur))
    if len(out) != 4:
        raise ValueError('invalid envelope')
    return out

def verify_and_summarize(document: str, client_keys: dict[str, bytes], now: int) -> dict:
    try:
        client, stamp_text, payload_text, digest = _fields(document)
        stamp = int(stamp_text)
        if client not in client_keys or abs(stamp - now) > 86400:
            raise ValueError('invalid plan')
        expected = hmac.new(client_keys[client], (client + '|' + stamp_text + '|' + payload_text).encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(digest, expected):
            raise ValueError('invalid plan')
        items = json.loads(payload_text)
        if not isinstance(items, list):
            raise ValueError('invalid payload')
        groups = {}
        for item in items:
            if not isinstance(item, dict) or not isinstance(item.get('date'), str) or (not isinstance(item.get('type'), str)):
                raise ValueError('invalid session')
            date = datetime.date.fromisoformat(item['date'])
            minutes = item.get('minutes')
            calories = item.get('calories', 0)
            if isinstance(minutes, bool) or not isinstance(minutes, int) or minutes <= 0 or isinstance(calories, bool) or (not isinstance(calories, int)) or (calories < 0):
                raise ValueError('invalid session')
            week = f'{date.isocalendar().year:04d}-W{date.isocalendar().week:02d}'
            if week not in groups:
                groups[week] = {'sessions': 0, 'minutes': 0, 'calories': 0, 'types': {}}
            group = groups[week]
            group['sessions'] += 1
            group['minutes'] += minutes
            group['calories'] += calories
            typ = item['type']
            if typ not in group['types']:
                group['types'][typ] = {'type': typ, 'sessions': 0, 'minutes': 0, 'calories': 0}
            row = group['types'][typ]
            row['sessions'] += 1
            row['minutes'] += minutes
            row['calories'] += calories
        result = {'client': client, 'timestamp': stamp, 'weeks': {}}
        for week in sorted(groups):
            group = groups[week]
            group['types'] = sorted(group['types'].values(), key=lambda x: (-x['minutes'], x['type']))
            result['weeks'][week] = group
        return result
    except (TypeError, ValueError, OverflowError, json.JSONDecodeError) as exc:
        if isinstance(exc, ValueError) and str(exc) in ('invalid plan', 'invalid payload', 'invalid session', 'invalid envelope'):
            raise
        raise ValueError('invalid plan') from None

