        eligible = record['status'] in {'pending', 'approved'} and record['income'] <= 30000 and (record['days'] >= 90)
        return (not eligible, -record['priority'], -record['days'], record['income'], record['applicant'])
    ordered = sorted(records, key=key)
    names = [record['applicant'] for record in ordered]
    return names if limit is None else names[:limit]

