        {"id": "a", "op": "create", "value": 100, "appraiser": "Lee", "ts": 1},
        {"id": "b", "op": "create", "value": 100, "appraiser": "Kim", "ts": 1},
        {"id": "a", "op": "update", "value": 250, "appraiser": "Kim", "ts": 2},
        {"id": "b", "op": "close", "value": 0, "appraiser": "ignored", "ts": 3},
        {"id": "c", "op": "create", "value": 250, "appraiser": "Lee", "ts": 3},
    ]
    payload = json.dumps({"events": events}, separators=(",", ":"))
    assert verify_and_summarize(payload, signed(payload), b"order-key") == {
        "orders": [
            {"id": "a", "value": 250, "appraiser": "Kim"},
            {"id": "c", "value": 250, "appraiser": "Lee"},
        ],
        "appraisers": [
            {"appraiser": "Kim", "orders": 1, "value": 250},
            {"appraiser": "Lee", "orders": 1, "value": 250},
        ],
    }


