        {"id": "m", "op": "create", "value": 40, "appraiser": "Max", "ts": 3},
    ]
    payload = json.dumps({"events": events}, separators=(",", ":"))
    result = verify_and_summarize(payload, signed(payload), b"order-key")
    assert result["appraisers"] == [
