import hashlib
import hmac
import json

def verify_and_summarize(payload: str, signature: str, secret: bytes) -> dict:
    if not isinstance(payload, str) or not isinstance(signature, str) or (not isinstance(secret, bytes)):
        raise ValueError('invalid input')
    try:
        expected = hmac.new(secret, payload.encode('utf-8'), hashlib.sha256).hexdigest()
        supplied = bytes.fromhex(signature)
    except (UnicodeError, ValueError, TypeError):
        raise ValueError('invalid signature')
    if len(supplied) != hashlib.sha256().digest_size or not hmac.compare_digest(bytes.fromhex(expected), supplied):
        raise ValueError('invalid signature')
    try:
        document = json.loads(payload)
    except (ValueError, TypeError):
        raise ValueError('invalid payload')
    if not isinstance(document, dict) or set(document) != {'events'} or (not isinstance(document['events'], list)):
        raise ValueError('invalid payload')
    active = {}
    last_ts = -1
    for event in document['events']:
        if not isinstance(event, dict) or set(event) != {'id', 'op', 'value', 'appraiser', 'ts'}:
            raise ValueError('invalid event')
        ident, op, value, appraiser, ts = (event[k] for k in ('id', 'op', 'value', 'appraiser', 'ts'))
        if not isinstance(ident, str) or not ident or (not isinstance(op, str)) or (op not in {'create', 'update', 'close'}) or (not isinstance(value, int)) or isinstance(value, bool) or (value < 0) or (not isinstance(appraiser, str)) or (not appraiser) or (not isinstance(ts, int)) or isinstance(ts, bool) or (ts < 0) or (ts < last_ts):
            raise ValueError('invalid event')
        last_ts = ts
        if op == 'create':
            if ident in active:
                raise ValueError('invalid transition')
            active[ident] = {'value': value, 'appraiser': appraiser}
        elif op == 'update':
            if ident not in active:
                raise ValueError('invalid transition')
            active[ident] = {'value': value, 'appraiser': appraiser}
        else:
            if ident not in active:
                raise ValueError('invalid transition')
            del active[ident]
    orders = [{'id': k, **v} for k, v in active.items()]
    orders.sort(key=lambda x: (-x['value'], x['id']))
    totals = {}
    for item in active.values():
        name = item['appraiser']
        if name not in totals:
            totals[name] = [0, 0]
        totals[name][0] += 1
        totals[name][1] += item['value']
    appraisers = [{'appraiser': k, 'orders': v[0], 'value': v[1]} for k, v in totals.items()]
    appraisers.sort(key=lambda x: (-x['value'], -x['orders'], x['appraiser']))
    return {'orders': orders, 'appraisers': appraisers}

