import secrets
import string

def generate_travel_authorization_code(employee_id: str, destination: str, length: int=8) -> str:
    if not isinstance(employee_id, str) or not isinstance(destination, str):
        raise TypeError('employee_id and destination must be strings')
    if not isinstance(length, int) or isinstance(length, bool):
        raise TypeError('length must be an integer')
    employee_id = employee_id.strip()
    destination = destination.strip()
    if not employee_id or not destination:
        raise ValueError('employee_id and destination cannot be empty')
    if length < 6 or length > 32:
        raise ValueError('length must be between 6 and 32')
    alphabet = string.ascii_uppercase + string.digits
    code = ''.join((secrets.choice(alphabet) for _ in range(length)))
    return f'TRV-{employee_id.upper()}-{destination.upper()}-{code}'

