import ast
import operator

def _evaluate(node, values):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in values:
            raise ValueError()
        return values[node.id]
    if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub, ast.Not):
        value = _evaluate(node.operand, values)
        return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
    if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
        left, right = (_evaluate(node.left, values), _evaluate(node.right, values))
        return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
    if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
        value = _evaluate(node.values[0], values)
        for item in node.values[1:]:
            if isinstance(node.op, ast.And) and (not value) or (isinstance(node.op, ast.Or) and value):
                return value
            value = _evaluate(item, values)
        return value
    if isinstance(node, ast.Compare):
        left = _evaluate(node.left, values)
        for op, part in zip(node.ops, node.comparators):
            right = _evaluate(part, values)
            if type(op) not in (ast.Lt, ast.LtE, ast.Eq, ast.NotEq, ast.Gt, ast.GtE):
                raise ValueError()
            if not {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Gt: operator.gt, ast.GtE: operator.ge}[type(op)](left, right):
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
        args = [_evaluate(a, values) for a in node.args]
        if node.func.id == 'round' and len(args) in (1, 2):
            return round(*args)
        if node.func.id in ('min', 'max') and args:
            return min(args) if node.func.id == 'min' else max(args)
    raise ValueError()

def select_rate_limit_clients(records: list[dict], rule: str, page: int=1, page_size: int=10) -> dict:
    if isinstance(page, bool) or isinstance(page_size, bool) or page <= 0 or (page_size <= 0):
        raise ValueError()
    try:
        tree = ast.parse(rule, mode='eval').body
    except Exception as exc:
        raise ValueError() from exc
    matched = []
    for record in records:
        try:
            result = _evaluate(tree, {'used': record['used'], 'quota': record['quota'], 'window': record['window']})
        except Exception as exc:
            raise ValueError() from exc
        if not isinstance(result, bool):
            raise ValueError()
        if result:
            matched.append(record)
    matched.sort(key=lambda r: (-(r['used'] - r['quota']), r['client']))
    total = len(matched)
    start = (page - 1) * page_size
    return {'total': total, 'pages': (total + page_size - 1) // page_size, 'clients': [r['client'] for r in matched[start:start + page_size]], 'used_total': sum((r['used'] for r in matched)), 'over_limit': sum((r['used'] > r['quota'] for r in matched))}

