import hashlib
import hmac
import os

def make_inspector(username: str, password: str) -> dict:
    if not isinstance(username, str) or not username or (not isinstance(password, str)) or (not password):
        raise ValueError('invalid inspector')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return {'username': username, 'password': salt.hex() + '$' + digest.hex()}

def check_password(inspector: dict, password: str) -> bool:
    if not isinstance(inspector, dict) or not isinstance(password, str):
        return False
    try:
        salt_text, expected = inspector['password'].split('$', 1)
        salt = bytes.fromhex(salt_text)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000).hex()
        return hmac.compare_digest(actual, expected)
    except (KeyError, ValueError, TypeError):
        return False

def parse_inspection(line: str) -> dict:
    if not isinstance(line, str):
        raise ValueError('invalid line')
    fields = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape')
    fields.append(''.join(current))
    if len(fields) != 5 or not fields[0] or (not fields[1]) or (fields[2] not in {str(i) for i in range(101)}) or (fields[3] not in {'pass', 'fail', 'rework'}):
        raise ValueError('invalid fields')
    return {'id': fields[0], 'inspector': fields[1], 'score': int(fields[2]), 'status': fields[3], 'notes': fields[4]}

def build_report(lines: list[str], inspectors: dict[str, dict], passwords: dict[str, str]) -> dict:
    records = []
    seen = set()
    for line in lines:
        record = parse_inspection(line)
        name = record['inspector']
        if record['id'] in seen or name not in inspectors or name not in passwords or (not check_password(inspectors[name], passwords[name])):
            raise ValueError('invalid inspection')
        seen.add(record['id'])
        records.append(record)
    statuses = {'pass': 0, 'fail': 0, 'rework': 0}
    grouped = {}
    for record in records:
        statuses[record['status']] += 1
        grouped.setdefault(record['inspector'], []).append(record)
    by_inspector = {}
    for name in sorted(grouped):
        group = grouped[name]
        counts = {'pass': 0, 'fail': 0, 'rework': 0}
        for record in group:
            counts[record['status']] += 1
        by_inspector[name] = {'count': len(group), 'average_score': round(sum((r['score'] for r in group)) / len(group), 2), 'statuses': counts}
    return {'total': len(records), 'by_status': statuses, 'average_score': round(sum((r['score'] for r in records)) / len(records), 2) if records else None, 'by_inspector': by_inspector, 'top': sorted(records, key=lambda r: (-r['score'], r['id']))[:3]}

