    try:
        completed = subprocess.run(['wc', '-l', path], capture_output=True, text=True, check=True)
        int(completed.stdout.split()[0])
        with open(path, newline='', encoding='utf-8') as handle:
            rows = list(csv.reader(handle))
    except (OSError, ValueError, IndexError, subprocess.SubprocessError) as exc:
        raise ValueError('invalid intake file') from exc
    result = []
    seen = set()
    for row in rows:
        if not row or all((not field.strip() for field in row)):
            continue
        if len(row) != 5:
            raise ValueError('invalid row')
        shelter, household, beds_text, priority_text, arrival = [field.strip() for field in row]
        if not shelter or not household or household in seen:
            raise ValueError('invalid household')
        try:
            beds = int(beds_text)
            priority = int(priority_text)
            datetime.datetime.strptime(arrival, '%H:%M')
        except ValueError as exc:
            raise ValueError('invalid row') from exc
        if beds <= 0 or len(arrival) != 5:
            raise ValueError('invalid row')
        seen.add(household)
        result.append((shelter, household, beds, priority, arrival))
    return result

