    remaining = {}
    for shelter, capacity in capacities.items():
        if not isinstance(capacity, int) or isinstance(capacity, bool) or capacity < 0:
            raise ValueError('invalid capacity')
        remaining[shelter] = capacity
    ordered = sorted(entries, key=lambda item: (-item[3], item[4], item[1]))
    result = {shelter: [] for shelter in capacities}
    result['waitlist'] = []
    seen = set()
    for shelter, household, beds, priority, arrival in ordered:
        if household in seen:
            raise ValueError('duplicate household')
        seen.add(household)
        if shelter in remaining and remaining[shelter] >= beds:
            result[shelter].append(household)
            remaining[shelter] -= beds
        else:
            result['waitlist'].append(household)
    return result

def format_report(allocation: dict[str, list[str] | list[str]]) -> str:
    if 'waitlist' not in allocation:
        raise ValueError('missing waitlist')
    lines = []
    for shelter, households in allocation.items():
        if shelter == 'waitlist':
            continue
        lines.append(f"{shelter}: {(','.join(households) if households else '-')}")
    waitlist = allocation['waitlist']
    lines.append(f"WAITLIST: {(','.join(waitlist) if waitlist else '-')}")
    return '\n'.join(lines)

