def parse_dispatch_line(line: str) -> dict:
    if not line.strip():
        raise ValueError('blank line')
    parts = line.rstrip('\n').split(',')
    if len(parts) != 6:
        raise ValueError('invalid field count')
    timestamp, courier, zone, order_id, minutes, fee = parts
    if not courier or not zone or (not order_id):
        raise ValueError('empty field')
    try:
        timestamp = int(timestamp)
        minutes = int(minutes)
        fee = int(fee)
    except ValueError as exc:
        raise ValueError('invalid number') from exc
    if timestamp < 0 or minutes < 0 or fee < 0:
        raise ValueError('negative number')
    return {'timestamp': timestamp, 'courier': courier, 'zone': zone, 'order_id': order_id, 'minutes': minutes, 'fee_cents': fee}

def dispatch_routes(manifest_path: str, capacity: int) -> list[dict]:
    if not isinstance(capacity, int) or isinstance(capacity, bool) or capacity <= 0:
        raise ValueError('capacity must be positive')
    result = subprocess.run(['sort', '-t,', '-k2,2', '-k1,1n', '-k4,4', manifest_path], capture_output=True, text=True, check=True)
    groups = {}
    seen = set()
    for raw in result.stdout.splitlines():
        if not raw.strip():
            continue
        row = parse_dispatch_line(raw)
        if row['order_id'] in seen:
            raise ValueError('duplicate order')
        seen.add(row['order_id'])
        groups.setdefault(row['courier'], []).append(row)
    output = []
    for courier in sorted(groups):
        rows = sorted(groups[courier], key=lambda x: (x['timestamp'], x['order_id']))
        for start in range(0, len(rows), capacity):
            batch = rows[start:start + capacity]
            zones = {}
