import sqlite3

def fetch_events(conn: sqlite3.Connection, min_energy: float, particle: str | None=None, sort_by: str='energy', descending: bool=False, limit: int=100, offset: int=0) -> list[dict[str, object]]:
    if isinstance(min_energy, bool) or not isinstance(min_energy, (int, float)) or (not math.isfinite(min_energy)):
        raise ValueError('min_energy must be finite')
    if particle is not None and (not isinstance(particle, str) or not particle):
        raise ValueError('particle must be nonempty')
    if sort_by not in {'energy', 'particle', 'detector', 'id'}:
        raise ValueError('invalid sort column')
    if isinstance(limit, bool) or not isinstance(limit, int) or (not 1 <= limit <= 1000):
        raise ValueError('invalid limit')
    if isinstance(offset, bool) or not isinstance(offset, int) or offset < 0:
        raise ValueError('invalid offset')
    columns = {'energy': 'energy', 'particle': 'particle', 'detector': 'detector', 'id': 'id'}
    order = 'DESC' if descending else 'ASC'
    sql = 'SELECT id, particle, energy, detector FROM events WHERE energy >= ?'
    values: list[object] = [min_energy]
    if particle is not None:
        sql += ' AND particle = ?'
        values.append(particle)
    sql += f' ORDER BY {columns[sort_by]} {order}, id ASC LIMIT ? OFFSET ?'
    values.extend([limit, offset])
    rows = conn.execute(sql, values).fetchall()
    return [{'id': row[0], 'particle': row[1], 'energy': round(row[2], 3), 'detector': row[3]} for row in rows]

