def build_diversity_report(records: list[dict[str, str]]) -> dict[str, object]:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    counts = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('each record must be a dictionary')
        group = record.get('group')
        if not isinstance(group, str) or not group:
            raise ValueError('group must be a non-empty string')
        counts[group] = counts.get(group, 0) + 1
    groups = {name: counts[name] for name in sorted(counts)}
    total = len(records)
    data = {'total': total, 'groups': groups}
    encoded = json.dumps(data, sort_keys=True, separators=(',', ':')).encode()
    key = os.environ.get('DIVERSITY_REPORT_KEY')
    if key is None:
        raise RuntimeError('DIVERSITY_REPORT_KEY is not set')
    signature = hmac.new(key.encode(), encoded, hashlib.sha256).hexdigest()
    return {'total': total, 'groups': groups, 'signature': signature}

