    if not 0 <= min_score <= 100:
        raise ValueError('min_score out of range')
    if limit < 0 or offset < 0:
        raise ValueError('invalid pagination')
    allowed = {'employee_id', 'average_score', 'passed_count', 'latest_completion'}
    if sort_by not in allowed:
        raise ValueError('invalid sort field')
    ids = list(dict.fromkeys(employee_ids))
    if not ids or limit == 0:
        return []
    placeholders = ','.join(('?' for _ in ids))
    query = f'SELECT employee_id, COUNT(*), AVG(score), SUM(CASE WHEN score >= 70 THEN 1 ELSE 0 END), MAX(completed_on) FROM training_records WHERE employee_id IN ({placeholders}) AND score >= ? GROUP BY employee_id'
    rows = conn.execute(query, [*ids, min_score]).fetchall()
    result = [{'employee_id': r[0], 'course_count': int(r[1]), 'average_score': round(float(r[2]), 2), 'passed_count': int(r[3]), 'latest_completion': r[4]} for r in rows]
    result.sort(key=lambda r: r['employee_id'])
    if sort_by == 'average_score':
        result.sort(key=lambda r: r['average_score'], reverse=True)
    elif sort_by == 'passed_count':
        result.sort(key=lambda r: r['passed_count'], reverse=True)
    elif sort_by == 'latest_completion':
        result.sort(key=lambda r: (r['latest_completion'] is not None, r['latest_completion'] or ''), reverse=True)
