import csv
import os
import tempfile


def make_file(rows):
    handle = tempfile.NamedTemporaryFile(mode="w", encoding="utf-8", newline="", delete=False)
    writer = csv.DictWriter(handle, fieldnames=["county", "precinct", "location", "address"])
    writer.writeheader()
    writer.writerows(rows)
    handle.close()
    return handle.name


def test_sorts_and_returns_all_rows():
    path = make_file([
        {"county": "Zeta", "precinct": "2", "location": "Hall", "address": "3 Main"},
        {"county": "alpha", "precinct": "10", "location": "Gym", "address": "2 Main"},
        {"county": "Alpha", "precinct": "1", "location": "Library", "address": "1 Main"},
    ])
    try:
        result = lookup_polling_places(path)
        assert result == {
            "total": 3,
            "page": 1,
            "page_size": 10,
            "pages": 1,
            "places": [
                {"county": "Alpha", "precinct": "1", "location": "Library", "address": "1 Main"},
                {"county": "alpha", "precinct": "10", "location": "Gym", "address": "2 Main"},
                {"county": "Zeta", "precinct": "2", "location": "Hall", "address": "3 Main"},
            ],
        }
    finally:
        os.unlink(path)


def test_filters_and_paginates():
    path = make_file([
        {"county": "North", "precinct": "3", "location": "C", "address": "C"},
        {"county": "South", "precinct": "1", "location": "S", "address": "S"},
        {"county": "North", "precinct": "1", "location": "A", "address": "A"},
        {"county": "North", "precinct": "2", "location": "B", "address": "B"},
    ])
    try:
        result = lookup_polling_places(path, county="North", page=2, page_size=2)
        assert result["total"] == 3
        assert result["pages"] == 2
        assert result["page"] == 2
        assert result["places"] == [{"county": "North", "precinct": "3", "location": "C", "address": "C"}]
    finally:
        os.unlink(path)


def test_empty_file_has_zero_pages():
    path = make_file([])
    try:
        assert lookup_polling_places(path) == {
            "total": 0, "page": 1, "page_size": 10, "pages": 0, "places": []
        }
    finally:
        os.unlink(path)


def test_out_of_range_page_is_empty():
    path = make_file([
        {"county": "A", "precinct": "1", "location": "One", "address": "X"}
    ])
    try:
        result = lookup_polling_places(path, page=3, page_size=1)
        assert result["total"] == 1
        assert result["pages"] == 1
        assert result["page"] == 3
        assert result["places"] == []
    finally:
        os.unlink(path)


def test_invalid_pagination_raises_value_error():
    path = make_file([])
    try:
        for kwargs in ({"page": 0}, {"page_size": 0}, {"page": -1}, {"page_size": -4}):
            try:
                lookup_polling_places(path, **kwargs)
                assert False
            except ValueError:
                pass
    finally:
        os.unlink(path)


def test_empty_county_is_exact_filter():
    path = make_file([
        {"county": "", "precinct": "2", "location": "Blank", "address": "B"},
        {"county": "A", "precinct": "1", "location": "Other", "address": "A"},
    ])
    try:
        result = lookup_polling_places(path, county="")
        assert result["total"] == 1
        assert result["places"] == [{"county": "", "precinct": "2", "location": "Blank", "address": "B"}]
    finally:
        os.unlink(path)


def test_missing_path_raises_file_not_found():
    try:
        lookup_polling_places("/tmp/this-polling-file-does-not-exist-987654.csv")
        assert False
    except FileNotFoundError:
        pass

