import csv
import math
import os
import subprocess
import io

def lookup_polling_places(file_path: str, county: str | None=None, page: int=1, page_size: int=10) -> dict:
    if page < 1 or page_size < 1:
        raise ValueError('page and page_size must be positive')
    if not os.path.isfile(file_path):
        raise FileNotFoundError(file_path)
    result = subprocess.run(['cat', file_path], capture_output=True, text=True, check=True)
    rows = []
    reader = csv.DictReader(io.StringIO(result.stdout))
    for row in reader:
        item = {key: row[key] for key in ('county', 'precinct', 'location', 'address')}
        if county is None or item['county'] == county:
            rows.append(item)
    rows.sort(key=lambda item: (item['county'].casefold(), item['precinct'].casefold(), item['location'].casefold()))
    total = len(rows)
    pages = math.ceil(total / page_size) if total else 0
    start = (page - 1) * page_size
    return {'total': total, 'page': page, 'page_size': page_size, 'pages': pages, 'places': rows[start:start + page_size]}

