    if type(page) is not int or type(page_size) is not int or page < 1 or (page_size < 1):
        raise ValueError()
    rows = []
    for record in records:
        score = float(round(_evaluate(expression, record['scores']), 2))
        rows.append({'student': record['student'], 'score': score})
    rows.sort(key=lambda row: (-row['score'], row['student']))
