import os

def create_inspector(name: str, pin: str) -> dict:
    if not isinstance(name, str) or not name.strip():
        raise ValueError('invalid name')
    if not isinstance(pin, str) or not pin:
        raise ValueError('invalid pin')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return {'name': name.strip(), 'pin_hash': salt.hex() + '$' + digest.hex()}

def authenticate_inspector(inspector: dict, pin: str) -> bool:
    if not isinstance(inspector, dict) or not isinstance(pin, str):
        return False
    if set(inspector) != {'name', 'pin_hash'} or not isinstance(inspector['pin_hash'], str):
        return False
    try:
        salt_text, digest_text = inspector['pin_hash'].split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def summarize_compliance(records: list[dict], inspector: dict, pin: str, minimum_score: float=0.0, page: int=1, page_size: int=10) -> list[dict]:
    if not authenticate_inspector(inspector, pin):
        raise PermissionError('authentication failed')
    if isinstance(minimum_score, bool) or not isinstance(minimum_score, (int, float)) or (not 0 <= minimum_score <= 100):
