            raise ValueError('invalid record')
        site, score, passed = (record['site'], record['score'], record['passed'])
        if not isinstance(site, str) or not site.strip() or isinstance(score, bool) or (not isinstance(score, (int, float))) or (not 0 <= score <= 100) or (not isinstance(passed, bool)):
            raise ValueError('invalid record')
        if score >= minimum_score:
            item = groups.setdefault(site.strip(), [0, 0, 0.0])
            item[0] += 1
            item[1] += int(passed)
            item[2] += score
    result = [{'site': site, 'count': v[0], 'passed_count': v[1], 'average_score': round(v[2] / v[0], 2)} for site, v in groups.items()]
