import csv
import os
import subprocess
from datetime import date, datetime, timedelta
_HEADER = ['case_id', 'date', 'start', 'duration', 'room', 'priority', 'participants']

def load_hearings(path: str) -> list[dict]:
    try:
        f = open(path, newline='', encoding='utf-8')
    except OSError as e:
        raise ValueError(str(e))
    with f:
        reader = csv.reader(f)
        try:
            header = next(reader)
        except StopIteration:
            raise ValueError('missing header')
        if header != _HEADER:
            raise ValueError('invalid header')
        result = []
        for row in reader:
            if len(row) != 7 or not row[0] or (not row[4]):
                raise ValueError('invalid row')
            try:
                date.fromisoformat(row[1])
                datetime.strptime(row[2], '%H:%M')
                duration = int(row[3])
                priority = int(row[5])
            except (ValueError, TypeError):
                raise ValueError('invalid row')
            if duration <= 0:
                raise ValueError('invalid duration')
            result.append({'case_id': row[0], 'date': row[1], 'start': row[2], 'duration': duration, 'room': row[4], 'priority': priority, 'participants': [x.strip() for x in row[6].split(';') if x.strip()]})
        return result

def list_exhibits(directory: str) -> dict[str, int]:
    if not os.path.isdir(directory):
        raise ValueError('not a directory')
    try:
        p = subprocess.run(['find', directory, '-maxdepth', '1', '-type', 'f'], capture_output=True, text=True, check=True)
    except (OSError, subprocess.CalledProcessError) as e:
        raise RuntimeError(str(e))
    names = sorted((os.path.basename(x) for x in p.stdout.splitlines()))
    result = {}
    for name in names:
        if '-' in name:
            key = name.split('-', 1)[0]
            result[key] = result.get(key, 0) + 1
    return result

def schedule_hearings(docket_path: str, exhibits_directory: str, hearing_date: str) -> list[dict]:
    try:
        date.fromisoformat(hearing_date)
    except ValueError:
        raise ValueError('invalid date')
    hearings = [x for x in load_hearings(docket_path) if x['date'] == hearing_date]
    hearings.sort(key=lambda x: (x['start'], x['priority'], x['case_id']))
    counts = list_exhibits(exhibits_directory)
    occupied = {}
    result = []
    for h in hearings:
        start = datetime.strptime(h['start'], '%H:%M')
        end = start + timedelta(minutes=h['duration'])
        previous = occupied.get(h['room'])
        if previous is not None and start < previous:
            raise ValueError('overlapping hearings')
        occupied[h['room']] = end
        result.append({'case_id': h['case_id'], 'room': h['room'], 'start': h['start'], 'end': end.strftime('%H:%M'), 'priority': h['priority'], 'participants': h['participants'], 'exhibit_count': counts.get(h['case_id'], 0)})
    return result

