import csv
import os
import tempfile
from pathlib import Path

def export_census_summary(records, destination, min_age=0):
    if isinstance(min_age, bool) or not isinstance(min_age, int) or (not 0 <= min_age <= 120):
        raise ValueError('invalid min_age')
    groups = {}
    for record in records:
        try:
            region = record['region']
            age = record['age']
            completed = record['completed']
            household_size = record['household_size']
        except (KeyError, TypeError):
            raise ValueError('invalid record')
        if not isinstance(region, str) or not region or isinstance(age, bool) or (not isinstance(age, int)) or (not 0 <= age <= 120) or (not isinstance(completed, bool)) or isinstance(household_size, bool) or (not isinstance(household_size, int)) or (not 1 <= household_size <= 20):
            raise ValueError('invalid record')
        if age < min_age:
            continue
        if region not in groups:
            groups[region] = [0, 0, 0]
        groups[region][0] += 1
        groups[region][1] += int(completed)
        groups[region][2] += household_size
    rows = []
    for region, (total, completed, household_total) in groups.items():
        rows.append((region, total, completed, household_total))
    rows.sort(key=lambda row: (-row[1], row[0]))
    parent = Path(destination).parent
    fd, temporary = tempfile.mkstemp(prefix='.census-', dir=str(parent), text=True)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as output:
            writer = csv.writer(output, lineterminator='\n')
            writer.writerow(['region', 'total', 'completed', 'completion_rate', 'average_household_size'])
            for region, total, completed, household_total in rows:
                writer.writerow([region, total, completed, f'{completed * 100 / total:.1f}', f'{household_total / total:.2f}'])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return len(rows)

