import hashlib
import hmac
import json

import pytest

from solution import summarize_appointment_webhook


SECRET = b"housekeeping-webhook-key"


def make_payload(appointments):
    return json.dumps({"appointments": appointments}, separators=(",", ":")).encode()


def sign(payload):
    return hmac.new(SECRET, payload, hashlib.sha256).hexdigest()


def test_empty_payload_list_returns_zero_summary():
    payload = make_payload([])
    assert summarize_appointment_webhook(payload, sign(payload), SECRET) == {
        "appointments": 0,
        "total_minutes": 0,
        "total_price": 0.0,
        "by_cleaner": [],
    }


def test_appointments_are_aggregated_and_cleaners_sorted():
    payload = make_payload([
        {"cleaner": "Zoe", "date": "2025-04-10", "minutes": 45, "price": 30.0},
        {"cleaner": "Amy", "date": "2025-04-10", "minutes": 60, "price": 42.25},
        {"cleaner": "Zoe", "date": "2025-04-11", "minutes": 30, "price": 20.5},
        {"cleaner": "Amy", "date": "2025-04-11", "minutes": 15, "price": 10.75},
    ])
    assert summarize_appointment_webhook(payload, sign(payload), SECRET) == {
        "appointments": 4,
        "total_minutes": 150,
        "total_price": 103.5,
        "by_cleaner": [
            {"cleaner": "Amy", "minutes": 75, "price": 53.0},
            {"cleaner": "Zoe", "minutes": 75, "price": 50.5},
        ],
    }


def test_day_filter_includes_only_matching_appointments():
    payload = make_payload([
        {"cleaner": "Mia", "date": "2025-05-01", "minutes": 20, "price": 12.345},
        {"cleaner": "Leo", "date": "2025-05-02", "minutes": 40, "price": 25.0},
        {"cleaner": "Mia", "date": "2025-05-02", "minutes": 10, "price": 7.655},
    ])
    assert summarize_appointment_webhook(payload, sign(payload), SECRET, "2025-05-02") == {
        "appointments": 2,
        "total_minutes": 50,
        "total_price": 32.66,
        "by_cleaner": [
            {"cleaner": "Leo", "minutes": 40, "price": 25.0},
            {"cleaner": "Mia", "minutes": 10, "price": 7.66},
        ],
    }


def test_valid_signature_does_not_change_payload_ordering_rules():
    payload = make_payload([
        {"cleaner": "Beta", "date": "2025-06-01", "minutes": 1, "price": 0},
        {"cleaner": "Alpha", "date": "2025-06-01", "minutes": 2, "price": 1.005},
    ])
    result = summarize_appointment_webhook(payload, sign(payload), SECRET)
    assert result["by_cleaner"] == [
