        {"cleaner": "Beta", "minutes": 1, "price": 0.0},
    ]


def test_bad_signature_raises_value_error():
    payload = make_payload([])
    with pytest.raises(ValueError):
        summarize_appointment_webhook(payload, "0" * 64, SECRET)


