import hmac
import os

def create_worker_record(worker_id: str, pin: str) -> dict:
    if not isinstance(worker_id, str) or not worker_id.strip():
        raise ValueError('invalid worker id')
    if not isinstance(pin, str) or len(pin) != 4 or (not all(('0' <= c <= '9' for c in pin))):
        raise ValueError('invalid pin')
