import hashlib
import hmac
import math
import os

def register_trader(traders: dict, trader_id: str, api_secret: str) -> None:
    if not isinstance(trader_id, str) or not trader_id or (not isinstance(api_secret, str)) or (not api_secret):
        raise ValueError('invalid trader')
    if trader_id in traders:
        raise ValueError('duplicate trader')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', api_secret.encode(), salt, 100000)
    traders[trader_id] = {'hash': salt.hex() + '$' + digest.hex()}

def authenticate_trader(traders: dict, trader_id: str, api_secret: str) -> bool:
    if not isinstance(trader_id, str) or not isinstance(api_secret, str):
        return False
    try:
        record = traders[trader_id]['hash']
        salt_hex, digest_hex = record.split('$', 1)
        salt = bytes.fromhex(salt_hex)
        expected = bytes.fromhex(digest_hex)
        actual = hashlib.pbkdf2_hmac('sha256', api_secret.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError, AttributeError):
        return False

def route_orders(orders: list[dict], quotes: dict[str, dict]) -> list[dict]:
    required_order = {'id', 'symbol', 'side', 'quantity', 'limit'}
    required_quote = {'bid', 'ask', 'bid_size', 'ask_size'}
    output = []
    for order in orders:
        if not isinstance(order, dict) or set(order) != required_order:
            raise ValueError('invalid order')
        if not isinstance(order['id'], str) or not isinstance(order['symbol'], str):
            raise ValueError('invalid order')
        if order['side'] not in ('buy', 'sell') or isinstance(order['quantity'], bool) or (not isinstance(order['quantity'], int)) or (order['quantity'] <= 0):
            raise ValueError('invalid order')
        if isinstance(order['limit'], bool) or not isinstance(order['limit'], (int, float)) or (not math.isfinite(order['limit'])):
            raise ValueError('invalid order')
        symbol = order['symbol']
        if symbol not in quotes:
            continue
        quote = quotes[symbol]
        if not isinstance(quote, dict) or set(quote) != required_quote:
            raise ValueError('invalid quote')
        for key in required_quote:
            value = quote[key]
            if isinstance(value, bool) or not isinstance(value, (int, float)) or (not math.isfinite(value)) or (value <= 0) or (key.endswith('_size') and (not isinstance(value, int) or value <= 0)):
                raise ValueError('invalid quote')
        price = quote['ask'] if order['side'] == 'buy' else quote['bid']
        size = quote['ask_size'] if order['side'] == 'buy' else quote['bid_size']
        executable = order['limit'] >= price if order['side'] == 'buy' else order['limit'] <= price
        if executable:
            quantity = min(order['quantity'], size)
            if quantity:
                output.append({'id': order['id'], 'symbol': symbol, 'side': order['side'], 'quantity': quantity, 'price': price})
    output.sort(key=lambda x: (-x['quantity'], x['price'], x['symbol'], x['id']))
    return output

