import hashlib
import hmac
import json

def authenticate_manifest(payload: str, signature: str, secret: str) -> dict:
    if not isinstance(payload, str) or not isinstance(signature, str) or (not isinstance(secret, str)):
        raise ValueError('invalid authentication input')
    if len(signature) != 71 or not signature.startswith('sha256='):
        raise ValueError('invalid signature')
    supplied = signature[7:]
    if any((c not in '0123456789abcdef' for c in supplied)):
        raise ValueError('invalid signature')
    expected = hmac.new(secret.encode(), payload.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(supplied, expected):
        raise ValueError('invalid signature')
    try:
        manifest = json.loads(payload)
    except Exception as exc:
        raise ValueError('invalid json') from exc
    if not isinstance(manifest, dict) or not isinstance(manifest.get('jobs'), list):
        raise ValueError('invalid manifest')
    ids = set()
    for item in manifest['jobs']:
        if not isinstance(item, dict) or set(('id', 'machine', 'duration', 'due', 'priority', 'depends')) - set(item):
            raise ValueError('invalid job')
        if not isinstance(item['id'], str) or not item['id'] or item['id'] in ids or (not isinstance(item['machine'], str)) or (not item['machine']) or (type(item['duration']) is not int) or (item['duration'] <= 0) or (type(item['due']) is not int) or (item['due'] < 0) or (type(item['priority']) is not int) or (not isinstance(item['depends'], list)) or any((not isinstance(x, str) for x in item['depends'])) or (item['id'] in item['depends']):
            raise ValueError('invalid job')
        ids.add(item['id'])
    if any((x not in ids for j in manifest['jobs'] for x in j['depends'])):
        raise ValueError('invalid dependency')
    return manifest

def make_schedule(manifest: dict, machine_capacity: dict[str, int]) -> list[dict]:
    if any((type(v) is not int or v <= 0 for v in machine_capacity.values())):
        raise ValueError('invalid capacity')
    jobs = {j['id']: j for j in manifest['jobs']}
    if any((j['machine'] not in machine_capacity for j in jobs.values())):
        raise ValueError('unknown machine')
    done = {}
    usage = {m: [] for m in machine_capacity}
    result = []
    while len(done) < len(jobs):
        ready = [j for j in jobs.values() if j['id'] not in done and all((x in done for x in j['depends']))]
