        raise ValueError('invalid header')
    grouped = {}
    for row in rows[1:]:
        if len(row) != 4 or any((value == '' for value in row)):
            raise ValueError('invalid row')
        permit_id, row_species, days_text, zone = row
        try:
            days = int(days_text)
        except ValueError:
            raise ValueError('invalid days')
        if days < 0:
            raise ValueError('invalid days')
        if species is not None and row_species != species:
            continue
        item = grouped.setdefault(permit_id, {'total_days': 0, 'zones': set()})
        item['total_days'] += days
        item['zones'].add(zone)
    result = [{'permit_id': permit_id, 'total_days': item['total_days'], 'zones': sorted(item['zones'])} for permit_id, item in grouped.items()]
    result.sort(key=lambda item: (-item['total_days'], item['permit_id']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

