    result, seen = ([], set())
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields = _split_fields(raw)
        if len(fields) != 6 or any((not x for x in fields)):
            raise ValueError('bad record')
        ident, destination, demand, priority, window, distance = fields
        if ident in seen:
            raise ValueError('duplicate id')
        try:
            demand, priority, distance = (int(demand), int(priority), int(distance))
            pair = window.split('-')
            if len(pair) != 2:
                raise ValueError
            start, end = (_clock(pair[0]), _clock(pair[1]))
        except (TypeError, ValueError):
            raise ValueError('bad record')
        if demand <= 0 or distance <= 0 or (not 0 <= priority <= 9) or (end <= start):
            raise ValueError('bad record')
        seen.add(ident)
        result.append({'id': ident, 'destination': destination, 'demand': demand, 'priority': priority, 'window_start': start, 'window_end': end, 'distance': distance})
    return result

def plan_routes(records: list[dict], capacity: int, vehicles: int) -> list[dict]:
    if capacity <= 0 or vehicles <= 0:
        raise ValueError('bad fleet')
    ordered = sorted(records, key=lambda r: (-r['priority'], r['window_start'], -r['demand'], r['id']))
    routes = []
    for record in ordered:
