    totals = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        required = ('route', 'stop', 'weight_kg', 'status')
        if any((key not in record for key in required)):
            raise ValueError('invalid record')
        route = record['route']
        stop = record['stop']
        weight = record['weight_kg']
        status = record['status']
        if not isinstance(route, str) or not route:
            raise ValueError('invalid record')
        if isinstance(stop, bool) or not isinstance(stop, int) or stop <= 0:
            raise ValueError('invalid record')
        if isinstance(weight, bool) or not isinstance(weight, (int, float)) or weight < 0:
            raise ValueError('invalid record')
        if status not in ('collected', 'missed'):
            raise ValueError('invalid record')
        if status == 'collected':
            if route not in totals:
                totals[route] = [0, 0.0]
            totals[route][0] += 1
            totals[route][1] += weight
    result = [{'route': route, 'stops': values[0], 'total_kg': round(values[1], 2)} for route, values in totals.items()]
    result.sort(key=lambda item: (-item['total_kg'], item['route']))
    directory = os.path.dirname(os.path.abspath(output_path))
    fd, temporary = tempfile.mkstemp(dir=directory, prefix='.route-')
    os.close(fd)
    try:
        with open(temporary, 'w', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['route', 'stops', 'total_kg'])
            for item in result:
                writer.writerow([item['route'], item['stops'], f"{item['total_kg']:.2f}"])
        os.replace(temporary, output_path)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return result

