from datetime import date

def _date(value):
    try:
        return date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def _payment(value):
    if not isinstance(value, dict) or set(('date', 'amount_cents', 'reference')) - value.keys():
        raise ValueError('invalid payment')
    d = _date(value['date'])
    if type(value['amount_cents']) is not int or value['amount_cents'] < 0 or (not isinstance(value['reference'], str)) or (not value['reference']):
        raise ValueError('invalid payment')
    return {'date': d.isoformat(), 'amount_cents': value['amount_cents'], 'reference': value['reference']}

def parse_payment_feed(text: str) -> list[dict]:
    if not isinstance(text, str):
        raise ValueError('invalid feed')
    result = []
    for line in text.splitlines():
        if not line:
            continue
        parts, current, escaped = ([], [], False)
        for ch in line:
            if escaped:
                if ch not in '\\|':
                    raise ValueError('invalid escape')
                current.append(ch)
                escaped = False
            elif ch == '\\':
                escaped = True
            elif ch == '|' and len(parts) < 2:
                parts.append(''.join(current))
                current = []
            elif ch == '|':
                raise ValueError('too many fields')
            else:
                current.append(ch)
        if escaped:
            raise ValueError('dangling escape')
        parts.append(''.join(current))
        if len(parts) != 3:
            raise ValueError('invalid record')
        try:
            amount = int(parts[1])
        except (TypeError, ValueError):
            raise ValueError('invalid amount')
        result.append(_payment({'date': parts[0], 'amount_cents': amount, 'reference': parts[2]}))
    return result

def lease_statement(lease: dict, payments: list[dict], as_of: str) -> dict:
    start, end, cutoff = (_date(lease['start_date']), _date(lease['end_date']), _date(as_of))
    if end < start or type(lease.get('monthly_cents')) is not int or lease['monthly_cents'] <= 0:
        raise ValueError('invalid lease')
    last = min(end, cutoff)
    months = [] if cutoff < start else [(y, m) for y in range(start.year, last.year + 1) for m in range(1, 13) if (y, m) >= (start.year, start.month) and (y, m) <= (last.year, last.month)]
    usable = sum((p['amount_cents'] for p in payments if start.isoformat() <= p['date'] <= last.isoformat()))
    unpaid, available = ([], usable)
    for y, m in months:
        if available >= lease['monthly_cents']:
            available -= lease['monthly_cents']
        else:
            unpaid.append(f'{y:04d}-{m:02d}')
            available = 0
    paid = usable
    return {'billed_months': len(months), 'paid_cents': paid, 'outstanding_cents': max(0, len(months) * lease['monthly_cents'] - paid), 'unpaid_months': unpaid}

def record_payment(requester: dict, lease: dict, payment: dict) -> dict:
    if not (requester.get('tenant_id') == lease.get('tenant_id') and (requester.get('id') == lease.get('owner_id') or requester.get('role') == 'property_manager')):
        raise PermissionError('not permitted')
    clean = _payment(payment)
    start, end = (_date(lease['start_date']), _date(lease['end_date']))
    if not start <= _date(clean['date']) <= end:
        raise ValueError('payment outside lease')
    lease.setdefault('payments', []).append(clean.copy())
    return {'receipt_id': len(lease['payments']), **clean}

