import ast

def evaluate_rule(expression: str, variables: dict[str, int | float | bool]) -> bool:
    allowed = {'min': min, 'max': max, 'round': round}
    allowed.update(variables)
    try:
        tree = ast.parse(expression, mode='eval')

        def check(node):
            if isinstance(node, ast.Expression):
                return check(node.body)
            if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
                return node.value
            if isinstance(node, ast.Name):
                if node.id not in allowed:
                    raise ValueError()
                return allowed[node.id]
            if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
                return check(node.operand)
            if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
                return check(node.left)
            if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
                return check(node.values[0])
            if isinstance(node, ast.Compare) and all((isinstance(x, (ast.Lt, ast.LtE, ast.Gt, ast.GtE, ast.Eq, ast.NotEq)) for x in node.ops)):
                return check(node.left)
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
                return check(node.func)
            raise ValueError()
        check(tree)
        return bool(eval(compile(tree, '', 'eval'), {'__builtins__': {}}, allowed))
    except Exception as exc:
        raise ValueError('invalid expression') from exc

def plan_feeding(records: list[dict], rule: str, base_rate: float) -> list[dict]:
    if not isinstance(base_rate, (int, float)) or base_rate <= 0:
        raise ValueError()
    seen, out = (set(), [])
    for r in records:
        if set(r) != {'id', 'day', 'biomass_kg', 'water_temp', 'oxygen_mg_l'} or not isinstance(r['id'], str) or (not r['id']) or (not isinstance(r['day'], int)) or (r['day'] < 1) or (r['biomass_kg'] <= 0) or (r['oxygen_mg_l'] <= 0):
            raise ValueError()
        if r['id'] in seen:
            raise ValueError()
        seen.add(r['id'])
        if evaluate_rule(rule, {'biomass': r['biomass_kg'], 'temp': r['water_temp'], 'oxygen': r['oxygen_mg_l'], 'day': r['day']}):
            f = 0.6 if r['water_temp'] < 15 else 0.8 if r['water_temp'] < 18 else 1.0
            if r['oxygen_mg_l'] < 5:
                f *= 0.5
            out.append({'id': r['id'], 'day': r['day'], 'feed_kg': round(r['biomass_kg'] * base_rate * f, 3)})
