import csv
import io
import math
from collections import defaultdict
from datetime import datetime, timezone

def parse_observation_lines(text: str) -> list[dict]:
    if not isinstance(text, str) or not text.strip():
        raise ValueError('empty input')
    rows = list(csv.reader(io.StringIO(text)))
    header = None
    records = []
    seen = set()
    expected = ['timestamp', 'temperature', 'humidity', 'wind_speed']
    for row in rows:
        if not any((x.strip() for x in row)):
            continue
        values = [x.strip() for x in row]
        if header is None:
            if values != expected:
                raise ValueError('invalid header')
            header = values
            continue
        if len(values) != 4:
            raise ValueError('invalid row')
        try:
            stamp = values[0]
            if not stamp.endswith('Z'):
                raise ValueError
            when = datetime.fromisoformat(stamp[:-1] + '+00:00')
            when = when.astimezone(timezone.utc)
            if when in seen:
                raise ValueError('duplicate timestamp')
            nums = [float(x) for x in values[1:]]
        except Exception as exc:
            raise ValueError('invalid observation') from exc
        if not all((math.isfinite(x) for x in nums)) or not 0 <= nums[1] <= 100 or nums[2] < 0:
            raise ValueError('invalid measurement')
        seen.add(when)
        records.append({'timestamp': when, 'temperature': nums[0], 'humidity': nums[1], 'wind_speed': nums[2]})
    if header is None:
        raise ValueError('missing header')
    return sorted(records, key=lambda x: x['timestamp'])

def build_station_report(requester: dict, station: dict, text: str) -> str:
    if requester['id'] != station['owner_id'] and 'weather_admin' not in requester['roles']:
        raise PermissionError('not permitted')
    records = parse_observation_lines(text)
    groups = defaultdict(list)
    for record in records:
        t = record['timestamp']
        hour = t.replace(minute=0, second=0, microsecond=0)
        groups[hour].append(record)
    lines = ['station_id,hour,avg_temperature,avg_humidity,max_wind_speed,reading_count']
    for hour in sorted(groups):
        items = groups[hour]
        avg_t = sum((x['temperature'] for x in items)) / len(items)
        avg_h = sum((x['humidity'] for x in items)) / len(items)
        max_w = max((x['wind_speed'] for x in items))
        lines.append(f"{station['id']},{hour:%Y-%m-%dT%H:00:00Z},{avg_t:.2f},{avg_h:.2f},{max_w:.2f},{len(items)}")
    return '\n'.join(lines) + '\n'

