    selected_day = None
    if day is not None:
        try:
            selected_day = datetime.date.fromisoformat(day)
        except (TypeError, ValueError) as exc:
            raise ValueError('invalid day') from exc
    rows = []
    for item in sessions:
        try:
            fields = [item['tutor'], item['student'], item['start'], item['duration'], item['subject']]
        except (KeyError, TypeError) as exc:
            raise ValueError('invalid session') from exc
        if any((not isinstance(value, str) or not value for value in fields)):
            raise ValueError('invalid session')
        try:
            start = datetime.datetime.strptime(item['start'], '%Y-%m-%d %H:%M')
            duration = int(item['duration'], 10)
        except (TypeError, ValueError) as exc:
            raise ValueError('invalid session') from exc
        if str(duration) != item['duration'] or not 1 <= duration <= 480:
            raise ValueError('invalid session')
        if selected_day is not None and start.date() != selected_day:
            continue
        end = start + datetime.timedelta(minutes=duration)
        rows.append((start, item['tutor'], item['student'], item['subject'], end))
    rows.sort(key=lambda row: (row[0], row[1], row[2]))
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent, prefix='.schedule-', suffix='.tmp')
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as stream:
            writer = csv.writer(stream)
            writer.writerow(['tutor', 'student', 'start', 'end', 'subject'])
            for start, tutor, student, subject, end in rows:
                writer.writerow([tutor, student, start.strftime('%Y-%m-%d %H:%M'), end.strftime('%Y-%m-%d %H:%M'), subject])
        os.replace(temporary, destination)
    except BaseException:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return len(rows)

