import os
import json
import hmac
import hashlib
from datetime import datetime

def build_attendance_report(records: list[dict], config: dict | None=None) -> dict:
    if config is not None:
        key = config.get('attendance_signing_key')
    else:
        key = os.environ.get('ATTENDANCE_SIGNING_KEY')
    if not isinstance(key, str) or not key:
        raise ValueError('attendance signing key is required')
    grouped = {}
    day = None
    for index, record in enumerate(records):
        try:
            child = record['child_id']
            name = record['name']
            stamp = record['timestamp']
            event = record['event']
        except (KeyError, TypeError):
            raise ValueError('invalid attendance record')
        if not isinstance(child, str) or not child or (not isinstance(name, str)) or (not name):
            raise ValueError('invalid attendance record')
        if not isinstance(stamp, str) or not stamp.endswith('Z'):
            raise ValueError('invalid timestamp')
        try:
            parsed = datetime.fromisoformat(stamp[:-1] + '+00:00')
        except ValueError:
            raise ValueError('invalid timestamp')
        current_day = parsed.date().isoformat()
        if day is None:
            day = current_day
        elif day != current_day:
            raise ValueError('timestamps must share a date')
        if event not in ('check_in', 'check_out'):
            raise ValueError('invalid event')
        grouped.setdefault(child, {'name': name, 'items': []})['items'].append((parsed, index, stamp, event, name))
    children = []
    for child in sorted(grouped):
        entry = grouped[child]
        items = sorted(entry['items'], key=lambda x: (x[0], x[1]))
        sessions = []
        opened = None
        for parsed, _, stamp, event, name in items:
            if name != entry['name']:
                raise ValueError('inconsistent name')
            if event == 'check_in':
                if opened is not None:
                    raise ValueError('invalid event sequence')
                opened = (parsed, stamp)
            else:
                if opened is None:
                    raise ValueError('invalid event sequence')
                seconds = (parsed - opened[0]).total_seconds()
                if seconds % 60:
                    raise ValueError('session is not a whole number of minutes')
                sessions.append({'check_in': opened[1], 'check_out': stamp, 'minutes': int(seconds // 60)})
                opened = None
        if opened is not None:
            raise ValueError('invalid event sequence')
        children.append({'child_id': child, 'name': entry['name'], 'sessions': sessions, 'total_minutes': sum((x['minutes'] for x in sessions))})
    payload = {'date': day, 'children': children}
    encoded = json.dumps(payload, sort_keys=True, separators=(',', ':')).encode()
    signature = hmac.new(key.encode(), encoded, hashlib.sha256).hexdigest()
    return {'date': day, 'children': children, 'signature': signature}

