import ast
import operator

def _value(node, values):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in values:
            raise ValueError('unknown name')
        return values[node.id]
    if isinstance(node, ast.BinOp) and type(node.op) in {ast.Add, ast.Sub, ast.Mult, ast.Div}:
        return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](_value(node.left, values), _value(node.right, values))
    if isinstance(node, ast.UnaryOp) and type(node.op) in {ast.UAdd, ast.USub, ast.Not}:
        return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](_value(node.operand, values))
    if isinstance(node, ast.BoolOp) and type(node.op) in {ast.And, ast.Or}:
        result = _value(node.values[0], values)
        for item in node.values[1:]:
            if isinstance(node.op, ast.And) and (not result) or (isinstance(node.op, ast.Or) and result):
                return result
            result = _value(item, values)
        return result
    if isinstance(node, ast.Compare):
        left = _value(node.left, values)
        for op, part in zip(node.ops, node.comparators):
            right = _value(part, values)
            if not {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}[type(op)](left, right):
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max', 'round'}) and (not node.keywords):
        return {'min': min, 'max': max, 'round': round}[node.func.id](*[_value(x, values) for x in node.args])
    raise ValueError('unsupported expression')

def rank_orders(orders: list[dict], formula: str) -> list[tuple[str, int | float]]:
    try:
        tree = ast.parse(formula, mode='eval').body
    except (SyntaxError, TypeError):
        raise ValueError('invalid formula')
    result = []
    for order in orders:
        score = _value(tree, {k: order[k] for k in ('amount', 'lead_days', 'rating')})
        if score > 0:
            result.append((order['id'], score))
    return sorted(result, key=lambda item: (-item[1], item[0]))

