def write_guest_points_report(records: list[dict], relative_name: str, base_dir: str, page: int=1, page_size: int=10) -> str:
    if not isinstance(relative_name, str) or not relative_name or os.path.isabs(relative_name):
        raise ValueError('invalid filename')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    totals = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        guest_id = record.get('guest_id')
        points = record.get('points')
        if not isinstance(guest_id, str) or not guest_id:
            raise ValueError('invalid guest')
        if not isinstance(points, int) or isinstance(points, bool):
            raise ValueError('invalid points')
        totals[guest_id] = totals.get(guest_id, 0) + points
    guests = sorted(totals.items(), key=lambda item: (-item[1], item[0]))
    start = (page - 1) * page_size
    selected = guests[start:start + page_size]
    base = os.path.realpath(os.path.abspath(base_dir))
    destination = os.path.realpath(os.path.join(base, relative_name))
    try:
        inside = os.path.commonpath((base, destination)) == base
    except ValueError:
        inside = False
    if not inside:
        raise ValueError('invalid filename')
    os.makedirs(os.path.dirname(destination), exist_ok=True)
    with open(destination, 'w', encoding='utf-8', newline='') as handle:
        writer = csv.writer(handle, lineterminator='\n')
        writer.writerow(['guest_id', 'total_points', 'rank'])
        for index, (guest_id, total) in enumerate(selected, start=start + 1):
            writer.writerow([guest_id, total, index])
    return os.path.abspath(destination)

