import hashlib
import hmac
import json

def verify_enrollment_packet(packet: bytes, secret: bytes) -> dict:
    if not isinstance(packet, bytes) or not isinstance(secret, bytes):
        raise ValueError('invalid packet')
    try:
        header, body = packet.split(b'\n\n', 1)
        if not header.startswith(b'X-Signature: ') or b'\n' in header:
            raise ValueError('invalid packet')
        text = header[len(b'X-Signature: '):].decode('ascii')
        if len(text) != 64 or text != text.lower():
            raise ValueError('invalid signature')
        supplied = bytes.fromhex(text)
        expected = hmac.new(secret, body, hashlib.sha256).digest()
        if not hmac.compare_digest(expected, supplied):
            raise ValueError('invalid signature')
        value = json.loads(body.decode('utf-8'))
    except (UnicodeError, ValueError, json.JSONDecodeError):
        raise ValueError('invalid packet')
    if not isinstance(value, dict) or not all((k in value for k in ('school', 'sections', 'requests'))):
        raise ValueError('invalid body')
    return value

def allocate_enrollment(payload: dict) -> dict:
    if not isinstance(payload, dict) or not isinstance(payload.get('school'), str):
        raise ValueError('invalid enrollment')
    sections = payload.get('sections')
    requests = payload.get('requests')
    if not isinstance(sections, list) or not isinstance(requests, list):
        raise ValueError('invalid enrollment')
    info = {}
    for section in sections:
        if not isinstance(section, dict) or not isinstance(section.get('id'), str) or (not section['id']) or (not isinstance(section.get('course'), str)):
            raise ValueError('invalid section')
        capacity = section.get('capacity')
        if isinstance(capacity, bool) or not isinstance(capacity, int) or capacity < 0 or (section['id'] in info):
            raise ValueError('invalid section')
        info[section['id']] = [capacity, []]
    pending = []
    seen = set()
    for request in requests:
        if not isinstance(request, dict) or not isinstance(request.get('student'), str) or (not request['student']) or (request['student'] in seen):
            raise ValueError('invalid request')
        choices = request.get('choices')
        if not isinstance(choices, list) or not choices or any((not isinstance(x, str) or x not in info for x in choices)):
            raise ValueError('invalid request')
        seen.add(request['student'])
        pending.append((request['student'], choices))
    unassigned = []
    for student, choices in sorted(pending):
        for choice in choices:
            if len(info[choice][1]) < info[choice][0]:
                info[choice][1].append(student)
                break
        else:
            unassigned.append(student)
    return {'school': payload['school'], 'placements': [{'section': k, 'students': info[k][1][:]} for k in sorted(info)], 'unassigned': unassigned}

