import csv
import hashlib
import hmac
import os
import re
from io import StringIO

def create_staff_account(username: str, password: str) -> dict[str, str]:
    if not isinstance(username, str) or not isinstance(password, str):
        raise TypeError('username and password must be strings')
    username = username.strip()
    if not username or len(password) < 4:
        raise ValueError('invalid account values')
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return {'username': username, 'salt': salt.hex(), 'password_hash': value.hex()}

def authenticate_staff(account: dict[str, str], password: str) -> bool:
    if not isinstance(password, str) or not isinstance(account, dict):
        if not isinstance(password, str):
            raise TypeError('password must be a string')
        return False
    try:
        salt = bytes.fromhex(account['salt'])
        expected = bytes.fromhex(account['password_hash'])
    except (KeyError, ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def summarize_orders(lines: list[str]) -> list[dict[str, object]]:
    groups = {}
    for line in lines:
        if not isinstance(line, str) or not line:
            raise ValueError('empty record')
        try:
            fields = next(csv.reader(StringIO(line)))
        except csv.Error as exc:
            raise ValueError('bad CSV') from exc
        if len(fields) != 5:
            raise ValueError('wrong field count')
        customer, item, quantity, price, priority = [x.strip() for x in fields]
        if not customer or not item or (not re.fullmatch('[1-9][0-9]*', quantity)):
            raise ValueError('invalid order')
        if not re.fullmatch('[0-9]+\\.[0-9]{2}', price):
            raise ValueError('invalid price')
        if not re.fullmatch('[0-9]+', priority) or int(priority) > 9:
            raise ValueError('invalid priority')
        qty = int(quantity)
        cents = int(price.replace('.', ''))
        group = groups.setdefault(customer, {'quantity': 0, 'total_cents': 0, 'highest_priority': 0, 'items': {}})
        group['quantity'] += qty
        group['total_cents'] += qty * cents
        group['highest_priority'] = max(group['highest_priority'], int(priority))
        group['items'][item] = group['items'].get(item, 0) + qty
    result = []
    for customer, group in groups.items():
        result.append({'customer': customer, 'quantity': group['quantity'], 'total_cents': group['total_cents'], 'highest_priority': group['highest_priority'], 'items': [{'item': k, 'quantity': group['items'][k]} for k in sorted(group['items'])]})
    return sorted(result, key=lambda x: (-x['total_cents'], -x['highest_priority'], x['customer']))

