import hashlib
import hmac
import os

def hash_password(password: str) -> str:
    if not isinstance(password, str) or not password:
        raise ValueError('password must be non-empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return salt.hex() + ':' + digest.hex()

def verify_password(password: str, stored: str) -> bool:
    if not isinstance(password, str) or not password or (not isinstance(stored, str)):
        return False
    try:
        salt_text, digest_text = stored.split(':')
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def create_map_account(username: str, password: str, region: str) -> dict[str, str]:
    if not isinstance(username, str) or not username:
        raise ValueError('username must be non-empty')
    if not isinstance(password, str) or not password:
        raise ValueError('password must be non-empty')
    if not isinstance(region, str) or not region:
        raise ValueError('region must be non-empty')
    return {'username': username, 'region': region, 'password_hash': hash_password(password)}

def authenticate_map_account(account: dict[str, str], password: str) -> dict[str, str] | None:
    if not isinstance(account, dict) or not isinstance(password, str):
        return None
    if not all((isinstance(account.get(key), str) for key in ('username', 'region', 'password_hash'))):
        return None
    if not verify_password(password, account['password_hash']):
        return None
    return {'username': account['username'], 'region': account['region']}

