from solution import assign_room
import pytest


def make_data():
    bookings = {
        "b1": {"guest_id": "u1", "hostel_id": "h1", "room_id": "r1", "status": "confirmed"},
        "b2": {"guest_id": "u2", "hostel_id": "h1", "room_id": "r2", "status": "confirmed"},
    }
    rooms = {
        "r1": {"hostel_id": "h1", "room_number": 1, "occupied": True},
        "r2": {"hostel_id": "h1", "room_number": 2, "occupied": True},
        "r3": {"hostel_id": "h1", "room_number": 3, "occupied": False},
        "r4": {"hostel_id": "h2", "room_number": 4, "occupied": False},
    }
    return bookings, rooms


def test_owner_can_assign_available_room():
    bookings, rooms = make_data()
    requester = {"user_id": "u1", "role": "guest", "hostel_id": "h1"}
    result = assign_room(requester, "b1", "r3", bookings, rooms)
    assert result == {"guest_id": "u1", "hostel_id": "h1", "room_id": "r3", "status": "confirmed"}
    assert bookings["b1"]["room_id"] == "r3"
    assert rooms["r1"]["occupied"] is False
    assert rooms["r3"]["occupied"] is True


def test_staff_can_assign_booking_for_another_guest():
    bookings, rooms = make_data()
    requester = {"user_id": "staff9", "role": "receptionist", "hostel_id": "h1"}
    result = assign_room(requester, "b2", "r3", bookings, rooms)
    assert result["room_id"] == "r3"
    assert bookings["b2"]["room_id"] == "r3"
    assert rooms["r2"]["occupied"] is False


def test_assigning_same_room_keeps_it_occupied():
    bookings, rooms = make_data()
    requester = {"user_id": "u1", "role": "guest", "hostel_id": "h1"}
    result = assign_room(requester, "b1", "r1", bookings, rooms)
    assert result is bookings["b1"]
    assert rooms["r1"]["occupied"] is True


def test_missing_booking_raises_key_error():
    bookings, rooms = make_data()
    requester = {"user_id": "u1", "role": "guest", "hostel_id": "h1"}
    with pytest.raises(KeyError):
        assign_room(requester, "missing", "r3", bookings, rooms)


def test_missing_room_raises_key_error():
    bookings, rooms = make_data()
    requester = {"user_id": "u1", "role": "guest", "hostel_id": "h1"}
    with pytest.raises(KeyError):
        assign_room(requester, "b1", "missing", bookings, rooms)


def test_occupied_room_raises_value_error_without_changes():
    bookings, rooms = make_data()
    requester = {"user_id": "u1", "role": "guest", "hostel_id": "h1"}
    with pytest.raises(ValueError):
        assign_room(requester, "b1", "r2", bookings, rooms)
    assert bookings["b1"]["room_id"] == "r1"
    assert rooms["r1"]["occupied"] is True


def test_wrong_hostel_room_raises_value_error():
    bookings, rooms = make_data()
    requester = {"user_id": "u1", "role": "guest", "hostel_id": "h1"}
    with pytest.raises(ValueError):
        assign_room(requester, "b1", "r4", bookings, rooms)


def test_unconfirmed_booking_raises_value_error():
    bookings, rooms = make_data()
    bookings["b1"]["status"] = "pending"
    requester = {"user_id": "u1", "role": "guest", "hostel_id": "h1"}
    with pytest.raises(ValueError):
        assign_room(requester, "b1", "r3", bookings, rooms)

