import csv
import datetime as dt
import json
import os
import tempfile
from decimal import Decimal, ROUND_HALF_UP
from io import StringIO
RATES = {'USD': Decimal('1'), 'EUR': Decimal('1.10'), 'GBP': Decimal('1.25')}
STATUSES = {'pending', 'approved', 'rejected'}

def _date(value):
    try:
        return dt.date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def build_approval_report(payload: str, as_of: str) -> list[dict]:
    try:
        items = json.loads(payload)
    except Exception:
        raise ValueError('invalid json')
    if not isinstance(items, list):
        raise ValueError('top level must be an array')
    today = _date(as_of)
    seen = set()
    rows = []
    for item in items:
        if not isinstance(item, dict):
            raise ValueError('invalid request')
        required = {'id', 'employee', 'submitted', 'status', 'expenses'}
        if set(item) - required - {'events'} or not required <= set(item):
            raise ValueError('invalid fields')
        ident, employee = (item['id'], item['employee'])
        if not isinstance(ident, str) or not ident or (not isinstance(employee, str)) or (not employee) or (ident in seen):
            raise ValueError('invalid identity')
        seen.add(ident)
        submitted = _date(item['submitted'])
        if submitted > today or item['status'] not in STATUSES:
            raise ValueError('invalid request date or status')
        expenses = item['expenses']
        if not isinstance(expenses, list) or not expenses:
            raise ValueError('invalid expenses')
        total = Decimal('0')
        cats = []
        for expense in expenses:
            if not isinstance(expense, dict) or set(expense) != {'amount', 'currency', 'category'}:
                raise ValueError('invalid expense')
            amount, currency, category = expense.values()
            if isinstance(amount, bool) or not isinstance(amount, (int, float)) or amount < 0 or (currency not in RATES) or (not isinstance(category, str)) or (not category):
                raise ValueError('invalid expense')
            total += Decimal(str(amount)) * RATES[currency]
            if category not in cats:
                cats.append(category)
        status = item['status']
        events = item.get('events', [])
        if not isinstance(events, list):
            raise ValueError('invalid events')
        latest = None
        for event in events:
            if not isinstance(event, dict) or set(event) != {'date', 'status'} or event['status'] not in STATUSES:
                raise ValueError('invalid event')
            event_date = _date(event['date'])
            if event_date < submitted or event_date > today:
                raise ValueError('invalid event date')
            if latest is None or event_date >= latest[0]:
                latest = (event_date, event['status'])
        if latest is not None:
            status = latest[1]
        total = total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        rows.append((status, total, submitted, ident, {'id': ident, 'employee': employee, 'status': status, 'total_usd': float(total), 'days_pending': (today - submitted).days + 1 if status == 'pending' else 0, 'categories': ','.join(cats)}))
    rows.sort(key=lambda x: ({'pending': 0, 'rejected': 1, 'approved': 2}[x[0]], -x[1], x[2], x[3]))
    return [row[4] for row in rows]

def export_approval_report(payload: str, destination: str, as_of: str) -> str:
    report = build_approval_report(payload, as_of)
    out = StringIO(newline='')
    writer = csv.writer(out, lineterminator='\n')
    writer.writerow(['id', 'employee', 'status', 'total_usd', 'days_pending', 'categories'])
    for row in report:
        writer.writerow([row['id'], row['employee'], row['status'], f"{row['total_usd']:.2f}", row['days_pending'], row['categories']])
    text = out.getvalue()
    fd, temporary = tempfile.mkstemp(dir=os.path.dirname(os.path.abspath(destination)))
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as handle:
            handle.write(text)
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return text

